def now_ts() -> int:
    return int(time.time())


def today() -> str:
    return datetime.now().strftime("%Y-%m-%d")


def display_name(user) -> str:
    if not user:
        return "کاربر"
    first = (getattr(user, "first_name", "") or "").strip()
    last = (getattr(user, "last_name", "") or "").strip()
    username = (getattr(user, "username", "") or "").strip()
    uid = getattr(user, "id", "")
    name = first
    if last:
        name += " " + last
    return name.strip() or ("@" + username if username else str(uid or "کاربر"))


def safe_text(text: Optional[str], limit: int = 500) -> str:
    text = (text or "").strip()
    return text[:limit]


def mention_html(user) -> str:
    name = safe_text(display_name(user), 60).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    return f'<a href="tg://user?id={user.id}">{name}</a>'


def keyboard(rows):
    return InlineKeyboardMarkup(rows)

def _button_style(text: str, data: Optional[str] = None) -> str:
    """انتخاب رنگ دکمه‌ها به‌صورت معنایی؛ پیش‌فرض آبی است تا پنل‌ها یکدست سبز نشوند."""
    t = str(text or "").lower().strip()
    d = str(data or "").lower()

    # 🔴 قرمز: عملیات خطرناک/حذف/بستن/خروج
    danger_words = (
        "حذف", "لغو", "خاموش", "بستن", "خروج", "ریست", "بازنشانی",
        "مسدود", "بن", "اخطار", "پاکسازی", "قفل", "رفع بن", "رفع اخطار",
        "danger", "delete", "cancel", "close", "ban", "remove", "reset"
    )
    if any(w in t or w in d for w in danger_words):
        return "danger"

    # 🟢 سبز: عملیات مثبت/ثبت/فعال‌سازی/تأیید
    success_words = (
        "تایید", "تأیید", "فعال", "شروع", "دریافت", "هدیه", "ثبت",
        "ذخیره", "ادامه", "پیوستن", "خرید", "روشن", "باز کردن",
        "ارسال", "تایید نهایی", "اعمال", "اجرا", "انتخاب", "فعال‌سازی",
        "success", "start", "join", "claim", "save", "apply", "enable",
        "confirm", "execute"
    )
    if any(w in t or w in d for w in success_words):
        return "success"

    # 🔵 آبی: ناوبری، اطلاعات، مشاهده و تنظیمات.
    # این حالت عمداً پیش‌فرض است تا پنل‌های معمولی آبی باشند.
    return "primary"

# Telegram button colors require Bot API 9.4 and python-telegram-bot 22.7+.
# Do NOT silently remove the style parameter: that would make the bot look
# like the colors were applied while Telegram actually receives plain buttons.
def _check_colored_buttons_support():
    try:
        major, minor = [int(x) for x in telegram.__version__.split('.')[:2]]
        if (major, minor) < (22, 7):
            raise RuntimeError(
                f"نسخه python-telegram-bot شما {telegram.__version__} است. "
                "برای دکمه‌های رنگی باید نسخه 22.7 یا جدیدتر نصب شود: "
                "pip install -U python-telegram-bot>=22.7"
            )
    except ValueError:
        raise RuntimeError(
            f"نسخه python-telegram-bot قابل تشخیص نیست: {telegram.__version__}. "
            "لطفاً python-telegram-bot>=22.7 نصب کنید."
        )

_check_colored_buttons_support()

def _bb_premium_look_text(text: str) -> str:
    """Polish inline-button labels using only normal Unicode/emoji.
    This does NOT use Telegram custom-emoji IDs, so it remains usable without
    a Premium owner account. Callback data is never changed.
    """
    t = str(text or '').strip()
    if not t:
        return t
    # Keep close/danger labels compact and clean.
    if t in {'❌ بستن پنل', '✕ بستن پنل'}:
        return '✕  بستن پنل'
    # Avoid changing already-decorated labels or URL-heavy buttons.
    if '✦' in t or '•' in t or len(t) > 38:
        return t
    # Small premium-style sparkle for ordinary inline buttons.
    return f'{t}  ✦'

def btn(text, data=None, url=None, style=None):
    chosen = style or _button_style(text, data)
    return InlineKeyboardButton(
        _bb_premium_look_text(text),
        callback_data=data,
        url=url,
        style=chosen,
    )

def reply_btn(text, request_location=False, style=None):
    chosen = style or _button_style(text)
    return KeyboardButton(text, request_location=request_location, style=chosen)

def cooldown_ok(uid: int, seconds: float = 1.0) -> bool:
    t = time.monotonic()
    old = USER_COOLDOWN.get(uid, 0.0)
    if t - old < seconds:
        return False
    USER_COOLDOWN[uid] = t
    return True


def normalize(text: str) -> str:
    return re.sub(r"\s+", " ", (text or "").strip().lower().replace("ي", "ی").replace("ك", "ک"))

# -----------------------------------------------------------------------------
# DATABASE - ONE CONSISTENT SCHEMA
# -----------------------------------------------------------------------------

class DB:
    def __init__(self, path: str):
        self.path = path
        self.conn = sqlite3.connect(path, check_same_thread=False)
        self.conn.row_factory = sqlite3.Row
        self.lock = asyncio.Lock()
        self._create_schema()

    def _create_schema(self):
        c = self.conn.cursor()
        c.executescript("""
        PRAGMA journal_mode=WAL;
        PRAGMA foreign_keys=ON;

        CREATE TABLE IF NOT EXISTS users (
            user_id INTEGER PRIMARY KEY,
            username TEXT DEFAULT '',
            first_name TEXT DEFAULT '',
            xp INTEGER NOT NULL DEFAULT 0,
            level INTEGER NOT NULL DEFAULT 1,
            bones INTEGER NOT NULL DEFAULT 0,
            dog_name TEXT NOT NULL DEFAULT 'هاپو',
            dog_level INTEGER NOT NULL DEFAULT 1,
            wins INTEGER NOT NULL DEFAULT 0,
            losses INTEGER NOT NULL DEFAULT 0,
            draws INTEGER NOT NULL DEFAULT 0,
            games INTEGER NOT NULL DEFAULT 0,
            messages INTEGER NOT NULL DEFAULT 0,
            daily_claim TEXT DEFAULT '',
            created_at INTEGER NOT NULL DEFAULT 0,
            updated_at INTEGER NOT NULL DEFAULT 0,
            last_hop_at INTEGER NOT NULL DEFAULT 0
        );

        CREATE TABLE IF NOT EXISTS chats (
            chat_id INTEGER PRIMARY KEY,
            title TEXT DEFAULT '',
            active INTEGER NOT NULL DEFAULT 1,
            forced_channel TEXT DEFAULT '',
            welcome_enabled INTEGER NOT NULL DEFAULT 0,
            welcome_text TEXT DEFAULT '',
            goodbye_enabled INTEGER NOT NULL DEFAULT 0,
            goodbye_text TEXT DEFAULT '',
            rules_text TEXT DEFAULT '',
            warn_limit INTEGER NOT NULL DEFAULT 3,
            mute_minutes INTEGER NOT NULL DEFAULT 10,
            created_at INTEGER NOT NULL DEFAULT 0,
            updated_at INTEGER NOT NULL DEFAULT 0
        );

        CREATE TABLE IF NOT EXISTS locks (
            chat_id INTEGER PRIMARY KEY,
            links INTEGER NOT NULL DEFAULT 0,
            forwards INTEGER NOT NULL DEFAULT 0,
            photos INTEGER NOT NULL DEFAULT 0,
            videos INTEGER NOT NULL DEFAULT 0,
            gifs INTEGER NOT NULL DEFAULT 0,
            files INTEGER NOT NULL DEFAULT 0,
            voices INTEGER NOT NULL DEFAULT 0,
            contacts INTEGER NOT NULL DEFAULT 0,
            locations INTEGER NOT NULL DEFAULT 0,
            stickers INTEGER NOT NULL DEFAULT 0,
            polls INTEGER NOT NULL DEFAULT 0,
            long_text INTEGER NOT NULL DEFAULT 0,
            caps INTEGER NOT NULL DEFAULT 0,
            flood INTEGER NOT NULL DEFAULT 0,
            repeat_messages INTEGER NOT NULL DEFAULT 0
        );

        CREATE TABLE IF NOT EXISTS warnings (
            chat_id INTEGER NOT NULL,
            user_id INTEGER NOT NULL,
            count INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY(chat_id, user_id)
        );

        CREATE TABLE IF NOT EXISTS admin_cache (
            chat_id INTEGER NOT NULL,
            user_id INTEGER NOT NULL,
            role TEXT NOT NULL DEFAULT 'administrator',
            PRIMARY KEY(chat_id, user_id)
        );

        CREATE TABLE IF NOT EXISTS missions (
            user_id INTEGER NOT NULL,
            day TEXT NOT NULL,
            hops INTEGER NOT NULL DEFAULT 0,
            games INTEGER NOT NULL DEFAULT 0,
            collect INTEGER NOT NULL DEFAULT 0,
            claimed INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY(user_id, day)
        );

        CREATE TABLE IF NOT EXISTS music_library (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            file_id TEXT NOT NULL,
            title TEXT DEFAULT 'موزیک بدون نام',
            created_at INTEGER NOT NULL
        );

        CREATE TABLE IF NOT EXISTS game_scores (
            user_id INTEGER NOT NULL,
            game TEXT NOT NULL,
            wins INTEGER NOT NULL DEFAULT 0,
            losses INTEGER NOT NULL DEFAULT 0,
            draws INTEGER NOT NULL DEFAULT 0,
            plays INTEGER NOT NULL DEFAULT 0,
            points INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY(user_id, game)
        );

        CREATE TABLE IF NOT EXISTS reports (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            chat_id INTEGER NOT NULL,
            reporter_id INTEGER NOT NULL,
            target_id INTEGER NOT NULL,
            reason TEXT DEFAULT '',
            status TEXT NOT NULL DEFAULT 'open',
            created_at INTEGER NOT NULL
        );

        CREATE TABLE IF NOT EXISTS bot_settings (
            key TEXT PRIMARY KEY,
            value TEXT DEFAULT ''
        );

        CREATE TABLE IF NOT EXISTS user_profiles (
            user_id INTEGER PRIMARY KEY,
            bio TEXT DEFAULT '',
            city TEXT DEFAULT '',
            origin TEXT DEFAULT '',
            nickname TEXT DEFAULT '',
            joined_at INTEGER DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS exemptions (
            chat_id INTEGER NOT NULL,
            user_id INTEGER NOT NULL,
            reason TEXT DEFAULT '',
            PRIMARY KEY(chat_id,user_id)
        );
        CREATE TABLE IF NOT EXISTS challenges (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            title TEXT NOT NULL,
            created_at INTEGER NOT NULL,
            done INTEGER DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS admin_audit (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            chat_id INTEGER, user_id INTEGER, action TEXT, target_id INTEGER DEFAULT 0, created_at INTEGER
        );
        CREATE TABLE IF NOT EXISTS chat_member_stats (
            chat_id INTEGER NOT NULL, user_id INTEGER NOT NULL, username TEXT DEFAULT '', first_name TEXT DEFAULT '',
            messages INTEGER NOT NULL DEFAULT 0, first_seen INTEGER NOT NULL DEFAULT 0, last_seen INTEGER NOT NULL DEFAULT 0, is_bot INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY(chat_id,user_id)
        );
        CREATE TABLE IF NOT EXISTS daily_stats (
            chat_id INTEGER NOT NULL, day TEXT NOT NULL, messages INTEGER NOT NULL DEFAULT 0, joins INTEGER NOT NULL DEFAULT 0, leaves INTEGER NOT NULL DEFAULT 0,
            games INTEGER NOT NULL DEFAULT 0, commands INTEGER NOT NULL DEFAULT 0, deleted INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY(chat_id,day)
        );
        CREATE TABLE IF NOT EXISTS group_items (
            chat_id INTEGER NOT NULL, user_id INTEGER NOT NULL, item_key TEXT NOT NULL, bought_at INTEGER NOT NULL,
            PRIMARY KEY(chat_id,user_id,item_key)
        );
        """)
        # Backward-compatible profile fields for existing databases.
        profile_cols = {r[1] for r in c.execute("PRAGMA table_info(user_profiles)").fetchall()}
        if "origin" not in profile_cols:
            c.execute("ALTER TABLE user_profiles ADD COLUMN origin TEXT DEFAULT ''")
        if "nickname" not in profile_cols:
            c.execute("ALTER TABLE user_profiles ADD COLUMN nickname TEXT DEFAULT ''")
        cols = {r[1] for r in c.execute("PRAGMA table_info(users)").fetchall()}
        if "last_hop_at" not in cols:
            c.execute("ALTER TABLE users ADD COLUMN last_hop_at INTEGER NOT NULL DEFAULT 0")
        chat_cols = {r[1] for r in c.execute("PRAGMA table_info(chats)").fetchall()}
        if "goodbye_enabled" not in chat_cols:
            c.execute("ALTER TABLE chats ADD COLUMN goodbye_enabled INTEGER NOT NULL DEFAULT 0")
        if "goodbye_text" not in chat_cols:
            c.execute("ALTER TABLE chats ADD COLUMN goodbye_text TEXT DEFAULT ''")
        extra_chat_cols = {
            "welcome_media_type":"TEXT DEFAULT ''", "welcome_media_id":"TEXT DEFAULT ''",
            "goodbye_media_type":"TEXT DEFAULT ''", "goodbye_media_id":"TEXT DEFAULT ''",
            "reaction_enabled":"INTEGER NOT NULL DEFAULT 0", "reaction_emoji":"TEXT DEFAULT '👍'",
            "reaction_timeout":"INTEGER NOT NULL DEFAULT 45", "auto_cleanup_enabled":"INTEGER NOT NULL DEFAULT 0",
            "auto_cleanup_seconds":"INTEGER NOT NULL DEFAULT 300"
        }
        for col, spec in extra_chat_cols.items():
            if col not in chat_cols:
                c.execute(f"ALTER TABLE chats ADD COLUMN {col} {spec}")
        self.conn.commit()

    async def execute(self, sql, params=(), fetch=False, many=False):
        async with self.lock:
            cur = self.conn.cursor()
            if many:
                cur.executemany(sql, params)
            else:
                cur.execute(sql, params)
            rows = cur.fetchall() if fetch else None
            self.conn.commit()
            return rows

    async def all(self, sql, params=()):
        """Return all rows for read queries used by feature modules."""
        return await self.execute(sql, params, fetch=True)

    async def one(self, sql, params=()):
        rows = await self.execute(sql, params, fetch=True)
        return rows[0] if rows else None

    async def close(self):
        async with self.lock:
            self.conn.commit()
            self.conn.close()

    async def ensure_user(self, user):
        if not user:
            return
        ts = now_ts()
        await self.execute("""
            INSERT INTO users(user_id,username,first_name,created_at,updated_at)
            VALUES(?,?,?,?,?)
            ON CONFLICT(user_id) DO UPDATE SET
              username=excluded.username,
              first_name=excluded.first_name,
              updated_at=excluded.updated_at
        """, (user.id, user.username or "", user.first_name or "", ts, ts))

    async def ensure_chat(self, chat):
        if not chat:
            return
        ts = now_ts()
        await self.execute("""
            INSERT INTO chats(chat_id,title,created_at,updated_at)
            VALUES(?,?,?,?)
            ON CONFLICT(chat_id) DO UPDATE SET title=excluded.title,updated_at=excluded.updated_at
        """, (chat.id, chat.title or "", ts, ts))
        await self.execute("INSERT OR IGNORE INTO locks(chat_id) VALUES(?)", (chat.id,))

    async def get_user(self, uid):
        return await self.one("SELECT * FROM users WHERE user_id=?", (uid,))

    async def get_chat(self, cid):
        return await self.one("SELECT * FROM chats WHERE chat_id=?", (cid,))

    async def get_locks(self, cid):
        return await self.one("SELECT * FROM locks WHERE chat_id=?", (cid,))

    async def add_xp(self, uid, amount):
        await self.ensure_user(type("U", (), {"id": uid, "username": "", "first_name": ""})())
        row = await self.get_user(uid)
        xp = max(0, row["xp"] + amount)
        level = max(1, 1 + xp // 100)
        await self.execute("UPDATE users SET xp=?,level=?,updated_at=? WHERE user_id=?", (xp, level, now_ts(), uid))
        return xp, level

    async def add_bones(self, uid, amount):
        await self.execute("UPDATE users SET bones=MAX(0,bones+?),updated_at=? WHERE user_id=?", (amount, now_ts(), uid))

    async def set_dog_name(self, uid, name):
        await self.execute("UPDATE users SET dog_name=?,updated_at=? WHERE user_id=?", (safe_text(name, 30), now_ts(), uid))

    async def warn(self, cid, uid):
        await self.execute("""
            INSERT INTO warnings(chat_id,user_id,count) VALUES(?,?,1)
            ON CONFLICT(chat_id,user_id) DO UPDATE SET count=count+1
        """, (cid, uid))
        row = await self.one("SELECT count FROM warnings WHERE chat_id=? AND user_id=?", (cid, uid))
        return row["count"] if row else 0

    async def clear_warn(self, cid, uid):
        await self.execute("DELETE FROM warnings WHERE chat_id=? AND user_id=?", (cid, uid))

    async def add_game(self, uid, game, result):
        w = 1 if result == "win" else 0
        l = 1 if result == "loss" else 0
        d = 1 if result == "draw" else 0
        p = 3 if result == "win" else (1 if result == "draw" else 0)
        await self.execute("""
            INSERT INTO game_scores(user_id,game,wins,losses,draws,plays,points)
            VALUES(?,?,?,?,?,?,?)
            ON CONFLICT(user_id,game) DO UPDATE SET
              wins=wins+excluded.wins,
              losses=losses+excluded.losses,
              draws=draws+excluded.draws,
              plays=plays+1,
              points=points+excluded.points
        """, (uid, game, w, l, d, 1, p))
        await self.execute("""
            UPDATE users SET games=games+1,
                wins=wins+?,losses=losses+?,draws=draws+?,xp=xp+?,updated_at=?
            WHERE user_id=?
        """, (w, l, d, p * 5, now_ts(), uid))

    async def hop(self, uid):
        await self.ensure_user(type("U", (), {"id": uid, "username": "", "first_name": ""})())
        row = await self.get_user(uid)
        now = now_ts()
        last = int(row["last_hop_at"] or 0)
        wait = 300 - (now - last)
        if wait > 0:
            return False, wait, 0, 0, int(row["xp"]), int(row["dog_level"])
        xp_gain = random.choice([2, 3, 4, 5, 6, 8, 10])
        bone_gain = random.choice([1, 1, 2, 2, 3])
        new_xp = int(row["xp"]) + xp_gain
        new_level = max(1, 1 + new_xp // 100)
        new_dog_level = max(int(row["dog_level"]), 1 + new_xp // 50)
        await self.execute("UPDATE users SET xp=?,level=?,dog_level=?,bones=bones+?,last_hop_at=?,updated_at=? WHERE user_id=?", (new_xp,new_level,new_dog_level,bone_gain,now,now,uid))
        await self.mission_inc(uid, "hops", 1)
        return True, 0, xp_gain, bone_gain, new_xp, new_dog_level

    async def mission(self, uid):
        d = today()
        await self.execute("INSERT OR IGNORE INTO missions(user_id,day) VALUES(?,?)", (uid, d))
        return await self.one("SELECT * FROM missions WHERE user_id=? AND day=?", (uid, d))

    async def mission_inc(self, uid, field, amount=1):
        if field not in {"hops", "games", "collect"}:
            return
        await self.execute("INSERT OR IGNORE INTO missions(user_id,day) VALUES(?,?)", (uid, today()))
        await self.execute(f"UPDATE missions SET {field}={field}+? WHERE user_id=? AND day=?", (amount, uid, today()))

DBX: Optional[DB] = None

