# -----------------------------------------------------------------------------
# PERMISSION HELPERS
# -----------------------------------------------------------------------------

async def is_owner(uid: int) -> bool:
    # مالک اصلی همیشه معتبر است؛ OWNER_ID محیطی فقط می‌تواند مالک دیگری را
    # اضافه کند و باعث از دست رفتن دسترسی مالک اصلی نمی‌شود.
    if int(uid or 0) == OWNER_ID_DEFAULT:
        return True
    owner = os.getenv(OWNER_ENV, "").strip()
    return bool(owner and str(uid) == owner)


async def is_admin(update: Update, uid: Optional[int] = None) -> bool:
    if not update.effective_chat:
        return False
    uid = uid or (update.effective_user.id if update.effective_user else 0)
    if await is_owner(uid):
        return True
    if update.effective_chat.type == "private":
        return False
    try:
        member = await update.effective_chat.get_member(uid)
        return member.status in {ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER}
    except TelegramError:
        return False


async def bot_can_delete(chat) -> bool:
    try:
        me = await chat.get_member(chat.get_member)
    except Exception:
        pass
    return True

