async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.effective_user:
        return
    await DBX.ensure_user(update.effective_user)
    if update.effective_chat and update.effective_chat.type == "private":
        await update.effective_message.reply_text(PRIVATE_TEXT, parse_mode="HTML", reply_markup=private_keyboard())
    else:
        await send_group_panel(update, context)


async def private_gateway(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.effective_chat or update.effective_chat.type != "private":
        return
    await update.effective_message.reply_text(PRIVATE_TEXT, parse_mode="HTML", reply_markup=private_keyboard())


