async def send_group_panel(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.effective_chat or not update.effective_user or not update.effective_message:
        return
    await DBX.ensure_chat(update.effective_chat)
    await DBX.ensure_user(update.effective_user)
    uid=update.effective_user.id
    u=await DBX.get_user(uid)
    admin=await is_admin(update,uid)
    text=(f"🐾 <b>پنل کاربری بیل بیلک</b>\n\n👤 {mention_html(update.effective_user)}\n"
          f"🐕 هاپو: <b>{safe_text(u['dog_name'])}</b> | سطح {u['dog_level']}\n"
          f"⭐ سطح کاربر: <b>{u['level']}</b> | XP: <b>{u['xp']}</b>\n"
          f"🦴 استخوان: <b>{u['bones']}</b>\n\n"
          "🔐 این پنل فقط برای خودت قابل استفاده است.")
    if admin:
        text += "\n🛡 پنل مدیریتت جداست و فقط خودت می‌توانی دکمه‌هایش را اجرا کنی."
    await update.effective_message.reply_text(text,parse_mode="HTML",reply_markup=group_home_keyboard(uid,admin))

async def send_admin_panel(q, context):
    if not q.message or not q.message.chat:
        return
    uid=q.from_user.id
    fake=Update(update_id=0,callback_query=q)
    if not await is_admin(fake,uid):
        await q.answer("⛔ این پنل فقط برای ادمین‌های واقعی است.",show_alert=True); return
    await q.edit_message_text("🛡 <b>پنل مدیریت شخصی تو</b>\n\nاین پنل فقط برای خودت است؛ ادمین دیگری نمی‌تواند دکمه‌هایش را اجرا کند.",parse_mode="HTML",reply_markup=management_keyboard(uid))

