async def dog_name_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.effective_chat or update.effective_chat.type == "private":
        return
    if not update.message.reply_to_message and not await is_admin(update):
        # name changes are allowed for the user themselves; state is local to user
        pass
    context.user_data["awaiting_dog_name"] = True
    await update.message.reply_text("✏️ اسم جدید هاپو رو در پیام بعدی بفرست.\nمثلاً: <b>رکس</b>", parse_mode="HTML")


async def claim_mission(q):
    uid = q.from_user.id
    m = await DBX.mission(uid)
    if m["claimed"]:
        await q.answer("پاداش امروز قبلاً گرفته شده.", show_alert=True)
        return
    if m["hops"] >= 3 and m["games"] >= 2 and m["collect"] >= 1:
        await DBX.execute("UPDATE missions SET claimed=1 WHERE user_id=? AND day=?", (uid, today()))
        await DBX.add_xp(uid, 25)
        await DBX.add_bones(uid, 10)
        await q.answer("🎁 پاداش گرفتی! +25 XP و +10 استخوان", show_alert=True)
        await q.edit_message_text("🎁 <b>پاداش امروز دریافت شد!</b>\n\n⭐ +25 XP\n🦴 +10 استخوان\n\nفردا مأموریت تازه داری.", parse_mode="HTML", reply_markup=keyboard([[btn("🔙 برگشت", "u:home")]]))
    else:
        await q.answer("هنوز مأموریت‌ها کامل نشده‌اند.", show_alert=True)

