async def game_callback(q, context):
    parts=(q.data or "").split(":",2)
    if len(parts)!=3 or parts[0]!="game" or int(parts[1])!=q.from_user.id:
        await q.answer("آقا این پنل تو نیست 😄",show_alert=True); return
    game=parts[2]; uid=q.from_user.id
    await DBX.ensure_user(q.from_user)
    if game=="rps":
        await q.edit_message_text("✊ <b>سنگ‌کاغذقیچی</b>\nانتخاب کن:",parse_mode="HTML",reply_markup=keyboard([[btn("✊ سنگ",f"rps:{uid}:rock"),btn("📄 کاغذ",f"rps:{uid}:paper")],[btn("✂️ قیچی",f"rps:{uid}:scissors")],[btn("🔙 بازی‌ها",user_cb(uid,"games"))]])); return
    if game=="number":
        context.user_data["guess_number"]=random.randint(1,10)
        await q.edit_message_text("🔢 <b>حدس عدد</b>\n\nیک عدد بین 1 تا 10 در پیام بعدی بفرست.",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 بازی‌ها",user_cb(uid,"games"))]])); return
    if game=="math":
        a,b=random.randint(2,15),random.randint(2,15); op=random.choice(["+","-"]); ans=a+b if op=="+" else a-b
        context.user_data["math_answer"]=ans
        await q.edit_message_text(f"➗ <b>ریاضی</b>\n\nجواب {a} {op} {b} چند است؟ در پیام بعدی بفرست.",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 بازی‌ها",user_cb(uid,"games"))]])); return
    if game=="word":
        word=random.choice(["هاپو","باران","کتاب","مدرسه","ربات","تلگرام"]); context.user_data["word_answer"]=word
        await q.edit_message_text(f"🔤 <b>کلمه</b>\n\nاین کلمه {len(word)} حرف دارد. یک حدس بزن.",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 بازی‌ها",user_cb(uid,"games"))]])); return
    if game=="memory":
        seq=" ".join(random.sample(["🍎","🐶","⚽","🚗","🌟","🎵"],4)); context.user_data["memory_answer"]=seq
        await q.edit_message_text(f"🧠 <b>حافظه</b>\n\n<b>{seq}</b>\n\nبعدش همان ترتیب را بفرست.",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 بازی‌ها",user_cb(uid,"games"))]])); return
    if game=="quiz":
        question,answer=random.choice([("پایتخت ایران چیست؟","تهران"),("2+2 چند است؟","4"),("بیل بیلک چه حیوانی است؟","سگ")]); context.user_data["quiz_answer"]=answer
        await q.edit_message_text(f"❓ <b>کوییز</b>\n\n{question}\n\nجوابت را در پیام بعدی بفرست.",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 بازی‌ها",user_cb(uid,"games"))]])); return
    if game=="ttt":
        context.user_data["ttt_board"]=[" "]*9
        await q.edit_message_text("⭕ <b>دوز</b>\n\nتو ❌ هستی و بیل بیلک ⭕. خانه را انتخاب کن.",parse_mode="HTML",reply_markup=keyboard([[btn(str(i),f"ttt:{uid}:{i}") for i in range(1,4)],[btn(str(i),f"ttt:{uid}:{i}") for i in range(4,7)],[btn(str(i),f"ttt:{uid}:{i}") for i in range(7,10)],[btn("🔙 بازی‌ها",user_cb(uid,"games"))]])); return
    if game=="truth":
        await q.edit_message_text("🎯 <b>حقیقت</b>\n\n"+random.choice(["امروز بابت چه چیزی خوشحال شدی؟","آخرین چیزی که یاد گرفتی چی بود؟","دوست داری چه مهارتی یاد بگیری؟"]),parse_mode="HTML",reply_markup=keyboard([[btn("🔄 یکی دیگه",f"game:{uid}:truth")],[btn("🔙 بازی‌ها",user_cb(uid,"games"))]]))

async def rps_callback(q):
    parts=(q.data or "").split(":",2)
    if len(parts)!=3 or parts[0]!="rps" or int(parts[1])!=q.from_user.id:
        await q.answer("آقا این پنل تو نیست 😄",show_alert=True); return
    user_choice=parts[2]; names={"rock":"سنگ","paper":"کاغذ","scissors":"قیچی"}
    if user_choice not in names: return
    bot_choice=random.choice(list(names)); win={("rock","scissors"),("paper","rock"),("scissors","paper")}
    if user_choice==bot_choice: result="draw"; msg="مساوی شد! 😄"
    elif (user_choice,bot_choice) in win: result="win"; msg="بردی! 🏆"
    else: result="loss"; msg="این دور رو باختی؛ دور بعد جبران کن 😄"
    await DBX.add_game(q.from_user.id,"rps",result); await DBX.mission_inc(q.from_user.id,"games",1)
    await q.edit_message_text(f"✊ انتخاب تو: {names[user_choice]}\n🤖 انتخاب بیل بیلک: {names[bot_choice]}\n\n<b>{msg}</b>",parse_mode="HTML",reply_markup=keyboard([[btn("🔁 دوباره",f"game:{q.from_user.id}:rps")],[btn("🔙 بازی‌ها",user_cb(q.from_user.id,"games"))]]))

async def ttt_callback(q, context):
    parts=(q.data or "").split(":",2)
    if len(parts)!=3 or parts[0]!="ttt" or int(parts[1])!=q.from_user.id:
        await q.answer("آقا این بازی برای تو نیست 😄",show_alert=True); return
    uid=q.from_user.id; pos=int(parts[2])
    board=context.user_data.setdefault("ttt_board",[" "]*9)
    if not 1<=pos<=9 or board[pos-1]!=" ":
        await q.answer("این خانه قبلاً انتخاب شده.",show_alert=True); return
    board[pos-1]="X"
    def winner(b):
        for a,b1,c in [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]:
            if b[a]!=" " and b[a]==b[b1]==b[c]: return b[a]
        return None
    w=winner(board)
    if not w and " " in board:
        empt=[i for i,v in enumerate(board) if v==" "]
        # simple defensive/random bot
        move=random.choice(empt); board[move]="O"; w=winner(board)
    symbols={"X":"❌","O":"⭕"," ":"▫️"}
    text="⭕ <b>دوز</b>\n\n"+"\n".join(" ".join(f"{i+1}:{symbols[board[i]]}" for i in range(r,r+3)) for r in (0,3,6))
    if w:
        result="win" if w=="X" else "loss"; await DBX.add_game(uid,"ttt",result); context.user_data.pop("ttt_board",None)
        text+=f"\n\n🏁 {'تو بردی! 🏆' if w=='X' else 'این دور را بیل بیلک برد 😄'}"
        await q.edit_message_text(text,parse_mode="HTML",reply_markup=keyboard([[btn("🔁 دوباره",f"game:{uid}:ttt")],[btn("🔙 بازی‌ها",user_cb(uid,"games"))]])); return
    if " " not in board:
        await DBX.add_game(uid,"ttt","draw"); context.user_data.pop("ttt_board",None); text+="\n\n🤝 مساوی شد!"
        await q.edit_message_text(text,parse_mode="HTML",reply_markup=keyboard([[btn("🔁 دوباره",f"game:{uid}:ttt")],[btn("🔙 بازی‌ها",user_cb(uid,"games"))]])); return
    rows=[]
    for r in range(0,9,3): rows.append([btn(symbols[board[i]] if board[i]!=" " else str(i+1),f"ttt:{uid}:{i+1}") for i in range(r,r+3)])
    rows.append([btn("🔙 بازی‌ها",user_cb(uid,"games"))])
    await q.edit_message_text(text+"\n\nخانه بعدی را انتخاب کن:",parse_mode="HTML",reply_markup=keyboard(rows))

