async def lock_toggle(q):
    parts=(q.data or "").split(":",3)
    if len(parts)!=4 or parts[0]!="a" or parts[2]!="lock":
        await q.answer("پنل نامعتبر است.",show_alert=True); return
    owner=int(parts[1])
    if owner!=q.from_user.id:
        await q.answer("آقا این پنل تو نیست 😄",show_alert=True); return
    if not await is_admin(Update(update_id=0,callback_query=q),owner):
        await q.answer("⛔ فقط ادمین واقعی.",show_alert=True); return
    cid=q.message.chat.id; field=parts[3]
    if field not in LOCK_FIELDS: return
    l=await DBX.get_locks(cid); current=int(l[field]) if l else 0
    await DBX.execute(f"UPDATE locks SET {field}=? WHERE chat_id=?",(0 if current else 1,cid))
    await q.answer("انجام شد")
    l=await DBX.get_locks(cid); pairs=[(label,f,int(l[f])) for f,(label,_) in LOCK_FIELDS.items()]
    await q.edit_message_text("🔒 <b>قفل‌های گروه</b>\n\nوضعیت‌ها ذخیره و اعمال شدند.",parse_mode="HTML",reply_markup=locks_keyboard(pairs,owner))

