async def target_from_reply(update):
    if not update.message or not update.message.reply_to_message:
        return None
    return update.message.reply_to_message.from_user


async def moderation_action(update: Update, context: ContextTypes.DEFAULT_TYPE, action: str):
    if not await is_admin(update):
        await update.message.reply_text("⛔ فقط ادمین واقعی گروه می‌تواند این کار را انجام دهد.")
        return
    target = await target_from_reply(update)
    if not target:
        await update.message.reply_text("👤 روی پیام کاربر ریپلای کن و دوباره دستور را بفرست.")
        return
    if await is_owner(target.id):
        await update.message.reply_text("⛔ این کار روی مالک تنظیم‌شده انجام نمی‌شود.")
        return
    chat = update.effective_chat
    try:
        if action == "warn":
            count = await DBX.warn(chat.id, target.id)
            # قالب جدید اخطار: سقف ثابت ۳ اخطار و در اخطار سوم، سکوت ۱۱۶ روزه.
            max_warnings = 3
            giver = update.effective_user
            target_name = safe_text(getattr(target, "full_name", None) or getattr(target, "first_name", None) or "کاربر", 80)
            target_name = html.escape(target_name)
            giver_mention = mention_html(giver) if giver else "ادمین"

            if count < max_warnings:
                warning_text = (
                    f"🔖 کاربر 〚 {target_name} 〛\n\n"
                    f"• {count}اخطار دریافت کرد اگر به حداکثر اخطار یعنی 3 اخطار برسد\n"
                    f"به مدت 116روز سکوت میشود\n"
                    f" ─┅━━🄰🄿🄸━━┅─\n"
                    f"📎 توسط : {giver_mention}"
                )
                await update.message.reply_text(warning_text, parse_mode="HTML")
            else:
                mute_until = datetime.now() + timedelta(days=116)
                await chat.restrict_member(
                    target.id,
                    ChatPermissions(can_send_messages=False),
                    until_date=mute_until
                )
                warning_text = (
                    f"🔖 کاربر 〚 {target_name} 〛\n\n"
                    f"• {count}اخطار دریافت کرد و به حداکثر اخطار یعنی 3 اخطار رسید\n"
                    f"به مدت 116روز سکوت شد\n"
                    f" ─┅━━🄰🄿🄸━━┅─\n"
                    f"📎 توسط : {giver_mention}"
                )
                await update.message.reply_text(warning_text, parse_mode="HTML")
                await DBX.clear_warn(chat.id, target.id)
        elif action == "unwarn":
            await DBX.clear_warn(chat.id, target.id)
            await update.message.reply_text("✅ اخطارهای کاربر پاک شد.")
        elif action == "mute":
            minutes = 10
            await chat.restrict_member(target.id, ChatPermissions(can_send_messages=False), until_date=datetime.now() + timedelta(minutes=minutes))
            await update.message.reply_text(f"🔇 {mention_html(target)} برای {minutes} دقیقه محدود شد.", parse_mode="HTML")
        elif action == "unmute":
            perms = ChatPermissions(can_send_messages=True, can_send_audios=True, can_send_documents=True, can_send_photos=True, can_send_videos=True, can_send_video_notes=True, can_send_voice_notes=True, can_send_polls=True, can_send_other_messages=True, can_add_web_page_previews=True)
            await chat.restrict_member(target.id, perms)
            await update.message.reply_text("🔊 محدودیت کاربر برداشته شد.")
        elif action == "ban":
            await chat.ban_member(target.id)
            await update.message.reply_text("🚫 کاربر از گروه حذف شد.")
        elif action == "unban":
            await chat.unban_member(target.id, only_if_banned=True)
            await update.message.reply_text("✅ بن کاربر برداشته شد.")
    except TelegramError as e:
        await update.message.reply_text(f"⚠️ اجرای عملیات ممکن نشد. دسترسی ربات و وضعیت ادمینی را بررسی کن.\n{safe_text(str(e),200)}", parse_mode="HTML")

# -----------------------------------------------------------------------------
# CONTENT LOCK ENGINE
# -----------------------------------------------------------------------------

URL_RE = re.compile(r"(?:https?://|www\.|t\.me/|telegram\.me/|(?:[a-z0-9-]+\.)+(?:com|ir|org|net|io|me|co|ly)(?:/|\b))", re.I)


def classify_message(message):
    if message.forward_origin is not None:
        return "forwards"
    if message.photo:
        return "photos"
    if message.video:
        return "videos"
    if message.animation:
        return "gifs"
    if message.document:
        return "files"
    if message.voice or message.video_note:
        return "voices"
    if message.contact:
        return "contacts"
    if message.location or message.venue:
        return "locations"
    if message.sticker:
        return "stickers"
    if message.poll:
        return "polls"
    text = message.text or message.caption or ""
    if URL_RE.search(text):
        return "links"
    if len(text) > 700:
        return "long_text"
    letters = [c for c in text if c.isalpha() and c.isascii()]
    if len(letters) >= 8 and sum(c.isupper() for c in letters) / max(1, len(letters)) >= 0.8:
        return "caps"
    return None


async def enforce_locks(update: Update) -> bool:
    msg = update.effective_message
    chat = update.effective_chat
    user = update.effective_user
    if not msg or not chat or chat.type == "private" or not user:
        return False
    if await is_admin(update, user.id):
        return False
    ex = await DBX.one("SELECT 1 FROM exemptions WHERE chat_id=? AND user_id=?", (chat.id, user.id))
    if ex:
        return False
    await DBX.ensure_chat(chat)
    locks = await DBX.get_locks(chat.id)
    field = classify_message(msg)
    if field and int(locks[field]):
        try:
            await msg.delete()
            return True
        except TelegramError:
            return False

    key = (chat.id, user.id)
    text = normalize(msg.text or msg.caption or "")
    if int(locks["flood"]):
        q = FLOOD_STATE[key]
        t = time.monotonic()
        q.append(t)
        while q and t - q[0] > 8:
            q.popleft()
        if len(q) >= 9:
            try:
                await msg.delete()
            except TelegramError:
                pass
            return True
    if int(locks["repeat_messages"]) and text:
        q = REPEAT_STATE[key]
        t = time.monotonic()
        q.append((t, text))
        while q and t - q[0][0] > 12:
            q.popleft()
        if sum(1 for _, x in q if x == text) >= 3:
            try:
                await msg.delete()
            except TelegramError:
                pass
            return True
    return False

