# MUSIC
# -----------------------------------------------------------------------------

async def music_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg = update.message
    if not msg or not update.effective_user:
        return
    t = normalize(msg.text or "")
    if t in {"ذخیره موزیک", "ذخیره آهنگ"}:
        if not msg.reply_to_message or not msg.reply_to_message.audio:
            await msg.reply_text("🎵 باید روی یک فایل Audio ریپلای کنی و بعد «ذخیره موزیک» بفرستی.")
            return
        audio = msg.reply_to_message.audio
        title = audio.title or audio.file_name or "موزیک بدون نام"
        await DBX.execute("INSERT INTO music_library(user_id,file_id,title,created_at) VALUES(?,?,?,?)", (update.effective_user.id, audio.file_id, title, now_ts()))
        await DBX.mission_inc(update.effective_user.id, "collect", 1)
        await msg.reply_text(f"🎵 ذخیره شد: <b>{safe_text(title,100)}</b>", parse_mode="HTML")
        return
    if t in {"پخش موزیک", "پخش آهنگ"}:
        row = await DBX.one("SELECT file_id,title FROM music_library WHERE user_id=? ORDER BY id DESC LIMIT 1", (update.effective_user.id,))
        if not row:
            await msg.reply_text("🎵 هنوز موزیکی ذخیره نکردی.")
            return
        await msg.reply_audio(row["file_id"], caption=f"🎵 {safe_text(row['title'],100)}")
        return

