async def rules_command(update, context):
    c = await DBX.get_chat(update.effective_chat.id)
    await update.message.reply_text(c["rules_text"] or "📜 قانونی ثبت نشده.")


async def set_rules(update, context):
    if not await is_admin(update):
        await update.message.reply_text("⛔ فقط ادمین.")
        return
    text = safe_text(" ".join(context.args), 1000)
    if not text:
        await update.message.reply_text("فرمت: /setrules متن قوانین")
        return
    await DBX.execute("UPDATE chats SET rules_text=?,updated_at=? WHERE chat_id=?", (text, now_ts(), update.effective_chat.id))
    await update.message.reply_text("📜 قوانین ذخیره شد.")


async def set_welcome(update, context):
    if not await is_admin(update):
        await update.message.reply_text("⛔ فقط ادمین.")
        return
    text = safe_text(" ".join(context.args), 500)
    await DBX.execute("UPDATE chats SET welcome_enabled=1,welcome_text=?,updated_at=? WHERE chat_id=?", (text or "خوش اومدی! 🐾", now_ts(), update.effective_chat.id))
    await update.message.reply_text("👋 خوش‌آمد روشن و ذخیره شد.")


async def toggle_welcome(update, context):
    if not await is_admin(update):
        return
    c = await DBX.get_chat(update.effective_chat.id)
    await DBX.execute("UPDATE chats SET welcome_enabled=? WHERE chat_id=?", (0 if c["welcome_enabled"] else 1, update.effective_chat.id))
    await update.message.reply_text("👋 وضعیت خوش‌آمد تغییر کرد.")


async def set_goodbye(update, context):
    if not await is_admin(update):
        await update.message.reply_text("⛔ فقط ادمین."); return
    text=safe_text(" ".join(context.args),500)
    await DBX.execute("UPDATE chats SET goodbye_enabled=1,goodbye_text=?,updated_at=? WHERE chat_id=?",(text or "👋 {name} از جمع ما خارج شد. امیدواریم دوباره ببینیمت!",now_ts(),update.effective_chat.id))
    await update.message.reply_text("👋 خداحافظی روشن و ذخیره شد. متغیرها: {name}، {id}، {username}")

async def toggle_goodbye(update, context):
    if not await is_admin(update): return
    c=await DBX.get_chat(update.effective_chat.id)
    await DBX.execute("UPDATE chats SET goodbye_enabled=? WHERE chat_id=?",(0 if c["goodbye_enabled"] else 1,update.effective_chat.id))
    await update.message.reply_text("👋 وضعیت خداحافظی تغییر کرد.")

async def forcejoin_command(update, context):
    if not await is_admin(update):
        await update.message.reply_text("⛔ فقط ادمین.")
        return
    cid = update.effective_chat.id
    args = context.args
    if not args:
        c = await DBX.get_chat(cid)
        await update.message.reply_text(f"🔗 کانال جوین اجباری: {c['forced_channel'] or 'تنظیم نشده'}\nبرای تنظیم: /forcejoin @channel\nبرای خاموش: /forcejoin off")
        return
    val = args[0]
    if val.lower() == "off":
        await DBX.execute("UPDATE chats SET forced_channel='' WHERE chat_id=?", (cid,))
        await update.message.reply_text("🔓 جوین اجباری خاموش شد.")
    else:
        await DBX.execute("UPDATE chats SET forced_channel=? WHERE chat_id=?", (val, cid))
        await update.message.reply_text(f"🔐 جوین اجباری روی {safe_text(val,100)} تنظیم شد.")


async def report_command(update, context):
    target = await target_from_reply(update)
    if not target:
        await update.message.reply_text("📣 روی پیام کاربر ریپلای کن و «گزارش» بفرست.")
        return
    reason = " ".join(context.args) if context.args else "بدون توضیح"
    await DBX.execute("INSERT INTO reports(chat_id,reporter_id,target_id,reason,created_at) VALUES(?,?,?,?,?)", (update.effective_chat.id, update.effective_user.id, target.id, safe_text(reason,300), now_ts()))
    await update.message.reply_text("📣 گزارش ثبت شد و در پنل مدیریت قابل مشاهده است.")


async def pin_command(update, context):
    if not await is_admin(update):
        await update.message.reply_text("⛔ فقط ادمین.")
        return
    if not update.message.reply_to_message:
        await update.message.reply_text("📌 روی پیام موردنظر ریپلای کن.")
        return
    try:
        await update.message.reply_to_message.pin(disable_notification=True)
        await update.message.reply_text("📌 پیام پین شد.")
    except TelegramError as e:
        await update.message.reply_text(f"⚠️ پین نشد: {safe_text(str(e),180)}")


async def cleanup(update, context, count=20):
    if not await is_admin(update):
        await update.message.reply_text("⛔ فقط ادمین.")
        return
    chat_id = update.effective_chat.id
    deleted = 0
    base = update.message.message_id
    for mid in range(base, max(0, base - count), -1):
        try:
            await context.bot.delete_message(chat_id, mid)
            deleted += 1
        except TelegramError:
            pass
    try:
        await context.bot.send_message(chat_id, f"🧹 پاکسازی انجام شد. تعداد موفق: {deleted}")
    except TelegramError:
        pass


# -----------------------------------------------------------------------------
# NEW MEMBERS / WELCOME / FORCE JOIN CHECK
# -----------------------------------------------------------------------------

async def new_member(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat = update.effective_chat
    cm = update.chat_member
    if not chat or not cm:
        return
    old_status = cm.old_chat_member.status
    new_status = cm.new_chat_member.status
    user = cm.new_chat_member.user
    if user.is_bot:
        return
    await DBX.ensure_chat(chat)
    await DBX.ensure_user(user)
    c = await DBX.get_chat(chat.id)
    joined = new_status in {ChatMemberStatus.MEMBER, ChatMemberStatus.RESTRICTED, ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER} and old_status in {ChatMemberStatus.LEFT, ChatMemberStatus.BANNED}
    left = new_status in {ChatMemberStatus.LEFT, ChatMemberStatus.BANNED} and old_status in {ChatMemberStatus.MEMBER, ChatMemberStatus.RESTRICTED, ChatMemberStatus.ADMINISTRATOR}
    if joined and c["welcome_enabled"]:
        text = c["welcome_text"] or "👋 خوش اومدی {name}!\n🐾 بیل بیلک امیدوارم اینجا بهت خوش بگذره.\n📝 برای راهنما «راهنما» رو بفرست."
        text=text.replace("{name}",mention_html(user)).replace("{id}",str(user.id)).replace("{username}",("@"+user.username if user.username else "بدون آیدی"))
        try: await chat.send_message(text,parse_mode="HTML")
        except TelegramError: pass
    if left and c["goodbye_enabled"]:
        text=c["goodbye_text"] or "👋 {name} از جمع ما خارج شد.\n🐾 امیدواریم دوباره ببینیمت!"
        text=text.replace("{name}",safe_text(display_name(user),60)).replace("{id}",str(user.id)).replace("{username}",("@"+user.username if user.username else "بدون آیدی"))
        try: await chat.send_message(text,parse_mode="HTML")
        except TelegramError: pass

async def enforce_forcejoin(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    chat=update.effective_chat; user=update.effective_user; msg=update.effective_message
    if not chat or chat.type=="private" or not user or not msg: return False
    if await is_admin(update,user.id): return False
    c=await DBX.get_chat(chat.id)
    channel=(c["forced_channel"] if c else "") or ""
    if not channel: return False
    try:
        member=await context.bot.get_chat_member(channel,user.id)
        if member.status not in {ChatMemberStatus.MEMBER,ChatMemberStatus.ADMINISTRATOR,ChatMemberStatus.OWNER,ChatMemberStatus.RESTRICTED}:
            raise TelegramError("not member")
        return False
    except TelegramError:
        try: await msg.delete()
        except TelegramError: pass
        join_url=channel if channel.startswith("http") else "https://t.me/"+channel.lstrip("@").strip()
        try:
            await chat.send_message(
                f"🔐 <b>جوین اجباری فعال است</b>\n\n{mention_html(user)} برای ارسال پیام باید ابتدا عضو کانال مشخص‌شده شود.\n\nبعد از عضویت، پیام بعدی‌ات به‌طور عادی پذیرفته می‌شود.",
                parse_mode="HTML",reply_markup=keyboard([[btn("📢 عضویت در کانال",url=join_url)]])
            )
        except TelegramError: pass
        return True

# -----------------------------------------------------------------------------
# MESSAGE ROUTER
# -----------------------------------------------------------------------------

async def process_text_state(update, context) -> bool:
    msg = update.message
    if not msg or not msg.text:
        return False
    t = normalize(msg.text)
    uid = update.effective_user.id

    if context.user_data.get("awaiting_dog_name"):
        name = safe_text(msg.text, 30)
        await DBX.set_dog_name(uid, name)
        context.user_data.pop("awaiting_dog_name", None)
        await msg.reply_text(f"🐕 اسم هاپو شد: <b>{name}</b>", parse_mode="HTML")
        return True

    if "guess_number" in context.user_data and t.isdigit():
        target = context.user_data.pop("guess_number")
        guess = int(t)
        result = "win" if guess == target else "loss"
        await DBX.add_game(uid, "number", result)
        await DBX.mission_inc(uid, "games", 1)
        await msg.reply_text("🏆 درست حدس زدی!" if result == "win" else f"😄 این بار نه! عدد {target} بود.")
        return True

    if "math_answer" in context.user_data and re.fullmatch(r"-?\d+", t):
        target = context.user_data.pop("math_answer")
        result = "win" if int(t) == target else "loss"
        await DBX.add_game(uid, "math", result)
        await DBX.mission_inc(uid, "games", 1)
        await msg.reply_text("➗ آفرین، درست بود!" if result == "win" else f"جواب درست {target} بود.")
        return True

    if "word_answer" in context.user_data:
        target = context.user_data.pop("word_answer")
        result = "win" if t == normalize(target) else "loss"
        await DBX.add_game(uid, "word", result)
        await DBX.mission_inc(uid, "games", 1)
        await msg.reply_text("🔤 درست گفتی!" if result == "win" else f"کلمه «{target}» بود.")
        return True

    if "memory_answer" in context.user_data:
        target=context.user_data.pop("memory_answer")
        result="win" if normalize(msg.text)==normalize(target) else "loss"
        await DBX.add_game(uid,"memory",result); await DBX.mission_inc(uid,"games",1)
        await msg.reply_text("🧠 عالی! ترتیب را درست گفتی و بردی! 🏆" if result=="win" else f"🧠 این بار نه 😄\nترتیب درست: <b>{safe_text(target,100)}</b>",parse_mode="HTML")
        return True

    if "quiz_answer" in context.user_data:
        target = context.user_data.pop("quiz_answer")
        result = "win" if t == normalize(target) else "loss"
        await DBX.add_game(uid, "quiz", result)
        await DBX.mission_inc(uid, "games", 1)
        await msg.reply_text("❓ درست! 🏆" if result == "win" else f"جواب درست: {target}")
        return True

    if t == "هاپ هاپ" or t == "هاپهاپ":
        ok,wait,xp_gain,bone_gain,new_xp,dog_level=await DBX.hop(uid)
        if not ok:
            mins,secs=wait//60,wait%60
            await msg.reply_text(f"⏳ هاپویی عجله نکن 😄\nحداقل ۵ دقیقه بین هر هاپ هاپ فاصله است.\n⏱ زمان باقی‌مانده: <b>{mins:02d}:{secs:02d}</b>",parse_mode="HTML")
            return True
        await msg.reply_text(f"🐾 هاپ هاپ! {mention_html(update.effective_user)}\n⭐ <b>+{xp_gain} XP</b>\n🦴 <b>+{bone_gain} استخوان</b>\n🐕 سطح هاپو: <b>{dog_level}</b>\n\n🎲 جایزه این دفعه با دفعه قبل فرق داشت!",parse_mode="HTML")
        return True

    if t in {"ذخیره موزیک", "ذخیره آهنگ", "پخش موزیک", "پخش آهنگ"}:
        await music_text(update, context)
        return True

    if context.user_data.get("owner_broadcast") and await is_owner(uid):
        context.user_data.pop("owner_broadcast",None)
        text=safe_text(msg.text,3500)
        rows=await DBX.execute("SELECT chat_id FROM chats",fetch=True)
        sent=0
        for r in rows:
            try:
                await context.bot.send_message(r["chat_id"],"📣 <b>پیام مالک بیل بیلک</b>\n\n"+text,parse_mode="HTML")
                sent+=1
            except TelegramError: pass
        await msg.reply_text(f"📣 ارسال تمام شد. موفق: <b>{sent}</b> گروه.",parse_mode="HTML")
        return True

    # Rich utility commands / features
    if await rich_text_command(update, context, t):
        return True

    # Text lock aliases: «قفل لینک» / «باز کردن لینک» and similar
    lock_aliases={
        "لینک":"links","فوروارد":"forwards","عکس":"photos","ویدیو":"videos","گیف":"gifs","فایل":"files",
        "ویس":"voices","مخاطب":"contacts","لوکیشن":"locations","استیکر":"stickers","نظرسنجی":"polls",
        "متن بلند":"long_text","حروف بزرگ":"caps","ضدفلود":"flood","تکرار":"repeat_messages"
    }
    if t.startswith("قفل ") or t.startswith("باز کردن "):
        if await is_admin(update):
            action_word="قفل" if t.startswith("قفل ") else "باز کردن"
            label=t.split(None,1)[1].strip()
            field=lock_aliases.get(label)
            if field:
                await DBX.ensure_chat(update.effective_chat)
                await DBX.execute(f"UPDATE locks SET {field}=? WHERE chat_id=?",(1 if action_word=="قفل" else 0,update.effective_chat.id))
                await msg.reply_text(f"🔒 قفل «{label}» {'فعال' if action_word=='قفل' else 'خاموش'} شد.")
                return True
        await msg.reply_text("⛔ تنظیم قفل‌ها فقط برای ادمین است."); return True

    # Management aliases
    actions = {
        "اخطار": "warn", "حذف اخطار": "unwarn", "سکوت": "mute", "رفع سکوت": "unmute",
        "بن": "ban", "رفع بن": "unban", "پین": "pin", "گزارش": "report"
    }
    if t in actions:
        if t == "گزارش":
            await report_command(update, context)
        elif t == "پین":
            await pin_command(update, context)
        else:
            await moderation_action(update, context, actions[t])
        return True

    if t in {"مدیریت", "پنل مدیریت"}:
        if await is_admin(update):
            await msg.reply_text("🛡 پنل مدیریت شخصی تو:",reply_markup=management_keyboard(update.effective_user.id))
        else:
            await msg.reply_text("⛔ این بخش فقط برای ادمین‌های واقعی است.")
        return True
    if t == "قوانین":
        await rules_command(update, context)
        return True
    if t.startswith("جوین اجباری"):
        parts = msg.text.split()
        context.args = parts[2:] if len(parts) > 1 else []
        await forcejoin_command(update, context)
        return True
    if t.startswith("اسم هاپو"):
        await dog_name_start(update, context)
        return True
    if t == "راهنما" or t == "دستورها":
        await msg.reply_text("📚 <b>راهنمای بیل بیلک</b>\n\nهاپ هاپ | پنل | بازی‌ها | ابزارها | موزیکال | مدیریت | قوانین | گزارش", parse_mode="HTML", reply_markup=user_help_keyboard(update.effective_user.id))
        return True
    if t in {"پنل", "پنل کاربری", "بیل بیلک", "بیلبیلک"}:
        await send_group_panel(update, context)
        return True
    return False


async def message_router(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg = update.effective_message
    if not msg:
        return
    if update.effective_chat and update.effective_chat.type != "private":
        await DBX.ensure_chat(update.effective_chat)
    if update.effective_user:
        await DBX.ensure_user(update.effective_user)

    # پاسخ بازی/ورودی ابزار باید قبل از قفل محتوا تشخیص داده شود.
    if context.user_data.get("guess_number") is not None or context.user_data.get("math_answer") is not None or context.user_data.get("word_answer") is not None or context.user_data.get("quiz_answer") is not None or context.user_data.get("memory_answer") is not None or context.user_data.get("awaiting_dog_name"):
        if await process_text_state(update, context):
            return

    if await enforce_forcejoin(update, context):
        return

    if await enforce_locks(update):
        return

    if await process_text_state(update, context):
        return

    # Audio can be saved only by an explicit reply command, so no automatic action.
    if msg.text and msg.text.startswith("/"):
        return

