# CALLBACK DISPATCHER - SINGLE CALLBACK FUNCTION
# -----------------------------------------------------------------------------

async def callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q=update.callback_query
    if not q: return
    try: await q.answer()
    except TelegramError: pass
    data=q.data or ""
    if data=="pv:home": await q.edit_message_text(PRIVATE_TEXT,parse_mode="HTML",reply_markup=private_keyboard()); return
    if data=="pv:help": await private_help(update,context); return
    if data=="pv:join": await private_join(update,context); return
    if data=="pv:force": await private_force(update,context); return
    if data.startswith("u:"): await user_panel_callback(q,context); return
    if data.startswith("a:"):
        if len(data.split(":",2))==3 and data.split(":",2)[2].startswith("lock:"): await lock_toggle(q); return
        await management_callback(q,context); return
    if data.startswith("game:"): await game_callback(q,context); return
    if data.startswith("rps:"): await rps_callback(q); return
    if data.startswith("ttt:"): await ttt_callback(q,context); return
    if data.startswith("help:"):
        parts=data.split(":",2)
        if len(parts)==3 and parts[1].isdigit() and int(parts[1])==q.from_user.id and parts[2] in HELP_TEXTS:
            uid=q.from_user.id; await q.edit_message_text(HELP_TEXTS[parts[2]],parse_mode="HTML",reply_markup=keyboard([[btn("🔙 راهنمای اصلی",user_cb(uid,"help"))],[btn("🏠 خانه",user_cb(uid,"home"))]])); return
        await q.answer("این راهنما برای کاربر دیگری است 😄",show_alert=True); return
    if data.startswith("mission:"):
        parts=data.split(":",2)
        if len(parts)==3 and parts[1].isdigit() and int(parts[1])==q.from_user.id and parts[2]=="claim": await claim_mission(q); return
        await q.answer("این پنل تو نیست 😄",show_alert=True); return
    if data.startswith("music:"):
        parts=data.split(":",2)
        if len(parts)==3 and parts[1].isdigit() and int(parts[1])==q.from_user.id:
            if parts[2]=="play":
                row=await DBX.one("SELECT file_id,title FROM music_library WHERE user_id=? ORDER BY id DESC LIMIT 1",(q.from_user.id,))
                if not row: await q.answer("هنوز موزیکی ذخیره نشده.",show_alert=True); return
                await q.message.reply_audio(row["file_id"],caption=f"🎵 {safe_text(row['title'],100)}"); return
            if parts[2]=="clear": await DBX.execute("DELETE FROM music_library WHERE user_id=?",(q.from_user.id,)); await q.answer("ذخیره‌های موزیک پاک شدند.",show_alert=True); return
        await q.answer("این بخش برای کاربر دیگری است 😄",show_alert=True); return
    if data.startswith("rank:"):
        parts=data.split(":",2)
        if len(parts)==3 and parts[1].isdigit() and int(parts[1])==q.from_user.id and parts[2]=="games":
            rows=await DBX.execute("SELECT u.first_name,u.username,g.points FROM game_scores g JOIN users u ON u.user_id=g.user_id ORDER BY g.points DESC LIMIT 10",fetch=True)
            text="🏆 <b>جدول امتیاز بازی</b>\n\n"+("\n".join(f"{i+1}. {safe_text(r['first_name'],30)} — {r['points']} امتیاز" for i,r in enumerate(rows)) if rows else "هنوز امتیازی ثبت نشده.")
            await q.edit_message_text(text,parse_mode="HTML",reply_markup=keyboard([[btn("🔙 پروفایل",user_cb(q.from_user.id,"profile"))]])); return
        await q.answer("این پنل تو نیست 😄",show_alert=True); return
    if data.startswith("tool:"):
        parts=data.split(":",2)
        if len(parts)==3 and parts[1].isdigit() and int(parts[1])==q.from_user.id:
            tool=parts[2]
            if tool=="rules":
                c=await DBX.get_chat(q.message.chat.id); await q.edit_message_text(c["rules_text"] or "📜 قانونی ثبت نشده.",reply_markup=keyboard([[btn("🔙 ابزارها",user_cb(q.from_user.id,"tools"))]])); return
            if tool=="report": await q.answer("برای گزارش روی پیام کاربر ریپلای کن و «گزارش» بنویس.",show_alert=True); return
            if tool=="force": await q.edit_message_text("🔗 تنظیم جوین اجباری از پنل مدیریت انجام می‌شود.",reply_markup=keyboard([[btn("🛡 پنل مدیریت",admin_cb(q.from_user.id,"forcejoin"))],[btn("🔙 ابزارها",user_cb(q.from_user.id,"tools"))]])); return
        await q.answer("این ابزار برای کاربر دیگری است 😄",show_alert=True); return
    if data.startswith("dog:"):
        parts=data.split(":",2)
        if len(parts)==3 and parts[1].isdigit() and int(parts[1])==q.from_user.id and parts[2]=="name":
            context.user_data["awaiting_dog_name"]=True
            await q.answer("اسم جدید هاپو را در پیام بعدی بفرست.",show_alert=True); return
        await q.answer("این پنل تو نیست 😄",show_alert=True); return
    if data.startswith("owner:"):
        await owner_callback(q, context); return
    if data.startswith("mafia:"):
        await mafia_callback(q, context); return
    if data.startswith("rich:"):
        await rich_callback(q, context); return
    if data.startswith("a:") or data.startswith("u:"): return
    await q.answer("این دکمه دیگر فعال نیست. پنل خودت را دوباره باز کن.",show_alert=True)

# -----------------------------------------------------------------------------
# ERROR HANDLER
# -----------------------------------------------------------------------------

async def error_handler(update: object, context: ContextTypes.DEFAULT_TYPE):
    err = context.error
    if isinstance(err, BadRequest) and "Message is not modified" in str(err):
        return
    if isinstance(err, Forbidden):
        log.warning("Telegram permission error: %s", err)
        return
    log.exception("Unhandled error: %s", err)

# -----------------------------------------------------------------------------
# STARTUP / SHUTDOWN
# -----------------------------------------------------------------------------

async def post_init(application: Application):
    await application.bot.set_my_commands([
        ("start", "شروع"),
        ("help", "راهنما"),
        ("panel", "پنل"),
        ("features", "قابلیت‌ها"),
        ("rules", "قوانین"),
        ("forcejoin", "جوین اجباری"),
    ])
    log.info("%s %s started", BOT_NAME, BOT_VERSION)


async def post_shutdown(application: Application):
    global DBX, MUSIC_VC_CLIENT, MUSIC_VC_ENGINE, MUSIC_VC_STARTED
    try:
        if MUSIC_VC_ENGINE is not None:
            stop = getattr(MUSIC_VC_ENGINE, 'stop', None)
            if stop:
                result = stop()
                if hasattr(result, '__await__'): await result
    except Exception as exc: log.warning('Music VC engine shutdown: %s', exc)
    try:
        if MUSIC_VC_CLIENT is not None:
            stop_client = getattr(MUSIC_VC_CLIENT, 'stop', None)
            if stop_client:
                result = stop_client()
                if hasattr(result, '__await__'): await result
    except Exception as exc: log.warning('Music VC client shutdown: %s', exc)
    MUSIC_VC_ENGINE = None; MUSIC_VC_CLIENT = None; MUSIC_VC_STARTED = False
    if DBX:
        await DBX.close()


def _bb_prompt_value(label: str, env_key: str = "", default: str = "") -> str:
    """Ask for a missing setup value in the same terminal as BOT_TOKEN."""
    value = os.getenv(env_key, "").strip() if env_key else ""
    if not value and DBX:
        try:
            DBX.conn.execute("CREATE TABLE IF NOT EXISTS bot_settings (key TEXT PRIMARY KEY, value TEXT DEFAULT '')")
            row = DBX.conn.execute("SELECT value FROM bot_settings WHERE key=?", (env_key,)).fetchone() if env_key else None
            value = ((row[0] if row else "") or "").strip()
        except Exception:
            value = ""
    if value:
        return value
    prompt = f"{label}" + (f" [{default}]" if default else "") + ": "
    try:
        value = input(prompt).strip()
    except EOFError:
        value = ""
    return value or default


def _bb_save_startup_setting(key: str, value: str) -> None:
    if not value or not DBX:
        return
    try:
        DBX.conn.execute("CREATE TABLE IF NOT EXISTS bot_settings (key TEXT PRIMARY KEY, value TEXT DEFAULT '')")
        DBX.conn.execute("INSERT INTO bot_settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (key, value))
        DBX.conn.commit()
        os.environ[key] = value
    except Exception as exc:
        log.warning("Could not persist startup setting %s: %s", key, exc)


def _bb_configure_startup_inputs() -> None:
    """Music settings are configured from the owner's private bot panel.

    Deliberately no TELEGRAM_API_ID/API_HASH/phone/session prompts are shown in
    the terminal. BOT_TOKEN may still come from BOT_TOKEN env; if absent the
    normal token prompt is the only required startup input.
    """
    return


def get_token() -> str:
    token = (BOT_TOKEN or "").strip()
    if not token or token == "PASTE_BOT_TOKEN_HERE":
        token = os.getenv(TOKEN_ENV, "").strip()
    if not token:
        try:
            token = input("BOT_TOKEN: ").strip()
        except EOFError:
            token = ""
    if not token:
        raise RuntimeError("BOT_TOKEN داخل کد یا محیط اجرا تنظیم نشده است.")
    return token

def build_application(token: str) -> Application:
    app = (
        ApplicationBuilder()
        .token(token)
        .post_init(post_init)
        .post_shutdown(post_shutdown)
        .build()
    )
    app.add_handler(CommandHandler("start", start))
    app.add_handler(CommandHandler("help", cmd_help))
    app.add_handler(CommandHandler("panel", cmd_panel))
    app.add_handler(CommandHandler("adminpanel", cmd_adminpanel))
    app.add_handler(CommandHandler("owner", owner_panel))
    app.add_handler(CommandHandler("features", cmd_features))
    app.add_handler(CommandHandler("rules", rules_command))
    app.add_handler(CommandHandler("setrules", set_rules))
    app.add_handler(CommandHandler("welcome", set_welcome))
    app.add_handler(CommandHandler("togglewelcome", toggle_welcome))
    app.add_handler(CommandHandler("goodbye", set_goodbye))
    app.add_handler(CommandHandler("togglegoodbye", toggle_goodbye))
    app.add_handler(CommandHandler("tools", lambda u,c: rich_text_command(u,c,"ابزارها")))
    app.add_handler(CommandHandler("forcejoin", forcejoin_command))
    app.add_handler(CommandHandler("report", report_command))
    app.add_handler(CommandHandler("pin", pin_command))
    app.add_handler(CommandHandler("cleanup", lambda u,c: cleanup(u,c,20)))
    app.add_handler(CommandHandler("warn", lambda u,c: moderation_action(u,c,"warn")))
    app.add_handler(CommandHandler("unwarn", lambda u,c: moderation_action(u,c,"unwarn")))
    app.add_handler(CommandHandler("mute", lambda u,c: moderation_action(u,c,"mute")))
    app.add_handler(CommandHandler("unmute", lambda u,c: moderation_action(u,c,"unmute")))
    app.add_handler(CommandHandler("ban", lambda u,c: moderation_action(u,c,"ban")))
    app.add_handler(CommandHandler("unban", lambda u,c: moderation_action(u,c,"unban")))
    app.add_handler(CallbackQueryHandler(callback_router))
    app.add_handler(ChatMemberHandler(new_member, ChatMemberHandler.CHAT_MEMBER))
    app.add_handler(MessageHandler(filters.LOCATION, location_handler))
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND, message_router))
    app.add_error_handler(error_handler)
    return app


def main():
    global DBX
    DBX = DB(DB_PATH)
    token = get_token()
    log.info("Database: %s", os.path.abspath(DB_PATH))
    app = build_application(token)
    app.run_polling(allowed_updates=Update.ALL_TYPES, drop_pending_updates=True)



