    if t == "چالش انجام شد":
        row=await DBX.one("SELECT id FROM challenges WHERE user_id=? AND done=0 ORDER BY id DESC LIMIT 1",(uid,))
        if row:
            await DBX.execute("UPDATE challenges SET done=1 WHERE id=?",(row["id"],)); await DBX.add_xp(uid,10)
            await msg.reply_text("🏆 آفرین! چالش ثبت شد و <b>+10 XP</b> گرفتی.",parse_mode="HTML")
