    if action=="faith": await q.edit_message_text(random.choice(DUAS)+"\n\n"+random.choice(HADITHS),reply_markup=keyboard([[btn("🔄 تازه",f"rich:{uid}:faith")],[btn("🔙 ابزارها",f"rich:{uid}:home")]])); return
