def apply_font_style(text, style):
    row=FONT_STYLES.get(str(style))
    if not row: return text
    return text.translate(str.maketrans(row[1], row[2]))

# ------------------------- DB v3 migration -------------------------
async def ensure_v3_schema():
    await DBX.execute("CREATE TABLE IF NOT EXISTS chat_member_stats (chat_id INTEGER NOT NULL,user_id INTEGER NOT NULL,username TEXT DEFAULT '',first_name TEXT DEFAULT '',messages INTEGER NOT NULL DEFAULT 0,first_seen INTEGER NOT NULL DEFAULT 0,last_seen INTEGER NOT NULL DEFAULT 0,is_bot INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(chat_id,user_id))")
    await DBX.execute("CREATE TABLE IF NOT EXISTS daily_stats (chat_id INTEGER NOT NULL,day TEXT NOT NULL,messages INTEGER NOT NULL DEFAULT 0,joins INTEGER NOT NULL DEFAULT 0,leaves INTEGER NOT NULL DEFAULT 0,games INTEGER NOT NULL DEFAULT 0,commands INTEGER NOT NULL DEFAULT 0,deleted INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(chat_id,day))")
    await DBX.execute("CREATE TABLE IF NOT EXISTS group_items (chat_id INTEGER NOT NULL,user_id INTEGER NOT NULL,item_key TEXT NOT NULL,bought_at INTEGER NOT NULL,PRIMARY KEY(chat_id,user_id,item_key))")
    c=await DBX.get_chat(-999999999999)
    # Chat columns were added by the class migration. These INSERTs ensure old DBs have rows.
    await DBX.execute("INSERT OR IGNORE INTO daily_stats(chat_id,day) VALUES(?,?)",(-999999999999,"bootstrap"))
    await DBX.execute("DELETE FROM daily_stats WHERE chat_id=? AND day=?",(-999999999999,"bootstrap"))

async def record_member_message(update):
    chat=update.effective_chat; user=update.effective_user; msg=update.effective_message
    if not chat or chat.type=="private" or not user or not msg: return
    ts=now_ts(); day=today()
    await DBX.execute("""INSERT INTO chat_member_stats(chat_id,user_id,username,first_name,messages,first_seen,last_seen,is_bot) VALUES(?,?,?,?,1,?,?,?)
        ON CONFLICT(chat_id,user_id) DO UPDATE SET username=excluded.username,first_name=excluded.first_name,messages=messages+1,last_seen=excluded.last_seen,is_bot=excluded.is_bot""",
        (chat.id,user.id,user.username or "",user.first_name or "",ts,ts,1 if user.is_bot else 0))
    await DBX.execute("""INSERT INTO daily_stats(chat_id,day,messages) VALUES(?,?,1) ON CONFLICT(chat_id,day) DO UPDATE SET messages=messages+1""",(chat.id,day))
    await DBX.execute("UPDATE users SET messages=messages+1,updated_at=? WHERE user_id=?",(ts,user.id))

async def record_stat(chat_id, field, amount=1):
    if field not in {"messages","joins","leaves","games","commands","deleted"}: return
    await DBX.execute(f"INSERT INTO daily_stats(chat_id,day,{field}) VALUES(?,?,?) ON CONFLICT(chat_id,day) DO UPDATE SET {field}={field}+excluded.{field}",(chat_id,today(),amount))

# ------------------------- Welcome/goodbye media -------------------------
def _welcome_payload(msg):
    if not msg: return "", ""
    if msg.photo: return "photo", msg.photo[-1].file_id
    if msg.video: return "video", msg.video.file_id
    if msg.animation: return "animation", msg.animation.file_id
    if msg.document and (msg.document.mime_type or "").startswith("image/"): return "photo", msg.document.file_id
    return "", ""

def render_group_text(template,user):
    return (template or "").replace("{name}",mention_html(user)).replace("{id}",str(user.id)).replace("{username}",("@"+user.username if user.username else "بدون آیدی"))

async def send_group_media(chat, kind, file_id, caption):
    if not file_id: return
    if kind=="photo": await chat.send_photo(file_id,caption=caption or "",parse_mode="HTML")
    elif kind=="video": await chat.send_video(file_id,caption=caption or "",parse_mode="HTML")
    elif kind=="animation": await chat.send_animation(file_id,caption=caption or "",parse_mode="HTML")

async def set_welcome(update, context):
    if not await is_admin(update):
        await update.message.reply_text("⛔ فقط ادمین واقعی گروه می‌تواند خوش‌آمد را تنظیم کند."); return
    await DBX.ensure_chat(update.effective_chat)
    text=safe_text(" ".join(context.args),700)
    reply=update.message.reply_to_message
    kind,file_id=_welcome_payload(reply)
    if reply and not kind and not text:
        text=safe_text(reply.text or reply.caption or "",700)
    await DBX.execute("UPDATE chats SET welcome_enabled=1,welcome_text=?,welcome_media_type=?,welcome_media_id=?,updated_at=? WHERE chat_id=?",(text or "👋 خوش اومدی {name}! 🐾\nاز حضورت خوشحالیم؛ برای دیدن امکانات «راهنما» را بفرست.",kind,file_id,now_ts(),update.effective_chat.id))
    await update.message.reply_text("👋 خوش‌آمد روشن شد و تنظیمات ذخیره شد.\n📸 عکس / 🎞 GIF / 🎬 ویدیو + متن پشتیبانی می‌شود.\nبرای تغییر، روی رسانه ریپلای کن و دوباره /welcome بزن.")

async def set_goodbye(update, context):
    if not await is_admin(update):
        await update.message.reply_text("⛔ فقط ادمین واقعی گروه می‌تواند خداحافظی را تنظیم کند."); return
    await DBX.ensure_chat(update.effective_chat)
    text=safe_text(" ".join(context.args),700); reply=update.message.reply_to_message
    kind,file_id=_welcome_payload(reply)
    if reply and not kind and not text: text=safe_text(reply.text or reply.caption or "",700)
    await DBX.execute("UPDATE chats SET goodbye_enabled=1,goodbye_text=?,goodbye_media_type=?,goodbye_media_id=?,updated_at=? WHERE chat_id=?",(text or "👋 {name} از جمع ما خداحافظی کرد. امیدواریم دوباره ببینیمت!",kind,file_id,now_ts(),update.effective_chat.id))
    await update.message.reply_text("🚪 خداحافظی روشن شد و تنظیمات ذخیره شد.\n📸 عکس / 🎞 GIF / 🎬 ویدیو + متن پشتیبانی می‌شود.")

async def new_member(update, context):
    chat=update.effective_chat; cm=update.chat_member
    if not chat or not cm: return
    old_status=cm.old_chat_member.status; new_status=cm.new_chat_member.status; user=cm.new_chat_member.user
    if user.is_bot: return
    await DBX.ensure_chat(chat); await DBX.ensure_user(user); c=await DBX.get_chat(chat.id)
    joined=new_status in {ChatMemberStatus.MEMBER,ChatMemberStatus.RESTRICTED,ChatMemberStatus.ADMINISTRATOR,ChatMemberStatus.OWNER} and old_status in {ChatMemberStatus.LEFT,ChatMemberStatus.BANNED}
    left=new_status in {ChatMemberStatus.LEFT,ChatMemberStatus.BANNED} and old_status in {ChatMemberStatus.MEMBER,ChatMemberStatus.RESTRICTED,ChatMemberStatus.ADMINISTRATOR,ChatMemberStatus.OWNER}
    if joined:
        await DBX.execute("INSERT OR IGNORE INTO chat_member_stats(chat_id,user_id,username,first_name,first_seen,last_seen,is_bot) VALUES(?,?,?,?,?,?,?)",(chat.id,user.id,user.username or "",user.first_name or "",now_ts(),now_ts(),0))
        await record_stat(chat.id,"joins")
        if c["welcome_enabled"]:
            text=render_group_text(c["welcome_text"] or "👋 خوش اومدی {name}! 🐾",user)
            try:
                if c["welcome_media_id"]: await send_group_media_v4(chat,c["welcome_media_type"],c["welcome_media_id"],text,context.bot)
                else: await chat.send_message(text,parse_mode="HTML")
            except TelegramError: pass
    if left:
        await record_stat(chat.id,"leaves")
        # همیشه و بدون تنظیم روشن/خاموش: پیام بازگشت به پیوی کاربر
        # (در صورت مجاز بودن پیام خصوصی توسط Telegram).
        await _bb_send_return_to_group(update, context, user, chat)
        if c["goodbye_enabled"]:
            text=render_group_text(c["goodbye_text"] or "👋 {name} از جمع ما خداحافظی کرد.\n🐾 امیدواریم دوباره ببینیمت!",user)
            try:
                if c["goodbye_media_id"]: await send_group_media_v4(chat,c["goodbye_media_type"],c["goodbye_media_id"],text,context.bot)
                else: await chat.send_message(text,parse_mode="HTML")
            except TelegramError: pass

async def _bb_send_return_to_group(update, context, user, chat):
    """ارسال خودکار پیام بازگشت به کاربر بعد از ترک گروه.

    این قابلیت عمداً هیچ سوییچ روشن/خاموشی ندارد و برای تمام گروه‌ها
    به‌صورت خودکار اجرا می‌شود. لینک عمومی گروه یا لینک دعوت گروه
    استفاده می‌شود. اگر کاربر قبلاً ربات را Start نکرده باشد، تلگرام
    اجازه ارسال پیام خصوصی از طرف ربات را نمی‌دهد و خطا نادیده گرفته می‌شود.
    """
    if not user or getattr(user, "is_bot", False) or not chat or chat.type not in ("group", "supergroup"):
        return False
    try:
        group_link = ""
        username = getattr(chat, "username", None)
        if username:
            group_link = f"https://t.me/{username}"
        else:
            # getChat can expose the current invite link when the bot has the
            # required administrator rights. Do not revoke the group's primary link.
            try:
                full_chat = await context.bot.get_chat(chat.id)
                group_link = getattr(full_chat, "invite_link", None) or ""
            except TelegramError:
                group_link = ""
            if not group_link:
                try:
                    inv = await context.bot.create_chat_invite_link(
                        chat.id,
                        name="Bilbilak-return",
                        creates_join_request=False,
                    )
                    group_link = getattr(inv, "invite_link", None) or ""
                except TelegramError:
                    group_link = ""
        if not group_link:
            return False

        group_name = safe_text(getattr(chat, "title", None) or "گروه", 100)
        text = (
            f"👋 {mention_html(user)} عزیز، از <b>{group_name}</b> رفتی!\n\n"
            "🥺 برگرد به گروه، بدون تو خوش نمی‌گذره!\n"
            "🐾 بیل بیلک منتظرته 💚"
        )
        markup = InlineKeyboardMarkup([[
            InlineKeyboardButton("🔗 برگرد به گروه", url=group_link)
        ]])
        await context.bot.send_message(
            chat_id=user.id,
            text=text,
            parse_mode="HTML",
            reply_markup=markup,
        )
        return True
    except Forbidden:
        # Telegram blocks bots from initiating private conversations with users
        # who have never started the bot. This is expected and not a bot error.
        return False
    except TelegramError:
        log.debug("automatic return-to-group DM failed for user=%s chat=%s", user.id, chat.id, exc_info=True)
        return False
    except Exception:
        log.debug("automatic return-to-group DM unexpected failure", exc_info=True)
        return False


# ------------------------- Force join with setup validation -------------------------
async def _forcejoin_setup_check(bot, channel):
    me=await bot.get_me()
    member=await bot.get_chat_member(channel,me.id)
    if member.status not in {ChatMemberStatus.ADMINISTRATOR,ChatMemberStatus.OWNER}:
        return False,"ربات در کانال مقصد ادمین کامل نیست."
    return True,""

async def forcejoin_command(update, context):
    if not await is_admin(update): await update.message.reply_text("⛔ فقط ادمین."); return
    cid=update.effective_chat.id; args=context.args
    if not args:
        c=await DBX.get_chat(cid)
        await update.message.reply_text("🔐 <b>جوین اجباری</b>\n\nاول ربات را به کانال مقصد اضافه کن و <b>ادمین کامل</b>ش کن؛ بعد:\nجوین اجباری @channel\n\nخاموش: جوین اجباری off\n\nربات برای هر عضو، عضویت را از کانال مقصد بررسی می‌کند.",parse_mode="HTML"); return
    val=args[0]
    if val.lower()=="off":
        await DBX.execute("UPDATE chats SET forced_channel='' WHERE chat_id=?",(cid,)); await update.message.reply_text("🔓 جوین اجباری خاموش شد."); return
    try:
        ok,reason=await _forcejoin_setup_check(context.bot,val)
        if not ok:
            await update.message.reply_text("❌ جوین اجباری فعال نشد.\n\n"+reason+"\n\n📌 مراحل درست:\n1) ربات را وارد کانال مقصد کن.\n2) ربات را ادمین کامل کانال کن.\n3) دوباره همین دستور را بزن.")
            return
    except TelegramError as e:
        await update.message.reply_text("❌ کانال مقصد قابل بررسی نیست. مطمئن شو آیدی کانال درست است و ربات داخل کانال و ادمین کامل است.\n\n"+safe_text(str(e),180)+"",parse_mode="HTML"); return
    await DBX.execute("UPDATE chats SET forced_channel=? WHERE chat_id=?",(val,cid))
    await update.message.reply_text(f"🔐 جوین اجباری فعال شد.\n\n📢 مقصد: <b>{safe_text(val,100)}</b>\n🤖 وضعیت ربات: ادمین تأیید شد.\n\nهر عضو غیرادمین قبل از ارسال پیام باید عضو کانال باشد.",parse_mode="HTML")

# ------------------------- Forced reaction -------------------------
PENDING_REACTIONS={}

def _reaction_matches(update):
    r=update.message_reaction
    if not r or not r.user: return False
    c=PENDING_REACTIONS.get((r.chat.id,r.message_id))
    if not c or c["user_id"]!=r.user.id: return False
    wanted=c["emoji"]
    for x in (r.new_reaction or []):
        if getattr(x,"emoji",None)==wanted: return True
    return False

async def reaction_handler(update, context):
    r=update.message_reaction
    if not r: return
    key=(r.chat.id,r.message_id)
    pending=PENDING_REACTIONS.get(key)
    if not pending: return
    if _reaction_matches(update):
        PENDING_REACTIONS.pop(key,None)
        try: await context.bot.send_message(r.chat.id,f"✅ {mention_html(r.user)} واکنش اجباری را ثبت کرد. 🐾",parse_mode="HTML")
        except TelegramError: pass

async def reaction_timeout_job(context):
    key=context.job.data if context.job else None
    if not key: return
    pending=PENDING_REACTIONS.pop(tuple(key),None)
    if not pending: return
    try:
        await context.bot.delete_message(pending["chat_id"],pending["message_id"])
        await record_stat(pending["chat_id"],"deleted")
    except TelegramError: pass

async def apply_forced_reaction(update, context):
    msg=update.effective_message; chat=update.effective_chat; user=update.effective_user
    if not msg or not chat or chat.type=="private" or not user or await is_admin(update,user.id): return
    c=await DBX.get_chat(chat.id)
    if not c or not c["reaction_enabled"]: return
    emoji=c["reaction_emoji"] or "👍"; timeout=max(15,min(300,int(c["reaction_timeout"] or 45)))
    key=(chat.id,msg.message_id); PENDING_REACTIONS[key]={"chat_id":chat.id,"message_id":msg.message_id,"user_id":user.id,"emoji":emoji}
    try: await msg.reply_text(f"⚡ {mention_html(user)} برای نگه‌داشتن این پیام باید ظرف {timeout} ثانیه واکنش {emoji} را بزند.",parse_mode="HTML")
    except TelegramError: pass
    try: context.job_queue.run_once(reaction_timeout_job,timeout,data=key,name=f"reaction:{chat.id}:{msg.message_id}")
    except Exception: pass

# ------------------------- Stats -------------------------
async def stats_command(update, context):
    if not update.effective_chat or update.effective_chat.type=="private":
        await update.message.reply_text("📊 آمار روزانه/هفتگی/ماهانه فقط داخل گروه قابل نمایش است."); return
    if not await is_admin(update): await update.message.reply_text("⛔ فقط ادمین واقعی."); return
    mode=normalize(context.args[0]) if context.args else "روزانه"
    days={"روزانه":1,"هفتگی":7,"ماهانه":30}.get(mode,1)
    rows=await DBX.execute("SELECT SUM(messages) messages,SUM(joins) joins,SUM(leaves) leaves,SUM(games) games,SUM(commands) commands,SUM(deleted) deleted FROM daily_stats WHERE chat_id=? AND day>=date('now',?)",(update.effective_chat.id,f"-{days-1} day"),fetch=True)
    r=rows[0] if rows else None
    members=await DBX.one("SELECT COUNT(*) c FROM chat_member_stats WHERE chat_id=?",(update.effective_chat.id,))
    top=await DBX.execute("SELECT first_name,username,messages FROM chat_member_stats WHERE chat_id=? ORDER BY messages DESC LIMIT 5",(update.effective_chat.id,),fetch=True)
    text=f"📊 <b>آمار {mode}</b>\n\n💬 پیام‌ها: <b>{(r['messages'] or 0) if r else 0}</b>\n➕ ورود: <b>{(r['joins'] or 0) if r else 0}</b>\n➖ خروج: <b>{(r['leaves'] or 0) if r else 0}</b>\n🎮 بازی‌ها: <b>{(r['games'] or 0) if r else 0}</b>\n🧹 حذف‌ها: <b>{(r['deleted'] or 0) if r else 0}</b>\n👥 اعضای شناخته‌شده: <b>{members['c'] if members else 0}</b>\n\n🔥 <b>فعال‌ترین‌ها</b>\n"
    text += "\n".join(f"{i+1}. {safe_text(x['first_name'] or x['username'] or str(x['messages']),30)} — {x['messages']} پیام" for i,x in enumerate(top)) or "هنوز آماری ثبت نشده."
    await update.message.reply_text(text,parse_mode="HTML")

# ------------------------- Tag system -------------------------
async def tag_users(update, context, mode="active"):
    if not await is_admin(update): await update.message.reply_text("⛔ فقط ادمین واقعی."); return
    chat=update.effective_chat; rows=[]
    if update.message.reply_to_message:
        u=update.message.reply_to_message.from_user
        if u: rows=[u]
    else:
        admins=None
        if mode=="admins":
            admins=await chat.get_administrators(); rows=[a.user for a in admins if not a.user.is_bot]
        else:
            cond=""
            params=[chat.id]
            if mode=="bots": cond=" AND is_bot=1"
            elif mode=="under300": cond=" AND messages<300 AND is_bot=0"
            elif mode=="over500": cond=" AND messages>500 AND is_bot=0"
            elif mode=="active": cond=" AND is_bot=0 AND last_seen>=?"; params.append(now_ts()-7*86400)
            elif mode=="quiet": cond=" AND is_bot=0 AND messages<50"
            data=await DBX.execute("SELECT user_id,first_name,username,is_bot FROM chat_member_stats WHERE chat_id=?"+cond+" ORDER BY messages DESC LIMIT 300",tuple(params),fetch=True)
            rows=[type("U",(),{"id":x["user_id"],"first_name":x["first_name"],"username":x["username"],"is_bot":bool(x["is_bot"])})() for x in data]
    if not rows: await update.message.reply_text("👥 برای این دسته هنوز عضو شناخته‌شده‌ای ثبت نشده."); return
    chunks=[]; cur=""
    for u in rows:
        tag=mention_html(u)
        if len(cur)+len(tag)+2>3300:
            chunks.append(cur); cur=""
        cur += tag+"  "
    if cur: chunks.append(cur)
    for i,ch in enumerate(chunks,1): await update.message.reply_text(f"🏷️ <b>تگ {mode}</b> — بخش {i}/{len(chunks)}\n\n{ch}",parse_mode="HTML")

async def tag_command(update, context):
    t=normalize(update.message.text or "")
    mapping={"تگ ادمین ها":"admins","تگ ادمین‌ها":"admins","تگ همه":"all","تگ اعضا":"all","تگ اعضای فعال":"active","تگ ربات ها":"bots","تگ ربات‌ها":"bots","تگ زیر 300":"under300","تگ زیر۳۰۰":"under300","تگ بالای 500":"over500","تگ بالای۵۰۰":"over500","تگ کم حرف ها":"quiet","تگ کم‌حرف‌ها":"quiet"}
    mode=mapping.get(t)
    if mode:
        await tag_users(update,context,mode); return True
    if t=="تگ خودکار کم حرف":
        if not await is_admin(update): await update.message.reply_text("⛔ فقط ادمین."); return True
        data=await DBX.execute("SELECT user_id,first_name,username FROM chat_member_stats WHERE chat_id=? AND is_bot=0 AND messages<50 ORDER BY messages ASC LIMIT 20",(update.effective_chat.id,),fetch=True)
        for x in data:
            u=type("U",(),{"id":x["user_id"],"first_name":x["first_name"],"username":x["username"]})()
            await update.message.reply_text("🏷️ "+mention_html(u),parse_mode="HTML")
            await asyncio.sleep(0.35)
        return True
    return False

