# ------------------------- Real utility engines -------------------------
async def translate_real(text, target="fa"):
    import urllib.parse, urllib.request, json as _json
    query=urllib.parse.urlencode({"q":text,"langpair":"auto|"+target})
    url="https://api.mymemory.translated.net/get?"+query
    def fetch():
        with urllib.request.urlopen(url,timeout=8) as r: return _json.loads(r.read().decode("utf-8","ignore"))
    try:
        data=await asyncio.to_thread(fetch); return data.get("responseData",{}).get("translatedText")
    except Exception: return None

async def football_real(update, query):
    import urllib.parse, urllib.request, json as _json
    q=urllib.parse.quote(query)
    url=f"https://www.thesportsdb.com/api/v1/json/3/searchteams.php?t={q}"
    def fetch():
        with urllib.request.urlopen(url,timeout=8) as r: return _json.loads(r.read().decode("utf-8","ignore"))
    try:
        data=await asyncio.to_thread(fetch); teams=data.get("teams") or []
        if not teams: await update.message.reply_text("⚽ تیم پیدا نشد. نام انگلیسی یا نام کامل تیم را امتحان کن."); return
        t=teams[0]
        text=f"⚽ <b>{safe_text(t.get('strTeam',''),80)}</b>\n\n🌍 کشور: {safe_text(t.get('strCountry',''),60)}\n🏟 ورزشگاه: {safe_text(t.get('strStadium','ثبت نشده'),80)}\n📅 تأسیس: {safe_text(t.get('intFormedYear','ثبت نشده'),20)}\n\n📊 این بخش اطلاعات تیم را از منبع داده ورزشی می‌گیرد؛ اگر نتیجه زنده لازم داری، دستور «فوتبال زنده نام تیم» را بفرست."
        await update.message.reply_text(text,parse_mode="HTML")
    except Exception: await update.message.reply_text("⚽ سرویس فوتبال در این لحظه در دسترس نبود؛ دوباره امتحان کن.")

