# ------------------------- More difficult games -------------------------
async def game_callback(q, context):
    parts=(q.data or "").split(":",2)
    if len(parts)!=3 or not parts[1].isdigit() or int(parts[1])!=q.from_user.id:
        await q.answer("این بازی برای شما نیست.",show_alert=True); return
    uid=q.from_user.id; game=parts[2]
    if game=="number":
        context.user_data["guess_number"]=random.randint(1,100)
        await q.edit_message_text("🔢 <b>حدس عدد — حالت سخت</b>\n\nیک عدد بین <b>۱ تا ۱۰۰</b> انتخاب کردم.\nتا ۷ فرصت داری. هر حدس اشتباه یک راهنمایی گرم/سرد می‌دهد.\n\nعدد را در پیام بعدی بفرست.",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 بازی‌ها",user_cb(uid,"games"))]])); return
    if game=="math":
        a=random.randint(8,40); b=random.randint(3,20); c=random.randint(2,9); op=random.choice(["+","-"])
        ans=(a+b)*c if op=="+" else (a-b)*c
        context.user_data["math_answer"]=ans
        await q.edit_message_text(f"🧠 <b>ریاضی — سخت</b>\n\nحاصل <b>({a} {op} {b}) × {c}</b> چند است؟\nفقط جواب عددی را در پیام بعدی بفرست.",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 بازی‌ها",user_cb(uid,"games"))]])); return
    if game=="word":
        words=["ماجراجویی","کتابخانه","کامپیوتر","هواپیما","دریاچه","پژوهشگر","دوچرخه","کهکشان"]
        word=random.choice(words); context.user_data["word_answer"]=word
        hint=word[0]+"…"+word[-1]
        await q.edit_message_text(f"🔤 <b>کلمه — سخت</b>\n\nکلمه {len(word)} حرف دارد.\n💡 سرنخ: <b>{hint}</b>\n\nحدس خودت را در پیام بعدی بفرست.",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 بازی‌ها",user_cb(uid,"games"))]])); return
    if game=="memory":
        seq="-".join(str(random.randint(0,9)) for _ in range(8)); context.user_data["memory_answer"]=seq
        await q.edit_message_text(f"🧠 <b>حافظه — سخت</b>\n\nاین رشته را ۵ ثانیه نگاه کن و بعد همان ترتیب را با خط تیره بفرست:\n\n<b>{seq}</b>",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 بازی‌ها",user_cb(uid,"games"))]])); return
    if game=="quiz":
        qs=[("کدام سیاره به خورشید نزدیک‌تر است؟",["زهره","عطارد","زمین","مریخ"],"عطارد"),("کدام عدد اول است؟",["21","29","39","51"],"29"),("آب در فشار معمولی چند درجه می‌جوشد؟",["80","90","100","120"],"100")]
        question,opts,ans=random.choice(qs); context.user_data["quiz_answer"]=ans
        await q.edit_message_text("❓ <b>کوییز — سخت</b>\n\n"+question,parse_mode="HTML",reply_markup=keyboard([[btn(x,f"quizans:{uid}:{x}") for x in opts[:2]],[btn(x,f"quizans:{uid}:{x}") for x in opts[2:]]])) ; return
    # fall back to old implementation for RPS/TTT/truth
    await _OLD_GAME_CALLBACK(q,context)

# ------------------------- Multiple mafia rooms -------------------------
MAFIA_ROOMS={}
MAFIA_SCENARIOS={
 "fog":"🌫️ شهر در مه فرو رفته؛ هیچ‌کس مطمئن نیست چه کسی حقیقت را می‌گوید.",
 "train":"🚆 قطار نیمه‌شب؛ بازیکنان باید قبل از رسیدن به ایستگاه آخر هویت‌ها را کشف کنند.",
 "museum":"🏛️ موزه خاموش؛ سرنخ‌ها در گفت‌وگوها پنهان شده‌اند و رأی‌های عجولانه خطرناک‌اند.",
 "hotel":"🏨 هتل مرموز؛ هر شب اطلاعات جدیدی ظاهر می‌شود و تیم‌ها باید منطقی تصمیم بگیرند."
}
MAFIA_ROLES={"مافیا":"با هماهنگی تیم خود، شهر را گمراه کن.","پزشک":"هر دور یک نفر را برای محافظت انتخاب کن.","کارآگاه":"هر دور می‌توانی درباره یک بازیکن تحقیق کنی.","شهروند":"با تحلیل حرف‌ها و رأی‌گیری، تیم مخفی را پیدا کن."}

def mafia_room_keyboard(room_id, uid):
    return keyboard([[btn("➕ ورود",f"mf2:{room_id}:join"),btn("👥 بازیکنان",f"mf2:{room_id}:players")],[btn("▶️ شروع",f"mf2:{room_id}:start"),btn("🚪 خروج",f"mf2:{room_id}:leave")],[btn("🎬 سناریو",f"mf2:{room_id}:scenario"),btn("📚 راهنما",f"mf2:{room_id}:help")],[btn("🔙 اتاق‌ها",f"mf2:{room_id}:rooms")]])

async def mafia_start_menu(update, context):
    chat=update.effective_chat; uid=update.effective_user.id
    rooms=[r for r in MAFIA_ROOMS.values() if r["chat_id"]==chat.id]
    if not rooms:
        rid=f"{chat.id}:{random.randint(1000,9999)}"; MAFIA_ROOMS[rid]={"chat_id":chat.id,"host":uid,"players":{},"state":"lobby","roles":{},"votes":{},"scenario":random.choice(list(MAFIA_SCENARIOS))}
        rooms=[MAFIA_ROOMS[rid]]
    rows=[]
    for r in rooms[:8]:
        rid = next((k for k,v in MAFIA_ROOMS.items() if v is r), "")
        if rid:
            rows.append([btn(f"♟️ اتاق {rid.split(':')[-1]} — {len(r['players'])} نفر",f"mf2:{rid}:open")])
    rows.append([btn("➕ ساخت اتاق جدید",f"mfnew:{uid}:new")]); rows.append([btn("📚 راهنمای کل مافیا",f"mfhelp:{uid}:help")])
    await update.effective_message.reply_text("♟️ <b>شهر مافیا</b>\n\nچند اتاق می‌تواند همزمان در یک گروه فعال باشد. هر اتاق میزبان، سناریو، بازیکنان و رأی‌گیری مستقل دارد.\n\n🎬 سناریوها: شهر مه‌آلود، قطار نیمه‌شب، موزه خاموش، هتل مرموز.",parse_mode="HTML",reply_markup=keyboard(rows))

async def mafia_rooms_menu(update, context):
    """Compatibility entry point used by older management callbacks."""
    return await mafia_start_menu(update, context)

async def mafia2_callback(q,context):
    data=q.data or ""; parts=data.split(":")
    if len(parts)<3: await q.answer("دکمه مافیا نامعتبر است.",show_alert=True); return
    rid=parts[1]; action=":".join(parts[2:]); room=MAFIA_ROOMS.get(rid)
    if not room: await q.answer("این اتاق دیگر وجود ندارد.",show_alert=True); return
    uid=q.from_user.id
    if action=="rooms": await mafia_start_menu(type("U",(),{"effective_chat":q.message.chat,"effective_user":q.from_user,"effective_message":q.message})(),context); return
    if action=="join":
        if room["state"]!="lobby": await q.answer("بازی شروع شده.",show_alert=True); return
        if len(room["players"])>=12: await q.answer("اتاق پر است.",show_alert=True); return
        room["players"][uid]=display_name(q.from_user); await q.answer("وارد اتاق شدی! 🐾")
        await q.edit_message_text(f"♟️ <b>اتاق {rid.split(':')[-1]}</b>\n\n🎬 {MAFIA_SCENARIOS[room['scenario']]}\n\n👥 بازیکنان: <b>{len(room['players'])}/12</b>\n👑 میزبان: <b>{safe_text(room['players'].get(room['host'],'میزبان'),50)}</b>\n\nبرای شروع حداقل ۵ بازیکن پیشنهاد می‌شود.",parse_mode="HTML",reply_markup=mafia_room_keyboard(rid,uid)); return
    if action=="leave": room["players"].pop(uid,None); await q.answer("از اتاق خارج شدی."); return
    if action=="players":
        names="\n".join(f"{i+1}. {safe_text(n,40)}" for i,n in enumerate(room["players"].values())) or "هنوز کسی وارد نشده."
        await q.edit_message_text(f"👥 <b>بازیکنان اتاق {rid.split(':')[-1]}</b>\n\n{names}",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 اتاق",f"mf2:{rid}:rooms")]])); return
    if action=="scenario":
        room["scenario"]=random.choice(list(MAFIA_SCENARIOS)); await q.edit_message_text(f"🎬 <b>سناریوی جدید</b>\n\n{MAFIA_SCENARIOS[room['scenario']]}",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 اتاق",f"mf2:{rid}:rooms")]])); return
    if action=="help":
        text="♟️ <b>راهنمای کامل مافیا</b>\n\n1️⃣ بازیکنان وارد یک اتاق می‌شوند.\n2️⃣ میزبان وقتی تعداد کافی شد بازی را شروع می‌کند.\n3️⃣ نقش هر نفر خصوصی ارسال می‌شود.\n4️⃣ در هر دور گفت‌وگو و سپس رأی‌گیری انجام می‌شود.\n5️⃣ ربات وضعیت اتاق را با ویرایش پیام‌ها به‌روز می‌کند.\n6️⃣ نقش‌ها: مافیا، پزشک، کارآگاه، شهروند.\n\n🎭 <b>راهنمای نقش‌ها</b>\n"+"\n".join(f"• <b>{k}</b>: {v}" for k,v in MAFIA_ROLES.items())+"\n\n🏆 هدف: تیمی که شرایط برد را زودتر کامل کند برنده است. هیچ شرط پولی یا قمار در بازی وجود ندارد."
        await q.edit_message_text(text,parse_mode="HTML",reply_markup=keyboard([[btn("🔙 اتاق",f"mf2:{rid}:rooms")]])); return
    if action=="start":
        if uid!=room["host"]: await q.answer("فقط میزبان اتاق می‌تواند شروع کند.",show_alert=True); return
        if len(room["players"])<5: await q.answer("حداقل ۵ بازیکن برای سناریوی کامل لازم است.",show_alert=True); return
        ids=list(room["players"]); random.shuffle(ids); m=max(1,len(ids)//4); roles={x:"مافیا" for x in ids[:m]}; rest=ids[m:]
        if rest: roles[rest[0]]="پزشک"
        if len(rest)>1: roles[rest[1]]="کارآگاه"
        for x in rest[2:]: roles[x]="شهروند"
        room["roles"]=roles; room["state"]="running"; room["votes"]={}; room["turn"]=1
        for x,role in roles.items():
            try: await context.bot.send_message(x,f"♟️ <b>نقش مخفی تو</b>\n\n🎭 <b>{role}</b>\n{MAFIA_ROLES[role]}\n\nسناریو: {MAFIA_SCENARIOS[room['scenario']]}",parse_mode="HTML")
            except TelegramError: pass
        await q.edit_message_text(f"🌙 <b>دور ۱ شروع شد!</b>\n\n🎬 {MAFIA_SCENARIOS[room['scenario']]}\n\n🎭 نقش‌ها خصوصی ارسال شدند.\n🗣️ گفت‌وگو کنید و بعد رأی‌گیری را باز کنید.\n\n📡 وضعیت این پیام با هر مرحله به‌روزرسانی می‌شود.",parse_mode="HTML",reply_markup=keyboard([[btn("🗳️ رأی‌گیری",f"mf2:{rid}:vote")],[btn("👥 بازیکنان",f"mf2:{rid}:players")]])); return
    if action=="vote":
        if room["state"]!="running": await q.answer("بازی در حال اجرا نیست.",show_alert=True); return
        rows=[]
        for x,n in room["players"].items():
            if x!=uid: rows.append([btn(safe_text(n,24),f"mf2:{rid}:v:{x}")])
        await q.edit_message_text(f"🗳️ <b>رأی‌گیری دور {room.get('turn',1)}</b>\n\nبه کسی رأی بده که فکر می‌کنی عضو تیم مخفی است.\nرأی‌ها تا تکمیل شدن جمع می‌شوند.",parse_mode="HTML",reply_markup=keyboard(rows)); return
    if action.startswith("v:"):
        if uid not in room["players"]: await q.answer("تو در این اتاق نیستی.",show_alert=True); return
        target=int(action.split(":",1)[1]); room["votes"][uid]=target; total=len(room["players"]); got=len(room["votes"])
        if got<total: await q.answer(f"رأی ثبت شد: {got}/{total}",show_alert=True); return
        counts=defaultdict(int)
        for x in room["votes"].values(): counts[x]+=1
        mx=max(counts.values()); tops=[x for x,v in counts.items() if v==mx]
        if len(tops)==1:
            out=tops[0]; name=room["players"].pop(out,"بازیکن"); role=room["roles"].get(out,"شهروند"); room["votes"]={}; room["turn"]=room.get("turn",1)+1
            await q.edit_message_text(f"🗳️ <b>نتیجه دور {room['turn']-1}</b>\n\n👤 {safe_text(name,50)} بیشترین رأی را گرفت.\n🎭 نقش او: <b>{role}</b>\n\n🔄 دور بعدی آماده است. پیام اتاق به‌روز شد.",parse_mode="HTML",reply_markup=keyboard([[btn("🗳️ رأی‌گیری دور بعد",f"mf2:{rid}:vote")],[btn("👥 بازیکنان",f"mf2:{rid}:players")]])); return
        room["votes"]={}; await q.edit_message_text("🤝 <b>رأی مساوی شد!</b>\n\nهیچ بازیکنی از دور خارج نشد. دور بعدی را شروع کنید.",parse_mode="HTML",reply_markup=keyboard([[btn("🗳️ رأی‌گیری دوباره",f"mf2:{rid}:vote")]])); return
    if action=="open":
        await q.edit_message_text(f"♟️ <b>اتاق {rid.split(':')[-1]}</b>\n\n🎬 {MAFIA_SCENARIOS[room['scenario']]}\n👥 بازیکنان: <b>{len(room['players'])}/12</b>\n👑 میزبان: <b>{safe_text(room['players'].get(room['host'],'میزبان'),50)}</b>",parse_mode="HTML",reply_markup=mafia_room_keyboard(rid,uid)); return

async def mafia2_new_callback(q,context):
    uid=q.from_user.id; chat=q.message.chat.id; rid=f"{chat}:{random.randint(1000,9999)}"
    while rid in MAFIA_ROOMS: rid=f"{chat}:{random.randint(1000,9999)}"
    MAFIA_ROOMS[rid]={"chat_id":chat,"host":uid,"players":{uid:display_name(q.from_user)},"state":"lobby","roles":{},"votes":{},"scenario":random.choice(list(MAFIA_SCENARIOS))}
    await q.answer("اتاق جدید ساخته شد! 🐾"); await mafia2_callback(type("Q",(),{"data":f"mf2:{rid}:open","from_user":q.from_user,"message":q.message,"answer":q.answer,"edit_message_text":q.edit_message_text})(),context)

async def mafia2_help(q):
    await q.edit_message_text("♟️ <b>مافیا؛ راهنمای کامل</b>\n\n🎬 سناریوها جداگانه انتخاب می‌شوند.\n👑 میزبان فقط خودش می‌تواند بازی را شروع کند.\n👥 هر گروه می‌تواند چند اتاق همزمان داشته باشد.\n🎭 نقش‌ها خصوصی ارسال می‌شوند.\n🗳️ رأی‌ها جمع می‌شوند و نتیجه در همان پیام اتاق به‌روز می‌شود.\n📡 ربات در هر مرحله وضعیت جدید را نشان می‌دهد.\n\n⚠️ بازی اجتماعی و بدون شرط پولی است.",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 برگشت",user_cb(q.from_user.id,"games"))]]))

# ------------------------- Text state additions -------------------------
_OLD_PROCESS_TEXT_STATE=process_text_state
_OLD_GAME_CALLBACK=game_callback

async def process_text_state(update, context):
    msg=update.message; t=normalize(msg.text or "") if msg and msg.text else ""; uid=update.effective_user.id if update.effective_user else 0
    # Hard game states get priority and richer feedback.
    if "guess_number" in context.user_data and t.isdigit():
        target=context.user_data["guess_number"]; guess=int(t); tries=context.user_data.get("guess_tries",0)+1; context.user_data["guess_tries"]=tries
        if guess==target:
            context.user_data.pop("guess_number",None); context.user_data.pop("guess_tries",None); await DBX.add_game(uid,"number","win"); await record_stat(update.effective_chat.id,"games"); await msg.reply_text(f"🏆 فوق‌العاده! عدد <b>{target}</b> بود و در <b>{tries}</b> تلاش پیداش کردی.",parse_mode="HTML"); return True
        if tries>=7:
            context.user_data.pop("guess_number",None); context.user_data.pop("guess_tries",None); await DBX.add_game(uid,"number","loss"); await record_stat(update.effective_chat.id,"games"); await msg.reply_text(f"⌛ فرصت‌ها تمام شد! عدد <b>{target}</b> بود.",parse_mode="HTML"); return True
        hint="🔥 نزدیکه!" if abs(guess-target)<=8 else ("❄️ خیلی دوری!" if abs(guess-target)>=25 else "🌤️ فاصله متوسطه.")
        await msg.reply_text(f"🎯 حدست ثبت شد: <b>{guess}</b>\n{hint}\n⏳ فرصت باقی: <b>{7-tries}</b>",parse_mode="HTML"); return True
    if "quiz_answer" in context.user_data and t:
        ans=context.user_data.pop("quiz_answer"); ok=normalize(t)==normalize(ans); await DBX.add_game(uid,"quiz","win" if ok else "loss"); await record_stat(update.effective_chat.id,"games"); await msg.reply_text("🏆 درست بود!" if ok else f"❌ جواب درست <b>{ans}</b> بود.",parse_mode="HTML"); return True
    if t.startswith("فونت "):
        source=msg.text.split(None,1)[1]; lines=[f"📝 <b>{name}</b>\n{apply_font_style(source,k)}" for k,(name,_,__) in FONT_STYLES.items()]
        await msg.reply_text("\n\n".join(lines),parse_mode="HTML"); return True
    if t.startswith("ترجمه "):
        source=msg.text.split(None,1)[1]; result=await translate_real(source,"fa")
        if not result: result="🌐 سرویس ترجمه موقتاً پاسخ نداد."
        await msg.reply_text(f"🌐 <b>ترجمه</b>\n\n{safe_text(result,1500)}",parse_mode="HTML"); return True
    if t.startswith("تبدیل "):
        parts=msg.text.split();
        if len(parts)>=4:
            try:
                v=float(parts[1]); a=normalize(parts[2]); b=normalize(parts[3]); units={"کیلومتر":1000,"متر":1,"سانتیمتر":0.01,"سانتی متر":0.01,"میلیمتر":0.001,"میلی متر":0.001,"کیلوگرم":1000,"گرم":1,"کیلو":1000}
                if a in units and b in units: out=v*units[a]/units[b]; await msg.reply_text(f"🔄 <b>{v:g} {parts[2]}</b> = <b>{out:g} {parts[3]}</b>",parse_mode="HTML")
                else: await msg.reply_text("🔄 واحد ناشناخته است. نمونه: تبدیل 5 کیلومتر متر")
            except Exception: await msg.reply_text("🔄 قالب درست: تبدیل 5 کیلومتر متر")
        return True
    if t.startswith("فوتبال "):
        await football_real(update,msg.text.split(None,1)[1]); return True
    if t=="رادیو" or t.startswith("رادیو "):
        await radio_menu(update); return True
    if t.startswith("سرچ آهنگ ") or t.startswith("جستجوی آهنگ "):
        q=safe_text(msg.text.split(None,2)[-1],80); enc=quote_plus(q)
        await msg.reply_text(f"🔎 <b>جستجوی آهنگ</b>\n\n🎵 {safe_text(q,80)}\n\nاز نتایج رسمی استفاده کن:",parse_mode="HTML",reply_markup=keyboard([[btn("▶️ YouTube",url=f"https://www.youtube.com/results?search_query={enc}")],[btn("🎵 Spotify",url=f"https://open.spotify.com/search/{enc}")]])); return True
    if t in {"پروفایل","بیو"}:
        await send_full_profile(update); return True
    if t.startswith("بیو "):
        await DBX.execute("INSERT OR IGNORE INTO user_profiles(user_id,joined_at) VALUES(?,?)",(uid,now_ts())); await DBX.execute("UPDATE user_profiles SET bio=? WHERE user_id=?",(safe_text(msg.text.split(None,1)[1],500),uid)); await send_full_profile(update); return True
    if t=="فروشگاه" or t=="فروشگاه هاپو":
        rows=[]
        for k,(name,price) in SHOP_ITEMS.items(): rows.append([btn(f"{name} — {price}🦴",f"shop:{uid}:buy:{k}")])
        await msg.reply_text("🛍️ <b>فروشگاه هاپو</b>\n\nاینجا فقط با استخوان‌های داخل ربات آیتم تزئینی می‌خری؛ هیچ پول واقعی و هیچ شرطی در کار نیست.",parse_mode="HTML",reply_markup=keyboard(rows)); return True
    if t in {"تگ ادمین ها","تگ ادمین‌ها","تگ همه","تگ اعضا","تگ اعضای فعال","تگ ربات ها","تگ ربات‌ها","تگ زیر 300","تگ زیر۳۰۰","تگ بالای 500","تگ بالای۵۰۰","تگ کم حرف ها","تگ کم‌حرف‌ها","تگ خودکار کم حرف"}:
        return await tag_command(update,context)
    if t in {"آمار روزانه","آمار هفتگی","آمار ماهانه"}:
        context.args=[t.split()[-1]]; await stats_command(update,context); return True
    if t=="تغییر عکس گروه": await set_group_photo(update,context); return True
    if t.startswith("تغییر نام گروه "):
        context.args=msg.text.split()[3:]; await set_group_title(update,context); return True
    if t.startswith("تغییر بیو گروه "):
        context.args=msg.text.split()[3:]; await set_group_bio(update,context); return True
    if t=="قمار" or t.startswith("شرط"):
        await msg.reply_text("⛔ بخش قمار یا شرط‌بندی را نمی‌توانم اضافه کنم. به‌جایش فروشگاه هاپو و بازی‌های امتیازی بدون شرط فعال است."); return True
    if t.startswith("پاکسازی همه"):
        if await is_admin(update): await cleanup(update,context,100); return True
    if t.startswith("پاکسازی خودکار"):
        if not await is_admin(update): await msg.reply_text("⛔ فقط ادمین."); return True
        parts=t.split(); sec=int(parts[1]) if len(parts)>1 and parts[1].isdigit() else 300; sec=max(30,min(sec,3600)); await DBX.execute("UPDATE chats SET auto_cleanup_enabled=1,auto_cleanup_seconds=? WHERE chat_id=?",(sec,update.effective_chat.id)); await msg.reply_text(f"🧹 پاکسازی خودکار روشن شد: {sec} ثانیه."); return True
    if t=="خاموش پاکسازی خودکار":
        if await is_admin(update): await DBX.execute("UPDATE chats SET auto_cleanup_enabled=0 WHERE chat_id=?",(update.effective_chat.id,)); await msg.reply_text("🧹 پاکسازی خودکار خاموش شد."); return True
    if t.startswith("ری اکشن اجباری") or t.startswith("واکنش اجباری"):
        if not await is_admin(update): await msg.reply_text("⛔ فقط ادمین."); return True
        parts=t.split(); emoji=parts[2] if len(parts)>=3 else "👍"; await DBX.execute("UPDATE chats SET reaction_enabled=1,reaction_emoji=? WHERE chat_id=?",(emoji,update.effective_chat.id)); await msg.reply_text(f"⚡ ری‌اکشن اجباری روشن شد: {emoji}\nربات باید ادمین باشد و دریافت updateهای reaction فعال باشد."); return True
    if t in {"خاموش ری اکشن اجباری","خاموش واکنش اجباری"}:
        if await is_admin(update): await DBX.execute("UPDATE chats SET reaction_enabled=0 WHERE chat_id=?",(update.effective_chat.id,)); await msg.reply_text("⚡ ری‌اکشن اجباری خاموش شد."); return True
    if t=="راهنمای کامل":
        await msg.reply_text(COMPREHENSIVE_HELP,parse_mode="HTML"); return True
    return await _OLD_PROCESS_TEXT_STATE(update,context)

