def full_guide_keyboard(uid, page=0):
    rows=[]
    if page == 0:
        rows=[[btn("🐾 هاپویی و پروفایل",f"guide:{uid}:1"),btn("🎮 بازی‌ها",f"guide:{uid}:2")],
              [btn("🧰 ابزارها",f"guide:{uid}:3"),btn("🎵 موزیکال/دانلود",f"guide:{uid}:4")],
              [btn("🛡 مدیریت",f"guide:{uid}:5"),btn("🧹 پاکسازی/گروه",f"guide:{uid}:6")],
              [btn("👑 مالک و AI",f"guide:{uid}:7"),btn("🔗 آدرس فنی دکمه‌ها",f"guide:{uid}:8")]]
    else:
        rows=[[btn("⬅️ قبلی",f"guide:{uid}:{max(0,page-1)}"),btn("🏠 راهنمای اصلی",f"guide:{uid}:0")],
              [btn("➡️ بعدی",f"guide:{uid}:{page+1 if page<8 else 1}")]]
    return keyboard(rows)

async def _bb_full_guide_callback(q, context):
    d=q.data or ""
    m=re.fullmatch(r"guide:(\d+):(\d+)",d)
    if not m: return False
    uid,page=int(m.group(1)),int(m.group(2))
    if uid != q.from_user.id or page not in range(0,9):
        await q.answer("⛔ این راهنما برای کاربر دیگری است.",show_alert=True); return True
    text=COMPREHENSIVE_HELP if page==0 else GUIDE_PAGES[page]
    await q.edit_message_text(text,parse_mode="HTML",reply_markup=full_guide_keyboard(uid,page))
    return True


