_OLD_RICH_CALLBACK=rich_callback
async def rich_callback(q,context):
    parts=(q.data or "").split(":",2)
    if len(parts)!=3 or not parts[1].isdigit() or int(parts[1])!=q.from_user.id:
        await q.answer("این بخش برای کاربر دیگری است 😄",show_alert=True); return
    uid=q.from_user.id; action=parts[2]
    if action=="profile": await send_full_profile(type("U",(),{"effective_user":q.from_user,"effective_message":q.message,"get_bot":lambda self:q.get_bot()})(),uid); return
    if action=="shop":
        await q.edit_message_text("🛍️ <b>فروشگاه هاپو</b>\n\nبا استخوان آیتم تزئینی بخر. هیچ پول واقعی و هیچ شرطی وجود ندارد.",parse_mode="HTML",reply_markup=keyboard([[btn(f"{n} — {p}🦴",f"shop:{uid}:buy:{k}")] for k,(n,p) in SHOP_ITEMS.items()]+[[btn("🔙 ابزارها",f"rich:{uid}:home")]])); return
    if action=="font": await q.edit_message_text("📝 <b>۱۰ فونت آماده</b>\n\nدر گروه بنویس: فونت متن تو\nهر ۱۰ سبک در یک پیام برمی‌گردد.",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 ابزارها",f"rich:{uid}:home")]])); return
    if action=="translate": await q.edit_message_text("🌐 مثال: ترجمه hello\nترجمه با سرویس آنلاین انجام می‌شود و اگر سرویس قطع باشد پیام خطا می‌گیری.",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 ابزارها",f"rich:{uid}:home")]])); return
    if action=="football": await q.edit_message_text("⚽ مثال: فوتبال Barcelona\nاین بخش اطلاعات واقعی تیم را از سرویس داده ورزشی می‌گیرد.",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 ابزارها",f"rich:{uid}:home")]])); return
    if action=="radio":
        await q.edit_message_text("📻 رادیو آماده است؛ از دستور رادیو یا دکمه‌های صفحه رادیو استفاده کن.",parse_mode="HTML",reply_markup=keyboard([[btn("📻 باز کردن رادیو",url="https://radio.garden/")],[btn("🔙 ابزارها",f"rich:{uid}:home")]])); return
    if action=="song": await q.edit_message_text("🔎 بنویس: سرچ آهنگ نام آهنگ",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 ابزارها",f"rich:{uid}:home")]])); return
    if action=="downloader":
        await q.edit_message_text("📥 <b>دانلودر بیل بیلک</b>\n\nدانلود https://... → رسانه عمومی\nدانلود ویدیو https://... → ویدیو\nدانلود آهنگ https://... → صوت\nدانلود صدا https://... → صوت\nدانلودر / راهنمای دانلودر → راهنمای دانلودر\n\n🔒 فقط لینک عمومی و محتوایی که اجازه دریافتش را داری؛ لینک خصوصی و محتوای محدود پشتیبانی نمی‌شود.",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 ابزارها",f"rich:{uid}:home")]])); return
    if action=="time":
        now=datetime.now()
        jalali='—'; weekday='—'
        try:
            import jdatetime
            j=jdatetime.datetime.fromgregorian(datetime=now)
            jalali=j.strftime('%Y/%m/%d')
            weekday=j.strftime('%A')
        except Exception:
            pass
        date_text=(
            '📅 <b>تاریخ / ساعت بیل بیلک</b>\n\n'
            '〰️〰️〰️〰️〰️〰️〰️\n\n'
            f'📆 تاریخ شمسی: <b>{jalali}</b>\n'
            f'📅 تاریخ میلادی: <b>{now.strftime("%Y/%m/%d")}</b>\n'
            f'📌 روز هفته: <b>{weekday}</b>\n'
            f'🕐 ساعت: <b>{now.strftime("%H:%M:%S")}</b>\n\n'
            '〰️〰️〰️〰️〰️〰️〰️'
        )
        await q.edit_message_text(date_text,parse_mode="HTML",reply_markup=keyboard([[btn("🔄 تازه‌سازی",f"rich:{uid}:time")],[btn("🔙 ابزارها",f"rich:{uid}:home")]])); return
    if action=="helpfull":
        admin = await _bb_help_is_privileged(uid, getattr(q.message, 'chat', None))
        if not admin and getattr(q.message, 'chat', None) and getattr(q.message.chat, 'type', None) != 'private':
            text = ('📚 <b>راهنمای کاربری</b>\n\n'
                    'فقط بخش‌های کاربری، بازی، ابزار و موزیکال برایت فعال است.')
        else:
            text = ('📚 <b>راهنمای بیل بیلک</b>\n\n'
                    'بخش‌های کاربری، بازی، ابزار و موزیکال را ببین. بخش‌های مدیریتی فقط برای ادمین‌ها نمایش داده می‌شوند.')
        await q.edit_message_text(text,parse_mode="HTML",reply_markup=_bb_complete_help_keyboard(uid, admin=admin)); return
    if action=="games": await q.edit_message_text("🎮 <b>بازی‌های سخت</b>\n\nاز پنل بازی‌ها حدس عدد ۱ تا ۱۰۰، ریاضی چندمرحله‌ای، حافظه ۸ رقمی، کلمه با سرنخ و کوییز چندگزینه‌ای را بازی کن.",parse_mode="HTML",reply_markup=keyboard([[btn("🎮 باز کردن بازی‌ها",user_cb(uid,"games"))],[btn("🔙 ابزارها",f"rich:{uid}:home")]])); return
    if action=="home": await q.edit_message_text("🧰 <b>مرکز ابزارهای واقعی</b>\n\nابزارها از پنل مدیریت جدا هستند. هر گزینه یک دستور یا سرویس مشخص دارد.",parse_mode="HTML",reply_markup=rich_keyboard(uid)); return
    await _OLD_RICH_CALLBACK(q,context)

# ------------------------- Shop callback -------------------------
async def shop_callback(q,context):
    parts=(q.data or "").split(":",3)
    if len(parts)!=4 or parts[0]!="shop" or int(parts[1])!=q.from_user.id: await q.answer("این فروشگاه برای شما نیست.",show_alert=True); return
    key=parts[3]
    if key not in SHOP_ITEMS: await q.answer("آیتم پیدا نشد.",show_alert=True); return
    cid=q.message.chat.id; name,price=SHOP_ITEMS[key]; u=await DBX.get_user(q.from_user.id)
    if await DBX.one("SELECT 1 FROM group_items WHERE chat_id=? AND user_id=? AND item_key=?",(cid,q.from_user.id,key)):
        await q.answer("این آیتم را قبلاً داری.",show_alert=True); return
    if (u["bones"] if u else 0)<price: await q.answer(f"استخوان کافی نیست؛ {price} استخوان لازم است.",show_alert=True); return
    await DBX.execute("UPDATE users SET bones=bones-? WHERE user_id=?",(price,q.from_user.id)); await DBX.execute("INSERT INTO group_items(chat_id,user_id,item_key,bought_at) VALUES(?,?,?,?)",(cid,q.from_user.id,key,now_ts())); await q.answer(f"{name} خریداری شد! 🐾",show_alert=True)

# ------------------------- Stats/tag aliases in router -------------------------
_OLD_MESSAGE_ROUTER=message_router
async def message_router(update,context):
    msg=update.effective_message
    if msg and update.effective_chat and update.effective_chat.type!="private" and update.effective_user:
        await record_member_message(update)
        if msg.text and msg.text.startswith("/"): await record_stat(update.effective_chat.id,"commands")
    await _OLD_MESSAGE_ROUTER(update,context)
    if msg and update.effective_chat and update.effective_chat.type!="private" and msg.message_id:
        try: await apply_forced_reaction(update,context)
        except Exception: pass

