def build_application(token: str) -> Application:
    app=(ApplicationBuilder().token(token).post_init(post_init).post_shutdown(post_shutdown).build())
    app.add_handler(CommandHandler("start",start)); app.add_handler(CommandHandler("help",cmd_help)); app.add_handler(CommandHandler("panel",cmd_panel)); app.add_handler(CommandHandler("adminpanel",cmd_adminpanel)); app.add_handler(CommandHandler("owner",owner_panel)); app.add_handler(CommandHandler("features",cmd_features)); app.add_handler(CommandHandler("rules",rules_command)); app.add_handler(CommandHandler("setrules",set_rules)); app.add_handler(CommandHandler("welcome",set_welcome)); app.add_handler(CommandHandler("togglewelcome",toggle_welcome)); app.add_handler(CommandHandler("goodbye",set_goodbye)); app.add_handler(CommandHandler("togglegoodbye",toggle_goodbye)); app.add_handler(CommandHandler("forcejoin",forcejoin_command)); app.add_handler(CommandHandler("report",report_command)); app.add_handler(CommandHandler("pin",pin_command)); app.add_handler(CommandHandler("cleanup",lambda u,c:cleanup(u,c,20))); app.add_handler(CommandHandler("stats",stats_command)); app.add_handler(CommandHandler("setgrouptitle",set_group_title)); app.add_handler(CommandHandler("setgroupbio",set_group_bio)); app.add_handler(CommandHandler("setgroupphoto",set_group_photo));
    app.add_handler(CommandHandler("warn",lambda u,c:moderation_action(u,c,"warn"))); app.add_handler(CommandHandler("unwarn",lambda u,c:moderation_action(u,c,"unwarn"))); app.add_handler(CommandHandler("mute",lambda u,c:moderation_action(u,c,"mute"))); app.add_handler(CommandHandler("unmute",lambda u,c:moderation_action(u,c,"unmute"))); app.add_handler(CommandHandler("ban",lambda u,c:moderation_action(u,c,"ban"))); app.add_handler(CommandHandler("unban",lambda u,c:moderation_action(u,c,"unban")))
    app.add_handler(CallbackQueryHandler(callback_router)); app.add_handler(ChatMemberHandler(new_member,ChatMemberHandler.CHAT_MEMBER));
    if MessageReactionHandler is not None:
        app.add_handler(MessageReactionHandler(reaction_handler))
        log.info("MessageReactionHandler enabled (forced reactions available)")
    else:
        log.warning("MessageReactionHandler is unavailable in this python-telegram-bot version; forced reactions are disabled. Upgrade with: python -m pip install -U python-telegram-bot")
    app.add_handler(MessageHandler(filters.LOCATION,location_handler)); app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,message_router)); app.add_error_handler(error_handler); return app

async def post_init(application):
    await ensure_v3_schema()
    await application.bot.set_my_commands([("start","شروع"),("help","راهنما"),("panel","پنل"),("features","قابلیت‌ها"),("rules","قوانین"),("forcejoin","جوین اجباری"),("stats","آمار"),("cleanup","پاکسازی")])
    log.info("%s %s started",BOT_NAME,BOT_VERSION)

