# ---- Text aliases for the new management engines ----
async def process_text_state_v4(update, context):
    msg=update.effective_message; t=normalize(msg.text or "") if msg and msg.text else ""
    if not t: return await process_text_state(update,context)
    if t in {"مدیریت","پنل مدیریت"}:
        if await is_admin(update): await msg.reply_text("🛡 <b>پنل مدیریت</b>",parse_mode="HTML",reply_markup=management_keyboard_v4(update.effective_user.id))
        else: await msg.reply_text("⛔ فقط ادمین واقعی.")
        return True
    if t.startswith("ثبت قوانین ") or t.startswith("ثبت قانون "):
        if not await is_admin(update): await msg.reply_text("⛔ فقط ادمین."); return True
        text=safe_text(msg.text.split(None,2)[2],1500); await DBX.ensure_chat(update.effective_chat); await DBX.execute("UPDATE chats SET rules_text=? WHERE chat_id=?",(text,update.effective_chat.id)); await msg.reply_text("📜 قوانین با موفقیت ثبت شد."); return True
    if t=="قوانین":
        await rules_command(update,context); return True
    if t=="پاکسازی همه": await cleanup_v4(update,context,500); return True
    if t.startswith("پاکسازی خودکار"):
        if not await is_admin(update): await msg.reply_text("⛔ فقط ادمین."); return True
        p=t.split(); sec=int(p[1]) if len(p)>1 and p[1].isdigit() else 300; sec=max(30,min(sec,3600)); await DBX.execute("UPDATE chats SET auto_cleanup_enabled=1,auto_cleanup_seconds=? WHERE chat_id=?",(sec,update.effective_chat.id)); await msg.reply_text(f"🧹 پاکسازی خودکار روشن شد: هر {sec} ثانیه."); return True
    if t=="خاموش پاکسازی خودکار":
        if await is_admin(update): await DBX.execute("UPDATE chats SET auto_cleanup_enabled=0 WHERE chat_id=?",(update.effective_chat.id,)); await msg.reply_text("🧹 خاموش شد.")
        return True
    if t.startswith("قفل ") or t.startswith("باز کردن "):
        # Reuse exact DB-backed lock toggling, with a visible permission check.
        aliases={"لینک":"links","لینک ها":"links","فوروارد":"forwards","عکس":"photos","ویدیو":"videos","گیف":"gifs","فایل":"files","ویس":"voices","مخاطب":"contacts","لوکیشن":"locations","استیکر":"stickers","نظرسنجی":"polls","متن بلند":"long_text","حروف بزرگ":"caps","ضدفلود":"flood","تکرار":"repeat_messages"}
        parts=t.split(None,1); label=parts[1] if len(parts)>1 else ""; field=aliases.get(label)
        if field:
            if not await is_admin(update): await msg.reply_text("⛔ فقط ادمین."); return True
            await DBX.ensure_chat(update.effective_chat); on=t.startswith("قفل "); await DBX.execute(f"UPDATE locks SET {field}=? WHERE chat_id=?",(1 if on else 0,update.effective_chat.id));
            rights=await get_bot_rights(context.bot,update.effective_chat.id)
            extra="" if (not on or rights["delete"]) else "\n⚠️ ربات دسترسی حذف پیام‌ها ندارد؛ قفل بدون این دسترسی نمی‌تواند حذف کند."
            await msg.reply_text(f"🔒 قفل «{label}» {'روشن' if on else 'خاموش'} شد.{extra}"); return True
    if t in {"تگ ادمین ها","تگ ادمین‌ها","تگ همه","تگ اعضا","تگ اعضای فعال","تگ ربات ها","تگ ربات‌ها","تگ زیر 300","تگ زیر۳۰۰","تگ بالای 500","تگ بالای۵۰۰","تگ کم حرف ها","تگ کم‌حرف‌ها"}:
        mapping={"تگ ادمین ها":"admins","تگ ادمین‌ها":"admins","تگ همه":"all","تگ اعضا":"all","تگ اعضای فعال":"active","تگ ربات ها":"bots","تگ ربات‌ها":"bots","تگ زیر 300":"under300","تگ زیر۳۰۰":"under300","تگ بالای 500":"over500","تگ بالای۵۰۰":"over500","تگ کم حرف ها":"quiet","تگ کم‌حرف‌ها":"quiet"}
        await tag_users_v4(update,context,mapping[t]); return True
    if t=="تگ خودکار کم حرف":
        data=await DBX.execute("SELECT user_id,first_name,username FROM chat_member_stats WHERE chat_id=? AND is_bot=0 AND messages<50 ORDER BY messages ASC LIMIT 50",(update.effective_chat.id,),fetch=True)
        for x in data:
            u=type("U",(),{"id":x["user_id"],"first_name":x["first_name"],"username":x["username"]})(); await msg.reply_text("🏷️ "+mention_html(u),parse_mode="HTML"); await asyncio.sleep(.2)
        return True
    if t in {"آمار روزانه","آمار هفتگی","آمار ماهانه"}:
        days={"آمار روزانه":1,"آمار هفتگی":7,"آمار ماهانه":30}[t]
        if await is_admin(update): await msg.reply_text(await stats_v4_text(update.effective_chat.id,days,update.effective_user.id),parse_mode="HTML")
        else: await msg.reply_text("⛔ آمار کلی فقط برای ادمین است. برای آمار خودت «آمار من» را بفرست.")
        return True
    if t in {"آمار من","آمار خودم","لیدربرد"}:
        await my_stats_v4(update,context); return True
    if t.startswith("سکوت") or t in {"سیک","هیس","خفه"}:
        if not await is_admin(update): await msg.reply_text("⛔ فقط ادمین."); return True
        if t.startswith("سکوت "):
            context.args=t.split()[1:]
        else: context.args=[]
        await moderation_v4(update,context,"mute"); return True
    if t in {"رفع سکوت","بن","رفع بن"}:
        await moderation_v4(update,context,{"رفع سکوت":"unmute","بن":"ban","رفع بن":"unban"}[t]); return True
    if t in {"عزل","عزل ادمین","حذف ادمین"}:
        # Direct demotion with explicit bot permission check.
        if not await is_admin(update): await msg.reply_text("⛔ فقط ادمین."); return True
        target=await target_from_reply(update)
        if not target: await msg.reply_text("👑 روی پیام ادمین ریپلای کن و «عزل ادمین» را بفرست."); return True
        try:
            tm=await update.effective_chat.get_member(target.id)
            if tm.status==ChatMemberStatus.OWNER: await msg.reply_text("⛔ مالک قابل عزل نیست."); return True
            await update.effective_chat.promote_member(target.id,can_change_info=False,can_post_messages=False,can_edit_messages=False,can_delete_messages=False,can_invite_users=False,can_restrict_members=False,can_pin_messages=False,can_promote_members=False,can_manage_video_chats=False,can_manage_topics=False)
            await msg.reply_text(f"👋 {mention_html(target)} از ادمینی عزل شد.",parse_mode="HTML")
        except TelegramError as e: await msg.reply_text("⚠️ عزل انجام نشد. ربات باید اجازه مدیریت ادمین‌ها را داشته باشد.\n"+safe_text(str(e),180))
        return True
    if t=="مکانیابی" or t=="ارسال موقعیت": await request_location_v4(update,context); return True
    return await process_text_state(update,context)

async def message_router_v4(update, context):
    msg=update.effective_message
    if not msg: return
    if update.effective_chat and update.effective_chat.type!="private": await DBX.ensure_chat(update.effective_chat)
    if update.effective_user: await DBX.ensure_user(update.effective_user)
    if update.effective_chat and update.effective_chat.type!="private" and update.effective_user:
        try: await record_v4_member_message(update)
        except Exception as e: log.warning("member stats failed: %s",e)
    if await enforce_forcejoin(update,context): return
    # Stateful games/tools and explicit commands get priority over content locks.
    if await process_text_state_v4(update,context): return
    await enforce_locks_v4(update,context)

async def rich_callback_v4(q,context):
    data=q.data or ""; p=data.split(":",2)
    if data.startswith("mafia2:") and data.endswith(":home"):
        fake=type("U",(),{"effective_chat":q.message.chat,"effective_user":q.from_user,"effective_message":q.message})(); await mafia_rooms_menu(fake,context); return
    if len(p)==3 and p[0]=="rich" and p[1].isdigit() and int(p[1])==q.from_user.id and p[2]=="location":
        await request_location_v4(type("U",(),{"effective_message":q.message})(),context); return
    if len(p)==3 and p[0]=="rich" and p[1].isdigit() and int(p[1])==q.from_user.id and p[2]=="mafia":
        fake=type("U",(),{"effective_chat":q.message.chat,"effective_user":q.from_user,"effective_message":q.message})(); await mafia_rooms_menu(fake,context); return
    # Fix shop callback path and all other rich pages by delegating to the previous implementation.
    await rich_callback(q,context)

async def callback_router_v4(update,context):
    q=update.callback_query
    if not q: return
    try: await q.answer()
    except TelegramError: pass
    data=q.data or ""
    if data.startswith("shop:"):
        p=data.split(":",3)
        if len(p)==4 and p[1].isdigit() and int(p[1])==q.from_user.id:
            key=p[3]
            if key not in SHOP_ITEMS: await q.answer("آیتم پیدا نشد.",show_alert=True); return
            cid=q.message.chat.id; name,price=SHOP_ITEMS[key]; u=await DBX.get_user(q.from_user.id)
            if await DBX.one("SELECT 1 FROM group_items WHERE chat_id=? AND user_id=? AND item_key=?",(cid,q.from_user.id,key)): await q.answer("این آیتم را قبلاً داری.",show_alert=True); return
            if (u["bones"] if u else 0)<price: await q.answer(f"{price} استخوان لازم است.",show_alert=True); return
            await DBX.execute("UPDATE users SET bones=bones-? WHERE user_id=?",(price,q.from_user.id)); await DBX.execute("INSERT INTO group_items(chat_id,user_id,item_key,bought_at) VALUES(?,?,?,?)",(cid,q.from_user.id,key,now_ts())); await q.answer(f"{name} خریداری شد! 🐾",show_alert=True); return
    if data.startswith("mfrooms:"):
        fake=type("U",(),{"effective_chat":q.message.chat,"effective_user":q.from_user,"effective_message":q.message})(); await mafia_rooms_menu(fake,context); return
    if data.startswith("mf2:"):
        await mafia2_callback(q,context); return
    if data.startswith("mfhelp:"):
        if len(data.split(":",2))>=2 and int(data.split(":",2)[1])==q.from_user.id: await mafia2_help(q)
        else: await q.answer("این راهنما برای کاربر دیگری است.",show_alert=True)
        return
    if data.startswith("rich:"):
        await rich_callback_v4(q,context); return
    if data.startswith("a:"):
        await management_v4(q,context); return
    # Preserve all old game/user/owner routes.
    await callback_router_base(update,context)

# Save the pre-v4 dispatcher before replacing it.
callback_router_base=callback_router

async def callback_router(update,context):
    # This name is used by build_application and resolves to the reliable V4 dispatcher.
    q=update.callback_query
    if not q: return
    try: await q.answer()
    except TelegramError: pass
    data=q.data or ""
    if data.startswith("shop:") or data.startswith("mfrooms:") or data.startswith("mf2:") or data.startswith("mfhelp:") or data.startswith("rich:") or data.startswith("a:"):
        # avoid double q.answer in delegated callbacks
        if data.startswith("a:"): await management_v4(q,context); return
        if data.startswith("shop:"):
            p=data.split(":",3)
            if len(p)!=4 or not p[1].isdigit() or int(p[1])!=q.from_user.id: await q.answer("این بخش برای شما نیست.",show_alert=True); return
            key=p[3]
            if key not in SHOP_ITEMS: await q.answer("آیتم پیدا نشد.",show_alert=True); return
            cid=q.message.chat.id; name,price=SHOP_ITEMS[key]; u=await DBX.get_user(q.from_user.id)
            if await DBX.one("SELECT 1 FROM group_items WHERE chat_id=? AND user_id=? AND item_key=?",(cid,q.from_user.id,key)): await q.answer("قبلاً خریدی.",show_alert=True); return
            if (u["bones"] if u else 0)<price: await q.answer(f"{price} استخوان لازم است.",show_alert=True); return
            await DBX.execute("UPDATE users SET bones=bones-? WHERE user_id=?",(price,q.from_user.id)); await DBX.execute("INSERT INTO group_items(chat_id,user_id,item_key,bought_at) VALUES(?,?,?,?)",(cid,q.from_user.id,key,now_ts())); await q.answer(f"{name} خریداری شد! 🐾",show_alert=True); return
        if data.startswith("mfrooms:"):
            fake=type("U",(),{"effective_chat":q.message.chat,"effective_user":q.from_user,"effective_message":q.message})(); await mafia_rooms_menu(fake,context); return
        if data.startswith("mf2:"): await mafia2_callback(q,context); return
        if data.startswith("mafia2:") and data.endswith(":home"):
            fake=type("U",(),{"effective_chat":q.message.chat,"effective_user":q.from_user,"effective_message":q.message})(); await mafia_rooms_menu(fake,context); return
        if data.startswith("mfhelp:"):
            p=data.split(":",2)
            if len(p)==3 and p[1].isdigit() and int(p[1])==q.from_user.id: await mafia2_help(q)
            else: await q.answer("این راهنما برای کاربر دیگری است.",show_alert=True)
            return
        if data.startswith("rich:"): await rich_callback_v4(q,context); return
    await callback_router_base(update,context)

async def post_init_v4(application):
    await ensure_v3_schema(); await ensure_v4_schema()
    await application.bot.set_my_commands([("start","شروع"),("help","راهنما"),("panel","پنل"),("features","قابلیت‌ها"),("rules","قوانین"),("stats","آمار"),("cleanup","پاکسازی")])
    # Auto cleanup runs every 30s and uses the per-chat configured age.
    if application.job_queue:
        application.job_queue.run_repeating(auto_cleanup_job,30,first=30,name="bilbilak-auto-cleanup")
    log.info("%s V4 reliable engines enabled",BOT_NAME)

def build_application(token: str) -> Application:
    app=ApplicationBuilder().token(token).post_init(post_init_v4).post_shutdown(post_shutdown).build()
    app.add_handler(CommandHandler("start",start)); app.add_handler(CommandHandler("help",cmd_help)); app.add_handler(CommandHandler("panel",cmd_panel)); app.add_handler(CommandHandler("adminpanel",cmd_adminpanel)); app.add_handler(CommandHandler("owner",owner_panel)); app.add_handler(CommandHandler("features",cmd_features)); app.add_handler(CommandHandler("rules",rules_command)); app.add_handler(CommandHandler("setrules",set_rules)); app.add_handler(CommandHandler("welcome",set_welcome)); app.add_handler(CommandHandler("togglewelcome",toggle_welcome)); app.add_handler(CommandHandler("goodbye",set_goodbye)); app.add_handler(CommandHandler("togglegoodbye",toggle_goodbye)); app.add_handler(CommandHandler("forcejoin",forcejoin_v4)); app.add_handler(CommandHandler("stats",stats_v4_command)); app.add_handler(CommandHandler("cleanup",lambda u,c:cleanup_v4(u,c,500))); app.add_handler(CommandHandler("setgrouptitle",set_group_title)); app.add_handler(CommandHandler("setgroupbio",set_group_bio)); app.add_handler(CommandHandler("setgroupphoto",set_group_photo_v4))
    app.add_handler(CommandHandler("warn",lambda u,c:moderation_action(u,c,"warn"))); app.add_handler(CommandHandler("unwarn",lambda u,c:moderation_action(u,c,"unwarn"))); app.add_handler(CommandHandler("mute",lambda u,c:moderation_v4(u,c,"mute"))); app.add_handler(CommandHandler("unmute",lambda u,c:moderation_v4(u,c,"unmute"))); app.add_handler(CommandHandler("ban",lambda u,c:moderation_v4(u,c,"ban"))); app.add_handler(CommandHandler("unban",lambda u,c:moderation_v4(u,c,"unban")))
    app.add_handler(CallbackQueryHandler(callback_router))
    if MessageReactionHandler is not None: app.add_handler(MessageReactionHandler(reaction_handler))
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS,service_members_v4)); app.add_handler(MessageHandler(filters.StatusUpdate.LEFT_CHAT_MEMBER,service_members_v4)); app.add_handler(MessageHandler(filters.LOCATION,location_v4)); app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,message_router_v4)); app.add_error_handler(error_handler)
    return app


