# More than 100 named locks are exposed. Only safe moderation/content categories are active.
ADV_LOCK_KEYS = list(ADV_LOCK_NAMES)

async def ensure_v5_schema():
    await DBX.execute('CREATE TABLE IF NOT EXISTS advanced_locks (chat_id INTEGER NOT NULL, lock_key TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(chat_id,lock_key))')
    await DBX.execute('CREATE TABLE IF NOT EXISTS chat_owners (chat_id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, created_at INTEGER NOT NULL)')
    await DBX.execute('CREATE TABLE IF NOT EXISTS vip_groups (chat_id INTEGER PRIMARY KEY, expires_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0)')
    await DBX.execute('CREATE TABLE IF NOT EXISTS custom_security (chat_id INTEGER PRIMARY KEY, warn_limit INTEGER NOT NULL DEFAULT 3, punishment TEXT NOT NULL DEFAULT "mute", mute_minutes INTEGER NOT NULL DEFAULT 10)')
    await DBX.execute('CREATE TABLE IF NOT EXISTS daily_media_stats (chat_id INTEGER NOT NULL, day TEXT NOT NULL, photos INTEGER DEFAULT 0, videos INTEGER DEFAULT 0, gifs INTEGER DEFAULT 0, voices INTEGER DEFAULT 0, audios INTEGER DEFAULT 0, stickers INTEGER DEFAULT 0, emojis INTEGER DEFAULT 0, calls INTEGER DEFAULT 0, PRIMARY KEY(chat_id,day))')
    await DBX.execute('CREATE TABLE IF NOT EXISTS personal_stats (chat_id INTEGER NOT NULL, user_id INTEGER NOT NULL, day TEXT NOT NULL, messages INTEGER DEFAULT 0, emojis INTEGER DEFAULT 0, photos INTEGER DEFAULT 0, videos INTEGER DEFAULT 0, gifs INTEGER DEFAULT 0, voices INTEGER DEFAULT 0, PRIMARY KEY(chat_id,user_id,day))')
    for cid in [r['chat_id'] for r in await DBX.execute('SELECT chat_id FROM chats',fetch=True)]:
        for key in ADV_LOCK_KEYS:
            await DBX.execute('INSERT OR IGNORE INTO advanced_locks(chat_id,lock_key,enabled) VALUES(?,?,0)',(cid,key))
    # Persist owner default without exposing it in normal group UI.
    await DBX.execute('INSERT OR IGNORE INTO bot_settings(key,value) VALUES("owner_id",?)',(str(OWNER_ID_DEFAULT),))

async def owner_check(uid:int)->bool:
    if uid==OWNER_ID_DEFAULT: return True
    return await is_owner(uid)

async def local_admin(update, uid=None):
    uid=uid or (update.effective_user.id if update.effective_user else 0)
    if await owner_check(uid): return True
    if not update.effective_chat or update.effective_chat.type=='private': return False
    row=await DBX.one('SELECT user_id FROM chat_owners WHERE chat_id=?',(update.effective_chat.id,))
    if row and int(row['user_id'])==uid: return True
    return await is_admin(update,uid)

async def active_vip(cid:int)->bool:
    row=await DBX.one('SELECT expires_at FROM vip_groups WHERE chat_id=?',(cid,))
    return bool(row and int(row['expires_at'])>now_ts())

async def require_vip(update):
    if await owner_check(update.effective_user.id): return True
    return await active_vip(update.effective_chat.id) if update.effective_chat else False

async def bot_ready_for_group(bot, chat_id):
    r=await get_bot_rights(bot,chat_id)
    return r

async def activate_group(update, context):
    if not update.effective_chat or update.effective_chat.type=='private': return False
    if not await is_admin(update):
        await update.effective_message.reply_text('⛔ فعال‌سازی فقط توسط مالک یا ادمین گروه انجام می‌شود.')
        return True
    rights=await get_bot_rights(context.bot,update.effective_chat.id)
    if not rights['admin'] or not rights['delete']:
        await update.effective_message.reply_text('⚠️ اول بیل بیلک را ادمین کامل کن و دسترسی «حذف پیام‌ها» را بده. ناشناس‌ماندن لازم نیست.')
        return True
    await DBX.ensure_chat(update.effective_chat)
    await DBX.execute('UPDATE chats SET active=1 WHERE chat_id=?',(update.effective_chat.id,))
    await DBX.execute('INSERT INTO chat_owners(chat_id,user_id,created_at) VALUES(?,?,?) ON CONFLICT(chat_id) DO UPDATE SET user_id=excluded.user_id',(update.effective_chat.id,update.effective_user.id,now_ts()))
    await update.effective_message.reply_text('🐕 <b>بیل بیلک فعال شد!</b>\n\nمدیریت گروه، قفل‌ها، امنیت، آمار، تگ، بازی‌ها و هاپویی آماده‌اند.\nمالک محلی این گروه ثبت شد.',parse_mode='HTML',reply_markup=management_keyboard_v5(update.effective_user.id))
    return True

