    if not update.effective_user or not await owner_check(update.effective_user.id):
        if update.effective_message: await update.effective_message.reply_text('⛔ این پنل فقط برای سازنده ربات است.')
        return
    if update.effective_chat and update.effective_chat.type!='private':
        await update.effective_message.reply_text('🛡 پنل مالک در پیوی قابل استفاده است.')
