# ---------------- V5 text router ----------------
async def process_text_state_v5(update,context):
    msg=update.effective_message; t=normalize(msg.text or '') if msg and msg.text else ''
    if not t: return await process_text_state_v4(update,context)
    if t=='فعال': return await activate_group(update,context)
    if t.startswith('شارژ vip '):
        p=t.split(); return await vip_charge_text(update,context,int(p[2])) if len(p)>=3 and p[2].isdigit() else True
    if t in {'سازنده','سازنده ربات','کی ساخته','سازنده ربات کیه'}:
        await msg.reply_text(str(OWNER_ID_DEFAULT)); return True
    if t in {'مافیا','اتاق مافیا','بازی مافیا'}:
        fake=type('U',(),{'effective_chat':update.effective_chat,'effective_user':update.effective_user,'effective_message':msg})(); await mafia_rooms_menu(fake,context); return True
    if t in {'پنل مدیریت','مدیریت'}:
        if await local_admin(update): await msg.reply_text('🛡 پنل مدیریت',reply_markup=await management_keyboard_v5(update.effective_user.id))
        else: await msg.reply_text('⛔ فقط ادمین واقعی.'); return True
        return True
    if t in {'پنل هاپویی','هاپویی'}:
        await send_group_panel(update,context); return True
    if t in {'امنیت','پنل امنیت'}:
        if await local_admin(update):
            q=type('Q',(),{'message':msg,'from_user':update.effective_user,'edit_message_text':msg.reply_text,'answer':lambda *a,**k:None})()
            await advanced_security_panel(q,update.effective_user.id,update.effective_chat.id,0)
        return True
    if t.startswith('قفل ') or t.startswith('باز کردن '):
        if not await local_admin(update): await msg.reply_text('⛔ فقط ادمین.'); return True
        phrase=t.split(None,1)[1] if ' ' in t else ''; on=t.startswith('قفل ')
        aliases={'لینک':'links','اسپم':'spam','فوروارد':'forward','منشن':'mention','آیدی':'id','عکس':'photo','ویدیو':'video','گیف':'gif','فایل':'file','ویس':'voice','لوکیشن':'location','استیکر':'sticker','نظرسنجی':'poll','ضدپورن':'porn','پورن':'porn','ضدتبچی':'tabchi','ضدتقلب':'cheat_keyword','ضدکلاهبرداری':'scam','فیشینگ':'phishing','ضدفیلم':'video','ضداسپم':'spam','تکراری':'repeat','ضدفوروارد':'forward','شماره':'phone','تماس':'phone','کپشن بلند':'largecaption'}
        key=aliases.get(phrase)
        if not key:
            key=next((k for k in ADV_LOCK_KEYS if phrase in k or phrase==ADV_LOCK_NAMES.get(k,'')),None)
        if key:
            await DBX.execute('INSERT OR IGNORE INTO advanced_locks(chat_id,lock_key,enabled) VALUES(?,?,0)',(update.effective_chat.id,key)); await DBX.execute('UPDATE advanced_locks SET enabled=? WHERE chat_id=? AND lock_key=?',(1 if on else 0,update.effective_chat.id,key)); await msg.reply_text(('🔒' if on else '🔓')+f' {ADV_LOCK_NAMES.get(key,key)} {"روشن" if on else "خاموش"} شد.'); return True
    if t in {'معاف','رفع معافیت','رفع معاف'}:
        if not await local_admin(update): return True
        target=await target_from_reply(update)
        if not target: await msg.reply_text('روی پیام فرد ریپلای کن.'); return True
        if t=='معاف': await DBX.execute('INSERT OR REPLACE INTO exemptions(chat_id,user_id,reason) VALUES(?,?,?)',(update.effective_chat.id,target.id,'admin')); await msg.reply_text('🛡 کاربر معاف شد.')
        else: await DBX.execute('DELETE FROM exemptions WHERE chat_id=? AND user_id=?',(update.effective_chat.id,target.id)); await msg.reply_text('🛡 معافیت برداشته شد.')
        return True
    if t in {'آمار من','آمار خودم'}:
        await msg.reply_text(await stats_v5_text(update.effective_chat.id,30,update.effective_user.id),parse_mode='HTML'); return True
    if t in {'آمار روزانه','آمار هفتگی','آمار ماهانه'} and await local_admin(update):
        d={'آمار روزانه':1,'آمار هفتگی':7,'آمار ماهانه':30}[t]; await msg.reply_text(await stats_v5_text(update.effective_chat.id,d),parse_mode='HTML'); return True
    return await process_text_state_v4(update,context)

async def message_router_v5(update,context):
    msg=update.effective_message
    if not msg: return
    if update.effective_chat and update.effective_chat.type!='private': await DBX.ensure_chat(update.effective_chat)
    if update.effective_user: await DBX.ensure_user(update.effective_user)
    if update.effective_chat and update.effective_chat.type!='private':
        try: await record_v4_member_message(update)
        except Exception: pass
    if await enforce_forcejoin(update,context): return
    if await process_text_state_v5(update,context): return
    if await advanced_lock_check(update,context): return
    await enforce_locks_v4(update,context)

async def callback_router_v5(update,context):
    q=update.callback_query
    if not q: return
    try: await q.answer()
    except TelegramError: pass
    data=q.data or ''
    if data.startswith('avlock:'):
        p=data.split(':',2); await advanced_lock_toggle(q,int(p[1]),q.message.chat.id,p[2]); await advanced_security_panel(q,q.from_user.id,q.message.chat.id,0); return
    if data.startswith('avpage:'):
        p=data.split(':'); await advanced_security_panel(q,int(p[1]),q.message.chat.id,int(p[2])); return
    if data.startswith('asec:settings:'):
        uid=int(data.rsplit(':',1)[1]); await q.edit_message_text('⚙️ <b>تنظیم مجازات امنیتی</b>\n\nفعلاً سقف پیش‌فرض ۳ اخطار است؛ پس از آن محدودسازی انجام می‌شود. برای تغییرات متنی از «تنظیم اخطار» استفاده کن.',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 امنیت',admin_cb(uid,'security'))]])); return
    if data.startswith('own5:'):
        if not await owner_check(q.from_user.id): await q.answer('⛔ فقط سازنده.',show_alert=True); return
        await q.answer('این بخش در حال آماده‌سازی اتصال کامل است.',show_alert=True); return
    if data.startswith('a:'):
        await management_v5(q,context); return
    await callback_router(update,context)

# Final override: use the V5 router and ensure schema before polling.
async def post_init_v5(application):
    await ensure_v3_schema(); await ensure_v4_schema(); await ensure_v5_schema()
    await application.bot.set_my_commands([('start','شروع'),('help','راهنما'),('panel','پنل'),('features','قابلیت‌ها'),('rules','قوانین'),('stats','آمار')])
    if application.job_queue: application.job_queue.run_repeating(auto_cleanup_job,30,first=30,name='bilbilak-auto-cleanup-v5')

