# OWNER CONTROL CENTER - BOT CUSTOMIZATION
# =============================================================================
OWNER_DISABLED = set()
OWNER_BUTTON_LABELS = {}
OWNER_COMMAND_ALIASES = {}
OWNER_CUSTOM_MESSAGES = {}
OWNER_PENDING_CLEANUP_ACCOUNT = set()

def owner_feature_enabled(key):
    return owner_feature_key(key) not in OWNER_DISABLED

def owner_label(key, default):
    return OWNER_BUTTON_LABELS.get(owner_feature_key(key), default)

def owner_message(key, default):
    return OWNER_CUSTOM_MESSAGES.get(owner_feature_key(key), default)

def owner_is_allowed(uid):
    return int(uid or 0) == int(OWNER_ID_DEFAULT)

def owner_feature_key(raw):
    return normalize(raw).replace(" ", "_")[:80]

async def owner_control_panel(q, context):
    if not owner_is_allowed(q.from_user.id):
        await q.answer('⛔ فقط سازنده.', show_alert=True); return
    await ensure_cleanup_pro_schema()
    acc = await cleanup_account_row()
    if acc and int(acc['account_user_id'] or 0):
        acc_state = '🟢 فعال' if int(acc['enabled'] or 0) else '🔴 خاموش'
        acc_text = f"{acc_state}\n👤 {safe_text(acc['account_name'] or 'بدون نام', 35)}\n🆔 {int(acc['account_user_id'])}\n🔎 {safe_text(acc['last_status'] or 'بررسی نشده', 35)}"
    else:
        acc_text = '❌ هنوز اکانت مکملی ثبت نشده است.'
    await q.edit_message_text(
        '👑 <b>مرکز کنترل کامل ربات</b>\n\n'
        f'🧩 خاموش: <b>{len(OWNER_DISABLED)}</b>\n'
        f'🔘 نام دکمه سفارشی: <b>{len(OWNER_BUTTON_LABELS)}</b>\n'
        f'💬 پیام سفارشی: <b>{len(OWNER_CUSTOM_MESSAGES)}</b>\n'
        f'⌨️ دستور سفارشی: <b>{len(OWNER_COMMAND_ALIASES)}</b>\n\n'
        '👤 <b>اکانت مکمل پاکسازی</b>\n' + acc_text + '\n\n'
        'تنظیمات در SQLite ذخیره می‌شوند و بعد از ری‌استارت باقی می‌مانند.',
        parse_mode='HTML', reply_markup=keyboard([
            [btn('👤 اکانت مکمل','oc:account'), btn('🧹 پاکسازی','oc:cleanup')],
            [btn('🧩 قابلیت‌ها','oc:features'),btn('🔘 دکمه‌ها','oc:buttons')],
            [btn('💬 پیام‌ها','oc:messages'),btn('⌨️ دستورات','oc:commands')],
            [btn('↕️ جابه‌جایی منو','oc:order'),btn('🔄 بازنشانی','oc:reset')],
            [btn('🔙 پنل مالک','own6:home')]
        ]))

async def owner_control_callback(q, context):
    if not owner_is_allowed(q.from_user.id):
        await q.answer("⛔ فقط سازنده.", show_alert=True); return
    action=(q.data or "").split(":",1)[1] if ":" in (q.data or "") else ""
    if action=="home": return await owner_control_panel(q,context)
    if action=="features":
        common=[("🎮 بازی‌ها","games"),("🐾 هاپویی","dog"),("🏭 کارخانه","factory"),("🤝 دوستی","friends"),("🏆 رقابت","competition"),("🧰 ابزارها","tools"),("📣 پیام همگانی","broadcast")]
        rows=[]
        for label,key in common:
            rows.append([btn(("🔴 " if key in OWNER_DISABLED else "🟢 ")+label,f"oct:toggle:{key}")])
        rows.append([btn("🔙 مرکز کنترل","oc:home")])
        await q.edit_message_text("🧩 <b>روشن/خاموش‌کردن قابلیت‌ها</b>\n\nدکمه هر قابلیت وضعیت فعلی را نشان می‌دهد.",parse_mode="HTML",reply_markup=keyboard(rows)); return
    if action=="buttons":
        await q.edit_message_text("🔘 <b>شخصی‌سازی دکمه‌ها</b>\n\nبرای تغییر نام نمایشی یک دکمه بنویس:\nنام دکمه games متن جدید\n\nبرای بازنشانی همان دکمه:\nحذف نام دکمه games",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 مرکز کنترل","oc:home")]])); return
    if action=="messages":
        await q.edit_message_text("💬 <b>شخصی‌سازی پیام‌ها</b>\n\nفرمت:\nپیام سفارشی welcome متن\nپیام سفارشی goodbye متن\nپیام سفارشی group_panel متن\n\nحذف: حذف پیام سفارشی welcome",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 مرکز کنترل","oc:home")]])); return
    if action=="commands":
        await q.edit_message_text("⌨️ <b>دستورات سفارشی</b>\n\nفرمت:\nدستور جدید اسم_دستور متن_مقصد\nمثال: دستور جدید راهنما help\n\nحذف: حذف دستور راهنما",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 مرکز کنترل","oc:home")]])); return
    if action=="reset":
        OWNER_DISABLED.clear(); OWNER_BUTTON_LABELS.clear(); OWNER_COMMAND_ALIASES.clear(); OWNER_CUSTOM_MESSAGES.clear()
        await q.answer("تنظیمات سفارشی بازنشانی شد.",show_alert=True); return await owner_control_panel(q,context)

async def owner_control_action_callback(q, context):
    if not owner_is_allowed(q.from_user.id):
        await q.answer("⛔ فقط سازنده.", show_alert=True); return
    parts=(q.data or "").split(":")
    if len(parts)>=3 and parts[0]=="oct" and parts[1]=="toggle":
        key=owner_feature_key(parts[2])
        if key in OWNER_DISABLED: OWNER_DISABLED.remove(key); state="روشن"
        else: OWNER_DISABLED.add(key); state="خاموش"
        await q.answer(f"{key}: {state}",show_alert=True)
        return await owner_control_callback(type("Q",(),{"from_user":q.from_user,"data":"oc:features","edit_message_text":q.edit_message_text,"answer":q.answer})(),context)

async def owner_control_text(update, context):
    msg=update.effective_message; uid=update.effective_user.id if update.effective_user else 0
    if not msg or not owner_is_allowed(uid): return False
    t=normalize(msg.text or "")
    if t in {"کنترل ربات","مرکز کنترل","کنترل کامل"}:
        q=type("Q",(),{"from_user":update.effective_user,"data":"oc:home","edit_message_text":msg.reply_text,"answer":lambda *a,**k:None})()
        await owner_control_panel(q,context); return True
    if t.startswith("حذف قابلیت "):
        key=owner_feature_key(t.replace("حذف قابلیت ","",1).strip()); OWNER_DISABLED.add(key); await msg.reply_text(f"🔴 قابلیت «{key}» خاموش شد."); return True
    if t.startswith("فعال قابلیت "):
        key=owner_feature_key(t.replace("فعال قابلیت ","",1).strip()); OWNER_DISABLED.discard(key); await msg.reply_text(f"🟢 قابلیت «{key}» روشن شد."); return True
    if t.startswith("نام دکمه "):
        p=t.split(" ",3)
        if len(p)>=4:
            OWNER_BUTTON_LABELS[p[2]]=p[3]; await msg.reply_text("🔘 نام دکمه ذخیره شد."); return True
    if t.startswith("حذف نام دکمه "):
        OWNER_BUTTON_LABELS.pop(t.split(" ",3)[3] if len(t.split(" ",3))>3 else "",None); await msg.reply_text("🔘 نام سفارشی حذف شد."); return True
    if t.startswith("پیام سفارشی "):
        p=t.split(" ",3)
        if len(p)>=4: OWNER_CUSTOM_MESSAGES[p[2]]=p[3]; await msg.reply_text("💬 پیام سفارشی ذخیره شد."); return True
    if t.startswith("حذف پیام سفارشی "):
        OWNER_CUSTOM_MESSAGES.pop(t.replace("حذف پیام سفارشی ","",1).strip(),None); await msg.reply_text("💬 پیام سفارشی حذف شد."); return True
    if t.startswith("دستور جدید "):
        p=t.split(" ",3)
        if len(p)>=4: OWNER_COMMAND_ALIASES[p[2]]=p[3]; await msg.reply_text("⌨️ دستور سفارشی ثبت شد."); return True
    if t.startswith("حذف دستور "):
        OWNER_COMMAND_ALIASES.pop(t.replace("حذف دستور ","",1).strip(),None); await msg.reply_text("⌨️ دستور حذف شد."); return True
    return False


