async def owner_broadcast_send(update, context):
    """Owner-only broadcast: forwards the owner's replied message to known users/chats."""
    if not await owner_check(update.effective_user.id):
        await update.effective_message.reply_text('⛔ فقط سازنده ربات می‌تواند پیام همگانی بفرستد.')
        return True
    msg = update.effective_message
    if not msg.reply_to_message:
        await msg.reply_text('📣 روی پیام موردنظر ریپلای کن و بنویس: پیام همگانی')
        return True
    rows = await DBX.execute('SELECT user_id FROM users', fetch=True)
    targets = {int(r['user_id']) for r in rows}
    chat_rows = await DBX.execute('SELECT chat_id FROM chats WHERE active=1', fetch=True)
    targets.update(int(r['chat_id']) for r in chat_rows)
    ok = fail = 0
    for target in targets:
        try:
            await msg.reply_to_message.copy(chat_id=target)
            ok += 1
        except TelegramError:
            fail += 1
        await asyncio.sleep(0.03)
    await msg.reply_text(f'📣 <b>پیام همگانی انجام شد</b>\n\n✅ موفق: {ok}\n⚠️ ناموفق: {fail}', parse_mode='HTML')
    return True


async def owner_callback_v6(q, context):
    if not await owner_check(q.from_user.id):
        await q.answer('⛔ فقط سازنده.', show_alert=True)
        return
    action=(q.data or '').split(':',1)[1] if ':' in (q.data or '') else ''
    if action == 'home':
        fake=type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat,'effective_message':q.message})()
        await owner_panel_v6(fake,context)
        return
    if action == 'stats':
        groups=(await DBX.execute('SELECT COUNT(*) n FROM chats',fetch=True))[0]['n']
        users=(await DBX.execute('SELECT COUNT(*) n FROM users',fetch=True))[0]['n']
        active=(await DBX.execute('SELECT COUNT(*) n FROM chats WHERE active=1',fetch=True))[0]['n']
        vip=(await DBX.execute('SELECT COUNT(*) n FROM vip_groups WHERE expires_at>?',(now_ts(),),fetch=True))[0]['n']
        await q.edit_message_text(
            f'📊 <b>آمار مرکزی بیل بیلک</b>\n\n👤 کاربران ثبت‌شده: <b>{users}</b>\n👥 گروه‌ها: <b>{groups}</b>\n🟢 گروه‌های فعال: <b>{active}</b>\n💎 گروه‌های VIP فعال: <b>{vip}</b>',
            parse_mode='HTML', reply_markup=keyboard([[btn('🔙 پنل مالک','own6:home')]])
        )
        return
    if action == 'vip':
        rows=await DBX.execute('SELECT chat_id,expires_at FROM vip_groups WHERE expires_at>? ORDER BY expires_at DESC LIMIT 30',(now_ts(),),fetch=True)
        if not rows:
            text='💎 <b>VIP</b>\n\nهیچ گروه VIP فعالی وجود ندارد.'
        else:
            parts=[]
            for r in rows:
                try:
                    ch=await context.bot.get_chat(int(r['chat_id']))
                    title=safe_text(ch.title or str(ch.id),40)
                except TelegramError:
                    title=str(r['chat_id'])
                remain=max(0,int(r['expires_at'])-now_ts())
                parts.append(f'• {title} — {remain//86400} روز و {(remain%86400)//3600} ساعت')
            text='💎 <b>گروه‌های VIP فعال</b>\n\n'+'\n'.join(parts)
        await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('🔙 پنل مالک','own6:home')]]))
        return
    if action == 'backup':
        try:
            await q.message.reply_document(document=open(DB_PATH,'rb'), caption='💾 بکاپ فعلی دیتابیس بیل بیلک')
        except Exception as e:
            await q.answer(f'بکاپ آماده نشد: {type(e).__name__}',show_alert=True)
        return
    if action == 'security':
        rows=await DBX.execute('SELECT lock_key,COUNT(*) n FROM advanced_locks WHERE enabled=1 GROUP BY lock_key ORDER BY n DESC LIMIT 12',fetch=True)
        text='🛡 <b>امنیت سراسری</b>\n\nاین بخش تنظیمات امنیتی فعال گروه‌ها را نمایش می‌دهد.\n\n'
        text += '\n'.join(f'• {ADV_LOCK_NAMES.get(r["lock_key"],r["lock_key"])} — {r["n"]} گروه' for r in rows) or 'هیچ قفل فعالی ثبت نشده.'
        await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('🔙 پنل مالک','own6:home')]]))
        return
    if action == 'help':
        await q.edit_message_text('📚 <b>راهنمای پنل مالک</b>\n\n💎 داخل هر گروه بنویس: شارژ vip تعداد_روز\n📣 برای پیام همگانی روی پیام ریپلای کن و بنویس پیام همگانی.\n💾 دکمه بکاپ، نسخه فعلی SQLite را برایت می‌فرستد.\n🛡 امنیت سراسری، وضعیت قفل‌های فعال گروه‌ها را نشان می‌دهد.',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 پنل مالک','own6:home')]]))
        return
    await q.answer('گزینه نامعتبر است.',show_alert=True)


