async def member_update_v6(update, context):
    """Reliable join/leave handling through ChatMemberHandler."""
    cm=update.chat_member
    if not cm or not cm.chat or cm.chat.type=='private':
        return
    old=cm.old_chat_member.status
    new=cm.new_chat_member.status
    user=cm.new_chat_member.user
    await DBX.ensure_chat(cm.chat)
    await DBX.ensure_user(user)
    joined = new in {ChatMemberStatus.MEMBER, ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER, ChatMemberStatus.RESTRICTED} and old in {ChatMemberStatus.LEFT, ChatMemberStatus.BANNED}
    left = new in {ChatMemberStatus.LEFT, ChatMemberStatus.BANNED} and old not in {ChatMemberStatus.LEFT, ChatMemberStatus.BANNED}
    if joined:
        try:
            await DBX.execute('UPDATE chat_member_stats SET adds=COALESCE(adds,0)+1,first_name=?,username=? WHERE chat_id=? AND user_id=?',(display_name(user),user.username or '',cm.chat.id,user.id))
        except Exception:
            pass
        try:
            row=await DBX.one('SELECT welcome_enabled,welcome_text FROM chats WHERE chat_id=?',(cm.chat.id,))
            if row and int(row['welcome_enabled'] or 0):
                text=(row['welcome_text'] or '🐕 خوش اومدی {name}! به {group} خوش اومدی.').replace('{name}',display_name(user)).replace('{id}',str(user.id)).replace('{username}',('@'+user.username) if user.username else display_name(user)).replace('{group}',cm.chat.title or 'گروه هاپویی').replace('{group_name}',cm.chat.title or 'گروه هاپویی')
                await context.bot.send_message(cm.chat.id,text,parse_mode='HTML')
        except TelegramError:
            pass
    elif left:
        try:
            row=await DBX.one('SELECT goodbye_enabled,goodbye_text FROM chats WHERE chat_id=?',(cm.chat.id,))
            if row and int(row['goodbye_enabled'] or 0):
                text=(row['goodbye_text'] or '👋 {name} از {group} رفت.').replace('{name}',display_name(user)).replace('{id}',str(user.id)).replace('{username}',('@'+user.username) if user.username else display_name(user)).replace('{group}',cm.chat.title or 'گروه هاپویی').replace('{group_name}',cm.chat.title or 'گروه هاپویی')
                await context.bot.send_message(cm.chat.id,text,parse_mode='HTML')
        except TelegramError:
            pass


