async def security_check_v6(update, context):
    """Improved advanced lock checker with configurable warning limit."""
    msg=update.effective_message; chat=update.effective_chat; user=update.effective_user
    if not msg or not chat or chat.type=='private' or not user: return False
    if await local_admin(update,user.id): return False
    if await DBX.one('SELECT 1 FROM exemptions WHERE chat_id=? AND user_id=?',(chat.id,user.id)): return False
    text=normalize(getattr(msg,'text','') or getattr(msg,'caption','') or '')
    checks=[]
    if text:
        if re.search(r'https?://|t\.me/|www\.',text,re.I): checks += ['links','url','tme']
        if len(re.findall(r'@[A-Za-z0-9_]{3,}',text))>=5: checks += ['mention','massmention']
        if len(text)>1500: checks += ['longtext','excessive_length']
        if re.search(r'(.)\1{8,}',text): checks += ['repeat','repeated_chars']
        if text.count('!')+text.count('?')>30: checks += ['spam','text_burst']
        if BAD_PATTERNS['adult'].search(text): checks += ['adult','porn','nsfw','adult_keyword','sexual_keyword']
        if BAD_PATTERNS['tabchi'].search(text): checks += ['tabchi','tabchi_pattern']
        if BAD_PATTERNS['scam'].search(text): checks += ['scam','phishing','scam_keyword','fraud','cheat_keyword']
    if getattr(msg,'photo',None): checks += ['photo','photo_spam']
    if getattr(msg,'video',None): checks += ['video','video_spam']
    if getattr(msg,'animation',None): checks += ['gif','animation','gif_spam']
    if getattr(msg,'voice',None): checks += ['voice','voice_spam']
    if getattr(msg,'audio',None): checks += ['audio']
    if getattr(msg,'document',None): checks += ['file','document','file_spam']
    if getattr(msg,'sticker',None): checks += ['sticker','sticker_spam']
    if getattr(msg,'contact',None): checks += ['contact','contact_spam']
    if getattr(msg,'location',None): checks += ['location','location_spam']
    if getattr(msg,'poll',None): checks += ['poll','poll_spam']
    if getattr(msg,'forward_origin',None): checks += ['forward','forwardedmedia']
    entities=getattr(msg,'entities',None) or getattr(msg,'caption_entities',None) or []
    if any(getattr(e,'type','')=='mention' for e in entities): checks.append('mention')
    active=[]
    for key in dict.fromkeys(checks):
        if await advanced_lock_status(chat.id,key): active.append(key)
    if not active: return False
    rights=await get_bot_rights(context.bot,chat.id)
    if not rights.get('delete'): return False
    try: await msg.delete(); await record_stat(chat.id,'deleted')
    except TelegramError: return False
    row=await DBX.one('SELECT warn_limit,punishment,mute_minutes FROM custom_security WHERE chat_id=?',(chat.id,))
    limit=int(row['warn_limit']) if row else 3
    punishment=(row['punishment'] if row else 'mute')
    minutes=int(row['mute_minutes']) if row else 10
    count=await DBX.warn(chat.id,user.id)
    warn=await context.bot.send_message(chat.id,f'⚠️ {mention_html(user)} پیام توسط امنیت حذف شد.\n🔒 {ADV_LOCK_NAMES.get(active[0],active[0])}\n⚠️ اخطار: <b>{count}/{limit}</b>',parse_mode='HTML')
    if context.job_queue: context.job_queue.run_once(delete_later_job,5,data=(chat.id,warn.message_id))
    if count>=limit:
        try:
            if punishment=='ban':
                await context.bot.ban_chat_member(chat.id,user.id)
            elif rights.get('restrict'):
                await chat.restrict_member(user.id,ChatPermissions(can_send_messages=False),until_date=datetime.now()+timedelta(minutes=minutes))
            await DBX.clear_warn(chat.id,user.id)
        except TelegramError:
            pass
    return True


async def mute_command_v6(update, context, permanent=False):
    if not await local_admin(update):
        await update.effective_message.reply_text('⛔ فقط ادمین واقعی.'); return True
    target=await target_from_reply(update)
    if not target:
        await update.effective_message.reply_text('🔇 روی پیام کاربر ریپلای کن.\nمثال: سکوت یا سکوت 5')
        return True
    parts=normalize(update.effective_message.text or '').split()
    minutes=None
    if len(parts)>=2 and parts[1].isdigit(): minutes=max(1,min(10080,int(parts[1])))
    try:
        perms=ChatPermissions(can_send_messages=False)
        until=None if minutes is None else datetime.now()+timedelta(minutes=minutes)
        await context.bot.restrict_chat_member(update.effective_chat.id,target.id,permissions=perms,until_date=until)
        await update.effective_message.reply_text('🔇 سکوت دائمی شد.' if minutes is None else f'🔇 کاربر {minutes} دقیقه ساکت شد.')
    except TelegramError as e:
        await update.effective_message.reply_text('⚠️ ربات دسترسی لازم برای سکوت این کاربر را ندارد.')
    return True


async def open_close_group_v6(update, context, close=True, minutes=None):
    if not await local_admin(update):
        await update.effective_message.reply_text('⛔ فقط ادمین واقعی.'); return True
    try:
        if close:
            until=datetime.now()+timedelta(minutes=minutes) if minutes else None
            perms=ChatPermissions(can_send_messages=False)
            await context.bot.set_chat_permissions(update.effective_chat.id,perms)
            text='🔒 گروه بسته شد.' if not minutes else f'🔒 گروه برای {minutes} دقیقه بسته شد.'
            if minutes and context.job_queue:
                context.job_queue.run_once(open_close_group_job,minutes*60,data=update.effective_chat.id)
        else:
            perms=ChatPermissions(can_send_messages=True,can_send_audios=True,can_send_documents=True,can_send_photos=True,can_send_videos=True,can_send_video_notes=True,can_send_voice_notes=True,can_send_polls=True,can_send_other_messages=True,can_add_web_page_previews=True)
            await context.bot.set_chat_permissions(update.effective_chat.id,perms)
            text='🔓 گروه باز شد.'
        await update.effective_message.reply_text(text)
    except TelegramError:
        await update.effective_message.reply_text('⚠️ دسترسی تغییر مجوزهای گروه برای ربات فعال نیست.')
    return True


async def open_close_group_job(context):
    cid=context.job.data
    try:
        perms=ChatPermissions(can_send_messages=True,can_send_audios=True,can_send_documents=True,can_send_photos=True,can_send_videos=True,can_send_video_notes=True,can_send_voice_notes=True,can_send_polls=True,can_send_other_messages=True,can_add_web_page_previews=True)
        await context.bot.set_chat_permissions(cid,perms)
    except TelegramError:
        pass


async def adventure_v6(update, context):
    """Safe replacement for weapon-based hunting: fictional dog adventure."""
    if not update.effective_chat or update.effective_chat.type=='private': return False
    await DBX.ensure_user(update.effective_user)
    u=await DBX.one('SELECT bones,dog_level FROM users WHERE user_id=?',(update.effective_user.id,))
    reward=random.randint(20,120)+int(u['dog_level'] or 1)*5
    await DBX.execute('UPDATE users SET bones=bones+?,xp=xp+? WHERE user_id=?',(reward,reward//2,update.effective_user.id))
    await update.effective_message.reply_text(f'🐾 <b>ماجراجویی هاپویی</b>\n\nهاپو یک مسیر تازه پیدا کرد و با موفقیت برگشت!\n🦴 جایزه: <b>+{reward}</b> استخوان\n\n🎒 بدون سلاح و بدون شرط؛ فقط یک ماجراجویی سرگرم‌کننده.',parse_mode='HTML',reply_markup=keyboard([[btn('🐕 هاپویی',user_cb(update.effective_user.id,'dog'))],[btn('🔙 بستن',user_cb(update.effective_user.id,'home'))]]))
    return True


async def process_text_state_v6(update, context):
    msg=update.effective_message
    t=normalize(getattr(msg,'text','') or '') if msg else ''
    if not t: return await process_text_state_v5(update,context)
    if t in {'شکار','منطقه شکار','ماجراجویی'}:
        return await adventure_v6(update,context)
    if t.startswith('سکوت') or t in {'هیس','خفه'}:
        return await mute_command_v6(update,context)
    if t in {'رفع سکوت','انحذف سکوت','باز کردن سکوت'}:
        if not await local_admin(update): await msg.reply_text('⛔ فقط ادمین واقعی.'); return True
        target=await target_from_reply(update)
        if not target: await msg.reply_text('روی پیام کاربر ریپلای کن.'); return True
        try:
            perms=ChatPermissions(can_send_messages=True,can_send_audios=True,can_send_documents=True,can_send_photos=True,can_send_videos=True,can_send_video_notes=True,can_send_voice_notes=True,can_send_polls=True,can_send_other_messages=True,can_add_web_page_previews=True)
            await context.bot.restrict_chat_member(update.effective_chat.id,target.id,permissions=perms)
            await msg.reply_text('🔊 سکوت کاربر برداشته شد.')
        except TelegramError: await msg.reply_text('⚠️ دسترسی لازم وجود ندارد.')
        return True
    if t.startswith('بستن گروه') or t.startswith('بستن'):
        if t=='بستن': return await open_close_group_v6(update,context,True,None)
        p=t.split(); mins=int(p[2]) if len(p)>=3 and p[2].isdigit() else None
        return await open_close_group_v6(update,context,True,mins)
    if t in {'باز کردن گروه','بازکردن گروه','باز کردن'}:
        return await open_close_group_v6(update,context,False,None)
    if t=='پیام همگانی': return await owner_broadcast_send(update,context)
    if t in {'امنیت','پنل امنیت'} and update.effective_chat and update.effective_chat.type!='private':
        if not await local_admin(update): await msg.reply_text('⛔ فقط ادمین واقعی.'); return True
        await msg.reply_text('🛡 <b>مرکز امنیت</b>\n\nاز پنل مدیریت وارد «۱۰۰+ قفل» شو.\nضدپورن، ضدتبچی، ضداسپم، ضدتقلب و ضدفیشینگ قابل فعال‌سازی‌اند.',parse_mode='HTML',reply_markup=await management_keyboard_v5(update.effective_user.id))
        return True
    # Fix the old fake-query security path by never constructing an invalid callback object.
    if t in {'تفنگ','قمار','کازینو'}:
        await msg.reply_text('⛔ این بخش‌ها به شکل سلاح یا شرط‌بندی پیاده‌سازی نمی‌شوند. به‌جایش «شکار» برای ماجراجویی امن و بازی‌های بدون شرط فعال است.')
        return True
    return await process_text_state_v5(update,context)


async def message_router_v6(update,context):
    msg=update.effective_message
    if not msg: return
    if update.effective_chat and update.effective_chat.type!='private':
        await DBX.ensure_chat(update.effective_chat)
    if update.effective_user:
        await DBX.ensure_user(update.effective_user)
    if update.effective_chat and update.effective_chat.type!='private':
        try: await record_v4_member_message(update)
        except Exception: pass
    if await enforce_forcejoin(update,context): return
    if await process_text_state_v6(update,context): return
    if await security_check_v6(update,context): return
    await enforce_locks_v4(update,context)


async def callback_router_v6(update,context):
    q=update.callback_query
    if not q: return
    try: await q.answer()
    except TelegramError: pass
    data=q.data or ''
    if data.startswith('own6:'):
        await owner_callback_v6(q,context); return
    if data.startswith('mfrooms:'):
        fake=type('U',(),{'effective_chat':q.message.chat,'effective_user':q.from_user,'effective_message':q.message})()
        await mafia_start_menu(fake,context); return
    if data.startswith('asecset:'):
        p=data.split(':'); await security_settings_v6(q,int(p[1]),q.message.chat.id,int(p[2])); return
    if data.startswith('asecpun:'):
        p=data.split(':'); await security_punish_v6(q,int(p[1]),q.message.chat.id,p[2]); return
    if data.startswith('avlock:'):
        p=data.split(':',2); await advanced_lock_toggle(q,int(p[1]),q.message.chat.id,p[2]); await advanced_security_panel(q,q.from_user.id,q.message.chat.id,0); return
    if data.startswith('avpage:'):
        p=data.split(':'); await advanced_security_panel(q,int(p[1]),q.message.chat.id,int(p[2])); return
    if data.startswith('asec:settings:'):
        uid=int(data.rsplit(':',1)[1]); await security_settings_v6(q,uid,q.message.chat.id); return
    if data.startswith('a:'):
        await management_v5(q,context); return
    await callback_router(update,context)


async def post_init_v6(application):
    await ensure_v3_schema(); await ensure_v4_schema(); await ensure_v5_schema()
    try:
        await application.bot.set_my_commands([('start','شروع'),('help','راهنما'),('panel','پنل'),('features','قابلیت‌ها'),('rules','قوانین'),('stats','آمار')])
    except TelegramError:
        pass
    if application.job_queue:
        application.job_queue.run_repeating(auto_cleanup_job,30,first=30,name='bilbilak-auto-cleanup-v6')


def build_application(token:str)->Application:
    app=ApplicationBuilder().token(token).post_init(post_init_v6).post_shutdown(post_shutdown).build()
    app.add_handler(CommandHandler('start',start_v5))
    app.add_handler(CommandHandler('help',cmd_help))
    app.add_handler(CommandHandler('panel',cmd_panel))
    app.add_handler(CommandHandler('adminpanel',cmd_adminpanel))
    app.add_handler(CommandHandler('owner',owner_panel_v6))
    app.add_handler(CommandHandler('features',cmd_features))
    app.add_handler(CommandHandler('rules',rules_command))
    app.add_handler(CommandHandler('setrules',set_rules))
    app.add_handler(CommandHandler('welcome',set_welcome))
    app.add_handler(CommandHandler('togglewelcome',toggle_welcome))
    app.add_handler(CommandHandler('goodbye',set_goodbye))
    app.add_handler(CommandHandler('togglegoodbye',toggle_goodbye))
    app.add_handler(CommandHandler('forcejoin',forcejoin_v4))
    app.add_handler(CommandHandler('stats',stats_v4_command))
    app.add_handler(CommandHandler('cleanup',lambda u,c:cleanup_v4(u,c,500)))
    app.add_handler(CommandHandler('warn',lambda u,c:moderation_action(u,c,'warn')))
    app.add_handler(CommandHandler('unwarn',lambda u,c:moderation_action(u,c,'unwarn')))
    app.add_handler(CommandHandler('mute',lambda u,c:mute_command_v6(u,c)))
    app.add_handler(CommandHandler('unmute',lambda u,c:moderation_v4(u,c,'unmute')))
    app.add_handler(CommandHandler('ban',lambda u,c:moderation_v4(u,c,'ban')))
    app.add_handler(CommandHandler('unban',lambda u,c:moderation_v4(u,c,'unban')))
    app.add_handler(ChatMemberHandler(member_update_v6, ChatMemberHandler.CHAT_MEMBER))
    app.add_handler(CallbackQueryHandler(callback_router_v6))
    if MessageReactionHandler is not None:
        app.add_handler(MessageReactionHandler(reaction_handler))
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS,service_members_v4))
    app.add_handler(MessageHandler(filters.StatusUpdate.LEFT_CHAT_MEMBER,service_members_v4))
    app.add_handler(MessageHandler(filters.LOCATION,location_v4))
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,message_router_v6))
    app.add_error_handler(error_handler)
    return app

