async def ensure_v7_schema():
    await DBX.execute('''CREATE TABLE IF NOT EXISTS dog_state (
        user_id INTEGER PRIMARY KEY,
        energy INTEGER NOT NULL DEFAULT 100,
        hunger INTEGER NOT NULL DEFAULT 20,
        happiness INTEGER NOT NULL DEFAULT 50,
        cleanliness INTEGER NOT NULL DEFAULT 80,
        last_daily INTEGER NOT NULL DEFAULT 0,
        created_at INTEGER NOT NULL DEFAULT 0
    )''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS friendships (
        user_id INTEGER NOT NULL,
        friend_id INTEGER NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending',
        created_at INTEGER NOT NULL,
        PRIMARY KEY(user_id, friend_id)
    )''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS daily_gifts (
        user_id INTEGER PRIMARY KEY,
        day TEXT NOT NULL,
        claimed INTEGER NOT NULL DEFAULT 0
    )''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS factory_items (
        user_id INTEGER NOT NULL,
        item_key TEXT NOT NULL,
        qty INTEGER NOT NULL DEFAULT 0,
        PRIMARY KEY(user_id,item_key)
    )''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS competition_scores (
        chat_id INTEGER NOT NULL,
        user_id INTEGER NOT NULL,
        season TEXT NOT NULL,
        points INTEGER NOT NULL DEFAULT 0,
        PRIMARY KEY(chat_id,user_id,season)
    )''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS safe_game_stats (
        user_id INTEGER NOT NULL,
        game_key TEXT NOT NULL,
        plays INTEGER NOT NULL DEFAULT 0,
        wins INTEGER NOT NULL DEFAULT 0,
        points INTEGER NOT NULL DEFAULT 0,
        PRIMARY KEY(user_id,game_key)
    )''')

async def ensure_dog_state(uid):
    await DBX.execute('INSERT OR IGNORE INTO dog_state(user_id,created_at) VALUES(?,?)',(uid,now_ts()))
    row=await DBX.one('SELECT * FROM dog_state WHERE user_id=?',(uid,))
    return row

