async def v7_dog_action(q, uid, action):
    if q.from_user.id!=uid:
        await q.answer('این پنل برای خودت نیست 😄',show_alert=True); return
    d=await ensure_dog_state(uid)
    vals={'energy':int(d['energy']),'hunger':int(d['hunger']),'happiness':int(d['happiness']),'cleanliness':int(d['cleanliness'])}
    u=await DBX.get_user(uid)
    if action=='feed':
        if int(u['bones'])<3:
            await q.answer('۳ استخوان برای غذا لازم داری.',show_alert=True); return
        vals['hunger']=min(100,vals['hunger']+25); vals['happiness']=min(100,vals['happiness']+5)
        await DBX.execute('UPDATE users SET bones=bones-3 WHERE user_id=?',(uid,)); msg='🍖 هاپو غذا خورد!'
    elif action=='play':
        if vals['energy']<15:
            await q.answer('⚡ انرژی هاپو کمه؛ اول استراحتش بده.',show_alert=True); return
        vals['energy']-=15; vals['happiness']=min(100,vals['happiness']+18); vals['hunger']=min(100,vals['hunger']+8); msg='🎾 هاپو کلی بازی کرد!'
    elif action=='clean':
        vals['cleanliness']=min(100,vals['cleanliness']+30); vals['happiness']=min(100,vals['happiness']+4); msg='🛁 هاپو تمیز و مرتب شد!'
    elif action=='rest':
        vals['energy']=min(100,vals['energy']+30); vals['hunger']=min(100,vals['hunger']+5); msg='😴 هاپو استراحت کرد و انرژی گرفت!'
    else: return
    await DBX.execute('UPDATE dog_state SET energy=?,hunger=?,happiness=?,cleanliness=? WHERE user_id=?',
                       (vals['energy'],vals['hunger'],vals['happiness'],vals['cleanliness'],uid))
    await q.answer(msg,show_alert=True)
    await v7_dog_panel(q,uid)

async def v7_daily(q, uid):
    if q.from_user.id!=uid: await q.answer('این هدیه برای خودت است.',show_alert=True); return
    day=datetime.now().strftime('%Y-%m-%d')
    row=await DBX.one('SELECT day,claimed FROM daily_gifts WHERE user_id=?',(uid,))
    if row and row['day']==day and int(row['claimed']):
        await q.answer('🎁 هدیه امروزت را قبلاً گرفتی.',show_alert=True); return
    reward=random.randint(8,20)
    await DBX.execute('INSERT OR REPLACE INTO daily_gifts(user_id,day,claimed) VALUES(?,?,1)',(uid,day))
    await DBX.execute('UPDATE users SET bones=bones+?,xp=xp+5 WHERE user_id=?',(reward,uid))
    await q.answer(f'🎁 +{reward} استخوان و +5 XP گرفتی!',show_alert=True)
    await v7_dog_panel(q,uid)

