def v8_game_keyboard(uid):
    items=list(V8_GAMES.items())
    rows=[]
    for i in range(0,len(items),2):
        rows.append([btn(a,f'v8game:{uid}:{k}') for k,a in items[i:i+2]])
    rows.append([btn('🏆 رتبه بازی‌ها',f'v8game:{uid}:rank')])
    rows.append([btn('🔙 خانه',user_cb(uid,'home'))])
    return keyboard(rows)


def v8_home_keyboard(uid, admin=False):
    rows=[
      [btn(owner_label('dog','🐾 هاپویی'),user_cb(uid,'dog')),btn(owner_label('games','🎮 ۵۰ بازی'),user_cb(uid,'games'))],
      [btn(owner_label('tools','🧰 ابزارها'),user_cb(uid,'tools')),btn(owner_label('factory','🏭 کارخانه'),f'v8factory:{uid}:home')],
      [btn(owner_label('friends','🤝 دوستی'),f'v8friend:{uid}:home'),btn(owner_label('competition','🏆 رقابت'),f'v8comp:{uid}:home')],
      [btn('👤 پروفایل من',user_cb(uid,'profile')),btn('🎁 مأموریت‌ها',user_cb(uid,'missions'))],
      [btn('📚 راهنما',user_cb(uid,'help')),btn('⚙️ تنظیمات من',f'v8settings:{uid}:home')],
    ]
    if admin: rows.insert(-1,[btn('🛡 پنل مدیریت',admin_cb(uid,'home'))])
    return keyboard(rows)

