async def v8_game(q,uid,key):
    if q.from_user.id!=uid: await q.answer('این بازی برای خودت نیست.',show_alert=True); return
    if key=='rank':
        rows=await DBX.execute("SELECT u.first_name,COALESCE(SUM(s.points),0) points FROM safe_game_stats s JOIN users u ON u.user_id=s.user_id GROUP BY s.user_id ORDER BY points DESC LIMIT 10",fetch=True)
        text='🏆 <b>۱۰ نفر برتر بازی‌ها</b>\n\n'+('\n'.join(f'{i+1}. {safe_text(r["first_name"],25)} — {r["points"]}' for i,r in enumerate(rows)) if rows else 'هنوز امتیازی ثبت نشده.')
        await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('🔙 بازی‌ها',f'v8page:{uid}:games')],[btn('🏠 خانه',f'v8page:{uid}:home')]])); return
    prompt=V8_PROMPTS.get(key,'یک چالش کوتاه و دوستانه انجام بده.')
    pts=random.randint(1,5)
    await DBX.execute("INSERT INTO safe_game_stats(user_id,game_key,plays,wins,points) VALUES(?,?,1,1,?) ON CONFLICT(user_id,game_key) DO UPDATE SET plays=plays+1,wins=wins+1,points=points+excluded.points",(uid,key,pts))
    await DBX.execute('UPDATE users SET xp=xp+?, bones=bones+? WHERE user_id=?',(pts,max(1,pts//2),uid))
    await q.edit_message_text(f'🎮 <b>{V8_GAMES[key]}</b>\n\n{prompt}\n\n⭐ این دور: <b>+{pts} XP</b>\n🦴 جایزه سرگرمی: <b>+{max(1,pts//2)} استخوان</b>\n\n🔒 این بازی هیچ شرط یا قمار ندارد.',parse_mode='HTML',reply_markup=keyboard([[btn('🔄 دوباره',f'v8game:{uid}:{key}')],[btn('🎮 فهرست بازی‌ها',f'v8page:{uid}:games')],[btn('🏠 خانه',f'v8page:{uid}:home')]]))

