async def v8_comp(q,uid):
    if q.from_user.id!=uid: await q.answer('این بخش برای خودت نیست.',show_alert=True); return
    season=datetime.now().strftime('%Y-%m')
    row=await DBX.one('SELECT points FROM competition_scores WHERE chat_id=? AND user_id=? AND season=?',(q.message.chat.id,uid,season)) if q.message and q.message.chat.type!='private' else None
    points=int(row['points']) if row else 0
    await q.edit_message_text(f'🏆 <b>رقابت ماهانه</b>\n\n⭐ امتیاز این دوره: <b>{points}</b>\n\nامتیاز از بازی‌ها و فعالیت‌های سالم جمع می‌شود.',parse_mode='HTML',reply_markup=keyboard([[btn('🏅 جدول برترها',f'v8comp:{uid}:rank')],[btn('🔙 خانه',user_cb(uid,'home'))]]))

