async def v8_callback_router(update,context):
    q=update.callback_query
    if not q: return
    try: await q.answer()
    except TelegramError: pass
    data=q.data or ''
    # Owner can disable selected feature families from the control center.
    feature_map={'v8game':'games','v8factory':'factory','v8friend':'friends','v8comp':'competition','v8tools':'tools'}
    prefix=data.split(':',1)[0]
    if prefix in feature_map and not owner_feature_enabled(feature_map[prefix]):
        await q.answer('این قابلیت فعلاً توسط سازنده غیرفعال شده است.',show_alert=True); return
    if data.startswith('v8game:'):
        p=data.split(':',2)
        if len(p)==3 and p[1].isdigit(): await v8_game(q,int(p[1]),p[2])
        return
    if data.startswith('v8page:'):
        p=data.split(':',2)
        if len(p)==3 and p[1].isdigit() and p[2]=='games': await v8_games(q,int(p[1]))
        elif len(p)==3 and p[1].isdigit() and p[2]=='home': await v8_home(q,int(p[1]))
        return
    if data.startswith('v8factory:'):
        p=data.split(':',2)
        if len(p)==3 and p[1].isdigit():
            if p[2]=='home': await v7_factory(q,int(p[1]))
            else: await v7_factory_craft(q,int(p[1]),p[2])
        return
    if data.startswith('v8friend:'):
        p=data.split(':',2)
        if len(p)==3 and p[1].isdigit(): await v8_friend(q,int(p[1]),p[2])
        return
    if data.startswith('v8comp:'):
        p=data.split(':',2)
        if len(p)==3 and p[1].isdigit():
            if p[2]=='rank': await v8_comp_rank(q,int(p[1]))
            else: await v8_comp(q,int(p[1]))
        return
    if data.startswith('v8settings:'):
        p=data.split(':',2)
        if len(p)==3 and p[1].isdigit(): await v8_settings(q,int(p[1]))
        return
    if data.startswith('v8tools:'):
        p=data.split(':',2)
        if len(p)==3 and p[1].isdigit(): await v8_tools(q,int(p[1]))
        return
    if data.startswith('u:'):
        p=data.split(':',2)
        if len(p)==3 and p[1].isdigit() and int(p[1])==q.from_user.id:
            uid=q.from_user.id; action=p[2]
            if action=='home': await v8_home(q,uid); return
            if action=='dog': await v7_dog_panel(q,uid); return
            if action=='games': await v8_games(q,uid); return
            if action=='tools': await v8_tools(q,uid); return
            if action=='friends': await v8_friend(q,uid); return
            if action=='profile':
                await q.edit_message_text(await user_profile_text(uid),parse_mode='HTML',reply_markup=keyboard([[btn('🎮 بازی‌ها',user_cb(uid,'games'))],[btn(owner_label('tools','🧰 ابزارها'),user_cb(uid,'tools'))],[btn('🔙 خانه',user_cb(uid,'home'))]])); return
            if action=='missions':
                m=await DBX.mission(uid)
                await q.edit_message_text(f'🎁 <b>مأموریت‌های امروز</b>\n\n🐾 هاپ‌هاپ: {m["hops"]}/3\n🎮 بازی: {m["games"]}/2\n🦴 جمع‌آوری: {m["collect"]}/1\n\nپاداش تکمیل: 25 XP و 10 استخوان.',parse_mode='HTML',reply_markup=keyboard([[btn('🎁 دریافت پاداش',f'mission:{uid}:claim')],[btn('🔙 خانه',user_cb(uid,'home'))]])); return
            if action=='help': await v7_help(q,uid); return
            if action=='music':
                await q.edit_message_text('🎵 <b>موزیکال</b>\n\nبرای جستجو بنویس: «سرچ آهنگ نام آهنگ»\nبرای رادیو بنویس: «رادیو نام ایستگاه»',parse_mode='HTML',reply_markup=keyboard([[btn(owner_label('tools','🧰 ابزارها'),user_cb(uid,'tools'))],[btn('🔙 خانه',user_cb(uid,'home'))]])); return
        # not this user: do not execute their panel
        await q.answer('این پنل برای کاربر دیگری است.',show_alert=True); return
    if data.startswith('own6:'):
        await owner_callback_v7(q,context); return
    if data.startswith('rich:'):
        # Existing rich tools already validate the user and provide their own return buttons.
        await callback_router_v6(update,context); return
    await callback_router_v6(update,context)

async def start_v8(update,context):
    if not update.effective_user: return
    await DBX.ensure_user(update.effective_user); await ensure_dog_state(update.effective_user.id)
    if update.effective_chat and update.effective_chat.type=='private':
        if await owner_check(update.effective_user.id): await owner_panel_v6(update,context)
        else: await update.effective_message.reply_text(PRIVATE_TEXT,parse_mode='HTML',reply_markup=private_keyboard())
    else:
        await send_group_panel(update,context)

async def message_router_v8(update,context):
    msg=update.effective_message
    if not msg: return
    if update.effective_chat and update.effective_chat.type!='private': await DBX.ensure_chat(update.effective_chat)
    if update.effective_user:
        await DBX.ensure_user(update.effective_user); await ensure_dog_state(update.effective_user.id)
    if update.effective_chat and update.effective_chat.type!='private':
        try: await record_v4_member_message(update)
        except Exception: pass
    if await enforce_forcejoin(update,context): return
    t=normalize(getattr(msg,'text','') or '')
    # Owner-defined aliases can point to an existing bot text command.
    if t in OWNER_COMMAND_ALIASES:
        t=normalize(OWNER_COMMAND_ALIASES[t])
    if t in {'بازی‌ها','بازی ها','شهر بازی','۵۰ بازی','50 بازی'}:
        if not owner_feature_enabled('games'):
            await msg.reply_text('⛔ این قابلیت فعلاً غیرفعال است.'); return

        await msg.reply_text('🎮 شهر بازی را از پنل کاربری باز کن 👇',reply_markup=keyboard([[btn('🎮 باز کردن شهر بازی',user_cb(update.effective_user.id,'games'))]])); return
    if t in {'هاپویی','پنل هاپویی'}:
        fake=type('Q',(),{'from_user':update.effective_user,'message':msg,'answer':lambda *a,**k:None,'edit_message_text':msg.reply_text})()
        await v7_dog_panel(fake,update.effective_user.id); return
    if t in {'کارخانه','کارخانه هاپویی'}:
        fake=type('Q',(),{'from_user':update.effective_user,'message':msg,'answer':lambda *a,**k:None,'edit_message_text':msg.reply_text})()
        await v7_factory(fake,update.effective_user.id); return
    if t in {'رقابت','مسابقه','جدول رقابت'}:
        fake=type('Q',(),{'from_user':update.effective_user,'message':msg,'answer':lambda *a,**k:None,'edit_message_text':msg.reply_text})()
        await v8_comp(fake,update.effective_user.id); return
    if t in {'دوستی','دوست'}:
        target=await target_from_reply(update)
        if target and target.id!=update.effective_user.id:
            await DBX.execute('INSERT OR REPLACE INTO friendships(user_id,friend_id,status,created_at) VALUES(?,?,?,?)',(update.effective_user.id,target.id,'pending',now_ts()))
            await msg.reply_text(f'🤝 درخواست دوستی برای {mention_html(target)} ثبت شد.',parse_mode='HTML')
        else: await msg.reply_text('🤝 روی پیام کاربر موردنظر ریپلای کن و «دوستی» بنویس.')
        return
    if await process_text_state_v6(update,context): return
    if await security_check_v6(update,context): return
    await enforce_locks_v4(update,context)

async def post_init_v8(application):
    await ensure_v3_schema(); await ensure_v4_schema(); await ensure_v5_schema(); await ensure_v7_schema()
    try: await application.bot.set_my_commands([('start','شروع'),('help','راهنما'),('panel','پنل'),('features','قابلیت‌ها'),('rules','قوانین'),('stats','آمار')])
    except TelegramError: pass
    if application.job_queue:
        application.job_queue.run_repeating(auto_cleanup_job,30,first=30,name='bilbilak-auto-cleanup-v8')


def build_application(token:str)->Application:
    app=ApplicationBuilder().token(token).post_init(post_init_v8).post_shutdown(post_shutdown).build()
    app.add_handler(CommandHandler('start',start_v8)); app.add_handler(CommandHandler('help',cmd_help)); app.add_handler(CommandHandler('panel',cmd_panel)); app.add_handler(CommandHandler('adminpanel',cmd_adminpanel)); app.add_handler(CommandHandler('owner',owner_panel_v6)); app.add_handler(CommandHandler('features',cmd_features)); app.add_handler(CommandHandler('rules',rules_command)); app.add_handler(CommandHandler('setrules',set_rules)); app.add_handler(CommandHandler('welcome',set_welcome)); app.add_handler(CommandHandler('togglewelcome',toggle_welcome)); app.add_handler(CommandHandler('goodbye',set_goodbye)); app.add_handler(CommandHandler('togglegoodbye',toggle_goodbye)); app.add_handler(CommandHandler('forcejoin',forcejoin_v4)); app.add_handler(CommandHandler('stats',stats_v4_command)); app.add_handler(CommandHandler('cleanup',lambda u,c:cleanup_v4(u,c,500)))
    app.add_handler(CommandHandler('warn',lambda u,c:moderation_action(u,c,'warn'))); app.add_handler(CommandHandler('unwarn',lambda u,c:moderation_action(u,c,'unwarn'))); app.add_handler(CommandHandler('mute',lambda u,c:mute_command_v6(u,c))); app.add_handler(CommandHandler('unmute',lambda u,c:moderation_v4(u,c,'unmute'))); app.add_handler(CommandHandler('ban',lambda u,c:moderation_v4(u,c,'ban'))); app.add_handler(CommandHandler('unban',lambda u,c:moderation_v4(u,c,'unban')))
    app.add_handler(ChatMemberHandler(member_update_v6, ChatMemberHandler.CHAT_MEMBER))
    app.add_handler(CallbackQueryHandler(owner_control_action_callback, pattern=r'^oct:'))
    app.add_handler(CallbackQueryHandler(owner_control_callback, pattern=r'^oc:'))
    app.add_handler(CallbackQueryHandler(v8_callback_router))
    if MessageReactionHandler is not None: app.add_handler(MessageReactionHandler(reaction_handler))
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS,service_members_v4)); app.add_handler(MessageHandler(filters.StatusUpdate.LEFT_CHAT_MEMBER,service_members_v4)); app.add_handler(MessageHandler(filters.LOCATION,location_v4)); app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,owner_control_text))
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,message_router_v8)); app.add_error_handler(error_handler)
    return app


# =============================================================================
# BILBILAK V9 - STABILITY + PERSISTENT OWNER CONTROL + VIP PRO + MAFIA PRO
# =============================================================================

async def ensure_v9_schema():
    await DBX.execute('''CREATE TABLE IF NOT EXISTS owner_config (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL DEFAULT ''
    )''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS vip_settings (
        chat_id INTEGER PRIMARY KEY,
        level TEXT NOT NULL DEFAULT 'gold',
        welcome_media INTEGER NOT NULL DEFAULT 1,
        advanced_security INTEGER NOT NULL DEFAULT 1,
        auto_cleanup INTEGER NOT NULL DEFAULT 1,
        extra_stats INTEGER NOT NULL DEFAULT 1,
        custom_panel INTEGER NOT NULL DEFAULT 1,
        music_enabled INTEGER NOT NULL DEFAULT 1,
        updated_at INTEGER NOT NULL DEFAULT 0
    )''')
    # Migration for databases created by older Bilbilak builds.
    try:
        await DBX.execute('ALTER TABLE vip_settings ADD COLUMN music_enabled INTEGER NOT NULL DEFAULT 1')
    except Exception:
        pass
    # Load persistent owner configuration into the runtime caches.
    rows = await DBX.execute('SELECT key,value FROM owner_config', fetch=True)
    OWNER_DISABLED.clear(); OWNER_BUTTON_LABELS.clear(); OWNER_COMMAND_ALIASES.clear(); OWNER_CUSTOM_MESSAGES.clear()
    for r in rows:
        k, v = str(r['key']), str(r['value'])
        if k.startswith('disabled:') and v == '1': OWNER_DISABLED.add(k[9:])
        elif k.startswith('label:'): OWNER_BUTTON_LABELS[k[6:]] = v
        elif k.startswith('alias:'): OWNER_COMMAND_ALIASES[k[6:]] = v
        elif k.startswith('msg:'): OWNER_CUSTOM_MESSAGES[k[4:]] = v

async def owner_cfg_set(key, value):
    await DBX.execute('INSERT INTO owner_config(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value', (str(key), str(value)))

async def owner_cfg_del(key):
    await DBX.execute('DELETE FROM owner_config WHERE key=?', (str(key),))

async def vip_level(cid):
    if not await active_vip(cid): return 'free'
    row = await DBX.one('SELECT level FROM vip_settings WHERE chat_id=?', (cid,))
    return (row['level'] if row else 'gold') or 'gold'

async def vip_feature(cid, feature):
    if not await active_vip(cid): return False
    row = await DBX.one('SELECT * FROM vip_settings WHERE chat_id=?', (cid,))
    if not row: return True
    col = {
        'welcome_media':'welcome_media', 'security':'advanced_security',
        'cleanup':'auto_cleanup', 'stats':'extra_stats', 'panel':'custom_panel',
        'music':'music_enabled'
    }.get(feature)
    return bool(row[col]) if col else True

async def ensure_vip_row(cid):
    await DBX.execute('INSERT OR IGNORE INTO vip_settings(chat_id,updated_at) VALUES(?,?)', (cid, now_ts()))

async def vip_status_text(cid):
    row = await DBX.one('SELECT expires_at FROM vip_groups WHERE chat_id=?', (cid,))
    exp = int(row['expires_at']) if row else 0
    remain = max(0, exp-now_ts())
    if not remain:
        return '💎 <b>VIP گروه</b>\n\nوضعیت: ⚪ <b>غیرفعال</b>\n\nبرای فعال‌سازی، سازنده ربات می‌تواند VIP را شارژ کند.'
    await ensure_vip_row(cid)
    level = await vip_level(cid)
    d, h = remain//86400, (remain%86400)//3600
    return (f'💎 <b>VIP گروه — {level.upper()}</b>\n\n'
            f'وضعیت: 🟢 فعال\n⏳ باقی‌مانده: <b>{d} روز و {h} ساعت</b>\n\n'
            '✨ امکانات فعال:\n'
            '• 🛡 امنیت پیشرفته\n'
            '• 🧹 پاکسازی خودکار\n'
            '• 👋 خوش‌آمد رسانه‌ای\n'
            '• 📊 آمار و گزارش بیشتر\n'
            '• 🎛 تنظیمات پنل و امکانات VIP\n\n'
            'شارژ VIP فقط توسط سازنده انجام می‌شود.')

async def vip_panel(q, context):
    cid = q.message.chat.id
    uid = q.from_user.id
    if not await local_admin(type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat})(), uid):
        await q.answer('⛔ فقط ادمین واقعی.', show_alert=True); return
    await q.edit_message_text(
        await vip_status_text(cid), parse_mode='HTML',
        reply_markup=keyboard([
            [btn('✨ امکانات VIP','vip9:'+str(uid)+':features'), btn('📊 وضعیت','vip9:'+str(uid)+':status')],
            [btn('⚙️ تنظیمات VIP','vip9:'+str(uid)+':settings')],
            [btn('🔙 مدیریت',admin_cb(uid,'home'))]
        ]))

async def vip9_callback(q, context):
    p=(q.data or '').split(':')
    if len(p)<3 or not p[1].isdigit() or int(p[1])!=q.from_user.id:
        await q.answer('⛔ این پنل برای تو نیست.',show_alert=True); return
    uid=q.from_user.id; cid=q.message.chat.id; action=p[0]+':'+p[1]+':'+':'.join(p[2:])
    if not await local_admin(type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat})(),uid):
        await q.answer('⛔ فقط ادمین واقعی.',show_alert=True); return
    if p[0]!='vip9': return
    sub=p[2]
    if sub=='status': return await vip_panel(q,context)
    if sub=='features':
        await q.edit_message_text('✨ <b>امکانات VIP بیل بیلک</b>\n\n'
            '🛡 امنیت پیشرفته و قفل‌های بیشتر\n'
            '🧹 پاکسازی خودکار و تنظیمات بیشتر\n'
            '👋 خوش‌آمد/خداحافظی رسانه‌ای\n'
            '📊 آمار و گزارش گسترده‌تر\n'
            '🎛 تنظیمات ویژه پنل گروه\n'
            '🐾 امکانات بیشتر هاپویی در نسخه‌های بعدی\n\n'
            '💡 این VIP اشتراک داخلی ربات است و پرداخت یا شرط مالی داخل بازی‌ها ندارد.',
            parse_mode='HTML',reply_markup=keyboard([[btn('🔙 VIP','vip9:'+str(uid)+':status')]])); return
    if sub=='settings':
        await ensure_vip_row(cid); r=await DBX.one('SELECT * FROM vip_settings WHERE chat_id=?',(cid,))
        await q.edit_message_text('⚙️ <b>تنظیمات VIP</b>\n\n'
            f'👋 خوش‌آمد رسانه‌ای: {"🟢" if r["welcome_media"] else "🔴"}\n'
            f'🛡 امنیت پیشرفته: {"🟢" if r["advanced_security"] else "🔴"}\n'
            f'🧹 پاکسازی خودکار: {"🟢" if r["auto_cleanup"] else "🔴"}\n'
            f'📊 آمار بیشتر: {"🟢" if r["extra_stats"] else "🔴"}\n'
            f'🎵 موزیکال: {"🟢" if r["music_enabled"] else "🔴"}',
            parse_mode='HTML',reply_markup=keyboard([
                [btn('👋 خوش‌آمد','vip9toggle:'+str(uid)+':welcome_media'),btn('🛡 امنیت','vip9toggle:'+str(uid)+':advanced_security')],
                [btn('🧹 پاکسازی','vip9toggle:'+str(uid)+':auto_cleanup'),btn('📊 آمار','vip9toggle:'+str(uid)+':extra_stats')],
                [btn('🎵 موزیکال','vip9toggle:'+str(uid)+':music_enabled')],
                [btn('🔙 VIP','vip9:'+str(uid)+':status')]
            ])); return

async def vip9_toggle_callback(q, context):
    p=(q.data or '').split(':')
    if len(p)!=3 or not p[1].isdigit() or int(p[1])!=q.from_user.id: await q.answer('⛔ پنل تو نیست.',show_alert=True); return
    uid=q.from_user.id; cid=q.message.chat.id; col=p[2]
    if col not in {'welcome_media','advanced_security','auto_cleanup','extra_stats','music_enabled'}: return
    if not await local_admin(type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat})(),uid): await q.answer('⛔ فقط ادمین.',show_alert=True); return
    if not await active_vip(cid): await q.answer('💎 این گروه VIP فعال ندارد.',show_alert=True); return
    await ensure_vip_row(cid); r=await DBX.one('SELECT '+col+' v FROM vip_settings WHERE chat_id=?',(cid,)); nv=0 if int(r['v'] or 0) else 1
    await DBX.execute('UPDATE vip_settings SET '+col+'=?,updated_at=? WHERE chat_id=?',(nv,now_ts(),cid))
    await q.answer('تنظیم شد.',show_alert=True); await vip_panel(q,context)

