async def owner_control_callback(q, context):
    if not owner_is_allowed(q.from_user.id): await q.answer('⛔ فقط سازنده.',show_alert=True); return
    action=(q.data or '').split(':',1)[1] if ':' in (q.data or '') else ''
    if action=='home': return await owner_control_panel(q,context)
    if action=='account':
        await ensure_cleanup_pro_schema()
        acc=await cleanup_account_row()
        if acc and int(acc['account_user_id'] or 0):
            state='🟢 فعال' if int(acc['enabled'] or 0) else '🔴 خاموش'
            text=(f'👤 <b>اکانت مکمل پاکسازی</b>\n\n'
                  f'{state}\n👤 نام: <b>{safe_text(acc["account_name"] or "بدون نام",50)}</b>\n'
                  f'🆔 {int(acc["account_user_id"])}\n'
                  f'🔎 وضعیت آخرین بررسی: <b>{safe_text(acc["last_status"] or "بررسی نشده",60)}</b>\n\n'
                  'این بخش فقط شناسه و تنظیمات را نگه می‌دارد؛ اطلاعات ورود، کد پیامکی و session ذخیره نمی‌شود.')
        else:
            text=('👤 <b>اتصال اکانت مکمل</b>\n\n'
                  'برای ثبت اکانت، دکمه زیر را بزن و شناسه عددی همان اکانت را ارسال کن.\n\n'
                  'مثال:\nثبت اکانت مکمل 123456789')
        await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([
            [btn('➕ ثبت/تغییر اکانت','oc:account_add')],
            [btn('🔎 بررسی در یک گروه','oc:account_check')],
            [btn('🟢/🔴 فعال یا خاموش','oc:account_toggle')],
            [btn('🗑 حذف تنظیمات','oc:account_del',style='danger')],
            [btn('🧹 تنظیمات پاکسازی','oc:cleanup')],
            [btn('🔙 مرکز کنترل','oc:home')]
        ])); return
    if action=='account_add':
        OWNER_PENDING_CLEANUP_ACCOUNT.add(q.from_user.id)
        await q.answer('شناسه را ارسال کن.',show_alert=True)
        await q.message.reply_text('👤 شناسه عددی اکانت مکمل را همینجا بفرست.\nمثال: ثبت اکانت مکمل 123456789',parse_mode='HTML'); return
    if action=='account_toggle':
        await ensure_cleanup_pro_schema(); acc=await cleanup_account_row()
        if not acc or not int(acc['account_user_id'] or 0):
            await q.answer('اول اکانت مکمل را ثبت کن.',show_alert=True); return
        nv=0 if int(acc['enabled'] or 0) else 1
        await DBX.execute('UPDATE cleanup_accounts SET enabled=?,updated_at=? WHERE id=1',(nv,now_ts()))
        await q.answer('🟢 فعال شد.' if nv else '🔴 خاموش شد.',show_alert=True)
        return await owner_control_callback(type('Q',(),{'from_user':q.from_user,'data':'oc:account','message':q.message,'edit_message_text':q.edit_message_text,'answer':q.answer})(),context)
    if action=='account_del':
        await ensure_cleanup_pro_schema(); await DBX.execute('DELETE FROM cleanup_accounts WHERE id=1')
        OWNER_PENDING_CLEANUP_ACCOUNT.discard(q.from_user.id)
        await q.answer('اکانت مکمل حذف شد.',show_alert=True); return await owner_control_panel(q,context)
    if action=='account_check':
        await ensure_cleanup_pro_schema(); acc=await cleanup_account_row()
        if not acc or not int(acc['account_user_id'] or 0):
            await q.answer('اول اکانت مکمل را ثبت کن.',show_alert=True); return
        await q.message.reply_text('🔎 برای بررسی، وارد گروه موردنظر شو و از پنل پاکسازی همان گروه «بررسی اکانت» را بزن.\n\n⚠️ پنل Owner شناسه اکانت را دائمی نگه می‌دارد، اما بررسی ادمین‌بودن وابسته به گروه است.')
        return
    if action=='cleanup':
        await q.edit_message_text('🧹 <b>پاکسازی Pro</b>\n\nاکانت مکمل از همین مرکز کنترل مدیریت می‌شود و تنظیماتش دائمی در SQLite می‌ماند.\n\nاز پنل مدیریت گروه، پاکسازی را اجرا کن.',parse_mode='HTML',reply_markup=keyboard([
            [btn('👤 اکانت مکمل','oc:account')],
            [btn('🔙 مرکز کنترل','oc:home')]
        ])); return
    if action=='features':
        common=[('🎮 بازی‌ها','games'),('🐾 هاپویی','dog'),('🏭 کارخانه','factory'),('🤝 دوستی','friends'),('🏆 رقابت','competition'),('🧰 ابزارها','tools'),('📣 پیام همگانی','broadcast')]
        rows=[[btn(('🔴 ' if key in OWNER_DISABLED else '🟢 ')+label,'oct:toggle:'+key)] for label,key in common]
        rows.append([btn('🔙 مرکز کنترل','oc:home')])
        await q.edit_message_text('🧩 <b>قابلیت‌ها</b>\n\nقرمز یعنی خاموش. وضعیت در دیتابیس ذخیره می‌شود.',parse_mode='HTML',reply_markup=keyboard(rows)); return
    if action=='buttons':
        await q.edit_message_text('🔘 <b>مدیریت دکمه‌ها</b>\n\n'
            'نام را عوض کن:\nنام دکمه games شهر بازی جدید\n'
            'دکمه را پنهان کن:\nحذف قابلیت games\n'
            'برگردان:\nفعال قابلیت games\n'
            'نام سفارشی را حذف کن:\nحذف نام دکمه games',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 مرکز کنترل','oc:home')]])); return
    if action=='messages':
        await q.edit_message_text('💬 <b>مدیریت پیام‌ها</b>\n\n'
            'پیام سفارشی group_panel متن\nپیام سفارشی welcome متن\n'
            'پیام سفارشی goodbye متن\n\nحذف: حذف پیام سفارشی group_panel',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 مرکز کنترل','oc:home')]])); return
    if action=='commands':
        await q.edit_message_text('⌨️ <b>دستورهای سفارشی</b>\n\n'
            'دستور جدید راهنما help\nدستور جدید بازی‌ها بازی‌ها\n\nحذف: حذف دستور راهنما',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 مرکز کنترل','oc:home')]])); return
    if action=='order':
        await q.edit_message_text('↕️ <b>جابه‌جایی منوی اصلی</b>\n\n'
            'برای جابه‌جایی واقعی دکمه‌ها از دستورهای زیر استفاده کن:\n'
            'جابه‌جایی games بالا\nجابه‌جایی tools پایین\n\n'
            'ترتیب در SQLite ذخیره می‌شود.',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 مرکز کنترل','oc:home')]])); return
    if action=='reset':
        await DBX.execute('DELETE FROM owner_config')
        OWNER_DISABLED.clear(); OWNER_BUTTON_LABELS.clear(); OWNER_COMMAND_ALIASES.clear(); OWNER_CUSTOM_MESSAGES.clear()
        await q.answer('تنظیمات سفارشی بازنشانی شد.',show_alert=True); return await owner_control_panel(q,context)

async def owner_control_action_callback(q, context):
    if not owner_is_allowed(q.from_user.id): await q.answer('⛔ فقط سازنده.',show_alert=True); return
    p=(q.data or '').split(':')
    if len(p)>=3 and p[0]=='oct' and p[1]=='toggle':
        key=owner_feature_key(p[2])
        if key in OWNER_DISABLED: OWNER_DISABLED.remove(key); await owner_cfg_del('disabled:'+key); state='روشن'
        else: OWNER_DISABLED.add(key); await owner_cfg_set('disabled:'+key,'1'); state='خاموش'
        await q.answer(f'{key}: {state}',show_alert=True); return await owner_control_panel(q,context)

async def owner_control_text(update, context):
    msg=update.effective_message; uid=update.effective_user.id if update.effective_user else 0
    if not msg or not owner_is_allowed(uid): return False
    t=normalize(msg.text or '')
    if t in {'کنترل ربات','مرکز کنترل','کنترل کامل'}:
        await msg.reply_text('👑 مرکز کنترل را از /owner باز کن و دکمه «کنترل کامل ربات» را بزن.')
        return True
    if t.startswith('ثبت اکانت مکمل '):
        raw=t.replace('ثبت اکانت مکمل ','',1).strip()
        if raw.isdigit():
            uid=int(raw)
            await ensure_cleanup_pro_schema()
            try:
                # Resolve basic display information without logging in as the user.
                chat=await context.bot.get_chat(uid)
                name=display_name(chat)
            except TelegramError:
                name=f'User {uid}'
            await DBX.execute("INSERT INTO cleanup_accounts(id,account_user_id,account_name,enabled,last_status,created_at,updated_at) VALUES(1,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET account_user_id=excluded.account_user_id,account_name=excluded.account_name,enabled=1,updated_at=excluded.updated_at",(uid,name,1,'ثبت‌شده از پنل Owner',now_ts(),now_ts()))
            OWNER_PENDING_CLEANUP_ACCOUNT.discard(uid if False else update.effective_user.id)
            await msg.reply_text(f'👤 اکانت مکمل ذخیره شد.\n\nنام: <b>{safe_text(name,50)}</b>\n🆔 {uid}\n\n💾 تنظیمات در دیتابیس دائمی ذخیره شد.\n⚠️ برای اجرای واقعی پاکسازی، وضعیت ادمین و دسترسی حذف در همان گروه بررسی می‌شود.',parse_mode='HTML')
            return True
        await msg.reply_text('⛔ شناسه باید عددی باشد. مثال: ثبت اکانت مکمل 123456789',parse_mode='HTML'); return True
    if t == 'حذف اکانت مکمل':
        await ensure_cleanup_pro_schema(); await DBX.execute('DELETE FROM cleanup_accounts WHERE id=1'); OWNER_PENDING_CLEANUP_ACCOUNT.discard(uid); await msg.reply_text('🗑 تنظیمات اکانت مکمل حذف شد.'); return True
    if t == 'خاموش کردن اکانت مکمل':
        await ensure_cleanup_pro_schema(); await DBX.execute('UPDATE cleanup_accounts SET enabled=0,updated_at=? WHERE id=1',(now_ts(),)); await msg.reply_text('🔴 اکانت مکمل خاموش شد.'); return True
    if t == 'فعال کردن اکانت مکمل':
        await ensure_cleanup_pro_schema(); await DBX.execute('UPDATE cleanup_accounts SET enabled=1,updated_at=? WHERE id=1',(now_ts(),)); await msg.reply_text('🟢 اکانت مکمل فعال شد.'); return True
    if t.startswith('حذف قابلیت '):
        key=owner_feature_key(t.replace('حذف قابلیت ','',1).strip()); OWNER_DISABLED.add(key); await owner_cfg_set('disabled:'+key,'1'); await msg.reply_text(f'🔴 قابلیت «{key}» خاموش شد.'); return True
    if t.startswith('فعال قابلیت '):
        key=owner_feature_key(t.replace('فعال قابلیت ','',1).strip()); OWNER_DISABLED.discard(key); await owner_cfg_del('disabled:'+key); await msg.reply_text(f'🟢 قابلیت «{key}» روشن شد.'); return True
    if t.startswith('نام دکمه '):
        p=t.split(' ',3)
        if len(p)>=4:
            key=owner_feature_key(p[2]); val=p[3].strip(); OWNER_BUTTON_LABELS[key]=val; await owner_cfg_set('label:'+key,val); await msg.reply_text('🔘 نام دکمه ذخیره شد.'); return True
    if t.startswith('حذف نام دکمه '):
        key=owner_feature_key(t.replace('حذف نام دکمه ','',1).strip()); OWNER_BUTTON_LABELS.pop(key,None); await owner_cfg_del('label:'+key); await msg.reply_text('🔘 نام سفارشی حذف شد.'); return True
    if t.startswith('پیام سفارشی '):
        p=t.split(' ',3)
        if len(p)>=4:
            key=owner_feature_key(p[2]); val=p[3].strip(); OWNER_CUSTOM_MESSAGES[key]=val; await owner_cfg_set('msg:'+key,val); await msg.reply_text('💬 پیام سفارشی ذخیره شد.'); return True
    if t.startswith('حذف پیام سفارشی '):
        key=owner_feature_key(t.replace('حذف پیام سفارشی ','',1).strip()); OWNER_CUSTOM_MESSAGES.pop(key,None); await owner_cfg_del('msg:'+key); await msg.reply_text('💬 پیام سفارشی حذف شد.'); return True
    if t.startswith('دستور جدید '):
        p=t.split(' ',3)
        if len(p)>=4:
            alias=normalize(p[2]); target=normalize(p[3]); OWNER_COMMAND_ALIASES[alias]=target; await owner_cfg_set('alias:'+alias,target); await msg.reply_text('⌨️ دستور سفارشی ثبت شد.'); return True
    if t.startswith('حذف دستور '):
        alias=normalize(t.replace('حذف دستور ','',1).strip()); OWNER_COMMAND_ALIASES.pop(alias,None); await owner_cfg_del('alias:'+alias); await msg.reply_text('⌨️ دستور حذف شد.'); return True
    return False

# ---- Cleanup callback fix ----
async def cleanup_v4(update, context, count=500):
    if not await is_admin(update):
        target=getattr(update,'effective_message',None) or getattr(update,'message',None)
        if target: await target.reply_text('⛔ فقط ادمین واقعی.')
        return
    chat=update.effective_chat
    target=getattr(update,'effective_message',None) or getattr(update,'message',None)
    rows=await DBX.execute('SELECT message_id FROM message_log WHERE chat_id=? ORDER BY created_at DESC LIMIT ?', (chat.id,int(count)), fetch=True)
    deleted=0
    for r in rows:
        try: await context.bot.delete_message(chat.id,r['message_id']); deleted+=1
        except TelegramError: pass
    await DBX.execute('DELETE FROM message_log WHERE chat_id=?',(chat.id,))
    await record_stat(chat.id,'deleted',deleted)
    if target: await target.reply_text(f'🧹 پاکسازی کامل انجام شد.\n🗑 حذف موفق: <b>{deleted}</b> پیام',parse_mode='HTML')

# ---- One professional Mafia scenario ----
MAFIA_PRO = {}
MAFIA_PRO_SCENARIO = 'شهر سایه‌ها'
MAFIA_PRO_ROLES = {
    'مافیا':'با هم‌تیمی‌های خود هماهنگ شو و تلاش کن هویت تیم شهر را پنهان نگه داری.',
    'پزشک':'هر شب یک بازیکن را برای نجات انتخاب کن.',
    'کارآگاه':'هر شب هویت یک بازیکن را به‌صورت خصوصی بررسی کن.',
    'شهروند':'با گفت‌وگو و رأی‌گیری، اعضای تیم مخفی را پیدا کن.'
}

def mafia_pro_room(cid, host=None):
    room=MAFIA_PRO.get(cid)
    if room is None:
        room={'host':host,'players':{},'roles':{},'alive':set(),'state':'lobby','round':0,
              'night':{'mafia':{},'doctor':{},'detective':{}},'votes':{}}
        MAFIA_PRO[cid]=room
    return room

def mafia_pro_check(room):
    alive=list(room['alive']); mafia=[u for u in alive if room['roles'].get(u)=='مافیا']; town=[u for u in alive if room['roles'].get(u)!='مافیا']
    if not mafia: return 'شهروندان'
    if len(mafia)>=len(town): return 'مافیا'
    return None

def mafia_pro_keyboard(cid,uid):
    return keyboard([
        [btn('➕ ورود',f'mf9:{cid}:join'),btn('👥 بازیکنان',f'mf9:{cid}:players')],
        [btn('▶️ شروع بازی',f'mf9:{cid}:start'),btn('🚪 خروج',f'mf9:{cid}:leave')],
        [btn('📖 قوانین کامل',f'mf9:{cid}:help')]
    ])

async def mafia_start_menu(update, context):
    chat=update.effective_chat; uid=update.effective_user.id
    if chat.type=='private':
        await update.effective_message.reply_text('♟️ مافیا برای گروه طراحی شده است؛ آن را داخل گروه اجرا کن.'); return
    room=mafia_pro_room(chat.id,uid)
    if room['host'] is None: room['host']=uid
    room['players'].setdefault(uid,display_name(update.effective_user))
    await update.effective_message.reply_text(
        f'♟️ <b>مافیا — سناریوی «{MAFIA_PRO_SCENARIO}»</b>\n\n'
        'یک سناریوی ثابت و کامل با ۴ نقش: مافیا، پزشک، کارآگاه و شهروند.\n'
        f'👥 بازیکنان: <b>{len(room["players"])} / 12</b>\n'
        f'👑 میزبان: <b>{safe_text(room["players"].get(room["host"],"میزبان"),50)}</b>\n\n'
        'حداقل ۵ نفر برای شروع پیشنهاد می‌شود. نقش‌ها خصوصی ارسال می‌شوند و بازی در فاز شب/روز پیش می‌رود.',
        parse_mode='HTML',reply_markup=mafia_pro_keyboard(chat.id,uid))

async def mafia2_callback(q,context):
    data=q.data or ''; p=data.split(':',2)
    if len(p)!=3 or p[0]!='mf9': return
    try: cid=int(p[1])
    except ValueError: await q.answer('اتاق نامعتبر است.',show_alert=True); return
    action=p[2]; uid=q.from_user.id; room=MAFIA_PRO.get(cid)
    if not room: await q.answer('این اتاق وجود ندارد.',show_alert=True); return
    if action=='join':
        if room['state']!='lobby': await q.answer('بازی شروع شده است.',show_alert=True); return
        if len(room['players'])>=12: await q.answer('اتاق پر است.',show_alert=True); return
        room['players'][uid]=display_name(q.from_user); await q.answer('وارد بازی شدی! 🐾')
        await q.edit_message_text(f'♟️ <b>مافیا — {MAFIA_PRO_SCENARIO}</b>\n\n👥 بازیکنان: <b>{len(room["players"])} / 12</b>\n👑 میزبان: <b>{safe_text(room["players"].get(room["host"],"میزبان"),50)}</b>',parse_mode='HTML',reply_markup=mafia_pro_keyboard(cid,uid)); return
    if action=='leave':
        room['players'].pop(uid,None); await q.answer('از اتاق خارج شدی.'); return
    if action=='players':
        names='\n'.join(f'{i+1}. {safe_text(n,40)}' for i,n in enumerate(room['players'].values())) or 'هنوز کسی وارد نشده.'
        await q.edit_message_text('👥 <b>بازیکنان مافیا</b>\n\n'+names,parse_mode='HTML',reply_markup=keyboard([[btn('🔙 مافیا',f'mf9:{cid}:back')]])); return
    if action=='back':
        await q.edit_message_text(f'♟️ <b>مافیا — {MAFIA_PRO_SCENARIO}</b>\n\n👥 بازیکنان: <b>{len(room["players"])}/12</b>',parse_mode='HTML',reply_markup=mafia_pro_keyboard(cid,uid)); return
    if action=='help':
        text='♟️ <b>قوانین مافیا — شهر سایه‌ها</b>\n\n'
        '1️⃣ میزبان بازی را شروع می‌کند.\n2️⃣ نقش‌ها خصوصی هستند.\n3️⃣ شب: مافیا هدف، پزشک نجات و کارآگاه بررسی می‌کند.\n4️⃣ روز: گفت‌وگو و رأی‌گیری انجام می‌شود.\n5️⃣ حذف از بازی فقط با نتیجه مکانیک بازی است و هیچ محتوای خشن نمایش داده نمی‌شود.\n6️⃣ برد: اگر همه اعضای مافیا از بازی خارج شوند، شهر می‌برد؛ اگر تعداد مافیا به شهروندان برسد، مافیا می‌برد.\n\n🎭 نقش‌ها:\n'+ '\n'.join(f'• <b>{k}</b>: {v}' for k,v in MAFIA_PRO_ROLES.items())
        await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('🔙 مافیا',f'mf9:{cid}:back')]])); return
    if action=='start':
        if uid!=room['host']: await q.answer('فقط میزبان می‌تواند بازی را شروع کند.',show_alert=True); return
        if len(room['players'])<5: await q.answer('حداقل ۵ بازیکن لازم است.',show_alert=True); return
        ids=list(room['players']); random.shuffle(ids); m=2 if len(ids)>=9 else 1
        roles={}; roles.update({x:'مافیا' for x in ids[:m]}); rest=ids[m:]
        if rest: roles[rest[0]]='پزشک'
        if len(rest)>1: roles[rest[1]]='کارآگاه'
        for x in rest[2:]: roles[x]='شهروند'
        room['roles']=roles; room['alive']=set(ids); room['state']='night'; room['round']=1; room['night']={'mafia':{},'doctor':{},'detective':{}}; room['votes']={}
        for x,role in roles.items():
            try: await context.bot.send_message(x,f'♟️ <b>نقش مخفی تو</b>\n\nسناریو: <b>{MAFIA_PRO_SCENARIO}</b>\n🎭 نقش: <b>{role}</b>\n\n{MAFIA_PRO_ROLES[role]}',parse_mode='HTML')
            except TelegramError: pass
            await mafia_private_action_keyboard(q, context, cid, x)
        await q.edit_message_text('🌙 <b>شب اول شروع شد</b>\n\nنقش‌های مافیا، پزشک و کارآگاه اقدامات خود را از پیام خصوصی انجام می‌دهند. سپس میزبان می‌تواند «پایان شب» را بزند.',parse_mode='HTML',reply_markup=keyboard([[btn('🌙 پایان شب',f'mf9:{cid}:endnight')],[btn('👥 بازیکنان زنده',f'mf9:{cid}:alive')]])); return
    if action=='alive':
        names='\n'.join(f'• {safe_text(room["players"].get(x,"کاربر"),40)}' for x in room['alive']) or '—'
        await q.edit_message_text('👥 <b>بازیکنان زنده</b>\n\n'+names,parse_mode='HTML',reply_markup=keyboard([[btn('🔙 بازی',f'mf9:{cid}:backgame')]])); return
    if action=='backgame':
        await q.edit_message_text(f'♟️ <b>دور {room["round"]}</b>\nوضعیت: {"🌙 شب" if room["state"]=="night" else "☀️ روز"}',parse_mode='HTML',reply_markup=keyboard([[btn('👥 زنده‌ها',f'mf9:{cid}:alive')]])); return
    if action=='endnight':
        if uid!=room['host']: await q.answer('فقط میزبان می‌تواند شب را تمام کند.',show_alert=True); return
        if room['state']!='night': await q.answer('الان شب نیست.',show_alert=True); return
        macts=room['night']['mafia']; dacts=room['night']['doctor']
        target=None
        if macts:
            counts=defaultdict(int)
            for t in macts.values():
                if t in room['alive']: counts[t]+=1
            if counts: target=max(counts,key=counts.get)
        protected=next(iter(dacts.values()),None) if dacts else None
        if target and target!=protected:
            room['alive'].discard(target)
            out=room['players'].get(target,'بازیکن')
            await context.bot.send_message(cid,f'🌙 نتیجه شب: {safe_text(out,50)} از بازی خارج شد.\nنقش: <b>{room["roles"].get(target,"شهروند")}</b>',parse_mode='HTML')
        else:
            await context.bot.send_message(cid,'🌙 نتیجه شب: امشب کسی از بازی خارج نشد. 🛡️',parse_mode='HTML')
        win=mafia_pro_check(room)
        if win:
            room['state']='ended'; await q.edit_message_text(f'🏆 <b>بازی تمام شد!</b>\n\nبرنده: <b>{win}</b>\n\nبرای شروع بازی جدید دوباره «مافیا» را بزن.',parse_mode='HTML',reply_markup=keyboard([[btn('♟️ مافیا',f'mf9:{cid}:reset')]])); return
        room['state']='day'; room['votes']={}; await q.edit_message_text(f'☀️ <b>روز {room["round"]}</b>\n\nحالا گفت‌وگو کنید و بعد رأی‌گیری را شروع کنید.',parse_mode='HTML',reply_markup=keyboard([[btn('🗳️ شروع رأی‌گیری',f'mf9:{cid}:vote')]])); return
    if action=='vote':
        if room['state']!='day': await q.answer('الان زمان رأی‌گیری روز نیست.',show_alert=True); return
        rows=[]
        for x in room['alive']:
            if x!=uid: rows.append([btn(safe_text(room['players'].get(x,'کاربر'),24),f'mf9:{cid}:v:{x}')])
        await q.edit_message_text(f'🗳️ <b>رأی‌گیری روز {room["round"]}</b>\n\nبه کسی رأی بده که فکر می‌کنی عضو تیم مافیاست.',parse_mode='HTML',reply_markup=keyboard(rows)); return
    if action.startswith('v:'):
        if uid not in room['alive']: await q.answer('تو دیگر در بازی نیستی.',show_alert=True); return
        target=int(action.split(':',1)[1])
        if target not in room['alive'] or target==uid: await q.answer('هدف نامعتبر است.',show_alert=True); return
        room['votes'][uid]=target; await q.answer(f'رأی ثبت شد: {len(room["votes"])}/{len(room["alive"])}')
        if len(room['votes'])<len(room['alive']): return
        counts=defaultdict(int)
        for t in room['votes'].values(): counts[t]+=1
        mx=max(counts.values()); tops=[x for x,v in counts.items() if v==mx]
        room['votes']={}
        if len(tops)>1:
            await q.edit_message_text('🤝 رأی مساوی شد؛ هیچ‌کس از بازی خارج نشد.\n\nشب بعد شروع می‌شود.',parse_mode='HTML',reply_markup=keyboard([[btn('🌙 شروع شب',f'mf9:{cid}:night')]])); return
        out=tops[0]; room['alive'].discard(out); name=room['players'].get(out,'بازیکن'); role=room['roles'].get(out,'شهروند')
        win=mafia_pro_check(room)
        if win:
            room['state']='ended'; await q.edit_message_text(f'🏆 <b>بازی تمام شد!</b>\n\n👤 {safe_text(name,50)} از بازی خارج شد.\n🎭 نقش: <b>{role}</b>\n\nبرنده: <b>{win}</b>',parse_mode='HTML',reply_markup=keyboard([[btn('♟️ بازی جدید',f'mf9:{cid}:reset')]])); return
        room['round']+=1; room['state']='night'; room['night']={'mafia':{},'doctor':{},'detective':{}}
        await q.edit_message_text(f'🌙 <b>شب {room["round"]} شروع شد</b>\n\nنقش‌های ویژه اقدامات خود را در پیوی انجام دهند.',parse_mode='HTML',reply_markup=keyboard([[btn('🌙 پایان شب',f'mf9:{cid}:endnight')]])); return
    if action=='night':
        room['state']='night'; room['night']={'mafia':{},'doctor':{},'detective':{}}; await q.edit_message_text('🌙 شب شروع شد. نقش‌های ویژه اقدامات خود را انجام دهند.',parse_mode='HTML',reply_markup=keyboard([[btn('🌙 پایان شب',f'mf9:{cid}:endnight')]])); return
    if action=='reset':
        MAFIA_PRO.pop(cid,None); return await mafia_start_menu(type('U',(),{'effective_chat':q.message.chat,'effective_user':q.from_user,'effective_message':q.message})(),context)
    await q.answer('گزینه مافیا نامعتبر است.',show_alert=True)

async def mafia2_new_callback(q,context):
    return await mafia_start_menu(type('U',(),{'effective_chat':q.message.chat,'effective_user':q.from_user,'effective_message':q.message})(),context)

# Private role action helper: players can send text commands in PV.
async def mafia_private_action(update, context):
    if not update.effective_chat or update.effective_chat.type!='private': return False
    uid=update.effective_user.id; t=normalize(update.effective_message.text or '')
    for cid,room in list(MAFIA_PRO.items()):
        if uid not in room.get('alive',set()) or room.get('state')!='night': continue
        role=room['roles'].get(uid)
        if role not in {'مافیا','پزشک','کارآگاه'}: continue
        m=re.match(r'^(?:هدف|انتخاب|بررسی)\s+(\d+)$',t)
        if not m: continue
        target=int(m.group(1))
        if target not in room['alive'] or target==uid: await update.effective_message.reply_text('❌ شناسه بازیکن معتبر نیست.'); return True
        key={'مافیا':'mafia','پزشک':'doctor','کارآگاه':'detective'}[role]
        room['night'][key][uid]=target
        if role=='کارآگاه':
            rr=room['roles'].get(target,'شهروند'); await update.effective_message.reply_text(f'🔎 نتیجه بررسی: <b>{"عضو تیم مافیا" if rr=="مافیا" else "عضو تیم شهر"}</b>',parse_mode='HTML')
        else: await update.effective_message.reply_text('✅ انتخابت برای این شب ثبت شد.')
        return True
    return False

async def message_router_v9(update, context):
    # Owner commands and VIP/Mafia commands are handled before the general router.
    if await owner_control_text(update,context): return
    msg=update.effective_message; t=normalize(msg.text or '') if msg and msg.text else ''
    if msg and update.effective_chat:
        if t in {'مافیا','شروع مافیا','بازی مافیا','اتاق مافیا'}:
            fake=type('U',(),{'effective_chat':update.effective_chat,'effective_user':update.effective_user,'effective_message':msg})()
            await mafia_start_menu(fake,context); return
        if t in {'vip','وی آی پی','وضعیت vip','وضعیت وی آی پی','امکانات vip'} and update.effective_chat.type!='private':
            q=type('Q',(),{'from_user':update.effective_user,'message':msg,'edit_message_text':msg.reply_text,'answer':lambda *a,**k:None})()
            await vip_panel(q,context); return
        if update.effective_chat.type=='private':
            if await mafia_private_action(update,context): return
    return await message_router_v8(update,context)

async def callback_router_v9(update, context):
    q=update.callback_query
    if not q: return
    data=q.data or ''
    try: await q.answer()
    except TelegramError: pass
    if data.startswith('mf9:'):
        await mafia2_callback(q,context); return
    if data.startswith('vip9toggle:'):
        await vip9_toggle_callback(q,context); return
    if data.startswith('vip9:'):
        await vip9_callback(q,context); return
    if data.startswith('oc:'):
        await owner_control_callback(q,context); return
    if data.startswith('oct:'):
        await owner_control_action_callback(q,context); return
    await v8_callback_router(update,context)

async def owner_control_update_callback(update, context):
    q=update.callback_query
    if q: await owner_control_callback(q,context)

async def owner_control_action_update_callback(update, context):
    q=update.callback_query
    if q: await owner_control_action_callback(q,context)

async def post_init_v9(application):
    await post_init_v8(application)
    await ensure_v9_schema()
    try:
        await application.bot.set_my_commands([
            ('start','شروع'),('help','راهنما'),('panel','پنل'),('features','قابلیت‌ها'),
            ('rules','قوانین'),('stats','آمار'),('mafia','مافیا')
        ])
    except TelegramError: pass


def build_application(token:str)->Application:
    app=ApplicationBuilder().token(token).post_init(post_init_v9).post_shutdown(post_shutdown).build()
    app.add_handler(CommandHandler('start',start_v8))
    app.add_handler(CommandHandler('help',cmd_help)); app.add_handler(CommandHandler('panel',cmd_panel)); app.add_handler(CommandHandler('adminpanel',cmd_adminpanel))
    app.add_handler(CommandHandler('owner',owner_panel_v6)); app.add_handler(CommandHandler('features',cmd_features)); app.add_handler(CommandHandler('rules',rules_command)); app.add_handler(CommandHandler('setrules',set_rules))
    app.add_handler(CommandHandler('welcome',set_welcome)); app.add_handler(CommandHandler('togglewelcome',toggle_welcome)); app.add_handler(CommandHandler('goodbye',set_goodbye)); app.add_handler(CommandHandler('togglegoodbye',toggle_goodbye)); app.add_handler(CommandHandler('forcejoin',forcejoin_v4)); app.add_handler(CommandHandler('stats',stats_v4_command))
    app.add_handler(CommandHandler('cleanup',lambda u,c:cleanup_v4(u,c,500))); app.add_handler(CommandHandler('warn',lambda u,c:moderation_action(u,c,'warn'))); app.add_handler(CommandHandler('unwarn',lambda u,c:moderation_action(u,c,'unwarn')))
    app.add_handler(CommandHandler('mute',lambda u,c:mute_command_v6(u,c))); app.add_handler(CommandHandler('unmute',lambda u,c:moderation_v4(u,c,'unmute'))); app.add_handler(CommandHandler('ban',lambda u,c:moderation_v4(u,c,'ban'))); app.add_handler(CommandHandler('unban',lambda u,c:moderation_v4(u,c,'unban')))
    app.add_handler(CommandHandler('mafia',lambda u,c:mafia_start_menu(u,c)))
    app.add_handler(ChatMemberHandler(member_update_v6, ChatMemberHandler.CHAT_MEMBER))
    app.add_handler(CallbackQueryHandler(callback_router_v9))
    if MessageReactionHandler is not None: app.add_handler(MessageReactionHandler(reaction_handler))
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS,service_members_v4)); app.add_handler(MessageHandler(filters.StatusUpdate.LEFT_CHAT_MEMBER,service_members_v4)); app.add_handler(MessageHandler(filters.LOCATION,location_v4))
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,message_router_v9)); app.add_error_handler(error_handler)
    return app


