OWNER_MENU_ORDER=['dog','games','mafia','tools','factory','friends','competition','profile','missions','help','settings','admin']

async def load_owner_menu_order():
    global OWNER_MENU_ORDER
    row=await DBX.one('SELECT value FROM owner_config WHERE key="menu_order"')
    if row:
        try:
            val=json.loads(row['value'])
            if isinstance(val,list) and val: OWNER_MENU_ORDER=[str(x) for x in val]
        except Exception: pass

async def save_owner_menu_order():
    await owner_cfg_set('menu_order',json.dumps(OWNER_MENU_ORDER,ensure_ascii=False))

def v9_menu_label(key, default):
    return owner_label(key,default)

def v9_home_keyboard(uid, admin=False):
    defaults={
        'dog':(v9_menu_label('dog','🐾 هاپویی'),user_cb(uid,'dog')),
        'games':(v9_menu_label('games','🎮 ۵۰ بازی'),user_cb(uid,'games')),
        'mafia':(v9_menu_label('mafia','♟️ مافیا'),f'mfrooms:{uid}:home'),
        'tools':(v9_menu_label('tools','🧰 ابزارها'),user_cb(uid,'tools')),
        'factory':(v9_menu_label('factory','🏭 کارخانه'),f'v8factory:{uid}:home'),
        'friends':(v9_menu_label('friends','🤝 دوستی'),f'v8friend:{uid}:home'),
        'competition':(v9_menu_label('competition','🏆 رقابت'),f'v8comp:{uid}:home'),
        'profile':('👤 پروفایل من',user_cb(uid,'profile')),
        'missions':('🎁 مأموریت‌ها',user_cb(uid,'missions')),
        'help':('📚 راهنما',user_cb(uid,'help')),
        'settings':('⚙️ تنظیمات من',f'v8settings:{uid}:home'),
        'admin':('🛡 پنل مدیریت',admin_cb(uid,'home')),
    }
    items=[]
    for key in OWNER_MENU_ORDER:
        if key=='admin' and not admin: continue
        if not owner_feature_enabled(key): continue
        if key in defaults:
            label, data = defaults[key]
            items.append(btn(label, data))
    rows=[items[i:i+2] for i in range(0,len(items),2)]
    return keyboard(rows)

