async def send_group_panel(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.effective_chat or not update.effective_user or not update.effective_message: return
    await DBX.ensure_chat(update.effective_chat); await DBX.ensure_user(update.effective_user)
    uid=update.effective_user.id; u=await DBX.get_user(uid); admin=await is_admin(update,uid)
    default=(f"🐾 <b>پنل کاربری بیل بیلک</b>\n\n👤 {mention_html(update.effective_user)}\n"
             f"🐕 هاپو: <b>{safe_text(u['dog_name'])}</b> | سطح {u['dog_level']}\n"
             f"⭐ سطح کاربر: <b>{u['level']}</b> | XP: <b>{u['xp']}</b>\n🦴 استخوان: <b>{u['bones']}</b>\n\n🔐 این پنل فقط برای خودت قابل استفاده است.")
    text=owner_message('group_panel',default)
    if admin and 'پنل مدیریت' not in text: text += '\n🛡 پنل مدیریتت جداست و فقط خودت می‌توانی دکمه‌هایش را اجرا کنی.'
    await update.effective_message.reply_text(text,parse_mode='HTML',reply_markup=v9_home_keyboard(uid,admin))

async def owner_control_text(update, context):
    msg=update.effective_message; uid=update.effective_user.id if update.effective_user else 0
    if not msg or not owner_is_allowed(uid): return False
    t=normalize(msg.text or '')
    if t in {'کنترل ربات','مرکز کنترل','کنترل کامل'}:
        await msg.reply_text('👑 مرکز کنترل را از /owner باز کن و دکمه «کنترل کامل ربات» را بزن.'); return True
    if t.startswith('جابه‌جایی ') or t.startswith('جابجایی '):
        p=t.replace('جابه‌جایی ','',1).replace('جابجایی ','',1).split()
        if len(p)>=2 and p[0] in OWNER_MENU_ORDER and p[1] in {'بالا','پایین'}:
            i=OWNER_MENU_ORDER.index(p[0]); j=max(0,i-1) if p[1]=='بالا' else min(len(OWNER_MENU_ORDER)-1,i+1)
            OWNER_MENU_ORDER[i],OWNER_MENU_ORDER[j]=OWNER_MENU_ORDER[j],OWNER_MENU_ORDER[i]
            await save_owner_menu_order(); await msg.reply_text('↕️ ترتیب منو ذخیره شد.'); return True
    if t.startswith('حذف قابلیت '):
        key=owner_feature_key(t.replace('حذف قابلیت ','',1).strip()); OWNER_DISABLED.add(key); await owner_cfg_set('disabled:'+key,'1'); await msg.reply_text(f'🔴 قابلیت «{key}» خاموش شد.'); return True
    if t.startswith('فعال قابلیت '):
        key=owner_feature_key(t.replace('فعال قابلیت ','',1).strip()); OWNER_DISABLED.discard(key); await owner_cfg_del('disabled:'+key); await msg.reply_text(f'🟢 قابلیت «{key}» روشن شد.'); return True
    if t.startswith('نام دکمه '):
        p=t.split(' ',3)
        if len(p)>=4:
            key=owner_feature_key(p[2]); val=p[3].strip(); OWNER_BUTTON_LABELS[key]=val; await owner_cfg_set('label:'+key,val); await msg.reply_text('🔘 نام دکمه ذخیره شد.'); return True
    if t.startswith('حذف نام دکمه '):
        key=owner_feature_key(t.replace('حذف نام دکمه ','',1).strip()); OWNER_BUTTON_LABELS.pop(key,None); await owner_cfg_del('label:'+key); await msg.reply_text('🔘 نام سفارشی حذف شد.'); return True
    if t.startswith('پیام سفارشی '):
        p=t.split(' ',3)
        if len(p)>=4:
            key=owner_feature_key(p[2]); val=p[3].strip(); OWNER_CUSTOM_MESSAGES[key]=val; await owner_cfg_set('msg:'+key,val); await msg.reply_text('💬 پیام سفارشی ذخیره شد.'); return True
    if t.startswith('حذف پیام سفارشی '):
        key=owner_feature_key(t.replace('حذف پیام سفارشی ','',1).strip()); OWNER_CUSTOM_MESSAGES.pop(key,None); await owner_cfg_del('msg:'+key); await msg.reply_text('💬 پیام سفارشی حذف شد.'); return True
    if t.startswith('دستور جدید '):
        p=t.split(' ',3)
        if len(p)>=4:
            alias=normalize(p[2]); target=normalize(p[3]); OWNER_COMMAND_ALIASES[alias]=target; await owner_cfg_set('alias:'+alias,target); await msg.reply_text('⌨️ دستور سفارشی ثبت شد.'); return True
    if t.startswith('حذف دستور '):
        alias=normalize(t.replace('حذف دستور ','',1).strip()); OWNER_COMMAND_ALIASES.pop(alias,None); await owner_cfg_del('alias:'+alias); await msg.reply_text('⌨️ دستور حذف شد.'); return True
    return False

async def mafia_private_action_keyboard(q, context, cid, uid):
    room=MAFIA_PRO.get(cid)
    if not room or uid not in room.get('alive',set()) or room.get('state')!='night': return
    role=room['roles'].get(uid)
    if role not in {'مافیا','پزشک','کارآگاه'}: return
    targets=[x for x in room['alive'] if x!=uid]
    buttons=[[btn(safe_text(room['players'].get(x,'کاربر'),24),f'mf9act:{cid}:{x}')] for x in targets]
    if buttons:
        await context.bot.send_message(uid,'🌙 <b>انتخاب شب</b>\n\nیک نفر را انتخاب کن:',parse_mode='HTML',reply_markup=keyboard(buttons))

async def mafia_private_action_callback(q,context):
    p=(q.data or '').split(':')
    if len(p)!=3 or p[0]!='mf9act': return
    cid=int(p[1]); target=int(p[2]); uid=q.from_user.id; room=MAFIA_PRO.get(cid)
    if not room or room.get('state')!='night' or uid not in room.get('alive',set()): await q.answer('این اقدام دیگر فعال نیست.',show_alert=True); return
    role=room['roles'].get(uid)
    if role not in {'مافیا','پزشک','کارآگاه'} or target not in room['alive'] or target==uid: await q.answer('هدف نامعتبر است.',show_alert=True); return
    key={'مافیا':'mafia','پزشک':'doctor','کارآگاه':'detective'}[role]; room['night'][key][uid]=target
    if role=='کارآگاه':
        rr=room['roles'].get(target,'شهروند'); await q.answer('بررسی انجام شد.',show_alert=True)
        await q.message.reply_text(f'🔎 نتیجه: <b>{"عضو تیم مافیا" if rr=="مافیا" else "عضو تیم شهر"}</b>',parse_mode='HTML')
    else: await q.answer('انتخاب شب ثبت شد.',show_alert=True)

# Rebuild post-init to restore persisted menu order.
async def post_init_v9(application):
    await post_init_v8(application); await ensure_v9_schema(); await load_owner_menu_order()
    try:
        await _music_init_voice_engine(getattr(application.bot, 'token', ''))
    except Exception as exc:
        log.warning('Music VC initialization skipped: %s', exc)
    try: await application.bot.set_my_commands([('start','شروع'),('help','راهنما'),('panel','پنل'),('features','قابلیت‌ها'),('rules','قوانین'),('stats','آمار'),('mafia','مافیا')])
    except TelegramError: pass

async def callback_router_v10(update, context):
    q=update.callback_query
    if not q: return
    data=q.data or ''
    try: await q.answer()
    except TelegramError: pass
    if data.startswith('mf9act:'): await mafia_private_action_callback(q,context); return
    await callback_router_v9(update,context)

def build_application(token:str)->Application:
    app=ApplicationBuilder().token(token).post_init(post_init_v9).post_shutdown(post_shutdown).build()
    for name,fn in [
        ('start',start_v8),('help',cmd_help),('panel',cmd_panel),('adminpanel',cmd_adminpanel),('owner',owner_panel_v6),
        ('features',cmd_features),('rules',rules_command),('setrules',set_rules),('welcome',set_welcome),('togglewelcome',toggle_welcome),
        ('goodbye',set_goodbye),('togglegoodbye',toggle_goodbye),('forcejoin',forcejoin_v4),('stats',stats_v4_command)
    ]: app.add_handler(CommandHandler(name,fn))
    app.add_handler(CommandHandler('cleanup',lambda u,c:cleanup_v4(u,c,500))); app.add_handler(CommandHandler('warn',lambda u,c:moderation_action(u,c,'warn'))); app.add_handler(CommandHandler('unwarn',lambda u,c:moderation_action(u,c,'unwarn')))
    app.add_handler(CommandHandler('mute',lambda u,c:mute_command_v6(u,c))); app.add_handler(CommandHandler('unmute',lambda u,c:moderation_v4(u,c,'unmute'))); app.add_handler(CommandHandler('ban',lambda u,c:moderation_v4(u,c,'ban'))); app.add_handler(CommandHandler('unban',lambda u,c:moderation_v4(u,c,'unban')))
    app.add_handler(CommandHandler('mafia',lambda u,c:mafia_start_menu(u,c)))
    app.add_handler(ChatMemberHandler(member_update_v6,ChatMemberHandler.CHAT_MEMBER))
    app.add_handler(CallbackQueryHandler(callback_router_v10))
    if MessageReactionHandler is not None: app.add_handler(MessageReactionHandler(reaction_handler))
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS,service_members_v4)); app.add_handler(MessageHandler(filters.StatusUpdate.LEFT_CHAT_MEMBER,service_members_v4)); app.add_handler(MessageHandler(filters.LOCATION,location_v4))
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,message_router_v9)); app.add_error_handler(error_handler)
    return app


