# Extra per-room state fields are added lazily so old rooms do not break.
def mafia9_defaults(room):
    room.setdefault('role_setup', list(MAFIA_DEFAULTS.get(len(room.get('players',{})), [])))
    room.setdefault('phase_started', 0)
    room.setdefault('phase_seconds', 0)
    room.setdefault('night', {'mafia':{},'doctor':{},'detective':{},'bodyguard':{},'consigliere':{},'framer':{},'silencer':{},'blocker':{}})
    room.setdefault('mafia_chat', {})
    room.setdefault('silenced', set())
    room.setdefault('blocked', set())
    room.setdefault('jester_winner', None)
    room.setdefault('last_night_result', None)
    room.setdefault('day_message_id', None)
    return room

