def mafia9_role_summary(room):
    counts=defaultdict(int)
    for r in room.get('role_setup',[]): counts[r]+=1
    lines=[]
    for r,n in counts.items():
        if n: lines.append(f'• {r}: <b>{n}</b> — {MAFIA_ROLE_INFO.get(r,"—")}')
    return '\n'.join(lines) or 'هنوز نقشی انتخاب نشده.'

async def mafia9_private_setup(q,context,cid):
    room=MAFIA_PRO.get(cid)
    if not room or q.from_user.id!=room.get('host'):
        await q.answer('فقط میزبان بازی می‌تواند تنظیمات نقش را تغییر دهد.',show_alert=True); return
    await q.answer()
    if not await mafia9_has_started(q.from_user.id):
        await q.answer('اول /start ربات را در پیوی اجرا کن.',show_alert=True); return
    mafia9_defaults(room)
    text=(f'⚙️ <b>تنظیم نقش‌های مافیا</b>\n\nاتاق: {cid}\n'
          f'تعداد بازیکنان فعلی: <b>{len(room["players"])}</b>\n\n{mafia9_role_summary(room)}\n\n'
          'این پنل فقط برای میزبان است. پس از ذخیره، هنگام شروع بازی نقش‌ها به‌صورت خصوصی برای بازیکنان ارسال می‌شوند.')
    await context.bot.send_message(q.from_user.id,text,parse_mode='HTML',reply_markup=mafia9_host_setup_keyboard(cid))
    await q.answer('پنل تنظیم نقش در پیوی برایت ارسال شد.')

async def mafia9_setup_callback(q,context):
    p=(q.data or '').split(':',3)
    if len(p)!=4 or p[0]!='mf9set': return False
    cid=int(p[1]); action=p[2]; role=p[3]; room=MAFIA_PRO.get(cid)
    if not room or q.from_user.id!=room.get('host'):
        await q.answer('فقط میزبان مجاز است.',show_alert=True); return True
    mafia9_defaults(room)
    setup=room['role_setup']
    if action=='inc' and len(setup)<len(room.get('players',{})):
        setup.append(role); await q.answer(f'نقش {role} اضافه شد.')
    elif action=='dec' and role in setup:
        setup.remove(role); await q.answer(f'یک {role} حذف شد.')
    elif action=='default':
        n=len(room.get('players',{})); room['role_setup']=list(MAFIA_DEFAULTS.get(n,[])); await q.answer('چیدمان پیشنهادی اعمال شد.')
    elif action=='clear':
        room['role_setup']=[]; await q.answer('نقش‌ها پاک شدند.')
    elif action=='save':
        if len(setup)!=len(room.get('players',{})):
            await q.answer('تعداد نقش‌ها باید دقیقاً برابر تعداد بازیکنان باشد.',show_alert=True); return True
        await q.answer('تنظیمات ذخیره شد.')
        await q.message.edit_text('💾 <b>تنظیم نقش‌ها ذخیره شد.</b>\n\n'+mafia9_role_summary(room),parse_mode='HTML',reply_markup=keyboard([[btn('🔙 بازگشت به مافیا',f'mf9:{cid}:back')]]))
        return True
    if q.message and q.message.chat.type=='private':
        await q.message.edit_text(f'⚙️ <b>تنظیم نقش‌ها</b>\n\nبازیکنان: <b>{len(room["players"])}</b>\n\n{mafia9_role_summary(room)}',parse_mode='HTML',reply_markup=mafia9_host_setup_keyboard(cid))
    return True

