async def mafia9_action_keyboard(cid,uid):
    room=MAFIA_PRO.get(cid)
    if not room: return None
    role=room['roles'].get(uid); alive=room['alive']
    if uid not in alive or room['state']!='night': return None
    targets=[x for x in alive if x!=uid]
    if role=='مافیا' or role=='پدرخوانده':
        return keyboard([[btn(safe_text(room['players'].get(x,'کاربر'),24),f'mf9act:{cid}:{x}')] for x in targets])
    if role in {'پزشک','محافظ','کارآگاه','مشاور مافیا','مسدودکننده','قاب‌ساز','ساکت‌کننده'}:
        return keyboard([[btn(safe_text(room['players'].get(x,'کاربر'),24),f'mf9act:{cid}:{x}')] for x in targets])
    return None

async def mafia9_private_action_callback(q,context):
    p=(q.data or '').split(':')
    if len(p)!=3 or p[0]!='mf9act': return False
    try: cid,target=int(p[1]),int(p[2])
    except: await q.answer('هدف نامعتبر است.',show_alert=True); return True
    room=MAFIA_PRO.get(cid); uid=q.from_user.id
    if not room or room.get('state')!='night' or uid not in room.get('alive',set()) or target not in room.get('alive',set()):
        await q.answer('این اقدام دیگر فعال نیست.',show_alert=True); return True
    role=room['roles'].get(uid)
    if role in {'مافیا','پدرخوانده'}: key='mafia'
    elif role=='پزشک': key='doctor'
    elif role=='محافظ': key='bodyguard'
    elif role=='کارآگاه': key='detective'
    elif role=='مشاور مافیا': key='consigliere'
    elif role=='قاب‌ساز': key='framer'
    elif role=='ساکت‌کننده': key='silencer'
    elif role=='مسدودکننده': key='blocker'
    else: await q.answer('این نقش اقدام شبانه ندارد.',show_alert=True); return True
    room['night'].setdefault(key,{})[uid]=target
    if role=='کارآگاه':
        result='عضو تیم مافیا' if MAFIA_ROLE_TEAM.get(room['roles'].get(target))=='mafia' else 'عضو تیم شهر'
        await q.answer('بررسی انجام شد.',show_alert=True); await q.message.reply_text('🔎 نتیجه بررسی: <b>'+result+'</b>',parse_mode='HTML')
    elif role=='مشاور مافیا':
        await q.answer('بررسی نقش ثبت شد.',show_alert=True); await q.message.reply_text('📋 نقش هدف: <b>'+safe_text(room['roles'].get(target,'شهروند'),40)+'</b>',parse_mode='HTML')
    else: await q.answer('انتخاب ثبت شد. ⏱️',show_alert=True)
    return True

async def mafia9_start_game(q,context,cid,room):
    ids=list(room['players'])
    if len(ids)<5 or len(ids)>12: await q.answer('بازی بین ۵ تا ۱۲ بازیکن است.',show_alert=True); return
    mafia9_defaults(room)
    setup=list(room.get('role_setup',[]))
    if len(setup)!=len(ids):
        setup=list(MAFIA_DEFAULTS.get(len(ids),[]))
    if len(setup)!=len(ids): await q.answer('برای این تعداد بازیکن چیدمان نقش آماده نیست.',show_alert=True); return
    random.shuffle(setup)
    random.shuffle(ids)
    room['roles']=dict(zip(ids,setup)); room['alive']=set(ids); room['state']='night'; room['round']=1
    room['night']={'mafia':{},'doctor':{},'detective':{},'bodyguard':{},'consigliere':{},'framer':{},'silencer':{},'blocker':{}}
    room['votes']={}; room['silenced']=set(); room['blocked']=set(); room['jester_winner']=None
    room['phase_started']=now_ts(); room['phase_seconds']=MAFIA_PHASE_SECONDS['night']
    for uid,role in room['roles'].items():
        try: await mafia9_send_role(uid,role,room,context)
        except TelegramError: pass
    await mafia9_send_mafia_room(room,context)
    # action buttons per player
    for uid in ids:
        kb=await mafia9_action_keyboard(cid,uid)
        if kb:
            try: await context.bot.send_message(uid,'🌙 <b>اقدام شب</b>\nهدف خودت را انتخاب کن:',parse_mode='HTML',reply_markup=kb)
            except TelegramError: pass
    await q.edit_message_text('🌙 <b>شب اول آغاز شد</b>\n\nنقش‌ها و اقدامات در پیوی انجام می‌شود.\n⏱️ پایان خودکار شب پس از ۹۰ ثانیه؛ میزبان هم می‌تواند زودتر پایان دهد.',parse_mode='HTML',reply_markup=keyboard([[btn('🌙 پایان شب',f'mf9:{cid}:endnight')],[btn('👥 بازیکنان زنده',f'mf9:{cid}:alive')]]))

async def mafia9_end_night(q,context,cid,room):
    if q.from_user.id!=room.get('host'): await q.answer('فقط میزبان.',show_alert=True); return
    if room.get('state')!='night': await q.answer('الان شب نیست.',show_alert=True); return
    n=room['night']; blocked_targets=set(n.get('blocker',{}).values());
    # blocked users cannot apply their action
    effective={k:{u:t for u,t in v.items() if u not in blocked_targets} for k,v in n.items()}
    mafia_votes=effective.get('mafia',{})
    counts=defaultdict(int)
    for t in mafia_votes.values():
        if t in room['alive']: counts[t]+=1
    target=max(counts,key=counts.get) if counts else None
    protect=set(effective.get('doctor',{}).values()) | set(effective.get('bodyguard',{}).values())
    # framer changes investigation result for this night
    framed=set(effective.get('framer',{}).values())
    silenced=set(effective.get('silencer',{}).values())
    room['silenced']=silenced
    if target and target not in protect:
        room['alive'].discard(target)
        room['last_night_result']=target
        await context.bot.send_message(cid,f'🌙 نتیجه شب: <b>{safe_text(room["players"].get(target,"بازیکن"),45)}</b> از بازی خارج شد.\n🎭 نقش: <b>{safe_text(room["roles"].get(target,"شهروند"),35)}</b>',parse_mode='HTML')
    else:
        room['last_night_result']=None
        await context.bot.send_message(cid,'🌙 نتیجه شب: امشب حذف شبانه‌ای رخ نداد. 🛡️',parse_mode='HTML')
    win=mafia_pro_check(room)
    if win:
        room['state']='ended'; await q.edit_message_text(f'🏆 <b>بازی تمام شد</b>\n\nبرنده: <b>{win}</b>',parse_mode='HTML',reply_markup=keyboard([[btn('♟️ بازی جدید',f'mf9:{cid}:reset')]])); return
    room['state']='day'; room['phase_started']=now_ts(); room['phase_seconds']=MAFIA_PHASE_SECONDS['day']; room['votes']={}
    await q.edit_message_text(f'☀️ <b>روز {room["round"]}</b>\n\nگفت‌وگو و تحلیل شروع شد.\n⏱️ زمان روز: ۱۸۰ ثانیه\n\nپس از گفت‌وگو، «شروع رأی‌گیری» را بزن.',parse_mode='HTML',reply_markup=keyboard([[btn('🗳️ شروع رأی‌گیری',f'mf9:{cid}:vote')]]))

