# Replace callback for Mafia while retaining all other bot callbacks.
_OLD_MAFIA2_CALLBACK=mafia2_callback
async def mafia2_callback(q,context):
    data=q.data or ''; p=data.split(':',2)
    if len(p)!=3 or p[0]!='mf9': return await _OLD_MAFIA2_CALLBACK(q,context)
    try: cid=int(p[1])
    except: await q.answer('اتاق نامعتبر است.',show_alert=True); return
    action=p[2]; uid=q.from_user.id; room=MAFIA_PRO.get(cid)
    if not room: await q.answer('اتاق پیدا نشد.',show_alert=True); return
    mafia9_defaults(room)
    if action=='setup':
        await mafia9_private_setup(q,context,cid); return
    if action=='start':
        if uid!=room.get('host'): await q.answer('فقط میزبان می‌تواند شروع کند.',show_alert=True); return
        if any(not await mafia9_has_started(x) for x in room['players']):
            missing=[room['players'].get(x,str(x)) for x in room['players'] if not await mafia9_has_started(x)]
            await q.answer('این بازیکنان هنوز /start را در پیوی نزده‌اند: '+', '.join(missing[:4]),show_alert=True); return
        await mafia9_start_game(q,context,cid,room); return
    if action=='endnight': await mafia9_end_night(q,context,cid,room); return
    if action=='help':
        text=('♟️ <b>راهنمای کامل مافیا</b>\n\n'
              '1) میزبان اتاق را می‌سازد و بازیکنان وارد می‌شوند.\n'
              '2) همه بازیکنان باید قبل از شروع، ربات را در پیوی /start کرده باشند.\n'
              '3) میزبان از پیوی خودش نقش‌ها را تنظیم می‌کند. تعداد نقش‌ها باید دقیقاً با تعداد بازیکنان برابر باشد.\n'
              '4) شروع بازی: ربات نقش هر نفر و توضیح همان نقش را خصوصی می‌فرستد.\n'
              '5) شب: مافیا در پیوی با هم مشورت می‌کنند؛ سپس انتخاب هدف را می‌فرستند. نقش‌های ویژه نیز اقدام خود را در پیوی انجام می‌دهند.\n'
              '6) پایان زمان شب: بیشترین انتخاب مافیا هدف می‌شود؛ محافظت پزشک/محافظ می‌تواند حذف شب را خنثی کند.\n'
              '7) روز: گفت‌وگو، تحلیل و رأی‌گیری. بازیکن با بیشترین رأی از بازی خارج می‌شود.\n'
              '8) جستر اگر با رأی روز حذف شود، به‌عنوان نقش مستقل برنده می‌شود.\n'
              '9) برد شهر: همه اعضای تیم مافیا از بازی خارج شوند. برد مافیا: تعداد مافیا به تعداد شهر برسد.\n\n'
              '🎭 <b>نقش‌ها</b>\n'+ '\n'.join(f'• <b>{r}</b>: {d}' for r,d in MAFIA_ROLE_INFO.items()))
        await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('🔙 مافیا',f'mf9:{cid}:back')]])); return
    # For join, enforce private start.
    if action=='join':
        if not await mafia9_has_started(uid):
            await q.answer('اول وارد پیوی ربات شو و /start را بزن؛ بعد برگرد و ورود را بزن.',show_alert=True); return
    await _OLD_MAFIA2_CALLBACK(q,context)

# Extend callback router for setup/private actions.
_OLD_CALLBACK_ROUTER_V10=callback_router_v10
async def callback_router_v10(update,context):
    q=update.callback_query
    if not q: return
    data=q.data or ''
    if data.startswith('mf9set:'):
        await mafia9_setup_callback(q,context); return
    if data.startswith('mf9act:'):
        await mafia9_private_action_callback(q,context); return
    if data.startswith('mf9:'):
        await mafia2_callback(q,context); return
    await _OLD_CALLBACK_ROUTER_V10(update,context)

# ---------- Time / country / live sports ----------
async def http_json(url,timeout=12):
    def _get():
        req=urllib.request.Request(url,headers={'User-Agent':'BilBilak/2.0'})
        with urllib.request.urlopen(req,timeout=timeout) as r:
            return json.loads(r.read().decode('utf-8','ignore'))
    try: return await asyncio.to_thread(_get)
    except Exception as e:
        log.warning('HTTP API error %s: %s',url,e); return None

async def world_time(zone):
    z=quote_plus(zone.strip())
    data=await http_json(f'https://worldtimeapi.org/api/timezone/{z}')
    if not data: return None
    return data

async def country_info(name):
    q=quote_plus(name.strip())
    return await http_json(f'https://restcountries.com/v3.1/name/{q}?fields=name,capital,region,subregion,population,currencies,languages,timezones,flags')

ESPN_LEAGUES={
    'فوتبال':'soccer/eng.1','پریمیرلیگ':'soccer/eng.1','لالیگا':'soccer/esp.1','لیگ قهرمانان':'soccer/uefa.champions',
    'nba':'basketball/nba','بسکتبال':'basketball/nba','nfl':'football/nfl','فوتبال آمریکایی':'football/nfl','mlb':'baseball/mlb','nhl':'hockey/nhl'
}
async def live_scores(league='فوتبال'):
    path=ESPN_LEAGUES.get(league.lower(),ESPN_LEAGUES['فوتبال'])
    data=await http_json(f'https://site.api.espn.com/apis/site/v2/sports/{path}/scoreboard')
    return data

def format_score_events(data):
    events=(data or {}).get('events',[]); lines=[]
    for e in events:
        comp=((e.get('competitions') or [{}])[0]); status=((e.get('status') or {}).get('type') or {}).get('shortDetail','')
        teams=[]
        for c in comp.get('competitors',[]): teams.append(f"{c.get('team',{}).get('displayName','?')} <b>{c.get('score','-')}</b>")
        if teams: lines.append('⚽ '+' — '.join(teams)+f'\n   ⏱️ {safe_text(status,80)}')
    return '\n\n'.join(lines)

async def ultimate_tools_router(update,context):
    msg=update.effective_message
    if not msg or not update.effective_user: return False
    text=(msg.text or '').strip(); low=text.lower()
    # Bil Bilak date/time card: Persian (Jalali) + Gregorian + exact time.
    if low in {'تاریخ','تاریخ امروز','امروز چه تاریخی است','امروز چندمه'}:
        now=datetime.now()
        jalali='—'
        weekday='—'
        try:
            import jdatetime
            j=jdatetime.datetime.fromgregorian(datetime=now)
            jalali=j.strftime('%Y/%m/%d')
            weekday=j.strftime('%A')
        except Exception:
            jalali='—'
        text_date=(
            '📅 <b>تاریخ / ساعت بیل بیلک</b>\n\n'
            '〰️〰️〰️〰️〰️〰️〰️\n\n'
            f'📆 تاریخ شمسی: <b>{jalali}</b>\n'
            f'📅 تاریخ میلادی: <b>{now.strftime("%Y/%m/%d")}</b>\n'
            f'📌 روز هفته: <b>{weekday}</b>\n'
            f'🕐 ساعت: <b>{now.strftime("%H:%M:%S")}</b>\n\n'
            '〰️〰️〰️〰️〰️〰️〰️'
        )
        await msg.reply_text(text_date,parse_mode='HTML'); return True
    # World time
    if low.startswith('ساعت کشور ') or low.startswith('زمان کشور '):
        name=text.split(' ',2)[2].strip(); info=await country_info(name)
        if not info: await msg.reply_text('❌ کشور پیدا نشد.'); return True
        arr=info if isinstance(info,list) else [info]; c=arr[0]; zones=c.get('timezones') or []
        lines=[f'🌍 <b>{safe_text(c.get("name",{}).get("common",name),50)}</b>']
        for z in zones[:12]:
            t=await world_time(z)
            if t: lines.append(f'🕒 {z} → <b>{safe_text(t.get("datetime","")[:19],30)}</b>')
        await msg.reply_text('\n'.join(lines),parse_mode='HTML'); return True
    if low.startswith('کشور ') or low.startswith('اطلاعات کشور '):
        name=text.split(' ',1)[1] if low.startswith('کشور ') else text.split(' ',2)[2]
        info=await country_info(name)
        if not info: await msg.reply_text('❌ اطلاعات کشور پیدا نشد.'); return True
        c=(info[0] if isinstance(info,list) else info); cur=', '.join((c.get('currencies') or {}).keys()) or '—'; langs=', '.join((c.get('languages') or {}).values()) or '—'
        await msg.reply_text(f'🌍 <b>{safe_text(c.get("name",{}).get("common",name),60)}</b>\n🏛 پایتخت: {safe_text(", ".join(c.get("capital") or []),60)}\n🗺 منطقه: {safe_text(c.get("region","—"),40)}\n👥 جمعیت: {c.get("population","—"):,}\n💱 ارز: {cur}\n🗣 زبان‌ها: {safe_text(langs,100)}\n🕒 منطقه‌های زمانی: {safe_text(", ".join(c.get("timezones") or []),180)}',parse_mode='HTML'); return True
    if low.startswith('ساعت ') or low.startswith('زمان '):
        zone=text.split(' ',1)[1].strip().replace(' ','_')
        # Common Persian city aliases
        aliases={'تهران':'Asia/Tehran','برلین':'Europe/Berlin','لندن':'Europe/London','پاریس':'Europe/Paris','دبی':'Asia/Dubai','استانبول':'Europe/Istanbul','نیویورک':'America/New_York','لس آنجلس':'America/Los_Angeles','توکیو':'Asia/Tokyo'}
        z=aliases.get(zone,zone)
        t=await world_time(z)
        if not t: await msg.reply_text('❌ منطقه زمانی پیدا نشد. مثال: ساعت Asia/Tehran',parse_mode='HTML'); return True
        await msg.reply_text(f'🕒 <b>{safe_text(t.get("timezone",z),80)}</b>\n📅 {safe_text(t.get("datetime","")[:19],40)}\n📆 روز سال: {t.get("day_of_year","—")}\n⏱ هفته: {t.get("week_number","—")}\n☀️ UTC: {safe_text(t.get("utc_datetime","")[:19],40)}',parse_mode='HTML'); return True
    if low.startswith('فوتبال زنده') or low in {'ورزش زنده','نتیجه زنده','نتایج زنده'}:
        league='فوتبال'; parts=text.split(' ',2); 
        if len(parts)>=3: league=parts[2].strip()
        data=await live_scores(league); out=format_score_events(data)
        await msg.reply_text(f'📡 <b>نتایج زنده — {safe_text(league,40)}</b>\n\n{out or "در حال حاضر رویداد زنده‌ای در این فید پیدا نشد."}',parse_mode='HTML'); return True
    if low.startswith('بسکتبال زنده'):
        data=await live_scores('بسکتبال'); out=format_score_events(data); await msg.reply_text('🏀 <b>بسکتبال زنده</b>\n\n'+(out or 'بازی زنده‌ای پیدا نشد.'),parse_mode='HTML'); return True
    if low.startswith('ابزارها') or low=='ابزار':
        await msg.reply_text('🧰 <b>ابزارهای جدید</b>\n\n🕒 ساعت کشور/منطقه\n🌍 اطلاعات کشور\n⚽ نتایج زنده فوتبال\n🏀 بسکتبال زنده\n🎙 ویس به متن (با نصب SpeechRecognition)\n🖼 عکس به متن (با نصب pytesseract)\n📥 دانلود رسانه با ریپلای «دانلود»',parse_mode='HTML'); return True
    # Simple calculator upgrade
    if low.startswith('محاسبه '):
        expr=text[8:].strip()
        if re.fullmatch(r'[0-9+\-*/().% ^]+',expr):
            try: result=eval(expr.replace('^','**'),{'__builtins__':{}},{}); await msg.reply_text(f'🧮 {safe_text(expr,100)} = <b>{result}</b>',parse_mode='HTML')
            except: await msg.reply_text('❌ عبارت قابل محاسبه نیست.')
        else: await msg.reply_text('❌ فقط عبارت ریاضی ساده مجاز است.')
        return True
    # Download a replied Telegram media to a document.
    if low in {'دانلود','دانلود فایل','ذخیره فایل'} and msg.reply_to_message:
        r=msg.reply_to_message
        obj = r.document or r.video or r.audio or r.voice or (r.photo[-1] if r.photo else None)
        if not obj: await msg.reply_text('❌ روی فایل/ویدیو/صدا/عکس ریپلای کن.'); return True
        try:
            tgfile=await context.bot.get_file(obj.file_id); path=os.path.join('/tmp',f'bilbilak_{obj.file_id}.bin'); await tgfile.download_to_drive(path)
            await msg.reply_document(document=open(path,'rb'),caption='📥 فایل آماده شد.')
            try: os.remove(path)
            except: pass
        except Exception as e: await msg.reply_text('❌ دانلود انجام نشد.'); log.warning('download tool: %s',e)
        return True
    return False

# Mafia private relay: the bot can relay team discussion privately.
async def mafia9_relay_router(update,context):
    msg=update.effective_message
    if not msg or update.effective_chat.type!='private' or not msg.text: return False
    t=msg.text.strip()
    if not (t.startswith('مشورت مافیا ') or t.startswith('مچت مافیا ')): return False
    body=t.split(' ',2)[2].strip()
    if not body: await msg.reply_text('مثال: مشورت مافیا به نظرم بازیکن ۳ مشکوک است',parse_mode='HTML'); return True
    uid=update.effective_user.id
    for cid,room in MAFIA_PRO.items():
        if room.get('state')!='night' or uid not in room.get('alive',set()) or MAFIA_ROLE_TEAM.get(room.get('roles',{}).get(uid))!='mafia': continue
        targets=[x for x in room['alive'] if x!=uid and MAFIA_ROLE_TEAM.get(room.get('roles',{}).get(x))=='mafia']
        sender=safe_text(room['players'].get(uid,'مافیا'),35)
        for target in targets:
            try: await context.bot.send_message(target,f'🕵️ <b>پیام مشورت مافیا</b>\nاز: {sender}\n\n{safe_text(body,1200)}',parse_mode='HTML')
            except TelegramError: pass
        await msg.reply_text(f'📨 پیام مشورت برای {len(targets)} هم‌تیمی ارسال شد.'); return True
    await msg.reply_text('⛔ الان در شب یک بازی مافیا فعال نیستی یا نقش تو مافیا نیست.')
    return True

# Media tools: optional dependencies, never crash the bot if absent.
async def media_tool_router(update,context):
    msg=update.effective_message
    if not msg: return False
    cap=(msg.caption or '').strip().lower()
    if msg.voice and cap in {'ویس به متن','تبدیل ویس به متن','متن کن'}:
        try:
            import speech_recognition as sr
            from pydub import AudioSegment
            f=await context.bot.get_file(msg.voice.file_id); src='/tmp/bil_voice.ogg'; wav='/tmp/bil_voice.wav'; await f.download_to_drive(src); AudioSegment.from_file(src).export(wav,format='wav')
            r=sr.Recognizer(); audio=r.record(sr.AudioFile(wav)); text=r.recognize_google(audio,language='fa-IR'); await msg.reply_text('🎙 <b>متن ویس:</b>\n\n'+safe_text(text,4000),parse_mode='HTML'); return True
        except ImportError:
            await msg.reply_text('ℹ️ برای ویس‌به‌متن این دو بسته را نصب کن:\npip install SpeechRecognition pydub\nو برای تبدیل OGG به WAV باید FFmpeg هم روی محیطت موجود باشد.',parse_mode='HTML'); return True
        except Exception as e:
            await msg.reply_text('❌ تبدیل ویس انجام نشد؛ فایل یا سرویس تشخیص گفتار را بررسی کن.'); log.warning('voice2text: %s',e); return True
    if msg.photo and cap in {'عکس به متن','تبدیل عکس به متن','ocr'}:
        try:
            import pytesseract
            from PIL import Image
            f=await context.bot.get_file(msg.photo[-1].file_id); path='/tmp/bil_ocr.jpg'; await f.download_to_drive(path); text=pytesseract.image_to_string(Image.open(path),lang='fas+eng'); await msg.reply_text('🖼 <b>متن تصویر:</b>\n\n'+safe_text(text or 'متنی پیدا نشد.',5000),parse_mode='HTML'); return True
        except ImportError:
            await msg.reply_text('ℹ️ برای OCR نصب کن:\npip install pytesseract pillow\nو موتور Tesseract OCR باید روی دستگاه نصب باشد.',parse_mode='HTML'); return True
        except Exception as e: await msg.reply_text('❌ OCR انجام نشد.'); log.warning('ocr: %s',e); return True
    if msg.text and msg.text.strip().lower().startswith('متن به ویس '):
        text=msg.text.strip()[11:].strip()
        try:
            from gtts import gTTS
            path='/tmp/bil_tts.mp3'; gTTS(text=text,lang='fa').save(path)
            await msg.reply_voice(voice=open(path,'rb'),caption='🔊 متن به ویس')
            try: os.remove(path)
            except: pass
        except ImportError:
            await msg.reply_text('ℹ️ برای متن‌به‌ویس نصب کن: pip install gTTS',parse_mode='HTML')
        except Exception as e:
            await msg.reply_text('❌ تبدیل متن به ویس انجام نشد.'); log.warning('tts: %s',e)
        return True
    return False

# Message router wrapper: run the new tools before the old router.
_OLD_MESSAGE_ROUTER_ULTIMATE=message_router_v9
async def message_router_v9(update,context):
    try:
        if await mafia9_relay_router(update,context): return
        if await media_tool_router(update,context): return
        if await ultimate_tools_router(update,context): return
    except Exception as e:
        log.warning('ultimate router: %s',e)
    return await _OLD_MESSAGE_ROUTER_ULTIMATE(update,context)

# New build with the overridden message/callback routers.
def build_application(token:str)->Application:
    app=ApplicationBuilder().token(token).post_init(post_init_v9).post_shutdown(post_shutdown).build()
    for name,fn in [('start',start_v8),('help',cmd_help),('panel',cmd_panel),('adminpanel',cmd_adminpanel),('owner',owner_panel_v6),('features',cmd_features),('rules',rules_command),('setrules',set_rules),('welcome',set_welcome),('togglewelcome',toggle_welcome),('goodbye',set_goodbye),('togglegoodbye',toggle_goodbye),('forcejoin',forcejoin_v4),('stats',stats_v4_command)]: app.add_handler(CommandHandler(name,fn))
    app.add_handler(CommandHandler('cleanup',lambda u,c:cleanup_v4(u,c,500))); app.add_handler(CommandHandler('warn',lambda u,c:moderation_action(u,c,'warn'))); app.add_handler(CommandHandler('unwarn',lambda u,c:moderation_action(u,c,'unwarn')))
    app.add_handler(CommandHandler('mute',lambda u,c:mute_command_v6(u,c))); app.add_handler(CommandHandler('unmute',lambda u,c:moderation_v4(u,c,'unmute'))); app.add_handler(CommandHandler('ban',lambda u,c:moderation_v4(u,c,'ban'))); app.add_handler(CommandHandler('unban',lambda u,c:moderation_v4(u,c,'unban')))
    app.add_handler(CommandHandler('mafia',lambda u,c:mafia_start_menu(u,c)))
    app.add_handler(ChatMemberHandler(member_update_v6,ChatMemberHandler.CHAT_MEMBER))
    app.add_handler(CallbackQueryHandler(callback_router_v10))
    if MessageReactionHandler is not None: app.add_handler(MessageReactionHandler(reaction_handler))
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS,service_members_v4)); app.add_handler(MessageHandler(filters.StatusUpdate.LEFT_CHAT_MEMBER,service_members_v4)); app.add_handler(MessageHandler(filters.LOCATION,location_v4))
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,message_router_v9)); app.add_error_handler(error_handler)
    return app


