VIP_PRO_LEVELS = {'gold': {'title':'🥇 GOLD'}, 'pro': {'title':'👑 PRO'}, 'ultra': {'title':'💠 ULTRA'}}

async def ensure_vip_pro_schema():
    await DBX.execute("""CREATE TABLE IF NOT EXISTS vip_pro_settings (
        chat_id INTEGER PRIMARY KEY, level TEXT NOT NULL DEFAULT 'gold',
        custom_theme TEXT NOT NULL DEFAULT '💎', custom_title TEXT NOT NULL DEFAULT '',
        custom_panel_text TEXT NOT NULL DEFAULT '', daily_reward INTEGER NOT NULL DEFAULT 1,
        extra_security INTEGER NOT NULL DEFAULT 1, extra_cleanup INTEGER NOT NULL DEFAULT 1,
        extra_stats INTEGER NOT NULL DEFAULT 1, welcome_plus INTEGER NOT NULL DEFAULT 1,
        vip_badge INTEGER NOT NULL DEFAULT 1, expiry_alerts INTEGER NOT NULL DEFAULT 1, updated_at INTEGER NOT NULL DEFAULT 0
    )""")
    await DBX.execute("""CREATE TABLE IF NOT EXISTS vip_pro_rewards (chat_id INTEGER NOT NULL, user_id INTEGER NOT NULL, last_claim INTEGER NOT NULL DEFAULT 0, total_claims INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(chat_id,user_id))""")
    await DBX.execute("""CREATE TABLE IF NOT EXISTS vip_pro_stats (chat_id INTEGER PRIMARY KEY, messages INTEGER NOT NULL DEFAULT 0, members_joined INTEGER NOT NULL DEFAULT 0, warnings INTEGER NOT NULL DEFAULT 0, cleanups INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0)""")

async def ensure_vip_pro_row(cid):
    await ensure_vip_row(cid)
    await DBX.execute("INSERT OR IGNORE INTO vip_pro_settings(chat_id,updated_at) VALUES(?,?)",(cid,now_ts()))
    await DBX.execute("INSERT OR IGNORE INTO vip_pro_stats(chat_id,updated_at) VALUES(?,?)",(cid,now_ts()))

async def vip_pro_data(cid):
    await ensure_vip_pro_row(cid); return await DBX.one("SELECT * FROM vip_pro_settings WHERE chat_id=?",(cid,))

async def vip_pro_level(cid):
    if not await active_vip(cid): return 'free'
    r=await vip_pro_data(cid); level=str(r['level'] or 'gold').lower(); return level if level in VIP_PRO_LEVELS else 'gold'

async def vip_pro_features(cid):
    level=await vip_pro_level(cid)
    if level=='free': return []
    base=['🛡 امنیت پیشرفته','🧹 پاکسازی خودکار','👋 خوش‌آمد رسانه‌ای','📊 آمار حرفه‌ای','🎛 پنل اختصاصی','🔔 هشدار انقضا','🎁 هدیه روزانه VIP','🏅 نشان VIP']
    if level in ('pro','ultra'): base += ['⚡ تنظیمات امنیتی بیشتر','📈 آمار ویژه اعضا','🎨 عنوان و تم سفارشی']
    if level=='ultra': base += ['🚀 اولویت امکانات جدید','💠 پنل Ultra اختصاصی','🏆 رتبه‌بندی VIP گروه']
    return base

async def vip_pro_status(cid):
    row=await DBX.one("SELECT expires_at FROM vip_groups WHERE chat_id=?",(cid,)); exp=int(row['expires_at']) if row else 0; remain=max(0,exp-now_ts())
    if not remain: return '💎 <b>VIP گروه</b>\n\n⚪ VIP این گروه فعال نیست.\n\nفقط سازنده ربات می‌تواند VIP را شارژ کند.'
    r=await vip_pro_data(cid); level=await vip_pro_level(cid); d=remain//86400; h=(remain%86400)//3600; m=(remain%3600)//60
    text=f'💎 <b>VIP {VIP_PRO_LEVELS[level]["title"]}</b>\n\n🟢 وضعیت: فعال\n⏳ باقی‌مانده: <b>{d} روز، {h} ساعت و {m} دقیقه</b>\n\n✨ <b>امکانات:</b>\n'+'\n'.join('• '+x for x in await vip_pro_features(cid))
    if r['custom_title']: text += f'\n\n🏷 عنوان: <b>{safe_text(str(r["custom_title"]),80)}</b>'
    return text

async def vip_pro_keyboard(uid,cid):
    if await vip_pro_level(cid)=='free': return keyboard([[btn('📊 وضعیت VIP',f'vipx:{uid}:status')],[btn('🔙 مدیریت',admin_cb(uid,'home'))]])
    return keyboard([[btn('✨ امکانات',f'vipx:{uid}:features'),btn('📊 وضعیت',f'vipx:{uid}:status')],[btn('⚙️ تنظیمات',f'vipx:{uid}:settings'),btn('🎁 هدیه روزانه',f'vipx:{uid}:reward')],[btn('📈 آمار VIP',f'vipx:{uid}:stats'),btn('🎨 شخصی‌سازی',f'vipx:{uid}:custom')],[btn('🏅 سطح VIP',f'vipx:{uid}:levels')],[btn('🔙 مدیریت',admin_cb(uid,'home'))]])

async def vip_pro_panel(q,context):
    cid=q.message.chat.id; uid=q.from_user.id
    if not await local_admin(type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat})(),uid): await q.answer('⛔ فقط ادمین واقعی.',show_alert=True); return
    await q.edit_message_text(await vip_pro_status(cid),parse_mode='HTML',reply_markup=await vip_pro_keyboard(uid,cid))

async def vip_pro_callback(q,context):
    p=(q.data or '').split(':')
    if len(p)<3 or p[0]!='vipx' or not p[1].isdigit() or int(p[1])!=q.from_user.id: await q.answer('⛔ این پنل برای تو نیست.',show_alert=True); return True
    uid=q.from_user.id; cid=q.message.chat.id; sub=p[2]
    if not await local_admin(type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat})(),uid): await q.answer('⛔ فقط ادمین واقعی.',show_alert=True); return True
    if sub=='status': await vip_pro_panel(q,context); return True
    if not await active_vip(cid): await q.answer('💎 VIP فعال نیست.',show_alert=True); return True
    await ensure_vip_pro_row(cid); r=await vip_pro_data(cid)
    if sub=='features':
        await q.edit_message_text('✨ <b>امکانات VIP</b>\n\n'+'\n'.join('• '+x for x in await vip_pro_features(cid)),parse_mode='HTML',reply_markup=keyboard([[btn('🔙 VIP',f'vipx:{uid}:status')]])); return True
    if sub=='levels':
        await q.edit_message_text('🏅 <b>سطح‌های VIP</b>\n\n🥇 GOLD — امکانات اصلی\n👑 PRO — امکانات پیشرفته و شخصی‌سازی\n💠 ULTRA — کامل‌ترین سطح\n\nسطح توسط سازنده ربات تعیین می‌شود.',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 VIP',f'vipx:{uid}:status')]])); return True
    if sub=='settings':
        await q.edit_message_text(f'⚙️ <b>تنظیمات VIP</b>\n\n🎁 هدیه روزانه: {"🟢" if r["daily_reward"] else "🔴"}\n🛡 امنیت اضافه: {"🟢" if r["extra_security"] else "🔴"}\n🧹 پاکسازی اضافه: {"🟢" if r["extra_cleanup"] else "🔴"}\n📊 آمار اضافه: {"🟢" if r["extra_stats"] else "🔴"}\n👋 خوش‌آمد Plus: {"🟢" if r["welcome_plus"] else "🔴"}\n🔔 هشدار انقضا: {"🟢" if r["expiry_alerts"] else "🔴"}',parse_mode='HTML',reply_markup=keyboard([[btn('🎁 هدیه',f'vipxt:{uid}:daily_reward'),btn('🛡 امنیت',f'vipxt:{uid}:extra_security')],[btn('🧹 پاکسازی',f'vipxt:{uid}:extra_cleanup'),btn('📊 آمار',f'vipxt:{uid}:extra_stats')],[btn('👋 خوش‌آمد',f'vipxt:{uid}:welcome_plus'),btn('🔔 هشدار',f'vipxt:{uid}:expiry_alerts')],[btn('🔙 VIP',f'vipx:{uid}:status')]])); return True
    if sub=='stats':
        st=await DBX.one('SELECT * FROM vip_pro_stats WHERE chat_id=?',(cid,)); text=f'📈 <b>آمار VIP</b>\n\n💬 پیام‌ها: <b>{int(st["messages"] or 0)}</b>\n👥 ورود اعضا: <b>{int(st["members_joined"] or 0)}</b>\n⚠️ هشدارها: <b>{int(st["warnings"] or 0)}</b>\n🧹 پاکسازی‌ها: <b>{int(st["cleanups"] or 0)}</b>'; await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('🔙 VIP',f'vipx:{uid}:status')]])); return True
    if sub=='custom':
        await q.edit_message_text('🎨 <b>شخصی‌سازی</b>\n\nvip عنوان متن — عنوان سفارشی\nvip پیام متن — پیام پنل\nvip سطح gold / pro / ultra — سطح VIP',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 VIP',f'vipx:{uid}:status')]])); return True
    if sub=='reward':
        now=now_ts(); rr=await DBX.one('SELECT * FROM vip_pro_rewards WHERE chat_id=? AND user_id=?',(cid,uid))
        if rr and now-int(rr['last_claim'] or 0)<86400: await q.answer('⏳ هدیه روزانه را قبلاً گرفتی.',show_alert=True); return True
        await DBX.execute('INSERT INTO vip_pro_rewards(chat_id,user_id,last_claim,total_claims) VALUES(?,?,?,1) ON CONFLICT(chat_id,user_id) DO UPDATE SET last_claim=excluded.last_claim,total_claims=total_claims+1',(cid,uid,now)); await DBX.execute('UPDATE users SET score=COALESCE(score,0)+100 WHERE user_id=?',(uid,)); await q.answer('🎁 ۱۰۰ امتیاز VIP گرفتی!',show_alert=True); return True
    return True

async def vip_pro_toggle_callback(q,context):
    p=(q.data or '').split(':')
    if len(p)!=3 or p[0]!='vipxt' or not p[1].isdigit() or int(p[1])!=q.from_user.id: return False
    uid=q.from_user.id; cid=q.message.chat.id; col=p[2]; allowed={'daily_reward','extra_security','extra_cleanup','extra_stats','welcome_plus','expiry_alerts'}
    if col not in allowed: return True
    if not await local_admin(type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat})(),uid): await q.answer('⛔ فقط ادمین.',show_alert=True); return True
    if not await active_vip(cid): await q.answer('💎 VIP فعال نیست.',show_alert=True); return True
    await ensure_vip_pro_row(cid); r=await DBX.one('SELECT '+col+' v FROM vip_pro_settings WHERE chat_id=?',(cid,)); nv=0 if int(r['v'] or 0) else 1
    await DBX.execute('UPDATE vip_pro_settings SET '+col+'=?,updated_at=? WHERE chat_id=?',(nv,now_ts(),cid)); await q.answer('تنظیم شد.',show_alert=True); await vip_pro_panel(q,context); return True

async def vip_pro_text_router(update,context):
    msg=update.effective_message
    if not msg or not msg.text or not update.effective_chat or update.effective_chat.type=='private': return False
    t=msg.text.strip(); low=t.lower(); cid=update.effective_chat.id; uid=update.effective_user.id
    if low in {'vip','💎 vip','وی آی پی','وی‌آی‌پی','پنل vip'}:
        if not await local_admin(update,uid): await msg.reply_text('⛔ فقط ادمین گروه می‌تواند پنل VIP را باز کند.'); return True
        await ensure_vip_pro_row(cid); await msg.reply_text(await vip_pro_status(cid),parse_mode='HTML',reply_markup=await vip_pro_keyboard(uid,cid)); return True
    if not await local_admin(update,uid): return False
    if low.startswith('vip سطح '):
        a=low.split('vip سطح ',1)[1].strip(); level={'gold':'gold','گلد':'gold','pro':'pro','پرو':'pro','ultra':'ultra','اولترا':'ultra'}.get(a)
        if level: await ensure_vip_pro_row(cid); await DBX.execute('UPDATE vip_pro_settings SET level=?,updated_at=? WHERE chat_id=?',(level,now_ts(),cid)); await msg.reply_text(f'🏅 سطح VIP روی <b>{VIP_PRO_LEVELS[level]["title"]}</b> تنظیم شد.',parse_mode='HTML'); return True
    if low.startswith('vip عنوان '):
        v=t.split(None,2)[2].strip(); await ensure_vip_pro_row(cid); await DBX.execute('UPDATE vip_pro_settings SET custom_title=?,updated_at=? WHERE chat_id=?',(v[:80],now_ts(),cid)); await msg.reply_text('🎨 عنوان VIP ذخیره شد.'); return True
    if low.startswith('vip پیام '):
        v=t.split(None,2)[2].strip(); await ensure_vip_pro_row(cid); await DBX.execute('UPDATE vip_pro_settings SET custom_panel_text=?,updated_at=? WHERE chat_id=?',(v[:1000],now_ts(),cid)); await msg.reply_text('📝 پیام پنل VIP ذخیره شد.'); return True
    return False

_OLD_VIPPRO_MESSAGE_ROUTER=message_router_v9
async def message_router_v9(update,context):
    try:
        if await vip_pro_text_router(update,context): return
        if update.effective_chat and update.effective_chat.type!='private' and await active_vip(update.effective_chat.id):
            await ensure_vip_pro_row(update.effective_chat.id); await DBX.execute('UPDATE vip_pro_stats SET messages=messages+1,updated_at=? WHERE chat_id=?',(now_ts(),update.effective_chat.id))
    except Exception as e: log.warning('vip pro: %s',e)
    return await _OLD_VIPPRO_MESSAGE_ROUTER(update,context)

# -----------------------------------------------------------------------------
# FINAL CALLBACK NAVIGATION GUARD
# Prevents two fast button taps / slow API callbacks from editing the same
# Telegram message out of order. Without this, an older page can finish later
# and replace the newer page, making buttons appear to move/disappear.
# -----------------------------------------------------------------------------
_CALLBACK_NAV_LOCKS = defaultdict(asyncio.Lock)

def _callback_lock_key(q):
    try:
        return (int(q.message.chat.id), int(q.message.message_id))
    except Exception:
        return (int(getattr(q.from_user, 'id', 0)), 0)

_OLD_VIPPRO_CALLBACK_ROUTER=callback_router_v10
async def callback_router_v10(update,context):
    q=getattr(update,'callback_query',None)
    if not q:
        return
    lock=_CALLBACK_NAV_LOCKS[_callback_lock_key(q)]
    async with lock:
        if q and (q.data or '').startswith('vipxt:'):
            await vip_pro_toggle_callback(q,context); return
        if q and (q.data or '').startswith('vipx:'):
            await vip_pro_callback(q,context); return
        return await _OLD_VIPPRO_CALLBACK_ROUTER(update,context)

_OLD_VIPPRO_POST_INIT=post_init_v9
async def post_init_vip_pro(application):
    await _OLD_VIPPRO_POST_INIT(application); await ensure_vip_pro_schema()

