async def cleanup_panel(q, context):
    uid, cid = q.from_user.id, q.message.chat.id
    fake=type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat})()
    if not await local_admin(fake, uid):
        await q.answer('⛔ فقط ادمین واقعی.', show_alert=True); return
    await q.edit_message_text(await cleanup_panel_text(cid), parse_mode='HTML', reply_markup=cleanup_panel_keyboard(uid))

async def cleanup_do_batch(context, cid, rows):
    deleted=0; failed=0
    # Telegram Bot API supports 1-100 message IDs per deleteMessages call.
    ids=[int(r['message_id']) for r in rows]
    for i in range(0, len(ids), 100):
        batch=ids[i:i+100]
        try:
            await context.bot.delete_messages(cid, batch)
            deleted += len(batch)
        except TelegramError:
            # Fallback to individual deletion to produce accurate counts.
            for mid in batch:
                try:
                    await context.bot.delete_message(cid, mid); deleted += 1
                except TelegramError:
                    failed += 1
    return deleted, failed

def _cleanup_row_kind(r):
    # message_log currently stores IDs/users only; use message_id availability
    # and the optional metadata columns when present in future schemas.
    return str(r['kind']) if 'kind' in r.keys() else ''

async def cleanup_run(q, context, uid, cid, mode, count):
    fake=type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat})()
    if not await local_admin(fake, uid):
        await q.answer('⛔ فقط ادمین واقعی.', show_alert=True); return
    # Bot must be an administrator with delete permission.
    try:
        me = await context.bot.get_me()
        bm = await context.bot.get_chat_member(cid, me.id)
        if bm.status not in {ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER} or not getattr(bm, 'can_delete_messages', False):
            await q.answer('⛔ بیل‌بیلک باید ادمین باشد و دسترسی حذف پیام داشته باشد.', show_alert=True); return
    except TelegramError:
        await q.answer('⛔ دسترسی حذف پیام بیل‌بیلک قابل بررسی نیست.', show_alert=True); return
    start=time.monotonic()
    rows=await DBX.execute("SELECT message_id,user_id,is_admin,created_at FROM message_log WHERE chat_id=? ORDER BY created_at DESC LIMIT ?", (cid, int(count)), fetch=True)
    if mode=='links':
        # لینک‌ها از روی متن قابل تشخیص نیستند چون message_log متن را ذخیره نمی‌کند.
        # برای جلوگیری از ادعای حذف اشتباه، فقط پیام‌هایی که بعداً metadata دارند قابل فیلتر هستند.
        rows=[]
    elif mode=='media':
        rows=[]
    elif mode=='bots':
        # message_log user_id is enough only if the member can be queried.
        filtered=[]
        for r in rows:
            try:
                m=await context.bot.get_chat_member(cid,int(r['user_id']))
                if m.user.is_bot: filtered.append(r)
            except TelegramError: pass
        rows=filtered
    deleted,failed=await cleanup_do_batch(context,cid,rows)
    elapsed=int((time.monotonic()-start)*1000)
    requested=len(rows)
    await DBX.execute("DELETE FROM message_log WHERE chat_id=? AND message_id IN (%s)" % (','.join('?'*len(rows)) if rows else 'NULL'), tuple([cid]+[int(r['message_id']) for r in rows]) if rows else (cid,))
    await DBX.execute("INSERT OR IGNORE INTO cleanup_stats(chat_id) VALUES(?)",(cid,))
    await DBX.execute("UPDATE cleanup_stats SET runs=runs+1,requested=requested+?,deleted=deleted+?,failed=failed+?,last_run=?,total_ms=total_ms+? WHERE chat_id=?",(requested,deleted,failed,now_ts(),elapsed,cid))
    await DBX.execute("INSERT INTO cleanup_runs(chat_id,admin_id,mode,requested,deleted,failed,elapsed_ms,created_at) VALUES(?,?,?,?,?,?,?,?)",(cid,uid,mode,requested,deleted,failed,elapsed,now_ts()))
    await q.edit_message_text(
        f"🐶 <b>پاکسازی انجام شد</b>\n\n📦 درخواست: <b>{count}</b>\n🗑 حذف موفق: <b>{deleted}</b>\n⚠️ ناموفق: <b>{failed}</b>\n⏱ زمان: <b>{elapsed/1000:.2f} ثانیه</b>\n\n⚠️ فقط پیام‌هایی که بیل‌بیلک در دسترس/ثبت‌شده داشته بررسی شدند.",
        parse_mode='HTML', reply_markup=keyboard([[btn('🧹 پاکسازی دوباره',f'cp:{uid}:home')],[btn('🔙 مدیریت',admin_cb(uid,'home'))]])
    )

async def cleanup_stats_panel(q, context, uid, cid):
    fake=type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat})()
    if not await local_admin(fake,uid): await q.answer('⛔ فقط ادمین.',show_alert=True); return
    st=await DBX.one("SELECT * FROM cleanup_stats WHERE chat_id=?",(cid,))
    runs=await DBX.execute("SELECT mode,requested,deleted,failed,elapsed_ms,created_at FROM cleanup_runs WHERE chat_id=? ORDER BY id DESC LIMIT 5",(cid,),fetch=True)
    text=(f"📊 <b>آمار پاکسازی</b>\n\n▶️ اجراها: <b>{int(st['runs']) if st else 0}</b>\n📦 بررسی/درخواست: <b>{int(st['requested']) if st else 0}</b>\n🗑 حذف موفق: <b>{int(st['deleted']) if st else 0}</b>\n⚠️ ناموفق: <b>{int(st['failed']) if st else 0}</b>\n\n<b>۵ عملیات اخیر:</b>\n")
    for r in runs:
        text += f"• {safe_text(r['mode'],20)} | {int(r['deleted'])}/{int(r['requested'])} | {int(r['elapsed_ms'])}ms\n"
    await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('🔙 پاکسازی',f'cp:{uid}:home')]]))

