async def owner_cleanup_account_check(q, context):
    if not owner_is_allowed(q.from_user.id):
        await q.answer('⛔ فقط سازنده.', show_alert=True)
        return
    acc = await cleanup_account_row()
    if not acc or not int(acc['account_user_id'] or 0):
        await q.answer('اول اکانت مکمل را ثبت کن.', show_alert=True)
        return
    groups = await DBX.execute("SELECT chat_id,title FROM chats WHERE active=1 LIMIT 30", fetch=True)
    checked = 0
    admins = 0
    for g in groups:
        try:
            m = await context.bot.get_chat_member(int(g['chat_id']), int(acc['account_user_id']))
            if m.status in {ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER}:
                admins += 1
            checked += 1
        except TelegramError:
            continue
    await DBX.execute(
        "UPDATE cleanup_accounts SET last_status=?,last_check=?,updated_at=? WHERE id=1",
        (f'ادمین در {admins} از {checked} گروه بررسی‌شده', now_ts(), now_ts())
    )
    await q.answer(f'در {admins} گروه از {checked} گروه بررسی شد.', show_alert=True)
    await owner_cleanup_dashboard(q, context)

async def owner_cleanup_account_delete(q, context):
    if not owner_is_allowed(q.from_user.id):
        await q.answer('⛔ فقط سازنده.', show_alert=True)
        return
    await ensure_cleanup_pro_schema()
    await DBX.execute('DELETE FROM cleanup_accounts WHERE id=1')
    OWNER_PENDING_CLEANUP_ACCOUNT.discard(q.from_user.id)
    await q.answer('اتصال حذف شد.', show_alert=True)
    await owner_cleanup_dashboard(q, context)

