_OLD_OWNER_CONTROL_CALLBACK_FINAL = owner_control_callback
async def owner_control_callback(q, context):
    if not owner_is_allowed(q.from_user.id):
        await q.answer('⛔ فقط سازنده.', show_alert=True)
        return
    action = (q.data or '').split(':', 1)[1] if ':' in (q.data or '') else ''
    if action == 'cleanup':
        await owner_cleanup_dashboard(q, context); return
    if action == 'cleanup_account_add':
        OWNER_PENDING_CLEANUP_ACCOUNT.add(q.from_user.id)
        await q.answer('شناسه را بفرست.', show_alert=True)
        await q.message.reply_text(
            '👤 <b>ثبت اکانت مکمل</b>\n\n'
            'شناسه عددی اکانت را ارسال کن:\n'
            'ثبت اکانت مکمل 123456789\n\n'
            'فقط شناسه ذخیره می‌شود؛ اطلاعات ورود اکانت ذخیره نمی‌شود.',
            parse_mode='HTML'
        )
        return
    if action == 'cleanup_account_check':
        await owner_cleanup_account_check(q, context); return
    if action == 'cleanup_account_toggle':
        acc = await cleanup_account_row()
        if not acc or not int(acc['account_user_id'] or 0):
            await q.answer('اول اکانت مکمل را ثبت کن.', show_alert=True); return
        nv = 0 if int(acc['enabled'] or 0) else 1
        await DBX.execute('UPDATE cleanup_accounts SET enabled=?,updated_at=? WHERE id=1', (nv, now_ts()))
        await q.answer('🟢 فعال شد.' if nv else '🔴 خاموش شد.', show_alert=True)
        await owner_cleanup_dashboard(q, context); return
    if action == 'cleanup_account_delete':
        await owner_cleanup_account_delete(q, context); return
    if action == 'cleanup_groups':
        await owner_cleanup_groups(q, context); return
    if action == 'cleanup_stats':
        await owner_cleanup_stats(q, context); return
    if action == 'account':
        await owner_cleanup_dashboard(q, context); return
    return await _OLD_OWNER_CONTROL_CALLBACK_FINAL(q, context)

# Make Owner text registration actually use the Owner's pending state.
_OLD_OWNER_CONTROL_TEXT_FINAL = owner_control_text
async def owner_control_text(update, context):
    msg = update.effective_message
    uid = update.effective_user.id if update.effective_user else 0
    if not msg or not owner_is_allowed(uid):
        return False
    t = normalize(msg.text or '')
    if t.startswith('ثبت اکانت مکمل '):
        raw = t.replace('ثبت اکانت مکمل ', '', 1).strip()
        if not raw.isdigit():
            await msg.reply_text('⛔ شناسه باید عددی باشد.')
            return True
        account_id = int(raw)
        await ensure_cleanup_pro_schema()
        try:
            chat = await context.bot.get_chat(account_id)
            name = display_name(chat)
        except TelegramError:
            name = f'User {account_id}'
        await DBX.execute(
            "INSERT INTO cleanup_accounts(id,account_user_id,account_name,enabled,last_status,created_at,updated_at) "
            "VALUES(1,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET account_user_id=excluded.account_user_id, "
            "account_name=excluded.account_name,enabled=1,last_status=excluded.last_status,updated_at=excluded.updated_at",
            (account_id, name, 1, 'ثبت‌شده از پنل Owner', now_ts(), now_ts())
        )
        OWNER_PENDING_CLEANUP_ACCOUNT.discard(uid)
        await msg.reply_text(
            f'👤 <b>اکانت مکمل ثبت شد</b>\n\nنام: <b>{safe_text(name,60)}</b>\n'
            f'🆔 {account_id}\n\n💾 ذخیره دائمی شد.',
            parse_mode='HTML'
        )
        return True
    return await _OLD_OWNER_CONTROL_TEXT_FINAL(update, context)

# Final callback wrapper: owner cleanup + existing cleanup + all previous routers.
_OLD_CALLBACK_ROUTER_OWNER_FINAL = callback_router_v10
async def callback_router_v10(update, context):
    q = getattr(update, 'callback_query', None)
    if q and (q.data or '').startswith('oc:'):
        lock = _CALLBACK_NAV_LOCKS[_callback_lock_key(q)]
        async with lock:
            await owner_control_callback(q, context)
        return
    return await _OLD_CALLBACK_ROUTER_OWNER_FINAL(update, context)

# Final application builder points at the final callback router dynamically.
_OLD_BUILD_APPLICATION_FINAL = build_application
def build_application(token: str) -> Application:
    app = _OLD_BUILD_APPLICATION_FINAL(token)
    # Passive logger: runs before the normal message router and never blocks it.
    # This makes future cleanup able to target messages the bot actually observed.
    try:
        app.add_handler(
            MessageHandler(filters.ALL & ~filters.COMMAND, record_v4_message, block=False),
            group=-10,
        )
    except Exception as e:
        log.warning('cleanup message recorder could not be installed: %s', e)
    return app

# The entry point MUST be last so every final override above is defined before startup.

# =============================================================================
# BIL BILAK - PUBLIC MEDIA DOWNLOADER
# =============================================================================
# فقط برای لینک‌های عمومی و محتوایی که کاربر حق دریافت آن را دارد.
# ورود به حساب، کوکی، DRM، محتوای خصوصی یا محدودیت‌های دسترسی پشتیبانی نمی‌شود.

DOWNLOADER_MAX_BYTES = 45 * 1024 * 1024
DOWNLOADER_TIMEOUT = 90


def _valid_public_url(url: str) -> bool:
    return bool(re.match(r"^https?://[^\s]+$", (url or '').strip(), re.I))


def _download_public_media(url: str, mode: str, folder: str):
    try:
        import yt_dlp
    except ImportError:
        raise RuntimeError("کتابخانه yt-dlp نصب نیست. در Pydroid اجرا کن: pip install -U yt-dlp")

    if mode == 'audio':
        fmt = 'bestaudio[ext=m4a]/bestaudio/best'
    else:
        # یک فایل مستقل انتخاب می‌شود تا برای Pydroid الزاماً به ffmpeg برای merge نیاز نباشد.
        fmt = 'best[ext=mp4][height<=720]/best[ext=mp4]/best'

    outtmpl = str(Path(folder) / '%(title).80s-%(id)s.%(ext)s')
    opts = {
        'format': fmt,
        'outtmpl': outtmpl,
        'noplaylist': True,
        'quiet': True,
        'no_warnings': True,
        'restrictfilenames': True,
        'socket_timeout': 20,
        'retries': 2,
        'fragment_retries': 2,
        'max_filesize': DOWNLOADER_MAX_BYTES,
    }
    with yt_dlp.YoutubeDL(opts) as ydl:
        info = ydl.extract_info(url, download=True)
        filename = ydl.prepare_filename(info)
        # بعضی extractorها پسوند نهایی را تغییر می‌دهند؛ اگر مسیر آماده وجود نداشت، فایل هم‌نام را پیدا کن.
        path = Path(filename)
        if not path.exists():
            candidates = list(Path(folder).glob(f'*{info.get("id", "")}*'))
            if candidates:
                path = candidates[0]
        if not path.exists():
            raise RuntimeError('فایل خروجی پیدا نشد.')
        if path.stat().st_size > DOWNLOADER_MAX_BYTES:
            path.unlink(missing_ok=True)
            raise RuntimeError('حجم فایل برای ارسال توسط ربات زیاد است (حداکثر حدود 45MB).')
        return str(path), info


async def downloader_text(update, context) -> bool:
    msg = update.effective_message
    if not msg or not msg.text:
        return False
    t = normalize(msg.text)
    mode = None
    prefix = None
    if t.startswith('دانلود ویدیو '):
        mode, prefix = 'video', 'دانلود ویدیو '
    elif t.startswith('دانلود آهنگ '):
        mode, prefix = 'audio', 'دانلود آهنگ '
    elif t.startswith('دانلود صدا '):
        mode, prefix = 'audio', 'دانلود صدا '
    elif t.startswith('دانلود '):
        mode, prefix = 'video', 'دانلود '
    elif t in {'دانلودر', 'دانلود', 'راهنمای دانلودر'}:
        await msg.reply_text(
            '📥 <b>دانلودر بیل بیلک</b>\n\n'
            'برای لینک عمومی از این قالب‌ها استفاده کن:\n'
            '• دانلود https://...\n'
            '• دانلود ویدیو https://...\n'
            '• دانلود آهنگ https://...\n\n'
            '🔒 لینک‌های خصوصی، ورود به حساب و محتوای دارای محدودیت دسترسی پشتیبانی نمی‌شوند.\n'
            '⚠️ فقط محتوایی را دریافت کن که اجازه دریافتش را داری.',
            parse_mode='HTML'
        )
        return True
    else:
        return False

    url = msg.text.split(None, len(prefix.split()))[-1].strip()
    if not _valid_public_url(url):
        await msg.reply_text('❌ لینک معتبر عمومی وارد کن.\nمثال: دانلود https://example.com/...', parse_mode='HTML')
        return True

    status = await msg.reply_text('⏳ در حال بررسی لینک و آماده‌سازی فایل...')
    folder = tempfile.mkdtemp(prefix='bilbilak_dl_')
    try:
        path, info = await asyncio.wait_for(
            asyncio.to_thread(_download_public_media, url, mode, folder),
            timeout=DOWNLOADER_TIMEOUT
        )
        title = safe_text(info.get('title') or 'فایل دانلودشده', 120)
        size_mb = Path(path).stat().st_size / (1024 * 1024)
        await status.edit_text(f'📤 در حال ارسال «{title}» ({size_mb:.1f}MB)...')
        with open(path, 'rb') as fh:
            if mode == 'audio':
                await msg.reply_audio(fh, title=title[:64], caption='🎵 دانلودر بیل بیلک')
            else:
                try:
                    await msg.reply_video(fh, caption=f'🎬 {title}', supports_streaming=True)
                except TelegramError:
                    fh.seek(0)
                    await msg.reply_document(fh, caption=f'📎 {title}')
        try:
            await status.delete()
        except TelegramError:
            pass
    except asyncio.TimeoutError:
        await status.edit_text('⏱ دانلود بیشتر از زمان مجاز طول کشید؛ دوباره با یک لینک عمومی دیگر امتحان کن.')
    except Exception as e:
        detail = safe_text(str(e), 220)
        await status.edit_text(f'❌ دانلود انجام نشد.\n{detail}', parse_mode='HTML')
    finally:
        try:
            import shutil
            shutil.rmtree(folder, ignore_errors=True)
        except Exception:
            pass
    return True


# Add downloader before the normal text router so its commands are handled first.
_OLD_MESSAGE_ROUTER_DOWNLOADER = message_router_v9
async def message_router_v10(update, context):
    try:
        if await downloader_text(update, context):
            return
    except Exception as e:
        log.warning('downloader router: %s', e)
    return await _OLD_MESSAGE_ROUTER_DOWNLOADER(update, context)

# The existing final build uses the global message_router_v9 at build time;
# rebuild it once here so the new router is installed without touching old features.
_OLD_BUILD_APPLICATION_DOWNLOADER = build_application
def build_application(token: str) -> Application:
    app = _OLD_BUILD_APPLICATION_DOWNLOADER(token)
    # Replace the normal non-command message handler with the downloader-aware router.
    # Keep the passive cleanup logger intact.
    try:
        app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND, message_router_v10), group=-5)
    except Exception as e:
        log.warning('downloader handler could not be installed: %s', e)
    return app


# =============================================================================
# BIL BILAK - GROUP SPEAKER / WELCOME ORGANIZATION
# =============================================================================
# این بخش فقط قابلیت‌های سخنگو را اضافه می‌کند و مسیرهای قبلی را دست‌نخورده نگه می‌دارد.

async def _speaker_schema():
    await DBX.execute("""
        CREATE TABLE IF NOT EXISTS speaker_settings (
            chat_id INTEGER PRIMARY KEY,
            enabled INTEGER NOT NULL DEFAULT 0,
            smart_match INTEGER NOT NULL DEFAULT 1,
            random_reply INTEGER NOT NULL DEFAULT 1,
            cooldown REAL NOT NULL DEFAULT 3,
            updated_at INTEGER NOT NULL DEFAULT 0
        )
    """)
    await DBX.execute("""
        CREATE TABLE IF NOT EXISTS speaker_chats (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            chat_id INTEGER NOT NULL,
            question TEXT NOT NULL,
            answer_type TEXT NOT NULL DEFAULT 'text',
            answer_text TEXT DEFAULT '',
            file_id TEXT DEFAULT '',
            caption TEXT DEFAULT '',
            created_by INTEGER NOT NULL DEFAULT 0,
            uses INTEGER NOT NULL DEFAULT 0,
            created_at INTEGER NOT NULL DEFAULT 0
        )
    """)
    await DBX.execute("CREATE INDEX IF NOT EXISTS idx_speaker_chats_question ON speaker_chats(chat_id, question)")
    # Global speaker knowledge: every approved group-admin registration is shared
    # across the whole bot database, while per-group enable/disable remains intact.
    await DBX.execute("""
        CREATE TABLE IF NOT EXISTS speaker_global_chats (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            question TEXT NOT NULL,
            answer_type TEXT NOT NULL DEFAULT 'text',
            answer_text TEXT DEFAULT '',
            file_id TEXT DEFAULT '',
            caption TEXT DEFAULT '',
            source_chat_id INTEGER NOT NULL DEFAULT 0,
            created_by INTEGER NOT NULL DEFAULT 0,
            uses INTEGER NOT NULL DEFAULT 0,
            created_at INTEGER NOT NULL DEFAULT 0
        )
    """)
    await DBX.execute("CREATE INDEX IF NOT EXISTS idx_speaker_global_question ON speaker_global_chats(question)")
    # One-time/continuous legacy migration: old per-group registrations are
    # copied into the shared store without duplicating identical Q/A entries.
    try:
        await DBX.execute("""
            INSERT INTO speaker_global_chats(question,answer_type,answer_text,file_id,caption,source_chat_id,created_by,uses,created_at)
            SELECT s.question,s.answer_type,s.answer_text,s.file_id,s.caption,s.chat_id,s.created_by,s.uses,s.created_at
            FROM speaker_chats s
            WHERE NOT EXISTS (
                SELECT 1 FROM speaker_global_chats g
                WHERE g.question=s.question
                  AND g.answer_type=s.answer_type
                  AND COALESCE(g.file_id,'')=COALESCE(s.file_id,'')
                  AND COALESCE(g.answer_text,'')=COALESCE(s.answer_text,'')
                  AND COALESCE(g.caption,'')=COALESCE(s.caption,'')
            )
        """)
    except Exception as e:
        log.debug("speaker global migration: %s", e)
    try:
        cols=await DBX.execute("PRAGMA table_info(speaker_settings)",fetch=True)
        names={str(r["name"]) for r in (cols or [])}
        for name,ddl in [("ai_enabled","INTEGER NOT NULL DEFAULT 0"),("ai_verbosity","TEXT NOT NULL DEFAULT 'short'"),("ai_tone","TEXT NOT NULL DEFAULT 'polite'"),("memory_enabled","INTEGER NOT NULL DEFAULT 1"),("memory_limit","INTEGER NOT NULL DEFAULT 20")]:
            if name not in names:
                await DBX.execute(f"ALTER TABLE speaker_settings ADD COLUMN {name} {ddl}")
    except Exception as e:
        log.warning("speaker ai schema migration: %s",e)
    await DBX.execute("""
        CREATE TABLE IF NOT EXISTS speaker_memory (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            chat_id INTEGER NOT NULL,
            role TEXT NOT NULL,
            user_id INTEGER NOT NULL DEFAULT 0,
            name TEXT DEFAULT '',
            content TEXT NOT NULL,
            created_at INTEGER NOT NULL DEFAULT 0
        )
    """)
    await DBX.execute("CREATE INDEX IF NOT EXISTS idx_speaker_memory_chat ON speaker_memory(chat_id, id)")


def _speaker_media_from_message(m):
    if not m:
        return None
    if getattr(m, 'photo', None): return ('photo', m.photo[-1].file_id, m.caption or '')
    if getattr(m, 'animation', None): return ('animation', m.animation.file_id, m.caption or '')
    if getattr(m, 'audio', None): return ('audio', m.audio.file_id, m.caption or '')
    if getattr(m, 'voice', None): return ('voice', m.voice.file_id, m.caption or '')
    if getattr(m, 'video', None): return ('video', m.video.file_id, m.caption or '')
    if getattr(m, 'video_note', None): return ('video_note', m.video_note.file_id, '')
    if getattr(m, 'sticker', None): return ('sticker', m.sticker.file_id, '')
    if getattr(m, 'text', None): return ('text', '', m.text)
    return None


def _speaker_clean_question(text):
    t=normalize(text or '')
    t=re.sub(r'[؟?!.,،؛:]+',' ',t)
    return re.sub(r'\s+',' ',t).strip()


def _speaker_similarity(a,b):
    from difflib import SequenceMatcher
    return SequenceMatcher(None,_speaker_clean_question(a),_speaker_clean_question(b)).ratio()

async def _speaker_setting(cid):
    await _speaker_schema()
    row=await DBX.one('SELECT * FROM speaker_settings WHERE chat_id=?',(cid,))
    if not row:
        await DBX.execute('INSERT INTO speaker_settings(chat_id) VALUES(?)',(cid,))
        row=await DBX.one('SELECT * FROM speaker_settings WHERE chat_id=?',(cid,))
    return row

async def _speaker_send_answer(msg,row):
    typ=row['answer_type']; fid=row['file_id']; text=row['answer_text'] or row['caption'] or ''
    if typ=='text': await msg.reply_text(text); return
    cap=row['caption'] or ''
    if typ=='photo': await msg.reply_photo(fid,caption=cap or None)
    elif typ=='animation': await msg.reply_animation(fid,caption=cap or None)
    elif typ=='audio': await msg.reply_audio(fid,caption=cap or None)
    elif typ=='voice': await msg.reply_voice(fid,caption=cap or None)
    elif typ=='video': await msg.reply_video(fid,caption=cap or None)
    elif typ=='video_note': await msg.reply_video_note(fid)
    elif typ=='sticker': await msg.reply_sticker(fid)

async def _speaker_memory_add(chat_id, role, content, user_id=0, name="", limit=20):
    content=safe_text(content, 1800)
    if not content: return
    try:
        await DBX.execute(
            'INSERT INTO speaker_memory(chat_id,role,user_id,name,content,created_at) VALUES(?,?,?,?,?,?)',
            (chat_id,role,int(user_id or 0),safe_text(name,80),content,now_ts())
        )
        limit=max(4,min(50,int(limit or 20)))
        await DBX.execute(
            'DELETE FROM speaker_memory WHERE chat_id=? AND id NOT IN (SELECT id FROM speaker_memory WHERE chat_id=? ORDER BY id DESC LIMIT ?)',
            (chat_id,chat_id,limit)
        )
    except Exception as e:
        log.warning("speaker memory add: %s",e)

async def _speaker_memory_get(chat_id, limit=20):
    try:
        limit=max(4,min(50,int(limit or 20)))
        rows=await DBX.execute('SELECT role,name,content FROM speaker_memory WHERE chat_id=? ORDER BY id DESC LIMIT ?', (chat_id,limit),fetch=True)
        return list(reversed(rows or []))
    except Exception as e:
        log.warning("speaker memory get: %s",e); return []

async def _speaker_memory_clear(chat_id):
    await DBX.execute('DELETE FROM speaker_memory WHERE chat_id=?',(chat_id,))

async def _speaker_ai_call(question, chat_title="", username="", verbosity="short", tone="polite", chat_id=None, memory_enabled=True, memory_limit=20, timeout=90):
    key=await _bb_pro_get("OPENROUTER_API_KEY", os.getenv("OPENROUTER_API_KEY",""))
    if not key: return None
    model=await _bb_pro_get("OPENROUTER_MODEL", os.getenv("OPENROUTER_MODEL","")) or await _bb_pro_get("cfg:openrouter_model","openai/gpt-4o-mini") or "openai/gpt-4o-mini"
    length="پاسخ کوتاه و جمع‌وجور، معمولاً ۱ تا ۲ جمله." if verbosity!="long" else "پاسخ نسبتاً کامل و پرحرف، معمولاً ۳ تا ۶ جمله."
    style="مودب، دوستانه و خودمانی باش." if tone!="rude" else "خودمانی، شوخ و کمی بی‌ادبِ دوستانه باش؛ فقط تیکه و شوخی ملایم، بدون توهین شدید، نفرت، تهدید، محتوای جنسی یا آزار هدفمند."
    messages=[{"role":"system","content":"تو سخنگوی هوشمند ربات تلگرامی «بیل بیلک» هستی. فارسی محاوره‌ای جواب بده و خودت را انسان جا نزن. "+length+" "+style+" اگر سؤال نامشخص بود کوتاه بپرس. اطلاعات خصوصی کاربران را درخواست یا افشا نکن. اگر سابقه مکالمه در اختیار توست، فقط برای حفظ پیوستگی گفتگو از آن استفاده کن و اطلاعات خصوصی را بازتولید نکن."}]
    if memory_enabled and chat_id:
        for h in await _speaker_memory_get(chat_id,memory_limit):
            role='assistant' if h['role']=='assistant' else 'user'
            who=(h['name'] or 'عضو گروه')
            messages.append({"role":role,"content":f"{who}: {h['content']}"})
    messages.append({"role":"user","content":f"گروه: {chat_title or 'گروه'}\nکاربر: {username or 'عضو گروه'}\nپیام: {safe_text(question,1800)}"})
    body={"model":model,"messages":messages,"temperature":0.8,"max_tokens":500 if verbosity=="long" else 180}
    try:
        r=await _bb_http_post("https://openrouter.ai/api/v1/chat/completions",{"Authorization":f"Bearer {key}","Content-Type":"application/json","HTTP-Referer":"https://t.me/","X-Title":"Bil Bilak"},body,timeout=timeout)
        data=r.json(); c=((data.get("choices") or [{}])[0].get("message") or {}).get("content")
        if isinstance(c,list): c="".join(str(x.get("text","")) if isinstance(x,dict) else str(x) for x in c)
        return (c or "").strip()[:3500] or None
    except Exception as e:
        log.warning("speaker ai request: %s",e); return None

async def _speaker_ai_reply(msg, setting):
    """پاسخ سریع سخنگو؛ بدون نیاز به صدا زدن نام ربات.
    اگر AI روشن باشد، حداکثر حدود ۰.۸۵ ثانیه برای AI صبر می‌کند؛
    اگر پاسخ نرسید، فوراً یک پاسخ تصادفی محلی می‌دهد.
    """
    text=msg.text or ''
    if not text or not msg.chat or not msg.from_user or msg.from_user.is_bot:
        return False

    key=(msg.chat.id,msg.from_user.id)
    now=time.monotonic()
    try:
        _setting = dict(setting)
    except Exception:
        _setting = {}
    cd=max(1.0,float(_setting.get("cooldown", 1) or 1))
    if now-USER_COOLDOWN.get(("speaker_ai",key),0)<cd:
        return False

    memory_enabled=bool(_setting.get('memory_enabled', 1))
    memory_limit=int(_setting.get('memory_limit', 20) or 20)
    ai_enabled=bool(_setting.get('ai_enabled', 0))

    # این پاسخ‌های محلی باعث می‌شوند سخنگو حتی در صورت کندی/قطعی API
    # هم تقریباً فوری جواب بدهد.
    quick_replies=[
        'هاپ 😄 چی شد؟',
        'جانم؟ 🐾',
        'بیل بیلک اینجاست 😎',
        'خب خب، ادامه بده 😂',
        'شنیدم 👀',
        'اوهو! جالب شد 😄',
        'آره، دارم گوش میدم 🐾',
        'چی میگی رفیق؟ 😂',
        'حواسم هست 😎',
        'هاپ هاپ! 🐶',
        'عه! 😄',
        'بگو ببینم چی شده؟ 👀',
        'من آماده‌ام 😎',
        'اینجام رفیق 🐾',
        'خب؟ 😄'
    ]

    if memory_enabled:
        await _speaker_memory_add(msg.chat.id,'user',text,msg.from_user.id,display_name(msg.from_user),memory_limit)

    ans=None
    if ai_enabled:
        try:
            ans=await _speaker_ai_call(
                text,getattr(msg.chat,"title",""),getattr(msg.from_user,"username",""),
                setting['ai_verbosity'] if 'ai_verbosity' in setting.keys() else 'short',
                setting['ai_tone'] if 'ai_tone' in setting.keys() else 'polite',
                chat_id=msg.chat.id,memory_enabled=memory_enabled,
                memory_limit=memory_limit,timeout=0.85
            )
        except Exception as e:
            log.warning('speaker fast ai reply: %s',e)

    if not ans:
        ans=random.choice(quick_replies)

    if memory_enabled:
        await _speaker_memory_add(msg.chat.id,'assistant',ans,0,'بیل بیلک',memory_limit)
    USER_COOLDOWN[("speaker_ai",key)]=time.monotonic()
    await msg.reply_text(ans)
    return True

async def speaker_text(update, context):
    msg=update.effective_message
    chat=update.effective_chat
    user=update.effective_user
    if not msg or not chat or chat.type=='private' or not user:
        return False
    text=msg.text or ''
    if not text or text.startswith('/'):
        return False
    await _speaker_schema()
    t=_speaker_clean_question(text)
    if not t: return False
    # Admin configuration commands
    admin=await is_admin(update,user.id)
    if admin and t in {'سخنگو روشن','سخنگو خاموش'}:
        val=1 if t.endswith('روشن') else 0
        await DBX.execute('INSERT INTO speaker_settings(chat_id,enabled,updated_at) VALUES(?,?,?) ON CONFLICT(chat_id) DO UPDATE SET enabled=excluded.enabled,updated_at=excluded.updated_at',(chat.id,val,now_ts()))
        await msg.reply_text('💬 سخنگوی بیل بیلک '+('روشن شد 🟢' if val else 'خاموش شد ⚪'))
        return True
    if admin and t.startswith('تنظیم چت '):
        question=t[len('تنظیم چت '):].strip()
        reply=msg.reply_to_message
        if not question or not reply:
            await msg.reply_text('❌ برای «تنظیم چت» باید روی پاسخ موردنظر ریپلای کنی.'); return True
        media=_speaker_media_from_message(reply)
        if not media:
            await msg.reply_text('❌ این نوع پیام برای پاسخ سخنگو پشتیبانی نمی‌شود.'); return True
        typ,fid,content=media
        await DBX.execute('INSERT INTO speaker_global_chats(question,answer_type,answer_text,file_id,caption,source_chat_id,created_by,created_at) VALUES(?,?,?,?,?,?,?,?)',(question,typ,content if typ=='text' else '',fid,content if typ!='text' else '',chat.id,user.id,now_ts()))
        await DBX.execute('INSERT OR IGNORE INTO speaker_settings(chat_id) VALUES(?)',(chat.id,))
        await msg.reply_text(f'✅ پاسخ برای «{question}» در دیتابیس سراسری ربات ثبت شد.\n🌍 این پاسخ از این به بعد برای همه گروه‌ها قابل استفاده است. نوع: {typ}')
        return True
    if admin and t.startswith('حذف چت ربات '):
        question=t[len('حذف چت ربات '):].strip()
        await DBX.execute('DELETE FROM speaker_global_chats WHERE question=?',(question,))
        await msg.reply_text(f'🗑 همه پاسخ‌های سراسری «{question}» حذف شدند.')
        return True
    if admin and t.startswith('حذف چت '):
        question=t[len('حذف چت '):].strip(); reply=msg.reply_to_message
        if reply:
            media=_speaker_media_from_message(reply)
            rows=await DBX.execute('SELECT id,answer_type,file_id,answer_text,caption FROM speaker_global_chats WHERE question=? ORDER BY id DESC',(question,),fetch=True)
            deleted=False
            for r in rows:
                if media and r['answer_type']==media[0] and (r['file_id'] or '')==(media[1] or '') and (r['answer_text'] or r['caption'] or '')==(media[2] or ''):
                    await DBX.execute('DELETE FROM speaker_global_chats WHERE id=?',(r['id'],)); deleted=True; break
            await msg.reply_text('✅ پاسخ سراسری ریپلای‌شده حذف شد.' if deleted else '❌ پاسخ موردنظر پیدا نشد.')
        else:
            await DBX.execute('DELETE FROM speaker_global_chats WHERE question=?',(question,)); await msg.reply_text('🗑 پاسخ‌های سراسری سؤال حذف شدند.')
        return True
    if admin and t=='لیست چت':
        rows=await DBX.execute('SELECT question,COUNT(*) n FROM speaker_global_chats GROUP BY question ORDER BY MAX(id) DESC LIMIT 100',fetch=True)
        text='💬 <b>فهرست سراسری چت‌های سخنگو</b>\n\n'+('\n'.join(f'• {safe_text(r["question"],60)} — {r["n"]} پاسخ' for r in rows) if rows else 'هنوز سؤالی ثبت نشده.')
        await msg.reply_text(text,parse_mode='HTML'); return True
    if admin and t=='پاکسازی لیست چت':
        await DBX.execute('DELETE FROM speaker_global_chats'); await msg.reply_text('🧹 کل فهرست سراسری چت سخنگو پاک شد.'); return True
    if admin and t in {'سخنگو هوش روشن','سخنگو هوش خاموش','سخنگو پرحرف','سخنگو کم حرف','سخنگو کم‌حرف','سخنگو مودب','سخنگو بی ادب','سخنگو بی‌ادب','سخنگو حافظه روشن','سخنگو حافظه خاموش','پاکسازی حافظه سخنگو','حافظه سخنگو','وضعیت سخنگو'}:
        row=await _speaker_setting(chat.id)
        if t=='وضعیت سخنگو':
            mem_count=await DBX.execute('SELECT COUNT(*) n FROM speaker_memory WHERE chat_id=?',(chat.id,),fetch=True)
            count=int(mem_count[0]['n']) if mem_count else 0
            await msg.reply_text(f"💬 <b>وضعیت سخنگو</b>\n\nهوش مصنوعی: {'🟢 روشن' if row.get('ai_enabled',0) else '⚪ خاموش'}\nحالت پاسخ: {'📖 پرحرف' if row.get('ai_verbosity')=='long' else '⚡ کم‌حرف'}\nلحن: {'😏 شوخ/بی‌ادب ملایم' if row.get('ai_tone')=='rude' else '🙂 مودب'}\nحافظه مکالمه: {'🟢 روشن' if row.get('memory_enabled',1) else '⚪ خاموش'}\nپیام‌های ذخیره‌شده: <b>{count}</b> / {row.get('memory_limit',20) or 20}",parse_mode='HTML'); return True
        if t=='حافظه سخنگو':
            count=await DBX.execute('SELECT COUNT(*) n FROM speaker_memory WHERE chat_id=?',(chat.id,),fetch=True)
            n=int(count[0]['n']) if count else 0
            await msg.reply_text(f'🧠 حافظه این گروه: <b>{n}</b> پیام از حداکثر <b>{row.get("memory_limit",20) or 20}</b> پیام اخیر.',parse_mode='HTML'); return True
        if t=='پاکسازی حافظه سخنگو':
            await _speaker_memory_clear(chat.id); await msg.reply_text('🧹 حافظه مکالمه سخنگوی این گروه کاملاً پاک شد.'); return True
        updates={}
        if t.endswith('هوش روشن'): updates['ai_enabled']=1
        elif t.endswith('هوش خاموش'): updates['ai_enabled']=0
        elif t.endswith('حافظه روشن'): updates['memory_enabled']=1
        elif t.endswith('حافظه خاموش'): updates['memory_enabled']=0
        elif t.endswith('پرحرف'): updates['ai_verbosity']='long'
        elif t.endswith('کم حرف') or t.endswith('کم‌حرف'): updates['ai_verbosity']='short'
        elif t.endswith('مودب'): updates['ai_tone']='polite'
        elif t.endswith('بی ادب') or t.endswith('بی‌ادب'): updates['ai_tone']='rude'
        await DBX.execute(f"UPDATE speaker_settings SET {','.join(k+'=?' for k in updates)},updated_at=? WHERE chat_id=?",list(updates.values())+[now_ts(),chat.id])
        await msg.reply_text('✅ تنظیم سخنگوی AI انجام شد.'); return True
    if t.startswith('چت ربات '):
        question=t[len('چت ربات '):].strip()
        rows=await DBX.execute('SELECT * FROM speaker_global_chats WHERE question=? ORDER BY id',(question,),fetch=True)
        if not rows: await msg.reply_text('❌ برای این سؤال در دیتابیس سراسری پاسخی ثبت نشده.'); return True
        await msg.reply_text(f'💬 {question}\n\n🌍 تعداد پاسخ‌های سراسری: {len(rows)}')
        for r in rows: await _speaker_send_answer(msg,r)
        return True
    # Automatic reply
    setting=await _speaker_setting(chat.id)
    if not setting or not setting['enabled'] or user.is_bot:
        return False
    # All approved registrations are global; the current group's setting only
    # controls whether the speaker answers in that group.
    rows=await DBX.execute('SELECT * FROM speaker_global_chats', fetch=True)
    best=[]; best_score=0.0
    for r in rows:
        score=1.0 if _speaker_clean_question(r['question'])==t else _speaker_similarity(r['question'],t)
        if score>=0.84:
            if score>best_score: best_score=score; best=[r]
            elif abs(score-best_score)<0.03: best.append(r)
    if not best:
        # سخنگو در حالت روشن، حتی بدون سؤال از پیش ثبت‌شده هم پاسخ می‌دهد.
        try:
            if await _speaker_ai_reply(msg, setting): return True
        except Exception as e: log.warning('speaker reply: %s',e)
        return False
    cooldown=max(1.0,float(setting['cooldown'] or 3))
    key=(chat.id,user.id)
    last=USER_COOLDOWN.get(('speaker',key),0.0)
    now=time.monotonic()
    if now-last<cooldown: return False
    USER_COOLDOWN[('speaker',key)]=now
    row=random.choice(best) if setting['random_reply'] else best[0]
    await DBX.execute('UPDATE speaker_global_chats SET uses=uses+1 WHERE id=?',(row['id'],))
    await _speaker_send_answer(msg,row)
    return True

# Wrap the already-installed downloader router so speaker commands are handled
# before the old general router, without changing the other message pipeline.
_OLD_MESSAGE_ROUTER_SPEAKER = message_router_v10
async def message_router_v11(update, context):
    try:
        if await speaker_text(update, context):
            return
    except Exception as e:
        log.warning('speaker router: %s', e)
    return await _OLD_MESSAGE_ROUTER_SPEAKER(update, context)

# The final build function above looks up message_router_v10 when called. Replace
# that global with the speaker-aware wrapper; no other handlers are changed.
message_router_v10 = message_router_v11


# ================================================================
# 🎵 بخش مستقل «موزیکال» بیل‌بیلک
# ---------------------------------------------------------------
# این بخش عمداً در انتهای فایل قرار گرفته تا با بخش‌های قبلی تداخل
# نداشته باشد. جستجوی محتوا از اینترنت انجام می‌شود و چیزی به عنوان
# «آهنگ آماده داخل کد» تعریف نشده است.
#
# وابستگی‌های اختیاری:
#   pip install yt-dlp
#   pip install py-tgcalls
#
# نکته مهم: پخش واقعی داخل Voice Chat به MTProto/PyTgCalls و محیطی
# نیاز دارد که کتابخانه native مربوط به تماس صوتی را پشتیبانی کند.
# در Android/Pydroid3 ممکن است PyTgCalls در دسترس نباشد؛ در این حالت
# جستجوی آنلاین و ارسال فایل به چت همچنان فعال می‌ماند و ربات ادعای
# «پخش در کال» نمی‌کند.
# ================================================================

import asyncio as _music_asyncio
import json as _music_json
import os as _music_os
import re as _music_re
import tempfile as _music_tempfile
import time as _music_time
from pathlib import Path as _music_Path

try:
    import yt_dlp as _music_yt_dlp
except Exception:
    _music_yt_dlp = None

try:
    from pyrogram import Client as _MusicPyrogramClient
except Exception:
    _MusicPyrogramClient = None

try:
    from pytgcalls import PyTgCalls as _MusicPyTgCalls
    try:
        from pytgcalls.types import MediaStream as _MusicMediaStream
    except Exception:
        _MusicMediaStream = None
except Exception:
    _MusicPyTgCalls = None
    _MusicMediaStream = None

try:
    from pyrogram import Client as _MusicPyroClient
    from pyrogram.raw.functions.phone import CreateGroupCall as _MusicCreateGroupCall
    _MusicPyro_AVAILABLE = True
except Exception:
    _MusicPyroClient = None
    _MusicCreateGroupCall = None
    _MusicPyro_AVAILABLE = False

MUSIC_ENABLED = True
MUSIC_MAX_DOWNLOAD_MB = int(_music_os.getenv('MUSIC_MAX_DOWNLOAD_MB', '80'))
MUSIC_SEARCH_LIMIT = 5
MUSIC_TMP_DIR = _music_Path(_music_os.getenv('MUSIC_TMP_DIR', _music_tempfile.gettempdir())) / 'bilbilak_music'
MUSIC_TMP_DIR.mkdir(parents=True, exist_ok=True)
MUSIC_VC_AVAILABLE = bool(_MusicPyTgCalls and _MusicMediaStream and _MusicPyro_AVAILABLE)
MUSIC_VC_CLIENT = None
MUSIC_VC_ENGINE = None
MUSIC_VC_STARTED = False
MUSIC_QUEUE = {}
MUSIC_CURRENT = {}
MUSIC_VC_LOCKS = {}
MUSIC_SEARCH_CACHE = {}


def _music_clean_query(value: str) -> str:
    """متن جستجوی موزیک را تمیز می‌کند."""
    value = (value or '').strip()
    value = _music_re.sub(r'\s+', ' ', value)
    return value[:300]


def _music_format_time(seconds) -> str:
    """ثانیه را به قالب دقیقه:ثانیه تبدیل می‌کند."""
    try:
        seconds = max(0, int(float(seconds or 0)))
    except Exception:
        seconds = 0
    return f'{seconds // 60:02d}:{seconds % 60:02d}'


def _music_progress(position, duration, width=14) -> str:
    """نوار پیشرفت متنی برای پیام پخش می‌سازد."""
    try:
        position = max(0, float(position or 0))
        duration = max(1, float(duration or 1))
    except Exception:
        position, duration = 0, 1
    filled = max(0, min(width, int(width * position / duration)))
    return '▰' * filled + '▱' * (width - filled)


def _music_ydl_options(*, audio_only=False, download=False):
    """تنظیمات yt-dlp را برای جستجو یا دریافت آنلاین آماده می‌کند."""
    if audio_only:
        fmt = 'bestaudio/best'
    else:
        fmt = 'bestvideo[height<=720]+bestaudio/best[height<=720]/best'
    return {
        'quiet': True,
        'no_warnings': True,
        'noplaylist': True,
        'format': fmt,
        'outtmpl': str(MUSIC_TMP_DIR / '%(id)s.%(ext)s'),
        'restrictfilenames': True,
        'geo_bypass': True,
        'skip_download': not download,
    }


async def _music_search_online(query: str, limit=MUSIC_SEARCH_LIMIT):
    """به‌صورت آنلاین در منبع عمومی جستجو می‌کند؛ نتیجه از اینترنت می‌آید."""
    query = _music_clean_query(query)
    if not query or _music_yt_dlp is None:
        return []
    key = query.lower()
    cached = MUSIC_SEARCH_CACHE.get(key)
    if cached and _music_time.time() - cached[0] < 120:
        return cached[1]

    def _search():
        opts = _music_ydl_options(audio_only=True, download=False)
        opts['extract_flat'] = True
        with _music_yt_dlp.YoutubeDL(opts) as ydl:
            data = ydl.extract_info(f'ytsearch{max(1, min(limit, 10))}:{query}', download=False)
        entries = data.get('entries') or []
        result = []
        for item in entries:
            if not item:
                continue
            result.append({
                'id': item.get('id'),
                'title': item.get('title') or 'بدون عنوان',
                'url': item.get('webpage_url') or item.get('url'),
                'duration': item.get('duration') or 0,
                'thumbnail': item.get('thumbnail'),
                'uploader': item.get('uploader') or '',
            })
        return result

    try:
        result = await _music_asyncio.to_thread(_search)
    except Exception as exc:
        log.warning('music online search failed: %s', exc)
        return []
    MUSIC_SEARCH_CACHE[key] = (_music_time.time(), result)
    return result


async def music_search(query: str):
    """رابط عمومی جستجوی آنلاین موزیک."""
    return await _music_search_online(query)


async def _music_download_online(url: str, audio_only=True):
    """محتوای عمومی انتخاب‌شده را موقتاً از اینترنت دریافت می‌کند."""
    if _music_yt_dlp is None:
        raise RuntimeError('yt-dlp نصب نیست.')
    url = (url or '').strip()
    if not url:
        raise ValueError('لینک خالی است.')

    folder = _music_Path(_music_tempfile.mkdtemp(prefix='bb_music_', dir=str(MUSIC_TMP_DIR)))
    try:
        def _download():
            opts = _music_ydl_options(audio_only=audio_only, download=True)
            opts['paths'] = {'home': str(folder)}
            opts['outtmpl'] = str(folder / '%(title).80s [%(id)s].%(ext)s')
            with _music_yt_dlp.YoutubeDL(opts) as ydl:
                info = ydl.extract_info(url, download=True)
                path = Path(ydl.prepare_filename(info))
                if not path.exists():
                    candidates = list(folder.glob('*'))
                    candidates = [x for x in candidates if x.is_file()]
                    if not candidates:
                        raise FileNotFoundError('فایل دریافت‌شده پیدا نشد.')
                    path = max(candidates, key=lambda x: x.stat().st_mtime)
                return info, path
        info, path = await _music_asyncio.to_thread(_download)
        size_mb = path.stat().st_size / (1024 * 1024)
        if size_mb > MUSIC_MAX_DOWNLOAD_MB:
            raise RuntimeError(f'فایل بزرگ‌تر از سقف {MUSIC_MAX_DOWNLOAD_MB}MB است.')
        return info, path, folder
    except Exception:
        import shutil as _music_shutil
        _music_shutil.rmtree(folder, ignore_errors=True)
        raise


async def _music_queue_add(chat_id, item):
    """یک آیتم را به صف هوشمند گروه اضافه می‌کند."""
    MUSIC_QUEUE.setdefault(chat_id, []).append(item)
    return len(MUSIC_QUEUE[chat_id])


async def get_queue(chat_id):
    """صف فعلی گروه را برمی‌گرداند."""
    return list(MUSIC_QUEUE.get(chat_id, []))


async def clear_queue(chat_id):
    """صف گروه را پاک می‌کند."""
    MUSIC_QUEUE[chat_id] = []


async def add_to_queue(chat_id, title, url, is_video=False, is_live=False,
                       requester_id=0, requester_name='', duration=0,
                       thumbnail=None):
    """آیتم استاندارد را به صف موزیکال اضافه می‌کند."""
    item = {
        'title': title,
        'url': url,
        'is_video': bool(is_video),
        'is_live': bool(is_live),
        'requester_id': requester_id,
        'requester_name': requester_name,
        'duration': duration or 0,
        'thumbnail': thumbnail,
        'added_at': _music_time.time(),
    }
    return await _music_queue_add(chat_id, item)


async def _music_init_voice_engine(bot_token: str):
    """راه‌اندازی موتور واقعی Voice Chat با خود حساب BOT در MTProto."""
    global MUSIC_VC_CLIENT, MUSIC_VC_ENGINE, MUSIC_VC_STARTED, MUSIC_VC_AVAILABLE
    if MUSIC_VC_STARTED:
        return True
    if not (_MusicPyro_AVAILABLE and _MusicPyTgCalls and _MusicMediaStream):
        MUSIC_VC_AVAILABLE = False
        log.warning("Music VC disabled: install pyrogram + tgcrypto + py-tgcalls.")
        return False
    api_id_raw = _music_os.getenv("TELEGRAM_API_ID", "").strip()
    api_hash = _music_os.getenv("TELEGRAM_API_HASH", "").strip()
    if not api_id_raw or not api_hash:
        MUSIC_VC_AVAILABLE = False
        log.warning("Music VC disabled: TELEGRAM_API_ID and TELEGRAM_API_HASH are required.")
        return False
    try:
        api_id = int(api_id_raw)
    except ValueError:
        MUSIC_VC_AVAILABLE = False
        log.warning("Music VC disabled: TELEGRAM_API_ID must be an integer.")
        return False
    try:
        MUSIC_VC_CLIENT = _MusicPyroClient("bilbilak_vc_bot", api_id=api_id, api_hash=api_hash, bot_token=bot_token, in_memory=True, workdir=str(MUSIC_TMP_DIR))
        await MUSIC_VC_CLIENT.start()
        MUSIC_VC_ENGINE = _MusicPyTgCalls(MUSIC_VC_CLIENT)
        result = MUSIC_VC_ENGINE.start()
        if hasattr(result, "__await__"):
            await result
        MUSIC_VC_STARTED = True
        MUSIC_VC_AVAILABLE = True
        log.info("Music Voice Chat engine started successfully.")
        return True
    except Exception as exc:
        log.exception("Music Voice Chat engine failed to start: %s", exc)
        MUSIC_VC_CLIENT = None; MUSIC_VC_ENGINE = None; MUSIC_VC_STARTED = False; MUSIC_VC_AVAILABLE = False
        return False


async def create_voice_call(chat_id):
    """اگر کال وجود نداشته باشد، با MTProto تلاش می‌کند Voice Chat بسازد."""
    if not MUSIC_VC_AVAILABLE or MUSIC_VC_ENGINE is None or MUSIC_VC_CLIENT is None:
        raise RuntimeError("موتور Voice Chat فعال نیست.")
    try:
        getter = getattr(MUSIC_VC_ENGINE, "get_active_call", None)
        if getter:
            result = getter(chat_id)
            if hasattr(result, "__await__"):
                result = await result
            if result:
                return result
    except Exception:
        pass
    try:
        peer = await MUSIC_VC_CLIENT.resolve_peer(chat_id)
        rnd = random.SystemRandom().randint(1, 2147483647)
        result = await MUSIC_VC_CLIENT.invoke(_MusicCreateGroupCall(peer=peer, random_id=rnd))
        log.info("Created Voice Chat in %s", chat_id)
        await _music_asyncio.sleep(1.0)
        return result
    except Exception as exc:
        raise RuntimeError("ساخت کال ناموفق بود؛ ربات باید دسترسی مناسب داشته باشد و گروه سوپرگروه باشد.") from exc


async def join_voice_call(chat_id, stream=None):
    """به کال وصل می‌شود و stream را پخش می‌کند."""
    if not MUSIC_VC_AVAILABLE or MUSIC_VC_ENGINE is None:
        raise RuntimeError("PyTgCalls فعال نیست.")
    if stream is None:
        raise RuntimeError("منبع پخش مشخص نشده است.")
    join = getattr(MUSIC_VC_ENGINE, "join_group_call", None)
    change = getattr(MUSIC_VC_ENGINE, "change_stream", None)
    if not join:
        raise RuntimeError("نسخه PyTgCalls تابع join_group_call ندارد.")
    try:
        calls = getattr(MUSIC_VC_ENGINE, "calls", {})
        result = change(chat_id, stream) if chat_id in calls and change else join(chat_id, stream)
        if hasattr(result, "__await__"):
            await result
        return True
    except Exception as exc:
        raise RuntimeError(f"اتصال/پخش در کال ناموفق بود: {exc}") from exc


async def ensure_voice_call(chat_id, stream=None):
    """کال را در صورت نیاز می‌سازد و سپس stream را پخش می‌کند."""
    if not MUSIC_VC_AVAILABLE or MUSIC_VC_ENGINE is None:
        return False
    try:
        active = False
        getter = getattr(MUSIC_VC_ENGINE, "get_active_call", None)
        if getter:
            try:
                result = getter(chat_id)
                if hasattr(result, "__await__"):
                    result = await result
                active = bool(result)
            except Exception:
                active = False
        if not active:
            await create_voice_call(chat_id)
        if stream is not None:
            await join_voice_call(chat_id, stream)
        return True
    except Exception as exc:
        log.warning("ensure voice call failed for %s: %s", chat_id, exc)
        return False


async def leave_voice_call(chat_id):
    """از کال خارج می‌شود، در صورت فعال بودن موتور واقعی."""
    if MUSIC_VC_ENGINE is None:
        return False
    try:
        fn = getattr(MUSIC_VC_ENGINE, 'leave_group_call', None)
        if fn:
            result = fn(chat_id)
            if hasattr(result, '__await__'):
                await result
        return True
    except Exception as exc:
        log.warning('music leave vc: %s', exc)
        return False


async def play_audio(chat_id, url, title='', thumbnail=None, add_to_queue=True):
    """پخش واقعی صوت: ساخت/اتصال کال + استریم آنلاین با PyTgCalls."""
    item = {'title': title or 'موزیک', 'url': url, 'is_video': False, 'is_live': False, 'requester_id': 0, 'requester_name': '', 'duration': 0, 'thumbnail': thumbnail}
    if add_to_queue:
        await _music_queue_add(chat_id, item)
    if not MUSIC_VC_AVAILABLE or MUSIC_VC_ENGINE is None or _MusicMediaStream is None:
        raise RuntimeError('موتور Voice Chat فعال نیست.')
    stream = _MusicMediaStream(url)
    if not await ensure_voice_call(chat_id, stream):
        raise RuntimeError('ساخت یا اتصال Voice Chat ناموفق بود.')
    MUSIC_CURRENT[chat_id] = {**item, 'started_at': _music_time.time(), 'position': 0}
    return len(MUSIC_QUEUE.get(chat_id, []))


async def play_video(chat_id, url, title='', thumbnail=None):
    """یک منبع ویدیویی عمومی را به صف اضافه می‌کند."""
    return await add_to_queue(chat_id, title or 'ویدیو', url, True, False, 0, '', 0, thumbnail)


async def play_live(chat_id, url, title='', thumbnail=None):
    """یک لایو عمومی را به صف اضافه می‌کند."""
    return await add_to_queue(chat_id, title or 'پخش زنده', url, False, True, 0, '', 0, thumbnail)


async def pause_call(chat_id):
    """پخش کال را متوقف موقت می‌کند."""
    if MUSIC_VC_ENGINE is None:
        return False
    fn = getattr(MUSIC_VC_ENGINE, 'pause', None) or getattr(MUSIC_VC_ENGINE, 'pause_stream', None)
    if not fn:
        return False
    result = fn(chat_id)
    if hasattr(result, '__await__'):
        await result
    return True


async def resume_call(chat_id):
    """پخش کال را ادامه می‌دهد."""
    if MUSIC_VC_ENGINE is None:
        return False
    fn = getattr(MUSIC_VC_ENGINE, 'resume', None) or getattr(MUSIC_VC_ENGINE, 'resume_stream', None)
    if not fn:
        return False
    result = fn(chat_id)
    if hasattr(result, '__await__'):
        await result
    return True


async def stop_call(chat_id):
    """پخش جاری را متوقف می‌کند."""
    MUSIC_CURRENT.pop(chat_id, None)
    if MUSIC_VC_ENGINE is None:
        return False
    fn = getattr(MUSIC_VC_ENGINE, 'leave_group_call', None)
    if fn:
        result = fn(chat_id)
        if hasattr(result, '__await__'):
            await result
        return True
    return False


async def skip_call(chat_id):
    """آیتم فعلی را حذف و پخش آیتم بعدی را فعال می‌کند."""
    MUSIC_CURRENT.pop(chat_id, None)
    return await play_next(chat_id)


async def change_volume(chat_id, volume):
    """مقدار صدای ذخیره‌شده را تغییر می‌دهد."""
    try:
        volume = max(0, min(200, int(volume)))
    except Exception:
        return False
    MUSIC_CURRENT.setdefault(chat_id, {})['volume'] = volume
    return True


async def play_next(chat_id):
    """آیتم بعدی صف را انتخاب می‌کند."""
    queue = MUSIC_QUEUE.get(chat_id) or []
    if not queue:
        return None
    item = queue.pop(0)
    item['started_at'] = _music_time.time()
    MUSIC_CURRENT[chat_id] = item
    return item


async def init_playback_state(chat_id, total_duration, file_path):
    """وضعیت اولیه تایمر پخش را ذخیره می‌کند."""
    state = MUSIC_CURRENT.setdefault(chat_id, {})
    state.update({'duration': total_duration or 0, 'file_path': str(file_path), 'position': 0, 'started_at': _music_time.time()})
    return state


async def get_current_position(chat_id):
    """موقعیت فعلی پخش را از زمان شروع محاسبه می‌کند."""
    state = MUSIC_CURRENT.get(chat_id)
    if not state:
        return 0
    if state.get('paused_at') is not None:
        return state.get('paused_at', 0)
    started = state.get('started_at') or _music_time.time()
    return max(0, _music_time.time() - started + float(state.get('position', 0) or 0))


async def update_playback_position(chat_id, new_position):
    """موقعیت پخش را به‌روزرسانی می‌کند."""
    state = MUSIC_CURRENT.setdefault(chat_id, {})
    state['position'] = max(0, float(new_position or 0))
    state['started_at'] = _music_time.time()
    return state


async def pause_playback(chat_id):
    """تایمر داخلی پخش را متوقف موقت می‌کند."""
    pos = await get_current_position(chat_id)
    state = MUSIC_CURRENT.get(chat_id)
    if not state:
        return False
    state['paused_at'] = pos
    return True


async def resume_playback(chat_id):
    """تایمر داخلی پخش را ادامه می‌دهد."""
    state = MUSIC_CURRENT.get(chat_id)
    if not state:
        return False
    state['position'] = state.get('paused_at', state.get('position', 0))
    state['paused_at'] = None
    state['started_at'] = _music_time.time()
    return True


async def clear_playback_state(chat_id):
    """وضعیت پخش جاری را حذف می‌کند."""
    MUSIC_CURRENT.pop(chat_id, None)


