async def search_youtube_live(query):
    """لایوهای عمومی یوتیوب را به‌صورت آنلاین جستجو می‌کند."""
    query = _music_clean_query(query)
    if not query or _music_yt_dlp is None:
        return []
    def _search():
        opts = _music_ydl_options(audio_only=False, download=False)
        opts['extract_flat'] = True
        opts['noplaylist'] = True
        with _music_yt_dlp.YoutubeDL(opts) as ydl:
            data = ydl.extract_info(f'ytsearch{MUSIC_SEARCH_LIMIT}:{query} live', download=False)
        return [
            {'title': x.get('title'), 'url': x.get('webpage_url') or x.get('url'), 'duration': x.get('duration')}
            for x in (data.get('entries') or []) if x
        ]
    try:
        return await _music_asyncio.to_thread(_search)
    except Exception as exc:
        log.warning('youtube live search failed: %s', exc)
        return []


