async def _music_send_results(message, results, query):
    """نتایج جستجو را با دکمه‌های متنی نمایش می‌دهد؛ انتخاب با دستور انجام می‌شود."""
    if not results:
        await message.reply_text('❌ نتیجه‌ای از جستجوی آنلاین پیدا نشد یا موتور جستجو نصب نیست.')
        return
    lines = [
        '🎵 <b>نتایج آنلاین موزیکال</b>',
        '══════════════════════',
        f'🔎 <b>{safe_text(query, 100)}</b>',
        ''
    ]
    for i, item in enumerate(results, 1):
        lines.append(f'🟢 <b>{i}.</b> {safe_text(item.get("title") or "بدون عنوان", 100)}')
        lines.append(f'   ⏱ {_music_format_time(item.get("duration"))}')
    lines += ['', '▶️ برای پخش بنویس: پخش آهنگ 1']
    await message.reply_text('\n'.join(lines), parse_mode='HTML')


async def _music_handle_text(update, context):
    """دستورات بدون اسلش موزیکال را پردازش می‌کند."""
    msg = update.effective_message
    chat = update.effective_chat
    user = update.effective_user
    if not msg or not chat or not user or not msg.text:
        return False
    raw = msg.text.strip()
    if not raw or raw.startswith('/'):
        return False
    low = _music_clean_query(raw).lower()

    if low in {'موزیکال', 'music', 'موزیک'}:
        await msg.reply_text(
            '🎵 <b>موزیکال بیل‌بیلک</b>\n'
            '══════════════════════\n'
            '🔎 پخش آهنگ نام آهنگ\n'
            '🎬 پخش فیلم نام\n'
            '📺 لایو نام\n'
            '📻 رادیو نام\n'
            '⚽ فوتبال نام تیم\n'
            '🎧 صف  بعدی  مکث  ادامه  توقف\n'
            '🔊 صدا 80\n'
            '📋 پلی‌لیست',
            parse_mode='HTML')
        return True

    m = _music_re.match(r'^(?:پخش آهنگ|play song)\s+(.+)$', raw, _music_re.I)
    if m:
        query = _music_clean_query(m.group(1))
        # انتخاب عددی از آخرین نتایج کاربر/گروه
        if query.isdigit() and f'{chat.id}:last' in MUSIC_SEARCH_CACHE:
            return await _music_play_cached_number(msg, chat.id, int(query))
        results = await music_search(query)
        if not results:
            await msg.reply_text('❌ جستجوی آنلاین نتیجه‌ای نداشت. مطمئن شو yt-dlp نصب است.')
            return True
        MUSIC_SEARCH_CACHE[f'{chat.id}:last'] = results
        # جستجو را خود بیل‌بیلک انجام می‌دهد؛ انتخاب و پخش واقعی توسط حساب شخصی انجام می‌شود.
        MUSIC_SEARCH_CACHE[f'{chat.id}:last'] = results
        rows = []
        for i, item in enumerate(results[:10], 1):
            title = safe_text(item.get('title') or 'بدون عنوان', 48)
            duration = _music_format_time(item.get('duration'))
            rows.append([btn(f'🎵 {i}. {title} • {duration}', f'mplay:{chat.id}:{i}')])
        rows.append([btn('🔄 جستجوی دوباره', f'msearch:{chat.id}')])
        await msg.reply_text(
            f'🔎 <b>نتایج جستجوی بیل‌بیلک</b>\n\n🎵 عبارت: <b>{safe_text(query, 100)}</b>\n\n'
            'یکی از نتایج را بزن؛ همان لحظه حساب شخصی موزیکال وارد Voice Chat می‌شود و پخش را شروع می‌کند.',
            parse_mode='HTML', reply_markup=keyboard(rows))
        return True

    m = _music_re.match(r'^(?:پخش فیلم|play video)\s+(.+)$', raw, _music_re.I)
    if m:
        query = _music_clean_query(m.group(1))
        results = await music_search(query)
        if results:
            item = results[0]
            await add_to_queue(chat.id, item['title'], item['url'], True, False, user.id, user.first_name or '', item.get('duration', 0), item.get('thumbnail'))
            await msg.reply_text(f'🎬 در صف قرار گرفت:\n<b>{safe_text(item["title"], 120)}</b>', parse_mode='HTML')
        else:
            await msg.reply_text('❌ ویدیو پیدا نشد.')
        return True

    m = _music_re.match(r'^(?:لایو|live)\s+(.+)$', raw, _music_re.I)
    if m:
        results = await search_youtube_live(m.group(1))
        if results:
            item = results[0]
            await play_live(chat.id, item['url'], item.get('title') or 'YouTube Live')
            await msg.reply_text(f'📺 لایو آنلاین در صف قرار گرفت:\n<b>{safe_text(item.get("title"), 120)}</b>', parse_mode='HTML')
        else:
            await msg.reply_text('❌ لایو عمومی پیدا نشد.')
        return True

    if low in {'صف', 'queue'}:
        queue = await get_queue(chat.id)
        if not queue:
            await msg.reply_text('📋 صف موزیکال خالی است.')
        else:
            text = '📋 <b>صف موزیکال</b>\n══════════════════════\n'
            text += '\n'.join(f'{i}. 🎵 {safe_text(x.get("title"), 100)}' for i, x in enumerate(queue, 1))
            await msg.reply_text(text, parse_mode='HTML')
        return True

    if low in {'بعدی', 'skip'}:
        item = await skip_call(chat.id)
        await msg.reply_text('⏭️ '+(f'رفتم سراغ: <b>{safe_text(item.get("title"), 100)}</b>' if item else 'صف تمام شد.'), parse_mode='HTML')
        return True

    if low in {'مکث', 'pause'}:
        ok = await pause_playback(chat.id)
        if MUSIC_VC_ENGINE:
            try: await pause_call(chat.id)
            except Exception: pass
        await msg.reply_text('⏸️ پخش مکث شد.' if ok else '❌ چیزی در حال پخش نیست.')
        return True

    if low in {'ادامه', 'resume'}:
        ok = await resume_playback(chat.id)
        if MUSIC_VC_ENGINE:
            try: await resume_call(chat.id)
            except Exception: pass
        await msg.reply_text('▶️ پخش ادامه پیدا کرد.' if ok else '❌ پخش فعالی نداریم.')
        return True

    if low in {'توقف', 'stop'}:
        await stop_call(chat.id)
        await clear_queue(chat.id)
        await msg.reply_text('⏹️ پخش و صف پاک شد.')
        return True

    m = _music_re.match(r'^(?:صدا|volume)\s+(\d{1,3})$', raw, _music_re.I)
    if m:
        value = int(m.group(1))
        ok = await change_volume(chat.id, value)
        await msg.reply_text(f'🔊 صدا روی <b>{value}%</b> تنظیم شد.' if ok else '❌ مقدار صدا نامعتبر است.', parse_mode='HTML')
        return True

    if low in {'پلی‌لیست', 'playlist'}:
        names = await get_all_playlists(user.id)
        await msg.reply_text('📋 <b>پلی‌لیست‌ها</b>\n' + ('\n'.join('• '+safe_text(x, 80) for x in names) if names else 'هنوز پلی‌لیستی ساخته نشده.'), parse_mode='HTML')
        return True

    return False


async def _music_play_cached_number(message, chat_id, number):
    """شماره نتیجه آخر را به صف اضافه می‌کند."""
    results = MUSIC_SEARCH_CACHE.get(f'{chat_id}:last') or []
    if not 1 <= number <= len(results):
        await message.reply_text('❌ شماره نتیجه معتبر نیست.')
        return True
    item = results[number - 1]
    await add_to_queue(chat_id, item['title'], item['url'], False, False,
                       message.from_user.id if message.from_user else 0,
                       message.from_user.first_name if message.from_user else '',
                       item.get('duration', 0), item.get('thumbnail'))
    await message.reply_text(
        f'✅ <b>{safe_text(item["title"], 120)}</b>\n'
        f'🎵 به صف آنلاین اضافه شد.\n'
        f'📋 جایگاه: {len(MUSIC_QUEUE.get(chat_id, []))}', parse_mode='HTML')
    return True


