async def bb_fetch_json(url, timeout=10):
    if not _BBURLREQ:
        return None
    def _load():
        req = _BBURLREQ.Request(url, headers={"User-Agent": "BilBilak/4.0"})
        with _BBURLREQ.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read().decode("utf-8", "ignore"))
    try:
        return await asyncio.to_thread(_load)
    except Exception as exc:
        log.warning("sports request failed: %s", exc)
        return None


async def bb_live_sports_text(sport="all"):
    # ESPN's public scoreboard endpoints are used only as a live-data source.
    # If unavailable, the bot clearly reports that live data is temporarily down.
    sports = ["soccer", "basketball", "tennis", "football", "hockey", "baseball", "racing", "rugby"] if sport == "all" else [sport]
    lines = ["🏟️ <b>نتایج زنده ورزش</b>", "══════════════════════"]
    found = 0
    for sp in sports:
        data = await bb_fetch_json(f"https://site.api.espn.com/apis/site/v2/sports/{sp}/scoreboard")
        if not data:
            continue
        events = data.get("events") or []
        for ev in events[:8]:
            comp = (ev.get("competitions") or [{}])[0]
            competitors = comp.get("competitors") or []
            if len(competitors) < 2:
                continue
            a, b = competitors[0], competitors[1]
            an = safe_text((a.get("team") or {}).get("displayName", "تیم ۱"), 45)
            bn = safe_text((b.get("team") or {}).get("displayName", "تیم ۲"), 45)
            av = a.get("score", "-"); bv = b.get("score", "-")
            status = safe_text((ev.get("status") or {}).get("type", {}).get("shortDetail", "زنده/برنامه"), 40)
            lines.append(f"\n🟢 <b>{an}</b>  {av}  —  {bv}  <b>{bn}</b>\n   ⏱ {status}")
            found += 1
    if not found:
        lines.append("\n🟡 فعلاً رویداد زنده‌ای از منبع داده دریافت نشد یا سرویس موقتاً در دسترس نیست.")
    lines.append("\n🔄 برای تازه‌ترین وضعیت، دکمه «تازه‌سازی» را بزن.")
    return "\n".join(lines)


async def bb_convert_voice_to_text(msg):
    if not _BBSR or not _bb_subprocess:
        return "⚠️ تبدیل ویس به متن روی این سرور فعال نیست. نصب پیشنهادی: SpeechRecognition و ffmpeg."
    voice = msg.voice or msg.audio
    if not voice:
        return "🎙️ روی یک ویس/فایل صوتی ریپلای کن."
    src = Path(tempfile.gettempdir()) / f"bb_voice_{msg.message_id}.ogg"
    wav = Path(tempfile.gettempdir()) / f"bb_voice_{msg.message_id}.wav"
    try:
        tgfile = await msg.get_bot().get_file(voice.file_id)
        await tgfile.download_to_drive(str(src))
        proc = await asyncio.create_subprocess_exec("ffmpeg", "-y", "-i", str(src), "-ar", "16000", "-ac", "1", str(wav), stdout=asyncio.subprocess.DEVNULL, stderr=asyncio.subprocess.DEVNULL)
        await proc.communicate()
        if proc.returncode != 0:
            return "⚠️ ffmpeg روی سرور پیدا نشد؛ تبدیل ویس فعلاً فعال نیست."
        rec = _BBSR.Recognizer()
        with _BBSR.AudioFile(str(wav)) as source:
            audio = rec.record(source)
        try:
            text = await asyncio.to_thread(rec.recognize_google, audio, "fa-IR")
        except Exception:
            text = await asyncio.to_thread(rec.recognize_google, audio, "en-US")
        return f"📝 <b>متن ویس:</b>\n\n{safe_text(text, 3500)}"
    except Exception as exc:
        log.warning("voice->text: %s", exc)
        return "❌ نتونستم این ویس رو به متن تبدیل کنم. ویس واضح‌تر یا کوتاه‌تر بفرست."
    finally:
        for f in (src, wav):
            try: f.unlink(missing_ok=True)
            except Exception: pass


async def bb_convert_photo_to_text(msg):
    if not _BBImage or not _BBTesseract:
        return "⚠️ OCR روی این سرور فعال نیست. برای عکس→متن، Pillow و pytesseract به‌همراه موتور Tesseract لازم است."
    photo = msg.photo[-1] if msg.photo else None
    if not photo:
        return "🖼️ روی یک عکس ریپلای کن."
    path = Path(tempfile.gettempdir()) / f"bb_ocr_{msg.message_id}.jpg"
    try:
        tgfile = await msg.get_bot().get_file(photo.file_id)
        await tgfile.download_to_drive(str(path))
        img = _BBImage.open(path)
        text = await asyncio.to_thread(_BBTesseract.image_to_string, img, lang="fas+eng")
        text = text.strip()
        return f"📝 <b>متن استخراج‌شده:</b>\n\n{safe_text(text, 4000)}" if text else "🟡 متنی در عکس پیدا نکردم."
    except Exception as exc:
        log.warning("photo->text: %s", exc)
        return "❌ OCR این عکس ناموفق بود."
    finally:
        try: path.unlink(missing_ok=True)
        except Exception: pass


async def bb_text_to_voice(msg, text):
    if not _BBGTTS:
        await msg.reply_text("⚠️ متن→ویس فعال نیست. روی VPS نصب کن: pip install gTTS", parse_mode="HTML")
        return True
    text = safe_text(text, 3000)
    if not text:
        await msg.reply_text("📝 متن را بعد از «متن به ویس» بفرست.")
        return True
    path = Path(tempfile.gettempdir()) / f"bb_tts_{msg.message_id}.mp3"
    try:
        await asyncio.to_thread(lambda: _BBGTTS(text=text, lang="fa").save(str(path)))
        with open(path, "rb") as f:
            await msg.reply_voice(f, caption="🎙️ متن به ویس تبدیل شد")
    except Exception as exc:
        log.warning("text->voice: %s", exc)
        await msg.reply_text("❌ تبدیل متن به ویس انجام نشد.")
    finally:
        try: path.unlink(missing_ok=True)
        except Exception: pass
    return True


async def bb_text_to_image(msg, text):
    if not _BBImage or not _BBImageDraw:
        await msg.reply_text("⚠️ متن→عکس فعال نیست. روی VPS نصب کن: pip install Pillow", parse_mode="HTML")
        return True
    text = safe_text(text, 1200)
    if not text:
        await msg.reply_text("📝 متن را بعد از «متن به عکس» بفرست.")
        return True
    path = Path(tempfile.gettempdir()) / f"bb_card_{msg.message_id}.png"
    try:
        img = _BBImage.new("RGB", (1080, 700), (28, 30, 40))
        draw = _BBImageDraw.Draw(img)
        draw.text((70, 70), "🐾 بیل‌بیلک", fill=(255, 255, 255))
        # Basic wrapping keeps this dependency-free; Persian shaping depends on the installed font.
        words = text.split(); lines=[]; line=""
        for w in words:
            if len(line)+len(w)+1 > 38:
                lines.append(line); line=w
            else: line=(line+" "+w).strip()
        if line: lines.append(line)
        y=170
        for ln in lines[:16]:
            draw.text((70,y), ln, fill=(235,235,235)); y+=32
        img.save(path)
        with open(path,"rb") as f:
            await msg.reply_photo(f, caption="🎨 متن به کارت تصویری تبدیل شد")
    except Exception as exc:
        log.warning("text->image: %s", exc)
        await msg.reply_text("❌ ساخت تصویر انجام نشد.")
    finally:
        try: path.unlink(missing_ok=True)
        except Exception: pass
    return True


