async def bb_tool_callback(q, context):
    parts=(q.data or "").split(":",2)
    if len(parts)!=3 or parts[0] not in {"tool","sport"} or not parts[1].isdigit() or int(parts[1])!=q.from_user.id:
        return False
    uid=q.from_user.id; action=parts[2]
    if parts[0]=="tool":
        if action=="home":
            await q.edit_message_text("🧰 <b>ابزارهای خفن بیل‌بیلک</b>\n\nتبدیل رسانه، ورزش زنده و مکانیابی اینجاست 👇", parse_mode="HTML", reply_markup=bb_tools_keyboard(uid)); return True
        if action in BB_CONVERTER_MODES:
            context.user_data["bb_convert_mode"] = action
            titles={"voice_text":"🎙️ ویس ➜ متن","photo_text":"🖼️ عکس ➜ متن","text_voice":"📝 متن ➜ ویس","text_image":"🎨 متن ➜ عکس"}
            examples={"voice_text":"یک ویس بفرست.","photo_text":"یک عکس بفرست.","text_voice":"حالا متن موردنظر را در پیام بعدی بفرست.","text_image":"حالا متن کارت تصویری را در پیام بعدی بفرست."}
            await q.edit_message_text(f"{titles[action]}\n\n{examples[action]}\n\n🔙 از دکمه برگشت برای لغو استفاده کن.", parse_mode="HTML", reply_markup=keyboard([[btn("🔙 ابزارها",f"tool:{uid}:home")]])); return True
        if action=="sports":
            await q.edit_message_text("🏟️ <b>مرکز ورزش زنده</b>\n\nنتایج زنده از رشته‌های مختلف را بررسی کن. اگر منبع زنده موقتاً قطع باشد، نتیجه ساختگی نمایش داده نمی‌شود.",parse_mode="HTML",reply_markup=bb_sports_keyboard(uid)); return True
        if action=="location":
            await q.edit_message_text("📍 مکانیابی در گفت‌وگوی خصوصی فعال می‌شود. در پیوی روی «ارسال موقعیت من» بزن.",parse_mode="HTML",reply_markup=keyboard([[btn("📍 درخواست موقعیت",f"tool:{uid}:location_request")],[btn("🔙 ابزارها",f"tool:{uid}:home")]])); return True
        if action=="location_request":
            await q.answer("درخواست موقعیت فقط در پیوی ارسال می‌شود.",show_alert=True)
            await bb_location_request(q.message)
            return True
    if parts[0]=="sport":
        await q.answer("در حال دریافت نتایج زنده…")
        text=await bb_live_sports_text(action)
        await q.edit_message_text(text,parse_mode="HTML",reply_markup=bb_sports_keyboard(uid)); return True
    return False


async def bb_hapoo_callback(q, context):
    parts=(q.data or "").split(":",2)
    if len(parts)!=3 or parts[0]!="dogx" or not parts[1].isdigit() or int(parts[1])!=q.from_user.id:
        return False
    uid=q.from_user.id; action=parts[2]; u=await DBX.get_user(uid)
    if action=="home":
        await q.edit_message_text(f"🐾 <b>باشگاه هاپویی</b>\n\n🐕 {safe_text(u['dog_name'])}\n⭐ سطح هاپو: <b>{u['dog_level']}</b>\n🦴 استخوان: <b>{u['bones']}</b>\n🏆 بردها: <b>{u['wins']}</b>\n\nهاپو فقط یک اسم نیست؛ XP، سطح، فروشگاه تزئینی، مأموریت و آمار خودش را دارد!",parse_mode="HTML",reply_markup=keyboard([[btn("🐾 هاپ هاپ",f"dogx:{uid}:hop")],[btn("🛍️ فروشگاه هاپو",f"dogx:{uid}:shop"),btn("📊 آمار هاپو",f"dogx:{uid}:stats")],[btn("✏️ تغییر اسم",f"dog:{uid}:name")],[btn("📚 راهنما",f"help:{uid}:dog"),btn("🔙 پنل",user_cb(uid,"home"))]])); return True
    if action=="hop":
        ok,wait,xp_gain,bone_gain,new_xp,dog_level=await DBX.hop(uid)
        if not ok:
            await q.answer(f"⏳ هنوز {wait//60}:{wait%60:02d} تا هاپ بعدی مانده.",show_alert=True); return True
        await q.edit_message_text(f"🐾 <b>هاپ هاپ!</b>\n\n⭐ +{xp_gain} XP\n🦴 +{bone_gain} استخوان\n🐕 سطح هاپو: <b>{dog_level}</b>\n\nهاپو امروز حسابی فعال بود! 😄",parse_mode="HTML",reply_markup=keyboard([[btn("🐾 دوباره",f"dogx:{uid}:hop")],[btn("🛍️ فروشگاه",f"dogx:{uid}:shop"),btn("📊 آمار",f"dogx:{uid}:stats")],[btn("🔙 هاپویی",f"dogx:{uid}:home")]])); return True
    if action=="stats":
        await q.edit_message_text(f"📊 <b>آمار هاپو</b>\n\n🐕 اسم: <b>{safe_text(u['dog_name'])}</b>\n⭐ سطح: <b>{u['dog_level']}</b>\n✨ XP کاربر: <b>{u['xp']}</b>\n🦴 استخوان: <b>{u['bones']}</b>\n🐾 تعداد بازی‌ها: <b>{u['games']}</b>\n🏆 برد: <b>{u['wins']}</b>",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 هاپویی",f"dogx:{uid}:home")]])); return True
    if action=="shop":
        rows=[[btn(f"{name} — {price}🦴",f"shop:{uid}:buy:{key}")] for key,(name,price) in SHOP_ITEMS.items()]
        rows.append([btn("🔙 هاپویی",f"dogx:{uid}:home")])
        await q.edit_message_text("🛍️ <b>فروشگاه هاپو</b>\n\nآیتم‌ها فقط تزئینی‌اند و با استخوان داخل ربات خریداری می‌شوند.",parse_mode="HTML",reply_markup=keyboard(rows)); return True
    return False


