async def message_router_v13(update, context):
    msg=update.effective_message
    if msg and update.effective_user:
        mode=context.user_data.get("bb_convert_mode")
        if mode=="voice_text" and (msg.voice or msg.audio):
            context.user_data.pop("bb_convert_mode",None)
            await msg.reply_text("⏳ دارم ویس رو به متن تبدیل می‌کنم…")
            await msg.reply_text(await bb_convert_voice_to_text(msg),parse_mode="HTML")
            return
        if mode=="photo_text" and msg.photo:
            context.user_data.pop("bb_convert_mode",None)
            await msg.reply_text("⏳ دارم متن عکس رو استخراج می‌کنم…")
            await msg.reply_text(await bb_convert_photo_to_text(msg),parse_mode="HTML")
            return
        if mode=="text_voice" and msg.text and not msg.text.startswith("/"):
            context.user_data.pop("bb_convert_mode",None)
            await bb_text_to_voice(msg,msg.text)
            return
        if mode=="text_image" and msg.text and not msg.text.startswith("/"):
            context.user_data.pop("bb_convert_mode",None)
            await bb_text_to_image(msg,msg.text)
            return
    t=normalize(msg.text or "") if msg else ""
    if t in {"ابزارها","ابزار","tools"}:
        await msg.reply_text("🧰 <b>ابزارهای خفن بیل‌بیلک</b>",parse_mode="HTML",reply_markup=bb_tools_keyboard(update.effective_user.id)); return
    if t in {"ورزش زنده","نتایج زنده","ورزش","live sports"}:
        await msg.reply_text("🏟️ <b>ورزش زنده</b>",parse_mode="HTML",reply_markup=bb_sports_keyboard(update.effective_user.id)); return
    if t in {"مکانیابی","لوکیشن","موقعیت"}:
        await msg.reply_text("📍 <b>جستجوی مکان</b>\n\nاسم مکان را بفرست یا بنویس: <b>برج ایفل کجاست؟</b>\nمکان پیدا می‌شود و مستقیم روی نقشه نمایش داده می‌شود.", parse_mode="HTML"); return
    if t in {"هاپویی","هاپو","باشگاه هاپو"}:
        await msg.reply_text("🐾 <b>باشگاه هاپویی</b>",parse_mode="HTML",reply_markup=keyboard([[btn("🐾 ورود به هاپویی",f"dogx:{update.effective_user.id}:home")]])); return
    if t in {"تبدیل ویس","ویس به متن"}:
        context.user_data["bb_convert_mode"]="voice_text"; await msg.reply_text("🎙️ حالا ویس را بفرست."); return
    if t in {"عکس به متن","ocr"}:
        context.user_data["bb_convert_mode"]="photo_text"; await msg.reply_text("🖼️ حالا عکس را بفرست."); return
    if t in {"متن به ویس","تبدیل متن به ویس"}:
        context.user_data["bb_convert_mode"]="text_voice"; await msg.reply_text("📝 متن را در پیام بعدی بفرست."); return
    if t in {"متن به عکس","تبدیل متن به عکس"}:
        context.user_data["bb_convert_mode"]="text_image"; await msg.reply_text("🎨 متن را در پیام بعدی بفرست."); return
    return await _old_message_router_40(update,context)
message_router_v12 = message_router_v13
message_router = message_router_v13

# Location updates are handled before the general router so they cannot be swallowed.
_old_location_handler_40 = location_handler
async def location_handler(update, context):
    if update.message and update.message.location:
        await bb_location_result(update,context)
        return
    return await _old_location_handler_40(update,context)


