def _td_room(cid):
    return BB_TD_ROOMS.setdefault(cid, {
        "state": "idle",          # idle / lobby / running / done
        "owner": None,
        "list_id": None,
        "players": {},              # uid -> display name
        "questions": [],
        "used_questions": [],
        "current_uid": None,
        "current_question": None,
        "turn": 0,
    })


def _td_mention(uid, name):
    # Telegram supports tg://user mentions in HTML messages.
    return f'<a href="tg://user?id={int(uid)}">{safe_text(name, 50)}</a>'


def _td_list_keyboard(owner):
    rows=[]
    for lid, item in sorted(BB_TD_LISTS.items(), key=lambda x: x[0]):
        name = safe_text(str(item.get("name", f"لیست {lid}")), 40)
        rows.append([btn(f"📋 {lid} ـ {name}", f"td:{owner}:list:{lid}")])
    rows.append([btn("🔙 بستن", f"td:{owner}:close")])
    return keyboard(rows)


def _td_lobby_keyboard(owner):
    return keyboard([
        [btn("➕ ورود به بازی", f"td:{owner}:join"), btn("👥 بازیکنان", f"td:{owner}:players")],
        [btn("▶️ شروع بازی", f"td:{owner}:start")],
        [btn("📋 تغییر لیست", f"td:{owner}:choose")],
        [btn("🛑 لغو بازی", f"td:{owner}:cancel")],
    ])


def _td_running_keyboard(uid):
    return keyboard([[btn("✅ جواب دادم", f"tdans:{uid}:done")]])


def _td_room_text(room):
    list_item = BB_TD_LISTS.get(room.get("list_id"), {})
    list_name = safe_text(str(list_item.get("name", "لیست انتخابی")), 50)
    names = "\n".join(
        f"{i}. {_td_mention(uid, name)}"
        for i, (uid, name) in enumerate(room["players"].items(), 1)
    ) or "هنوز کسی وارد بازی نشده."
    return (
        "🎭 <b>اتاق جرأت و حقیقت بیل‌بیلک</b>\n\n"
        f"📋 لیست انتخاب‌شده: <b>{list_name}</b>\n"
        f"👥 تعداد بازیکنان: <b>{len(room['players'])}</b>\n\n"
        "بازیکنان یکی‌یکی وارد می‌شوند. تا وقتی مدیر «شروع بازی» را نزند، "
        "هیچ سؤال یا محتوای لیست نمایش داده نمی‌شود.\n\n"
        f"{names}"
    )


async def _td_start_panel(msg, context):
    cid = msg.chat.id
    room = _td_room(cid)
    uid = msg.from_user.id
    # جرأت و حقیقت برای همه اعضای گروه آزاد است؛ نیازی به ادمین بودن نیست.
    if not BB_TD_LISTS:
        await msg.reply_text("📋 هنوز لیست‌های جرأت و حقیقت ثبت نشده‌اند. لیست‌ها را بفرست تا اضافه‌شان کنم.")
        return
    room.update({
        "state": "choose",
        "owner": uid,
        "list_id": None,
        "players": {},
        "questions": [],
        "used_questions": [],
        "current_uid": None,
        "current_question": None,
        "turn": 0,
    })
    await msg.reply_text(
        "🎭 <b>ساخت بازی جرأت و حقیقت</b>\n\n"
        "اول شمارهٔ لیست سؤال‌ها را انتخاب کن.\n"
        "🔒 خود سؤال‌ها تا شروع بازی نمایش داده نمی‌شوند.\n"
        "بعد از انتخاب لیست، بازیکنان می‌توانند یکی‌یکی وارد شوند.",
        parse_mode="HTML",
        reply_markup=_td_list_keyboard(uid),
    )


async def _td_render_lobby(q, room):
    await q.edit_message_text(
        _td_room_text(room),
        parse_mode="HTML",
        reply_markup=_td_lobby_keyboard(room["owner"]),
    )


async def _td_next_turn(context, cid, room, edit_message=None):
    if not room["players"] or not room["questions"]:
        room["state"] = "done"
        room["current_uid"] = None
        room["current_question"] = None
        if edit_message:
            await edit_message.edit_text(
                "🏁 <b>بازی تمام شد!</b>\n\nهمه سؤال‌های این لیست استفاده شدند. 🎉",
                parse_mode="HTML",
                reply_markup=keyboard([[btn("🎭 بازی جدید", f"td:{room['owner']}:new")]]),
            )
        return

    # Do not repeat a player until everyone has had a turn when possible.
    player_ids=list(room["players"].keys())
    previous=room.get("used_players", [])
    available=[x for x in player_ids if x not in previous]
    if not available:
        available=player_ids[:]
        previous=[]
    target=random.choice(available)
    previous.append(target)
    room["used_players"]=previous

    question=random.choice(room["questions"])
    room["questions"].remove(question)
    room["used_questions"].append(question)
    room["current_uid"]=target
    room["current_question"]=question
    room["turn"] += 1

    name=room["players"].get(target, str(target))
    text=(
        f"🎭 <b>نوبت {room['turn']}</b>\n\n"
        f"🎯 {_td_mention(target, name)}\n\n"
        f"❓ <b>{safe_text(question, 3000)}</b>\n\n"
        "وقتی بازیکن جوابش را گفت، خودش دکمهٔ «✅ جواب دادم» را بزند تا نوبت بعدی انتخاب شود."
    )
    if edit_message:
        await edit_message.edit_text(text, parse_mode="HTML", reply_markup=_td_running_keyboard(target))
    else:
        await context.bot.send_message(cid, text, parse_mode="HTML", reply_markup=_td_running_keyboard(target))


async def td_callback(q, context):
    data=q.data or ""
    parts=data.split(":")
    # Tool-center entry point: opens the new multi-player room instead of the old one-off game.
    if len(parts)==3 and parts[0]=="td" and parts[2]=="open":
        await _td_start_panel(q.message, context)
        return True
    if len(parts) < 3 or parts[0] not in {"td", "tdans"}:
        return False
    if not parts[1].isdigit():
        await q.answer("پنل نامعتبر است.", show_alert=True); return True
    actor=int(parts[1]); cid=q.message.chat.id
    room=_td_room(cid)

    if parts[0]=="tdans":
        if len(parts)!=3 or parts[2]!="done":
            return True
        if room.get("state")!="running":
            await q.answer("این بازی در حال اجرا نیست.", show_alert=True); return True
        if q.from_user.id != room.get("current_uid"):
            await q.answer("فقط بازیکنی که نوبتش است می‌تواند این دکمه را بزند.", show_alert=True); return True
        await q.answer("جوابت ثبت شد! نوبت بعدی 🎭")
        await _td_next_turn(context, cid, room, q.message)
        return True

    # td:<owner>:action[:value]
    owner=actor
    if q.from_user.id != owner:
        # Players may join/view; only owner controls list/start/cancel.
        if len(parts)>=3 and parts[2] not in {"join", "players"}:
            await q.answer("این دکمه فقط برای مدیر بازی است.", show_alert=True); return True

    action=parts[2]
    if action=="new":
        room.update({"state":"choose", "owner":q.from_user.id, "list_id":None, "players":{}, "questions":[], "used_questions":[], "current_uid":None, "current_question":None, "turn":0})
        await q.edit_message_text("🎭 <b>لیست جرأت و حقیقت را انتخاب کن:</b>\n\n🔒 متن سؤال‌ها تا شروع بازی نمایش داده نمی‌شود.",parse_mode="HTML",reply_markup=_td_list_keyboard(q.from_user.id)); return True
    if action=="choose":
        await q.edit_message_text("📋 <b>انتخاب لیست</b>\n\nیکی از لیست‌ها را انتخاب کن. محتوای لیست در این مرحله نمایش داده نمی‌شود.",parse_mode="HTML",reply_markup=_td_list_keyboard(owner)); return True
    if action=="list":
        if len(parts)!=4 or not parts[3].isdigit():
            await q.answer("لیست نامعتبر است.",show_alert=True); return True
        if q.from_user.id!=owner:
            await q.answer("فقط سازنده بازی می‌تواند لیست را انتخاب کند.",show_alert=True); return True
        lid=int(parts[3]); item=BB_TD_LISTS.get(lid)
        if not item or not item.get("questions"):
            await q.answer("این لیست هنوز سؤال ندارد.",show_alert=True); return True
        room["state"]="lobby"; room["owner"]=owner; room["list_id"]=lid; room["players"]={}; room["questions"]=list(item["questions"]); room["used_questions"]=[]; room["used_players"]=[]; room["current_uid"]=None; room["current_question"]=None; room["turn"]=0
        await q.edit_message_text(_td_room_text(room),parse_mode="HTML",reply_markup=_td_lobby_keyboard(owner)); return True
    if action=="join":
        if room.get("state")!="lobby":
            await q.answer("ورود به این بازی ممکن نیست.",show_alert=True); return True
        uid=q.from_user.id
        room["players"][uid]=display_name(q.from_user)
        await q.answer("وارد بازی شدی! 🎭")
        await _td_render_lobby(q,room); return True
    if action=="players":
        names="\n".join(f"{i}. {_td_mention(uid,name)}" for i,(uid,name) in enumerate(room["players"].items(),1)) or "هنوز بازیکنی وارد نشده."
        await q.edit_message_text(f"👥 <b>بازیکنان بازی</b>\n\n{names}",parse_mode="HTML",reply_markup=keyboard([[btn("🔙 اتاق",f"td:{room['owner']}:lobby")]])); return True
    if action=="lobby":
        if room.get("state") not in {"lobby","choose"}:
            await q.answer("اتاق در حال اجراست.",show_alert=True); return True
        await _td_render_lobby(q,room); return True
    if action=="start":
        if q.from_user.id!=owner:
            await q.answer("فقط سازنده بازی می‌تواند شروع کند.",show_alert=True); return True
        if room.get("state")!="lobby":
            await q.answer("اول یک لیست را انتخاب کن و بازیکنان وارد شوند.",show_alert=True); return True
        if len(room["players"])<2:
            await q.answer("حداقل ۲ بازیکن لازم است.",show_alert=True); return True
        room["state"]="running"; room["used_players"]=[]
        await q.answer("بازی شروع شد! 🎭")
        await _td_next_turn(context,cid,room,q.message); return True
    if action=="cancel":
        if q.from_user.id!=owner:
            await q.answer("فقط سازنده بازی می‌تواند لغو کند.",show_alert=True); return True
        BB_TD_ROOMS.pop(cid,None)
        await q.edit_message_text("🛑 <b>بازی جرأت و حقیقت لغو شد.</b>",parse_mode="HTML",reply_markup=keyboard([[btn("🎭 بازی جدید",f"td:{owner}:new")]])); return True
    if action=="close":
        if q.from_user.id!=owner:
            await q.answer("فقط مدیر.",show_alert=True); return True
        BB_TD_ROOMS.pop(cid,None)
        await q.edit_message_text("🎭 اتاق جرأت و حقیقت بسته شد.",parse_mode="HTML"); return True
    return False


# Final router layer: keeps the older bot features intact while giving the new
# Truth/Dare room its own callback namespace, preventing button cross-wiring.
_BB_TD_OLD_CALLBACK_ROUTER = callback_router
async def callback_router(update, context):
    q=update.callback_query
    if q:
        try:
            if await td_callback(q, context):
                return
        except Exception as exc:
            log.exception("truth/dare callback failed: %s", exc)
            try: await q.answer("یک خطا در بازی رخ داد.", show_alert=True)
            except Exception: pass
    return await _BB_TD_OLD_CALLBACK_ROUTER(update, context)

_BB_TD_OLD_MESSAGE_ROUTER = message_router
async def message_router(update, context):
    msg=update.effective_message
    if msg and msg.text:
        t=normalize(msg.text or "")
        if t in {"جرعت و حقیقت", "جرئت و حقیقت", "جرات و حقیقت", "حقیقت و جرأت", "حقیقت جرأت", "truth or dare"}:
            await _td_start_panel(msg, context)
            return
        if t in {"شروع جرأت حقیقت", "شروع جرئت حقیقت", "شروع جرات حقیقت"}:
            await _td_start_panel(msg, context)
            return
    return await _BB_TD_OLD_MESSAGE_ROUTER(update, context)

