# FINAL CLEAN UI / ROUTER PATCH
# =============================================================================
# This layer deliberately isolates the tool center into pages and normalizes
# CallbackQuery permission checks. It is placed last so no older redefinition
# can overwrite it at runtime.

async def is_admin(update, uid: Optional[int] = None) -> bool:
    """Accept both Update and CallbackQuery safely."""
    if update is None:
        return False
    # CallbackQuery has .message/.from_user but not .effective_chat.
    chat = getattr(update, "effective_chat", None)
    user = getattr(update, "effective_user", None)
    if chat is None and hasattr(update, "message"):
        chat = getattr(update.message, "chat", None)
    if user is None and hasattr(update, "from_user"):
        user = update.from_user
    if uid is None:
        uid = getattr(user, "id", 0) if user else 0
    if not uid:
        return False
    if await is_owner(uid):
        return True
    if chat is None or getattr(chat, "type", None) == "private":
        return False
    try:
        member = await chat.get_member(uid)
        return member.status in {ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER}
    except TelegramError:
        return False
    except Exception:
        return False


async def request_location_v4(update, context):
    """Location request that works with Update and CallbackQuery alike."""
    msg = getattr(update, "effective_message", None)
    if msg is None and hasattr(update, "message"):
        msg = update.message
    chat = getattr(update, "effective_chat", None)
    if chat is None and msg is not None:
        chat = getattr(msg, "chat", None)
    if not msg or not chat:
        return
    if getattr(chat, "type", None) != "private":
        await msg.reply_text("📍 ارسال موقعیت فقط در گفت‌وگوی خصوصی بات قابل درخواست است. از پیوی بیل‌بیلک استفاده کن.")
        return
    kb = ReplyKeyboardMarkup(
        [[reply_btn("📍 ارسال موقعیت من", request_location=True, style="success")]],
        resize_keyboard=True,
        one_time_keyboard=True,
    )
    await msg.reply_text(
        "📍 دکمه زیر را بزن و موقعیتت را ارسال کن. بیل‌بیلک مختصات را ذخیره نمی‌کند.",
        reply_markup=kb,
    )


