def bb_tools_keyboard(uid, page=1):
    page = max(1, min(3, int(page)))
    text, rows = _bb_tool_pages(uid)[page]
    return text, keyboard(rows)


async def bb_tool_page_callback(q, context):
    parts = (q.data or "").split(":")
    if len(parts) != 3 or parts[0] != "toolpage" or not parts[1].isdigit() or int(parts[1]) != q.from_user.id:
        return False
    page = int(parts[2]) if parts[2].isdigit() else 1
    text, markup = bb_tools_keyboard(q.from_user.id, page)
    await q.edit_message_text(text, parse_mode="HTML", reply_markup=markup)
    return True


# Keep the richer tool callback but remove the old all-tools single-page menu.
_BB_OLD_TOOL_CALLBACK_FINAL = bb_tool_callback
async def bb_tool_callback(q, context):
    if await bb_tool_page_callback(q, context):
        return True
    parts = (q.data or "").split(":", 2)
    if len(parts) == 3 and parts[0] == "tool" and parts[1].isdigit() and int(parts[1]) == q.from_user.id:
        if parts[2] == "home":
            text, markup = bb_tools_keyboard(q.from_user.id, 1)
            await q.edit_message_text(text, parse_mode="HTML", reply_markup=markup)
            return True
    return await _BB_OLD_TOOL_CALLBACK_FINAL(q, context)


