def rich_keyboard(uid):
    text, markup = bb_tools_keyboard(uid, 1)
    return markup


# Final callback router: isolated namespaces are checked before legacy routers.
_BB_OLD_FINAL_CALLBACK = callback_router
async def callback_router(update, context):
    q = getattr(update, "callback_query", None)
    if q:
        try:
            await q.answer()
        except TelegramError:
            pass
        try:
            # Legacy rich-location buttons are normalized here too, so the old
            # fake Update object can never reach request_location_v4.
            rparts = (q.data or "").split(":", 2)
            if len(rparts) == 3 and rparts[0] == "rich" and rparts[1].isdigit() and int(rparts[1]) == q.from_user.id and rparts[2] == "location":
                await request_location_v4(q, context)
                return
            if await bb_tool_page_callback(q, context):
                return
            if await td_callback(q, context):
                return
            if await bb_tool_callback(q, context):
                return
            if await bb_hapoo_callback(q, context):
                return
        except BadRequest as exc:
            # Telegram returns this when a callback tries to edit a message
            # with exactly the same text/keyboard. It is harmless and should
            # never be reported as a real button failure.
            if "Message is not modified" in str(exc):
                try:
                    await q.answer("این صفحه از قبل همین‌طور است 🙂")
                except Exception:
                    pass
                return
            log.warning("final callback Telegram BadRequest: %s", exc)
            try:
                await q.answer("⚠️ عملیات انجام نشد.", show_alert=True)
            except Exception:
                pass
            return
        except Exception as exc:
            log.exception("final callback router error: %s", exc)
            try:
                await q.answer("⚠️ این دکمه با خطا مواجه شد؛ دوباره پنل را باز کن.", show_alert=True)
            except Exception:
                pass
            return
    return await _BB_OLD_FINAL_CALLBACK(update, context)


