# =============================================================================
# FINAL TRUTH/DARE OWNER FIX
# =============================================================================
# When the game is opened from an inline-button callback, q.message.from_user is
# the BOT, not the person who pressed the button.  The previous implementation
# therefore accidentally saved the bot's ID as the room owner.  This final layer
# uses q.from_user.id (the actual button clicker) as the owner.
_BB_TD_CALLBACK_BEFORE_OWNER_FIX = td_callback

async def td_callback(q, context):
    data = q.data or ""
    parts = data.split(":")
    if len(parts) == 3 and parts[0] == "td" and parts[2] == "open":
        uid = q.from_user.id
        cid = q.message.chat.id
        room = _td_room(cid)
        room.update({
            "state": "choose",
            "owner": uid,
            "list_id": None,
            "players": {},
            "questions": [],
            "used_questions": [],
            "used_players": [],
            "current_uid": None,
            "current_question": None,
            "turn": 0,
        })
        if not BB_TD_LISTS:
            await q.answer("هنوز لیستی ثبت نشده است.", show_alert=True)
            return True
        await q.edit_message_text(
            "🎭 <b>ساخت بازی جرأت و حقیقت</b>\n\n"
            "اول شمارهٔ لیست سؤال‌ها را انتخاب کن.\n"
            "🔒 سؤال‌ها تا شروع بازی نمایش داده نمی‌شوند.",
            parse_mode="HTML",
            reply_markup=_td_list_keyboard(uid),
        )
        await q.answer()
        return True
    return await _BB_TD_CALLBACK_BEFORE_OWNER_FIX(q, context)


