BB_EXTRA_GAME_LOCK = asyncio.Lock()


def _bb_game_pages(uid, page=1):
    items=list(BB_EXTRA_GAMES.items())
    per=10
    total=(len(items)+per-1)//per
    page=max(1,min(total,int(page or 1)))
    chunk=items[(page-1)*per:page*per]
    rows=[]
    for i in range(0,len(chunk),2):
        rows.append([btn(BB_EXTRA_GAMES[k],f"xgame:{uid}:{k}") for k,_ in chunk[i:i+2]])
    nav=[]
    if page>1: nav.append(btn("⬅️ قبلی",f"xgames:{uid}:{page-1}"))
    if page<total: nav.append(btn("➡️ بعدی",f"xgames:{uid}:{page+1}"))
    if nav: rows.append(nav)
    rows.append([btn("🎮 بازی‌های قبلی",f"v8page:{uid}:games")])
    rows.append([btn("🏠 خانه",user_cb(uid,"home"))])
    return total,page,keyboard(rows)


def _bb_random_result(key):
    if key in BB_EXTRA_GAME_RESULTS:
        return random.choice(BB_EXTRA_GAME_RESULTS[key])
    if key in {"dice2"}:
        return f"🎲 عدد تاس: {random.randint(1,6)}"
    if key in {"coin2"}:
        return random.choice(["🪙 شیر","🪙 خط"])
    if key in {"number2"}:
        return f"🔢 عدد انتخاب‌شده: {random.randint(1,100)}"
    if key in {"speed2","reaction2"}:
        return f"⚡ امتیاز سرعت این دور: {random.randint(1,10)}"
    if key in {"math4"}:
        return "🧮 جواب: ۲۹"
    if key in {"math5"}:
        return "🧮 جواب: ۱۳"
    if key in {"compare2"}:
        return "⚖️ پاسخ: ۲۵ بزرگ‌تر است."
    if key in {"compare3"}:
        return "⚖️ پاسخ: ۲۴ کوچک‌تر است."
    if key in {"pattern3"}:
        return "🔷 پاسخ: 🟩"
    if key in {"pattern4"}:
        return "🔶 پاسخ: ۹"
    if key in {"count2"}:
        return "🔢 پاسخ: ۶"
    if key in {"count3"}:
        return "🔢 پاسخ: ۴"
    if key in {"trivia2"}:
        return "🌊 پاسخ: اقیانوس آرام"
    if key in {"trivia3"}:
        return "☀️ پاسخ: ستاره"
    if key in {"science2"}:
        return "🔬 پاسخ: H₂O"
    if key in {"english2"}:
        return "🇬🇧 پاسخ: سلام"
    if key in {"focus2"}:
        return "🎯 تمرکز ثبت شد!"
    return random.choice(["🌟 عالی!","🐾 موفق شدی!","✨ نتیجه مثبت!","🏆 این دور هم ثبت شد!"])


async def bb_extra_game_callback(q, context):
    data=q.data or ""
    parts=data.split(":")
    if len(parts)<3 or parts[0] not in {"xgame","xgames"}:
        return False
    if not parts[1].isdigit() or int(parts[1])!=q.from_user.id:
        await q.answer("این بازی برای خودت است.",show_alert=True); return True
    uid=q.from_user.id
    if parts[0]=="xgames":
        page=int(parts[2]) if parts[2].isdigit() else 1
        total,page,markup=_bb_game_pages(uid,page)
        await q.edit_message_text(f"🎮 <b>۵۰ بازی جدید بیل‌بیلک</b>\n\nصفحه <b>{page}</b> از <b>{total}</b>\nهمه بازی‌ها بدون شرط و فقط برای سرگرمی و امتیاز هستند.",parse_mode="HTML",reply_markup=markup)
        return True
    key=parts[2]
    if key not in BB_EXTRA_GAMES:
        return True
    await DBX.ensure_user(q.from_user)
    pts=random.randint(1,5)
    result=_bb_random_result(key)
    await DBX.execute("INSERT INTO safe_game_stats(user_id,game_key,plays,wins,points) VALUES(?,?,1,1,?) ON CONFLICT(user_id,game_key) DO UPDATE SET plays=plays+1,wins=wins+1,points=points+excluded.points",(uid,"extra_"+key,pts))
    await DBX.execute("UPDATE users SET xp=xp+?, bones=bones+?, games=games+1, wins=wins+1, updated_at=? WHERE user_id=?",(pts,max(1,pts//2),now_ts(),uid))
    await q.edit_message_text(f"🎮 <b>{BB_EXTRA_GAMES[key]}</b>\n\n{BB_EXTRA_GAME_PROMPTS.get(key,'یک چالش کوتاه و دوستانه.') }\n\n🎲 نتیجه: <b>{safe_text(result,160)}</b>\n⭐ این دور: <b>+{pts} XP</b>\n🦴 استخوان: <b>+{max(1,pts//2)}</b>\n\n🔒 بدون شرط و قمار.",parse_mode="HTML",reply_markup=keyboard([[btn("🔄 دوباره",f"xgame:{uid}:{key}")],[btn("🎮 فهرست ۵۰ بازی جدید",f"xgames:{uid}:1")],[btn("🏠 خانه",user_cb(uid,"home"))]]))
    return True


# ----------------------------- Moderation ---------------------------------

async def bb_target(update):
    msg=update.effective_message
    if not msg or not msg.reply_to_message:
        return None
    return msg.reply_to_message.from_user

async def bb_admin_guard(update):
    if not update.effective_chat or update.effective_chat.type=="private":
        return False
    if not await is_admin(update):
        await update.effective_message.reply_text("⛔ فقط ادمین واقعی گروه می‌تواند این کار را انجام دهد.")
        return False
    return True

async def bb_can_touch_target(chat, target_id, action="manage"):
    try:
        m=await chat.get_member(target_id)
        if m.status==ChatMemberStatus.OWNER:
            return False,"مالک گروه قابل مدیریت توسط این دستور نیست."
        if m.status==ChatMemberStatus.ADMINISTRATOR and action in {"ban","mute","demote"}:
            return False,"برای مدیریت ادمین دیگر باید دسترسی و سطح مناسب داشته باشی."
    except TelegramError:
        pass
    return True,""

async def bb_moderation_text(update, context, action):
    if not await bb_admin_guard(update): return True
    target=await bb_target(update)
    if not target:
        await update.effective_message.reply_text("👤 روی پیام کاربر ریپلای کن و دوباره دستور را بفرست.")
        return True
    if await is_owner(target.id):
        await update.effective_message.reply_text("⛔ مالک اصلی ربات قابل مدیریت نیست.")
        return True
    chat=update.effective_chat
    ok,why=await bb_can_touch_target(chat,target.id,action)
    if not ok:
        await update.effective_message.reply_text("⛔ "+why); return True
    try:
        if action=="ban":
            await chat.ban_member(target.id)
            await update.effective_message.reply_text(f"🚫 {mention_html(target)} بن شد.",parse_mode="HTML")
        elif action=="remove":
            await chat.ban_member(target.id)
            try: await chat.unban_member(target.id,only_if_banned=True)
            except TelegramError: pass
            await update.effective_message.reply_text(f"👋 {mention_html(target)} از گروه خارج شد.",parse_mode="HTML")
        elif action=="unban":
            await chat.unban_member(target.id,only_if_banned=True)
            await update.effective_message.reply_text(f"✅ بن {mention_html(target)} برداشته شد.",parse_mode="HTML")
        elif action=="mute":
            mins=10
            if context.args and str(context.args[0]).isdigit(): mins=max(1,min(int(context.args[0]),10080))
            await chat.restrict_member(target.id,ChatPermissions(can_send_messages=False),until_date=datetime.now()+timedelta(minutes=mins))
            await update.effective_message.reply_text(f"🔇 {mention_html(target)} برای {mins} دقیقه ساکت شد.",parse_mode="HTML")
        elif action=="unmute":
            perms=ChatPermissions(can_send_messages=True,can_send_audios=True,can_send_documents=True,can_send_photos=True,can_send_videos=True,can_send_video_notes=True,can_send_voice_notes=True,can_send_polls=True,can_send_other_messages=True,can_add_web_page_previews=True)
            await chat.restrict_member(target.id,perms)
            await update.effective_message.reply_text(f"🔊 سکوت {mention_html(target)} برداشته شد.",parse_mode="HTML")
        elif action=="exempt":
            await DBX.execute("INSERT OR REPLACE INTO exemptions(chat_id,user_id,reason) VALUES(?,?,?)",(chat.id,target.id,"manual exemption"))
            await update.effective_message.reply_text(f"🛡 {mention_html(target)} معاف شد.",parse_mode="HTML")
        elif action=="unexempt":
            await DBX.execute("DELETE FROM exemptions WHERE chat_id=? AND user_id=?",(chat.id,target.id))
            await update.effective_message.reply_text(f"🛡 معافیت {mention_html(target)} لغو شد.",parse_mode="HTML")
        elif action=="promote":
            # Telegram requires the bot itself to have the "Add New Admins"
            # (can_promote_members) right before it can promote another member.
            me = await context.bot.get_me()
            bm = await context.bot.get_chat_member(chat.id, me.id)
            if getattr(bm, 'status', None) != ChatMemberStatus.ADMINISTRATOR:
                raise RuntimeError('ربات ادمین گروه نیست.')
            if not bool(getattr(getattr(bm, 'can_promote_members', None), '__bool__', lambda: False)()):
                raise RuntimeError('دسترسی «افزودن ادمین‌های جدید / Add New Admins» برای ربات فعال نیست.')
            tm = await context.bot.get_chat_member(chat.id, target.id)
            if getattr(tm, 'status', None) == ChatMemberStatus.OWNER:
                raise RuntimeError('مالک گروه قابل ارتقا نیست.')
            if getattr(tm, 'status', None) == ChatMemberStatus.ADMINISTRATOR:
                raise RuntimeError('این کاربر از قبل ادمین است یا سطح دسترسی او بالاتر از ربات است.')
            try:
                await context.bot.promote_chat_member(
                    chat.id, target.id,
                    can_manage_chat=False,
                    can_delete_messages=True,
                    can_restrict_members=True,
                    can_invite_users=True,
                    can_pin_messages=True,
                    can_manage_topics=True,
                    can_promote_members=False,
                    can_manage_video_chats=False,
                    can_change_info=False,
                    can_post_messages=False,
                    can_edit_messages=False
                )
            except TelegramError as first_exc:
                # Some Telegram group types reject newer/optional rights; retry with
                # the minimal broadly-supported admin rights.
                log.warning('promote full-rights failed: %s', first_exc)
                await context.bot.promote_chat_member(
                    chat.id, target.id,
                    can_manage_chat=False,
                    can_delete_messages=True,
                    can_restrict_members=True,
                    can_invite_users=True,
                    can_pin_messages=True,
                    can_promote_members=False,
                    can_change_info=False,
                    can_post_messages=False,
                    can_edit_messages=False,
                    can_manage_video_chats=False
                )
            await update.effective_message.reply_text(f"👑 {mention_html(target)} ادمین شد.",parse_mode="HTML")
        elif action=="demote":
            await chat.promote_member(target.id,can_manage_chat=False,can_change_info=False,can_post_messages=False,can_edit_messages=False,can_delete_messages=False,can_invite_users=False,can_restrict_members=False,can_pin_messages=False,can_promote_members=False,can_manage_video_chats=False,can_manage_topics=False)
            await update.effective_message.reply_text(f"👋 {mention_html(target)} عزل شد.",parse_mode="HTML")
    except TelegramError as e:
        await update.effective_message.reply_text("⚠️ عملیات انجام نشد.\n" + safe_text(type(e).__name__ + ': ' + str(e), 300))
    except Exception as e:
        await update.effective_message.reply_text("⚠️ عملیات انجام نشد.\n" + safe_text(type(e).__name__ + ': ' + str(e), 300))
    return True


async def bb_group_lock(update, close: bool):
    if not await bb_admin_guard(update): return True
    chat=update.effective_chat
    try:
        if close:
            await chat.set_permissions(ChatPermissions(can_send_messages=False))
            await update.effective_message.reply_text("🔒 ارسال پیام برای اعضای عادی بسته شد.")
        else:
            perms=ChatPermissions(can_send_messages=True,can_send_audios=True,can_send_documents=True,can_send_photos=True,can_send_videos=True,can_send_video_notes=True,can_send_voice_notes=True,can_send_polls=True,can_send_other_messages=True,can_add_web_page_previews=True)
            await chat.set_permissions(perms)
            await update.effective_message.reply_text("🔓 ارسال پیام برای اعضای عادی باز شد.")
    except TelegramError as e:
        await update.effective_message.reply_text("⚠️ تغییر وضعیت گروه ممکن نشد. دسترسی Restrict Members را بررسی کن.\n"+safe_text(str(e),180))
    return True


# ----------------------------- Nickname / اصل --------------------------------

async def bb_profile_label(update, kind, value=None):
    uid=update.effective_user.id
    await DBX.execute("CREATE TABLE IF NOT EXISTS member_labels(chat_id INTEGER NOT NULL,user_id INTEGER NOT NULL,nickname TEXT DEFAULT '',asl TEXT DEFAULT '',PRIMARY KEY(chat_id,user_id))")
    if update.effective_chat.type=="private":
        cid=uid
    else:
        cid=update.effective_chat.id
    if value is None:
        row=await DBX.one("SELECT nickname,asl FROM member_labels WHERE chat_id=? AND user_id=?",(cid,uid))
        await update.effective_message.reply_text(f"🏷️ لقب: {safe_text(row['nickname'],80) if row and row['nickname'] else 'ثبت نشده'}\n📌 اصل/معرفی: {safe_text(row['asl'],120) if row and row['asl'] else 'ثبت نشده'}")
    else:
        row=await DBX.one("SELECT nickname,asl FROM member_labels WHERE chat_id=? AND user_id=?",(cid,uid))
        nick=row['nickname'] if row else ''
        asl=row['asl'] if row else ''
        if kind=="nickname": nick=safe_text(value,80)
        else: asl=safe_text(value,120)
        await DBX.execute("INSERT OR REPLACE INTO member_labels(chat_id,user_id,nickname,asl) VALUES(?,?,?,?)",(cid,uid,nick,asl))
        await update.effective_message.reply_text("✅ ثبت شد.")
    return True


# ----------------------------- Group link ----------------------------------

async def bb_group_info(update, context):
    chat=update.effective_chat
    if not chat or chat.type=="private":
        await update.effective_message.reply_text("ℹ️ این دستور را داخل گروه بفرست."); return True
    await DBX.ensure_chat(chat)
    try:
        link=("https://t.me/"+chat.username) if chat.username else await context.bot.export_chat_invite_link(chat.id)
    except TelegramError:
        link="لینک قابل ساخت نیست؛ ربات باید دسترسی ساخت لینک دعوت داشته باشد."
    try:
        full=await context.bot.get_chat(chat.id)
        desc=getattr(full,"description",None) or "بیو/توضیحی ثبت نشده."
        title=getattr(full,"title",None) or chat.title or "بدون نام"
    except TelegramError:
        desc=getattr(chat,"description",None) or "بیو/توضیحی ثبت نشده."
        title=chat.title or "بدون نام"
    owner="پیدا نشد"
    try:
        admins=await context.bot.get_chat_administrators(chat.id)
        own=next((a.user for a in admins if a.status==ChatMemberStatus.OWNER),None)
        if own: owner=mention_html(own)
    except TelegramError: pass
    await update.effective_message.reply_text(f"🔗 <b>اطلاعات گروه</b>\n\n📛 نام: <b>{safe_text(title,120)}</b>\n📝 بیو: {safe_text(desc,500)}\n👑 مالک: {owner}\n🔗 لینک گروه: {safe_text(link,500)}",parse_mode="HTML")
    return True


# ----------------------------- Reports -------------------------------------

async def bb_report_admin_mentions(context, chat_id):
    try:
        admins=await context.bot.get_chat_administrators(chat_id)
        users=[a.user for a in admins if not a.user.is_bot]
        if not users: return ""
        return " ".join(mention_html(u) for u in users)
    except TelegramError:
        return ""

async def bb_create_report(update, context, reason="بدون دلیل"):
    target=await bb_target(update)
    if not target:
        await update.effective_message.reply_text("📣 روی پیام فرد موردنظر ریپلای کن و بنویس: گزارش دلیل")
        return True
    if target.id==update.effective_user.id:
        await update.effective_message.reply_text("📣 نمی‌توانی پیام خودت را گزارش کنی."); return True
    reason=safe_text(reason or "بدون دلیل",300)
    await DBX.execute("INSERT INTO reports(chat_id,reporter_id,target_id,reason,status,created_at) VALUES(?,?,?,?,?,?)",(update.effective_chat.id,update.effective_user.id,target.id,reason,"open",now_ts()))
    row=await DBX.one("SELECT last_insert_rowid() id")
    rid=int(row["id"])
    tags=await bb_report_admin_mentions(context,update.effective_chat.id)
    kb=keyboard([[btn("✅ بررسی شد",f"report:{rid}:review"),btn("🗑 حذف گزارش",f"report:{rid}:delete")]])
    text=f"📣 <b>گزارش جدید #{rid}</b>\n\n👤 گزارش‌دهنده: {mention_html(update.effective_user)}\n🎯 فرد گزارش‌شده: {mention_html(target)}\n📝 دلیل: <b>{safe_text(reason,300)}</b>\n\n{tags or '👑 ادمین‌ها پیدا نشدند.'}"
    await update.effective_message.reply_text(text,parse_mode="HTML",reply_markup=kb)
    return True

async def bb_report_callback(q, context):
    parts=(q.data or "").split(":")
    if len(parts)!=3 or parts[0]!="report" or not parts[1].isdigit(): return False
    rid=int(parts[1]); action=parts[2]
    if not await is_admin(q):
        await q.answer("⛔ فقط ادمین می‌تواند گزارش را مدیریت کند.",show_alert=True); return True
    row=await DBX.one("SELECT * FROM reports WHERE id=?",(rid,))
    if not row:
        await q.answer("گزارش پیدا نشد.",show_alert=True); return True
    if action=="review":
        await DBX.execute("UPDATE reports SET status='reviewed' WHERE id=?",(rid,))
        await q.edit_message_reply_markup(reply_markup=keyboard([[btn("☑️ بررسی شد",f"report:{rid}:noop"),btn("🗑 حذف گزارش",f"report:{rid}:delete")]]))
        await q.answer("گزارش به وضعیت بررسی‌شده رفت.",show_alert=True); return True
    if action=="delete":
        await DBX.execute("DELETE FROM reports WHERE id=?",(rid,))
        await q.edit_message_text(f"🗑 گزارش #{rid} حذف شد.")
        await q.answer("گزارش حذف شد.",show_alert=True); return True
    if action=="noop":
        await q.answer("این گزارش قبلاً بررسی شده است.",show_alert=True); return True
    return True


# ----------------------------- Accurate stats ------------------------------

async def bb_accurate_stats(update):
    if not await bb_admin_guard(update): return True
    cid=update.effective_chat.id
    rows=await DBX.execute("SELECT SUM(messages) messages,SUM(joins) joins,SUM(leaves) leaves,SUM(games) games,SUM(deleted) deleted FROM daily_stats WHERE chat_id=?",(cid,),fetch=True)
    r=rows[0] if rows else None
    members=await DBX.one("SELECT COUNT(*) c FROM chat_member_stats WHERE chat_id=?",(cid,))
    top=await DBX.execute("SELECT first_name,username,messages,first_seen,last_seen FROM chat_member_stats WHERE chat_id=? AND is_bot=0 ORDER BY messages DESC,last_seen DESC LIMIT 10",(cid,),fetch=True)
    warns=await DBX.one("SELECT COALESCE(SUM(count),0) c FROM warnings WHERE chat_id=?",(cid,))
    reports=await DBX.one("SELECT COUNT(*) c FROM reports WHERE chat_id=? AND status='open'",(cid,))
    text=(f"📊 <b>آمار دقیق گروه</b>\n\n💬 پیام ثبت‌شده: <b>{int((r['messages'] or 0) if r else 0)}</b>\n➕ ورود: <b>{int((r['joins'] or 0) if r else 0)}</b>\n➖ خروج: <b>{int((r['leaves'] or 0) if r else 0)}</b>\n🎮 بازی: <b>{int((r['games'] or 0) if r else 0)}</b>\n🧹 حذف: <b>{int((r['deleted'] or 0) if r else 0)}</b>\n⚠️ اخطار فعال: <b>{int(warns['c'] if warns else 0)}</b>\n📣 گزارش باز: <b>{int(reports['c'] if reports else 0)}</b>\n👥 اعضای شناخته‌شده: <b>{int(members['c'] if members else 0)}</b>\n\n🏆 <b>۱۰ عضو فعال‌تر</b>\n")
    if top:
        text += "\n".join(f"{i+1}. {safe_text(r['first_name'] or r['username'] or str(r['user_id'] if 'user_id' in r.keys() else ''),35)} — {int(r['messages'] or 0)} پیام" for i,r in enumerate(top))
    else:
        text += "هنوز داده کافی ثبت نشده."
    await update.effective_message.reply_text(text,parse_mode="HTML")
    return True


# ----------------------------- Force join custom message -------------------

async def bb_forcejoin_custom(update, text):
    if not await bb_admin_guard(update): return True
    await DBX.execute("CREATE TABLE IF NOT EXISTS group_extra_settings(chat_id INTEGER PRIMARY KEY,forcejoin_text TEXT DEFAULT '')")
    await DBX.execute("INSERT OR REPLACE INTO group_extra_settings(chat_id,forcejoin_text) VALUES(?,?)",(update.effective_chat.id,safe_text(text,1000)))
    await update.effective_message.reply_text("✅ پیام عضویت اجباری شخصی‌سازی شد.\nمتغیرها: {name} {first_name} {mention} {username} {id} {user_id} {group} {group_name} {group_id} {chat_id} {date} {time} {datetime} {day} {bot} {bot_username} {channel}")
    return True


# ----------------------------- World tools ---------------------------------

async def _bb_http_json(url, timeout=8):
    def run():
        import urllib.request, json
        req=urllib.request.Request(url,headers={"User-Agent":"BilBilak/2.1"})
        with urllib.request.urlopen(req,timeout=timeout) as r:
            return json.loads(r.read().decode("utf-8","ignore"))
    return await asyncio.to_thread(run)

async def bb_world_time(update, query):
    query=safe_text(query,80)
    if not query:
        await update.effective_message.reply_text("🕒 بنویس: ساعت ژاپن یا ساعت Tokyo"); return True
    try:
        data=await _bb_http_json("https://geocoding-api.open-meteo.com/v1/search?name="+quote_plus(query)+"&count=1&language=fa&format=json")
        res=(data.get("results") or [None])[0]
        if not res or not res.get("timezone"):
            await update.effective_message.reply_text("❌ مکان پیدا نشد."); return True
        tz=res["timezone"]
        import zoneinfo
        local=datetime.now(zoneinfo.ZoneInfo(tz))
        await update.effective_message.reply_text(f"🕒 <b>زمان {safe_text(res.get('name') or query,80)}</b>\n\n📍 منطقه زمانی: {tz}\n🕐 ساعت: <b>{local.strftime('%H:%M:%S')}</b>\n📅 تاریخ: <b>{local.strftime('%Y-%m-%d')}</b>",parse_mode="HTML")
    except Exception as e:
        await update.effective_message.reply_text("⚠️ دریافت زمان ممکن نشد. دوباره نام شهر یا کشور را امتحان کن.")
    return True

async def bb_weather(update, query):
    query=safe_text(query,80)
    if not query:
        await update.effective_message.reply_text("🌦️ بنویس: هوا Frankfurt یا هوا تهران"); return True
    try:
        data=await _bb_http_json("https://geocoding-api.open-meteo.com/v1/search?name="+quote_plus(query)+"&count=1&language=fa&format=json")
        res=(data.get("results") or [None])[0]
        if not res:
            await update.effective_message.reply_text("❌ مکان پیدا نشد."); return True
        lat,lon=res["latitude"],res["longitude"]
        wx=await _bb_http_json(f"https://api.open-meteo.com/v1/forecast?latitude={lat}&longitude={lon}&current=temperature_2m,relative_humidity_2m,apparent_temperature,weather_code,wind_speed_10m&timezone=auto")
        cur=wx.get("current",{})
        code=cur.get("weather_code","?")
        labels={0:"آسمان صاف",1:"عمدتاً صاف",2:"نیمه‌ابری",3:"ابری",45:"مه",48:"مه یخ‌زده",51:"نم‌نم باران",61:"بارانی",63:"باران متوسط",65:"باران شدید",71:"برف",80:"رگبار",95:"رعدوبرق"}
        await update.effective_message.reply_text(f"🌦️ <b>هوای {safe_text(res.get('name') or query,80)}</b>\n\n🌡️ دما: <b>{cur.get('temperature_2m','?')}°C</b>\n🥵 دمای محسوس: <b>{cur.get('apparent_temperature','?')}°C</b>\n💧 رطوبت: <b>{cur.get('relative_humidity_2m','?')}%</b>\n💨 باد: <b>{cur.get('wind_speed_10m','?')} km/h</b>\n☁️ وضعیت: <b>{labels.get(code,'کد هوا: '+str(code))}</b>\n\n📡 منبع داده: Open-Meteo",parse_mode="HTML")
    except Exception:
        await update.effective_message.reply_text("⚠️ دریافت هوا انجام نشد. نام شهر را واضح‌تر بنویس.")
    return True

async def bb_currency(update, query):
    query=safe_text(query,40).upper()
    if not query: query="USD EUR"
    parts=re.split(r"[ ,/]+",query)
    base=parts[0] if parts and parts[0] else "USD"
    quote=parts[1] if len(parts)>1 else ("EUR" if base!="EUR" else "USD")
    aliases={"دلار":"USD","یورو":"EUR","پوند":"GBP","ین":"JPY","درهم":"AED","لیر":"TRY","فرانک":"CHF","دلارکانادا":"CAD","دلاراسترالیا":"AUD"}
    base=aliases.get(base,base); quote=aliases.get(quote,quote)
    try:
        data=await _bb_http_json(f"https://api.frankfurter.dev/v2/rates?base={quote_plus(base)}&quotes={quote_plus(quote)}")
        rates=data.get("rates") or []
        if isinstance(rates,list): rate=rates[0].get("rate") if rates else None
        else: rate=rates.get(quote)
        if rate is None: raise ValueError("unsupported")
        await update.effective_message.reply_text(f"💱 <b>نرخ ارز</b>\n\n۱ <b>{base}</b> ≈ <b>{rate}</b> {quote}\n\n📡 منبع: Frankfurter\nℹ️ نرخ‌ها روزانه/بانکی هستند و قیمت لحظه‌ای بازار آزاد محسوب نمی‌شوند.",parse_mode="HTML")
    except Exception:
        await update.effective_message.reply_text("❌ این جفت‌ارز در منبع فعلی پشتیبانی نشد. نمونه: «ارز USD EUR» یا «ارز دلار یورو»")
    return True


