async def ensure_bilbilak_21_schema():
    await DBX.execute("CREATE TABLE IF NOT EXISTS member_labels(chat_id INTEGER NOT NULL,user_id INTEGER NOT NULL,nickname TEXT DEFAULT '',asl TEXT DEFAULT '',PRIMARY KEY(chat_id,user_id))")
    await DBX.execute("CREATE TABLE IF NOT EXISTS group_extra_settings(chat_id INTEGER PRIMARY KEY,forcejoin_text TEXT DEFAULT '')")
    await DBX.execute("CREATE INDEX IF NOT EXISTS idx_reports_chat_status ON reports(chat_id,status)")

_BB_PREV_POST_INIT_21=post_init
async def post_init(application):
    # تنظیمات حساس اتصال موزیکال از SQLite قبل از هر post_init قبلی بارگذاری می‌شوند
    # تا موتور Voice Chat در همان اجرای اول بتواند از تنظیمات پنل مالک استفاده کند.
    global MUSIC_USER_PHONE, MUSIC_USER_SESSION
    try:
        await DBX.execute("CREATE TABLE IF NOT EXISTS bot_settings (key TEXT PRIMARY KEY, value TEXT DEFAULT '')")
        for _k in ("TELEGRAM_API_ID", "TELEGRAM_API_HASH", "MUSIC_USER_PHONE", "MUSIC_USER_SESSION"):
            _r = await DBX.one("SELECT value FROM bot_settings WHERE key=?", (_k,))
            _v = ((_r["value"] if _r else "") or "").strip()
            if _v:
                os.environ[_k] = _v
                if _k == "MUSIC_USER_PHONE":
                    MUSIC_USER_PHONE = _v or '+27629775379'
                elif _k == "MUSIC_USER_SESSION":
                    MUSIC_USER_SESSION = _v
    except Exception as exc:
        log.warning("persistent owner settings load failed: %s", exc)
    await _BB_PREV_POST_INIT_21(application)
    try:
        await ensure_bilbilak_21_schema()
    except Exception as exc:
        log.warning("2.1 schema setup failed: %s",exc)



# FINAL force-join message customization override
_BB_PREV_FORCEJOIN_21 = enforce_forcejoin
async def enforce_forcejoin(update, context):
    chat=update.effective_chat; user=update.effective_user; msg=update.effective_message
    if not chat or chat.type=="private" or not user or not msg: return False
    if await is_admin(update,user.id): return False
    c=await DBX.get_chat(chat.id)
    channel=(c["forced_channel"] if c else "") or ""
    if not channel: return False
    try:
        member=await context.bot.get_chat_member(channel,user.id)
        if member.status in {ChatMemberStatus.MEMBER,ChatMemberStatus.ADMINISTRATOR,ChatMemberStatus.OWNER,ChatMemberStatus.RESTRICTED}:
            return False
    except TelegramError:
        pass
    try: await msg.delete()
    except TelegramError: pass
    join_url=channel if channel.startswith("http") else "https://t.me/"+channel.lstrip("@").strip()
    custom=""
    try:
        row=await DBX.one("SELECT forcejoin_text FROM group_extra_settings WHERE chat_id=?",(chat.id,))
        custom=(row["forcejoin_text"] if row else "") or ""
    except Exception: pass
    text=custom or "🔐 <b>عضویت اجباری فعال است</b>\n\n{name} برای ارسال پیام باید ابتدا عضو کانال شود."
    text=_bb_render_welcome_vars(text,user,chat,mode="forcejoin").replace("{channel}",safe_text(channel,100))
    try:
        await chat.send_message(text,parse_mode="HTML",reply_markup=keyboard([[btn("📢 عضویت در کانال",url=join_url)]]))
    except TelegramError: pass
    return True

