# Add slash fallbacks so the tools work even when Telegram group Privacy Mode
# prevents the bot from receiving ordinary Persian text messages.
_BB_PREV_BUILD_FINAL_TOOLS = build_application
def build_application(token: str) -> Application:
    app = _BB_PREV_BUILD_FINAL_TOOLS(token)
    app.add_handler(CommandHandler("time", bb_cmd_time), group=1)
    app.add_handler(CommandHandler("weather", bb_cmd_weather), group=1)
    app.add_handler(CommandHandler("currency", bb_cmd_currency), group=1)
    app.add_handler(CommandHandler("grouplink", bb_cmd_grouplink), group=1)
    return app


# =============================================================================
# FINAL PLAIN-PERSIAN TOOL ROUTER (NO SLASH)
# =============================================================================
def _bb_plain_tool_text(text: str) -> str:
    t = (text or "").strip()
    t = t.replace("ي", "ی").replace("ك", "ک")
    t = re.sub(r"\s+", " ", t)
    return t

async def bb_plain_persian_tools(update, context):
    msg = update.effective_message
    if not msg or not getattr(msg, "text", None):
        return
    t = _bb_plain_tool_text(msg.text)
    low = t.lower()

    # Group link/info
    if low in {"لینک گروه", "لینک گپ", "لینک گروپ", "اطلاعات گروه", "معرفی گروه"}:
        await bb_group_info(update, context)
        raise ApplicationHandlerStop

    # World time
    if t == "ساعت" or t.startswith("ساعت ") or t == "زمان" or t.startswith("زمان "):
        q = t.split(" ", 1)[1].strip() if " " in t else ""
        await bb_world_time(update, q)
        raise ApplicationHandlerStop

    # Weather
    weather_prefixes = ("آب و هوا ", "آبوهوا ", "هوا ")
    if t in {"آب و هوا", "آبوهوا", "هوا"} or any(t.startswith(x) for x in weather_prefixes):
        q = re.sub(r"^(آب و هوا|آبوهوا|هوا)\s*", "", t).strip()
        await bb_weather(update, q)
        raise ApplicationHandlerStop

    # Currency
    currency_prefixes = ("نرخ ارز ", "قیمت ارز ", "ارز ")
    if t in {"ارز", "نرخ ارز", "قیمت ارز"} or any(t.startswith(x) for x in currency_prefixes):
        q = re.sub(r"^(نرخ ارز|قیمت ارز|ارز)\s*", "", t).strip()
        await bb_currency(update, q)
        raise ApplicationHandlerStop

async def bb_plain_tool_filter(update, context):
    """Kept as a separate callable for compatibility/debugging."""
    return await bb_plain_persian_tools(update, context)

# Re-wrap the final application so these Persian no-slash phrases are checked
# before the large generic message router.
_BB_PREV_BUILD_PLAIN_TOOLS = build_application
def build_application(token: str) -> Application:
    app = _BB_PREV_BUILD_PLAIN_TOOLS(token)
    app.add_handler(
        MessageHandler(filters.TEXT & ~filters.COMMAND, bb_plain_tool_filter),
        group=-20,
    )
    return app



# =============================================================================
# FINAL MUSIC ACCOUNT + SINGLE-PASS MESSAGE FIX
# =============================================================================
# این بخش از یک حساب کاربری شخصیِ خود صاحب ربات برای Voice Chat استفاده می‌کند.
# حساب باید با رضایت صاحبش و با API_ID/API_HASH رسمی تلگرام وارد شود.
# برای امنیت، کد ورود/رمز دو مرحله‌ای داخل فایل ذخیره نمی‌شود.
# متغیرهای لازم برای ورود اولیه:
#   TELEGRAM_API_ID=...
#   TELEGRAM_API_HASH=...
#   MUSIC_USER_PHONE=+...
#   MUSIC_USER_SESSION=/path/to/bilbilak_music_user
# پس از ورود، session file باقی می‌ماند و دفعات بعد نیاز به کد ندارد.
# دستورات مالک برای ورود:
#   /music_login
#   /music_code 12345
#   /music_2fa PASSWORD
# وضعیت:
#   /music_account
# خروج:
#   /music_logout
#
# نکته: حساب شخصی باید خودش از قبل عضو گروه موردنظر باشد و برای ساخت/استفاده
# از Voice Chat دسترسی لازم را داشته باشد. ربات هیچ دعوت یا دورزدن دسترسی‌ای
# انجام نمی‌دهد.

MUSIC_USER_CLIENT = None
MUSIC_USER_PHONE = MUSIC_USER_PHONE or os.getenv('MUSIC_USER_PHONE', '')
MUSIC_USER_CODE_HASH = None
MUSIC_USER_LOGIN_STATE = None
MUSIC_USER_LOGIN_LOCK = asyncio.Lock()
MUSIC_USER_SESSION = MUSIC_USER_SESSION or os.getenv('MUSIC_USER_SESSION', str(Path.home() / 'bilbilak_music_user'))

# تنظیمات ورود حساب شخصی موزیکال که از پنل مالک قابل تغییر هستند.
OWNER_PENDING_MUSIC_SETTING = {}
MUSIC_SETTING_KEYS = {
    'api_id': 'TELEGRAM_API_ID',
    'api_hash': 'TELEGRAM_API_HASH',
    'phone': 'MUSIC_USER_PHONE',
    'session': 'MUSIC_USER_SESSION',
}

async def _bb_get_music_setting(key, default=''):
    try:
        row = await DBX.one("SELECT value FROM bot_settings WHERE key=?", (key,))
        value = ((row['value'] if row else '') or '').strip()
        return value if value else default
    except Exception:
        return default

async def _bb_set_music_setting(key, value):
    value = str(value or '').strip()
    await DBX.execute(
        "CREATE TABLE IF NOT EXISTS bot_settings (key TEXT PRIMARY KEY, value TEXT DEFAULT '')"
    )
    await DBX.execute(
        "INSERT INTO bot_settings(key,value) VALUES(?,?) "
        "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
        (key, value)
    )
    if value:
        os.environ[key] = value
    else:
        os.environ.pop(key, None)

async def _bb_music_seed_defaults():
    """Keep music defaults only when the user has not configured them yet."""
    try:
        await DBX.execute(
            "CREATE TABLE IF NOT EXISTS bot_settings (key TEXT PRIMARY KEY, value TEXT DEFAULT '')"
        )
        row = await DBX.one("SELECT value FROM bot_settings WHERE key=?", ('MUSIC_USER_SESSION',))
        if not row or not (row['value'] or '').strip():
            phone = await _bb_get_music_setting('MUSIC_USER_PHONE', os.getenv('MUSIC_USER_PHONE', ''))
            digits = re.sub(r'\D', '', phone or '') or 'default'
            await _bb_set_music_setting('MUSIC_USER_SESSION', str(Path(tempfile.gettempdir()) / f'bilbilak_music_user_{digits}'))
    except Exception as exc:
        log.warning('Could not seed music defaults: %s', exc)


async def _bb_music_settings_snapshot():
    api_id = await _bb_get_music_setting('TELEGRAM_API_ID', os.getenv('TELEGRAM_API_ID', ''))
    api_hash = await _bb_get_music_setting('TELEGRAM_API_HASH', os.getenv('TELEGRAM_API_HASH', ''))
    phone = await _bb_get_music_setting('MUSIC_USER_PHONE', os.getenv('MUSIC_USER_PHONE', ''))
    session = await _bb_get_music_setting('MUSIC_USER_SESSION', MUSIC_USER_SESSION)
    return api_id, api_hash, phone, session

async def _bb_owner_music_settings_panel(q, context):
    if not await owner_check(q.from_user.id):
        await q.answer('⛔ فقط سازنده.', show_alert=True); return
    api_id, api_hash, phone, session = await _bb_music_settings_snapshot()
    api_ok = '✅ تنظیم شده' if api_id and api_id.isdigit() else '❌ تنظیم نشده'
    hash_ok = '✅ تنظیم شده' if api_hash else '❌ تنظیم نشده'
    phone_ok = '✅ تنظیم شده' if phone else '❌ تنظیم نشده'
    session_text = safe_text(session, 55) if session else 'مسیر پیش‌فرض'
    connected = bool(MUSIC_USER_CLIENT is not None and getattr(MUSIC_USER_CLIENT, 'is_connected', False))
    state = '🟢 حساب متصل است' if connected else '🔴 حساب متصل نیست'
    panel_text = (
        '🎵 <b>تنظیمات اتصال موزیکال</b>\n\n'
        f'🔢 API ID: <b>{api_ok}</b>\n'
        f'🔐 API Hash: <b>{hash_ok}</b>\n'
        f'📱 شماره حساب: <b>{phone_ok}</b>\n'
        f'💾 Session: {session_text}\n'
        f'\n{state}\n\n'
        'از دکمه‌های زیر تنظیمات را ذخیره کن؛ اطلاعات در SQLite خود ربات می‌ماند و بعد از ری‌استارت دوباره بارگذاری می‌شود.'
    )
    markup = keyboard([
        [btn('🔢 تنظیم API ID','own6:music_api_id'), btn('🔐 تنظیم API Hash','own6:music_api_hash')],
        [btn('📱 تنظیم شماره حساب','own6:music_phone'), btn('💾 تنظیم Session','own6:music_session')],
        [btn('🔌 اتصال/ورود حساب','own6:music_login'), btn('📊 وضعیت اتصال','own6:music_status')],
        [btn('🗑 پاک‌کردن تنظیمات','own6:music_clear'), btn('🔙 پنل مالک','own6:home')],
    ])
    # پنل مالک ممکن است همراه عکس پروفایل ربات ارسال شده باشد؛ در آن حالت
    # edit_message_text روی پیام photo خطای "There is no text" می‌دهد.
    if getattr(q, 'message', None) is not None and getattr(q.message, 'photo', None):
        await q.message.edit_caption(caption=panel_text, parse_mode='HTML', reply_markup=markup)
    else:
        await q.edit_message_text(panel_text, parse_mode='HTML', reply_markup=markup)

async def _bb_owner_music_setting_prompt(q, field):
    labels = {
        'api_id': ('API ID', 'عدد API ID را بفرست. مثال: 12345678'),
        'api_hash': ('API Hash', 'API Hash را بفرست. مقدار را دقیقاً همان‌طور که از Telegram گرفته‌ای ارسال کن.'),
        'phone': ('شماره حساب', 'شماره همان حساب شخصی که قرار است وارد Voice Chat شود را با کد کشور بفرست. مثال: +491234567890'),
        'session': ('مسیر Session', 'مسیر فایل Session را بفرست؛ اگر نمی‌خواهی تغییرش بدهی، همان مسیر پیش‌فرض را نگه دار.'),
    }
    title, text = labels[field]
    OWNER_PENDING_MUSIC_SETTING[q.from_user.id] = field
    await q.answer('منتظر دریافت مقدار هستم.', show_alert=False)
    await q.message.reply_text(
        f'✏️ <b>{title}</b>\n\n{text}\n\n'
        '⚠️ پیام مقدار را بعد از دریافت خودکار حذف می‌کنم.',
        parse_mode='HTML'
    )

async def _bb_owner_music_setting_text(update, context):
    msg = update.effective_message
    uid = update.effective_user.id if update.effective_user else 0
    if not msg or not owner_is_allowed(uid):
        return False
    field = OWNER_PENDING_MUSIC_SETTING.get(uid)
    if not field or not getattr(msg, 'text', None):
        return False
    value = msg.text.strip()
    try:
        await msg.delete()
    except Exception:
        pass
    key = MUSIC_SETTING_KEYS[field]
    if field == 'api_id':
        if not value.isdigit():
            await update.effective_chat.send_message('❌ API ID باید فقط عدد باشد.')
            return True
    elif field == 'phone':
        compact = value.replace(' ', '').replace('-', '')
        if not re.fullmatch(r'\+?[0-9]{7,20}', compact):
            await update.effective_chat.send_message('❌ شماره معتبر نیست. نمونه: +491234567890', parse_mode='HTML')
            return True
        value = compact
    elif field == 'session':
        value = value or str(Path.home() / 'bilbilak_music_user')
    await _bb_set_music_setting(key, value)
    if field == 'session':
        global MUSIC_USER_SESSION
        MUSIC_USER_SESSION = value
    OWNER_PENDING_MUSIC_SETTING.pop(uid, None)
    labels = {'api_id':'API ID','api_hash':'API Hash','phone':'شماره حساب','session':'مسیر Session'}
    await update.effective_chat.send_message(
        f'✅ <b>{labels[field]}</b> ذخیره شد.\n\n'
        'حالا از «تنظیمات اتصال موزیکال» می‌توانی اتصال حساب را شروع کنی.',
        parse_mode='HTML',
        reply_markup=keyboard([[btn('🎵 تنظیمات اتصال موزیکال','own6:music')]])
    )
    return True

try:
    from pyrogram.errors import SessionPasswordNeeded as _BBSessionPasswordNeeded
except Exception:
    _BBSessionPasswordNeeded = Exception


def _bb_music_api_config():
    api_id_raw = str(TELEGRAM_API_ID or os.getenv('TELEGRAM_API_ID', '')).strip()
    api_hash = str(TELEGRAM_API_HASH or os.getenv('TELEGRAM_API_HASH', '')).strip()
    phone = str(MUSIC_USER_PHONE or os.getenv('MUSIC_USER_PHONE', '')).strip()
    if not api_id_raw or api_id_raw == '0' or not api_hash or api_hash == 'PASTE_API_HASH_HERE':
        return None, None, phone
    try:
        return int(api_id_raw), api_hash, phone
    except ValueError:
        return None, None, phone


async def _bb_music_user_is_connected():
    global MUSIC_USER_CLIENT
    return bool(MUSIC_USER_CLIENT is not None and getattr(MUSIC_USER_CLIENT, 'is_connected', False))


def _bb_music_remove_invalid_session(session_path):
    """Remove only the Pyrogram session files when Telegram invalidates the auth key."""
    try:
        base = Path(session_path).expanduser()
        candidates = [base]
        if base.suffix != '.session':
            candidates.append(Path(str(base) + '.session'))
        for item in candidates:
            try:
                if item.exists() and item.is_file():
                    item.unlink()
                    log.info('Removed invalid music session file: %s', item)
            except Exception as exc:
                log.warning('Could not remove invalid music session %s: %s', item, exc)
    except Exception as exc:
        log.warning('Could not inspect music session path: %s', exc)


async def _bb_music_terminal_login(api_id, api_hash, phone):
    """ورود اولیه حساب شخصی در همان event loop برنامه؛ کد و 2FA فقط در ترمینال."""
    global MUSIC_USER_CLIENT, MUSIC_VC_CLIENT, MUSIC_VC_ENGINE, MUSIC_USER_PHONE, MUSIC_USER_SESSION
    if not phone:
        phone = (await _music_asyncio.to_thread(input, '📱 شماره حساب موزیکال (مثال +98912...): ')).strip()
    if not phone:
        raise RuntimeError('شماره حساب وارد نشد.')
    MUSIC_USER_PHONE = phone
    session_path = Path(MUSIC_USER_SESSION).expanduser()
    session_path.parent.mkdir(parents=True, exist_ok=True)
    client = _MusicPyroClient(
        session_path.stem, api_id=api_id, api_hash=api_hash,
        workdir=str(session_path.parent), in_memory=False
    )
    await client.connect()
    try:
        me = await client.get_me()
        if me:
            MUSIC_USER_CLIENT = client
            MUSIC_VC_CLIENT = client
            MUSIC_VC_ENGINE = _MusicPyTgCalls(client)
            await MUSIC_VC_ENGINE.start()
            return True, me
    except Exception:
        pass
    sent = await client.send_code(phone)
    code = (await _music_asyncio.to_thread(input, '🔐 کد ورود تلگرام را در ترمینال وارد کن: ')).strip().replace(' ', '')
    try:
        await client.sign_in(phone, sent.phone_code_hash, code)
    except _BBSessionPasswordNeeded:
        password = await _music_asyncio.to_thread(input, '🔑 رمز دو مرحله‌ای تلگرام: ')
        await client.check_password(password.strip())
    me = await client.get_me()
    MUSIC_USER_CLIENT = client
    MUSIC_VC_CLIENT = client
    MUSIC_VC_ENGINE = _MusicPyTgCalls(client)
    await MUSIC_VC_ENGINE.start()
    log.info('Music personal account logged in: %s', getattr(me, 'username', None) or getattr(me, 'phone_number', 'unknown'))
    return True, me


async def _bb_music_user_start_existing():
    """اگر session قبلاً مجاز شده باشد، بدون درخواست کد آن را اجرا می‌کند."""
    global MUSIC_USER_CLIENT, MUSIC_VC_CLIENT, MUSIC_VC_ENGINE
    if _MusicPyroClient is None or _MusicPyTgCalls is None or _MusicMediaStream is None:
        return False, 'کتابخانه‌های Pyrogram/PyTgCalls نصب نیستند.'
    api_id, api_hash, phone = _bb_music_api_config()
    if not api_id or not api_hash:
        return False, 'TELEGRAM_API_ID و TELEGRAM_API_HASH تنظیم نشده‌اند.'
    try:
        client = _MusicPyroClient(
            str(Path(MUSIC_USER_SESSION).expanduser().stem),
            api_id=api_id,
            api_hash=api_hash,
            workdir=str(Path(MUSIC_USER_SESSION).expanduser().parent),
            in_memory=False,
        )
        await client.connect()
        me = await client.get_me()
        if not me:
            await client.disconnect()
            return False, 'session هنوز برای حساب شخصی مجاز نشده است.'
        MUSIC_USER_CLIENT = client
        MUSIC_VC_CLIENT = client
        if MUSIC_VC_ENGINE is not None:
            try:
                stop = getattr(MUSIC_VC_ENGINE, 'stop', None)
                if stop:
                    r = stop()
                    if hasattr(r, '__await__'):
                        await r
            except Exception:
                pass
        MUSIC_VC_ENGINE = _MusicPyTgCalls(client)
        r = MUSIC_VC_ENGINE.start()
        if hasattr(r, '__await__'):
            await r
        log.info('Music personal account connected: %s', getattr(me, 'username', None) or getattr(me, 'phone_number', 'unknown'))
        return True, me
    except Exception as exc:
        log.warning('Existing music user session unavailable: %s', exc)
        try:
            if MUSIC_USER_CLIENT is not None and getattr(MUSIC_USER_CLIENT, 'is_connected', False):
                await MUSIC_USER_CLIENT.disconnect()
        except Exception:
            pass
        MUSIC_USER_CLIENT = None
        return False, str(exc)


async def _bb_music_user_login_begin(update, context):
    global MUSIC_USER_CLIENT, MUSIC_USER_PHONE, MUSIC_USER_CODE_HASH, MUSIC_USER_LOGIN_STATE, MUSIC_VC_CLIENT, MUSIC_VC_ENGINE
    uid = update.effective_user.id if update.effective_user else 0
    msg = update.effective_message
    if not await is_owner(uid):
        if msg:
            await msg.reply_text('⛔ فقط مالک ربات می‌تواند حساب موزیکال را متصل کند.')
        return True
    if msg and update.effective_chat and update.effective_chat.type != 'private':
        await msg.reply_text('🔐 ورود حساب موزیکال را فقط در گفت‌وگوی خصوصی با ربات انجام بده.')
        return True
    async with MUSIC_USER_LOGIN_LOCK:
        await _bb_music_seed_defaults()
        api_id, api_hash, phone = _bb_music_api_config()
        if not api_id or not api_hash:
            await msg.reply_text('⚠️ ابتدا TELEGRAM_API_ID و TELEGRAM_API_HASH را در محیط اجرا تنظیم کن.')
            return True
        if not phone:
            await msg.reply_text('⚠️ متغیر MUSIC_USER_PHONE تنظیم نشده است؛ شماره حساب را فقط در محیط سرور تنظیم کن.')
            return True
        try:
            if MUSIC_USER_CLIENT is not None and getattr(MUSIC_USER_CLIENT, 'is_connected', False):
                try:
                    current_me = await MUSIC_USER_CLIENT.get_me()
                    current_phone = str(getattr(current_me, 'phone_number', '') or getattr(current_me, 'phone', '') or '')
                    target_phone = phone.replace('+', '').replace(' ', '')
                    current_phone = current_phone.replace('+', '').replace(' ', '')
                    if current_phone and current_phone == target_phone:
                        await msg.reply_text('✅ حساب موزیکال همین الان متصل است و با شماره تنظیم‌شده مطابقت دارد.')
                        return True
                except Exception:
                    pass
                try:
                    await MUSIC_USER_CLIENT.disconnect()
                except Exception:
                    pass
                MUSIC_USER_CLIENT = None
            client = _MusicPyroClient(
                'bilbilak_music_user',
                api_id=api_id,
                api_hash=api_hash,
                workdir=str(Path(MUSIC_USER_SESSION).expanduser().parent),
                in_memory=False,
            )
            try:
                await client.connect()
                me = await client.get_me()
                if me:
                    MUSIC_USER_CLIENT = client
                    MUSIC_VC_CLIENT = client
                    if MUSIC_VC_ENGINE is None:
                        MUSIC_VC_ENGINE = _MusicPyTgCalls(client)
                        r = MUSIC_VC_ENGINE.start()
                        if hasattr(r, '__await__'):
                            await r
                    await msg.reply_text('✅ session قبلی پیدا شد و حساب موزیکال متصل شد.')
                    return True
            except Exception as session_exc:
                if 'AUTH_KEY_UNREGISTERED' not in str(session_exc).upper():
                    raise
                log.warning('Invalid music session detected; deleting it and starting a fresh login.')
                try:
                    if getattr(client, 'is_connected', False):
                        await client.disconnect()
                except Exception:
                    pass
                _bb_music_remove_invalid_session(MUSIC_USER_SESSION)
                client = _MusicPyroClient(
                    'bilbilak_music_user',
                    api_id=api_id,
                    api_hash=api_hash,
                    workdir=str(Path(MUSIC_USER_SESSION).expanduser().parent),
                    in_memory=False,
                )
                await client.connect()
            sent = await client.send_code(phone)
            MUSIC_USER_CLIENT = client
            MUSIC_USER_PHONE = phone
            MUSIC_USER_CODE_HASH = sent.phone_code_hash
            MUSIC_USER_LOGIN_STATE = 'code'
            await msg.reply_text('📲 کد ورود به حساب ارسال شد.\n\nکد را فقط در پیام خصوصی به ربات با این قالب بفرست:\n/music_code 12345')
        except Exception as exc:
            log.warning('music login begin failed: %s', exc)
            try:
                if MUSIC_USER_CLIENT is not None and getattr(MUSIC_USER_CLIENT, 'is_connected', False):
                    await MUSIC_USER_CLIENT.disconnect()
            except Exception:
                pass
            MUSIC_USER_CLIENT = None
            MUSIC_USER_CODE_HASH = None
            MUSIC_USER_LOGIN_STATE = None
            # خطای واقعی را برای مالک نشان بده تا مشخص شود مشکل API، شماره، Session یا کتابخانه است.
            err_name = type(exc).__name__
            err_text = str(exc).strip() or 'بدون متن خطا'
            safe_err = safe_text(f'{err_name}: {err_text}', 700)
            await msg.reply_text(
                '❌ شروع ورود حساب موزیکال انجام نشد.\n\n'
                f'🔎 خطای واقعی: {safe_err}\n\n'
                '📱 شماره ثبت‌شده: ' + safe_text(phone, 30) + '\n'
                '🔢 API ID: ' + ('✅' if api_id else '❌') + '\n'
                '🔐 API Hash: ' + ('✅' if api_hash else '❌'),
                parse_mode='HTML'
            )
    return True


async def _bb_music_user_login_code(update, context):
    global MUSIC_USER_CLIENT, MUSIC_USER_CODE_HASH, MUSIC_USER_LOGIN_STATE, MUSIC_VC_CLIENT, MUSIC_VC_ENGINE
    uid = update.effective_user.id if update.effective_user else 0
    msg = update.effective_message
    if not await is_owner(uid):
        return True
    if not update.effective_chat or update.effective_chat.type != 'private':
        await msg.reply_text('🔐 این دستور را فقط در خصوصی بفرست.')
        return True
    if not MUSIC_USER_CLIENT or not MUSIC_USER_CODE_HASH or MUSIC_USER_LOGIN_STATE != 'code':
        await msg.reply_text('❌ مرحله ورود فعال نیست. اول /music_login را بزن.')
        return True
    code = ' '.join(context.args or []).strip().replace(' ', '')
    if not code:
        await msg.reply_text('نمونه: /music_code 12345')
        return True
    try:
        try:
            await msg.delete()
        except Exception:
            pass
        await MUSIC_USER_CLIENT.sign_in(MUSIC_USER_PHONE, MUSIC_USER_CODE_HASH, code)
        MUSIC_USER_LOGIN_STATE = 'ready'
        MUSIC_VC_CLIENT = MUSIC_USER_CLIENT
        MUSIC_VC_ENGINE = _MusicPyTgCalls(MUSIC_USER_CLIENT)
        r = MUSIC_VC_ENGINE.start()
        if hasattr(r, '__await__'):
            await r
        me = await MUSIC_USER_CLIENT.get_me()
        MUSIC_USER_CODE_HASH = None
        await update.effective_chat.send_message('✅ حساب شخصی موزیکال با موفقیت وصل شد.\n👤 ' + safe_text(getattr(me, 'first_name', '') or 'حساب کاربری', 80))
    except _BBSessionPasswordNeeded:
        MUSIC_USER_LOGIN_STATE = '2fa'
        MUSIC_USER_CODE_HASH = None
        try:
            await msg.delete()
        except Exception:
            pass
        await update.effective_chat.send_message('🔐 این حساب رمز دومرحله‌ای دارد. رمز را فقط در خصوصی با این قالب بفرست:\n/music_2fa YOUR_PASSWORD')
    except Exception as exc:
        log.warning('music login code failed: %s', exc)
        await update.effective_chat.send_message('❌ کد ورود معتبر نبود یا منقضی شده است. /music_login را دوباره اجرا کن.')
    return True


async def _bb_music_user_login_2fa(update, context):
    global MUSIC_USER_LOGIN_STATE, MUSIC_VC_CLIENT, MUSIC_VC_ENGINE, MUSIC_USER_CODE_HASH
    uid = update.effective_user.id if update.effective_user else 0
    msg = update.effective_message
    if not await is_owner(uid):
        return True
    if not update.effective_chat or update.effective_chat.type != 'private':
        await msg.reply_text('🔐 این دستور را فقط در خصوصی بفرست.')
        return True
    if not MUSIC_USER_CLIENT or MUSIC_USER_LOGIN_STATE != '2fa':
        await msg.reply_text('❌ مرحله رمز دومرحله‌ای فعال نیست. اول /music_login را بزن.')
        return True
    password = ' '.join(context.args or []).strip()
    if not password:
        await msg.reply_text('نمونه: /music_2fa YOUR_PASSWORD')
        return True
    try:
        await msg.delete()
    except Exception:
        pass
    try:
        await MUSIC_USER_CLIENT.check_password(password)
        MUSIC_USER_LOGIN_STATE = 'ready'
        MUSIC_USER_CODE_HASH = None
        MUSIC_VC_CLIENT = MUSIC_USER_CLIENT
        MUSIC_VC_ENGINE = _MusicPyTgCalls(MUSIC_USER_CLIENT)
        r = MUSIC_VC_ENGINE.start()
        if hasattr(r, '__await__'):
            await r
        me = await MUSIC_USER_CLIENT.get_me()
        await update.effective_chat.send_message('✅ حساب شخصی موزیکال با موفقیت وصل شد.\n👤 ' + safe_text(getattr(me, 'first_name', '') or 'حساب کاربری', 80))
    except Exception:
        await update.effective_chat.send_message('❌ رمز دومرحله‌ای صحیح نبود یا ورود کامل نشد.')
    return True


async def _bb_music_account_status(update, context):
    uid = update.effective_user.id if update.effective_user else 0
    msg = update.effective_message
    if not await is_owner(uid):
        return True
    if MUSIC_USER_CLIENT is None or not getattr(MUSIC_USER_CLIENT, 'is_connected', False):
        await msg.reply_text('🎵 حساب شخصی موزیکال: ❌ متصل نیست')
        return True
    try:
        me = await MUSIC_USER_CLIENT.get_me()
        username = ('@' + me.username) if getattr(me, 'username', None) else 'بدون یوزرنیم'
        await msg.reply_text(f'🎵 حساب شخصی موزیکال: ✅ متصل\n👤 {safe_text(getattr(me, "first_name", ""), 80)}\n🔹 {safe_text(username, 80)}')
    except Exception:
        await msg.reply_text('🎵 حساب شخصی موزیکال: ⚠️ اتصال ناقص')
    return True


async def _bb_music_account_logout(update, context):
    global MUSIC_USER_CLIENT, MUSIC_VC_CLIENT, MUSIC_VC_ENGINE, MUSIC_USER_LOGIN_STATE, MUSIC_USER_CODE_HASH
    uid = update.effective_user.id if update.effective_user else 0
    msg = update.effective_message
    if not await is_owner(uid):
        return True
    try:
        if MUSIC_VC_ENGINE is not None:
            stop = getattr(MUSIC_VC_ENGINE, 'stop', None)
            if stop:
                r = stop()
                if hasattr(r, '__await__'):
                    await r
    except Exception:
        pass
    try:
        if MUSIC_USER_CLIENT is not None:
            await MUSIC_USER_CLIENT.log_out()
    except Exception:
        try:
            if MUSIC_USER_CLIENT is not None and getattr(MUSIC_USER_CLIENT, 'is_connected', False):
                await MUSIC_USER_CLIENT.disconnect()
        except Exception:
            pass
    MUSIC_USER_CLIENT = None
    MUSIC_VC_CLIENT = None
    MUSIC_VC_ENGINE = None
    MUSIC_USER_LOGIN_STATE = None
    MUSIC_USER_CODE_HASH = None
    await msg.reply_text('🔌 حساب شخصی موزیکال از بیل‌بیلک جدا شد.')
    return True


async def _music_init_voice_engine_personal(_bot_token=''):
    """نسخه نهایی موتور VC: اول حساب شخصی موزیکال را استفاده می‌کند."""
    global MUSIC_VC_AVAILABLE, MUSIC_VC_STARTED, MUSIC_VC_CLIENT, MUSIC_VC_ENGINE
    if MUSIC_VC_STARTED and MUSIC_VC_ENGINE is not None:
        return True
    ok, info = await _bb_music_user_start_existing()
    if ok:
        MUSIC_VC_STARTED = True
        MUSIC_VC_AVAILABLE = True
        return True
    MUSIC_VC_STARTED = False
    MUSIC_VC_AVAILABLE = False
    log.info('Personal music account is not authorized yet; use /music_login in private chat.')
    return False


# Override the original initializer at runtime; older post_init layers call this name.
_music_init_voice_engine = _music_init_voice_engine_personal

_OLD_OWNER_CALLBACK_V6_MUSIC = owner_callback_v6
async def owner_callback_v6(q, context):
    if not await owner_check(q.from_user.id):
        await q.answer('⛔ فقط سازنده.', show_alert=True)
        return
    action = (q.data or '').split(':', 1)[1] if ':' in (q.data or '') else ''
    if action == 'music':
        await _bb_owner_music_settings_panel(q, context); return
    if action in {'music_api_id','music_api_hash','music_phone','music_session'}:
        await _bb_owner_music_setting_prompt(q, action.replace('music_','',1)); return
    if action == 'music_status':
        api_id, api_hash, phone, session = await _bb_music_settings_snapshot()
        connected = bool(MUSIC_USER_CLIENT is not None and getattr(MUSIC_USER_CLIENT, 'is_connected', False))
        if connected:
            try:
                me = await MUSIC_USER_CLIENT.get_me()
                account = safe_text(getattr(me, 'first_name', '') or 'حساب کاربری', 60)
                username = ('@'+me.username) if getattr(me, 'username', None) else 'بدون یوزرنیم'
                text = f'🟢 <b>حساب موزیکال متصل است</b>\n\n👤 {account}\n🔹 {safe_text(username,60)}'
            except Exception:
                text = '🟡 اتصال برقرار است ولی وضعیت حساب خوانده نشد.'
        else:
            text = '🔴 <b>حساب موزیکال متصل نیست.</b>'
        text += f'\n\n🔢 API ID: {"✅" if api_id and api_id.isdigit() else "❌"}\n🔐 API Hash: {"✅" if api_hash else "❌"}\n📱 شماره: {"✅" if phone else "❌"}\n💾 Session: {safe_text(session,80)}'
        await q.edit_message_text(text, parse_mode='HTML', reply_markup=keyboard([[btn('🔄 اتصال/ورود','own6:music_login')],[btn('🔙 تنظیمات موزیکال','own6:music')]])); return
    if action == 'music_login':
        fake = type('U', (), {'effective_user': q.from_user, 'effective_chat': q.message.chat, 'effective_message': q.message})()
        await _bb_music_user_login_begin(fake, context); return
    if action == 'music_clear':
        for key in MUSIC_SETTING_KEYS.values():
            await _bb_set_music_setting(key, '')
        global MUSIC_USER_PHONE, MUSIC_USER_SESSION
        MUSIC_USER_PHONE = ''
        MUSIC_USER_SESSION = str(Path.home() / 'bilbilak_music_user')
        OWNER_PENDING_MUSIC_SETTING.pop(q.from_user.id, None)
        await q.answer('تنظیمات اتصال پاک شد.', show_alert=True)
        await _bb_owner_music_settings_panel(q, context); return
    return await _OLD_OWNER_CALLBACK_V6_MUSIC(q, context)



_OLD_OWNER_CONTROL_TEXT_MUSIC = owner_control_text
async def owner_control_text(update, context):
    if await _bb_owner_music_setting_text(update, context):
        return True
    return await _OLD_OWNER_CONTROL_TEXT_MUSIC(update, context)


async def _bb_music_login_commands(update, context):
    if not update.effective_message or not update.effective_user:
        return False
    text = (update.effective_message.text or '').strip().lower()
    if text.startswith('/music_login'):
        return await _bb_music_user_login_begin(update, context)
    if text.startswith('/music_code'):
        return await _bb_music_user_login_code(update, context)
    if text.startswith('/music_2fa'):
        return await _bb_music_user_login_2fa(update, context)
    if text.startswith('/music_account'):
        return await _bb_music_account_status(update, context)
    if text.startswith('/music_logout'):
        return await _bb_music_account_logout(update, context)
    return False


async def _bb_single_pass_message_handler(update, context):
    """تنها یک مسیر پردازش پیام متنی؛ جلوی اجرای دوباره routerهای تاریخی فایل را می‌گیرد."""
    msg = update.effective_message
    if not msg:
        raise ApplicationHandlerStop
    try:
        if await _bb_music_login_commands(update, context):
            raise ApplicationHandlerStop
        # message_router is the final composed router and contains all existing features.
        await message_router(update, context)
    except ApplicationHandlerStop:
        raise
    except Exception as exc:
        log.exception('single-pass message handler failed: %s', exc)
        try:
            if getattr(msg, 'text', None):
                await msg.reply_text('⚠️ اجرای دستور با خطا مواجه شد؛ دوباره امتحان کن.')
        except Exception:
            pass
    raise ApplicationHandlerStop


# Keep the current builder intact, but put one authoritative text handler before
# every historical message handler. ApplicationHandlerStop prevents duplicate replies.
_BB_PREV_BUILD_ACCOUNT_FIX = build_application

def build_application(token: str) -> Application:
    app = _BB_PREV_BUILD_ACCOUNT_FIX(token)
    app.add_handler(
        CommandHandler('music_login', _bb_music_user_login_begin),
        group=-100,
    )
    app.add_handler(
        CommandHandler('music_code', _bb_music_user_login_code),
        group=-100,
    )
    app.add_handler(
        CommandHandler('music_2fa', _bb_music_user_login_2fa),
        group=-100,
    )
    app.add_handler(
        CommandHandler('music_account', _bb_music_account_status),
        group=-100,
    )
    app.add_handler(
        CommandHandler('music_logout', _bb_music_account_logout),
        group=-100,
    )
    app.add_handler(
        MessageHandler(filters.TEXT & ~filters.COMMAND, _bb_single_pass_message_handler),
        group=-9,
    )
    return app


