# Generic proxy for historical owner callbacks: if an old handler calls
# q.edit_message_text() while the panel is a photo, transparently redirect it
# to edit_caption(). This leaves every non-owner/group feature untouched.
class _BBPhotoSafeCallbackQuery:
    def __init__(self, q):
        self._q = q
        self.from_user = q.from_user
        self.message = q.message
        self.data = q.data

    async def answer(self, *args, **kwargs):
        return await self._q.answer(*args, **kwargs)

    async def edit_message_text(self, text, **kwargs):
        return await _bb_owner_safe_edit(self._q, text, **kwargs)

    async def edit_message_caption(self, caption=None, **kwargs):
        msg = self.message
        if msg is not None and getattr(msg, 'photo', None):
            return await msg.edit_caption(caption=caption, **kwargs)
        return await self._q.edit_message_text(caption, **kwargs)

    def __getattr__(self, name):
        return getattr(self._q, name)


_OLD_OWNER_CALLBACK_V6_PHOTO_SAFE = owner_callback_v6
async def owner_callback_v6(q, context):
    if getattr(getattr(q, 'message', None), 'photo', None):
        return await _OLD_OWNER_CALLBACK_V6_PHOTO_SAFE(_BBPhotoSafeCallbackQuery(q), context)
    return await _OLD_OWNER_CALLBACK_V6_PHOTO_SAFE(q, context)

# The historical owner-control callback also contains old edit_message_text
# calls. Wrap only that callback when it is invoked on the photo-based owner
# panel; ordinary group management callbacks remain unchanged.
_OLD_OWNER_CONTROL_CALLBACK_PHOTO_SAFE = owner_control_callback
async def owner_control_callback(q, context):
    if getattr(getattr(q, 'message', None), 'photo', None):
        return await _OLD_OWNER_CONTROL_CALLBACK_PHOTO_SAFE(_BBPhotoSafeCallbackQuery(q), context)
    return await _OLD_OWNER_CONTROL_CALLBACK_PHOTO_SAFE(q, context)


