BOT_ADMIN_TABLE_READY = False
CLEANUP_USER_CLIENT = None
CLEANUP_USER_PHONE = ''
CLEANUP_USER_CODE_HASH = None
CLEANUP_USER_LOGIN_STATE = None
CLEANUP_USER_LOGIN_LOCK = asyncio.Lock()
CLEANUP_USER_SESSION = str(Path.home() / 'bilbilak_cleanup_user')
OWNER_PENDING_CLEANUP_SETTING = {}
OWNER_PENDING_BOT_ADMIN = set()
