async def _bb_cleanup_settings_snapshot():
    await _bb_pro_schema()
    row = await DBX.one('SELECT * FROM cleanup_accounts_pro WHERE id=1')
    api_id = await _bb_get_music_setting('TELEGRAM_API_ID', os.getenv('TELEGRAM_API_ID',''))
    api_hash = await _bb_get_music_setting('TELEGRAM_API_HASH', os.getenv('TELEGRAM_API_HASH',''))
    phone = ((row['phone'] if row else '') or '').strip()
    session = ((row['session'] if row else '') or str(Path.home()/'bilbilak_cleanup_user')).strip()
    return api_id, api_hash, phone, session, row

async def _bb_cleanup_save(phone=None, session=None, account_user_id=None, account_name=None, status=None):
    await _bb_pro_schema()
    api_id, api_hash, old_phone, old_session, old = await _bb_cleanup_settings_snapshot()
    await DBX.execute(
        'INSERT INTO cleanup_accounts_pro(id,phone,session,account_user_id,account_name,enabled,last_status,created_at,updated_at) VALUES(1,?,?,?,?,1,?,?,?) '
        'ON CONFLICT(id) DO UPDATE SET phone=excluded.phone,session=excluded.session,account_user_id=excluded.account_user_id,account_name=excluded.account_name,enabled=1,last_status=excluded.last_status,updated_at=excluded.updated_at',
        (phone if phone is not None else old_phone, session if session is not None else old_session, int(account_user_id or 0) if account_user_id is not None else int((old['account_user_id'] if old else 0) or 0), account_name if account_name is not None else ((old['account_name'] if old else '') or ''), status if status is not None else ((old['last_status'] if old else '') or ''), now_ts(), now_ts())
    )

def _bb_pyrogram_client(api_id, api_hash, session, phone, name):
    try:
        from pyrogram import Client
    except Exception as exc:
        raise RuntimeError('Pyrogram نصب نیست.') from exc
    sp=Path(session).expanduser(); return Client(name=sp.stem or name, api_id=int(api_id), api_hash=api_hash, phone_number=phone, workdir=str(sp.parent))

async def _bb_cleanup_remove_session_files(session):
    """Remove only the cleanup account's Pyrogram session artifacts.
    This is used when Telegram invalidates the auth key or SQLite reports a stale lock.
    """
    try:
        sp = Path(session).expanduser()
        candidates = [sp]
        if sp.suffix != '.session':
            candidates.append(Path(str(sp) + '.session'))
        for suffix in ('-journal', '-wal', '-shm'):
            candidates.extend([Path(str(sp) + suffix), Path(str(sp) + '.session' + suffix)])
        for f in candidates:
            try:
                if f.exists():
                    f.unlink()
            except Exception as exc:
                log.warning('cleanup session artifact remove failed (%s): %s', f, exc)
    except Exception as exc:
        log.warning('cleanup session cleanup failed: %s', exc)

async def _bb_cleanup_connect_existing():
    global CLEANUP_USER_CLIENT, CLEANUP_USER_PHONE, CLEANUP_USER_SESSION, CLEANUP_USER_LOGIN_STATE
    async with CLEANUP_USER_LOGIN_LOCK:
        api_id, api_hash, phone, session, row = await _bb_cleanup_settings_snapshot()
        if not (api_id and api_id.isdigit() and api_hash and phone and session):
            return False, 'API ID، API Hash و شماره اکانت پاکسازی را از پنل مالک تنظیم کن.'
        CLEANUP_USER_PHONE, CLEANUP_USER_SESSION = phone, session
        client = None
        try:
            # Never allow two Pyrogram clients to open the same cleanup session DB.
            if CLEANUP_USER_CLIENT is not None:
                try:
                    if getattr(CLEANUP_USER_CLIENT, 'is_connected', False):
                        me = await CLEANUP_USER_CLIENT.get_me()
                        if me:
                            CLEANUP_USER_LOGIN_STATE = 'ready'
                            return True, 'متصل'
                except Exception:
                    pass
                try:
                    if getattr(CLEANUP_USER_CLIENT, 'is_connected', False):
                        await CLEANUP_USER_CLIENT.disconnect()
                except Exception:
                    pass
                CLEANUP_USER_CLIENT = None

            client = _bb_pyrogram_client(api_id, api_hash, session, phone, 'bilbilak_cleanup_user')
            await client.connect()
            me = await client.get_me()
            if not me:
                try: await client.disconnect()
                except Exception: pass
                return False, 'Session اکانت پاکسازی معتبر نیست.'
            CLEANUP_USER_CLIENT = client
            CLEANUP_USER_LOGIN_STATE = 'ready'
            await _bb_cleanup_save(account_user_id=me.id, account_name=display_name(me), status='متصل')
            return True, 'متصل'
        except Exception as exc:
            text = str(exc)
            upper = text.upper()
            try:
                if client is not None and getattr(client, 'is_connected', False):
                    await client.disconnect()
            except Exception:
                pass
            CLEANUP_USER_CLIENT = None
            if 'AUTH_KEY_UNREGISTERED' in upper:
                await _bb_cleanup_remove_session_files(session)
                CLEANUP_USER_LOGIN_STATE = None
                return False, 'Session قبلی اکانت پاکسازی باطل شده بود و حذف شد؛ دوباره «ورود/اتصال» را بزن تا کد جدید ارسال شود.'
            if 'DATABASE IS LOCKED' in upper or 'database is locked' in text:
                # A stale Pyrogram SQLite sidecar is a common cause on Android/Pydroid.
                await _bb_cleanup_remove_session_files(session)
                CLEANUP_USER_LOGIN_STATE = None
                return False, 'فایل Session اکانت پاکسازی قفل شده بود؛ قفل قدیمی پاک شد. حالا دوباره «ورود/اتصال» را بزن.'
            log.warning('cleanup account connect: %s', exc)
            return False, f'اتصال اکانت پاکسازی ناموفق بود: {type(exc).__name__}'

async def _bb_cleanup_login_begin(q, context):
    global CLEANUP_USER_CLIENT, CLEANUP_USER_CODE_HASH, CLEANUP_USER_LOGIN_STATE, CLEANUP_USER_PHONE, CLEANUP_USER_SESSION
    if not await _bb_is_bot_admin(q.from_user.id):
        await q.answer('⛔ دسترسی ندارید.', show_alert=True); return
    async with CLEANUP_USER_LOGIN_LOCK:
        api_id, api_hash, phone, session, row = await _bb_cleanup_settings_snapshot()
        if not (api_id and api_id.isdigit() and api_hash and phone):
            await q.message.reply_text('⚠️ اول API ID/API Hash و شماره اکانت پاکسازی را از همین پنل تنظیم کن.')
            return
        client = None
        try:
            if CLEANUP_USER_CLIENT and getattr(CLEANUP_USER_CLIENT,'is_connected',False):
                try:
                    me = await CLEANUP_USER_CLIENT.get_me()
                    if me:
                        CLEANUP_USER_LOGIN_STATE='ready'
                        await q.message.reply_text(f'🟢 اکانت پاکسازی از قبل متصل است: <b>{safe_text(display_name(me),60)}</b>', parse_mode='HTML')
                        return
                except Exception:
                    try: await CLEANUP_USER_CLIENT.disconnect()
                    except Exception: pass
                    CLEANUP_USER_CLIENT=None

            # Try the saved session first. If Telegram says its auth key is invalid,
            # remove it and immediately start a clean login with a fresh session file.
            client = _bb_pyrogram_client(api_id, api_hash, session, phone, 'bilbilak_cleanup_user')
            try:
                await client.connect()
                me = await client.get_me()
                if me:
                    CLEANUP_USER_CLIENT = client
                    CLEANUP_USER_PHONE, CLEANUP_USER_SESSION = phone, session
                    CLEANUP_USER_LOGIN_STATE='ready'
                    await _bb_cleanup_save(account_user_id=me.id, account_name=display_name(me), status='متصل')
                    await q.message.reply_text(f'🟢 <b>اکانت پاکسازی متصل شد.</b>\n\n👤 {safe_text(display_name(me),60)}', parse_mode='HTML')
                    return
            except Exception as session_exc:
                upper = str(session_exc).upper()
                try:
                    if getattr(client, 'is_connected', False): await client.disconnect()
                except Exception: pass
                client = None
                if 'AUTH_KEY_UNREGISTERED' not in upper and 'DATABASE IS LOCKED' not in upper:
                    raise
                await _bb_cleanup_remove_session_files(session)

            # Fresh session file; no old SQLite lock/auth key is reused.
            fresh = Path(session).expanduser()
            if fresh.suffix != '.session':
                fresh = Path(str(fresh) + '.session')
            # Pyrogram accepts a name without .session; use a unique fallback only when needed.
            fresh_name = str(fresh.with_suffix(''))
            client = _bb_pyrogram_client(api_id, api_hash, fresh_name, phone, 'bilbilak_cleanup_user')
            await client.connect()
            sent = await client.send_code(phone)
            CLEANUP_USER_CLIENT = client
            CLEANUP_USER_PHONE = phone
            CLEANUP_USER_SESSION = fresh_name
            CLEANUP_USER_CODE_HASH = sent.phone_code_hash
            CLEANUP_USER_LOGIN_STATE = 'code'
            await _bb_cleanup_save(session=fresh_name)
            await q.message.reply_text('📩 کد ورود برای اکانت پاکسازی ارسال شد. کد را فقط در PV ربات و با دستور «کد پاکسازی 12345» وارد کن؛ آن را برای من در چت دیگری نفرست.')
        except Exception as exc:
            CLEANUP_USER_LOGIN_STATE = None
            CLEANUP_USER_CODE_HASH = None
            try:
                if client and getattr(client,'is_connected',False): await client.disconnect()
            except Exception: pass
            CLEANUP_USER_CLIENT = None
            upper = str(exc).upper()
            if 'DATABASE IS LOCKED' in upper:
                await _bb_cleanup_remove_session_files(session)
                text='❌ فایل Session اکانت پاکسازی قفل است. قفل قدیمی پاک شد؛ یک بار دیگر «ورود/اتصال» را بزن.'
            else:
                text='❌ شروع ورود اکانت پاکسازی ناموفق بود: '+safe_text(str(exc),400)
            await q.message.reply_text(text)

async def _bb_cleanup_login_text(update, context):
    global CLEANUP_USER_LOGIN_STATE, CLEANUP_USER_CODE_HASH
    msg = update.effective_message
    if not msg or not update.effective_user or not await _bb_is_bot_admin(update.effective_user.id) or not msg.text: return False
    t = normalize(msg.text)
    if not t.startswith('کد پاکسازی '): return False
    code = t.replace('کد پاکسازی ','',1).strip()
    if not CLEANUP_USER_CLIENT or not CLEANUP_USER_CODE_HASH or CLEANUP_USER_LOGIN_STATE != 'code':
        await msg.reply_text('⚠️ ابتدا از پنل پاکسازی «ورود/اتصال» را بزن.'); return True
    try:
        await CLEANUP_USER_CLIENT.sign_in(CLEANUP_USER_PHONE, CLEANUP_USER_CODE_HASH, code)
        CLEANUP_USER_LOGIN_STATE='ready'
        me=await CLEANUP_USER_CLIENT.get_me()
        await _bb_cleanup_save(account_user_id=me.id,account_name=display_name(me),status='متصل')
        await msg.reply_text(f'🟢 <b>اکانت پاکسازی متصل شد.</b>\n\n👤 {safe_text(display_name(me),60)}',parse_mode='HTML')
    except Exception as exc:
        # Pyrogram's SessionPasswordNeeded is detected by name to avoid hard dependency on exception classes.
        if 'SessionPasswordNeeded' in type(exc).__name__ or 'PASSWORD' in str(exc).upper():
            CLEANUP_USER_LOGIN_STATE='2fa'
            await msg.reply_text('🔐 ورود دومرحله‌ای فعال است. رمز را فقط با «رمز پاکسازی ...» در همین PV وارد کن.')
        else:
            await msg.reply_text('❌ کد ورود نامعتبر یا منقضی شده است.')
    return True

async def _bb_cleanup_login_2fa_text(update, context):
    global CLEANUP_USER_LOGIN_STATE
    msg=update.effective_message
    if not msg or not update.effective_user or not await _bb_is_bot_admin(update.effective_user.id) or not msg.text: return False
    t=normalize(msg.text)
    if not t.startswith('رمز پاکسازی '): return False
    password=msg.text.split(' ',2)[2].strip() if len(msg.text.split(' ',2))>=3 else ''
    if not CLEANUP_USER_CLIENT or CLEANUP_USER_LOGIN_STATE!='2fa':
        await msg.reply_text('⚠️ ابتدا ورود اکانت پاکسازی را شروع کن.'); return True
    try:
        await CLEANUP_USER_CLIENT.check_password(password)
        CLEANUP_USER_LOGIN_STATE='ready'
        me=await CLEANUP_USER_CLIENT.get_me()
        await _bb_cleanup_save(account_user_id=me.id,account_name=display_name(me),status='متصل')
        await msg.reply_text(f'🟢 <b>اکانت پاکسازی متصل شد.</b>\n\n👤 {safe_text(display_name(me),60)}',parse_mode='HTML')
    except Exception:
        await msg.reply_text('❌ رمز دومرحله‌ای درست نبود.')
    return True

async def _bb_cleanup_account_status(q):
    ok, reason = await _bb_cleanup_connect_existing()
    if not ok:
        await q.message.reply_text('🔴 <b>اکانت پاکسازی آماده نیست.</b>\n\n'+safe_text(reason,700),parse_mode='HTML'); return
    me=await CLEANUP_USER_CLIENT.get_me()
    await q.message.reply_text(f'🟢 <b>اکانت پاکسازی متصل است.</b>\n\n👤 {safe_text(display_name(me),60)}\n🆔 {me.id}')

async def _bb_cleanup_group_check(chat_id):
    ok, reason = await _bb_cleanup_connect_existing()
    if not ok:
        return False, reason
    try:
        me = await CLEANUP_USER_CLIENT.get_me()
        if not me:
            return False, 'اکانت پاکسازی شناسایی نشد؛ اتصال اکانت را دوباره انجام بده.'

        member = await CLEANUP_USER_CLIENT.get_chat_member(int(chat_id), int(me.id))
        raw_status = getattr(member, 'status', '')
        status = getattr(raw_status, 'value', raw_status)
        status = str(status).strip().lower()
        if '.' in status:
            status = status.rsplit('.', 1)[-1]

        # Pyrogram versions can expose privileges either through
        # member.privileges or directly on the ChatMember object.
        priv = getattr(member, 'privileges', None)
        can_delete = getattr(priv, 'can_delete_messages', None) if priv is not None else None
        if can_delete is None:
            can_delete = getattr(member, 'can_delete_messages', None)

        log.info('cleanup group check: chat=%s account=%s status=%r can_delete=%r',
                 chat_id, me.id, status, can_delete)

        if status not in {'administrator', 'owner'}:
            return False, (
                f'اکانت پاکسازی با شناسه {me.id} در این گروه وضعیت ادمین ندارد.\n'
                f'وضعیت دریافت‌شده از تلگرام: {safe_text(status or "unknown",40)}\n\n'
                'اکانت را با همین شناسه وارد گروه کن و بعد از ورود، آن را ادمین کن.'
            )

        # Owner has all required management rights. For an administrator,
        # explicitly require delete-message permission when Telegram reports it.
        if status == 'administrator' and can_delete is False:
            return False, (
                f'اکانت پاکسازی ادمین است، اما دسترسی «حذف پیام‌ها» ندارد.\n'
                f'شناسه اکانت: {me.id}\n\n'
                'در تنظیمات ادمین گروه، اجازه حذف پیام‌ها را برای این اکانت فعال کن.'
            )

        return True, 'ok'
    except Exception as exc:
        log.warning('cleanup group check failed: chat=%s error=%r', chat_id, exc)
        return False, (
            'بررسی ادمین اکانت پاکسازی از طریق تلگرام انجام نشد.\n'
            f'خطای فنی: {safe_text(type(exc).__name__,80)}\n\n'
            'مطمئن شو اکانت پاکسازی واقعاً عضو همین گروه/سوپرگروه است و دسترسی حذف پیام دارد.'
        )

async def _bb_cleanup_run(chat_id, requester_id, mode='count', count=500):
    ok, reason = await _bb_cleanup_group_check(chat_id)
    if not ok: return {'error':reason}
    scanned=deleted=failed=0
    started=now_ts()
    run_id=0
    # Detailed breakdown for the final report.
    type_counts={
        'text':0,'photo':0,'video':0,'audio':0,'voice':0,
        'document':0,'sticker':0,'gif':0,'forward':0,'link':0,'service':0,'other':0
    }
    type_names={
        'text':'📝 متن','photo':'🖼 عکس','video':'🎬 ویدیو','audio':'🎵 صوت/آهنگ',
        'voice':'🎙 ویس','document':'📎 فایل','sticker':'🎭 استیکر','gif':'🎞 گیف',
        'forward':'↪️ فوروارد','link':'🔗 لینک','service':'⚙️ سرویس','other':'📦 سایر'
    }
    def classify_message(m):
        # One message can have several properties; report it by its most useful type.
        if getattr(m,'photo',None): return 'photo'
        if getattr(m,'video',None): return 'video'
        if getattr(m,'voice',None) or getattr(m,'video_note',None): return 'voice'
        if getattr(m,'audio',None): return 'audio'
        if getattr(m,'document',None): return 'document'
        if getattr(m,'sticker',None): return 'sticker'
        if getattr(m,'animation',None): return 'gif'
        if getattr(m,'forward_origin',None): return 'forward'
        txt=(getattr(m,'text',None) or getattr(m,'caption',None) or '')
        if txt and re.search(r'https?://|t\.me/|www\.',txt,re.I): return 'link'
        if getattr(m,'new_chat_members',None) or getattr(m,'left_chat_member',None) or getattr(m,'new_chat_title',None) or getattr(m,'new_chat_photo',None): return 'service'
        if txt: return 'text'
        return 'other'
    try:
        await _bb_pro_schema()
        # Support both the old cleanup_runs schema and the current PRO schema.
        cols = {str(r[1]) for r in await DBX.execute('PRAGMA table_info(cleanup_runs)', fetch=True)}
        if 'admin_id' in cols:
            cur=await DBX.execute(
                'INSERT INTO cleanup_runs(chat_id,admin_id,requester_id,mode,scanned,deleted,failed,started_at,finished_at) VALUES(?,?,?,?,?,?,?,?,?)',
                (chat_id,requester_id,requester_id,mode,0,0,0,started,0)
            )
        else:
            cur=await DBX.execute(
                'INSERT INTO cleanup_runs(chat_id,requester_id,mode,scanned,deleted,failed,started_at,finished_at) VALUES(?,?,?,?,?,?,?,?)',
                (chat_id,requester_id,mode,0,0,0,started,0)
            )
        run_id=cur.lastrowid if cur else 0
        limit = None if mode=='all' else max(1,min(int(count),5000))
        batch=[]
        batch_types=[]
        async for m in CLEANUP_USER_CLIENT.get_chat_history(chat_id, limit=limit):
            scanned += 1
            if mode not in {'all','count'} and not _bb_cleanup_match(m,mode):
                continue
            kind=classify_message(m)
            batch.append(m.id)
            batch_types.append(kind)
            if len(batch)>=100:
                try:
                    await CLEANUP_USER_CLIENT.delete_messages(chat_id,batch,revoke=True)
                    deleted += len(batch)
                    for k in batch_types: type_counts[k]=type_counts.get(k,0)+1
                except Exception:
                    for mid,kind in zip(batch,batch_types):
                        try:
                            await CLEANUP_USER_CLIENT.delete_messages(chat_id,[mid],revoke=True)
                            deleted+=1
                            type_counts[kind]=type_counts.get(kind,0)+1
                        except Exception:
                            failed+=1
                batch=[]; batch_types=[]
        if batch:
            try:
                await CLEANUP_USER_CLIENT.delete_messages(chat_id,batch,revoke=True)
                deleted+=len(batch)
                for k in batch_types: type_counts[k]=type_counts.get(k,0)+1
            except Exception:
                for mid,kind in zip(batch,batch_types):
                    try:
                        await CLEANUP_USER_CLIENT.delete_messages(chat_id,[mid],revoke=True)
                        deleted+=1
                        type_counts[kind]=type_counts.get(kind,0)+1
                    except Exception:
                        failed+=1
    except Exception as exc:
        failed += 1
        log.exception('cleanup run failed: %s',exc)
    finished=now_ts()
    # Reporting must never fail the cleanup result after messages have already been deleted.
    if run_id:
        try:
            await DBX.execute('UPDATE cleanup_runs SET scanned=?,deleted=?,failed=?,finished_at=? WHERE id=?',(scanned,deleted,failed,finished,run_id))
        except Exception as exc:
            log.warning('cleanup report db update failed: %r',exc)
    elapsed=max(0, finished-started)
    breakdown=[f'{type_names[k]}: <b>{v}</b>' for k,v in type_counts.items() if v]
    return {
        'scanned':scanned,'deleted':deleted,'failed':failed,'mode':mode,
        'elapsed':elapsed,'types':type_counts,'breakdown':breakdown
    }

def _bb_cleanup_match(m, mode):
    if mode=='text': return bool(getattr(m,'text',None))
    if mode=='photo': return bool(getattr(m,'photo',None))
    if mode=='video': return bool(getattr(m,'video',None))
    if mode=='audio': return bool(getattr(m,'audio',None))
    if mode=='voice': return bool(getattr(m,'voice',None) or getattr(m,'video_note',None))
    if mode=='document': return bool(getattr(m,'document',None))
    if mode=='sticker': return bool(getattr(m,'sticker',None))
    if mode=='gif': return bool(getattr(m,'animation',None))
    if mode=='forward': return bool(getattr(m,'forward_origin',None))
    if mode=='link':
        txt=(getattr(m,'text',None) or getattr(m,'caption',None) or '')
        return bool(re.search(r'https?://|t\.me/|www\.',txt,re.I))
    if mode=='service': return bool(getattr(m,'new_chat_members',None) or getattr(m,'left_chat_member',None) or getattr(m,'new_chat_title',None) or getattr(m,'new_chat_photo',None))
    return False

async def _bb_cleanup_group_router(update, context):
    msg=update.effective_message
    if not msg or not update.effective_chat or update.effective_chat.type=='private' or not msg.text: return False
    t=normalize(msg.text)
    if not t.startswith('پاکسازی'): return False
    if not await is_admin(update):
        await msg.reply_text('⛔ فقط ادمین واقعی گروه می‌تواند پاکسازی را اجرا کند.'); return True
    if not await active_vip(update.effective_chat.id):
        # Core cleanup remains available to normal groups; advanced whole-group/type cleanup is VIP.
        if t not in {'پاکسازی','پاکسازی 10','پاکسازی 30','پاکسازی 50','پاکسازی 100','پاکسازی 500'}:
            await msg.reply_text('🔒 این نوع پاکسازی پیشرفته فقط برای گروه VIP باز است.'); return True
    if t in {'پاکسازی','پاکسازی 10','پاکسازی 30','پاکسازی 50','پاکسازی 100','پاکسازی 500'}:
        n=int(t.split()[1]) if len(t.split())>1 else 100
        r=await _bb_cleanup_run(update.effective_chat.id,update.effective_user.id,'count',n)
    elif t=='پاکسازی همه':
        await msg.reply_text('🧹 شروع پاکسازی همه پیام‌های قابل حذف…')
        r=await _bb_cleanup_run(update.effective_chat.id,update.effective_user.id,'all')
    else:
        names={'متن':'text','عکس':'photo','ویدیو':'video','فیلم':'video','صوت':'audio','آهنگ':'audio','ویس':'voice','فایل':'document','سند':'document','استیکر':'sticker','گیف':'gif','فوروارد':'forward','لینک':'link','سرویس':'service'}
        key=t.replace('پاکسازی ','',1).strip()
        mode=names.get(key)
        if not mode:
            await msg.reply_text('🧹 گزینه‌ها: پاکسازی همه، پاکسازی 100، پاکسازی عکس، پاکسازی ویدیو، پاکسازی متن، پاکسازی ویس، پاکسازی فایل، پاکسازی لینک، پاکسازی فوروارد، پاکسازی استیکر، پاکسازی گیف')
            return True
        r=await _bb_cleanup_run(update.effective_chat.id,update.effective_user.id,mode,5000)
    if 'error' in r:
        await msg.reply_text('⚠️ <b>اکانت پاکسازی آماده نیست:</b>\n'+safe_text(r['error'],1000),parse_mode='HTML')
    else:
        breakdown='\n'.join(r.get('breakdown') or ['• موردی برای گزارش جزئی ثبت نشد'])
        await msg.reply_text(
            f'🧹 <b>گزارش کامل پاکسازی</b>\n\n'
            f'🔎 بررسی‌شده: <b>{r["scanned"]}</b>\n'
            f'🗑 حذف موفق: <b>{r["deleted"]}</b>\n'
            f'⚠️ ناموفق: <b>{r["failed"]}</b>\n'
            f'⏱ مدت اجرا: <b>{r.get("elapsed",0)} ثانیه</b>\n\n'
            f'<b>📊 تفکیک موارد حذف‌شده:</b>\n{breakdown}\n\n'
            'ℹ️ فقط پیام‌هایی حذف شده‌اند که Telegram اجازه حذفشان را داده است.',
            parse_mode='HTML'
        )
    return True

# -----------------------------------------------------------------------------
# Real AI audio generation: ElevenLabs Music + Sound Effects, optional Replicate fallback.
# -----------------------------------------------------------------------------
async def _bb_ai_key(name):
    return await _bb_pro_get(name, os.getenv(name,''))

async def _bb_http_post(url, headers, json_body=None, timeout=180):
    import requests
    def work():
        r=requests.post(url,headers=headers,json=json_body,timeout=timeout)
        r.raise_for_status()
        return r
    return await asyncio.to_thread(work)

async def _bb_generate_eleven_music(prompt, length_ms=30000, instrumental=False):
    key=await _bb_ai_key('ELEVENLABS_API_KEY')
    if not key: return None, 'ELEVENLABS_API_KEY تنظیم نشده است.'
    try:
        r=await _bb_http_post('https://api.elevenlabs.io/v1/music',{'xi-api-key':key,'Content-Type':'application/json'}, {'prompt':safe_text(prompt,4000),'music_length_ms':max(3000,min(int(length_ms),600000)),'model_id':'music_v2','force_instrumental':bool(instrumental)},300)
        path=Path(tempfile.gettempdir())/f'bilbilak_song_{now_ts()}_{random.randint(1000,9999)}.mp3'
        path.write_bytes(r.content)
        return path,None
    except Exception as exc:
        return None, f'تولید آهنگ ناموفق بود: {type(exc).__name__}'

async def _bb_generate_eleven_sfx(prompt, duration=5):
    key=await _bb_ai_key('ELEVENLABS_API_KEY')
    if not key:
        return None, 'ELEVENLABS_API_KEY تنظیم نشده است.'
    try:
        r=await _bb_http_post_raw(
            'https://api.elevenlabs.io/v1/sound-generation',
            {'xi-api-key':key,'Content-Type':'application/json','Accept':'audio/mpeg'},
            json_body={'text':safe_text(prompt,800),'duration_seconds':max(.5,min(float(duration),30)),'model_id':'eleven_text_to_sound_v2','prompt_influence':0.85},
            timeout=180)
        if not r.ok or not r.content or len(r.content)<500:
            body=(r.text or '').strip().replace('\n',' ')[:600]
            return None, f'ساخت صدای حیوان ناموفق بود: HTTP {r.status_code} {body}'
        path=Path(tempfile.gettempdir())/f'bilbilak_sfx_{now_ts()}_{random.randint(1000,9999)}.mp3'
        path.write_bytes(r.content)
        return path,None
    except Exception as exc:
        return None, f'ساخت صدای حیوان ناموفق بود: {type(exc).__name__}: {str(exc)[:300]}'

async def _bb_generate_song_for_user(msg, prompt, length_ms=30000, instrumental=False):
    await msg.reply_text('🎼 در حال ساخت آهنگ واقعی با سرویس تولید موسیقی…')
    path,err=await _bb_generate_eleven_music(prompt,length_ms,instrumental)
    if err:
        await msg.reply_text('❌ '+safe_text(err,500)); return True
    try:
        with open(path,'rb') as f:
            await msg.reply_audio(f,title='🎼 آهنگ ساخته‌شده توسط بیل بیلک',caption='🎼 تولید شد')
    finally:
        try: path.unlink(missing_ok=True)
        except Exception: pass
    return True

async def _bb_generate_animal_for_user(msg, animal):
    aliases={'سگ':'dog','گربه':'cat','شیر':'lion','گرگ':'wolf','اسب':'horse','گاو':'cow','گوسفند':'sheep','خرس':'bear','فیل':'elephant','میمون':'monkey','پرنده':'bird','مرغ':'chicken','خروس':'rooster','اردک':'duck','ببر':'tiger','پلنگ':'leopard','خر':'donkey','بز':'goat','روباه':'fox','زرافه':'giraffe','فیل':'elephant'}
    animal_raw=safe_text(animal,80).strip()
    species=aliases.get(normalize(animal_raw), animal_raw)
    prompt=(f'Create ONLY a realistic isolated {species} vocalization. One animal species only. No music, no human voice, no speech, no narrator, no other animals, no ambient soundtrack. Clean natural recording of the animal making its characteristic sound.')
    path,err=await _bb_generate_eleven_sfx(prompt,5)
    if err:
        await msg.reply_text('❌ '+safe_text(err,500)); return True
    try:
        with open(path,'rb') as f: await msg.reply_audio(f,title=f'صدای {animal}',caption=f'🐾 صدای {animal}')
    finally:
        try: path.unlink(missing_ok=True)
        except Exception: pass
    return True

