async def _bb_owner_pro_panel(q, context):
    if not await _bb_is_bot_admin(q.from_user.id): await q.answer('⛔ دسترسی ندارید.',show_alert=True); return
    await _bb_pro_schema()
    admins=await DBX.execute('SELECT user_id FROM bot_admins ORDER BY created_at',fetch=True)
    info=await _bb_pro_get('info_channel','')
    api=await _bb_ai_key('ELEVENLABS_API_KEY')
