# Add these pages to the existing user-help dictionary so the old help callback
# can also open them through help:<uid>:<page>.
for _k, _v in FULL_HELP_TEXTS.items():
    HELP_TEXTS[_k] = _v


async def _bb_help_is_privileged(uid, chat=None):
    """راهنمای مدیریتی فقط برای ادمین گروه/ادمین مرکزی باشد."""
    try:
        if await _bb_is_bot_admin(uid):
            return True
    except Exception:
        pass
    if chat is None or getattr(chat, 'type', None) == 'private':
        return False
    try:
        member = await chat.get_member(uid)
        status = getattr(member, 'status', None)
        value = getattr(status, 'value', status)
        return str(value).lower().split('.')[-1] in {'administrator', 'owner'}
    except Exception:
        return False


def _bb_complete_help_keyboard(uid, admin=False):
    """کیبورد راهنما بر اساس سطح دسترسی؛ اطلاعات مالک هرگز در راهنمای عمومی نیست."""
    rows = [
        [btn('👤 کاربری', f'help:{uid}:user'), btn('🎮 بازی و سرگرمی', f'help:{uid}:fun')],
        [btn('🧰 ابزارهای کامل', f'help:{uid}:tools_full'), btn('🎵 موزیکال', f'help:{uid}:music_full')],
    ]
    if admin:
        rows += [
            [btn('🛡 مدیریت گروه', f'help:{uid}:management_full'), btn('🧹 پاکسازی', f'help:{uid}:cleanup_full')],
            [btn('🎼 AI آهنگ/صدا', f'help:{uid}:ai_full'), btn('⌨️ دستورهای /', f'help:{uid}:slash')],
            [btn('🕵️ دکمه‌های مخفی و مسیرها', f'help:{uid}:hidden_paths')],
        ]
    rows.append([btn('🏠 پنل من', user_cb(uid, 'home'))])
    return keyboard(rows)


async def _bb_complete_help_page(q, uid, page):
    if uid != q.from_user.id:
        await q.answer('⛔ این راهنما برای کاربر دیگری است.', show_alert=True)
        return True

    # راهنمای مالک/سازنده فقط از پنل مالک قابل دسترسی است و در مرکز راهنما نمایش داده نمی‌شود.
    if page in {'owner_full', 'music_owner'}:
        await q.answer('🔒 راهنمای مالک فقط داخل پنل مالک در دسترس است.', show_alert=True)
        return True

    privileged_pages = {'management_full', 'cleanup_full', 'ai_full', 'slash', 'hidden_paths'}
    if page in privileged_pages:
        chat = getattr(q.message, 'chat', None)
        if not await _bb_help_is_privileged(uid, chat):
            await q.answer('⛔ این بخش فقط برای ادمین‌های گروه است.', show_alert=True)
            return True

    admin = await _bb_help_is_privileged(uid, getattr(q.message, 'chat', None))
    if page == 'all':
        if admin:
            text = (
                "🛡 <b>راهنمای کامل ادمین بیل بیلک</b>\n\n"
                "این راهنما برای ادمین‌های گروه است و بخش‌های کاربری، بازی، ابزار، موزیکال، مدیریت، پاکسازی، AI و دستورهای اسلش را شامل می‌شود.\n\n"
                "🔒 راهنمای سازنده/مالک و تنظیمات مرکزی در این راهنما نمایش داده نمی‌شود و فقط داخل پنل مالک است.\n\n"
                "💡 برای دیدن جزئیات هر بخش، دکمه‌های زیر را انتخاب کن."
            )
        else:
            text = (
                "📚 <b>راهنمای کاربری بیل بیلک</b>\n\n"
                "این راهنما مخصوص کاربر عادی است و فقط بخش‌های کاربری، بازی و سرگرمی، ابزارها و موزیکال را نشان می‌دهد.\n\n"
                "🔒 مدیریت گروه، پاکسازی، تنظیمات مرکزی و راهنمای مالک برای کاربران عادی نمایش داده نمی‌شود.\n\n"
                "💡 برای جزئیات هر بخش، دکمه‌های زیر را انتخاب کن."
            )
    else:
        text = FULL_HELP_TEXTS.get(page)
        if not text:
            return False
    await q.edit_message_text(text, parse_mode='HTML', reply_markup=keyboard([
        [btn('🔙 راهنمای من', f'help:{uid}:all'), btn('🏠 پنل من', user_cb(uid, 'home'))]
    ]))
    return True


# Final callback wrapper: route the expanded help pages before legacy callbacks.
_BB_HELP_BEFORE_COMPLETE = callback_router
async def callback_router(update, context):
    q = getattr(update, 'callback_query', None)
    if q:
        data = q.data or ''
        parts = data.split(':', 2)
        if len(parts) == 3 and parts[0] == 'help' and parts[1].isdigit():
            page = parts[2]
            if page in FULL_HELP_TEXTS:
                if await _bb_complete_help_page(q, int(parts[1]), page):
                    return
    return await _BB_HELP_BEFORE_COMPLETE(update, context)


