# =============================================================================
# FINAL WELCOME FIX — reliable welcome from both Telegram join update types
# Only affects welcome/goodbye join handling; all other features remain unchanged.
# =============================================================================
_BB_WELCOME_SENT = {}

async def _bb_delete_welcome_later(bot, chat_id, message_id):
    """Delete an automatic welcome message 45 seconds after it is sent."""
    try:
        await asyncio.sleep(45)
        await bot.delete_message(chat_id=chat_id, message_id=message_id)
    except Exception as e:
        log.debug('welcome auto-delete skipped: %s', e)

async def _bb_send_welcome_once(chat, user, context):
    """Send the configured welcome once, without a button, then delete it after 45s."""
    if not chat or not user or getattr(user, 'is_bot', False):
        return False
    try:
        c = await DBX.get_chat(chat.id)
        if not c or not int(c['welcome_enabled'] or 0):
            return False

        # Short in-memory deduplication prevents duplicate messages when both
        # Telegram update types arrive for the same join.
        key = (chat.id, user.id)
        now = time.time()
        old = _BB_WELCOME_SENT.get(key, 0.0)
        if now - old < 8.0:
            return False
        _BB_WELCOME_SENT[key] = now
        if len(_BB_WELCOME_SENT) > 5000:
            cutoff = now - 60.0
            for k, ts in list(_BB_WELCOME_SENT.items()):
                if ts < cutoff:
                    _BB_WELCOME_SENT.pop(k, None)

        text = render_group_text(
            c['welcome_text'] or
            '👋 خوش اومدی {name}! 🐾\nاز حضورت خوشحالیم؛ برای دیدن امکانات «راهنما» را بفرست.',
            user
        )
        kind = (c['welcome_media_type'] or '') if 'welcome_media_type' in c.keys() else ''
        file_id = (c['welcome_media_id'] or '') if 'welcome_media_id' in c.keys() else ''

        # Send only the welcome itself: no inline keyboard/button.
        if file_id and kind == 'photo':
            sent = await chat.send_photo(file_id, caption=text or '', parse_mode='HTML')
        elif file_id and kind == 'video':
            sent = await chat.send_video(file_id, caption=text or '', parse_mode='HTML')
        elif file_id and kind == 'animation':
            sent = await chat.send_animation(file_id, caption=text or '', parse_mode='HTML')
        else:
            sent = await context.bot.send_message(chat.id, text, parse_mode='HTML')

        # Automatic deletion exactly 45 seconds after the welcome is sent.
        if sent and getattr(sent, 'message_id', None):
            asyncio.create_task(_bb_delete_welcome_later(context.bot, chat.id, sent.message_id))
        return True
    except Exception as e:
        log.warning('welcome send failed: %s', e)
        return False

async def member_update_v6(update, context):
    """Final reliable member join/leave handler."""
    try:
        cm = getattr(update, 'chat_member', None)
        if not cm or not cm.chat or cm.chat.type == 'private':
            return
        old = cm.old_chat_member.status
        new = cm.new_chat_member.status
        user = cm.new_chat_member.user
        await DBX.ensure_chat(cm.chat)
        await DBX.ensure_user(user)
        active = {ChatMemberStatus.MEMBER, ChatMemberStatus.ADMINISTRATOR,
                  ChatMemberStatus.OWNER, ChatMemberStatus.RESTRICTED}
        joined = new in active and old in {ChatMemberStatus.LEFT, ChatMemberStatus.BANNED}
        left = new in {ChatMemberStatus.LEFT, ChatMemberStatus.BANNED} and old in active
        if joined:
            try:
                await DBX.execute(
                    'UPDATE chat_member_stats SET adds=COALESCE(adds,0)+1,first_name=?,username=? WHERE chat_id=? AND user_id=?',
                    (display_name(user), user.username or '', cm.chat.id, user.id)
                )
            except Exception:
                pass
            await _bb_send_welcome_once(cm.chat, user, context)
        elif left:
            try:
                c = await DBX.get_chat(cm.chat.id)
                if c and int(c['goodbye_enabled'] or 0):
                    text = render_group_text(
                        c['goodbye_text'] or '👋 {name} از {group} رفت. امیدواریم دوباره ببینیمت!', user
                    ).replace('{group}', cm.chat.title or 'گروه').replace('{group_name}', cm.chat.title or 'گروه')
                    await context.bot.send_message(cm.chat.id, text, parse_mode='HTML')
            except Exception as e:
                log.warning('goodbye send failed: %s', e)
    except Exception as e:
        log.warning('member update welcome handler failed: %s', e)

async def service_members_v4(update, context):
    """Handle Telegram's NEW_CHAT_MEMBERS service message as a second reliable
    welcome path. It also keeps the existing add-stat accounting."""
    msg = update.effective_message
    chat = update.effective_chat
    if not msg or not chat or chat.type == 'private':
        return
    new_members = list(getattr(msg, 'new_chat_members', None) or [])
    if not new_members:
        return
    if msg.from_user:
        actor = msg.from_user
        try:
            await DBX.ensure_user(actor)
            await DBX.execute(
                'INSERT OR IGNORE INTO chat_member_stats(chat_id,user_id,username,first_name,first_seen,last_seen,is_bot) VALUES(?,?,?,?,?,?,?)',
                (chat.id, actor.id, actor.username or '', actor.first_name or '', now_ts(), now_ts(), int(actor.is_bot))
            )
            await DBX.execute(
                'UPDATE chat_member_stats SET adds=COALESCE(adds,0)+? WHERE chat_id=? AND user_id=?',
                (len(new_members), chat.id, actor.id)
            )
            await record_stat(chat.id, 'adds', len(new_members))
        except Exception as e:
            log.warning('member add stats failed: %s', e)
    await DBX.ensure_chat(chat)
    for user in new_members:
        await DBX.ensure_user(user)
        if not getattr(user, 'is_bot', False):
            await _bb_send_welcome_once(chat, user, context)


