async def _bb_google_image_url(query):
    """Get a direct image URL from a Google Images result page."""
    import requests, re, html as _html
    try:
        url = "https://www.google.com/search?tbm=isch&q=" + quote_plus(query)
        def work():
            r = requests.get(url, headers={
                "User-Agent": "Mozilla/5.0 (Linux; Android 12) AppleWebKit/537.36 Chrome/120 Mobile Safari/537.36",
                "Accept-Language": "fa-IR,fa;q=0.9,en;q=0.8",
            }, timeout=4)
            r.raise_for_status()
            return r.text
        page = await asyncio.to_thread(work)
        # Google embeds image URLs in the result HTML. Prefer common image extensions.
        candidates = re.findall(r'https?://[^\"\\ ]+', page)
        good = []
        for x in candidates:
            x = _html.unescape(x).replace('\\u003d','=').replace('\\u0026','&').replace('\\/','/')
            if any(ext in x.lower().split('?')[0] for ext in ('.jpg','.jpeg','.png','.webp')):
                if 'gstatic.com' not in x and 'google.com' not in x:
                    good.append(x)
        if good:
            return random.choice(good[:20])
    except Exception as e:
        log.warning('google image search failed: %s', e)
    return None

async def _bb_google_profile_command(update, context, gender='random'):
    msg = update.effective_message
    if not msg:
        return True
    if gender == 'female':
        query = 'پروفایل دخترانه خفن با کیفیت'
        label = 'دخترانه'
    elif gender == 'male':
        query = 'پروفایل پسرانه خفن با کیفیت'
        label = 'پسرانه'
    else:
        query = random.choice(['پروفایل خفن با کیفیت', 'عکس پروفایل خاص', 'پروفایل مینیمال خفن'])
        label = 'تصادفی'
    image_url = await _bb_google_image_url(query)
    if image_url:
        try:
            # Download the selected result first so Telegram receives the actual image,
            # instead of depending on Telegram's ability to fetch the source URL.
            import requests, io
            def get_image():
                r = requests.get(image_url, headers={'User-Agent':'Mozilla/5.0'}, timeout=5)
                r.raise_for_status()
                return r.content
            image_bytes = await asyncio.to_thread(get_image)
            if image_bytes and len(image_bytes) > 1000:
                await msg.reply_photo(photo=io.BytesIO(image_bytes), caption=f'🖼️ پروفایل {label}\n\n🔎 انتخاب از Google Images')
                return True
        except Exception as e:
            log.warning('google profile image download/send failed: %s', e)
        try:
            # Second attempt: let Telegram fetch the source URL directly.
            await msg.reply_photo(photo=image_url, caption=f'🖼️ پروفایل {label}\n\n🔎 انتخاب از Google Images')
            return True
        except Exception as e:
            log.warning('google profile direct send failed: %s', e)
    # Fallback: provide the Google Images search itself if Telegram cannot fetch the image.
    search_url = 'https://www.google.com/search?tbm=isch&q=' + quote_plus(query)
    await msg.reply_text(f'🖼️ پروفایل {label}\n\nنتونستم عکس را مستقیم دریافت کنم؛ اینجا نتایج Google Images است:\n{search_url}')
    return True

# Wrap the actual rich text command router so these exact commands are handled
# before the old personal-profile implementation. "بیو متن" stays unchanged.
_BB_OLD_RICH_TEXT_COMMAND = rich_text_command
async def rich_text_command(update, context, t):
    if t == 'بیو':
        text = None
        try:
            import requests
            def work():
                r = requests.get('https://api.majidapi.ir/fun/bio', timeout=4,
                                 headers={'User-Agent':'Mozilla/5.0'})
                r.raise_for_status()
                return r.text
            raw = await asyncio.to_thread(work)
            try:
                data = json.loads(raw)
                if isinstance(data, dict):
                    for key in ('result','bio','text','message','data'):
                        if data.get(key):
                            text = str(data[key])
                            break
                elif isinstance(data, list) and data:
                    text = str(random.choice(data))
            except Exception:
                text = raw.strip()
        except Exception as e:
            log.warning('bio api failed: %s', e)
        if not text or len(text) > 800:
            text = random.choice(_BB_BIO_TEXTS)
        await update.effective_message.reply_text('🖤 <b>بیو خفن</b>\n\n' + safe_text(text, 700), parse_mode='HTML')
        return True
    # Random bio/profile tools are completely separate from the personal profile.
    if t in {'پروفایل', 'پروفایل خفن', 'عکس پروفایل'}:
        return await _bb_google_profile_command(update, context, 'random')
    if t in {'پروفایل دخترانه', 'پروف دخترانه', 'عکس پروفایل دخترانه'}:
        return await _bb_google_profile_command(update, context, 'female')
    if t in {'پروفایل پسرانه', 'پروف پسرانه', 'عکس پروفایل پسرانه'}:
        return await _bb_google_profile_command(update, context, 'male')

    # Personal profile aliases stay separate and never trigger the random tools.
    if t in {'پروفایل من', 'بیو من'}:
        return await _BB_OLD_RICH_TEXT_COMMAND(update, context, 'پروفایل' if t == 'پروفایل من' else 'بیو')

    # Personal profile: register origin and nickname.
    if t.startswith('ثبت اصل ') or t.startswith('اصل '):
        value = safe_text(update.effective_message.text.split(None, 2)[-1], 120)
        await DBX.execute("INSERT OR IGNORE INTO user_profiles(user_id) VALUES(?)", (update.effective_user.id,))
        await DBX.execute("UPDATE user_profiles SET origin=? WHERE user_id=?", (value, update.effective_user.id))
        await update.effective_message.reply_text(f'🌍 <b>اصل</b> با موفقیت ثبت شد:\n\n{safe_text(value,120)}', parse_mode='HTML')
        return True
    if t.startswith('ثبت لقب ') or t.startswith('لقب '):
        value = safe_text(update.effective_message.text.split(None, 2)[-1], 80)
        if not value:
            await update.effective_message.reply_text('🏷️ بعد از «ثبت لقب» اسم لقب را هم بنویس.')
            return True
        # Use the dedicated member_labels table. It is created safely with IF NOT EXISTS
        # and avoids schema races in older user_profiles databases.
        return await bb_profile_label(update, 'nickname', value)

    return await _BB_OLD_RICH_TEXT_COMMAND(update, context, t)


