# FINAL ALL-IN-ONE HARDENING PATCH — 2026-09-11
# =============================================================================
# این لایه فقط قابلیت‌های درخواستیِ امن و قابل‌اجرای Telegram را کامل‌تر می‌کند
# و روی معماری قبلی سوار می‌شود تا بخش‌های نامرتبط فایل دست‌نخورده بمانند.

from datetime import date as _bb_date
try:
    from zoneinfo import ZoneInfo as _BBZoneInfo
except Exception:
    _BBZoneInfo = None

_BB_TZ = os.getenv('BILBILAK_TZ', 'Asia/Tehran')
_BB_FA_WEEKDAYS = ['دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه','شنبه','یکشنبه']
_BB_FA_MONTHS = ['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند']
_BB_EN_MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December']
_BB_FA_DIGITS = str.maketrans('0123456789','۰۱۲۳۴۵۶۷۸۹')

def _bb_local_now():
    try:
        if _BBZoneInfo:
            return datetime.now(_BBZoneInfo(_BB_TZ))
    except Exception:
        pass
    return datetime.now()

def _bb_fa_num(x):
    return str(x).translate(_BB_FA_DIGITS)

def _bb_jalali_fallback(gy, gm, gd):
    # الگوریتم استاندارد تبدیل میلادی به جلالی، بدون وابستگی اجباری.
    g_days_in_month=[31,28,31,30,31,30,31,31,30,31,30,31]
    j_days_in_month=[31,31,31,31,31,31,30,30,30,30,30,29]
    gy2=gy-1600; gm2=gm-1; gd2=gd-1
    g_day_no=365*gy2+(gy2+3)//4-(gy2+99)//100+(gy2+399)//400
    for i in range(gm2): g_day_no+=g_days_in_month[i]
    if gm2>1 and ((gy%4==0 and gy%100!=0) or gy%400==0): g_day_no+=1
    g_day_no+=gd2; j_day_no=g_day_no-79
    j_np=j_day_no//12053; j_day_no%=12053
    jy=979+33*j_np+4*(j_day_no//1461); j_day_no%=1461
    if j_day_no>=366:
        jy+=(j_day_no-1)//365; j_day_no=(j_day_no-1)%365
    i=0
    while i<11 and j_day_no>=j_days_in_month[i]:
        j_day_no-=j_days_in_month[i]; i+=1
    return jy, i+1, j_day_no+1

def _bb_jalali(when):
    try:
        import jdatetime
        j=jdatetime.datetime.fromgregorian(datetime=when.replace(tzinfo=None))
        return int(j.year),int(j.month),int(j.day)
    except Exception:
        return _bb_jalali_fallback(when.year,when.month,when.day)

def _bb_hijri(when):
    for modname in ('hijri_converter','hijridate'):
        try:
            if modname=='hijri_converter':
                from hijri_converter import Gregorian
                h=Gregorian(when.year,when.month,when.day).to_hijri()
                return int(h.year),int(h.month),int(h.day),str(h.month_name()) if hasattr(h,'month_name') else ''
            from hijridate import Gregorian
            h=Gregorian(when.year,when.month,when.day).to_hijri()
            return int(h.year),int(h.month),int(h.day),''
        except Exception:
            pass
    return 1448,3,29,'ربیع‌الاول'

def _bb_progress(done,total,width=5):
    pct=max(0,min(100,round(done*100/total))) if total else 0
    filled=round(width*pct/100)
    return pct, '▰'*filled+'▱'*(width-filled)

def _bb_date_panel_text():
    now=_bb_local_now(); jy,jm,jd=_bb_jalali(now); hy,hm,hd,hmn=_bb_hijri(now)
    jstart = datetime(jy,3,21,tzinfo=now.tzinfo) if jm>=1 else datetime(jy,3,21,tzinfo=now.tzinfo)
    # استفاده از کتابخانه جلالی برای طول سال در صورت وجود
    try:
        import jdatetime
        jstart_g=jdatetime.date(jy,1,1).togregorian()
        next_g=jdatetime.date(jy+1,1,1).togregorian()
        elapsed=(now.date()-jstart_g).days+1
        remaining=(next_g-now.date()).days
        total=elapsed+remaining
    except Exception:
        elapsed=(now.date()-date(jy+621,3,21)).days+1
        total=365
        remaining=max(0,total-elapsed)
    gp_elapsed=now.timetuple().tm_yday
    gp_total=366 if ((now.year%4==0 and now.year%100!=0) or now.year%400==0) else 365
    gp_remaining=gp_total-gp_elapsed
    jp,jbar=_bb_progress(elapsed,total,5); gpercent,gbar=_bb_progress(gp_elapsed,gp_total,5)
    weekday=_BB_FA_WEEKDAYS[now.weekday()]
    fa_date=f'{_bb_fa_num(jy):>4}/{_bb_fa_num(jm).zfill(2)}/{_bb_fa_num(jd).zfill(2)}'
    en_date=f'{now.strftime("%Y/%m/%d")}'
    hmonth=hmn or ['محرم','صفر','ربیع‌الاول','ربیع‌الثانی','جمادی‌الاول','جمادی‌الثانی','رجب','شعبان','رمضان','شوال','ذی‌القعده','ذی‌الحجه'][hm-1]
    return (
        '📅 <b>تاریخ / ساعت بیل بیلک</b>\n\n'
        '〰️〰️〰️〰️〰️〰️〰️\n\n'
        f'⏰ ساعت : <b>{_bb_fa_num(now.strftime("%H:%M:%S"))}</b>\n'
        f'📅 تاریخ : <b>{weekday} - {fa_date} ({_BB_FA_MONTHS[jm-1]})</b>\n\n'
        f'🌙 تاریخ قمری : <b>{weekday} - {_bb_fa_num(hy)}/{_bb_fa_num(hm).zfill(2)}/{_bb_fa_num(hd).zfill(2)} ({hmonth})</b>\n'
        f'☀️ تاریخ میلادی : <b>{now.strftime("%A")} - {en_date} ({_BB_EN_MONTHS[now.month-1]})</b>\n\n'
        '🎉 تا پایان سال (شمسی)\n'
        f'┘─ 📅 روز های سپری شده : <b>{_bb_fa_num(elapsed)} روز</b>\n'
        f'┘─ ⌛️ روز های باقی مانده : <b>{_bb_fa_num(remaining)} روز</b>\n'
        f'‏┘─ 🛍 {jp}% {jbar}\n\n'
        '🎄 تا پایان سال (میلادی)\n'
        f'┘─ 📅 روز های سپری شده : <b>{gp_elapsed} روز</b>\n'
        f'┘─ ⌛️ روز های باقی مانده : <b>{gp_remaining} روز</b>\n'
        f'‏┘─ 🛍 {gpercent}% {gbar}\n\n'
        '〰️〰️〰️〰️〰️〰️〰️'
    )

async def _bb_final_schema():
    await DBX.execute("CREATE TABLE IF NOT EXISTS bb_message_daily(chat_id INTEGER NOT NULL,user_id INTEGER NOT NULL,day TEXT NOT NULL,messages INTEGER DEFAULT 0,PRIMARY KEY(chat_id,user_id,day))")
    await DBX.execute("CREATE INDEX IF NOT EXISTS idx_bb_message_daily_chat_day ON bb_message_daily(chat_id,day)")
    await DBX.execute("CREATE TABLE IF NOT EXISTS bb_required_targets(chat_id INTEGER NOT NULL,target TEXT NOT NULL,kind TEXT DEFAULT 'join',PRIMARY KEY(chat_id,target,kind))")
    await DBX.execute("CREATE TABLE IF NOT EXISTS bb_optin_users(user_id INTEGER PRIMARY KEY, opted_at INTEGER DEFAULT 0)")
    await DBX.execute("CREATE TABLE IF NOT EXISTS bb_user_titles(chat_id INTEGER NOT NULL,user_id INTEGER NOT NULL,title TEXT DEFAULT '',PRIMARY KEY(chat_id,user_id))")
    await DBX.execute("CREATE TABLE IF NOT EXISTS bb_announcement(chat_id INTEGER PRIMARY KEY,channel TEXT DEFAULT '',footer TEXT DEFAULT '')")

async def _bb_final_record_message(update):
    msg=update.effective_message; chat=update.effective_chat; user=update.effective_user
    if not msg or not chat or not user or chat.type=='private': return
    try:
        day=_bb_local_now().strftime('%Y-%m-%d')
        await DBX.execute("INSERT INTO bb_message_daily(chat_id,user_id,day,messages) VALUES(?,?,?,1) ON CONFLICT(chat_id,user_id,day) DO UPDATE SET messages=messages+1",(chat.id,user.id,day))
        await DBX.ensure_user(user); await DBX.ensure_chat(chat)
        await DBX.execute("INSERT OR IGNORE INTO chat_member_stats(chat_id,user_id,username,first_name,first_seen,last_seen,is_bot) VALUES(?,?,?,?,?,?,?)",(chat.id,user.id,user.username or '',user.first_name or '',now_ts(),now_ts(),int(user.is_bot)))
        await DBX.execute("UPDATE chat_member_stats SET messages=COALESCE(messages,0)+1,last_seen=?,username=?,first_name=? WHERE chat_id=? AND user_id=?",(now_ts(),user.username or '',user.first_name or '',chat.id,user.id))
    except Exception as e: log.debug('final message stats: %s',e)

async def _bb_final_announcement(chat_id):
    try:
        r=await DBX.one('SELECT channel,footer FROM bb_announcement WHERE chat_id=?',(chat_id,))
        if not r: return ''
        ch=(r['channel'] or '').strip(); ft=(r['footer'] or '').strip()
        if ch or ft:
            return '\n\n━━━━━━━━━━━━━━\n'+(f'📢 اطلاعیه: {ch}' if ch else '')+(f'\n{ft}' if ft else '')
    except Exception: pass
    return ''

async def _bb_final_date_command(update, context):
    msg=update.effective_message
    if msg:
        await msg.reply_text(_bb_date_panel_text(),parse_mode='HTML')
        if update.effective_chat and update.effective_chat.type!='private':
            try: await msg.reply_text(await _bb_final_announcement(update.effective_chat.id),parse_mode='HTML') if await _bb_final_announcement(update.effective_chat.id) else None
            except Exception: pass
    return True

async def _bb_final_stats(update, mode='روزانه'):
    chat=update.effective_chat; msg=update.effective_message
    if not chat or chat.type=='private': return False
    if not await is_admin(update):
        await msg.reply_text('⛔ این گزارش فقط برای ادمین‌های واقعی گروه است.'); return True
    days={'روزانه':1,'هفتگی':7,'ماهانه':30}.get(mode,1)
    rows=await DBX.execute("SELECT user_id,SUM(messages) messages FROM bb_message_daily WHERE chat_id=? AND day>=date('now',?) GROUP BY user_id ORDER BY messages DESC",(chat.id,f'-{days-1} day'),fetch=True)
    total=sum(int(r['messages'] or 0) for r in rows)
    top=[]
    for i,r in enumerate(rows[:10],1):
        u=await DBX.one('SELECT first_name,username FROM users WHERE user_id=?',(r['user_id'],))
        name=(u['first_name'] if u else '') or ((('@'+u['username']) if u and u['username'] else '') if u else '') or str(r['user_id'])
        top.append(f'{i}. <b>{safe_text(name,40)}</b> — {int(r["messages"] or 0):,} پیام')
    text=f'📊 <b>آمار دقیق {mode}</b>\n\n💬 مجموع پیام‌ها: <b>{total:,}</b>\n👥 کاربران فعال: <b>{len(rows):,}</b>\n\n🔥 <b>فعال‌ترین اعضا</b>\n'+'\n'.join(top or ['هنوز آماری ثبت نشده.'])
    await msg.reply_text(text+await _bb_final_announcement(chat.id),parse_mode='HTML')
    return True

async def _bb_final_tag_users(update, mode='all'):
    msg=update.effective_message; chat=update.effective_chat
    if not msg or not chat or chat.type=='private': return True
    if not await is_admin(update): await msg.reply_text('⛔ فقط ادمین واقعی.'); return True
    data=await DBX.execute('SELECT user_id,first_name,username,is_bot FROM chat_member_stats WHERE chat_id=? ORDER BY last_seen DESC LIMIT 1000',(chat.id,),fetch=True)
    if mode=='bots': data=[x for x in data if x['is_bot']]
    elif mode=='admins':
        admins=await chat.get_administrators(); ids={a.user.id for a in admins}; data=[x for x in data if x['user_id'] in ids and not x['is_bot']]
    else: data=[x for x in data if not x['is_bot']]
    if not data:
        await msg.reply_text('👥 هنوز اعضای کافی برای تگ در پایگاه داده ربات ثبت نشده‌اند. ربات باید پیام/عضویت آن‌ها را دیده باشد.')
        return True
    chunks=[]; cur=''
    for x in data:
        u=type('U',(),{'id':x['user_id'],'first_name':x['first_name'] or 'کاربر','username':x['username'] or ''})()
        tag=mention_html(u)
        if len(cur)+len(tag)+2>3200: chunks.append(cur); cur=''
        cur += tag+'  '
    if cur: chunks.append(cur)
    for i,ch in enumerate(chunks,1): await msg.reply_text(f'🏷️ <b>تگ {mode}</b> — {i}/{len(chunks)}\n\n{ch}',parse_mode='HTML')
    return True

async def _bb_final_tag_panel_callback(q):
    if not q or not (q.data or '').startswith('bbtag:'): return False
    _,uid,mode=q.data.split(':',2); uid=int(uid)
    if q.from_user.id!=uid: await q.answer('🔒 این پنل برای شخص دیگری است.',show_alert=True); return True
    fake=type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat,'effective_message':q.message})()
    await _bb_final_tag_users(fake,mode); 
    try: await q.message.delete()
    except Exception: pass
    return True

async def _bb_final_moderation_text(update, context):
    msg=update.effective_message; chat=update.effective_chat; t=_bb_plain_tool_text(getattr(msg,'text','') or '')
    if not msg or not chat or chat.type=='private': return False
    if t in {'آنپین','رفع پین','حذف پین'}:
        if not await is_admin(update): await msg.reply_text('⛔ فقط ادمین.'); return True
        try:
            if msg.reply_to_message: await context.bot.unpin_chat_message(chat.id,msg.reply_to_message.message_id)
            else: await context.bot.unpin_chat_message(chat.id)
            await msg.reply_text('📌 پین با موفقیت برداشته شد. 🐾')
        except TelegramError as e: await msg.reply_text('⚠️ برداشتن پین انجام نشد؛ دسترسی ربات را بررسی کن.')
        return True
    if t in {'آنبن','رفع بن'}:
        if not await is_admin(update): await msg.reply_text('⛔ فقط ادمین.'); return True
        target=getattr(msg.reply_to_message,'from_user',None)
        if not target: await msg.reply_text('👤 روی پیام کاربر بن‌شده ریپلای کن و «آنبن» بفرست.'); return True
        try: await context.bot.unban_chat_member(chat.id,target.id,only_if_banned=True); await msg.reply_text(f'🔓 {mention_html(target)} از بن خارج شد.',parse_mode='HTML')
        except TelegramError: await msg.reply_text('⚠️ رفع بن انجام نشد؛ ممکن است کاربر بن نباشد یا دسترسی کافی وجود نداشته باشد.')
        return True
    m=re.match(r'^(?:لقب|عنوان)\s+(.+)$',t)
    if m:
        if not await is_admin(update): await msg.reply_text('⛔ فقط ادمین.'); return True
        target=getattr(msg.reply_to_message,'from_user',None)
        if not target: await msg.reply_text('🏷️ روی پیام کاربر ریپلای کن و «لقب متن» را بفرست.'); return True
        title=safe_text(m.group(1),80)
        await DBX.execute('INSERT INTO bb_user_titles(chat_id,user_id,title) VALUES(?,?,?) ON CONFLICT(chat_id,user_id) DO UPDATE SET title=excluded.title',(chat.id,target.id,title))
        # اگر هدف ادمین باشد، عنوان واقعی تلگرام هم تلاش می‌شود.
        try:
            cm=await context.bot.get_chat_member(chat.id,target.id)
            if cm.status in {ChatMemberStatus.ADMINISTRATOR,ChatMemberStatus.OWNER} and cm.status==ChatMemberStatus.ADMINISTRATOR:
                await context.bot.set_chat_administrator_custom_title(chat.id,target.id,title)
                await msg.reply_text(f'👑 عنوان تلگرامی {mention_html(target)} روی «{safe_text(title,80)}» تنظیم شد.',parse_mode='HTML')
            else:
                await msg.reply_text(f'🏷️ لقب {mention_html(target)} ذخیره شد.\nℹ️ عنوان رسمی Telegram فقط برای ادمین‌ها قابل ثبت است.',parse_mode='HTML')
        except Exception:
            await msg.reply_text(f'🏷️ لقب {mention_html(target)} ذخیره شد.',parse_mode='HTML')
        return True
    if t.startswith('آمار '):
        return await _bb_final_stats(update,t.split(None,1)[1].strip())
    if t in {'آمار دقیق','آمار','آمار روزانه','آمار هفتگی','آمار ماهانه'}:
        return await _bb_final_stats(update, t.split()[-1] if t.split()[-1] in {'روزانه','هفتگی','ماهانه'} else 'روزانه')
    if t in {'تگ همه کاربران','تگ همه','تگ اعضا'}:
        return await _bb_final_tag_users(update,'all',context=context)
    if t in {'تگ ربات ها','تگ ربات‌ها'}:
        return await _bb_final_tag_users(update,'bots',context=context)
    if t in {'تگ ادمین ها','تگ ادمین‌ها'}:
        return await _bb_final_tag_users(update,'admins',context=context)
    if t=='تگ پنل':
        if not await is_admin(update): await msg.reply_text('⛔ فقط ادمین.'); return True
        if not msg.reply_to_message: await msg.reply_text('🏷️ «تگ پنل» باید روی پیام موردنظر ریپلای شود.'); return True
        await msg.reply_text('🏷️ <b>پنل تگ</b>\n\nانتخاب کن کدام گروه از اعضا روی پیام ریپلای‌شده تگ شوند.',parse_mode='HTML',reply_markup=keyboard([[btn('👥 همه اعضای شناخته‌شده',f'bbtag:{update.effective_user.id}:all')],[btn('🤖 ربات‌ها',f'bbtag:{update.effective_user.id}:bots'),btn('👑 ادمین‌ها',f'bbtag:{update.effective_user.id}:admins')]]))
        return True
    return False

async def _bb_final_add_command(update, context):
    """سیستم VIP دعوت امن: فقط کاربرانی که قبلاً با ربات تعامل داشته‌اند و امکان
    دعوت‌شان توسط Telegram وجود دارد پردازش می‌شوند؛ Bot API اجازه add مستقیم هر
    user_id دلخواه را نمی‌دهد، بنابراین موفقیت جعلی گزارش نمی‌شود."""
    msg=update.effective_message; chat=update.effective_chat; t=_bb_plain_tool_text(getattr(msg,'text','') or '')
    m=re.fullmatch(r'اد\s+([1-9][0-9]?)',t)
    if not m or not chat or chat.type=='private': return False
    if not await is_admin(update): await msg.reply_text('⛔ فقط ادمین واقعی گروه می‌تواند این دستور VIP را اجرا کند.'); return True
    try:
        if not await active_vip(chat.id): await msg.reply_text('💎 قابلیت «اد ۱ تا ۱۰۰» فقط برای گروه VIP فعال است.'); return True
    except Exception: await msg.reply_text('💎 وضعیت VIP گروه قابل بررسی نیست.'); return True
    slot=int(m.group(1)); row=await DBX.one('SELECT user_id,first_name,username FROM users ORDER BY user_id LIMIT 1 OFFSET ?',(slot-1,))
    if not row: await msg.reply_text(f'❌ کاربر شماره {slot} در فهرست کاربران شناخته‌شده پیدا نشد.'); return True
    target_id=int(row['user_id'])
    try:
        member=await context.bot.get_chat_member(chat.id,target_id)
        if member.status not in {ChatMemberStatus.LEFT,ChatMemberStatus.BANNED}: await msg.reply_text('ℹ️ این کاربر همین حالا عضو گروه است.'); return True
    except Exception: pass
    try:
        # Telegram Bot API intentionally does not expose arbitrary-user add.
        invite=await context.bot.create_chat_invite_link(chat.id,member_limit=1,name=f'VIP-{slot}')
        await msg.reply_text(f'💎 <b>دعوت VIP آماده شد</b>\n\n👤 کاربر: {target_id}\n🔢 شماره فهرست: <b>{slot}</b>\n\n🔗 لینک یک‌بارمصرف/محدود: {invite.invite_link}\n\n⚠️ کاربر باید خودش وارد لینک شود؛ Telegram اجازه Add مستقیم هر ID دلخواه را به Bot API نمی‌دهد.',parse_mode='HTML')
    except TelegramError:
        await msg.reply_text('⚠️ ساخت لینک دعوت انجام نشد؛ ربات باید دسترسی مدیریت دعوت‌ها را داشته باشد.')
    return True

async def _bb_final_forcejoin_check(update, context):
    chat=update.effective_chat; user=update.effective_user; msg=update.effective_message
    if not chat or chat.type=='private' or not user or not msg or await is_admin(update,user.id): return False
    try: rows=await DBX.execute("SELECT target,kind FROM bb_required_targets WHERE chat_id=?",(chat.id,),fetch=True)
    except Exception: return False
    if not rows: return False
    vip=False
    try: vip=bool(await active_vip(chat.id))
    except Exception: pass
    # normal=5, VIP=10
    rows=rows[:10 if vip else 5]
    missing=[]
    for r in rows:
        target=r['target']
        try:
            cm=await context.bot.get_chat_member(target,user.id)
            if cm.status in {ChatMemberStatus.LEFT,ChatMemberStatus.BANNED}: missing.append(target)
        except Exception: missing.append(target)
    if not missing: return False
    try: await msg.delete()
    except Exception: pass
    buttons=[]
    for target in missing:
        url=target if str(target).startswith('http') else 'https://t.me/'+str(target).lstrip('@')
        buttons.append([btn('📢 عضویت: '+str(target)[:30],url=url)])
    buttons.append([btn('🔄 بررسی دوباره',f'bbfj:{user.id}')])
    await context.bot.send_message(chat.id,'🔐 <b>ورود به گروه کامل نشده!</b>\n\nبرای ادامه فعالیت، اول عضو مقصدهای اجباری شو و بعد «بررسی دوباره» را بزن. 🐾',parse_mode='HTML',reply_markup=keyboard(buttons))
    return True

async def _bb_final_forcejoin_callback(q,context):
    if not q or not (q.data or '').startswith('bbfj:'): return False
    uid=int(q.data.split(':')[1])
    if q.from_user.id!=uid: await q.answer('🔒 این دکمه برای کاربر دیگری است.',show_alert=True); return True
    fake=type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat,'effective_message':q.message})()
    blocked=await _bb_final_forcejoin_check(fake,context)
    if not blocked:
        await q.answer('✅ عضویت تأیید شد؛ خوش آمدی! 🐾',show_alert=True)
        try: await q.message.delete()
        except Exception: pass
    else: await q.answer('❌ هنوز در یکی از مقصدها عضو نیستی.',show_alert=True)
    return True

async def _bb_final_admin_config(update, context):
    msg=update.effective_message; chat=update.effective_chat; t=_bb_plain_tool_text(getattr(msg,'text','') or '')
    if not msg or not chat or chat.type=='private' or not await is_admin(update): return False
    m=re.match(r'^جوین اجباری\s+(.+)$',t)
    if m:
        target=m.group(1).strip()
        if target.lower() in {'off','خاموش'}:
            await DBX.execute('DELETE FROM bb_required_targets WHERE chat_id=?',(chat.id,)); await msg.reply_text('🔓 جوین اجباری این گروه خاموش شد.'); return True
        vip=bool(await active_vip(chat.id))
        count=int((await DBX.execute('SELECT COUNT(*) n FROM bb_required_targets WHERE chat_id=?',(chat.id,),fetch=True))[0]['n'])
        limit=10 if vip else 5
        if count>=limit: await msg.reply_text(f'⚠️ سقف مقصدهای جوین اجباری در این سطح {limit} مورد است.'); return True
        await DBX.execute('INSERT OR IGNORE INTO bb_required_targets(chat_id,target,kind) VALUES(?,?,?)',(chat.id,target,'join'))
        await msg.reply_text(f'🔐 مقصد اجباری ثبت شد: <b>{safe_text(target,100)}</b>\n📦 ظرفیت: {count+1}/{limit}',parse_mode='HTML'); return True
    m=re.match(r'^کانال اعلان\s*(.*)$',t)
    if m:
        ch=m.group(1).strip()
        await DBX.execute('INSERT INTO bb_announcement(chat_id,channel,footer) VALUES(?,?,?) ON CONFLICT(chat_id) DO UPDATE SET channel=excluded.channel',(chat.id,ch,''))
        await msg.reply_text('📢 کانال اعلان ذخیره شد. از این به بعد پیام‌های بخش‌های نهایی می‌توانند اعلان را نمایش دهند.'); return True
    m=re.match(r'^متن اعلان\s+(.+)$',t)
    if m:
        await DBX.execute('INSERT INTO bb_announcement(chat_id,channel,footer) VALUES(?,?,?) ON CONFLICT(chat_id) DO UPDATE SET footer=excluded.footer',(chat.id,'',safe_text(m.group(1),1000)))
        await msg.reply_text('📝 متن اعلان ذخیره شد.'); return True
    return False

