async def _bb_music_play_audio_final(chat_id,url,title='',thumbnail=None,add_to_queue=True):
    item={'title':title or 'موزیک','url':url,'is_video':False,'is_live':False,'requester_id':0,'requester_name':'','duration':0,'thumbnail':thumbnail}
    if add_to_queue: await _music_queue_add(chat_id,item)
    if not MUSIC_VC_ENGINE or not MUSIC_USER_CLIENT: raise RuntimeError('حساب شخصی موزیکال یا موتور PyTgCalls آماده نیست.')
    play=getattr(MUSIC_VC_ENGINE,'play',None)
    if play:
        try:
            r=play(chat_id,url)
            if hasattr(r,'__await__'): await r
        except TypeError:
            r=play(chat_id,_MusicMediaStream(url))
            if hasattr(r,'__await__'): await r
    else:
        stream=_MusicMediaStream(url) if _MusicMediaStream else None
        await join_voice_call(chat_id,stream)
    MUSIC_CURRENT[chat_id]={**item,'started_at':_music_time.time(),'position':0,'duration':item.get('duration') or 0}
    return len(MUSIC_QUEUE.get(chat_id,[]))

async def _bb_music_pause_final(chat_id):
    if MUSIC_VC_ENGINE:
        fn=getattr(MUSIC_VC_ENGINE,'pause_stream',None) or getattr(MUSIC_VC_ENGINE,'pause',None)
        if fn:
            r=fn(chat_id); 
            if hasattr(r,'__await__'): await r
            return True
    return False

async def _bb_music_resume_final(chat_id):
    if MUSIC_VC_ENGINE:
        fn=getattr(MUSIC_VC_ENGINE,'resume_stream',None) or getattr(MUSIC_VC_ENGINE,'resume',None)
        if fn:
            r=fn(chat_id); 
            if hasattr(r,'__await__'): await r
            return True
    return False

async def _bb_music_stop_final(chat_id):
    MUSIC_CURRENT.pop(chat_id,None)
    if MUSIC_VC_ENGINE:
        fn=getattr(MUSIC_VC_ENGINE,'leave_call',None) or getattr(MUSIC_VC_ENGINE,'leave_group_call',None)
        if fn:
            r=fn(chat_id); 
            if hasattr(r,'__await__'): await r
            return True
    return False

async def _bb_music_volume_final(chat_id,volume):
    volume=max(0,min(200,int(volume))); MUSIC_VOLUME[chat_id]=volume; MUSIC_CURRENT.setdefault(chat_id,{})['volume']=volume
    if MUSIC_VC_ENGINE:
        fn=getattr(MUSIC_VC_ENGINE,'change_volume_call',None) or getattr(MUSIC_VC_ENGINE,'change_volume',None) or getattr(MUSIC_VC_ENGINE,'set_volume',None)
        if fn:
            try:
                r=fn(chat_id,volume); 
                if hasattr(r,'__await__'): await r
            except Exception: pass
    return volume

# Only replace these runtime names; historical callers automatically use the fixed implementation.
play_audio=_bb_music_play_audio_final
pause_call=_bb_music_pause_final
resume_call=_bb_music_resume_final
stop_call=_bb_music_stop_final
_bb_music_set_volume=_bb_music_volume_final

