_BB_BUILD_BEFORE_ALLINONE=build_application
async def _bb_allinone_message_handler(update,context):
    try:
        await _bb_final_record_message(update)
        if await _bb_final_forcejoin_check(update,context): raise ApplicationHandlerStop
        if await _bb_final_admin_config(update,context): raise ApplicationHandlerStop
        if await _bb_final_add_command(update,context): raise ApplicationHandlerStop
        msg=update.effective_message; t=_bb_plain_tool_text(getattr(msg,'text','') or '') if msg else ''
        if t in {'تاریخ','تاریخ و زمان'}: await _bb_final_date_command(update,context); raise ApplicationHandlerStop
        if await _bb_final_moderation_text(update,context): raise ApplicationHandlerStop
    except ApplicationHandlerStop: raise
    except Exception as e: log.exception('all-in-one guard: %s',e)
    # never stop unrelated legacy features


def build_application(token: str) -> Application:
    app=_BB_BUILD_BEFORE_ALLINONE(token)
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,_bb_allinone_message_handler),group=-1000)
    app.add_handler(CallbackQueryHandler(_bb_final_tag_panel_callback),group=-1000)
    app.add_handler(CallbackQueryHandler(_bb_final_forcejoin_callback),group=-999)
    return app

_BB_POST_BEFORE_ALLINONE=post_init
async def post_init(application):
    await _BB_POST_BEFORE_ALLINONE(application)
    try:
        await _bb_final_schema()
        await _bb_music_seed_defaults()
        # Session is validated at startup, but failure is non-fatal: the owner can
        # reconnect from the panel without killing the bot process.
        ok,reason=await _bb_music_lazy_connect()
        if not ok: log.warning('Music startup check: %s',reason)
    except Exception as e: log.exception('final startup patch failed: %s',e)

