# --- Music account: load owner-panel settings before every connection attempt.
async def _bb_music_lazy_connect():
    global MUSIC_VC_ENGINE, MUSIC_VC_STARTED, MUSIC_VC_AVAILABLE, MUSIC_USER_SESSION, MUSIC_USER_PHONE
    try:
        api_id, api_hash, phone, session = await _bb_music_settings_snapshot()
        if api_id:
            os.environ['TELEGRAM_API_ID'] = str(api_id)
        if api_hash:
            os.environ['TELEGRAM_API_HASH'] = str(api_hash)
        if phone:
            os.environ['MUSIC_USER_PHONE'] = str(phone)
            MUSIC_USER_PHONE = str(phone)
        if session:
            MUSIC_USER_SESSION = str(Path(session).expanduser())
            os.environ['MUSIC_USER_SESSION'] = MUSIC_USER_SESSION
        # A running client is only accepted if Telegram can answer get_me().
        if MUSIC_USER_CLIENT is not None and getattr(MUSIC_USER_CLIENT, 'is_connected', False):
            try:
                me = await MUSIC_USER_CLIENT.get_me()
                if me and MUSIC_VC_ENGINE is not None and MUSIC_VC_STARTED:
                    MUSIC_VC_AVAILABLE = True
                    return True, ''
            except Exception:
                pass
        ok, info = await _bb_music_user_start_existing()
        if not ok:
            # اولین اجرا: ورود کامل از خود ترمینال انجام می‌شود و session ذخیره می‌گردد.
            ok, info = await _bb_music_terminal_login(api_id, api_hash, phone)
        if ok:
            MUSIC_VC_STARTED = True
            MUSIC_VC_AVAILABLE = True
            return True, ''
        return False, 'حساب شخصی موزیکال به‌طور کامل احراز نشده یا موتور PyTgCalls قابل استفاده نیست.'
    except Exception as exc:
        log.exception('final music lazy connect failed: %s', exc)
        MUSIC_VC_STARTED = False
        MUSIC_VC_AVAILABLE = False
        return False, safe_text(str(exc), 500)

async def _bb_music_personal_photo_file():
    """Download the personal music account avatar temporarily for the panel."""
    try:
        if MUSIC_USER_CLIENT is None or not getattr(MUSIC_USER_CLIENT, 'is_connected', False):
            return None
        me = await MUSIC_USER_CLIENT.get_me()
        photos = await MUSIC_USER_CLIENT.get_profile_photos(me.id, limit=1)
        if not photos:
            return None
        photo = photos[0]
        path = MUSIC_TMP_DIR / f'music_account_avatar_{me.id}.jpg'
        try:
            result = await MUSIC_USER_CLIENT.download_media(photo.file_id, file_name=str(path))
            return str(result or path) if Path(str(result or path)).exists() else None
        except Exception:
            return None
    except Exception:
        return None

async def _bb_music_resolve_source(url, is_video=False, is_live=False):
    """Resolve public webpage URLs to direct media URLs when yt-dlp can do so."""
    url=(url or '').strip()
    if not url:
        raise ValueError('لینک خالی است.')
    if re.match(r'^https?://[^ ]+\.(?:m3u8|mp4|mp3|aac|ogg|webm)(?:\?.*)?$', url, re.I):
        return url, {}
    if _music_yt_dlp is None:
        return url, {}
    def _extract():
        opts=_music_ydl_options(audio_only=not is_video, download=False)
        opts['skip_download']=True
        opts['noplaylist']=True
        if is_live:
            opts['live_from_start']=False
        with _music_yt_dlp.YoutubeDL(opts) as ydl:
            info=ydl.extract_info(url, download=False)
            direct=info.get('url')
            if not direct and info.get('requested_formats'):
                direct=info['requested_formats'][0].get('url')
            return direct or url, info
    return await _music_asyncio.to_thread(_extract)

async def _bb_music_play_now(chat_id, item):
    """Start one item immediately using the configured personal account."""
    ok, reason = await _bb_music_lazy_connect()
    if not ok:
        raise RuntimeError(reason)
    ok, reason = await _bb_music_personal_group_check(chat_id)
    if not ok:
        raise RuntimeError(reason)
    direct, info = await _bb_music_resolve_source(item.get('url'), bool(item.get('is_video')), bool(item.get('is_live')))
    item=dict(item)
    item['source_url']=direct
    item['duration']=item.get('duration') or (info.get('duration') if isinstance(info,dict) else 0) or 0
    item['started_at']=_music_time.time()
    item['position']=0
    item['paused_at']=None
    # Current and older PyTgCalls APIs are handled without assuming one version.
    play=getattr(MUSIC_VC_ENGINE,'play',None) if MUSIC_VC_ENGINE else None
    if play:
        last=None
        for source in (direct, _MusicMediaStream(direct) if _MusicMediaStream else None):
            if source is None: continue
            try:
                r=play(chat_id, source)
                if hasattr(r,'__await__'): await r
                last=None
                break
            except Exception as exc:
                last=exc
        if last is not None:
            raise last
    else:
        stream=_MusicMediaStream(direct) if _MusicMediaStream else None
        if stream is None or not await ensure_voice_call(chat_id, stream):
            raise RuntimeError('PyTgCalls نتوانست Voice Chat را شروع کند.')
    MUSIC_CURRENT[chat_id]=item
    return item

async def _bb_music_start_or_queue(chat_id, item, panel_message=None, bot=None):
    queue=MUSIC_QUEUE.setdefault(chat_id, [])
    if MUSIC_CURRENT.get(chat_id):
        queue.append(item)
        return False, None
    started=await _bb_music_play_now(chat_id,item)
    owner=int(item.get('requester_id') or 0)
    panel=await _bb_music_render_panel(chat_id,owner,message=panel_message,bot=bot)
    if panel:
        await _bb_music_start_refresh(chat_id,owner,panel)
    return True,panel

# --- Better multi-platform live search, limited to public pages/sources.
async def _bb_public_domain_search(query, domains, limit=5):
    try:
        from urllib.parse import quote_plus
        from urllib.request import Request, urlopen
        from html import unescape
        q=quote_plus(query)
        html=await _music_asyncio.to_thread(lambda: urlopen(Request('https://html.duckduckgo.com/html/?q='+q,headers={'User-Agent':'Mozilla/5.0'}),timeout=12).read().decode('utf-8','ignore'))
        out=[]
        for m in re.finditer(r'class="result__a"[^>]*href="([^"]+)"[^>]*>(.*?)</a>',html,re.I|re.S):
            url=unescape(re.sub('<.*?>','',m.group(1)))
            title=unescape(re.sub('<.*?>',' ',m.group(2))).strip()
            if not any(d in url.lower() for d in domains): continue
            out.append({'title':title or 'Live','url':url,'duration':0,'thumbnail':None,'uploader':'','is_live':True})
            if len(out)>=limit: break
        return out
    except Exception as exc:
        log.warning('public live search failed: %s',exc)
        return []

async def search_kick_live(query): return await _bb_public_domain_search(query+' live',['kick.com'])
async def search_twitch_live(query): return await _bb_public_domain_search(query+' live',['twitch.tv'])
async def search_aparat_live(query): return await _bb_public_domain_search(query+' live',['aparat.com'])

