# --- Final music text router. Other bot commands are left untouched.
async def _bb_music_message_router_final(update, context):
    msg=update.effective_message; chat=update.effective_chat; user=update.effective_user
    if not msg or not chat or not user or not getattr(msg,'text',None): return False
    raw=msg.text.strip(); low=_music_clean_query(raw).lower()

    # ------------------------------------------------------------------
    # Per-group VIP music switch.  The global owner (6801805335) can turn
    # music on/off for this group without disabling the group's VIP itself.
    # Newly activated VIP groups default to music_enabled=1.
    # ------------------------------------------------------------------
    if chat.type != 'private':
        music_toggle = re.fullmatch(r'موزیکال\s+(روشن|خاموش)', raw, re.I)
        music_words = (
            low in {'موزیکال','music','موزیک','صف','queue','بعدی','skip','قبلی','previous','مکث','pause',
                    'ادامه','resume','پلی','play','اتمام','توقف','stop'}
            or bool(re.match(r'^(?:پخش آهنگ|پخش فیلم|پخش سریال|لایو|live|پخش لایو|رادیو|ریمیکس|استریم|پخش ورزش|صدا|volume|ساخت آهنگ|ساخت موزیک)\b', raw, re.I))
        )

        if music_toggle:
            if not await owner_check(user.id):
                await msg.reply_text('⛔ فقط مالک اصلی ربات می‌تواند موزیکال این گروه را روشن یا خاموش کند.')
                return True
            if not await active_vip(chat.id):
                await msg.reply_text('💎 ابتدا VIP این گروه را فعال کن؛ تنظیم موزیکال فقط برای گروه VIP ذخیره می‌شود.')
                return True
            await ensure_vip_row(chat.id)
            enabled = 1 if music_toggle.group(1) == 'روشن' else 0
            await DBX.execute('UPDATE vip_settings SET music_enabled=?,updated_at=? WHERE chat_id=?',(enabled,now_ts(),chat.id))
            if not enabled:
                # Stop current playback and clear the local queue when the owner disables music.
                try: await _bb_music_stop_final(chat.id)
                except Exception: pass
                MUSIC_QUEUE[chat.id]=[]
                MUSIC_PENDING_LIVE.pop(chat.id,None)
                MUSIC_PANEL_META.pop(chat.id,None)
                task=MUSIC_REFRESH_TASKS.pop(chat.id,None)
                if task:
                    try: task.cancel()
                    except Exception: pass
            await msg.reply_text(('🎵 موزیکال این گروه خاموش شد.' if not enabled else '🎵 موزیکال این گروه روشن شد؛ VIP همچنان فعال است.'))
            return True

        if low in {'وضعیت موزیکال','وضعیت موزیک','music status'}:
            if not await active_vip(chat.id):
                await msg.reply_text('💎 VIP این گروه فعال نیست.')
                return True
            enabled = await vip_feature(chat.id,'music')
            await msg.reply_text('🎵 <b>وضعیت موزیکال</b>\n\n' + ('🟢 فعال' if enabled else '🔴 خاموش') + '\n\n👑 تغییر این وضعیت فقط توسط مالک اصلی ربات انجام می‌شود.',parse_mode='HTML')
            return True

        if music_words:
            if not await active_vip(chat.id):
                await msg.reply_text('💎 قابلیت موزیکال فقط در گروه VIP فعال است.')
                return True
            if not await vip_feature(chat.id,'music'):
                await msg.reply_text('🔴 موزیکال برای این گروه توسط مالک خاموش شده است.')
                return True

    # If the user selected «لینک مستقیم» in the live picker, the next public URL is played.
    pending=MUSIC_PENDING_LIVE.get(chat.id)
    if chat.type!='private' and pending and pending.get('requester_id')==user.id and _music_time.time()-pending.get('created',0)<=600 and re.fullmatch(r'https?://\S+',raw,re.I):
        item={'title':'پخش زنده مستقیم','url':raw,'is_video':False,'is_live':True,'requester_id':user.id,'requester_name':user.first_name or 'کاربر','duration':0,'thumbnail':None}
        try:
            await _bb_music_start_or_queue(chat.id,item,panel_message=None,bot=msg.get_bot())
            MUSIC_PENDING_LIVE.pop(chat.id,None)
            await msg.reply_text('📡 لایو به پخش اضافه شد؛ اگر پخش دیگری در جریان باشد در صف قرار می‌گیرد.')
        except Exception as exc:
            await msg.reply_text('⚠️ پخش لینک مستقیم انجام نشد: '+safe_text(str(exc),500))
        return True
    if chat.type=='private':
        if low in {'موزیکال','music','موزیک'} and await owner_check(user.id):
            await _bb_music_owner_panel_photo(update,context); return True
        return False
    if re.match(r'^(?:پخش آهنگ|پخش فیلم|پخش سریال|لایو|live|پخش لایو|رادیو|ریمیکس|استریم|پخش ورزش)\b',raw,re.I) is None and low not in {'صف','queue','بعدی','قبلی','مکث','pause','ادامه','resume','پلی','اتمام','توقف','stop'} and not re.match(r'^(?:صدا|volume)\s+\d+',raw,re.I):
        return False
    if low in {'صف','queue'}:
        q=MUSIC_QUEUE.get(chat.id) or []
        await msg.reply_text('📋 <b>صف پخش</b>\n\n'+('\n'.join(f'{i}. {safe_text(x.get("title"),100)}' for i,x in enumerate(q,1)) or 'صف خالی است.'),parse_mode='HTML'); return True
    if low in {'مکث','pause'}:
        ok=await pause_playback(chat.id)
        try: await pause_call(chat.id)
        except Exception: pass
        await msg.reply_text('⏸️ پخش مکث شد.' if ok else '❌ چیزی در حال پخش نیست.'); return True
    if low in {'ادامه','resume','پلی','play'}:
        ok=await resume_playback(chat.id)
        try: await resume_call(chat.id)
        except Exception: pass
        await msg.reply_text('▶️ پخش ادامه یافت.' if ok else '❌ پخش فعالی نداریم.'); return True
    if low in {'بعدی','skip'}:
        item=await _bb_music_skip(chat.id)
        await msg.reply_text('⏭️ '+(safe_text(item.get('title'),100) if item else 'صف تمام شد.')); return True
    if low in {'قبلی','previous'}:
        item=await _bb_music_prev(chat.id)
        await msg.reply_text('⏮️ '+(safe_text(item.get('title'),100) if item else 'مورد قبلی نداریم.')); return True
    if low in {'اتمام','توقف','stop'}:
        await _bb_music_stop_final(chat.id); await clear_queue(chat.id); MUSIC_HISTORY.pop(chat.id,None); MUSIC_PANEL_META.pop(chat.id,None)
        task=MUSIC_REFRESH_TASKS.pop(chat.id,None)
        if task: task.cancel()
        await msg.reply_text('⏹️ پخش تمام شد؛ Voice Chat گروه خاموش نشد و فقط حساب موزیکال از پخش خارج شد.'); return True
    m=re.match(r'^(?:صدا|volume)\s+(\d{1,3})$',raw,re.I)
    if m:
        v=await _bb_music_set_volume(chat.id,int(m.group(1))); await msg.reply_text(f'🔊 صدا روی <b>{v}%</b> قرار گرفت.',parse_mode='HTML'); return True
    m=re.match(r'^(?:پخش لایو|لایو|live|استریم|پخش ورزش)\s+(.+)$',raw,re.I)
    if m:
        query=_music_clean_query(m.group(1)); MUSIC_PENDING_LIVE[chat.id]={'query':query,'requester_id':user.id,'requester_name':user.first_name or 'کاربر','created':_music_time.time()}
        await _bb_live_picker(msg,query); return True
    patterns=[(r'^پخش آهنگ\s+(.+)$',False,False),(r'^پخش فیلم\s+(.+)$',True,False),(r'^پخش سریال\s+(.+)$',True,False),(r'^رادیو\s+(.+)$',False,True),(r'^ریمیکس\s+(.+)$',False,False)]
    for pat,is_video,is_live in patterns:
        m=re.match(pat,raw,re.I)
        if not m: continue
        query=_music_clean_query(m.group(1))
        results=await music_search(query + (' remix' if 'ریمیکس' in raw else ''))
        if not results:
            await msg.reply_text('❌ نتیجه عمومی پیدا نشد یا yt-dlp روی سرور نصب نیست.'); return True
        MUSIC_SEARCH_CACHE[f'{chat.id}:last']=results
        rows=[]
        for i,item in enumerate(results[:10],1):
            rows.append([btn(f'🎧 {i}. {safe_text(item.get("title") or "بدون عنوان",55)} • {_music_format_time(item.get("duration"))}',f'mplay:{chat.id}:{user.id}:{i}')])
        await msg.reply_text('🔎 <b>نتایج موزیکال</b>\n\nیکی را انتخاب کن؛ اگر چیزی در حال پخش باشد، مورد جدید به صف می‌رود.',parse_mode='HTML',reply_markup=keyboard(rows)); return True
    return False

_bb_music_message_router = _bb_music_message_router_final

async def _bb_music_result_callback_final(update, context):
    q=getattr(update,'callback_query',None)
    if not q or not (q.data or '').startswith('mplay:'): return False
    try:
        _,chat_raw,owner_raw,index_raw=q.data.split(':',3); chat_id=int(chat_raw); owner_id=int(owner_raw); index=int(index_raw)
        if q.from_user.id!=owner_id:
            await q.answer('🔒 این پنل مربوط به درخواست‌کننده است و تو نمی‌توانی از آن استفاده کنی.',show_alert=True); return True
        results=MUSIC_SEARCH_CACHE.get(f'{chat_id}:last') or []
        if not 1<=index<=len(results): await q.answer('❌ نتیجه منقضی شده؛ دوباره جستجو کن.',show_alert=True); return True
        x=results[index-1]
        item={'title':x.get('title') or 'بدون عنوان','url':x.get('url'),'is_video':False,'is_live':False,'requester_id':owner_id,'requester_name':q.from_user.first_name or 'کاربر','duration':x.get('duration') or 0,'thumbnail':x.get('thumbnail')}
        if x.get('is_video'): item['is_video']=True
        try:
            await _bb_music_start_or_queue(chat_id,item,panel_message=None,bot=q.message.get_bot())
            try: await q.message.delete()
            except Exception: pass
            await q.answer('✅ پخش شروع شد یا به صف اضافه شد.')
        except Exception as exc:
            await q.answer('⚠️ پخش انجام نشد.',show_alert=True)
            await q.message.reply_text('⚠️ <b>حساب موزیکال آماده نیست یا Voice Chat قابل استفاده نیست.</b>\n\n'+safe_text(str(exc),700),parse_mode='HTML')
        return True
    except Exception as exc:
        log.exception('final music result callback: %s',exc); return True

async def _bb_music_live_callback_final(update, context):
    q=getattr(update,'callback_query',None)
    if not q or not (q.data or '').startswith('livepick:'): return False
    platform=q.data.split(':',1)[1]
    chat_id=q.message.chat.id
    pending=MUSIC_PENDING_LIVE.get(chat_id)
    if not pending or _music_time.time()-pending.get('created',0)>600:
        await q.answer('⏳ درخواست لایو منقضی شده؛ دوباره جستجو کن.',show_alert=True); return True
    if q.from_user.id!=pending['requester_id']:
        await q.answer('🔒 این انتخاب برای درخواست‌کننده دیگری است.',show_alert=True); return True
    if platform=='direct':
        await q.answer('لینک مستقیم را به‌صورت پیام بفرست.',show_alert=False); return True
    query=pending['query']
    if platform=='youtube': results=await search_youtube_live(query)
    elif platform=='kick': results=await search_kick_live(query)
    elif platform=='twitch': results=await search_twitch_live(query)
    elif platform=='aparat': results=await search_aparat_live(query)
    else:
        results=[]
        for fn in (search_youtube_live,search_kick_live,search_twitch_live,search_aparat_live):
            try: results.extend(await fn(query))
            except Exception: pass
    if not results:
        await q.answer('❌ لایو عمومی پیدا نشد.',show_alert=True); return True
    MUSIC_SEARCH_CACHE[f'{chat_id}:last']=results[:10]
    rows=[[btn(f'📡 {i}. {safe_text(x.get("title") or "Live",55)}',f'mplaylive:{chat_id}:{pending["requester_id"]}:{i}')] for i,x in enumerate(results[:10],1)]
    try: await q.message.edit_text('📡 <b>نتایج پخش زنده</b>\n\nیک مورد را انتخاب کن:',parse_mode='HTML',reply_markup=keyboard(rows))
    except Exception: await q.message.reply_text('📡 <b>نتایج پخش زنده</b>',parse_mode='HTML',reply_markup=keyboard(rows))
    await q.answer(); return True

async def _bb_music_live_result_callback_final(update, context):
    q=getattr(update,'callback_query',None)
    if not q or not (q.data or '').startswith('mplaylive:'): return False
    _,chat_raw,owner_raw,index_raw=q.data.split(':',3); chat_id=int(chat_raw); owner_id=int(owner_raw); index=int(index_raw)
