async def _bb_music_download_callback_final(update, context):
    q=getattr(update,'callback_query',None)
    if not q or not (q.data or '').startswith('mdownload:'): return False
    _,chat_raw,owner_raw=q.data.split(':',2); chat_id=int(chat_raw); owner_id=int(owner_raw)
    if q.from_user.id!=owner_id:
        await q.answer('🔒 این پنل مربوط به درخواست‌کننده است و تو نمی‌توانی از آن استفاده کنی.',show_alert=True); return True
    state=MUSIC_CURRENT.get(chat_id) or {}
    if not state or state.get('is_video') or state.get('is_live'):
        await q.answer('⬇️ دریافت فایل فقط برای آهنگ فعال است.',show_alert=True); return True
    try:
        await q.answer('⬇️ در حال آماده‌سازی فایل...')
        info,path,folder=await _music_download_online(state.get('url'),audio_only=True)
        with open(path,'rb') as fh:
            await q.message.reply_document(document=fh,filename=path.name,caption='🎵 '+safe_text(state.get('title'),120))
        import shutil; shutil.rmtree(folder,ignore_errors=True)
    except Exception as exc:
        await q.message.reply_text('❌ دریافت فایل انجام نشد: '+safe_text(str(exc),500))
    return True

# Panel gets file download and keeps requester lock.
def _bb_music_panel_buttons(chat_id, owner_id):
    """پنل مدیریت موزیکال با چیدمان نزدیک به نمونه تصویری کاربر.

    فقط UI/callbackهای پنل را می‌سازد؛ موتور پخش و صف در توابع موجود باقی می‌مانند.
    """
    p = f'mctrl:{chat_id}:{owner_id}'
    state = MUSIC_CURRENT.get(chat_id) or {}
    speed = MUSIC_SPEED[chat_id]
    eq = MUSIC_EQ_MODE[chat_id]
    muted = MUSIC_MUTED[chat_id]

    rows = [
        [btn('🟥 توقف', p+':stop'), btn('⏸️ مکث', p+':pause')],
        [btn('🔉', p+':vol-10'), btn('🔊 میزان صدا', p+':vol'), btn('🔊', p+':vol+10')],
        [btn('🔇 بی‌صدا' if not muted else '🔊 صدادار', p+':mute')],
        [btn('➖', p+':speed-'), btn(f'سرعت پخش: {speed:g}×', p+':speed'), btn('➕', p+':speed+')],
        [btn('🔵 60-', p+':seek-60'), btn('🔵 30-', p+':seek-30'), btn('🟢 +30', p+':seek+30'), btn('🟢 +60', p+':seek+60')],
        [btn(f'🎚️ اکولایزر: {eq}', p+':eq')],
    ]

    # Match the reference panel: download is visible for downloadable media,
    # while live streams keep their existing restriction in the download handler.
    if state:
        rows.append([btn('⬇️ دریافت فایل', f'mdownload:{chat_id}:{owner_id}')])

    rows.append([btn('❌ بستن', p+':close')])
    return keyboard(rows)


async def _bb_music_control_callback_final(update, context):
    q=getattr(update,'callback_query',None)
    if not q or not (q.data or '').startswith('mctrl:'): return False
    try:
        _,chat_raw,owner_raw,action=q.data.split(':',3); chat_id=int(chat_raw); owner_id=int(owner_raw)
        if q.from_user.id!=owner_id:
            await q.answer('🔒 این پنل مربوط به درخواست‌کننده است و تو نمی‌توانی از آن استفاده کنی.',show_alert=True); return True
        if action=='pause': ok=await pause_playback(chat_id); await pause_call(chat_id); await q.answer('⏸️ مکث شد.' if ok else '❌ چیزی در حال پخش نیست.')
        elif action=='resume': ok=await resume_playback(chat_id); await resume_call(chat_id); await q.answer('▶️ ادامه یافت.' if ok else '❌ پخش فعالی نداریم.')
        elif action=='prev': item=await _bb_music_prev(chat_id); await q.answer('⏮️ '+(safe_text(item.get('title'),60) if item else 'مورد قبلی نداریم.'))
        elif action=='skip': item=await _bb_music_skip(chat_id); await q.answer('⏭️ '+(safe_text(item.get('title'),60) if item else 'صف تمام شد.'))
        elif action=='vol-10': await _bb_music_set_volume(chat_id,MUSIC_VOLUME[chat_id]-10); await q.answer('🔉 صدا کم شد.')
        elif action=='vol+10': await _bb_music_set_volume(chat_id,MUSIC_VOLUME[chat_id]+10); await q.answer('🔊 صدا زیاد شد.')
        elif action=='vol': await q.answer(f'🔊 صدا: {MUSIC_VOLUME[chat_id]}%')
        elif action=='queue':
            queue=MUSIC_QUEUE.get(chat_id) or []
            await q.answer('صف نمایش داده شد.')
            await q.message.reply_text('📋 <b>صف پخش</b>\n\n'+('\n'.join(f'{i}. {safe_text(x.get("title"),90)}' for i,x in enumerate(queue,1)) or 'صف خالی است.'),parse_mode='HTML'); return True
        elif action=='refresh': await q.answer('🔄 تازه شد.')
        elif action=='stop':
            await _bb_music_stop_final(chat_id); MUSIC_QUEUE[chat_id]=[]; MUSIC_HISTORY.pop(chat_id,None)
            task=MUSIC_REFRESH_TASKS.pop(chat_id,None)
            if task: task.cancel()
            try:
                if getattr(q.message,'photo',None): await q.message.edit_caption(caption='⏹️ <b>پخش به پایان رسید.</b>',parse_mode='HTML',reply_markup=None)
                else: await q.message.edit_text('⏹️ <b>پخش به پایان رسید.</b>',parse_mode='HTML',reply_markup=None)
            except Exception: pass
            await q.answer('⏹️ پخش تمام شد؛ Voice Chat خاموش نشد.')
            return True
        else: await q.answer('❌ گزینه نامعتبر.',show_alert=True); return True
        try: await _bb_music_render_panel(chat_id,owner_id,message=q.message)
        except Exception: pass
        return True
    except Exception as exc:
        log.exception('final music control failed: %s',exc)
        try: await q.answer('⚠️ کنترل پخش انجام نشد.',show_alert=True)
        except Exception: pass
        return True


async def _bb_music_start_refresh(chat_id, owner_id, message):
    old=MUSIC_REFRESH_TASKS.pop(chat_id,None)
    if old: old.cancel()
    MUSIC_PANEL_META[chat_id]={'owner_id':owner_id,'message_id':getattr(message,'message_id',0),'chat_id':chat_id}
    async def worker():
        while chat_id in MUSIC_CURRENT and chat_id in MUSIC_PANEL_META:
            await asyncio.sleep(5)
            state=MUSIC_CURRENT.get(chat_id)
            if not state: break
            try:
                pos=await get_current_position(chat_id); duration=float(state.get('duration') or 0)
                if duration and pos>=max(1,duration-2):
                    nxt=await _bb_music_skip(chat_id)
                    if nxt:
                        try: await _bb_music_render_panel(chat_id,int(nxt.get('requester_id') or owner_id),message=message)
                        except Exception: pass
                        continue
                    # Finished and nothing queued: leave the call but do not end the Telegram call itself.
                    await _bb_music_stop_final(chat_id)
                    MUSIC_PANEL_META.pop(chat_id,None)
                    try:
                        if getattr(message,'photo',None): await message.edit_caption(caption='⏹️ <b>پخش به پایان رسید.</b>',parse_mode='HTML',reply_markup=None)
                        else: await message.edit_text('⏹️ <b>پخش به پایان رسید.</b>',parse_mode='HTML',reply_markup=None)
                    except Exception: pass
                    break
                try: await _bb_music_render_panel(chat_id,int(state.get('requester_id') or owner_id),message=message,position=pos)
                except Exception: pass
            except Exception:
                # A transient Telegram edit error must not kill playback monitoring.
                continue
    MUSIC_REFRESH_TASKS[chat_id]=asyncio.create_task(worker())

# Callback dispatcher for the final music layer.
async def _bb_final_music_callback_dispatch(update, context):
    for fn in (_bb_music_live_callback_final,_bb_music_live_result_callback_final,_bb_music_result_callback_final,_bb_music_download_callback_final,_bb_music_control_callback_final):
        try:
            if await fn(update,context): return
        except Exception as exc:
            log.exception('music callback layer: %s',exc)
            try: await update.callback_query.answer('⚠️ عملیات انجام نشد.',show_alert=True)
            except Exception: pass
            return

# --- Exact Persian date panel. No external calendar is mandatory.
def _bb_date_panel_text():
    now=_bb_local_now(); jy,jm,jd=_bb_jalali(now); hy,hm,hd,hmn=_bb_hijri(now)
    try:
        import jdatetime
        start=jdatetime.date(jy,1,1).togregorian(); nxt=jdatetime.date(jy+1,1,1).togregorian()
        elapsed=(now.date()-start).days+1; remaining=(nxt-now.date()).days; total=elapsed+remaining
    except Exception:
        # Farvardin 1 is March 21 for the supported 1400s range.
        start=datetime(jy+621,3,21).date(); nxt=datetime(jy+622,3,21).date()
        elapsed=(now.date()-start).days+1; remaining=max(0,(nxt-now.date()).days); total=elapsed+remaining
    gp_elapsed=now.timetuple().tm_yday; gp_total=366 if ((now.year%4==0 and now.year%100!=0) or now.year%400==0) else 365; gp_remaining=gp_total-gp_elapsed
    jp,jbar=_bb_progress(elapsed,total,5); gp,gbar=_bb_progress(gp_elapsed,gp_total,5)
    weekday=_BB_FA_WEEKDAYS[now.weekday()]
    fa=f'{_bb_fa_num(jy)}/{_bb_fa_num(jm).zfill(2)}/{_bb_fa_num(jd).zfill(2)}'
    hmonths=['محرم','صفر','ربیع‌الاول','ربیع‌الثانی','جمادی‌الاول','جمادی‌الثانی','رجب','شعبان','رمضان','شوال','ذی‌القعده','ذی‌الحجه']
    hmonth=hmn or hmonths[hm-1] if 1<=hm<=12 else 'قمری'
    return ('📅 <b>تاریخ / ساعت بیل بیلک</b>\n\n'
            '〰️〰️〰️〰️〰️〰️〰️\n\n'
            f'⏰ ساعت : <b>{_bb_fa_num(now.strftime("%H:%M:%S"))}</b>\n'
            f'📅 تاریخ : <b>{weekday} - {fa} ({_BB_FA_MONTHS[jm-1]})</b>\n\n'
            f'🌙 تاریخ قمری : <b>{weekday} - {_bb_fa_num(hy)}/{_bb_fa_num(hm).zfill(2)}/{_bb_fa_num(hd).zfill(2)} ({hmonth})</b>\n'
            f'☀️ تاریخ میلادی : <b>{now.strftime("%A")} - {now.strftime("%Y/%m/%d")} ({_BB_EN_MONTHS[now.month-1]})</b>\n\n'
            '🎉 تا پایان سال (شمسی)\n'
            f'┘─ 📅 روز های سپری شده : <b>{_bb_fa_num(elapsed)} روز</b>\n'
            f'┘─ ⌛️ روز های باقی مانده : <b>{_bb_fa_num(remaining)} روز</b>\n'
            f'‏┘─ 🛍 {jp}% {jbar}\n\n'
            '🎄 تا پایان سال (میلادی)\n'
            f'┘─ 📅 روز های سپری شده : <b>{gp_elapsed} روز</b>\n'
            f'┘─ ⌛️ روز های باقی مانده : <b>{gp_remaining} روز</b>\n'
            f'‏┘─ 🛍 {gp}% {gbar}\n\n'
            '〰️〰️〰️〰️〰️〰️〰️')

# --- Accurate local daily/weekly/monthly stats.
async def _bb_final_stats(update, mode='روزانه'):
    chat=update.effective_chat; msg=update.effective_message
    if not chat or chat.type=='private': return False
    if not await is_admin(update): await msg.reply_text('⛔ این گزارش فقط برای ادمین‌های واقعی گروه است.'); return True
    days={'روزانه':1,'هفتگی':7,'ماهانه':30}.get(mode,1)
    today_date=_bb_local_now().date(); cutoff=today_date-timedelta(days=days-1)
    rows=await DBX.execute('SELECT user_id,SUM(messages) messages FROM bb_message_daily WHERE chat_id=? AND day>=? AND day<=? GROUP BY user_id ORDER BY messages DESC',(chat.id,cutoff.strftime('%Y-%m-%d'),today_date.strftime('%Y-%m-%d')),fetch=True)
    total=sum(int(r['messages'] or 0) for r in rows)
    top=[]
    for i,r in enumerate(rows[:10],1):
        u=await DBX.one('SELECT first_name,username FROM users WHERE user_id=?',(r['user_id'],)); name=(u['first_name'] if u and u['first_name'] else '') or (('@'+u['username']) if u and u['username'] else '') or str(r['user_id'])
        top.append(f'{i}. <b>{safe_text(name,40)}</b> — {int(r["messages"] or 0):,} پیام')
    await msg.reply_text(f'📊 <b>آمار دقیق {mode}</b>\n\n💬 مجموع پیام‌ها: <b>{total:,}</b>\n👥 کاربران فعال: <b>{len(rows):,}</b>\n\n🏆 <b>لیدربرد</b>\n'+('\n'.join(top) or 'هنوز آماری ثبت نشده.'),parse_mode='HTML')
    return True

# --- Permanent mute when no number is supplied; number means minutes.
_OLD_FINAL_MODERATION_TEXT=_bb_final_moderation_text
async def _bb_final_moderation_text(update, context):
    msg=update.effective_message; chat=update.effective_chat; t=_bb_plain_tool_text(getattr(msg,'text','') or '')
    if msg and chat and chat.type!='private' and re.fullmatch(r'(?:سکوت|سیک|هیس|خفه)',t):
        if not await is_admin(update): await msg.reply_text('⛔ فقط ادمین.'); return True
        target=getattr(msg.reply_to_message,'from_user',None)
        if not target: await msg.reply_text('🔇 روی پیام کاربر ریپلای کن و «سکوت» بفرست.'); return True
        try:
            await context.bot.restrict_chat_member(chat.id,target.id,permissions=ChatPermissions(can_send_messages=False))
            await msg.reply_text(f'🔇 {mention_html(target)} به‌صورت دائمی ساکت شد.',parse_mode='HTML')
        except TelegramError: await msg.reply_text('⚠️ سکوت انجام نشد؛ دسترسی Restrict را بررسی کن.')
        return True
    m=re.fullmatch(r'(?:سکوت|سیک|هیس|خفه)\s+(\d+)',t)
    if msg and chat and chat.type!='private' and m:
        if not await is_admin(update): await msg.reply_text('⛔ فقط ادمین.'); return True
        target=getattr(msg.reply_to_message,'from_user',None)
        if not target: await msg.reply_text('🔇 روی پیام کاربر ریپلای کن و «سکوت 120» بفرست.'); return True
        mins=max(1,min(10080,int(m.group(1))))
        try:
            await context.bot.restrict_chat_member(chat.id,target.id,permissions=ChatPermissions(can_send_messages=False),until_date=now_ts()+mins*60)
            await msg.reply_text(f'🔇 {mention_html(target)} برای <b>{mins}</b> دقیقه ساکت شد.',parse_mode='HTML')
        except TelegramError: await msg.reply_text('⚠️ سکوت انجام نشد؛ دسترسی Restrict را بررسی کن.')
        return True
    return await _OLD_FINAL_MODERATION_TEXT(update,context)

# --- Use the final handlers before every older music handler.
_BB_BUILD_BEFORE_REQUESTED_PATCH=build_application
def build_application(token: str) -> Application:
    app=_BB_BUILD_BEFORE_REQUESTED_PATCH(token)
    app.add_handler(CallbackQueryHandler(_bb_final_music_callback_dispatch),group=-400)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, _bb_music_message_router_final),group=-300)
    return app

_BB_POST_BEFORE_REQUESTED_PATCH=post_init
async def post_init(application):
    await _BB_POST_BEFORE_REQUESTED_PATCH(application)
    try:
        await _bb_music_seed_defaults()
        ok,reason=await _bb_music_lazy_connect()
        if not ok: log.warning('requested music startup check: %s',reason)
    except Exception as exc:
        log.exception('requested final startup patch: %s',exc)



