async def _bb_conversion_allowed(user_id, chat_id):
    """Two conversions per rolling 10h for normal users; VIP is unlimited."""
    try:
        if chat_id and chat_id < 0 and await active_vip(chat_id):
            return True, 0
    except Exception:
        pass
    await DBX.execute("CREATE TABLE IF NOT EXISTS bb_conversion_usage(user_id INTEGER NOT NULL, used_at INTEGER NOT NULL)")
    cutoff=now_ts()-36000
    row=await DBX.one("SELECT COUNT(*) n FROM bb_conversion_usage WHERE user_id=? AND used_at>=?",(user_id,cutoff))
    used=int(row['n'] or 0) if row else 0
    if used>=2:
        return False, 0
    await DBX.execute("INSERT INTO bb_conversion_usage(user_id,used_at) VALUES(?,?)",(user_id,now_ts()))
    return True, used+1

