# FINAL PATCH 3 — AI conversion backends + robust ElevenLabs music generation
# =============================================================================

async def _bb_http_post_raw(url, headers=None, *, json_body=None, data=None, files=None, timeout=180, params=None):
    import requests
    def work():
        r=requests.post(url, headers=headers or {}, json=json_body, data=data, files=files,
                        timeout=timeout, params=params)
        return r
    return await asyncio.to_thread(work)

async def _bb_generate_eleven_music(prompt, length_ms=30000, instrumental=False):
    """Generate a real MP3, with useful API errors and a v2->v1 fallback."""
    key=await _bb_ai_key('ELEVENLABS_API_KEY')
    if not key:
        return None, 'ELEVENLABS_API_KEY تنظیم نشده است. از پنل مالک → ساخت آهنگ و صدا کلید را ثبت کن.'
    prompt=safe_text(prompt,4000).strip()
    length=max(3000,min(int(length_ms),600000))
    attempts=[('music_v2', {'prompt':prompt,'music_length_ms':length,'model_id':'music_v2','force_instrumental':bool(instrumental)}),
              ('music_v1', {'prompt':prompt,'music_length_ms':length,'model_id':'music_v1','force_instrumental':bool(instrumental)})]
    errors=[]
    for model,payload in attempts:
        try:
            r=await _bb_http_post_raw(
                'https://api.elevenlabs.io/v1/music',
                {'xi-api-key':key,'Content-Type':'application/json','Accept':'audio/mpeg'},
                json_body=payload, timeout=420)
            if r.ok and r.content and len(r.content)>1000:
                path=Path(tempfile.gettempdir())/f'bilbilak_song_{now_ts()}_{random.randint(1000,9999)}.mp3'
                path.write_bytes(r.content)
                return path,None
            body=(r.text or '').strip().replace('\n',' ')[:700]
            errors.append(f'{model}: HTTP {r.status_code} {body}')
        except Exception as exc:
            errors.append(f'{model}: {type(exc).__name__}: {str(exc)[:300]}')
    return None, 'تولید آهنگ ناموفق بود.\n'+'\n'.join(errors)

async def _bb_ai_voice_to_text(msg):
    """Try ElevenLabs Speech-to-Text first; return None to use the old engine."""
    key=await _bb_ai_key('ELEVENLABS_API_KEY')
    if not key or not getattr(msg,'voice',None) and not getattr(msg,'audio',None):
        return None
    src=msg.voice or msg.audio
    tmp=None
    try:
        f=await src.get_file()
        tmp=Path(tempfile.gettempdir())/f'bb_stt_{now_ts()}_{random.randint(1000,9999)}.ogg'
        await f.download_to_drive(str(tmp))
        with open(tmp,'rb') as fh:
            r=await _bb_http_post_raw(
                'https://api.elevenlabs.io/v1/speech-to-text',
                {'xi-api-key':key},
                data={'model_id':'scribe_v2'},
                files={'file':('audio.ogg',fh,'audio/ogg')}, timeout=180)
        if not r.ok:
            return None
        try: data=r.json()
        except Exception: return None
        text=(data.get('text') or '').strip()
        return text or None
    except Exception as exc:
        log.warning('AI STT failed, fallback to local: %s',exc)
        return None
    finally:
        try:
            if tmp: tmp.unlink(missing_ok=True)
        except Exception: pass

async def _bb_ai_photo_to_text(msg):
    """Try OpenRouter vision for OCR/description; return None to use local OCR."""
    key=await _bb_ai_key('OPENROUTER_API_KEY')
    if not key or not getattr(msg,'photo',None): return None
    tmp=None
    try:
        photo=msg.photo[-1]
        f=await photo.get_file()
        tmp=Path(tempfile.gettempdir())/f'bb_vision_{now_ts()}_{random.randint(1000,9999)}.jpg'
        await f.download_to_drive(str(tmp))
        import base64
        b64=base64.b64encode(tmp.read_bytes()).decode('ascii')
        body={
            'model': await _bb_pro_get('OPENROUTER_VISION_MODEL','google/gemini-2.0-flash-001'),
            'messages':[{'role':'user','content':[
                {'type':'text','text':'متن داخل این تصویر را دقیق استخراج کن. اگر تصویر متن ندارد، خیلی کوتاه توضیح بده چه چیزی دیده می‌شود. فقط نتیجه را بده.'},
                {'type':'image_url','image_url':{'url':f'data:image/jpeg;base64,{b64}'}}
            ]}],
            'temperature':0.1
        }
        r=await _bb_http_post_raw(
            'https://openrouter.ai/api/v1/chat/completions',
            {'Authorization':f'Bearer {key}','Content-Type':'application/json'},
            json_body=body, timeout=120)
        if not r.ok: return None
        data=r.json(); text=data.get('choices',[{}])[0].get('message',{}).get('content','')
        text=safe_text(text,5000).strip()
        return text or None
    except Exception as exc:
        log.warning('AI vision failed, fallback to local OCR: %s',exc)
        return None
    finally:
        try:
            if tmp: tmp.unlink(missing_ok=True)
        except Exception: pass

# AI-first wrappers. The existing local implementations remain the fallback.
_OLD_BB_VOICE_TO_TEXT_AI=bb_convert_voice_to_text
async def bb_convert_voice_to_text(msg):
    uid=getattr(getattr(msg,'from_user',None),'id',0); cid=getattr(getattr(msg,'chat',None),'id',0)
    ok,_=await _bb_conversion_allowed(uid,cid)
    if not ok: return '⏳ سهمیه تبدیل برایت تمام شده است. هر ۱۰ ساعت حداکثر ۲ تبدیل داری؛ گروه VIP این محدودیت را ندارد.'
    text=await _bb_ai_voice_to_text(msg)
    if text:
        return f'🧠 <b>متن استخراج‌شده با AI:</b>\n\n{safe_text(text,5000)}'
    return await _OLD_BB_VOICE_TO_TEXT_AI(msg)

_OLD_BB_PHOTO_TO_TEXT_AI=bb_convert_photo_to_text
async def bb_convert_photo_to_text(msg):
    uid=getattr(getattr(msg,'from_user',None),'id',0); cid=getattr(getattr(msg,'chat',None),'id',0)
    ok,_=await _bb_conversion_allowed(uid,cid)
    if not ok: return '⏳ سهمیه تبدیل برایت تمام شده است. هر ۱۰ ساعت حداکثر ۲ تبدیل داری؛ گروه VIP این محدودیت را ندارد.'
    text=await _bb_ai_photo_to_text(msg)
    if text:
        return f'🧠 <b>نتیجه AI:</b>\n\n{safe_text(text,5000)}'
    return await _OLD_BB_PHOTO_TO_TEXT_AI(msg)

# Fix the tag sender: the previous patch created the coroutine without awaiting it.
async def _bb_final_tag_users(update, mode='all', target_message_id=None, context=None):
    msg=update.effective_message; chat=update.effective_chat
    if not msg or not chat or chat.type=='private': return True
    if not await is_admin(update): await msg.reply_text('⛔ فقط ادمین واقعی.'); return True
    members=[]
    try:
        if MUSIC_USER_CLIENT is not None and getattr(MUSIC_USER_CLIENT,'is_connected',False):
            async for m in MUSIC_USER_CLIENT.get_chat_members(chat.id):
                u=getattr(m,'user',None)
                if not u: continue
                is_bot=bool(getattr(u,'is_bot',False)); status=getattr(m,'status',None)
                if mode=='bots' and not is_bot: continue
                if mode=='admins' and status not in {'administrator','owner'}: continue
                if mode=='all' and is_bot: continue
                members.append(u)
    except Exception as exc:
        log.warning('full tag via music account failed: %s',exc)
    if not members:
        data=await DBX.execute('SELECT user_id,first_name,username,is_bot FROM chat_member_stats WHERE chat_id=? ORDER BY last_seen DESC LIMIT 5000',(chat.id,),fetch=True)
        for x in data:
            if mode=='bots' and not x['is_bot']: continue
            if mode=='all' and x['is_bot']: continue
            members.append(type('U',(),{'id':x['user_id'],'first_name':x['first_name'] or 'کاربر','username':x['username'] or '','is_bot':bool(x['is_bot'])})())
    if not members:
        await msg.reply_text('👥 عضو قابل تگی پیدا نشد. اکانت مکمل موزیکال/پاکسازی باید عضو گروه باشد تا بتواند اعضا را ببیند.'); return True
    chunks=[]; cur=''
    for u in members:
        tag=mention_html(u)
        if len(cur)+len(tag)+2>3000: chunks.append(cur); cur=''
        cur+=tag+'  '
    if cur: chunks.append(cur)
    for i,chtext in enumerate(chunks,1):
        kwargs={'chat_id':chat.id,'text':f'🏷️ <b>تگ {mode}</b> — {i}/{len(chunks)}\n\n{chtext}','parse_mode':'HTML'}
        if target_message_id:
            try:
                from telegram import ReplyParameters
                kwargs['reply_parameters']=ReplyParameters(message_id=target_message_id)
            except Exception: pass
        bot = getattr(context, 'bot', None) if context is not None else None
        if bot is None:
            bot = msg.get_bot()
        await bot.send_message(**kwargs)
    return True

