# =============================================================================
# FINAL DUPLICATE-UPDATE GUARD — 2026-09-11
# جلوگیری از ارسال دوباره یک پنل/پیام وقتی Telegram یک Update یکسان را
# بیش از یک بار تحویل می‌دهد. این گارد قبل از تمام MessageHandlerهای قدیمی اجرا می‌شود.
# =============================================================================
from collections import OrderedDict as _BBOrderedDict

_BB_SEEN_UPDATE_IDS = _BBOrderedDict()
_BB_SEEN_UPDATE_TTL = 90.0
_BB_SEEN_UPDATE_MAX = 5000

async def _bb_duplicate_update_guard(update, context):
    uid = getattr(update, 'update_id', None)
    if uid is None:
        return
    now = time.time()
    # پاکسازی رکوردهای قدیمی
    while _BB_SEEN_UPDATE_IDS:
        first_id, first_time = next(iter(_BB_SEEN_UPDATE_IDS.items()))
        if now - first_time <= _BB_SEEN_UPDATE_TTL:
            break
        _BB_SEEN_UPDATE_IDS.pop(first_id, None)
    # یک Update یکسان فقط یک بار اجازه عبور دارد.
    if uid in _BB_SEEN_UPDATE_IDS:
        raise ApplicationHandlerStop
    _BB_SEEN_UPDATE_IDS[uid] = now
    while len(_BB_SEEN_UPDATE_IDS) > _BB_SEEN_UPDATE_MAX:
        _BB_SEEN_UPDATE_IDS.popitem(last=False)

_BB_BUILD_BEFORE_DUP_GUARD = build_application

def build_application(token: str) -> Application:
    app = _BB_BUILD_BEFORE_DUP_GUARD(token)
    # باید از همه MessageHandlerهای دیگر زودتر اجرا شود.
    app.add_handler(
        MessageHandler(filters.ALL & ~filters.COMMAND, _bb_duplicate_update_guard),
        group=-10000,
    )
    return app


