def _g2_k(text,data):
    return btn(text,data)

def _g2_panel(uid, page=0):
    items=list(BB_GAME2.items())
    per=12
    total=(len(items)+per-1)//per
    page=max(0,min(total-1,int(page or 0)))
    chunk=items[page*per:(page+1)*per]
    rows=[]
    for i in range(0,len(chunk),2):
        rows.append([_g2_k(label,f'g2:{uid}:play:{key}') for key,label in chunk[i:i+2]])
    nav=[]
    if page>0: nav.append(_g2_k('⬅️ قبلی',f'g2:{uid}:page:{page-1}'))
    if page<total-1: nav.append(_g2_k('➡️ بعدی',f'g2:{uid}:page:{page+1}'))
    if nav: rows.append(nav)
    rows.append([_g2_k('🏆 رتبه بازی‌ها',f'g2:{uid}:rank'),_g2_k('🏠 خانه',user_cb(uid,'home'))])
    return keyboard(rows), page+1, total

def _g2_question(key):
    if key=='math':
        a=random.randint(2,15); b=random.randint(2,12); op=random.choice(['+','×','-'])
        ans=a+b if op=='+' else a*b if op=='×' else a-b
        opts={ans}
        while len(opts)<4: opts.add(ans+random.randint(-10,10))
        opts=list(opts); random.shuffle(opts)
        return f'{a} {op} {b} = ؟',opts,opts.index(ans)
    if key=='quickmath':
        a=random.randint(5,30); b=random.randint(2,15); ans=a+b
        opts=[ans,ans+2,ans-3,ans+5]; random.shuffle(opts)
        return f'⚡ سریع: {a} + {b} = ؟',opts,opts.index(ans)
    if key=='quiz': return random.choice(BB_GAME2_QUIZ)
    if key=='trivia': return random.choice(BB_GAME2_TRIVIA)
    if key=='capital': return random.choice(BB_GAME2_CAPITAL)
    if key=='science': return random.choice(BB_GAME2_SCIENCE)
    if key=='logic': return random.choice(BB_GAME2_LOGIC)
    if key=='truefalse':
        qs=[('زمین یک سیاره است.',True),('خورشید یک سیاره است.',False),('آب در شرایط عادی می‌تواند یخ بزند.',True)]
        q,a=random.choice(qs); return q,['درست','غلط'],0 if a else 1
    if key=='odd':
        vals=['🐶','🐶','🐶','🐱']; random.shuffle(vals); return 'کدام گزینه متفاوت است؟',vals,vals.index('🐱')
    if key=='count':
        n=random.randint(3,8); s='⭐ '*n; opts=[n,max(1,n-1),n+1,n+2]; random.shuffle(opts)
        return f'{s}\nچند ستاره است؟',opts,opts.index(n)
    if key=='sequence':
        start=random.randint(1,8); step=random.randint(2,5); ans=start+step*4
        seq=[start+i*step for i in range(4)]; opts=[ans,ans+step,ans-1,ans+2*step]; random.shuffle(opts)
        return '، '.join(map(str,seq))+'، ؟',opts,opts.index(ans)
    if key=='pattern':
        ans=random.choice(['🟩','🔵','⭐']); return '🔷 الگو: 🟩 🔵 🟩 🔵 ؟', ['🟩','🔵','⭐','🔴'], 1
    if key=='anagram':
        scrambled,answer=random.choice(BB_GAME2_ANAGRAM); opts=[answer]
        while len(opts)<4:
            x=random.choice(BB_GAME2_WORDS)
            if x not in opts: opts.append(x)
        random.shuffle(opts); return f'حروف به‌هم‌ریخته: <b>{scrambled}</b>',opts,opts.index(answer)
    if key=='emoji':
        data=[('🐶🏠','سگ و خانه'),('🌧️☂️','باران و چتر'),('📚🏫','کتاب و مدرسه'),('⚽🏆','فوتبال و قهرمانی')]
        q,a=random.choice(data); opts=[a,'غذا و آشپزخانه','سفر و هواپیما','دریا و کشتی']; random.shuffle(opts); return f'این ایموجی‌ها بیشتر به کدام گزینه می‌خورند؟\n{q}',opts,opts.index(a)
    return None

async def _g2_score(uid, key, win, pts=None):
    await DBX.ensure_user(await _g2_fake_user(uid)) if False else asyncio.sleep(0)
    pts = pts if pts is not None else (3 if win else 1)
    try:
        await DBX.execute("INSERT INTO safe_game_stats(user_id,game_key,plays,wins,points) VALUES(?,?,?,?,?) ON CONFLICT(user_id,game_key) DO UPDATE SET plays=plays+1,wins=wins+excluded.wins,points=points+excluded.points",(uid,'g2_'+key,1,1 if win else 0,pts))
        await DBX.execute('UPDATE users SET xp=xp+?, bones=bones+?, games=games+? WHERE user_id=?',(pts,max(0,pts//2),1,uid))
    except Exception:
        pass

async def _g2_play(q, uid, key):
    if q.from_user.id!=uid:
        await q.answer('این بازی برای خودت نیست.',show_alert=True); return
    if key not in BB_GAME2:
        await q.answer('این بازی پیدا نشد.',show_alert=True); return
    if key=='rps':
        rows=[[btn('✊ سنگ',f'g2:{uid}:rps:rock'),btn('📄 کاغذ',f'g2:{uid}:rps:paper'),btn('✂️ قیچی',f'g2:{uid}:rps:scissors')],[btn('🔙 بازی‌ها',f'g2:{uid}:page:0')]]
        await q.edit_message_text('✊ <b>سنگ کاغذ قیچی</b>\n\nحرکتت را انتخاب کن:',parse_mode='HTML',reply_markup=keyboard(rows)); return
    if key in {'dice','coin','luck','reaction','color','higher','word','creative','choice','typing'}:
        if key=='dice': text=f'🎲 عدد تاس: <b>{random.randint(1,6)}</b>'; rows=[[btn('🎲 دوباره',f'g2:{uid}:play:dice')]]
        elif key=='coin': text=f'🪙 نتیجه: <b>{random.choice(["شیر","خط"])}</b>'; rows=[[btn('🪙 دوباره',f'g2:{uid}:play:coin')]]
        elif key=='luck': text=f'🍀 نتیجه امروز: <b>{random.choice(["ایده تازه","یک خبر خوب","یک برد کوچک","یک تجربه جالب"])}</b>'; rows=[[btn('🍀 دوباره',f'g2:{uid}:play:luck')]]
        elif key=='reaction': text=f'⚡ امتیاز واکنش تمرینی: <b>{random.randint(1,100)}</b>/100'; rows=[[btn('⚡ دوباره',f'g2:{uid}:play:reaction')]]
        elif key=='color':
            colors=['🔴 قرمز','🔵 آبی','🟢 سبز','🟡 زرد']; target=random.choice(colors); text=f'🎨 رنگ هدف: <b>{target}</b>\n\nفقط برای تمرین تشخیص رنگ است.'; rows=[[btn(x,f'g2:{uid}:play:color') for x in colors]]
        elif key=='higher':
            a=random.randint(10,90); b=random.randint(1,9); target=a+b; BB_GAME2_STATE[(uid,'higher')]=target; text=f'📈 عدد فعلی: <b>{a}</b>\nعدد بعدی {b} واحد بیشتر است. حدس بزن: <b>{target-2}</b>، <b>{target}</b> یا <b>{target+2}</b>'; rows=[[btn(str(x),f'g2:{uid}:higher:{x}:{target}') for x in (target-2,target,target+2)]]
        elif key=='word':
            w=random.choice(BB_GAME2_WORDS); text=f'🔤 یک کلمه پیدا کن که با حرف «<b>{w[0]}</b>» شروع شود.'; rows=[[btn('🔄 کلمه جدید',f'g2:{uid}:play:word')]]
        elif key=='creative':
            text=f'✨ موضوع خلاقیت: <b>{random.choice(["یک اسم برای بازی","یک اسم برای هاپو","یک شعار کوتاه","یک ایده برای ربات"])}</b>\n\nجوابت را در چت بنویس.'; rows=[[btn('🔄 موضوع جدید',f'g2:{uid}:play:creative')]]
        else:
            text=f'🔀 بین این دو انتخاب کن: <b>{random.choice(["یادگیری","سرگرمی"])}</b> یا <b>{random.choice(["خلاقیت","ورزش"])}</b>.'; rows=[[btn('گزینه اول',f'g2:{uid}:choice:1'),btn('گزینه دوم',f'g2:{uid}:choice:2')]]
        await _g2_score(uid,key,True,2)
        rows.append([btn('🎮 فهرست بازی‌ها',f'g2:{uid}:page:0'),btn('🏠 خانه',user_cb(uid,'home'))])
        await q.edit_message_text(f'🎮 <b>{BB_GAME2[key]}</b>\n\n{text}\n\n⭐ +۲ XP',parse_mode='HTML',reply_markup=keyboard(rows)); return
    if key=='memory':
        seq=random.sample(BB_GAME2_WORDS,4); BB_GAME2_STATE[(uid,'memory')]=seq
        await q.edit_message_text('🧠 <b>حافظه</b>\n\nاین ۴ واژه را به خاطر بسپار:\n\n'+' — '.join(seq)+'\n\nوقتی آماده شدی «آماده‌ام» را بزن.',parse_mode='HTML',reply_markup=keyboard([[btn('✅ آماده‌ام',f'g2:{uid}:memorycheck')],[btn('🔙 بازی‌ها',f'g2:{uid}:page:0')]])); return
    data=_g2_question(key)
    if data:
        question,opts,correct=data
        BB_GAME2_STATE[(uid,key)]={'opts':opts,'correct':correct}
        rows=[]
        for i,o in enumerate(opts): rows.append([btn(str(o),f'g2:{uid}:ans:{key}:{i}')])
        rows.append([btn('🎮 فهرست بازی‌ها',f'g2:{uid}:page:0')])
        await q.edit_message_text(f'🎮 <b>{BB_GAME2[key]}</b>\n\n{question}\n\nیک پاسخ را انتخاب کن 👇',parse_mode='HTML',reply_markup=keyboard(rows)); return
    await q.answer('این بازی در حال آماده‌سازی است.',show_alert=True)

async def _g2_callback(update, context):
    q=update.callback_query; data=q.data or ''
    if not data.startswith('g2:'): return False
    p=data.split(':')
    if len(p)<3 or not p[1].isdigit(): return True
    uid=int(p[1])
    if q.from_user.id!=uid:
        await q.answer('این پنل برای خودت نیست.',show_alert=True); return True
    try: await q.answer()
    except Exception: pass
    action=p[2]
    if action=='page':
        markup,page,total=_g2_panel(uid,int(p[3]) if len(p)>3 and p[3].isdigit() else 0)
        await q.edit_message_text(f'🎮 <b>شهر بازی بیل بیلک</b>\n\nصفحه <b>{page}</b> از <b>{total}</b>\n\nبازی‌ها بدون شرط و فقط برای سرگرمی و امتیاز هستند 👇',parse_mode='HTML',reply_markup=markup); return True
    if action=='play' and len(p)>3:
        await _g2_play(q,uid,p[3]); return True
    if action=='rps' and len(p)>3:
        me=p[3]; bot=random.choice(['rock','paper','scissors']); names={'rock':'✊ سنگ','paper':'📄 کاغذ','scissors':'✂️ قیچی'}
        win=(me=='rock' and bot=='scissors') or (me=='paper' and bot=='rock') or (me=='scissors' and bot=='paper')
        draw=me==bot; pts=3 if win else 1
        await _g2_score(uid,'rps',win,pts)
        result='🤝 مساوی!' if draw else ('🏆 بردی!' if win else '🤖 بیل بیلک برد!')
        await q.edit_message_text(f'✊ <b>سنگ کاغذ قیچی</b>\n\nتو: {names[me]}\nبیل بیلک: {names[bot]}\n\n<b>{result}</b>\n⭐ +{pts} XP',parse_mode='HTML',reply_markup=keyboard([[btn('🔁 دوباره',f'g2:{uid}:play:rps')],[btn('🎮 بازی‌ها',f'g2:{uid}:page:0'),btn('🏠 خانه',user_cb(uid,'home'))]])); return True
    if action=='ans' and len(p)>4:
        key=p[3]; idx=int(p[4]) if p[4].isdigit() else -1; state=BB_GAME2_STATE.get((uid,key))
        if not state: await q.answer('این سؤال منقضی شده؛ دوباره شروعش کن.',show_alert=True); return True
        ok=idx==state.get('correct'); await _g2_score(uid,key,ok,3 if ok else 1)
        text='🏆 <b>درست!</b> +۳ XP' if ok else f'❌ <b>اشتباه بود.</b> پاسخ درست: <b>{state["opts"][state["correct"]]}</b>\n⭐ +۱ XP'
        await q.edit_message_text(f'🎮 <b>{BB_GAME2.get(key,key)}</b>\n\n{text}',parse_mode='HTML',reply_markup=keyboard([[btn('🔄 سؤال بعدی',f'g2:{uid}:play:{key}')],[btn('🎮 بازی‌ها',f'g2:{uid}:page:0'),btn('🏠 خانه',user_cb(uid,'home'))]])); return True
    if action=='memorycheck':
        seq=BB_GAME2_STATE.pop((uid,'memory'),None)
        if not seq: await q.answer('این دور تمام شده.',show_alert=True); return True
        # بعد از نمایش، به‌جای پاسخ متنی یک آزمون ترتیب می‌سازیم.
        shuffled=seq[:]; random.shuffle(shuffled); correct=shuffled==seq
        BB_GAME2_STATE[(uid,'memory_order')]=seq
        rows=[]
        for i,x in enumerate(shuffled): rows.append([btn(f'{i+1}. {x}',f'g2:{uid}:memorder:{i}')])
        await q.edit_message_text('🧠 <b>حافظه</b>\n\nحالا ترتیب اصلی را یادت هست؟\nگزینه‌ها را به ترتیب انتخاب کن؛ برای هر انتخاب جایگاه را ثبت می‌کنیم.',parse_mode='HTML',reply_markup=keyboard(rows+[[btn('🎮 بازی‌ها',f'g2:{uid}:page:0')]])); return True
    if action=='memorder':
        await q.answer('ترتیب کامل در نسخه بعدی مرحله‌ای می‌شود؛ این دور به‌عنوان تمرین ثبت شد.',show_alert=True)
        await _g2_score(uid,'memory',True,2)
        await q.edit_message_text('🧠 <b>حافظه ثبت شد!</b>\n\n⭐ +۲ XP\nبرای یک دور جدید دوباره وارد بازی حافظه شو.',parse_mode='HTML',reply_markup=keyboard([[btn('🔄 دوباره',f'g2:{uid}:play:memory')],[btn('🎮 بازی‌ها',f'g2:{uid}:page:0'),btn('🏠 خانه',user_cb(uid,'home'))]])); return True
    if action=='higher' and len(p)>4:
        target=int(p[4]); expected=int(p[5]) if len(p)>5 and p[5].isdigit() else target
        ok=target==expected; await _g2_score(uid,'higher',ok,3 if ok else 1)
        await q.edit_message_text(('🏆 درست حدس زدی! +۳ XP' if ok else f'❌ اشتباه. عدد درست <b>{expected}</b> بود. +۱ XP'),parse_mode='HTML',reply_markup=keyboard([[btn('🔄 دوباره',f'g2:{uid}:play:higher')],[btn('🎮 بازی‌ها',f'g2:{uid}:page:0')]])); return True
    if action=='choice':
        await _g2_score(uid,'choice',True,2); await q.edit_message_text('🔀 انتخابت ثبت شد!\n⭐ +۲ XP',reply_markup=keyboard([[btn('🔄 دوباره',f'g2:{uid}:play:choice')],[btn('🎮 بازی‌ها',f'g2:{uid}:page:0')]])); return True
    if action=='rank':
        rows=await DBX.execute("SELECT u.first_name,COALESCE(SUM(s.points),0) points FROM safe_game_stats s JOIN users u ON u.user_id=s.user_id WHERE s.game_key LIKE 'g2_%' GROUP BY s.user_id ORDER BY points DESC LIMIT 10",fetch=True)
        text='🏆 <b>۱۰ نفر برتر بازی‌های جدید</b>\n\n'+('\n'.join(f'{i}. {safe_text(r["first_name"],25)} — {r["points"]} امتیاز' for i,r in enumerate(rows,1)) if rows else 'هنوز امتیازی ثبت نشده.')
        await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('🎮 بازی‌ها',f'g2:{uid}:page:0')],[btn('🏠 خانه',user_cb(uid,'home'))]])); return True
    return True

async def _g2_message(update, context):
    msg=update.effective_message; user=update.effective_user
    if not msg or not user or not getattr(msg,'text',None): return False
    t=normalize(msg.text)
    if t in {'بازی‌ها','بازی ها','بازی','شهر بازی','مرکز بازی‌ها','مرکز بازی ها'}:
        uid=user.id; markup,page,total=_g2_panel(uid,0)
        await msg.reply_text(f'🎮 <b>شهر بازی بیل بیلک</b>\n\nصفحه <b>{page}</b> از <b>{total}</b>\n\n🎯 بازی‌های فکری، سرعتی، آموزشی و شانسیِ بدون شرط\n🔘 همه گزینه‌های اصلی با دکمه‌های شیشه‌ای هستند 👇',parse_mode='HTML',reply_markup=markup)
        return True
    return False

