# Final build wrapper: register duplicate guard first, then game message/callback.
_BB_BUILD_BEFORE_FINAL_G2 = build_application

def build_application(token: str) -> Application:
    app=_BB_BUILD_BEFORE_FINAL_G2(token)
    # duplicate-update guard is already installed by the previous final wrapper.
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,_g2_message),group=-9999)
    app.add_handler(CallbackQueryHandler(_g2_callback),group=-10001)
    app.add_handler(CallbackQueryHandler(_nf_callback),group=-10002)
    return app

# اجرای برنامه در انتهای فایل انجام می‌شود تا تمام overrideهای نهایی
