# -----------------------------------------------------------------------------
# FINAL MUSIC FALLBACK CHAIN 2026-09-11
# معماری اصلی موزیک:
#   Resolver 1: yt-dlp
#   Resolver 2: Streamlink
#   Resolver 3: pytubefix (اختیاری؛ YouTube)
#   Resolver 4: direct URL
# سپس برای هر منبع:
#   Playback 1: PyTgCalls.play(URL)
#   Playback 2: PyTgCalls.play(MediaStream(URL))
#   Playback 3: ensure_voice_call(MediaStream(URL)) (اگر موجود باشد)
# اگر همه شکست بخورند، خطای واقعی برگردانده می‌شود.
# -----------------------------------------------------------------------------

async def _bb_music_backend_yt_dlp(url, is_video=False, is_live=False):
    if _music_yt_dlp is None:
        raise RuntimeError('yt-dlp نصب نیست')
    def _extract():
        opts = _music_ydl_options(audio_only=not is_video, download=False)
        opts['skip_download'] = True
        opts['noplaylist'] = True
        if is_live:
            opts['live_from_start'] = False
        with _music_yt_dlp.YoutubeDL(opts) as ydl:
            info = ydl.extract_info(url, download=False)
            if not info:
                raise RuntimeError('yt-dlp اطلاعاتی از منبع دریافت نکرد')
            direct = info.get('url')
            if not direct and info.get('requested_formats'):
                # برای ویدیو، اول فرمت دارای هر دو جریان یا سپس بهترین URL را امتحان می‌کنیم.
                candidates = []
                for f in info.get('requested_formats') or []:
                    if f.get('url'):
                        candidates.append(f['url'])
                direct = candidates[0] if candidates else None
            if not direct:
                raise RuntimeError('yt-dlp لینک استریم مستقیم برنگرداند')
            return direct, info
    return await _music_asyncio.to_thread(_extract)


async def _bb_music_backend_streamlink(url, is_video=False, is_live=False):
    try:
        import streamlink
    except Exception as exc:
        raise RuntimeError('Streamlink نصب نیست') from exc

    def _extract():
        session = streamlink.Streamlink()
        try:
            session.set_option('stream-segment-attempts', 2)
            session.set_option('stream-segment-timeout', 8)
            session.set_option('hls-live-edge', 3)
        except Exception:
            pass
        streams = session.streams(url)
        if not streams:
            raise RuntimeError('Streamlink هیچ استریمی پیدا نکرد')
        order = ('audio_only', 'best', '720p', '480p', 'worst') if not is_video else ('best', '720p', '480p', 'worst')
        selected = next((streams[k] for k in order if k in streams), None)
        if selected is None:
            selected = next(iter(streams.values()))
        direct = getattr(selected, 'url', None)
        if not direct:
            raise RuntimeError('Streamlink URL مستقیم برنگرداند')
        return direct, {'duration': 0, 'backend': 'streamlink'}
    return await _music_asyncio.to_thread(_extract)


async def _bb_music_backend_pytubefix(url, is_video=False, is_live=False):
    """Fallback اختیاری برای YouTube؛ اگر نصب نباشد به backend بعدی می‌رویم."""
    if is_live or not re.search(r'(youtube\.com|youtu\.be)', url or '', re.I):
        raise RuntimeError('pytubefix فقط برای YouTube غیرزنده استفاده می‌شود')
    try:
        from pytubefix import YouTube
    except Exception as exc:
        raise RuntimeError('pytubefix نصب نیست') from exc

    def _extract():
        yt = YouTube(url)
        if is_video:
            stream = yt.streams.filter(progressive=True, file_extension='mp4').order_by('resolution').desc().first()
        else:
            stream = yt.streams.filter(only_audio=True).order_by('abr').desc().first()
        if stream is None:
            raise RuntimeError('pytubefix استریم مناسب پیدا نکرد')
        direct = getattr(stream, 'url', None)
        if not direct:
            raise RuntimeError('pytubefix URL مستقیم برنگرداند')
        return direct, {
            'title': getattr(yt, 'title', '') or '',
            'duration': int(getattr(yt, 'length', 0) or 0),
            'backend': 'pytubefix',
        }
    return await _music_asyncio.to_thread(_extract)


async def _bb_music_backend_direct(url, is_video=False, is_live=False):
    url = (url or '').strip()
    if not re.match(r'^https?://', url, re.I):
        raise RuntimeError('لینک مستقیم معتبر نیست')
    # صفحه‌های وب مستقیم به PyTgCalls داده نمی‌شوند؛ فقط رسانه/استریم واقعی.
    if not re.search(r'\.(?:m3u8|mp4|mp3|aac|ogg|webm|m4a|ts)(?:\?.*)?$', url, re.I):
        raise RuntimeError('این URL لینک مستقیم رسانه نیست')
    return url, {'duration': 0, 'backend': 'direct'}


async def _bb_music_try_play_sources(chat_id, direct, is_video=False):
    """پخش فقط با API مدرن PyTgCalls 2.3.x؛ بدون APIهای منسوخ."""
    if not MUSIC_VC_ENGINE:
        raise RuntimeError('موتور PyTgCalls آماده نیست')
    play = getattr(MUSIC_VC_ENGINE, 'play', None)
    if not play or _MusicMediaStream is None:
        raise RuntimeError('PyTgCalls 2.3.3 یا MediaStream در دسترس نیست')
    stream = _MusicMediaStream(
        direct,
        video_flags=_MusicMediaStream.Flags.IGNORE if hasattr(_MusicMediaStream, 'Flags') else None
    )
    try:
        result = play(chat_id, stream)
        if hasattr(result, '__await__'):
            await result
        return 'PyTgCalls 2.3.3 / MediaStream'
    except Exception as exc:
        raise RuntimeError(f'پخش با PyTgCalls شکست خورد: {type(exc).__name__}: {exc}') from exc


async def _bb_music_play_now(chat_id, item):
    """هسته اصلی پخش: هر backend شکست بخورد، backend بعدی امتحان می‌شود."""
    ok, reason = await _bb_music_lazy_connect()
    if not ok:
        raise RuntimeError(reason)
    ok, reason = await _bb_music_personal_group_check(chat_id)
    if not ok:
        raise RuntimeError(reason)

    url = (item.get('url') or item.get('source_url') or '').strip()
    if not url:
        raise RuntimeError('منبع آهنگ خالی است')

    is_video = bool(item.get('is_video'))
    is_live = bool(item.get('is_live'))
    resolvers = (
        ('yt-dlp', _bb_music_backend_yt_dlp),
        ('streamlink', _bb_music_backend_streamlink),
        ('pytubefix', _bb_music_backend_pytubefix),
        ('direct', _bb_music_backend_direct),
    )
    errors = []

    for backend_name, resolver in resolvers:
        try:
            direct, info = await resolver(url, is_video, is_live)
            if not direct:
                raise RuntimeError('منبع خالی برگشت داده شد')
            try:
                method = await _bb_music_try_play_sources(chat_id, direct, is_video)
            except Exception as play_exc:
                errors.append(f'{backend_name} → پخش: {type(play_exc).__name__}: {safe_text(str(play_exc), 220)}')
                continue

            new_item = dict(item)
            new_item['source_url'] = direct
            new_item['backend'] = backend_name
            new_item['play_method'] = method
            if isinstance(info, dict):
                if not new_item.get('duration'):
                    new_item['duration'] = info.get('duration') or 0
                if not new_item.get('title') and info.get('title'):
                    new_item['title'] = info['title']
            new_item['started_at'] = _music_time.time()
            new_item['position'] = 0
            new_item['paused_at'] = None
            MUSIC_CURRENT[chat_id] = new_item
            log.info('music started chat=%s backend=%s method=%s', chat_id, backend_name, method)
            return new_item
        except Exception as exc:
            errors.append(f'{backend_name} → آماده‌سازی: {type(exc).__name__}: {safe_text(str(exc), 220)}')
            log.warning('music resolver %s failed: %s', backend_name, exc)

    raise RuntimeError('❌ پخش آهنگ انجام نشد؛ همه موتورهای پخش امتحان شدند.\n\n' + '\n'.join('• ' + x for x in errors))


async def _bb_music_start_or_queue(chat_id, item, panel_message=None, bot=None, requester_id=None):
    """صف ترتیبی اصلی موزیک؛ با امضای سازگار با router فعلی فایل."""
    queue = MUSIC_QUEUE.setdefault(chat_id, [])
    if requester_id is not None:
        item = dict(item, requester_id=requester_id)
    if MUSIC_CURRENT.get(chat_id):
        queue.append(dict(item))
        return False, None
    try:
        started = await _bb_music_play_now(chat_id, item)
        owner = int(item.get('requester_id') or requester_id or 0)
        panel = None
        render = globals().get('_bb_music_render_panel')
        refresh = globals().get('_bb_music_start_refresh')
        if callable(render):
            panel = await render(chat_id, owner, message=panel_message, bot=bot)
            if panel and callable(refresh):
                await refresh(chat_id, owner, panel)
        return True, panel
    except Exception:
        raise


async def _bb_music_play_next_safe(chat_id):
    """بدون قفل تودرتو؛ تا پیدا شدن اولین مورد قابل پخش، صف را جلو می‌برد."""
    lock = _music_chat_locks.setdefault(chat_id, asyncio.Lock()) if '_music_chat_locks' in globals() else None
    if lock is None:
        # در معماری فعلی MUSIC_QUEUE ممکن است قفل اختصاصی نداشته باشد.
        while True:
            q = MUSIC_QUEUE.get(chat_id) or []
            if not q:
                return False
            item = q.pop(0)
            try:
                await _bb_music_play_now(chat_id, item)
                return True
            except Exception as exc:
                log.error('music next item failed: %s', exc)
                continue

    async with lock:
        while True:
            q = MUSIC_QUEUE.get(chat_id) or []
            if not q:
                return False
            item = q.pop(0)
            try:
                await _bb_music_play_now(chat_id, item)
                return True
            except Exception as exc:
                log.error('music next item failed: %s', exc)
                continue


# سازگاری با نام‌های قبلی فایل
play_audio_in_vc = globals().get('play_audio_in_vc', None)


# =============================================================================
# FINAL SECURITY FAST-LANE + MEDIA CONTENT SCAN
# 2026-09-11
# - Fast in-memory lock cache: no SQLite query for every individual rule.
# - Cleanup-account permission cache: avoid repeated Telegram permission checks.
# - Immediate local text/link/flood/repeat checks remain synchronous.
# - Photo/video/animation deep scan runs asynchronously so normal messages are
#   not held up by an external vision model.
# - Voice/audio: speech-to-text (when ElevenLabs is configured) + text moderation.
# - Media classification is optional and fail-open on API/network errors: a
#   temporary scanner outage must not delete legitimate media.
# =============================================================================

SECURITY_LOCK_CACHE = {}
SECURITY_LOCK_CACHE_TTL = 8.0
SECURITY_CLEANUP_CACHE = {}
SECURITY_CLEANUP_CACHE_TTL = 60.0
SECURITY_MEDIA_TASKS = set()
SECURITY_MEDIA_SEEN = {}
SECURITY_MEDIA_SEEN_TTL = 120.0


def _bb_security_cache_prune(now=None):
    now = now or time.monotonic()
    for k, v in list(SECURITY_LOCK_CACHE.items()):
        if now - v[0] > SECURITY_LOCK_CACHE_TTL:
            SECURITY_LOCK_CACHE.pop(k, None)
    for k, v in list(SECURITY_CLEANUP_CACHE.items()):
        if now - v[0] > SECURITY_CLEANUP_CACHE_TTL:
            SECURITY_CLEANUP_CACHE.pop(k, None)
    for k, v in list(SECURITY_MEDIA_SEEN.items()):
        if now - v > SECURITY_MEDIA_SEEN_TTL:
            SECURITY_MEDIA_SEEN.pop(k, None)


async def _bb_security_enabled_locks(cid):
    """Load all enabled security locks for a group in ONE DB query and cache them."""
    now = time.monotonic()
    cached = SECURITY_LOCK_CACHE.get(int(cid))
    if cached and now - cached[0] <= SECURITY_LOCK_CACHE_TTL:
        return cached[1]
    try:
        rows = await DBX.execute(
            'SELECT lock_key FROM advanced_locks WHERE chat_id=? AND enabled=1',
            (int(cid),), fetch=True
        )
        enabled = {str(r['lock_key']) for r in (rows or [])}
    except Exception as exc:
        log.warning('security lock cache load failed: %r', exc)
        enabled = set()
    SECURITY_LOCK_CACHE[int(cid)] = (now, enabled)
    return enabled


async def _bb_security_fast_lock(cid, key, enabled=None):
    if enabled is None:
        enabled = await _bb_security_enabled_locks(cid)
    return key in enabled


# Invalidate the fast cache immediately when an admin changes a lock.
_OLD_ADVANCED_LOCK_TOGGLE_FINAL = advanced_lock_toggle
async def advanced_lock_toggle(q, uid, cid, key):
    result = await _OLD_ADVANCED_LOCK_TOGGLE_FINAL(q, uid, cid, key)
    SECURITY_LOCK_CACHE.pop(int(cid), None)
    return result


async def _bb_cleanup_can_delete_fast(chat_id):
    """Cache cleanup-account permission; re-check only on expiry or failure."""
    now = time.monotonic()
    cached = SECURITY_CLEANUP_CACHE.get(int(chat_id))
    if cached and now - cached[0] <= SECURITY_CLEANUP_CACHE_TTL:
        return bool(cached[1])
    try:
        ok, _ = await _bb_cleanup_group_check(int(chat_id))
        SECURITY_CLEANUP_CACHE[int(chat_id)] = (now, bool(ok))
        return bool(ok)
    except Exception:
        SECURITY_CLEANUP_CACHE[int(chat_id)] = (now, False)
        return False


async def _bb_fast_delete_message(chat_id, message_id, context=None):
    """Fast deletion path: cleanup account first, bot fallback second."""
    try:
        if await _bb_cleanup_can_delete_fast(chat_id):
            try:
                ok, _ = await _bb_cleanup_delete_message(int(chat_id), int(message_id))
                if ok:
                    return True, 'cleanup'
            except Exception:
                SECURITY_CLEANUP_CACHE.pop(int(chat_id), None)
    except Exception:
        pass
    if context is None:
        return False, 'none'
    try:
        rights = await get_bot_rights(context.bot, int(chat_id))
        if not rights.get('delete'):
            return False, 'none'
        await context.bot.delete_message(int(chat_id), int(message_id))
        return True, 'bot'
    except Exception:
        return False, 'none'


def _bb_media_kind(msg):
    if getattr(msg, 'photo', None): return 'photo'
    if getattr(msg, 'video', None): return 'video'
    if getattr(msg, 'animation', None): return 'animation'
    if getattr(msg, 'voice', None): return 'voice'
    if getattr(msg, 'audio', None): return 'audio'
    return None


def _bb_media_id(msg):
    for obj_name in ('photo', 'video', 'animation', 'voice', 'audio'):
        obj = getattr(msg, obj_name, None)
        if obj:
            try:
                if obj_name == 'photo': obj = obj[-1]
                fid = getattr(obj, 'file_unique_id', None) or getattr(obj, 'file_id', None)
                if fid: return str(fid)
            except Exception:
                pass
    return f'{getattr(msg, "chat_id", 0)}:{getattr(msg, "message_id", 0)}'


async def _bb_download_media_message(msg, suffix='bin'):
    src = getattr(msg, 'photo', None) or getattr(msg, 'video', None) or getattr(msg, 'animation', None) or getattr(msg, 'voice', None) or getattr(msg, 'audio', None)
    if not src:
        return None
    if isinstance(src, (list, tuple)):
        src = src[-1]
    try:
        f = await src.get_file()
        path = Path(tempfile.gettempdir()) / f'bb_sec_{now_ts()}_{random.randint(100000,999999)}.{suffix}'
        await f.download_to_drive(str(path))
        return path
    except Exception as exc:
        log.warning('security media download failed: %r', exc)
        return None


async def _bb_run_subprocess(*args, timeout=8):
    def work():
        import subprocess
        return subprocess.run(args, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                              timeout=timeout, check=False)
    return await asyncio.to_thread(work)


async def _bb_extract_video_frames(path, max_frames=3):
    outdir = Path(tempfile.mkdtemp(prefix='bb_sec_frames_'))
    pattern = str(outdir / 'frame_%02d.jpg')
    try:
        # Sample a small number of frames across the video. ffmpeg exits normally
        # even when a short clip has fewer than max_frames.
        result = await _bb_run_subprocess(
            'ffmpeg', '-hide_banner', '-loglevel', 'error', '-i', str(path),
            '-vf', 'fps=1/3,scale=768:-2', '-frames:v', str(max_frames),
            '-q:v', '5', pattern, timeout=12
        )
        frames = sorted(outdir.glob('frame_*.jpg'))
        if not frames:
            # Fallback: first frame for videos where fps filtering failed.
            await _bb_run_subprocess(
                'ffmpeg', '-hide_banner', '-loglevel', 'error', '-i', str(path),
                '-frames:v', '1', '-q:v', '5', str(outdir / 'frame_01.jpg'), timeout=8
            )
            frames = sorted(outdir.glob('frame_*.jpg'))
        return frames[:max_frames]
    except Exception as exc:
        log.warning('security frame extraction failed: %r', exc)
        return []


async def _bb_openrouter_moderate_images(paths):
    """Return (adult_or_sexual, violence, confidence, reason).
    The model receives only the sampled media needed for moderation.
    """
    key = await _bb_ai_key('OPENROUTER_API_KEY')
    if not key or not paths:
        return None
    try:
        import base64
        content = [{
            'type': 'text',
            'text': (
                'این رسانه را فقط برای تعدیل محتوای یک گروه تلگرامی بررسی کن. '
                'دو برچسب مستقل بده: sexual_adult و graphic_violence. '
                'sexual_adult فقط وقتی true است که محتوای جنسی/برهنگی صریح یا آشکار بزرگسالان دیده شود. '
                'graphic_violence فقط وقتی true است که خشونت شدید یا صحنه آسیب‌زا به‌وضوح دیده شود. '
                'اگر مطمئن نیستی false بده. خروجی فقط JSON باشد با کلیدهای '
                'sexual_adult, graphic_violence, confidence, reason. '
                'confidence عددی بین 0 و 1 باشد.'
            )
        }]
        for p in paths[:3]:
            raw = p.read_bytes()
            if len(raw) > 2_000_000:
                continue
            b64 = base64.b64encode(raw).decode('ascii')
            content.append({'type':'image_url','image_url':{'url':f'data:image/jpeg;base64,{b64}'}})
        if len(content) == 1:
            return None
        body = {
            'model': await _bb_pro_get('OPENROUTER_VISION_MODEL','google/gemini-2.0-flash-001'),
            'messages':[{'role':'user','content':content}],
            'temperature':0,
            'max_tokens':120,
        }
        r = await _bb_http_post_raw(
            'https://openrouter.ai/api/v1/chat/completions',
            {'Authorization':f'Bearer {key}','Content-Type':'application/json'},
            json_body=body, timeout=12
        )
        if not r.ok:
            return None
        data = r.json()
        raw = ((data.get('choices') or [{}])[0].get('message') or {}).get('content','')
        if isinstance(raw, list):
            raw = ''.join(str(x.get('text','')) if isinstance(x,dict) else str(x) for x in raw)
        raw = str(raw).strip().replace('```json','').replace('```','').strip()
        obj = json.loads(raw)
        conf = float(obj.get('confidence', 0) or 0)
        return bool(obj.get('sexual_adult')), bool(obj.get('graphic_violence')), max(0,min(conf,1)), safe_text(obj.get('reason',''),240)
    except Exception as exc:
        log.warning('security vision moderation failed: %r', exc)
        return None


async def _bb_openrouter_moderate_text(text):
    key = await _bb_ai_key('OPENROUTER_API_KEY')
    if not key or not text:
        return None
    try:
        body = {
            'model': await _bb_pro_get('OPENROUTER_MODEL','openai/gpt-4o-mini'),
            'messages':[
                {'role':'system','content':(
                    'برای تعدیل محتوای گروه، متن را بررسی کن. فقط JSON بده: '
                    'sexual_adult, graphic_violence, confidence, reason. '
                    'sexual_adult برای محتوای جنسی صریح/آشکار، graphic_violence برای خشونت شدید/آسیب‌زا. '
                    'در شک، false. confidence بین 0 و 1.'
                )},
                {'role':'user','content':safe_text(text,5000)}
            ],
            'temperature':0,
            'max_tokens':100,
        }
        r=await _bb_http_post_raw(
            'https://openrouter.ai/api/v1/chat/completions',
            {'Authorization':f'Bearer {key}','Content-Type':'application/json'},
            json_body=body, timeout=8
        )
        if not r.ok: return None
        data=r.json(); raw=((data.get('choices') or [{}])[0].get('message') or {}).get('content','')
        if isinstance(raw,list): raw=''.join(str(x.get('text','')) if isinstance(x,dict) else str(x) for x in raw)
        obj=json.loads(str(raw).replace('```json','').replace('```','').strip())
        conf=max(0,min(float(obj.get('confidence',0) or 0),1))
        return bool(obj.get('sexual_adult')), bool(obj.get('graphic_violence')), conf, safe_text(obj.get('reason',''),240)
    except Exception as exc:
        log.warning('security text moderation failed: %r', exc)
        return None


async def _bb_media_security_scan(update, context, enabled_locks):
    msg=update.effective_message; chat=update.effective_chat; user=update.effective_user
    if not msg or not chat or not user or chat.type=='private': return
    if await local_admin(update,user.id): return
    kind=_bb_media_kind(msg)
    if not kind: return

    want_adult = ('porn_media_ai' in enabled_locks or 'adult_media_ai' in enabled_locks or
                  'porn' in enabled_locks or 'adult' in enabled_locks or 'nsfw' in enabled_locks)
    want_violence = ('violence_media_ai' in enabled_locks or 'violence_keyword' in enabled_locks or
                     'violent_media' in enabled_locks)
    if not (want_adult or want_violence): return

    mid=int(getattr(msg,'message_id',0) or 0)
    skey=(int(chat.id),mid,_bb_media_id(msg))
    now=time.monotonic(); _bb_security_cache_prune(now)
    if skey in SECURITY_MEDIA_SEEN: return
    SECURITY_MEDIA_SEEN[skey]=now

    path=None; frames=[]; result=None
    try:
        if kind=='photo':
            path=await _bb_download_media_message(msg,'jpg')
            if path: result=await _bb_openrouter_moderate_images([path])
        elif kind in {'video','animation'}:
            path=await _bb_download_media_message(msg,'mp4')
            if path:
                frames=await _bb_extract_video_frames(path,3)
                result=await _bb_openrouter_moderate_images(frames)
        elif kind in {'voice','audio'}:
            # Voice/audio is moderated by speech content. Acoustic violence itself
            # cannot be reliably classified without a dedicated audio classifier.
            text=await _bb_ai_voice_to_text(msg)
            if text:
                result=await _bb_openrouter_moderate_text(text)

        if not result:
            return
        adult, violence, confidence, reason=result
        # High-confidence only: avoid destructive false positives from uncertain AI.
        if confidence < 0.86:
            return
        hit_adult=adult and want_adult
        hit_violence=violence and want_violence
        if not (hit_adult or hit_violence): return

        deleted,via=await _bb_fast_delete_message(chat.id,msg.message_id,context)
        if not deleted: return
        await record_stat(chat.id,'deleted')
        label='🛡 محتوای نامناسب رسانه‌ای' if hit_adult and not hit_violence else ('⚠️ محتوای خشونت‌آمیز رسانه‌ای' if hit_violence and not hit_adult else '🛡 محتوای نامناسب/خشونت‌آمیز رسانه‌ای')
        # Keep the public moderation notice short and non-graphic.
        try:
            warning=await context.bot.send_message(
                chat.id,
                f'⚠️ {mention_html(user)} رسانه توسط سیستم امنیتی حذف شد.\n'
                f'🔒 دلیل: {label}\n'
                f'🧹 عامل: {"اکانت پاکسازی" if via=="cleanup" else "ربات"}',
                parse_mode='HTML'
            )
            if context.job_queue:
                context.job_queue.run_once(delete_later_job,5,data=(chat.id,warning.message_id))
        except Exception:
            pass
    except Exception as exc:
        log.warning('media security scan failed: %r', exc)
    finally:
        for p in [path,*frames]:
            try:
                if p: Path(p).unlink(missing_ok=True)
            except Exception: pass
        for d in {str(Path(p).parent) for p in frames if p}:
            try: Path(d).rmdir()
            except Exception: pass


async def _bb_schedule_media_security(update, context, enabled_locks):
    try:
        task=asyncio.create_task(_bb_media_security_scan(update,context,enabled_locks))
        SECURITY_MEDIA_TASKS.add(task)
        task.add_done_callback(SECURITY_MEDIA_TASKS.discard)
    except Exception as exc:
        log.warning('media security task schedule failed: %r', exc)


# Final security handler: one DB read for all enabled locks, local checks first,
# media AI scan asynchronously.
async def advanced_lock_check(update, context):
    msg=update.effective_message; chat=update.effective_chat; user=update.effective_user
    if not msg or not chat or chat.type=='private' or not user: return False
    if await local_admin(update,user.id): return False
    try:
        if await DBX.one('SELECT 1 FROM exemptions WHERE chat_id=? AND user_id=?',(chat.id,user.id)):
            return False
    except Exception:
        pass

    enabled=await _bb_security_enabled_locks(chat.id)
    text=normalize(getattr(msg,'text','') or getattr(msg,'caption','') or '')
    checks=[]
    if text:
        if re.search(r'https?://|t\.me/|www\.',text,re.I): checks += ['links','url']
        if len(re.findall(r'@[A-Za-z0-9_]{3,}',text))>=5: checks += ['mention','massmention']
        if len(text)>1500: checks += ['longtext','excessive_length']
        if re.search(r'(.)\1{8,}',text): checks += ['repeated_chars']
        if text.count('!')+text.count('?')>30: checks += ['spam','text_burst']
        if BAD_PATTERNS['adult'].search(text): checks += ['adult','porn','nsfw','adult_keyword','sexual_keyword']
        if re.search(r'(عضو\s*شو|جوین\s*شو|ساب\s*کن|فالو\s*کن|کلیک\s*کن|دایرکت\s*بده|تبلیغ\s*کانال)',text,re.I): checks += ['tabchi','tabchi_pattern','promo']
        if re.search(r'(کد\s*ورود|رمز\s*یکبارمصرف|کیف\s*پول|برنده\s*شد[یید])',text,re.I): checks += ['scam','phishing','scam_keyword']
        if re.search(r'(.)\1{3,}\s+(?:\1\s*){3,}',text): checks += ['copy_paste','repeated_words']
    if getattr(msg,'photo',None): checks += ['photo','photo_spam']
    if getattr(msg,'video',None): checks += ['video','video_spam']
    if getattr(msg,'animation',None): checks += ['gif','animation','gif_spam']
    if getattr(msg,'voice',None): checks += ['voice','voice_spam']
    if getattr(msg,'audio',None): checks += ['audio']
    if getattr(msg,'document',None): checks += ['file','document','file_spam']
    if getattr(msg,'sticker',None): checks += ['sticker','sticker_spam']
    if getattr(msg,'contact',None): checks += ['contact','contact_spam']
    if getattr(msg,'location',None): checks += ['location','location_spam']
    if getattr(msg,'poll',None): checks += ['poll','poll_spam']
    if getattr(msg,'forward_origin',None): checks += ['forward','forwardedmedia']
    if getattr(msg,'entities',None) and any(getattr(e,'type','')=='mention' for e in msg.entities):
        checks += ['mention']

    # Very cheap in-memory rate checks.
    try:
        key=(chat.id,user.id); now=time.monotonic(); bucket=FLOOD_STATE[key]; bucket.append(now)
        while bucket and now-bucket[0]>8: bucket.popleft()
        if len(bucket)>=8: checks += ['flood','text_burst','tabchi_pattern']
        rkey=(chat.id,user.id,normalize(text)[:300]); rb=REPEAT_STATE[rkey]; rb.append(now)
        while rb and now-rb[0]>30: rb.popleft()
        if text and len(rb)>=3: checks += ['repeat','same_caption','copy_paste']
    except Exception: pass

    active=[k for k in dict.fromkeys(checks) if k in enabled]

    # Media content classification never blocks the fast path.
    if _bb_media_kind(msg):
        await _bb_schedule_media_security(update,context,enabled)

    if not active:
        return False

    reason_key=active[0]
    deleted,via=await _bb_fast_delete_message(chat.id,msg.message_id,context)
    if not deleted: return False
    await record_stat(chat.id,'deleted')
    try:
        count=await DBX.warn(chat.id,user.id)
        c=await DBX.get_chat(chat.id); limit=int(c['warn_limit'] or 3)
    except Exception:
        count=0; c=None; limit=3
    try:
        warning=await context.bot.send_message(
            chat.id,
            f'⚠️ {mention_html(user)} پیام توسط سیستم امنیتی حذف شد.\n'
            f'🔒 دلیل: {ADV_LOCK_NAMES.get(reason_key,reason_key)}\n'
            f'🧹 عامل پاکسازی: {"اکانت مکمل" if via=="cleanup" else "ربات"}\n'
            f'⚠️ اخطار {count}/{limit}',
            parse_mode='HTML'
        )
        if context.job_queue:
            context.job_queue.run_once(delete_later_job,5,data=(chat.id,warning.message_id))
    except Exception: pass
    try:
        rights=await get_bot_rights(context.bot,chat.id)
        if count>=limit and rights.get('restrict'):
            await context.bot.restrict_chat_member(
                chat.id,user.id,
                permissions=ChatPermissions(can_send_messages=False),
                until_date=datetime.now()+timedelta(minutes=int((c['mute_minutes'] if c else 10) or 10))
            )
            await DBX.clear_warn(chat.id,user.id)
    except Exception: pass
    return True


