# Invalidate cached cleanup permission whenever a fresh group check is requested.
_OLD_BB_CLEANUP_GROUP_CHECK_FINAL=_bb_cleanup_group_check
async def _bb_cleanup_group_check(chat_id):
    result=await _OLD_BB_CLEANUP_GROUP_CHECK_FINAL(chat_id)
    try:
        SECURITY_CLEANUP_CACHE[int(chat_id)]=(time.monotonic(),bool(result[0]))
    except Exception: pass
    return result



