# سخنگو فقط از پاسخ‌های متنی ثبت‌شده استفاده می‌کند.
# هیچ AI/حافظه/پاسخ تصادفی برای پیام‌های عادی سخنگو اجرا نمی‌شود.
# قابلیت‌های صدا/تولید صدا در بخش‌های مستقل خودشان دست‌نخورده می‌مانند.
async def speaker_text_text_only(update, context):
    msg=update.effective_message
    chat=update.effective_chat
    user=update.effective_user
    if not msg or not chat or chat.type=='private' or not user:
        return False
    text=msg.text or ''
    if not text or text.startswith('/'):
        return False
    await _speaker_schema()
    t=_speaker_clean_question(text)
    if not t:
        return False

    admin=await is_admin(update,user.id)
    if admin and t in {'سخنگو روشن','سخنگو خاموش'}:
        val=1 if t.endswith('روشن') else 0
        await DBX.execute(
            'INSERT INTO speaker_settings(chat_id,enabled,updated_at) VALUES(?,?,?) '
            'ON CONFLICT(chat_id) DO UPDATE SET enabled=excluded.enabled,updated_at=excluded.updated_at',
            (chat.id,val,now_ts())
        )
        await msg.reply_text('💬 سخنگوی بیل بیلک '+('روشن شد 🟢' if val else 'خاموش شد ⚪'))
        return True

    if admin and t.startswith('تنظیم چت '):
        question=t[len('تنظیم چت '):].strip()
        reply=msg.reply_to_message
        if not question or not reply:
            await msg.reply_text('❌ برای «تنظیم چت» باید روی پاسخ موردنظر ریپلای کنی.')
            return True
        media=_speaker_media_from_message(reply)
        if not media:
            await msg.reply_text('❌ این نوع پیام برای پاسخ سخنگو پشتیبانی نمی‌شود.')
            return True
        typ,fid,content=media
        await DBX.execute(
            'INSERT INTO speaker_global_chats(question,answer_type,answer_text,file_id,caption,source_chat_id,created_by,created_at) VALUES(?,?,?,?,?,?,?,?)',
            (question,typ,content if typ=='text' else '',fid,content if typ!='text' else '',chat.id,user.id,now_ts())
        )
        await DBX.execute('INSERT OR IGNORE INTO speaker_settings(chat_id) VALUES(?)',(chat.id,))
        await msg.reply_text(f'✅ پاسخ برای «{question}» در دیتابیس سراسری ربات ثبت شد. 🌍 نوع پاسخ: {typ}')
        return True

    if admin and t.startswith('حذف چت ربات '):
        question=t[len('حذف چت ربات '):].strip()
        await DBX.execute('DELETE FROM speaker_global_chats WHERE question=?',(question,))
        await msg.reply_text(f'🗑 همه پاسخ‌های «{question}» حذف شدند.')
        return True

    if admin and t.startswith('حذف چت '):
        question=t[len('حذف چت '):].strip()
        reply=msg.reply_to_message
        if reply:
            media=_speaker_media_from_message(reply)
            rows=await DBX.execute(
                'SELECT id,answer_type,file_id,answer_text,caption FROM speaker_global_chats WHERE question=? ORDER BY id DESC',
                (question,),fetch=True
            )
            deleted=False
            for r in rows:
                if media and r['answer_type']==media[0] and (r['file_id'] or '')==(media[1] or '') and (r['answer_text'] or r['caption'] or '')==(media[2] or ''):
                    await DBX.execute('DELETE FROM speaker_global_chats WHERE id=?',(r['id'],))
                    deleted=True
                    break
            await msg.reply_text('✅ پاسخ ریپلای‌شده حذف شد.' if deleted else '❌ پاسخ موردنظر پیدا نشد.')
        else:
            await DBX.execute('DELETE FROM speaker_global_chats WHERE question=?',(question,))
            await msg.reply_text('🗑 پاسخ‌های سؤال حذف شدند.')
        return True

    if admin and t=='لیست چت':
        rows=await DBX.execute(
            'SELECT question,COUNT(*) n FROM speaker_global_chats GROUP BY question ORDER BY MAX(id) DESC LIMIT 100',
            (),fetch=True
        )
        out='💬 <b>فهرست چت‌های سخنگو</b>\n\n'+(
            '\n'.join(f'• {safe_text(r["question"],60)} — {r["n"]} پاسخ' for r in rows)
            if rows else 'هنوز سؤالی ثبت نشده.'
        )
        await msg.reply_text(out,parse_mode='HTML')
        return True

