        if t=='سخنگو حافظه روشن':
            await DBX.execute('UPDATE speaker_settings SET memory_enabled=1,updated_at=? WHERE chat_id=?',(now_ts(),chat.id)); await msg.reply_text('🧠 حافظه سخنگو روشن شد 🟢'); return True
        if t=='سخنگو حافظه خاموش':
            await DBX.execute('UPDATE speaker_settings SET memory_enabled=0,updated_at=? WHERE chat_id=?',(now_ts(),chat.id)); await msg.reply_text('🧠 حافظه سخنگو خاموش شد ⚪'); return True
