# FINAL MUSIC OVERRIDE — SunoAPI.org برای ساخت آهنگ + ElevenLabs برای افکت/صدای حیوان.
# مستندات سرویس Suno API: https://docs.sunoapi.org/suno-api/quickstart

async def _bb_generate_suno_music(prompt, length_ms=30000, instrumental=False):
    """Generate music through SunoAPI.org and return a local MP3 path.

    Flow:
      1) POST /api/v1/generate -> taskId
      2) GET /api/v1/generate/record-info?taskId=... until SUCCESS
      3) download the first audio_url to a temporary MP3 file
    """
    key=await _bb_pro_get('SUNO_API_KEY', os.getenv('SUNO_API_KEY',''))
    if not key:
        return None, '⚠️ کلید SUNO_API_KEY تنظیم نشده است. از پنل مالک → مرکز ساخت صدا و آهنگ → 🎵 Suno API کلید را ثبت کن.'

    prompt=safe_text(prompt,5000).strip()
    if not prompt:
        return None, '⚠️ پرامپت آهنگ خالی است.'

    # The API works asynchronously.  Keep the Telegram request responsive while
    # polling the provider in the background thread through the existing async HTTP helpers.
    headers={
        'Authorization': f'Bearer {key}',
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'User-Agent': 'BilBilak/2026',
    }
    payload={
        'prompt': prompt,
        'customMode': False,
        'instrumental': bool(instrumental),
        'model': 'V5',
    }

    try:
        r=await _bb_http_post_raw(
            'https://api.sunoapi.org/api/v1/generate',
            headers,
            json_body=payload,
            timeout=120,
        )
    except Exception as exc:
        return None, f'❌ ارتباط با Suno API ناموفق بود: {type(exc).__name__}: {str(exc)[:500]}'

    if not getattr(r,'ok',False):
        body=(getattr(r,'text','') or '').strip().replace('\n',' ')[:1000]
        return None, f'❌ Suno API درخواست ساخت آهنگ را رد کرد: HTTP {getattr(r,"status_code","?")} {body}'

    try:
        result=r.json()
    except Exception:
        return None, '❌ پاسخ Suno API قابل خواندن نبود.'

    data=result.get('data') if isinstance(result,dict) else None
    task_id=data.get('taskId') if isinstance(data,dict) else None
    if not task_id:
        return None, f'❌ Suno API شناسه ساخت آهنگ برنگرداند: {safe_text(str(result),800)}'

    # Provider docs recommend polling the record-info endpoint.  Ten minutes is
    # enough for normal generation while avoiding an endless task.
    deadline=time.monotonic()+600
    last_status='UNKNOWN'
    while time.monotonic()<deadline:
        try:
            sr=await _bb_http_get_json(
                'https://api.sunoapi.org/api/v1/generate/record-info',
                {'Authorization': f'Bearer {key}','Accept':'application/json','User-Agent':'BilBilak/2026'},
                params={'taskId':task_id},
                timeout=45,
            )
        except Exception as exc:
            # Temporary provider/network errors are retried on the next poll.
            last_status=f'network:{type(exc).__name__}'
            await asyncio.sleep(8)
            continue

        if not isinstance(sr,dict):
            await asyncio.sleep(8)
            continue

        sd=sr.get('data') if isinstance(sr.get('data'),dict) else {}
        status=str(sd.get('status') or '').upper()
        last_status=status or last_status

        if status=='SUCCESS':
            response=sd.get('response') if isinstance(sd.get('response'),dict) else {}
            tracks=response.get('data') if isinstance(response.get('data'),list) else []
            if not tracks:
                return None, '❌ Suno ساخت آهنگ را موفق اعلام کرد ولی فایل صوتی در پاسخ وجود نداشت.'

            first=tracks[0] if isinstance(tracks[0],dict) else {}
            audio_url=first.get('audio_url') or first.get('audioUrl') or first.get('source_audio_url')
            if not audio_url:
                return None, '❌ Suno ساخت آهنگ را موفق اعلام کرد ولی لینک فایل صوتی پیدا نشد.'

            # Use requests in a worker so large MP3 downloads do not block the bot event loop.
            try:
                import requests
                def _download():
                    rr=requests.get(str(audio_url),timeout=180,headers={'User-Agent':'BilBilak/2026'})
                    rr.raise_for_status()
                    return rr.content
                audio_bytes=await asyncio.to_thread(_download)
            except Exception as exc:
                return None, f'❌ دانلود فایل ساخته‌شده از Suno ناموفق بود: {type(exc).__name__}: {str(exc)[:500]}'

            if not audio_bytes or len(audio_bytes)<1000:
                return None, '❌ فایل صوتی دریافتی از Suno خالی یا ناقص بود.'

            path=Path(tempfile.gettempdir())/f'bilbilak_suno_{now_ts()}_{random.randint(1000,9999)}.mp3'
            try:
                path.write_bytes(audio_bytes)
            except Exception as exc:
                return None, f'❌ ذخیره فایل آهنگ ناموفق بود: {type(exc).__name__}: {str(exc)[:400]}'
            return path,None

        if status in {'FAILED','ERROR','FAILURE'}:
            err_msg=sd.get('errorMessage') or sd.get('error') or sr.get('msg') or 'تولید آهنگ ناموفق شد.'
            return None, f'❌ Suno تولید آهنگ را ناموفق اعلام کرد: {safe_text(str(err_msg),700)}'

        await asyncio.sleep(10)

    return None, f'⏱️ زمان انتظار برای ساخت آهنگ تمام شد. وضعیت آخر: {safe_text(last_status,100)}. دوباره درخواست بده.'


async def _bb_generate_eleven_music(prompt, length_ms=30000, instrumental=False):
    """Compatibility wrapper: music generation is now handled by Suno API."""
    return await _bb_generate_suno_music(prompt,length_ms,instrumental)


async def _bb_generate_song_for_user(msg, prompt, length_ms=30000, instrumental=False):
    await msg.reply_text('🎼 در حال ساخت آهنگ با Suno…\n⏳ ساخت آهنگ ممکن است چند دقیقه طول بکشد.')
    path,err=await _bb_generate_suno_music(prompt,length_ms,instrumental)
    if err:
        await msg.reply_text(safe_text(err,1200),parse_mode='HTML')
        return True
    try:
        with open(path,'rb') as f:
            await msg.reply_audio(f,title='🎼 آهنگ ساخته‌شده با Suno',caption='🎼 توسط بیل بیلک ساخته شد')
    finally:
        try: path.unlink(missing_ok=True)
        except Exception: pass
    return True

