def _bb_diamond_board(uid, session, reveal=False):
    rows=[]
    bomb=int(session['bomb'])
    picked=set(session.get('picked', set()))
    for r in range(3):
        row=[]
        for c in range(3):
            n=r*3+c
            if reveal:
                label='💣' if n==bomb else ('💎' if n in picked else '▫️')
                cb=f'bc2_noop:{uid}'
            elif n in picked:
                label='💎'
                cb=f'bc2_noop:{uid}'
            else:
                label='💎'
                cb=f'bc2_pick:{uid}:{session["id"]}:{n}'
            row.append(btn(label, cb))
        rows.append(row)
    return rows


