from urllib.parse import quote_plus as _bb_quote_plus
import html as _bb_html

BB_TOOL_PENDING = globals().get('BB_TOOL_PENDING', {})
BB_PRIVATE_NOTES = globals().get('BB_PRIVATE_NOTES', {})
BB_TOOL_CACHE = globals().get('BB_TOOL_CACHE', {})

async def _bb_http_get_json(url, headers=None, params=None, timeout=25):
    """GET helper using the already available requests dependency."""
    import requests
    def _work():
        r=requests.get(url, headers=headers or {}, params=params or {}, timeout=timeout)
        try:
            data=r.json()
        except Exception:
            data=None
        return r.status_code, data, (r.text or '')[:2000]
    return await asyncio.to_thread(_work)


def _bb_h(v):
    return _bb_html.escape(str(v if v is not None else ''))


def _bb_now_date_iso():
    return datetime.utcnow().strftime('%Y-%m-%d')

# ---------- Country data ----------
BB_COUNTRY_ALIASES = {
    'ایران':'iran','ایالات متحده':'united states','امریکا':'united states','آمریکا':'united states',
    'انگلیس':'united kingdom','بریتانیا':'united kingdom','کره جنوبی':'south korea','کره شمالی':'north korea',
    'روسیه':'russia','چین':'china','ژاپن':'japan','آلمان':'germany','فرانسه':'france','ایتالیا':'italy',
    'اسپانیا':'spain','ترکیه':'turkey','امارات':'united arab emirates','امارات متحده عربی':'united arab emirates',
    'عربستان':'saudi arabia','هند':'india','پاکستان':'pakistan','افغانستان':'afghanistan','کانادا':'canada',
    'استرالیا':'australia','برزیل':'brazil','آرژانتین':'argentina','مکزیک':'mexico','مصر':'egypt',
}

async def _bb_country_fetch(name):
    q=BB_COUNTRY_ALIASES.get(normalize(name), name).strip()
    if not q: return None
    cache_key='country:'+normalize(q)
    if cache_key in BB_TOOL_CACHE: return BB_TOOL_CACHE[cache_key]
    # Prefer the current authenticated REST Countries API if owner configured a key.
    api_key=await _bb_pro_get('RESTCOUNTRIES_API_KEY','')
    if api_key:
        try:
            st,data,_=await _bb_http_get_json(
                'https://api.restcountries.com/v3.1/all',
                headers={'Authorization':f'Bearer {api_key}'},
                params={},timeout=20)
            if st==200 and isinstance(data,dict):
                objs=(data if isinstance(data,list) else ((data.get('data') or {}).get('objects') or data.get('objects') or []))
                if objs:
                    BB_TOOL_CACHE[cache_key]=objs[0]; return objs[0]
        except Exception as exc:
            log.warning('REST Countries v5 failed: %s',exc)
    # Public legacy endpoint fallback; no key required. The bot still works without a key.
    try:
        st,data,_=await _bb_http_get_json(
            f'https://restcountries.com/v3.1/name/{_bb_quote_plus(q)}',
            params={'fullText':'false'},timeout=20)
        if st==200 and isinstance(data,list) and data:
            BB_TOOL_CACHE[cache_key]=data[0]; return data[0]
    except Exception as exc:
        log.warning('country lookup failed: %s',exc)
    return None


def _bb_country_get(d,key,default=''):
    if not isinstance(d,dict): return default
    if key in d: return d.get(key) or default
    return default


def _bb_country_name(d):
    n=d.get('name') or {}
    if isinstance(n,dict):
        return n.get('common') or n.get('official') or 'نامشخص'
    return str(n or 'نامشخص')


def _bb_country_leader(d):
    leaders=d.get('leaders') if isinstance(d,dict) else None
    if isinstance(leaders,list) and leaders:
        vals=[]
        for x in leaders[:3]:
            if isinstance(x,dict): vals.append(x.get('name') or x.get('common') or '')
            elif x: vals.append(str(x))
        if vals: return '، '.join(v for v in vals if v)
    return 'در داده عمومی این منبع ثبت نشده'

async def _bb_country_leader_v5(name):
    api_key=await _bb_pro_get('RESTCOUNTRIES_API_KEY','')
    if not api_key: return ''
    try:
        st,data,_=await _bb_http_get_json('https://api.restcountries.com/v3.1/all',headers={'Authorization':f'Bearer {api_key}'},params={},timeout=20)
        objs=(data if isinstance(data,list) else (((data or {}).get('data') or {}).get('objects') if isinstance(data,dict) else None))
        if objs:
            return _bb_country_leader(objs[0])
    except Exception: pass
    return ''

async def _bb_country_text(name):
    d=await _bb_country_fetch(name)
    if not d: return None, None
    n=d.get('name') or {}
    common=n.get('common') if isinstance(n,dict) else str(n or '')
    official=n.get('official') if isinstance(n,dict) else ''
    capital=', '.join(d.get('capital') or []) or 'ثبت نشده'
    languages=', '.join((d.get('languages') or {}).values()) or 'ثبت نشده'
    currencies=d.get('currencies') or {}
    cur_parts=[]
    for code,c in list(currencies.items())[:3]:
        cur_parts.append(f'{c.get("name",code)} ({code})' if isinstance(c,dict) else str(code))
    currency='، '.join(cur_parts) or 'ثبت نشده'
    flags=d.get('flags') or {}
    flag=flags.get('png') or flags.get('svg')
    region=d.get('region') or 'ثبت نشده'
    subregion=d.get('subregion') or 'ثبت نشده'
    population=d.get('population') or 0
    tz=', '.join(d.get('timezones') or []) or 'ثبت نشده'
    tld=', '.join(d.get('tld') or []) or 'ثبت نشده'
    calling=(d.get('idd') or {}).get('root','') + ''.join((d.get('idd') or {}).get('suffixes') or [])
    if not calling: calling='ثبت نشده'
    leader=await _bb_country_leader_v5(common) or _bb_country_leader(d)
    dem=d.get('demonyms') or {}
    passport='رتبه دقیق و روزآمد در این نسخه از منبع داده کشور قابل استخراج خودکار نیست؛ دکمه منبع رسمی در ادامه راهنما قرار می‌گیرد.'
    local_time='ثبت نشده'
    try:
        from zoneinfo import ZoneInfo
        zname=(d.get('timezones') or ['UTC'])[0]
        local_time=datetime.now(ZoneInfo(zname)).strftime('%Y-%m-%d %H:%M:%S')
    except Exception:
        pass
    # Try the first listed currency against IRR so the country card also shows its value.
    currency_irr='ثبت نشده'
    try:
        first_code=next(iter(currencies.keys()),'')
        if first_code:
            rate_text=await _bb_currency_one(first_code)
            mrate=re.search(r'≈\s*<b>([0-9,]+)',rate_text or '')
            if mrate: currency_irr=f'1 {first_code} ≈ {mrate.group(1)} ریال'
    except Exception:
        pass
    # A five-line description assembled only from country data, without inventing facts.
    desc=(
        f'🌍 {common} کشوری در قاره/منطقه {region} و ناحیه {subregion} است.\n'
        f'🏙 پایتخت آن {capital} است و جمعیت ثبت‌شده در داده منبع حدود {population:,} نفر است.\n'
        f'🗣 زبان‌های ثبت‌شده: {languages}.\n'
        f'💰 واحد/واحدهای پول: {currency}.\n'
        f'🧭 این رکورد اطلاعات جغرافیایی، زمانی و ارتباطی کشور را نیز در اختیار ربات می‌گذارد.'
    )
    text=(
        f'🌍 <b>{_bb_h(common)}</b>\n\n'
        f'🏳️ نام کامل: <b>{_bb_h(official or common)}</b>\n'
        f'🗣 زبان: <b>{_bb_h(languages)}</b>\n'
        f'💰 واحد پول: <b>{_bb_h(currency)}</b>\n'
        f'🏙 پایتخت: <b>{_bb_h(capital)}</b>\n'
        f'👑 رئیس‌جمهور/رهبر/پادشاه: <b>{_bb_h(leader)}</b>\n'
        f'🌎 قاره/منطقه: <b>{_bb_h(region)}</b> / {_bb_h(subregion)}\n'
        f'👥 جمعیت: <b>{population:,}</b>\n'
        f'🕐 منطقه زمانی: <b>{_bb_h(tz)}</b>\n'
        f'📅 تاریخ/ساعت محلی: <b>{_bb_h(local_time)}</b>\n'
        f'💱 ارزش تقریبی پول نسبت به ریال: <b>{_bb_h(currency_irr)}</b>\n'
        f'📊 رتبه پاسپورت: <b>{_bb_h(passport)}</b>\n'
        f'📞 کد تماس: <b>{_bb_h(calling)}</b>\n'
        f'🌐 دامنه اینترنتی: <b>{_bb_h(tld)}</b>\n'
        f'🎨 رنگ پوست: <b>این ویژگی یک مشخصه رسمی و قابل تعمیم برای یک کشور نیست.</b>\n\n'
        f'📝 <b>درباره کشور:</b>\n{_bb_h(desc)}'
    )
    return text, flag

# ---------- Weather ----------
BB_WMO = {
    0:'آسمان صاف',1:'عمدتاً صاف',2:'نیمه‌ابری',3:'ابری',45:'مه',48:'مه یخ‌زن',
    51:'نم‌نم باران',53:'باران ریز',55:'باران ریز شدید',56:'نم‌نم یخ‌زن',57:'نم‌نم یخ‌زن شدید',
    61:'باران',63:'باران متوسط',65:'باران شدید',66:'باران یخ‌زن',67:'باران یخ‌زن شدید',
    71:'برف',73:'برف متوسط',75:'برف شدید',77:'دانه‌های برف',80:'رگبار باران',81:'رگبار متوسط',82:'رگبار شدید',
    85:'رگبار برف',86:'رگبار برف شدید',95:'رعدوبرق',96:'رعدوبرق و تگرگ',99:'رعدوبرق و تگرگ شدید'
}

async def _bb_weather_lookup(city):
    q=city.strip()
    if not q: return '❌ نام شهر را بنویس.'
    try:
        st,g,_=await _bb_http_get_json('https://geocoding-api.open-meteo.com/v1/search',params={'name':q,'count':3,'language':'fa','format':'json'},timeout=15)
        places=(g or {}).get('results') if isinstance(g,dict) else None
        if not places:
            return f'❌ شهر «{_bb_h(q)}» پیدا نشد.'
        p=places[0]; lat,lon=p.get('latitude'),p.get('longitude')
        st,w,_=await _bb_http_get_json('https://api.open-meteo.com/v1/forecast',params={
            'latitude':lat,'longitude':lon,'current':'temperature_2m,apparent_temperature,relative_humidity_2m,precipitation,rain,snowfall,weather_code,wind_speed_10m',
            'hourly':'precipitation_probability,rain_probability,snowfall_probability','forecast_days':1,'timezone':'auto'
        },timeout=20)
        if st!=200 or not isinstance(w,dict): return '❌ سرویس آب‌وهوا پاسخ نداد.'
        c=w.get('current') or {}; h=w.get('hourly') or {}
        code=int(c.get('weather_code') or 0); desc=_bb_h(BB_WMO.get(code,'وضعیت جوی'))
        probs=[]
        for key,label in [('rain_probability','باران'),('snowfall_probability','برف')]:
            vals=h.get(key) or []
            if vals:
                mx=max(int(x or 0) for x in vals)
                if mx>0: probs.append(f'☔ احتمال {label}: <b>{mx}%</b>')
        tz=w.get('timezone','')
        return (
            f'🌦️ <b>آب‌وهوای {_bb_h(p.get("name") or q)}</b>\n\n'
            f'🌡 دما: <b>{c.get("temperature_2m","-")}°C</b>\n'
            f'🌡 دمای محسوس: <b>{c.get("apparent_temperature","-")}°C</b>\n'
            f'☁️ وضعیت: <b>{desc}</b>\n'
            f'💧 رطوبت: <b>{c.get("relative_humidity_2m","-")}%</b>\n'
            f'💨 باد: <b>{c.get("wind_speed_10m","-")} km/h</b>\n'
            f'🌧 بارش فعلی: <b>{c.get("precipitation","0")} mm</b>\n'
            + (''.join('\n'+x for x in probs) if probs else '') +
            f'\n🕐 منطقه زمانی: {_bb_h(tz)}'
        )
    except Exception as exc:
        log.warning('weather tool failed: %s',exc)
        return '❌ دریافت آب‌وهوا موقتاً ناموفق بود.'

