# ---------- Currency (Iran free-market API) ----------
# Uses a dedicated Iranian-market feed instead of a generic global FX feed.
# The API reports Iranian-market prices in Toman; Bilbilak converts them to Rial.
BB_CURRENCY_NAMES = {
 'دلار':'USD','دلار آمریکا':'USD','یورو':'EUR','پوند':'GBP','پوند انگلیس':'GBP','ین':'JPY','یوان':'CNY',
 'ریال':'IRR','تومان':'IRR','درهم':'AED','لیر':'TRY','روبل':'RUB','روپیه':'INR','دینار عراق':'IQD',
 'دینار کویت':'KWD','ریال عمان':'OMR','ریال قطر':'QAR','منات':'AZN','لاری':'GEL','فرانک سوئیس':'CHF',
 'دلار کانادا':'CAD','دلار استرالیا':'AUD','دلار نیوزیلند':'NZD','وون':'KRW','کرون سوئد':'SEK','کرون نروژ':'NOK',
 'کرون دانمارک':'DKK','رند':'ZAR','بات':'THB','رینگیت':'MYR','پزو':'PHP','پزوی مکزیک':'MXN','پزوی آرژانتین':'ARS',
}
BB_CURRENCY_SYMBOLS={'USD':'💵','EUR':'💶','GBP':'💷','JPY':'💴','CNY':'🪙','IRR':'🇮🇷','AED':'🇦🇪','TRY':'🇹🇷','RUB':'🇷🇺','INR':'🇮🇳','CHF':'🇨🇭','CAD':'🇨🇦','AUD':'🇦🇺','KRW':'🇰🇷'}

async def _bb_currency_rates():
    """Return Iranian free-market rates from NetArz.
    Response prices are Toman; callers convert to Rial when displaying.
    """
    key = await _bb_pro_get('NETARZ_API_KEY', os.getenv('NETARZ_API_KEY',''))
    if not key:
        return None
    cache_key='currency:NETARZ:IRAN'
    cached=BB_TOOL_CACHE.get(cache_key)
    if cached and isinstance(cached,dict) and time.time()-float(cached.get('_ts',0) or 0) < 180:
        return cached
    try:
        st,data,_=await _bb_http_get_json(
            'https://netarz.ir/api/fx/v1/rates',
            headers={'Authorization':f'Bearer {key}','Accept':'application/json'},
            timeout=20
        )
        if st==200 and isinstance(data,dict) and isinstance(data.get('data'),list):
            data['_ts']=time.time()
            BB_TOOL_CACHE[cache_key]=data
            return data
        log.warning('NETARZ currency API failed: HTTP %s',st)
    except Exception as exc:
        log.warning('NETARZ currency API error: %s',exc)
    return None

def _bb_currency_rows(data):
    rows={}
    for item in ((data or {}).get('data') or []):
        if not isinstance(item,dict):
            continue
        code=str(item.get('code') or '').upper()
        if code:
            rows[code]=item
    return rows

async def _bb_currency_code(raw):
    x=raw.strip(); up=x.upper()
    if re.fullmatch(r'[A-Z]{3}',up): return up
    return BB_CURRENCY_NAMES.get(normalize(x))

async def _bb_currency_one(raw):
    code=await _bb_currency_code(raw)
    if not code:
        return '❌ ارز پیدا نشد. کد سه‌حرفی ISO مثل USD را هم می‌توانی بنویسی.'
    if code=='IRR':
        return '🇮🇷 <b>1 IRR</b> = <b>1 ریال ایران</b>'
    data=await _bb_currency_rates()
    if not data:
        return '⚠️ <b>API ارز در دسترس نیست.</b>\n\nکلید <b>NETARZ_API_KEY</b> را در پنل API تنظیم کن.'
    row=_bb_currency_rows(data).get(code)
    if not row:
        return f'❌ نرخ <b>{_bb_h(code)}</b> در API فعلی موجود نیست.'
    try:
        unit=max(1,float(row.get('unit') or 1))
        buy=float(row.get('buy'))*10/unit
        sell=float(row.get('sell'))*10/unit
        mid=float(row.get('mid') or ((float(row.get('buy'))+float(row.get('sell')))/2))*10/unit
    except Exception:
        return f'❌ داده نرخ <b>{_bb_h(code)}</b> از API معتبر نبود.'
    sym=BB_CURRENCY_SYMBOLS.get(code,'💱')
    return (f'{sym} <b>1 {code}</b>\n'
            f'🟢 خرید: <b>{buy:,.0f} ریال</b>\n'
            f'🔴 فروش: <b>{sell:,.0f} ریال</b>\n'
            f'📊 میانگین: <b>{mid:,.0f} ریال</b>\n\n'
            'ℹ️ منبع: نرخ بازار ایران؛ قیمت‌ها تقریبی و وابسته به زمان دریافت هستند.')

async def _bb_currency_top10():
    data=await _bb_currency_rates()
    if not data:
        return '⚠️ <b>API ارز در دسترس نیست.</b>\n\nکلید <b>NETARZ_API_KEY</b> را در پنل API تنظیم کن.'
    rows=_bb_currency_rows(data)
    codes=['USD','EUR','GBP','JPY','CNY','AED','TRY','CAD','AUD','CHF']
    lines=['💱 <b>۱۰ ارز معروف نسبت به ریال ایران</b>','']
    for i,c in enumerate(codes,1):
        row=rows.get(c)
        if not row:
            continue
        try:
            unit=max(1,float(row.get('unit') or 1))
            mid=float(row.get('mid') or ((float(row.get('buy'))+float(row.get('sell')))/2))*10/unit
            sym=BB_CURRENCY_SYMBOLS.get(c,'💱')
            lines.append(f'{i}. {sym} <b>{c}</b> ≈ <b>{mid:,.0f} ریال</b>')
        except Exception:
            continue
    lines.append('\nبرای هر ارز دیگر: <b>ارز CODE</b>')
    return '\n'.join(lines)

# ---------- Maps / location ----------
async def _bb_geocode_place(query):
    try:
        st,data,_=await _bb_http_get_json('https://nominatim.openstreetmap.org/search',headers={'User-Agent':'BilBilak/2026 country-weather-tools'},params={'q':query,'format':'jsonv2','limit':3,'addressdetails':1,'accept-language':'fa,en'},timeout=20)
        if st==200 and isinstance(data,list): return data
    except Exception as exc: log.warning('geocode failed: %s',exc)
    return []

async def _bb_location_tool(msg, query):
    q=query.strip()
    if not q: return False
    results=await _bb_geocode_place(q)
    if not results:
        await msg.reply_text(f'❌ «{_bb_h(q)}» پیدا نشد.'); return True
    r=results[0]; lat=r.get('lat'); lon=r.get('lon'); title=r.get('display_name') or q
    enc=_bb_quote_plus(q)
    google=f'https://www.google.com/maps/search/?api=1&query={enc}'
    # Search links are intentionally used instead of vendor API keys; they open the selected map app/site.
    balad=f'https://balad.ir/search/{enc}'
    neshan=f'https://neshan.org/search/{enc}'
    try:
        await msg.reply_location(latitude=float(lat), longitude=float(lon))
    except Exception as exc:
        log.warning('send location pin failed: %s', exc)
    await msg.reply_text(
        f'📍 <b>{_bb_h(title)}</b>\n\n📌 مختصات: {lat}, {lon}\n\nمکان روی نقشه بالا نمایش داده شد. برای باز کردن در سرویس‌های دیگر:',
        parse_mode='HTML',reply_markup=keyboard([
            [btn('🗺 Google Maps',url=google)],
            [btn('🧭 بلد',url=balad),btn('📍 نشان',url=neshan)],
        ]))
    return True

