async def _bb_sports_find_league(sport, league):
    api=await _bb_pro_get('APISPORTS_API_KEY','')
    if not api: return None,'کلید API-Sports تنظیم نشده است.'
    info=BB_SPORTS.get(sport)
    if not info: return None,'ورزش پشتیبانی نمی‌شود.'
    base=info[1]
    try:
        st,data,_=await _bb_http_get_json(base+'/leagues',headers={'x-apisports-key':api},params={'search':league.strip()},timeout=20)
        if st!=200: return None,f'API-Sports HTTP {st}'
        resp=(data or {}).get('response') or []
        if not resp: return None,'لیگ پیدا نشد.'
        # Prefer a league with a current/latest season.
        return resp[0],None
    except Exception as exc:
        return None,f'خطای سرویس ورزش: {type(exc).__name__}'

async def _bb_sports_today(sport, league):
    item,err=await _bb_sports_find_league(sport,league)
    if err: return err
    api=await _bb_pro_get('APISPORTS_API_KEY','')
    base=BB_SPORTS[sport][1]
    lid=((item.get('league') or {}).get('id')) if isinstance(item,dict) else None
    seasons=((item.get('seasons') or []) if isinstance(item,dict) else [])
    year=datetime.utcnow().year
    available=[int(x.get('season')) for x in seasons if isinstance(x,dict) and str(x.get('season','')).isdigit()]
    season=year if year in available else (max(available) if available else year)
    endpoint='/fixtures' if sport=='فوتبال' else '/games'
    params={'date':_bb_now_date_iso()}
    if lid: params['league']=lid; params['season']=season
    try:
        st,data,_=await _bb_http_get_json(base+endpoint,headers={'x-apisports-key':api},params=params,timeout=25)
        if st!=200: return f'❌ سرویس {sport} پاسخ HTTP {st} داد.'
        games=(data or {}).get('response') or []
        if not games: return f'⚽ بازی امروز برای «{_bb_h(league)}» پیدا نشد.'
        lines=[f'🏟 <b>بازی‌های امروز {sport} — {_bb_h(league)}</b>','']
        for g in games[:15]:
            lg=g.get('league') or {}; teams=g.get('teams') or {}; home=teams.get('home') or {}; away=teams.get('away') or {}
            if sport=='فوتبال':
                dt=((g.get('fixture') or {}).get('date') or '')
                timepart=dt[11:16] if len(dt)>=16 else '-'
            else:
                dt=g.get('date') or ''
                timepart=dt[11:16] if len(dt)>=16 else '-'
            lines.append(f'🏆 <b>{_bb_h(lg.get("name") or league)}</b>\n• {_bb_h(home.get("name") or "-")} vs {_bb_h(away.get("name") or "-")} — <b>{timepart}</b>')
        # Official/legal destination choices; no stream is proxied by the bot.
        rows=[[btn('📺 Footballi',url='https://footballi.net/')] if sport=='فوتبال' else [btn('🌐 جستجوی رسمی ورزش',url=f'https://www.google.com/search?q={_bb_quote_plus(sport+" "+league)}')]]
        if sport=='فوتبال': rows[0].append(btn('📺 360',url='https://360tv.ir/'))
        rows.append([btn('🔙 بستن',f'sportclose:{g.get("league",{}).get("id",0)}')])
        return '\n\n'.join(lines),keyboard(rows)
    except Exception as exc:
        log.warning('sports lookup failed: %s',exc)
        return '❌ دریافت برنامه مسابقات موقتاً ناموفق بود.'

# ---------- Anonymous/private-note feature ----------
async def _bb_anon_create(msg, target_raw, body):
    target=target_raw.strip()
    uid=msg.from_user.id
    note_id=f'{now_ts()}_{random.randint(100000,999999)}'
    BB_PRIVATE_NOTES[note_id]={'sender':uid,'target':target,'body':body[:3500],'created':now_ts()}
    target_label=target if target.startswith('@') else f'کاربر {target}'
    markup=keyboard([[btn('📖 خواندن پیام',f'anread:{uid}:{note_id}')]])
    # The secret body is never placed in a group message. This is stronger than a
    # Telegram spoiler because Telegram spoilers cannot enforce per-user access.
    if msg.chat and getattr(msg.chat,'type',None) in {'group','supergroup'}:
        await msg.reply_text(
            f'🔐 <b>یک پیام محرمانه برای {_bb_h(target_label)} ثبت شد.</b>\n\n'
            'محتوای پیام در گروه نمایش داده نمی‌شود. فقط گیرنده مجاز می‌تواند آن را بخواند.',
            parse_mode='HTML',reply_markup=markup)
    else:
        await msg.reply_text(
            f'🔐 <b>پیام محرمانه ثبت شد</b>\n\nبرای <b>{_bb_h(target_label)}</b> آماده شد.\n'
            'محتوا فقط در خصوصی برای گیرنده ارسال می‌شود.',
            parse_mode='HTML',reply_markup=markup)
    return True

async def _bb_anon_callback(q, context):
    data=(q.data or '').split(':',2)
    if len(data)!=3 or data[0]!='anread': return False
    sender=int(data[1]) if data[1].isdigit() else 0; note_id=data[2]
    note=BB_PRIVATE_NOTES.get(note_id)
    if not note:
        await q.answer('⏳ این پیام دیگر در دسترس نیست.',show_alert=True); return True
    target=str(note.get('target','')).strip()
    user=q.from_user
    allowed=str(user.id)==target or (target.startswith('@') and (('@'+(user.username or '')).lower()==target.lower()))
    if not allowed:
        await q.answer(f'😏 به تو چه! این پیام برای {_bb_h(target or "کاربر") } است.',show_alert=True); return True
    # Send privately to the recipient; this guarantees the content is not exposed in the group.
    try:
        await context.bot.send_message(user.id,f'🔐 <b>پیام محرمانه:</b>\n\n{_bb_h(note["body"])}',parse_mode='HTML')
        await q.answer('📩 پیام محرمانه در خصوصی برایت ارسال شد.',show_alert=True)
    except Exception:
        await q.answer('❌ برای دریافت پیام محرمانه، اول ربات را در خصوصی /start کن.',show_alert=True)
    return True

