# ---------- Final tool text router ----------
async def _bb_expanded_tools_text(update, context):
    msg=update.effective_message; user=update.effective_user; chat=update.effective_chat
    if not msg or not user or not msg.text: return False
    t=msg.text.strip(); n=normalize(t)

    # Country
    if re.match(r'^کشور\s+.+',t):
        name=re.sub(r'^کشور\s+','',t).strip(); text,flag=await _bb_country_text(name)
        if not text: await msg.reply_text('❌ کشور پیدا نشد. نام کشور را واضح‌تر بنویس.'); return True
        country_markup=keyboard([[btn('📊 رتبه پاسپورت 2026',url='https://www.henleyglobal.com/passport-index/ranking')]])
        if flag:
            try: await msg.reply_photo(flag,caption=text,parse_mode='HTML',reply_markup=country_markup); return True
            except Exception: pass
        await msg.reply_text(text,parse_mode='HTML',reply_markup=country_markup); return True

    # Weather
    m=re.match(r'^(?:آب\s*و\s*هوا|هوا)(?:ی)?\s+(.+)$',t)
    if m:
        await msg.reply_text(await _bb_weather_lookup(m.group(1)),parse_mode='HTML'); return True

    # Currency
    if n in {'قیمت ارزها','قیمت ارز ها','نرخ ارزها','نرخ ارز ها'}:
        await msg.reply_text(await _bb_currency_top10(),parse_mode='HTML'); return True
    m=re.match(r'^(?:ارز|قیمت ارز|نرخ ارز)\s+(.+)$',t,re.I)
    if m:
        await msg.reply_text(await _bb_currency_one(m.group(1)),parse_mode='HTML'); return True

    # Maps: never request user's own location.
    m=re.match(r'^(?:مکانیابی|مکان|لوکیشن|موقعیت)\s+(.+)$',t)
    if m:
        return await _bb_location_tool(msg,m.group(1))
    if t.endswith('کجاست؟') or t.endswith('کجاست?'):
        q=t[:-6].strip()
        if q: return await _bb_location_tool(msg,q)

    # Sports: football(league), and generic sport(league).
    for fa in BB_SPORTS:
        m=re.match(r'^'+re.escape(fa)+r'\s+(.+)$',t,re.I)
        if m:
            result=await _bb_sports_today(fa,m.group(1))
            if isinstance(result,tuple): text,markup=result; await msg.reply_text(text,parse_mode='HTML',reply_markup=markup)
            else: await msg.reply_text('🏟 '+safe_text(result,1500),parse_mode='HTML')
            return True

    # Anonymous/private note: /secret <id|@username> <message> or /anon ...
    if t.startswith('/secret ') or t.startswith('/anon '):
        parts=t.split(maxsplit=2)
        if len(parts)<3:
            await msg.reply_text('فرمت: /secret 123456789 متن پیام یا /secret @username متن پیام',parse_mode='HTML'); return True
        return await _bb_anon_create(msg,parts[1],parts[2])

    if n in {'فال','فال حافظ','فال قهوه'}:
        if n=='فال قهوه': title='☕ فال قهوه روزانه'; body=random.choice(BB_COFFEE_FORTUNES)
        else: title='📜 فال حافظ روزانه'; body=random.choice(BB_HAFEZ_FORTUNES)
        await msg.reply_text(f'<b>{title}</b>\n\n{_bb_h(body)}',parse_mode='HTML'); return True

    m=re.match(r'^فال\s+(حافظ|قهوه)$',t)
    if m:
        body=random.choice(BB_HAFEZ_FORTUNES if m.group(1)=='حافظ' else BB_COFFEE_FORTUNES)
        await msg.reply_text(f'🔮 <b>فال {m.group(1)} روزانه</b>\n\n{_bb_h(body)}',parse_mode='HTML'); return True

    # Quran page N: text + official page button + first ayah audio when available.
    m=re.match(r'^(?:صفحه|صفحه قرآن|قرآن صفحه)\s*(\d{1,3})$',t)
    if m:
        page=max(1,min(604,int(m.group(1))))
        try:
            st,data,_=await _bb_http_get_json(f'https://api.alquran.cloud/v1/page/{page}/quran-uthmani',timeout=20)
            ayahs=((data or {}).get('data') or {}).get('ayahs') or []
            if not ayahs:
                await msg.reply_text('❌ صفحه قرآن پیدا نشد.'); return True
            lines=[f'📖 <b>صفحه {page} قرآن</b>','']
            for a in ayahs:
                lines.append(f'﴿{_bb_h(a.get("numberInSurah",""))}﴾ {_bb_h(a.get("text",""))}')
            rows=[[btn('📖 باز کردن صفحه قرآن',url=f'https://quran.com/page/{page}')]]
            # Audio is sent for the first ayah; the CDN is public and documented by Al Quran Cloud.
            first=ayahs[0]; num=first.get('number')
            if num:
                rows.append([btn('🔊 پخش صوت آیه اول',url=f'https://cdn.islamic.network/quran/audio/128/ar.alafasy/{num}.mp3')])
            await msg.reply_text('\n'.join(lines)[:3900],parse_mode='HTML',reply_markup=keyboard(rows)); return True
        except Exception as exc:
            log.warning('quran page failed: %s',exc); await msg.reply_text('❌ دریافت صفحه قرآن ناموفق بود.'); return True

    if n in {'دعا','دعای روز','دعای تصادفی'}:
        title,body=random.choice(BB_DUAS)
        await msg.reply_text(f'<b>{title}</b>\n\n{_bb_h(body)}\n\n🌙 معنی: از خدا آرامش، خیر و گشایش می‌خواهیم.',parse_mode='HTML'); return True

    if n=='بیو':
        await msg.reply_text('🪪 <b>بیوی پیشنهادی برای پروفایلت:</b>\n\n'+_bb_h(random.choice(BB_BIOS)),parse_mode='HTML'); return True

    return False

