async def _bb_expanded_tool_callback(q,context):
    data=q.data or ''; p=data.split(':')
    if len(p)==3 and p[0]=='toolpage2' and p[1].isdigit() and int(p[1])==q.from_user.id:
        page=int(p[2]) if p[2].isdigit() else 1
        text,rows=_bb_tool_pages_expanded(q.from_user.id).get(max(1,min(5,page)),_bb_tool_pages_expanded(q.from_user.id)[1])
        await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard(rows)); return True
    if len(p)==3 and p[0]=='toolhint' and p[1].isdigit() and int(p[1])==q.from_user.id:
        hints={
          'country':'بنویس: کشور ژاپن', 'weather':'بنویس: آب و هوای تهران',
          'currency':'بنویس: ارز USD یا قیمت ارزها', 'location':'بنویس: برج میلاد تهران یا شهربازی کجاست؟',
          'football':'بنویس: فوتبال لیگ برتر', 'sports':'مثال: بسکتبال NBA یا والیبال لیگ ملت‌ها',
          'quran':'بنویس: صفحه قرآن 1', 'dua':'بنویس: دعا', 'fortune':'بنویس: فال یا فال قهوه',
          'secret':'در PV ربات: /secret 123456789 متن پیام', 'bio':'بنویس: بیو'
        }
        await q.answer(hints.get(p[2],'دستور این ابزار در راهنما آمده است.'),show_alert=True); return True
    if data.startswith('sportclose:'):
        await q.message.delete(); return True
    if data.startswith('anread:'):
        return await _bb_anon_callback(q,context)
    return False

