OWNER_PENDING_TOOL_KEY=globals().get('OWNER_PENDING_TOOL_KEY',{})
async def _bb_tools_api_callback(q,context):
    data=q.data or ''
    if data=='pro:tools_api': return await _bb_tools_api_panel(q,context)
    if data.startswith('protoolkey:'):
        if not await _bb_is_bot_admin(q.from_user.id): await q.answer('⛔ دسترسی ندارید.',show_alert=True); return True
        key=data.split(':',1)[1]
        OWNER_PENDING_TOOL_KEY[q.from_user.id]=key
        await q.answer('کلید را در PV بفرست.',show_alert=True)
        await q.message.reply_text(f'🔐 کلید {_bb_h(key)} را در پیام بعدی بفرست.',parse_mode='HTML')
        return True
    return False

# Extend the owner PRO panel's text input with tool API keys.
_OLD_BB_PRO_TEXT_TOOLS=globals().get('_bb_pro_text_router')
async def _bb_pro_text_router_tools(update,context):
    msg=update.effective_message; uid=update.effective_user.id if update.effective_user else 0
    if msg and msg.text and await _bb_is_bot_admin(uid):
        pending=OWNER_PENDING_TOOL_KEY.get(uid)
        if pending and update.effective_chat and update.effective_chat.type=='private':
            val=msg.text.strip()
            if len(val)<8:
                await msg.reply_text('❌ کلید کوتاه است.'); return True
            await _bb_pro_set(pending,val); OWNER_PENDING_TOOL_KEY.pop(uid,None)
            await msg.reply_text(f'✅ {pending} ذخیره شد.')
            return True
    return await _OLD_BB_PRO_TEXT_TOOLS(update,context) if _OLD_BB_PRO_TEXT_TOOLS else False
_bb_pro_text_router=_bb_pro_text_router_tools

