_BB_PROFILE_BG_CACHE = None
_BB_PROFILE_BG_TS = 0.0
_BB_PROFILE_BG_LOCK = asyncio.Lock()
_BB_PROFILE_FONT_REG = None
_BB_PROFILE_FONT_BOLD = None
_BB_WELCOME_EMOJIS = ['🐾','🦴','🐶','🌟','✨','💛','🔥','🎉','😎','🌸']
_BB_DAY_NAMES = {
    0:'دوشنبه',1:'سه‌شنبه',2:'چهارشنبه',3:'پنج‌شنبه',4:'جمعه',5:'شنبه',6:'یکشنبه'
}

def _bb_profile_shape(text):
    text = str(text or '')
    try:
        import arabic_reshaper
        from bidi.algorithm import get_display
        return get_display(arabic_reshaper.reshape(text))
    except Exception:
        return text

def _bb_profile_font(size, bold=False):
    global _BB_PROFILE_FONT_REG, _BB_PROFILE_FONT_BOLD
    try:
        from PIL import ImageFont
        candidates_bold = [
            '/usr/share/fonts/truetype/noto/NotoSansArabic-Bold.ttf',
            '/usr/share/fonts/truetype/noto/NotoSansArabic-ExtraBold.ttf',
            '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'
        ]
        candidates_reg = [
            '/usr/share/fonts/truetype/noto/NotoSansArabic-Regular.ttf',
            '/usr/share/fonts/truetype/noto/NotoSansArabicUI-Regular.ttf',
            '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'
        ]
        cache = _BB_PROFILE_FONT_BOLD if bold else _BB_PROFILE_FONT_REG
        if cache and cache[0] == size:
            return cache[1]
        for fp in (candidates_bold if bold else candidates_reg):
            if os.path.exists(fp):
                f = ImageFont.truetype(fp, size=size)
                if bold: _BB_PROFILE_FONT_BOLD=(size,f)
                else: _BB_PROFILE_FONT_REG=(size,f)
                return f
        return ImageFont.load_default()
    except Exception:
        return None

async def _bb_telegram_file_bytes(bot, file_id):
    if not file_id:
        return None
    try:
        f = await bot.get_file(file_id)
        data = await f.download_as_bytearray()
        return bytes(data)
    except Exception as e:
        log.warning('profile image download failed: %s', e)
        return None

async def _bb_get_bot_avatar_bytes(bot):
    global _BB_PROFILE_BG_CACHE, _BB_PROFILE_BG_TS
    if _BB_PROFILE_BG_CACHE and time.time() - _BB_PROFILE_BG_TS < 900:
        return _BB_PROFILE_BG_CACHE
    async with _BB_PROFILE_BG_LOCK:
        if _BB_PROFILE_BG_CACHE and time.time() - _BB_PROFILE_BG_TS < 900:
            return _BB_PROFILE_BG_CACHE
        try:
            me = await bot.get_me()
            photos = await bot.get_user_profile_photos(me.id, limit=1)
            if photos.total_count and photos.photos:
                b = await _bb_telegram_file_bytes(bot, photos.photos[0][-1].file_id)
                if b:
                    _BB_PROFILE_BG_CACHE=b; _BB_PROFILE_BG_TS=time.time()
                    return b
        except Exception as e:
            log.warning('bot avatar fetch failed: %s', e)
    return None

async def _bb_get_user_avatar_bytes(bot, uid):
    try:
        photos = await bot.get_user_profile_photos(uid, limit=1)
        if photos.total_count and photos.photos:
            return await _bb_telegram_file_bytes(bot, photos.photos[0][-1].file_id)
    except Exception as e:
        log.warning('user avatar fetch failed: %s', e)
    return None

async def _bb_profile_score(uid):
    total = 0
    try:
        r = await DBX.one('SELECT COALESCE(SUM(points),0) AS p FROM safe_game_stats WHERE user_id=?',(uid,))
        total = int(r['p'] or 0) if r else 0
    except Exception:
        pass
    if total == 0:
        try:
            r = await DBX.one('SELECT COALESCE(SUM(points),0) AS p FROM game_scores WHERE user_id=?',(uid,))
            total = int(r['p'] or 0) if r else 0
        except Exception:
            pass
    return total

async def _bb_profile_group_rank(chat_id, uid):
    # رتبه گروه بر اساس فعالیت ثبت‌شده همان گروه؛ کاربر خودش همیشه در محاسبه لحاظ می‌شود.
    try:
        rows = await DBX.execute(
            'SELECT user_id, COALESCE(messages,0) AS activity FROM chat_member_stats '
            'WHERE chat_id=? AND is_bot=0 ORDER BY activity DESC, user_id ASC',
            (chat_id,), fetch=True)
        if rows:
            for i,r in enumerate(rows,1):
                if int(r['user_id']) == int(uid):
                    return i, len(rows)
        r = await DBX.one('SELECT COALESCE(messages,0) AS activity FROM chat_member_stats WHERE chat_id=? AND user_id=?',(chat_id,uid))
        if r:
            higher = await DBX.one('SELECT COUNT(*) AS c FROM chat_member_stats WHERE chat_id=? AND is_bot=0 AND messages>?',(chat_id,int(r['activity'] or 0)))
            return int((higher['c'] if higher else 0) or 0)+1, int((higher['c'] if higher else 0) or 0)+1
    except Exception:
        pass
    return 1, 1

async def _bb_profile_mafia_level(uid):
    try:
        r = await DBX.one("SELECT COALESCE(wins,0) wins, COALESCE(plays,0) plays FROM game_scores WHERE user_id=? AND game='mafia'",(uid,))
        if r:
            return max(1, 1 + int(r['wins'] or 0)//5)
    except Exception:
        pass
    return 1

async def _bb_profile_title(chat_id, uid, bot):
    try:
        member = await bot.get_chat_member(chat_id, uid)
        custom = getattr(member, 'custom_title', None)
        if custom:
            return safe_text(custom, 80)
    except Exception:
        pass
    try:
        row = await DBX.one('SELECT nickname FROM member_labels WHERE chat_id=? AND user_id=?',(chat_id,uid))
        if row and row['nickname']:
            return safe_text(row['nickname'],80)
    except Exception:
        pass
    try:
        row = await DBX.one('SELECT nickname FROM user_profiles WHERE user_id=?',(uid,))
        if row and row['nickname']:
            return safe_text(row['nickname'],80)
    except Exception:
        pass
    return 'لقب ندارد'


def _bb_profile_font(size, bold=False):
    global _BB_PROFILE_FONT_REG, _BB_PROFILE_FONT_BOLD
    try:
        from PIL import ImageFont
        cache = _BB_PROFILE_FONT_BOLD if bold else _BB_PROFILE_FONT_REG
        if cache and cache[0] == size:
            return cache[1]
        roots = [
            "/usr/share/fonts", "/system/fonts",
            "/data/user/0/ru.iiec.pydroid3/files",
            "/data/data/ru.iiec.pydroid3/files",
        ]
        names = (
            ("NotoSansArabic-Bold.ttf", "NotoKufiArabic-Bold.ttf", "DejaVuSans-Bold.ttf")
            if bold else
            ("NotoSansArabic-Regular.ttf", "NotoSansArabicUI-Regular.ttf",
             "NotoKufiArabic-Regular.ttf", "DejaVuSans.ttf")
        )
        candidates = []
        for root in roots:
            for name in names:
                candidates.append(os.path.join(root, name))
        for root in ("/usr/share/fonts", "/system/fonts"):
            if os.path.isdir(root):
                for name in names:
                    candidates.extend(glob.glob(os.path.join(root, "**", name), recursive=True))
        for fp in candidates:
            if os.path.exists(fp):
                f = ImageFont.truetype(fp, size=size)
                if bold: _BB_PROFILE_FONT_BOLD = (size, f)
                else: _BB_PROFILE_FONT_REG = (size, f)
                return f
        return ImageFont.load_default()
    except Exception:
        return None

_BB_AR_FORMS = {
    'ا':('ﺍ','ﺎ',None,None),'آ':('ﺁ','ﺂ',None,None),'أ':('ﺃ','ﺄ',None,None),'إ':('ﺇ','ﺈ',None,None),
    'ب':('ﺏ','ﺐ','ﺑ','ﺒ'),'پ':('ﭖ','ﭗ','ﭘ','ﭙ'),'ت':('ﺕ','ﺖ','ﺗ','ﺘ'),'ث':('ﺙ','ﺚ','ﺛ','ﺜ'),
    'ج':('ﺝ','ﺞ','ﺟ','ﺠ'),'چ':('ﭺ','ﭻ','ﭼ','ﭽ'),'ح':('ﺡ','ﺢ','ﺣ','ﺤ'),'خ':('ﺥ','ﺦ','ﺧ','ﺨ'),
    'د':('ﺩ','ﺪ',None,None),'ذ':('ﺫ','ﺬ',None,None),'ر':('ﺭ','ﺮ',None,None),'ز':('ﺯ','ﺰ',None,None),
    'ژ':('ﮊ','ﮋ',None,None),'س':('ﺱ','ﺲ','ﺳ','ﺴ'),'ش':('ﺵ','ﺶ','ﺷ','ﺸ'),'ص':('ﺹ','ﺺ','ﺻ','ﺼ'),
    'ض':('ﺽ','ﺾ','ﺿ','ﻀ'),'ط':('ﻁ','ﻂ','ﻃ','ﻄ'),'ظ':('ﻅ','ﻆ','ﻇ','ﻈ'),'ع':('ﻉ','ﻊ','ﻋ','ﻌ'),
    'غ':('ﻍ','ﻎ','ﻏ','ﻐ'),'ف':('ﻑ','ﻒ','ﻓ','ﻔ'),'ق':('ﻕ','ﻖ','ﻗ','ﻘ'),'ک':('ﮎ','ﮏ','ﮐ','ﮑ'),
    'ك':('ﻙ','ﻚ','ﻛ','ﻜ'),'گ':('ﮒ','ﮓ','ﮔ','ﮕ'),'ل':('ﻝ','ﻞ','ﻟ','ﻠ'),'م':('ﻡ','ﻢ','ﻣ','ﻤ'),
    'ن':('ﻥ','ﻦ','ﻧ','ﻨ'),'و':('ﻭ','ﻮ',None,None),'ه':('ﻩ','ﻪ','ﻫ','ﻬ'),'ی':('ﯼ','ﯽ','ﯾ','ﯿ'),
    'ي':('ﻱ','ﻲ','ﻳ','ﻴ')
}
_BB_AR_NONJOIN = set('اآأإدذرزژوو')

def _bb_profile_shape(text):
    s = str(text or '')
    try:
        import arabic_reshaper
        from bidi.algorithm import get_display
        return get_display(arabic_reshaper.reshape(s))
    except Exception:
        pass
    out=[]; chars=list(s)
    for i,ch in enumerate(chars):
        f=_BB_AR_FORMS.get(ch)
        if not f:
            out.append(ch); continue
        prev=chars[i-1] if i else ''; nxt=chars[i+1] if i+1<len(chars) else ''
        cp=prev in _BB_AR_FORMS and prev not in _BB_AR_NONJOIN
        cn=nxt in _BB_AR_FORMS and ch not in _BB_AR_NONJOIN
        iso,fin,ini,med=f
        out.append(med if cp and cn and med else fin if cp and fin else ini if cn and ini else iso)
    shaped=''.join(out)
    def is_ar(c):
        return '\u0600'<=c<='\u06ff' or '\ufb50'<=c<='\ufdff' or '\ufe70'<=c<='\ufeff'
    parts=[]; buf=''; state=None
    for c in shaped:
        st=is_ar(c)
        if state is None or st==state:
            buf+=c
        else:
            parts.append(buf[::-1] if state else buf); buf=c; state=st
    if buf: parts.append(buf[::-1] if state else buf)
    return ''.join(parts)

def _bb_profile_text(draw, xy, text, font, fill, anchor='la'):
    try:
        draw.text(xy, str(text or ''), font=font, fill=fill, anchor=anchor,
                  direction='rtl', language='fa')
    except Exception:
        draw.text(xy, _bb_profile_shape(text), font=font, fill=fill, anchor=anchor)

async def _bb_make_profile_card(bot, chat_id, user):
    try:
        from PIL import Image, ImageDraw, ImageFilter, ImageOps
        from io import BytesIO
    except Exception as e:
        log.warning('Pillow unavailable for profile card: %s', e)
        return None

    u=await DBX.get_user(user.id)
    if not u:
        await DBX.ensure_user(user)
        u=await DBX.get_user(user.id)
    u=u or {}
    p=await DBX.one('SELECT bio,nickname,joined_at FROM user_profiles WHERE user_id=?',(user.id,)) or {}

    bio=safe_text(p.get('bio',''),180) or 'بیو ثبت نشده'
    username='@'+user.username if getattr(user,'username',None) else f'ID: {user.id}'
    score=await _bb_profile_score(user.id)
    mafia_level=await _bb_profile_mafia_level(user.id)
    rank,total_members=await _bb_profile_group_rank(chat_id,user.id)
    title=await _bb_profile_title(chat_id,user.id,bot)

    xp=max(0,int(u.get('xp',0) or 0))
    level=max(1,int(u.get('level',1) or 1))
    games=max(0,int(u.get('games',0) or 0))
    current_xp=xp%100

    try:
        from zoneinfo import ZoneInfo
        now=datetime.now(ZoneInfo(os.getenv('BB_PROFILE_TIMEZONE','Asia/Tehran')))
    except Exception:
        now=datetime.now()

    # تاریخ ساخت پروفایل از joined_at، سپس created_at؛ اگر موجود نبود، زمان فعلی.
    created_ts=int(p.get('joined_at') or u.get('created_at') or 0)
    try:
        created_at=datetime.fromtimestamp(created_ts,now.tzinfo) if created_ts>0 else now
    except Exception:
        created_at=now
    try:
        jy,jm,jd=_bb_gregorian_to_jalali(created_at.year,created_at.month,created_at.day)
        created_date=f'{jy:04d}/{jm:02d}/{jd:02d}'
    except Exception:
        created_date=created_at.strftime('%Y/%m/%d')
    created_time=created_at.strftime('%H:%M:%S')

    W,H=1400,820
    bg_bytes=await _bb_get_bot_avatar_bytes(bot)
    if bg_bytes:
        try:
            bg=Image.open(BytesIO(bg_bytes)).convert('RGB')
            bg=ImageOps.fit(bg,(W,H),method=Image.Resampling.LANCZOS)
            bg=bg.filter(ImageFilter.GaussianBlur(3))
            bg=Image.alpha_composite(bg.convert('RGBA'),Image.new('RGBA',(W,H),(0,0,0,178)))
        except Exception:
            bg=Image.new('RGBA',(W,H),(10,10,14,255))
    else:
        bg=Image.new('RGBA',(W,H),(10,10,14,255))

    draw=ImageDraw.Draw(bg)
    gold=(235,188,76,255); white=(248,248,248,255); muted=(205,202,195,255)
    panel=(7,7,10,215)
    draw.rounded_rectangle((22,22,W-22,H-22),radius=34,outline=(155,155,155,210),width=3)
    draw.rounded_rectangle((340,300,W-55,520),radius=28,fill=panel,outline=(200,170,105,230),width=2)
    draw.rounded_rectangle((340,570,W-55,755),radius=28,fill=(7,7,10,225),outline=(200,170,105,230),width=2)

    avatar_b=await _bb_get_user_avatar_bytes(bot,user.id)
    ax,ay,asize=65,105,265
    if avatar_b:
        try:
            av=Image.open(BytesIO(avatar_b)).convert('RGB')
            av=ImageOps.fit(av,(asize,asize),method=Image.Resampling.LANCZOS)
            mask=Image.new('L',(asize,asize),0)
            ImageDraw.Draw(mask).ellipse((0,0,asize,asize),fill=255)
            bg.paste(av,(ax,ay),mask)
        except Exception:
            pass
    draw.ellipse((ax-8,ay-8,ax+asize+8,ay+asize+8),outline=gold,width=5)

    f_title=_bb_profile_font(52,True); f_name=_bb_profile_font(34,True)
    f_big=_bb_profile_font(31,True); f=_bb_profile_font(25,False)
    f_b=_bb_profile_font(27,True); f_small=_bb_profile_font(21,False)
    def T(x,y,s,font,fill=white,anchor='la'):
        _bb_profile_text(draw,(x,y),s,font,fill,anchor)

    T(650,95,'پروفایل بیل بیلک',f_title,gold,'ra')
    T(650,168,safe_text(user.first_name,40),f_name,white,'ra')
    T(650,220,username,f,white,'ra')
    T(W-75,92,f'رتبه {rank} از {total_members}',f_b,gold,'ra')
    T(W-75,135,'رتبه در گروه',f_small,muted,'ra')

    status='هاپویی تازه‌کار' if level<=2 else ('هاپویی حرفه‌ای' if level<=5 else ('هاپویی قدیمی' if level<=10 else 'هاپویی افسانه‌ای'))
    T(W-75,205,status,f_b,white,'ra')
    T(W-75,248,f'سطح {level}',f_b,gold,'ra')

    bar_x1,bar_y1,bar_x2,bar_y2=380,342,W-75,390
    draw.rounded_rectangle((bar_x1,bar_y1,bar_x2,bar_y2),radius=24,fill=(38,38,42,255))
    ratio=max(0,min(1,current_xp/100))
    if ratio>0:
        draw.rounded_rectangle((bar_x1,bar_y1,bar_x1+int((bar_x2-bar_x1)*ratio),bar_y2),radius=24,fill=gold)
    T(W-75,398,f'{current_xp} / 100 XP تا سطح بعد',f_small,muted,'ra')

    cells=[(470,'امتیاز',str(score)),(680,'بازی‌ها',str(games)),(890,'سطح مافیا',str(mafia_level)),
           (1100,'سطح',str(level)),(1290,'رتبه',f'{rank}/{total_members}')]
    for x,label,val in cells:
        T(x,432,label,f_small,gold,'ma'); T(x,476,val,f_big,white,'ma')

    T(560,600,'لقب',f_small,gold,'ra'); T(560,646,safe_text(title,32),f_b,white,'ra')
    T(840,600,'ملیت',f_small,gold,'ra'); T(840,646,'ایران',f_b,white,'ra')
    T(1110,600,'تاریخ ساخت پروفایل',f_small,gold,'ra'); T(1110,646,created_date,f_b,white,'ra')
    T(1330,600,'ساعت ساخت',f_small,gold,'ra'); T(1330,646,created_time,f_b,white,'ra')
    T(650,705,'بیو',f_small,gold,'ra'); T(650,739,bio[:70],f_small,white,'ra')

    bot_tag='@'+BB_BOT_USERNAME.lstrip('@')
    T(380,790,f'{bot_tag}  •  Bilbilak',f_small,gold,'la')

    out=BytesIO(); out.name='bilbilak_profile.jpg'
    bg.convert('RGB').save(out,format='JPEG',quality=92,optimize=True)
    out.seek(0)
    return out


async def _bb_profile_card_command(update, context):
    msg=update.effective_message; chat=update.effective_chat; user=update.effective_user
    if not msg or not chat or not user:
        return True
    loading=None
    try:
        loading=await msg.reply_text('⏳ چند لحظه صبر کن...\nدرحال ساخت پروفایل...')
        cid=user.id if chat.type=='private' else chat.id
        card=await _bb_make_profile_card(context.bot,cid,user)

        if loading:
            try:
                await loading.delete()
            except Exception:
                pass

        if card:
            sent=False
            last_exc=None
            for _attempt in range(2):
                try:
                    try:
                        card.seek(0)
                    except Exception:
                        pass
                    await msg.reply_photo(
                        photo=card, caption='🐾 پروفایل بیل بیلک',
                        read_timeout=90, write_timeout=90,
                        connect_timeout=30, pool_timeout=30
                    )
                    sent=True
                    break
                except Exception as exc:
                    last_exc=exc
                    if _attempt == 0:
                        await asyncio.sleep(1)
            if not sent:
                # The image was generated successfully; if Telegram upload is
                # temporarily unavailable, never leave the user without a result.
                log.warning('profile card upload failed after retry: %s', last_exc)
                await msg.reply_text(
                    '🪪 <b>کارت پروفایل آماده شد</b>\n\n'
                    f'👤 {mention_html(user)}\n'
                    '⚠️ ارسال تصویر به تلگرام در این لحظه ناموفق بود؛ دوباره «پروفایل» را بزن.',
                    parse_mode='HTML'
                )
        else:
            await msg.reply_text('❌ ساخت کارت پروفایل انجام نشد.')
    except Exception as e:
        log.exception('profile card failed: %s',e)
        if loading:
            try:
                await loading.delete()
            except Exception:
                pass
        try:
            await msg.reply_text('❌ ساخت کارت پروفایل انجام نشد.')
        except Exception:
            pass
    return True

# جایگزینی «پروفایل» قدیمی؛ «پروفایل من» هم کارت جدید را باز می‌کند.
_BB_OLD_MESSAGE_ROUTER_PROFILE_CARD = message_router
async def message_router(update, context):
    try:
        msg=update.effective_message
        t=normalize(getattr(msg,'text','') or '') if msg else ''
        if t in {'پروفایل','پروفایل من','بیو من','کارت پروفایل'}:
            return await _bb_profile_card_command(update,context)
    except Exception:
        log.exception('profile command pre-router failed')
    return await _BB_OLD_MESSAGE_ROUTER_PROFILE_CARD(update,context)

# -------------------------- Smart welcome / goodbye --------------------------
def _bb_render_welcome_vars(template,user,chat,mode='welcome'):
    """Render the full standardized design-variable contract for group messages."""
    try:
        from zoneinfo import ZoneInfo
        now=datetime.now(ZoneInfo(os.getenv('BB_PROFILE_TIMEZONE','Asia/Tehran')))
    except Exception:
        now=datetime.now()
    username=('@'+user.username) if getattr(user,'username',None) else ''
    group_name=safe_text(getattr(chat,'title','') or 'گروه',120)
    first_name=safe_text(getattr(user,'first_name','') or getattr(user,'full_name','کاربر') or 'کاربر',120)
    mention=mention_html(user)
    # Standard variables available to group admins in welcome/goodbye/force-join.
    repl={
        '{data}': str(getattr(user,'full_name','') or first_name),
        '{section}': mode,
        '{name}': mention,
        '{first_name}': first_name,
        '{mention}': mention,
        '{id}':str(user.id), '{user_id}':str(user.id),
        '{username}':username or 'بدون یوزرنیم',
        '{group}':group_name, '{group_name}':group_name,
        '{group_id}':str(getattr(chat,'id','')), '{chat_id}':str(getattr(chat,'id','')),
        '{date}':now.strftime('%Y/%m/%d'), '{time}':now.strftime('%H:%M:%S'),
        '{datetime}':now.strftime('%Y/%m/%d %H:%M:%S'),
        '{day}':_BB_DAY_NAMES.get(now.weekday(),now.strftime('%A')),
        '{jalali_date}':now.strftime('%Y/%m/%d'),
        '{gregorian_date}':now.strftime('%Y/%m/%d'),
        '{hijri_date}':'',
        '{emoji}':random.choice(_BB_WELCOME_EMOJIS),
        '{bot}':'@Bil_bilakapibot', '{bot_username}':'@Bil_bilakapibot',
        '{admin_name}': '', '{admin_username}':'', '{admin_title}':'',
        '{target_name}':first_name, '{target_mention}':mention, '{target_id}':str(user.id),
    }
    out=template or ''
    for k,v in repl.items(): out=out.replace(k,str(v))
    return out

async def _bb_send_member_media(chat,bot,kind,file_id,text):
    if not file_id:
        return await chat.send_message(text,parse_mode='HTML')
    if kind=='photo': return await chat.send_photo(file_id,caption=text or '',parse_mode='HTML')
    if kind=='video': return await chat.send_video(file_id,caption=text or '',parse_mode='HTML')
    if kind=='animation': return await chat.send_animation(file_id,caption=text or '',parse_mode='HTML')
    return await chat.send_message(text,parse_mode='HTML')

async def new_member(update, context):
    chat=update.effective_chat; cm=getattr(update,'chat_member',None)
    if not chat or not cm: return
    old_status=cm.old_chat_member.status; new_status=cm.new_chat_member.status; user=cm.new_chat_member.user
    if user.is_bot: return
    await DBX.ensure_chat(chat); await DBX.ensure_user(user)
    c=await DBX.get_chat(chat.id)
    joined=new_status in {ChatMemberStatus.MEMBER,ChatMemberStatus.RESTRICTED,ChatMemberStatus.ADMINISTRATOR,ChatMemberStatus.OWNER} and old_status in {ChatMemberStatus.LEFT,ChatMemberStatus.BANNED}
    left=new_status in {ChatMemberStatus.LEFT,ChatMemberStatus.BANNED} and old_status in {ChatMemberStatus.MEMBER,ChatMemberStatus.RESTRICTED,ChatMemberStatus.ADMINISTRATOR}
    if joined and c and c['welcome_enabled']:
        default=(
            '{name} خوش اومدی به {group} {emoji}\n'
            'بمونی برامون گل 🌹\n'
            'ــــــــــــــــــــــــــــ\n'
            '🐾 𝓑𝓲𝓵𝓫𝓲𝓵𝓪𝓴 | @Bil_bilakapibot\n'
            'ــــــــــــــــــــــــــــ\n'
            'تاریخ: {date}\n'
            'ساعت: {time}\n'
            'روز: {day}'
        )
        text=_bb_render_welcome_vars(c['welcome_text'] or default,user,chat,'welcome')
        try: await _bb_send_member_media(chat,context.bot,(c['welcome_media_type'] or ''),(c['welcome_media_id'] or ''),text)
        except TelegramError: pass
    if left and c and c['goodbye_enabled']:
        default='{name} از {group} خداحافظ! 👋\nتاریخ: {date}\nساعت: {time}\nروز: {day}'
        text=_bb_render_welcome_vars(c['goodbye_text'] or default,user,chat,'goodbye')
        try: await _bb_send_member_media(chat,context.bot,(c['goodbye_media_type'] or ''),(c['goodbye_media_id'] or ''),text)
        except TelegramError: pass

