# =============================================================================
# FINAL PANEL CLOSE BUTTON
# =============================================================================
# هر پنل اینلاین یک دکمه بستن دارد. خود callback در آخرین build_application
# با اولویت بالا ثبت می‌شود تا قبل از callbackهای عمومی پنل را ببندد.

_BB_ORIGINAL_KEYBOARD_FOR_PANEL_CLOSE = keyboard

def keyboard(rows):
    """ساخت کیبورد با دکمه عمومی «بستن پنل» برای پنل‌های اینلاین."""
    try:
        copied = [list(r) for r in (rows or [])]
        already = any(
            str(getattr(b, 'callback_data', '') or '') == 'panelclose'
            or 'بستن پنل' in str(getattr(b, 'text', '') or '')
            for r in copied for b in r
        )
        if not already:
            copied.append([btn('❌ بستن پنل', 'panelclose')])
        return InlineKeyboardMarkup(copied)
    except Exception:
        return _BB_ORIGINAL_KEYBOARD_FOR_PANEL_CLOSE(rows)

async def _bb_panel_close_callback(update, context):
    q = getattr(update, 'callback_query', None)
    if not q:
        return
    try:
        await q.answer('پنل بسته شد.', show_alert=False)
    except Exception:
        pass
    user = getattr(q, 'from_user', None)
    mention = mention_html(user) if user else 'کاربر'
    text = f'• پنل توسط {mention} بسته شد !'
    msg = getattr(q, 'message', None)
    if not msg:
        return
    # اول پیام پنل (حتی اگر عکس/گیف داشته باشد) حذف می‌شود تا پنل قدیمی نماند.
    try:
        await msg.delete()
        await context.bot.send_message(chat_id=msg.chat_id, text=text, parse_mode='HTML')
        return
    except Exception:
        pass
    # اگر حذف مجاز نبود، تلاش برای جایگزینی متن/کپشن.
    try:
        await q.edit_message_text(text, parse_mode='HTML')
        return
    except Exception:
        pass
    try:
        await q.edit_message_caption(caption=text, parse_mode='HTML')
    except Exception:
        pass

_BB_ORIGINAL_BUILD_APPLICATION_FOR_PANEL_CLOSE = build_application

def build_application(token):
    app = _BB_ORIGINAL_BUILD_APPLICATION_FOR_PANEL_CLOSE(token)
    try:
        # گروه منفی‌تر = اولویت بالاتر در PTB
        app.add_handler(CallbackQueryHandler(_bb_panel_close_callback, pattern=r'^panelclose$'), group=-20000)
    except Exception:
        log.exception('panel close handler registration failed')
    return app



