_OLD_BB_MESSAGE_ROUTER_ANALYTICS=globals().get('message_router')
async def message_router(update,context):
    try:
        msg=update.effective_message
        raw=(getattr(msg,'text','') or '').strip()
        n=normalize(raw)
        # Instagram forms: آنالیز @page | آنالیز پیج @page | آنالیز(@page)
        m=re.fullmatch(r'آنالیز\s*(?:پیج\s*)?[(@]?([A-Za-z0-9._]{1,30})\)?', n, re.I)
        if m:
            return await _bb_instagram_analysis_command(update,context,m.group(1))
        m=re.fullmatch(r'آنالیز\s+کانال\s*[@]?([A-Za-z0-9_]{3,64})', n, re.I)
        if m:
            return await _bb_telegram_analysis_command(update,context,m.group(1))
        if await _bb_analytics_text_router(update,context): return True
    except Exception as exc:
        log.exception('analytics message router failed: %s',exc)
    return await _OLD_BB_MESSAGE_ROUTER_ANALYTICS(update,context) if _OLD_BB_MESSAGE_ROUTER_ANALYTICS else False

