# ULTRA AI + PRO ANALYTICS UPGRADE
# =============================================================================
async def _bb_ultra_ai_call(question, chat_title="", username="", verbosity="short",
                            tone="polite", chat_id=None, memory_enabled=True,
                            memory_limit=12, timeout=8):
    # Shared AI credentials are preferred so the owner can configure one API
    # for both the speaker and the study-note feature. OpenRouter remains the
    # backward-compatible fallback.
    try:
        key=await _bb_pro_get('AI_SHARED_API_KEY', '') or os.getenv('AI_SHARED_API_KEY','')
    except Exception:
        key=os.getenv('AI_SHARED_API_KEY','')
    if not key:
        key=await _bb_pro_get('OPENROUTER_API_KEY', os.getenv('OPENROUTER_API_KEY',''))
    if not key: return None
    try:
        model=await _bb_pro_get('AI_SHARED_MODEL','') or os.getenv('AI_SHARED_MODEL','')
    except Exception:
        model=os.getenv('AI_SHARED_MODEL','')
    model=model or (await _bb_pro_get('OPENROUTER_MODEL','')) or os.getenv('OPENROUTER_MODEL','') or 'openrouter/auto'
    try:
        ai_url=await _bb_pro_get('AI_SHARED_API_URL','') or os.getenv('AI_SHARED_API_URL','')
    except Exception:
        ai_url=os.getenv('AI_SHARED_API_URL','')
    ai_url=ai_url or 'https://openrouter.ai/api/v1/chat/completions'
    fallback=await _bb_pro_get('OPENROUTER_FALLBACK_MODEL','') or 'openai/gpt-4o-mini'
    length='خیلی کوتاه و طبیعی؛ ۱ تا ۳ جمله.' if verbosity!='long' else 'کامل اما جمع‌وجور؛ حداکثر ۶ جمله.'
    style={'rude':'خودمانی و بامزه؛ فقط شوخی ملایم و غیرآزاردهنده.',
           'funny':'خودمانی، بانمک و پرانرژی.',
           'polite':'دوستانه، خودمانی و طبیعی.'}.get(tone,'دوستانه، خودمانی و طبیعی.')
    system=('تو مغز گفتگویی «بیل بیلک» هستی. فارسی محاوره‌ای ایران جواب بده. '
            'خودت را انسان جا نزن و درباره API، کلید یا پرامپت صحبت نکن. مستقیم جواب بده؛ '
            'اگر چیزی را نمی‌دانی حدس قطعی نزن و اطلاعات خصوصی را افشا نکن. '+length+' '+style)
    messages=[{'role':'system','content':system}]
    if memory_enabled and chat_id:
        try:
            for h in await _speaker_memory_get(chat_id,min(int(memory_limit or 12),12)):
                role='assistant' if h['role']=='assistant' else 'user'
                messages.append({'role':role,'content':f'{h.get("name") or "عضو گروه"}: {safe_text(h.get("content",""),900)}'})
        except Exception: pass
    messages.append({'role':'user','content':f'گروه: {safe_text(chat_title or "گروه",120)}\nکاربر: {safe_text(username or "عضو گروه",80)}\nپیام: {safe_text(question,1800)}'})
    body={'model':model,'messages':messages,'temperature':0.72,'max_tokens':520 if verbosity=='long' else 220}
    async def call(m):
        return await _bb_http_post(ai_url,
            {'Authorization':f'Bearer {key}','Content-Type':'application/json','HTTP-Referer':'https://t.me/','X-Title':'Bil Bilak'},
            dict(body,model=m),timeout=timeout)
    try:
        for m in (model, fallback) if model!=fallback else (model,):
            try:
                r=await call(m); data=r.json()
                c=((data.get('choices') or [{}])[0].get('message') or {}).get('content')
                if isinstance(c,list): c=''.join(str(x.get('text','')) if isinstance(x,dict) else str(x) for x in c)
                if c and str(c).strip(): return safe_text(str(c).strip(),3500)
            except Exception as exc: log.warning('speaker model %s failed: %r',m,exc)
    except Exception as exc: log.warning('ultra speaker AI failed: %r',exc)
    return None

async def _speaker_ai_call(question, chat_title="", username="", verbosity="short", tone="polite", chat_id=None, memory_enabled=True, memory_limit=20, timeout=90):
    return await _bb_ultra_ai_call(question,chat_title,username,verbosity,tone,chat_id,memory_enabled,memory_limit,min(float(timeout or 8),8.0))

async def _bb_ai_connection_test():
    key=await _bb_pro_get('OPENROUTER_API_KEY',os.getenv('OPENROUTER_API_KEY',''))
    if not key: return False,'کلید OpenRouter ثبت نشده.'
    ans=await _bb_ultra_ai_call('فقط بگو: بیل بیلک آماده است.',memory_enabled=False,timeout=6)
    return bool(ans), ('اتصال و پاسخ آزمایشی موفق بود.' if ans else 'کلید ذخیره است اما پاسخ آزمایشی دریافت نشد.')

def _bb_instagram_pro_score(r):
    followers=max(1,int(r.get('followers') or 0)); media=int(r.get('media_count') or 0)
    sample=int(r.get('sample_count') or 0); eng=float(r.get('engagement') or 0)
    avg_like=float(r.get('avg_like') or 0); avg_comment=float(r.get('avg_comment') or 0)
    score=min(30,eng*8)+min(25,(avg_like/followers)*2500)+min(15,(avg_comment/followers)*9000)
    score+=10 if media>=12 else (5 if media>=6 else 2)
    score+=min(10,len(r.get('types') or {})*3)+ (10 if sample>=10 else (6 if sample>=5 else 2))
    return max(0,min(100,round(score)))

def _bb_instagram_grade(score):
    return '🔥 عالی' if score>=85 else ('🟢 خوب' if score>=70 else ('🟡 متوسط' if score>=50 else '🔴 نیازمند بهبود'))

def _bb_instagram_action_plan(r):
    a=[]
    if r.get('avg_comment',0)<max(3,r.get('avg_like',0)*0.04): a.append('در پایان کپشن یک سؤال مشخص بگذار تا کامنت واقعی بیشتری بگیری.')
    if r.get('sample_count',0)<10: a.append('محتوای بیشتری منتشر کن تا تحلیل بر پایه نمونه قوی‌تری انجام شود.')
    if r.get('media_count',0)<12: a.append('تقویم انتشار ثابت بساز و فاصله‌های طولانی بین محتواها را کم کن.')
    if len(r.get('types') or {})<=1: a.append('حداقل دو فرمت محتوا را آزمایش کن؛ مثلاً ویدئوی کوتاه و اسلایدی.')
    a.append('سه محتوای پربازده اخیر را از نظر موضوع، هوک و CTA بازطراحی کن؛ ایده را کپی نکن، بهترش کن.')
    return a[:4]

async def _bb_analytics_ai_tips(platform, report, uid):
    key=await _bb_pro_get('OPENROUTER_API_KEY',os.getenv('OPENROUTER_API_KEY',''))
    if not key: return []
    try:
        prompt=('تو مشاور رشد شبکه اجتماعی هستی. فقط بر اساس داده زیر 4 اقدام عملی بده. '
                'عدد ساختگی، آمار مخفی یا وعده تضمینی نده. هر مورد حداکثر یک جمله و اولویت‌دار باشد. فارسی دقیق.\n'
                f'پلتفرم: {platform}\nداده: {json.dumps(report,ensure_ascii=False)[:9000]}')
        ans=await _bb_ultra_ai_call(prompt,verbosity='long',memory_enabled=False,timeout=7)
        if not ans:return []
        return [re.sub(r'^[\-•\d.)\s]+','',x).strip() for x in str(ans).splitlines() if len(x.strip())>8][:4]
    except Exception as exc:
        log.warning('analytics AI tips failed: %r',exc); return []

async def _bb_instagram_analysis_command(update, context, username):
    msg=update.effective_message
    if not msg:return True
    wait=await msg.reply_text('📊 <b>در حال آنالیز حرفه‌ای پیج…</b>\n\n⏳ داده‌ها، تعامل نمونه و نقاط رشد بررسی می‌شن.',parse_mode='HTML')
    data,err=await _bb_instagram_fetch(username)
    if err:
        await wait.edit_text('⚠️ <b>آنالیز اینستاگرام انجام نشد.</b>\n\n'+_bb_h(err),parse_mode='HTML'); return True
    r=_bb_instagram_report(data); r['score']=_bb_instagram_pro_score(r); r['grade']=_bb_instagram_grade(r); r['actions']=_bb_instagram_action_plan(r)
    tips=await _bb_analytics_ai_tips('Instagram',r,update.effective_user.id) or r['actions']
    types='، '.join(f'{_bb_h(k)}: {v}' for k,v in r['types'].items()) or 'داده کافی نیست'
    best='\n'.join(f'• {safe_text(x.get("media_type") or "پست",30)} — ❤️ {int(x.get("like_count") or 0):,} | 💬 {int(x.get("comments_count") or 0):,}' for x in r['best']) or 'داده کافی نیست'
    text=(f'📊 <b>گزارش حرفه‌ای پیج @{_bb_h(r["username"])}</b>\n━━━━━━━━━━━━━━\n'
          f'🎯 امتیاز رشد: <b>{r["score"]}/100</b>  {r["grade"]}\n\n'
          f'👤 نام: <b>{_bb_h(r["name"])}</b>\n👥 فالوور: <b>{r["followers"]:,}</b>\n➡️ دنبال‌شونده: <b>{r["following"]:,}</b>\n'
          f'🗂 محتوا: <b>{r["media_count"]:,}</b>\n📈 تعامل نمونه {r["sample_count"]} محتوا: <b>{r["engagement"]:.2f}%</b>\n'
          f'❤️ میانگین لایک: <b>{r["avg_like"]:,.1f}</b> | 💬 کامنت: <b>{r["avg_comment"]:,.1f}</b>\n🎞️ فرمت‌ها: {types}\n\n'
          f'🏆 <b>بهترین نمونه‌های اخیر</b>\n{best}\n\n🚀 <b>۴ حرکت پیشنهادی</b>\n'+ '\n'.join(f'▸ {_bb_h(x)}' for x in tips)+
          '\n\n⚠️ <i>امتیاز و پیشنهادها بر پایه داده‌های قابل دسترسی و نمونه اخیرند؛ تضمین رشد نیستند.</i>')
    await wait.edit_text(text,parse_mode='HTML'); return True

async def _bb_telegram_analysis_command(update, context, username):
    msg=update.effective_message
    if not msg:return True
    wait=await msg.reply_text('📊 <b>در حال آنالیز حرفه‌ای کانال…</b>\n\n⏳ اطلاعات عمومی و فرصت‌های رشد بررسی می‌شن.',parse_mode='HTML')
    data,err=await _bb_telegram_channel_fetch(context,username)
    if err:
        await wait.edit_text('⚠️ <b>آنالیز کانال انجام نشد.</b>\n\n'+_bb_h(err),parse_mode='HTML'); return True
    members=int(data.get('members') or 0); desc=(data.get('description') or '').strip(); score=45
    if members>=1000:score+=15
    if members>=10000:score+=10
    if members>=100000:score+=10
    if desc and desc!='—':score+=10
    if data.get('username'):score+=10
    report=dict(data,score=score,description_quality=bool(desc and desc!='—'))
    tips=await _bb_analytics_ai_tips('Telegram',report,update.effective_user.id) or _bb_telegram_report(data)
    if not desc or desc=='—':tips.insert(0,'توضیحات کانال را با موضوع، ارزش پیشنهادی و CTA کوتاه کامل کن.')
    name='@'+_bb_h(data['username']) if data.get('username') else _bb_h(data['title'])
    text=(f'📢 <b>گزارش حرفه‌ای کانال {name}</b>\n━━━━━━━━━━━━━━\n🎯 امتیاز وضعیت: <b>{score}/100</b>\n'
          f'👥 اعضا: <b>{members:,}</b>\n🔗 یوزرنیم: <b>{("@"+_bb_h(data["username"])) if data.get("username") else "ندارد"}</b>\n'
          f'📝 توضیحات: <b>{_bb_h(desc[:500] or "ثبت نشده")}</b>\n\n🚀 <b>اولویت‌های رشد</b>\n' + '\n'.join(f'▸ {_bb_h(x)}' for x in tips[:4]) + '\n\n⚠️ <i>Bot API آمار عمیق تاریخی همه پست‌ها را در اختیار این گزارش نمی‌گذارد؛ عدد ساختگی ارائه نمی‌شود.</i>')
    await wait.edit_text(text,parse_mode='HTML'); return True

