# =============================================================================
# BILBILAK SMART GROUP MANAGER — AI GROUP INTELLIGENCE
# =============================================================================
# این ماژول فقط تحلیل و پیشنهاد مدیریتی می‌دهد؛ هیچ اقدام خطرناک/خودکاری انجام نمی‌دهد.

async def _bb_smart_group_report(chat_id):
    try:
        members=await DBX.one('SELECT COUNT(*) c FROM chat_member_stats WHERE chat_id=? AND is_bot=0',(chat_id,))
        total=await DBX.one('SELECT COALESCE(SUM(messages),0) n FROM chat_member_stats WHERE chat_id=? AND is_bot=0',(chat_id,))
        active=await DBX.one('SELECT COUNT(*) c FROM chat_member_stats WHERE chat_id=? AND is_bot=0 AND messages>0',(chat_id,))
        top=await DBX.execute('SELECT user_id,first_name,username,messages FROM chat_member_stats WHERE chat_id=? AND is_bot=0 ORDER BY messages DESC LIMIT 5',(chat_id,),fetch=True)
        days=await DBX.execute('SELECT day,messages,joins,leaves,commands,deleted FROM daily_stats WHERE chat_id=? ORDER BY day DESC LIMIT 7',(chat_id,),fetch=True)
        deleted=await DBX.one('SELECT COALESCE(SUM(deleted),0) n FROM daily_stats WHERE chat_id=?',(chat_id,))
        joins=await DBX.one('SELECT COALESCE(SUM(joins),0) n FROM daily_stats WHERE chat_id=?',(chat_id,))
        leaves=await DBX.one('SELECT COALESCE(SUM(leaves),0) n FROM daily_stats WHERE chat_id=?',(chat_id,))
        cmds=await DBX.one('SELECT COALESCE(SUM(commands),0) n FROM daily_stats WHERE chat_id=?',(chat_id,))
    except Exception as exc:
        log.warning('smart group report db error: %r',exc); return None
    val=lambda x,k: int((x or {}).get(k,0)) if isinstance(x,dict) else 0
    return {'members_tracked':val(members,'c'),'messages_total':val(total,'n'),'active_members':val(active,'c'),
            'top':[dict(x) for x in (top or [])],'daily':[dict(x) for x in (days or [])],
            'deleted_total':val(deleted,'n'),'joins_total':val(joins,'n'),'leaves_total':val(leaves,'n'),'commands_total':val(cmds,'n')}

def _bb_smart_group_score(r):
    tracked=max(1,r['members_tracked'])
    activity=min(35,int(r['active_members']/tracked*35))
    msgs=min(25,int(r['messages_total']/max(1,tracked*4)))
    retention=20 if r['leaves_total']<=r['joins_total'] else max(5,20-int((r['leaves_total']-r['joins_total'])/max(1,r['joins_total'])*20))
    consistency=min(20,len(r['daily'])*4)
    return max(0,min(100,activity+msgs+retention+consistency))

async def _bb_smart_group_ai(r,chat_title=''):
    if not await _bb_pro_get('OPENROUTER_API_KEY',''): return []
    compact={'tracked_members':r['members_tracked'],'active_members':r['active_members'],'messages_total':r['messages_total'],
             'joins':r['joins_total'],'leaves':r['leaves_total'],'commands':r['commands_total'],'deleted':r['deleted_total'],
             'last_7_days':r['daily'],'top_members':[{'name':x.get('first_name') or x.get('username') or str(x.get('user_id')),'messages':int(x.get('messages') or 0)} for x in r['top']]}
    prompt=(f"تو مدیر هوشمند یک گروه تلگرامی به نام {chat_title or 'این گروه'} هستی.\n"
            "فقط بر اساس DATA تحلیل کن و هیچ عددی را حدس نزن. دقیقاً 4 پیشنهاد کوتاه و عملی برای رشد سالم، افزایش مشارکت و مدیریت بهتر گروه بده.\n"
            "پیشنهادها نباید شامل اسپم، مزاحمت، فریب، خرید عضو یا اقدام خودکار روی کاربران باشند. هر مورد یک جمله و با ▸ شروع شود.\nDATA:\n"+json.dumps(compact,ensure_ascii=False))
    try:
        text=await _speaker_ai_call(prompt,chat_title=chat_title,verbosity='short',tone='polite',chat_id=None,memory_enabled=False,memory_limit=0,timeout=8)
        out=[]
        for line in str(text or '').splitlines():
            line=re.sub(r'^[-*•▸\d\.\)\s]+','',line.strip()).strip()
            if line: out.append(line)
        return out[:4]
    except Exception as exc:
        log.warning('smart group ai failed: %r',exc); return []

def _bb_smart_group_fallback(r):
    tips=[]
    if r['active_members']<max(3,int(r['members_tracked']*.25)): tips.append('برای اعضای کم‌فعال سؤال‌های کوتاه و موضوعات روزانه بگذار تا مشارکت آسان‌تر شود.')
    else: tips.append('موضوعات پربحث را به بحث‌های سریالی تبدیل کن و سؤال مشخص بپرس.')
    if r['leaves_total']>r['joins_total']: tips.append('روند خروج از ورود بیشتر است؛ قوانین، توضیحات و تجربه اعضای جدید را بازبینی کن.')
    if r['messages_total']<max(20,r['members_tracked']*4): tips.append('برای شروع گفتگو از نظرسنجی، سؤال روز و چالش‌های غیررقابتی استفاده کن.')
    if r['deleted_total']>0: tips.append('پیام‌های حذف‌شده را بررسی کن و قوانین گروه را شفاف‌تر و در دسترس‌تر نگه دار.')
    if not tips: tips.append('روند فعلی خوب است؛ روی محتوای منظم، گفت‌وگوی باکیفیت و تعامل واقعی تمرکز کن.')
    return tips[:4]

async def _bb_smart_group_command(update,context):
    msg=update.effective_message; chat=update.effective_chat
    if not msg or not chat or chat.type=='private': return False
    wait=await msg.reply_text('🧠 <b>مدیر هوشمند بیل‌بیلک</b>\n\n⏳ دارم فعالیت گروه، مشارکت اعضا و روند اخیر را بررسی می‌کنم…',parse_mode='HTML')
    r=await _bb_smart_group_report(chat.id)
    if not r:
        await wait.edit_text('⚠️ اطلاعات آماری گروه هنوز برای تحلیل کافی نیست.',parse_mode='HTML'); return True
    score=_bb_smart_group_score(r); grade='🔥 عالی' if score>=80 else ('🟢 خوب' if score>=60 else ('🟡 متوسط' if score>=40 else '🔴 نیازمند توجه'))
    tips=await _bb_smart_group_ai(r,getattr(chat,'title','')) or _bb_smart_group_fallback(r)
    top='\n'.join(f'• {safe_text(x.get("first_name") or x.get("username") or str(x.get("user_id")),35)} — {int(x.get("messages") or 0):,} پیام' for x in r['top']) or 'داده کافی نیست'
    daily='\n'.join(f'• {safe_text(x.get("day") or "—",20)} — {int(x.get("messages") or 0):,} پیام' for x in r['daily'][:5]) or 'هنوز داده روزانه کافی نیست'
    text=(f'🧠 <b>گزارش مدیر هوشمند گروه</b>\n━━━━━━━━━━━━━━\n🎯 امتیاز سلامت گروه: <b>{score}/100</b> {grade}\n\n'
          f'👥 اعضای ثبت‌شده: <b>{r["members_tracked"]:,}</b>\n💬 پیام‌های ثبت‌شده: <b>{r["messages_total"]:,}</b>\n⚡ اعضای فعال: <b>{r["active_members"]:,}</b>\n'
          f'➕ ورود: <b>{r["joins_total"]:,}</b> | ➖ خروج: <b>{r["leaves_total"]:,}</b>\n🗑 حذف‌شده ثبت‌شده: <b>{r["deleted_total"]:,}</b>\n\n'
          f'🏆 <b>فعال‌ترین اعضا</b>\n{top}\n\n📅 <b>روند اخیر</b>\n{daily}\n\n🚀 <b>۴ پیشنهاد مدیر هوشمند</b>\n'+ '\n'.join('▸ '+safe_text(x,350) for x in tips[:4])+
          '\n\nℹ️ فقط از داده‌هایی استفاده می‌شود که بیل‌بیلک در گروه ثبت کرده؛ آمار ناموجود ساختگی نمی‌شود.')
    await wait.edit_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('🔄 تحلیل دوباره','bbsmart:run')],[btn('❌ بستن پنل','panelclose')]])); return True

async def _bb_smart_panel(q,context):
    if not await _bb_is_bot_admin(q.from_user.id): await q.answer('⛔ فقط ادمین گروه.',show_alert=True); return True
    await q.edit_message_text('🧠 <b>مدیر هوشمند بیل‌بیلک</b>\n\n📊 فعالیت اعضا\n💬 میزان گفتگو\n📈 روند ورود و خروج\n🗑 وضعیت حذف پیام‌ها\n🤖 پیشنهادهای هوش مصنوعی\n\nگزارش بر اساس داده‌های داخلی ربات ساخته می‌شود.',parse_mode='HTML',reply_markup=keyboard([[btn('🚀 اجرای تحلیل هوشمند','bbsmart:run')],[btn('❌ بستن پنل','panelclose')]])); return True

_OLD_BB_CALLBACK_SMART=globals().get('callback_router')
async def callback_router(update,context):
    q=getattr(update,'callback_query',None); data=getattr(q,'data','') if q else ''
    if data=='bbsmart:panel': return await _bb_smart_panel(q,context)
    if data=='bbsmart:run':
        if not await _bb_is_bot_admin(q.from_user.id): await q.answer('⛔ فقط ادمین گروه.',show_alert=True); return True
        await q.answer('در حال تحلیل…'); return await _bb_smart_group_command(update,context)
    return await _OLD_BB_CALLBACK_SMART(update,context) if _OLD_BB_CALLBACK_SMART else None

_OLD_BB_MESSAGE_SMART=globals().get('message_router')
async def message_router(update,context):
    try:
        msg=update.effective_message; chat=update.effective_chat; n=normalize((getattr(msg,'text','') or '').strip()) if msg else ''
        if chat and chat.type!='private' and n in {'گزارش هوشمند گروه','مدیر هوشمند','آنالیز هوشمند گروه','گزارش گروه'}:
            if not await _bb_is_bot_admin(update.effective_user.id): await msg.reply_text('⛔ این گزارش مخصوص ادمین‌های گروه است.'); return True
            return await _bb_smart_group_command(update,context)
    except Exception as exc: log.warning('smart manager router failed: %r',exc)
    return await _OLD_BB_MESSAGE_SMART(update,context) if _OLD_BB_MESSAGE_SMART else False

