BB_UI_LANGS = {
    'fa': '🇮🇷 فارسی',
    'en': '🇬🇧 English',
    'ar': '🇸🇦 العربية',
    'tr': '🇹🇷 Türkçe',
}
BB_LANG_NAMES = {'fa':'فارسی','en':'English','ar':'العربية','tr':'Türkçe'}

async def _bb_lang_schema():
    await _bb_pro_schema()
    await DBX.execute('CREATE TABLE IF NOT EXISTS user_languages (user_id INTEGER PRIMARY KEY, lang TEXT NOT NULL DEFAULT "fa", updated_at INTEGER DEFAULT 0)')

async def _bb_get_global_lang():
    v = await _bb_pro_get('GLOBAL_LANGUAGE', 'fa')
    return v if v in BB_UI_LANGS else 'fa'

async def _bb_get_user_lang(uid):
    await _bb_lang_schema()
    r = await DBX.one('SELECT lang FROM user_languages WHERE user_id=?', (int(uid or 0),))
    if r and r['lang'] in BB_UI_LANGS:
        return r['lang']
    return await _bb_get_global_lang()

async def _bb_set_user_lang(uid, lang):
    await _bb_lang_schema()
    if lang not in BB_UI_LANGS: lang='fa'
    await DBX.execute('INSERT INTO user_languages(user_id,lang,updated_at) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET lang=excluded.lang,updated_at=excluded.updated_at', (int(uid),lang,now_ts()))

async def _bb_set_global_lang(lang):
    if lang not in BB_UI_LANGS: lang='fa'
    await _bb_pro_set('GLOBAL_LANGUAGE', lang)

