def _bb_lt(lang, key, **kw):
    lang = lang if lang in BB_UI_LANGS else 'fa'
    return BB_LANG_TEXT[lang].get(key, BB_LANG_TEXT['fa'].get(key,key)).format(**kw)

def _bb_lang_keyboard(prefix='bblang:user'):
    return keyboard([[btn(v, f'{prefix}:{k}') for k,v in BB_UI_LANGS.items()]])

async def _bb_language_menu(update, context, admin=False):
    msg = update.effective_message
    uid = update.effective_user.id
    cur = await _bb_get_global_lang() if admin else await _bb_get_user_lang(uid)
    text = _bb_lt(cur,'choose') + f'\n\n🔹 انتخاب فعلی: <b>{_bb_h(BB_LANG_NAMES[cur])}</b>'
    rows = [[btn(v, f'bblang:{"global" if admin else "user"}:{k}')] for k,v in BB_UI_LANGS.items()]
    await msg.reply_text(text, parse_mode='HTML', reply_markup=keyboard(rows))
    return True

async def _bb_language_callback(q, context):
    data = str(getattr(q,'data','') or '')
    parts=data.split(':')
    if len(parts)!=3: return False
    scope,lang=parts[1],parts[2]
    if lang not in BB_UI_LANGS: return False
    if scope=='global':
        if not await _bb_primary_owner(q.from_user.id): await q.answer('⛔ فقط سازنده اصلی.',show_alert=True); return True
        await _bb_set_global_lang(lang)
        await q.answer('زبان سراسری تغییر کرد.')
        await q.edit_message_text(_bb_lt(lang,'global_saved',lang=BB_LANG_NAMES[lang]),parse_mode='HTML')
    else:
        await _bb_set_user_lang(q.from_user.id,lang)
        await q.answer('زبان ذخیره شد.')
        await q.edit_message_text(_bb_lt(lang,'saved',lang=BB_LANG_NAMES[lang]),parse_mode='HTML')
    return True

async def _bb_news_fetch(lang='fa', topic='top stories'):
    key = await _bb_pro_get('GNEWS_API_KEY','')
    if not key: return []
    try:
        lang_code = {'fa':'fa','en':'en','ar':'ar','tr':'tr'}.get(lang,'fa')
        country = {'fa':'ir','en':'us','ar':'sa','tr':'tr'}.get(lang,'ir')
        status,data,_ = await _bb_http_get_json('https://gnews.io/api/v4/top-headlines', params={'apikey':key,'lang':lang_code,'country':country,'max':6}, timeout=15)
        if status != 200 or not isinstance(data,dict): return []
        return data.get('articles') or []
    except Exception as exc:
        log.warning('news fetch failed: %r',exc); return []

async def _bb_news_command(update, context):
    msg=update.effective_message
    if not msg: return False
    lang=await _bb_get_user_lang(update.effective_user.id)
    key=await _bb_pro_get('GNEWS_API_KEY','')
    if not key:
        await msg.reply_text(_bb_lt(lang,'news_empty')+'\n\n⚙️ مدیر باید <b>GNEWS_API_KEY</b> را در پنل تنظیم کند.',parse_mode='HTML'); return True
    wait=await msg.reply_text(_bb_lt(lang,'news_loading'),parse_mode='HTML')
    arts=await _bb_news_fetch(lang)
    if not arts:
        await wait.edit_text(_bb_lt(lang,'news_empty'),parse_mode='HTML'); return True
    lines=[_bb_lt(lang,'news')+'\n━━━━━━━━━━━━━━']
    for i,a in enumerate(arts[:6],1):
        title=safe_text((a.get('title') or '—'),180)
        source=safe_text(((a.get('source') or {}).get('name') or '—'),60)
        url=a.get('url') or ''
        if url:
            lines.append(f'{i}. <a href="{_bb_h(url)}">{_bb_h(title)}</a>\n   🏷 { _bb_h(source) }')
        else: lines.append(f'{i}. <b>{_bb_h(title)}</b>\n   🏷 {_bb_h(source)}')
    await wait.edit_text('\n\n'.join(lines),parse_mode='HTML',disable_web_page_preview=True)
    return True

async def _bb_news_owner_panel(q, context):
    if not await _bb_primary_owner(q.from_user.id): await q.answer('⛔ فقط سازنده اصلی.',show_alert=True); return True
    key=await _bb_pro_get('GNEWS_API_KEY','')
    await q.edit_message_text(f'📰 <b>تنظیمات اخبار</b>\n\n🔑 GNews API: {"🟢 ثبت شده" if key else "🔴 تنظیم نشده"}\n\nدستور کاربران: اخبار',parse_mode='HTML',reply_markup=keyboard([[btn('🔑 تنظیم API اخبار','bbnews:key')],[btn('❌ بستن پنل','panelclose')]]))
    return True

BB_NEWS_PENDING=set()
async def _bb_news_key_start(q,context):
    if not await _bb_primary_owner(q.from_user.id): await q.answer('⛔ فقط سازنده اصلی.',show_alert=True); return True
    BB_NEWS_PENDING.add(q.from_user.id); await q.answer('کلید را بفرست.')
    try: await q.message.reply_text('🔑 کلید <b>GNews API</b> را در همین پیوی بفرست.',parse_mode='HTML')
    except Exception: pass
    return True

# Local, fast enhancement: 2x high-quality resampling + detail/sharpening.
# It requires no external AI key. Optional Cloudinary can be added later for AI super-resolution.
async def _bb_enhance_photo(update, context):
    msg=update.effective_message
    if not msg or not getattr(msg,'photo',None): return False
    rep=msg.reply_to_message
    text=normalize((getattr(msg,'caption','') or getattr(msg,'text','') or ''))
    if not rep or not getattr(rep,'photo',None) or text not in {'افزایش کیفیت','بهبود کیفیت','کیفیت عکس','enhance quality','improve quality','تحسين الجودة','kaliteyi artır'}:
        return False
    lang=await _bb_get_user_lang(update.effective_user.id)
    wait=await msg.reply_text(_bb_lt(lang,'upscale_loading'),parse_mode='HTML')
    path=None; out=None
    try:
        from PIL import Image, ImageFilter, ImageEnhance
        import io
        p=rep.photo[-1]
        f=await p.get_file(); data=await f.download_as_bytearray()
        im=Image.open(io.BytesIO(bytes(data))).convert('RGB')
        w,h=im.size
        scale=2 if max(w,h)<1800 else 1.5
        nw,nh=int(w*scale),int(h*scale)
        im=im.resize((nw,nh),Image.Resampling.LANCZOS)
        im=im.filter(ImageFilter.UnsharpMask(radius=1.2,percent=130,threshold=3))
        im=ImageEnhance.Contrast(im).enhance(1.03)
        buf=io.BytesIO(); buf.name='bilbilak_enhanced.jpg'; im.save(buf,'JPEG',quality=95,optimize=True); buf.seek(0)
        await msg.reply_photo(photo=buf,caption=_bb_lt(lang,'upscale_done'),parse_mode='HTML')
        await wait.delete()
    except Exception as exc:
        log.warning('image enhance failed: %r',exc)
        try: await wait.edit_text('⚠️ افزایش کیفیت انجام نشد. مطمئن شو Pillow نصب است: pip install pillow',parse_mode='HTML')
        except Exception: pass
    return True

