async def message_router(update,context):
    try:
        msg=update.effective_message; uid=getattr(getattr(update,'effective_user',None),'id',0); n=normalize((getattr(msg,'text','') or '').strip()) if msg else ''
        if msg and uid in BB_NEWS_PENDING and n:
            if await _bb_primary_owner(uid):
                await _bb_pro_set('GNEWS_API_KEY',n); BB_NEWS_PENDING.discard(uid)
                await msg.reply_text('✅ کلید GNews ذخیره شد.')
                return True
        if msg and n in {'زبان','language','lang'}:
            return await _bb_language_menu(update,context,admin=False)
        if msg and n in {'اخبار','خبر','اخبار روز','daily news','news'}:
            return await _bb_news_command(update,context)
        if msg and n in {'افزایش کیفیت','بهبود کیفیت','کیفیت عکس','enhance quality','improve quality','تحسين الجودة','kaliteyi artır'} and getattr(msg,'reply_to_message',None):
            return await _bb_enhance_photo(update,context)
        if msg and n in {'زبان پیشفرض ربات','زبان کل ربات','زبان ربات','global language'} and await _bb_primary_owner(uid):
            return await _bb_language_menu(update,context,admin=True)
    except Exception as exc: log.warning('news/lang router failed: %r',exc)
    return await _OLD_BB_MESSAGE_NEWS_LANG(update,context) if _OLD_BB_MESSAGE_NEWS_LANG else False

_OLD_BB_CALLBACK_NEWS_LANG=callback_router
async def callback_router(update,context):
    q=getattr(update,'callback_query',None); data=str(getattr(q,'data','') or '') if q else ''
    if data.startswith('bblang:'): return await _bb_language_callback(q,context)
    if data=='bbnews:key': return await _bb_news_key_start(q,context)
    if data=='bbnews:panel': return await _bb_news_owner_panel(q,context)
    return await _OLD_BB_CALLBACK_NEWS_LANG(update,context) if _OLD_BB_CALLBACK_NEWS_LANG else None

_OLD_BB_BUILD_NEWS_LANG=build_application
def build_application(token):
    app=_OLD_BB_BUILD_NEWS_LANG(token)
    try:
        app.add_handler(MessageHandler(filters.PHOTO, _bb_enhance_photo), group=-30000)
    except Exception: log.exception('image enhancement handler registration failed')
    return app

