_BB_STYLE_MARK = "🐾 𝓑𝓲𝓵𝓫𝓲𝓵𝓪𝓴"
_BB_STYLE_FOOTER = "\n\n━━━━━━━━━━━━━━━━━━\n🐾 𝓑𝓲𝓵𝓫𝓲𝓵𝓪𝓴 • @Bil_bilakapibot"


def _bb_pretty_message(text, parse_mode=None):
    """Add a consistent Bilbilak visual identity without deleting user content."""
    if text is None:
        return text
    value = str(text)
    if not value.strip():
        return value
    if _BB_STYLE_MARK in value or "@Bil_bilakapibot" in value and "━━━━━━━━━━━━━━━━━━" in value:
        return value
    # Telegram text messages have a hard limit. Never truncate existing content.
    if len(value) > 4050:
        return value
    # Keep Markdown messages plain so we never inject HTML into Markdown.
    if parse_mode and str(parse_mode).lower() not in {"html", "telegram.constants.parsemode.html"}:
        return value + "\n\n━━━━━━━━━━━━━━━━━━\n🐾 Bilbilak • @Bil_bilakapibot"
    return f"🐾 <b>𝓑𝓲𝓵𝓫𝓲𝓵𝓪𝓴</b>\n{value}{_BB_STYLE_FOOTER}"


# Patch Bot text/caption sending once. reply_text/edit_text ultimately use these
# Bot methods, so old features also receive the visual layer without rewriting
# thousands of existing messages.
if not getattr(telegram.Bot, "_bb_global_polish_installed", False):
    _BB_ORIG_SEND_MESSAGE = telegram.Bot.send_message
    _BB_ORIG_EDIT_MESSAGE_TEXT = telegram.Bot.edit_message_text
    _BB_ORIG_SEND_PHOTO = telegram.Bot.send_photo
    _BB_ORIG_SEND_VIDEO = telegram.Bot.send_video
    _BB_ORIG_SEND_ANIMATION = telegram.Bot.send_animation
    _BB_ORIG_SEND_DOCUMENT = telegram.Bot.send_document
    _BB_ORIG_SEND_AUDIO = telegram.Bot.send_audio
    _BB_ORIG_SEND_VOICE = telegram.Bot.send_voice

    async def _bb_send_message(self, chat_id, text, *args, **kwargs):
        kwargs["text"] = _bb_pretty_message(text, kwargs.get("parse_mode"))
        return await _BB_ORIG_SEND_MESSAGE(self, chat_id, kwargs.pop("text"), *args, **kwargs)

    async def _bb_edit_message_text(self, *args, **kwargs):
        if "text" in kwargs:
            kwargs["text"] = _bb_pretty_message(kwargs["text"], kwargs.get("parse_mode"))
        elif len(args) >= 3:
            args = list(args)
            args[2] = _bb_pretty_message(args[2], kwargs.get("parse_mode"))
            args = tuple(args)
        return await _BB_ORIG_EDIT_MESSAGE_TEXT(self, *args, **kwargs)

    def _bb_caption(caption, parse_mode):
        return _bb_pretty_message(caption, parse_mode) if caption else caption

    async def _bb_send_photo(self, *args, **kwargs):
        kwargs["caption"] = _bb_caption(kwargs.get("caption"), kwargs.get("parse_mode"))
        return await _BB_ORIG_SEND_PHOTO(self, *args, **kwargs)

    async def _bb_send_video(self, *args, **kwargs):
        kwargs["caption"] = _bb_caption(kwargs.get("caption"), kwargs.get("parse_mode"))
        return await _BB_ORIG_SEND_VIDEO(self, *args, **kwargs)

    async def _bb_send_animation(self, *args, **kwargs):
        kwargs["caption"] = _bb_caption(kwargs.get("caption"), kwargs.get("parse_mode"))
        return await _BB_ORIG_SEND_ANIMATION(self, *args, **kwargs)

    async def _bb_send_document(self, *args, **kwargs):
        kwargs["caption"] = _bb_caption(kwargs.get("caption"), kwargs.get("parse_mode"))
        return await _BB_ORIG_SEND_DOCUMENT(self, *args, **kwargs)

    async def _bb_send_audio(self, *args, **kwargs):
        kwargs["caption"] = _bb_caption(kwargs.get("caption"), kwargs.get("parse_mode"))
        return await _BB_ORIG_SEND_AUDIO(self, *args, **kwargs)

    async def _bb_send_voice(self, *args, **kwargs):
        kwargs["caption"] = _bb_caption(kwargs.get("caption"), kwargs.get("parse_mode"))
        return await _BB_ORIG_SEND_VOICE(self, *args, **kwargs)

    telegram.Bot.send_message = _bb_send_message
    telegram.Bot.edit_message_text = _bb_edit_message_text
    telegram.Bot.send_photo = _bb_send_photo
    telegram.Bot.send_video = _bb_send_video
    telegram.Bot.send_animation = _bb_send_animation
    telegram.Bot.send_document = _bb_send_document
    telegram.Bot.send_audio = _bb_send_audio
    telegram.Bot.send_voice = _bb_send_voice
    telegram.Bot._bb_global_polish_installed = True


async def _bb_group_info_pretty(update, context):
    """Beautiful group information with a real Telegram share chooser button."""
    chat = update.effective_chat
    msg = update.effective_message
    if not chat or chat.type == "private":
        await msg.reply_text(
            "🔗 <b>دریافت لینک گروه</b>\n\n"
            "این دستور را داخل همان گروه بفرست تا لینک قابل اشتراک‌گذاری ساخته شود.",
            parse_mode="HTML"
        )
        return True

    await DBX.ensure_chat(chat)
    try:
        link = ("https://t.me/" + chat.username) if chat.username else await context.bot.export_chat_invite_link(chat.id)
    except TelegramError:
        link = ""

    try:
        full = await context.bot.get_chat(chat.id)
        title = getattr(full, "title", None) or chat.title or "بدون نام"
        desc = getattr(full, "description", None) or "توضیحی برای این گروه ثبت نشده است."
        username = getattr(full, "username", None) or getattr(chat, "username", None)
    except TelegramError:
        title = chat.title or "بدون نام"
        desc = "توضیحی برای این گروه ثبت نشده است."
        username = getattr(chat, "username", None)

    owner = "پیدا نشد"
    try:
        admins = await context.bot.get_chat_administrators(chat.id)
        own = next((a.user for a in admins if a.status == ChatMemberStatus.OWNER), None)
        if own:
            owner = mention_html(own)
    except TelegramError:
        pass

    if link:
        share_text = (
            f"🐾 لینک گروه «{safe_text(title, 100)}»\n\n"
            f"برای پیوستن به گروه روی لینک بزنید.\n"
            f"{link}"
        )
        share_url = "https://t.me/share/url?url=" + quote_plus(link) + "&text=" + quote_plus(share_text)
        rows = [
            [InlineKeyboardButton("📤 کلیک کنید برای اشتراک‌گذاری لینک گروه", url=share_url)],
            [InlineKeyboardButton("🔗 باز کردن لینک گروه", url=link)],
        ]
    else:
        rows = []

    public_name = f"@{username}" if username else "خصوصی / لینک دعوت"
    text = (
        "🔗 <b>اطلاعات کامل گروه</b>\n\n"
        f"📛 <b>نام:</b> {safe_text(title, 120)}\n"
        f"📝 <b>توضیحات:</b> {safe_text(desc, 500)}\n"
        f"👑 <b>مالک:</b> {owner}\n"
        f"🌐 <b>شناسه عمومی:</b> {safe_text(public_name, 100)}\n"
        f"🆔 <b>Chat ID:</b> {chat.id}\n\n"
    )
    if link:
        text += (
            "🔗 <b>لینک گروه:</b>\n"
            f"{safe_text(link, 500)}\n\n"
            "📤 <b>اشتراک‌گذاری:</b> روی دکمه بالا بزن؛ تلگرام صفحه انتخاب مخاطب را باز می‌کند "
            "تا لینک گروه را برای هر کسی که خواستی ارسال کنی."
        )
    else:
        text += "⚠️ لینک دعوت ساخته نشد؛ ربات باید دسترسی لازم برای ساخت لینک دعوت را داشته باشد."

    await msg.reply_text(text, parse_mode="HTML", reply_markup=InlineKeyboardMarkup(rows) if rows else None)
    return True


