TD_CUSTOM_DARE_RAW = """

"""

TD_CUSTOM_TRUTH_RAW = """

"""

TD_CUSTOM_GIRL_RAW = """

"""

TD_CUSTOM_BOY_RAW = """

"""

_TD_SAFE_DARES = [q.strip() for q in TD_CUSTOM_DARE_RAW.splitlines() if q.strip()]
_TD_SAFE_TRUTHS = [q.strip() for q in TD_CUSTOM_TRUTH_RAW.splitlines() if q.strip()]
_TD_SAFE_GIRL = [q.strip() for q in TD_CUSTOM_GIRL_RAW.splitlines() if q.strip()]
_TD_SAFE_BOY = [q.strip() for q in TD_CUSTOM_BOY_RAW.splitlines() if q.strip()]


