async def _bb_factory_callback(q, context):
    p=(q.data or '').split(':')
    if len(p)!=3 or p[0]!='bbfac' or not p[1].isdigit() or int(p[1])!=q.from_user.id:
        return False
    uid=q.from_user.id; action=p[2]
    if action=='produce':
        st=await _bb_factory_row(uid); now=now_ts(); until=int(st['production_until'] or 0)
        if until>now:
            await q.answer(f'⏳ تولید درحال انجام است؛ {until-now} ثانیه مانده.',show_alert=True); return True
        if int(st['warehouse'] or 0)>=int(st['warehouse_capacity'] or 50000):
            await q.answer('📦 انبار کارخانه پر است.',show_alert=True); return True
        await DBX.execute('UPDATE hapoo_factory_state SET production_until=? WHERE user_id=?',(now+int(st['production_seconds'] or 10),uid))
        await q.answer('🏭 خط تولید شروع شد! ۱۰ ثانیه دیگر محصول آماده می‌شود.',show_alert=True)
        await v7_factory(q,uid); return True
    if action=='storage':
        st=await _bb_factory_row(uid)
        await q.edit_message_text(
            f'📦 <b>انبار کارخانه</b>\n\nموجودی: <b>{int(st["warehouse"]):,}</b>\nظرفیت: <b>{int(st["warehouse_capacity"]):,}</b>\n\nهر محصول تولیدشده اینجا ثبت می‌شود.',
            parse_mode='HTML',reply_markup=keyboard([[btn('🔙 کارخانه',f'v8factory:{uid}:home')]])
        ); return True
    if action=='workers':
        st=await _bb_factory_row(uid)
        await q.edit_message_text(
            f'👷 <b>کارگران کارخانه</b>\n\nتعداد: <b>{int(st["workers"])}/{int(st["worker_capacity"])}</b>\nسطح: <b>{int(st["factory_level"])}</b> ⭐\n\nکارگران فعلی مسئول تولید محصولات کارخانه‌اند.',
            parse_mode='HTML',reply_markup=keyboard([[btn('🔙 کارخانه',f'v8factory:{uid}:home')]])
        ); return True
    if action=='machines':
        st=await _bb_factory_row(uid)
        await q.edit_message_text(
            f'⚙️ <b>دستگاه‌های تولید</b>\n\nسطح دستگاه: <b>{int(st["machine_level"])}</b> ⭐\nزمان تولید: <b>{int(st["production_seconds"])} ثانیه</b> ⏱️\n\nخط تولید کارخانه برای بازی آماده است.',
            parse_mode='HTML',reply_markup=keyboard([[btn('🔙 کارخانه',f'v8factory:{uid}:home')]])
        ); return True
    return True

# Make the requested plain-text commands open the screenshot-inspired panels.
_OLD_HAPOOYI_ROUTER = message_router_v9
async def message_router_v9(update, context):
    msg=update.effective_message
    if msg and msg.text:
        t=normalize(msg.text or '')
        if t in {'هاپویی','پنل هاپویی'}:
            fake=type('Q',(),{
                'from_user':update.effective_user,'message':msg,
                'answer':lambda *a,**k:None,'edit_message_text':msg.reply_text
            })()
            await _bb_hapoo_panel(fake,update.effective_user.id); return
        if t in {'کارخانه','کارخانه هاپویی','کارخانه هاپو'}:
            fake=type('Q',(),{
                'from_user':update.effective_user,'message':msg,
                'answer':lambda *a,**k:None,'edit_message_text':msg.reply_text
            })()
            await v7_factory(fake,update.effective_user.id); return
    return await _OLD_HAPOOYI_ROUTER(update,context)

_OLD_HAPOOYI_CALLBACK = callback_router_v10
async def callback_router_v10(update, context):
    q=getattr(update,'callback_query',None)
    if q and (q.data or '').startswith('bbfac:'):
        try: await q.answer()
        except Exception: pass
        await _bb_factory_callback(q,context); return
    if q and (q.data or '').startswith('v8factory:'):
        p=(q.data or '').split(':')
        if len(p)==3 and p[1].isdigit() and int(p[1])==q.from_user.id:
            try: await q.answer()
            except Exception: pass
            if p[2]=='home': await v7_factory(q,q.from_user.id); return
    return await _OLD_HAPOOYI_CALLBACK(update,context)

# Rebuild application once more so the latest message/callback routers are used.
def build_application(token:str)->Application:
    app=ApplicationBuilder().token(token).post_init(post_init_vip_pro).post_shutdown(post_shutdown).build()
    for name,fn in [('start',start_v8),('help',cmd_help),('panel',cmd_panel),('adminpanel',cmd_adminpanel),('owner',owner_panel_v6),('features',cmd_features),('rules',rules_command),('setrules',set_rules),('welcome',set_welcome),('togglewelcome',toggle_welcome),('goodbye',set_goodbye),('togglegoodbye',toggle_goodbye),('forcejoin',forcejoin_v4),('stats',stats_v4_command)]:
        app.add_handler(CommandHandler(name,fn))
    app.add_handler(CommandHandler('cleanup',lambda u,c:cleanup_v4(u,c,500)))
    app.add_handler(CommandHandler('warn',lambda u,c:moderation_action(u,c,'warn')))
    app.add_handler(CommandHandler('unwarn',lambda u,c:moderation_action(u,c,'unwarn')))
    app.add_handler(CommandHandler('mute',lambda u,c:mute_command_v6(u,c)))
    app.add_handler(CommandHandler('unmute',lambda u,c:moderation_v4(u,c,'unmute')))
    app.add_handler(CommandHandler('ban',lambda u,c:moderation_v4(u,c,'ban')))
    app.add_handler(CommandHandler('unban',lambda u,c:moderation_v4(u,c,'unban')))
    app.add_handler(CommandHandler('mafia',lambda u,c:mafia_start_menu(u,c)))
    app.add_handler(ChatMemberHandler(member_update_v6,ChatMemberHandler.CHAT_MEMBER))
    app.add_handler(CallbackQueryHandler(callback_router_v10))
    if MessageReactionHandler is not None: app.add_handler(MessageReactionHandler(reaction_handler))
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS,service_members_v4))
    app.add_handler(MessageHandler(filters.StatusUpdate.LEFT_CHAT_MEMBER,service_members_v4))
    app.add_handler(MessageHandler(filters.LOCATION,location_v4))
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,message_router_v9))
    app.add_error_handler(error_handler)
    return app




# =============================================================================
# BILBILAK HAPOOYI BANK — screenshot-inspired virtual bank
# Uses only the bot's in-app virtual Bones currency; no real money/payments.
# =============================================================================

BB_BANK_PENDING = {}
BB_BANK_INTEREST = 0.03  # virtual 3% interest per 24 hours

async def _bb_bank_schema():
    await DBX.execute("""CREATE TABLE IF NOT EXISTS hapoo_bank_accounts (
        user_id INTEGER PRIMARY KEY,
        account_number TEXT NOT NULL UNIQUE,
        balance INTEGER NOT NULL DEFAULT 0,
        interest_rate REAL NOT NULL DEFAULT 0.03,
        deposited_at INTEGER NOT NULL DEFAULT 0,
        last_interest_at INTEGER NOT NULL DEFAULT 0,
        created_at INTEGER NOT NULL DEFAULT 0,
        updated_at INTEGER NOT NULL DEFAULT 0
    )""")
    await DBX.execute("""CREATE TABLE IF NOT EXISTS hapoo_bank_transactions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        kind TEXT NOT NULL,
        amount INTEGER NOT NULL,
        balance_after INTEGER NOT NULL,
        created_at INTEGER NOT NULL DEFAULT 0
    )""")


def _bb_bank_account_number(uid):
    # Stable-looking virtual account number, unique per user.
    import hashlib
    raw = hashlib.sha256(f"bilbilak-bank:{uid}".encode()).hexdigest()
    return str(int(raw[:18], 16))[-12:].zfill(12)


async def _bb_bank_row(uid):
    await _bb_bank_schema()
    row = await DBX.one("SELECT * FROM hapoo_bank_accounts WHERE user_id=?", (uid,))
    if not row:
        now = now_ts()
        acc = _bb_bank_account_number(uid)
        await DBX.execute(
            "INSERT OR IGNORE INTO hapoo_bank_accounts(user_id,account_number,interest_rate,created_at,updated_at) VALUES(?,?,?,?,?)",
            (uid, acc, BB_BANK_INTEREST, now, now)
        )
        row = await DBX.one("SELECT * FROM hapoo_bank_accounts WHERE user_id=?", (uid,))
    return row


async def _bb_bank_apply_interest(uid):
    row = await _bb_bank_row(uid)
    now = now_ts()
    bal = int(row['balance'] or 0)
    last = int(row['last_interest_at'] or row['deposited_at'] or now)
    # Interest is virtual and credited once per completed 24-hour period.
    periods = max(0, (now - last) // 86400)
    if periods and bal > 0:
        total_interest = 0
        current = bal
        for _ in range(min(periods, 30)):
            gain = int(current * float(row['interest_rate'] or BB_BANK_INTEREST) / 100)
            if gain <= 0:
                break
            current += gain
            total_interest += gain
        periods = min(periods, 30)
        if total_interest:
            await DBX.execute(
                "UPDATE hapoo_bank_accounts SET balance=?,last_interest_at=?,updated_at=? WHERE user_id=?",
                (current, last + periods * 86400, now, uid)
            )
            await DBX.execute(
                "INSERT INTO hapoo_bank_transactions(user_id,kind,amount,balance_after,created_at) VALUES(?,?,?,?,?)",
                (uid, 'interest', total_interest, current, now)
            )
        else:
            await DBX.execute("UPDATE hapoo_bank_accounts SET last_interest_at=?,updated_at=? WHERE user_id=?", (last + periods * 86400, now, uid))
        row = await _bb_bank_row(uid)
    return row


def _bb_bank_time(ts):
    try:
        import datetime
        return datetime.datetime.fromtimestamp(int(ts)).strftime('%Y/%m/%d %H:%M')
    except Exception:
        return '—'


async def _bb_bank_panel(q, uid):
    if getattr(q.from_user, 'id', uid) != uid:
        await q.answer('این حساب بانکی برای خودت نیست.', show_alert=True)
        return
    await _bb_bank_apply_interest(uid)
    row = await _bb_bank_row(uid)
    u = await DBX.get_user(uid)
    wallet = int(u['bones'] or 0)
    bal = int(row['balance'] or 0)
    rate = float(row['interest_rate'] or BB_BANK_INTEREST)
    deposited_at = int(row['deposited_at'] or 0)
    text = (
        '🏦 <b>بانک هاپویی</b> 🐾\n\n'
        f'📱 <b>شماره حساب:</b> {row["account_number"]}\n'
        f'👤 <b>به نام:</b> {safe_text(u["first_name"] or "کاربر", 35)}\n\n'
        f'🪙 <b>موجودی حساب:</b> <b>{bal:,}</b>\n'
        f'💰 <b>موجودی کیف پول:</b> <b>{wallet:,}</b> 🦴\n\n'
        f'🤑 <b>سود بانکی:</b> <b>{rate:g}%</b> در هر ۲۴ ساعت\n'
        f'└ حداقل مدت محاسبه: <b>۲۴ ساعت</b>\n'
        f'📥 <b>آخرین واریز:</b> <b>{_bb_bank_time(deposited_at) if deposited_at else "هنوز واریزی ثبت نشده"}</b>\n\n'
        '⚠️ این بانک کاملاً <b>مجازی و داخل ربات</b> است و ارزش پول واقعی ندارد.\n\n'
        '❗ برای مدیریت حساب از گزینه‌های زیر استفاده کن 👇'
    )
    kb = keyboard([
        [btn('💳 کارت به کارت هاپویی', f'bbbank:{uid}:transfer')],
        [btn('➖ برداشت', f'bbbank:{uid}:withdraw'), btn('➕ واریز', f'bbbank:{uid}:deposit')],
        [btn('🔄 تغییر شماره حساب', f'bbbank:{uid}:change')],
        [btn('🧾 تراکنش‌ها', f'bbbank:{uid}:transactions')],
        [btn('🐾 هاپویی', user_cb(uid, 'dog')), btn('🏠 خانه', user_cb(uid, 'home'))],
    ])
    await q.edit_message_text(text, parse_mode='HTML', reply_markup=kb)


async def _bb_bank_prompt(q, uid, action):
    if getattr(q.from_user, 'id', uid) != uid:
        await q.answer('این حساب برای خودت نیست.', show_alert=True); return True
    labels = {
        'deposit': '➕ <b>واریز به بانک</b>',
        'withdraw': '➖ <b>برداشت از بانک</b>',
    }
    BB_BANK_PENDING[uid] = action
    await q.edit_message_text(
        f'{labels[action]}\n\n'
        'مبلغ را فقط به صورت عدد بفرست.\n'
        'مثال: 5000\n\n'
        '🦴 واریز: از کیف پول مجازی کم و به بانک اضافه می‌شود.\n'
        '🪙 برداشت: از بانک کم و به کیف پول مجازی اضافه می‌شود.\n\n'
        '❌ برای لغو، لغو را بفرست.',
        parse_mode='HTML',
        reply_markup=keyboard([[btn('🔙 بانک', f'bbbank:{uid}:home')]])
    )
    return True


async def _bb_bank_transactions(q, uid):
    if getattr(q.from_user, 'id', uid) != uid:
        await q.answer('این حساب برای خودت نیست.', show_alert=True); return True
    await _bb_bank_apply_interest(uid)
    rows = await DBX.all('SELECT kind,amount,balance_after,created_at FROM hapoo_bank_transactions WHERE user_id=? ORDER BY id DESC LIMIT 10', (uid,))
    names = {'deposit':'➕ واریز', 'withdraw':'➖ برداشت', 'interest':'🤑 سود بانکی', 'transfer_out':'↗️ انتقال', 'transfer_in':'↙️ دریافت'}
    lines = []
    for r in rows:
        lines.append(f"{names.get(r['kind'], r['kind'])} — <b>{int(r['amount']):,}</b> — {_bb_bank_time(r['created_at'])}\n└ موجودی: {int(r['balance_after']):,}")
    body = '\n\n'.join(lines) if lines else 'هنوز تراکنشی ثبت نشده است.'
    await q.edit_message_text(
        '🧾 <b>تراکنش‌های بانک هاپویی</b>\n\n' + body,
        parse_mode='HTML',
        reply_markup=keyboard([[btn('🔙 بانک', f'bbbank:{uid}:home')]])
    )
    return True


async def _bb_bank_transfer_info(q, uid):
    if getattr(q.from_user, 'id', uid) != uid:
        await q.answer('این حساب برای خودت نیست.', show_alert=True); return True
    await q.edit_message_text(
        '💳 <b>کارت به کارت هاپویی</b>\n\n'
        'برای جلوگیری از اشتباه، انتقال بین کاربران در این بخش فقط به‌صورت مجازی انجام می‌شود.\n\n'
        'فعلاً از <b>واریز</b> و <b>برداشت</b> برای مدیریت موجودی خودت استفاده کن.\n'
        'هیچ پرداخت واقعی یا اتصال بانکی وجود ندارد.',
        parse_mode='HTML',
        reply_markup=keyboard([[btn('🔙 بانک', f'bbbank:{uid}:home')]])
    )
    return True


async def _bb_bank_callback(q, context):
    p = (q.data or '').split(':')
    if len(p) != 3 or p[0] != 'bbbank' or not p[1].isdigit() or int(p[1]) != q.from_user.id:
        return False
    uid = q.from_user.id
    action = p[2]
    if action == 'home':
        await _bb_bank_panel(q, uid); return True
    if action in ('deposit','withdraw'):
        await _bb_bank_prompt(q, uid, action); return True
    if action == 'transactions':
        await _bb_bank_transactions(q, uid); return True
    if action == 'transfer':
        await _bb_bank_transfer_info(q, uid); return True
    if action == 'change':
        row = await _bb_bank_row(uid)
        new_acc = _bb_bank_account_number(uid)
        # Add a deterministic variant while keeping it unique.
        import hashlib
        suffix = str(int(hashlib.sha256(f"{uid}:{now_ts()}".encode()).hexdigest()[:12],16))[-4:]
        new_acc = (new_acc[:-4] + suffix).zfill(12)
        await DBX.execute('UPDATE hapoo_bank_accounts SET account_number=?,updated_at=? WHERE user_id=?', (new_acc, now_ts(), uid))
        await q.answer('🔄 شماره حساب تغییر کرد.', show_alert=True)
        await _bb_bank_panel(q, uid); return True
    return True


async def _bb_bank_text_handler(update, context):
    msg = update.effective_message
    user = update.effective_user
    if not msg or not user or not msg.text:
        return False
    uid = user.id
    action = BB_BANK_PENDING.get(uid)
    if not action:
        return False
    t = normalize(msg.text or '')
    if t in {'لغو', 'انصراف'}:
        BB_BANK_PENDING.pop(uid, None)
        fake = type('Q', (), {'from_user': user, 'message': msg, 'edit_message_text': msg.reply_text, 'answer': lambda *a, **k: None})()
        await _bb_bank_panel(fake, uid)
        return True
    raw = (msg.text or '').replace(',', '').replace('٬', '').strip()
    if not raw.isdigit() or int(raw) <= 0:
        await msg.reply_text('❌ فقط یک مبلغ عددی مثبت بفرست. مثال: 5000', parse_mode='HTML')
        return True
    amount = int(raw)
    if amount > 10_000_000_000:
        await msg.reply_text('❌ مبلغ بیش از حد مجاز است.', parse_mode='HTML'); return True
    await _bb_bank_apply_interest(uid)
    row = await _bb_bank_row(uid)
    now = now_ts()
    if action == 'deposit':
        u = await DBX.get_user(uid)
        wallet = int(u['bones'] or 0)
        if amount > wallet:
            await msg.reply_text(f'❌ موجودی کیف پول کافی نیست.\n🦴 کیف پول: <b>{wallet:,}</b>', parse_mode='HTML'); return True
        new_bal = int(row['balance'] or 0) + amount
        await DBX.execute('UPDATE users SET bones=bones-?,updated_at=? WHERE user_id=?', (amount, now, uid))
        await DBX.execute('UPDATE hapoo_bank_accounts SET balance=?,deposited_at=?,last_interest_at=?,updated_at=? WHERE user_id=?', (new_bal, now, now, now, uid))
        await DBX.execute('INSERT INTO hapoo_bank_transactions(user_id,kind,amount,balance_after,created_at) VALUES(?,?,?,?,?)', (uid,'deposit',amount,new_bal,now))
        result = f'✅ <b>{amount:,}</b> 🦴 با موفقیت به بانک واریز شد.'
    else:
        bal = int(row['balance'] or 0)
        if amount > bal:
            await msg.reply_text(f'❌ موجودی بانک کافی نیست.\n🪙 موجودی بانک: <b>{bal:,}</b>', parse_mode='HTML'); return True
        new_bal = bal - amount
        await DBX.execute('UPDATE users SET bones=bones+?,updated_at=? WHERE user_id=?', (amount, now, uid))
        await DBX.execute('UPDATE hapoo_bank_accounts SET balance=?,updated_at=? WHERE user_id=?', (new_bal, now, uid))
        await DBX.execute('INSERT INTO hapoo_bank_transactions(user_id,kind,amount,balance_after,created_at) VALUES(?,?,?,?,?)', (uid,'withdraw',amount,new_bal,now))
        result = f'✅ <b>{amount:,}</b> 🦴 از بانک برداشت شد.'
    BB_BANK_PENDING.pop(uid, None)
    await msg.reply_text(result, parse_mode='HTML', reply_markup=keyboard([[btn('🏦 باز کردن بانک', f'bbbank:{uid}:home')]]))
    return True


_OLD_BANK_CALLBACK_ROUTER = callback_router_v10
async def callback_router_v10(update, context):
    q = getattr(update, 'callback_query', None)
    if q and (q.data or '').startswith('bbbank:'):
        try: await q.answer()
        except Exception: pass
        await _bb_bank_callback(q, context); return
    return await _OLD_BANK_CALLBACK_ROUTER(update, context)

_OLD_BANK_MESSAGE_ROUTER = message_router_v9
async def message_router_v9(update, context):
    if await _bb_bank_text_handler(update, context):
        return
    msg = update.effective_message
    if msg and msg.text:
        t = normalize(msg.text or '')
        if t in {'بانک هاپویی','بانک هاپو','بانک','بانک میویی'}:
            uid = update.effective_user.id
            fake = type('Q', (), {
                'from_user': update.effective_user,
                'message': msg,
                'answer': lambda *a, **k: None,
                'edit_message_text': msg.reply_text,
            })()
            await _bb_bank_panel(fake, uid)
            return
    return await _OLD_BANK_MESSAGE_ROUTER(update, context)



