TD_ADMIN_KINDS = {
    "dare": ("💙 جرأت", "td_questions_dare"),
    "truth": ("❤️ حقیقت", "td_questions_truth"),
    "girl": ("👩 دخترانه", "td_questions_girl"),
    "boy": ("👨 پسرانه", "td_questions_boy"),
}

async def _td_admin_schema():
    for _, (_, table) in TD_ADMIN_KINDS.items():
        await DBX.execute(f"""CREATE TABLE IF NOT EXISTS {table} (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            question TEXT NOT NULL,
            created_at INTEGER NOT NULL DEFAULT 0
        )""")

async def _td_admin_count(kind):
    await _td_admin_schema()
    table = TD_ADMIN_KINDS[kind][1]
    row = await DBX.one(f"SELECT COUNT(*) AS c FROM {table}")
    return int(row["c"] if row else 0)

async def _td_admin_questions(kind, limit=50, offset=0):
    await _td_admin_schema()
    table = TD_ADMIN_KINDS[kind][1]
    return await DBX.all(f"SELECT id, question FROM {table} ORDER BY id ASC LIMIT ? OFFSET ?", (limit, offset))

async def _td_admin_add(kind, text):
    await _td_admin_schema()
    table = TD_ADMIN_KINDS[kind][1]
    rows = [x.strip() for x in (text or "").splitlines() if x.strip()]
    added = 0
    now = int(time.time())
    for q in rows:
        if len(q) > 1000:
            q = q[:1000]
        if not q:
            continue
        await DBX.execute(f"INSERT INTO {table}(question,created_at) VALUES(?,?)", (q, now))
        added += 1
    return added

async def _td_admin_delete(kind, qid):
    await _td_admin_schema()
    table = TD_ADMIN_KINDS[kind][1]
    await DBX.execute(f"DELETE FROM {table} WHERE id=?", (int(qid),))

async def _td_admin_clear(kind):
    await _td_admin_schema()
    table = TD_ADMIN_KINDS[kind][1]
    await DBX.execute(f"DELETE FROM {table}")

async def _td_admin_panel_message():
    await _td_admin_schema()
    counts = {k: await _td_admin_count(k) for k in TD_ADMIN_KINDS}
    return (
        "🛠 <b>مدیریت سراسری سؤال‌های جرأت و حقیقت</b>\n\n"
        "ادمین هر گروه می‌تواند سؤال ثبت کند؛ سؤال‌ها در دیتابیس مرکزی ذخیره می‌شوند و در همه گروه‌ها قابل استفاده‌اند.\n"
        "برای افزودن چند سؤال، هر سؤال را در یک خط جدا بفرست.\n\n"
        f"💙 جرأت: <b>{counts['dare']}</b> سؤال\n"
        f"❤️ حقیقت: <b>{counts['truth']}</b> سؤال\n"
        f"👩 دخترانه: <b>{counts['girl']}</b> سؤال\n"
        f"👨 پسرانه: <b>{counts['boy']}</b> سؤال"
    )

def _td_admin_panel_keyboard():
    return keyboard([
        [btn("💙 مدیریت جرأت", "tdadm:cat:dare"), btn("❤️ مدیریت حقیقت", "tdadm:cat:truth")],
        [btn("👩 مدیریت دخترانه", "tdadm:cat:girl"), btn("👨 مدیریت پسرانه", "tdadm:cat:boy")],
        [btn("📊 آمار همه دسته‌ها", "tdadm:stats")],
        [btn("❌ بستن پنل", "tdadm:close")],
    ])

def _td_admin_cat_keyboard(kind):
    return keyboard([
        [btn("➕ افزودن سؤال", f"tdadm:add:{kind}")],
        [btn("📋 نمایش سؤال‌ها", f"tdadm:list:{kind}:0")],
        [btn("🗑 حذف یک سؤال", f"tdadm:delhelp:{kind}")],
        [btn("♻️ پاک کردن همه", f"tdadm:clearask:{kind}")],
        [btn("⬅️ بازگشت", "tdadm:home")],
    ])

async def _td_admin_open(update, context):
    msg = update.effective_message
    user = update.effective_user
    if not msg or not user or (not await is_admin(update, user.id) and not await is_owner(user.id)):
        if msg:
            await msg.reply_text("⛔ فقط مالک ربات یا ادمین همین گروه می‌تواند سؤال‌های سراسری را مدیریت کند.")
        return True
    await msg.reply_text(await _td_admin_panel_message(), parse_mode="HTML", reply_markup=_td_admin_panel_keyboard())
    return True

async def _td_admin_callback(q, context):
    data = q.data or ""
    p = data.split(":")
    if len(p) < 2 or p[0] != "tdadm":
        return False
    if not await is_admin(q, q.from_user.id) and not await is_owner(q.from_user.id):
        await q.answer("⛔ فقط مالک ربات یا ادمین همین گروه دسترسی دارد.", show_alert=True)
        return True
    await _td_admin_schema()
    action = p[1]
    if action == "close":
        try: await q.answer()
        except Exception: pass
        try: await q.edit_message_text("❌ <b>پنل مدیریت سؤال‌ها بسته شد.</b>", parse_mode="HTML")
        except Exception: pass
        return True
    if action == "home":
        await q.answer()
        await q.edit_message_text(await _td_admin_panel_message(), parse_mode="HTML", reply_markup=_td_admin_panel_keyboard())
        return True
    if action == "stats":
        await q.answer()
        counts = {k: await _td_admin_count(k) for k in TD_ADMIN_KINDS}
        text = ("📊 <b>آمار سؤال‌ها</b>\n\n" + "\n".join(f"{TD_ADMIN_KINDS[k][0]}: <b>{counts[k]}</b>" for k in TD_ADMIN_KINDS))
        await q.edit_message_text(text, parse_mode="HTML", reply_markup=_td_admin_panel_keyboard())
        return True
    if action == "cat" and len(p) >= 3 and p[2] in TD_ADMIN_KINDS:
        kind = p[2]
        await q.answer()
        count = await _td_admin_count(kind)
        await q.edit_message_text(
            f"🛠 <b>{TD_ADMIN_KINDS[kind][0]}</b>\n\nتعداد فعلی: <b>{count}</b>\n\nیکی از گزینه‌ها را انتخاب کن:",
            parse_mode="HTML", reply_markup=_td_admin_cat_keyboard(kind))
        return True
    if action == "add" and len(p) >= 3 and p[2] in TD_ADMIN_KINDS:
        kind = p[2]
        TD_ADMIN_PENDING[q.from_user.id] = {"kind": kind, "mode": "add"}
        await q.answer("حالت افزودن فعال شد")
        await q.message.reply_text(
            f"➕ <b>افزودن سؤال به {TD_ADMIN_KINDS[kind][0]}</b>\n\n"
            "حالا سؤال‌ها را بفرست.\n"
            "هر سؤال در یک خط باشد؛ می‌توانی هر تعداد که خواستی در چند پیام اضافه کنی.\n\n"
            "برای لغو: لغو سوال", parse_mode="HTML")
        return True
    if action == "list" and len(p) >= 4 and p[2] in TD_ADMIN_KINDS:
        kind = p[2]; page = max(0, int(p[3])); per = 10
        rows = await _td_admin_questions(kind, per, page * per)
        total = await _td_admin_count(kind)
        if not rows:
            text = f"📋 <b>{TD_ADMIN_KINDS[kind][0]}</b>\n\nهنوز سؤالی ثبت نشده."
        else:
            lines = [f"📋 <b>{TD_ADMIN_KINDS[kind][0]}</b> — {page*per+1} تا {min(page*per+len(rows), total)} از {total}\n"]
            for i, r in enumerate(rows, page*per+1):
                lines.append(f"<b>{i}.</b> {safe_text(r['question'], 900)} [ID:{r['id']}]")
            text = "\n".join(lines)
        buttons = []
        nav = []
        if page > 0: nav.append(btn("⬅️ قبلی", f"tdadm:list:{kind}:{page-1}"))
        if (page+1)*per < total: nav.append(btn("➡️ بعدی", f"tdadm:list:{kind}:{page+1}"))
        if nav: buttons.append(nav)
        buttons.append([btn("⬅️ بازگشت", f"tdadm:cat:{kind}")])
        await q.answer()
        await q.edit_message_text(text, parse_mode="HTML", reply_markup=keyboard(buttons))
        return True
    if action == "delhelp" and len(p) >= 3 and p[2] in TD_ADMIN_KINDS:
        kind = p[2]
        TD_ADMIN_PENDING[q.from_user.id] = {"kind": kind, "mode": "delete"}
        await q.answer("حالت حذف فعال شد")
        await q.message.reply_text(
            f"🗑 <b>حذف سؤال از {TD_ADMIN_KINDS[kind][0]}</b>\n\n"
            "ID سؤال را بفرست.\nمثال: 25\n\nبرای لغو: لغو سوال", parse_mode="HTML")
        return True
    if action == "clearask" and len(p) >= 3 and p[2] in TD_ADMIN_KINDS:
        kind = p[2]
        TD_ADMIN_PENDING[q.from_user.id] = {"kind": kind, "mode": "clear_confirm"}
        await q.answer("تأیید لازم است")
        await q.message.reply_text(
            f"⚠️ می‌خواهی <b>همه</b> سؤال‌های {TD_ADMIN_KINDS[kind][0]} پاک شوند؟\n\n"
            "اگر مطمئنی بنویس: تأیید پاکسازی سوالات", parse_mode="HTML")
        return True
    return True

async def _td_admin_text(update, context):
    msg = update.effective_message
    user = update.effective_user
    if not msg or not user or not msg.text or (not await is_admin(update, user.id) and not await is_owner(user.id)):
        return False
    pending = TD_ADMIN_PENDING.get(user.id)
    if not pending:
        return False
    t = normalize(msg.text or "")
    if t in {"لغو سوال", "لغو", "انصراف"}:
        TD_ADMIN_PENDING.pop(user.id, None)
        await msg.reply_text("❌ عملیات لغو شد.")
        return True
    kind = pending["kind"]; mode = pending["mode"]
    if mode == "add":
        n = await _td_admin_add(kind, msg.text)
        if n:
            await msg.reply_text(f"✅ <b>{n}</b> سؤال به {TD_ADMIN_KINDS[kind][0]} اضافه شد.\n\nمی‌تونی پیام بعدی را هم بفرستی تا باز اضافه شود.", parse_mode="HTML")
        else:
            await msg.reply_text("⚠️ سؤال معتبری پیدا نشد. هر سؤال را در یک خط بفرست.")
        return True
    if mode == "delete":
        raw = msg.text.strip()
        if not raw.isdigit():
            await msg.reply_text("❌ فقط ID عددی سؤال را بفرست.")
            return True
        await _td_admin_delete(kind, int(raw))
        TD_ADMIN_PENDING.pop(user.id, None)
        await msg.reply_text(f"✅ سؤال با ID {raw} حذف شد.", parse_mode="HTML")
        return True
    if mode == "clear_confirm":
        if t == "تأیید پاکسازی سوالات":
            await _td_admin_clear(kind)
            TD_ADMIN_PENDING.pop(user.id, None)
            await msg.reply_text(f"♻️ همه سؤال‌های {TD_ADMIN_KINDS[kind][0]} پاک شدند.")
        else:
            await msg.reply_text("برای انجام پاکسازی دقیقاً بنویس: تأیید پاکسازی سوالات", parse_mode="HTML")
        return True
    return False

# اتصال پنل مدیریت به روترهای نهایی بدون دست‌زدن به منطق قبلی.
_OLD_TD_ADMIN_MESSAGE_ROUTER = message_router_v9
async def message_router_v9(update, context):
    if await _td_admin_text(update, context):
        return
    msg = update.effective_message
    if msg and msg.text and normalize(msg.text or "") in {
        "مدیریت سوالات جرأت حقیقت", "مدیریت سوالات جرعت حقیقت",
        "پنل سوالات جرأت حقیقت", "پنل سوالات جرعت حقیقت",
        "تنظیم سوالات جرأت حقیقت", "تنظیم سوالات جرعت حقیقت",
        "مدیریت سوالات بازی"
    }:
        await _td_admin_open(update, context)
        return
    return await _OLD_TD_ADMIN_MESSAGE_ROUTER(update, context)

_OLD_TD_ADMIN_CALLBACK_ROUTER = callback_router_v10
async def callback_router_v10(update, context):
    q = getattr(update, "callback_query", None)
    if q and (q.data or "").startswith("tdadm:"):
        return await _td_admin_callback(q, context)
    return await _OLD_TD_ADMIN_CALLBACK_ROUTER(update, context)

def build_application(token: str) -> Application:
    app=ApplicationBuilder().token(token).post_init(post_init_vip_pro).post_shutdown(post_shutdown).build()
    for name,fn in [('start',start_v8),('help',cmd_help),('panel',cmd_panel),('adminpanel',cmd_adminpanel),('owner',owner_panel_v6),('features',cmd_features),('rules',rules_command),('setrules',set_rules),('welcome',set_welcome),('togglewelcome',toggle_welcome),('goodbye',set_goodbye),('togglegoodbye',toggle_goodbye),('forcejoin',forcejoin_v4),('stats',stats_v4_command)]:
        app.add_handler(CommandHandler(name,fn))
    app.add_handler(CommandHandler('cleanup',lambda u,c:cleanup_v4(u,c,500)))
    app.add_handler(CommandHandler('warn',lambda u,c:moderation_action(u,c,'warn')))
    app.add_handler(CommandHandler('unwarn',lambda u,c:moderation_action(u,c,'unwarn')))
    app.add_handler(CommandHandler('mute',lambda u,c:mute_command_v6(u,c)))
    app.add_handler(CommandHandler('unmute',lambda u,c:moderation_v4(u,c,'unmute')))
    app.add_handler(CommandHandler('ban',lambda u,c:moderation_v4(u,c,'ban')))
    app.add_handler(CommandHandler('unban',lambda u,c:moderation_v4(u,c,'unban')))
    app.add_handler(CommandHandler('mafia',lambda u,c:mafia_start_menu(u,c)))
    app.add_handler(ChatMemberHandler(member_update_v6,ChatMemberHandler.CHAT_MEMBER))
    app.add_handler(CallbackQueryHandler(callback_router_v10))
    if MessageReactionHandler is not None: app.add_handler(MessageReactionHandler(reaction_handler))
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS,service_members_v4))
    app.add_handler(MessageHandler(filters.StatusUpdate.LEFT_CHAT_MEMBER,service_members_v4))
    app.add_handler(MessageHandler(filters.LOCATION,location_v4))
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,message_router_v9))
    app.add_error_handler(error_handler)
    return app


