BB_LIFE_PENDING = {}
BB_REMINDER_TASK = None
BB_REMINDER_STOP = None

async def ensure_life_tools_schema():
    await DBX.execute("""CREATE TABLE IF NOT EXISTS bb_notes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        chat_id INTEGER NOT NULL DEFAULT 0,
        title TEXT NOT NULL DEFAULT '',
        content TEXT NOT NULL,
        created_at INTEGER NOT NULL DEFAULT 0,
        updated_at INTEGER NOT NULL DEFAULT 0
    )""")
    await DBX.execute("""CREATE INDEX IF NOT EXISTS idx_bb_notes_user ON bb_notes(user_id,id DESC)""")
    await DBX.execute("""CREATE TABLE IF NOT EXISTS bb_reminders (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        chat_id INTEGER NOT NULL,
        text TEXT NOT NULL,
        due_at INTEGER NOT NULL,
        created_at INTEGER NOT NULL DEFAULT 0,
        sent_at INTEGER NOT NULL DEFAULT 0,
        cancelled INTEGER NOT NULL DEFAULT 0
    )""")
    await DBX.execute("""CREATE INDEX IF NOT EXISTS idx_bb_reminders_due ON bb_reminders(sent_at,cancelled,due_at)""")


def _bb_digits(s):
    return str(s or '').translate(str.maketrans('۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩','01234567890123456789'))


def _bb_escape(s, n=3500):
    return safe_text(str(s or ''), n)


def _bb_note_panel_text(uid):
    return (
        "📝 <b>دفترچه یادداشت بیل بیلک</b>\n\n"
        "یادداشت‌هات فقط به حساب خودت وصل می‌شن و با ری‌استارت ربات پاک نمی‌شن.\n\n"
        "• برای افزودن: یادداشت متن یادداشت\n"
        "• برای عنوان‌دار: یادداشت | عنوان | متن\n"
        "• دیدن: یادداشت‌ها\n"
        "• حذف: حذف یادداشت ID"
    )


async def _bb_notes_list(uid, limit=12):
    return await DBX.execute(
        "SELECT id,title,content,created_at,updated_at FROM bb_notes WHERE user_id=? ORDER BY id DESC LIMIT ?",
        (uid, max(1,min(30,int(limit or 12)))), fetch=True
    )


async def _bb_note_add(uid, chat_id, content, title=''):
    now=now_ts()
    content=_bb_escape(content,4000).strip()
    title=_bb_escape(title,120).strip()
    if not content: return None
    await DBX.execute(
        "INSERT INTO bb_notes(user_id,chat_id,title,content,created_at,updated_at) VALUES(?,?,?,?,?,?)",
        (uid,chat_id,title,content,now,now)
    )
    row=await DBX.one("SELECT id FROM bb_notes WHERE user_id=? ORDER BY id DESC LIMIT 1",(uid,))
    return int(row['id']) if row else None


async def _bb_note_delete(uid, note_id):
    row=await DBX.one("SELECT id FROM bb_notes WHERE user_id=? AND id=?",(uid,int(note_id)))
    if not row: return False
    await DBX.execute("DELETE FROM bb_notes WHERE user_id=? AND id=?",(uid,int(note_id)))
    return True


def _bb_format_notes(rows):
    if not rows:
        return "📝 <b>یادداشت‌ها</b>\n\nهنوز هیچ یادداشتی نداری."
    out=["📝 <b>یادداشت‌های تو</b>",""]
    for r in rows:
        title=f" — {r['title']}" if r['title'] else ''
        text=_bb_escape(r['content'],500)
        out.append(f"🆔 {r['id']}{_bb_escape(title,140)}\n{text}\n")
    return '\n'.join(out)[:3900]


def _bb_parse_reminder(raw):
    """پشتیبانی از: 10 دقیقه بعد، 2 ساعت بعد، 1 روز بعد، امروز 18:30، فردا 18:30، 18:30."""
    text=_bb_digits(str(raw or '').strip())
    if not text: return None,None
    now=datetime.now()
    patterns=[
        (r'^(\d+)\s*(?:دقیقه|دقیقه‌ای|دقيقه)\s*(?:بعد|دیگه|دیگر)\s+(.+)$', 'minutes'),
        (r'^(\d+)\s*(?:ساعت|ساعته)\s*(?:بعد|دیگه|دیگر)\s+(.+)$', 'hours'),
        (r'^(\d+)\s*(?:روز|روزه)\s*(?:بعد|دیگه|دیگر)\s+(.+)$', 'days'),
    ]
    for pat,unit in patterns:
        m=re.match(pat,text,re.I)
        if m:
            num=int(m.group(1)); body=m.group(2).strip()
            if num<1 or not body: return None,None
            delta={'minutes':timedelta(minutes=num),'hours':timedelta(hours=num),'days':timedelta(days=num)}[unit]
            return int((now+delta).timestamp()),body
    m=re.match(r'^(?:(امروز|فردا)\s+)?(\d{1,2}):(\d{2})\s+(.+)$',text,re.I)
    if m:
        dayword=m.group(1) or 'امروز'; hh=int(m.group(2)); mm=int(m.group(3)); body=m.group(4).strip()
        if hh>23 or mm>59 or not body: return None,None
        d=now.date()+timedelta(days=1 if dayword=='فردا' else 0)
        dt=datetime(d.year,d.month,d.day,hh,mm)
        if dayword=='امروز' and dt.timestamp()<=time.time(): dt+=timedelta(days=1)
        return int(dt.timestamp()),body
    return None,None


async def _bb_reminder_add(uid,chat_id,due_at,text):
    now=now_ts()
    await DBX.execute("INSERT INTO bb_reminders(user_id,chat_id,text,due_at,created_at) VALUES(?,?,?,?,?)",
                      (uid,chat_id,_bb_escape(text,1200),int(due_at),now))
    row=await DBX.one("SELECT id FROM bb_reminders WHERE user_id=? ORDER BY id DESC LIMIT 1",(uid,))
    return int(row['id']) if row else None


async def _bb_reminder_list(uid,limit=12):
    return await DBX.execute(
        "SELECT id,text,due_at FROM bb_reminders WHERE user_id=? AND cancelled=0 AND sent_at=0 ORDER BY due_at ASC LIMIT ?",
        (uid,max(1,min(30,int(limit or 12)))),fetch=True)


async def _bb_reminder_delete(uid,rid):
    row=await DBX.one("SELECT id FROM bb_reminders WHERE user_id=? AND id=? AND sent_at=0 AND cancelled=0",(uid,int(rid)))
    if not row: return False
    await DBX.execute("UPDATE bb_reminders SET cancelled=1 WHERE user_id=? AND id=?",(uid,int(rid)))
    return True


async def _bb_reminder_loop(application):
    while True:
        try:
            now=int(time.time())
            rows=await DBX.execute(
                "SELECT id,user_id,chat_id,text FROM bb_reminders WHERE due_at<=? AND sent_at=0 AND cancelled=0 ORDER BY due_at ASC LIMIT 30",
                (now,),fetch=True)
            for r in rows or []:
                rid=int(r['id'])
                # علامت ارسال قبل از Telegram call: اگر شبکه کند شد، یک reminder دوبار ارسال نمی‌شود.
                await DBX.execute("UPDATE bb_reminders SET sent_at=? WHERE id=? AND sent_at=0",(now,rid))
                try:
                    await application.bot.send_message(
                        chat_id=int(r['chat_id']),
                        text=("⏰ <b>یادآوری بیل بیلک</b>\n\n"+_bb_escape(r['text'],3000)),
                        parse_mode='HTML'
                    )
                except Exception as exc:
                    log.warning('reminder send %s failed: %r',rid,exc)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            log.warning('reminder loop: %r',exc)
        await asyncio.sleep(15)


# ------------------------- Recipe engine -------------------------
BB_RECIPE_CATALOG={
    'املت': ('🍳 املت ساده', ['تخم‌مرغ','گوجه‌فرنگی','نمک','فلفل','کمی روغن'], ['گوجه را خرد و کمی تفت بده.','تخم‌مرغ‌ها را اضافه کن و هم بزن.','نمک و فلفل بزن و تا بسته‌شدن تخم‌مرغ‌ها بپز.']),
    'نیمرو': ('🍳 نیمرو', ['تخم‌مرغ','کمی روغن یا کره','نمک'], ['تابه را گرم کن و روغن را اضافه کن.','تخم‌مرغ را بشکن و با حرارت ملایم بپز.','در پایان کمی نمک اضافه کن.']),
    'پاستا': ('🍝 پاستای ساده', ['پاستا','سس گوجه','پیاز','نمک','فلفل','کمی روغن'], ['پاستا را طبق بسته‌بندی در آب جوش بپز.','پیاز را تفت بده و سس گوجه را اضافه کن.','پاستا را آبکش و با سس مخلوط کن.']),
    'ماکارونی': ('🍝 ماکارونی', ['ماکارونی','پیاز','گوشت یا سویا (اختیاری)','رب گوجه','نمک','فلفل','زردچوبه'], ['ماکارونی را در آب جوش نیم‌پز کن.','پیاز و مواد دلخواه را تفت بده و رب را اضافه کن.','مواد را با ماکارونی مخلوط کن و با حرارت ملایم دم بده.']),
    'پنکیک': ('🥞 پنکیک ساده', ['آرد','تخم‌مرغ','شیر','کمی شکر','بکینگ‌پودر'], ['مواد را تا یکدست‌شدن مخلوط کن.','تابه نچسب را با حرارت متوسط گرم کن.','هر طرف پنکیک را تا طلایی‌شدن بپز.']),
    'کیک': ('🍰 کیک ساده', ['آرد','تخم‌مرغ','شکر','شیر','روغن','بکینگ‌پودر','وانیل'], ['تخم‌مرغ و شکر را مخلوط کن.','شیر و روغن را اضافه و سپس آرد و بکینگ‌پودر را کم‌کم اضافه کن.','در قالب بریز و در فر از قبل گرم‌شده تا پخت کامل بپز.']),
    'سیب زمینی': ('🥔 سیب‌زمینی تنوری', ['سیب‌زمینی','روغن','نمک','فلفل'], ['سیب‌زمینی را بشوی و تکه‌ای کن.','با روغن، نمک و فلفل مخلوط کن.','در فر داغ تا طلایی و نرم‌شدن بپز.']),
    'سوپ': ('🍲 سوپ ساده', ['پیاز','هویج','سیب‌زمینی','آب یا آب مرغ','نمک','فلفل'], ['پیاز را کمی تفت بده.','هویج و سیب‌زمینی را اضافه و آب را روی مواد بریز.','تا نرم‌شدن مواد بپز و در پایان مزه را تنظیم کن.']),
}


def _bb_recipe_local(name):
    n=normalize(name).strip()
    for key,val in BB_RECIPE_CATALOG.items():
        if normalize(key) in n or n in normalize(key):
            title,ings,steps=val
            return title,ings,steps
    return None


async def _bb_recipe_ai(name):
    if not name: return None
    prompt=("برای غذای زیر یک دستور پخت خانگی و ایمن به فارسی محاوره‌ای بده. "
            "فقط این بخش‌ها را داشته باش: مواد لازم، مراحل، زمان تقریبی، نکته. "
            "از مواد خطرناک یا دستورهای غیرخوراکی استفاده نکن. غذا: "+_bb_escape(name,160))
    try:
        ans=await _bb_ultra_ai_call(prompt,verbosity='long',tone='polite',memory_enabled=False,timeout=7)
        return ans
    except Exception:
        return None


async def _bb_recipe_show(update,name):
    msg=update.effective_message
    local=_bb_recipe_local(name)
    if local:
        title,ings,steps=local
        text="🍽️ <b>"+_bb_escape(title,100)+"</b>\n\n<b>🧺 مواد لازم:</b>\n"+"\n".join("• "+_bb_escape(x,100) for x in ings)+"\n\n<b>👨‍🍳 مراحل:</b>\n"+"\n".join(f"{i+1}. "+_bb_escape(x,500) for i,x in enumerate(steps))+"\n\n💡 <b>نکته:</b> مقدار مواد را با تعداد نفرات تنظیم کن."
        await msg.reply_text(text,parse_mode='HTML'); return True
    ans=await _bb_recipe_ai(name)
    if ans:
        await msg.reply_text("🍽️ <b>دستور پخت "+_bb_escape(name,120)+"</b>\n\n"+_bb_escape(ans,3500),parse_mode='HTML'); return True
    await msg.reply_text("🍽️ اسم غذا را بفرست؛ مثلاً دستور پخت پاستا یا دستور پخت کیک.\n\nبرای غذاهای ناشناخته اگر OpenRouter در ربات تنظیم شده باشد، دستور را هوشمندانه می‌سازم.",parse_mode='HTML')
    return True


async def _bb_life_panel(update):
    msg=update.effective_message
    text=("🧠 <b>مرکز زندگی بیل بیلک</b>\n\n"
          "📝 <b>یادداشت</b> — ذخیره و مدیریت یادداشت‌های شخصی\n"
          "⏰ <b>یادآوری</b> — یادآوری زمان‌دار حتی بعد از ری‌استارت\n"
          "🍳 <b>دستور پخت</b> — دستور غذاهای معروف و تولید دستور برای غذای درخواستی\n\n"
          "مثال‌ها:\n"
          "یادداشت | خرید | شیر و نان بخر\n"
          "یادآوری 30 دقیقه بعد درس بخون\n"
          "یادآوری فردا 18:30 تکلیفم رو انجام بدم\n"
          "دستور پخت پاستا")
    await msg.reply_text(text,parse_mode='HTML',reply_markup=keyboard([
        [btn('📝 یادداشت‌ها','bblife:notes'),btn('➕ یادداشت جدید','bblife:newnote')],
        [btn('⏰ یادآوری‌ها','bblife:reminders'),btn('➕ یادآوری','bblife:newreminder')],
        [btn('🍳 دستور پخت','bblife:recipe')],
        [btn('❌ بستن پنل','bblife:close')]
    ]))


async def _bb_life_callback(q,context):
    data=q.data or ''
    if not data.startswith('bblife:'): return False
    uid=int(q.from_user.id); action=data.split(':',1)[1]
    await q.answer()
    if action=='close':
        try: await q.message.delete()
        except Exception: pass
        return True
    if action=='notes':
        rows=await _bb_notes_list(uid)
        await q.message.edit_text(_bb_format_notes(rows),parse_mode='HTML',reply_markup=keyboard([[btn('➕ یادداشت جدید','bblife:newnote')],[btn('🏠 مرکز زندگی','bblife:home')]])); return True
    if action=='reminders':
        rows=await _bb_reminder_list(uid)
        if not rows: text='⏰ <b>یادآوری‌ها</b>\n\nیادآوری فعالی نداری.'
        else:
            text='⏰ <b>یادآوری‌های فعال</b>\n\n'
            for r in rows:
                dt=datetime.fromtimestamp(int(r['due_at'])).strftime('%Y-%m-%d %H:%M')
                text+=f"🆔 {r['id']} — {dt}\n{_bb_escape(r['text'],400)}\n\n"
        await q.message.edit_text(text[:3900],parse_mode='HTML',reply_markup=keyboard([[btn('➕ یادآوری جدید','bblife:newreminder')],[btn('🏠 مرکز زندگی','bblife:home')]])); return True
    if action=='newnote':
        BB_LIFE_PENDING[uid]={'type':'note','chat_id':q.message.chat.id}
        await q.message.edit_text("📝 <b>یادداشت جدید</b>\n\nحالا متن یادداشت را بفرست.\nبرای عنوان‌دار کردن: عنوان | متن\n\nلغو: لغو",parse_mode='HTML'); return True
    if action=='newreminder':
        BB_LIFE_PENDING[uid]={'type':'reminder','chat_id':q.message.chat.id}
        await q.message.edit_text("⏰ <b>یادآوری جدید</b>\n\nیکی از این قالب‌ها را بفرست:\n30 دقیقه بعد درس بخون\n2 ساعت بعد آب بخور\nفردا 18:30 تکلیفم\n18:30 فیلم ببین\n\nلغو: لغو",parse_mode='HTML'); return True
    if action=='recipe':
        BB_LIFE_PENDING[uid]={'type':'recipe','chat_id':q.message.chat.id}
        await q.message.edit_text("🍳 <b>دستور پخت</b>\n\nاسم غذا را بفرست؛ مثلاً:\nپاستا\nاملت\nکیک شکلاتی\n\nلغو: لغو",parse_mode='HTML'); return True
    if action=='home':
        # Telegram message edit برای پنل اصلی
        await q.message.edit_text("🧠 <b>مرکز زندگی بیل بیلک</b>\n\n📝 یادداشت | ⏰ یادآوری | 🍳 دستور پخت",parse_mode='HTML',reply_markup=keyboard([
            [btn('📝 یادداشت‌ها','bblife:notes'),btn('➕ یادداشت جدید','bblife:newnote')],
            [btn('⏰ یادآوری‌ها','bblife:reminders'),btn('➕ یادآوری','bblife:newreminder')],
            [btn('🍳 دستور پخت','bblife:recipe')],[btn('❌ بستن پنل','bblife:close')]
        ])); return True
    return True


async def _bb_life_text(update,context):
    msg=update.effective_message
    if not msg or not msg.text or not update.effective_user: return False
    uid=int(update.effective_user.id); raw=msg.text.strip(); t=normalize(raw)
    pending=BB_LIFE_PENDING.get(uid)
    if pending:
        if t in {'لغو','انصراف','لغو عملیات'}:
            BB_LIFE_PENDING.pop(uid,None); await msg.reply_text('❌ عملیات لغو شد.'); return True
        typ=pending.get('type')
        if typ=='note':
            title=''; content=raw
            if '|' in raw:
                title,content=[x.strip() for x in raw.split('|',1)]
            nid=await _bb_note_add(uid,msg.chat.id,content,title)
            BB_LIFE_PENDING.pop(uid,None)
            await msg.reply_text(f'✅ یادداشت ذخیره شد.\n🆔 {nid}',parse_mode='HTML'); return True
        if typ=='reminder':
            due,body=_bb_parse_reminder(raw)
            if not due:
                await msg.reply_text('⚠️ قالب یادآوری درست نیست. نمونه: 30 دقیقه بعد درس بخون',parse_mode='HTML'); return True
            rid=await _bb_reminder_add(uid,msg.chat.id,due,body)
            BB_LIFE_PENDING.pop(uid,None)
            when=datetime.fromtimestamp(due).strftime('%Y-%m-%d %H:%M')
            await msg.reply_text(f'✅ یادآوری ثبت شد.\n🆔 {rid}\n🕐 {when}\n📝 {_bb_escape(body,800)}',parse_mode='HTML'); return True
        if typ=='recipe':
            BB_LIFE_PENDING.pop(uid,None)
            return await _bb_recipe_show(update,raw)
    if t in {'یادداشت','دفترچه یادداشت','یادداشت ها','یادداشت‌ها','notes'}:
        await _bb_life_panel(update); return True
    if t in {'یادآوری ها','یادآوری‌ها','reminders'}:
        rows=await _bb_reminder_list(uid)
        if not rows: await msg.reply_text('⏰ یادآوری فعالی نداری.'); return True
        out=['⏰ <b>یادآوری‌های فعال</b>','']
        for r in rows:
            out.append(f"🆔 {r['id']} — {datetime.fromtimestamp(int(r['due_at'])).strftime('%Y-%m-%d %H:%M')}\n{_bb_escape(r['text'],500)}")
        await msg.reply_text('\n\n'.join(out)[:3900],parse_mode='HTML'); return True
    if t.startswith('حذف یادداشت '):
        x=_bb_digits(t.split()[-1])
        if x.isdigit():
            ok=await _bb_note_delete(uid,int(x)); await msg.reply_text('🗑️ یادداشت حذف شد.' if ok else '❌ چنین یادداشتی پیدا نشد.'); return True
    if t.startswith('حذف یادآوری '):
        x=_bb_digits(t.split()[-1])
        if x.isdigit():
            ok=await _bb_reminder_delete(uid,int(x)); await msg.reply_text('🗑️ یادآوری لغو شد.' if ok else '❌ چنین یادآوری فعالی پیدا نشد.'); return True
    if t.startswith('یادداشت |') or t.startswith('یادداشت|'):
        payload=raw.split('|',1)[1].strip() if '|' in raw else ''
        if '|' in payload:
            title,content=[x.strip() for x in payload.split('|',1)]
        else: title=''; content=payload
        nid=await _bb_note_add(uid,msg.chat.id,content,title)
        await msg.reply_text(f'✅ یادداشت ذخیره شد. 🆔 {nid}',parse_mode='HTML'); return True
    if t.startswith('یادداشت '):
        content=raw.split(None,1)[1].strip(); nid=await _bb_note_add(uid,msg.chat.id,content)
        await msg.reply_text(f'✅ یادداشت ذخیره شد. 🆔 {nid}',parse_mode='HTML'); return True
    if t.startswith('یادآوری '):
        due,body=_bb_parse_reminder(raw.split(None,1)[1])
        if not due:
            await msg.reply_text('⏰ نمونه درست: یادآوری 30 دقیقه بعد درس بخون یا یادآوری فردا 18:30 تکلیفم',parse_mode='HTML'); return True
        rid=await _bb_reminder_add(uid,msg.chat.id,due,body)
        when=datetime.fromtimestamp(due).strftime('%Y-%m-%d %H:%M')
        await msg.reply_text(f'✅ یادآوری ثبت شد. 🆔 {rid}\n🕐 {when}',parse_mode='HTML'); return True
    if t in {'دستور پخت','رسپی','recipe'}:
        BB_LIFE_PENDING[uid]={'type':'recipe','chat_id':msg.chat.id}
        await msg.reply_text('🍳 اسم غذا را بفرست؛ مثلاً دستور پخت پاستا.',parse_mode='HTML'); return True
    if t.startswith('دستور پخت '):
        return await _bb_recipe_show(update,raw.split(None,2)[-1])
    if t.startswith('طرز تهیه '):
        return await _bb_recipe_show(update,raw.split(None,2)[-1])
    return False


# Final router layer: life tools run before the older generic text router.
_OLD_LIFE_MESSAGE_ROUTER=message_router_v9
async def message_router_v9(update,context):
    try:
        if await _bb_life_text(update,context): return
    except Exception as exc:
        log.exception('life tools message router failed: %r',exc)
    return await _OLD_LIFE_MESSAGE_ROUTER(update,context)

_OLD_LIFE_CALLBACK_ROUTER=callback_router_v10
async def callback_router_v10(update,context):
    q=getattr(update,'callback_query',None)
    if q and (q.data or '').startswith('bblife:'):
        try: return await _bb_life_callback(q,context)
        except Exception as exc:
            log.exception('life tools callback failed: %r',exc)
            try: await q.answer('خطا در پنل',show_alert=True)
            except Exception: pass
            return True
    return await _OLD_LIFE_CALLBACK_ROUTER(update,context)



# =============================================================================
# FINAL CLEANUP ACCOUNT — TERMINAL LOGIN + RELIABLE REPORT
# =============================================================================
# ورود اکانت پاکسازی، مثل اکانت موزیکال، فقط از ترمینال انجام می‌شود.
# کد ورود و رمز دومرحله‌ای هرگز از طریق چت درخواست نمی‌شوند.

async def _bb_cleanup_terminal_login_pro():
    global CLEANUP_USER_CLIENT, CLEANUP_USER_CODE_HASH
    global CLEANUP_USER_LOGIN_STATE, CLEANUP_USER_PHONE, CLEANUP_USER_SESSION

    if CLEANUP_USER_CLIENT is not None and getattr(CLEANUP_USER_CLIENT, 'is_connected', False):
        try:
            me = await CLEANUP_USER_CLIENT.get_me()
            if me:
                CLEANUP_USER_LOGIN_STATE = 'ready'
                return True, me
        except Exception:
            pass

    # Never block a daemon/container that has no interactive terminal.
    try:
        if not hasattr(sys.stdin, 'isatty') or not sys.stdin.isatty():
            return False, 'ترمینال تعاملی در دسترس نیست.'
    except Exception:
        return False, 'ترمینال تعاملی در دسترس نیست.'

    api_id, api_hash, phone, session, row = await _bb_cleanup_settings_snapshot()
    if not api_id or not str(api_id).isdigit():
        api_id = (await asyncio.to_thread(input, '🆔 TELEGRAM_API_ID اکانت پاکسازی: ')).strip()
    if not api_hash:
        api_hash = (await asyncio.to_thread(input, '🔑 TELEGRAM_API_HASH اکانت پاکسازی: ')).strip()
    if not phone:
        phone = (await asyncio.to_thread(input, '📱 شماره اکانت پاکسازی: ')).strip()
    if not session:
        session = str(Path.home() / 'bilbilak_cleanup_user')

    if not (api_id and str(api_id).isdigit() and api_hash and phone):
        return False, 'اطلاعات API ID/API Hash/شماره کامل نیست.'

    CLEANUP_USER_PHONE = phone
    CLEANUP_USER_SESSION = session
    base = Path(session).expanduser()
    if base.suffix == '.session':
        base = base.with_suffix('')
    base.parent.mkdir(parents=True, exist_ok=True)

    def new_client():
        return _bb_pyrogram_client(api_id, api_hash, str(base), phone, 'bilbilak_cleanup_user')

    client = new_client()
    try:
        await client.connect()
        try:
            me = await client.get_me()
        except Exception as exc:
            if 'AUTH_KEY_UNREGISTERED' in str(exc).upper():
                try: await client.disconnect()
                except Exception: pass
                await _bb_cleanup_remove_session_files(str(base))
                client = new_client()
                await client.connect()
                me = None
            else:
                raise

        if me:
            CLEANUP_USER_CLIENT = client
            CLEANUP_USER_LOGIN_STATE = 'ready'
            await _bb_cleanup_save(phone=phone, session=str(base), account_user_id=me.id,
                                   account_name=display_name(me), status='متصل')
            return True, me

        # No authorized session: start a fresh terminal login.
        sent = await client.send_code(phone)
        CLEANUP_USER_CLIENT = client
        CLEANUP_USER_CODE_HASH = sent.phone_code_hash
        CLEANUP_USER_LOGIN_STATE = 'code'
        print('\n📩 کد ورود اکانت پاکسازی ارسال شد.')
        code = (await asyncio.to_thread(input, '🔐 کد ورود تلگرام اکانت پاکسازی: ')).strip().replace(' ', '')
        if not code:
            raise RuntimeError('کد ورود وارد نشد.')
        try:
            await client.sign_in(phone, sent.phone_code_hash, code)
        except Exception as exc:
            if 'SessionPasswordNeeded' in type(exc).__name__ or 'PASSWORD' in str(exc).upper():
                CLEANUP_USER_LOGIN_STATE = '2fa'
                password = await asyncio.to_thread(input, '🔑 رمز دومرحله‌ای اکانت پاکسازی: ')
                await client.check_password(password.strip())
            else:
                raise

        me = await client.get_me()
        if not me:
            raise RuntimeError('اکانت پاکسازی بعد از ورود شناسایی نشد.')
        CLEANUP_USER_CLIENT = client
        CLEANUP_USER_CODE_HASH = None
        CLEANUP_USER_LOGIN_STATE = 'ready'
        await _bb_cleanup_save(phone=phone, session=str(base), account_user_id=me.id,
                               account_name=display_name(me), status='متصل')
        print(f'✅ اکانت پاکسازی متصل شد: {display_name(me)} ({me.id})')
        return True, me
    except Exception as exc:
        try:
            if client is not None and getattr(client, 'is_connected', False):
                await client.disconnect()
        except Exception:
            pass
        CLEANUP_USER_CLIENT = None
        CLEANUP_USER_CODE_HASH = None
        CLEANUP_USER_LOGIN_STATE = None
        return False, f'{type(exc).__name__}: {exc}'


async def _bb_cleanup_terminal_report(chat_id, requester_id, mode='all', count=5000):
    """Run cleanup through the personal cleanup account and always return a report."""
    started = time.time()
    result = await _bb_cleanup_run(chat_id, requester_id, mode, count)
    elapsed = round(time.time() - started, 2)
    result['elapsed'] = elapsed
    return result


async def _bb_cleanup_startup_pro(application):
    """Reuse the saved cleanup Session; if absent/invalid, request login in terminal."""
    try:
        ok, me = await _bb_cleanup_terminal_login_pro()
        if ok:
            log.info('Cleanup personal account ready: id=%s username=%s',
                     getattr(me, 'id', 0), getattr(me, 'username', None))
        else:
            log.warning('Cleanup personal account is not ready: %s', me)
    except Exception as exc:
        log.exception('Cleanup terminal login failed: %s', exc)


_OLD_LIFE_POST_INIT=post_init_vip_pro
async def post_init_vip_pro(application):
    global BB_REMINDER_TASK
    await _OLD_LIFE_POST_INIT(application)
    await ensure_life_tools_schema()
    await _bb_cleanup_startup_pro(application)
    if BB_REMINDER_TASK and not BB_REMINDER_TASK.done():
        return
    BB_REMINDER_TASK=asyncio.create_task(_bb_reminder_loop(application))

_OLD_LIFE_POST_SHUTDOWN=post_shutdown
async def post_shutdown(application):
    global BB_REMINDER_TASK
    if BB_REMINDER_TASK:
        BB_REMINDER_TASK.cancel()
        try: await BB_REMINDER_TASK
        except asyncio.CancelledError: pass
        except Exception: pass
        BB_REMINDER_TASK=None
    return await _OLD_LIFE_POST_SHUTDOWN(application)

# Add a normal command alias too; Persian text commands are handled by the router.
def _bb_life_command(update,context):
    return _bb_life_panel(update)

# Final application builder keeps every previously-added feature and registers the
# life tools through the final message/callback routers above.
def build_application(token: str) -> Application:
    app=ApplicationBuilder().token(token).post_init(post_init_vip_pro).post_shutdown(post_shutdown).build()
    for name,fn in [('start',start_v8),('help',cmd_help),('panel',cmd_panel),('adminpanel',cmd_adminpanel),('owner',owner_panel_v6),('features',cmd_features),('rules',rules_command),('setrules',set_rules),('welcome',set_welcome),('togglewelcome',toggle_welcome),('goodbye',set_goodbye),('togglegoodbye',toggle_goodbye),('forcejoin',forcejoin_v4),('stats',stats_v4_command)]:
        app.add_handler(CommandHandler(name,fn))
    app.add_handler(CommandHandler('cleanup',lambda u,c:cleanup_v4(u,c,500)))
    app.add_handler(CommandHandler('warn',lambda u,c:moderation_action(u,c,'warn')))
    app.add_handler(CommandHandler('unwarn',lambda u,c:moderation_action(u,c,'unwarn')))
    app.add_handler(CommandHandler('mute',lambda u,c:mute_command_v6(u,c)))
    app.add_handler(CommandHandler('unmute',lambda u,c:moderation_v4(u,c,'unmute')))
    app.add_handler(CommandHandler('ban',lambda u,c:moderation_v4(u,c,'ban')))
    app.add_handler(CommandHandler('unban',lambda u,c:moderation_v4(u,c,'unban')))
    app.add_handler(CommandHandler('mafia',lambda u,c:mafia_start_menu(u,c)))
    app.add_handler(CommandHandler('life',_bb_life_command))
    app.add_handler(ChatMemberHandler(member_update_v6,ChatMemberHandler.CHAT_MEMBER))
    app.add_handler(CallbackQueryHandler(callback_router_v10))
    if MessageReactionHandler is not None: app.add_handler(MessageReactionHandler(reaction_handler))
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS,service_members_v4))
    app.add_handler(MessageHandler(filters.StatusUpdate.LEFT_CHAT_MEMBER,service_members_v4))
    app.add_handler(MessageHandler(filters.LOCATION,location_v4))
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,message_router_v9))
    app.add_error_handler(error_handler)
    return app


