# FINAL CALLBACK COMPATIBILITY + DATE/GROUP-LINK FIX 2026-09-12
# =============================================================================
# PTB CallbackQueryHandler passes an Update object. Several historical layers in
# this large single-file bot were written to receive CallbackQuery directly.
# This adapter exposes BOTH interfaces, so old and new layers can coexist.
class _BBCallbackCompat:
    def __init__(self, update):
        self._update = update
        self.callback_query = getattr(update, 'callback_query', None)
    def __getattr__(self, name):
        q = self.callback_query
        if q is not None and hasattr(q, name):
            return getattr(q, name)
        return getattr(self._update, name)

# Final callback entry point: normalize once, then let the complete historical
# callback chain run without Update/CallbackQuery type mismatches.
_OLD_FINAL_LIFE_CALLBACK_ROUTER = callback_router_v10
async def callback_router_v10(update, context):
    q = getattr(update, 'callback_query', None)
    if not q:
        return
    compat = _BBCallbackCompat(update)
    try:
        return await _OLD_FINAL_LIFE_CALLBACK_ROUTER(compat, context)
    except Exception as exc:
        log.exception('final callback router failed: %r', exc)
        try:
            await q.answer('⚠️ این دکمه فعلاً با خطا روبه‌رو شد؛ دوباره امتحان کن.', show_alert=True)
        except Exception:
            pass
        return True

# ---------- Persian/Gregorian/Islamic date helpers ----------
def _bb_fa_digits(value):
    return str(value).translate(str.maketrans('0123456789', '۰۱۲۳۴۵۶۷۸۹'))

_BB_FA_WEEKDAYS = {
    0:'دوشنبه', 1:'سه‌شنبه', 2:'چهارشنبه', 3:'پنجشنبه',
    4:'جمعه', 5:'شنبه', 6:'یکشنبه'
}
_BB_EN_MONTHS = {
    1:'January',2:'February',3:'March',4:'April',5:'May',6:'June',
    7:'July',8:'August',9:'September',10:'October',11:'November',12:'December'
}
_BB_FA_JMONTHS = {
    1:'فروردین',2:'اردیبهشت',3:'خرداد',4:'تیر',5:'مرداد',6:'شهریور',
    7:'مهر',8:'آبان',9:'آذر',10:'دی',11:'بهمن',12:'اسفند'
}
_BB_FA_HMONTHS = {
    1:'محرم',2:'صفر',3:'ربیع‌الاول',4:'ربیع‌الثانی',5:'جمادی‌الاول',6:'جمادی‌الثانی',
    7:'رجب',8:'شعبان',9:'رمضان',10:'شوال',11:'ذیقعده',12:'ذیحجه'
}
_BB_EN_HMONTHS = {
    1:'Muharram',2:'Safar',3:'Rabi al-Awwal',4:'Rabi al-Thani',5:'Jumada al-Awwal',
    6:'Jumada al-Thani',7:'Rajab',8:'Sha’ban',9:'Ramadan',10:'Shawwal',
    11:'Dhu al-Qadah',12:'Dhu al-Hijjah'
}

def _bb_gregorian_to_jalali(gy, gm, gd):
    # Dependency-free conversion for the current/near-current Persian years.
    # Nowruz dates below cover the years used by the bot around 2026.
    starts={
        2024:(1403,3,20), 2025:(1404,3,21), 2026:(1405,3,21),
        2027:(1406,3,21), 2028:(1407,3,20), 2029:(1408,3,21),
        2030:(1409,3,21), 2031:(1410,3,21), 2032:(1411,3,20),
    }
    cur=date(gy,gm,gd)
    sy=gy if (gy in starts and cur>=date(gy,starts[gy][1],starts[gy][2])) else gy-1
    if sy not in starts:
        # Safe fallback for dates outside the table.
        sy=gy if cur>=date(gy,3,21) else gy-1
        jy=sy+621
        start=date(sy,3,21)
    else:
        jy,sm,sd=starts[sy]; start=date(sy,sm,sd)
    day=(cur-start).days
    if day<186:
        jm=1+day//31; jd=1+day%31
    else:
        jm=7+(day-186)//30; jd=1+(day-186)%30
    return jy,jm,jd

def _bb_gregorian_to_islamic(gy, gm, gd):
    # Tabular/civil Islamic calendar; keeps the bot dependency-free.
    a=(14-gm)//12
    y=gy+4800-a
    m=gm+12*a-3
    jdn=gd+(153*m+2)//5+365*y+y//4-y//100+y//400-32045
    # Align the civil calculation with the Iranian lunar date convention used by the bot.
    jdn += 2
    l=jdn-1948440+10632
    n=(l-1)//10631
    l=l-10631*n+354
    j=((10985-l)//5316)*((50*l)//17719)+(l//5670)*((43*l)//15238)
    l=l-((30-j)//15)*((17719*j)//50)-(j//16)*((15238*j)//43)+29
    mm=(24*l)//709
    dd=l-(709*mm)//24
    yy=30*n+j-30
    return int(yy),int(mm),int(dd)

def _bb_date_payload():
    try:
        from zoneinfo import ZoneInfo
        now=datetime.now(ZoneInfo('Asia/Tehran'))
    except Exception:
        now=datetime.now()
    gy,gm,gd=now.year,now.month,now.day
    jy,jm,jd=_bb_gregorian_to_jalali(gy,gm,gd)
    hy,hm,hd=_bb_gregorian_to_islamic(gy,gm,gd)
    pyday=(date(gy,gm,gd)-date(gy,3,21)).days+1 if (gm,gd)>=(3,21) else (date(gy,gm,gd)-date(gy-1,3,21)).days+1
    # Persian year 1405 begins 2026-03-21; its end is 2027-03-20.
    jalali_year_start=date(gy,3,21) if (gm,gd)>=(3,21) else date(gy-1,3,21)
    next_jalali_year=date(jalali_year_start.year+1,3,21)
    jalali_elapsed=(date(gy,gm,gd)-jalali_year_start).days+1
    jalali_remaining=(next_jalali_year-date(gy,gm,gd)).days-1
    greg_elapsed=now.timetuple().tm_yday
    greg_remaining=(366 if ((gy%4==0 and gy%100!=0) or gy%400==0) else 365)-greg_elapsed
    return now,jy,jm,jd,hy,hm,hd,jalali_elapsed,jalali_remaining,greg_elapsed,greg_remaining

async def _bb_date_time_callback(q, context):
    uid=q.from_user.id
    now,jy,jm,jd,hy,hm,hd,je,jr,ge,gr=_bb_date_payload()
    fa_week=_BB_FA_WEEKDAYS[now.weekday()]
    en_week=now.strftime('%A')
    fa_jdate=f'{_bb_fa_digits(jy)}/{_bb_fa_digits(jm):0>2}/{_bb_fa_digits(jd):0>2}'
    fa_hdate=f'{_bb_fa_digits(hy)}/{_bb_fa_digits(hm):0>2}/{_bb_fa_digits(hd):0>2}'
    en_date=f'{now.year:04d}/{now.month:02d}/{now.day:02d}'
    pct_j=round(je/(je+jr)*100) if je+jr else 0
    pct_g=round(ge/(ge+gr)*100) if ge+gr else 0
    bar_j='▰'*round(pct_j/20)+'▱'*(5-round(pct_j/20))
    bar_g='▰'*round(pct_g/20)+'▱'*(5-round(pct_g/20))
    text=(
        '📅 <b>تاریخ / ساعت بیل بیلک 🐕</b>\n\n'
        '‏〰️〰️〰️〰️〰️〰️〰️\n\n'
        f'⏰ ساعت : <b>{_bb_fa_digits(now.strftime("%H:%M:%S"))}</b>\n'
        f'📅 تاریخ : <b>{fa_week} - {fa_jdate} ({_BB_FA_JMONTHS[jm]})</b>\n\n'
        f'🌙 تاریخ قمری : <b>{fa_week} - {fa_hdate} ({_BB_FA_HMONTHS[hm]})</b>\n'
        f'☀️ تاریخ میلادی : <b>{en_week} - {en_date} ({_BB_EN_MONTHS[now.month]})</b>\n\n'
        '🎉 تا پایان سال (شمسی)\n'
        f'┘─ 📅 روز های سپری شده : <b>{_bb_fa_digits(je)} روز</b>\n'
        f'┘─ ⌛️ روز های باقی مانده : <b>{_bb_fa_digits(jr)} روز</b>\n'
        f'‏┘─ 🛍 {pct_j}% {bar_j}\n\n'
        '🎄 تا پایان سال (میلادی)\n'
        f'┘─ 📅 روز های سپری شده : <b>{ge} روز</b>\n'
        f'┘─ ⌛️ روز های باقی مانده : <b>{gr} روز</b>\n'
        f'‏┘─ 🛍 {pct_g}% {bar_g}\n\n'
        '‏〰️〰️〰️〰️〰️〰️〰️'
    )
    await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([
        [btn('🔄 تازه‌سازی',f'rich:{uid}:time')],
        [btn('🔙 ابزارها',f'rich:{uid}:home')]
    ]))
    return True

# Replace only the rich-callback implementation while preserving all other tools.
_OLD_RICH_CALLBACK_FINAL_DATE = rich_callback
async def rich_callback(q, context):
    data=getattr(q,'data','') or ''
    parts=data.split(':',2)
    if len(parts)==3 and parts[0]=='rich' and parts[1].isdigit() and int(parts[1])==q.from_user.id:
        if parts[2]=='time':
            return await _bb_date_time_callback(q,context)
        if parts[2]=='grouplink':
            chat=getattr(getattr(q,'message',None),'chat',None)
            if not chat or getattr(chat,'type',None)=='private':
                await q.edit_message_text('🔗 <b>لینک گروه</b>\n\nاین گزینه را باید داخل همان گروه اجرا کنی.',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 ابزارها',f'rich:{q.from_user.id}:home')]]))
                return True
            try:
                if getattr(chat,'username',None):
                    link='https://t.me/'+chat.username
                else:
                    link=await context.bot.export_chat_invite_link(chat.id)
                title=getattr(chat,'title',None) or 'گروه'
                await q.edit_message_text(
                    f'🔗 <b>لینک گروه</b>\n\n📛 نام: <b>{safe_text(title,120)}</b>\n\n'
                    f'🔗 لینک: {safe_text(link,500)}',
                    parse_mode='HTML',
                    reply_markup=keyboard([
                        [btn('🔗 باز کردن لینک گروه',url=link)],
                        [btn('🔙 ابزارها',f'rich:{q.from_user.id}:home')]
                    ])
                )
                return True
            except TelegramError as exc:
                await q.edit_message_text(
                    '⚠️ <b>ساخت لینک گروه ممکن نشد.</b>\n\n'
                    'اگر گروه لینک عمومی ندارد، ربات باید دسترسی ساخت لینک دعوت داشته باشد.',
                    parse_mode='HTML',reply_markup=keyboard([[btn('🔙 ابزارها',f'rich:{q.from_user.id}:home')]])
                )
                log.warning('group link callback failed: %s',exc)
                return True
    return await _OLD_RICH_CALLBACK_FINAL_DATE(q,context)



