# =============================================================================
# FINAL RUNTIME HARDENING — callback compatibility + deterministic tool routes
# =============================================================================
# A number of old callback layers were written for CallbackQuery directly,
# while PTB supplies Update.  Instead of relying on a particular historical
# wrapper, make Update transparently expose callback-query attributes whenever
# it actually is a callback update. This fixes .data/.from_user/.message and
# answer/edit/delete calls throughout the legacy chain.
try:
    _BB_UPDATE_OLD_GETATTR = getattr(telegram.Update, '__getattr__', None)
    def _bb_update_callback_getattr(self, name):
        q = getattr(self, 'callback_query', None)
        if q is not None and hasattr(q, name):
            return getattr(q, name)
        if _BB_UPDATE_OLD_GETATTR is not None:
            return _BB_UPDATE_OLD_GETATTR(self, name)
        raise AttributeError(name)
    telegram.Update.__getattr__ = _bb_update_callback_getattr
except Exception as _bb_update_patch_exc:
    log.warning('Update callback compatibility patch unavailable: %r', _bb_update_patch_exc)

# A second explicit normalization is kept for the final entry point.
def _bb_real_callback(obj):
    q = getattr(obj, 'callback_query', None)
    return q if q is not None else obj

_BB_PREVIOUS_FINAL_CALLBACK = callback_router_v10
async def callback_router_v10(update, context):
    q = getattr(update, 'callback_query', None)
    if q is None:
        return False
    data = str(getattr(q, 'data', '') or '')

    # Deterministic routes for the two tools that previously produced
    # Update.data errors. They are handled before the historical chain.
    try:
        if data.startswith('toolpage2:') or data.startswith('toolhint:') or data.startswith('sportclose:') or data.startswith('anread:'):
            if await _bb_expanded_tool_callback(q, context):
                return True
    except Exception as exc:
        log.exception('expanded tools callback failed after normalization: %r', exc)
        try: await q.answer('⚠️ ابزار فعلاً خطا داد؛ دوباره امتحان کن.', show_alert=True)
        except Exception: pass
        return True

    # Direct date and group-link routes: these no longer depend on an old rich
    # callback layer being selected first.
    if data.startswith('rich:'):
        parts = data.split(':', 2)
        if len(parts) == 3 and parts[1].isdigit() and int(parts[1]) == q.from_user.id:
            if parts[2] == 'time':
                try: await q.answer()
                except Exception: pass
                return await _bb_date_time_callback(q, context)
            if parts[2] == 'grouplink':
                try: await q.answer()
                except Exception: pass
                chat = getattr(getattr(q, 'message', None), 'chat', None)
                if not chat or getattr(chat, 'type', None) == 'private':
                    await q.edit_message_text(
                        '🔗 <b>لینک گروه</b>\n\nاین گزینه را باید داخل همان گروه اجرا کنی.',
                        parse_mode='HTML',
                        reply_markup=keyboard([[btn('🔙 ابزارها', f'rich:{q.from_user.id}:home')]])
                    )
                    return True
                try:
                    if getattr(chat, 'username', None):
                        link = 'https://t.me/' + str(chat.username).lstrip('@')
                    else:
                        link = await context.bot.export_chat_invite_link(chat.id)
                    title = safe_text(getattr(chat, 'title', None) or 'گروه', 120)
                    text = (
                        '🔗 <b>اطلاعات و لینک گروه</b> 🐕\n\n'
                        f'📛 نام گروه : <b>{title}</b>\n'
                        f'🆔 شناسه گروه : {chat.id}\n'
                        f'🔗 لینک گروه : {safe_text(link, 500)}\n\n'
                        '📤 می‌توانی لینک را مستقیم برای دیگران بفرستی.'
                    )
                    share_url = 'https://t.me/share/url?url=' + quote_plus(link) + '&text=' + quote_plus(title)
                    await q.edit_message_text(
                        text, parse_mode='HTML',
                        reply_markup=keyboard([
                            [btn('📤 اشتراک‌گذاری لینک', url=share_url)],
                            [btn('🔗 باز کردن لینک گروه', url=link)],
                            [btn('🔙 ابزارها', f'rich:{q.from_user.id}:home')]
                        ])
                    )
                except Exception as exc:
                    log.warning('group link callback failed: %r', exc)
                    await q.edit_message_text(
                        '⚠️ <b>لینک گروه ساخته نشد.</b>\n\nاگر گروه خصوصی است، ربات باید دسترسی ساخت لینک دعوت داشته باشد.',
                        parse_mode='HTML',
                        reply_markup=keyboard([[btn('🔙 ابزارها', f'rich:{q.from_user.id}:home')]])
                    )
                return True

    # Per-group music state is enforced here too, so old inline music buttons
    # cannot bypass «موزیکال خاموش».
    music_prefixes = ('mplay:', 'mplaylive:', 'msearch:', 'mctrl:', 'mdownload:', 'mf2:', 'mf9:', 'mf9act:', 'mf9set:', 'mfhelp:', 'mfnew:', 'mfrooms:', 'music:')
    if data.startswith(music_prefixes):
        chat = getattr(getattr(q, 'message', None), 'chat', None)
        if chat and getattr(chat, 'type', None) != 'private':
            try:
                if not await vip_active(chat.id):
                    await q.answer('⛔ موزیکال فقط در گروه VIP فعال است.', show_alert=True)
                    return True
                if not await vip_feature(chat.id, 'music'):
                    await q.answer('🔴 موزیکال این گروه خاموش است.\nبرای روشن‌کردن: موزیکال روشن', show_alert=True)
                    return True
            except Exception as exc:
                log.warning('music vip guard failed: %r', exc)

    # Continue the complete historical chain, but pass the real CallbackQuery.
    try:
        return await _BB_PREVIOUS_FINAL_CALLBACK(update, context)
    except Exception as exc:
        # One broken legacy branch must never crash the callback update.
        log.warning('legacy callback branch skipped: %r', exc)
        try: await q.answer('⚠️ این دکمه با این نسخه سازگار نبود؛ دوباره از پنل وارد شو.', show_alert=True)
        except Exception: pass
        return True

# Make the internal smoke test stricter and independent of network/Telegram.
def _bb_internal_smoke_test_final():
    assert BB_BOT_USERNAME == 'Bil_bilakapibot'
    now,jy,jm,jd,hy,hm,hd,je,jr,ge,gr = _bb_date_payload()
    assert (jy,jm,jd) == (1405,6,21), (jy,jm,jd)
    assert (hy,hm,hd) == (1448,4,1), (hy,hm,hd)
    assert je == 176 and jr == 189, (je,jr)
    assert ge == 255 and gr == 110, (ge,gr)
    return True



