# card free of the global visual wrapper so its layout stays exactly readable.
_BB_DATE_HEADER = '📅 <b>تاریخ / ساعت بیل بیلک 🐕</b>'
_BB_DATE_HEADER_PLAIN = '📅 تاریخ / ساعت بیل بیلک'
_BB_OLD_PRETTY_MESSAGE_FINAL = _bb_pretty_message

def _bb_pretty_message(text, parse_mode=None):
    if text is None:
        return text
    value = str(text)
    # Do not add the global header/footer to the dedicated date card.
    if _BB_DATE_HEADER in value or _BB_DATE_HEADER_PLAIN in value:
        return value
    return _BB_OLD_PRETTY_MESSAGE_FINAL(value, parse_mode)


def _bb_date_card_text():
    now,jy,jm,jd,hy,hm,hd,je,jr,ge,gr = _bb_date_payload()
    fa_week = _BB_FA_WEEKDAYS[now.weekday()]
    en_week = now.strftime('%A')
    fa_jdate = f'{_bb_fa_digits(jy)}/{_bb_fa_digits(jm):0>2}/{_bb_fa_digits(jd):0>2}'
    fa_hdate = f'{_bb_fa_digits(hy)}/{_bb_fa_digits(hm):0>2}/{_bb_fa_digits(hd):0>2}'
    en_date = f'{now.year:04d}/{now.month:02d}/{now.day:02d}'
    pct_j = round(je/(je+jr)*100) if je+jr else 0
    pct_g = round(ge/(ge+gr)*100) if ge+gr else 0
    bar_j = '▰'*round(pct_j/20) + '▱'*(5-round(pct_j/20))
    bar_g = '▰'*round(pct_g/20) + '▱'*(5-round(pct_g/20))
    # The Gregorian elapsed/remaining figures are intentionally Latin digits,
    # matching the owner's reference card.
    return (
        '📅 <b>تاریخ / ساعت بیل بیلک 🐕</b>\n\n'
        '‏〰️〰️〰️〰️〰️〰️〰️\n\n'
        f'⏰ ساعت : <b>{_bb_fa_digits(now.strftime("%H:%M:%S"))}</b>\n'
        f'📅 تاریخ : <b>{fa_week} - {fa_jdate} ({_BB_FA_JMONTHS[jm]})</b>\n\n'
        f'🌙 تاریخ قمری : <b>{fa_week} - {fa_hdate} ({_BB_FA_HMONTHS[hm]})</b>\n'
        f'☀️ تاریخ میلادی : <b>{en_week} - {en_date} ({_BB_EN_MONTHS[now.month]})</b>\n\n'
        '🎉 تا پایان سال (شمسی)\n'
        f'┘─ 📅 روز های سپری شده : <b>{_bb_fa_digits(je)} روز</b>\n'
        f'┘─ ⌛️ روز های باقی مانده : <b>{_bb_fa_digits(jr)} روز</b>\n'
        f'‏┘─ 🛍 {pct_j}% {bar_j}\n\n'
        '🎄 تا پایان سال (میلادی)\n'
        f'┘─ 📅 روز های سپری شده : <b>{ge} روز</b>\n'
        f'┘─ 📅 روز های باقی مانده : <b>{gr} روز</b>\n'
        f'‏┘─ 🛍 {pct_g}% {bar_g}\n\n'
        '‏〰️〰️〰️〰️〰️〰️〰️'
    )

async def _bb_send_date_card(update, context):
    msg = getattr(update, 'effective_message', None)
    user = getattr(update, 'effective_user', None)
    if not msg or not user:
        return True
    uid = user.id
    await msg.reply_text(
        _bb_date_card_text(),
        parse_mode='HTML',
        reply_markup=keyboard([
            [btn('🔄 تازه‌سازی', f'rich:{uid}:time')],
            [btn('🔙 ابزارها', f'rich:{uid}:home')]
        ])
    )
    return True

async def _bb_reliable_group_link(update, context):
    """Return a usable public/invite link when Telegram permits it."""
    chat = getattr(update, 'effective_chat', None)
    msg = getattr(update, 'effective_message', None)
    if not chat or not msg:
        return True
    if getattr(chat, 'type', None) == 'private':
        await msg.reply_text(
            '🔗 <b>لینک گروه</b>\n\nاین دستور را داخل همان گروه اجرا کن.',
            parse_mode='HTML'
        )
        return True
    await DBX.ensure_chat(chat)
    link = None
    try:
        username = getattr(chat, 'username', None)
        if username:
            link = 'https://t.me/' + str(username).lstrip('@')
        else:
            link = await context.bot.export_chat_invite_link(chat.id)
    except TelegramError as exc:
        log.warning('reliable group link failed: %s', exc)
    title = safe_text(getattr(chat, 'title', None) or 'گروه', 120)
    if not link:
        await msg.reply_text(
            '⚠️ <b>لینک گروه ساخته نشد.</b>\n\n'
            'اگر گروه خصوصی است، ربات باید داخل گروه ادمین باشد و اجازهٔ دعوت کاربران/ساخت لینک دعوت را داشته باشد.',
            parse_mode='HTML',
            reply_markup=keyboard([[btn('🔙 ابزارها', f'rich:{getattr(update.effective_user, "id", 0)}:home')]])
        )
        return True
    share_text = f'🐾 لینک گروه «{title}»\n\nبرای پیوستن به گروه روی لینک بزنید.\n{link}'
    share_url = 'https://t.me/share/url?url=' + quote_plus(link) + '&text=' + quote_plus(share_text)
    await msg.reply_text(
        '🔗 <b>اطلاعات و لینک گروه</b> 🐕\n\n'
        f'📛 نام گروه : <b>{title}</b>\n'
        f'🆔 شناسه گروه : {chat.id}\n'
        f'🔗 لینک گروه : {safe_text(link, 500)}\n\n'
        '📤 لینک آمادهٔ اشتراک‌گذاری است.',
        parse_mode='HTML',
        reply_markup=keyboard([
            [btn('📤 اشتراک‌گذاری لینک', url=share_url)],
            [btn('🔗 باز کردن لینک گروه', url=link)],
            [btn('🔙 ابزارها', f'rich:{getattr(update.effective_user, "id", 0)}:home')]
        ])
    )
    return True

# Put the two text routes before every historical message-router layer. This
# fixes the case where an older router consumes «تاریخ»/«لینک گروه» first.
_BB_FINAL_MESSAGE_BEFORE_DATE_LINK = message_router_v9
async def message_router_v9(update, context):
    msg = getattr(update, 'effective_message', None)
    text = str(getattr(msg, 'text', '') or '').strip() if msg else ''
    normalized = normalize(text) if text else ''
    if normalized in {'تاریخ', 'تاریخ امروز', 'ساعت و تاریخ', 'تاریخ و ساعت', 'time', 'date'}:
        return await _bb_send_date_card(update, context)
    if normalized in {'لینک گروه', 'لینک گپ', 'لینک گروپ', 'اطلاعات گروه', 'معرفی گروه', 'لینک این گروه'}:
        return await _bb_reliable_group_link(update, context)
    return await _BB_FINAL_MESSAGE_BEFORE_DATE_LINK(update, context)

# Add explicit slash commands as well.  They are useful when a text router is
# bypassed by Telegram's command filtering.
_BB_PREVIOUS_BUILD_FOR_FINAL_COMMANDS = build_application
def build_application(token: str) -> Application:
    app = _BB_PREVIOUS_BUILD_FOR_FINAL_COMMANDS(token)
    app.add_handler(CommandHandler('time', _bb_send_date_card), group=0)
    app.add_handler(CommandHandler('date', _bb_send_date_card), group=0)
    app.add_handler(CommandHandler('grouplink', _bb_reliable_group_link), group=0)
    return app

# Stronger local-only assertions for the exact reference date layout.
def _bb_internal_smoke_test_reference():
    text = _bb_date_card_text()
    assert '📅 <b>تاریخ / ساعت بیل بیلک 🐕</b>' in text
    assert '🎉 تا پایان سال (شمسی)' in text
    assert '🎄 تا پایان سال (میلادی)' in text
    return True

# =============================================================================
# ABSOLUTE FINAL ROUTE FIX — date/link MUST win over legacy routers
# =============================================================================
# These handlers are registered in a negative-priority group from the final
# build.  They therefore run before every historical text/callback router and
# cannot be shadowed by one of the many legacy overrides in this large file.

async def _bb_absolute_date_route(update, context):
    msg = getattr(update, 'effective_message', None)
    if not msg:
        return True
    try:
        await msg.reply_text(
            _bb_date_card_text(),
            parse_mode='HTML',
            reply_markup=keyboard([
                [btn('🔄 تازه‌سازی', f'rich:{getattr(update.effective_user, "id", 0)}:time')],
                [btn('🔙 ابزارها', f'rich:{getattr(update.effective_user, "id", 0)}:home')]
            ])
        )
    except Exception as exc:
        log.exception('absolute date route failed: %r', exc)
    return True

async def _bb_absolute_group_link_route(update, context):
    # Final authority: «لینک گروه» must open the selectable four-format panel.
    return await _bb_group_link_panel_text(update, context)

async def _bb_absolute_rich_route(update, context):
    q = getattr(update, 'callback_query', None)
    if q is None:
        return False
    data = str(getattr(q, 'data', '') or '')
    parts = data.split(':', 2)
    if len(parts) != 3 or parts[0] != 'rich' or not parts[1].isdigit():
        return False
    if int(parts[1]) != getattr(getattr(q, 'from_user', None), 'id', -1):
        return False
    if parts[2] == 'time':
        try:
            await q.answer()
        except Exception:
            pass
        return await _bb_date_time_callback(q, context)
    if parts[2] == 'grouplink':
        try:
            await q.answer()
        except Exception:
            pass
        chat = getattr(getattr(q, 'message', None), 'chat', None)
        if not chat or getattr(chat, 'type', None) == 'private':
            await q.edit_message_text(
                '🔗 <b>لینک گروه</b>\n\nاین گزینه را باید داخل همان گروه اجرا کنی.',
                parse_mode='HTML',
                reply_markup=keyboard([[btn('🔙 ابزارها', f'rich:{q.from_user.id}:home')]])
            )
            return True
        try:
            username = getattr(chat, 'username', None)
            if username:
                link = 'https://t.me/' + str(username).lstrip('@')
            else:
                link = await context.bot.export_chat_invite_link(chat.id)
            title = safe_text(getattr(chat, 'title', None) or 'گروه', 120)
            share_url = 'https://t.me/share/url?url=' + quote_plus(link) + '&text=' + quote_plus(title)
            await q.edit_message_text(
                '🔗 <b>اطلاعات و لینک گروه</b> 🐕\n\n'
                f'📛 نام گروه : <b>{title}</b>\n'
                f'🆔 شناسه گروه : {chat.id}\n'
                f'🔗 لینک گروه : {safe_text(link, 500)}',
                parse_mode='HTML',
                reply_markup=keyboard([
                    [btn('📤 اشتراک‌گذاری لینک', url=share_url)],
                    [btn('🔗 باز کردن لینک گروه', url=link)],
                    [btn('🔙 ابزارها', f'rich:{q.from_user.id}:home')]
                ])
            )
        except Exception as exc:
            log.exception('absolute group-link callback failed: %r', exc)
            try:
                await q.edit_message_text(
                    '⚠️ <b>لینک گروه ساخته نشد.</b>\n\n'
                    'اگر گروه خصوصی است، ربات باید دسترسی ساخت لینک دعوت داشته باشد.',
                    parse_mode='HTML',
                    reply_markup=keyboard([[btn('🔙 ابزارها', f'rich:{q.from_user.id}:home')]])
                )
            except Exception:
                pass
        return True
    return False

# Keep every feature from the existing final builder, but add these deterministic
# routes at a higher priority.  This wrapper is intentionally the last builder.
_BB_BUILDER_BEFORE_ABSOLUTE_ROUTES = build_application

def build_application(token: str) -> Application:
    app = _BB_BUILDER_BEFORE_ABSOLUTE_ROUTES(token)
    # Private-message reveal buttons are handled before legacy callback layers.
    app.add_handler(CallbackQueryHandler(_bb_anon_callback, pattern=r'^anread:'), group=-1001)
    # Text routes: run before all historical message routers.
    app.add_handler(MessageHandler(
        filters.Regex(r'^(تاریخ|تاریخ امروز|ساعت و تاریخ|تاریخ و ساعت|time|date)$'),
        _bb_absolute_date_route
    ), group=-1000)
    app.add_handler(MessageHandler(
        filters.Regex(r'^(لینک گروه|لینک گپ|لینک گروپ|اطلاعات گروه|معرفی گروه|لینک این گروه)$'),
        _bb_absolute_group_link_route
    ), group=-1000)
    # Callback routes: also run before every historical CallbackQueryHandler.
    app.add_handler(CallbackQueryHandler(_bb_absolute_rich_route), group=-1000)
    return app

