# =============================================================================
# FINAL TELEGRAM NETWORK RESILIENCE — Pydroid/mobile connections
# =============================================================================
# The observed failure is a transport CONNECT timeout, not a bot-logic error.
# Use longer connection/read timeouts and a small retry only for connection
# timeouts, so a transient mobile-network stall does not kill a handler.
try:
    if _BB_HTTPXRequest is not None:
        _BB_OriginalHTTPXRequest = _BB_HTTPXRequest

        class _BBResilientHTTPXRequest(_BB_OriginalHTTPXRequest):
            def __init__(self, *args, **kwargs):
                kwargs["connect_timeout"] = max(float(kwargs.get("connect_timeout", 0) or 0), 60.0)
                kwargs["read_timeout"] = max(float(kwargs.get("read_timeout", 0) or 0), 120.0)
                kwargs["write_timeout"] = max(float(kwargs.get("write_timeout", 0) or 0), 120.0)
                kwargs["pool_timeout"] = max(float(kwargs.get("pool_timeout", 0) or 0), 45.0)
                super().__init__(*args, **kwargs)

        _BB_HTTPXRequest = _BBResilientHTTPXRequest

    _BB_ORIG_RESILIENT_SEND_MESSAGE = telegram.Bot.send_message

    async def _bb_resilient_send_message(self, chat_id, text, *args, **kwargs):
        last_exc = None
        # Do not retry indefinitely. A failed connection is retried twice,
        # with a short backoff, then the normal error handler gets the failure.
        for attempt in range(3):
            try:
                return await _BB_ORIG_RESILIENT_SEND_MESSAGE(
                    self, chat_id, text, *args, **kwargs
                )
            except Exception as exc:
                last_exc = exc
                name = type(exc).__name__
                if name not in {"TimedOut", "ConnectTimeout"} or attempt >= 2:
                    raise
                await asyncio.sleep(1.5 * (attempt + 1))
        raise last_exc

    # The visual-polish send_message wrapper already installed earlier must
    # remain active, so retry its wrapper rather than bypassing it.
    if globals().get("_bb_send_message") is not None:
        _BB_VISUAL_SEND_MESSAGE = _bb_send_message

        async def _bb_send_message_resilient(self, chat_id, text, *args, **kwargs):
            last_exc = None
            for attempt in range(3):
                try:
                    return await _BB_VISUAL_SEND_MESSAGE(
                        self, chat_id, text, *args, **kwargs
                    )
                except Exception as exc:
                    last_exc = exc
                    if type(exc).__name__ not in {"TimedOut", "ConnectTimeout"} or attempt >= 2:
                        raise
                    await asyncio.sleep(1.5 * (attempt + 1))
            raise last_exc

        telegram.Bot.send_message = _bb_send_message_resilient
    else:
        telegram.Bot.send_message = _bb_resilient_send_message

    log.info("Telegram network resilience enabled: connect=60s read=120s retries=2")
except Exception as _bb_net_exc:
    log.warning("Telegram network resilience setup failed: %r", _bb_net_exc)

