# ABSOLUTE FINAL PUBLIC TOOLS + ANALYTICS PERMISSIONS REPAIR
# =============================================================================

async def _bb_public_tools_final(update, context):
    msg = getattr(update, "effective_message", None)
    user = getattr(update, "effective_user", None)
    if not msg or not user or not getattr(msg, "text", None):
        return False

    raw = str(msg.text or "").strip()
    n = normalize(raw)

    # Public Instagram / Telegram channel analytics.
    m = re.fullmatch(r"آنالیز\s*(?:پیج\s*)?[@(]?([A-Za-z0-9._]{1,30})\)?", n, re.I)
    if m:
        return await _bb_instagram_analysis_command(update, context, m.group(1))

    m = re.fullmatch(r"آنالیز\s+کانال\s*[@]?([A-Za-z0-9_]{3,64})", n, re.I)
    if m:
        return await _bb_telegram_analysis_command(update, context, m.group(1))

    # Smart group report: every real group admin/owner may run it.
    chat = getattr(update, "effective_chat", None)
    if chat and getattr(chat, "type", "") != "private":
        if n in {"گزارش هوشمند گروه", "مدیر هوشمند", "آنالیز هوشمند گروه", "گزارش گروه"}:
            try:
                allowed = await is_admin(update, user.id)
            except Exception:
                allowed = False
            if not allowed:
                await msg.reply_text("⛔ این گزارش فقط برای ادمین‌ها و مالک‌های همین گروه است.")
                return True
            return await _bb_smart_group_command(update, context)

    # News.
    if n in {"اخبار", "خبر", "اخبار روز", "daily news", "news"}:
        return await _bb_news_command(update, context)

    # Weather.
    if n in {"آب و هوا", "آبوهوا", "هوا"}:
        return await msg.reply_text(await _bb_weather_lookup("تهران"))

    m = re.match(r"^(?:آب\s*و\s*هوا|آبوهوا|هوا)(?:ی)?\s+(.+)$", raw, re.I)
    if m:
        return await msg.reply_text(await _bb_weather_lookup(m.group(1).strip()))

    # Currency.
    if n in {"قیمت ارزها", "قیمت ارز ها", "نرخ ارزها", "نرخ ارز ها"}:
        return await msg.reply_text(await _bb_currency_top10())

    m = re.match(r"^(?:ارز|قیمت ارز|نرخ ارز)\s+(.+)$", raw, re.I)
    if m:
        return await msg.reply_text(await _bb_currency_one(m.group(1).strip()))

    # Country.
    m = re.match(r"^(?:کشور|اطلاعات کشور)\s+(.+)$", raw, re.I)
    if m:
        name = m.group(1).strip()
        try:
            result = await _bb_country_text(name)
            if result and result[0]:
                body, flag = result
                if flag:
                    await msg.reply_photo(flag, caption=body, parse_mode="HTML")
                else:
                    await msg.reply_text(body, parse_mode="HTML")
                return True
        except Exception as exc:
            log.warning("final country tool failed: %r", exc)
        await msg.reply_text("❌ اطلاعات کشور در دسترس نبود.")
        return True

    # Football / sports: use the existing no-key ESPN feed for live results,
    # and API-Sports when a league-specific request is made.
    if n in {"فوتبال", "فوتبالی", "ورزش زنده", "نتیجه زنده", "نتایج زنده"}:
        try:
            data = await live_scores("فوتبال")
            out_text = format_score_events(data)
            await msg.reply_text(
                "⚽ <b>فوتبال</b>\n\n" +
                (out_text or "در حال حاضر بازی زنده‌ای در فید پیدا نشد."),
                parse_mode="HTML"
            )
        except Exception as exc:
            log.warning("final football feed failed: %r", exc)
            await msg.reply_text("⚠️ سرویس فوتبال موقتاً پاسخ نداد؛ دوباره امتحان کن.")
        return True

    m = re.match(r"^فوتبال(?:\s+زنده)?\s+(.+)$", raw, re.I)
    if m:
        league = m.group(1).strip()
        try:
            data = await live_scores(league)
            out_text = format_score_events(data)
            await msg.reply_text(
                f"⚽ <b>فوتبال — {_bb_h(league)}</b>\n\n" +
                (out_text or "برای این رقابت در فید فعلی بازی‌ای پیدا نشد."),
                parse_mode="HTML"
            )
        except Exception as exc:
            log.warning("final football league feed failed: %r", exc)
            await msg.reply_text("⚠️ دریافت اطلاعات فوتبال ناموفق بود.")
        return True

    return False


async def _bb_public_tools_final_callback(update, context):
    q = getattr(update, "callback_query", None)
    if not q:
        return False
    data = str(getattr(q, "data", "") or "")
    if data == "bbsmart:panel":
        chat = getattr(getattr(q, "message", None), "chat", None)
        allowed = False
        if chat:
            try:
                allowed = await is_admin(update, q.from_user.id)
            except Exception:
                allowed = False
        if not allowed:
            await q.answer("⛔ فقط ادمین یا مالک همین گروه.", show_alert=True)
            return True
        return await _bb_smart_panel(q, context)

    if data == "bbsmart:run":
        try:
            allowed = await is_admin(update, q.from_user.id)
        except Exception:
            allowed = False
        if not allowed:
            await q.answer("⛔ فقط ادمین یا مالک همین گروه.", show_alert=True)
            return True
        await q.answer("در حال تحلیل…")
        return await _bb_smart_group_command(update, context)

    return False


# Highest-priority registration. These run before the old historical routers.
_BB_BUILD_BEFORE_ABSOLUTE_PUBLIC_TOOLS = build_application

def build_application(token: str) -> Application:
    app = _BB_BUILD_BEFORE_ABSOLUTE_PUBLIC_TOOLS(token)

    app.add_handler(
        MessageHandler(
            filters.TEXT & ~filters.COMMAND,
            _bb_public_tools_final
        ),
        group=-50000,
    )

    app.add_handler(
        CallbackQueryHandler(
            _bb_public_tools_final_callback,
            pattern=r"^(?:bbsmart:(?:panel|run))$",
        ),
        group=-50001,
    )

    # Slash aliases for environments/groups where privacy mode blocks plain text.
    app.add_handler(CommandHandler("news", _bb_news_command), group=-49999)
    app.add_handler(CommandHandler("weather", bb_cmd_weather), group=-49999)
    app.add_handler(CommandHandler("currency", bb_cmd_currency), group=-49999)
    app.add_handler(CommandHandler("football", lambda u, c: live_scores("فوتبال")), group=-49999)

    return app



