async def _bb_majid_json(path, params=None):
    token = await _bb_pro_get("MAJID_API_TOKEN", os.getenv("MAJID_API_TOKEN", ""))
    if not token:
        return None, "کلید MAJID_API_TOKEN تنظیم نشده است."
    p = dict(params or {})
    p["token"] = token
    try:
        st, data, _ = await _bb_http_get_json(
            "https://api.majidapi.ir/" + path.lstrip("/"), params=p, timeout=20
        )
        if st != 200:
            return None, f"MajidAPI HTTP {st}"
        return data, None
    except Exception as exc:
        return None, f"خطای اتصال API: {safe_text(str(exc),180)}"

def _bb_api_text(data):
    if isinstance(data, dict):
        for k in ("result","data","response","text","message","bio","content"):
            v = data.get(k)
            if isinstance(v, (str,int,float)) and str(v).strip():
                return str(v).strip()
            if isinstance(v, (dict,list)):
                z = _bb_api_text(v)
                if z:
                    return z
    if isinstance(data, list) and data:
        return _bb_api_text(random.choice(data))
    return str(data).strip() if isinstance(data,(str,int,float)) else ""

async def _bb_strict_fortune(kind):
    path = "fun/fal/coffee" if kind == "coffee" else "fun/fal"
    data, err = await _bb_majid_json(path, {} if kind=="coffee" else {"type":"text"})
    if err: return None, err
    value = _bb_api_text(data)
    return (value, None) if value else (None, "API فال پاسخ قابل استفاده‌ای نداد.")

