async def _bb_strict_country(name):
    key = await _bb_pro_get("RESTCOUNTRIES_API_KEY","")
    if not key:
        return None, "کلید RESTCOUNTRIES_API_KEY تنظیم نشده است."
    q = BB_COUNTRY_ALIASES.get(normalize(name), name).strip()
    try:
        st, data, _ = await _bb_http_get_json(
            f"https://restcountries.com/v3.1/name/{_bb_quote_plus(q)}",
            headers={"Authorization":f"Bearer {key}"},
            params={"fullText":"false"}, timeout=20
        )
        if st != 200 or not isinstance(data,list) or not data:
            return None, f"REST Countries API HTTP {st}"
        return data[0], None
    except Exception as exc:
        return None, f"خطای REST Countries API: {safe_text(str(exc),180)}"

async def _bb_strict_ai_tips(platform, report, uid):
    key = await _bb_pro_get("OPENROUTER_API_KEY", os.getenv("OPENROUTER_API_KEY",""))
    if not key:
        return None, "کلید OPENROUTER_API_KEY تنظیم نشده است."
    try:
        prompt = (
            "برای این گزارش سه پیشنهاد کوتاه و عملی به فارسی بده؛ عدد ساختگی نساز.\n"
            f"پلتفرم: {platform}\nداده: {json.dumps(report,ensure_ascii=False)[:6000]}"
        )
        answer = await _speaker_ai_call(
            prompt, verbosity="short", tone="polite", chat_id=uid,
            memory_enabled=False, timeout=45
        )
        if not answer:
            return None, "OpenRouter پاسخ قابل استفاده‌ای نداد."
        lines = [
            re.sub(r"^[\-•\d.)\s]+","",x).strip()
            for x in str(answer).splitlines()
        ]
        lines = [x for x in lines if len(x)>8][:3]
        return (lines,None) if lines else (None,"OpenRouter پاسخ قابل استفاده‌ای نداد.")
    except Exception as exc:
        return None, f"خطای OpenRouter API: {safe_text(str(exc),180)}"

async def _bb_strict_api_router(update, context):
    msg = getattr(update,"effective_message",None)
    user = getattr(update,"effective_user",None)
    if not msg or not user or not getattr(msg,"text",None):
        return False
    raw = str(msg.text).strip()
    n = normalize(raw)

    # Instagram: Meta API + OpenRouter suggestions.
    m = re.fullmatch(r"آنالیز\s*(?:پیج\s*)?@?([A-Za-z0-9._]{1,30})",raw,re.I)
    if m:
        wait = await msg.reply_text("📊 در حال دریافت داده از API اینستاگرام…")
        data, err = await _bb_instagram_fetch(m.group(1))
        if err:
            await wait.edit_text("⚠️ <b>API اینستاگرام در دسترس نیست.</b>\n\n"+_bb_h(err),parse_mode="HTML")
            return True
        report = _bb_instagram_report(data)
        tips, err = await _bb_strict_ai_tips("Instagram",report,user.id)
        if err:
            await wait.edit_text("⚠️ <b>API پیشنهادهای هوشمند در دسترس نیست.</b>\n\n"+_bb_h(err),parse_mode="HTML")
            return True
        await wait.edit_text(
            f'📸 <b>آنالیز @{_bb_h(report["username"])}</b>\n\n'
            f'👥 فالوور: <b>{report["followers"]:,}</b>\n'
            f'➡️ دنبال‌شونده: <b>{report["following"]:,}</b>\n'
            f'🗂 محتوا: <b>{report["media_count"]:,}</b>\n\n'
            '🚀 <b>پیشنهادهای هوشمند:</b>\n'+
            "\n".join("• "+_bb_h(x) for x in tips),parse_mode="HTML")
        return True

    # Telegram channel: Bot API + OpenRouter suggestions.
    m = re.fullmatch(r"آنالیز\s+کانال\s*@?([A-Za-z0-9_]{3,64})",raw,re.I)
    if m:
        wait = await msg.reply_text("📢 در حال دریافت داده از Telegram API…")
        data, err = await _bb_telegram_channel_fetch(context,m.group(1))
        if err:
            await wait.edit_text("⚠️ <b>API کانال در دسترس نیست.</b>\n\n"+_bb_h(err),parse_mode="HTML")
            return True
        tips, err = await _bb_strict_ai_tips("Telegram Channel",data,user.id)
        if err:
            await wait.edit_text("⚠️ <b>API پیشنهادهای هوشمند در دسترس نیست.</b>\n\n"+_bb_h(err),parse_mode="HTML")
            return True
        await wait.edit_text(
            f'📢 <b>آنالیز کانال {_bb_h(data.get("username") or data.get("title",""))}</b>\n\n'
            f'👥 اعضا: <b>{int(data.get("members") or 0):,}</b>\n\n'
            '🚀 <b>پیشنهادهای هوشمند:</b>\n'+
            "\n".join("• "+_bb_h(x) for x in tips),parse_mode="HTML")
        return True

    # Group report: every admin/owner of that group.
    chat = getattr(update,"effective_chat",None)
    if chat and getattr(chat,"type","")!="private" and n in {
        "گزارش هوشمند گروه","مدیر هوشمند","آنالیز هوشمند گروه","گزارش گروه"
    }:
        if not await is_admin(update):
            await msg.reply_text("⛔ این گزارش فقط برای ادمین‌ها و مالک‌های همین گروه است.")
            return True
        report = await _bb_smart_group_report(chat.id)
        if not report:
            await msg.reply_text("⚠️ داده کافی برای گزارش گروه وجود ندارد.")
            return True
        wait = await msg.reply_text("🧠 در حال گرفتن پیشنهادهای هوشمند از API…")
        tips, err = await _bb_strict_ai_tips("Telegram Group",report,user.id)
        if err:
            await wait.edit_text("⚠️ <b>API پیشنهادهای گروه در دسترس نیست.</b>\n\n"+_bb_h(err),parse_mode="HTML")
            return True
        await wait.edit_text(
            '🧠 <b>گزارش هوشمند گروه</b>\n\n'
            f'👥 اعضای ثبت‌شده: <b>{int(report["members_tracked"]):,}</b>\n'
            f'💬 پیام‌های ثبت‌شده: <b>{int(report["messages_total"]):,}</b>\n'
            f'⚡ اعضای فعال: <b>{int(report["active_members"]):,}</b>\n\n'
            '🚀 <b>پیشنهادهای مدیر هوشمند:</b>\n'+
            "\n".join("• "+_bb_h(x) for x in tips),parse_mode="HTML")
        return True

    # Country: authenticated API only.
    m = re.match(r"^کشور\s+(.+)$",raw)
    if m:
        data, err = await _bb_strict_country(m.group(1))
        if err:
            await msg.reply_text("⚠️ <b>API کشور در دسترس نیست.</b>\n\n"+_bb_h(err),parse_mode="HTML")
            return True
        ndata = data.get("name") or {}
        body = (
            f'🌍 <b>{_bb_h(ndata.get("common") or ndata.get("official") or "نامشخص")}</b>\n\n'
            f'🏛 پایتخت: <b>{_bb_h(", ".join(data.get("capital") or []) or "ثبت نشده")}</b>\n'
            f'👥 جمعیت: <b>{int(data.get("population") or 0):,}</b>\n'
            f'🗺 منطقه: <b>{_bb_h(data.get("region") or "ثبت نشده")}</b>\n'
            f'🗣 زبان: <b>{_bb_h(", ".join(str(v) for v in (data.get("languages") or {}).values()) or "ثبت نشده")}</b>\n'
            f'💱 ارز: <b>{_bb_h(", ".join(str((v or {}).get("name") or k) for k,v in (data.get("currencies") or {}).items()) or "ثبت نشده")}</b>'
        )
        flag=((data.get("flags") or {}).get("png") or "")
        if flag:
            try:
                await msg.reply_photo(flag,caption=body,parse_mode="HTML")
                return True
            except Exception:
                pass
        await msg.reply_text(body,parse_mode="HTML")
        return True

    # Football: API-Sports only.
    m = re.match(r"^فوتبال\s+(.+)$",raw,re.I)
    if m:
        if not await _bb_pro_get("APISPORTS_API_KEY",""):
            await msg.reply_text("⚠️ <b>API-Sports تنظیم نشده است.</b>",parse_mode="HTML")
            return True
        result = await _bb_sports_today("فوتبال",m.group(1).strip())
        if isinstance(result,tuple):
            body,markup=result
            await msg.reply_text(body,parse_mode="HTML",reply_markup=markup)
        else:
            await msg.reply_text("⚠️ <b>API-Sports:</b> "+_bb_h(result),parse_mode="HTML")
        return True

    if n in {"اخبار","خبر","اخبار روز","news","daily news"}:
        return await _bb_news_command(update,context)

    # Public APIs: no static fallback.
    m = re.match(r"^(?:آب\s*و\s*هوا|هوا)(?:ی)?\s+(.+)$",raw)
    if m:
        result = await _bb_weather_lookup(m.group(1))
        if "سرویس آب‌وهوا پاسخ نداد" in str(result):
            result = "⚠️ API آب‌وهوا در دسترس نیست."
        await msg.reply_text(result,parse_mode="HTML")
        return True

    if n in {"قیمت ارزها","قیمت ارز ها","نرخ ارزها","نرخ ارز ها"}:
        if not await _bb_currency_rates():
            await msg.reply_text("⚠️ <b>API ارز در دسترس نیست.</b>",parse_mode="HTML")
        else:
            await msg.reply_text(await _bb_currency_top10(),parse_mode="HTML")
        return True

    m = re.match(r"^(?:ارز|قیمت ارز|نرخ ارز)\s+(.+)$",raw,re.I)
    if m:
        if not await _bb_currency_rates():
            await msg.reply_text("⚠️ <b>API ارز در دسترس نیست.</b>",parse_mode="HTML")
        else:
            await msg.reply_text(await _bb_currency_one(m.group(1)),parse_mode="HTML")
        return True

    # API-backed fortune/bio/hadith/motivation.
    if n in {"فال","فال حافظ","فال قهوه"}:
        body, err = await _bb_strict_fortune("coffee" if n=="فال قهوه" else "hafez")
        if err:
            await msg.reply_text("⚠️ <b>API فال در دسترس نیست.</b>\n\n"+_bb_h(err),parse_mode="HTML")
        else:
            await msg.reply_text("🔮 <b>فال</b>\n\n"+_bb_h(body),parse_mode="HTML")
        return True

    if n=="بیو":
        body, err = await _bb_strict_bio()
        if err:
            await msg.reply_text("⚠️ <b>API بیو در دسترس نیست.</b>\n\n"+_bb_h(err),parse_mode="HTML")
        else:
            await msg.reply_text("🪪 <b>بیوی پیشنهادی</b>\n\n"+_bb_h(body),parse_mode="HTML")
        return True

    if n in {"دعا","دعای روز","دعای تصادفی","حدیث"}:
        body, err = await _bb_strict_hadith()
        if err:
            await msg.reply_text("⚠️ <b>API متن معنوی در دسترس نیست.</b>\n\n"+_bb_h(err),parse_mode="HTML")
        else:
            await msg.reply_text("🤲 <b>متن معنوی</b>\n\n"+_bb_h(body),parse_mode="HTML")
        return True

    if n in {"انگیزشی","انگیزه"}:
        body, err = await _bb_strict_motivation()
        if err:
            await msg.reply_text("⚠️ <b>API انگیزشی در دسترس نیست.</b>\n\n"+_bb_h(err),parse_mode="HTML")
        else:
            await msg.reply_text("💡 <b>انگیزشی</b>\n\n"+_bb_h(body),parse_mode="HTML")
        return True

    # Quran API-only.
    m = re.match(r"^(?:صفحه|صفحه قرآن|قرآن صفحه)\s*(\d{1,3})$",raw)
    if m:
        page=max(1,min(604,int(m.group(1))))
        try:
            st,data,_=await _bb_http_get_json(
                f"https://api.alquran.cloud/v1/page/{page}/quran-uthmani",timeout=20)
            ayahs=((data or {}).get("data") or {}).get("ayahs") or []
            if st!=200 or not ayahs:
                raise RuntimeError(f"Al Quran Cloud HTTP {st}")
            lines=[f"📖 <b>صفحه {page} قرآن</b>",""]
            for a in ayahs:
                lines.append(f'﴿{_bb_h(a.get("numberInSurah",""))}﴾ {_bb_h(a.get("text",""))}')
            await msg.reply_text("\n".join(lines)[:3900],parse_mode="HTML")
        except Exception as exc:
            await msg.reply_text("⚠️ <b>API قرآن در دسترس نیست.</b>\n\n"+_bb_h(str(exc)[:180]),parse_mode="HTML")
        return True

    return False

# Final API router wrapper.
_BB_BUILD_BEFORE_STRICT_API = build_application
def build_application(token: str) -> Application:
    app = _BB_BUILD_BEFORE_STRICT_API(token)
    app.add_handler(
        MessageHandler(filters.TEXT & ~filters.COMMAND, _bb_strict_api_router),
        group=-70000
    )
    return app


