# FINAL PROFILE CARD REPAIR
# =============================================================================
# Android/Pydroid Pillow builds may lack RAQM.  Without it Persian can appear
# disconnected, reversed, or as replacement boxes.  Use RAQM when available;
# otherwise shape Persian/Arabic letters with Unicode presentation forms.
import unicodedata as _bb_ucd

def _bb_profile_shape_rtl(text):
    text=str(text or '')
    try:
        from PIL import features as _bb_pil_features
        if _bb_pil_features.check('raqm'):
            return text, True
    except Exception:
        pass
    forms={
      'ا':('ﺍ','ﺎ'), 'آ':('ﺁ','ﺂ'), 'ب':('ﺏ','ﺐ','ﺑ','ﺒ'), 'پ':('ﭖ','ﭗ','ﭘ','ﭙ'),
      'ت':('ﺕ','ﺖ','ﺗ','ﺘ'), 'ث':('ﺙ','ﺚ','ﺛ','ﺜ'), 'ج':('ﺝ','ﺞ','ﺟ','ﺠ'),
      'چ':('ﭺ','ﭻ','ﭼ','ﭽ'), 'ح':('ﺡ','ﺢ','ﺣ','ﺤ'), 'خ':('ﺥ','ﺦ','ﺧ','ﺨ'),
      'د':('ﺩ','ﺪ'), 'ذ':('ﺫ','ﺬ'), 'ر':('ﺭ','ﺮ'), 'ز':('ﺯ','ﺰ'), 'ژ':('ﮊ','ﮋ'),
      'س':('ﺱ','ﺲ','ﺳ','ﺴ'), 'ش':('ﺵ','ﺶ','ﺷ','ﺸ'), 'ص':('ﺹ','ﺺ','ﺻ','ﺼ'),
      'ض':('ﺽ','ﺾ','ﺿ','ﻀ'), 'ط':('ﻁ','ﻂ','ﻃ','ﻄ'), 'ظ':('ﻅ','ﻆ','ﻇ','ﻈ'),
      'ع':('ﻉ','ﻊ','ﻋ','ﻌ'), 'غ':('ﻍ','ﻎ','ﻏ','ﻐ'), 'ف':('ﻑ','ﻒ','ﻓ','ﻔ'),
      'ق':('ﻕ','ﻖ','ﻗ','ﻘ'), 'ک':('ﮎ','ﮏ','ﮐ','ﮑ'), 'ك':('ﻙ','ﻚ','ﻛ','ﻜ'),
      'گ':('ﮒ','ﮓ','ﮔ','ﮕ'), 'ل':('ﻝ','ﻞ','ﻟ','ﻠ'), 'م':('ﻡ','ﻢ','ﻣ','ﻤ'),
      'ن':('ﻥ','ﻦ','ﻧ','ﻨ'), 'ه':('ﻩ','ﻪ','ﻫ','ﻬ'), 'و':('ﻭ','ﻮ'),
      'ی':('ﯼ','ﯽ','ﯾ','ﯿ'), 'ي':('ﻱ','ﻲ','ﻳ','ﻴ'), 'ئ':('ﺉ','ﺊ','ﺋ','ﺌ'),
      'ؤ':('ﺅ','ﺆ'), 'ة':('ﺓ','ﺔ'),
    }
    dual={k for k,v in forms.items() if len(v)==4}
    can_follow=set(forms)
    out=[]; i=0
    while i<len(text):
        c=text[i]
        if c=='ل' and i+1<len(text) and text[i+1] in {'ا','آ'}:
            out.append('ﻻ' if text[i+1]=='ا' else 'ﻵ'); i+=2; continue
        if c not in forms:
            out.append(c); i+=1; continue
        prev=text[i-1] if i else ''
        nxt=text[i+1] if i+1<len(text) else ''
        jp=prev in forms and prev in dual and c in can_follow
        jn=nxt in forms and c in dual and nxt in can_follow
        fs=forms[c]
        if len(fs)==2: out.append(fs[1] if jp else fs[0])
        else: out.append(fs[3] if jp and jn else fs[1] if jp else fs[2] if jn else fs[0])
        i+=1
    shaped=''.join(out)
    # Reverse RTL runs while preserving Latin/digit runs in their natural order.
    def rtlch(ch):
        return _bb_ucd.bidirectional(ch) in ('R','AL','AN') or '\u0600'<=ch<='\u06ff' or '\ufb50'<=ch<='\ufdff' or '\ufe70'<=ch<='\ufeff'
    chunks=[]; cur=''; cur_r=False
    for ch in shaped:
        r=rtlch(ch)
        if cur and r!=cur_r:
            chunks.append((cur_r,cur)); cur=''
        cur_r=r; cur+=ch
    if cur: chunks.append((cur_r,cur))
    return ''.join(part[::-1] if isr else part for isr,part in reversed(chunks)), False

async def _bb_make_profile_card_final(bot, chat_id, user):
    """Readable Persian profile card with live, detailed statistics.

    The card deliberately avoids emoji/custom-glyph rendering inside the image;
    this prevents square/box glyphs on hosts whose emoji fonts are incomplete.
    Persian is rendered with a Noto Arabic font and Pillow's RTL shaping.
    """
    try:
        from PIL import Image, ImageDraw, ImageFilter, ImageOps, ImageFont
        from io import BytesIO
    except Exception:
        log.exception('Pillow unavailable for profile card')
        return None

    try:
        # -------- live profile data --------
        u = {}; p = {}
        try: u = await DBX.get_user(user.id) or {}
        except Exception: pass
        if not u:
            try:
                await DBX.ensure_user(user)
                u = await DBX.get_user(user.id) or {}
            except Exception: pass
        try:
            p = await DBX.one(
                'SELECT bio,nickname,joined_at FROM user_profiles WHERE user_id=?',
                (user.id,)
            ) or {}
            if not isinstance(p, dict): p = dict(p)
        except Exception: p = {}
        if not isinstance(u, dict):
            try: u = dict(u)
            except Exception: u = {}

        first_name = safe_text(getattr(user, 'full_name', None) or getattr(user, 'first_name', None) or 'کاربر', 55)
        username = '@' + user.username if getattr(user, 'username', None) else 'بدون نام کاربری'
        bio = safe_text(p.get('bio', '') or 'بیو ثبت نشده', 110)
        title = 'لقب ندارد'
        level = max(1, int(u.get('level', 1) or 1))
        xp = max(0, int(u.get('xp', 0) or 0))
        games = max(0, int(u.get('games', 0) or 0))
        try: score = int(await _bb_profile_score(user.id) or 0)
        except Exception: score = 0
        try: mafia_level = max(1, int(await _bb_profile_mafia_level(user.id) or 1))
        except Exception: mafia_level = 1
        try: title = safe_text(await _bb_profile_title(chat_id, user.id, bot), 60) or title
        except Exception: pass

        # Group statistics from the live stats table. These are intentionally
        # independent of the image renderer so a stats lookup cannot break the card.
        total_messages = today_messages = total_adds = today_adds = call_seconds = 0
        membership_days = 0
        group_name = 'خصوصی'
        role = 'کاربر'
        if chat_id and chat_id > 0:
            try:
                # chat_member_stats is the canonical live counter in this bot.
                # It is updated by the unified message hook and is not affected by
                # the older bbx_stats presentation layer, so the profile card does
                # not double-count messages.
                live = await DBX.one(
                    'SELECT COALESCE(messages,0) messages, COALESCE(adds,0) adds, COALESCE(call_joins,0) calls, first_seen FROM chat_member_stats WHERE chat_id=? AND user_id=?',
                    (chat_id, user.id)
                )
                total_messages = int(live['messages'] or 0) if live else 0
                total_adds = int(live['adds'] or 0) if live else 0
                # Today's message count comes from the dedicated daily table.
                drow = await DBX.one(
                    'SELECT COALESCE(messages,0) messages FROM bb_message_daily WHERE chat_id=? AND user_id=? AND day=?',
                    (chat_id, user.id, _bb_local_now().strftime('%Y-%m-%d'))
                )
                today_messages = int(drow['messages'] or 0) if drow else 0
                # Adds today are tracked in the dedicated daily-add table.
                arow = await DBX.one(
                    'SELECT COALESCE(adds,0) adds FROM bb_member_daily_adds WHERE chat_id=? AND user_id=? AND day=?',
                    (chat_id, user.id, _bb_stats_day_local(0))
                )
                today_adds = int(arow['adds'] or 0) if arow else 0
                call_seconds = 0
                if live and live['first_seen']:
                    membership_days = max(1, (date.today() - datetime.fromtimestamp(int(live['first_seen'])).date()).days + 1)
            except Exception:
                pass
            try:
                ch = await bot.get_chat(chat_id)
                group_name = safe_text(getattr(ch, 'title', None) or 'گروه', 55)
            except Exception: pass
            try:
                m = await bot.get_chat_member(chat_id, user.id)
                role = {'creator':'مالک','administrator':'ادمین','member':'کاربر','restricted':'کاربر محدود'}.get(str(m.status), 'کاربر')
            except Exception: pass

        created_ts = int(p.get('joined_at') or u.get('created_at') or 0)
        try:
            from zoneinfo import ZoneInfo
            now = datetime.now(ZoneInfo(os.getenv('BB_PROFILE_TIMEZONE', 'Asia/Tehran')))
        except Exception:
            now = datetime.now()
        try:
            created_at = datetime.fromtimestamp(created_ts, now.tzinfo) if created_ts > 0 else now
        except Exception:
            created_at = now
        try:
            jy,jm,jd = _bb_gregorian_to_jalali(created_at.year, created_at.month, created_at.day)
            created_date = f'{jy:04d}/{jm:02d}/{jd:02d}'
        except Exception:
            created_date = created_at.strftime('%Y/%m/%d')
        created_time = created_at.strftime('%H:%M')

        # -------- canvas / fonts --------
        W, H = 1500, 900
        bg_bytes = None
        try: bg_bytes = await _bb_get_bot_avatar_bytes(bot)
        except Exception: pass
        if bg_bytes:
            try:
                bg = Image.open(BytesIO(bg_bytes)).convert('RGB')
                bg = ImageOps.fit(bg, (W,H), method=Image.Resampling.LANCZOS)
                bg = bg.filter(ImageFilter.GaussianBlur(7)).convert('RGBA')
                bg = Image.alpha_composite(bg, Image.new('RGBA',(W,H),(5,5,10,225)))
            except Exception:
                bg = Image.new('RGBA',(W,H),(10,10,16,255))
        else:
            bg = Image.new('RGBA',(W,H),(10,10,16,255))
        draw = ImageDraw.Draw(bg)

        def pick_font(size, bold=False):
            names = (
                ['NotoNaskhArabic-Bold.ttf','NotoKufiArabic-Bold.ttf','NotoSansArabic-Bold.ttf','DejaVuSans-Bold.ttf']
                if bold else
                ['NotoNaskhArabic-Regular.ttf','NotoKufiArabic-Regular.ttf','NotoSansArabic-Regular.ttf','DejaVuSans.ttf']
            )
            roots = ['/usr/share/fonts','/system/fonts','/data/user/0/ru.iiec.pydroid3/files']
            candidates=[]
            for root in roots:
                for name in names:
                    candidates.append(os.path.join(root,name))
                    candidates.extend(glob.glob(os.path.join(root,'**',name), recursive=True)) if os.path.isdir(root) else None
            for fp in candidates:
                try:
                    if os.path.exists(fp): return ImageFont.truetype(fp,size)
                except Exception: pass
            return ImageFont.load_default()

        f_title=pick_font(48,True); f_name=pick_font(38,True); f_head=pick_font(27,True)
        f_body=pick_font(24,False); f_small=pick_font(20,False); f_value=pick_font(30,True)

        gold=(238,190,72,255); white=(250,250,250,255); muted=(190,190,198,255)
        panel=(8,8,14,235); line=(155,130,72,230)
        draw.rounded_rectangle((24,24,W-24,H-24), radius=34, fill=(4,4,9,115), outline=(170,170,178,220), width=3)
        draw.rounded_rectangle((360,52,W-55,250), radius=28, fill=panel, outline=line, width=2)
        draw.rounded_rectangle((360,285,W-55,555), radius=28, fill=panel, outline=line, width=2)
        draw.rounded_rectangle((360,590,W-55,845), radius=28, fill=panel, outline=line, width=2)

        def _profile_label(text):
            try: return _bb_ui_get(str(text), 'text')
            except Exception: return str(text or '')

        def _profile_plain(text):
            import re as _pre
            t=str(text or '')
            t=_pre.sub(r'<tg-emoji[^>]*>.*?</tg-emoji>', '', t, flags=_pre.S)
            t=_pre.sub(r'<[^>]+>', '', t)
            return ''.join(ch for ch in t if not (0x1F000 <= ord(ch) <= 0x1FAFF)).strip()

        def rtl(x,y,text,font,fill=white,anchor='ra'):
            text=_profile_plain(_profile_label(text))
            try:
                shaped,has_raqm=_bb_profile_shape_rtl(text)
                if has_raqm:
                    draw.text((x,y), shaped, font=font, fill=fill, anchor=anchor, direction='rtl', language='fa', spacing=6)
                else:
                    draw.text((x,y), shaped, font=font, fill=fill, anchor=anchor, spacing=6)
            except Exception:
                draw.text((x,y), text, font=font, fill=fill, anchor=anchor)
        def ltr(x,y,text,font,fill=white,anchor='la'):
            try: draw.text((x,y), str(text or ''), font=font, fill=fill, anchor=anchor)
            except Exception: pass

        # Avatar
        avatar_b=None
        try: avatar_b=await _bb_get_user_avatar_bytes(bot,user.id)
        except Exception: pass
        ax,ay,asize=70,115,245
        if avatar_b:
            try:
                av=Image.open(BytesIO(avatar_b)).convert('RGB')
                av=ImageOps.fit(av,(asize,asize),method=Image.Resampling.LANCZOS)
                mask=Image.new('L',(asize,asize),0); ImageDraw.Draw(mask).ellipse((0,0,asize,asize),fill=255)
                bg.paste(av,(ax,ay),mask)
            except Exception: pass
        draw.ellipse((ax-8,ay-8,ax+asize+8,ay+asize+8), outline=gold, width=5)

        rtl(W-85,88,'پروفایل بیل بیلک',f_title,gold)
        rtl(W-85,145,first_name,f_name,white)
        ltr(420,118,username,f_body,muted)
        ltr(420,160,f'ID: {user.id}',f_body,muted)
        rtl(W-85,205,f'نقش: {role}',f_body,white)
        rtl(690,205,f'گروه: {group_name}',f_body,white)

        # XP bar
        rtl(W-85,310,f'سطح {level}',f_head,gold)
        bar_l,bar_r,bar_t,bar_b=410,W-85,355,398
        draw.rounded_rectangle((bar_l,bar_t,bar_r,bar_b),radius=21,fill=(38,38,45,255))
        ratio=max(0,min(1,(xp%100)/100))
        if ratio:
            draw.rounded_rectangle((bar_l,bar_t,bar_l+max(10,int((bar_r-bar_l)*ratio)),bar_b),radius=21,fill=gold)
        rtl(W-85,430,f'{xp%100} از 100 امتیاز تا سطح بعد',f_small,muted)

        # Five key values, no emoji/custom glyphs.
        cells=[(455,'امتیاز',score),(675,'بازی ها',games),(895,'سطح مافیا',mafia_level),(1115,'پیام امروز',today_messages),(1325,'کل پیام',total_messages)]
        for x,label,val in cells:
            rtl(x,480,label,f_small,gold,'ma'); rtl(x,520,str(val),f_value,white,'ma')

        # Detailed live stats
        rtl(W-85,620,'آمار دقیق کاربر',f_head,gold)
        detail=[
            ('کل پیام ها',total_messages),('پیام امروز',today_messages),
            ('کل ادها',total_adds),('اد امروز',today_adds),
            ('روزهای حضور',membership_days),('زمان تماس',f'{call_seconds} ثانیه'),
            ('لقب',title),('تاریخ ساخت',created_date),('ساعت ساخت',created_time),
        ]
        cols=[(650,675),(980,675),(1310,675)]
        for i,(label,val) in enumerate(detail):
            x,y=cols[i%3]; yy=y+(i//3)*55
            rtl(x,yy,label,f_small,gold,'ra')
            sval=str(val)
            if re.fullmatch(r'[0-9:/ .,+-]+',sval):
                ltr(x,yy+28,sval,f_small,white,'ra')
            else:
                rtl(x,yy+28,sval,f_small,white,'ra')
        rtl(W-85,835,f'بیو: {bio}',f_small,muted)

        out=BytesIO(); out.name='bilbilak_profile.jpg'
        bg.convert('RGB').save(out,format='JPEG',quality=94,optimize=True)
        out.seek(0)
        return out
    except Exception as exc:
        log.exception('FINAL readable profile card failed: %r', exc)
        return None

