async def _bb_repaired_api_panel_callback(update, context):
    q=getattr(update,'callback_query',None)
    if q and str(getattr(q,'data',''))=='bbfinalapi:panel':
        await q.answer(); await _bb_final_tools_api_panel_repaired(q,context); return

_BB_BUILD_BEFORE_REPAIRED_PANEL=build_application
def build_application(token: str) -> Application:
    app=_BB_BUILD_BEFORE_REPAIRED_PANEL(token)
    app.add_handler(CallbackQueryHandler(_bb_repaired_api_panel_callback, pattern=r'^bbfinalapi:panel$'), group=-40000)
    return app


# Update the final mandatory route so Pillow is the only hard dependency.
async def _bb_profile_card_mandatory(update, context):
    msg=getattr(update,'effective_message',None)
    if not msg: raise ApplicationHandlerStop
    try:
        result=await _bb_profile_card_command(update,context)
        raise ApplicationHandlerStop
    except ApplicationHandlerStop:
        raise
    except Exception as exc:
        log.exception('final mandatory profile route failed: %r',exc)
        try: await msg.reply_text('❌ کارت پروفایل ساخته نشد.\n\nجزئیات خطا در لاگ سرور ثبت شد.')
        except Exception: pass
        raise ApplicationHandlerStop

# The API panel must expose the Iranian-market currency key.
async def _bb_final_tools_api_panel_repaired(q, context):
    uid=getattr(q.from_user,'id',0)
    if not await _bb_is_bot_admin(uid):
        await q.answer('⛔ فقط مالک/مدیر اصلی می‌تواند APIها را تنظیم کند.',show_alert=True); raise ApplicationHandlerStop

    # Central API registry. Every service has a dedicated field in the bot panel.
    # Some providers genuinely do not require a key; their field is still present
    # so the owner can keep all service credentials in one place. The bot only
    # sends a credential to a provider when that provider supports authentication.
    api_items = [
        ('🤖 Telegram Bot Token','BOT_TOKEN','هسته ربات / Bot API',True),
        ('🧠 OpenRouter','OPENROUTER_API_KEY','هوش مصنوعی و Vision',True),
        ('🌍 REST Countries','RESTCOUNTRIES_API_KEY','کشورها و اطلاعات جغرافیایی',True),
        ('🏟️ API-Sports','APISPORTS_API_KEY','فوتبال و ورزش',True),
        ('📰 GNews','GNEWS_API_KEY','اخبار',True),
        ('💱 NetArz','NETARZ_API_KEY','نرخ بازار ارز ایران',True),
        ('🧩 MajidAPI','MAJID_API_TOKEN','فال، بیو، متن معنوی و انگیزشی',True),
        ('📸 Meta / Instagram','META_ACCESS_TOKEN','آنالیز اینستاگرام',True),
        ('🆔 Instagram User ID','META_IG_USER_ID','شناسه حساب اینستاگرام',True),
        ('🌦️ Open-Meteo','OPENMETEO_API_KEY','آب‌وهوا؛ کلید در صورت داشتن کلید/پروکسی',False),
        ('📖 Quran / Al Quran Cloud','QURAN_API_KEY','قرآن؛ کلید اختیاری برای تنظیم مرکزی',False),
        ('🕐 WorldTimeAPI','WORLDTIME_API_KEY','زمان جهانی؛ کلید اختیاری',False),
        ('📍 Maps / Geocoding','MAPS_API_KEY','جستجوی مکان و مختصات؛ وابسته به سرویس نقشه انتخابی',True),
        ('🆔 Telegram API ID','TELEGRAM_API_ID','برای کلاینت شخصی/موزیکال',True),
        ('🔐 Telegram API Hash','TELEGRAM_API_HASH','برای کلاینت شخصی/موزیکال',True),
    ]
    vals = {key: (await _bb_pro_get(key,'')) for _,key,_,_ in api_items}
    configured = sum(1 for v in vals.values() if v)
    lines=['🔑 <b>مرکز کامل تنظیم APIهای بیل بیلک</b> 🐾',
           f'\n📊 تنظیم شده: <b>{configured}/{len(api_items)}</b>',
           '💡 هر مورد دکمه مستقل دارد؛ بعد از انتخاب، مقدار را در PV ربات بفرست.',
           '']
    for label,key,desc,required in api_items:
        status='🟢' if vals[key] else ('🔴' if required else '⚪')
        lines.append(f'{status} {label}: <code>{key}</code>')
        lines.append(f'   ↳ {desc}')
    lines.append('')
    lines.append('⚠️ برای سرویس‌هایی که خودشان API Key ندارند، وارد کردن مقدار الزامی نیست و ربات بدون آن سرویس را استفاده می‌کند.')
    lines.append('')
    lines.append('🔒 کلیدها در تنظیمات داخلی ربات ذخیره می‌شوند.')

    buttons=[]
    # Keep the panel usable on a phone: two columns for the long list.
    for i in range(0,len(api_items),2):
        row=[]
        for label,key,_,_ in api_items[i:i+2]:
            row.append(btn(label, f'bbfinalapi:set:{key}'))
        buttons.append(row)
    buttons += [[btn('🔄 بروزرسانی وضعیت','bbfinalapi:panel')],[btn('❌ بستن پنل','panelclose')]]
    await q.edit_message_text('\n'.join(lines),parse_mode='HTML',reply_markup=keyboard(buttons))
    raise ApplicationHandlerStop

_bb_final_tools_api_panel = _bb_final_tools_api_panel_repaired


# ===================== BILBILAK V3 MEGA EXTENSION =====================
# افزونه‌ی نهایی: مسیرهای فارسی، پروفایل، API، آمار، نجوا، هاپو، بازی و مدیریت
# این بخش عمداً مستقل است و قبل از entrypoint به فایل پایه تزریق می‌شود.

BBX_DB_LOCK = asyncio.Lock()
BBX_API_WAIT = {}
BBX_WHISPER_WAIT = {}
BBX_WHISPERS = {}
BBX_STATS_CACHE = defaultdict(lambda: defaultdict(lambda: defaultdict(int)))
BBX_FLOOD = defaultdict(deque)
BBX_WARNING_LIMIT_DEFAULT = 3
BBX_FORBIDDEN = re.compile(r'(?:porn|xxx|nude|مواد\s*مخدر)', re.I)


def bbx_db():
    con = sqlite3.connect(DB_PATH, timeout=30)
    con.row_factory = sqlite3.Row
    return con


def bbx_init_db():
    con = bbx_db()
    con.executescript('''
    CREATE TABLE IF NOT EXISTS bbx_profiles(user_id INTEGER PRIMARY KEY, bio TEXT DEFAULT '', nickname TEXT DEFAULT '', joined_at INTEGER DEFAULT 0, bones INTEGER DEFAULT 0, xp INTEGER DEFAULT 0, level INTEGER DEFAULT 1, hop INTEGER DEFAULT 0, dog_name TEXT DEFAULT '', dog_level INTEGER DEFAULT 1);
    CREATE TABLE IF NOT EXISTS bbx_group_settings(chat_id INTEGER PRIMARY KEY, rules TEXT DEFAULT '', welcome INTEGER DEFAULT 1, warning_limit INTEGER DEFAULT 3, strict INTEGER DEFAULT 0, force_join INTEGER DEFAULT 0, force_join_count INTEGER DEFAULT 0, channel_link TEXT DEFAULT '', filtered_words TEXT DEFAULT '', muted_all INTEGER DEFAULT 0);
    CREATE TABLE IF NOT EXISTS bbx_warnings(chat_id INTEGER, user_id INTEGER, count INTEGER DEFAULT 0, PRIMARY KEY(chat_id,user_id));
    CREATE TABLE IF NOT EXISTS bbx_apis(k TEXT PRIMARY KEY, v TEXT NOT NULL DEFAULT '');
    CREATE TABLE IF NOT EXISTS bbx_channels(owner_id INTEGER PRIMARY KEY, channel TEXT NOT NULL DEFAULT '');
    CREATE TABLE IF NOT EXISTS bbx_stats(chat_id INTEGER, user_id INTEGER, day TEXT, messages INTEGER DEFAULT 0, adds INTEGER DEFAULT 0, call_seconds INTEGER DEFAULT 0, PRIMARY KEY(chat_id,user_id,day));
    CREATE TABLE IF NOT EXISTS bbx_whispers(id TEXT PRIMARY KEY, chat_id INTEGER, sender_id INTEGER, receiver_id INTEGER, payload TEXT, created_at INTEGER, expires_at INTEGER, read INTEGER DEFAULT 0);
    CREATE TABLE IF NOT EXISTS bbx_hop(chat_id INTEGER, user_id INTEGER, points INTEGER DEFAULT 0, dog_name TEXT DEFAULT '', dog_level INTEGER DEFAULT 1, hook_level INTEGER DEFAULT 1, bank INTEGER DEFAULT 0, city INTEGER DEFAULT 1, factory INTEGER DEFAULT 0, PRIMARY KEY(chat_id,user_id));
    CREATE TABLE IF NOT EXISTS bbx_bio_index(user_id INTEGER PRIMARY KEY, last_bio TEXT DEFAULT '');
    ''')
    con.commit(); con.close()

bbx_init_db()


def bbx_get_profile(uid):
    con=bbx_db(); r=con.execute('SELECT * FROM bbx_profiles WHERE user_id=?',(uid,)).fetchone()
    if not r:
        con.execute('INSERT INTO bbx_profiles(user_id,joined_at) VALUES(?,?)',(uid,int(time.time()))); con.commit(); r=con.execute('SELECT * FROM bbx_profiles WHERE user_id=?',(uid,)).fetchone()
    con.close(); return r


def bbx_set_api(k,v):
    con=bbx_db(); con.execute('INSERT INTO bbx_apis(k,v) VALUES(?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v',(k,v)); con.commit(); con.close()


def bbx_get_api(k,default=''):
    con=bbx_db(); r=con.execute('SELECT v FROM bbx_apis WHERE k=?',(k,)).fetchone(); con.close(); return r['v'] if r else default


def bbx_group(cid):
    con=bbx_db(); r=con.execute('SELECT * FROM bbx_group_settings WHERE chat_id=?',(cid,)).fetchone()
    if not r:
        con.execute('INSERT INTO bbx_group_settings(chat_id) VALUES(?)',(cid,)); con.commit(); r=con.execute('SELECT * FROM bbx_group_settings WHERE chat_id=?',(cid,)).fetchone()
    con.close(); return r


def bbx_escape(s):
    return telegram.helpers.escape_markdown(str(s or ''),version=2)


def bbx_html(s):
    return telegram.helpers.escape(safe_text(str(s or ''),500)) if 'safe_text' in globals() else str(s or '')


def bbx_is_owner(uid):
    try: return int(uid)==int(os.getenv('OWNER_ID','0')) or int(uid)==int(globals().get('OWNER_ID',0))
    except: return False


async def bbx_is_admin(update, uid=None):
    uid = uid or update.effective_user.id
    if bbx_is_owner(uid): return True
    chat=update.effective_chat
    if not chat or chat.type=='private': return False
    try:
        m=await chat.get_member(uid)
        return m.status in (ChatMemberStatus.ADMINISTRATOR,ChatMemberStatus.OWNER)
    except Exception: return False


def bbx_user_target(update):
    msg=update.effective_message
    if msg and msg.reply_to_message and msg.reply_to_message.from_user:
        return msg.reply_to_message.from_user
    parts=(msg.text or '').split() if msg else []
    # آیدی متنی: فقط عدد/یوزرنیم پذیرفته نمی‌شود؛ «آیدی» در این نسخه با شناسه عددی ریپلای/متن پشتیبانی می‌شود.
    if len(parts)>1 and parts[1].isdigit():
        class U: pass
        u=U(); u.id=int(parts[1]); u.first_name='کاربر'; u.username=''; return u
    return None


def bbx_stat(cid,uid,field='messages',amount=1):
    d=date.today().isoformat(); con=bbx_db();
    con.execute('INSERT OR IGNORE INTO bbx_stats(chat_id,user_id,day) VALUES(?,?,?)',(cid,uid,d))
    con.execute(f'UPDATE bbx_stats SET {field}={field}+? WHERE chat_id=? AND user_id=? AND day=?',(amount,cid,uid,d)); con.commit(); con.close()


def bbx_stat_rows(cid,days,field):
    since=(date.today()-timedelta(days=days-1)).isoformat(); con=bbx_db()
    rows=con.execute(f'''SELECT user_id,SUM({field}) n FROM bbx_stats WHERE chat_id=? AND day>=? GROUP BY user_id ORDER BY n DESC LIMIT 20''',(cid,since)).fetchall(); con.close(); return rows


def bbx_user_stat(cid,uid,days=None):
    con=bbx_db();
    if days:
        since=(date.today()-timedelta(days=days-1)).isoformat(); r=con.execute('SELECT COALESCE(SUM(messages),0) m,COALESCE(SUM(adds),0) a,COALESCE(SUM(call_seconds),0) c FROM bbx_stats WHERE chat_id=? AND user_id=? AND day>=?',(cid,uid,since)).fetchone()
    else: r=con.execute('SELECT COALESCE(SUM(messages),0) m,COALESCE(SUM(adds),0) a,COALESCE(SUM(call_seconds),0) c FROM bbx_stats WHERE chat_id=? AND user_id=?',(cid,uid)).fetchone()
    con.close(); return r


def bbx_hop(cid,uid):
    con=bbx_db(); r=con.execute('SELECT * FROM bbx_hop WHERE chat_id=? AND user_id=?',(cid,uid)).fetchone()
    if not r:
        con.execute('INSERT INTO bbx_hop(chat_id,user_id) VALUES(?,?)',(cid,uid)); con.commit(); r=con.execute('SELECT * FROM bbx_hop WHERE chat_id=? AND user_id=?',(cid,uid)).fetchone()
    con.close(); return r


def bbx_hop_update(cid,uid,**kw):
    con=bbx_db(); bbx_hop(cid,uid)
    sets=[]; vals=[]
    for k,v in kw.items(): sets.append(f'{k}=?'); vals.append(v)
    vals += [cid,uid]; con.execute(f'UPDATE bbx_hop SET {", ".join(sets)} WHERE chat_id=? AND user_id=?',vals); con.commit(); con.close()


def bbx_btn_copy(label,text):
    # Telegram has no universal clipboard button. The safest portable fallback is a URL that opens a prefilled message.
    return InlineKeyboardButton(label,url='https://t.me/share/url?url=&text='+quote_plus(text))


