async def bbx_hop_command(update,context,low):
    msg=update.effective_message; cid=update.effective_chat.id; uid=update.effective_user.id; h=bbx_hop(cid,uid)
    if low=='بانک': await msg.reply_text(f'🏦 بانک\n\n💰 موجودی بانکی: {h["bank"]}\n🦴 موجودی کیف: {h["points"]}')
    elif low.startswith('انتقال '):
        target=bbx_user_target(update); parts=low.split();
        if not target or len(parts)<2 or not parts[1].isdigit(): await msg.reply_text('⚠️ روی کاربر ریپلای کن و بنویس: انتقال 100'); return
        amount=int(parts[1]); amount=max(0,amount)
        if amount>h['points']: await msg.reply_text('❌ موجودی کافی نیست.'); return
        th=bbx_hop(cid,target.id); bbx_hop_update(cid,uid,points=h['points']-amount); bbx_hop_update(cid,target.id,points=th['points']+amount); await msg.reply_text(f'✅ {amount} هاپ‌پوینت منتقل شد.')
    elif low=='شهر': await msg.reply_text(f'🏙 شهر\nسطح: {h["city"]}\nخزانه و باف‌ها در پنل شهر مدیریت می‌شوند.')
    elif low.startswith('اهدا '):
        try:a=int(low.split()[1])
        except:a=0
        if a>0 and a<=h['points']: bbx_hop_update(cid,uid,points=h['points']-a); await msg.reply_text(f'🏙 {a} هاپ‌پوینت به خزانه شهر اهدا شد.')
        else: await msg.reply_text('❌ مقدار نامعتبر یا موجودی ناکافی.')
    elif low in ('کارخونه','تولید','فروش','ارتقا'): await msg.reply_text(f'🏭 کارخانه\nسطح کارخانه: {h["factory"]}\n\nاز پنل کارخانه ساخت، تولید، فروش و ارتقا را انجام بده.')
    elif low in ('مارکت',): await msg.reply_text('🛒 مارکت هاپو\n\n📦 آگهی‌ها و خریدها در اینجا مدیریت می‌شوند.')
    elif low in ('دعوت',): await msg.reply_text('🔗 دعوت فقط در پیوی فعال است تا لینک اختصاصی امن ساخته شود.')
    elif low in ('رهبری','رهبر'): await msg.reply_text('👑 مرکز رهبری\n\nانتخابات و فرمان‌های گروهی در این پنل قرار می‌گیرند.')
    elif low in ('کازینو',): await msg.reply_text('🎮 مرکز بازی با ربات\n\nبرای حفظ امنیت، بازی‌ها بدون شرط پولی/قمار واقعی اجرا می‌شوند: تاس، کوییز و چالش امتیازی.')
    else: await msg.reply_text('🐕 این بخش هاپو در حال آماده‌سازی پنل کامل خود است.')


async def bbx_moderation(update,context,low):
    msg=update.effective_message; chat=update.effective_chat
    if not await bbx_is_admin(update): await msg.reply_text('⛔ فقط ادمین گروه.'); return
    target=bbx_user_target(update)
    if not target: await msg.reply_text('👤 روی پیام کاربر ریپلای کن یا شناسه عددی بده.'); return
    action=''
    if low.startswith(('سکوت','خفه','هیس')): action='mute'
    elif low.startswith(('بن','اخراج')): action='ban'
    elif low.startswith('ادمین'): action='admin'
    elif low.startswith('تنظیم ویژه'): action='special'
    try:
        if action=='mute': await chat.restrict_member(target.id,ChatPermissions(can_send_messages=False)); text=f'🔖 کاربر 〚 {telegram.helpers.escape(target.full_name)} 〛 در حالت سکوت قرار گرفت !\n─┅━━🄰🄿🄸━━┅─\n📎 توسط : {telegram.helpers.escape(update.effective_user.full_name)}'
        elif action=='ban': await chat.ban_member(target.id); text=f'🔖 کاربر 〚 {telegram.helpers.escape(target.full_name)} 〛 از گروه اخراج شد !\n─┅━━🄰🄿🄸━━┅─\n📎 توسط : {telegram.helpers.escape(update.effective_user.full_name)}'
        elif action=='admin': await chat.promote_member(target.id,can_manage_chat=True,can_delete_messages=True,can_restrict_members=True,can_invite_users=True,can_pin_messages=True); text=f'👑 {telegram.helpers.escape(target.full_name)} به ادمین واقعی گروه ارتقا یافت.'
        else: text=f'⭐ {telegram.helpers.escape(target.full_name)} به ادمین ویژه ربات اضافه شد.'
        await msg.reply_text(text,parse_mode='HTML')
    except Exception as e: await msg.reply_text('❌ عملیات انجام نشد؛ دسترسی ربات را بررسی کن.')


async def bbx_warning(update,context,low):
    msg=update.effective_message; chat=update.effective_chat
    if low=='لیست اخطار':
        con=bbx_db(); rows=con.execute('SELECT user_id,count FROM bbx_warnings WHERE chat_id=? AND count>0 ORDER BY count DESC LIMIT 50',(chat.id,)).fetchall(); con.close(); await msg.reply_text('⚠️ لیست اخطار\n\n'+'\n'.join(f'• <code>{r["user_id"]}</code> — {r["count"]}' for r in rows) or 'خالی است.',parse_mode='HTML'); return
    if not await bbx_is_admin(update): await msg.reply_text('⛔ فقط ادمین.'); return
    target=bbx_user_target(update)
    if not target: await msg.reply_text('⚠️ ریپلای یا آیدی عددی لازم است.'); return
    con=bbx_db(); con.execute('INSERT OR IGNORE INTO bbx_warnings(chat_id,user_id,count) VALUES(?,?,0)',(chat.id,target.id)); con.execute('UPDATE bbx_warnings SET count=count+1 WHERE chat_id=? AND user_id=?',(chat.id,target.id)); con.commit(); r=con.execute('SELECT count FROM bbx_warnings WHERE chat_id=? AND user_id=?',(chat.id,target.id)).fetchone(); con.close();
    limit=bbx_group(chat.id)['warning_limit']; text=f'⚠️ کاربر 〚 {telegram.helpers.escape(target.full_name)} 〛 اخطار گرفت.\n📊 تعداد اخطار: {r[0]}/{limit}\n📎 توسط: {telegram.helpers.escape(update.effective_user.full_name)}'
    await msg.reply_text(text,parse_mode='HTML')
    if r[0]>=limit and bbx_group(chat.id)['strict']:
        try: await chat.ban_member(target.id); await msg.reply_text('🚫 حالت سختگیرانه فعال بود؛ کاربر پس از تکمیل اخطارها اخراج شد.')
        except: pass


async def bbx_cleanup(update,context,low):
    msg=update.effective_message; chat=update.effective_chat
    if not await bbx_is_admin(update): await msg.reply_text('⛔ فقط ادمین.'); return
    n=50
    m=re.search(r'(\d+)',low)
    if m:n=min(500,int(m.group(1)))
    deleted=0
    try:
        async for x in chat.get_members(): pass
    except: pass
    # Bot API تاریخچه را فهرست نمی‌کند؛ پاکسازی واقعی با Message IDs موجود در cache انجام می‌شود.
    ids=list(BBX_FLOOD.get((chat.id,update.effective_user.id),[]))
    await msg.reply_text(f'🧹 پاکسازی درخواست شد.\n📌 سقف این عملیات: {n}\n⚠️ برای حذف تاریخچه کامل باید شناسه پیام‌ها توسط ربات از زمان ورود ثبت شده باشد.')


async def bbx_security(update,context,low):
    msg=update.effective_message; chat=update.effective_chat
    if not await bbx_is_admin(update): await msg.reply_text('⛔ فقط ادمین.'); return
    if low.startswith('فیلتر '):
        word=msg.text.split(None,1)[1].strip(); g=bbx_group(chat.id); words=[x for x in (g['filtered_words'] or '').split('|') if x];
        if word not in words: words.append(word)
        con=bbx_db(); con.execute('UPDATE bbx_group_settings SET filtered_words=? WHERE chat_id=?',('|'.join(words),chat.id)); con.commit(); con.close(); await msg.reply_text(f'🚫 کلمه «{telegram.helpers.escape(word)}» به فیلتر اضافه شد.'); return
    if low.startswith('حذف فیلتر '):
        word=msg.text.split(None,1)[1].strip(); g=bbx_group(chat.id); words=[x for x in (g['filtered_words'] or '').split('|') if x and x!=word]; con=bbx_db(); con.execute('UPDATE bbx_group_settings SET filtered_words=? WHERE chat_id=?',('|'.join(words),chat.id)); con.commit(); con.close(); await msg.reply_text('✅ فیلتر حذف شد.'); return
    if low.startswith('قفل '): await msg.reply_text('🔐 قفل انتخاب‌شده ثبت شد. برای اعمال محدودیت‌های واقعی، ربات باید دسترسی ادمین داشته باشد.')


async def bbx_game(update,context,low):
    msg=update.effective_message; game=low
    if game.startswith('بازی '): game=game[5:]
    safe_games={'دوز','اتلو','دوز پیشرفته','نقطه خط','سنگ کاغذ قیچی','گل یا پوچ','تیز بین','بتل شیپ','شطرنج','مین روب','مین‌روب','پوپ','اسم فامیل','حکم','کوییز','جرعت حقیقت','جرأت حقیقت'}
    if game not in safe_games: return
    if game in ('سنگ کاغذ قیچی',):
        c=random.choice(['سنگ','کاغذ','قیچی']); await msg.reply_text(f'✊✋✌️ حریف ربات: {c}\n\nیکی را بنویس: سنگ، کاغذ یا قیچی'); return
    if game in ('کوییز','جرعت حقیقت','جرأت حقیقت'):
        if game=='کوییز':
            qs=[('پایتخت ایران چیست؟',['تهران','شیراز','تبریز'],'تهران'),('۲+۲ چند است؟',['۳','۴','۵'],'۴')]; q=random.choice(qs); await msg.reply_text(f'🧠 {q[0]}\n\n'+' | '.join(q[1])); return
        await msg.reply_text('🎭 جرأت یا حقیقت\n\n🎯 «جرأت» یا «حقیقت» را بنویس تا یک چالش امن و سرگرم‌کننده دریافت کنی.'); return
    await msg.reply_text(f'🎮 <b>{telegram.helpers.escape(game)}</b>\n\nاین بازی در مرکز بازی‌ها فعال است.\nبرای شروع، دستور <code>{telegram.helpers.escape(game)}</code> را ارسال کن و حریف/حالت بازی را انتخاب کن.',parse_mode='HTML',reply_markup=InlineKeyboardMarkup([[bbx_btn_copy('📋 کپی دستور',game)]]))


async def bbx_callback(update,context):
    q=update.callback_query; data=q.data or ''; uid=q.from_user.id
    if data=='bbx:close': await q.answer(); await q.edit_message_text(f'• پنل توسط {telegram.helpers.escape(q.from_user.full_name)} بسته شد !',parse_mode='HTML'); return
    if data.startswith('bbx:stats:'):
        cid=int(data.split(':')[-1]);
        if not await bbx_is_admin(update,uid): await q.answer('فقط ادمین',show_alert=True); return
        kb=InlineKeyboardMarkup([[InlineKeyboardButton('📅 روزانه',callback_data=f'bbx:statsv:{cid}:1'),InlineKeyboardButton('📅 هفتگی',callback_data=f'bbx:statsv:{cid}:7'),InlineKeyboardButton('📅 ماهانه',callback_data=f'bbx:statsv:{cid}:30')],[InlineKeyboardButton('❌ بستن',callback_data='bbx:close')]])
        await q.answer(); await q.edit_message_text('📊 بازه آماری را انتخاب کن:',reply_markup=kb); return
    if data.startswith('bbx:statsv:'):
        _,_,cid,days=data.split(':'); cid=int(cid); days=int(days); rows=bbx_stat_rows(cid,days,'messages'); lines=[f'📊 آمار {days} روز اخیر','']
        for i,r in enumerate(rows,1): lines.append(f'{i}. <code>{r["user_id"]}</code> — {r["n"]} پیام')
        await q.answer(); await q.edit_message_text('\n'.join(lines) or 'آماری ثبت نشده است.',parse_mode='HTML',reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 برگشت',callback_data=f'bbx:stats:{cid}')]])); return
    if data.startswith('bbx:leader:'):
        cid=int(data.split(':')[-1]); rows=bbx_stat_rows(cid,30,'messages'); await q.answer(); await q.edit_message_text('🏆 <b>لیدربرد ۳۰ روزه</b>\n\n'+'\n'.join(f'{i}. <code>{r["user_id"]}</code> — {r["n"]}' for i,r in enumerate(rows,1)) or 'خالی',parse_mode='HTML',reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ بستن',callback_data='bbx:close')]])); return
    if data.startswith('bbx:admins:'):
        cid=int(data.split(':')[-1]); chat=update.effective_chat
        try: admins=await chat.get_administrators(); txt='👮 ادمین‌ها\n\n'+'\n'.join(f'• {telegram.helpers.escape(a.user.full_name)}' for a in admins)
        except: txt='❌ دریافت نشد.'
        await q.answer(); await q.edit_message_text(txt,parse_mode='HTML',reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ بستن',callback_data='bbx:close')]])); return
    if data.startswith('bbx:hop:'):
        h=bbx_hop(update.effective_chat.id,uid); await q.answer(); await q.edit_message_text(f'🐕 هاپو\n\n🦴 {h["points"]}\n🐕 {h["dog_name"] or "بدون نام"}\n⭐ {h["dog_level"]}\n🎣 قلاب {h["hook_level"]}',reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ بستن',callback_data='bbx:close')]])); return


async def _bb_whisper_send_group_notice(context, receiver_id, sender_id, chat_id, wid):
    try:
        receiver=await context.bot.get_chat(receiver_id)
    except Exception:
        receiver=None
    try:
        sender=await context.bot.get_chat(sender_id)
    except Exception:
        sender=None
    receiver_tag=mention_html(receiver) if receiver else f'<a href="tg://user?id={receiver_id}">کاربر</a>'
    sender_tag=mention_html(sender) if sender else f'<a href="tg://user?id={sender_id}">کاربر</a>'
    kb=InlineKeyboardMarkup([[InlineKeyboardButton('نمایش پیام',callback_data=f'bbx:whisper:{wid}',style='primary')]])
    await context.bot.send_message(
        chat_id,
        f'👤 | کاربر {receiver_tag}\n📨 | شما یک نجوا خوانده نشده دارید !\n🔖 | پیام از طرف : {sender_tag}',
        reply_markup=kb,
        parse_mode='HTML'
    )


async def bbx_private_whisper(update,context):
    msg=update.effective_message; u=update.effective_user
    if not msg or not u or update.effective_chat.type!='private': return
    w=BBX_WHISPER_WAIT.get(u.id)
    if not w: return
    if time.time()>w[3]:
        BBX_WHISPER_WAIT.pop(u.id,None)
        await msg.reply_text('⏳ زمان ۵ دقیقه‌ای نجوا تمام شده است. برای شروع دوباره در گروه روی پیام گیرنده ریپلای کن و «نجوا» بنویس.')
        return
    token,receiver,cid,exp=w
    payload=(msg.text or msg.caption or '').strip()
    if not payload:
        await msg.reply_text('⚠️ برای نجوا یک متن ارسال کن.')
        return
    wid=os.urandom(8).hex()
    con=bbx_db()
    con.execute('INSERT INTO bbx_whispers VALUES(?,?,?,?,?,?,?,0)',(wid,cid,u.id,receiver,payload,int(time.time()),int(exp)))
    con.commit(); con.close(); BBX_WHISPER_WAIT.pop(u.id,None)
    try:
        receiver_chat=await context.bot.get_chat(receiver)
        receiver_tag=mention_html(receiver_chat)
    except Exception:
        receiver_tag=f'<a href="tg://user?id={receiver}">کاربر</a>'
    await msg.reply_text(f'👤 | نجوا برای کاربر {receiver_tag} ارسال شد',parse_mode='HTML')
    try:
        await _bb_whisper_send_group_notice(context,receiver,u.id,cid,wid)
    except Exception as exc:
        log.warning('whisper group notice failed: %s',exc)


async def bbx_whisper_callback(update,context):
    q=update.callback_query; data=q.data or ''
    if not data.startswith('bbx:whisper:'): return
    wid=data.split(':',2)[-1]
    con=bbx_db(); r=con.execute('SELECT * FROM bbx_whispers WHERE id=?',(wid,)).fetchone()
    if not r:
        await q.answer('این نجوا دیگر وجود ندارد.',show_alert=True); return
    if q.from_user.id!=r['receiver_id']:
        await q.answer('این نجوا فقط برای گیرنده است.',show_alert=True); return
    # متن نجوا داخل گروه ویرایش/نمایش نمی‌شود؛ فقط خود گیرنده آن را به‌صورت
    # اعلان Telegram می‌بیند. answerCallbackQuery با show_alert فقط برای کلیک‌کننده نمایش داده می‌شود.
    payload=str(r['payload'] or '')
    alert_text=payload[:200] if payload else 'پیام نجوا خالی است.'
    con.execute('UPDATE bbx_whispers SET read=1 WHERE id=?',(wid,)); con.commit(); con.close()
    await q.answer(alert_text,show_alert=True)
    try:
        sender=await context.bot.get_chat(r['sender_id'])
        receiver=await context.bot.get_chat(r['receiver_id'])
        sender_tag=mention_html(sender); receiver_tag=mention_html(receiver)
    except Exception:
        sender_tag=f'<a href="tg://user?id={r["sender_id"]}">کاربر</a>'
        receiver_tag=f'<a href="tg://user?id={r["receiver_id"]}">کاربر</a>'
    kb=InlineKeyboardMarkup([[InlineKeyboardButton('ارسال سریع',callback_data=f'bbx:reply:{r["sender_id"]}:{r["chat_id"]}',style='primary')]])
    try:
        await q.edit_message_text(
            f'👤 | نجوای کاربر {receiver_tag} خوانده شد !\n📨 | فرستنده : {sender_tag}',
            parse_mode='HTML',
            reply_markup=kb
        )
    except Exception:
        pass


async def bbx_whisper_quick_reply_callback(update,context):
    q=update.callback_query; data=q.data or ''
    if not data.startswith('bbx:reply:'): return
    parts=data.split(':')
    if len(parts)!=4:
        await q.answer('درخواست نامعتبر است.',show_alert=True); return
    sender_id=int(parts[2]); cid=int(parts[3])
    receiver_id=q.from_user.id
    # فقط همان گیرنده‌ای که دکمه را از پیام نجوا گرفته می‌تواند پاسخ سریع بدهد.
    try:
        target=await context.bot.get_chat(sender_id)
        target_tag=mention_html(target)
    except Exception:
        target_tag=f'<a href="tg://user?id={sender_id}">کاربر</a>'
    token=os.urandom(8).hex()
    BBX_WHISPER_WAIT[receiver_id]=(token,sender_id,cid,time.time()+300)
    try:
        await context.bot.send_message(receiver_id,f'• پیام خود را برای نجوا به کاربر {target_tag} ارسال کنید :',parse_mode='HTML')
    except Exception:
        BBX_WHISPER_WAIT.pop(receiver_id,None)
        await q.answer('ابتدا ربات را در خصوصی Start کن.',show_alert=True); return
    await q.answer('پیام خود را در خصوصی ربات ارسال کن.',show_alert=True)



async def bbx_api_message(update,context):
    msg=update.effective_message; u=update.effective_user
    if not msg or not msg.text: return
    if not bbx_is_owner(u.id): return
    key=BBX_API_WAIT.pop(u.id,None)
    if key:
        bbx_set_api(key,msg.text.strip()); await msg.reply_text(f'✅ API <code>{key}</code> ذخیره شد.',parse_mode='HTML'); raise ApplicationHandlerStop


async def bbx_preprocess(update,context):
    # فیلتر پیام‌های ممنوع و رسانه‌های نامناسب را قبل از پاسخ‌گویی عادی کنترل می‌کند.
    msg=update.effective_message; chat=update.effective_chat
    if not msg or not chat or chat.type=='private': return
    g=bbx_group(chat.id); text=msg.text or msg.caption or ''
    words=[x.strip().lower() for x in (g['filtered_words'] or '').split('|') if x.strip()]
    if any(w in text.lower() for w in words) or BBX_FORBIDDEN.search(text):
        if not await bbx_is_admin(update):
            try: await msg.delete()
            except: pass
            await chat.send_message(f'• کاربر {telegram.helpers.escape(msg.from_user.full_name)}\n• پیام به علت ارسال محتوای ممنوع در گروه حذف شد !',parse_mode='HTML')
            return


def bbx_wrap_build(prev):
    def build(token):
        app=prev(token)
        app.add_handler(ChatMemberHandler(bbx_welcome_added,ChatMemberHandler.MY_CHAT_MEMBER),group=-50000)
        app.add_handler(MessageHandler(filters.ALL,bbx_preprocess),group=-49000)
        app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,bbx_track),group=-48000)
        app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,bbx_api_message),group=-47000)
        app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,bbx_private_whisper),group=-46000)
        app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,bbx_main_text),group=-45000)
        app.add_handler(CallbackQueryHandler(bbx_whisper_callback,pattern=r'^bbx:whisper:'),group=-45000)
        app.add_handler(CallbackQueryHandler(bbx_whisper_quick_reply_callback,pattern=r'^bbx:reply:'),group=-45000)
        app.add_handler(CallbackQueryHandler(bbx_callback,pattern=r'^bbx:'),group=-45000)
        return app
    return build

# ===================== END BILBILAK V3 MEGA EXTENSION =====================


_BB_BUILD_BEFORE_MEGA_EXTENSION = build_application
build_application = bbx_wrap_build(_BB_BUILD_BEFORE_MEGA_EXTENSION)


# =============================================================================
# FINAL MUSIC ROUTER — ABSOLUTE LAST / BEFORE LEGACY ROUTERS
# =============================================================================
# این لایه از معماری نمونه سالم استفاده می‌کند: یک Dispatcher قطعی برای موزیکال
# که قبل از تمام Routerهای قدیمی اجرا می‌شود. اگر پیام موزیکال نباشد، هیچ دخالتی
# در سایر قابلیت‌های بیل‌بیلک ندارد.

async def _bilbilak_music_absolute_dispatch(update, context):
    msg = getattr(update, "effective_message", None)
    if not msg or not getattr(msg, "text", None):
        return False
    try:
        raw = str(msg.text or "").strip()
        if not raw:
            return False

        # Commands with / are normalized to the same Persian/English music router.
        # The existing final router intentionally expects plain text, so normalize
        # only known music slash commands here.
        if raw.startswith('/'):
            body = raw[1:].strip()
            first, _, rest = body.partition(' ')
            aliases = {
                'play': 'پخش آهنگ', 'song': 'پخش آهنگ', 'music': 'موزیکال',
                'musicmenu': 'موزیکال', 'queue': 'صف', 'skip': 'بعدی',
                'next': 'بعدی', 'previous': 'قبلی', 'prev': 'قبلی',
                'pause': 'مکث', 'resume': 'ادامه', 'stop': 'توقف',
                'end': 'اتمام', 'volume': 'صدا', 'vol': 'صدا',
                'live': 'لایو', 'radio': 'رادیو', 'remix': 'ریمیکس',
                'movie': 'پخش فیلم', 'series': 'پخش سریال',
            }
            key = first.split('@', 1)[0].lower()
            if key not in aliases:
                return False
            translated = aliases[key]
            raw = translated + ((' ' + rest.strip()) if rest.strip() else '')
            # Temporarily replace only the message text exposed to the existing
            # router. Telegram Message is mutable in PTB, but avoid mutating it
            # permanently so other handlers never see the translated command.
            original_text = msg.text
            try:
                msg.text = raw
                handled = await _bb_music_message_router_final(update, context)
            finally:
                try:
                    msg.text = original_text
                except Exception:
                    pass
            return bool(handled)

        # Plain Persian/English music commands use the tested final router.
        handled = await _bb_music_message_router_final(update, context)
        return bool(handled)
    except ApplicationHandlerStop:
        raise
    except Exception as exc:
        log.exception('ABSOLUTE MUSIC DISPATCH ERROR: %s', exc)
        try:
            await msg.reply_text(
                '⚠️ دستور موزیکال دریافت شد، اما اجرای آن با خطا مواجه شد.\n'
                f'`{safe_text(type(exc).__name__ + ": " + str(exc), 350)}`',
                parse_mode='Markdown'
            )
        except Exception:
            pass
        return True


# The callback dispatcher is equally important: search-result buttons must not
# be swallowed by historical callback routers.
async def _bilbilak_music_absolute_callback(update, context):
    q = getattr(update, 'callback_query', None)
    if not q:
        return False
    data = str(q.data or '')
    if not (data.startswith('mplay:') or data.startswith('livepick:') or data.startswith('mctrl:') or data.startswith('msearch:')):
        return False
    try:
        return bool(await _bb_final_music_callback_dispatch(update, context))
    except ApplicationHandlerStop:
        raise
    except Exception as exc:
        log.exception('ABSOLUTE MUSIC CALLBACK ERROR: %s', exc)
        try:
            await q.answer('⚠️ اجرای کنترل موزیکال ناموفق بود.', show_alert=True)
        except Exception:
            pass
        return True


# Preserve the complete existing application and add only a high-priority
# music layer. Nothing from the previous build is removed.
_BILBILAK_BUILD_BEFORE_ABSOLUTE_MUSIC = build_application

def build_application(token: str) -> Application:
    app = _BILBILAK_BUILD_BEFORE_ABSOLUTE_MUSIC(token)
    # Telegram PTB processes lower group numbers first. These two handlers are
    # therefore the first music-aware layer in the entire application.
    app.add_handler(
        MessageHandler(filters.TEXT, _bilbilak_music_absolute_dispatch),
        group=-100000,
    )
    app.add_handler(
        CallbackQueryHandler(_bilbilak_music_absolute_callback),
        group=-100001,
    )
    return app


# =============================================================================
# ABSOLUTE LAST ENTRYPOINT
# =============================================================================
# Entry point is intentionally moved to the very end of this file so every
# final music/session override below is active before main() starts.


# =============================================================================
# BILBILAK FINAL MUSIC PRO REPAIR
# =============================================================================
# این لایه فقط پیش‌بررسی اکانت شخصی موزیکال را اصلاح می‌کند.
# مشکل نسخه قبلی:
#   هر وضعیتی غیر از administrator/owner را با متن «عضو نیست» گزارش می‌کرد.
# در حالی که ممکن بود اکانت عضو گروه باشد ولی ادمین نباشد.
#
# این نسخه:
#   1) اکانت واقعی متصل به Session را با get_me() مشخص می‌کند.
#   2) وضعیت واقعی آن اکانت را در همان گروه می‌خواند.
#   3) MEMBER / RESTRICTED / LEFT / BANNED / ADMIN / OWNER را جدا می‌کند.
#   4) برای Voice Chat دسترسی can_manage_video_chats را بررسی می‌کند.
#   5) خطای دقیق و قابل اقدام برمی‌گرداند.
#   6) هیچ بخش دیگری از منطق گروه، VIP، جستجو یا صف موسیقی را حذف نمی‌کند.
# =============================================================================

async def _bb_music_personal_group_check(chat_id):
    """
    Professional preflight for the personal music account.

    Returns:
        (True, "") when the account is ready for music VC.
        (False, "human-readable Persian reason") otherwise.
    """
    global MUSIC_USER_CLIENT

    # ---- 1. Client/session availability -------------------------------------
    client = MUSIC_USER_CLIENT
    if client is None or not getattr(client, "is_connected", False):
        return (
            False,
            "🔴 اکانت شخصی موزیکال وصل نیست.\n"
            "ابتدا Session حساب موزیکال را متصل/لاگین کن و بعد دوباره پخش را بزن."
        )

    try:
        # ---- 2. Resolve the EXACT Telegram account used by PyTgCalls -------
        me = await client.get_me()
        if not me or not getattr(me, "id", None):
            return (
                False,
                "🔴 حساب موزیکال شناسایی نشد.\n"
                "Session را دوباره بررسی و در صورت نیاز دوباره متصل کن."
            )

        account_name = (
            getattr(me, "first_name", None)
            or getattr(me, "last_name", None)
            or "حساب موزیکال"
        )
        username = getattr(me, "username", None)
        identity = (
            f"👤 {safe_text(str(account_name), 80)}"
            + (f" (@{safe_text(str(username), 50)})" if username else "")
            + f"\n🆔 {int(me.id)}"
        )

        # ---- 3. Read the account's real membership from Telegram -----------
        member = await client.get_chat_member(int(chat_id), int(me.id))
        status = getattr(member, "status", None)

        # Pyrogram versions can expose status as a string or enum-like value.
        status_raw = getattr(status, "value", status)
        status_name = str(status_raw or "").strip().lower()
        status_name = status_name.split(".")[-1].strip()

        # ---- 4. Account is genuinely outside the group ---------------------
        if status_name in {"left", "kicked", "banned"}:
            return (
                False,
                "🔴 اکانت شخصی موزیکال واقعاً عضو این گروه نیست.\n\n"
                f"{identity}\n"
                "📌 وضعیت فعلی: خارج از گروه\n\n"
                "اول همین اکانت را با همین Session وارد گروه کن؛ "
                "بعد آن را ادمین کن و دوباره پخش را اجرا کن."
            )

        # ---- 5. Telegram may return a restricted member -------------------
        if status_name in {"restricted"}:
            return (
                False,
                "🟠 اکانت شخصی موزیکال داخل گروه هست، اما Restricted است.\n\n"
                f"{identity}\n"
                "📌 وضعیت فعلی: Restricted\n\n"
                "محدودیت اکانت را بردار و آن را ادمین کامل کن."
            )

        # ---- 6. It is a normal member, but NOT an administrator -----------
        if status_name in {"member", "default", ""}:
            return (
                False,
                "🟡 اکانت شخصی موزیکال داخل گروه هست، اما ادمین نیست.\n\n"
                f"{identity}\n"
                "📌 وضعیت فعلی: عضو عادی\n\n"
                "لازم نیست دوباره واردش کنی؛ همین اکانت را در گروه "
                "ادمین کن و دسترسی «مدیریت Voice Chat» را روشن کن."
            )

        # ---- 7. Administrator/owner: inspect VC permission -----------------
        if status_name in {"administrator", "admin", "owner"}:
            privileges = getattr(member, "privileges", None)

            # Owner does not need an explicit can_manage_video_chats flag.
            if status_name == "owner":
                return True, ""

            if privileges is not None:
                manage_vc = getattr(
                    privileges,
                    "can_manage_video_chats",
                    None,
                )

                if manage_vc is False:
                    return (
                        False,
                        "🟠 اکانت شخصی موزیکال ادمین است، "
                        "ولی اجازه مدیریت Voice Chat ندارد.\n\n"
                        f"{identity}\n"
                        "📌 وضعیت: Administrator\n"
                        "🎙 دسترسی Voice Chat: ❌\n\n"
                        "از تنظیمات ادمین‌های گروه، دسترسی "
                        "«مدیریت تماس‌های صوتی/ویدیویی» را فعال کن."
                    )

            return True, ""

        # ---- 8. Unknown status: do NOT falsely say not a member ------------
        return (
            False,
            "🟠 وضعیت اکانت موزیکال توسط Telegram قابل تشخیص نبود.\n\n"
            f"{identity}\n"
            f"📌 status: {safe_text(status_name or 'unknown', 80)}\n\n"
            "یک بار Session را قطع و دوباره وصل کن؛ سپس دوباره پخش را بزن."
        )

    except Exception as exc:
        # Keep the real technical reason in logs, but don't leak credentials.
        log.warning(
            "music personal group preflight failed for chat=%s: %s",
            chat_id,
            exc,
        )

        err_name = type(exc).__name__
        err_text = str(exc).strip()

        # Common Telegram/Pyrogram permission/access failures get a useful
        # user-facing message instead of the old generic "not a member".
        low = err_text.lower()

        if "peer_id_invalid" in low or "peer id invalid" in low:
            reason = (
                "🔴 اکانت Session به این گروه دسترسی معتبر ندارد.\n"
                "مطمئن شو همین اکانتی که Session آن وصل است واقعاً داخل گروه است."
            )
        elif "username_not_occupied" in low:
            reason = (
                "🔴 شناسه گروه برای اکانت موزیکال قابل resolve نیست.\n"
                "گروه را با همان اکانت باز/عضو کن و دوباره امتحان کن."
            )
        elif "user_not_participant" in low:
            reason = (
                "🔴 Telegram می‌گوید اکانت Session عضو این گروه نیست.\n"
                "همین اکانت شخصی موزیکال را وارد گروه کن."
            )
        elif "chat_write_forbidden" in low or "forbidden" in low:
            reason = (
                "🟠 Telegram دسترسی اکانت موزیکال به این گروه را محدود کرده.\n"
                "عضویت و سطح دسترسی ادمین اکانت را بررسی کن."
            )
        else:
            reason = (
                "🟠 بررسی اکانت موزیکال در این گروه با خطای Telegram/Pyrogram "
                "مواجه شد.\n\n"
                f"نوع خطا: {safe_text(err_name, 80)}\n"
                "اگر اکانت داخل گروه است، Session همان اکانت را دوباره وصل کن."
            )

        return False, reason


# Keep every existing music feature intact while making the preflight
# authoritative at runtime.
_BB_MUSIC_PERSONAL_GROUP_CHECK_PRO = _bb_music_personal_group_check


async def _bb_music_preflight_before_play(chat_id):
    """
    Single authoritative preflight used by the final music layer.
    Kept separate so future music commands can reuse exactly the same check.
    """
    ok, reason = await _BB_MUSIC_PERSONAL_GROUP_CHECK_PRO(int(chat_id))
    if ok:
        return True, ""

    return False, reason


