# =============================================================================
# BILBILAK BLACK MUSIC PRO FINAL — SESSION / VOICE CHAT / AUDIO / VIDEO / LIVE
# =============================================================================
# این لایه نهایی است و عمداً در انتهای فایل قرار دارد تا قبل از main() فعال شود.
#
# طراحی:
# 1) Session حساب شخصی در فایل پایدار کنار پروژه ذخیره می‌شود؛ نه /tmp.
# 2) اگر Session معتبر باشد، بدون کد دوباره وصل می‌شود.
# 3) اگر Session خراب/منقضی باشد، فقط همان فایل Session پاک و ورود تازه انجام می‌شود.
# 4) ورود اولیه می‌تواند کاملاً از ترمینال انجام شود: شماره، کد و 2FA.
# 5) موتور Voice Chat فقط با همان حساب شخصی Session اجرا می‌شود.
# 6) قبل از پخش، هویت واقعی Session و عضویت/ادمین/مجوز Voice Chat بررسی می‌شود.
# 7) صوت و ویدیو با MediaStream مناسب خودشان پخش می‌شوند؛ ویدیو دیگر با IGNORE
#    پخش نمی‌شود.
# 8) آهنگ/ویدیوهای معمولی برای پایداری بیشتر روی دیسک موقت دانلود و سپس پخش می‌شوند.
# 9) Live مستقیماً از استریم پخش می‌شود.
# 10) StreamEnded به‌صورت واقعی صف را جلو می‌برد؛ تایمر UI فقط برای نمایش Progress است.
# =============================================================================

try:
    from pytgcalls import filters as _BB_MUSIC_CALL_FILTERS
except Exception:
    _BB_MUSIC_CALL_FILTERS = None

try:
    from pytgcalls.types import StreamEnded as _BB_MUSIC_STREAM_ENDED
except Exception:
    _BB_MUSIC_STREAM_ENDED = None

try:
    from pytgcalls.types import AudioQuality as _BB_MUSIC_AUDIO_QUALITY
except Exception:
    _BB_MUSIC_AUDIO_QUALITY = None

try:
    from pytgcalls.types import VideoQuality as _BB_MUSIC_VIDEO_QUALITY
except Exception:
    _BB_MUSIC_VIDEO_QUALITY = None

BB_MUSIC_SEARCH_MODE = {}
BB_MUSIC_ENGINE_BOUND = set()
BB_MUSIC_PLAY_LOCKS = {}
BB_MUSIC_LAST_END = {}
BB_MUSIC_SESSION_ROOT = Path(__file__).resolve().parent / "sessions"
BB_MUSIC_SESSION_ROOT.mkdir(parents=True, exist_ok=True)


def _bb_music_stable_session_path(phone=''):
    digits = re.sub(r'\D', '', str(phone or ''))
    suffix = digits or 'default'
    return str(BB_MUSIC_SESSION_ROOT / f'bilbilak_music_user_{suffix}')


def _bb_music_session_base(path):
    p = Path(str(path or '')).expanduser()
    if not p.is_absolute():
        p = BB_MUSIC_SESSION_ROOT / p
    p.parent.mkdir(parents=True, exist_ok=True)
    # Pyrogram accepts the session name without .session when workdir is used.
    if p.suffix == '.session':
        return p.with_suffix('')
    return p


async def _bb_music_seed_defaults_pro():
    global MUSIC_USER_SESSION, MUSIC_USER_PHONE
    try:
        await DBX.execute(
            "CREATE TABLE IF NOT EXISTS bot_settings "
            "(key TEXT PRIMARY KEY, value TEXT DEFAULT '')"
        )
        phone = await _bb_get_music_setting(
            'MUSIC_USER_PHONE',
            os.getenv('MUSIC_USER_PHONE', MUSIC_USER_PHONE or '')
        )
        session = await _bb_get_music_setting(
            'MUSIC_USER_SESSION',
            ''
        )
        if not session:
            session = _bb_music_stable_session_path(phone)
            await _bb_set_music_setting('MUSIC_USER_SESSION', session)
        MUSIC_USER_SESSION = str(_bb_music_session_base(session))
        if phone:
            MUSIC_USER_PHONE = phone
    except Exception as exc:
        log.warning('pro music session defaults failed: %s', exc)


async def _bb_music_start_engine_pro(client):
    global MUSIC_VC_ENGINE, MUSIC_VC_CLIENT, MUSIC_VC_STARTED, MUSIC_VC_AVAILABLE
    if client is None:
        raise RuntimeError('حساب شخصی موزیکال آماده نیست.')

    # Stop an older engine cleanly before replacing it.
    old = MUSIC_VC_ENGINE
    if old is not None and old is not MUSIC_VC_ENGINE:
        try:
            r = old.stop()
            if hasattr(r, '__await__'):
                await r
        except Exception:
            pass

    if _MusicPyTgCalls is None or _MusicMediaStream is None:
        raise RuntimeError('PyTgCalls/MediaStream روی سرور نصب نیست.')

    engine = _MusicPyTgCalls(client)
    r = engine.start()
    if hasattr(r, '__await__'):
        await r

    MUSIC_VC_CLIENT = client
    MUSIC_VC_ENGINE = engine
    MUSIC_VC_STARTED = True
    MUSIC_VC_AVAILABLE = True
    await _bb_music_bind_stream_end_pro(engine)
    return engine


async def _bb_music_bind_stream_end_pro(engine):
    if engine is None or _BB_MUSIC_CALL_FILTERS is None:
        return False
    key = id(engine)
    if key in BB_MUSIC_ENGINE_BOUND:
        return True
    try:
        filt = _BB_MUSIC_CALL_FILTERS.stream_end()

        async def _ended_handler(_, update):
            cid = getattr(update, 'chat_id', None)
            if cid is None:
                cid = getattr(update, 'chat', None)
            if cid is None:
                return
            try:
                cid = int(cid)
            except Exception:
                return
            # Ignore duplicate end events arriving within a very short window.
            now = time.monotonic()
            last = BB_MUSIC_LAST_END.get(cid, 0.0)
            if now - last < 1.0:
                return
            BB_MUSIC_LAST_END[cid] = now
            try:
                await _bb_music_on_stream_end_pro(cid)
            except Exception as exc:
                log.exception('music stream-end handler failed: %s', exc)

        engine.on_update(filt)(_ended_handler)
        BB_MUSIC_ENGINE_BOUND.add(key)
        return True
    except Exception as exc:
        log.warning('could not bind PyTgCalls StreamEnded: %s', exc)
        return False


def _bb_music_cleanup_local_state(item):
    if not isinstance(item, dict):
        return
    folder = item.get('_music_folder')
    path = item.get('_music_path')
    try:
        if folder:
            shutil.rmtree(str(folder), ignore_errors=True)
        elif path:
            p = Path(str(path))
            if p.exists() and str(p).startswith(str(MUSIC_TMP_DIR)):
                p.unlink(missing_ok=True)
    except Exception:
        pass


async def _bb_music_terminal_login_pro(api_id, api_hash, phone):
    """ورود اولیه کاملاً ترمینالی با Session دائمی."""
    global MUSIC_USER_CLIENT, MUSIC_VC_CLIENT, MUSIC_VC_ENGINE
    global MUSIC_USER_PHONE, MUSIC_USER_SESSION

    if not api_id or not api_hash:
        raise RuntimeError('TELEGRAM_API_ID و TELEGRAM_API_HASH تنظیم نشده‌اند.')

    if not phone:
        phone = (await asyncio.to_thread(
            input, '📱 شماره حساب موزیکال را وارد کن: '
        )).strip()
    if not phone:
        raise RuntimeError('شماره حساب وارد نشد.')

    MUSIC_USER_PHONE = phone
    base = _bb_music_session_base(
        MUSIC_USER_SESSION or _bb_music_stable_session_path(phone)
    )
    MUSIC_USER_SESSION = str(base)
    base.parent.mkdir(parents=True, exist_ok=True)

    async def new_client():
        return _MusicPyroClient(
            base.name,
            api_id=int(api_id),
            api_hash=str(api_hash),
            workdir=str(base.parent),
            in_memory=False,
        )

    client = await new_client()

    # A stale auth key must not poison the next login.
    try:
        await client.connect()
        try:
            me = await client.get_me()
        except Exception as exc:
            if 'AUTH_KEY_UNREGISTERED' in str(exc).upper():
                try:
                    await client.disconnect()
                except Exception:
                    pass
                _bb_music_remove_invalid_session(str(base))
                client = await new_client()
                await client.connect()
                me = None
            else:
                raise

        if me:
            MUSIC_USER_CLIENT = client
            await _bb_music_start_engine_pro(client)
            log.info('Music session reused: id=%s username=%s',
                     getattr(me, 'id', 0), getattr(me, 'username', None))
            return True, me
    except Exception as exc:
        try:
            if getattr(client, 'is_connected', False):
                await client.disconnect()
        except Exception:
            pass
        if 'AUTH_KEY_UNREGISTERED' not in str(exc).upper():
            raise

    # Fresh login.
    client = await new_client()
    await client.connect()
    sent = await client.send_code(phone)
    code = (await asyncio.to_thread(
        input, '🔐 کد ورود تلگرام را در ترمینال وارد کن: '
    )).strip().replace(' ', '')

    try:
        await client.sign_in(phone, sent.phone_code_hash, code)
    except _BBSessionPasswordNeeded:
        password = await asyncio.to_thread(
            input, '🔑 رمز دومرحله‌ای تلگرام را در ترمینال وارد کن: '
        )
        await client.check_password(password.strip())

    me = await client.get_me()
    if not me:
        raise RuntimeError('Telegram حساب واردشده را برنگرداند.')

    MUSIC_USER_CLIENT = client
    await _bb_music_start_engine_pro(client)
    log.info('Music personal account logged in: id=%s username=%s',
             getattr(me, 'id', 0), getattr(me, 'username', None))
    return True, me


async def _bb_music_user_start_existing_pro():
    """استفاده از Session موجود بدون درخواست کد."""
    global MUSIC_USER_CLIENT, MUSIC_USER_SESSION, MUSIC_USER_PHONE

    if _MusicPyroClient is None or _MusicPyTgCalls is None or _MusicMediaStream is None:
        return False, 'کتابخانه‌های Pyrogram/PyTgCalls نصب نیستند.'

    api_id, api_hash, phone = _bb_music_api_config()
    if not api_id or not api_hash:
        return False, 'TELEGRAM_API_ID و TELEGRAM_API_HASH تنظیم نشده‌اند.'

    base = _bb_music_session_base(
        MUSIC_USER_SESSION or _bb_music_stable_session_path(phone)
    )
    MUSIC_USER_SESSION = str(base)

    try:
        client = _MusicPyroClient(
            base.name,
            api_id=int(api_id),
            api_hash=str(api_hash),
            workdir=str(base.parent),
            in_memory=False,
        )
        await client.connect()
        try:
            me = await client.get_me()
        except Exception as exc:
            if 'AUTH_KEY_UNREGISTERED' in str(exc).upper():
                try:
                    await client.disconnect()
                except Exception:
                    pass
                _bb_music_remove_invalid_session(str(base))
                return False, 'Session قبلی باطل شده؛ ورود تازه لازم است.'
            raise

        if not me:
            await client.disconnect()
            return False, 'Session برای حساب شخصی مجاز نشده است.'

        MUSIC_USER_CLIENT = client
        await _bb_music_start_engine_pro(client)
        return True, me

    except Exception as exc:
        try:
            if MUSIC_USER_CLIENT is not None and getattr(MUSIC_USER_CLIENT, 'is_connected', False):
                await MUSIC_USER_CLIENT.disconnect()
        except Exception:
            pass
        MUSIC_USER_CLIENT = None
        return False, f'{type(exc).__name__}: {exc}'


async def _bb_music_lazy_connect_pro():
    global MUSIC_USER_SESSION, MUSIC_USER_PHONE
    global MUSIC_VC_ENGINE, MUSIC_VC_STARTED, MUSIC_VC_AVAILABLE

    try:
        await _bb_music_seed_defaults_pro()
        api_id, api_hash, phone, session = await _bb_music_settings_snapshot()
        if not api_id:
            api_id = str(TELEGRAM_API_ID or '')
        if not api_hash:
            api_hash = str(TELEGRAM_API_HASH or '')
        if not phone:
            phone = str(MUSIC_USER_PHONE or '')
        if not session:
            session = _bb_music_stable_session_path(phone)

        MUSIC_USER_PHONE = phone
        MUSIC_USER_SESSION = str(_bb_music_session_base(session))
        os.environ['TELEGRAM_API_ID'] = str(api_id)
        os.environ['TELEGRAM_API_HASH'] = str(api_hash)
        os.environ['MUSIC_USER_PHONE'] = str(phone)
        os.environ['MUSIC_USER_SESSION'] = MUSIC_USER_SESSION

        if MUSIC_USER_CLIENT is not None and getattr(MUSIC_USER_CLIENT, 'is_connected', False):
            try:
                me = await MUSIC_USER_CLIENT.get_me()
                if me and MUSIC_VC_ENGINE is not None and MUSIC_VC_STARTED:
                    MUSIC_VC_AVAILABLE = True
                    return True, ''
            except Exception:
                pass

        ok, info = await _bb_music_user_start_existing_pro()
        if ok:
            MUSIC_VC_STARTED = True
            MUSIC_VC_AVAILABLE = True
            return True, ''

        # First run or invalidated session: terminal login.
        ok, info = await _bb_music_terminal_login_pro(api_id, api_hash, phone)
        if ok:
            MUSIC_VC_STARTED = True
            MUSIC_VC_AVAILABLE = True
            return True, ''

        return False, str(info or 'حساب موزیکال متصل نشد.')
    except Exception as exc:
        MUSIC_VC_STARTED = False
        MUSIC_VC_AVAILABLE = False
        log.exception('pro music lazy connect failed: %s', exc)
        return False, f'{type(exc).__name__}: {exc}'


async def _bb_music_personal_group_check_pro(chat_id):
    """بررسی دقیق هویت Session و دسترسی واقعی همان حساب در گروه."""
    client = MUSIC_USER_CLIENT
    if client is None or not getattr(client, 'is_connected', False):
        return False, (
            '🔴 اکانت شخصی موزیکال وصل نیست.\n'
            'Session را از طریق ورود ترمینال وصل کن.'
        )

    try:
        me = await client.get_me()
        if not me or not getattr(me, 'id', None):
            return False, '🔴 Session حساب موزیکال هویت معتبری برنگرداند.'

        member = await client.get_chat_member(int(chat_id), int(me.id))
        raw = getattr(member, 'status', '')
        status = str(getattr(raw, 'value', raw) or '').lower().split('.')[-1]

        name = safe_text(
            getattr(me, 'first_name', None)
            or getattr(me, 'last_name', None)
            or 'حساب موزیکال', 80
        )
        identity = f'👤 {name}\n🆔 {int(me.id)}'
        if getattr(me, 'username', None):
            identity += f' (@{safe_text(me.username, 50)})'

        if status in {'left', 'kicked', 'banned'}:
            return False, (
                '🔴 همین حساب Session واقعاً عضو گروه نیست.\n\n'
                f'{identity}\n\n'
                'همین حساب را وارد گروه کن و سپس ادمینش کن.'
            )

        if status == 'restricted':
            return False, (
                '🟠 حساب Session داخل گروه است ولی Restricted است.\n\n'
                f'{identity}\n\n'
                'محدودیت را بردار و دسترسی مدیریت Voice Chat را فعال کن.'
            )

        if status in {'member', 'default'}:
            return False, (
                '🟡 حساب Session داخل گروه هست، اما ادمین نیست.\n\n'
                f'{identity}\n\n'
                'همین حساب را ادمین کن و «مدیریت تماس‌های صوتی/ویدیویی» '
                'را فعال کن.'
            )

        if status in {'owner', 'administrator', 'admin'}:
            if status != 'owner':
                priv = getattr(member, 'privileges', None)
                manage_vc = getattr(priv, 'can_manage_video_chats', None) if priv else None
                if manage_vc is False:
                    return False, (
                        '🟠 حساب Session ادمین است، اما اجازه مدیریت Voice Chat ندارد.\n\n'
                        f'{identity}\n\n'
                        'مجوز مدیریت تماس‌های صوتی/ویدیویی را فعال کن.'
                    )
            return True, ''

        return False, (
            '🟠 وضعیت حساب Session نامشخص است.\n\n'
            f'{identity}\n'
            f'📌 status: {safe_text(status or "unknown", 80)}'
        )
    except Exception as exc:
        low = str(exc).lower()
        if 'user_not_participant' in low:
            return False, '🔴 Telegram می‌گوید همین Session عضو این گروه نیست.'
        if 'peer_id_invalid' in low or 'peer id invalid' in low:
            return False, '🔴 Session به این گروه دسترسی معتبر ندارد.'
        log.warning('pro personal group check failed for %s: %s', chat_id, exc)
        return False, (
            '🟠 بررسی عضویت/دسترسی حساب موزیکال با خطای Telegram مواجه شد.\n'
            f'نوع خطا: {safe_text(type(exc).__name__, 80)}'
        )


async def _bb_music_make_stream_pro(source, is_video=False, is_live=False):
    if _MusicMediaStream is None:
        raise RuntimeError('MediaStream در PyTgCalls موجود نیست.')

    source = str(source)
    if is_video or is_live:
        # For video/live do NOT use Flags.IGNORE: that flag intentionally disables
        # the video track. Use the audio+video MediaStream signature.
        if _BB_MUSIC_AUDIO_QUALITY is not None and _BB_MUSIC_VIDEO_QUALITY is not None:
            return _MusicMediaStream(
                source,
                _BB_MUSIC_AUDIO_QUALITY.HIGH,
                _BB_MUSIC_VIDEO_QUALITY.HD_720p,
            )
        return _MusicMediaStream(source)

    return _MusicMediaStream(
        source,
        video_flags=(
            _MusicMediaStream.Flags.IGNORE
            if hasattr(_MusicMediaStream, 'Flags') else None
        ),
    )


async def _bb_music_backend_yt_dlp_pro(url, is_video=False, is_live=False):
    if _music_yt_dlp is None:
        raise RuntimeError('yt-dlp نصب نیست.')

    # Normal media is downloaded first. This avoids signed-stream expiry,
    # network stalls and mid-track restarts. Live stays online.
    if not is_live:
        info, path, folder = await _music_download_online(
            url, audio_only=not is_video
        )
        return str(path), {
            'title': info.get('title') if isinstance(info, dict) else '',
            'duration': info.get('duration', 0) if isinstance(info, dict) else 0,
            'backend': 'yt-dlp-download',
            '_music_folder': str(folder),
            '_music_path': str(path),
        }

    def _extract_live():
        opts = _music_ydl_options(audio_only=not is_video, download=False)
        opts['skip_download'] = True
        opts['noplaylist'] = True
        opts['live_from_start'] = False
        with _music_yt_dlp.YoutubeDL(opts) as ydl:
            info = ydl.extract_info(url, download=False)
            direct = info.get('url') if info else None
            if not direct and info and info.get('requested_formats'):
                direct = next(
                    (f.get('url') for f in info.get('requested_formats') or [] if f.get('url')),
                    None
                )
            if not direct:
                raise RuntimeError('لینک مستقیم Live پیدا نشد.')
            return direct, {
                'title': info.get('title', '') if info else '',
                'duration': 0,
                'backend': 'yt-dlp-live',
            }

    return await asyncio.to_thread(_extract_live)


async def _bb_music_backend_streamlink_pro(url, is_video=False, is_live=False):
    try:
        import streamlink
    except Exception as exc:
        raise RuntimeError('Streamlink نصب نیست.') from exc

    def _extract():
        session = streamlink.Streamlink()
        try:
            session.set_option('stream-segment-attempts', 3)
            session.set_option('stream-segment-timeout', 10)
            session.set_option('hls-live-edge', 3)
        except Exception:
            pass
        streams = session.streams(url)
        if not streams:
            raise RuntimeError('Streamlink استریمی پیدا نکرد.')
        order = (
            ('best', '720p', '480p', 'worst')
            if is_video else
            ('audio_only', 'best', '720p', '480p', 'worst')
        )
        selected = next((streams[k] for k in order if k in streams), None)
        if selected is None:
            selected = next(iter(streams.values()))
        direct = getattr(selected, 'url', None)
        if not direct:
            raise RuntimeError('Streamlink لینک مستقیم برنگرداند.')
        return direct, {'duration': 0, 'backend': 'streamlink'}

    return await asyncio.to_thread(_extract)


async def _bb_music_try_play_sources_pro(chat_id, source, is_video=False, is_live=False):
    if MUSIC_VC_ENGINE is None:
        raise RuntimeError('موتور PyTgCalls آماده نیست.')

    play = getattr(MUSIC_VC_ENGINE, 'play', None)
    if not play:
        play = getattr(MUSIC_VC_ENGINE, 'join_group_call', None)

    if not play:
        raise RuntimeError('API پخش PyTgCalls پیدا نشد.')

    stream = await _bb_music_make_stream_pro(
        source, is_video=is_video, is_live=is_live
    )

    # Ensure the group call exists. If it already exists, Telegram simply
    # returns the existing call/error and playback continues.
    try:
        if is_live or True:
            try:
                await create_voice_call(chat_id)
            except Exception as create_exc:
                # "already exists" is a normal condition.
                if not any(k in str(create_exc).lower() for k in (
                    'already', 'groupcall', 'call', 'already_exists'
                )):
                    log.debug('voice call create/check: %s', create_exc)
    except Exception:
        pass

    result = play(chat_id, stream)
    if hasattr(result, '__await__'):
        await result
    return 'PyTgCalls MediaStream'


async def _bb_music_play_now_pro(chat_id, item):
    ok, reason = await _bb_music_lazy_connect_pro()
    if not ok:
        raise RuntimeError(reason)

    ok, reason = await _bb_music_personal_group_check_pro(chat_id)
    if not ok:
        raise RuntimeError(reason)

    url = (item.get('url') or item.get('source_url') or '').strip()
    if not url:
        raise RuntimeError('منبع پخش خالی است.')

    is_video = bool(item.get('is_video'))
    is_live = bool(item.get('is_live'))
    errors = []

    resolvers = (
        ('yt-dlp', _bb_music_backend_yt_dlp_pro),
        ('streamlink', _bb_music_backend_streamlink_pro),
        ('direct', _bb_music_backend_direct),
    )

    for backend_name, resolver in resolvers:
        info = {}
        try:
            source, info = await resolver(url, is_video, is_live)
            if not source:
                raise RuntimeError('منبع خالی است.')

            try:
                method = await _bb_music_try_play_sources_pro(
                    chat_id, source, is_video=is_video, is_live=is_live
                )
            except Exception as exc:
                # If a downloaded file failed, remove it before the next backend.
                _bb_music_cleanup_local_state(info)
                raise exc

            new_item = dict(item)
            new_item['source_url'] = source
            new_item['backend'] = backend_name
            new_item['play_method'] = method
            if isinstance(info, dict):
                if not new_item.get('duration'):
                    new_item['duration'] = info.get('duration') or 0
                if not new_item.get('title') and info.get('title'):
                    new_item['title'] = info['title']
                if info.get('_music_folder'):
                    new_item['_music_folder'] = info['_music_folder']
                if info.get('_music_path'):
                    new_item['_music_path'] = info['_music_path']

            new_item['started_at'] = time.time()
            new_item['position'] = 0
            new_item['paused_at'] = None
            MUSIC_CURRENT[chat_id] = new_item
            log.info(
                'PRO MUSIC START chat=%s backend=%s video=%s live=%s',
                chat_id, backend_name, is_video, is_live
            )
            return new_item

        except Exception as exc:
            errors.append(
                f'{backend_name}: {type(exc).__name__}: '
                f'{safe_text(str(exc), 240)}'
            )
            log.warning('pro music backend %s failed: %s', backend_name, exc)

    raise RuntimeError(
        '❌ پخش انجام نشد؛ همه موتورهای پخش امتحان شدند.\n\n' +
        '\n'.join('• ' + x for x in errors)
    )


async def _bb_music_play_item_pro(chat_id, item):
    return await _bb_music_play_now_pro(chat_id, item)


async def _bb_music_skip_pro(chat_id):
    current = MUSIC_CURRENT.pop(chat_id, None)
    if current:
        MUSIC_HISTORY.setdefault(chat_id, []).append(dict(current))
        MUSIC_HISTORY[chat_id] = MUSIC_HISTORY[chat_id][-30:]
        _bb_music_cleanup_local_state(current)

    queue = MUSIC_QUEUE.get(chat_id) or []
    if not queue:
        try:
            await _bb_music_stop_final(chat_id)
        except Exception:
            pass
        return None

    item = queue.pop(0)
    try:
        return await _bb_music_play_item_pro(chat_id, item)
    except Exception:
        # Keep trying the remaining queue items.
        while queue:
            nxt = queue.pop(0)
            try:
                return await _bb_music_play_item_pro(chat_id, nxt)
            except Exception as exc:
                log.warning('queued item failed: %s', exc)
                continue
        return None


async def _bb_music_prev_pro(chat_id):
    hist = MUSIC_HISTORY.get(chat_id) or []
    if not hist:
        return None

    current = MUSIC_CURRENT.pop(chat_id, None)
    if current:
        _bb_music_cleanup_local_state(current)
        MUSIC_QUEUE.setdefault(chat_id, []).insert(0, current)

    item = hist.pop()
    try:
        return await _bb_music_play_item_pro(chat_id, item)
    except Exception:
        return None


async def _bb_music_start_or_queue_pro(chat_id, item, panel_message=None, bot=None, requester_id=None):
    lock = BB_MUSIC_PLAY_LOCKS.setdefault(chat_id, asyncio.Lock())
    async with lock:
        if requester_id is not None:
            item = dict(item, requester_id=requester_id)

        current = MUSIC_CURRENT.get(chat_id)
        if current:
            MUSIC_QUEUE.setdefault(chat_id, []).append(dict(item))
            return False, None

        started = await _bb_music_play_now_pro(chat_id, item)
        owner = int(item.get('requester_id') or requester_id or 0)

        panel = None
        render = globals().get('_bb_music_render_panel')
        refresh = globals().get('_bb_music_start_refresh')
        if callable(render):
            panel = await render(
                chat_id, owner, message=panel_message, bot=bot
            )
        if panel and callable(refresh):
            await refresh(chat_id, owner, panel)
        return True, panel


async def _bb_music_show_finished_panel(chat_id, finished_item):
    """نمایش کارت پایان پخش با همان thumbnail آهنگ/ویدئوی تمام‌شده."""
    if not finished_item:
        return None

    # Resolve the artwork BEFORE the playback state is removed.
    try:
        await _bb_music_resolve_thumbnail(finished_item)
    except Exception:
        pass

    title = safe_text(finished_item.get('title') or 'بدون عنوان', 120)
    media_type = (
        '🎬 فیلم' if finished_item.get('is_video') else
        ('📡 پخش زنده' if finished_item.get('is_live') else '🎵 آهنگ')
    )
    requester = safe_text(finished_item.get('requester_name') or 'کاربر', 80)
    thumbnail = finished_item.get('thumbnail')
    meta = MUSIC_PANEL_META.get(chat_id) or {}
    message = meta.get('message')
    bot = meta.get('bot')
    owner_id = int(finished_item.get('requester_id') or meta.get('owner_id') or 0)

    caption = (
        '⏹️ <b>پخش به پایان رسید</b>\n'
        '━━━━━━━━━━━━━━━━━━\n'
        f'🎧 <b>{title}</b>\n\n'
        '• موزیک متوقف شد.\n'
        f'• نوع پخش: {media_type}\n'
        '• محل پخش: گروه\n'
        f'• درخواست کننده: {requester}\n'
        '• وضعیت: <b>اتمام پخش</b>'
    )

    # Preferred path: edit the existing photo panel's caption. This keeps the
    # EXACT SAME thumbnail instead of sending a new/incorrect image.
    if message is not None and getattr(message, 'photo', None):
        try:
            await message.edit_caption(
                caption=caption, parse_mode='HTML', reply_markup=None
            )
            meta['message'] = message
            meta['message_id'] = getattr(message, 'message_id', 0)
            meta['fingerprint'] = ('finished', title, thumbnail or '')
            meta['thumbnail'] = thumbnail
            return message
        except Exception as exc:
            if not _bb_music_is_stale_message_error(exc):
                log.debug('finished music panel edit skipped: %s', exc)

    # Fallback: if the old panel was text-only/deleted, send a new photo using
    # the same resolved thumbnail.
    if bot is None and message is not None:
        try:
            bot = message.get_bot()
        except Exception:
            bot = None

    if bot is not None and thumbnail:
        try:
            finished_message = await bot.send_photo(
                chat_id, photo=thumbnail, caption=caption,
                parse_mode='HTML', reply_markup=None
            )
            meta['message'] = finished_message
            meta['message_id'] = getattr(finished_message, 'message_id', 0)
            meta['fingerprint'] = ('finished', title, thumbnail or '')
            meta['thumbnail'] = thumbnail
            return finished_message
        except Exception as exc:
            log.debug('finished music thumbnail send skipped: %s', exc)

    if bot is not None:
        try:
            finished_message = await bot.send_message(
                chat_id, caption, parse_mode='HTML', reply_markup=None
            )
            meta['message'] = finished_message
            meta['message_id'] = getattr(finished_message, 'message_id', 0)
            meta['fingerprint'] = ('finished', title, thumbnail or '')
            return finished_message
        except Exception:
            pass

    return None


async def _bb_music_on_stream_end_pro(chat_id):
    lock = BB_MUSIC_PLAY_LOCKS.setdefault(chat_id, asyncio.Lock())
    async with lock:
        # Keep the finished item intact long enough to reuse its EXACT thumbnail
        # in the end-of-track card.
        current = MUSIC_CURRENT.get(chat_id)

        queue = MUSIC_QUEUE.get(chat_id) or []
        if queue:
            # The next item starts immediately; therefore do not show a finished
            # card between tracks. Only replace the existing panel with the next
            # track's panel.
            MUSIC_CURRENT.pop(chat_id, None)
            if current:
                _bb_music_cleanup_local_state(current)

            # Try queued items in order; skip broken items automatically.
            while queue:
                item = queue.pop(0)
                try:
                    await _bb_music_play_item_pro(chat_id, item)
                    owner = int(item.get('requester_id') or 0)
                    meta = MUSIC_PANEL_META.get(chat_id) or {}
                    if meta.get('message_id'):
                        try:
                            await _bb_music_render_panel(
                                chat_id, owner, message=meta.get('message')
                            )
                        except Exception:
                            pass
                    return
                except Exception as exc:
                    log.warning('stream-ended next item failed: %s', exc)
                    continue

        # No next item: show the completion card FIRST, using the same thumbnail
        # as the track that just ended, then clean up playback state.
        if current:
            try:
                await _bb_music_show_finished_panel(chat_id, current)
            except Exception as exc:
                log.debug('finished music panel failed: %s', exc)
            _bb_music_cleanup_local_state(current)

        # Leave the personal account out of the VC, but do not delete the
        # Telegram group or touch the bot's normal group call state.
        try:
            await _bb_music_stop_final(chat_id)
        except Exception:
            pass
        MUSIC_CURRENT.pop(chat_id, None)

        # Stop the refresh worker after the final card has been rendered.
        task = MUSIC_REFRESH_TASKS.pop(chat_id, None)
        if task and task is not asyncio.current_task():
            try:
                task.cancel()
            except Exception:
                pass


# Make the final playback path authoritative.
_bb_music_user_start_existing = _bb_music_user_start_existing_pro
_bb_music_terminal_login = _bb_music_terminal_login_pro
_bb_music_lazy_connect = _bb_music_lazy_connect_pro
_bb_music_personal_group_check = _bb_music_personal_group_check_pro
_bb_music_play_now = _bb_music_play_now_pro
_bb_music_play_item = _bb_music_play_item_pro
_bb_music_skip = _bb_music_skip_pro
_bb_music_prev = _bb_music_prev_pro
_bb_music_start_or_queue = _bb_music_start_or_queue_pro
_bb_music_seed_defaults = _bb_music_seed_defaults_pro


# Re-route the owner login command to the same terminal/session system.
async def _bb_music_user_login_begin_pro(update, context):
    uid = update.effective_user.id if update.effective_user else 0
    msg = update.effective_message
    if not await is_owner(uid):
        if msg:
            await msg.reply_text('⛔ فقط مالک ربات می‌تواند حساب موزیکال را وصل کند.')
        return True
    if update.effective_chat and update.effective_chat.type != 'private':
        await msg.reply_text('🔐 ورود حساب موزیکال را فقط در خصوصی یا ترمینال انجام بده.')
        return True
    try:
        await _bb_music_seed_defaults_pro()
        api_id, api_hash, phone, session = await _bb_music_settings_snapshot()
        if not api_id:
            api_id = str(TELEGRAM_API_ID or '')
        if not api_hash:
            api_hash = str(TELEGRAM_API_HASH or '')
        if not phone:
            phone = str(MUSIC_USER_PHONE or '')
        if session:
            globals()['MUSIC_USER_SESSION'] = str(_bb_music_session_base(session))
        await _bb_music_terminal_login_pro(api_id, api_hash, phone)
        await msg.reply_text('✅ حساب موزیکال با Session حرفه‌ای متصل شد و موتور Voice Chat آماده است.')
    except Exception as exc:
        log.exception('manual music login failed: %s', exc)
        await msg.reply_text(
            '❌ اتصال حساب موزیکال انجام نشد.\n\n'
            + safe_text(f'{type(exc).__name__}: {exc}', 700)
        )
    return True


_bb_music_user_login_begin = _bb_music_user_login_begin_pro


# Final video-aware search metadata. Existing result callbacks use this value.
_OLD_BB_MUSIC_MESSAGE_ROUTER_FINAL_PRO = _bb_music_message_router_final

async def _bb_music_message_router_final_pro(update, context):
    msg = update.effective_message
    chat = update.effective_chat
    raw = (getattr(msg, 'text', '') or '').strip() if msg else ''
    if chat and chat.type != 'private':
        m = re.match(
            r'^(?:پخش آهنگ|پخش فیلم|پخش سریال|رادیو|ریمیکس)\s+(.+)$',
            raw, re.I
        )
        if m:
            kind = 'video' if raw.lower().startswith(('پخش فیلم', 'پخش سریال')) else 'audio'
            BB_MUSIC_SEARCH_MODE[int(chat.id)] = kind
    return await _OLD_BB_MUSIC_MESSAGE_ROUTER_FINAL_PRO(update, context)

_bb_music_message_router_final = _bb_music_message_router_final_pro


# Replace the final result callback so «پخش فیلم» really creates a video stream.
_OLD_BB_MUSIC_RESULT_CALLBACK_FINAL_PRO = _bb_music_result_callback_final

async def _bb_music_result_callback_final_pro(update, context):
    q = getattr(update, 'callback_query', None)
    if not q or not (q.data or '').startswith('mplay:'):
        return False
    try:
        _, chat_raw, owner_raw, index_raw = q.data.split(':', 3)
        chat_id, owner_id, index = int(chat_raw), int(owner_raw), int(index_raw)
        if q.from_user.id != owner_id:
            await q.answer('🔒 این پنل برای درخواست‌کننده دیگری است.', show_alert=True)
            return True

        results = MUSIC_SEARCH_CACHE.get(f'{chat_id}:last') or []
        if not 1 <= index <= len(results):
            await q.answer('❌ نتیجه منقضی شده؛ دوباره جستجو کن.', show_alert=True)
            return True

        x = results[index - 1]
        is_video = BB_MUSIC_SEARCH_MODE.get(chat_id) == 'video'
        item = {
            'title': x.get('title') or 'بدون عنوان',
            'url': x.get('url'),
            'is_video': bool(is_video),
            'is_live': False,
            'requester_id': owner_id,
            'requester_name': q.from_user.first_name or 'کاربر',
            'duration': x.get('duration') or 0,
            'thumbnail': x.get('thumbnail'),
        }

        try:
            await _bb_music_start_or_queue(
                chat_id, item, panel_message=None, bot=q.message.get_bot()
            )
            try:
                await q.message.delete()
            except Exception:
                pass
            await q.answer('✅ پخش شروع شد یا به صف اضافه شد.')
        except Exception as exc:
            await q.answer('⚠️ پخش انجام نشد.', show_alert=True)
            await q.message.reply_text(
                '⚠️ <b>پخش آماده نشد.</b>\n\n' +
                safe_text(str(exc), 1000),
                parse_mode='HTML'
            )
        return True
    except Exception as exc:
        log.exception('pro music result callback failed: %s', exc)
        return True

_bb_music_result_callback_final = _bb_music_result_callback_final_pro


# Rebuild callback dispatcher so the overridden result callback is used.
async def _bb_final_music_callback_dispatch_pro(update, context):
    for fn in (
        _bb_music_live_callback_final,
        _bb_music_live_result_callback_final,
        _bb_music_result_callback_final_pro,
        _bb_music_download_callback_final,
        _bb_music_control_callback_final,
    ):
        try:
            if await fn(update, context):
                return
        except Exception as exc:
            log.exception('pro music callback layer: %s', exc)
            try:
                await update.callback_query.answer(
                    '⚠️ عملیات موزیکال انجام نشد.', show_alert=True
                )
            except Exception:
                pass
            return

_bb_final_music_callback_dispatch = _bb_final_music_callback_dispatch_pro


# Final refresh worker: UI progress only. Playback completion is event-driven.
async def _bb_music_start_refresh_pro(chat_id, owner_id, message):
    old = MUSIC_REFRESH_TASKS.pop(chat_id, None)
    if old:
        old.cancel()

    MUSIC_PANEL_META[chat_id] = {
        'owner_id': owner_id,
        'message_id': getattr(message, 'message_id', 0),
        'chat_id': chat_id,
        'message': message,
    }

    async def worker():
        while chat_id in MUSIC_CURRENT and chat_id in MUSIC_PANEL_META:
            await asyncio.sleep(5)
            state = MUSIC_CURRENT.get(chat_id)
            if not state:
                break
            try:
                pos = await get_current_position(chat_id)
                duration = float(state.get('duration') or 0)

                # Safety fallback if a library build doesn't emit StreamEnded.
                if duration and pos >= max(1, duration - 1.0):
                    await _bb_music_on_stream_end_pro(chat_id)
                    continue

                await _bb_music_render_panel(
                    chat_id,
                    int(state.get('requester_id') or owner_id),
                    message=message,
                    position=pos,
                )
            except asyncio.CancelledError:
                raise
            except Exception:
                continue

    MUSIC_REFRESH_TASKS[chat_id] = asyncio.create_task(worker())


_bb_music_start_refresh = _bb_music_start_refresh_pro


# Final control callback: use the real final skip/prev/playback functions.
_OLD_BB_MUSIC_CONTROL_CALLBACK_FINAL_PRO = _bb_music_control_callback_final

async def _bb_music_control_callback_final_pro(update, context):
    q = getattr(update, 'callback_query', None)
    if not q or not (q.data or '').startswith('mctrl:'):
        return False
    try:
        _, chat_raw, owner_raw, action = q.data.split(':', 3)
        chat_id, owner_id = int(chat_raw), int(owner_raw)
        if q.from_user.id != owner_id:
            await q.answer('🔒 این پنل برای درخواست‌کننده دیگری است.', show_alert=True)
            return True

        if action == 'pause':
            ok = await pause_playback(chat_id)
            try:
                await pause_call(chat_id)
            except Exception:
                pass
            await q.answer('⏸️ مکث شد.' if ok else '❌ چیزی در حال پخش نیست.')

        elif action == 'resume':
            ok = await resume_playback(chat_id)
            try:
                await resume_call(chat_id)
            except Exception:
                pass
            await q.answer('▶️ ادامه یافت.' if ok else '❌ پخش فعالی نداریم.')

        elif action == 'prev':
            item = await _bb_music_prev_pro(chat_id)
            await q.answer('⏮️ ' + (safe_text(item.get('title'), 70) if item else 'مورد قبلی نداریم.'))

        elif action == 'skip':
            item = await _bb_music_skip_pro(chat_id)
            await q.answer('⏭️ ' + (safe_text(item.get('title'), 70) if item else 'صف تمام شد.'))

        elif action == 'vol-10':
            await _bb_music_set_volume(chat_id, MUSIC_VOLUME[chat_id] - 10)
            MUSIC_MUTED[chat_id] = False
            await q.answer('🔉 صدا کم شد.')

        elif action == 'vol+10':
            await _bb_music_set_volume(chat_id, MUSIC_VOLUME[chat_id] + 10)
            MUSIC_MUTED[chat_id] = False
            await q.answer('🔊 صدا زیاد شد.')

        elif action == 'vol':
            await q.answer(f'🔊 میزان صدا: {MUSIC_VOLUME[chat_id]}%')

        elif action == 'mute':
            if MUSIC_MUTED[chat_id]:
                MUSIC_MUTED[chat_id] = False
                restore = MUSIC_PRE_MUTE_VOLUME[chat_id] or 100
                await _bb_music_set_volume(chat_id, restore)
                await q.answer('🔊 صدا دوباره فعال شد.')
            else:
                MUSIC_PRE_MUTE_VOLUME[chat_id] = MUSIC_VOLUME[chat_id] or 100
                MUSIC_MUTED[chat_id] = True
                await _bb_music_set_volume(chat_id, 0)
                await q.answer('🔇 صدا قطع شد.')

        elif action in ('speed-', 'speed+'):
            current = float(MUSIC_SPEED[chat_id])
            current += -0.25 if action == 'speed-' else 0.25
            current = max(0.5, min(2.0, round(current, 2)))
            MUSIC_SPEED[chat_id] = current
            state = MUSIC_CURRENT.setdefault(chat_id, {})
            state['playback_speed'] = current
            # PyTgCalls builds differ. Use a supported speed API if one exists;
            # otherwise keep the selected speed visible in the panel.
            applied = False
            if MUSIC_VC_ENGINE is not None:
                for name in ('set_playback_speed', 'set_speed', 'change_speed'):
                    fn = getattr(MUSIC_VC_ENGINE, name, None)
                    if fn:
                        try:
                            result = fn(chat_id, current)
                            if hasattr(result, '__await__'):
                                await result
                            applied = True
                            break
                        except Exception:
                            pass
            await q.answer(f'⚡ سرعت پخش: {current:g}×' + (' اعمال شد.' if applied else '.'))

        elif action == 'speed':
            await q.answer(f'⚡ سرعت پخش: {MUSIC_SPEED[chat_id]:g}×')

        elif action.startswith('seek'):
            delta_map = {
                'seek-60': -60,
                'seek-30': -30,
                'seek+30': 30,
                'seek+60': 60,
            }
            delta = delta_map.get(action, 0)
            state = MUSIC_CURRENT.get(chat_id) or {}
            duration = float(state.get('duration') or 0)
            try:
                current_pos = float(await get_current_position(chat_id))
            except Exception:
                current_pos = float(state.get('position') or 0)
            target_pos = max(0.0, current_pos + delta)
            if duration:
                target_pos = min(duration, target_pos)
            state['position'] = target_pos

            applied = False
            if MUSIC_VC_ENGINE is not None:
                for name in ('seek', 'seek_stream', 'seek_call'):
                    fn = getattr(MUSIC_VC_ENGINE, name, None)
                    if fn:
                        try:
                            result = fn(chat_id, int(target_pos))
                            if hasattr(result, '__await__'):
                                await result
                            applied = True
                            break
                        except Exception:
                            pass
            await q.answer(('⏪ ' if delta < 0 else '⏩ ') + f'{abs(delta)} ثانیه' + (' اعمال شد.' if applied else '.'))

        elif action == 'eq':
            modes = ('عادی', 'بیس', 'شفاف', 'واید')
            current = MUSIC_EQ_MODE[chat_id]
            idx = modes.index(current) if current in modes else 0
            next_mode = modes[(idx + 1) % len(modes)]
            MUSIC_EQ_MODE[chat_id] = next_mode
            state = MUSIC_CURRENT.setdefault(chat_id, {})
            state['equalizer'] = next_mode
            await q.answer(f'🎚️ اکولایزر: {next_mode}')

        elif action == 'queue':
            queue = MUSIC_QUEUE.get(chat_id) or []
            await q.answer('صف نمایش داده شد.')
            await q.message.reply_text(
                '📋 <b>صف پخش</b>\n\n' +
                ('\n'.join(
                    f'{i}. {safe_text(x.get("title"), 90)}'
                    for i, x in enumerate(queue, 1)
                ) or 'صف خالی است.'),
                parse_mode='HTML'
            )
            return True

        elif action == 'refresh':
            await q.answer('🔄 پنل تازه شد.')

        elif action == 'close':
            try:
                await q.message.delete()
            except Exception:
                try:
                    if getattr(q.message, 'photo', None):
                        await q.message.edit_caption(caption='🎵 <b>پنل بسته شد.</b>', parse_mode='HTML', reply_markup=None)
                    else:
                        await q.message.edit_text('🎵 <b>پنل بسته شد.</b>', parse_mode='HTML', reply_markup=None)
                except Exception:
                    pass
            MUSIC_PANEL_META.pop(chat_id, None)
            task = MUSIC_REFRESH_TASKS.pop(chat_id, None)
            if task:
                task.cancel()
            await q.answer('❌ پنل بسته شد؛ پخش ادامه دارد.')
            return True

        elif action == 'stop':
            current = MUSIC_CURRENT.pop(chat_id, None)
            if current:
                _bb_music_cleanup_local_state(current)
            MUSIC_QUEUE[chat_id] = []
            MUSIC_HISTORY.pop(chat_id, None)
            task = MUSIC_REFRESH_TASKS.pop(chat_id, None)
            if task:
                task.cancel()
            MUSIC_PANEL_META.pop(chat_id, None)
            try:
                await _bb_music_stop_final(chat_id)
            except Exception:
                pass
            try:
                if getattr(q.message, 'photo', None):
                    await q.message.edit_caption(
                        caption='⏹️ <b>پخش متوقف شد.</b>',
                        parse_mode='HTML', reply_markup=None
                    )
                else:
                    await q.message.edit_text(
                        '⏹️ <b>پخش متوقف شد.</b>',
                        parse_mode='HTML', reply_markup=None
                    )
            except Exception:
                pass
            await q.answer('⏹️ پخش متوقف شد.')
            return True

        else:
            await q.answer('❌ گزینه نامعتبر.', show_alert=True)
            return True

        try:
            await _bb_music_render_panel(
                chat_id, owner_id, message=q.message
            )
        except Exception:
            pass
        return True

    except Exception as exc:
        log.exception('pro music control failed: %s', exc)
        try:
            await q.answer('⚠️ کنترل پخش ناموفق بود.', show_alert=True)
        except Exception:
            pass
        return True

_bb_music_control_callback_final = _bb_music_control_callback_final_pro






# =============================================================================
# BILBILAK FINAL MUSIC ANTI-SPAM / SINGLE-PANEL PATCH
# =============================================================================
# مشکل اصلی نسخه قبلی:
# - render_panel روی "Message is not modified" دوباره reply_text می‌کرد؛
#   بنابراین هر 5 ثانیه یک پیام جدید ساخته می‌شد.
# - چند build wrapper یک dispatcher موزیکال را دوباره register می‌کردند.
# - dispatcher بعد از هندل موزیک، ApplicationHandlerStop نمی‌کرد و routerهای
#   قدیمی هم می‌توانستند همان پیام را دوباره پردازش کنند.
#
# این لایه نهایی هر سه مشکل را می‌بندد:
# 1) یک پنل واقعی برای هر chat
# 2) فقط edit همان پنل؛ هرگز fallback به reply برای Message is not modified
# 3) fingerprint برای جلوگیری از editهای بی‌دلیل
# 4) فقط یک refresh task فعال برای هر chat
# 5) فقط یک music dispatcher در build نهایی
# 6) بعد از هندل موفق موزیک، بقیه handlerها متوقف می‌شوند
# 7) خطاهای stale-message فقط لاگ harmless می‌شوند و باعث spam نمی‌شوند.

BB_MUSIC_PANEL_LOCKS = {}
BB_MUSIC_PANEL_FINGERPRINTS = {}
BB_MUSIC_PANEL_REPLACEMENT_LOCKS = {}


def _bb_music_markup_fingerprint(markup):
    try:
        rows = []
        for row in getattr(markup, 'inline_keyboard', []) or []:
            rows.append(tuple(
                (
                    getattr(b, 'text', ''),
                    getattr(b, 'callback_data', ''),
                    getattr(b, 'url', ''),
                )
                for b in row
            ))
        return repr(rows)
    except Exception:
        return repr(markup)


def _bb_music_panel_fingerprint(caption, markup):
    return (
        str(caption or ''),
        _bb_music_markup_fingerprint(markup),
    )


def _bb_music_is_same_message_error(exc):
    s = str(exc or '').lower()
    return (
        'message is not modified' in s
        or 'specified new message content and reply markup are exactly the same' in s
    )


def _bb_music_is_stale_message_error(exc):
    s = str(exc or '').lower()
    return (
        'message to be replied not found' in s
        or 'message to edit not found' in s
        or 'message to delete not found' in s
        or 'message_id_invalid' in s
        or 'message identifier is not specified' in s
    )


async def _bb_music_resolve_thumbnail(state):
    """اطمینان از اینکه پنل تا جای ممکن thumbnail واقعی همان رسانه را دارد."""
    if not state:
        return None
    existing = state.get('thumbnail')
    if existing:
        return existing
    if state.get('_thumbnail_checked'):
        return None

    state['_thumbnail_checked'] = True
    url = (state.get('url') or state.get('source_url') or '').strip()
    if not url or _music_yt_dlp is None:
        return None

    def _extract_thumbnail():
        opts = {
            'quiet': True,
            'no_warnings': True,
            'skip_download': True,
            'noplaylist': True,
        }
        with _music_yt_dlp.YoutubeDL(opts) as ydl:
            info = ydl.extract_info(url, download=False)
        return (info or {}).get('thumbnail')

    try:
        thumb = await asyncio.to_thread(_extract_thumbnail)
        if thumb:
            state['thumbnail'] = thumb
            return thumb
    except Exception as exc:
        log.debug('music thumbnail resolve skipped: %s', exc)
    return None


async def _bb_music_render_panel_nospam(
    chat_id,
    owner_id,
    message=None,
    bot=None,
    position=None,
):
    """Render exactly one persistent music panel. Never reply-spam on edit errors."""
    lock = BB_MUSIC_PANEL_LOCKS.setdefault(chat_id, asyncio.Lock())

    async with lock:
        state = MUSIC_CURRENT.get(chat_id) or {}
        # Resolve the actual media artwork once when a backend did not already
        # provide it. The thumbnail is stored back into the same playback state.
        await _bb_music_resolve_thumbnail(state)
        title = safe_text(state.get('title') or 'چیزی در حال پخش نیست', 120)

        try:
            duration = float(state.get('duration') or 0)
        except Exception:
            duration = 0.0

        if position is None:
            try:
                position = await get_current_position(chat_id)
            except Exception:
                position = float(state.get('position') or 0)

        try:
            position = max(0.0, float(position or 0))
        except Exception:
            position = 0.0

        bar = _music_progress(position, duration, 18) if duration else '▱' * 18
        time_text = (
            f'{_music_format_time(position)} / {_music_format_time(duration)}'
            if duration else 'LIVE / --:--'
        )
        status = (
            '⏸️ مکث'
            if state.get('paused_at') is not None
            else ('▶️ در حال پخش' if state else '⏹️ متوقف')
        )

        # Metadata is read-only UI data from the existing MUSIC_CURRENT state.
        media_type = (
            '🎬 فیلم' if state.get('is_video') else
            ('📡 پخش زنده' if state.get('is_live') else '🎵 آهنگ')
        )
        source_label = safe_text(
            state.get('source') or state.get('backend') or 'خودکار', 80
        )
        location_label = 'گروه'
        requester_label = safe_text(
            state.get('requester_name') or 'کاربر', 80
        )

        speed = MUSIC_SPEED[chat_id]
        eq = MUSIC_EQ_MODE[chat_id]
        mute_text = '🔇 بی‌صدا' if MUSIC_MUTED[chat_id] else f'🔊 صدا: {MUSIC_VOLUME[chat_id]}%'
        status_text = '⏸️ موزیک در حالت مکث میباشد.' if state.get('paused_at') is not None else '• موزیک در حال پخش میباشد.'

        caption = (
            '🎵 <b>پنل مدیریت موزیک بیل‌بیلک</b>\n'
            '━━━━━━━━━━━━━━━━━━\n'
            f'🎧 <b>{title}</b>\n\n'
            f'• <b>{status_text}</b>\n'
            f'• نوع پخش: <b>{media_type}</b>\n'
            f'• محل پخش: <b>{location_label}</b>\n'
            f'• درخواست کننده: <b>{requester_label}</b>\n'
            f'• منبع پخش: <b>{source_label}</b>\n\n'
            f'{bar}\n'
            f'⏱ <b>{time_text}</b>  |  {mute_text}  |  ⚡ {speed:g}×  |  🎚️ {eq}'
        )


        markup = _bb_music_panel_buttons(chat_id, owner_id)
        fp = (_bb_music_panel_fingerprint(caption, markup), state.get('thumbnail') or '')

        meta = MUSIC_PANEL_META.setdefault(chat_id, {})
        previous_thumbnail = meta.get('thumbnail')
        meta['owner_id'] = owner_id
        meta['chat_id'] = chat_id
        if bot is not None:
            meta['bot'] = bot

        # If we already rendered this exact state, do absolutely nothing.
        if (
            meta.get('message_id')
            and meta.get('fingerprint') == fp
            and meta.get('message') is not None
        ):
            return meta['message']

        target = message or meta.get('message')

        # If the caller passed a stale/deleted Message object, don't repeatedly
        # reply to it. We replace the panel once and store the new Message.
        if target is not None:
            try:
                # Telegram cannot change a photo while editing only its caption.
                # When the track thumbnail changes, replace the panel photo once.
                if (
                    getattr(target, 'photo', None)
                    and previous_thumbnail != state.get('thumbnail')
                ):
                    raise RuntimeError('MUSIC_PANEL_THUMBNAIL_CHANGED')
                if getattr(target, 'photo', None):
                    await target.edit_caption(
                        caption=caption,
                        parse_mode='HTML',
                        reply_markup=markup,
                    )
                elif state.get('thumbnail'):
                    # A text-only legacy panel must be replaced by the real
                    # thumbnail panel as soon as artwork is available.
                    raise RuntimeError('MUSIC_PANEL_NEEDS_THUMBNAIL_PHOTO')
                else:
                    await target.edit_text(
                        caption,
                        parse_mode='HTML',
                        reply_markup=markup,
                    )

                meta['message'] = target
                meta['message_id'] = getattr(target, 'message_id', 0)
                meta['fingerprint'] = fp
                meta['thumbnail'] = state.get('thumbnail')
                return target

            except Exception as exc:
                if _bb_music_is_same_message_error(exc):
                    # This is SUCCESS for our purposes: Telegram already has
                    # exactly the desired panel. NEVER call reply_text here.
                    meta['message'] = target
                    meta['message_id'] = getattr(target, 'message_id', 0)
                    meta['fingerprint'] = fp
                    meta['thumbnail'] = state.get('thumbnail')
                    return target

                if not _bb_music_is_stale_message_error(exc):
                    log.debug('music panel edit skipped: %s', exc)
                # For a stale/deleted target we continue to one replacement send.

        # Replacement/new panel. A per-chat lock prevents two simultaneous
        # workers/callbacks from creating two panels.
        replacement_lock = BB_MUSIC_PANEL_REPLACEMENT_LOCKS.setdefault(
            chat_id, asyncio.Lock()
        )
        async with replacement_lock:
            # Another concurrent call may have created the panel while we waited.
            meta = MUSIC_PANEL_META.setdefault(chat_id, {})
            if (
                meta.get('message_id')
                and meta.get('fingerprint') == fp
                and meta.get('message') is not None
            ):
                return meta['message']

            use_bot = bot or meta.get('bot')
            if use_bot is None and target is not None:
                try:
                    use_bot = target.get_bot()
                except Exception:
                    use_bot = None

            new_message = None
            thumb = state.get('thumbnail')

            try:
                if use_bot is not None:
                    if thumb:
                        try:
                            new_message = await use_bot.send_photo(
                                chat_id,
                                photo=thumb,
                                caption=caption,
                                parse_mode='HTML',
                                reply_markup=markup,
                            )
                        except Exception as exc:
                            log.debug('music thumbnail send skipped: %s', exc)

                    if new_message is None:
                        new_message = await use_bot.send_message(
                            chat_id,
                            caption,
                            parse_mode='HTML',
                            reply_markup=markup,
                        )
                elif target is not None:
                    # Last-resort direct send through the message's chat object.
                    chat_obj = getattr(target, 'chat', None)
                    if chat_obj is not None:
                        new_message = await chat_obj.send_message(
                            caption,
                            parse_mode='HTML',
                            reply_markup=markup,
                        )
            except Exception as exc:
                # Do not create a second reply as an error fallback.
                log.warning('music panel replacement failed: %s', exc)
                return None

            if new_message is not None:
                meta['message'] = new_message
                meta['message_id'] = getattr(new_message, 'message_id', 0)
                meta['fingerprint'] = fp
                meta['thumbnail'] = state.get('thumbnail')
                return new_message

            return None


async def _bb_music_start_refresh_nospam(chat_id, owner_id, message=None, bot=None):
    """One monitor task per chat; it edits the existing panel only."""
    old = MUSIC_REFRESH_TASKS.pop(chat_id, None)
    if old:
        try:
            old.cancel()
        except Exception:
            pass

    meta = MUSIC_PANEL_META.setdefault(chat_id, {})
    meta.update({
        'owner_id': owner_id,
        'chat_id': chat_id,
        'message': message or meta.get('message'),
        'message_id': getattr(message, 'message_id', 0) if message is not None
                     else meta.get('message_id', 0),
    })
    if bot is not None:
        meta['bot'] = bot

    generation = int(meta.get('refresh_generation', 0)) + 1
    meta['refresh_generation'] = generation

    async def worker():
        try:
            while (
                chat_id in MUSIC_CURRENT
                and chat_id in MUSIC_PANEL_META
                and MUSIC_PANEL_META.get(chat_id, {}).get('refresh_generation') == generation
            ):
                await asyncio.sleep(5)

                if (
                    chat_id not in MUSIC_CURRENT
                    or chat_id not in MUSIC_PANEL_META
                    or MUSIC_PANEL_META.get(chat_id, {}).get('refresh_generation') != generation
                ):
                    break

                state = MUSIC_CURRENT.get(chat_id)
                if not state:
                    break

                try:
                    pos = await get_current_position(chat_id)
                except Exception:
                    pos = float(state.get('position') or 0)

                try:
                    duration = float(state.get('duration') or 0)
                except Exception:
                    duration = 0.0

                # Only use the timer as a safety fallback. The primary end-of-
                # stream transition remains the StreamEnded event.
                if duration and pos >= max(1.0, duration - 1.0):
                    try:
                        await _bb_music_on_stream_end_pro(chat_id)
                    except Exception as exc:
                        log.warning('music stream-end fallback failed: %s', exc)
                    continue

                current_meta = MUSIC_PANEL_META.get(chat_id) or {}
                panel = await _bb_music_render_panel_nospam(
                    chat_id,
                    int(state.get('requester_id') or owner_id),
                    message=current_meta.get('message'),
                    bot=current_meta.get('bot') or bot,
                    position=pos,
                )

                if panel is not None:
                    current_meta['message'] = panel
                    current_meta['message_id'] = getattr(panel, 'message_id', 0)

        except asyncio.CancelledError:
            raise
        except Exception as exc:
            log.debug('music refresh worker stopped: %s', exc)

    task = asyncio.create_task(worker())
    MUSIC_REFRESH_TASKS[chat_id] = task
    return task


# Make anti-spam functions authoritative.
_bb_music_render_panel = _bb_music_render_panel_nospam
_bb_music_start_refresh = _bb_music_start_refresh_nospam


async def _bilbilak_music_absolute_dispatch_nospam(update, context):
    """Music dispatcher that stops all lower legacy routers after handling."""
    msg = getattr(update, 'effective_message', None)
    if not msg or not getattr(msg, 'text', None):
        return False

    try:
        raw = str(msg.text or '').strip()
        if not raw:
            return False

        if raw.startswith('/'):
            body = raw[1:].strip()
            first, _, rest = body.partition(' ')
            aliases = {
                'play': 'پخش آهنگ', 'song': 'پخش آهنگ', 'music': 'موزیکال',
                'musicmenu': 'موزیکال', 'queue': 'صف', 'skip': 'بعدی',
                'next': 'بعدی', 'previous': 'قبلی', 'prev': 'قبلی',
                'pause': 'مکث', 'resume': 'ادامه', 'stop': 'توقف',
                'end': 'اتمام', 'volume': 'صدا', 'vol': 'صدا',
                'live': 'لایو', 'radio': 'رادیو', 'remix': 'ریمیکس',
                'movie': 'پخش فیلم', 'series': 'پخش سریال',
            }
            key = first.split('@', 1)[0].lower()
            if key not in aliases:
                return False

            original_text = msg.text
            msg.text = aliases[key] + ((' ' + rest.strip()) if rest.strip() else '')
            try:
                handled = await _bb_music_message_router_final(update, context)
            finally:
                try:
                    msg.text = original_text
                except Exception:
                    pass
        else:
            handled = await _bb_music_message_router_final(update, context)

        if handled:
            # This is essential: otherwise legacy message routers can process
            # the same "پخش آهنگ" again and create another panel/result.
            raise ApplicationHandlerStop

        return False

    except ApplicationHandlerStop:
        raise
    except Exception as exc:
        log.exception('ABSOLUTE MUSIC DISPATCH ERROR: %s', exc)
        # Never reply to an already-deleted/stale message from an exception path.
        try:
            await msg.reply_text(
                '⚠️ دستور موزیکال دریافت شد، اما اجرای آن با خطا مواجه شد.\n'
                f'`{safe_text(type(exc).__name__ + ": " + str(exc), 350)}`',
                parse_mode='Markdown',
            )
        except Exception:
            pass
        return True


async def _bilbilak_music_absolute_callback_nospam(update, context):
    """Music callback dispatcher with a single authoritative callback path."""
    q = getattr(update, 'callback_query', None)
    if not q:
        return False

    data = str(q.data or '')
    if not (
        data.startswith('mplay:')
        or data.startswith('livepick:')
        or data.startswith('mctrl:')
        or data.startswith('msearch:')
    ):
        return False

    try:
        handled = bool(await _bb_final_music_callback_dispatch(update, context))
        if handled:
            raise ApplicationHandlerStop
        return False
    except ApplicationHandlerStop:
        raise
    except Exception as exc:
        log.exception('ABSOLUTE MUSIC CALLBACK ERROR: %s', exc)
        try:
            await q.answer('⚠️ اجرای کنترل موزیکال ناموفق بود.', show_alert=True)
        except Exception:
            pass
        return True


_bb_music_render_panel = _bb_music_render_panel_nospam
_bb_music_start_refresh = _bb_music_start_refresh_nospam
_bilbilak_music_absolute_dispatch = _bilbilak_music_absolute_dispatch_nospam
_bilbilak_music_absolute_callback = _bilbilak_music_absolute_callback_nospam


async def _bb_music_final_error_handler(update: object, context: ContextTypes.DEFAULT_TYPE):
    """Ignore harmless Telegram stale/edit errors; log real errors."""
    err = context.error
    s = str(err or '').lower()

    if _bb_music_is_same_message_error(err):
        return

    if (
        'message to be replied not found' in s
        or 'message to edit not found' in s
        or 'message to delete not found' in s
        or 'query is too old' in s
        or 'query id is invalid' in s
    ):
        log.debug('ignored stale Telegram music/message error: %s', err)
        return

    if isinstance(err, Forbidden):
        log.warning('Telegram permission error: %s', err)
        return

    log.exception('Unhandled Telegram error: %s', err)


# Final build: use the already-installed absolute music layer from the previous
# build chain, but DO NOT register it a second time.
_BB_BUILD_BEFORE_BLACK_MUSIC_FIXED = build_application

def build_application(token: str) -> Application:
    app = _BB_BUILD_BEFORE_BLACK_MUSIC_FIXED(token)

    # The absolute music handlers were already registered by the earlier build
    # layer. Registering them again here was a direct source of double routing.
    # Only add the final harmless-error handler.
    try:
        app.add_error_handler(_bb_music_final_error_handler)
    except Exception:
        pass

    return app





# =============================================================================
# BILBILAK FINAL MUSIC DELIVERY / STALE-REPLY / VIP GUARD PATCH
# =============================================================================
# This layer fixes the remaining production issues seen in the server log:
#   1) vip_active was referenced but only active_vip exists.
#   2) The search-result message could be deleted before a panel was safely
#      created, causing "Message to be replied not found" in an exception path.
#   3) Panel creation relied on Message.get_bot(); use context.bot explicitly.
#   4) A failed panel edit must never create a reply message.
#   5) A successful music start must always attempt exactly one panel send/edit.

# Compatibility alias used by the final callback guard.
if 'vip_active' not in globals():
    async def vip_active(cid: int) -> bool:
        return await active_vip(cid)

# Keep the existing feature guard, but make sure it is callable even on older DBs.
if 'vip_feature' not in globals():
    async def vip_feature(cid, feature):
        return True

async def _bb_music_result_callback_delivery_final(update, context):
    """Single authoritative search-result handler with guaranteed panel delivery."""
    q = getattr(update, 'callback_query', None)
    if not q or not str(getattr(q, 'data', '') or '').startswith('mplay:'):
        return False

    try:
        parts = str(q.data).split(':', 3)
        if len(parts) != 4:
            return False
        _, chat_raw, owner_raw, index_raw = parts
        chat_id = int(chat_raw)
        owner_id = int(owner_raw)
        index = int(index_raw)

        if int(q.from_user.id) != owner_id:
            await q.answer('🔒 این پنل برای درخواست‌کننده دیگری است.', show_alert=True)
            return True

        results = MUSIC_SEARCH_CACHE.get(f'{chat_id}:last') or []
        if not 1 <= index <= len(results):
            await q.answer('❌ نتیجه منقضی شده؛ دوباره جستجو کن.', show_alert=True)
            return True

        x = results[index - 1]
        is_video = BB_MUSIC_SEARCH_MODE.get(chat_id) == 'video'
        item = {
            'title': x.get('title') or 'بدون عنوان',
            'url': x.get('url'),
            'is_video': bool(is_video),
            'is_live': False,
            'requester_id': owner_id,
            'requester_name': q.from_user.first_name or 'کاربر',
            'duration': x.get('duration') or 0,
            'thumbnail': x.get('thumbnail'),
        }

        # Always use the current Bot instance. Do not depend on a Message object
        # that is about to be deleted.
        bot = getattr(context, 'bot', None)
        if bot is None:
            raise RuntimeError('Bot instance is unavailable for music panel delivery.')

        started, panel = await _bb_music_start_or_queue(
            chat_id,
            item,
            panel_message=None,
            bot=bot,
            requester_id=owner_id,
        )

        # If another legacy layer returned without creating a panel, force one
        # safe render now. This is intentionally NOT a reply to the search result.
        if panel is None and MUSIC_CURRENT.get(chat_id):
            panel = await _bb_music_render_panel(
                chat_id,
                owner_id,
                message=None,
                bot=bot,
            )
            if panel is not None:
                await _bb_music_start_refresh(chat_id, owner_id, panel, bot=bot)

        if panel is None and MUSIC_CURRENT.get(chat_id):
            raise RuntimeError('پخش شروع شد اما پیام پنل پخش ارسال نشد.')

        # Delete the old search-result message only AFTER the new panel has been
        # delivered. Never attempt reply_text() on this old message afterwards.
        try:
            await q.message.delete()
        except Exception as exc:
            if not _bb_music_is_stale_message_error(exc):
                log.debug('music search-result delete skipped: %s', exc)

        await q.answer('✅ پخش شروع شد یا به صف اضافه شد.')
        log.info(
            'MUSIC PANEL DELIVERY OK chat=%s started=%s panel=%s message_id=%s',
            chat_id,
            started,
            bool(panel),
            getattr(panel, 'message_id', 0) if panel else 0,
        )
        return True

    except Exception as exc:
        log.exception('music result delivery failed: %s', exc)
        try:
            await q.answer('⚠️ پخش آماده نشد.', show_alert=True)
        except Exception:
            pass

        # IMPORTANT: never reply to q.message here. It may already be deleted.
        # Send a fresh standalone diagnostic to the same chat instead.
        try:
            bot = getattr(context, 'bot', None)
            chat_id = int(getattr(getattr(q, 'message', None), 'chat_id', 0) or 0)
            if bot is not None and chat_id:
                await bot.send_message(
                    chat_id,
                    '⚠️ <b>پخش آماده نشد.</b>\n\n' +
                    safe_text(f'{type(exc).__name__}: {exc}', 1000),
                    parse_mode='HTML',
                )
        except Exception as send_exc:
            log.debug('music diagnostic send skipped: %s', send_exc)
        return True

# Make every dispatcher that references this final callback use the repaired one.
_bb_music_result_callback_final_pro = _bb_music_result_callback_delivery_final
_bb_music_result_callback_final = _bb_music_result_callback_delivery_final

# Rebuild the final callback chain without changing any other music controls.
async def _bb_final_music_callback_dispatch_delivery_final(update, context):
    for fn in (
        _bb_music_live_callback_final,
        _bb_music_live_result_callback_final,
        _bb_music_result_callback_delivery_final,
        _bb_music_download_callback_final,
        _bb_music_control_callback_final,
    ):
        try:
            if await fn(update, context):
                return True
        except Exception as exc:
            log.exception('music callback delivery layer: %s', exc)
            q = getattr(update, 'callback_query', None)
            try:
                if q:
                    await q.answer('⚠️ عملیات موزیکال انجام نشد.', show_alert=True)
            except Exception:
                pass
            return True
    return False

_bb_final_music_callback_dispatch = _bb_final_music_callback_dispatch_delivery_final

# Final absolute callback wrapper. It is deliberately installed at the highest
# priority in build_application below.
async def _bilbilak_music_absolute_callback_delivery_final(update, context):
    q = getattr(update, 'callback_query', None)
    if not q:
        return False
    data = str(getattr(q, 'data', '') or '')
    if not (
        data.startswith('mplay:')
        or data.startswith('livepick:')
        or data.startswith('mctrl:')
        or data.startswith('msearch:')
    ):
        return False
    try:
        handled = await _bb_final_music_callback_dispatch_delivery_final(update, context)
        if handled:
            raise ApplicationHandlerStop
        return False
    except ApplicationHandlerStop:
        raise
    except Exception as exc:
        log.exception('FINAL MUSIC CALLBACK ERROR: %s', exc)
        try:
            await q.answer('⚠️ اجرای کنترل موزیکال ناموفق بود.', show_alert=True)
        except Exception:
            pass
        return True

_bilbilak_music_absolute_callback = _bilbilak_music_absolute_callback_delivery_final

# The last build wrapper adds only the repaired callback handler. Existing
# handlers remain intact; this handler wins because of the negative group.
_BILBILAK_BUILD_BEFORE_DELIVERY_FINAL = build_application

def build_application(token: str) -> Application:
    app = _BILBILAK_BUILD_BEFORE_DELIVERY_FINAL(token)
    app.add_handler(
        CallbackQueryHandler(_bilbilak_music_absolute_callback_delivery_final),
        group=-100002,
    )
    return app


