# BILBILAK FINAL STATS PANEL — DAILY / TOTAL / 7D / MONTH / VC PRESENCE
# =============================================================================
# این لایه فقط سیستم آمار را جایگزین می‌کند. منطق سایر بخش‌ها دست‌نخورده است.

_BB_STATS_PANEL_READY = False
_BB_STATS_JOB_NAME = 'bilbilak-midnight-daily-stats'

async def _bb_stats_schema():
    global _BB_STATS_PANEL_READY
    if _BB_STATS_PANEL_READY:
        return
    await DBX.execute("""
        CREATE TABLE IF NOT EXISTS bb_member_daily_adds(
            chat_id INTEGER NOT NULL,
            user_id INTEGER NOT NULL,
            day TEXT NOT NULL,
            adds INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY(chat_id,user_id,day)
        )
    """)
    await DBX.execute("""
        CREATE TABLE IF NOT EXISTS bb_call_presence(
            chat_id INTEGER NOT NULL,
            user_id INTEGER NOT NULL,
            day TEXT NOT NULL,
            seconds INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY(chat_id,user_id,day)
        )
    """)
    await DBX.execute("CREATE INDEX IF NOT EXISTS idx_bb_member_daily_adds ON bb_member_daily_adds(chat_id,day)")
    await DBX.execute("CREATE INDEX IF NOT EXISTS idx_bb_call_presence ON bb_call_presence(chat_id,day)")
    _BB_STATS_PANEL_READY = True


def _bb_stats_day_local(offset_days=0):
    try:
        from zoneinfo import ZoneInfo
        d = datetime.now(ZoneInfo('Asia/Tehran')).date() + timedelta(days=offset_days)
    except Exception:
        d = datetime.utcnow().date() + timedelta(hours=3, minutes=30) + timedelta(days=offset_days)
    return d.strftime('%Y-%m-%d')


def _bb_stats_fmt_seconds(seconds):
    try:
        seconds = max(0, int(seconds or 0))
    except Exception:
        seconds = 0
    days, rem = divmod(seconds, 86400)
    hours, rem = divmod(rem, 3600)
    minutes, secs = divmod(rem, 60)
    parts=[]
    if days: parts.append(f'{days} روز')
    if hours: parts.append(f'{hours} ساعت')
    if minutes: parts.append(f'{minutes} دقیقه')
    if secs or not parts: parts.append(f'{secs} ثانیه')
    return ' و '.join(parts)


def _bb_stats_user_html(row, value, rank):
    uid=int(row['user_id'])
    name=safe_text(row['first_name'] or 'کاربر', 40)
    username=(row['username'] or '').strip()
    if username:
        who=f'@{safe_text(username,40)}'
    else:
        who=f'<a href="tg://user?id={uid}">{name}</a>'
    return f'<b>{rank}.</b> {who} — <b>{int(value or 0):,}</b>'

async def _bb_stats_rows(chat_id, metric, day=None, days=None, limit=10):
    if metric == 'messages_today':
        rows=await DBX.execute(
            "SELECT s.user_id,s.first_name,s.username,COALESCE(d.messages,0) value "
            "FROM chat_member_stats s JOIN bb_message_daily d ON d.chat_id=s.chat_id AND d.user_id=s.user_id "
            "WHERE s.chat_id=? AND d.day=? AND COALESCE(d.messages,0)>0 ORDER BY value DESC,s.user_id ASC LIMIT ?",
            (chat_id,day,limit),fetch=True)
        return rows
    if metric == 'messages_7d' or metric == 'messages_month':
        start=day if days==1 else _bb_stats_day_local(-(days-1))
        rows=await DBX.execute(
            "SELECT s.user_id,s.first_name,s.username,SUM(d.messages) value "
            "FROM chat_member_stats s JOIN bb_message_daily d ON d.chat_id=s.chat_id AND d.user_id=s.user_id "
            "WHERE s.chat_id=? AND d.day BETWEEN ? AND ? GROUP BY s.user_id "
            "HAVING SUM(d.messages)>0 ORDER BY value DESC,s.user_id ASC LIMIT ?",
            (chat_id,start,day,limit),fetch=True)
        return rows
    if metric == 'messages_total':
        return await DBX.execute(
            "SELECT user_id,first_name,username,messages value FROM chat_member_stats WHERE chat_id=? AND messages>0 ORDER BY messages DESC,user_id ASC LIMIT ?",
            (chat_id,limit),fetch=True)
    if metric == 'adds_today':
        return await DBX.execute(
            "SELECT s.user_id,s.first_name,s.username,SUM(a.adds) value FROM chat_member_stats s "
            "JOIN bb_member_daily_adds a ON a.chat_id=s.chat_id AND a.user_id=s.user_id "
            "WHERE s.chat_id=? AND a.day=? GROUP BY s.user_id HAVING SUM(a.adds)>0 ORDER BY value DESC,s.user_id ASC LIMIT ?",
            (chat_id,day,limit),fetch=True)
    if metric == 'adds_total':
        return await DBX.execute(
            "SELECT user_id,first_name,username,COALESCE(adds,0) value FROM chat_member_stats WHERE chat_id=? AND adds>0 ORDER BY adds DESC,user_id ASC LIMIT ?",
            (chat_id,limit),fetch=True)
    if metric == 'call_today':
        return await DBX.execute(
            "SELECT s.user_id,s.first_name,s.username,SUM(p.seconds) value FROM chat_member_stats s "
            "JOIN bb_call_presence p ON p.chat_id=s.chat_id AND p.user_id=s.user_id "
            "WHERE s.chat_id=? AND p.day=? GROUP BY s.user_id HAVING SUM(p.seconds)>0 ORDER BY value DESC,s.user_id ASC LIMIT ?",
            (chat_id,day,limit),fetch=True)
    if metric == 'call_total':
        return await DBX.execute(
            "SELECT s.user_id,s.first_name,s.username,SUM(p.seconds) value FROM chat_member_stats s "
            "JOIN bb_call_presence p ON p.chat_id=s.chat_id AND p.user_id=s.user_id "
            "WHERE s.chat_id=? GROUP BY s.user_id HAVING SUM(p.seconds)>0 ORDER BY value DESC,s.user_id ASC LIMIT ?",
            (chat_id,limit),fetch=True)
    return []

_BB_STATS_LABELS={
    'adds_today':('➕ ادد امروز','تعداد افرادی که امروز توسط هر کاربر به گروه اضافه شده‌اند.'),
    'messages_today':('💬 پیام‌های امروز','تعداد پیام‌های ثبت‌شده امروز.'),
    'messages_total':('📚 تعداد پیام‌های کل','مجموع پیام‌های ثبت‌شده از شروع آمارگیری.'),
    'adds_total':('👥 ادد کلی','مجموع اعضایی که هر کاربر به گروه اضافه کرده است.'),
    'call_today':('🎙 مدت حضور در کال امروز','مدت حضور اعضا در کال؛ فقط داده‌های حضور ثبت‌شده نمایش داده می‌شود.'),
    'call_total':('📡 مدت حضور در کال کلی','مجموع مدت حضور ثبت‌شده اعضا در کال.'),
    'messages_7d':('📅 پیام‌های ۷ روز اخیر','مجموع پیام‌های هر کاربر در هفت روز اخیر.'),
    'messages_month':('🗓 پیام‌های ماهانه','مجموع پیام‌های هر کاربر در ۳۰ روز اخیر.'),
}

async def _bb_stats_total(chat_id, metric, day=None):
    rows=await _bb_stats_rows(chat_id,metric,day=day,days=(7 if metric=='messages_7d' else 30 if metric=='messages_month' else 1),limit=100000)
    return sum(int(r['value'] or 0) for r in rows)

async def _bb_stats_detail_text(chat_id, metric, limit=10, day=None):
    await _bb_stats_schema()
    day=day or _bb_stats_day_local(0)
    rows=await _bb_stats_rows(chat_id,metric,day=day,days=(7 if metric=='messages_7d' else 30 if metric=='messages_month' else 1),limit=limit)
    title,desc=_BB_STATS_LABELS[metric]
    if not rows:
        return f'🐾 <b>{title}</b>\n\n📭 برای این بخش هنوز آماری ثبت نشده است.'
    lines=[f'🐾 <b>{title}</b>',f'▫️ {desc}','',f'🏆 <b>۱۰ نفر برتر</b>']
    for i,row in enumerate(rows,1):
        value=int(row['value'] or 0)
        shown=_bb_stats_fmt_seconds(value) if metric.startswith('call_') else f'{value:,} مورد'
        lines.append(_bb_stats_user_html(row,value,i).replace(f' — <b>{value:,}</b>',f' — <b>{shown}</b>'))
    total=sum(int(r['value'] or 0) for r in rows)
    lines += ['',f'📊 مجموع رتبه‌های نمایش‌داده‌شده: <b>{_bb_stats_fmt_seconds(total) if metric.startswith("call_") else f"{total:,}"}</b>', '✨ بیل‌بیلک می‌گه: آمار، داستان فعالیت گروهه؛ نه فقط چندتا عدد! 🐶']
    return '\n'.join(lines)


def _bb_stats_panel_keyboard(uid):
    return keyboard([
        [btn('➕ ادد امروز',f'bstats:{uid}:adds_today',style='success'),btn('💬 پیام امروز',f'bstats:{uid}:messages_today',style='primary')],
        [btn('📚 پیام کل',f'bstats:{uid}:messages_total',style='primary'),btn('👥 ادد کلی',f'bstats:{uid}:adds_total',style='success')],
        [btn('🎙 کال امروز',f'bstats:{uid}:call_today',style='primary'),btn('📡 کال کلی',f'bstats:{uid}:call_total',style='primary')],
        [btn('📅 پیام ۷ روز',f'bstats:{uid}:messages_7d',style='success'),btn('🗓 پیام ماهانه',f'bstats:{uid}:messages_month',style='success')],
        [btn('🐾 جمع‌بندی امروز',f'bstats:{uid}:summary',style='primary'),btn('✕ بستن پنل',f'bstats:{uid}:close',style='danger')],
    ])

async def _bb_stats_open_panel(update, context):
    msg=update.effective_message; chat=update.effective_chat; user=update.effective_user
    if not msg or not chat or chat.type=='private':
        if msg: await msg.reply_text('📊 آمار گروه را داخل گروه باز کن.')
        return True
    if not await is_admin(update):
        await msg.reply_text('⛔ فقط ادمین واقعی گروه می‌تواند آمار مدیریتی را ببیند.')
        return True
    await _bb_stats_schema()
    text=(
        '🐾 <b>مرکز آمار بیل‌بیلک</b>\n'
        '━━━━━━━━━━━━━━━━━━\n'
        '📊 اینجا همه‌چیز مرتب و بیل‌بیلکی جمع شده!\n'
        'روی هر دکمه بزن تا آمار دقیق همان بخش + ۱۰ نفر اول را ببینی.\n\n'
        '✨ هر بخش اگر داده نداشته باشد، صادقانه می‌گوید «آماری ثبت نشده».\n'
        '━━━━━━━━━━━━━━━━━━'
    )
    sent=await msg.reply_text(text,parse_mode='HTML',reply_markup=_bb_stats_panel_keyboard(user.id))
    return True

async def _bb_stats_callback(update, context):
    q=getattr(update,'callback_query',None)
    if not q or not str(q.data or '').startswith('bstats:'):
        return False
    p=str(q.data).split(':',2)
    if len(p)!=3: return True
    try: uid=int(p[1])
    except Exception: uid=0
    if q.from_user.id!=uid:
        await q.answer('⛔ این پنل آمار برای ادمین دیگری است.',show_alert=True); return True
    try:
        chat_id=q.message.chat.id
        fake=type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat,'effective_message':q.message})()
        if not await is_admin(fake,uid):
            await q.answer('⛔ دسترسی ادمینی نداری.',show_alert=True); return True
        action=p[2]
        if action=='close':
            await q.message.delete(); await q.answer('🐾 پنل آمار بسته شد.'); return True
        if action=='home':
            text=('🐾 <b>مرکز آمار بیل‌بیلک</b>\n━━━━━━━━━━━━━━━━━━\n'
                  '📊 روی هر دکمه بزن تا آمار دقیق همان بخش + ۱۰ نفر اول را ببینی.\n'
                  '✨ اگر داده‌ای نباشد، بیل‌بیلک صادقانه اعلام می‌کند.')
            await q.edit_message_text(text,parse_mode='HTML',reply_markup=_bb_stats_panel_keyboard(uid))
            await q.answer('🐾 برگشتیم به مرکز آمار.')
            return True
        if action=='summary':
            text=await _bb_stats_nightly_text(chat_id,_bb_stats_day_local(0),topn=3,heading='🐾 جمع‌بندی امروز')
            await q.edit_message_text(text,parse_mode='HTML',reply_markup=_bb_stats_panel_keyboard(uid)); await q.answer('✨ جمع‌بندی آماده شد.'); return True
        text=await _bb_stats_detail_text(chat_id,action,10)
        await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('🔙 بازگشت به مرکز آمار',f'bstats:{uid}:home',style='primary')]]))
        await q.answer('📊 آمار دقیق آماده شد.')
        return True
    except Exception as exc:
        log.exception('stats callback failed: %s',exc)
        await q.answer('⚠️ نمایش آمار انجام نشد.',show_alert=True)
        return True

async def _bb_stats_nightly_text(chat_id, day, topn=3, heading='🌙 گزارش شبانه بیل‌بیلک'):
    parts=[f'{heading}',f'📅 تاریخ آماری: <b>{day}</b>','━━━━━━━━━━━━━━━━━━']
    for metric in _BB_STATS_LABELS:
        rows=await _bb_stats_rows(chat_id,metric,day=day,days=(7 if metric=='messages_7d' else 30 if metric=='messages_month' else 1),limit=topn)
        label=_BB_STATS_LABELS[metric][0]
        parts.append(f'\n{label}')
        if not rows:
            parts.append('📭 کسی/داده‌ای برای این بخش ثبت نشده.')
        else:
            for i,r in enumerate(rows,1):
                v=int(r['value'] or 0)
                shown=_bb_stats_fmt_seconds(v) if metric.startswith('call_') else f'{v:,}'
                parts.append(_bb_stats_user_html(r,v,i).replace(f' — <b>{v:,}</b>',f' — <b>{shown}</b>'))
    parts.append('\n━━━━━━━━━━━━━━━━━━\n🐾 <b>بیل‌بیلک:</b> شب بخیر! اینم گزارش امشب؛ عددها خوابشون نمی‌بره 😎🐶')
    return '\n'.join(parts)

async def _bb_stats_nightly_job(context):
    await _bb_stats_schema()
    day=_bb_stats_day_local(-1)
    rows=await DBX.execute('SELECT chat_id FROM chats WHERE chat_id<0 AND active=1',fetch=True)
    for r in rows:
        cid=int(r['chat_id'])
        try:
            text=await _bb_stats_nightly_text(cid,day,topn=3)
            await context.bot.send_message(cid,text,parse_mode='HTML')
        except Exception as exc:
            log.warning('nightly stats failed chat=%s: %s',cid,exc)

async def _bb_stats_install_job(application):
    await _bb_stats_schema()
    jq=getattr(application,'job_queue',None)
    if jq is None: return
    old=jq.get_jobs_by_name(_BB_STATS_JOB_NAME)
    for job in old:
        try: job.schedule_removal()
        except Exception: pass
    try:
        from zoneinfo import ZoneInfo
        at=datetime.now(ZoneInfo('Asia/Tehran')).replace(hour=0,minute=0,second=0,microsecond=0).timetz()
    except Exception:
        at=datetime.strptime('00:00','%H:%M').time()
    jq.run_daily(_bb_stats_nightly_job,time=at,name=_BB_STATS_JOB_NAME)

# Track per-user adds for the new panel without changing the old welcome/add logic.
_BB_STATS_OLD_SERVICE_MEMBERS=service_members_v4
async def service_members_v4(update, context):
    await _BB_STATS_OLD_SERVICE_MEMBERS(update,context)
    msg=update.effective_message; chat=update.effective_chat
    if not msg or not chat or chat.type=='private' or not msg.new_chat_members or not msg.from_user: return
    try:
        await _bb_stats_schema()
        day=_bb_stats_day_local(0); n=len(msg.new_chat_members)
        await DBX.execute(
            'INSERT INTO bb_member_daily_adds(chat_id,user_id,day,adds) VALUES(?,?,?,?) ON CONFLICT(chat_id,user_id,day) DO UPDATE SET adds=adds+excluded.adds',
            (chat.id,msg.from_user.id,day,n)
        )
    except Exception as exc: log.debug('daily add stats: %s',exc)

# Replace the old plain-Persian stats commands with the new glass-style panel.
_BB_STATS_OLD_PROCESS_TEXT=process_text_state_v5
async def process_text_state_v5(update,context):
    msg=update.effective_message; t=normalize(msg.text or '') if msg and msg.text else ''
    if t=='آمار':
        return await _bb_stats_open_panel(update,context)
    return await _BB_STATS_OLD_PROCESS_TEXT(update,context)

# Override the slash command too, while leaving all other commands untouched.
async def _bb_stats_command_panel(update,context):
    return await _bb_stats_open_panel(update,context)

# Final build wrapper for the stats panel and midnight scheduler.
_BB_STATS_BUILD_PREV=build_application
def build_application(token: str) -> Application:
    app=_BB_STATS_BUILD_PREV(token)
    app.add_handler(CallbackQueryHandler(_bb_stats_callback),group=-100010)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_stats_text_absolute),group=-100011) if '_bb_stats_text_absolute' in globals() else None
    try:
        app.add_handler(CommandHandler('stats',_bb_stats_command_panel),group=-100012)
    except Exception: pass
    old_post_init=getattr(app,'post_init',None)
    async def _stats_post_init(application):
        if old_post_init:
            await old_post_init(application)
        try: await _bb_stats_install_job(application)
        except Exception as exc: log.exception('stats scheduler install failed: %s',exc)
    try: app.post_init=_stats_post_init
    except Exception: pass
    return app

async def _bb_stats_text_absolute(update,context):
    msg=update.effective_message
    if msg and normalize(msg.text or '')=='آمار':
        await _bb_stats_open_panel(update,context)
        raise ApplicationHandlerStop
    return False



# =============================================================================
# BILBILAK MUSIC PRO MAX — MULTI-SOURCE SEARCH / LARGE-FILE DELIVERY /
# SPECIAL PLAYER / REPLY-TO-MEDIA PLAYBACK
# =============================================================================
# این لایه فقط قابلیت‌های موزیکالِ صریحاً درخواستی را اضافه/تقویت می‌کند.
# منطق سایر بخش‌های ربات دست‌نخورده می‌ماند.
#
# محدودیت واقعی تلگرام:
# - Bot API معمولی: دانلود با getFile تا 20MB و آپلود فایل تا 50MB.
# - Local Bot API Server: دانلود بدون سقف و آپلود تا 2GB.
# - برای رسانه‌ای که از قبل در همان گروه است، تا جای ممکن file_id استفاده می‌کنیم
#   تا دانلود/آپلود دوباره انجام نشود.
# - برای فایل‌های بزرگ خارجی، اگر Session شخصی موزیکال متصل باشد، ارسال با همان
#   اکانت انجام می‌شود تا محدودیت آپلود Bot API دور زده نشود؛ DRM/محتوای خصوصی
#   یا محدودیت دسترسی دور زده نمی‌شود.

MUSIC_SPECIAL_PLAYER_TABLE_READY = False
MUSIC_SEARCH_SOURCES = (
    ('youtube', 'ytsearch{limit}:{query}'),
    ('soundcloud', 'scsearch{limit}:{query}'),
    # Bandcamp search is available in yt-dlp builds that expose its search IE.
    ('bandcamp', 'bcsearch{limit}:{query}'),
)


def _bb_music_human_size(size):
    try:
        size = int(size or 0)
    except Exception:
        size = 0
    if size < 1024:
        return f'{size} B'
    units = ('KB', 'MB', 'GB', 'TB')
    value = float(size)
    for unit in units:
        value /= 1024.0
        if value < 1024 or unit == units[-1]:
            return f'{value:.2f} {unit}'
    return f'{size} B'


async def _bb_music_ensure_special_player_table():
    global MUSIC_SPECIAL_PLAYER_TABLE_READY
    if MUSIC_SPECIAL_PLAYER_TABLE_READY:
        return
    await DBX.execute('''
        CREATE TABLE IF NOT EXISTS music_special_players (
            chat_id INTEGER NOT NULL,
            user_id INTEGER NOT NULL,
            granted_by INTEGER NOT NULL DEFAULT 0,
            created_at INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY(chat_id, user_id)
        )
    ''')
    MUSIC_SPECIAL_PLAYER_TABLE_READY = True


async def _bb_music_is_special_player(chat_id, user_id):
    if not chat_id or not user_id:
        return False
    await _bb_music_ensure_special_player_table()
    row = await DBX.one(
        'SELECT user_id FROM music_special_players WHERE chat_id=? AND user_id=?',
        (int(chat_id), int(user_id)),
    )
    return bool(row)


async def _bb_music_set_special_player(chat_id, user_id, granted_by):
    await _bb_music_ensure_special_player_table()
    await DBX.execute(
        'INSERT OR REPLACE INTO music_special_players(chat_id,user_id,granted_by,created_at) VALUES(?,?,?,?)',
        (int(chat_id), int(user_id), int(granted_by), int(time.time())),
    )


async def _bb_music_remove_special_player(chat_id, user_id):
    await _bb_music_ensure_special_player_table()
    await DBX.execute(
        'DELETE FROM music_special_players WHERE chat_id=? AND user_id=?',
        (int(chat_id), int(user_id)),
    )


async def _bb_music_special_players(chat_id):
    await _bb_music_ensure_special_player_table()
    return await DBX.execute(
        'SELECT user_id,granted_by,created_at FROM music_special_players WHERE chat_id=? ORDER BY created_at DESC',
        (int(chat_id),), fetch=True,
    )


async def _bb_music_can_request(update):
    """ادمین واقعی یا ویژه‌پلیر؛ برای کنترل‌های حساس همچنان ادمین واقعی لازم است."""
    chat = getattr(update, 'effective_chat', None)
    user = getattr(update, 'effective_user', None)
    if not chat or getattr(chat, 'type', None) == 'private' or not user:
        return False
    if await _bb_music_group_admin(update, user.id):
        return True
    return await _bb_music_is_special_player(chat.id, user.id)


async def _bb_music_admin_manage_special_player(update, action):
    msg = getattr(update, 'effective_message', None)
    chat = getattr(update, 'effective_chat', None)
    actor = getattr(update, 'effective_user', None)
    if not msg or not chat or not actor:
        return False
    if chat.type == 'private':
        return False
    if not await _bb_music_group_admin(update, actor.id):
        await msg.reply_text('⛔ فقط ادمین واقعی گروه می‌تواند ویژه‌پلیر تعیین کند.')
        return True

    reply = getattr(msg, 'reply_to_message', None)
    target = getattr(reply, 'from_user', None) if reply else None
    if not target:
        await msg.reply_text('👤 روی پیام کاربر ریپلای کن و بنویس: ویژه پلیر')
        return True
    if getattr(target, 'is_bot', False):
        await msg.reply_text('🤖 ربات را نمی‌توان ویژه‌پلیر کرد.')
        return True

    if action == 'grant':
        await _bb_music_set_special_player(chat.id, target.id, actor.id)
        await msg.reply_text(
            f'⭐ {mention_html(target)} به <b>ویژه‌پلیر موزیکال</b> این گروه اضافه شد.\n'
            'از این به بعد می‌تواند درخواست پخش آهنگ، فیلم، رادیو و لایو بدهد.',
            parse_mode='HTML',
        )
    elif action == 'revoke':
        await _bb_music_remove_special_player(chat.id, target.id)
        await msg.reply_text(f'🚫 ویژه‌پلیر {mention_html(target)} حذف شد.', parse_mode='HTML')
    return True


async def _bb_music_special_player_text(update):
    msg = getattr(update, 'effective_message', None)
    chat = getattr(update, 'effective_chat', None)
    if not msg or not chat or chat.type == 'private':
        return False
    raw = (getattr(msg, 'text', '') or '').strip()
    low = normalize(raw)

    if low in {'ویژه پلیر', 'ویژه‌پلیر', 'ویژه پلیر کن', 'ویژه‌پلیر کن'}:
        return await _bb_music_admin_manage_special_player(update, 'grant')
    if low in {'حذف ویژه پلیر', 'حذف ویژه‌پلیر', 'لغو ویژه پلیر', 'لغو ویژه‌پلیر'}:
        return await _bb_music_admin_manage_special_player(update, 'revoke')
    if low in {'لیست ویژه پلیر', 'لیست ویژه‌پلیر'}:
        if not await _bb_music_group_admin(update):
            await msg.reply_text('⛔ فقط ادمین واقعی گروه.')
            return True
        rows = await _bb_music_special_players(chat.id)
        if not rows:
            await msg.reply_text('⭐ هنوز ویژه‌پلیر موزیکال برای این گروه ثبت نشده است.')
            return True
        lines = ['⭐ <b>ویژه‌پلیرهای موزیکال</b>', '━━━━━━━━━━━━━━━━━━']
        for i, row in enumerate(rows[:50], 1):
            uid = int(row['user_id'])
            try:
                member = await chat.get_member(uid)
                name = getattr(getattr(member, 'user', None), 'full_name', None) or str(uid)
            except Exception:
                name = str(uid)
            lines.append(f'{i}. {_bb_html.escape(safe_text(name, 70))} — <code>{uid}</code>')
        await msg.reply_text('\n'.join(lines), parse_mode='HTML')
        return True
    return False


async def _bb_music_multisource_search(query, limit=MUSIC_SEARCH_LIMIT, *, video=False):
    """جستجوی موازی در چند موتور yt-dlp؛ YouTube تنها منبع نیست."""
    query = _music_clean_query(query)
    if not query or _music_yt_dlp is None:
        return []
    limit = max(1, min(int(limit or 10), 10))

    async def one(source_name, expression):
        def _run():
            opts = _music_ydl_options(audio_only=not video, download=False)
            opts['extract_flat'] = True
            opts['noplaylist'] = True
            with _music_yt_dlp.YoutubeDL(opts) as ydl:
                data = ydl.extract_info(
                    expression.format(limit=limit, query=query), download=False
                ) or {}
            out = []
            for item in data.get('entries') or []:
                if not item:
                    continue
                out.append({
                    'id': item.get('id'),
                    'title': item.get('title') or 'بدون عنوان',
                    'url': item.get('webpage_url') or item.get('original_url') or item.get('url'),
                    'duration': item.get('duration') or 0,
                    'thumbnail': item.get('thumbnail'),
                    'uploader': item.get('uploader') or '',
                    'source': source_name,
                })
            return out
        try:
            return await asyncio.to_thread(_run)
        except Exception as exc:
            log.debug('music multi-source search %s failed: %s', source_name, exc)
            return []

    results = await asyncio.gather(*(
        one(name, expr) for name, expr in MUSIC_SEARCH_SOURCES
    ), return_exceptions=False)

    merged = []
    seen = set()
    for source_results in results:
        for item in source_results:
            key = str(item.get('url') or item.get('id') or item.get('title')).strip().lower()
            if not key or key in seen:
                continue
            seen.add(key)
            merged.append(item)
            if len(merged) >= limit * 3:
                break
    return merged[:limit * 3]


# Search wrapper: retain the old cache/contract, but search multiple public
# sources concurrently. Existing callers therefore need no structural changes.
_OLD_MUSIC_SEARCH_ONLINE_PRO_MAX = _music_search_online
async def _music_search_online_pro_max(query: str, limit=MUSIC_SEARCH_LIMIT):
    query = _music_clean_query(query)
    if not query:
        return []
    key = 'multi:' + query.lower()
    cached = MUSIC_SEARCH_CACHE.get(key)
    if cached and _music_time.time() - cached[0] < 120:
        return cached[1]
    result = await _bb_music_multisource_search(query, limit=limit)
    if not result:
        # Fallback to the existing resolver in case a particular yt-dlp build
        # lacks one of the search extractors.
        result = await _OLD_MUSIC_SEARCH_ONLINE_PRO_MAX(query, limit=limit)
    MUSIC_SEARCH_CACHE[key] = (_music_time.time(), result)
    return result

_music_search_online = _music_search_online_pro_max
music_search = _music_search_online_pro_max


async def _bb_music_download_online_unlimited(url: str, audio_only=True):
    """دریافت بدون سقف مصنوعی؛ سقف واقعی ارسال Telegram در مرحله delivery اعمال می‌شود."""
    if _music_yt_dlp is None:
        raise RuntimeError('yt-dlp نصب نیست.')
    url = (url or '').strip()
    if not url:
        raise ValueError('لینک خالی است.')
    folder = _music_Path(_music_tempfile.mkdtemp(prefix='bb_music_', dir=str(MUSIC_TMP_DIR)))
    try:
        def _download():
            opts = _music_ydl_options(audio_only=audio_only, download=True)
            opts['paths'] = {'home': str(folder)}
            opts['outtmpl'] = str(folder / '%(title).100s [%(id)s].%(ext)s')
            opts['continuedl'] = True
            opts['retries'] = 5
            opts['fragment_retries'] = 5
            opts['concurrent_fragment_downloads'] = max(1, int(_music_os.getenv('MUSIC_FRAGMENT_WORKERS', '4')))
            opts['buffersize'] = '16K'
            opts['http_chunk_size'] = 10 * 1024 * 1024
            opts.pop('max_filesize', None)
            with _music_yt_dlp.YoutubeDL(opts) as ydl:
                info = ydl.extract_info(url, download=True)
                path = Path(ydl.prepare_filename(info))
                if not path.exists():
                    candidates = [x for x in folder.glob('*') if x.is_file()]
                    if not candidates:
                        raise FileNotFoundError('فایل دریافت‌شده پیدا نشد.')
                    path = max(candidates, key=lambda x: x.stat().st_mtime)
                return info, path
        info, path = await _music_asyncio.to_thread(_download)
        return info, path, folder
    except Exception:
        import shutil as _bb_shutil
        _bb_shutil.rmtree(folder, ignore_errors=True)
        raise

_music_download_online = _bb_music_download_online_unlimited


def _bb_music_telegram_upload_limit_bytes(bot=None):
    # Local Bot API Server supports up to 2GB uploads; default Bot API supports
    # 50MB multipart uploads. Detect the configured base URL when possible.
    local_url = str(_music_os.getenv('TELEGRAM_LOCAL_BOT_API_URL', '')).strip().lower()
    base_url = str(getattr(bot, 'base_url', '') or getattr(bot, '_base_url', '') or '').lower()
    if local_url or any(host in base_url for host in ('127.0.0.1', 'localhost', '0.0.0.0')):
        return 2 * 1024 * 1024 * 1024
    return 50 * 1024 * 1024


async def _bb_music_send_large_media(chat_id, path, *, title='', is_video=False, is_audio=False, caption='', bot=None):
    """ارسال سریع رسانه با file upload مناسب؛ برای فایل بزرگ از Session شخصی استفاده می‌کند."""
    path = Path(path)
    if not path.exists():
        raise FileNotFoundError('فایل خروجی وجود ندارد.')
    size = path.stat().st_size
    human = _bb_music_human_size(size)
    bot = bot or globals().get('application_bot')

    # Bot API: ordinary upload limit is 50MB; a local Bot API server can go to 2GB.
    if size <= _bb_music_telegram_upload_limit_bytes(bot) and bot is not None:
        with open(path, 'rb') as fh:
            if is_video:
                sent = await bot.send_video(chat_id, video=fh, caption=caption, supports_streaming=True, filename=path.name)
            elif is_audio:
                sent = await bot.send_audio(chat_id, audio=fh, caption=caption, filename=path.name)
            else:
                sent = await bot.send_document(chat_id, document=fh, caption=caption, filename=path.name)
        return sent, human, 'Bot API'

    # Large uploads: use the connected personal Session if available. This is
    # an upload path, not an access-control bypass.
    client = MUSIC_USER_CLIENT
    if client is not None and getattr(client, 'is_connected', False):
        if is_video:
            sent = await client.send_video(chat_id, video=str(path), caption=caption)
        elif is_audio:
            sent = await client.send_audio(chat_id, audio=str(path), caption=caption)
        else:
            sent = await client.send_document(chat_id, document=str(path), caption=caption)
        return sent, human, 'Music Session'

    limit = _bb_music_telegram_upload_limit_bytes(bot)
    raise RuntimeError(
        f'حجم فایل {human} است. برای ارسال فایل‌های بالاتر از {_bb_music_human_size(limit)}، '
        'اکانت Session موزیکال را وصل کن یا Local Bot API Server را فعال کن.'
    )


async def _bb_music_extract_reply_media(update, context):
    """رسانه ریپلای‌شده را از خود Telegram/Session می‌گیرد و برای پخش آماده می‌کند."""
    msg = getattr(update, 'effective_message', None)
    reply = getattr(msg, 'reply_to_message', None) if msg else None
    if not reply:
        return None

    # Identify the richest supported media object.
    media = None
    is_video = False
    is_audio = False
    for attr, video, audio in (
        ('audio', False, True),
        ('voice', False, True),
        ('video', True, False),
        ('document', False, False),
        ('animation', True, False),
        ('video_note', True, False),
    ):
        obj = getattr(reply, attr, None)
        if obj is not None:
            media = obj
            is_video = video
            is_audio = audio
            break
    if media is None:
        return None

    title = (
        getattr(media, 'title', None)
        or getattr(media, 'file_name', None)
        or getattr(reply, 'caption', None)
        or 'رسانه ریپلای‌شده'
    )
    file_id = getattr(media, 'file_id', None)
    file_size = int(getattr(media, 'file_size', 0) or 0)
    thumbnail = None
    thumbs = getattr(media, 'thumbs', None) or []
    if thumbs:
        thumbnail = getattr(thumbs[-1], 'file_id', None)
    if thumbnail is None:
        thumb = getattr(media, 'thumbnail', None)
        thumbnail = getattr(thumb, 'file_id', None) if thumb else None

    # For playback, use the personal Session to download the original message.
    client = MUSIC_USER_CLIENT
    if client is None or not getattr(client, 'is_connected', False):
        raise RuntimeError('برای پخش مستقیم رسانه ریپلای‌شده، اکانت Session موزیکال باید متصل باشد.')
    try:
        pmsg = await client.get_messages(int(msg.chat_id), int(reply.message_id))
        if not pmsg:
            raise RuntimeError('رسانه ریپلای‌شده توسط Session پیدا نشد.')
        folder = _music_Path(_music_tempfile.mkdtemp(prefix='bb_reply_', dir=str(MUSIC_TMP_DIR)))
        local_path = await client.download_media(pmsg, file_name=str(folder / 'media'))
        if not local_path or not Path(local_path).exists():
            raise RuntimeError('دانلود رسانه ریپلای‌شده ناموفق بود.')
        size = Path(local_path).stat().st_size
        return {
            'title': safe_text(str(title), 120),
            'url': str(local_path),
            'local_path': str(local_path),
            '_music_folder': str(folder),
            'is_video': is_video,
            'is_live': False,
            'is_audio': is_audio,
            'thumbnail': thumbnail,
            'telegram_file_id': file_id,
            'telegram_file_size': file_size or size,
            'duration': getattr(media, 'duration', 0) or 0,
        }
    except Exception:
        # If the source is already in Telegram and the bot can access it, the
        # file_id can still be useful for delivery, but playback needs a local
        # source. Keep the original error for the requester.
        raise


async def _bb_music_reply_play_handler(update, context):
    msg = getattr(update, 'effective_message', None)
    chat = getattr(update, 'effective_chat', None)
    user = getattr(update, 'effective_user', None)
    if not msg or not chat or chat.type == 'private' or not user:
        return False
    raw = normalize(getattr(msg, 'text', '') or '')
    if raw not in {
        'پخش این', 'پخش اینو', 'پخش کن', 'پخش رسانه', 'پخش این رسانه',
        'play this', 'play', 'پخش',
    }:
        return False
    if not await _bb_music_can_request(update):
        await msg.reply_text(_bb_music_admin_required_text())
        return True
    if not getattr(msg, 'reply_to_message', None):
        await msg.reply_text('↩️ برای «پخش این» باید روی آهنگ، صدا، فیلم یا فایل رسانه‌ای ریپلای کنی.')
        return True
    try:
        item = await _bb_music_extract_reply_media(update, context)
        if not item:
            await msg.reply_text('❌ رسانه قابل پخش پیدا نشد.')
            return True
        item['requester_id'] = user.id
        item['requester_name'] = user.first_name or 'کاربر'
        item['source'] = 'Telegram Reply'
        started, panel = await _bb_music_start_or_queue(
            chat.id, item, panel_message=None, bot=context.bot, requester_id=user.id
        )
        if panel:
            await _bb_music_start_refresh(chat.id, user.id, panel, bot=context.bot)
        await msg.reply_text(
            f'✅ <b>{safe_text(item.get("title"),120)}</b>\n'
            f'📦 حجم رسانه: <b>{_bb_music_human_size(item.get("telegram_file_size"))}</b>\n'
            f'🎵 {"ویدیو" if item.get("is_video") else "صدا/آهنگ"} برای پخش آماده شد.',
            parse_mode='HTML',
        )
    except Exception as exc:
        await msg.reply_text('❌ پخش رسانه ریپلای‌شده ناموفق بود:\n' + safe_text(str(exc), 700))
    return True


# Local-file playback: inserted before the normal online resolvers.
_OLD_BB_MUSIC_PLAY_NOW_PRO_MAX = _bb_music_play_now_pro
async def _bb_music_play_now_pro_max(chat_id, item):
    local_path = (item or {}).get('local_path')
    if not local_path:
        return await _OLD_BB_MUSIC_PLAY_NOW_PRO_MAX(chat_id, item)

    ok, reason = await _bb_music_lazy_connect_pro()
    if not ok:
        raise RuntimeError(reason)
    ok, reason = await _bb_music_personal_group_check_pro(chat_id)
    if not ok:
        raise RuntimeError(reason)
    if not Path(local_path).exists():
        raise RuntimeError('فایل محلی رسانه دیگر وجود ندارد.')

    is_video = bool(item.get('is_video'))
    try:
        method = await _bb_music_try_play_sources_pro(
            chat_id, str(local_path), is_video=is_video, is_live=False
        )
    except Exception:
        raise

    new_item = dict(item)
    new_item['url'] = str(local_path)
    new_item['source_url'] = str(local_path)
    new_item['backend'] = 'telegram-reply-local'
    new_item['play_method'] = method
    new_item['started_at'] = time.time()
    new_item['position'] = 0
    new_item['paused_at'] = None
    MUSIC_CURRENT[chat_id] = new_item
    return new_item

_bb_music_play_now_pro = _bb_music_play_now_pro_max


# Final download callback: supports audio/video/document and reports the exact size.
async def _bb_music_download_callback_pro_max(update, context):
    q = getattr(update, 'callback_query', None)
    if not q or not str(q.data or '').startswith('mdownload:'):
        return False
    try:
        _, chat_raw, owner_raw = str(q.data).split(':', 2)
        chat_id, owner_id = int(chat_raw), int(owner_raw)
        if q.from_user.id != owner_id:
            await q.answer('🔒 این پنل برای درخواست‌کننده دیگری است.', show_alert=True)
            return True

        state = MUSIC_CURRENT.get(chat_id) or {}
        if not state:
            await q.answer('❌ چیزی برای دریافت وجود ندارد.', show_alert=True)
            return True

        await q.answer('⬇️ در حال آماده‌سازی و محاسبه حجم فایل...')
        bot = getattr(context, 'bot', None)

        # If this track came from a Telegram reply and has a reusable file_id,
        # resend it directly when possible: this is the fastest path.
        file_id = state.get('telegram_file_id')
        if file_id and bot is not None:
            caption = (
                '🎵 <b>' + safe_text(state.get('title') or 'رسانه', 120) + '</b>\n'
                '📦 حجم: <b>' + _bb_music_human_size(state.get('telegram_file_size')) + '</b>'
            )
            try:
                await bot.send_document(chat_id, document=file_id, caption=caption, parse_mode='HTML')
                return True
            except Exception:
                pass

        path = state.get('_music_path') or state.get('local_path')
        folder = state.get('_music_folder')
        temp_folder = None
        if not path or not Path(str(path)).exists():
            info, path_obj, folder_obj = await _music_download_online(
                state.get('url') or state.get('source_url'),
                audio_only=not bool(state.get('is_video')),
            )
            path = str(path_obj)
            temp_folder = str(folder_obj)
        path = Path(path)
        size = path.stat().st_size
        caption = (
            '🎵 <b>' + safe_text(state.get('title') or 'رسانه', 120) + '</b>\n'
            '📦 حجم فایل: <b>' + _bb_music_human_size(size) + '</b>\n'
            '⚡ آماده‌سازی با بیشترین سرعت ممکن'
        )
        sent, human, route = await _bb_music_send_large_media(
            chat_id,
            path,
            title=state.get('title') or '',
            is_video=bool(state.get('is_video')),
            is_audio=not bool(state.get('is_video')) and not bool(state.get('is_live')),
            caption=caption,
            bot=bot,
        )
        await q.answer(f'✅ فایل {human} تحویل شد.')
        return True
    except Exception as exc:
        log.exception('music max download failed: %s', exc)
        try:
            await q.message.reply_text('❌ دریافت فایل انجام نشد:\n' + safe_text(str(exc), 900))
        except Exception:
            try:
                await context.bot.send_message(chat_id, '❌ دریافت فایل انجام نشد:\n' + safe_text(str(exc), 900))
            except Exception:
                pass
        return True

_bb_music_download_callback_final = _bb_music_download_callback_pro_max


# Special-player-aware final music router. Admins keep the complete existing
# music router; special players get only playback requests, as requested.
_OLD_BB_MUSIC_MESSAGE_ROUTER_MAX = _bb_music_message_router_final
async def _bb_music_message_router_final_max(update, context):
    if await _bb_music_special_player_text(update):
        return True
    if await _bb_music_reply_play_handler(update, context):
        return True

    chat = getattr(update, 'effective_chat', None)
    user = getattr(update, 'effective_user', None)
    msg = getattr(update, 'effective_message', None)
    if not chat or not user or chat.type == 'private':
        return await _OLD_BB_MUSIC_MESSAGE_ROUTER_MAX(update, context)

    if await _bb_music_group_admin(update, user.id):
        return await _OLD_BB_MUSIC_MESSAGE_ROUTER_MAX(update, context)

    if not await _bb_music_is_special_player(chat.id, user.id):
        # Preserve unrelated commands for the rest of Bil Bilak.
        return await _OLD_BB_MUSIC_MESSAGE_ROUTER_MAX(update, context)

    # Keep the existing per-group VIP/music switch semantics for special players.
    try:
        if not await active_vip(chat.id):
            await msg.reply_text('💎 قابلیت موزیکال فقط در گروه VIP فعال است.')
            return True
        if not await vip_feature(chat.id, 'music'):
            await msg.reply_text('🔴 موزیکال برای این گروه توسط مالک خاموش شده است.')
            return True
    except Exception:
        pass

    raw = (getattr(msg, 'text', '') or '').strip()
    m = re.match(
        r'^(?:پخش آهنگ|play song|پخش فیلم|پخش سریال|رادیو|ریمیکس|پخش فوتبال|پخش لایو|لایو|live)\s+(.+)$',
        raw, re.I,
    )
    if not m:
        # Special player is intentionally NOT allowed to control queue/volume/stop.
        return False

    query = _music_clean_query(m.group(1))
    kind = 'video' if re.match(r'^پخش (?:فیلم|سریال)\b', raw, re.I) else 'audio'
    suffix = ''
    low = normalize(raw)
    if low.startswith('پخش فوتبال '):
        suffix = ' football live'
    elif low.startswith(('پخش لایو ', 'لایو ', 'live ')):
        suffix = ' live stream'
    elif low.startswith('رادیو '):
        suffix = ' live radio'
    elif low.startswith('ریمیکس '):
        suffix = ' remix'

    # Direct public URL: stream/download through the existing resolver chain.
    if _valid_public_url(query):
        item = {
            'title': 'Media Stream',
            'url': query,
            'is_video': kind == 'video',
            'is_live': ('live' in low or low.startswith('رادیو ')),
            'requester_id': user.id,
            'requester_name': user.first_name or 'ویژه‌پلیر',
            'duration': 0,
            'thumbnail': None,
        }
        try:
            await _bb_music_start_or_queue(chat.id, item, panel_message=None, bot=context.bot, requester_id=user.id)
            await msg.reply_text('📡 درخواست ویژه‌پلیر برای پخش ثبت شد.')
        except Exception as exc:
            await msg.reply_text('❌ پخش ناموفق بود:\n' + safe_text(str(exc), 700))
        return True

    results = await _bb_music_multisource_search(query + suffix, limit=MUSIC_SEARCH_LIMIT, video=(kind == 'video'))
    if not results:
        await msg.reply_text('❌ از منابع عمومی قابل دسترس نتیجه‌ای پیدا نشد.')
        return True

    MUSIC_SEARCH_CACHE[f'{chat.id}:last'] = results
    BB_MUSIC_SEARCH_MODE[chat.id] = kind
    rows = []
    for i, item in enumerate(results[:10], 1):
        source = safe_text(item.get('source') or 'منبع عمومی', 20)
        rows.append([btn(
            f'🎵 {i}. {safe_text(item.get("title") or "بدون عنوان", 42)} • {source}',
            f'mplay:{chat.id}:{user.id}:{i}',
        )])
    rows.append([btn('🔄 جستجوی دوباره', f'msearch:{chat.id}:{user.id}')])
    await msg.reply_text(
        '⭐ <b>درخواست ویژه‌پلیر</b>\n━━━━━━━━━━━━━━━━━━\n'
        f'🔎 {safe_text(query,100)}\n\n'
        'نتایج از چند منبع عمومی جمع‌آوری شده‌اند؛ یکی را انتخاب کن.',
        parse_mode='HTML', reply_markup=keyboard(rows),
    )
    return True

_bb_music_message_router_final = _bb_music_message_router_final_max


# Final callback dispatcher: include the expanded download callback and keep the
# original playback controls untouched.
async def _bb_final_music_callback_dispatch_max(update, context):
    for fn in (
        _bb_music_live_callback_final,
        _bb_music_live_result_callback_final,
        _bb_music_result_callback_final,
        _bb_music_download_callback_pro_max,
        _bb_music_control_callback_final,
    ):
        try:
            if await fn(update, context):
                return True
        except Exception as exc:
            log.exception('music max callback layer: %s', exc)
            q = getattr(update, 'callback_query', None)
            try:
                if q:
                    await q.answer('⚠️ عملیات موزیکال انجام نشد.', show_alert=True)
            except Exception:
                pass
            return True
    return False

_bb_final_music_callback_dispatch = _bb_final_music_callback_dispatch_max


# Absolute callback dispatcher must also recognize mdownload:.
async def _bilbilak_music_absolute_callback_max(update, context):
    q = getattr(update, 'callback_query', None)
    if not q:
        return False
    data = str(q.data or '')
    if not (
        data.startswith('mplay:')
        or data.startswith('livepick:')
        or data.startswith('mctrl:')
        or data.startswith('msearch:')
        or data.startswith('mdownload:')
    ):
        return False
    try:
        handled = bool(await _bb_final_music_callback_dispatch(update, context))
        if handled:
            raise ApplicationHandlerStop
        return False
    except ApplicationHandlerStop:
        raise
    except Exception as exc:
        log.exception('ABSOLUTE MUSIC MAX CALLBACK ERROR: %s', exc)
        try:
            await q.answer('⚠️ اجرای عملیات موزیکال ناموفق بود.', show_alert=True)
        except Exception:
            pass
        return True

_bilbilak_music_absolute_callback = _bilbilak_music_absolute_callback_max

# Final build wrapper: no new handlers are registered here; the existing final
