# =============================================================================
# BILBILAK — MUSIC PERSONAL ACCOUNT VOICE-CALL PRESENCE TRACKER
# =============================================================================
# The same personal Telegram account used by PyTgCalls also receives MTProto
# group-call participant updates.  This layer records real participant time;
# it does not fabricate presence from Bot API messages.

_BB_VC_TRACK_READY = False
_BB_VC_RAW_HANDLER_CLIENTS = set()
_BB_VC_CALLS = {}          # call_id -> {chat_id, access_hash, ...}
_BB_VC_ACTIVE = {}         # (chat_id, user_id) -> start_epoch
_BB_VC_LOCK = asyncio.Lock()

async def _bb_vc_tracker_schema():
    await DBX.execute("""
        CREATE TABLE IF NOT EXISTS bb_call_active(
            chat_id INTEGER NOT NULL,
            user_id INTEGER NOT NULL,
            started_at INTEGER NOT NULL,
            PRIMARY KEY(chat_id,user_id)
        )
    """)
    await DBX.execute("CREATE INDEX IF NOT EXISTS idx_bb_call_active_chat ON bb_call_active(chat_id)")


def _bb_vc_tehran():
    try:
        from zoneinfo import ZoneInfo
        return ZoneInfo('Asia/Tehran')
    except Exception:
        return timezone(timedelta(hours=3, minutes=30))


def _bb_vc_day_from_epoch(ts):
    return datetime.fromtimestamp(float(ts), tz=_bb_vc_tehran()).strftime('%Y-%m-%d')


async def _bb_vc_add_seconds(chat_id, user_id, start_ts, end_ts):
    """Split one interval at Tehran midnight and persist it exactly once."""
    start_ts = int(start_ts or 0)
    end_ts = int(end_ts or 0)
    if end_ts <= start_ts:
        return
    tz = _bb_vc_tehran()
    cur = datetime.fromtimestamp(start_ts, tz=tz)
    end = datetime.fromtimestamp(end_ts, tz=tz)
    while cur < end:
        next_midnight = datetime.combine(cur.date() + timedelta(days=1), datetime.min.time(), tzinfo=tz)
        stop = min(end, next_midnight)
        seconds = max(0, int((stop - cur).total_seconds()))
        if seconds:
            day = cur.strftime('%Y-%m-%d')
            # Keep the member visible to the stats JOIN even when their only
            # activity so far has been Voice Chat presence.
            await DBX.execute(
                "INSERT OR IGNORE INTO chat_member_stats(chat_id,user_id,username,first_seen,last_seen,is_bot,messages,adds) "
                "VALUES(?,?,?,?,?,?,0,0)",
                (int(chat_id), int(user_id), '', now_ts(), now_ts(), 0)
            )
            await DBX.execute(
                "UPDATE chat_member_stats SET last_seen=? WHERE chat_id=? AND user_id=?",
                (now_ts(), int(chat_id), int(user_id))
            )
            await DBX.execute(
                "INSERT INTO bb_call_presence(chat_id,user_id,day,seconds) VALUES(?,?,?,?) "
                "ON CONFLICT(chat_id,user_id,day) DO UPDATE SET seconds=seconds+excluded.seconds",
                (int(chat_id), int(user_id), day, seconds)
            )
        cur = stop


async def _bb_vc_flush_active(chat_id=None, user_id=None, now_epoch=None):
    """Accrue currently-open sessions without closing them."""
    await _bb_vc_tracker_schema()
    now_epoch = int(now_epoch or time.time())
    rows = await DBX.execute(
        "SELECT chat_id,user_id,started_at FROM bb_call_active "
        + ("WHERE chat_id=? AND user_id=?" if chat_id is not None and user_id is not None else
           "WHERE chat_id=?" if chat_id is not None else ""),
        ((int(chat_id), int(user_id)) if chat_id is not None and user_id is not None else
         (int(chat_id),) if chat_id is not None else ()),
        fetch=True
    )
    for row in rows or []:
        cid, uid, started = int(row['chat_id']), int(row['user_id']), int(row['started_at'])
        if now_epoch > started:
            await _bb_vc_add_seconds(cid, uid, started, now_epoch)
            await DBX.execute(
                "UPDATE bb_call_active SET started_at=? WHERE chat_id=? AND user_id=?",
                (now_epoch, cid, uid)
            )


async def _bb_vc_start_participant(chat_id, user_id, joined_at=None, username='', first_name=''):
    await _bb_vc_tracker_schema()
    cid, uid = int(chat_id), int(user_id)
    started = int(joined_at or time.time())
    if started > int(time.time()) + 10:
        started = int(time.time())
    # Seed/update the normal member stats row so Top-10 JOINs work.
    await DBX.execute(
        "INSERT OR IGNORE INTO chat_member_stats(chat_id,user_id,username,first_name,first_seen,last_seen,is_bot,messages,adds) "
        "VALUES(?,?,?,?,?,?,0,0,0)",
        (cid, uid, username or '', first_name or '', now_ts(), now_ts())
    )
    if username or first_name:
        await DBX.execute(
            "UPDATE chat_member_stats SET username=?,first_name=?,last_seen=? WHERE chat_id=? AND user_id=?",
            (username or '', first_name or '', now_ts(), cid, uid)
        )
    old = await DBX.execute(
        "SELECT started_at FROM bb_call_active WHERE chat_id=? AND user_id=?",
        (cid, uid), fetch=True
    )
    if old:
        old_start = int(old[0]['started_at'])
        # A re-join/update must not double-count the same open interval.
        if abs(old_start - started) <= 5:
            return
        await _bb_vc_flush_active(cid, uid)
    await DBX.execute(
        "INSERT INTO bb_call_active(chat_id,user_id,started_at) VALUES(?,?,?) "
        "ON CONFLICT(chat_id,user_id) DO UPDATE SET started_at=excluded.started_at",
        (cid, uid, started)
    )
    _BB_VC_ACTIVE[(cid, uid)] = started


async def _bb_vc_stop_participant(chat_id, user_id, left_at=None):
    await _bb_vc_tracker_schema()
    cid, uid = int(chat_id), int(user_id)
    row = await DBX.execute(
        "SELECT started_at FROM bb_call_active WHERE chat_id=? AND user_id=?",
        (cid, uid), fetch=True
    )
    if not row:
        _BB_VC_ACTIVE.pop((cid, uid), None)
        return
    started = int(row[0]['started_at'])
    ended = int(left_at or time.time())
    if ended > started:
        await _bb_vc_add_seconds(cid, uid, started, ended)
    await DBX.execute("DELETE FROM bb_call_active WHERE chat_id=? AND user_id=?", (cid, uid))
    _BB_VC_ACTIVE.pop((cid, uid), None)


def _bb_vc_peer_user_id(peer):
    if peer is None:
        return None
    for attr in ('user_id', 'id'):
        value = getattr(peer, attr, None)
        if value is not None:
            try:
                return int(value)
            except Exception:
                pass
    return None


async def _bb_vc_raw_update(client, update, users, chats):
    try:
        cname = update.__class__.__name__
        if cname == 'UpdateGroupCall':
            call = getattr(update, 'call', None)
            chat_id = getattr(update, 'chat_id', None)
            if call is not None and chat_id is not None:
                _BB_VC_CALLS[int(getattr(call, 'id', 0) or 0)] = {
                    'chat_id': int(chat_id),
                    'access_hash': int(getattr(call, 'access_hash', 0) or 0),
                    'call': call,
                }
            return

        if cname != 'UpdateGroupCallParticipants':
            return
        call = getattr(update, 'call', None)
        call_id = int(getattr(call, 'id', 0) or 0)
        info = _BB_VC_CALLS.get(call_id)
        if not info:
            return
        chat_id = int(info['chat_id'])
        participants = getattr(update, 'participants', None) or []
        for part in participants:
            uid = _bb_vc_peer_user_id(getattr(part, 'peer', None))
            if uid is None:
                continue
            u = (users or {}).get(uid)
            username = getattr(u, 'username', '') if u else ''
            first_name = getattr(u, 'first_name', '') if u else ''
            is_left = bool(getattr(part, 'left', False))
            joined_at = int(getattr(part, 'date', 0) or 0) or int(time.time())
            if is_left:
                await _bb_vc_stop_participant(chat_id, uid, int(time.time()))
            else:
                await _bb_vc_start_participant(chat_id, uid, joined_at, username, first_name)
    except Exception as exc:
        log.warning('voice presence tracker raw update failed: %r', exc)


async def _bb_vc_install_tracker(client):
    global _BB_VC_TRACK_READY
    if client is None:
        return False
    key = id(client)
    if key in _BB_VC_RAW_HANDLER_CLIENTS:
        return True
    try:
        from pyrogram.handlers import RawUpdateHandler
        await _bb_vc_tracker_schema()
        client.add_handler(RawUpdateHandler(_bb_vc_raw_update), group=9999)
        _BB_VC_RAW_HANDLER_CLIENTS.add(key)
        _BB_VC_TRACK_READY = True
        log.info('Bil Bilak voice presence tracker attached to music personal account.')
        return True
    except Exception as exc:
        log.warning('Could not attach voice presence tracker: %r', exc)
        return False


# Wrap the existing personal-account startup path.  No second Telegram account
# or second Session is created; the existing MUSIC_USER_CLIENT is reused.
_BB_OLD_MUSIC_START_EXISTING_FOR_VC = _bb_music_user_start_existing
async def _bb_music_user_start_existing_with_vc_tracker(*args, **kwargs):
    result = await _BB_OLD_MUSIC_START_EXISTING_FOR_VC(*args, **kwargs)
    try:
        if MUSIC_USER_CLIENT is not None and getattr(MUSIC_USER_CLIENT, 'is_connected', False):
            await _bb_vc_install_tracker(MUSIC_USER_CLIENT)
    except Exception as exc:
        log.warning('voice presence tracker startup hook failed: %r', exc)
    return result
_bb_music_user_start_existing = _bb_music_user_start_existing_with_vc_tracker


# Flush live participants whenever the stats panel/report is generated, so the
# currently-running call is included even before Telegram emits a leave event.
_BB_OLD_STATS_DETAIL_FOR_VC = _bb_stats_detail_text
