def _bb_premium_icon_id(text):
    t = str(text or '').strip().lower()
    for key, emoji_id in _BB_PREMIUM_EMOJI_IDS.items():
        if key in t:
            return emoji_id
    return _BB_PREMIUM_DEFAULT_ID


def _bb_premium_clean_button_text(text):
    t = str(text or '').strip()
    # Remove the old Unicode decoration we added in the previous visual layer;
    # Telegram now renders the premium custom emoji as the actual button icon.
    for prefix in ('🐾  ', '✨  ', '↩️  ', '✕  ', '✖️  ', '🗑️  ', '🧹  ', '🚫  ',
                   '⚙️  ', '🔑  ', '💾  ', '🟢  ', '🔴  ', '➕  ', '👥  ',
                   '👤  ', '💬  ', '📊  ', '☀️  ', '📅  ', '🗓️  ', '🎙️  ',
                   '🎵  ', '▶️  ', '⏹️  ', '⏸️  ', '⏭️  ', '⏮️  ', '📋  ',
                   '🔊  ', '📥  ', '🎬  ', '📺  ', '🎧  ', '🌍  ', 'ℹ️  ',
                   '🌤️  ', '💱  ', '🏆  ', '🔎  ', '❓  ', '📖  ', '🛡️  ',
                   '🔐  ', '🔒  ', '🚪  ', '✅  ', '❌  ', '📂  ', '👤  ',
                   '🎮  ', '🔮  ', '🤲  ', '🪪  '):
        if t.startswith(prefix):
            t = t[len(prefix):].strip()
            break
    # Remove the older trailing sparkle marker if present.
    if t.endswith('  ✦'):
        t = t[:-3].rstrip()
    return t


# Replace the previous visual button wrapper with a real custom-emoji icon
# field. This is supported by Bot API 9.4+ and recent python-telegram-bot.
def btn(text, data=None, url=None, style=None):
    chosen = style or _button_style(text, data)
    label = _bb_premium_clean_button_text(text)
    kwargs = {
        'text': label,
        'callback_data': data,
        'url': url,
        'style': chosen,
        'icon_custom_emoji_id': _bb_premium_icon_id(label),
    }
    try:
        return InlineKeyboardButton(**kwargs)
    except TypeError:
        # Compatibility fallback for an older PTB build: keep colored button
        # and text rather than breaking the bot at import/runtime.
        kwargs.pop('icon_custom_emoji_id', None)
        return InlineKeyboardButton(**kwargs)


def reply_btn(text, request_location=False, style=None):
    chosen = style or _button_style(text)
    label = _bb_premium_clean_button_text(text)
    kwargs = {
        'text': label,
        'request_location': request_location,
        'style': chosen,
        'icon_custom_emoji_id': _bb_premium_icon_id(label),
    }
    try:
        return KeyboardButton(**kwargs)
    except TypeError:
        kwargs.pop('icon_custom_emoji_id', None)
        return KeyboardButton(**kwargs)


# =============================================================================
# PREMIUM MESSAGE EMOJI HELPERS
# =============================================================================
# Custom emoji inside ordinary message text must be represented as a
# MessageEntity/HTML tg-emoji entity; a bot token cannot simply turn Unicode
# characters into Premium emoji. Keep the existing tiny-message Unicode polish,
# while exposing a helper for places that explicitly want a real custom emoji.

def bb_premium_emoji(emoji='🐕', emoji_id=None):
    """Safe message fallback for environments that reject <tg-emoji> HTML.

    Custom emoji IDs are still stored/used by the UI system and button icons.
    For ordinary message bodies, return the Unicode fallback instead of
    emitting unsupported HTML markup.
    """
    return str(emoji or '🐕')

