# Rebuild skip/previous around the restored play_item so queue navigation also
# uses exactly the same stable playback engine.
async def _bb_music_skip_restored(chat_id):
    current = MUSIC_CURRENT.pop(chat_id, None)
    if current:
        MUSIC_HISTORY.setdefault(chat_id, []).append(dict(current))
        MUSIC_HISTORY[chat_id] = MUSIC_HISTORY[chat_id][-30:]
        try:
            _bb_music_cleanup_local_state(current)
        except Exception:
            pass
    queue = MUSIC_QUEUE.get(chat_id) or []
    while queue:
        item = queue.pop(0)
        try:
            return await _bb_music_play_item_pro(chat_id, item)
        except Exception as exc:
            log.warning('restored queued item failed: %s', exc)
    return None

async def _bb_music_prev_restored(chat_id):
    hist = MUSIC_HISTORY.get(chat_id) or []
    if not hist:
        return None
    current = MUSIC_CURRENT.pop(chat_id, None)
    if current:
        try:
            _bb_music_cleanup_local_state(current)
        except Exception:
            pass
        MUSIC_QUEUE.setdefault(chat_id, []).insert(0, current)
    item = hist.pop()
    try:
        return await _bb_music_play_item_pro(chat_id, item)
    except Exception as exc:
        log.warning('restored previous item failed: %s', exc)
        return None

_bb_music_skip_pro = _bb_music_skip_restored
_bb_music_prev_pro = _bb_music_prev_restored
_bb_music_skip = _bb_music_skip_restored
_bb_music_prev = _bb_music_prev_restored


