# ------------------------- Unicode cleanup + premium alphanumerics -------------------------
_BB_EMOJI_RE=re.compile('[\\U0001F000-\\U0001FAFF\\U00002600-\\U000027BF\\U0001F1E6-\\U0001F1FF\\u200d\\ufe0f]')
def _bb_strip_unicode_emoji(s):
    return _BB_EMOJI_RE.sub('',str(s or ''))

def _bb_html_px(ch, eid):
    return f'<tg-emoji emoji-id="{eid}">{ch}</tg-emoji>'

def _bb_premiumize_alnum_html(text):
    # Do not transform code blocks, URLs, Telegram IDs or technical values.
    parts=re.split(r'(<code>.*?</code>|https?://[^\s<>]+|tg://[^\s<>]+)',str(text or ''),flags=re.S|re.I)
    out=[]
    for part in parts:
        if not part:continue
        if part.startswith('<code>') or re.match(r'^(?:https?://|tg://)',part,re.I):out.append(part);continue
        chars=[]
        for ch in part:
            if 'A'<=ch<='Z' or 'a'<=ch<='z':
                idx=ord(ch.upper())-65; chars.append(_bb_html_px(ch,_BB_PX['AtoZ'][idx]))
            elif ch.isdigit(): chars.append(_bb_html_px(ch,_BB_PX['digits'][int(ch)]))
            else: chars.append(ch)
        out.append(''.join(chars))
    return ''.join(out)

def _bb_premium_message(text):
    if text is None:return text
    t=str(text)
    # IMPORTANT: never inject <tg-emoji> markup into ordinary message text.
    # The installed Telegram Bot API/PTB environment rejects that tag and
    # raises: "unsupported start tag <tg-emoji>". Custom emoji IDs remain
    # available for button icons and owner configuration; ordinary messages
    # use safe Unicode text instead.
    # Preserve all existing message emoji and HTML markup.
    t=re.sub(r'@Bil_bilakapibot\b','',t,flags=re.I)
    return t.strip()

# Final button constructor: no Unicode emoji in labels; real Premium icon on the side.
def btn(text,data=None,url=None,style=None):
    label=_bb_strip_unicode_emoji(str(text or '').strip())
    label=re.sub(r'\s{2,}',' ',label).strip()
    chosen=style or _button_style(label,data)
    eid=_bb_px_for_label(label)
    kwargs={'text':label,'callback_data':data,'url':url,'style':chosen}
    if eid:kwargs['icon_custom_emoji_id']=eid
    try:return InlineKeyboardButton(**kwargs)
    except TypeError:
        kwargs.pop('icon_custom_emoji_id',None); return InlineKeyboardButton(**kwargs)

def reply_btn(text,request_location=False,style=None):
    label=_bb_strip_unicode_emoji(str(text or '').strip()); label=re.sub(r'\s{2,}',' ',label).strip()
    chosen=style or _button_style(label); eid=_bb_px_for_label(label)
    kwargs={'text':label,'request_location':request_location,'style':chosen}
    if eid:kwargs['icon_custom_emoji_id']=eid
    try:return KeyboardButton(**kwargs)
    except TypeError:
        kwargs.pop('icon_custom_emoji_id',None); return KeyboardButton(**kwargs)

# Patch the main text send/edit methods so legacy messages also use the catalog.
def _bb_patch_method(cls,name,text_positions=(1,),kw='text'):
    old=getattr(cls,name,None)
    if not old:return
    async def wrapper(self,*args,**kwargs):
        if kw in kwargs and isinstance(kwargs[kw],str):kwargs[kw]=_bb_premium_message(kwargs[kw])
        elif args:
            a=list(args)
            for pos in text_positions:
                if len(a)>pos and isinstance(a[pos],str):a[pos]=_bb_premium_message(a[pos])
            args=tuple(a)
        return await old(self,*args,**kwargs)
    setattr(cls,name,wrapper)

try:
    _bb_patch_method(telegram.Message,'reply_text',(1,),'text')
    _bb_patch_method(telegram.Message,'reply_html',(1,),'text')
    _bb_patch_method(telegram.Message,'edit_text',(1,),'text')
    _bb_patch_method(telegram.Message,'edit_caption',(1,),'caption')
    _bb_patch_method(telegram.Bot,'send_message',(1,),'text')
    _bb_patch_method(telegram.Bot,'edit_message_text',(2,),'text')
    _bb_patch_method(telegram.Bot,'edit_message_caption',(2,),'caption')
except Exception as _bb_visual_patch_exc:
    log.warning('premium message patch: %r',_bb_visual_patch_exc)


