# ------------------------- dynamic bot username -------------------------
BB_BOT_USERNAME=''
async def _bb_runtime_bot_username(bot):
    global BB_BOT_USERNAME
    if BB_BOT_USERNAME:return BB_BOT_USERNAME
    try:
        me=await bot.get_me()
        BB_BOT_USERNAME=str(getattr(me,'username','') or '').lstrip('@')
    except Exception as exc:log.warning('could not resolve runtime bot username: %s',exc)
    return BB_BOT_USERNAME

# ------------------------- robust PV API/phone/session input -------------------------
_BB_API_VALIDATORS={
    'TELEGRAM_API_ID':lambda v: bool(re.fullmatch(r'\d{5,12}',v)),
    'TELEGRAM_API_HASH':lambda v: bool(re.fullmatch(r'[0-9a-fA-F]{20,64}',v)),
    'MUSIC_USER_PHONE':lambda v: bool(re.fullmatch(r'\+?[0-9]{7,20}',v.replace(' ','').replace('-',''))),
    'MUSIC_USER_SESSION':lambda v: bool(v and len(v)<=300),
}
async def _bb_final_config_text_verified(update,context):
    msg=getattr(update,'effective_message',None); user=getattr(update,'effective_user',None); chat=getattr(update,'effective_chat',None)
    if not msg or not user or not chat or chat.type!='private' or not getattr(msg,'text',None):return False
    if not await _bb_is_bot_admin(user.id):return False
    key=BB_CONFIG_PENDING.get(user.id)
    # Legacy owner panels have their own pending state; let their dedicated
    # handler handle those messages.
    if not key:return False
    raw=str(msg.text).strip()
    if normalize(raw) in {'پاک','حذف','delete','clear'}:
        value=''
    else:
        value=raw
    validator=_BB_API_VALIDATORS.get(key)
    if validator and value and not validator(value):
        await msg.reply_text('مقدار واردشده معتبر نیست؛ فرمت را اصلاح کن و دوباره بفرست.')
        return True
    if key=='MUSIC_USER_PHONE' and value:value=value.replace(' ','').replace('-','')
    try:
        await _bb_pro_set(key,value)
        if value:os.environ[key]=value
        else:os.environ.pop(key,None)
        BB_CONFIG_PENDING.pop(user.id,None)
        # Keep the runtime music globals synchronized.
        global TELEGRAM_API_ID,TELEGRAM_API_HASH,MUSIC_USER_PHONE
        if key=='TELEGRAM_API_ID':TELEGRAM_API_ID=int(value or 0)
        elif key=='TELEGRAM_API_HASH':TELEGRAM_API_HASH=value
        elif key=='MUSIC_USER_PHONE':MUSIC_USER_PHONE=value
        await msg.reply_text('تنظیم با موفقیت اعتبارسنجی و در SQLite ذخیره شد.')
    except Exception as exc:
        await msg.reply_text('ذخیره تنظیم انجام نشد. '+safe_text(str(exc),300))
    return True

