# ------------------------- currency quantities + global fallback -------------------------
# Users can now write bare amounts such as «10 دلار», «۲۵ یورو», «100 USD»
# or «دلار 10».  NetArz is preferred for Iranian free-market prices; when a
# currency is not present there, the configured REST Countries Currencies API
# is used as a global FX fallback.
_BB_CURRENCY_ALIASES_EXTRA={'تون':'TON','تن':'TON','ton':'TON','تتر':'USDT','usdt':'USDT','دلار':'USD','یورو':'EUR','پوند':'GBP'}
_BB_OLD_CURRENCY_ONE=_bb_currency_one

def _bb_digits_to_ascii(value):
    table=str.maketrans('۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩','01234567890123456789')
    return str(value or '').translate(table).replace('٫','.').replace('٬',',')

def _bb_currency_amount_parse(query):
    raw=normalize(query)
    raw=_bb_digits_to_ascii(raw)
    # Supports both simple input and explicit targets, e.g.
    # «16 دلار»، «دلار 16»، «16 دلار به تومان»، «16 دلار به تومن و دلار».
    word=r'[\u0600-\u06ffA-Za-z][\u0600-\u06ffA-Za-z0-9_-]{1,20}'
    m=re.fullmatch(r'([0-9]+(?:[.,][0-9]+)?)\s*('+word+r')(?:\s+به\s+.*)?',raw)
    if m:
        return float(m.group(1).replace(',','.')),m.group(2)
    # currency first: دلار 16 / USD 16 / دلار 16 به تومان
    m=re.fullmatch(r'('+word+r')\s*([0-9]+(?:[.,][0-9]+)?)(?:\s+به\s+.*)?',raw)
    if m:
        return float(m.group(2).replace(',','.')),m.group(1)
    return None,None

async def _bb_currency_global_convert(code,amount):
    """Fallback converter for currencies outside the Iranian-market feed."""
    key=await _bb_pro_get('RESTCOUNTRIES_API_KEY',os.getenv('RESTCOUNTRIES_API_KEY',''))
    if not key:return None,None
    try:
        st,data,_=await _bb_http_get_json(
            'https://api.restcountries.com/currencies/v1/convert',
            headers={'Authorization':'Bearer '+key,'Accept':'application/json'},
            params={'from':str(code).upper(),'to':'IRR','amount':str(amount)},
            timeout=20
        )
        obj=((data or {}).get('data') or {}).get('objects') if isinstance(data,dict) else None
        obj=(obj or [None])[0]
        if st==200 and isinstance(obj,dict) and obj.get('result') is not None:
            return float(obj.get('result')),obj.get('as_of')
    except Exception as exc:
        log.warning('global currency conversion failed: %s',exc)
    return None,None

def _bb_currency_mid_irr(row):
    unit=max(1,float(row.get('unit') or 1))
    return float(row.get('mid') or ((float(row.get('buy'))+float(row.get('sell')))/2))*10/unit

async def _bb_currency_quantity(query):
    qty,name=_bb_currency_amount_parse(query)
    if qty is None:return None
    if qty < 0:return '❌ مبلغ ارز نمی‌تواند منفی باشد.'
    normalized_name=normalize(name)
    code=_BB_CURRENCY_ALIASES_EXTRA.get(name.lower(),_BB_CURRENCY_ALIASES_EXTRA.get(normalized_name)) or await _bb_currency_code(name)
    if not code:return None

    # تومان/ریال را هم به‌عنوان ورودی واقعی پشتیبانی کن.
    if normalized_name in {'تومان','تومن'}:
        toman=qty
        irr=qty*10
        data=await _bb_currency_rates()
        usd_toman=None
        if data:
            usdrow=_bb_currency_rows(data).get('USD')
            if usdrow:
                try: usd_toman=float(usdrow.get('mid') or ((float(usdrow.get('buy'))+float(usdrow.get('sell')))/2))/max(1,float(usdrow.get('unit') or 1))
                except Exception: usd_toman=None
        usd=(toman/usd_toman) if usd_toman else None
        extra=f'💵 معادل دلار: <b>{usd:,.2f}</b> USD\n' if usd is not None else ''
        return (f'💱 <b>{qty:g} تومان</b>\n\n'
                f'💰 تومان: <b>{toman:,.0f}</b>\n'
                f'🇮🇷 ریال: <b>{irr:,.0f}</b>\n'
                f'{extra}'
                '━━━━━━━━━━━━━━\n'
                'ℹ️ معادل دلار با نرخ فعلی ارز محاسبه شده است.')

    data=await _bb_currency_rates()
    if not data:
        return '⚠️ <b>API ارز در دسترس نیست.</b>\n\nکلید <b>NETARZ_API_KEY</b> را در پنل API تنظیم کن.'
    rows=_bb_currency_rows(data)
    row=rows.get(code)
    if not row:
        return f'❌ نرخ <b>{_bb_h(code)}</b> در API فعلی موجود نیست.'

    try:
        unit=max(1,float(row.get('unit') or 1))
        mid=float(row.get('mid') or ((float(row.get('buy'))+float(row.get('sell')))/2))
        source_toman_rate=mid/unit
        toman=qty*source_toman_rate
        irr=toman*10
    except Exception:
        return f'❌ نرخ <b>{_bb_h(code)}</b> قابل محاسبه نیست.'

    # دلار مقصد از همان فید NetArz محاسبه می‌شود؛ بنابراین مثلاً
    # «16 یورو به تومان و دلار» هر دو نتیجه را از یک نرخ لحظه‌ای می‌گیرد.
    usd=None
    usdrow=rows.get('USD')
    if usdrow:
        try:
            usd_mid=float(usdrow.get('mid') or ((float(usdrow.get('buy'))+float(usdrow.get('sell')))/2))
            usd_toman_rate=usd_mid/max(1,float(usdrow.get('unit') or 1))
            if usd_toman_rate>0: usd=toman/usd_toman_rate
        except Exception:
            usd=None

    flag=BB_CURRENCY_SYMBOLS.get(code,'💱')
    usd_line=f'💵 دلار: <b>{usd:,.2f}</b> USD\n' if usd is not None else ''
    source_display=code
    return (f'{flag} <b>{qty:g} {source_display}</b>\n\n'
            f'╭───────────────╮\n'
            f'│ 💱 <b>تبدیل مبلغ</b>\n'
            f'│ {source_display}: <b>{qty:g}</b>\n'
            f'│ 💰 تومان: <b>{toman:,.0f}</b> تومان\n'
            f'│ 🇮🇷 ریال: <b>{irr:,.0f}</b> ریال\n'
            f'│ {usd_line.rstrip()}\n'
            f'╰───────────────╯\n\n'
            f'🕐 منبع نرخ: <b>NetArz</b>\n'
            'ℹ️ تومان و دلار بر اساس نرخ جاری API محاسبه شده‌اند.')

async def _bb_currency_one_final(raw):
    q=normalize(raw)
    quantity=await _bb_currency_quantity(q)
    if quantity is not None:return quantity
    # Plain code/name keeps the existing detailed rate output.
    code=_BB_CURRENCY_ALIASES_EXTRA.get(q) or _BB_CURRENCY_ALIASES_EXTRA.get(q.upper())
    return await _BB_OLD_CURRENCY_ONE(code or raw)
_bb_currency_one=_bb_currency_one_final

async def _bb_currency_quantity_message(update,context):
    """Handle bare user messages like «10 دلار» before legacy routers."""
    msg=getattr(update,'effective_message',None)
    if not msg or not getattr(msg,'text',None):return False
    result=await _bb_currency_quantity(str(msg.text))
    if result is None:return False
    await msg.reply_text(result,parse_mode='HTML')
    return True

# ------------------------- 5-minute HAPO + dog store/adventure -------------------------
_BB_DOGS={
 'هاسکی':(120,2),'ژرمن شپرد':(180,3),'گلدن رتریور':(240,4),'لابرادور':(300,5),'مالینویز':(420,6),'آکیتا':(550,8)
}
async def _bb_dog_schema():
    await DBX.execute("CREATE TABLE IF NOT EXISTS bbx_dog_adventure(chat_id INTEGER NOT NULL,user_id INTEGER NOT NULL,dog_key TEXT NOT NULL,chapter INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(chat_id,user_id))")
    cols=await DBX.execute('PRAGMA table_info(bbx_hop)',fetch=True)
    names={r['name'] for r in cols}
    if 'last_hop_at' not in names: await DBX.execute('ALTER TABLE bbx_hop ADD COLUMN last_hop_at INTEGER NOT NULL DEFAULT 0')
    if 'bones' not in names: await DBX.execute('ALTER TABLE bbx_hop ADD COLUMN bones INTEGER NOT NULL DEFAULT 0')

async def _bb_dog_text(update,context):
    msg=update.effective_message; chat=update.effective_chat; user=update.effective_user
    if not msg or not chat or not user or chat.type=='private':return False
    low=normalize(msg.text or '')
    if low not in {'هاپ','هاپ هاپ','هاپهاپ','هاپو','سگ'}:return False
    await _bb_dog_schema(); h=bbx_hop(chat.id,user.id); now=int(time.time()); last=int(h['last_hop_at'] or 0)
    if low in {'هاپ','هاپ هاپ','هاپهاپ','هاپو'}:
        remain=300-(now-last)
        if remain>0:
            await msg.reply_text(f'برای هاپ بعدی {remain//60 + (1 if remain%60 else 0)} دقیقه دیگر صبر کن.')
            return True
        gain=random.randint(15,45); old=int(h['points'] or 0); new=old+gain
        await DBX.execute('UPDATE bbx_hop SET points=?,bones=bones+?,last_hop_at=? WHERE chat_id=? AND user_id=?',(new,gain,now,chat.id,user.id))
        await msg.reply_text(f'هاپ انجام شد. استخوان: +{gain}. موجودی: {new}.')
        return True
    # سگ: show store only when level/bones permit.
    rows=[]
    for name,(cost,req_level) in _BB_DOGS.items():
        status='قابل خرید' if int(h['dog_level'] or 1)>=req_level and int(h['bones'] or h['points'] or 0)>=cost else 'قفل'
        rows.append([btn(f'{name} — {cost} استخوان — سطح {req_level}',f'dogbuy:{chat.id}:{user.id}:{name}')])
    await msg.reply_text(f'فروشگاه سگ‌ها\nسطح: {h["dog_level"]}\nاستخوان: {int(h["bones"] or h["points"] or 0)}\n\nیک سگ انتخاب کن:',reply_markup=keyboard(rows))
    return True

async def _bb_dog_callback(update,context):
    q=update.callback_query; data=str(q.data or '')
    if not data.startswith('dogbuy:'):return False
    _,cid,uid,name=data.split(':',3); cid=int(cid);uid=int(uid)
    if q.from_user.id!=uid:await q.answer('این پنل برای کاربر دیگری است.',show_alert=True);return True
    await _bb_dog_schema(); h=bbx_hop(cid,uid); item=_BB_DOGS.get(name)
    if not item:await q.answer('سگ پیدا نشد.',show_alert=True);return True
    cost,req=item; bones=int(h['bones'] or h['points'] or 0); lvl=int(h['dog_level'] or 1)
    if lvl<req:await q.answer('سطح کافی نیست.',show_alert=True);return True
    if bones<cost:await q.answer('استخوان کافی نیست.',show_alert=True);return True
    await DBX.execute('UPDATE bbx_hop SET bones=bones-?,points=points-?,dog_name=?,dog_level=? WHERE chat_id=? AND user_id=?',(cost,cost,name,max(lvl,req),cid,uid))
    await DBX.execute('INSERT INTO bbx_dog_adventure(chat_id,user_id,dog_key,chapter,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(chat_id,user_id) DO UPDATE SET dog_key=excluded.dog_key,chapter=0,updated_at=excluded.updated_at',(cid,uid,name,0,int(time.time())))
    await q.edit_message_text(f'سگ {name} خریداری شد. ماجراجویی از فصل اول شروع شد.',reply_markup=keyboard([[btn('شروع ماجراجویی','dogadv:'+str(cid)+':'+str(uid))]]))
    return True

async def _bb_dog_adventure_callback(update,context):
    q=update.callback_query; d=str(q.data or '')
    if not d.startswith('dogadv:'):return False
    _,cid,uid=d.split(':');cid=int(cid);uid=int(uid)
    if q.from_user.id!=uid:await q.answer('این ماجراجویی برای تو نیست.',show_alert=True);return True
    row=await DBX.one('SELECT * FROM bbx_dog_adventure WHERE chat_id=? AND user_id=?',(cid,uid))
    if not row:await q.answer('اول یک سگ بخر.',show_alert=True);return True
    chapter=int(row['chapter'] or 0)+1
    stories=['دروازه جنگل مه‌آلود باز شد؛ هاپوی تو رد پنجه‌های تازه را پیدا کرد.','کنار رودخانه، یک جعبه قدیمی پیدا کردید و باید مسیر درست را انتخاب کنید.','شب شد؛ هاپو صدای عجیبی شنید و از کمپ محافظت کرد.','در قلعه متروکه، نقشه گنج پیدا شد؛ سفر هنوز ادامه دارد.','گنج پیدا شد؛ ماجراجویی فصل اول با یک جایزه استخوانی تمام شد.']
    idx=min(chapter,len(stories)); reward=10+chapter*5
    if chapter>=len(stories):
        await DBX.execute('UPDATE bbx_hop SET bones=bones+?,points=points+? WHERE chat_id=? AND user_id=?',(reward,reward,cid,uid)); chapter=0
    await DBX.execute('UPDATE bbx_dog_adventure SET chapter=?,updated_at=? WHERE chat_id=? AND user_id=?',(chapter,int(time.time()),cid,uid))
    await q.edit_message_text(f'فصل {idx}\n\n{stories[idx-1]}\n\nپاداش این مرحله: {reward} استخوان.',reply_markup=keyboard([[btn('ادامه','dogadv:'+str(cid)+':'+str(uid))],[btn('ارتقای سگ','dogup:'+str(cid)+':'+str(uid))]]))
    return True

async def _bb_dog_upgrade_callback(update,context):
    q=update.callback_query;d=str(q.data or '')
    if not d.startswith('dogup:'):return False
    _,cid,uid=d.split(':');cid=int(cid);uid=int(uid)
    if q.from_user.id!=uid:await q.answer('این پنل برای تو نیست.',show_alert=True);return True
    h=bbx_hop(cid,uid);lvl=int(h['dog_level'] or 1);cost=lvl*100;bones=int(h['bones'] or h['points'] or 0)
    if bones<cost:await q.answer(f'برای ارتقا {cost} استخوان لازم است.',show_alert=True);return True
    await DBX.execute('UPDATE bbx_hop SET bones=bones-?,points=points-?,dog_level=dog_level+1 WHERE chat_id=? AND user_id=?',(cost,cost,cid,uid))
    await q.answer('ارتقا انجام شد.',show_alert=True)
    await _bb_dog_adventure_callback(update,context)
    return True

# ------------------------- «یواشکی» exact alias -------------------------
async def _bb_yavashki_alias(update,context):
    msg=update.effective_message;chat=update.effective_chat;user=update.effective_user
    if not msg or not user or not chat or normalize(msg.text or '')!='یواشکی':return False
    if chat.type=='private':await msg.reply_text('یواشکی را داخل گروه، با ریپلای روی گیرنده شروع کن.');return True
    if not msg.reply_to_message or not msg.reply_to_message.from_user:await msg.reply_text('روی پیام گیرنده ریپلای کن و یواشکی را بفرست.');return True
    r=msg.reply_to_message.from_user
    if r.is_bot:await msg.reply_text('برای ربات نمی‌توان یواشکی فرستاد.');return True
    BBX_WHISPER_WAIT[user.id]=(os.urandom(8).hex(),r.id,chat.id,time.time()+300)
    username=await _bb_runtime_bot_username(context.bot)
    url=f'https://t.me/{username}' if username else 'https://t.me/'
    kb=keyboard([[btn('ورود به ربات و ارسال یواشکی',url=url)]])
    try:
        await context.bot.send_message(user.id,'متن یواشکی خود را ارسال کن.')
    except Exception:
        BBX_WHISPER_WAIT.pop(user.id,None)
        await msg.reply_text('ابتدا ربات را در خصوصی Start کن؛ سپس دوباره یواشکی را بزن.',reply_markup=kb);return True
    await msg.reply_text('پیام یواشکی را در خصوصی ربات بفرست. زمان: ۵ دقیقه.',reply_markup=kb)
    return True

# ------------------------- group-link four-format panel -------------------------
async def _bb_group_link_panel_text(update,context):
    msg=update.effective_message; chat=update.effective_chat
    if not msg or not chat or chat.type=='private': return False
    if normalize(msg.text or '') not in {'لینک گروه','پنل لینک گروه','لینک این گروه'}: return False
    if not await is_admin(update):
        await msg.reply_text(_bb_ui_get('فقط ادمین گروه.','text') if '_bb_ui_get' in globals() else 'فقط ادمین گروه.')
        return True
    labels={
        'title': _bb_ui_get('🔗 پنل لینک گروه','text') if '_bb_ui_get' in globals() else '🔗 پنل لینک گروه',
        'hint': _bb_ui_get('یکی از چهار مدل را انتخاب کن.','text') if '_bb_ui_get' in globals() else 'یکی از چهار مدل را انتخاب کن.',
        'qr': _bb_ui_get('لینک QR کددار','button') if '_bb_ui_get' in globals() else 'لینک QR کددار',
        'photo': _bb_ui_get('لینک عکس‌دار','button') if '_bb_ui_get' in globals() else 'لینک عکس‌دار',
        'pv': _bb_ui_get('لینک پیوی','button') if '_bb_ui_get' in globals() else 'لینک پیوی',
        'advanced': _bb_ui_get('لینک پیشرفته','button') if '_bb_ui_get' in globals() else 'لینک پیشرفته',
    }
    await msg.reply_text(labels['title']+'\n\n'+labels['hint'],reply_markup=keyboard([
        [btn(labels['qr'],f'bblink:{chat.id}:qr'),btn(labels['photo'],f'bblink:{chat.id}:photo')],
        [btn(labels['pv'],f'bblink:{chat.id}:pv'),btn(labels['advanced'],f'bblink:{chat.id}:advanced')]
    ]))
    return True

async def _bb_group_link_callback(update,context):
    q=update.callback_query; d=str(q.data or '')
    if not d.startswith('bblink:'): return False
    parts=d.split(':',2)
    if len(parts)!=3: return True
    _,cid,kind=parts; cid=int(cid)
    try: member=await context.bot.get_chat_member(cid,q.from_user.id)
    except Exception:
        await q.answer('دسترسی بررسی نشد.',show_alert=True); return True
    if getattr(member,'status','') not in {ChatMemberStatus.ADMINISTRATOR,ChatMemberStatus.OWNER}:
        await q.answer(_bb_ui_get('فقط ادمین گروه.','text') if '_bb_ui_get' in globals() else 'فقط ادمین.',show_alert=True); return True
    try: link=(await context.bot.create_chat_invite_link(cid,creates_join_request=False)).invite_link
    except Exception:
        try: link=await context.bot.export_chat_invite_link(cid)
        except Exception:
            await q.answer('ساخت لینک ممکن نشد.',show_alert=True); return True
    get=lambda value,kind='text': (_bb_ui_get(value,kind) if '_bb_ui_get' in globals() else value)
    if kind=='qr':
        qr='https://quickchart.io/qr?size=600&text='+quote_plus(link)
        await q.message.reply_photo(qr,caption=f'{get("لینک QR گروه:")}\n{link}')
    elif kind=='photo':
        image='https://quickchart.io/qr?size=900&margin=2&text='+quote_plus(link)
        await q.message.reply_photo(image,caption=f'{get("کارت لینک گروه:")}\n{link}')
    elif kind=='pv':
        share='https://t.me/share/url?url='+quote_plus(link)+'&text='+quote_plus('لینک گروه')
        await q.message.reply_text(f'{get("لینک پیوی:")}\n{share}',reply_markup=keyboard([[btn(get('باز کردن لینک پیوی','button'),url=share)]]))
    else:
        advanced=link+'&start=bilbilak' if '?' in link else link+'?start=bilbilak'
        await q.message.reply_text(f'{get("لینک پیشرفته:")}\n{advanced}',reply_markup=keyboard([[btn(get('باز کردن لینک','button'),url=advanced)]]))
    await q.answer()
    return True

# ------------------------- final build registration -------------------------
_BB_FINAL_BUILD_BEFORE_OWNER_PATCH=build_application
def build_application(token:str)->Application:
    app=_BB_FINAL_BUILD_BEFORE_OWNER_PATCH(token)
    # Highest-priority exact aliases / dog system / group-link panel.
    app.add_handler(CallbackQueryHandler(_bb_dog_callback,pattern=r'^dogbuy:'),group=-500000)
    app.add_handler(CallbackQueryHandler(_bb_dog_adventure_callback,pattern=r'^dogadv:'),group=-500001)
    app.add_handler(CallbackQueryHandler(_bb_dog_upgrade_callback,pattern=r'^dogup:'),group=-500002)
    app.add_handler(CallbackQueryHandler(_bb_group_link_callback,pattern=r'^bblink:'),group=-500003)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_yavashki_alias),group=-500010)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_dog_text),group=-500011)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_group_link_panel_text),group=-500012)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_final_config_text_verified),group=-500013)
    old_post=getattr(app,'post_init',None)
    async def _bb_final_post_init(application):
        if old_post:await old_post(application)
        try:
            global BB_BOT_USERNAME
            me=await application.bot.get_me();BB_BOT_USERNAME=str(getattr(me,'username','') or '').lstrip('@')
            await _bb_dog_schema()
        except Exception as exc:log.warning('final post-init failed: %s',exc)
    try:app.post_init=_bb_final_post_init
    except Exception:pass
    return app



# Final legacy-PV setting validator: handles the older owner/music and cleanup
# panels too, so a malformed API/phone value is never persisted.
async def _bb_final_legacy_setting_text(update,context):
    msg=getattr(update,'effective_message',None); uid=getattr(getattr(update,'effective_user',None),'id',0)
    if not msg or not getattr(msg,'text',None) or not uid:return False
    if not await _bb_is_bot_admin(uid):return False
    field=OWNER_PENDING_MUSIC_SETTING.get(uid) if 'OWNER_PENDING_MUSIC_SETTING' in globals() else None
    if field:
        val=str(msg.text).strip()
        if field=='api_id' and not re.fullmatch(r'\d{5,12}',val):
            await msg.reply_text('API ID باید فقط عدد معتبر باشد.');return True
        if field=='api_hash' and not re.fullmatch(r'[0-9a-fA-F]{20,64}',val):
            await msg.reply_text('API Hash معتبر نیست؛ مقدار هگزادسیمال را کامل بفرست.');return True
        if field=='phone':
            val=val.replace(' ','').replace('-','')
            if not re.fullmatch(r'\+?[0-9]{7,20}',val):await msg.reply_text('شماره معتبر نیست.');return True
        if field=='session' and not val:val=str(Path.home()/'bilbilak_music_user')
        key=MUSIC_SETTING_KEYS[field]
        await _bb_set_music_setting(key,val)
        if field=='api_id':
            global TELEGRAM_API_ID
            TELEGRAM_API_ID=int(val)
        elif field=='api_hash':
            global TELEGRAM_API_HASH
            TELEGRAM_API_HASH=val
        elif field=='phone':
            global MUSIC_USER_PHONE
            MUSIC_USER_PHONE=val
        elif field=='session':
            global MUSIC_USER_SESSION
            MUSIC_USER_SESSION=val
        OWNER_PENDING_MUSIC_SETTING.pop(uid,None)
        try:await msg.delete()
        except Exception:pass
        await context.bot.send_message(update.effective_chat.id,'مقدار معتبر بود و در تنظیمات موزیکال و SQLite ذخیره شد.',reply_markup=keyboard([[btn('تنظیمات موزیکال','own6:music')]]))
        return True
    field=OWNER_PENDING_CLEANUP_SETTING.get(uid) if 'OWNER_PENDING_CLEANUP_SETTING' in globals() else None
    if field:
        val=str(msg.text).strip()
        if field=='phone':
            val=val.replace(' ','').replace('-','')
            if not re.fullmatch(r'\+?[0-9]{7,20}',val):await msg.reply_text('شماره معتبر نیست.');return True
            await _bb_cleanup_save(phone=val)
        elif field=='session':
            val=str(Path.home()/'bilbilak_cleanup_user') if normalize(val) in {'default','پیشفرض','پیش فرض'} else val
            if not val or len(val)>300:await msg.reply_text('مسیر Session معتبر نیست.');return True
            await _bb_cleanup_save(session=val)
            try:
                global CLEANUP_USER_SESSION
                CLEANUP_USER_SESSION=val
            except Exception:pass
        OWNER_PENDING_CLEANUP_SETTING.pop(uid,None)
        try:await msg.delete()
        except Exception:pass
        await context.bot.send_message(update.effective_chat.id,'مقدار معتبر بود و در تنظیمات پاکسازی و SQLite ذخیره شد.')
        return True
    return False

_BB_BUILD_WITH_FINAL_SETTINGS=build_application
def build_application(token:str)->Application:
    app=_BB_BUILD_WITH_FINAL_SETTINGS(token)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_final_legacy_setting_text),group=-500014)
    return app


