_BB_UI_SCHEMA_READY=False
_BB_UI_CACHE={}
_BB_UI_EMOJI_CACHE={}
_BB_UI_PENDING=set()
_BB_UI_CATEGORIES={'history':'🏺 ماجراجویی تاریخ ایران','home':'🏠 منوی اصلی','owner':'👑 پنل مالک','settings':'⚙️ تنظیمات','tools':'🧰 ابزارها','games':'🎮 بازی‌ها','mafia':'🕵️ مافیا','football':'⚽ فوتبال','teams':'🏆 تیم‌ها و جام‌ها','players':'👤 بازیکنان','music':'🎵 موزیکال','downloader':'📥 دانلودر','vip':'💎 VIP','economy':'💰 اقتصاد','stats':'🏅 آمار','group':'👥 گروه','group_link':'🔗 لینک گروه','ai':'🤖 هوش مصنوعی','help':'📚 راهنما','errors':'❌ خطاها','status':'🔄 وضعیت‌ها','buttons':'🔘 دکمه‌ها','life':'💍 زندگی و ازدواج','career':'💼 شغل و تحصیلات','wedding':'💐 عقد و عروسی','raffle':'🎟 قرعه‌کشی','family':'👨‍👩‍👧 خانواده','other':'📦 سایر'}

def _bb_ui_guess_category(text,kind='text'):
    t=normalize(str(text or ''))
    rules=[('music',('موزیک','آهنگ','پخش','رادیو','صف','بعدی','قبلی','مکث','ادامه','توقف','صدا')),('downloader',('دانلود','ویدیو','فیلم')),('owner',('مالک','کنترل کامل','پنل مرکزی','پیام همگانی','بکاپ','امنیت سراسری')),('games',('بازی','دوز','شطرنج','مافیا','جرأت','حقیقت')),('tools',('ابزار','هوا','ارز','فونت','مکانیابی','کشور')),('profile',('پروفایل','کاربر','بیو')),('vip',('vip','ویژه','پرمیوم')),('stats',('آمار','رتبه','امتیاز')),('settings',('تنظیم','پیکربندی','تنظیمات')),('help',('راهنما','کمک')),('group',('گروه','عضو','ادمین','مدیریت')),('life',('زندگی','ازدواج','خانواده','دختر کوچولوی بابا')),('career',('شغل','کار','تحصیلات','بلاگر','بلاگری')),('wedding',('عقد','عروسی','دعوتنامه','عاقد','ساقدوش','بله گفتن')),('raffle',('قرعه','قرعه‌کشی'))]
    for cat,words in rules:
        if any(w in t for w in words): return cat
    return 'buttons' if kind=='button' else 'other'

async def _bb_ui_schema():
    global _BB_UI_SCHEMA_READY
    if _BB_UI_SCHEMA_READY or not DBX:return
    await DBX.execute("CREATE TABLE IF NOT EXISTS bb_ui_texts(key TEXT PRIMARY KEY,category TEXT DEFAULT 'other',original TEXT DEFAULT '',custom TEXT DEFAULT '',kind TEXT DEFAULT 'text',emoji_id TEXT DEFAULT '',updated_at INTEGER DEFAULT 0)")
    await DBX.execute("CREATE TABLE IF NOT EXISTS bb_ui_meta(key TEXT PRIMARY KEY,value TEXT DEFAULT '')")
    _BB_UI_SCHEMA_READY=True
    await _bb_ui_refresh()

def _bb_ui_key(original,kind='text'):
    import hashlib
    return hashlib.sha256((str(kind)+'|'+str(original)).encode('utf-8')).hexdigest()[:32]

async def _bb_ui_register(original,category=None,kind='text'):
    original=str(original or '')
    if not original.strip() or not DBX:return
    # Runtime button/text registration can happen before post_init() finishes.
    # Always ensure the UI tables exist before touching them.
    await _bb_ui_schema()
    await DBX.execute('INSERT OR IGNORE INTO bb_ui_texts(key,category,original,custom,kind,emoji_id,updated_at) VALUES(?,?,?,?,?,?,?)',(_bb_ui_key(original,kind),category or _bb_ui_guess_category(original,kind),original,'',kind,'',now_ts()))

def _bb_ui_cache_register(original,category=None,kind='text'):
    original=str(original or '')
    if not original.strip():return
    key=_bb_ui_key(original,kind);_BB_UI_CACHE.setdefault((kind,original),original)
    marker=(key,category,kind)
    if marker not in _BB_UI_PENDING:
        _BB_UI_PENDING.add(marker)
        try:asyncio.get_running_loop().create_task(_bb_ui_register(original,category,kind))
        except Exception:pass

async def _bb_ui_refresh():
    try:
        rows=await DBX.execute('SELECT original,custom,kind,emoji_id FROM bb_ui_texts',fetch=True)
        _BB_UI_CACHE.clear();_BB_UI_EMOJI_CACHE.clear()
        for r in rows:
            o=str(r['original'] or '');k=str(r['kind'] or 'text');_BB_UI_CACHE[(k,o)]=str(r['custom'] or '') or o
            if r['emoji_id']:_BB_UI_EMOJI_CACHE[(k,o)]=str(r['emoji_id'])
    except Exception as exc:log.debug('UI cache refresh: %s',exc)

def _bb_ui_get(original,kind='text'):
    o=str(original);base=_BB_UI_CACHE.get((kind,o),o)
    eid=_BB_UI_EMOJI_CACHE.get((kind,o),'')
    if not eid:return base
    if kind=='text' and str(eid).isdigit(): return f'<tg-emoji emoji-id=\"{eid}\">✨</tg-emoji> {base}'
    if str(eid).isdigit(): return f'✨ {base}'
    return f'{eid} {base}'
def _bb_ui_text(text):return _bb_ui_get(str(text or ''),'text')

_BB_UI_OLD_BTN=btn
def btn(text,data=None,url=None,style=None):
    original=str(text or '')
    _bb_ui_cache_register(original,kind='button')
    return _BB_UI_OLD_BTN(_bb_ui_get(original,'button'),data=data,url=url,style=style)

try:
    _BB_UI_OLD_VISUAL_MESSAGE_TEXT=_bb_visual_message_text
    def _bb_visual_message_text(text):return _BB_UI_OLD_VISUAL_MESSAGE_TEXT(_bb_ui_text(text))
except Exception:pass

async def _bb_ui_scan_source():
    try:
        import ast
        src=Path(__file__).read_text(encoding='utf-8');tree=ast.parse(src)
        for n in ast.walk(tree):
            if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id in ('btn','reply_btn') and n.args and isinstance(n.args[0],ast.Constant) and isinstance(n.args[0].value,str):await _bb_ui_register(n.args[0].value,kind='button')
            if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and n.func.attr in ('reply_text','edit_message_text') and n.args and isinstance(n.args[0],ast.Constant) and isinstance(n.args[0].value,str):await _bb_ui_register(n.args[0].value,kind='text')
    except Exception as exc:log.debug('UI source scan failed: %s',exc)

async def _bb_ui_owner_home(q):
    await _bb_ui_schema()
    rows=[[btn('🏠 منوی اصلی','bbui:home')],[btn('🔘 دکمه‌ها','bbui:list:button'),btn('📝 متن‌ها','bbui:list:text')],[btn('🎵 موزیکال','bbui:cat:music'),btn('📥 دانلودر','bbui:cat:downloader')],[btn('👑 مالک','bbui:cat:owner'),btn('⚙️ تنظیمات','bbui:cat:settings')],[btn('📂 همه دسته‌ها','bbui:cats')],[btn('🧹 بازنشانی یک مورد','bbui:reset'),btn('📊 پوشش UI','bbui:coverage')],[btn('🔙 پنل مالک','bbui:back')]]
    await q.edit_message_text('🎨 <b>طراحی متن و دکمه‌ها</b>\n\nاز اینجا متن‌ها و عنوان دکمه‌ها را شخصی‌سازی کن.\nعملکرد، callback، لینک و مسیر اجرای دکمه‌ها تغییر نمی‌کند.',parse_mode='HTML',reply_markup=keyboard(rows))

async def _bb_ui_list(q,kind='button',category=None):
    await _bb_ui_schema(); rows=await DBX.execute('SELECT original,custom FROM bb_ui_texts WHERE kind=?'+(' AND category=?' if category else '')+' ORDER BY original LIMIT 100',((kind,category) if category else (kind,)),fetch=True)
    kb=[]
    for r in rows[:20]:
        o=str(r['original'] or '');shown=str(r['custom'] or '') or o;label=shown[:43]+('…' if len(shown)>43 else '')
        kb.append([btn(label,f'bbui:edit:{kind}:{_bb_ui_key(o,kind)}')])
    if not kb:kb=[[btn('ℹ️ موردی پیدا نشد','bbui:home')]]
    kb.append([btn('🔙 طراحی','bbui:home')]);title='🔘 دکمه‌ها' if kind=='button' else '📝 متن‌ها'
    if category:title+=f' — {_BB_UI_CATEGORIES.get(category,category)}'
    await q.edit_message_text(f'<b>{title}</b>\n\nبرای ویرایش روی مورد بزن.',parse_mode='HTML',reply_markup=keyboard(kb))

async def _bb_ui_callback(update,context):
    q=getattr(update,'callback_query',None)
    if not q or not str(q.data or '').startswith('bbui:'):return False
    if not await _bb_is_bot_admin(q.from_user.id):await q.answer('⛔ فقط مالک یا ادمین مرکزی ربات.',show_alert=True);return True
    await q.answer();d=q.data or ''
    if d=='bbui:home':await _bb_ui_owner_home(q);return True
    if d=='bbui:back':
        await q.edit_message_text('👑 <b>پنل مالک بیل بیلک</b>\n\nیک بخش را انتخاب کن:',parse_mode='HTML',reply_markup=owner_keyboard(q.from_user.id));return True
    if d=='bbui:emoji':
        context.user_data['bbui_pending_emoji']=True
        await q.edit_message_text('✨ <b>طراحی ایموجی پرمیوم</b>\n\nایموجی پرمیوم موردنظر را در پیام بعدی بفرست. اگر تلگرام شناسه Custom Emoji آن را همراه پیام بفرستد، شناسه ذخیره می‌شود.\n\nبعد از آن متن یا عنوان موردنظر را بفرست.',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 طراحی','bbui:home')]]));return True
    if d in ('bbui:list:button','bbui:list:text'):
        await _bb_ui_list(q,'button' if d.endswith('button') else 'text');return True
    if d.startswith('bbui:cat:'):await _bb_ui_list(q,'button',d.split(':',2)[2]);return True
    if d=='bbui:cats':
        await q.edit_message_text('📂 <b>دسته‌بندی طراحی</b>',parse_mode='HTML',reply_markup=keyboard([[btn(v,f'bbui:cat:{k}')] for k,v in _BB_UI_CATEGORIES.items()]+[[btn('🔙 طراحی','bbui:home')]]));return True
    if d=='bbui:coverage':
        total=int((await DBX.one('SELECT COUNT(*) c FROM bb_ui_texts'))['c']);buttons=int((await DBX.one("SELECT COUNT(*) c FROM bb_ui_texts WHERE kind='button'"))['c']);texts=int((await DBX.one("SELECT COUNT(*) c FROM bb_ui_texts WHERE kind='text'"))['c'])
        await q.edit_message_text(f'📊 <b>پوشش طراحی</b>\n\n🔘 دکمه‌ها: {buttons}\n📝 متن‌ها: {texts}\n📦 مجموع: {total}',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 طراحی','bbui:home')]]));return True
    if d=='bbui:reset':
        context.user_data['bbui_pending_reset']=True;await q.edit_message_text('🧹 متن اصلی مورد را در پیام بعدی بفرست.',reply_markup=keyboard([[btn('🔙 لغو','bbui:home')]]));return True
    if d.startswith('bbui:edit:'):
        _,_,kind,key=d.split(':',3);row=await DBX.one('SELECT original,custom FROM bb_ui_texts WHERE key=?',(key,))
        if not row:await q.answer('مورد پیدا نشد.',show_alert=True);return True
        context.user_data['bbui_edit']={'key':key};await q.edit_message_text(f'✏️ <b>ویرایش</b>\n\nفعلی:\n<code>{safe_text(row["custom"] or row["original"],1200)}</code>\n\nمتن جدید را بفرست؛ برای بازگشت بنویس <code>اصلی</code>.',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 لغو','bbui:home')]]));return True
    return True

async def _bb_ui_message(update,context):
    msg=getattr(update,'effective_message',None);u=getattr(update,'effective_user',None)
    if not msg or not u or not await _bb_is_bot_admin(u.id):return False
    if context.user_data.pop('bbui_pending_emoji',False):
        entities=getattr(msg,'entities',None) or []
        ce=next((e for e in entities if str(getattr(e,'type',''))=='custom_emoji'),None)
        emoji_text=str(msg.text or '').strip()
        emoji_id=getattr(ce,'custom_emoji_id',None) if ce else None
        context.user_data['bbui_emoji_value']={'emoji':emoji_text,'emoji_id':emoji_id or ''}
        await msg.reply_text('✅ ایموجی دریافت شد. حالا متن یا عنوان موردنظر را دقیقاً بفرست.')
        return True
    ev=context.user_data.pop('bbui_emoji_value',None)
    if ev:
        original=str(msg.text or '').strip()
        if original:
            rows=await DBX.execute('SELECT key,kind FROM bb_ui_texts WHERE original=?',(original,),fetch=True)
            if rows:
                for row in rows:
                    await DBX.execute('UPDATE bb_ui_texts SET emoji_id=?,updated_at=? WHERE key=?',(ev.get('emoji_id') or ev.get('emoji',''),now_ts(),row['key']))
                await _bb_ui_refresh();await msg.reply_text('✨ ایموجی برای متن/دکمه ذخیره شد.')
            else:
                await DBX.execute('INSERT OR IGNORE INTO bb_ui_texts(key,category,original,custom,kind,emoji_id,updated_at) VALUES(?,?,?,?,?,?,?)',(_bb_ui_key(original,'text'),'other',original,'','text',ev.get('emoji_id') or ev.get('emoji',''),now_ts()))
                await _bb_ui_refresh();await msg.reply_text('✨ مورد ثبت و ایموجی آن ذخیره شد.')
        return True
    edit=context.user_data.pop('bbui_edit',None)
    if edit:
        val=str(msg.text or '').strip();row=await DBX.one('SELECT original FROM bb_ui_texts WHERE key=?',(edit['key'],))
        if row and val:
            await DBX.execute('UPDATE bb_ui_texts SET custom=?,updated_at=? WHERE key=?',('' if normalize(val)=='اصلی' else val,now_ts(),edit['key']));await _bb_ui_refresh();await msg.reply_text('✅ ذخیره شد.')
        return True
    if context.user_data.pop('bbui_pending_reset',False):
        val=str(msg.text or '').strip();row=await DBX.one('SELECT key FROM bb_ui_texts WHERE original=?',(val,))
        if row:await DBX.execute('UPDATE bb_ui_texts SET custom="",emoji_id="",updated_at=? WHERE key=?',(now_ts(),row['key']));await _bb_ui_refresh();await msg.reply_text('✅ به حالت اصلی برگشت.')
        else:await msg.reply_text('❌ موردی پیدا نشد.')
        return True
    return False

async def _bb_ui_post_init(application):
    await _bb_ui_schema();await _bb_ui_scan_source();await _bb_ui_refresh()
    await _BB_UI_PREV_POST_INIT(application)
