_BB_UI_PREV_BUILD=build_application
def build_application(token:str)->Application:
    app=_BB_UI_PREV_BUILD(token)
    # Direct owner-only command for the visual designer. Telegram command names
    # are ASCII, so both /design and /tarahi are provided.
    app.add_handler(CommandHandler(['design','tarahi'],_bb_ui_design_command),group=-900002)
    app.add_handler(CallbackQueryHandler(_bb_ui_callback,pattern=r'^bbui:'),group=-900000)
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,_bb_ui_message),group=-900001)
    return app



