_BB_STUDIO_V2_READY=False
async def _bb_studio_v2_schema():
    global _BB_STUDIO_V2_READY
    if _BB_STUDIO_V2_READY or not DBX: return
    await _bb_ui_schema()
    for sql in (
        "ALTER TABLE bb_ui_texts ADD COLUMN source_line INTEGER DEFAULT 0",
        "ALTER TABLE bb_ui_texts ADD COLUMN source_name TEXT DEFAULT ''",
        "ALTER TABLE bb_ui_texts ADD COLUMN media_type TEXT DEFAULT ''",
        "ALTER TABLE bb_ui_texts ADD COLUMN media_id TEXT DEFAULT ''",
        "ALTER TABLE bb_ui_texts ADD COLUMN media_caption TEXT DEFAULT ''",
    ):
        try: await DBX.execute(sql)
        except Exception: pass
    await DBX.execute('CREATE TABLE IF NOT EXISTS bb_api_settings(key TEXT PRIMARY KEY,value TEXT DEFAULT \'\',updated_at INTEGER DEFAULT 0)')
    await DBX.execute('CREATE TABLE IF NOT EXISTS bb_voice_replies(id INTEGER PRIMARY KEY AUTOINCREMENT,trigger TEXT UNIQUE,response_type TEXT DEFAULT \'text\',response_value TEXT DEFAULT \'\',media_id TEXT DEFAULT \'\',caption TEXT DEFAULT \'\',updated_at INTEGER DEFAULT 0)')
    await DBX.execute('CREATE TABLE IF NOT EXISTS bb_game_lists(game TEXT NOT NULL,item TEXT NOT NULL,created_at INTEGER DEFAULT 0,PRIMARY KEY(game,item))')
    await DBX.execute('CREATE TABLE IF NOT EXISTS bb_feature_specs(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT DEFAULT \'\',ui_text TEXT DEFAULT \'\',buttons TEXT DEFAULT \'\',created_at INTEGER DEFAULT 0,updated_at INTEGER DEFAULT 0)')
    await DBX.execute('CREATE TABLE IF NOT EXISTS bb_player_data(name TEXT PRIMARY KEY,nationality TEXT DEFAULT \'\',current_team TEXT DEFAULT \'\',prime_team TEXT DEFAULT \'\',prime_year TEXT DEFAULT \'\',age TEXT DEFAULT \'\',children TEXT DEFAULT \'\',world_cups TEXT DEFAULT \'\',national_trophies TEXT DEFAULT \'\',club_trophies TEXT DEFAULT \'\',spouse TEXT DEFAULT \'\',emoji_id TEXT DEFAULT \'\')')
    await DBX.execute('CREATE TABLE IF NOT EXISTS bb_team_data(name TEXT PRIMARY KEY,description TEXT DEFAULT \'\',trophies TEXT DEFAULT \'\',emoji_id TEXT DEFAULT \'\')')
    _BB_STUDIO_V2_READY=True

async def _bb_api_set(key,value):
    await _bb_studio_v2_schema(); await DBX.execute('INSERT OR REPLACE INTO bb_api_settings(key,value,updated_at) VALUES(?,?,?)',(str(key),str(value or ''),now_ts()))
async def _bb_api_get(key,default=''):
    await _bb_studio_v2_schema(); r=await DBX.one('SELECT value FROM bb_api_settings WHERE key=?',(key,)); return str(r['value']) if r else default

# -----------------------------------------------------------------------------
# Exhaustive source scanner. It registers static user-facing strings from the
# entire file, not just the old btn()/reply_text hooks.
# -----------------------------------------------------------------------------
def _bb_studio_literal_category(value):
    return _bb_ui_guess_category(value,'text')

def _bb_studio_is_ui_string(value):
    v=str(value or '').strip()
    if len(v)<2: return False
    if v.startswith(('SELECT ','INSERT ','UPDATE ','DELETE ','CREATE TABLE','ALTER TABLE','http://','https://','sqlite://','file://')): return False
    if any(x in v for x in ('__name__','__file__','%(id)s','%(ext)s','utf-8','text/x-python')): return False
    # Keep Persian, emoji, spaces and ordinary visible English UI strings.
    return bool(re.search(r'[\u0600-\u06ff\u200c\U0001F000-\U0001FAFF\s]',v)) or len(v)>=8

async def _bb_studio_register_literal(value,kind='text',line=0,source=''):
    value=_bb_no_premium_markup(value)
    if not _bb_studio_is_ui_string(value): return
    await _bb_ui_register(value,category=_bb_studio_literal_category(value),kind=kind)
    try:
        await DBX.execute('UPDATE bb_ui_texts SET source_line=?,source_name=? WHERE key=?',(int(line or 0),str(source or ''),_bb_ui_key(value,kind)))
    except Exception: pass

async def _bb_studio_scan_everything():
    try:
        import ast
        path=Path(__file__); tree=ast.parse(path.read_text(encoding='utf-8'))
        seen=set()
        for n in ast.walk(tree):
            # Button labels / reply buttons.
            if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id in {'btn','reply_btn'}:
                if n.args and isinstance(n.args[0],ast.Constant) and isinstance(n.args[0].value,str):
                    k=('button',n.args[0].value)
                    if k not in seen: seen.add(k); await _bb_studio_register_literal(n.args[0].value,'button',getattr(n,'lineno',0),path.name)
            # Every common Telegram text/caption/alert argument.
            if isinstance(n,ast.Call):
                fname=n.func.attr if isinstance(n.func,ast.Attribute) else (n.func.id if isinstance(n.func,ast.Name) else '')
                if fname in {'reply_text','edit_message_text','send_message','answer','reply_photo','send_photo','reply_animation','send_animation','edit_caption','reply_voice','send_voice','reply_sticker','send_sticker'}:
                    for a in list(n.args)+[kw.value for kw in n.keywords if kw.arg in {'text','caption'}]:
                        vals=[]
                        if isinstance(a,ast.Constant) and isinstance(a.value,str): vals=[a.value]
                        elif isinstance(a,ast.JoinedStr):
                            vals=[x.value for x in a.values if isinstance(x,ast.Constant) and isinstance(x.value,str)]
                        for val in vals:
                            k=('text',val)
                            if k not in seen: seen.add(k); await _bb_studio_register_literal(val,'text',getattr(n,'lineno',0),path.name)
            # Static constants inside user-facing lists (truth/dare/mafia/name-family/etc.).
            if isinstance(n,ast.Constant) and isinstance(n.value,str) and _bb_studio_is_ui_string(n.value):
                val=n.value
                if len(val)>=4 and not val.strip().startswith(('r\'', 'f\'')):
                    k=('text',val)
                    if k not in seen: seen.add(k); await _bb_studio_register_literal(val,'text',getattr(n,'lineno',0),path.name)
        await _bb_ui_refresh()
        return len(seen)
    except Exception as exc:
        log.exception('studio exhaustive scan failed: %s',exc); return 0

# Dynamic replacement: static chunks registered by the AST scanner are also
# applied to runtime-rendered f-strings.
def _bb_studio_apply_text(value):
    value=_bb_no_premium_markup(value)
    if not value: return value
    exact=_BB_UI_CACHE.get(('text',value))
    if exact and exact!=value: return exact
    # Replace only sufficiently distinctive custom entries to avoid changing
    # generic one-word content accidentally.
    try:
        for (kind,original),custom in list(_BB_UI_CACHE.items()):
            if kind!='text' or not custom or custom==original or len(original.strip())<5: continue
            if original in value: value=value.replace(original,custom)
    except Exception: pass
    return value

# Keep button behaviour/callbacks untouched while changing only visible labels.
_BB_STUDIO_OLD_BTN=btn
def btn(text,data=None,url=None,style=None):
    # Final button constructor: normal Unicode emoji are allowed; Telegram custom
    # emoji IDs are never injected automatically. Functionality is unchanged.
    shown=_bb_studio_apply_text(text)
    kwargs={'text':_bb_no_premium_markup(shown),'callback_data':data,'url':url}
    if style is not None: kwargs['style']=style
    # Custom emoji is allowed only when the owner explicitly saved an ID for
    # this exact button; there is no built-in ID in the source code.
    eid=_BB_UI_EMOJI_CACHE.get(('button',str(text or ''))) or _BB_UI_EMOJI_CACHE.get(('button',str(shown or '')))
    if eid: kwargs['icon_custom_emoji_id']=str(eid)
    try:
        return InlineKeyboardButton(**kwargs)
    except TypeError:
        kwargs.pop('icon_custom_emoji_id',None)
        kwargs.pop('style',None)
        return InlineKeyboardButton(**kwargs)

