# -----------------------------------------------------------------------------
# Currency service: configurable API, default CoinGecko-compatible endpoint.
# Supports "16 ton", "16 TON", "16 تون" and common symbols. Toman is IRR/10.
# -----------------------------------------------------------------------------
_BB_COIN_IDS={'ton':'the-open-network','تون':'the-open-network','btc':'bitcoin','بیتکوین':'bitcoin','eth':'ethereum','اتریوم':'ethereum','usdt':'tether','usd':'usd','دلار':'usd','eur':'eur','یورو':'eur'}
async def _bb_currency_price(asset):
    import urllib.parse, urllib.request, json as _json
    asset=str(asset or '').strip().lower()
    api=await _bb_api_get('CURRENCY_API_URL','https://api.coingecko.com/api/v3')
    key=await _bb_api_get('CURRENCY_API_KEY','')
    aid=_BB_COIN_IDS.get(asset,asset)
    if aid in {'usd','eur'}:
        return 1.0 if aid=='usd' else None
    url=api.rstrip('/')+'/simple/price?'+urllib.parse.urlencode({'ids':aid,'vs_currencies':'usd,irr'})
    req=urllib.request.Request(url,headers={'User-Agent':'Bilbilak/2.0','x-cg-demo-api-key':key} if key else {'User-Agent':'Bilbilak/2.0'})
    raw=await asyncio.to_thread(lambda: urllib.request.urlopen(req,timeout=12).read())
    data=_json.loads(raw.decode('utf-8','ignore')); row=data.get(aid) or {}
    return {'usd':float(row.get('usd') or 0),'irr':float(row.get('irr') or 0)}

def _bb_parse_currency_query(text):
    m=re.search(r'(\d+(?:\.\d+)?)\s*([A-Za-z]+|[\u0600-\u06ff]+)',str(text or ''),re.I)
    if not m:return None
    return float(m.group(1)),m.group(2).lower()

async def _bb_currency_reply(update,context):
    import urllib.request, urllib.parse, json as _json
    msg=getattr(update,'effective_message',None)
    if not msg:return False
    q=_bb_parse_currency_query(msg.text or '')
    if not q:return False
    amount,symbol=q
    try:
        price=await _bb_currency_price(symbol)
        if isinstance(price,dict): usd=price['usd']; irr=price['irr']
        else: usd=float(price or 0); irr=0
        toman=irr/10 if irr else 0
        total_usd=amount*usd; total_toman=amount*toman
        lines=[f'💱 <b>{amount:g} {safe_text(symbol,20).upper()}</b>',f'💵 هر واحد: <b>{usd:,.6f} دلار</b>']
        if toman: lines.append(f'💰 هر واحد: <b>{toman:,.0f} تومان</b>')
        lines.append(f'📦 ارزش {amount:g}: <b>{total_usd:,.2f} دلار</b>')
        if toman: lines.append(f'🇮🇷 ارزش {amount:g}: <b>{total_toman:,.0f} تومان</b>')
        # Optional market mini-chart.
        try:
            import io
            from PIL import Image,ImageDraw
            api=await _bb_api_get('CURRENCY_API_URL','https://api.coingecko.com/api/v3'); aid=_BB_COIN_IDS.get(symbol,symbol)
            u=api.rstrip('/')+f'/coins/{urllib.parse.quote(aid)}/market_chart?vs_currency=usd&days=1'
            req=urllib.request.Request(u,headers={'User-Agent':'Bilbilak/2.0'})
            raw=await asyncio.to_thread(lambda: urllib.request.urlopen(req,timeout=12).read()); dat=_json.loads(raw.decode('utf8','ignore'))
            vals=[float(x[1]) for x in dat.get('prices',[]) if len(x)>1]
            if vals:
                im=Image.new('RGB',(900,420),'#10131b'); d=ImageDraw.Draw(im); lo,hi=min(vals),max(vals); span=(hi-lo) or 1
                pts=[]
                for i,v in enumerate(vals): pts.append((40+i*820/max(1,len(vals)-1),380-(v-lo)/span*320))
                d.line(pts,fill='#4dd0e1',width=5); d.text((40,20),f'{symbol.upper()} / USD',fill='white')
                bio=io.BytesIO();bio.name='bilbilak_currency_chart.png';im.save(bio,'PNG');bio.seek(0)
                await msg.reply_photo(bio,caption='📈 نمودار ۲۴ ساعت اخیر\n\n'+'\n'.join(lines),parse_mode='HTML'); return True
        except Exception as chart_exc: log.debug('currency chart skipped: %s',chart_exc)
        await msg.reply_text('\n'.join(lines),parse_mode='HTML'); return True
    except Exception as exc:
        await msg.reply_text('⚠️ سرویس ارز در دسترس نیست؛ API را از /apis تنظیم کن.'); log.warning('currency failed: %s',exc); return True

