async def _bb_studio_v2_callback(update,context):
    q=getattr(update,'callback_query',None)
    if not q or not str(q.data or '').startswith('sv2:'): return False
    if not await _bb_owner_gate(update): await q.answer('⛔ فقط مالک در PV.',show_alert=True); return True
    await _bb_studio_v2_schema(); await q.answer()
    d=str(q.data)
    if d=='sv2:coverage':
        r=await DBX.execute('SELECT kind,COUNT(*) n FROM bb_ui_texts GROUP BY kind',fetch=True)
        stats={str(x['kind']):int(x['n']) for x in r}; total=sum(stats.values())
        await q.edit_message_text(f'📊 <b>پوشش کامل UI</b>\n\n📝 متن: {stats.get("text",0)}\n🔘 دکمه: {stats.get("button",0)}\n📦 مجموع: {total}\n\nاسکن کل فایل انجام می‌شود.',parse_mode='HTML',reply_markup=keyboard([[btn('🔄 اسکن کامل','sv2:rescan')],[btn('🔙 طراحی','sv2:home')]])); return True
    if d=='sv2:rescan':
        n=await _bb_studio_scan_everything(); await q.answer(f'اسکن شد: {n} مورد',show_alert=True); await _bb_studio_command(type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat,'effective_message':q.message})(),context); return True
    if d=='sv2:home': await _bb_studio_command(type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat,'effective_message':q.message})(),context); return True
    if d.startswith('sv2:cat:') or d.startswith('sv2:text:') or d.startswith('sv2:button:'):
        # قبل از نمایش، کل سورس دوباره اسکن می‌شود تا هیچ متن/دکمه‌ای جا نماند.
        await _bb_studio_scan_everything()
        parts=d.split(':'); kind='text'; cat=None; page=0
        if parts[1]=='text': kind='text'; page=int(parts[2])
        elif parts[1]=='button': kind='button'; page=int(parts[2])
        else: cat=parts[2]; page=int(parts[3]); kind='button'
        where='WHERE kind=?'; params=[kind]
        if cat: where+=' AND category=?'; params.append(cat)
        total_row=await DBX.one(f'SELECT COUNT(*) c FROM bb_ui_texts {where}',tuple(params))
        total=int(total_row['c'] or 0) if total_row else 0
        page_size=12; offset=page*page_size
        rows=await DBX.execute(f'SELECT key,original,custom FROM bb_ui_texts {where} ORDER BY CASE WHEN source_line>0 THEN source_line ELSE 999999 END, original LIMIT ? OFFSET ?',(*params,page_size,offset),fetch=True)
        kb=[]
        for r in rows:
            original=str(r['original'] or ''); shown=str(r['custom'] or '') or original
            clean=shown.replace('\n',' '); label=clean[:52]+('…' if len(clean)>52 else '')
            kb.append([btn(label,f'sv2:edit:{r["key"]}')])
        nav=[]
        if page>0: nav.append(btn('⬅️ قبلی',f'sv2:{"cat:"+cat if cat else kind}:{page-1}'))
        if offset+len(rows)<total: nav.append(btn('بعدی ➡️',f'sv2:{"cat:"+cat if cat else kind}:{page+1}'))
        if nav: kb.append(nav)
        kb.append([btn('🔄 اسکن و نمایش دوباره','sv2:rescan')])
        kb.append([btn('🔙 طراحی','sv2:home')])
        title=('🔘 دکمه‌ها' if kind=='button' else '📝 متن‌ها')+(f' — {_BB_UI_CATEGORIES.get(cat,cat)}' if cat else '')
        await q.edit_message_text(f'<b>{title}</b>\n\nنمایش {min(offset+1,total) if total else 0} تا {min(offset+len(rows),total)} از {total} مورد\nهر مورد از خود کد اسکن شده و قابل ویرایش است.',parse_mode='HTML',reply_markup=keyboard(kb)); return True
    if d.startswith('sv2:edit:'):
        key=d.split(':',2)[2]; r=await DBX.one('SELECT original,custom,kind,emoji_id,media_type FROM bb_ui_texts WHERE key=?',(key,))
        if not r: return True
        context.user_data['sv2_edit']=key
        await q.edit_message_text('✏️ <b>ویرایش مورد</b>\n\nفعلی:\n<code>'+safe_text(r['custom'] or r['original'],1800)+'</code>\n\nپیام جدید را بفرست. برای حفظ متن اصلی: <code>اصلی</code>\nبرای تنظیم ایموجی پرمیوم فقط ID را بفرست: <code>emoji 123456</code>\nبرای پاک کردن ایموجی: <code>emoji off</code>',parse_mode='HTML'); return True
    if d.startswith('sv2:apis:'):
        rows=await DBX.execute('SELECT key,value FROM bb_api_settings ORDER BY key',fetch=True); txt='🔑 <b>APIها</b>\n\n'+('\n'.join(f'{r["key"]}: {"🟢" if r["value"] else "🔴"}' for r in rows) or 'خالی')
        await q.edit_message_text(txt+'\n\n<code>api KEY VALUE</code>',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 طراحی','sv2:home')]])); return True
    if d.startswith('sv2:players:'):
        page=int(d.split(':')[-1]); rows=await DBX.execute('SELECT name FROM bb_player_data ORDER BY name LIMIT 30 OFFSET ?', (page*30,),fetch=True); kb=[[btn(str(r['name']),f'sv2:pedit:{page}:{i}')] for i,r in enumerate(rows)]; kb.append([btn('⬅️','sv2:players:'+str(max(0,page-1))),btn('➡️','sv2:players:'+str(page+1))]); kb.append([btn('🔙 طراحی','sv2:home')]); await q.edit_message_text('👤 <b>بازیکنان</b>\nفقط ایموجی پیش‌فرض خالی است؛ اطلاعات پایه در DB قرار دارد.',parse_mode='HTML',reply_markup=keyboard(kb)); return True
    if d.startswith('sv2:teams:'):
        page=int(d.split(':')[-1]); rows=await DBX.execute('SELECT name FROM bb_team_data ORDER BY name LIMIT 30 OFFSET ?', (page*30,),fetch=True); kb=[[btn(str(r['name']),f'sv2:teamedit:{r["name"]}')] for r in rows]; kb.append([btn('🔙 طراحی','sv2:home')]); await q.edit_message_text('🏆 <b>تیم‌ها و جام‌ها</b>\nبرای هر تیم نام همه جام‌ها در فیلد trophies ذخیره می‌شود.',parse_mode='HTML',reply_markup=keyboard(kb)); return True
    if d.startswith('sv2:voice:'):
        await q.edit_message_text('🎙 <b>سخنگو</b>\n\nثبت با دستور <code>voice KEYWORD RESPONSE</code> یا ارسال رسانه بعد از <code>voice KEYWORD</code>.',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 طراحی','sv2:home')]])); return True
    if d.startswith('sv2:game:'):
        game=d.split(':')[2]; await q.edit_message_text(f'🎭 <b>{game}</b>\n\nبرای ثبت آیتم: <code>{game} متن</code>',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 طراحی','sv2:home')]])); return True
    if d.startswith('sv2:feature:'):
        await q.edit_message_text('🧠 <b>قابلیت جدید</b>\n\n<code>feature عنوان | توضیح | UI</code> را در PV بفرست.',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 طراحی','sv2:home')]])); return True
    return True

async def _bb_studio_v2_message(update,context):
    if not await _bb_owner_gate(update): return False
    msg=update.effective_message; t=str(getattr(msg,'text','') or '').strip()
    await _bb_studio_v2_schema()
    # Text editor state.
    key=context.user_data.pop('sv2_edit',None)
    if key:
        if t.lower().startswith('emoji '):
            eid=t.split(' ',1)[1].strip(); eid='' if eid.lower()=='off' else eid
            await DBX.execute('UPDATE bb_ui_texts SET emoji_id=?,updated_at=? WHERE key=?',(eid,now_ts(),key)); await _bb_ui_refresh(); await msg.reply_text('✅ ایموجی تنظیم شد.'); return True
        val='' if normalize(t)=='اصلی' else t
        await DBX.execute('UPDATE bb_ui_texts SET custom=?,updated_at=? WHERE key=?',(val,now_ts(),key)); await _bb_ui_refresh(); await msg.reply_text('✅ متن ذخیره شد.'); return True
    # API settings.
    if re.match(r'^api\s+',t,re.I):
        p=t.split(None,2)
        if len(p)==3: await _bb_api_set(p[1],p[2]); await msg.reply_text('✅ API ذخیره شد.'); return True
    # Voice rules, including media messages.
    if re.match(r'^voice\s+',t,re.I):
        rest=t.split(None,1)[1]; p=rest.split(None,1); trigger=p[0].strip(); response=p[1].strip() if len(p)>1 else ''
        await DBX.execute('INSERT OR REPLACE INTO bb_voice_replies(trigger,response_type,response_value,updated_at) VALUES(?,?,?,?)',(trigger,'text',response,now_ts())); await msg.reply_text('✅ پاسخ سخنگو ذخیره شد.'); return True
    # Game list registration.
    m=re.match(r'^(truth|dare|mafia|family)\s+(.+)$',t,re.I)
    if m:
        await DBX.execute('INSERT OR IGNORE INTO bb_game_lists(game,item,created_at) VALUES(?,?,?)',(m.group(1).lower(),m.group(2).strip(),now_ts())); await msg.reply_text('✅ آیتم بازی ثبت شد.'); return True
    # AI feature spec.
    if t.lower().startswith('feature '):
        raw=t[8:].strip(); parts=[x.strip() for x in raw.split('|')]
        await DBX.execute('INSERT INTO bb_feature_specs(title,description,ui_text,buttons,created_at,updated_at) VALUES(?,?,?,?,?,?)',(parts[0] if parts else raw,parts[1] if len(parts)>1 else '',parts[2] if len(parts)>2 else '',parts[3] if len(parts)>3 else '',now_ts(),now_ts())); await msg.reply_text('✅ قابلیت برای تحلیل/طراحی AI ذخیره شد.'); return True
    # Forwarded/sent media after "voice KEYWORD". Telegram media objects can be
    # stored by file_id without exposing the original source message to users.
    if getattr(msg,'photo',None) or getattr(msg,'voice',None) or getattr(msg,'sticker',None) or getattr(msg,'animation',None):
        pending=context.user_data.get('sv2_media_trigger')
        if pending:
            typ='photo' if msg.photo else ('voice' if msg.voice else ('sticker' if msg.sticker else 'animation'))
            obj=msg.photo[-1] if typ=='photo' else getattr(msg,typ)
            fid=getattr(obj,'file_id','')
            await DBX.execute('UPDATE bb_voice_replies SET response_type=?,media_id=? WHERE trigger=?',(typ,fid,pending)); context.user_data.pop('sv2_media_trigger',None); await msg.reply_text('✅ رسانه پاسخ ذخیره شد.'); return True
    return False


# Final group-link behaviour: never reuse the old stale group-link payload.
async def _bb_group_link_callback(update,context):
    q=getattr(update,'callback_query',None); d=str(getattr(q,'data','') or '')
    if not q or not d.startswith('bblink:'): return False
    _,cid,kind=d.split(':',2); cid=int(cid)
    try: member=await context.bot.get_chat_member(cid,q.from_user.id)
    except Exception: await q.answer('دسترسی ادمین بررسی نشد.',show_alert=True); return True
    if getattr(member,'status','') not in {ChatMemberStatus.ADMINISTRATOR,ChatMemberStatus.OWNER}: await q.answer('⛔ فقط ادمین گروه.',show_alert=True); return True
    try: inv=(await context.bot.create_chat_invite_link(cid,creates_join_request=False)).invite_link
    except Exception:
        try: inv=await context.bot.export_chat_invite_link(cid)
        except Exception: await q.answer('ساخت لینک ممکن نشد.',show_alert=True); return True
    chat=await context.bot.get_chat(cid)
    title=safe_text(getattr(chat,'title','گروه'),120)
    bio=safe_text(getattr(chat,'description','') or 'بدون بیو',500)
    owner_id='نامشخص'
    try:
        admins=await context.bot.get_chat_administrators(cid)
        own=next((a for a in admins if getattr(a,'status','')==ChatMemberStatus.OWNER),None)
        if own: owner_id=str(own.user.id)
    except Exception: pass
    def _gl(k, fallback):
        try: return _bb_ui_get(fallback,'text')
        except Exception: return fallback
    caption=(f'{_gl("اطلاعات و لینک گروه","🔗 اطلاعات و لینک گروه")}\n\n'
             f'📝 {_gl("بیو","بیو")}: {bio}\n'
             f'👑 {_gl("آیدی مالک","آیدی مالک")}: <code>{owner_id}</code>\n'
             f'🔗 {_gl("لینک گروه","لینک گروه")}: {inv}')
    if kind=='qr':
        qr='https://quickchart.io/qr?size=700&text='+quote_plus(inv)
        await q.message.reply_photo(qr,caption=caption,parse_mode='HTML')
    elif kind=='photo':
        photo=None
        try:
            if getattr(chat,'photo',None):
                f=await context.bot.get_file(chat.photo.big_file_id); photo=f.file_path
        except Exception: photo=None
        if photo: await q.message.reply_photo(photo,caption=caption,parse_mode='HTML')
        else: await q.message.reply_text(caption,parse_mode='HTML')
    elif kind=='pv':
        try:
            await context.bot.send_message(q.from_user.id,caption,parse_mode='HTML')
            await q.answer('✅ لینک کامل به PV تو ارسال شد.')
        except Exception: await q.answer('ابتدا ربات را در PV استارت کن.',show_alert=True)
        return True
    else:
        await q.message.reply_text(caption,parse_mode='HTML',reply_markup=keyboard([[btn('🔗 باز کردن لینک',url=inv)]]))
    await q.answer(); return True


# -----------------------------------------------------------------------------
# Final owner-only build layer. Commands NEVER register in groups.
# -----------------------------------------------------------------------------
_BB_BUILD_BEFORE_STUDIO_V2=build_application
def build_application(token:str)->Application:
    app=_BB_BUILD_BEFORE_STUDIO_V2(token)
    app.add_handler(CommandHandler(['design','tarahi'],_bb_studio_command),group=-990010)
    app.add_handler(CommandHandler(['apis','api'],_bb_studio_api_command),group=-990011)
    app.add_handler(CommandHandler(['voice','sokhangoo'],_bb_studio_voice_command),group=-990012)
    app.add_handler(CommandHandler(['gameset','lists'],_bb_studio_game_command),group=-990013)
    app.add_handler(CommandHandler(['feature','newfeature'],_bb_studio_feature_command),group=-990014)
    app.add_handler(CallbackQueryHandler(_bb_studio_v2_callback,pattern=r'^sv2:'),group=-990020)
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,_bb_voice_runtime_router),group=-990019)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_id_runtime_router),group=-990018)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_player_runtime_router),group=-990017)
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,_bb_studio_v2_message),group=-990021)
    return app

# Ensure source scan and seed data run before the app starts.
_BB_STUDIO_OLD_POST_INIT=post_init
async def post_init(application):
    await _bb_studio_v2_schema()
    await _bb_seed_players()
    await _bb_seed_teams()
    await _bb_studio_scan_everything()
    if _BB_STUDIO_OLD_POST_INIT: await _BB_STUDIO_OLD_POST_INIT(application)


async def _bb_voice_runtime_router(update,context):
    msg=getattr(update,'effective_message',None)
    if not msg or not getattr(msg,'text',None): return False
    await _bb_studio_v2_schema(); trigger=normalize(str(msg.text or '')).strip()
    row=await DBX.one('SELECT response_type,response_value,media_id,caption FROM bb_voice_replies WHERE trigger=?',(trigger,))
    if not row: return False
    typ=str(row['response_type'] or 'text'); media=row['media_id'] or ''
    try:
        if typ=='photo' and media: await msg.reply_photo(media,caption=_bb_studio_apply_text(row['caption'] or ''),parse_mode='HTML' if row['caption'] else None)
        elif typ=='voice' and media: await msg.reply_voice(media,caption=_bb_studio_apply_text(row['caption'] or ''),parse_mode='HTML' if row['caption'] else None)
        elif typ=='sticker' and media: await msg.reply_sticker(media)
        elif typ=='animation' and media: await msg.reply_animation(media,caption=_bb_studio_apply_text(row['caption'] or ''),parse_mode='HTML' if row['caption'] else None)
        else: await msg.reply_text(_bb_studio_apply_text(row['response_value'] or ''))
        return True
    except Exception as exc: log.warning('voice runtime reply failed: %s',exc); return False



async def _bb_reply_custom_emoji_text(msg,text,emoji_id=None,emoji_char='◉'):
    if not emoji_id:
        await msg.reply_text(text); return
    pos=text.find(emoji_char)
    if pos<0:
        await msg.reply_text(text); return
    try:
        ent=telegram.MessageEntity(type='custom_emoji',offset=pos,length=len(emoji_char),custom_emoji_id=str(emoji_id))
        await msg.reply_text(text,entities=[ent]); return
    except Exception:
        await msg.reply_text(text)

async def _bb_player_runtime_router(update,context):
    msg=getattr(update,'effective_message',None)
    if not msg or not getattr(msg,'text',None): return False
    q=normalize(str(msg.text or '')).strip()
    if len(q)<3: return False
    await _bb_studio_v2_schema()
    # Direct name lookup, plus common aliases.
    aliases={'رونالدو':'کریستیانو رونالدو','cristiano ronaldo':'کریستیانو رونالدو','مسی':'لیونل مسی','messi':'لیونل مسی','ronaldo':'کریستیانو رونالدو','mbappe':'کیلیان امباپه','امباپه':'کیلیان امباپه','neymar':'نیمار','نیمار':'نیمار'}
    name=aliases.get(q.lower(),q)
    row=await DBX.one('SELECT * FROM bb_player_data WHERE lower(name)=lower(?)',(name,))
    if not row: return False
    txt=(f'◉ <b>{safe_text(row["name"],100)}</b>\n'
         f'🌍 ملیت: {safe_text(row["nationality"],80) or "—"}\n'
         f'⚽ تیم فعلی: {safe_text(row["current_team"],100) or "—"}\n'
         f'🔥 دوران اوج: {safe_text(row["prime_team"],100) or "—"} / {safe_text(row["prime_year"],20) or "—"}\n'
         f'🎂 سن: {safe_text(row["age"],10) or "—"}\n'
         f'👶 فرزند: {safe_text(row["children"],20) or "—"}\n'
         f'🌐 جام جهانی: {safe_text(row["world_cups"],20) or "—"}\n'
         f'🏳️ جام‌های ملی: {safe_text(row["national_trophies"],20) or "—"}\n'
         f'🏆 جام‌های باشگاهی: {safe_text(row["club_trophies"],20) or "—"}\n'
         f'💍 همسر: {safe_text(row["spouse"],100) or "—"}')
    await _bb_reply_custom_emoji_text(msg,txt,row['emoji_id'] or '')
    return True

async def _bb_id_runtime_router(update,context):
    """ID/آیدی command: show the live text profile card, not the image profile card.

    The image card is reserved for «پروفایل».  ID aliases intentionally use the
    existing group-profile/stat format and stop propagation so legacy routers
    cannot send a second response.
    """
    msg=getattr(update,'effective_message',None); user=getattr(update,'effective_user',None)
    chat=getattr(update,'effective_chat',None)
    if not msg or not user: return False
    command=normalize(str(getattr(msg,'text','') or '')).strip().lower()
    if command not in {'id','آیدی','ایدی','شناسه'}: return False

    # Keep the live counters current even though this high-priority handler
    # intentionally stops the older message routers from answering again.
    try:
        if chat and getattr(chat,'type','') != 'private':
            key=_bb_stats_message_key(chat.id,getattr(msg,'message_id',0))
            if key not in _BB_STATS_COUNTED_MESSAGES: bbx_stat(chat.id,user.id,'messages',1); _BB_STATS_COUNTED_MESSAGES.add(key)
    except Exception:
        pass

    try:
        # Reply-to-user support is preserved: «آیدی» on someone's message
        # shows that user's current stats.
        target=bbx_user_target(update) or user
        txt=await bbx_profile_text(update,target)
        await msg.reply_text(txt,parse_mode='HTML')
    except Exception as exc:
        log.warning('id profile route failed: %s',exc)
        try:
            await msg.reply_text(f'⚠️ نمایش آیدی انجام نشد: {safe_text(str(exc),180)}')
        except Exception:
            pass
    raise ApplicationHandlerStop


# -----------------------------------------------------------------------------
# Currency router is inserted at the end so it can understand both Persian and
# Latin forms without changing the older tools.
# -----------------------------------------------------------------------------
_BB_CURRENCY_OLD_ROUTER=message_router
async def message_router(update,context):
    msg=getattr(update,'effective_message',None)
    text=getattr(msg,'text','') if msg else ''
    # Do not hijack ordinary words; only explicit amount + currency symbols.
    if re.search(r'\d+(?:\.\d+)?\s*(?:TON|تون|BTC|بیتکوین|ETH|اتریوم|USDT|USD|دلار|EUR|یورو)\b',str(text or ''),re.I):
        if await _bb_currency_reply(update,context): return True
    return await _BB_CURRENCY_OLD_ROUTER(update,context)

# Date card: single-send guard per update to stop duplicate date messages.
_BB_DATE_SENT_GUARD=set()
_BB_OLD_SEND_DATE_CARD_V2=globals().get('_bb_send_date_card')
async def _bb_send_date_card(update,context):
    marker=(getattr(getattr(update,'effective_chat',None),'id',0),getattr(getattr(update,'effective_message',None),'message_id',0))
    if marker in _BB_DATE_SENT_GUARD: return True
    _BB_DATE_SENT_GUARD.add(marker)
    if len(_BB_DATE_SENT_GUARD)>5000: _BB_DATE_SENT_GUARD.clear()
    if _BB_OLD_SEND_DATE_CARD_V2: return await _BB_OLD_SEND_DATE_CARD_V2(update,context)
    return True

# Rebind the final music resolver with strict numeric normalization. This is the
# compatibility fix for yt-dlp builds that return duration/limits as strings.
_BB_OLD_MUSIC_RESOLVE_SOURCE_V2=globals().get('_bb_music_resolve_source')
async def _bb_music_resolve_source(url,is_video=False,is_live=False):
    if not _BB_OLD_MUSIC_RESOLVE_SOURCE_V2: return url,{}
    try:
        direct,info=await _BB_OLD_MUSIC_RESOLVE_SOURCE_V2(url,bool(is_video),bool(is_live))
        if isinstance(info,dict):
            for k in ('duration','width','height','fps'):
                if k in info and info[k] is not None:
                    try: info[k]=float(info[k]) if '.' in str(info[k]) else int(float(info[k]))
                    except Exception: pass
        return direct,info
    except TypeError as exc:
        # Retry using the safest audio format used by 1.py when yt-dlp's
        # selector encounters mixed string/int metadata.
        if _music_yt_dlp is None: raise
        def _retry():
            opts={'quiet':True,'no_warnings':True,'noplaylist':True,'skip_download':True,'format':'bestaudio/best'}
            with _music_yt_dlp.YoutubeDL(opts) as ydl:
                info=ydl.extract_info(str(url),download=False) or {}
                return info.get('url') or str(url),info
        try: return await asyncio.to_thread(_retry)
        except Exception: raise exc



# =============================================================================
# BILBILAK PLAYER STATS V3 + DIGIT CUSTOM EMOJI + MULTI-SOURCE MUSIC V3
# =============================================================================
# همه مقادیر آماری به صورت عدد صحیح در DB ذخیره می‌شوند؛ نمایش می‌تواند با
# custom emoji رقم‌های 0..9 انجام شود، بدون اینکه مقدار واقعی عدد تغییر کند.

async def _bb_player_stats_schema():
    await _bb_studio_v2_schema()
    await DBX.execute("CREATE TABLE IF NOT EXISTS bb_player_stats(player_name TEXT NOT NULL,stat_key TEXT NOT NULL,value INTEGER DEFAULT 0,PRIMARY KEY(player_name,stat_key))")
    # Global Premium-Emoji registry: these mappings are intentionally NOT
    # scoped to an owner/user. Once the owner registers an emoji, every feature
    # in this bot reads the same mapping from the shared bot database.
    await DBX.execute("CREATE TABLE IF NOT EXISTS bb_digit_emojis(digit INTEGER PRIMARY KEY,emoji_id TEXT DEFAULT '',updated_at INTEGER DEFAULT 0)")
    await DBX.execute("CREATE TABLE IF NOT EXISTS bb_char_emojis(char TEXT PRIMARY KEY,emoji_id TEXT DEFAULT '',updated_at INTEGER DEFAULT 0)")
    await DBX.execute("CREATE TABLE IF NOT EXISTS bb_emoji_input_state(owner_id TEXT PRIMARY KEY,target_type TEXT NOT NULL,target TEXT NOT NULL)")
    # Keep compatibility with databases created by an earlier version.
    try: await DBX.execute("ALTER TABLE bb_digit_emojis ADD COLUMN updated_at INTEGER DEFAULT 0")
    except Exception: pass
    try: await DBX.execute("ALTER TABLE bb_char_emojis ADD COLUMN updated_at INTEGER DEFAULT 0")
    except Exception: pass
    await DBX.execute("CREATE INDEX IF NOT EXISTS idx_bb_player_stats_name ON bb_player_stats(player_name)")
    # No Premium Emoji IDs are hardcoded here.
    # The owner registers every digit/character from the owner panel.
    try:
        for i in range(10):
            await DBX.execute('INSERT OR IGNORE INTO bb_digit_emojis(digit,emoji_id) VALUES(?,?)',(i,''))
        for ch in 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyzاآبپتثجچحخدذرزژسشصضطظعغفقکگلمنوهیءئؤإأۀةى':
            await DBX.execute('INSERT OR IGNORE INTO bb_char_emojis(char,emoji_id) VALUES(?,?)',(ch,''))
        for ch in '۰۱۲۳۴۵۶۷۸۹':
            await DBX.execute('INSERT OR IGNORE INTO bb_char_emojis(char,emoji_id) VALUES(?,?)',(ch,''))
    except Exception:
        pass

_BB_PLAYER_STAT_LABELS={
    'apps':'بازی', 'starts':'فیکس', 'minutes':'دقیقه', 'goals':'گل',
    'assists':'پاس گل', 'yellow':'کارت زرد', 'red':'کارت قرمز',
    'second_yellow':'زرد دوم', 'clean_sheets':'کلین‌شیت',
    'penalties':'پنالتی', 'penalty_goals':'گل پنالتی', 'free_kick_goals':'گل آزاد',
    'hat_tricks':'هت‌تریک', 'shots':'شوت', 'shots_on_target':'شوت در چارچوب',
    'key_passes':'پاس کلیدی', 'dribbles':'دریبل موفق', 'tackles':'تکل موفق',
    'interceptions':'قطع توپ', 'offsides':'آفساید', 'fouls':'خطا',
    'fouls_won':'خطای گرفته‌شده',
}

async def _bb_emoji_input_set(owner_id,target_type,target):
    await _bb_player_stats_schema()
    await DBX.execute('INSERT OR REPLACE INTO bb_emoji_input_state(owner_id,target_type,target) VALUES(?,?,?)',(str(owner_id),str(target_type),str(target)))

async def _bb_emoji_input_get(owner_id):
    await _bb_player_stats_schema()
    row=await DBX.one('SELECT target_type,target FROM bb_emoji_input_state WHERE owner_id=?',(str(owner_id),))
    return (str(row['target_type']),str(row['target'])) if row else None

async def _bb_emoji_input_clear(owner_id):
    await _bb_player_stats_schema()
    await DBX.execute('DELETE FROM bb_emoji_input_state WHERE owner_id=?',(str(owner_id),))

def _bb_custom_emoji_id_from_message(msg):
    ents=list(getattr(msg,'entities',None) or [])
    customs=[e for e in ents if str(getattr(e,'type','')).lower() in ('custom_emoji','customemoji') and getattr(e,'custom_emoji_id',None)]
    if len(customs)!=1:
        return ''
    return str(getattr(customs[0],'custom_emoji_id','') or '')

async def _bb_numemoji_set(digit,eid):
    await _bb_player_stats_schema()
    d=int(digit)
    if d<0 or d>9: raise ValueError('رقم باید بین 0 تا 9 باشد.')
    await DBX.execute('INSERT OR REPLACE INTO bb_digit_emojis(digit,emoji_id,updated_at) VALUES(?,?,?)',(d,str(eid or ''),now_ts()))

async def _bb_numemoji_map():
    await _bb_player_stats_schema()
    rows=await DBX.execute('SELECT digit,emoji_id FROM bb_digit_emojis ORDER BY digit',fetch=True)
    return {int(r['digit']):str(r['emoji_id'] or '') for r in rows}

async def _bb_char_emoji_set(ch,eid):
    await _bb_player_stats_schema()
    ch=str(ch or '')
    if len(ch)!=1: raise ValueError('فقط یک حرف/کاراکتر وارد کن.')
    await DBX.execute('INSERT OR REPLACE INTO bb_char_emojis(char,emoji_id,updated_at) VALUES(?,?,?)',(ch,'' if str(eid).lower()=='off' else str(eid or ''),now_ts()))

async def _bb_char_emoji_map():
    await _bb_player_stats_schema()
    rows=await DBX.execute('SELECT char,emoji_id FROM bb_char_emojis ORDER BY char',fetch=True)
    return {str(r['char']):str(r['emoji_id'] or '') for r in rows}

def _bb_utf16_len(ch):
    return len(str(ch).encode('utf-16-le'))//2

async def _bb_number_entities(text, base_offset=0):
    """Entities for individual ASCII digits. Numeric value remains exact."""
    mp=await _bb_numemoji_map()
    entities=[]; i=0; utf=0
    for ch in str(text):
        if ch.isdigit() and '0' <= ch <= '9' and mp.get(int(ch)):
            entities.append(telegram.MessageEntity(type='custom_emoji',offset=base_offset+utf,length=1,custom_emoji_id=mp[int(ch)]))
        utf += _bb_utf16_len(ch); i += 1
    return entities

async def _bb_reply_player_stats(msg, txt, player_emoji=''):
    # The stats text is deliberately made of ASCII 0..9. Custom emoji entities
    # only change the glyph; the underlying value remains the exact number.
    ents=[]
    if player_emoji:
        pos=txt.find('◉')
        if pos>=0: ents.append(telegram.MessageEntity(type='custom_emoji',offset=pos,length=1,custom_emoji_id=str(player_emoji)))
    ents.extend(await _bb_number_entities(txt))
    try:
        await msg.reply_text(txt,parse_mode='HTML',entities=ents or None)
    except Exception:
        await msg.reply_text(txt,parse_mode='HTML')

async def _bb_get_player_stats(name):
    await _bb_player_stats_schema()
    rows=await DBX.execute('SELECT stat_key,value FROM bb_player_stats WHERE player_name=? ORDER BY stat_key',(name,),fetch=True)
    return {str(r['stat_key']):int(r['value'] or 0) for r in rows}

async def _bb_set_player_stat(name,key,value):
    await _bb_player_stats_schema()
    if key not in _BB_PLAYER_STAT_LABELS: return False
    v=int(str(value).replace(',','').strip())
    if v<0: raise ValueError('آمار منفی مجاز نیست.')
    await DBX.execute('INSERT OR REPLACE INTO bb_player_stats(player_name,stat_key,value) VALUES(?,?,?)',(name,key,v))
    return True

async def _bb_player_upsert_from_owner(raw,msg):
    parts=[x.strip() for x in raw.split('|')]
    if len(parts)<11:
        await msg.reply_text('فرمت ثبت بازیکن:\n<code>player نام | ملیت | تیم فعلی | تیم اوج | سال اوج | سن | فرزند | جام جهانی | جام ملی | جام باشگاهی | همسر</code>',parse_mode='HTML'); return True
    vals=parts[:11]
    await _bb_player_stats_schema()
    await DBX.execute('INSERT OR REPLACE INTO bb_player_data(name,nationality,current_team,prime_team,prime_year,age,children,world_cups,national_trophies,club_trophies,spouse,emoji_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,COALESCE((SELECT emoji_id FROM bb_player_data WHERE name=?),\'\'))',tuple(vals+[vals[0]]))
    await msg.reply_text('✅ اطلاعات واقعی/ثبت‌شده بازیکن در پنل ذخیره شد. حالا آمار دقیق را با <code>stat ...</code> ثبت کن.',parse_mode='HTML')
    return True

async def _bb_player_stat_command(raw,msg):
    parts=[x.strip() for x in raw.split('|')]
    if len(parts)<2:
        await msg.reply_text('فرمت:\n<code>stat نام بازیکن | goals=900 | assists=300 | yellow=20 | red=2</code>',parse_mode='HTML'); return True
    name=parts[0]
    row=await DBX.one('SELECT name FROM bb_player_data WHERE lower(name)=lower(?)',(name,))
    if not row:
        await msg.reply_text('❌ بازیکن پیدا نشد. اول با <code>player ...</code> ثبتش کن.',parse_mode='HTML'); return True
    done=[]
    for item in parts[1:]:
        if '=' not in item: continue
        k,v=[x.strip() for x in item.split('=',1)]
        k=k.lower()
        try:
            if await _bb_set_player_stat(name,k,v): done.append(f'{_BB_PLAYER_STAT_LABELS[k]}={int(v)}')
        except Exception: pass
    await msg.reply_text('✅ آمار ذخیره شد:\n'+('\n'.join(done) if done else 'هیچ کلید آماری معتبر نبود.'))
    return True

