# =============================================================================
# Music search V3: YouTube is not the only source. Google web search is used as
# an additional discovery source when GOOGLE_API_KEY + GOOGLE_CSE_ID are set.
# Any YouTube result shown by the music search is first tested with yt-dlp; if it
# cannot be extracted/playable, it is omitted from the result list.
# =============================================================================
async def _bb_google_music_search(query,limit=5):
    key=await _bb_api_get('GOOGLE_API_KEY',''); cx=await _bb_api_get('GOOGLE_CSE_ID','')
    if not key or not cx: return []
    try:
        import json as _j, urllib.parse as _up, urllib.request as _ur
        u='https://www.googleapis.com/customsearch/v1?'+_up.urlencode({'key':key,'cx':cx,'q':query+' music','num':min(10,int(limit))})
        raw=await asyncio.to_thread(lambda:_ur.urlopen(_ur.Request(u,headers={'User-Agent':'Bilbilak/3.0'}),timeout=10).read())
        data=_j.loads(raw.decode('utf-8','ignore')); out=[]
        for x in data.get('items',[]):
            url=x.get('link'); title=x.get('title') or 'بدون عنوان'
            if url: out.append({'id':'','title':title,'url':url,'duration':0,'thumbnail':'','uploader':x.get('displayLink',''),'source':'google'})
        return out
    except Exception as exc:
        log.debug('google music search failed: %s',exc); return []

async def _bb_music_playable(item):
    url=str(item.get('url') or '').strip()
    if not url or _music_yt_dlp is None: return False
    def _check():
        try:
            opts=_music_ydl_options(audio_only=True,download=False); opts['noplaylist']=True; opts['skip_download']=True
            with _music_yt_dlp.YoutubeDL(opts) as ydl:
                info=ydl.extract_info(url,download=False)
            return bool(info and (info.get('url') or info.get('requested_formats') or info.get('formats')))
        except Exception: return False
    return await asyncio.to_thread(_check)

_BB_OLD_MUSIC_MULTI_V3=globals().get('_bb_music_multisource_search')
async def _bb_music_multisource_search(query,limit=MUSIC_SEARCH_LIMIT,*,video=False):
    base=await _BB_OLD_MUSIC_MULTI_V3(query,limit=limit,video=video) if _BB_OLD_MUSIC_MULTI_V3 else []
    google=await _bb_google_music_search(query,limit=5)
    candidates=base+google
    # YouTube results are kept only when the actual resolver can extract them.
    checked=[]; seen=set()
    for item in candidates:
        url=str(item.get('url') or '')
        key=url.lower()
        if not key or key in seen: continue
        if str(item.get('source','')).lower()=='youtube':
            if not await _bb_music_playable(item): continue
        seen.add(key); checked.append(item)
        if len(checked)>=max(1,int(limit))*3: break
    return checked

_music_search_online = _music_search_online_pro_max
music_search = _music_search_online_pro_max

