# =============================================================================
# BILBILAK PLAYER REMOTE SEARCH / PER-PLAYER DESIGN V4
# =============================================================================
# API credentials are owner-configurable. No player emoji ID or logo is hardcoded.
# Search order: configured football API -> Wikipedia REST (no key) -> Google CSE
# (if configured). The owner can import/edit a result before exposing it.

async def _bb_player_remote_schema():
    await _bb_player_stats_schema()
    for sql in [
        "ALTER TABLE bb_player_data ADD COLUMN photo_url TEXT DEFAULT ''",
        "ALTER TABLE bb_player_data ADD COLUMN source_url TEXT DEFAULT ''",
        "ALTER TABLE bb_player_data ADD COLUMN player_id TEXT DEFAULT ''",
    ]:
        try: await DBX.execute(sql)
        except Exception: pass
    await DBX.execute("CREATE TABLE IF NOT EXISTS bb_player_emojis(player_name TEXT NOT NULL,slot TEXT NOT NULL,emoji_id TEXT DEFAULT '',PRIMARY KEY(player_name,slot))")
    await DBX.execute("CREATE INDEX IF NOT EXISTS idx_bb_player_emojis_name ON bb_player_emojis(player_name)")

_BB_PLAYER_EMOJI_SLOTS = {
    'name':'نام', 'nationality':'ملیت', 'team':'تیم فعلی', 'prime':'تیم اوج',
    'year':'سال اوج', 'age':'سن', 'children':'فرزند', 'wc':'جام جهانی',
    'national':'جام ملی', 'club':'جام باشگاهی', 'spouse':'همسر', 'stats':'آمار',
    'logo':'تصویر بازیکن'
}

async def _bb_player_emoji_set(name,slot,eid):
    await _bb_player_remote_schema()
    if slot not in _BB_PLAYER_EMOJI_SLOTS: return False
    await DBX.execute('INSERT OR REPLACE INTO bb_player_emojis(player_name,slot,emoji_id) VALUES(?,?,?)',(name,slot,str(eid or '')))
    return True

async def _bb_player_emoji_map(name):
    await _bb_player_remote_schema()
    rows=await DBX.execute('SELECT slot,emoji_id FROM bb_player_emojis WHERE player_name=?',(name,),fetch=True)
    return {str(r['slot']):str(r['emoji_id'] or '') for r in rows}

async def _bb_http_json(url,headers=None,timeout=12):
    import urllib.request as _ur, json as _json
    def _go():
        req=_ur.Request(url,headers=headers or {'User-Agent':'Bilbilak/4.0'})
        return _json.loads(_ur.urlopen(req,timeout=timeout).read().decode('utf-8','ignore'))
    return await asyncio.to_thread(_go)

async def _bb_player_search_football_api(query):
    base=(await _bb_api_get('PLAYER_API_URL','')).strip().rstrip('/')
    key=(await _bb_api_get('PLAYER_API_KEY','')).strip()
    host=(await _bb_api_get('PLAYER_API_HOST','')).strip()
    if not base or not key: return []
    # Supports API-Football style /players?search=...
    try:
        import urllib.parse as _up
        url=base + ('/players' if not base.endswith('/players') else '') + '?' + _up.urlencode({'search':query})
        headers={'User-Agent':'Bilbilak/4.0','x-apisports-key':key}
        if host: headers['x-rapidapi-host']=host
        data=await _bb_http_json(url,headers)
        out=[]
        for x in (data.get('response') or data.get('results') or []):
            p=x.get('player',x) or {}; stats=(x.get('statistics') or [{}])[0] or {}
            team=stats.get('team') or x.get('team') or {}
            out.append({'id':p.get('id',''),'name':p.get('name') or query,
                        'nationality':p.get('nationality') or '', 'age':p.get('age') or '',
                        'photo_url':p.get('photo') or '', 'current_team':team.get('name') or '',
                        'source_url':base})
        return out[:10]
    except Exception as exc:
        log.debug('player football api failed: %s',exc); return []

async def _bb_player_search_wikipedia(query):
    try:
        import urllib.parse as _up
        q=_up.quote(query+' footballer')
        data=await _bb_http_json('https://en.wikipedia.org/w/rest.php/v1/search/page?q='+q+'&limit=8')
        out=[]
        for p in data.get('pages',[]):
            title=p.get('title') or ''
            if not title: continue
            key=p.get('key') or _up.quote(title.replace(' ','_'))
            out.append({'id':'','name':title,'nationality':'','age':'','current_team':'',
                        'photo_url':'https://en.wikipedia.org/wiki/Special:Redirect/file/'+_up.quote(title.replace(' ','_'))+'.jpg',
                        'source_url':'https://en.wikipedia.org/wiki/'+key})
        return out
    except Exception as exc:
        log.debug('wikipedia player search failed: %s',exc); return []

async def _bb_player_search_google(query):
    key=await _bb_api_get('GOOGLE_API_KEY',''); cx=await _bb_api_get('GOOGLE_CSE_ID','')
    if not key or not cx: return []
    try:
        import urllib.parse as _up
        u='https://www.googleapis.com/customsearch/v1?'+_up.urlencode({'key':key,'cx':cx,'q':query+' football player','searchType':'image','num':5})
        data=await _bb_http_json(u)
        out=[]
        for x in data.get('items',[]):
            out.append({'id':'','name':query,'nationality':'','age':'','current_team':'',
                        'photo_url':((x.get('image') or {}).get('contextLink') or x.get('link') or ''),
                        'source_url':x.get('link') or ''})
        return out
    except Exception as exc:
        log.debug('google player image search failed: %s',exc); return []

async def _bb_player_remote_search(query):
    q=str(query).strip()
    if not q: return []
    out=await _bb_player_search_football_api(q)
    if out: return out
    out=await _bb_player_search_wikipedia(q)
    if out: return out
    return await _bb_player_search_google(q)

async def _bb_player_import_result(result,msg):
    await _bb_player_remote_schema()
    name=str(result.get('name') or '').strip()
    if not name: return False
    old=await DBX.one('SELECT * FROM bb_player_data WHERE lower(name)=lower(?)',(name,))
    vals={k:str(result.get(k) or '') for k in ('nationality','current_team','age','photo_url','source_url','player_id')}
    await DBX.execute('''INSERT OR IGNORE INTO bb_player_data(name,nationality,current_team,prime_team,prime_year,age,children,world_cups,national_trophies,club_trophies,spouse,emoji_id,photo_url,source_url,player_id)
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)''',(name,vals['nationality'],vals['current_team'],'','',''+vals['age'],'','','','','','',vals['photo_url'],vals['source_url'],vals['player_id']))
    if old:
        await DBX.execute('UPDATE bb_player_data SET nationality=COALESCE(NULLIF(?,\'\'),nationality),current_team=COALESCE(NULLIF(?,\'\'),current_team),age=COALESCE(NULLIF(?,\'\'),age),photo_url=COALESCE(NULLIF(?,\'\'),photo_url),source_url=COALESCE(NULLIF(?,\'\'),source_url),player_id=COALESCE(NULLIF(?,\'\'),player_id) WHERE name=?',(vals['nationality'],vals['current_team'],vals['age'],vals['photo_url'],vals['source_url'],vals['player_id'],name))
    await msg.reply_text('✅ بازیکن ثبت شد/به‌روزرسانی شد.\n👤 '+safe_text(name,100)+'\nبرای شخصی‌سازی ایموجی‌ها: <code>pemoji '+safe_text(name,60)+' | slot | EMOJI_ID</code>',parse_mode='HTML')
    return True

async def _bb_player_search_owner(raw,msg):
    if not await _bb_owner_gate(msg): return True
    q=str(raw).strip()
    rows=await _bb_player_remote_search(q)
    if not rows:
        await msg.reply_text('❌ بازیکنی پیدا نشد. API بازیکنان یا Google API را در /apis تنظیم کن.'); return True
    context=None
    # Persist the result list in user_data for callback selection.
    try: context=msg._context
    except Exception: pass
    # owner command is called from update router; callback handler receives same user_data.
    # Attach compact results through global per-user cache to avoid relying on message internals.
    uid=getattr(getattr(msg,'from_user',None),'id',0)
    _BB_PLAYER_SEARCH_CACHE[int(uid)] = rows
    kb=[]
    for i,r in enumerate(rows[:8]): kb.append([btn('👤 '+str(r.get('name') or q)[:45],f'sv2:psel:{i}')])
    await msg.reply_text('🔎 <b>نتایج جستجوی بازیکن</b>\n'+ '\n'.join(f'{i+1}. {safe_text(str(r.get("name") or q),80)} | {safe_text(str(r.get("current_team") or "-"),50)}' for i,r in enumerate(rows[:8])),parse_mode='HTML',reply_markup=keyboard(kb))
    return True

_BB_PLAYER_SEARCH_CACHE={}

async def _bb_player_search_callback(update,context,d):
    q=update.callback_query
    uid=getattr(getattr(q,'from_user',None),'id',0)
    rows=_BB_PLAYER_SEARCH_CACHE.get(int(uid),[])
    try: idx=int(d.split(':')[-1])
    except: idx=-1
    if idx<0 or idx>=len(rows): return True
    r=rows[idx]
    name=str(r.get('name') or '')
    await _bb_player_remote_schema()
    em=await _bb_player_emoji_map(name)
    text=('👤 <b>'+safe_text(name,100)+'</b>\n\n'
          '🌍 ملیت: '+safe_text(str(r.get('nationality') or '-'),80)+'\n'
          '⚽ تیم: '+safe_text(str(r.get('current_team') or '-'),80)+'\n'
          '🎂 سن: '+safe_text(str(r.get('age') or '-'),20)+'\n'
          '🖼 تصویر: '+('ثبت شده' if r.get('photo_url') else 'ندارد')+'\n\n'
          'از اینجا می‌توانی بازیکن را ثبت کنی و برای همین بازیکن، هر ایموجی را جداگانه تعیین کنی.')
    kb=[[btn('✅ ثبت/به‌روزرسانی','sv2:pimport:'+str(idx))],[btn('🖼 ثبت تصویر','sv2:plogo:'+str(idx))],[btn('✨ ایموجی‌های همین بازیکن','sv2:pemoji:'+str(idx))]]
    await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard(kb)); return True

async def _bb_player_emoji_panel(update,context,idx):
    q=update.callback_query; uid=getattr(getattr(q,'from_user',None),'id',0); rows=_BB_PLAYER_SEARCH_CACHE.get(int(uid),[])
    try: i=int(idx)
    except: i=-1
    if i<0 or i>=len(rows): return True
    name=str(rows[i].get('name') or '')
    mp=await _bb_player_emoji_map(name)
    lines=['✨ <b>ایموجی اختصاصی بازیکن</b>',safe_text(name,100),'']
    lines += [f'• {label}: '+('🟢 تنظیم' if mp.get(slot) else '🔴 خالی') for slot,label in _BB_PLAYER_EMOJI_SLOTS.items()]
    lines += ['', 'ثبت از PV:', '<code>pemoji نام بازیکن | slot | EMOJI_ID</code>', 'مثال: <code>pemoji رونالدو | goals | 123456789</code>']
    await q.edit_message_text('\n'.join(lines),parse_mode='HTML',reply_markup=keyboard([[btn('🔙 نتیجه','sv2:psel:'+str(i))]])); return True

# Extend owner commands with remote player search and per-player emoji controls.
_BB_OLD_STUDIO_V2_MESSAGE_V4=globals().get('_bb_studio_v2_message')
async def _bb_studio_v2_message(update,context):
    if await _bb_owner_gate(update):
        msg=update.effective_message; t=str(getattr(msg,'text','') or '').strip()
        if re.match(r'^psearch\s+',t,re.I): return await _bb_player_search_owner(t.split(None,1)[1],msg)
        if re.match(r'^pemoji\s+',t,re.I):
            p=t.split(None,1)[1].split('|')
            if len(p)>=3:
                name,slot,eid=[x.strip() for x in p[:3]]
                if await _bb_player_emoji_set(name,slot,'' if eid.lower()=='off' else eid): await msg.reply_text('✅ ایموجی اختصاصی همین بازیکن ذخیره شد.'); return True
                await msg.reply_text('❌ slot نامعتبر است. slotها را از پنل بازیکن ببین.'); return True
        if re.match(r'^plogo\s+',t,re.I):
            p=t.split(None,1)[1].split('|')
            if len(p)>=2:
                name,url=p[0].strip(),p[1].strip(); await _bb_player_remote_schema()
                await DBX.execute('UPDATE bb_player_data SET photo_url=? WHERE name=?',(url,name)); await msg.reply_text('✅ تصویر اختصاصی بازیکن ذخیره شد.'); return True
    return await _BB_OLD_STUDIO_V2_MESSAGE_V4(update,context)

_BB_OLD_STUDIO_V2_CALLBACK_V4=globals().get('_bb_studio_v2_callback')
async def _bb_studio_v2_callback(update,context):
    d=str(getattr(getattr(update,'callback_query',None),'data','') or '')
    if d.startswith('sv2:psel:'):
        if not await _bb_owner_gate(update): return True
        return await _bb_player_search_callback(update,context,d)
    if d.startswith('sv2:pemoji:'):
        if not await _bb_owner_gate(update): return True
        return await _bb_player_emoji_panel(update,context,d.split(':')[-1])
    if d.startswith('sv2:pimport:'):
        if not await _bb_owner_gate(update): return True
        uid=getattr(getattr(update,'callback_query',None),'from_user',None); uid=getattr(uid,'id',0)
        rows=_BB_PLAYER_SEARCH_CACHE.get(int(uid),[])
        try: i=int(d.split(':')[-1])
        except: i=-1
        if 0<=i<len(rows): return await _bb_player_import_result(rows[i],update.callback_query.message)
        return True
    if d.startswith('sv2:plogo:'):
        if not await _bb_owner_gate(update): return True
        await update.callback_query.answer('در PV دستور plogo نام | URL را بفرست.',show_alert=True); return True
    return await _BB_OLD_STUDIO_V2_CALLBACK_V4(update,context)

# Make /apis show the extra player/search API slots as well.
_BB_OLD_API_COMMAND_V4=globals().get('_bb_api_owner_command')
async def _bb_api_owner_command(update,context):
    if not await _bb_owner_gate(update): return
    body='''🔌 <b>APIهای قابل تنظیم بیل بیلک</b>\n\n'''
    keys=['CURRENCY_API_KEY','CURRENCY_API_URL','GOOGLE_API_KEY','GOOGLE_CSE_ID','PLAYER_API_URL','PLAYER_API_KEY','PLAYER_API_HOST']
