    await msg.reply_text('✅ کشور ثبت شد/به‌روزرسانی شد.\n🌍 '+safe_text(name,100)+'\nبرای ایموجی اختصاصی: <code>cemoji '+safe_text(name,60)+' | slot | EMOJI_ID</code>',parse_mode='HTML')
