# =============================================================================
# BILBILAK IMAGE UPSCALER V1 — 1080P / 2K / 4K
# =============================================================================
# Trigger: user replies to a photo with a text such as «افزایش کیفیت».
# The result keeps the requested target resolution and puts the current date
# under the image.  The UI is owner-editable through the existing UI registry.
#
# Engine policy:
#   1) Optional Real-ESRGAN/other external engine can be plugged in later.
#   2) Built-in Pillow LANCZOS + mild unsharp mask always produces a real,
#      correctly sized output without inventing a fake resolution claim.
# This avoids silently claiming AI super-resolution when no model is installed.

_BB_UPSCALE_TEXT = "🖼️ پنل افزایش کیفیت تصویر"
_BB_UPSCALE_SUBTEXT = "کیفیت موردنظر را انتخاب کن:"
_BB_UPSCALE_DATE_PREFIX = "📅 تاریخ"

async def _bb_upscale_schema():
    try:
        await DBX.execute("""CREATE TABLE IF NOT EXISTS bb_upscale_settings(
            key TEXT PRIMARY KEY, value TEXT DEFAULT '', updated_at INTEGER DEFAULT 0
        )""")
    except Exception:
        pass
    # Register UI elements in the same editable UI table used by /design.
    try:
        await _bb_ui_schema()
        items = [
            ("upscale.title", _BB_UPSCALE_TEXT, "upscaler", "upscale"),
            ("upscale.subtitle", _BB_UPSCALE_SUBTEXT, "upscaler", "upscale"),
            ("upscale.1080", "🎯 1080p", "upscaler", "upscale"),
            ("upscale.2k", "💎 2K", "upscaler", "upscale"),
            ("upscale.4k", "👑 4K", "upscaler", "upscale"),
            ("upscale.date", _BB_UPSCALE_DATE_PREFIX, "upscaler", "upscale"),
            ("upscale.processing", "⏳ در حال افزایش کیفیت تصویر...", "upscaler", "upscale"),
            ("upscale.done", "✅ تصویر با کیفیت جدید آماده شد.", "upscaler", "upscale"),
            ("upscale.error", "❌ افزایش کیفیت تصویر انجام نشد.", "upscaler", "upscale"),
        ]
        for key,text0,cat,src in items:
            try:
                await DBX.execute(
                    """INSERT OR IGNORE INTO bb_ui_texts(key,text,category,source_line,source_name)
                       VALUES(?,?,?,?,?)""",(key,text0,cat,0,src)
                )
            except Exception:
                try:
                    await DBX.execute(
                        "INSERT OR IGNORE INTO bb_ui_texts(key,text,category) VALUES(?,?,?)",
                        (key,text0,cat)
                    )
                except Exception:
                    pass
    except Exception:
        pass

async def _bb_upscale_ui(key, default):
    try:
        await _bb_upscale_schema()
        row = await DBX.one("SELECT text FROM bb_ui_texts WHERE key=?", (key,))
        if row and row.get("text") is not None:
            return str(row["text"])
    except Exception:
        pass
    return default

def _bb_upscale_date():
    # Latin digits as requested for numeric displays.
    return datetime.now().strftime("%Y-%m-%d")

async def _bb_upscale_panel(update, context):
    await _bb_upscale_schema()
    q = getattr(update, "callback_query", None)
    msg = getattr(update, "effective_message", None)
    if not msg:
        return True
    title = await _bb_upscale_ui("upscale.title", _BB_UPSCALE_TEXT)
    sub = await _bb_upscale_ui("upscale.subtitle", _BB_UPSCALE_SUBTEXT)
    rows = [
        [btn(await _bb_upscale_ui("upscale.1080", "🎯 1080p"), "upscale:1080")],
        [btn(await _bb_upscale_ui("upscale.2k", "💎 2K"), "upscale:2560")],
        [btn(await _bb_upscale_ui("upscale.4k", "👑 4K"), "upscale:3840")],
    ]
    text = f"{title}\n\n{sub}"
    if q:
        await q.answer()
        await q.edit_message_text(text, reply_markup=keyboard(rows))
    else:
        await msg.reply_text(text, reply_markup=keyboard(rows))
    return True

def _bb_target_dimensions(width, height, target_long):
    width, height = max(1,int(width)), max(1,int(height))
    target_long = int(target_long)
    scale = target_long / float(max(width,height))
    # Upscale only to requested long edge; preserve aspect ratio.
    nw = max(1, int(round(width*scale)))
    nh = max(1, int(round(height*scale)))
    return nw, nh

def _bb_high_quality_resize(im, size):
    # Pillow's high-quality resampling + restrained sharpening.
    from PIL import Image, ImageFilter
    out = im.convert("RGB").resize(size, Image.Resampling.LANCZOS)
    # Mild sharpening prevents a visibly soft Lanczos result without
    # hallucinating details.
    out = out.filter(ImageFilter.UnsharpMask(radius=1.15, percent=115, threshold=3))
    return out

async def _bb_upscale_photo(update, context, target_long):
    msg = update.effective_message
    if not msg or not msg.photo:
        return False
    status = await msg.reply_text(await _bb_upscale_ui(
        "upscale.processing","⏳ در حال افزایش کیفیت تصویر..."
    ))
    temp_in = temp_out = None
    try:
        from PIL import Image, ImageOps
        photo = msg.photo[-1]
        tg_file = await photo.get_file()
        fd, temp_in = tempfile.mkstemp(suffix=".jpg", prefix="bb_up_")
        os.close(fd)
        await tg_file.download_to_drive(temp_in)

        with Image.open(temp_in) as src:
            src = ImageOps.exif_transpose(src)
            w,h = src.size
            # Never downscale an already-larger image.
            long_target = max(int(target_long), max(w,h))
            nw,nh = _bb_target_dimensions(w,h,long_target)
            out = _bb_high_quality_resize(src,(nw,nh))

            fd, temp_out = tempfile.mkstemp(suffix=".jpg", prefix="bb_up_out_")
            os.close(fd)
            out.save(temp_out,"JPEG",quality=97,subsampling=0,optimize=True)

        caption = (
            (await _bb_upscale_ui("upscale.done","✅ تصویر با کیفیت جدید آماده شد."))
            + "\n"
            + (await _bb_upscale_ui("upscale.date","📅 تاریخ"))
            + f": {_bb_upscale_date()}"
            + f"\n{nw}×{nh}"
        )
        with open(temp_out,"rb") as fh:
            await msg.reply_photo(photo=fh, caption=caption)
        try:
            await status.delete()
        except Exception:
            pass
        return True
    except Exception as exc:
        log.exception("upscale failed: %s",exc)
        try:
            await status.edit_text(await _bb_upscale_ui(
                "upscale.error","❌ افزایش کیفیت تصویر انجام نشد."
            ))
        except Exception:
            pass
        return True
    finally:
        for p in (temp_in,temp_out):
            if p:
                try: os.remove(p)
                except Exception: pass

async def _bb_upscale_callback(update, context):
    q=update.callback_query
    data=str(q.data or "")
    try:
        target=int(data.split(":",1)[1])
    except Exception:
        await q.answer("گزینه نامعتبر است.",show_alert=True); return True
    # The panel is attached to a message; the original photo is stored in
    # per-user context when the panel was opened.
    uid=int(getattr(q.from_user,"id",0))
    pending=_BB_UPSCALE_PENDING.get(uid)
    if not pending:
        await q.answer("عکس برای پردازش پیدا نشد؛ دوباره روی عکس «افزایش کیفیت» بزن.",show_alert=True)
        return True
    await q.answer("در حال پردازش...")
    # Download from the original photo message rather than trying to use
    # the panel message as an image.
    try:
        orig_update, orig_msg = pending
        # Reuse the current context and process via the original Message.
        class _Proxy:
            effective_message = orig_msg
        await _bb_upscale_photo(_Proxy(), context, target)
    finally:
        _BB_UPSCALE_PENDING.pop(uid,None)
    return True

_BB_UPSCALE_PENDING={}

async def _bb_upscale_message_router(update, context):
    msg=update.effective_message
    if not msg:
        return False
    # Only activate when the user replies to the image with the trigger.
    # A direct photo with no trigger remains untouched.
    if not getattr(msg,"reply_to_message",None):
        return False
    txt=str(msg.text or msg.caption or "").strip().lower()
    triggers=("افزایش کیفیت","کیفیت عکس","کیفیت تصویر","upscale","enhance")
    if txt not in triggers and not any(x in txt for x in triggers):
        return False
    original=msg.reply_to_message
    if not getattr(original,"photo",None):
        await msg.reply_text("❌ پیام ریپلای‌شده یک عکس نیست.")
        return True
    uid=int(getattr(getattr(msg,"from_user",None),"id",0))
    _BB_UPSCALE_PENDING[uid]=(update,original)
    return await _bb_upscale_panel(update,context)

async def _bb_upscale_command(update, context):
    # Optional direct command: /upscale while replying to a photo.
    msg=update.effective_message
    if not msg or not getattr(msg,"reply_to_message",None):
        await msg.reply_text("روی یک عکس ریپلای کن و /upscale را بفرست.")
        return True
    original=msg.reply_to_message
    if not getattr(original,"photo",None):
        await msg.reply_text("❌ پیام ریپلای‌شده یک عکس نیست.")
        return True
    uid=int(getattr(getattr(msg,"from_user",None),"id",0))
    _BB_UPSCALE_PENDING[uid]=(update,original)
    return await _bb_upscale_panel(update,context)

_BB_OLD_BUILD_UPSCALE=globals().get("build_application")
def build_application(token=None):
    app=_BB_OLD_BUILD_UPSCALE(token) if _BB_OLD_BUILD_UPSCALE else Application.builder().token(token or BOT_TOKEN).build()
    # High-priority router: it only consumes explicit photo-quality replies.
    # User sends a normal text reply to the photo; the text itself is the trigger.
    app.add_handler(MessageHandler(
        filters.TEXT & ~filters.COMMAND,
        _bb_upscale_message_router
    ), group=-990500)
    app.add_handler(CommandHandler(["upscale"], _bb_upscale_command), group=-990500)
    app.add_handler(CallbackQueryHandler(_bb_upscale_callback,pattern=r"^upscale:"),group=-990500)
    return app




