    await _bb_image_pool_schema()
    rows=await DBX.all("SELECT id,media_id FROM bb_v7_content WHERE kind='fortune_image' AND enabled=1 AND media_id<>'' ORDER BY id")
    if not rows:
        await msg.reply_text('⚠️ هنوز عکس فال برای این بخش ثبت نشده است.')
