# FINAL COLORED BUTTON VISUAL LAYER — 2026-09-25
# Presentation-only layer: keeps all existing callback data and button logic.
# Uses Telegram's native button style parameter where supported.
try:
    _BB_ORIGINAL_INLINE_BUTTON = InlineKeyboardButton

    def _bb_colored_inline_button(*args, **kwargs):
        label = ""
        data = ""
        if args:
            label = str(args[0] or "")
        if len(args) > 1:
            data = str(args[1] or "")
        label = str(kwargs.get("text", label) or "")
        data = str(
            kwargs.get("callback_data",
                       kwargs.get("url",
                                  kwargs.get("web_app", data))) or ""
        )

        # Never override special button types such as URL/login/web-app buttons
        # unless Telegram accepts the style field for them.
        if "style" not in kwargs:
            kwargs["style"] = _button_style(label, data)

        return _BB_ORIGINAL_INLINE_BUTTON(*args, **kwargs)

    InlineKeyboardButton = _bb_colored_inline_button
    BB_BUTTON_COLOR_LAYER = True
    log.info("Bilbilak colored button layer enabled: native Telegram styles")
except Exception as _bb_color_exc:
    BB_BUTTON_COLOR_LAYER = False
    log.warning("Colored button layer unavailable: %r", _bb_color_exc)


# =============================================================================
# FINAL OWNER WIZARD — VOICE WORD/ANSWER + TRUTH/DARE QUESTION REGISTRATION
# =============================================================================
# Adds button-driven two-step registration without removing the legacy commands.
# Telegram's ForceReply/reply flow is intentionally kept simple: the owner taps
# a button, sends the requested text, then sends the second text; the pair is
# stored in the global DB. Telegram documents ForceReply as a supported way to
# guide users through step-by-step input.

async def _bb_owner_voice_add_start(update, context):
    if not await _bb_owner_gate(update): return True
    await _bb_studio_v2_schema()
    context.user_data['bb_voice_wizard'] = 'question'
    await update.effective_message.reply_text(
        '🎙 <b>افزودن کلمه جدید</b>\n\n'
        'مرحله ۱ از ۲\n'
        'کلمه یا جمله‌ای که کاربر باید بفرستد را ارسال کن.\n\n'
        'مثال: <code>سلام بیل بیلک</code>\n\n'
        'برای لغو: <code>لغو</code>',
        parse_mode='HTML'
    )
    return True

async def _bb_owner_voice_wizard_text(update, context):
    msg=update.effective_message
    if not msg or not getattr(msg,'text',None): return False
    if not await _bb_owner_gate(update): return False
    state=context.user_data.get('bb_voice_wizard')
    if not state: return False
    text=str(msg.text or '').strip()
    if normalize(text) in {'لغو','cancel'}:
        context.user_data.pop('bb_voice_wizard',None)
        await msg.reply_text('❌ ثبت سخنگو لغو شد.')
        return True
    if state=='question':
        if not text:
            await msg.reply_text('⚠️ کلمه/سؤال خالی است؛ دوباره بفرست.')
            return True
        context.user_data['bb_voice_wizard_question']=text
        context.user_data['bb_voice_wizard']='answer'
        await msg.reply_text(
            '✅ کلمه ذخیره شد.\n\n'
            'مرحله ۲ از ۲\n'
            'حالا جواب سخنگو را بفرست.\n\n'
            'مثال: <code>سلام رفیق 🐾</code>\n\n'
            'برای لغو: <code>لغو</code>',
            parse_mode='HTML'
        )
        return True
    if state=='answer':
        if not text:
            await msg.reply_text('⚠️ جواب خالی است؛ دوباره بفرست.')
            return True
        trigger=str(context.user_data.get('bb_voice_wizard_question') or '').strip()
        if not trigger:
            context.user_data.pop('bb_voice_wizard',None)
            context.user_data.pop('bb_voice_wizard_question',None)
            await msg.reply_text('❌ مرحله اول پیدا نشد؛ دوباره از «افزودن کلمه جدید» شروع کن.')
            return True
        await _bb_v7_schema()
        await DBX.execute(
            'INSERT INTO bb_voice_pool(trigger,response_type,response_value,media_id,caption,enabled,created_at) VALUES(?,?,?,?,?,?,?)',
            (normalize(trigger),'text',text,'','',1,now_ts())
        )
        context.user_data.pop('bb_voice_wizard',None)
        context.user_data.pop('bb_voice_wizard_question',None)
        await msg.reply_text(
            '✅ <b>کلمه و جواب سخنگو ذخیره شد.</b>\n\n'
            f'🗣 کلمه: <code>{safe_text(trigger,200)}</code>\n'
            f'💬 جواب: {safe_text(text,500)}',
            parse_mode='HTML'
        )
        return True
    context.user_data.pop('bb_voice_wizard',None)
    context.user_data.pop('bb_voice_wizard_question',None)
    return False

