async def _bb_game_add_callback_final(update, context):
    q=getattr(update,'callback_query',None)
    if not q: return False
    d=str(q.data or '')
    if not d.startswith('sv2:game:add:'): return False
    if not await _bb_owner_gate(update):
        await q.answer('⛔ فقط مالک.',show_alert=True); return True
    game=d.rsplit(':',1)[-1]
    if game not in ('truth','dare'):
        return False
    await q.answer()
    context.user_data['bb_td_wizard']=game
    label='حقیقت' if game=='truth' else 'جرأت'
    await q.message.reply_text(
        f'🎭 <b>افزودن مورد {label}</b>\n\n'
        f'یک مورد {label} را بفرست.\n'
        f'مثال: <code>{"آخرین دروغی که گفتی چی بود؟" if game=="truth" else "۱۰ ثانیه با صدای بلند آواز بخوان."}</code>\n\n'
        'برای لغو: <code>لغو</code>', parse_mode='HTML'
    )
    return True

async def _bb_td_wizard_text(update, context):
    msg=update.effective_message
    if not msg or not getattr(msg,'text',None): return False
    if not await _bb_owner_gate(update): return False
    game=context.user_data.get('bb_td_wizard')
    if game not in ('truth','dare'): return False
    text=str(msg.text or '').strip()
    if normalize(text) in {'لغو','cancel'}:
        context.user_data.pop('bb_td_wizard',None)
        await msg.reply_text('❌ ثبت جرأت/حقیقت لغو شد.')
        return True
    if not text:
        await msg.reply_text('⚠️ متن خالی است؛ دوباره بفرست.')
        return True
    await _bb_studio_v2_schema()
    await DBX.execute(
        'INSERT OR IGNORE INTO bb_game_lists(game,item,created_at) VALUES(?,?,?)',
        (game,text,now_ts())
    )
    context.user_data.pop('bb_td_wizard',None)
    label='حقیقت' if game=='truth' else 'جرأت'
    row=await DBX.one('SELECT COUNT(*) c FROM bb_game_lists WHERE game=?',(game,))
    await msg.reply_text(f'✅ مورد {label} ذخیره شد.\n📊 تعداد {label}: {int(row["c"] or 0) if row else 0}')
    return True

async def _bb_game_panel_callback_final(update, context):
    q=getattr(update,'callback_query',None)
    if not q: return False
    d=str(q.data or '')
    if d not in ('sv2:game:truth:0','sv2:game:dare:0'): return False
    if not await _bb_owner_gate(update):
        await q.answer('⛔ فقط مالک.',show_alert=True); return True
    await q.answer()
    game='truth' if d.startswith('sv2:game:truth') else 'dare'
    label='حقیقت' if game=='truth' else 'جرأت'
    await _bb_studio_v2_schema()
    row=await DBX.one('SELECT COUNT(*) c FROM bb_game_lists WHERE game=?',(game,))
    count=int(row['c'] or 0) if row else 0
    await q.edit_message_text(
        f'🎭 <b>جرأت / حقیقت — {label}</b>\n\n'
        f'📚 موارد ثبت‌شده: <b>{count}</b>\n\n'
        f'برای اضافه‌کردن مورد جدید، دکمه را بزن و متن {label} را بفرست.',
        parse_mode='HTML',
        reply_markup=keyboard([
            [btn(f'➕ افزودن {label}',f'sv2:game:add:{game}')],
            [btn('🔙 طراحی','sv2:home')]
        ])
    )
    return True

async def _bb_td_db_priority_router(update, context):
    msg=update.effective_message
    if not msg or not getattr(msg,'text',None): return False
    t=normalize(str(msg.text or '')).strip()
    if t not in {'حقیقت','جرأت','جرئت','جرعت'}: return False
    game='truth' if t=='حقیقت' else 'dare'
    await _bb_studio_v2_schema()
    rows=await DBX.execute('SELECT item FROM bb_game_lists WHERE game=? ORDER BY rowid',(game,),fetch=True)
    if not rows: return False
    item=_bb_random.choice(rows)
    await msg.reply_text(str(item['item']))
    return True

# Highest-priority final build wrapper. Existing commands/callbacks remain intact;
# these handlers only consume their own new callback/state namespaces.
_BB_WIZARD_BUILD_OLD=build_application
def build_application(token=None):
    app=_BB_WIZARD_BUILD_OLD(token)
    app.add_handler(CallbackQueryHandler(_bb_voice_wizard_callback,pattern=r'^sv2:voice:add$'),group=-1000015)
    app.add_handler(CallbackQueryHandler(_bb_voice_panel_wizard_callback,pattern=r'^sv2:voice:0$'),group=-1000014)
    app.add_handler(CallbackQueryHandler(_bb_game_add_callback_final,pattern=r'^sv2:game:add:(truth|dare)$'),group=-1000013)
    app.add_handler(CallbackQueryHandler(_bb_game_panel_callback_final,pattern=r'^sv2:game:(truth|dare):0$'),group=-1000012)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_owner_voice_wizard_text),group=-1000011)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_td_wizard_text),group=-1000010)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_td_db_priority_router),group=-1000009)
    return app

# =============================================================================
# FINAL GROUP CONTROL / STATS / TAGS PATCH 2026-09-26
# =============================================================================
# هدف: یک مسیر نهایی و یکپارچه برای آمار ریز، گزارش 00:00، قفل/امنیت با
# اکانت پاکسازی، و پنل شیشه‌ای «تگ» بدون حذف مسیرهای قدیمی.

_BB_DEEP_STATS_READY = False
_BB_DEEP_STATS_JOB = 'bilbilak-deep-midnight-stats-v2'
_BB_DEEP_TAG_TARGETS = {}

async def _bb_deep_stats_schema():
    global _BB_DEEP_STATS_READY
    if _BB_DEEP_STATS_READY:
        return
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_stats_hourly(
        chat_id INTEGER NOT NULL,
        user_id INTEGER NOT NULL,
        hour TEXT NOT NULL,
        messages INTEGER DEFAULT 0,
        text_messages INTEGER DEFAULT 0,
        photos INTEGER DEFAULT 0,
        videos INTEGER DEFAULT 0,
        gifs INTEGER DEFAULT 0,
        documents INTEGER DEFAULT 0,
        voices INTEGER DEFAULT 0,
        audios INTEGER DEFAULT 0,
        stickers INTEGER DEFAULT 0,
        links INTEGER DEFAULT 0,
        commands INTEGER DEFAULT 0,
        PRIMARY KEY(chat_id,user_id,hour)
    )''')
    await DBX.execute('CREATE INDEX IF NOT EXISTS idx_bb_stats_hourly_chat_hour ON bb_stats_hourly(chat_id,hour)')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_stats_events(
        chat_id INTEGER NOT NULL,
        day TEXT NOT NULL,
        event TEXT NOT NULL,
        amount INTEGER DEFAULT 0,
        PRIMARY KEY(chat_id,day,event)
    )''')
    await DBX.execute('CREATE INDEX IF NOT EXISTS idx_bb_stats_events_chat_day ON bb_stats_events(chat_id,day)')
    _BB_DEEP_STATS_READY = True


def _bb_deep_hour_key():
    try:
        from zoneinfo import ZoneInfo
        return datetime.now(ZoneInfo('Asia/Tehran')).strftime('%Y-%m-%d %H:00')
    except Exception:
        return datetime.utcnow().strftime('%Y-%m-%d %H:00')


def _bb_deep_day_key():
    try:
        from zoneinfo import ZoneInfo
        return datetime.now(ZoneInfo('Asia/Tehran')).strftime('%Y-%m-%d')
    except Exception:
        return datetime.utcnow().strftime('%Y-%m-%d')


async def _bb_deep_record_message(update):
    msg=update.effective_message; chat=update.effective_chat; user=update.effective_user
    if not msg or not chat or chat.type=='private' or not user:
        return
    try:
        await _bb_deep_stats_schema()
        hour=_bb_deep_hour_key()
        vals={
            'messages':1,
            'text_messages':1 if bool(getattr(msg,'text',None)) else 0,
            'photos':1 if getattr(msg,'photo',None) else 0,
            'videos':1 if getattr(msg,'video',None) else 0,
            'gifs':1 if getattr(msg,'animation',None) else 0,
            'documents':1 if getattr(msg,'document',None) else 0,
            'voices':1 if getattr(msg,'voice',None) else 0,
            'audios':1 if getattr(msg,'audio',None) else 0,
            'stickers':1 if getattr(msg,'sticker',None) else 0,
            'links':1 if re.search(r'https?://|t\.me/|www\.', str(getattr(msg,'text','') or getattr(msg,'caption','') or ''), re.I) else 0,
            'commands':1 if str(getattr(msg,'text','') or '').lstrip().startswith('/') else 0,
        }
        cols=','.join(vals.keys())
        placeholders=','.join('?' for _ in vals)
        updates=','.join(f'{k}={k}+excluded.{k}' for k in vals)
        await DBX.execute(
            f'INSERT INTO bb_stats_hourly(chat_id,user_id,hour,{cols}) VALUES(?,?,?,{placeholders}) '
            f'ON CONFLICT(chat_id,user_id,hour) DO UPDATE SET {updates}',
            (chat.id,user.id,hour,*vals.values())
        )
    except Exception as exc:
        log.debug('deep hourly stats: %s',exc)


async def _bb_deep_record_event(chat_id,event,amount=1,day=None):
    try:
        await _bb_deep_stats_schema()
        day=day or _bb_deep_day_key()
        await DBX.execute(
            'INSERT INTO bb_stats_events(chat_id,day,event,amount) VALUES(?,?,?,?) '
            'ON CONFLICT(chat_id,day,event) DO UPDATE SET amount=amount+excluded.amount',
            (int(chat_id),day,str(event),int(amount))
        )
    except Exception as exc:
        log.debug('deep event stats: %s',exc)


async def _bb_deep_stats_report(chat_id, days=1, target_day=None):
    await _bb_deep_stats_schema()
    try:
        from zoneinfo import ZoneInfo
        today=datetime.now(ZoneInfo('Asia/Tehran')).date()
    except Exception:
        today=datetime.utcnow().date()
    if target_day:
        end=target_day
        start=(datetime.strptime(target_day,'%Y-%m-%d').date()-timedelta(days=days-1)).strftime('%Y-%m-%d')
    else:
        end=today.strftime('%Y-%m-%d')
        start=(today-timedelta(days=days-1)).strftime('%Y-%m-%d')
    rows=await DBX.execute('''SELECT
        COALESCE(SUM(messages),0) messages, COALESCE(SUM(text_messages),0) texts,
        COALESCE(SUM(photos),0) photos, COALESCE(SUM(videos),0) videos,
        COALESCE(SUM(gifs),0) gifs, COALESCE(SUM(documents),0) documents,
        COALESCE(SUM(voices),0) voices, COALESCE(SUM(audios),0) audios,
        COALESCE(SUM(stickers),0) stickers, COALESCE(SUM(links),0) links,
        COALESCE(SUM(commands),0) commands
        FROM bb_stats_hourly WHERE chat_id=? AND substr(hour,1,10) BETWEEN ? AND ?''',(chat_id,start,end),fetch=True)
    r=rows[0] if rows else {}
    events=await DBX.execute('SELECT event,SUM(amount) amount FROM bb_stats_events WHERE chat_id=? AND day BETWEEN ? AND ? GROUP BY event',(chat_id,start,end),fetch=True)
    ev={str(x['event']):int(x['amount'] or 0) for x in events}
    unique=await DBX.execute('SELECT COUNT(DISTINCT user_id) n FROM bb_stats_hourly WHERE chat_id=? AND substr(hour,1,10) BETWEEN ? AND ?',(chat_id,start,end),fetch=True)
    peak=await DBX.execute('''SELECT hour,SUM(messages) n FROM bb_stats_hourly
        WHERE chat_id=? AND substr(hour,1,10) BETWEEN ? AND ? GROUP BY hour ORDER BY n DESC LIMIT 1''',(chat_id,start,end),fetch=True)
    top=await DBX.execute('''SELECT h.user_id,COALESCE(s.first_name,'کاربر') first_name,
        COALESCE(s.username,'') username,SUM(h.messages) messages
        FROM bb_stats_hourly h LEFT JOIN chat_member_stats s ON s.chat_id=h.chat_id AND s.user_id=h.user_id
        WHERE h.chat_id=? AND substr(h.hour,1,10) BETWEEN ? AND ?
        GROUP BY h.user_id ORDER BY messages DESC,h.user_id ASC LIMIT 10''',(chat_id,start,end),fetch=True)
    return start,end,r,ev,int(unique[0]['n'] if unique else 0),peak,top


def _bb_deep_report_text(report, title):
    start,end,r,ev,unique,peak,top=report
    def n(k): return int(r[k] or 0) if r and k in r.keys() else 0
    lines=[
        f'📊 <b>{title}</b>',
        f'📅 بازه: <b>{start}</b> تا <b>{end}</b>',
        '━━━━━━━━━━━━━━━━━━',
        f'💬 کل پیام‌ها: <b>{n("messages"):,}</b>',
        f'👥 کاربران فعال: <b>{unique:,}</b>',
        f'📝 متنی: <b>{n("texts"):,}</b>   🔗 لینک: <b>{n("links"):,}</b>',
        f'🖼 عکس: <b>{n("photos"):,}</b>   🎬 ویدیو: <b>{n("videos"):,}</b>',
        f'🎞 گیف: <b>{n("gifs"):,}</b>   📄 فایل: <b>{n("documents"):,}</b>',
        f'🎙 ویس: <b>{n("voices"):,}</b>   🎵 صوت: <b>{n("audios"):,}</b>',
        f'🎭 استیکر: <b>{n("stickers"):,}</b>   🤖 دستور: <b>{n("commands"):,}</b>',
        '',
        f'➕ ورود/افزودن: <b>{ev.get("adds",0):,}</b>   ➖ خروج: <b>{ev.get("leaves",0):,}</b>',
        f'🧹 حذف امنیتی/مدیریتی: <b>{ev.get("deleted",0):,}</b>',
        f'⚠️ اخطار: <b>{ev.get("warns",0):,}</b>',
    ]
    if peak:
        lines += [f'🔥 شلوغ‌ترین ساعت: <b>{safe_text(peak[0]["hour"],30)}</b> — {int(peak[0]["n"]):,} پیام']
    lines += ['', '🏆 <b>۱۰ نفر فعال‌تر</b>']
    if top:
        for i,x in enumerate(top,1):
            name=safe_text(x['first_name'] or 'کاربر',35)
            who=f'@{safe_text(x["username"],35)}' if x['username'] else f'<a href="tg://user?id={int(x["user_id"])}">{name}</a>'
            lines.append(f'{i}. {who} — <b>{int(x["messages"]):,}</b> پیام')
    else:
        lines.append('📭 هنوز داده‌ای ثبت نشده است.')
    return '\n'.join(lines)


def _bb_deep_stats_keyboard(uid):
    return keyboard([
        [btn('📌 امروز',f'dstats:{uid}:1'),btn('🗓 ۷ روز',f'dstats:{uid}:7')],
        [btn('📆 ۳۰ روز',f'dstats:{uid}:30'),btn('🕛 گزارش ۰۰:۰۰',f'dstats:{uid}:midnight')],
        [btn('⏱ ساعتی امروز',f'dstats:{uid}:hours'),btn('🏆 لیدربرد',f'dstats:{uid}:top')],
        [btn('🔄 بروزرسانی',f'dstats:{uid}:home'),btn('✕ بستن',f'dstats:{uid}:close',style='danger')],
    ])

async def _bb_deep_stats_open(update,context):
    msg=update.effective_message; chat=update.effective_chat; user=update.effective_user
    if not msg or not chat or chat.type=='private': return True
    if not await is_admin(update):
        await msg.reply_text('⛔ مرکز آمار فقط برای ادمین واقعی گروه است.'); return True
    await _bb_deep_stats_schema()
    report=await _bb_deep_stats_report(chat.id,1)
    text=_bb_deep_report_text(report,'مرکز آمار دقیق بیل‌بیلک')
    await msg.reply_text(text,parse_mode='HTML',reply_markup=_bb_deep_stats_keyboard(user.id))
    return True

async def _bb_deep_stats_callback(update,context):
    q=getattr(update,'callback_query',None)
    if not q or not str(q.data or '').startswith('dstats:'): return False
    p=str(q.data).split(':',2)
    if len(p)!=3: return True
    try: uid=int(p[1])
    except Exception: return True
    if uid!=q.from_user.id:
        await q.answer('⛔ این پنل برای ادمین دیگری است.',show_alert=True); return True
    fake=type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat,'effective_message':q.message})()
    if not await is_admin(fake,uid):
        await q.answer('⛔ دسترسی ادمینی نداری.',show_alert=True); return True
    action=p[2]; cid=q.message.chat.id
    try:
        if action=='close':
            await q.message.delete(); await q.answer('مرکز آمار بسته شد.'); return True
        if action=='home':
            text=_bb_deep_report_text(await _bb_deep_stats_report(cid,1),'مرکز آمار دقیق بیل‌بیلک')
            await q.edit_message_text(text,parse_mode='HTML',reply_markup=_bb_deep_stats_keyboard(uid)); await q.answer('🔄 بروزرسانی شد.'); return True
        if action=='midnight':
            report=await _bb_deep_stats_report(cid,1,target_day=_bb_stats_day_local(-1))
            await q.edit_message_text(_bb_deep_report_text(report,'🌙 گزارش کامل نیمه‌شب — روز گذشته'),parse_mode='HTML',reply_markup=_bb_deep_stats_keyboard(uid)); return True
        if action in {'1','7','30'}:
            report=await _bb_deep_stats_report(cid,int(action))
            await q.edit_message_text(_bb_deep_report_text(report,f'📊 آمار {action} روزه'),parse_mode='HTML',reply_markup=_bb_deep_stats_keyboard(uid)); return True
        if action=='hours':
            await _bb_deep_stats_schema()
            day=_bb_deep_day_key()
            rows=await DBX.execute('SELECT hour,SUM(messages) n FROM bb_stats_hourly WHERE chat_id=? AND substr(hour,1,10)=? GROUP BY hour ORDER BY hour',(cid,day),fetch=True)
            lines=['⏱ <b>ریز ساعتی امروز</b>','━━━━━━━━━━━━━━━━━━']
            for x in rows:
                lines.append(f'🕐 {safe_text(x["hour"],30)}  →  <b>{int(x["n"] or 0):,}</b> پیام')
            if not rows: lines.append('📭 امروز هنوز داده‌ای ثبت نشده.')
            await q.edit_message_text('\n'.join(lines),parse_mode='HTML',reply_markup=_bb_deep_stats_keyboard(uid)); return True
        if action=='top':
            report=await _bb_deep_stats_report(cid,1)
            top=report[-1]
            lines=['🏆 <b>لیدربرد دقیق امروز</b>','━━━━━━━━━━━━━━━━━━']
            for i,x in enumerate(top,1):
                name=safe_text(x['first_name'] or 'کاربر',35)
                who=f'@{safe_text(x["username"],35)}' if x['username'] else f'<a href="tg://user?id={int(x["user_id"])}">{name}</a>'
                lines.append(f'{i}. {who} — <b>{int(x["messages"]):,}</b> پیام')
            await q.edit_message_text('\n'.join(lines),parse_mode='HTML',reply_markup=_bb_deep_stats_keyboard(uid)); return True
    except Exception as exc:
        log.exception('deep stats callback: %s',exc)
        await q.answer('⚠️ نمایش آمار ناموفق بود.',show_alert=True)
    return True


async def _bb_deep_midnight_job(context):
    await _bb_deep_stats_schema()
    day=_bb_stats_day_local(-1)
    rows=await DBX.execute('SELECT chat_id FROM chats WHERE chat_id<0 AND active=1',fetch=True)
    for row in rows:
        cid=int(row['chat_id'])
        try:
            report=await _bb_deep_stats_report(cid,1,target_day=day)
            text=_bb_deep_report_text(report,'🌙 گزارش کامل ساعت ۱۲ شب بیل‌بیلک')
            await context.bot.send_message(cid,text,parse_mode='HTML')
        except Exception as exc:
            log.warning('deep midnight stats failed chat=%s: %s',cid,exc)


