async def _bb_premium_ux_schema():
    await DBX.execute("""CREATE TABLE IF NOT EXISTS bb_global_messages(
        key TEXT PRIMARY KEY, value TEXT DEFAULT '', updated_at INTEGER DEFAULT 0)""")
    await DBX.execute("""CREATE TABLE IF NOT EXISTS bb_premium_pool(
        id INTEGER PRIMARY KEY AUTOINCREMENT, emoji_id TEXT NOT NULL UNIQUE,
        enabled INTEGER DEFAULT 1, created_at INTEGER DEFAULT 0)""")
    await DBX.execute("""CREATE TABLE IF NOT EXISTS bb_pv_required_targets(
        target TEXT PRIMARY KEY, kind TEXT DEFAULT 'channel', label TEXT DEFAULT '',
        join_url TEXT DEFAULT '', enabled INTEGER DEFAULT 1, created_at INTEGER DEFAULT 0)""")

async def _bb_global_message_get(key, default=''):
    await _bb_premium_ux_schema()
    r=await DBX.one('SELECT value FROM bb_global_messages WHERE key=?',(str(key),))
    return (str(r['value']) if r else '') or default

async def _bb_global_message_set(key,value):
    await _bb_premium_ux_schema()
    await DBX.execute('INSERT INTO bb_global_messages(key,value,updated_at) VALUES(?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at',(str(key),str(value or ''),now_ts()))

async def _bb_premium_ids():
    await _bb_premium_ux_schema()
    rows=await DBX.execute('SELECT emoji_id FROM bb_premium_pool WHERE enabled=1 ORDER BY id',fetch=True)
    return [str(r['emoji_id']) for r in rows if str(r['emoji_id'] or '').strip()]

def _bb_premium_html(emoji_id):
    # Telegram's HTML custom-emoji form wraps exactly one normal fallback emoji.
    # The bot owner must have Premium for bots to send custom emoji directly.
    return f'<tg-emoji emoji-id="{safe_text(str(emoji_id),80)}">{_BB_PREMIUM_FALLBACK}</tg-emoji>'

async def _bb_apply_premium_vars(template):
    text=str(template or '')
    ids=await _bb_premium_ids()
    if not ids or '{premium}' not in text:
        return text
    while '{premium}' in text:
        eid=random.choice(ids)
        text=text.replace('{premium}',_bb_premium_html(eid),1)
    return text

async def _bb_render_global_template(template,user=None,chat=None):
    try:
        from zoneinfo import ZoneInfo
        now=datetime.now(ZoneInfo(os.getenv('BB_PROFILE_TIMEZONE','Asia/Tehran')))
    except Exception:
        now=datetime.now()
    name=mention_html(user) if user else 'کاربر'
    uid=str(getattr(user,'id','')) if user else ''
    username=('@'+user.username) if user and getattr(user,'username',None) else uid
    group_name=safe_text(getattr(chat,'title','') or 'گروه',120) if chat else 'گروه'
    repl={'{name}':name,'{id}':uid,'{username}':username,'{group}':group_name,'{group_name}':group_name,
          '{date}':now.strftime('%Y/%m/%d'),'{time}':now.strftime('%H:%M:%S'),
          '{day}':_BB_DAY_NAMES.get(now.weekday(),now.strftime('%A')),'{bot}':'Bilbilak','{bot_username}':'@Bil_bilakapibot'}
    out=str(template or '')
    for k,v in repl.items(): out=out.replace(k,v)
    return await _bb_apply_premium_vars(out)

# Extend the already-existing welcome renderer without removing its old vars.
_BB_OLD_RENDER_WELCOME_PREMIUM=globals().get('_bb_render_welcome_vars')
def _bb_render_welcome_vars(template,user,chat,mode='welcome'):
    base=_BB_OLD_RENDER_WELCOME_PREMIUM(template,user,chat,mode) if _BB_OLD_RENDER_WELCOME_PREMIUM else str(template or '')
    # Premium is deliberately handled asynchronously at send time; this marker
    # survives until the new sender below replaces it.
    return base

async def _bb_render_welcome_async(template,user,chat,mode='welcome'):
    base=_BB_OLD_RENDER_WELCOME_PREMIUM(template,user,chat,mode) if _BB_OLD_RENDER_WELCOME_PREMIUM else str(template or '')
    return await _bb_apply_premium_vars(base)

async def _bb_send_welcome_async(chat,user,context,mode='welcome'):
    if not chat or not user or getattr(user,'is_bot',False): return False
    c=await DBX.get_chat(chat.id)
    if not c: return False
    enabled=bool(c['welcome_enabled'] if mode=='welcome' else c['goodbye_enabled'])
    if not enabled: return False
    if mode=='welcome':
        default=('👋 {name} خوش اومدی به {group} {premium}\n'
                 '📅 {date}\n⏰ {time}\n📆 {day}')
        template=c['welcome_text'] or default
        kind=(c['welcome_media_type'] or '') if 'welcome_media_type' in c.keys() else ''
        fid=(c['welcome_media_id'] or '') if 'welcome_media_id' in c.keys() else ''
    else:
        default=('👋 {name} از {group} خداحافظ!\n{premium}\n'
                 '📅 {date}\n⏰ {time}\n📆 {day}')
        template=c['goodbye_text'] or default
        kind=(c['goodbye_media_type'] or '') if 'goodbye_media_type' in c.keys() else ''
        fid=(c['goodbye_media_id'] or '') if 'goodbye_media_id' in c.keys() else ''
    text=await _bb_render_welcome_async(template,user,chat,mode)
    try:
        return await _bb_send_member_media(chat,context.bot,kind,fid,text)
    except Exception:
        return False

async def _bb_pv_join_targets():
    await _bb_premium_ux_schema()
    return await DBX.execute('SELECT target,kind,label,join_url FROM bb_pv_required_targets WHERE enabled=1 ORDER BY created_at',fetch=True)

async def _bb_target_url(target, bot):
    raw=str(target or '').strip()
    if raw.startswith('http://') or raw.startswith('https://'): return raw
    if raw.startswith('@'): return 'https://t.me/'+raw[1:]
    try:
        c=await bot.get_chat(raw)
        if getattr(c,'username',None): return 'https://t.me/'+c.username
    except Exception: pass
    return raw

async def _bb_pv_missing_targets(update,context):
    user=getattr(update,'effective_user',None)
    if not user: return []
    missing=[]
    for r in await _bb_pv_join_targets():
        target=str(r['target'])
        try:
            cm=await context.bot.get_chat_member(target,user.id)
            if cm.status in {ChatMemberStatus.LEFT,ChatMemberStatus.BANNED}:
                missing.append(r)
        except Exception:
            # If Telegram cannot verify membership, keep the destination in the
            # mandatory list rather than silently letting the user bypass it.
            missing.append(r)
    return missing

async def _bb_pv_forcejoin_message(update,context,missing=None):
    missing=missing if missing is not None else await _bb_pv_missing_targets(update,context)
    if not missing: return False
    user=update.effective_user
    template=await _bb_global_message_get('pv_forcejoin_text','🔐 برای استفاده از بیل‌بیلک ابتدا عضو مقصدهای زیر شو. {premium}')
    text=await _bb_render_global_template(template,user,None)
    rows=[]
    for r in missing:
        url=r['join_url'] or await _bb_target_url(r['target'],context.bot)
        rows.append([btn('📢 عضویت در '+safe_text(r['label'] or r['target'],35),url=url)])
    rows.append([btn('🔄 بررسی عضویت','pvfj:check')])
    await update.effective_message.reply_text(text,parse_mode='HTML',reply_markup=keyboard(rows))
    return True

async def _bb_private_start_final(update,context):
    user=update.effective_user; msg=update.effective_message; chat=update.effective_chat
    if not user or not msg or not chat or chat.type!='private': return False
    await DBX.ensure_user(user); await _bb_premium_ux_schema()
    # Self-healing migration: this table is required by /start, so create it
    # here as well as in the global schema. This keeps old SQLite databases
    # compatible even if an earlier post_init chain was skipped.
    try:
        await DBX.execute('CREATE TABLE IF NOT EXISTS bb_optin_users(user_id INTEGER PRIMARY KEY, opted_at INTEGER DEFAULT 0)')
    except Exception as exc:
        log.warning('opt-in schema repair failed: %s', exc)
    # Mark that the user has actually started the bot. This is used by the
    # leave-group private reminder; users who never started are never messaged.
    await DBX.execute('INSERT OR IGNORE INTO bb_optin_users(user_id,opted_at) VALUES(?,?)',(user.id,now_ts()))
    if await _bb_pv_forcejoin_message(update,context): return True
    if await _bb_is_bot_admin(user.id):
        await owner_panel_v6(update,context); return True
    default=('👋 سلام {name}! به بیل بیلک خوش اومدی. {premium}\n\n'
             'از دکمه‌های شیشه‌ای زیر برای شروع استفاده کن.')
    template=await _bb_global_message_get('start_user_text',default)
    text=await _bb_render_global_template(template,user,None)
    rows=[[btn('📚 راهنما','uxhelp:home')],[btn('🐕 هاپویی','u:'+str(user.id)+':dog')],
          [btn('➕ افزودن بیل بیلک به گروه',url=(f'https://t.me/{BOT_USERNAME}?startgroup=true' if BOT_USERNAME else 'https://t.me/'))]]
    b=await _bb_info_button()
    if b: rows.append([b])
    await msg.reply_text(text,parse_mode='HTML',reply_markup=keyboard(rows))
    return True

async def _bb_private_start_callback(update,context):
    q=update.callback_query; d=str(q.data or '')
    if d!='pvfj:check': return False
    missing=await _bb_pv_missing_targets(update,context)
    if missing:
        await q.answer('❌ هنوز عضویت کامل نشده.',show_alert=True)
        return True
    await q.answer('✅ عضویت تأیید شد.',show_alert=True)
    user=q.from_user
    default=('👋 سلام {name}! به بیل بیلک خوش اومدی. {premium}\n\nاز دکمه‌های شیشه‌ای زیر استفاده کن.')
    text=await _bb_render_global_template(await _bb_global_message_get('start_user_text',default),user,None)
    await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('📚 راهنما','uxhelp:home')],[btn('🐕 هاپویی','u:'+str(user.id)+':dog')]]))
    return True

