async def _bb_premium_design_callback(update,context):
    q=update.callback_query; d=str(q.data or '')
    if not d.startswith('uxdesign:'): return False
    if not await _bb_is_bot_admin(q.from_user.id): await q.answer('⛔ فقط مالک/ادمین مرکزی.',show_alert=True); return True
    action=d.split(':',1)[1]
    if action=='premium':
        ids=await _bb_premium_ids()
        await q.message.reply_text(f'✨ <b>ایموجی‌های پرمیوم</b>\n\nتعداد فعلی: <b>{len(ids)}</b>\n\nبرای ثبت، روی «ثبت ایموجی» بزن و بعد <b>خودِ Premium Custom Emoji</b> را بفرست؛ ID لازم نیست.',parse_mode='HTML',reply_markup=keyboard([[btn('➕ ثبت ایموجی','uxdesign:padd')],[btn('🗑 حذف همه','uxdesign:pclear')],[btn('🔙 طراحی','uxdesign:home')]])); return True
    if action=='padd':
        _BB_PREMIUM_DESIGN_PENDING[q.from_user.id]='premium'
        await q.message.reply_text('✨ خودِ ایموجی پرمیومی را همینجا بفرست.\nفقط یک Custom Emoji در پیام بفرست؛ ربات ID واقعی را خودش از entity می‌خواند.')
        return True
    if action=='pclear':
        await DBX.execute('DELETE FROM bb_premium_pool'); await q.answer('لیست ایموجی‌های پرمیوم پاک شد.',show_alert=True); return True
    if action=='home': return await _bb_premium_design_panel(type('U',(),{'effective_user':q.from_user,'effective_message':q.message,'effective_chat':q.message.chat})(),context)
    if action in {'help','welcome','goodbye','start','hapoo','daughter','forcejoin'}:
        key={'help':'guide_text','welcome':'welcome_text','goodbye':'goodbye_text','start':'start_user_text','hapoo':'hapoo_text','daughter':'daughter_baba_text','forcejoin':'pv_forcejoin_text'}[action]
        _BB_PREMIUM_DESIGN_PENDING[q.from_user.id]=key
        current=await _bb_global_message_get(key,'')
        label={'help':'راهنما','welcome':'خوش‌آمد','goodbye':'خداحافظی','start':'پیام /start','hapoo':'هاپویی','daughter':'دختر بابا','forcejoin':'جوین اجباری'}[action]
        await q.message.reply_text(f'📝 <b>طراحی {label}</b>\n\nمتن جدید را بفرست.\nمتغیرها: {{name}} {{id}} {{username}} {{group}} {{date}} {{time}} {{day}} {{premium}}\n\nمتن فعلی:\n{safe_text(current or "ثبت نشده",1800)}')
        return True
    if action=='ads':
        rows=await DBX.execute('SELECT target,kind,label FROM bb_pv_required_targets ORDER BY created_at',fetch=True)
        body='\n'.join(f'• {safe_text(r["label"] or r["target"],60)} — {r["kind"]}' for r in rows) or 'هیچ مقصدی ثبت نشده.'
        await q.message.reply_text('📢 <b>تبلیغات/جوین اجباری PV</b>\n\n'+body+'\n\nدستورها:\n<code>ثبت کانال @channel</code>\n<code>ثبت تبلیغ @channel</code>\n<code>حذف تبلیغ @channel</code>\n<code>حذف کانال @channel</code>\n<code>لیست تبلیغات</code>',parse_mode='HTML'); return True
    return True

async def _bb_premium_design_text(update,context):
    msg=update.effective_message; user=update.effective_user
    if not msg or not user or not await _bb_is_bot_admin(user.id): return False
    pending=_BB_PREMIUM_DESIGN_PENDING.get(user.id)
    if not pending: return False
    if pending=='premium':
        eid=_bb_custom_emoji_id_from_message(msg)
        if not eid:
            await msg.reply_text('❌ یک Premium Custom Emoji واقعی بفرست؛ ID تایپ نکن.')
            return True
        await _bb_premium_ux_schema()
        await DBX.execute('INSERT OR IGNORE INTO bb_premium_pool(emoji_id,enabled,created_at) VALUES(?,?,?)',(eid,1,now_ts()))
        _BB_PREMIUM_DESIGN_PENDING.pop(user.id,None)
        await msg.reply_text('✅ ایموجی پرمیومی ثبت شد و از این به بعد متغیر {premium} می‌تواند تصادفی از آن استفاده کند.')
        return True
    if not isinstance(pending,str): return False
    text=msg.text or ''
    if not text.strip(): return False
    if pending=='guide_text':
        await _bb_global_message_set('guide_text',text)
    else:
        await _bb_global_message_set(pending,text)
    _BB_PREMIUM_DESIGN_PENDING.pop(user.id,None)
    await msg.reply_text('✅ طراحی ذخیره شد. از این به بعد نسخه جدید در همان بخش نمایش داده می‌شود.')
    return True

