async def _bb_owner_global_target_command(update,context):
    msg=update.effective_message; user=update.effective_user; chat=update.effective_chat
    if not msg or not user or chat.type!='private' or not await _bb_is_bot_admin(user.id): return False
    t=_bb_plain_tool_text(msg.text or '')
    if t in {'لیست تبلیغات','لیست کانال‌ها','لیست کانال ها'}:
        rows=await DBX.execute('SELECT target,kind,label FROM bb_pv_required_targets ORDER BY created_at',fetch=True)
        body='\n'.join(f'• {safe_text(r["label"] or r["target"],70)} — {r["kind"]}' for r in rows) or 'هیچ مقصدی ثبت نشده.'
        await msg.reply_text('📢 <b>لیست جوین اجباری PV</b>\n\n'+body,parse_mode='HTML'); return True
    m=re.match(r'^(ثبت کانال|ثبت تبلیغ)\s+(.+)$',t)
    if m:
        target=m.group(2).strip(); kind='channel' if m.group(1)=='ثبت کانال' else 'ad'
        try:
            c=await context.bot.get_chat(target)
            label=getattr(c,'title',None) or getattr(c,'username',None) or target
            url=await _bb_target_url(target,context.bot)
            await context.bot.get_chat_member(target,user.id)  # validates target resolution where possible
        except Exception as exc:
            await msg.reply_text('❌ مقصد قابل بررسی نیست. برای کانال/گروه عمومی @username یا لینک t.me بده و مطمئن شو ربات دسترسی لازم برای بررسی عضویت دارد.')
            return True
        await _bb_premium_ux_schema()
        await DBX.execute('INSERT INTO bb_pv_required_targets(target,kind,label,join_url,enabled,created_at) VALUES(?,?,?,?,1,?) ON CONFLICT(target) DO UPDATE SET kind=excluded.kind,label=excluded.label,join_url=excluded.join_url,enabled=1',(target,kind,safe_text(label,100),url,now_ts()))
        await msg.reply_text(f'✅ {"تبلیغ" if kind=="ad" else "کانال"} ثبت شد و از این به بعد فقط در <b>PV ربات</b> در لیست جوین اجباری نمایش داده می‌شود.',parse_mode='HTML'); return True
    m=re.match(r'^(حذف تبلیغ|حذف کانال)\s+(.+)$',t)
    if m:
        target=m.group(2).strip(); await DBX.execute('DELETE FROM bb_pv_required_targets WHERE target=?',(target,)); await msg.reply_text('🗑 از لیست جوین اجباری PV حذف شد.'); return True
    return False

async def _bb_pv_leave_reminder(update,context):
    cm=getattr(update,'chat_member',None)
    if not cm or not cm.chat or cm.chat.type=='private': return
    old=str(cm.old_chat_member.status); new=str(cm.new_chat_member.status)
    user=cm.new_chat_member.user
    if not user or getattr(user,'is_bot',False): return
    if new not in {ChatMemberStatus.LEFT,ChatMemberStatus.BANNED}: return
    if old not in {ChatMemberStatus.MEMBER,ChatMemberStatus.RESTRICTED,ChatMemberStatus.ADMINISTRATOR}: return
    # Always enabled for every group; there is intentionally no opt-in/toggle gate.
    # Telegram still requires that the user has previously opened the bot in private
    # (otherwise the private message cannot be delivered).
    dedupe=context.application.bot_data.setdefault('bb_leave_pv_dedupe', {})
    import time as _time
    _dk=(int(cm.chat.id), int(user.id))
    _now=_time.time()
    if _now-float(dedupe.get(_dk,0)) < 12:
        return
    dedupe[_dk]=_now
    # Keep this map bounded.
    if len(dedupe)>5000:
        cutoff=_now-120
        for _k,_v in list(dedupe.items()):
            if _v<cutoff: dedupe.pop(_k,None)
    try:
        botme=await context.bot.get_me(); username=getattr(botme,'username','') or BOT_USERNAME
        group_url=''
        if getattr(cm.chat,'username',None): group_url='https://t.me/'+cm.chat.username
        else:
            # Private groups cannot be turned into a public t.me URL. If the bot
            # can create an invite, create one for the reminder button.
            try: group_url=(await context.bot.create_chat_invite_link(cm.chat.id,name='return-reminder')).invite_link
            except Exception: group_url=''
        text=await _bb_render_global_template('🥺 {name}، بدون تو گروه خوش نمی‌گذره!\n\nهمین الان بیا 🐾 {premium}',user,cm.chat)
        rows=[[btn('🐾 همین الان بیا',url=group_url)]] if group_url else []
        if rows: await context.bot.send_message(user.id,text,parse_mode='HTML',reply_markup=keyboard(rows))
        else: await context.bot.send_message(user.id,text,parse_mode='HTML')
    except Exception as exc:
        log.debug('private leave reminder skipped user=%s: %s',getattr(user,'id',0),exc)

# Make the global PV targets participate in /start before the old start UI.
# Group starts remain exactly on the legacy path.
_BB_OLD_START_FINAL_UX=globals().get('start_v8')
async def start_v8(update,context):
    if update.effective_chat and update.effective_chat.type=='private':
        if await _bb_private_start_final(update,context): return
    if _BB_OLD_START_FINAL_UX:
        return await _BB_OLD_START_FINAL_UX(update,context)

# The configurable group welcome/goodbye sender is wired at the member-event
# layer; legacy handling remains the fallback for groups without customization.
_BB_OLD_MEMBER_UPDATE_UX=globals().get('member_update_v6')
async def member_update_v6(update,context):
    try:
        cm=getattr(update,'chat_member',None)
        if cm and cm.chat and cm.chat.type!='private':
            old=cm.old_chat_member.status; new=cm.new_chat_member.status; user=cm.new_chat_member.user
            active={ChatMemberStatus.MEMBER,ChatMemberStatus.RESTRICTED,ChatMemberStatus.ADMINISTRATOR,ChatMemberStatus.OWNER}
            joined=new in active and old in {ChatMemberStatus.LEFT,ChatMemberStatus.BANNED}
            left=new in {ChatMemberStatus.LEFT,ChatMemberStatus.BANNED} and old in active
            c=await DBX.get_chat(cm.chat.id)
            if joined and c and c['welcome_enabled']:
                await _bb_send_welcome_async(cm.chat,user,context,'welcome')
                # Do not call the old join sender when custom premium/date text exists.
                if '{premium}' in str(c['welcome_text'] or '') or '{date}' in str(c['welcome_text'] or '') or '{time}' in str(c['welcome_text'] or ''):
                    return
            if left and c and c['goodbye_enabled']:
                await _bb_send_welcome_async(cm.chat,user,context,'goodbye')
                if '{premium}' in str(c['goodbye_text'] or '') or '{date}' in str(c['goodbye_text'] or '') or '{time}' in str(c['goodbye_text'] or ''):
                    await _bb_pv_leave_reminder(update,context)
                    return
            if left:
                await _bb_pv_leave_reminder(update,context)
    except Exception as exc:
        log.debug('ux member layer: %s',exc)
    if _BB_OLD_MEMBER_UPDATE_UX:
        return await _BB_OLD_MEMBER_UPDATE_UX(update,context)

# Design command: a single glass panel for all user-facing text systems.
async def _bb_design_command_final(update,context):
    if await _bb_owner_gate(update):
        await _bb_premium_design_panel(update,context)

_BB_BUILD_BEFORE_PREMIUM_UX=build_application
def build_application(token):
    app=_BB_BUILD_BEFORE_PREMIUM_UX(token)
    app.add_handler(CommandHandler('design',_bb_design_command_final),group=-30000)
    # Persian command names are not valid Telegram BotCommand tokens. Keep `طراحی` as a normal text command.
    app.add_handler(MessageHandler(filters.Regex(r'^\s*طراحی\s*$'),_bb_design_command_final),group=-29999)
    app.add_handler(CallbackQueryHandler(_bb_premium_design_callback,pattern=r'^uxdesign:'),group=-30001)
    app.add_handler(CallbackQueryHandler(_bb_glass_help,pattern=r'^uxhelp:'),group=-30002)
    app.add_handler(CallbackQueryHandler(_bb_glass_help_callback,pattern=r'^uxhelp:'),group=-30003)
    app.add_handler(CallbackQueryHandler(_bb_private_start_callback,pattern=r'^pvfj:'),group=-30004)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_premium_design_text),group=-30005)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_owner_global_target_command),group=-30006)
    app.add_handler(ChatMemberHandler(_bb_pv_leave_reminder,ChatMemberHandler.CHAT_MEMBER),group=-30007)
    app.add_handler(CommandHandler('start',start_v8),group=-30008)
    async def _ux_post_init(application):
        old=getattr(application,'post_init',None)
        if old: await old(application)
        await _bb_premium_ux_schema()
    app.post_init=_ux_post_init
    return app

# --- Final polish for premium templates and the glass guide ---
_BB_OLD_FORCEJOIN_UX_PREMIUM=globals().get('enforce_forcejoin')
async def enforce_forcejoin(update,context):
    # Preserve the existing per-group membership logic, but allow {premium} in
    # the configured force-join message.
    if not update.effective_chat or update.effective_chat.type=='private':
        return False
    chat=update.effective_chat; user=update.effective_user; msg=update.effective_message
    if not user or not msg or await is_admin(update,user.id): return False
    c=await DBX.get_chat(chat.id)
    channel=(c['forced_channel'] if c else '') or ''
    if not channel: return False
    try:
        member=await context.bot.get_chat_member(channel,user.id)
        if member.status in {ChatMemberStatus.MEMBER,ChatMemberStatus.ADMINISTRATOR,ChatMemberStatus.OWNER,ChatMemberStatus.RESTRICTED}:
            return False
    except Exception: pass
    try: await msg.delete()
    except Exception: pass
    join_url=channel if str(channel).startswith('http') else 'https://t.me/'+str(channel).lstrip('@').strip()
    custom=''
    try:
        row=await DBX.one('SELECT forcejoin_text FROM group_extra_settings WHERE chat_id=?',(chat.id,))
        custom=(row['forcejoin_text'] if row else '') or ''
    except Exception: pass
    text=custom or '🔐 <b>عضویت اجباری فعال است</b>\n\n{name} برای ارسال پیام باید ابتدا عضو کانال شود. {premium}'
    text=await _bb_render_global_template(text,user,chat)
    try:
        await chat.send_message(text,parse_mode='HTML',reply_markup=keyboard([[btn('📢 عضویت در کانال',url=join_url)]]))
    except Exception: pass
    return True

_BB_OLD_HAPOO_PANEL_DESIGN=globals().get('_bb_hapoo_panel')
async def _bb_hapoo_panel(q,uid):
    if not _BB_OLD_HAPOO_PANEL_DESIGN:
        return
    await _BB_OLD_HAPOO_PANEL_DESIGN(q,uid)
    try:
        custom=await _bb_global_message_get('hapoo_text','')
        if custom and getattr(q,'message',None):
            body=getattr(q.message,'text',None) or ''
            # Avoid duplicating the designed header if the owner saved it twice.
            if body and custom.strip() not in body:
                await q.edit_message_text(custom+'\n\n'+body,parse_mode='HTML',reply_markup=getattr(q.message,'reply_markup',None))
    except Exception as exc:
        log.debug('hapoo design render: %s',exc)

# Guide body is also owner-designable; the navigation remains entirely glass.
