# ============================================================================
# FINAL ARCADE REBUILD — compact, interactive, glass UI
# The legacy game catalog is intentionally no longer exposed through the user
# interface. This layer provides the new arcade entry-point and owns its routes.
# ============================================================================
_BB_ARCADE_ROOMS = {}
_BB_ARCADE_SINGLE = {}
_BB_ARCADE_GAMES = ('aim', 'guess', 'rps', 'ttt', 'quiz')
_BB_ARCADE_GAME_LABELS = {
    'aim': '🎯 شکار ستاره',
    'guess': '🧠 حدس عدد',
    'rps': '✂️ سنگ کاغذ قیچی',
    'ttt': '❌⭕ دوز',
    'quiz': '⚡ مسابقه سرعت',
}
_BB_ARCADE_EMOJI_FALLBACK = {'aim':'🎯','guess':'🧠','rps':'✂️','ttt':'❌','quiz':'⚡'}

async def _bb_arcade_schema():
    await DBX.execute('CREATE TABLE IF NOT EXISTS bb_arcade_premium_emojis(slot TEXT PRIMARY KEY, emoji_id TEXT NOT NULL DEFAULT "", updated_at INTEGER DEFAULT 0)')
    await DBX.execute('CREATE TABLE IF NOT EXISTS bb_arcade_settings(key TEXT PRIMARY KEY, value TEXT DEFAULT "", updated_at INTEGER DEFAULT 0)')

async def _bb_arcade_emoji(slot='default'):
    try:
        await _bb_arcade_schema()
        rows=await DBX.execute('SELECT emoji_id FROM bb_arcade_premium_emojis WHERE emoji_id<>""',( ),fetch=True)
        if rows:
            import random as _arc_random
            return str(_arc_random.choice(rows)['emoji_id'])
    except Exception:
        pass
    return ''

def _bb_arcade_emoji_html(eid, fallback):
    if eid:
        return f'<tg-emoji emoji-id="{safe_text(str(eid),80)}">{fallback}</tg-emoji>'
    return fallback

async def _bb_arcade_header(title, subtitle=''):
    eid=await _bb_arcade_emoji()
    icon=_bb_arcade_emoji_html(eid,'🎮')
    return f'{icon} <b>شهربازی بیل‌بیلک</b>\n\n<b>{safe_text(title,100)}</b>\n{safe_text(subtitle,500)}'

def _bb_arcade_panel_markup():
    return keyboard([
        [btn('🎯 تک‌نفره','arc:single'),btn('⚔️ دونفره','arc:duo')],
        [btn('👥 چندنفره','arc:multi'),btn('🏆 امتیازات','arc:scores')],
        [btn('✨ قوانین','arc:rules')]
    ])

async def _bb_arcade_home(update, context):
    msg=update.effective_message
    if not msg: return True
    await _bb_arcade_schema()
    text=await _bb_arcade_header('مرکز بازی', 'کم‌تعداد، سریع و واقعاً قابل بازی؛ هر بازی با دکمه‌های شیشه‌ای اجرا می‌شود.')
    await msg.reply_text(text,parse_mode='HTML',reply_markup=_bb_arcade_panel_markup())
    return True

async def _bb_arcade_menu_callback(update, context):
    q=update.callback_query; d=str(q.data or '') if q else ''
    if not d.startswith('arc:'): return False
    await _bb_arcade_schema()
    if d=='arc:home':
        await q.edit_message_text(await _bb_arcade_header('مرکز بازی','یک حالت را انتخاب کن.'),parse_mode='HTML',reply_markup=_bb_arcade_panel_markup()); return True
    if d=='arc:single':
        await q.edit_message_text(await _bb_arcade_header('بازی‌های تک‌نفره','خودت با ربات رقابت کن.'),parse_mode='HTML',reply_markup=keyboard([
            [btn('🎯 شکار ستاره','arc:start:aim')],[btn('🧠 حدس عدد','arc:start:guess')],[btn('🔙 شهربازی','arc:home')]
        ])); return True
    if d=='arc:duo':
        await q.edit_message_text(await _bb_arcade_header('بازی‌های دونفره','حریف را با دکمه ورود به اتاق دعوت کن.'),parse_mode='HTML',reply_markup=keyboard([
            [btn('✂️ سنگ کاغذ قیچی','arc:start:rps')],[btn('❌⭕ دوز','arc:start:ttt')],[btn('🎭 جرأت حقیقت','arc:start:truth')],[btn('🔙 شهربازی','arc:home')]
        ])); return True
    if d=='arc:multi':
        await q.edit_message_text(await _bb_arcade_header('بازی چندنفره','یک اتاق بساز و دوستانت را وارد کن.'),parse_mode='HTML',reply_markup=keyboard([
            [btn('⚡ مسابقه سرعت','arc:start:quiz')],[btn('📝 اسم فامیل','arc:start:family')],[btn('🔙 شهربازی','arc:home')]
        ])); return True
    if d=='arc:rules':
        await q.edit_message_text(await _bb_arcade_header('قوانین','بدون پول، شرط یا قمار؛ فقط بازی و امتیاز.\n\n• تک‌نفره: امتیاز برای رکورد شخصی\n• دونفره: یک اتاق برای دو بازیکن\n• چندنفره: چند بازیکن در یک اتاق\n• هر بازی با دکمه‌های شیشه‌ای کنترل می‌شود.'),parse_mode='HTML',reply_markup=keyboard([[btn('🔙 شهربازی','arc:home')]])); return True
    if d=='arc:scores':
        rows=await DBX.execute('SELECT user_id, SUM(points) p FROM safe_game_stats GROUP BY user_id ORDER BY p DESC LIMIT 10',(),fetch=True)
        lines=['🏆 <b>امتیازات شهربازی</b>','']
        if rows:
            for i,r in enumerate(rows,1): lines.append(f'{i}. <code>{r["user_id"]}</code> — <b>{int(r["p"] or 0)}</b>')
        else: lines.append('هنوز امتیازی ثبت نشده است.')
        await q.edit_message_text('\n'.join(lines),parse_mode='HTML',reply_markup=keyboard([[btn('🔙 شهربازی','arc:home')]])); return True
    if d.startswith('arc:start:'):
        game=d.rsplit(':',1)[-1]
        if game=='aim': return await _bb_arcade_start_aim(q,context)
        if game=='guess': return await _bb_arcade_start_guess(q,context)
        if game in ('rps','ttt'): return await _bb_arcade_start_duo(q,context,game)
        if game=='quiz': return await _bb_arcade_start_quiz(q,context)
    return False

async def _bb_arcade_add_score(uid, points):
    try:
        await DBX.execute('INSERT INTO safe_game_stats(user_id,points) VALUES(?,?)',(uid,int(points)))
    except Exception:
        pass

async def _bb_arcade_start_aim(q,context):
    import random as _arc_random
    uid=q.from_user.id; target=_arc_random.randint(1,5)
    _BB_ARCADE_SINGLE[uid]={'game':'aim','target':target,'tries':0}
    await q.edit_message_text(await _bb_arcade_header('🎯 شکار ستاره','یکی از پنج ستاره را انتخاب کن؛ فقط یکی هدف است.'),parse_mode='HTML',reply_markup=keyboard([
        [btn('⭐ ۱','arc:aim:1'),btn('⭐ ۲','arc:aim:2'),btn('⭐ ۳','arc:aim:3')],
        [btn('⭐ ۴','arc:aim:4'),btn('⭐ ۵','arc:aim:5')],[btn('🔙 شهربازی','arc:home')]
    ]))
    return True

async def _bb_arcade_start_guess(q,context):
    import random as _arc_random
    uid=q.from_user.id; secret=_arc_random.randint(1,20)
    _BB_ARCADE_SINGLE[uid]={'game':'guess','secret':secret,'tries':0}
    await q.edit_message_text(await _bb_arcade_header('🧠 حدس عدد','یک عدد بین ۱ تا ۲۰ را انتخاب کن.'),parse_mode='HTML',reply_markup=keyboard([
        [btn(str(i),f'arc:guess:{i}') for i in range(1,6)],
        [btn(str(i),f'arc:guess:{i}') for i in range(6,11)],
        [btn('صفحه ۲','arc:guesspage:2')],[btn('🔙 شهربازی','arc:home')]
    ]))
    return True

async def _bb_arcade_start_duo(q,context,game):
    cid=q.message.chat.id; uid=q.from_user.id
    _BB_ARCADE_ROOMS[(cid,game)]={'game':game,'owner':uid,'players':{uid:q.from_user.first_name or 'بازیکن'},'board':['']*9,'turn':uid,'choices':{}}
    label=_BB_ARCADE_GAME_LABELS[game]
    await q.edit_message_text(await _bb_arcade_header(label,'اتاق ساخته شد؛ نفر دوم روی «ورود» بزند.'),parse_mode='HTML',reply_markup=keyboard([
        [btn('➕ ورود به اتاق',f'arc:join:{game}')],[btn('▶️ شروع',f'arc:duostart:{game}')],[btn('🔙 شهربازی','arc:home')]
    ]))
    return True

async def _bb_arcade_start_quiz(q,context):
    cid=q.message.chat.id; uid=q.from_user.id
    _BB_ARCADE_ROOMS[(cid,'quiz')]={'game':'quiz','owner':uid,'players':{uid:q.from_user.first_name or 'بازیکن'},'scores':{},'started':False,'question':None}
    await q.edit_message_text(await _bb_arcade_header('⚡ مسابقه سرعت','اتاق ساخته شد؛ دوستانت را با «ورود» جمع کن.'),parse_mode='HTML',reply_markup=keyboard([
        [btn('➕ ورود', 'arc:join:quiz')],[btn('▶️ شروع مسابقه','arc:duostart:quiz')],[btn('🔙 شهربازی','arc:home')]
    ])); return True

async def _bb_arcade_callback_game(update,context):
    q=update.callback_query; d=str(q.data or '') if q else ''; uid=q.from_user.id; cid=q.message.chat.id
    if not d.startswith('arc:'): return False
    if d.startswith('arc:aim:'):
        st=_BB_ARCADE_SINGLE.get(uid)
        if not st or st.get('game')!='aim': await q.answer('اول بازی را شروع کن.',show_alert=True); return True
        pick=int(d.rsplit(':',1)[-1]); st['tries']+=1
        if pick==st['target']:
            points=max(5,20-st['tries']*3); await _bb_arcade_add_score(uid,points)
            _BB_ARCADE_SINGLE.pop(uid,None)
            await q.edit_message_text(await _bb_arcade_header('🎯 بردی! ',f'ستاره درست را پیدا کردی. +{points} امتیاز'),parse_mode='HTML',reply_markup=keyboard([[btn('🔁 دوباره','arc:start:aim'),btn('🎮 شهربازی','arc:home')]]))
        else:
            await q.answer('این ستاره نبود؛ دوباره امتحان کن!')
        return True
    if d.startswith('arc:guesspage:'):
        page=int(d.rsplit(':',1)[-1]); nums=range(11,21) if page==2 else range(1,11)
        rows=[[btn(str(i),f'arc:guess:{i}') for i in list(nums)[r:r+5]] for r in range(0,10,5)]
        rows.append([btn('صفحه ۱','arc:guesspage:1'),btn('🔙 شهربازی','arc:home')])
        await q.edit_message_text(await _bb_arcade_header('🧠 حدس عدد','عددت را انتخاب کن.'),parse_mode='HTML',reply_markup=keyboard(rows)); return True
    if d.startswith('arc:guess:'):
        st=_BB_ARCADE_SINGLE.get(uid)
        if not st or st.get('game')!='guess': await q.answer('اول بازی را شروع کن.',show_alert=True); return True
        pick=int(d.rsplit(':',1)[-1]); st['tries']+=1; sec=st['secret']
        if pick==sec:
            points=max(5,30-st['tries']*2); await _bb_arcade_add_score(uid,points); _BB_ARCADE_SINGLE.pop(uid,None)
            await q.edit_message_text(await _bb_arcade_header('🧠 درست حدس زدی!',f'عدد {sec} بود. +{points} امتیاز'),parse_mode='HTML',reply_markup=keyboard([[btn('🔁 دوباره','arc:start:guess'),btn('🎮 شهربازی','arc:home')]]))
        else:
            hint='بالاتر ⬆️' if pick<sec else 'پایین‌تر ⬇️'
            await q.answer(hint)
        return True
    if d.startswith('arc:join:'):
        game=d.rsplit(':',1)[-1]; room=_BB_ARCADE_ROOMS.get((cid,game))
        if not room: await q.answer('اتاق پیدا نشد.',show_alert=True); return True
        if uid not in room['players']:
            if game in ('rps','ttt') and len(room['players'])>=2: await q.answer('این بازی فقط دو نفره است.',show_alert=True); return True
            room['players'][uid]=q.from_user.first_name or 'بازیکن'
        await q.answer('وارد اتاق شدی!')
        return True
    if d.startswith('arc:duostart:'):
        game=d.rsplit(':',1)[-1]; room=_BB_ARCADE_ROOMS.get((cid,game))
        if not room: await q.answer('اتاق پیدا نشد.',show_alert=True); return True
        if uid!=room['owner']: await q.answer('فقط سازنده می‌تواند شروع کند.',show_alert=True); return True
        if game in ('rps','ttt') and len(room['players'])!=2: await q.answer('برای شروع دو بازیکن لازم است.',show_alert=True); return True
        if game=='rps':
            await q.edit_message_text(await _bb_arcade_header('✂️ سنگ کاغذ قیچی','هر دو بازیکن انتخاب کنند؛ نتیجه بعد از انتخاب نفر دوم مشخص می‌شود.'),parse_mode='HTML',reply_markup=keyboard([[btn('🪨 سنگ','arc:rps:rock'),btn('📄 کاغذ','arc:rps:paper'),btn('✂️ قیچی','arc:rps:scissors')],[btn('🎮 شهربازی','arc:home')]])); return True
        if game=='ttt':
            room['turn']=list(room['players'])[0]; await _bb_arcade_render_ttt(q,room,cid); return True
        if game=='quiz':
            if len(room['players'])<2: await q.answer('حداقل دو بازیکن لازم است.',show_alert=True); return True
            room['started']=True; room['scores']={u:0 for u in room['players']}; await _bb_arcade_quiz_question(q,room,cid); return True
    if d.startswith('arc:rps:'):
        room=_BB_ARCADE_ROOMS.get((cid,'rps'))
        if not room or uid not in room['players']: await q.answer('اول وارد اتاق شو.',show_alert=True); return True
        room['choices'][uid]=d.rsplit(':',1)[-1]
        if len(room['choices'])<2: await q.answer('انتخاب ثبت شد؛ منتظر حریف...'); return True
        ids=list(room['players']); a,b=ids[0],ids[1]; ca,cb=room['choices'][a],room['choices'][b]
        winner=None if ca==cb else (a if (ca,cb) in {('rock','scissors'),('scissors','paper'),('paper','rock')} else b)
        if winner: await _bb_arcade_add_score(winner,10)
        names=room['players']; result='مساوی شد.' if not winner else f'🏆 {safe_text(names[winner],50)} برنده شد! +۱۰ امتیاز'
        room['choices']={}
        await q.edit_message_text(await _bb_arcade_header('✂️ نتیجه',result),parse_mode='HTML',reply_markup=keyboard([[btn('🔁 دور بعد','arc:duostart:rps'),btn('🎮 شهربازی','arc:home')]])); return True
    if d.startswith('arc:ttt:'):
        room=_BB_ARCADE_ROOMS.get((cid,'ttt'))
        if not room or uid!=room.get('turn'): await q.answer('الان نوبت تو نیست.',show_alert=True); return True
        idx=int(d.rsplit(':',1)[-1]);
        if room['board'][idx]: await q.answer('این خانه پر است.'); return True
        ids=list(room['players']); mark='X' if uid==ids[0] else 'O'; room['board'][idx]=mark; room['turn']=ids[1] if uid==ids[0] else ids[0]
        board=room['board']; wins=((0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6))
        win=next((line for line in wins if board[line[0]] and board[line[0]]==board[line[1]]==board[line[2]]),None)
        if win:
            await _bb_arcade_add_score(uid,15); room['board']=['']*9
            await q.edit_message_text(await _bb_arcade_header('❌⭕ برد!',f'{safe_text(room["players"][uid],50)} برنده شد! +۱۵ امتیاز'),parse_mode='HTML',reply_markup=keyboard([[btn('🔁 دوباره','arc:duostart:ttt'),btn('🎮 شهربازی','arc:home')]])); return True
        if all(board):
            room['board']=['']*9; await q.edit_message_text(await _bb_arcade_header('❌⭕ مساوی','هیچ‌کس برنده نشد.'),parse_mode='HTML',reply_markup=keyboard([[btn('🔁 دوباره','arc:duostart:ttt'),btn('🎮 شهربازی','arc:home')]])); return True
        await _bb_arcade_render_ttt(q,room,cid); return True
    return False

async def _bb_arcade_render_ttt(q,room,cid):
    b=room['board']; rows=[]
    for r in range(0,9,3):
        rows.append([btn(b[i] or '▫️',f'arc:ttt:{i}') for i in range(r,r+3)])
    turn=room['players'].get(room['turn'],'بازیکن')
    rows.append([btn(f'نوبت: {turn}','arc:home')])
    rows.append([btn('🎮 شهربازی','arc:home')])
    await q.edit_message_text(await _bb_arcade_header('❌⭕ دوز',f'نوبت {safe_text(turn,50)}'),parse_mode='HTML',reply_markup=keyboard(rows))

_BB_ARCADE_QUIZ_POOL=[
    ('پایتخت ایران کدام است؟',['تهران','شیراز','تبریز','مشهد'],0),
    ('کدام سیاره به سیاره سرخ معروف است؟',['زهره','مریخ','مشتری','عطارد'],1),
    ('۵ × ۶ چند می‌شود؟',['۲۰','۲۵','۳۰','۳۵'],2),
    ('کدام حیوان پستاندار است؟',['کبوتر','مار','دلفین','مارمولک'],2),
]
async def _bb_arcade_quiz_question(q,room,cid):
    import random as _arc_random
    item=_arc_random.choice(_BB_ARCADE_QUIZ_POOL); room['question']=item
    opts=item[1]; rows=[[btn(f'{i+1}. {safe_text(x,40)}',f'arc:quiz:{i}') for i,x in enumerate(opts[:2])],[btn(f'{i+3}. {safe_text(x,40)}',f'arc:quiz:{i+2}') for i,x in enumerate(opts[2:])]]
    await q.edit_message_text(await _bb_arcade_header('⚡ مسابقه سرعت',item[0]),parse_mode='HTML',reply_markup=keyboard(rows))

async def _bb_arcade_quiz_callback(update,context):
    q=update.callback_query; d=str(q.data or '') if q else ''
    if not d.startswith('arc:quiz:'): return False
    cid=q.message.chat.id; uid=q.from_user.id; room=_BB_ARCADE_ROOMS.get((cid,'quiz'))
    if not room or not room.get('started') or uid not in room['players']: await q.answer('مسابقه فعال نیست.',show_alert=True); return True
    pick=int(d.rsplit(':',1)[-1]); item=room.get('question')
    if not item: return True
    if pick==item[2]: room['scores'][uid]=room['scores'].get(uid,0)+10; await _bb_arcade_add_score(uid,10); await q.answer('+۱۰ امتیاز 🎉')
    else: await q.answer('جواب اشتباه بود.')
    if max(room['scores'].values() or [0])>=30:
        winner=max(room['scores'],key=room['scores'].get); name=room['players'][winner]
        await q.edit_message_text(await _bb_arcade_header('⚡ پایان مسابقه',f'🏆 {safe_text(name,50)} با {room["scores"][winner]} امتیاز برنده شد.'),parse_mode='HTML',reply_markup=keyboard([[btn('🔁 مسابقه جدید','arc:start:quiz'),btn('🎮 شهربازی','arc:home')]])); return True
    await _bb_arcade_quiz_question(q,room,cid); return True

async def _bb_arcade_owner_panel(update,context):
    q=update.callback_query
    if q and not await owner_check(q.from_user.id): await q.answer('⛔ فقط سازنده.',show_alert=True); return True
    await _bb_arcade_schema()
    rows=await DBX.execute('SELECT slot,emoji_id FROM bb_arcade_premium_emojis ORDER BY slot',(),fetch=True)
