# ARCADE EXTENSION — TRUTH/DARE + NAME/FAMILY
# These two games are added to the compact arcade without reviving the legacy
# game catalog.  Name/Family reuses its existing multiplayer room engine.
# =============================================================================
async def _bb_arcade_truth_family_start(update, context):
    q=update.callback_query
    d=str(q.data or '') if q else ''
    if not q or not d.startswith('arc:start:'):
        return False
    game=d.rsplit(':',1)[-1]
    if game not in ('truth','family'):
        return False
    if game=='truth':
        await q.edit_message_text(
            await _bb_arcade_header('🎭 جرأت یا حقیقت','یکی را انتخاب کن؛ سوال‌ها و چالش‌ها از لیست ثبت‌شده یا بانک پیش‌فرض انتخاب می‌شوند.'),
            parse_mode='HTML',
            reply_markup=keyboard([
                [btn('💬 حقیقت','arc:truth:truth'),btn('🎯 جرأت','arc:truth:dare')],
                [btn('🎮 شهربازی','arc:home')]
            ])
        )
        return True
    # اسم فامیل: create/reuse the established multiplayer room and let the
    # existing nf:* callback engine handle joining, rounds and scoring.
    chat=q.message.chat
    user=q.from_user
    if chat.id not in NAME_FAMILY_ROOMS or NAME_FAMILY_ROOMS.get(chat.id,{}).get('state')=='ended':
        NAME_FAMILY_ROOMS[chat.id]=_nf_make_room(chat.id,user.id)
    room=NAME_FAMILY_ROOMS[chat.id]
    room['host_id']=user.id
    await q.edit_message_text(
        _nf_board(room),
        parse_mode='HTML',
        reply_markup=keyboard([
            [btn('➕ پیوستن','nf:join:'+str(chat.id)),btn('▶️ شروع دور اول','nf:start:'+str(chat.id))],
            [btn('🌐 زبان','nf:lang:'+str(chat.id)),btn('🔢 تعداد دور','nf:rounds:'+str(chat.id))],
            [btn('📚 راهنما','nf:help:'+str(chat.id))],
            [btn('🎮 شهربازی','arc:home')]
        ])
    )
    return True

async def _bb_arcade_truth_callback(update, context):
    q=update.callback_query
    d=str(q.data or '') if q else ''
    if not d.startswith('arc:truth:'):
        return False
    kind=d.rsplit(':',1)[-1]
    if kind not in ('truth','dare'):
        return False
    # Prefer the owner's globally registered list; fall back to the existing
    # built-in safe prompts when no custom item exists.
    try:
        rows=await DBX.execute('SELECT item FROM bb_game_lists WHERE game=? ORDER BY rowid',(kind,),fetch=True)
    except Exception:
        rows=[]
    import random as _arc_random
    if rows:
        item=str(_arc_random.choice(rows)['item'])
    elif kind=='truth':
        item=_arc_random.choice(TRUTH_QUESTIONS)
    else:
        item=_arc_random.choice(DARES)
    title='💬 حقیقت' if kind=='truth' else '🎯 جرأت'
    await q.edit_message_text(
        await _bb_arcade_header(title,item),
        parse_mode='HTML',
        reply_markup=keyboard([
            [btn('🔁 مورد جدید',f'arc:truth:{kind}')],
            [btn('🎭 جرأت یا حقیقت','arc:start:truth'),btn('🎮 شهربازی','arc:home')]
        ])
    )
    return True

# Add the two games to the arcade's mode lists through a high-priority bridge.
_BB_ARCADE_EXT_BUILD_OLD=build_application
def build_application(token=None):
    app=_BB_ARCADE_EXT_BUILD_OLD(token)
    app.add_handler(CallbackQueryHandler(_bb_arcade_truth_callback,pattern=r'^arc:truth:(truth|dare)$'),group=-40035)
    app.add_handler(CallbackQueryHandler(_bb_arcade_truth_family_start,pattern=r'^arc:start:(truth|family)$'),group=-40036)
    return app

# ============================================================================
# ARCADE MINE SWEEPER — single-player, callback-driven, glass UI
# ============================================================================
import random as _bb_mine_random

_BB_ARCADE_GAMES = tuple(dict.fromkeys(tuple(globals().get('_BB_ARCADE_GAMES', ())) + ('mine',)))
_BB_ARCADE_GAME_LABELS['mine'] = '💣 مین‌روب'
_BB_ARCADE_EMOJI_FALLBACK['mine'] = '💣'

async def _bb_arcade_start_mine(q, context):
    uid = q.from_user.id
    size = 5
    mines = 5
    cells = list(range(size * size))
    mine_set = set(_bb_mine_random.sample(cells, mines))
    _BB_ARCADE_SINGLE[uid] = {
        'game': 'mine', 'size': size, 'mines': mine_set,
        'revealed': set(), 'flags': set(), 'started': True,
    }
    await _bb_arcade_render_mine(q, _BB_ARCADE_SINGLE[uid], '💣 مین‌روب', '۵ مین را پیدا کن؛ روی خانه‌ها بزن و مراقب باش!')
    return True


def _bb_mine_neighbors(idx, size=5):
    r, c = divmod(idx, size)
    out = []
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if not dr and not dc:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < size and 0 <= nc < size:
                out.append(nr * size + nc)
    return out


def _bb_mine_count(idx, state):
    return sum(1 for n in _bb_mine_neighbors(idx, state['size']) if n in state['mines'])


def _bb_mine_reveal(idx, state):
    if idx in state['revealed'] or idx in state['flags']:
        return
    if idx in state['mines']:
        state['revealed'].add(idx)
        return
    queue = [idx]
    seen = set()
    while queue:
        cur = queue.pop()
        if cur in seen or cur in state['mines'] or cur in state['flags']:
            continue
        seen.add(cur)
        state['revealed'].add(cur)
        if _bb_mine_count(cur, state) == 0:
            queue.extend(_bb_mine_neighbors(cur, state))


async def _bb_arcade_render_mine(q, state, title='💣 مین‌روب', subtitle=''):
    size = state['size']
    rows = []
    for r in range(size):
        row = []
        for c in range(size):
            idx = r * size + c
            if idx in state['revealed']:
                if idx in state['mines']:
                    label = '💥'
                else:
                    n = _bb_mine_count(idx, state)
                    label = '·' if n == 0 else str(n)
            elif idx in state['flags']:
                label = '🚩'
            else:
                label = '▫️'
            row.append(btn(label, f'arc:mine:{idx}'))
        rows.append(row)
    rows.append([btn('🚩 پرچم‌گذاری', 'arc:mine:flag'), btn('🎮 شهربازی', 'arc:home')])
    await q.edit_message_text(
        await _bb_arcade_header(title, subtitle),
        parse_mode='HTML', reply_markup=keyboard(rows)
    )


async def _bb_arcade_mine_callback(update, context):
    q = update.callback_query
    d = str(q.data or '') if q else ''
    if not d.startswith('arc:mine:'):
        return False
    uid = q.from_user.id
    state = _BB_ARCADE_SINGLE.get(uid)
    if not state or state.get('game') != 'mine':
        await q.answer('اول مین‌روب را شروع کن.', show_alert=True)
        return True

    action = d.rsplit(':', 1)[-1]
    if action == 'flag':
        state['flag_mode'] = not state.get('flag_mode', False)
        mode = 'فعال شد 🚩' if state['flag_mode'] else 'خاموش شد'
        await q.answer(f'حالت پرچم {mode}')
        return await _bb_arcade_render_mine(q, state, '💣 مین‌روب', 'حالت پرچم را انتخاب کن یا دوباره روی پرچم بزن.')

    idx = int(action)
    if not 0 <= idx < state['size'] * state['size']:
        return True
    if state.get('flag_mode'):
        if idx not in state['revealed']:
            if idx in state['flags']:
                state['flags'].remove(idx)
            elif len(state['flags']) < len(state['mines']):
                state['flags'].add(idx)
        state['flag_mode'] = False
        await q.answer('پرچم ثبت شد 🚩')
        return await _bb_arcade_render_mine(q, state, '💣 مین‌روب', 'پرچم‌گذاری انجام شد؛ خانه بعدی را انتخاب کن.')

    if idx in state['flags']:
        await q.answer('اول پرچم این خانه را بردار.')
        return True
    if idx in state['revealed']:
        await q.answer('این خانه قبلاً باز شده.')
        return True

    if idx in state['mines']:
        state['revealed'].update(state['mines'])
        await q.answer('💥 مین بود!', show_alert=True)
        await _bb_arcade_add_score(uid, 0)
        _BB_ARCADE_SINGLE.pop(uid, None)
        await q.edit_message_text(
            await _bb_arcade_header('💥 مین منفجر شد!', 'این دور تمام شد؛ دفعه بعد دقیق‌تر برو جلو.'),
            parse_mode='HTML',
            reply_markup=keyboard([[btn('🔁 دوباره', 'arc:start:mine'), btn('🎮 شهربازی', 'arc:home')]])
        )
        return True

    _bb_mine_reveal(idx, state)
    safe_total = state['size'] * state['size'] - len(state['mines'])
    if len(state['revealed']) >= safe_total:
        points = 40 + max(0, len(state['flags'])) * 2
        await _bb_arcade_add_score(uid, points)
        _BB_ARCADE_SINGLE.pop(uid, None)
        await q.answer('🏆 مین‌روب را کامل کردی!', show_alert=True)
        await q.edit_message_text(
            await _bb_arcade_header('🏆 مین‌روب کامل شد!', f'همه خانه‌های امن را پیدا کردی. +{points} امتیاز'),
            parse_mode='HTML',
            reply_markup=keyboard([[btn('🔁 دوباره', 'arc:start:mine'), btn('🎮 شهربازی', 'arc:home')]])
        )
        return True

    await q.answer('خانه امن بود ✅')
    return await _bb_arcade_render_mine(q, state, '💣 مین‌روب', f'خانه‌های امن: {len(state["revealed"])} / {safe_total}')


