# =============================================================================
# FINAL LOCATION HOTFIX — reliable private Location request + map result
# =============================================================================
async def _bb_location_result_final(update, context):
    msg=getattr(update,'effective_message',None)
    loc=getattr(msg,'location',None) if msg else None
    if not msg or not loc:
        return False
    lat=float(loc.latitude); lon=float(loc.longitude)
    map_url=f"https://www.openstreetmap.org/?mlat={lat:.6f}&mlon={lon:.6f}#map=17/{lat:.6f}/{lon:.6f}"
    try:
        await msg.reply_text(
            f"📍 <b>موقعیتت دریافت شد</b>\n\n"
            f"🌐 عرض جغرافیایی: <code>{lat:.6f}</code>\n"
            f"🌐 طول جغرافیایی: <code>{lon:.6f}</code>\n\n"
            "🔐 این مختصات در دیتابیس بیل‌بیلک ذخیره نمی‌شود.",
            parse_mode='HTML', reply_markup=ReplyKeyboardRemove()
        )
        await msg.reply_text(
            "🗺️ مشاهده موقعیت روی نقشه:",
            reply_markup=keyboard([[btn('🗺️ باز کردن نقشه',url=map_url)]])
        )
    except Exception as exc:
        log.exception('final location result failed: %s',exc)
        try:
            await msg.reply_text('⚠️ موقعیت دریافت شد، اما ساخت لینک نقشه انجام نشد.',reply_markup=ReplyKeyboardRemove())
        except Exception:
            pass
    return True

async def location_v4(update, context):
    return await _bb_location_result_final(update,context)

async def _bb_location_callback_final(update, context):
    q=getattr(update,'callback_query',None)
    if not q: return False
    data=str(q.data or '')
    parts=data.split(':',2)
    if len(parts)!=3 or parts[0] not in {'rich','tool'} or not parts[1].isdigit() or int(parts[1])!=q.from_user.id or parts[2]!='location':
        return False
    try: await q.answer()
    except Exception: pass
    await request_location_v4(q,context)
    return True

_OLD_LOCATION_CALLBACK_ROUTER_FINAL=callback_router_v10
async def callback_router_v10(update, context):
    if await _bb_location_callback_final(update,context):
        return
    return await _OLD_LOCATION_CALLBACK_ROUTER_FINAL(update,context)

