# =============================================================================
# FINAL RAFFLE / GIVEAWAY SYSTEM — «قرعه کشی»
# =============================================================================
_BB_RAFFLE_WIZARD = {}
_BB_RAFFLE_JOBS = {}
_BB_RAFFLE_TEXT_SETUP = '🎟️ <b>ساخت قرعه‌کشی</b>\n\nظرفیت چند نفر است؟\nمثلاً: <code>50</code>\n\nبرای لغو: <code>لغو</code>'
_BB_RAFFLE_TEXT_WINNERS = '🏆 <b>تعداد برنده‌ها</b>\n\nچند نفر برنده شوند؟\nمثلاً: <code>3</code>'
_BB_RAFFLE_TEXT_PRIZE = '🎁 <b>جایزه</b>\n\nجایزه قرعه‌کشی چیست؟\nمثلاً: کارت هدیه ۵۰۰ هزار تومانی'
_BB_RAFFLE_TEXT_RULES = '📜 <b>قوانین قرعه‌کشی</b>\n\nقوانین را کامل بفرست؛ مثلاً شرایط شرکت، محدودیت‌ها و زمان قرعه.'
_BB_RAFFLE_TEXT_DESC = '📝 <b>توضیحات</b>\n\nتوضیحات تکمیلی قرعه‌کشی را بفرست.'
_BB_RAFFLE_TEXT_READY = '⏳ <b>قرعه‌کشی آماده شد</b>\n\nثبت‌نام کاربران انجام می‌شود و پس از تأیید ادمین‌ها، ظرفیت اصلی تکمیل خواهد شد.\nقرعه‌کشی رأس ساعت ۰۰:۰۰ همان شب انجام می‌شود.'
_BB_RAFFLE_BTN_REGISTER = '🎟️ ثبت‌نام'
_BB_RAFFLE_BTN_WAITING = '👀 مشاهده لیست انتظار'
_BB_RAFFLE_BTN_APPROVE = '✅ تأیید'
_BB_RAFFLE_BTN_REJECT = '❌ رد'
_BB_RAFFLE_BTN_CLOSE = '🔒 بستن'
_BB_RAFFLE_BTN_BACK = '🔙 بازگشت'
_BB_RAFFLE_ANNOUNCEMENT_TEMPLATE = '🎟️ <b>قرعه‌کشی بیل‌بیلک #{id}</b>\n\n🎁 <b>جایزه:</b> {prize}\n👥 <b>ظرفیت:</b> {capacity} نفر\n🏆 <b>تعداد برنده:</b> {winners} نفر\n📋 <b>تأییدشده‌ها:</b> {approved}/{capacity}\n⏳ <b>در انتظار تأیید:</b> {waiting}\n📌 <b>وضعیت:</b> {status}\n\n📜 <b>قوانین</b>\n{rules}\n\n📝 <b>توضیحات</b>\n{description}\n\nبرای شرکت روی «ثبت‌نام» بزن. ثبت‌نام ابتدا وارد لیست انتظار می‌شود و سپس توسط برگزارکننده/ادمین تأیید می‌گردد.'
_BB_RAFFLE_RESULT_TEMPLATE = '🎉 <b>نتیجه قرعه‌کشی #{id}</b>\n\n🎁 <b>جایزه:</b> {prize}\n\n{winners_list}\n\n🎲 انتخاب برندگان به‌صورت تصادفی انجام شد.'

async def _bb_raffle_schema():
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_raffles(
        id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id INTEGER NOT NULL, organizer_id INTEGER NOT NULL,
        capacity INTEGER NOT NULL, winners_count INTEGER NOT NULL DEFAULT 1, prize TEXT NOT NULL DEFAULT '',
        rules TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'open',
        draw_at INTEGER NOT NULL DEFAULT 0, announcement_message_id INTEGER DEFAULT 0,
        created_at INTEGER NOT NULL DEFAULT 0, drawn_at INTEGER DEFAULT 0)''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_raffle_participants(
        raffle_id INTEGER NOT NULL, user_id INTEGER NOT NULL, user_name TEXT NOT NULL DEFAULT '',
        status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL DEFAULT 0, approved_at INTEGER DEFAULT 0,
        PRIMARY KEY(raffle_id,user_id))''')

async def _bb_raffle_is_group_admin(bot, chat_id, user_id):
    try:
        m=await bot.get_chat_member(chat_id,int(user_id))
        return str(getattr(m,'status','')) in {'administrator','creator','owner'}
    except Exception:
        return False

async def _bb_raffle_is_manager(bot, chat_id, user_id, organizer_id):
    return int(user_id or 0)==int(organizer_id or 0) or await _bb_raffle_is_group_admin(bot,chat_id,user_id)

def _bb_raffle_tehran_midnight_epoch():
    from zoneinfo import ZoneInfo
    tz=ZoneInfo(os.getenv('BB_PROFILE_TIMEZONE','Asia/Tehran'))
    now=datetime.now(tz)
    nxt=(now+timedelta(days=1)).replace(hour=0,minute=0,second=0,microsecond=0)
    return int(nxt.timestamp())

def _bb_raffle_escape(value, limit=1800):
    return safe_text(str(value or ''),limit).replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')

async def _bb_raffle_render_message(row, waiting=None, approved=None, drawn=False):
    waiting=int(waiting if waiting is not None else 0); approved=int(approved if approved is not None else 0)
    status='🏁 قرعه انجام شده' if drawn else ('🔒 ظرفیت تکمیل شد؛ قرعه در ۰۰:۰۰ انجام می‌شود.' if approved>=int(row['capacity']) else '🟢 ثبت‌نام فعال است')
    template=_bb_ui_text(_BB_RAFFLE_ANNOUNCEMENT_TEMPLATE)
    vals={'id':int(row['id']),'prize':_bb_raffle_escape(row['prize']),'capacity':int(row['capacity']),'winners':int(row['winners_count']),'approved':approved,'waiting':waiting,'status':status,'rules':_bb_raffle_escape(row['rules'],2500),'description':_bb_raffle_escape(row['description'],2500)}
    return template.format(**vals)

async def _bb_raffle_keyboard(row):
    return keyboard([[btn(_BB_RAFFLE_BTN_REGISTER,f'raffle:join:{int(row["id"])}')],
                     [btn(_BB_RAFFLE_BTN_WAITING,f'raffle:wait:{int(row["id"])}')]])

async def _bb_raffle_create_announcement(bot,row):
    waiting=await DBX.one('SELECT COUNT(*) c FROM bb_raffle_participants WHERE raffle_id=? AND status="pending"',(row['id'],))
    approved=await DBX.one('SELECT COUNT(*) c FROM bb_raffle_participants WHERE raffle_id=? AND status="approved"',(row['id'],))
    text=await _bb_raffle_render_message(row,int(waiting['c']),int(approved['c']))
    sent=await bot.send_message(row['chat_id'],text,parse_mode='HTML',reply_markup=await _bb_raffle_keyboard(row))
    try: await bot.pin_chat_message(row['chat_id'],sent.message_id,disable_notification=True)
    except Exception as exc: log.warning('raffle pin failed chat=%s: %s',row['chat_id'],exc)
    await DBX.execute('UPDATE bb_raffles SET announcement_message_id=? WHERE id=?',(int(sent.message_id),int(row['id'])))
    return sent

async def _bb_raffle_refresh_announcement(bot, raffle_id):
    row=await DBX.one('SELECT * FROM bb_raffles WHERE id=?',(int(raffle_id),))
    if not row or not int(row['announcement_message_id'] or 0): return
    waiting=await DBX.one('SELECT COUNT(*) c FROM bb_raffle_participants WHERE raffle_id=? AND status="pending"',(raffle_id,))
    approved=await DBX.one('SELECT COUNT(*) c FROM bb_raffle_participants WHERE raffle_id=? AND status="approved"',(raffle_id,))
    text=await _bb_raffle_render_message(row,int(waiting['c']),int(approved['c']),str(row['status'])=='drawn')
    try:
        await bot.edit_message_text(chat_id=row['chat_id'],message_id=row['announcement_message_id'],text=text,parse_mode='HTML',reply_markup=await _bb_raffle_keyboard(row) if row['status']=='open' else None)
    except Exception as exc: log.debug('raffle announcement refresh failed: %s',exc)

async def _bb_raffle_draw_job(context):
    raffle_id=int(getattr(context.job,'data',0) or 0)
    await _bb_raffle_draw_now(context.application.bot,raffle_id); _BB_RAFFLE_JOBS.pop(raffle_id,None)

async def _bb_raffle_schedule(application, raffle_id, draw_at):
    jq=getattr(application,'job_queue',None)
    if not jq: return
    old=_BB_RAFFLE_JOBS.get(int(raffle_id))
    if old:
        try: old.schedule_removal()
        except Exception: pass
    delay=max(1,int(draw_at)-int(now_ts()))
    try: _BB_RAFFLE_JOBS[int(raffle_id)]=jq.run_once(_bb_raffle_draw_job,when=delay,data=int(raffle_id),name=f'raffle:{int(raffle_id)}')
    except Exception as exc: log.warning('raffle schedule failed: %s',exc)

async def _bb_raffle_draw_now(bot, raffle_id):
    await _bb_raffle_schema(); row=await DBX.one('SELECT * FROM bb_raffles WHERE id=?',(int(raffle_id),))
    if not row or str(row['status'])!='open': return
    rows=await DBX.execute('SELECT user_id,user_name FROM bb_raffle_participants WHERE raffle_id=? AND status="approved" ORDER BY approved_at,rowid',(int(raffle_id),),fetch=True)
    players=[(int(r['user_id']),str(r['user_name'] or 'کاربر')) for r in rows]
    if not players:
        await DBX.execute('UPDATE bb_raffles SET status="drawn",drawn_at=? WHERE id=?',(now_ts(),int(raffle_id)))
        sent=await bot.send_message(row['chat_id'],f'🎟️ <b>قرعه‌کشی #{int(raffle_id)}</b>\n\nهیچ شرکت‌کننده تأییدشده‌ای وجود نداشت؛ قرعه بدون برنده بسته شد.',parse_mode='HTML')
        try: await bot.pin_chat_message(row['chat_id'],sent.message_id,disable_notification=True)
        except Exception: pass
        await _bb_raffle_refresh_announcement(bot,raffle_id); return
    import secrets as _bb_secrets
    winners=_bb_secrets.SystemRandom().sample(players,min(int(row['winners_count']),len(players)))
    lines=[f'🏆 <b>برنده {i}:</b> <a href="tg://user?id={uid}">{_bb_raffle_escape(name,100)}</a>' for i,(uid,name) in enumerate(winners,1)]
    result=_bb_ui_text(_BB_RAFFLE_RESULT_TEMPLATE).format(id=int(raffle_id),prize=_bb_raffle_escape(row['prize']),winners_list='\n'.join(lines))
    sent=await bot.send_message(row['chat_id'],result,parse_mode='HTML')
    try: await bot.pin_chat_message(row['chat_id'],sent.message_id,disable_notification=True)
    except Exception as exc: log.warning('raffle result pin failed: %s',exc)
    await DBX.execute('UPDATE bb_raffles SET status="drawn",drawn_at=? WHERE id=?',(now_ts(),int(raffle_id)))
    await _bb_raffle_refresh_announcement(bot,raffle_id)

async def _bb_raffle_finalize_creation(update,context):
    uid=int(update.effective_user.id); st=_BB_RAFFLE_WIZARD.pop(uid,None); msg=update.effective_message; chat=update.effective_chat
    draw_at=_bb_raffle_tehran_midnight_epoch(); await _bb_raffle_schema()
    await DBX.execute('INSERT INTO bb_raffles(chat_id,organizer_id,capacity,winners_count,prize,rules,description,status,draw_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)',(int(chat.id),uid,int(st['capacity']),int(st['winners']),st['prize'],st['rules'],st['description'],'open',draw_at,now_ts()))
    row=await DBX.one('SELECT * FROM bb_raffles WHERE chat_id=? AND organizer_id=? ORDER BY id DESC LIMIT 1',(int(chat.id),uid))
    await _bb_raffle_create_announcement(context.bot,row); await _bb_raffle_schedule(context.application,int(row['id']),draw_at)
    await msg.reply_text(_bb_ui_text(_BB_RAFFLE_TEXT_READY),parse_mode='HTML'); return True

async def _bb_raffle_text(update,context):
    msg=getattr(update,'effective_message',None); user=getattr(update,'effective_user',None); chat=getattr(update,'effective_chat',None)
    if not msg or not user or not chat or not getattr(msg,'text',None): return False
    raw=str(msg.text).strip(); t=normalize(raw); uid=int(user.id); st=_BB_RAFFLE_WIZARD.get(uid)
    if st:
        if t in {'لغو','انصراف'}: _BB_RAFFLE_WIZARD.pop(uid,None); await msg.reply_text('❌ ساخت قرعه‌کشی لغو شد.'); return True
        step=st['step']
        if step=='capacity':
            try: n=int(_bb_digits(raw))
            except Exception: n=0
            if n<1 or n>1000: await msg.reply_text('⚠️ ظرفیت باید بین ۱ تا ۱۰۰۰ نفر باشد.'); return True
            st.update(capacity=n,step='winners'); await msg.reply_text(_bb_ui_text(_BB_RAFFLE_TEXT_WINNERS),parse_mode='HTML'); return True
        if step=='winners':
            try: n=int(_bb_digits(raw))
            except Exception: n=0
            if n<1 or n>int(st['capacity']): await msg.reply_text(f'⚠️ تعداد برنده باید بین ۱ تا {st["capacity"]} باشد.'); return True
            st.update(winners=n,step='prize'); await msg.reply_text(_bb_ui_text(_BB_RAFFLE_TEXT_PRIZE),parse_mode='HTML'); return True
        if step=='prize':
            if not raw: await msg.reply_text('⚠️ جایزه را وارد کن.'); return True
            st.update(prize=raw[:1000],step='rules'); await msg.reply_text(_bb_ui_text(_BB_RAFFLE_TEXT_RULES),parse_mode='HTML'); return True
        if step=='rules': st.update(rules=raw[:3000],step='description'); await msg.reply_text(_bb_ui_text(_BB_RAFFLE_TEXT_DESC),parse_mode='HTML'); return True
        if step=='description': st.update(description=raw[:3000]); return await _bb_raffle_finalize_creation(update,context)
    if t in {'قرعه کشی','قرعه‌کشی','قرعه','giveaway','raffle'}:
        if chat.type=='private': await msg.reply_text('🎟️ قرعه‌کشی فقط داخل گروه قابل برگزاری است.'); return True
        if not await _bb_raffle_is_group_admin(context.bot,chat.id,uid): await msg.reply_text('⛔ فقط مالک یا ادمین گروه می‌تواند قرعه‌کشی برگزار کند.'); return True
        _BB_RAFFLE_WIZARD[uid]={'chat_id':int(chat.id),'step':'capacity'}; await msg.reply_text(_bb_ui_text(_BB_RAFFLE_TEXT_SETUP),parse_mode='HTML'); return True
    return False

async def _bb_raffle_callback(update,context):
    q=getattr(update,'callback_query',None)
    if not q or not str(q.data or '').startswith('raffle:'): return False
    await _bb_raffle_schema(); parts=str(q.data).split(':'); action=parts[1] if len(parts)>1 else ''; uid=int(q.from_user.id)
    try: rid=int(parts[2])
    except Exception: await q.answer('قرعه نامعتبر است.',show_alert=True); return True
    row=await DBX.one('SELECT * FROM bb_raffles WHERE id=?',(rid,))
    if not row: await q.answer('این قرعه پیدا نشد.',show_alert=True); return True
    if action=='join':
        if str(row['status'])!='open': await q.answer('ثبت‌نام این قرعه بسته شده است.',show_alert=True); return True
        existing=await DBX.one('SELECT status FROM bb_raffle_participants WHERE raffle_id=? AND user_id=?',(rid,uid))
        if existing: await q.answer('قبلاً در این قرعه ثبت‌نام کرده‌ای.',show_alert=True); return True
        approved=await DBX.one('SELECT COUNT(*) c FROM bb_raffle_participants WHERE raffle_id=? AND status="approved"',(rid,))
        if int(approved['c'])>=int(row['capacity']): await q.answer('ظرفیت تکمیل شده است.',show_alert=True); return True
        await DBX.execute('INSERT INTO bb_raffle_participants(raffle_id,user_id,user_name,status,created_at) VALUES(?,?,?,?,?)',(rid,uid,display_name(q.from_user),'pending',now_ts()))
        await q.answer('✅ ثبت شد؛ درخواستت در لیست انتظار قرار گرفت.',show_alert=True); await _bb_raffle_refresh_announcement(context.bot,rid); return True
    if action=='wait':
        if not await _bb_raffle_is_manager(context.bot,row['chat_id'],uid,row['organizer_id']): await q.answer('⛔ فقط برگزارکننده یا ادمین گروه می‌تواند لیست انتظار را ببیند.',show_alert=True); return True
        pending=await DBX.execute('SELECT user_id,user_name FROM bb_raffle_participants WHERE raffle_id=? AND status="pending" ORDER BY created_at',(rid,),fetch=True)
        approved=await DBX.execute('SELECT user_id,user_name FROM bb_raffle_participants WHERE raffle_id=? AND status="approved" ORDER BY approved_at',(rid,),fetch=True)
        lines=['📋 <b>لیست انتظار</b>']
        if pending:
            lines.append('\n<b>⏳ در انتظار:</b>'); lines += [f'{i}. <a href="tg://user?id={int(r["user_id"])}">{_bb_raffle_escape(r["user_name"],80)}</a>' for i,r in enumerate(pending,1)]
        else: lines.append('\n⏳ لیست انتظار خالی است.')
        lines.append('\n<b>🎟️ لیست اصلی:</b>')
        if approved: lines += [f'{i}. <a href="tg://user?id={int(r["user_id"])}">{_bb_raffle_escape(r["user_name"],80)}</a>' for i,r in enumerate(approved,1)]
        else: lines.append('هنوز کسی تأیید نشده است.')
        kb=[]
        for r in pending[:30]: kb.append([btn(f'✅ تأیید {safe_text(r["user_name"],28)}',f'raffle:approve:{rid}:{int(r["user_id"])}'),btn(_BB_RAFFLE_BTN_REJECT,f'raffle:reject:{rid}:{int(r["user_id"])}')])
        kb.append([btn(_BB_RAFFLE_BTN_BACK,f'raffle:back:{rid}')])
        await q.message.reply_text('\n'.join(lines)[:3900],parse_mode='HTML',reply_markup=keyboard(kb)); await q.answer(); return True
    if action in {'approve','reject'}:
        if not await _bb_raffle_is_manager(context.bot,row['chat_id'],uid,row['organizer_id']): await q.answer('⛔ فقط برگزارکننده یا ادمین.',show_alert=True); return True
        try: target=int(parts[3])
        except Exception: await q.answer('کاربر نامعتبر است.',show_alert=True); return True
        if action=='approve':
            count=await DBX.one('SELECT COUNT(*) c FROM bb_raffle_participants WHERE raffle_id=? AND status="approved"',(rid,))
            if int(count['c'])>=int(row['capacity']): await q.answer('ظرفیت اصلی پر شده است.',show_alert=True); return True
            await DBX.execute('UPDATE bb_raffle_participants SET status="approved",approved_at=? WHERE raffle_id=? AND user_id=?',(now_ts(),rid,target)); await q.answer('تأیید شد.')
        else:
            await DBX.execute('UPDATE bb_raffle_participants SET status="rejected" WHERE raffle_id=? AND user_id=?',(rid,target)); await q.answer('رد شد.')
        await _bb_raffle_refresh_announcement(context.bot,rid); return True
    if action=='back': await q.answer(); await _bb_raffle_refresh_announcement(context.bot,rid); return True
    return True

async def _bb_raffle_post_init(application):
    await _bb_raffle_schema()
    rows=await DBX.execute('SELECT id,draw_at,status FROM bb_raffles WHERE status="open"',fetch=True)
    for r in rows:
        try: await _bb_raffle_schedule(application,int(r['id']),int(r['draw_at']))
        except Exception as exc: log.debug('raffle restore failed: %s',exc)
    try:
        for value,kind in [(_BB_RAFFLE_TEXT_SETUP,'text'),(_BB_RAFFLE_TEXT_WINNERS,'text'),(_BB_RAFFLE_TEXT_PRIZE,'text'),(_BB_RAFFLE_TEXT_RULES,'text'),(_BB_RAFFLE_TEXT_DESC,'text'),(_BB_RAFFLE_TEXT_READY,'text'),(_BB_RAFFLE_ANNOUNCEMENT_TEMPLATE,'text'),(_BB_RAFFLE_RESULT_TEMPLATE,'text'),(_BB_RAFFLE_BTN_REGISTER,'button'),(_BB_RAFFLE_BTN_WAITING,'button'),(_BB_RAFFLE_BTN_APPROVE,'button'),(_BB_RAFFLE_BTN_REJECT,'button'),(_BB_RAFFLE_BTN_CLOSE,'button'),(_BB_RAFFLE_BTN_BACK,'button')]:
            try: await _bb_ui_register(value,category='raffle',kind=kind)
            except Exception: pass
    except Exception: pass

_BB_RAFFLE_BUILD_PREV=build_application
def build_application(token=None):
    app=_BB_RAFFLE_BUILD_PREV(token)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_raffle_text),group=-1000000)
    app.add_handler(CallbackQueryHandler(_bb_raffle_callback,pattern=r'^raffle:'),group=-1000001)
    old_post=getattr(app,'post_init',None)
    async def _raffle_post_init(application):
        if old_post: await old_post(application)
        await _bb_raffle_post_init(application)
    app.post_init=_raffle_post_init
    return app

