_BB_REL_TEXT_FRIEND_HOME = '🤝 <b>باشگاه دوستی</b>\n\nاینجا درخواست‌های دوستی، دوستان تأییدشده و درخواست‌های دریافتی‌ات را می‌بینی.\n\nبرای درخواست دوستی، روی پیام کاربر ریپلای کن و بنویس: <code>دوستی</code>'
_BB_REL_TEXT_MARRIAGE_HOME = '💍 <b>بخش ازدواج</b>\n\nوضعیت رابطه، درخواست‌های ازدواج و همسر فعلی‌ات از اینجا مدیریت می‌شود.\n\nبرای خواستگاری، روی پیام کاربر ریپلای کن و بنویس: <code>ازدواج</code>'
_BB_REL_TEXT_FRIEND_SENT = '🤝 درخواست دوستی برای {name} ارسال شد.\nطرف مقابل می‌تواند آن را تأیید یا رد کند.'
_BB_REL_TEXT_FRIEND_IN = '🤝 {name} برایت درخواست دوستی فرستاده است.\n\nمی‌خواهی قبولش کنی؟'
_BB_REL_TEXT_FRIEND_ACCEPT = '✅ درخواست دوستی پذیرفته شد. شما حالا دوست هستید.'
_BB_REL_TEXT_FRIEND_REJECT = '❌ درخواست دوستی رد شد.'
_BB_REL_TEXT_MARRIAGE_SENT = '💍 درخواست ازدواج برای {name} ارسال شد.\nطرف مقابل می‌تواند آن را تأیید یا رد کند.'
_BB_REL_TEXT_MARRIAGE_IN = '💍 {name} برایت درخواست ازدواج فرستاده است.\n\nمی‌خواهی قبولش کنی؟'
_BB_REL_TEXT_MARRIAGE_ACCEPT = '💍❤️ درخواست ازدواج پذیرفته شد. از حالا در سیستم بیل‌بیلک همسر ثبت شدید.'
_BB_REL_TEXT_MARRIAGE_REJECT = '❌ درخواست ازدواج رد شد.'
_BB_REL_TEXT_DIVORCE = '💔 ثبت طلاق انجام شد. رابطه ازدواجی شما پایان یافت.'
_BB_REL_BTN_FRIENDS = '🤝 دوستی'
_BB_REL_BTN_MARRIAGE = '💍 ازدواج'
_BB_REL_BTN_ACCEPT = '✅ قبول'
_BB_REL_BTN_REJECT = '❌ رد'
_BB_REL_BTN_DIVORCE = '💔 طلاق'
_BB_REL_BTN_REFRESH = '🔄 تازه‌سازی'
_BB_REL_BTN_BACK = '🔙 خانه'

async def _bb_rel_schema():
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_friend_requests(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        sender_id INTEGER NOT NULL,
        receiver_id INTEGER NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending',
        created_at INTEGER NOT NULL,
        UNIQUE(sender_id,receiver_id)
    )''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_marriage_requests(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        sender_id INTEGER NOT NULL,
        receiver_id INTEGER NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending',
        created_at INTEGER NOT NULL,
        UNIQUE(sender_id,receiver_id)
    )''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_marriages(
        user1_id INTEGER PRIMARY KEY,
        user2_id INTEGER NOT NULL UNIQUE,
        married_at INTEGER NOT NULL
    )''')

async def _bb_rel_user_name(uid):
    try:
        u=await DBX.get_user(int(uid))
        return safe_text((u['first_name'] if u else '') or f'کاربر {uid}',40)
    except Exception:
        return f'کاربر {uid}'

async def _bb_rel_is_married(uid):
    try:
        await DBX.execute('ALTER TABLE bb_marriages ADD COLUMN chat_id INTEGER')
    except Exception: pass
    r=await DBX.one('SELECT user1_id,user2_id,married_at,chat_id FROM bb_marriages WHERE user1_id=? OR user2_id=?',(int(uid),int(uid)))
    if not r: return None
    other=int(r['user2_id']) if int(r['user1_id'])==int(uid) else int(r['user1_id'])
    return {'other_id':other,'married_at':int(r['married_at']),'chat_id':(int(r['chat_id']) if r['chat_id'] is not None else None)}

async def _bb_rel_friend_status(a,b):
    r=await DBX.one('''SELECT status FROM bb_friend_requests
                       WHERE (sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?)
                       ORDER BY id DESC LIMIT 1''',(int(a),int(b),int(b),int(a)))
    return str(r['status']) if r else ''

def _bb_rel_kb_friend(uid):
    return keyboard([[btn(_BB_REL_BTN_REFRESH,f'bbrel:friends:{uid}')],
                     [btn(_BB_REL_BTN_MARRIAGE,f'bbrel:marriage:{uid}')],
                     [btn(_BB_REL_BTN_BACK,user_cb(uid,'home'))]])

def _bb_rel_kb_marriage(uid, married=False):
    rows=[]
    if married: rows.append([btn(_BB_REL_BTN_DIVORCE,f'bbrel:divorce:{uid}')])
    rows.append([btn(_BB_REL_BTN_REFRESH,f'bbrel:marriage:{uid}')])
    rows.append([btn(_BB_REL_BTN_FRIENDS,f'bbrel:friends:{uid}')])
    rows.append([btn(_BB_REL_BTN_BACK,user_cb(uid,'home'))])
    return keyboard(rows)

async def _bb_rel_friend_panel(q,uid):
    if int(q.from_user.id)!=int(uid):
        await q.answer('⛔ این پنل برای کاربر دیگری است.',show_alert=True); return
    incoming=await DBX.execute('SELECT id,sender_id,created_at FROM bb_friend_requests WHERE receiver_id=? AND status="pending" ORDER BY created_at DESC LIMIT 10',(uid,),fetch=True)
    outgoing=await DBX.execute('SELECT receiver_id,created_at FROM bb_friend_requests WHERE sender_id=? AND status="pending" ORDER BY created_at DESC LIMIT 10',(uid,),fetch=True)
    friends=await DBX.execute('''SELECT CASE WHEN sender_id=? THEN receiver_id ELSE sender_id END AS friend_id
                                 FROM bb_friend_requests WHERE status='accepted' AND (sender_id=? OR receiver_id=?)
                                 ORDER BY id DESC LIMIT 20''',(uid,uid,uid),fetch=True)
    lines=[_BB_REL_TEXT_FRIEND_HOME]
    lines.append('\n👥 <b>دوستان تأییدشده:</b>')
    if friends:
        for i,r in enumerate(friends,1): lines.append(f'{i}. <a href="tg://user?id={int(r["friend_id"])}">{await _bb_rel_user_name(int(r["friend_id"]))}</a>')
    else: lines.append('هنوز دوستی تأییدشده‌ای نداری.')
    lines.append('\n📥 <b>درخواست‌های دریافتی:</b>')
    if incoming:
        for r in incoming: lines.append(f'• <a href="tg://user?id={int(r["sender_id"])}">{await _bb_rel_user_name(int(r["sender_id"]))}</a>')
    else: lines.append('موردی نیست.')
    lines.append('\n📤 <b>درخواست‌های ارسالی:</b>')
    if outgoing:
        for r in outgoing: lines.append(f'• {await _bb_rel_user_name(int(r["receiver_id"]))}')
    else: lines.append('موردی نیست.')
    kb=[]
    for r in incoming[:10]:
        name=await _bb_rel_user_name(int(r['sender_id']))
        kb.append([btn(f'✅ قبول {name[:18]}',f'bbrel:faccept:{int(r["id"])}:{uid}'),btn(_BB_REL_BTN_REJECT,f'bbrel:freject:{int(r["id"])}:{uid}')])
    kb.append([btn(_BB_REL_BTN_REFRESH,f'bbrel:friends:{uid}'),btn(_BB_REL_BTN_MARRIAGE,f'bbrel:marriage:{uid}')])
    kb.append([btn(_BB_REL_BTN_BACK,user_cb(uid,'home'))])
    await q.edit_message_text('\n'.join(lines)[:3900],parse_mode='HTML',reply_markup=keyboard(kb))

async def _bb_rel_marriage_panel(q,uid):
    if int(q.from_user.id)!=int(uid):
        await q.answer('⛔ این پنل برای کاربر دیگری است.',show_alert=True); return
    married=await _bb_rel_is_married(uid)
    incoming=await DBX.execute('SELECT id,sender_id,created_at FROM bb_marriage_requests WHERE receiver_id=? AND status="pending" ORDER BY created_at DESC LIMIT 10',(uid,),fetch=True)
    outgoing=await DBX.execute('SELECT receiver_id,created_at FROM bb_marriage_requests WHERE sender_id=? AND status="pending" ORDER BY created_at DESC LIMIT 10',(uid,),fetch=True)
    lines=[_BB_REL_TEXT_MARRIAGE_HOME]
    if married:
        lines.append(f'\n💍 <b>همسر فعلی:</b> <a href="tg://user?id={married["other_id"]}">{await _bb_rel_user_name(married["other_id"])}</a>')
    else:
        lines.append('\n💍 <b>وضعیت:</b> مجرد')
    lines.append('\n📥 <b>درخواست‌های دریافتی:</b>')
    if incoming:
        for r in incoming: lines.append(f'• <a href="tg://user?id={int(r["sender_id"])}">{await _bb_rel_user_name(int(r["sender_id"]))}</a>')
    else: lines.append('موردی نیست.')
    lines.append('\n📤 <b>درخواست‌های ارسالی:</b>')
    if outgoing:
        for r in outgoing: lines.append(f'• {await _bb_rel_user_name(int(r["receiver_id"]))}')
    else: lines.append('موردی نیست.')
    kb=[]
    if married: kb.append([btn(_BB_REL_BTN_DIVORCE,f'bbrel:divorce:{uid}')])
    for r in incoming[:10]:
        name=await _bb_rel_user_name(int(r['sender_id']))
        kb.append([btn(f'✅ قبول {name[:18]}',f'bbrel:maccept:{int(r["id"])}:{uid}'),btn(_BB_REL_BTN_REJECT,f'bbrel:mreject:{int(r["id"])}:{uid}')])
    kb.append([btn(_BB_REL_BTN_REFRESH,f'bbrel:marriage:{uid}'),btn(_BB_REL_BTN_FRIENDS,f'bbrel:friends:{uid}')])
    kb.append([btn(_BB_REL_BTN_BACK,user_cb(uid,'home'))])
    await q.edit_message_text('\n'.join(lines)[:3900],parse_mode='HTML',reply_markup=keyboard(kb))

async def _bb_rel_send_notification(bot,receiver_id,text,reply_markup):
    try:
        await bot.send_message(int(receiver_id),text,parse_mode='HTML',reply_markup=reply_markup)
    except Exception as exc:
        log.debug('relationship notification failed: %s',exc)

async def _bb_rel_text(update,context):
    msg=getattr(update,'effective_message',None); user=getattr(update,'effective_user',None); chat=getattr(update,'effective_chat',None)
    if not msg or not user or not getattr(msg,'text',None): return False
    t=normalize(str(msg.text).strip())
    if t not in {'دوستی','دوست','ازدواج','خواستگاری','طلاق'}: return False
    if not msg.reply_to_message or not getattr(msg.reply_to_message,'from_user',None):
        await msg.reply_text('💡 برای این بخش باید روی پیام کاربر موردنظر ریپلای کنی.'); return True
    target=msg.reply_to_message.from_user; uid=int(user.id); tid=int(target.id)
    if uid==tid:
        await msg.reply_text('😄 این کار برای خودت امکان‌پذیر نیست.'); return True
    await _bb_rel_schema(); await DBX.ensure_user(user); await DBX.ensure_user(target)
    if t in {'دوستی','دوست'}:
        status=await _bb_rel_friend_status(uid,tid)
        if status=='accepted': await msg.reply_text('🤝 شما از قبل دوست هستید.'); return True
        if status=='pending': await msg.reply_text('⏳ یک درخواست دوستی در حال انتظار وجود دارد.'); return True
        await DBX.execute('''INSERT INTO bb_friend_requests(sender_id,receiver_id,status,created_at) VALUES(?,?,"pending",?)
                             ON CONFLICT(sender_id,receiver_id) DO UPDATE SET status="pending",created_at=excluded.created_at''',(uid,tid,now_ts()))
        name=await _bb_rel_user_name(uid)
        await msg.reply_text(_bb_ui_text(_BB_REL_TEXT_FRIEND_SENT).format(name=await _bb_rel_user_name(tid)),parse_mode='HTML')
        await _bb_rel_send_notification(context.bot,tid,_bb_ui_text(_BB_REL_TEXT_FRIEND_IN).format(name=name),keyboard([[btn(_BB_REL_BTN_ACCEPT,f'bbrel:fquickaccept:{uid}:{tid}'),btn(_BB_REL_BTN_REJECT,f'bbrel:fquickreject:{uid}:{tid}')]]))
        return True
    if t=='طلاق':
        married=await _bb_rel_is_married(uid)
        if not married: await msg.reply_text('💔 در حال حاضر ازدواج ثبت‌شده‌ای نداری.'); return True
        if int(married['other_id'])!=tid: await msg.reply_text('💔 این کاربر همسر ثبت‌شده‌ات نیست.'); return True
        a,b=sorted([uid,tid]); await DBX.execute('DELETE FROM bb_marriages WHERE user1_id=? AND user2_id=?',(a,b))
        await msg.reply_text(_bb_ui_text(_BB_REL_TEXT_DIVORCE),parse_mode='HTML')
        await _bb_rel_send_notification(context.bot,tid,_bb_ui_text(_BB_REL_TEXT_DIVORCE),None)
        return True
    if t in {'ازدواج','خواستگاری'} and getattr(chat,'type',None) not in ('group','supergroup'):
        await msg.reply_text('💍 درخواست ازدواج را داخل گروه و با ریپلای روی پیام کاربر ارسال کن؛ درخواست همان‌جا با تگ کاربر نمایش داده می‌شود.')
        return True
    married=await _bb_rel_is_married(uid)
    if married: await msg.reply_text('💍 تو همین حالا یک همسر ثبت‌شده داری.'); return True
    target_married=await _bb_rel_is_married(tid)
    if target_married: await msg.reply_text('💍 این کاربر در حال حاضر همسر ثبت‌شده دارد.'); return True
    old=await DBX.one('SELECT status FROM bb_marriage_requests WHERE sender_id=? AND receiver_id=? ORDER BY id DESC LIMIT 1',(uid,tid))
    if old and str(old['status'])=='pending': await msg.reply_text('⏳ درخواست ازدواجت قبلاً ارسال شده است.'); return True
    await DBX.execute('''INSERT INTO bb_marriage_requests(sender_id,receiver_id,status,created_at) VALUES(?,?,"pending",?)
                         ON CONFLICT(sender_id,receiver_id) DO UPDATE SET status="pending",created_at=excluded.created_at''',(uid,tid,now_ts()))
    await msg.reply_text(_bb_ui_text(_BB_REL_TEXT_MARRIAGE_SENT).format(name=await _bb_rel_user_name(tid)),parse_mode='HTML')
    # Marriage requests are announced in the originating group and tag the
    # target; do not attempt a private-message notification because the target
    # may never have started the bot in PV.
    if chat and getattr(chat,'type',None) in ('group','supergroup'):
        target_mention=f'<a href="tg://user?id={tid}">{safe_text(await _bb_rel_user_name(tid),80)}</a>'
        sender_name=await _bb_rel_user_name(uid)
        notice=_bb_ui_text(_BB_REL_TEXT_MARRIAGE_IN).format(name=sender_name,target_mention=target_mention)
        await context.bot.send_message(chat.id,notice,parse_mode='HTML',reply_markup=keyboard([[btn(_BB_REL_BTN_ACCEPT,f'bbrel:mquickaccept:{uid}:{tid}'),btn(_BB_REL_BTN_REJECT,f'bbrel:mquickreject:{uid}:{tid}')]]))
    else:
        await msg.reply_text('💍 درخواست ازدواج باید داخل گروه ارسال شود تا درخواست در همان گروه و با تگ کاربر نمایش داده شود.')
    return True

async def _bb_rel_callback(update,context):
    q=getattr(update,'callback_query',None)
    if not q or not str(q.data or '').startswith('bbrel:'): return False
    await _bb_rel_schema(); parts=str(q.data).split(':'); action=parts[1] if len(parts)>1 else ''
    uid=int(q.from_user.id)
    try: await q.answer()
    except Exception: pass
    if action in {'friends','marriage'}:
        try: owner=int(parts[2])
        except Exception: owner=uid
        if owner!=uid: await q.answer('⛔ این پنل برای تو نیست.',show_alert=True); return True
        if action=='friends': await _bb_rel_friend_panel(q,uid)
        else: await _bb_rel_marriage_panel(q,uid)
        return True
    if action in {'faccept','freject'}:
        rid=int(parts[2]); owner=int(parts[3])
        if uid!=owner: await q.answer('⛔ دسترسی نداری.',show_alert=True); return True
        r=await DBX.one('SELECT sender_id,receiver_id,status FROM bb_friend_requests WHERE id=?',(rid,))
        if not r or int(r['receiver_id'])!=uid or str(r['status'])!='pending': await q.answer('این درخواست دیگر معتبر نیست.',show_alert=True); return True
        if action=='faccept':
            await DBX.execute('UPDATE bb_friend_requests SET status="accepted" WHERE id=?',(rid,)); text=_bb_ui_text(_BB_REL_TEXT_FRIEND_ACCEPT)
            await _bb_rel_send_notification(context.bot,int(r['sender_id']),text,None)
        else:
            await DBX.execute('UPDATE bb_friend_requests SET status="rejected" WHERE id=?',(rid,)); text=_bb_ui_text(_BB_REL_TEXT_FRIEND_REJECT)
            await _bb_rel_send_notification(context.bot,int(r['sender_id']),text,None)
        await q.answer('انجام شد.'); await _bb_rel_friend_panel(q,uid); return True
    if action in {'fquickaccept','fquickreject'}:
        sender=int(parts[2]); receiver=int(parts[3])
        if uid!=receiver: await q.answer('⛔ این درخواست برای تو نیست.',show_alert=True); return True
        r=await DBX.one('SELECT id,status FROM bb_friend_requests WHERE sender_id=? AND receiver_id=? ORDER BY id DESC LIMIT 1',(sender,receiver))
        if not r or str(r['status'])!='pending': await q.answer('درخواست دیگر معتبر نیست.',show_alert=True); return True
        status='accepted' if action=='fquickaccept' else 'rejected'; await DBX.execute('UPDATE bb_friend_requests SET status=? WHERE id=?',(status,int(r['id'])))
        await q.answer('✅ قبول شد.' if status=='accepted' else '❌ رد شد.',show_alert=True)
        if status=='accepted': await _bb_rel_send_notification(context.bot,sender,_bb_ui_text(_BB_REL_TEXT_FRIEND_ACCEPT),None)
        return True
    if action in {'maccept','mreject'}:
        rid=int(parts[2]); owner=int(parts[3])
        if uid!=owner: await q.answer('⛔ دسترسی نداری.',show_alert=True); return True
        r=await DBX.one('SELECT sender_id,receiver_id,status FROM bb_marriage_requests WHERE id=?',(rid,))
        if not r or int(r['receiver_id'])!=uid or str(r['status'])!='pending': await q.answer('این درخواست دیگر معتبر نیست.',show_alert=True); return True
        if action=='mreject':
            await DBX.execute('UPDATE bb_marriage_requests SET status="rejected" WHERE id=?',(rid,)); await _bb_rel_send_notification(context.bot,int(r['sender_id']),_bb_ui_text(_BB_REL_TEXT_MARRIAGE_REJECT),None); await q.answer('❌ رد شد.'); await _bb_rel_marriage_panel(q,uid); return True
        if await _bb_rel_is_married(uid) or await _bb_rel_is_married(int(r['sender_id'])):
            await q.answer('💍 یکی از شما در حال حاضر همسر ثبت‌شده دارد.',show_alert=True); return True
        a,b=sorted([uid,int(r['sender_id'])])
        await DBX.execute('INSERT INTO bb_marriages(user1_id,user2_id,married_at,chat_id) VALUES(?,?,?,?)',(a,b,now_ts(),int(q.message.chat.id) if q.message and q.message.chat else None))
        await DBX.execute('UPDATE bb_marriage_requests SET status="accepted" WHERE id=?',(rid,))
        text=_bb_ui_text(_BB_REL_TEXT_MARRIAGE_ACCEPT); await _bb_rel_send_notification(context.bot,int(r['sender_id']),text,None)
        await q.answer('💍 ازدواج ثبت شد.'); await _bb_rel_marriage_panel(q,uid); return True
    if action in {'mquickaccept','mquickreject'}:
        sender=int(parts[2]); receiver=int(parts[3])
        if uid!=receiver: await q.answer('⛔ این درخواست برای تو نیست.',show_alert=True); return True
        r=await DBX.one('SELECT id,status FROM bb_marriage_requests WHERE sender_id=? AND receiver_id=? ORDER BY id DESC LIMIT 1',(sender,receiver))
        if not r or str(r['status'])!='pending': await q.answer('درخواست دیگر معتبر نیست.',show_alert=True); return True
        if action=='mquickreject':
            await DBX.execute('UPDATE bb_marriage_requests SET status="rejected" WHERE id=?',(int(r['id']),)); await q.answer('❌ رد شد.',show_alert=True); return True
        if await _bb_rel_is_married(receiver) or await _bb_rel_is_married(sender): await q.answer('💍 یکی از شما همسر ثبت‌شده دارد.',show_alert=True); return True
        a,b=sorted([sender,receiver]); await DBX.execute('INSERT INTO bb_marriages(user1_id,user2_id,married_at,chat_id) VALUES(?,?,?,?)',(a,b,now_ts(),int(q.message.chat.id) if q.message and q.message.chat else None))
        await DBX.execute('UPDATE bb_marriage_requests SET status="accepted" WHERE id=?',(int(r['id']),))
        await q.answer('💍 ازدواج ثبت شد!',show_alert=True); await _bb_rel_send_notification(context.bot,sender,_bb_ui_text(_BB_REL_TEXT_MARRIAGE_ACCEPT),None); return True
    if action=='divorce':
        owner=int(parts[2])
        if uid!=owner: await q.answer('⛔ این پنل برای تو نیست.',show_alert=True); return True
        married=await _bb_rel_is_married(uid)
        if not married: await q.answer('ازدواجی ثبت نشده است.',show_alert=True); return True
        a,b=sorted([uid,int(married['other_id'])]); await DBX.execute('DELETE FROM bb_marriages WHERE user1_id=? AND user2_id=?',(a,b))
        await q.answer('💔 طلاق ثبت شد.',show_alert=True); await _bb_rel_send_notification(context.bot,int(married['other_id']),_bb_ui_text(_BB_REL_TEXT_DIVORCE),None); await _bb_rel_marriage_panel(q,uid); return True
    return True

# Add relationship buttons to the user home without removing any existing menu items.
_BB_REL_OLD_HOME_KEYBOARD=v9_home_keyboard
def v9_home_keyboard(uid, admin=False):
    kb=_BB_REL_OLD_HOME_KEYBOARD(uid,admin)
