        (_BB_REL_TEXT_FRIEND_SENT,'text'),(_BB_REL_TEXT_FRIEND_IN,'text'),
        (_BB_REL_TEXT_FRIEND_ACCEPT,'text'),(_BB_REL_TEXT_FRIEND_REJECT,'text'),
        (_BB_REL_TEXT_MARRIAGE_SENT,'text'),(_BB_REL_TEXT_MARRIAGE_IN,'text'),
        (_BB_REL_TEXT_MARRIAGE_ACCEPT,'text'),(_BB_REL_TEXT_MARRIAGE_REJECT,'text'),
        (_BB_REL_TEXT_DIVORCE,'text'),(_BB_REL_BTN_FRIENDS,'button'),(_BB_REL_BTN_MARRIAGE,'button'),
        (_BB_REL_BTN_ACCEPT,'button'),(_BB_REL_BTN_REJECT,'button'),(_BB_REL_BTN_DIVORCE,'button'),
