_BB_REL_BUILD_PREV=build_application
def build_application(token=None):
    app=_BB_REL_BUILD_PREV(token)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_rel_text),group=-1000002)
