async def _bb_hist_schema():
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_iran_history(
        user_id INTEGER PRIMARY KEY, stage INTEGER NOT NULL DEFAULT 0, score INTEGER NOT NULL DEFAULT 0,
        attempts INTEGER NOT NULL DEFAULT 0, last_play_ts INTEGER NOT NULL DEFAULT 0,
        created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL)''')

async def _bb_hist_row(uid):
    await _bb_hist_schema(); r=await DBX.one('SELECT * FROM bb_iran_history WHERE user_id=?',(int(uid),))
    if r: return r
    ts=now_ts(); await DBX.execute('INSERT OR IGNORE INTO bb_iran_history(user_id,stage,score,attempts,last_play_ts,created_at,updated_at) VALUES(?,?,?,?,?,?,?)',(int(uid),0,0,0,0,ts,ts))
    return await DBX.one('SELECT * FROM bb_iran_history WHERE user_id=?',(int(uid),))

def _bb_hist_rank(stage):
    rank=_BB_HIST_RANKS[0][1]
    for need,title in _BB_HIST_RANKS:
        if int(stage)>=need: rank=title
    return rank

def _bb_hist_stage_text(row):
    s=min(int(row['stage']),len(_BB_HIST_STAGES)-1); title,desc,era,cost=_BB_HIST_STAGES[s]
    nxt='🏁 این آخرین مرحله است؛ با پشت سر گذاشتن آن به بالاترین مقام بازی، «👑 کوروش بزرگ» می‌رسی.' if s==len(_BB_HIST_STAGES)-1 else f'مرحله بعد: {_BB_HIST_STAGES[s+1][0]}'
    return _bb_ui_text(_BB_HIST_TEXTS['panel']).format(stage=s+1,total=len(_BB_HIST_STAGES),title=title,era=era,desc=desc,score=int(row['score']),rank=_bb_hist_rank(s),cost=cost,next_text=nxt)

async def _bb_hist_panel(q,uid):
    if int(q.from_user.id)!=int(uid): await q.answer('⛔ این پنل برای خودت است.',show_alert=True); return True
    row=await _bb_hist_row(uid); s=min(int(row['stage']),len(_BB_HIST_STAGES)-1)
    rows=[[btn('⚔️ ورود به مرحله',f'bbhist:play:{uid}')],
          [btn('🏆 مقام و پیشرفت',f'bbhist:rank:{uid}')],
          [btn('📜 فهرست مراحل',f'bbhist:list:{uid}')],
          [btn('🔙 برگشت',f'bblife:home:{uid}')]]
    await q.edit_message_text(_bb_hist_stage_text(row),parse_mode='HTML',reply_markup=keyboard(rows)); return True

async def _bb_hist_play(q,uid):
    row=await _bb_hist_row(uid); s=int(row['stage'])
    if s>=len(_BB_HIST_STAGES):
        await q.answer('👑 ماجراجویی کامل شده است.',show_alert=True); return True
    now=now_ts(); wait=max(0,180-(now-int(row['last_play_ts'] or 0)))
    if wait>0:
        await q.answer(f'⏳ برای عبور از این مرحله {wait} ثانیه دیگر صبر کن.',show_alert=True); return True
    title,desc,era,cost=_BB_HIST_STAGES[s]
    # Hard progression: escalating cost + a 2-step historical challenge.
    text=_bb_ui_text(_BB_HIST_TEXTS['attempt']).format(stage=s+1,title=title,desc=desc,cost=cost)
    await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([
        [btn(f'🔥 تلاش سخت — {cost:,} 🦴',f'bbhist:attempt:{uid}')],
        [btn('🔙 تاریخ ایران',f'bbhist:home:{uid}')]
    ])); return True

async def _bb_hist_attempt(q,uid):
    row=await _bb_hist_row(uid); s=int(row['stage'])
    if s>=len(_BB_HIST_STAGES): await q.answer('👑 کامل شده!',show_alert=True); return True
    now=now_ts(); wait=max(0,180-(now-int(row['last_play_ts'] or 0)))
    if wait>0: await q.answer(f'⏳ {wait} ثانیه دیگر دوباره تلاش کن.',show_alert=True); return True
    cost=_BB_HIST_STAGES[s][3]
    if not await _bb_sim_sub_money(uid,cost):
        await q.answer(f'❌ برای این مرحله {cost:,} 🦴 لازم داری.',show_alert=True); return True
    # Each stage is intentionally demanding but deterministic enough to remain fair.
    bonus=cost//2 + (s+1)*100
    new_stage=min(s+1,len(_BB_HIST_STAGES)); ts=now_ts()
    await DBX.execute('UPDATE bb_iran_history SET stage=?,score=score+?,attempts=attempts+1,last_play_ts=?,updated_at=? WHERE user_id=?',(new_stage,bonus,ts,ts,int(uid)))
    nr=await _bb_hist_row(uid)
    if new_stage>=len(_BB_HIST_STAGES):
        text=_bb_ui_text(_BB_HIST_TEXTS['finish'])
    else:
        text=_bb_ui_text(_BB_HIST_TEXTS['success']).format(title=_BB_HIST_STAGES[s][0],bonus=bonus,rank=_bb_hist_rank(new_stage),next_title=_BB_HIST_STAGES[new_stage][0])
    await q.answer('🏺 مرحله ثبت شد!',show_alert=True)
    await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('🏺 ادامه ماجراجویی',f'bbhist:home:{uid}')],[btn('🔙 زندگی',f'bblife:home:{uid}')]])); return True

async def _bb_hist_rank_panel(q,uid):
    row=await _bb_hist_row(uid); s=int(row['stage']);
    completed=min(s,len(_BB_HIST_STAGES)); pct=int(completed*100/len(_BB_HIST_STAGES))
    await q.edit_message_text(_bb_ui_text(_BB_HIST_TEXTS['rank']).format(rank=_bb_hist_rank(s),completed=completed,total=len(_BB_HIST_STAGES),pct=pct,score=int(row['score']),attempts=int(row['attempts'])),parse_mode='HTML',reply_markup=keyboard([[btn('🔙 تاریخ ایران',f'bbhist:home:{uid}')]])); return True

async def _bb_hist_list(q,uid):
    row=await _bb_hist_row(uid); cur=int(row['stage']); lines=[_bb_ui_text(_BB_HIST_TEXTS['list_title']),'']
    for i,(title,desc,era,cost) in enumerate(_BB_HIST_STAGES):
        mark='✅' if i<cur else ('🔓' if i==cur else '🔒')
        lines.append(f'{mark} {i+1}. {title} — {era}')
    await q.edit_message_text('\n'.join(lines),parse_mode='HTML',reply_markup=keyboard([[btn('🔙 تاریخ ایران',f'bbhist:home:{uid}')]])); return True

async def _bb_hist_callback(update,context):
    q=getattr(update,'callback_query',None); data=str(getattr(q,'data','') or '')
    if not q or not data.startswith('bbhist:'): return False
    p=data.split(':'); action=p[1] if len(p)>1 else ''; uid=int(p[2]) if len(p)>2 and p[2].isdigit() else int(q.from_user.id)
    if int(q.from_user.id)!=uid: await q.answer('⛔ این پنل برای خودت است.',show_alert=True); return True
    if action=='home': return await _bb_hist_panel(q,uid)
    if action=='play': return await _bb_hist_play(q,uid)
    if action=='attempt': return await _bb_hist_attempt(q,uid)
    if action=='rank': return await _bb_hist_rank_panel(q,uid)
    if action=='list': return await _bb_hist_list(q,uid)
    return True

async def _bb_hist_text(update,context):
    msg=getattr(update,'effective_message',None); user=getattr(update,'effective_user',None)
    if not msg or not user or not getattr(msg,'text',None): return False
    t=normalize(str(msg.text).strip())
    if t == 'ماجراجویی':
        fake=type('Q',(),{'from_user':user,'edit_message_text':msg.reply_text,'answer':lambda *a,**k:None})(); return await _bb_hist_panel(fake,int(user.id))
    return False

_BB_HIST_BUILD_PREV=build_application
def build_application(token=None):
    app=_BB_HIST_BUILD_PREV(token)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_hist_text),group=-3100000)
    app.add_handler(CallbackQueryHandler(_bb_hist_callback,pattern=r'^bbhist:'),group=-3100001)
    old_post=getattr(app,'post_init',None)
    async def _hist_post(application):
        if old_post: await old_post(application)
        await _bb_hist_schema()
        try:
            for _k,_v in _BB_HIST_TEXTS.items():
                try: await _bb_ui_register(_v,category='history',kind='text')
                except Exception: pass
            for _v in _BB_HIST_BUTTONS:
                try: await _bb_ui_register(_v,category='history',kind='button')
                except Exception: pass
            try: await _bb_ui_register('🏺 ماجراجویی تاریخ ایران',category='history',kind='button')
            except Exception: pass
            try: await _bb_ui_register('🏺 ماجراجویی تاریخ ایران',category='history',kind='text')
            except Exception: pass
        except Exception: pass
    app.post_init=_hist_post
    return app


# ===================== PERSEPOLIS + CYRUS GOVERNANCE EXPANSION =====================
_BB_PERSEPOLIS_PIECES = ['دروازه ملل','ستون سنگی','سرستون گاو','پلکان شرقی','پلکان شمالی','نقش سربازان','نقش نمایندگان','تالار آپادانا','ستون آپادانا','کاخ تچر','کاخ هدیش','کاخ داریوش','کاخ خشایارشا','تالار صدستون','دروازه سنگی','نقش‌برجسته شاه','باغ و حیاط شاهی','تالار آیین','خزانه شاهی','سنگ‌نوشته شاهی','تخت فرمانروایی','تخت جمشید کامل']
_BB_HIST_GOV_TEXTS = {
'panel':'🏺 <b>تخت جمشید تو</b>\n\n🧱 بخش‌های بازسازی‌شده: <b>{pieces}/{total}</b>\n📜 منشورهای نوشته‌شده: <b>{charters}</b>\n⚖️ عدالت: <b>{justice}</b>\n👑 اعتبار فرمانروایی: <b>{reign}</b>\n\n{status}',
'locked':'🔒 <b>تالار فرمانروایی هنوز باز نشده</b>\n\nابتدا باید تمام فصل‌های ماجراجویی تاریخ ایران را پشت سر بگذاری و همه بخش‌های تخت جمشید را کامل کنی.',
'charter':'📜 <b>منشور شاهی</b>\n\nتو در تخت جمشید می‌توانی منشور داستانی خودت را بنویسی.\n\n✍️ تعداد منشورها: <b>{charters}</b>\n🏛 اعتبار فرمانروایی: <b>{reign}</b>',
'justice':'⚖️ <b>دادگاه عدالت</b>\n\nیک پرونده به دربارت آمده است.\n\n⚖️ عدالت فعلی: <b>{justice}</b>\n👑 اعتبار: <b>{reign}</b>',
'decision':'⚖️ <b>حکم عادلانه ثبت شد</b>\n\nبرای امروز یک امتیاز عدالت به دست آوردی.\n⚖️ عدالت: <b>{justice}</b>\n👑 اعتبار: <b>{reign}</b>',
'rule':'👑 <b>تخت فرمانروایی</b>\n\nامروز بر تخت جمشید خود نشستی.\n🏛 حکومت: فعال\n⚖️ عدالت: {justice}\n📜 منشورها: {charters}\n👑 اعتبار: {reign}\n\nهر روز می‌توانی یک فرمان داستانی صادر کنی و مسیر حکومتت را بسازی.'}
_BB_HIST_GOV_BUTTONS = ['🏛️ تخت جمشید من','📜 نوشتن منشور','⚖️ بخشش و عدالت','👑 فرمانروایی امروز','🔙 ماجراجویی تاریخ ایران','⚖️ صدور حکم عادلانه']

async def _bb_hist_gov_schema():
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_iran_governance(user_id INTEGER PRIMARY KEY,pieces INTEGER NOT NULL DEFAULT 0,charters INTEGER NOT NULL DEFAULT 0,justice INTEGER NOT NULL DEFAULT 0,reign_score INTEGER NOT NULL DEFAULT 0,last_rule_ts INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL)''')
async def _bb_hist_gov_row(uid):
    await _bb_hist_gov_schema(); r=await DBX.one('SELECT * FROM bb_iran_governance WHERE user_id=?',(int(uid),))
    if r:return r
    ts=now_ts(); await DBX.execute('INSERT OR IGNORE INTO bb_iran_governance(user_id,pieces,charters,justice,reign_score,last_rule_ts,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)',(int(uid),0,0,0,0,0,ts,ts)); return await DBX.one('SELECT * FROM bb_iran_governance WHERE user_id=?',(int(uid),))
async def _bb_hist_gov_sync_piece(uid,completed_stage):
    r=await _bb_hist_gov_row(uid); pieces=min(int(completed_stage),len(_BB_PERSEPOLIS_PIECES)); ts=now_ts()
    if pieces>int(r['pieces']): await DBX.execute('UPDATE bb_iran_governance SET pieces=?,updated_at=? WHERE user_id=?',(pieces,ts,int(uid)))
    return await _bb_hist_gov_row(uid)
async def _bb_hist_gov_panel(q,uid):
    r=await _bb_hist_gov_row(uid); total=len(_BB_PERSEPOLIS_PIECES); pieces=int(r['pieces']); status=f'🔨 هنوز <b>{total-pieces}</b> بخش دیگر باقی مانده است.' if pieces<total else '👑 <b>تمام تخت جمشید کامل شده و تالار فرمانروایی کوروش باز است.</b>'
    text=_bb_ui_text(_BB_HIST_GOV_TEXTS['panel']).format(pieces=pieces,total=total,charters=int(r['charters']),justice=int(r['justice']),reign=int(r['reign_score']),status=status)
    rows=[[btn('📜 نوشتن منشور',f'bbhist:charter:{uid}'),btn('⚖️ بخشش و عدالت',f'bbhist:justice:{uid}')],[btn('👑 فرمانروایی امروز',f'bbhist:rule:{uid}')],[btn('🔙 ماجراجویی تاریخ ایران',f'bbhist:home:{uid}')]]
    await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard(rows)); return True
async def _bb_hist_gov_action(q,uid,action):
    r=await _bb_hist_gov_row(uid); total=len(_BB_PERSEPOLIS_PIECES); pieces=int(r['pieces'])
    if pieces<total:
        await q.edit_message_text(_bb_ui_text(_BB_HIST_GOV_TEXTS['locked']),parse_mode='HTML',reply_markup=keyboard([[btn('🔙 ماجراجویی تاریخ ایران',f'bbhist:home:{uid}')]])); return True
    ts=now_ts()
    if action=='charter':
        await DBX.execute('UPDATE bb_iran_governance SET charters=charters+1,reign_score=reign_score+5,updated_at=? WHERE user_id=?',(ts,int(uid))); r=await _bb_hist_gov_row(uid); text=_bb_ui_text(_BB_HIST_GOV_TEXTS['charter']).format(charters=int(r['charters']),reign=int(r['reign_score'])); rows=[[btn('📜 نوشتن منشور دیگر',f'bbhist:charter:{uid}')],[btn('🏛️ تخت جمشید من',f'bbhist:govern:{uid}')]]
    elif action=='justice':
        text=_bb_ui_text(_BB_HIST_GOV_TEXTS['justice']).format(justice=int(r['justice']),reign=int(r['reign_score'])); rows=[[btn('⚖️ صدور حکم عادلانه',f'bbhist:justice_yes:{uid}')],[btn('🔙 تخت جمشید من',f'bbhist:govern:{uid}')]]
    elif action=='justice_yes':
        await DBX.execute('UPDATE bb_iran_governance SET justice=justice+1,reign_score=reign_score+10,updated_at=? WHERE user_id=?',(ts,int(uid))); r=await _bb_hist_gov_row(uid); text=_bb_ui_text(_BB_HIST_GOV_TEXTS['decision']).format(justice=int(r['justice']),reign=int(r['reign_score'])); rows=[[btn('⚖️ عدالت و بخشش',f'bbhist:justice:{uid}')],[btn('🏛️ تخت جمشید من',f'bbhist:govern:{uid}')]]
    elif action=='rule':
        if ts-int(r['last_rule_ts'] or 0)<86400: await q.answer('⏳ فرمانروایی امروزت را قبلاً ثبت کرده‌ای.',show_alert=True); return True
        await DBX.execute('UPDATE bb_iran_governance SET reign_score=reign_score+20,last_rule_ts=?,updated_at=? WHERE user_id=?',(ts,ts,int(uid))); r=await _bb_hist_gov_row(uid); text=_bb_ui_text(_BB_HIST_GOV_TEXTS['rule']).format(justice=int(r['justice']),charters=int(r['charters']),reign=int(r['reign_score'])); rows=[[btn('📜 منشور',f'bbhist:charter:{uid}'),btn('⚖️ عدالت',f'bbhist:justice:{uid}')],[btn('🔙 ماجراجویی',f'bbhist:home:{uid}')]]
    else:return await _bb_hist_gov_panel(q,uid)
    await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard(rows)); return True
async def _bb_hist_gov_callback(update,context):
    q=getattr(update,'callback_query',None); data=str(getattr(q,'data','') or '')
    if not q or not data.startswith('bbhist:'): return False
    p=data.split(':'); action=p[1] if len(p)>1 else ''; uid=int(p[2]) if len(p)>2 and p[2].isdigit() else int(q.from_user.id)
    if int(q.from_user.id)!=uid: await q.answer('⛔ این پنل برای خودت است.',show_alert=True); return True
    if action=='govern': return await _bb_hist_gov_panel(q,uid)
    if action in {'charter','justice','justice_yes','rule'}: return await _bb_hist_gov_action(q,uid,action)
    return False
_BB_HIST_BUILD_PREV2=build_application
def build_application(token=None):
    app=_BB_HIST_BUILD_PREV2(token); app.add_handler(CallbackQueryHandler(_bb_hist_gov_callback,pattern=r'^bbhist:'),group=-3100002); old_post=getattr(app,'post_init',None)
    async def _hist_gov_post(application):
        if old_post: await old_post(application)
        await _bb_hist_gov_schema()
        try:
            for _k,_v in _BB_HIST_GOV_TEXTS.items(): await _bb_ui_register(_v,category='history',kind='text')
            for _v in _BB_HIST_GOV_BUTTONS: await _bb_ui_register(_v,category='history',kind='button')
        except Exception: pass
    app.post_init=_hist_gov_post; return app
_BB_HIST_ATTEMPT_PREV=_bb_hist_attempt
async def _bb_hist_attempt(q,uid):
    before=await _bb_hist_row(uid); old_stage=int(before['stage']); ok=await _BB_HIST_ATTEMPT_PREV(q,uid); after=await _bb_hist_row(uid)
    if int(after['stage'])>old_stage: await _bb_hist_gov_sync_piece(uid,int(after['stage']))
    return ok

# ===================== IRAN HISTORY: REST / BATTLE / TOKEN SYSTEM =====================
# Players must rest between battles, can fight up to 3 times per day, collect POWER,
# and spend historical TOKENS to unlock the harder stages.
_BB_HIST_BATTLE_ENEMIES = [
    ('نگهبان پارسی', 100, 1), ('سوار اشکانی', 180, 1), ('سپاه ساسانی', 280, 2),
    ('دژبان خراسان', 420, 2), ('فرمانده صفوی', 600, 3), ('سردار قاجار', 820, 3),
    ('لشکر زمان معاصر', 1100, 4)
]
_BB_HIST_BATTLE_TEXTS = {
    'panel':'⚔️ <b>اردوی نبرد تاریخی</b>\n\n💪 نیروی جمع‌شده: <b>{power:,}</b>\n🎟️ توکن تاریخی: <b>{tokens}</b>\n⚔️ نبرد امروز: <b>{fights}/3</b>\n🛌 وضعیت: <b>{rest}</b>\n\nبرای به‌دست‌آوردن توکن و عبور از مراحل سخت‌تر باید استراحت کنی، نیرو جمع کنی و در نبردهای روزانه پیروز شوی.\n\n👹 دشمن بعدی: <b>{enemy}</b>\n💥 قدرت دشمن: <b>{enemy_power:,}</b>',
    'rest':'🛌 <b>استراحت</b>\n\nنیروهایت را جمع کردی و آماده نبرد بعدی شدی.\n\n💪 نیروی فعلی: <b>{power:,}</b>\n⏳ برای نبرد بعدی باید کمی استراحت کنی.',
    'battle':'⚔️ <b>نبرد تاریخی</b>\n\n👹 دشمن: <b>{enemy}</b>\n💥 قدرت دشمن: <b>{enemy_power:,}</b>\n💪 نیروی تو: <b>{power:,}</b>\n\nبرای پیروزی باید نیروی کافی جمع کرده باشی.',
    'win':'🏆 <b>پیروزی!</b>\n\n👹 {enemy} شکست خورد.\n💪 +{gain:,} نیرو\n🎟️ +{token} توکن تاریخی\n\n⚔️ نبردهای امروز: <b>{fights}/3</b>',
    'locked':'🔒 <b>برای این مرحله توکن کافی نداری.</b>\n\n🎟️ توکن لازم: <b>{need}</b>\n🎟️ توکن فعلی: <b>{tokens}</b>\n\nبه اردو برو، استراحت کن و با نبردهای روزانه توکن جمع کن.'
}
_BB_HIST_BATTLE_BUTTONS = ['⚔️ اردو و نبرد','🛌 استراحت','⚔️ نبرد با نیروی قوی','🔙 ماجراجویی تاریخ ایران']

async def _bb_hist_battle_schema():
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_iran_battle(
        user_id INTEGER PRIMARY KEY, power INTEGER NOT NULL DEFAULT 0, tokens INTEGER NOT NULL DEFAULT 0,
        fights_today INTEGER NOT NULL DEFAULT 0, battle_day TEXT NOT NULL DEFAULT '',
        last_battle_ts INTEGER NOT NULL DEFAULT 0, rested INTEGER NOT NULL DEFAULT 1,
        created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL)''')

async def _bb_hist_battle_row(uid):
    await _bb_hist_battle_schema()
    r=await DBX.one('SELECT * FROM bb_iran_battle WHERE user_id=?',(int(uid),))
    if r: return r
    ts=now_ts(); day=time.strftime('%Y-%m-%d',time.gmtime(ts))
    await DBX.execute('INSERT OR IGNORE INTO bb_iran_battle(user_id,power,tokens,fights_today,battle_day,last_battle_ts,rested,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)',(int(uid),0,0,0,day,0,1,ts,ts))
    return await DBX.one('SELECT * FROM bb_iran_battle WHERE user_id=?',(int(uid),))

def _bb_hist_battle_day(ts=None):
    return time.strftime('%Y-%m-%d',time.gmtime(ts or now_ts()))

async def _bb_hist_battle_refresh(uid):
    r=await _bb_hist_battle_row(uid); day=_bb_hist_battle_day()
    if str(r['battle_day'])!=day:
        ts=now_ts(); await DBX.execute('UPDATE bb_iran_battle SET fights_today=0,battle_day=?,rested=1,updated_at=? WHERE user_id=?',(day,ts,int(uid))); r=await _bb_hist_battle_row(uid)
    return r

def _bb_hist_enemy_for_stage(stage):
    return _BB_HIST_BATTLE_ENEMIES[min(max(int(stage)//3,0),len(_BB_HIST_BATTLE_ENEMIES)-1)]

async def _bb_hist_battle_panel(q,uid):
    r=await _bb_hist_battle_refresh(uid); h=_bb_hist_enemy_for_stage(int((await _bb_hist_row(uid))['stage']))
    now=now_ts(); cd=max(0,5400-(now-int(r['last_battle_ts'] or 0))) if int(r['last_battle_ts'] or 0) else 0
    if cd: rest=f'⏳ {cd//60} دقیقه دیگر'
    elif not int(r['rested']): rest='🛌 اول استراحت کن'
    else: rest='✅ آماده'
    text=_bb_ui_text(_BB_HIST_BATTLE_TEXTS['panel']).format(power=int(r['power']),tokens=int(r['tokens']),fights=int(r['fights_today']),rest=rest,enemy=h[0],enemy_power=h[1])
    rows=[[btn('⚔️ نبرد با نیروی قوی',f'bbhist:battle:{uid}')],[btn('🛌 استراحت',f'bbhist:rest:{uid}')],[btn('🔙 ماجراجویی تاریخ ایران',f'bbhist:home:{uid}')]]
    await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard(rows)); return True

async def _bb_hist_rest(q,uid):
    r=await _bb_hist_battle_refresh(uid); ts=now_ts()
    if int(r['fights_today'])>=3:
        await q.answer('🌙 سهمیه سه نبرد امروزت تمام شده؛ فردا دوباره برگرد.',show_alert=True); return True
    if int(r['rested']):
        await q.answer('🛌 تو همین حالا آماده‌ای؛ بعد از هر نبرد باید دوباره استراحت کنی.',show_alert=True); return True
    await DBX.execute('UPDATE bb_iran_battle SET rested=1,updated_at=? WHERE user_id=?',(ts,int(uid)))
    r=await _bb_hist_battle_row(uid)
    text=_bb_ui_text(_BB_HIST_BATTLE_TEXTS['rest']).format(power=int(r['power']))
    await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('⚔️ نبرد با نیروی قوی',f'bbhist:battle:{uid}')],[btn('🔙 اردو',f'bbhist:battlepanel:{uid}')]])); return True

async def _bb_hist_battle(q,uid):
    r=await _bb_hist_battle_refresh(uid); stage=int((await _bb_hist_row(uid))['stage']); enemy,enemy_power,base_token=_bb_hist_enemy_for_stage(stage)
    now=now_ts()
    if int(r['fights_today'])>=3: await q.answer('🌙 امروز سه نبرد انجام دادی. برای فردا استراحت کن.',show_alert=True); return True
    if not int(r['rested']): await q.answer('🛌 بعد از نبرد قبلی باید استراحت کنی.',show_alert=True); return True
    if int(r['last_battle_ts'] or 0) and now-int(r['last_battle_ts'])<5400:
        await q.answer(f'⏳ هنوز {max(1,(5400-(now-int(r["last_battle_ts"])))//60)} دقیقه تا نبرد بعدی مانده.',show_alert=True); return True
    power=int(r['power'])
    text=_bb_ui_text(_BB_HIST_BATTLE_TEXTS['battle']).format(enemy=enemy,enemy_power=enemy_power,power=power)
    rows=[[btn('⚔️ حمله',f'bbhist:fight:{uid}')],[btn('🛌 استراحت',f'bbhist:rest:{uid}')],[btn('🔙 اردو',f'bbhist:battlepanel:{uid}')]]
    await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard(rows)); return True

async def _bb_hist_fight(q,uid):
    r=await _bb_hist_battle_refresh(uid); stage=int((await _bb_hist_row(uid))['stage']); enemy,enemy_power,base_token=_bb_hist_enemy_for_stage(stage); now=now_ts()
    if int(r['fights_today'])>=3 or not int(r['rested']): await q.answer('🛌 استراحت یا سهمیه روزانه را بررسی کن.',show_alert=True); return True
    if int(r['last_battle_ts'] or 0) and now-int(r['last_battle_ts'])<5400: await q.answer('⏳ هنوز برای نبرد بعدی آماده نیستی.',show_alert=True); return True
    # Power is accumulated over days; victory consumes some of it, while awarding a token.
    power=int(r['power'])
    if power < enemy_power:
        await DBX.execute('UPDATE bb_iran_battle SET fights_today=fights_today+1,last_battle_ts=?,rested=0,updated_at=? WHERE user_id=?',(now,now,int(uid)))
        await q.answer(f'💥 شکست خوردی؛ {enemy} از تو قوی‌تر بود. باید نیروی بیشتری جمع کنی.',show_alert=True); return True
    gain=enemy_power//2 + 50 + stage*10; token=max(1,base_token)
    new_power=max(0,power-enemy_power//3)+gain
    await DBX.execute('UPDATE bb_iran_battle SET power=?,tokens=tokens+?,fights_today=fights_today+1,last_battle_ts=?,rested=0,updated_at=? WHERE user_id=?',(new_power,token,now,now,int(uid)))
    nr=await _bb_hist_battle_row(uid)
    text=_bb_ui_text(_BB_HIST_BATTLE_TEXTS['win']).format(enemy=enemy,gain=gain,token=token,fights=int(nr['fights_today']))
    await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('🛌 استراحت',f'bbhist:rest:{uid}')],[btn('⚔️ اردو',f'bbhist:battlepanel:{uid}')],[btn('🔙 ماجراجویی',f'bbhist:home:{uid}')]])); return True

# Replace the historical attempt with a token gate while preserving the existing stage logic.
_BB_HIST_TOKEN_OLD_ATTEMPT=_bb_hist_attempt
async def _bb_hist_attempt(q,uid):
    r=await _bb_hist_battle_refresh(uid); stage=int((await _bb_hist_row(uid))['stage']); need=1+(stage//5)
    if int(r['tokens'])<need:
        text=_bb_ui_text(_BB_HIST_BATTLE_TEXTS['locked']).format(need=need,tokens=int(r['tokens']))
        await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('⚔️ اردو و نبرد',f'bbhist:battlepanel:{uid}')],[btn('🔙 تاریخ ایران',f'bbhist:home:{uid}')]])); return True
    await DBX.execute('UPDATE bb_iran_battle SET tokens=tokens-?,updated_at=? WHERE user_id=?',(need,now_ts(),int(uid)))
    return await _BB_HIST_TOKEN_OLD_ATTEMPT(q,uid)

# Patch the panel so battle resources are always visible and add battle callbacks.
_BB_HIST_OLD_PANEL=_bb_hist_panel
async def _bb_hist_panel(q,uid):
    await _bb_hist_battle_schema(); r=await _bb_hist_battle_refresh(uid); row=await _bb_hist_row(uid); s=min(int(row['stage']),len(_BB_HIST_STAGES)-1)
    h=_bb_hist_enemy_for_stage(int(row['stage'])); need=1+(int(row['stage'])//5)
    base=_bb_hist_stage_text(row)
    base += f'\n\n💪 نیروی جنگی: <b>{int(r["power"]):,}</b>  |  🎟️ توکن: <b>{int(r["tokens"])}</b>\n⚔️ نبرد امروز: <b>{int(r["fights_today"])}/3</b>\n🎟️ توکن لازم برای این مرحله: <b>{need}</b>\n👹 دشمن اردو: <b>{h[0]}</b> ({h[1]:,} قدرت)'
    rows=[[btn('⚔️ ورود به مرحله',f'bbhist:play:{uid}')],[btn('⚔️ اردو و نبرد',f'bbhist:battlepanel:{uid}')],[btn('🏆 مقام و پیشرفت',f'bbhist:rank:{uid}')],[btn('📜 فهرست مراحل',f'bbhist:list:{uid}')],[btn('🔙 برگشت',f'bblife:home:{uid}')]]
    await q.edit_message_text(base,parse_mode='HTML',reply_markup=keyboard(rows)); return True

_BB_HIST_BATTLE_BUILD_PREV=build_application
def build_application(token=None):
    app=_BB_HIST_BATTLE_BUILD_PREV(token)
    app.add_handler(CallbackQueryHandler(_bb_hist_battle_callback,pattern=r'^bbhist:(?:battlepanel|rest|battle|fight):'),group=-3100005)
    old_post=getattr(app,'post_init',None)
    async def _hist_battle_post(application):
        if old_post: await old_post(application)
        await _bb_hist_battle_schema()
        for v in _BB_HIST_BATTLE_TEXTS.values():
            try: await _bb_ui_register(v,category='history',kind='text')
            except Exception: pass
        for v in _BB_HIST_BATTLE_BUTTONS:
            try: await _bb_ui_register(v,category='history',kind='button')
            except Exception: pass
    app.post_init=_hist_battle_post
    return app

async def _bb_hist_battle_callback(update,context):
    q=getattr(update,'callback_query',None); data=str(getattr(q,'data','') or '')
    if not q or not data.startswith('bbhist:'): return False
    p=data.split(':'); action=p[1] if len(p)>1 else ''; uid=int(p[2]) if len(p)>2 and p[2].isdigit() else int(q.from_user.id)
    if int(q.from_user.id)!=uid: await q.answer('⛔ این پنل برای خودت است.',show_alert=True); return True
    if action=='battlepanel': return await _bb_hist_battle_panel(q,uid)
    if action=='rest': return await _bb_hist_rest(q,uid)
    if action=='battle': return await _bb_hist_battle(q,uid)
    if action=='fight': return await _bb_hist_fight(q,uid)
    return False


# ===================== FAMILY GROUP LIFE LAYER =====================
# Family events belong to the exact group where the couple married. Only the two spouses
# can operate the family controls; other members can see the story event but cannot act on it.
_BB_FAMILY_TEXTS = {
    'panel': '👨‍👩‍👧 <b>مدیریت خانواده</b>\n\n💍 زوج: {spouse}\n👶 فرزندان: {children}\n🏦 بدهی خانواده: {debt:,} 🦴\n📨 اتفاق‌های اخیر: {events}\n\nهمه اتفاق‌های خانواده در همین گروه ثبت می‌شوند و فقط همین خانواده می‌تواند آن‌ها را مدیریت کند.',
    'event': '📨 <b>اتفاق خانوادگی</b>\n\n👶 فرزند: <b>{child}</b>\n{title}\n{body}\n\n💰 هزینه پیشنهادی: <b>{cost:,}</b> 🦴\n\nاین اتفاق مخصوص خانواده همین زوج است.',
    'access': '⛔ این بخش فقط برای همان خانواده‌ای است که در این گروه ازدواج کرده‌اند.',
    'guide': '👨‍👩‍👧 <b>خانواده</b>\n\nدستور اصلی: <code>خانواده</code>\n\nاتفاق‌های فرزندان، هزینه‌ها، مدرسه، شناسنامه و مراحل بزرگ شدن در همان گروهی که ازدواج ثبت شده مدیریت می‌شود.\n\nهر خانواده پرونده و اتفاق‌های مستقل خودش را دارد.'
}
_BB_FAMILY_BUTTONS = ['👨‍👩‍👧 مدیریت خانواده','📨 اتفاق‌های خانواده','🪪 شناسنامه فرزندان','👶 فرزندان','💳 پرداخت هزینه','🔙 زندگی']

async def _bb_family_group_id(uid, chat_id=None):
    m=await _bb_rel_is_married(uid)
    if not m: return None
    if m.get('chat_id') is None and chat_id is not None:
        try:
            await DBX.execute('UPDATE bb_marriages SET chat_id=? WHERE user1_id=? AND user2_id=?',(int(chat_id),min(uid,m['other_id']),max(uid,m['other_id'])))
            m['chat_id']=int(chat_id)
        except Exception: pass
    return m.get('chat_id')

async def _bb_family_access(uid, chat_id):
    m=await _bb_rel_is_married(uid)
    if not m: return None
    gid=await _bb_family_group_id(uid,chat_id)
    if gid is None or int(gid)!=int(chat_id): return None
    return m

async def _bb_family_panel_message(chat_id, uid, bot):
    m=await _bb_family_access(uid,chat_id)
    if not m:
        await bot.send_message(chat_id=chat_id,text=_bb_ui_text(_BB_FAMILY_TEXTS['access']),parse_mode='HTML'); return
    rows=await _bb_sim_child_rows(uid)
    debt=await DBX.one('SELECT COALESCE(SUM(remaining),0) AS c FROM bb_life_loans WHERE user_id=? AND status="active"',(int(uid),))
    ev=await DBX.one('SELECT COUNT(*) AS c FROM bb_life_events WHERE user1_id=? AND user2_id=?',(min(uid,m['other_id']),max(uid,m['other_id'])))
    spouse=await _bb_rel_user_name(m['other_id'])
    text=_bb_ui_text(_BB_FAMILY_TEXTS['panel']).format(spouse=spouse,children=len(rows),debt=int(debt['c'] if debt else 0),events=int(ev['c'] if ev else 0))
    kb=keyboard([[btn('👶 فرزندان',f'bbfamily:children:{uid}')],[btn('📨 اتفاق‌های خانواده',f'bbfamily:events:{uid}')],[btn('🪪 شناسنامه فرزندان',f'bbfamily:cert:{uid}')],[btn('🔙 زندگی',f'bblife:home:{uid}')]])
    await bot.send_message(chat_id=chat_id,text=text,parse_mode='HTML',reply_markup=kb)

async def _bb_family_command(update,context):
    msg=update.effective_message; chat=update.effective_chat; user=update.effective_user
    if not msg or not user or not chat or chat.type not in {'group','supergroup'}: return False
    if _bb_plain_tool_text(msg.text or '') != 'خانواده': return False
    m=await _bb_family_access(int(user.id),int(chat.id))
    if not m:
        await msg.reply_text(_bb_ui_text(_BB_FAMILY_TEXTS['access']),parse_mode='HTML'); return True
    await _bb_family_panel_message(int(chat.id),int(user.id),context.bot); return True

async def _bb_family_events(q,uid,chat_id):
    m=await _bb_family_access(uid,chat_id)
    if not m:
        await q.answer(_bb_ui_text(_BB_FAMILY_TEXTS['access']),show_alert=True); return True
    a,b=sorted([uid,int(m['other_id'])]); rows=await DBX.all('SELECT * FROM bb_life_events WHERE user1_id=? AND user2_id=? ORDER BY id DESC LIMIT 8',(a,b))
    if not rows: text='📨 <b>اتفاق‌های خانواده</b>\n\nهنوز اتفاقی ثبت نشده.'
    else: text='📨 <b>اتفاق‌های خانواده</b>\n\n'+'\n\n'.join(f"• {r['text']}" for r in rows)
    await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('👨‍👩‍👧 خانواده',f'bbfamily:home:{uid}')]])); return True

async def _bb_family_callback(update,context):
    q=getattr(update,'callback_query',None); d=str(getattr(q,'data','') or '')
    if not q or not d.startswith('bbfamily:'): return False
    p=d.split(':'); action=p[1] if len(p)>1 else ''; uid=int(p[2]) if len(p)>2 and p[2].isdigit() else int(q.from_user.id)
    if int(q.from_user.id)!=uid: await q.answer(_bb_ui_text(_BB_FAMILY_TEXTS['access']),show_alert=True); return True
    chat_id=int(q.message.chat.id) if q.message and q.message.chat else 0
    m=await _bb_family_access(uid,chat_id)
    if not m: await q.answer(_bb_ui_text(_BB_FAMILY_TEXTS['access']),show_alert=True); return True
    if action=='home': await _bb_family_panel_message(chat_id,uid,q.get_bot()); return True
    if action=='events': return await _bb_family_events(q,uid,chat_id)
    if action=='children': return await _bb_sim_children_panel(q,uid)
    if action=='cert': return await _bb_sim_cert(q,uid)
    return False

# Route all automatic child notices to the marriage group instead of private messages.
_BB_SIM_TICK_OLD=_bb_sim_child_event_tick
async def _bb_sim_child_event_tick(application=None):
    await _BB_SIM_TICK_OLD(application)
    # Re-broadcast the newest family events into the exact marriage group, once per event.
    if not application: return
    rows=await DBX.all('SELECT * FROM bb_life_events WHERE event_type IN ("child_challenge","child_love") ORDER BY id DESC LIMIT 20')
    for r in rows:
        marker=f'family_event_sent:{int(r["id"])}'
        sent=await DBX.one('SELECT id FROM bb_life_events WHERE event_type=? AND text LIKE ? LIMIT 1',('family_event_sent',f'%#{int(r["id"])}%'))
        if sent: continue
        m=await _bb_rel_is_married(int(r['user1_id']))
        gid=m.get('chat_id') if m else None
        if not gid: continue
        txt=f"👨‍👩‍👧 <b>اتفاق جدید خانواده</b>\n\n{r['text']}\n\n🔒 فقط همین زوج می‌توانند از دستور «خانواده» مدیریت کنند."
        try: await application.bot.send_message(chat_id=int(gid),text=txt,parse_mode='HTML')
        except Exception: continue
        await DBX.execute('INSERT INTO bb_life_events(user1_id,user2_id,event_type,text,created_at) VALUES(?,?,?,?,?)',(int(r['user1_id']),int(r['user2_id']),'family_event_sent',marker,now_ts()))

# Final registration layer: command, family callback, guide entry, and designable strings/buttons.
_BB_FAMILY_BUILD_PREV=build_application
def build_application(token=None):
    app=_BB_FAMILY_BUILD_PREV(token)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_family_command),group=-3200010)
    app.add_handler(CallbackQueryHandler(_bb_family_callback,pattern=r'^bbfamily:'),group=-3200011)
    old_post=getattr(app,'post_init',None)
    async def _family_post(application):
        if old_post: await old_post(application)
        try:
            await DBX.execute('ALTER TABLE bb_marriages ADD COLUMN chat_id INTEGER')
        except Exception: pass
        for v in _BB_FAMILY_TEXTS.values():
            try: await _bb_ui_register(v,category='relationships',kind='text')
            except Exception: pass
        for v in _BB_FAMILY_BUTTONS:
            try: await _bb_ui_register(v,category='relationships',kind='button')
            except Exception: pass
    app.post_init=_family_post
    return app

# Add the family topic to the glass guide without replacing existing guide pages.
_BB_GLASS_HELP_CALLBACK_OLD=_bb_glass_help_callback
async def _bb_glass_help_callback(update,context):
    q=update.callback_query; d=str(q.data or '')
    if d=='uxhelp:games':
        uid=q.from_user.id
        text='🎮 <b>بازی‌ها و زندگی</b>\n\n🏺 <b>ماجراجویی تاریخ ایران</b>\n<code>ماجراجویی</code>\n\n👨‍👩‍👧 <b>خانواده</b>\n<code>خانواده</code>\n\n«خانواده» فقط در همان گروهی کار می‌کند که ازدواج ثبت شده و پرونده هر زوج مستقل است.'
        await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('🔙 راهنما','uxhelp:home')]])); return True
    return await _BB_GLASS_HELP_CALLBACK_OLD(update,context)


# Replace the automatic family ticker with a group-only version. No private family event messages are sent.
async def _bb_sim_child_event_tick(application=None):
    import random
    now=now_ts()
    # Births are probabilistic: an attempt can succeed or fail.
    pregnancies=await DBX.all('SELECT * FROM bb_life_pregnancies WHERE due_ts<=?',(now,))
    for p in pregnancies:
        a,b=sorted([int(p['user1_id']),int(p['user2_id'])])
        m=await _bb_rel_is_married(a)
        gid=m.get('chat_id') if m else None
        if random.random() < 0.72:
            gender=random.choice(['👧 دختر','👦 پسر']); name=random.choice(_BB_CHILD_NAMES[gender]); seed=random.randint(100000,999999)
            await DBX.execute('INSERT INTO bb_life_children(parent1_id,parent2_id,gender,born_at,created_at,age_years,stage,school,family_seed,name) VALUES(?,?,?,?,?,?,?,?,?,?)',(a,b,gender,now,now,0,'نوزاد',0,seed,name))
            text=_bb_ui_text(_BB_SIM_TEXTS['child_born']).format(gender=gender,name=name)
        else:
            text='💔 <b>خبر خانواده</b>\n\nاین بار تلاش برای بچه‌دار شدن نتیجه نداد. نگران نباشید؛ در آینده می‌توانید دوباره اقدام کنید.'
        await DBX.execute('DELETE FROM bb_life_pregnancies WHERE user1_id=? AND user2_id=?',(a,b))
        await DBX.execute('INSERT INTO bb_life_events(user1_id,user2_id,event_type,text,created_at) VALUES(?,?,?,?,?)',(a,b,'child_birth',text,now))
        if application and gid:
            try: await application.bot.send_message(chat_id=int(gid),text='👨‍👩‍👧 <b>خبر خانواده</b>\n\n'+text+'\n\n🔒 مدیریت این خبر فقط برای همین زوج است؛ دستور «خانواده» را بزنید.',parse_mode='HTML')
            except Exception: pass
    rows=await DBX.all('SELECT * FROM bb_life_children WHERE alive=1')
    for r in rows:
        age=int(r['age_years'] or 0); born=int(r['born_at'] or now); target=min(30,max(0,(now-born)//(3*86400)))
        if target>age:
            new_age=int(target); stage=await _bb_sim_child_stage(new_age); school=1 if 6<=new_age<18 else 0
            await DBX.execute('UPDATE bb_life_children SET age_years=?,stage=?,school=? WHERE id=?',(new_age,stage,school,int(r['id'])))
            if new_age in (6,18):
                a,b=sorted([int(r['parent1_id']),int(r['parent2_id'])]); m=await _bb_rel_is_married(a); gid=m.get('chat_id') if m else None
                text=f"🎂 <b>رشد فرزند خانواده</b>\n\n👤 {r['name']} وارد مرحله «{stage}» شد."
                await DBX.execute('INSERT INTO bb_life_events(user1_id,user2_id,event_type,text,created_at) VALUES(?,?,?,?,?)',(a,b,'child_growth',text,now_ts()))
                if application and gid:
                    try: await application.bot.send_message(chat_id=int(gid),text=text+'\n\n🔒 فقط همین خانواده می‌تواند مدیریت کند.',parse_mode='HTML')
                    except Exception: pass
        last=await DBX.one('SELECT created_at FROM bb_life_events WHERE user1_id=? AND user2_id=? AND event_type="child_challenge" ORDER BY id DESC LIMIT 1',(int(r['parent1_id']),int(r['parent2_id'])))
        if not last or now-int(last['created_at'])>=86400:
            title,body=random.choice(_BB_CHILD_EVENTS); cost=random.choice([250,300,350,400,500]); event_text=f"#{int(r['id'])} {title} {body} هزینه پیشنهادی {cost} 🦴"
            a,b=sorted([int(r['parent1_id']),int(r['parent2_id'])]); m=await _bb_rel_is_married(a); gid=m.get('chat_id') if m else None
            await DBX.execute('INSERT INTO bb_life_events(user1_id,user2_id,event_type,text,created_at) VALUES(?,?,?,?,?)',(a,b,'child_challenge',event_text,now_ts()))
            if application and gid:
                notice=f"👨‍👩‍👧 <b>اتفاق ناگهانی برای خانواده!</b>\n\n👤 {r['name']}\n{title}\n{body}\n\n💰 هزینه پیشنهادی: <b>{cost:,}</b> 🦴\n\n🔒 فقط همین زوج می‌توانند با «خانواده» مدیریت کنند."
                try: await application.bot.send_message(chat_id=int(gid),text=notice,parse_mode='HTML')
                except Exception: pass
        # Married couples can also face relationship crises: betrayal is rare and never forced.
        # It is recorded as a family/life event and reduces trust/intimacy, but does not auto-divorce.
        a,b=sorted([int(r['parent1_id']),int(r['parent2_id'])])
        # Check a recent betrayal for this couple so frequent scheduler runs cannot spam it.
        recent_betrayal=await DBX.one('SELECT created_at FROM bb_life_events WHERE user1_id=? AND user2_id=? AND event_type=\"betrayal\" ORDER BY id DESC LIMIT 1',(a,b))
        if (not recent_betrayal or now-int(recent_betrayal['created_at'])>=3*86400) and random.random()<0.025:
            cheater=random.choice([a,b]); other=b if cheater==a else a
            cheater_name=await _bb_rel_user_name(cheater); other_name=await _bb_rel_user_name(other)
            betrayal_text=(f'💔 <b>بحران رابطه</b>\n\n{cheater_name} در یک موقعیت وسوسه‌برانگیز قرار گرفت و یک خیانت عاطفی در داستان زندگی ثبت شد.\n'
                           f'اعتماد بین {cheater_name} و {other_name} آسیب دید؛ ادامه رابطه به انتخاب و رفتار بعدی آن‌ها بستگی دارد.')
            await DBX.execute('INSERT INTO bb_life_events(user1_id,user2_id,event_type,text,created_at) VALUES(?,?,?,?,?)',(a,b,'betrayal',betrayal_text,now_ts()))
            await DBX.execute('UPDATE bb_life_accounts SET mood=MAX(0,mood-10),intimacy=MAX(0,intimacy-12) WHERE user_id IN (?,?)',(a,b))
            m=await _bb_rel_is_married(a); gid=m.get('chat_id') if m else None
            if application and gid:
                try:
                    await application.bot.send_message(chat_id=int(gid),text=betrayal_text+'\n\n🧩 برای دیدن روند رابطه، «زندگی» را باز کنید.',parse_mode='HTML')
                except Exception: pass

        # Adult children can independently enter a love story; still posted only to their family group.
        if int(r['age_years'] or 0)>=18 and str(r['relationship_status'])=='single' and random.random()<0.12:
            opposite='👧 دختر' if str(r['gender'])=='👦 پسر' else '👦 پسر'; name=random.choice(_BB_CHILD_NAMES[opposite])
            await DBX.execute('UPDATE bb_life_children SET relationship_status="in_love",partner_name=? WHERE id=?',(name,int(r['id'])))
            a,b=sorted([int(r['parent1_id']),int(r['parent2_id'])]); m=await _bb_rel_is_married(a); gid=m.get('chat_id') if m else None
            love_text=f"💘 {r['name']} عاشق {name} شده است؛ وقت آشنایی و خواستگاری خانوادگی رسیده."
            await DBX.execute('INSERT INTO bb_life_events(user1_id,user2_id,event_type,text,created_at) VALUES(?,?,?,?,?)',(a,b,'child_love',love_text,now_ts()))
            if application and gid:
                try: await application.bot.send_message(chat_id=int(gid),text='👨‍👩‍👧 <b>خبر مهم خانواده</b>\n\n'+love_text+'\n\nبرای ادامه، دستور «خانواده» را مدیریت کنید.',parse_mode='HTML')
                except Exception: pass
        # Love can later end in a heartbreak; this is separate from the parents' marriage.
        if int(r['age_years'] or 0)>=18 and str(r['relationship_status'])=='in_love':
            last_love=await DBX.one('SELECT created_at FROM bb_life_events WHERE user1_id=? AND user2_id=? AND event_type=\"child_love\" ORDER BY id DESC LIMIT 1',(int(r['parent1_id']),int(r['parent2_id'])))
            last_break=await DBX.one('SELECT created_at FROM bb_life_events WHERE user1_id=? AND user2_id=? AND event_type=\"heartbreak\" ORDER BY id DESC LIMIT 1',(int(r['parent1_id']),int(r['parent2_id'])))
            if last_love and (not last_break or int(last_break['created_at']) < int(last_love['created_at'])) and now-int(last_love['created_at'])>=86400 and random.random()<0.10:
                partner=str(r['partner_name'] or 'عشقش')
                heartbreak=f'💔 <b>شکست عشقی</b>\n\nرابطه {r["name"]} و {partner} به پایان رسید و {r["name"]} مدتی دل‌شکسته است.\n\nاین اتفاق به‌معنی پایان همیشگی داستان نیست؛ ممکن است در آینده دوباره عاشق شود.'
                a,b=sorted([int(r['parent1_id']),int(r['parent2_id'])])
                await DBX.execute('UPDATE bb_life_children SET relationship_status=\"single\",partner_name=NULL WHERE id=?',(int(r['id']),))
                await DBX.execute('INSERT INTO bb_life_events(user1_id,user2_id,event_type,text,created_at) VALUES(?,?,?,?,?)',(a,b,'heartbreak',heartbreak,now_ts()))
                m=await _bb_rel_is_married(a); gid=m.get('chat_id') if m else None
                if application and gid:
                    try: await application.bot.send_message(chat_id=int(gid),text='👨‍👩‍👧 <b>خبر عاطفی خانواده</b>\n\n'+heartbreak+'\n\nبرای پیگیری، «خانواده» را بزنید.',parse_mode='HTML')
                    except Exception: pass

# =============================================================================
# FINAL LIFE-GENERATION LAYER — FULLY DESIGNABLE LIFE/DEATH/REBIRTH
# =============================================================================
# The life simulator is intentionally generational: when the player's virtual
# age reaches the configured end-of-life age, the player can continue the story
# through an adult son.  This is a game mechanic; Telegram identity itself is
# never changed.
_BB_LIFE_GEN_TEXTS = {
    'death': '🕯️ <b>پایان یک نسل</b>\n\n{old_name} در سن <b>{age}</b> سالگی از دنیا رفت.\n\nداستان خانواده اما تمام نشده است؛ زندگی تو حالا از نسل بعد ادامه پیدا می‌کند.',
    'rebirth': '🌱 <b>نسل بعدی</b>\n\nتو وارد جسم پسرت، <b>{child}</b>، شدی.\n\n👤 سن فعلی: <b>{age}</b> سال\n🧬 نسل: <b>{generation}</b>\n\nاز اینجا به بعد، زندگی واقعی‌تر ادامه دارد: کار، رابطه، ازدواج، فرزند، اتفاق‌های خوب و بد و در نهایت یک چرخه جدید زندگی.',
    'no_successor': '🕯️ <b>پایان نسل</b>\n\nزندگی تو به پایان طبیعی خود رسید، اما هنوز فرزند پسر بالغی برای ادامه نسل وجود ندارد.\n\nبرای ادامه داستان، خانواده باید نسل بعدی داشته باشد.',
    'status': '🧬 <b>نسل زندگی</b>\n\n👤 سن: <b>{age}</b> سال\n🧬 نسل: <b>{generation}</b>\n❤️ وضعیت زندگی: {alive}\n👶 جانشین: {child}',
    'child_death': '🕯️ <b>خبر تلخ خانواده</b>\n\n{child} در سن <b>{age}</b> سالگی از دنیا رفت.\n\nاین اتفاق در پرونده خانواده ثبت شد و داستان نسل‌ها ادامه پیدا می‌کند.',
}
_BB_LIFE_GEN_BUTTONS = [
    '🧬 وضعیت نسل', '👶 ادامه با پسرم', '👨‍👩‍👧 خانواده', '🔙 زندگی',
]
_BB_LIFE_GEN_MAX_AGE = 80

async def _bb_life_generation_schema():
    await DBX.execute("ALTER TABLE bb_life_accounts ADD COLUMN life_age INTEGER NOT NULL DEFAULT 18") if not await _bb_col_exists('bb_life_accounts','life_age') else None
    await DBX.execute("ALTER TABLE bb_life_accounts ADD COLUMN life_birth_ts INTEGER NOT NULL DEFAULT 0") if not await _bb_col_exists('bb_life_accounts','life_birth_ts') else None
    await DBX.execute("ALTER TABLE bb_life_accounts ADD COLUMN life_alive INTEGER NOT NULL DEFAULT 1") if not await _bb_col_exists('bb_life_accounts','life_alive') else None
    await DBX.execute("ALTER TABLE bb_life_accounts ADD COLUMN life_generation INTEGER NOT NULL DEFAULT 1") if not await _bb_col_exists('bb_life_accounts','life_generation') else None
    await DBX.execute("ALTER TABLE bb_life_accounts ADD COLUMN incarnation_child_id INTEGER NOT NULL DEFAULT 0") if not await _bb_col_exists('bb_life_accounts','incarnation_child_id') else None
    await DBX.execute("ALTER TABLE bb_life_accounts ADD COLUMN last_life_event_ts INTEGER NOT NULL DEFAULT 0") if not await _bb_col_exists('bb_life_accounts','last_life_event_ts') else None
    now=now_ts()
    rows=await DBX.all('SELECT user_id,life_age,life_birth_ts FROM bb_life_accounts')
    for r in rows:
        if int(r['life_birth_ts'] or 0)<=0:
            age=max(0,int(r['life_age'] or 18))
            await DBX.execute('UPDATE bb_life_accounts SET life_age=?,life_birth_ts=? WHERE user_id=?',(age,now-age*3*86400,int(r['user_id'])))

async def _bb_col_exists(table,col):
    try:
        rows=await DBX.all(f'PRAGMA table_info({table})')
        return any(str(x['name'])==col for x in rows)
    except Exception:
        return False

async def _bb_life_generation_account(uid):
    await _bb_sim_schema()
    await _bb_life_generation_schema()
    return await DBX.one('SELECT * FROM bb_life_accounts WHERE user_id=?',(int(uid),))

async def _bb_life_generation_event(a,b,event_type,text):
    a,b=sorted([int(a),int(b)])
    await DBX.execute('INSERT INTO bb_life_events(user1_id,user2_id,event_type,text,created_at) VALUES(?,?,?,?,?)',(a,b,event_type,text,now_ts()))

async def _bb_life_send_group(application,uid,text):
    if not application:return
    m=await _bb_rel_is_married(int(uid)); gid=m.get('chat_id') if m else None
    if not gid:
        return
    try:
        await application.bot.send_message(chat_id=int(gid),text=text,parse_mode='HTML')
    except Exception:
        pass

async def _bb_life_reincarnate(application,uid,acc,children):
    import random
    uid=int(uid)
    adult_sons=[r for r in children if int(r['alive'] or 0) and int(r['age_years'] or 0)>=18 and 'پسر' in str(r['gender'])]
    adult_children=[r for r in children if int(r['alive'] or 0) and int(r['age_years'] or 0)>=18]
    child=(random.choice(adult_sons) if adult_sons else (random.choice(adult_children) if adult_children else None))
    if not child:
        return False
    old_name=await _bb_rel_user_name(uid)
    old_age=int(acc['life_age'] or 0)
    generation=int(acc['life_generation'] or 1)+1
    child_name=str(child['name'] or 'فرزند')
    child_age=int(child['age_years'] or 18)
    # The old character dies. The Telegram account remains the same player,
    # but the life simulator switches the playable character to the child.
    await DBX.execute('''UPDATE bb_life_accounts
        SET life_alive=1,life_age=?,life_birth_ts=?,life_generation=?,incarnation_child_id=?,
            last_life_event_ts=?,job='',mood=80,intimacy=80,last_salary_day=''
        WHERE user_id=?''',(child_age,now_ts()-child_age*3*86400,generation,int(child['id']),now_ts(),uid))
    # Prevent the same child from being selected as a second incarnation.
    await DBX.execute('UPDATE bb_life_children SET relationship_status="incarnated" WHERE id=?',(int(child['id']),))
    death=_bb_ui_text(_BB_LIFE_GEN_TEXTS['death']).format(old_name=old_name,age=old_age)
    rebirth=_bb_ui_text(_BB_LIFE_GEN_TEXTS['rebirth']).format(child=child_name,age=child_age,generation=generation)
    await DBX.execute('INSERT INTO bb_life_events(user1_id,user2_id,event_type,text,created_at) VALUES(?,?,?,?,?)',(uid,uid,'player_death',death,now_ts()))
    await DBX.execute('INSERT INTO bb_life_events(user1_id,user2_id,event_type,text,created_at) VALUES(?,?,?,?,?)',(uid,uid,'reincarnation',rebirth,now_ts()))
    await _bb_life_send_group(application,uid,death+'\n\n'+rebirth)
    return True

async def _bb_life_generation_tick(application=None):
    import random
    await _bb_life_generation_schema()
    now=now_ts()
    rows=await DBX.all('SELECT * FROM bb_life_accounts WHERE life_alive=1')
    for acc in rows:
        uid=int(acc['user_id'])
        birth=int(acc['life_birth_ts'] or 0)
        if birth<=0: continue
        age=min(_BB_LIFE_GEN_MAX_AGE,max(0,(now-birth)//(3*86400)))
        if age!=int(acc['life_age'] or 0):
            await DBX.execute('UPDATE bb_life_accounts SET life_age=? WHERE user_id=?',(int(age),uid))
        # A character does not die before the configured age.  Once the age is
        # reached, an adult son is preferred as the next playable body.
        if age>=_BB_LIFE_GEN_MAX_AGE:
            children=await DBX.all('SELECT * FROM bb_life_children WHERE parent1_id=? OR parent2_id=? ORDER BY age_years DESC',(uid,uid))
            if not any(int(r['alive'] or 0) and int(r['age_years'] or 0)>=18 and 'پسر' in str(r['gender']) for r in children):
                # Keep the character alive until a suitable adult son exists.
                # This avoids ending the player's story with no playable successor.
                continue
            await _bb_life_reincarnate(application,uid,acc,children)

    # Rare natural deaths for children. Adults are more likely than young kids;
    # this remains a game event, not a real-world medical model.
    children=await DBX.all('SELECT * FROM bb_life_children WHERE alive=1 AND age_years>=18')
    for r in children:
        age=int(r['age_years'] or 0)
        if age<18: continue
        # Only check once per roughly 24 hours per family/child.
        marker=await DBX.one('SELECT created_at FROM bb_life_events WHERE event_type="child_death" AND text LIKE ? ORDER BY id DESC LIMIT 1',(f'%#{int(r["id"])}%',))
        if marker and now-int(marker['created_at'])<86400: continue
        chance=0.0008 if age<60 else 0.0025 if age<75 else 0.008
        if random.random()>=chance: continue
        a,b=sorted([int(r['parent1_id']),int(r['parent2_id'])])
        child_name=str(r['name'] or 'فرزند')
        text=_bb_ui_text(_BB_LIFE_GEN_TEXTS['child_death']).format(child=child_name,age=age)+'\n\n#'+str(int(r['id']))
        await DBX.execute('UPDATE bb_life_children SET alive=0,relationship_status="deceased" WHERE id=?',(int(r['id']),))
        await DBX.execute('INSERT INTO bb_life_events(user1_id,user2_id,event_type,text,created_at) VALUES(?,?,?,?,?)',(a,b,'child_death',text,now_ts()))
        m=await _bb_rel_is_married(a); gid=m.get('chat_id') if m else None
        if application and gid:
            try: await application.bot.send_message(chat_id=int(gid),text=text,parse_mode='HTML')
            except Exception: pass

# Replace the family/life ticker one final time so aging, relationship events,
# and generational succession all run from the same scheduler.
_BB_LIFE_PREV_TICK=_bb_sim_child_event_tick
async def _bb_sim_child_event_tick(application=None):
    await _BB_LIFE_PREV_TICK(application)
    try:
        await _bb_life_generation_tick(application)
    except Exception as exc:
        log.warning('life generation tick failed: %s',exc)

# Full life/family design registry. These are templates, so placeholders remain
# editable by the owner while runtime values are filled safely at send time.
async def _bb_register_full_life_design():
    for k,v in {**_BB_LIFE_GEN_TEXTS,**_BB_FAMILY_TEXTS}.items():
        try: await _bb_ui_register(v,category='relationships',kind='text')
        except Exception: pass
    for v in list(_BB_LIFE_GEN_BUTTONS)+list(_BB_FAMILY_BUTTONS):
        try: await _bb_ui_register(v,category='relationships',kind='button')
        except Exception: pass

# Final build wrapper: add the complete design registry to the owner studio.
# python-telegram-bot's Application uses __slots__, so startup state cannot be
# stored as a custom Application attribute. Keep the re-entry guard externally.
_BB_FULL_LIFE_POST_RUNNING=set()
_BB_FULL_LIFE_BUILD_PREV=build_application
def build_application(token=None):
    app=_BB_FULL_LIFE_BUILD_PREV(token)
    old_post=getattr(app,'post_init',None)
    async def _full_life_post(application):
        # Some earlier feature patches wrap build_application and therefore
        # their post_init callbacks can form a cycle. Guard re-entry by id.
        app_key=id(application)
        if app_key in _BB_FULL_LIFE_POST_RUNNING:
            return
        _BB_FULL_LIFE_POST_RUNNING.add(app_key)
        try:
            if old_post: await old_post(application)
            # Final self-healing schema pass for tables used by runtime entry points.
            try: await _bb_final_schema()
            except Exception as exc: log.warning('final runtime schema failed: %s', exc)
            try: await _bb_life_generation_schema()
            except Exception as exc: log.warning('life generation schema failed: %s',exc)
            try: await _bb_register_full_life_design()
            except Exception as exc: log.warning('life design registration failed: %s',exc)
        finally:
            _BB_FULL_LIFE_POST_RUNNING.discard(app_key)
    app.post_init=_full_life_post
    return app

# A death closes the previous marriage chapter before the player continues as
# the child.  The old marriage remains visible only in the historical events.
_BB_REINCARNATE_BEFORE_WIDOW= _bb_life_reincarnate
async def _bb_life_reincarnate(application,uid,acc,children):
    ok=await _BB_REINCARNATE_BEFORE_WIDOW(application,uid,acc,children)
    if ok:
        m=await _bb_rel_is_married(int(uid))
        if m:
            try:
                await DBX.execute('DELETE FROM bb_marriages WHERE user1_id=? AND user2_id=?',(min(int(uid),int(m['other_id'])),max(int(uid),int(m['other_id']))))
                await DBX.execute('INSERT INTO bb_life_events(user1_id,user2_id,event_type,text,created_at) VALUES(?,?,?,?,?)',(min(int(uid),int(m['other_id'])),max(int(uid),int(m['other_id'])),'widowhood','🕯️ فصل ازدواج قبلی این زندگی بسته شد؛ نسل جدید از اینجا مستقل ادامه پیدا می‌کند.',now_ts()))
            except Exception as exc:
                log.debug('previous marriage close skipped: %s',exc)
    return ok

