# =============================================================================
# ABSOLUTE FINAL PRESENTATION / PERSIAN COMMAND LAYER
# =============================================================================
# Presentation-only: does not alter music/media callbacks or playback logic.
# Every inline keyboard is normalized so a close button, when present, is the
# final row. Direct InlineKeyboardButton instances also inherit native colors.
try:
    _BB_OLD_IKM_INIT = InlineKeyboardMarkup.__init__
    def _bb_final_markup_init(self, inline_keyboard):
        rows = [list(r) for r in (inline_keyboard or [])]
        close_rows = []
        normal_rows = []
        for row in rows:
            keep=[]
            for b in row:
                label=str(getattr(b,'text','') or '').strip().lower()
                data=str(getattr(b,'callback_data','') or '').strip().lower()
                is_close = (
                    'بستن پنل' in label or label in {'بستن','✕ بستن','❌ بستن','🔒 بستن','close'}
                    or data in {'panelclose','bbx:close'}
                    or data.endswith(':close')
                )
                if is_close:
                    close_rows.append([b])
                else:
                    keep.append(b)
            if keep:
                normal_rows.append(keep)
        # Keep exactly one close row at the bottom when one exists; preserve
        # duplicate close buttons only when they have different callback data.
        if close_rows:
            seen=set(); final_close=[]
            for r in close_rows:
                b=r[0]; key=(str(getattr(b,'text','')),str(getattr(b,'callback_data','')))
                if key not in seen:
                    seen.add(key); final_close.append(b)
            if final_close:
                normal_rows.append(final_close)
        return _BB_OLD_IKM_INIT(self, normal_rows)
    InlineKeyboardMarkup.__init__ = _bb_final_markup_init
    BB_CLOSE_BUTTON_BOTTOM_LAYER = True
except Exception as _bb_markup_exc:
    BB_CLOSE_BUTTON_BOTTOM_LAYER = False
