# Short Persian user commands. These are aliases only: existing commands and
# all music logic remain untouched. The router raises ApplicationHandlerStop so
# one Persian command produces one response instead of duplicate messages.
_BB_FA_COMMAND_ALIASES = {
    'راهنما': 'help',
    'آمار': 'stats',
    'پروفایل': 'profile',
    'بیو': 'profile',
    'زندگی': 'life',
    'خانواده': 'family',
    'ماجراجویی': 'history',
    'قرعه': 'raffle',
    'قرعه کشی': 'raffle',
    'طراحی': 'design',
    'بازی': 'games',
    'الماس': 'diamond',
    'یادآوری': 'reminder',
    'فال': 'fortune',
    'دعا': 'dua',
    'قرآن': 'quran',
    'کشورها': 'countries',
    'کشور': 'countries',
    'صوت': 'voice',
    'موزیک': 'music',
    'موسیقی': 'music',
    'دانلود': 'download',
    'هوا': 'weather',
    'ارز': 'currency',
    'نظرسنجی': 'poll',
    'جرأت حقیقت': 'truth',
    'جرات حقیقت': 'truth',
    'اسم فامیل': 'games',
}

def _bb_fa_cmd_norm(t):
    return normalize(str(t or '').replace('‌',' ')).strip()

async def _bb_fa_command_router(update, context):
    msg=getattr(update,'effective_message',None)
    if not msg or not getattr(msg,'text',None):
        return False
    t=_bb_fa_cmd_norm(msg.text)
    target=_BB_FA_COMMAND_ALIASES.get(t)
    if not target:
        return False
    try:
        # Existing routers are deliberately reused. No music handler is
        # replaced; this layer only selects the same existing entry point.
        if target=='profile':
            await _bb_profile_card_command(update,context)
        elif target=='life' and '_bb_sim_text' in globals():
            await globals()['_bb_sim_text'](update,context)
        elif target=='family' and '_bb_family_command' in globals():
            await globals()['_bb_family_command'](update,context)
        elif target=='history' and '_bb_hist_text' in globals():
            await globals()['_bb_hist_text'](update,context)
        elif target=='design' and '_bb_ui_design_command' in globals():
            await globals()['_bb_ui_design_command'](update,context)
        elif target=='help' and '_bb_final_help' in globals():
            await globals()['_bb_final_help'](update,context)
        else:
            # Fall through to the existing text router for commands whose
            # feature-specific function name differs across older layers.
            handled=False
            for name in ('message_router','_bb_final_message_router_v5','_bb_v7_priority_router','_bb_strict_api_router'):
                fn=globals().get(name)
                if fn:
                    result=await fn(update,context)
                    if result:
                        handled=True
                        break
            if not handled:
                return False
        raise ApplicationHandlerStop
    except ApplicationHandlerStop:
        raise
    except Exception as exc:
        log.exception('Persian command router failed for %s: %s', t, exc)
        try:
            await msg.reply_text('⚠️ اجرای این دستور در حال حاضر ناموفق بود.')
        except Exception:
            pass
        raise ApplicationHandlerStop

# Register once, at the very end, so it wins over legacy duplicate text routers.
_BB_FINAL_PRESENTATION_BUILD_PREV = build_application
def build_application(token=None):
    app=_BB_FINAL_PRESENTATION_BUILD_PREV(token)
    app.add_handler(
        MessageHandler(filters.TEXT & ~filters.COMMAND, _bb_fa_command_router),
        group=-10000000
    )
    return app

