    t=_bb_fa_cmd_norm(msg.text)
    if not await _bb_is_bot_admin(update.effective_user.id if update.effective_user else 0):
        return False
    pairs=[
        ('تنظیم قوانین', set_rules), ('عنوان گروه', setgroup_title if 'setgroup_title' in globals() else None),
        ('بیو گروه', setgroup_bio if 'setgroup_bio' in globals() else None),
        ('عکس گروه', setgroup_photo if 'setgroup_photo' in globals() else None),
    ]
    # Do not guess function names: only invoke handlers when their exact
    # implementation is present; otherwise the normal router will handle it.
    for prefix,fn in pairs:
        if fn and t.startswith(prefix+' '):
            await fn(update,context); raise ApplicationHandlerStop
    return False

