# =============================================================================
# FINAL COMMAND AUTHORITY LAYER
# =============================================================================
# The newest registered slash-command handler is authoritative. Older duplicate
# CommandHandlers are left intact for compatibility, but this high-priority
# router invokes only the newest callback and then stops propagation.
_BB_LATEST_COMMAND_REGISTRY = {}
_BB_LATEST_COMMAND_ORDER = []


def _bb_collect_latest_commands(app):
    latest = {}
    order = []
    try:
        groups = getattr(app, 'handlers', {}) or {}
        for group in sorted(groups.keys()):
            for h in list(groups.get(group, []) or []):
                if isinstance(h, CommandHandler):
                    cmds = getattr(h, 'commands', None) or []
                    for cmd in cmds:
                        name = str(cmd).lstrip('/').lower()
                        if not name:
                            continue
                        latest[name] = h
                        if name in order:
                            order.remove(name)
                        order.append(name)
    except Exception as exc:
        log.warning('latest command registry build failed: %r', exc)
    return latest, order


def _bb_command_text_parts(text):
    raw = str(text or '').strip()
    if not raw.startswith('/'):
        return '', []
    first, *rest = raw.split(None, 1)
    token = first[1:]
    if '@' in token:
        token = token.split('@', 1)[0]
    args = rest[0].split() if rest else []
    return token.lower(), args


async def _bb_latest_slash_router(update, context):
    msg = getattr(update, 'effective_message', None)
    if not msg or not getattr(msg, 'text', None):
        return
    name, args = _bb_command_text_parts(msg.text)
    if not name:
        return
    h = _BB_LATEST_COMMAND_REGISTRY.get(name)
    if h is None:
        return
    try:
        # Keep the same argument contract expected by existing CommandHandlers.
        try:
            context.args = args
        except Exception:
            pass
        callback = getattr(h, 'callback', None)
        if callback is None:
            return
        result = callback(update, context)
        if inspect.isawaitable(result):
            await result
        raise ApplicationHandlerStop
    except ApplicationHandlerStop:
        raise
    except Exception:
        log.exception('latest slash command failed: /%s', name)
        raise ApplicationHandlerStop


