# =============================================================================
# FINAL PV START + DUPLICATE DELIVERY HOTFIX
# 2026-09-26
# - /start in PV must always produce a response for normal users and owners.
# - Telegram duplicate deliveries are blocked before every text router.
# - Persian command router is placed before all legacy text handlers so a
#   handled command cannot be answered twice by an older router.
# - Music/playback logic is not changed; this is routing/presentation only.
# =============================================================================

async def _bb_private_start_final_safe(update, context):
    user = getattr(update, 'effective_user', None)
    msg = getattr(update, 'effective_message', None)
    chat = getattr(update, 'effective_chat', None)
    if not user or not msg or not chat or getattr(chat, 'type', None) != 'private':
        return False

    # Never let an optional PV feature prevent /start from answering.
    try:
        await DBX.ensure_user(user)
    except Exception as exc:
        log.warning('PV start ensure_user failed: %r', exc)

    try:
        await _bb_premium_ux_schema()
    except Exception as exc:
        log.warning('PV start premium schema failed: %r', exc)

    try:
        await DBX.execute(
            'CREATE TABLE IF NOT EXISTS bb_optin_users('
            'user_id INTEGER PRIMARY KEY, opted_at INTEGER DEFAULT 0)'
        )
        await DBX.execute(
            'INSERT OR IGNORE INTO bb_optin_users(user_id,opted_at) VALUES(?,?)',
            (user.id, now_ts())
        )
    except Exception as exc:
        log.warning('PV start opt-in save failed: %r', exc)

    # Force-join is optional. If its DB/API check fails, do not swallow /start.
    try:
        if await _bb_pv_forcejoin_message(update, context):
            return True
    except Exception as exc:
        log.warning('PV forcejoin check failed during /start: %r', exc)

    try:
        if await _bb_is_bot_admin(user.id):
            try:
                await owner_panel_v6(update, context)
            except Exception as exc:
                log.exception('owner PV /start panel failed: %r', exc)
                await msg.reply_text('👑 پنل مالک آماده است، اما نمایش کامل پنل با خطا مواجه شد. دوباره /start بزن.')
            return True
    except Exception as exc:
        log.warning('owner check failed during PV /start: %r', exc)

    default = (
        '👋 سلام {name}! به بیل بیلک خوش اومدی. {premium}\n\n'
        'از دکمه‌های شیشه‌ای زیر برای شروع استفاده کن.'
    )
    try:
        template = await _bb_global_message_get('start_user_text', default)
        text = await _bb_render_global_template(template, user, None)
    except Exception as exc:
        log.warning('PV start template failed: %r', exc)
        text = f'👋 سلام {mention_html(user)}! به بیل بیلک خوش اومدی.\n\nاز منوی زیر شروع کن.'

    rows = [
        [btn('📚 راهنما', 'uxhelp:home')],
        [btn('🐕 هاپویی', 'u:' + str(user.id) + ':dog')],
        [btn(
            '➕ افزودن بیل بیلک به گروه',
            url=(f'https://t.me/{BOT_USERNAME}?startgroup=true' if BOT_USERNAME else 'https://t.me/')
        )],
    ]
    try:
        b = await _bb_info_button()
        if b:
            rows.append([b])
    except Exception:
        pass
    try:
        await msg.reply_text(text, parse_mode='HTML', reply_markup=keyboard(rows))
    except Exception as exc:
        log.exception('PV user /start send failed: %r', exc)
        # Last-resort plain text: /start must not end silently.
        try:
            await msg.reply_text('👋 سلام! به بیل بیلک خوش اومدی 🌷')
        except Exception:
            pass
    return True

# Replace only the private branch of start_v8; group start remains unchanged.
_BB_START_V8_BEFORE_SAFE_PV = start_v8
async def start_v8(update, context):
    chat = getattr(update, 'effective_chat', None)
    if chat and getattr(chat, 'type', None) == 'private':
        return await _bb_private_start_final_safe(update, context)
    return await _BB_START_V8_BEFORE_SAFE_PV(update, context)

# Put the Persian router before every older text handler. It already raises
# ApplicationHandlerStop for handled commands, so older routers cannot answer
# the same command a second time.
_BB_BUILD_BEFORE_EARLY_FA_ROUTER = build_application
def build_application(token: str) -> Application:
    app = _BB_BUILD_BEFORE_EARLY_FA_ROUTER(token)
    app.add_handler(
        MessageHandler(filters.TEXT & ~filters.COMMAND, _bb_fa_command_router),
        group=-10000050,
    )
    return app

# Move the duplicate-update guard ahead of all text handlers. The older guard
# remains harmless; this one catches a repeated Telegram update immediately.
_BB_BUILD_BEFORE_EARLY_DUP_GUARD = build_application
def build_application(token: str) -> Application:
    app = _BB_BUILD_BEFORE_EARLY_DUP_GUARD(token)
    app.add_handler(
        MessageHandler(filters.ALL, _bb_duplicate_update_guard),
        group=-10000060,
    )
    return app


# =============================================================================
# ABSOLUTE RUNTIME AUTHORITY — LAST DEFINITION WINS
# =============================================================================
# This block MUST remain the final executable layer. It fixes the root cause of
# the previous duplicate responses: the file contains many historical
# build_application definitions and an earlier __main__ call could start the
# bot before the last routers were installed.

async def _bb_final_single_text_authority(update, context):
    """Exactly-one-response authority for the user's sensitive text commands."""
    msg=getattr(update,'effective_message',None)
    if not msg or not getattr(msg,'text',None):
        return False
    n=normalize(str(msg.text).strip())
    # Exact profile aliases ONLY. ID/stat/date/link have separate routes.
    if n in {'پروفایل','پروفایل من','بیو من','کارت پروفایل'}:
        await _bb_profile_card_mandatory(update,context)
        return True
    if n in {'id','آیدی','ایدی','شناسه'}:
        await _bb_id_runtime_router(update,context)
        return True
    if n in {'تاریخ','تاریخ امروز','ساعت و تاریخ','تاریخ و ساعت','time','date'}:
        await _bb_absolute_date_route(update,context)
        return True
    if n in {'لینک گروه','لینک گپ','لینک گروپ','اطلاعات گروه','معرفی گروه','لینک این گروه'}:
        await _bb_absolute_group_link_route(update,context)
        return True
    return False

async def _bb_final_text_authority_handler(update, context):
    try:
        handled=await _bb_final_single_text_authority(update,context)
        if handled:
            raise ApplicationHandlerStop
    except ApplicationHandlerStop:
        raise
    except Exception as exc:
        log.exception('absolute text authority failed: %r',exc)
        raise ApplicationHandlerStop

# Rebuild latest slash-command registry at the final moment, then execute each
# slash command only through the newest registered callback.
_BB_RUNTIME_BUILD_BEFORE_ABSOLUTE_AUTHORITY = build_application
def build_application(token=None):
    app=_BB_RUNTIME_BUILD_BEFORE_ABSOLUTE_AUTHORITY(token)
    global _BB_LATEST_COMMAND_REGISTRY, _BB_LATEST_COMMAND_ORDER
    try:
        _BB_LATEST_COMMAND_REGISTRY, _BB_LATEST_COMMAND_ORDER = _bb_collect_latest_commands(app)
    except Exception:
        pass
    # Duplicate Update guard MUST be first.
    app.add_handler(MessageHandler(filters.ALL, _bb_duplicate_update_guard), group=-100000100)
    # /start is special: its final safe implementation is defined after the
    # historical CommandHandler registrations, so route it directly to the
    # current function instead of an older callback object captured earlier.
    async def _bb_final_start_authority(update, context):
        msg=getattr(update,'effective_message',None)
        text=str(getattr(msg,'text','') or '').split()[0].lower() if msg and getattr(msg,'text',None) else ''
        if not text.startswith('/start'):
            return False
        try:
            await start_v8(update,context)
        finally:
            raise ApplicationHandlerStop
    app.add_handler(MessageHandler(filters.Regex(r'^/start(?:@[^ ]+)?(?:\s.*)?$'), _bb_final_start_authority), group=-100000095)
    # Latest slash command wins. No old slash handler is allowed to answer after it.
    app.add_handler(MessageHandler(filters.COMMAND, _bb_latest_slash_router), group=-100000090)
    # Exact text authority: profile/id/date/group-link each answer once.
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, _bb_final_text_authority_handler), group=-100000080)
    return app

