# queue, downloader and playback state are not changed here.

# ---- Design catalog: scan direct InlineKeyboardButton labels too, and expose
# every registered item with pagination instead of hiding the first 100 rows.
_BB_STUDIO_SCAN_ALL_OLD = globals().get('_bb_studio_scan_everything')
async def _bb_studio_scan_everything_final():
    if _BB_STUDIO_SCAN_ALL_OLD:
        try:
            await _BB_STUDIO_SCAN_ALL_OLD()
        except Exception as exc:
            log.debug('old studio scan failed: %s', exc)
    try:
        import ast
        path=Path(__file__); tree=ast.parse(path.read_text(encoding='utf-8')); seen=set()
        for n in ast.walk(tree):
            if not isinstance(n, ast.Call):
                continue
            fname=n.func.attr if isinstance(n.func, ast.Attribute) else (n.func.id if isinstance(n.func, ast.Name) else '')
            # Direct InlineKeyboardButton / button constructors were previously
            # missed by the scanner, which is why many music buttons disappeared.
            if fname in {'InlineKeyboardButton','KeyboardButton','reply_btn','btn'} and n.args:
                a=n.args[0]
                if isinstance(a, ast.Constant) and isinstance(a.value,str):
                    k=('button',a.value)
                    if k not in seen:
                        seen.add(k); await _bb_studio_register_literal(a.value,'button',getattr(n,'lineno',0),path.name)
            if fname in {'reply_text','edit_message_text','send_message','answer','reply_photo','send_photo','reply_animation','send_animation','edit_caption','reply_voice','send_voice','reply_sticker','send_sticker'}:
                vals=[]
                for a in list(n.args)+[kw.value for kw in n.keywords if kw.arg in {'text','caption'}]:
                    if isinstance(a,ast.Constant) and isinstance(a.value,str): vals.append(a.value)
                    elif isinstance(a,ast.JoinedStr): vals.extend(x.value for x in a.values if isinstance(x,ast.Constant) and isinstance(x.value,str))
                for v in vals:
                    k=('text',v)
                    if k not in seen:
                        seen.add(k); await _bb_studio_register_literal(v,'text',getattr(n,'lineno',0),path.name)
    except Exception as exc:
        log.debug('final studio scanner failed: %s', exc)

_bb_studio_scan_everything = _bb_studio_scan_everything_final

