def _bb_render_design_template(template, update=None, user=None, chat=None, extra=None):
    text=str(template or '')
    user=user or getattr(update,'effective_user',None)
    chat=chat or getattr(update,'effective_chat',None)
    now=datetime.now()
    name=getattr(user,'full_name','کاربر') or 'کاربر'
    username=getattr(user,'username',None)
    mention=mention_html(user) if user else name
    msg=getattr(update,'effective_message',None) if update else None
    # اگر route داده اختصاصی نداده باشد، data خالی می‌ماند؛ این بهتر از این است
    # که متن یک بخش اشتباهاً داده بخش دیگری را نشان دهد.
    ex=dict(extra or {})
    data=ex.get('data','')
    section=ex.get('section','')
    vals={
        '{data}': str(data or ''), '{section}': str(section or ''),
        '{date}': now.strftime('%Y/%m/%d'), '{time}': now.strftime('%H:%M:%S'),
        '{datetime}': now.strftime('%Y/%m/%d %H:%M:%S'), '{group}': getattr(chat,'title','خصوصی') or 'خصوصی',
        '{group_name}': getattr(chat,'title','خصوصی') or 'خصوصی', '{group_id}': str(getattr(chat,'id','')), '{chat_id}': str(getattr(chat,'id','')),
        '{name}': name, '{first_name}': getattr(user,'first_name',name) or name,
        '{mention}': mention, '{username}': ('@'+username) if username else 'بدون یوزرنیم',
        '{id}': str(getattr(user,'id','')), '{user_id}': str(getattr(user,'id','')),
        '{day}': now.strftime('%A'), '{bot}': '@Bil_bilakapibot', '{bot_username}':'@Bil_bilakapibot',
    }
    # استانداردسازی aliasهای data: هر route می‌تواند فقط data را بفرستد یا
    # کلیدهای اختصاصی را هم ارسال کند. هیچ مقدار بخش دیگری حدس زده نمی‌شود.
    for key in ('data_name','data_id','data_value','data_type','data_url','data_logo',
                'country_name','country_code','country_iso2','country_iso3','country_capital','country_region','country_population','country_currency','country_flag','country_logo',
                'team_name','team_id','team_country','team_logo','team_description',
                'player_name','player_id','player_team','player_nationality','player_age','player_photo',
                'currency','currency_name','currency_code','currency_rate','currency_amount','currency_result',
                'music_title','music_artist','music_duration','music_source','music_url','music_size',
                'admin_name','admin_username','admin_title','target_name','target_mention','target_id',
                'jalali_date','gregorian_date','hijri_date'):
        vals['{'+key+'}']=str(ex.get(key,'') or '')
    # اگر data یک dict باشد، چند فیلد رایج آن را خودکار به data_* نگاشت می‌کنیم.
    if isinstance(data,dict):
        for k in ('name','id','value','type','url','logo','title','artist','duration','source','size','code','capital','region','population','rate','amount','result'):
            if ex.get('data_'+k,'')=='': vals['{data_'+k+'}']=str(data.get(k,'') or '')
    if extra:
        for k,v in extra.items():
            vals['{'+str(k)+'}']=str(v)
    for k,v in vals.items(): text=text.replace(k,str(v))
    return text

# ---- Separate commands: «ماجراجویی» is Iran history only; «هاپویی» opens the
# dog adventure.  The final high-priority route below stops all legacy aliases.
async def _bb_final_adventure_authority(update,context):
    msg=getattr(update,'effective_message',None); chat=getattr(update,'effective_chat',None)
    if not msg or not getattr(msg,'text',None): return False
    n=normalize(str(msg.text).strip())
    if n=='ماجراجویی':
        try:
            return bool(await _bb_hist_text(update,context))
        except Exception as exc:
            log.exception('history adventure authority failed: %s',exc)
            await msg.reply_text('⚠️ ماجراجویی تاریخ ایران فعلاً آماده پاسخ نیست.')
            return True
    if n in {'هاپویی','ماجراجویی هاپویی','ماجراجویی هاپو'}:
        # Reuse the existing dog panel instead of duplicating its game logic.
        try:
            return bool(await _bb_dog_panel(update,context))
        except Exception:
            # Fallback to the known dog command/panel route when the helper name
            # differs between old builds.
            try:
                h=bbx_hop(chat.id,update.effective_user.id)
                await msg.reply_text(
                    f'🐕 <b>مرکز هاپویی</b>\n\n🦴 استخوان: {int(h["points"] or 0)}\n⭐ سطح: {int(h["dog_level"] or 1)}',
                    parse_mode='HTML', reply_markup=keyboard([[btn('شروع ماجراجویی',f'dogadv:{chat.id}:{update.effective_user.id}')]])
                )
                return True
            except Exception:
                return False
    return False

# Replace the short five-chapter dog story with a long multi-stage journey.
async def _bb_dog_adventure_callback_final(update,context):
    q=getattr(update,'callback_query',None); d=str(getattr(q,'data','') or '')
    if not q or not d.startswith('dogadv:'): return False
    _,cid,uid=d.split(':'); cid=int(cid); uid=int(uid)
    if q.from_user.id!=uid:
        await q.answer('این ماجراجویی برای تو نیست.',show_alert=True); return True
    row=await DBX.one('SELECT * FROM bbx_dog_adventure WHERE chat_id=? AND user_id=?',(cid,uid))
    if not row:
        await q.answer('اول یک سگ بخر.',show_alert=True); return True
    chapter=int(row['chapter'] or 0)+1
    stories=[
        ('دروازه جنگل مه‌آلود','هاپو کنار درختان خیس ردپاهایی تازه پیدا می‌کند. صدای پرنده‌ها آرام‌آرام قطع می‌شود و یک مسیر باریک میان بوته‌ها ظاهر می‌شود. تو باید تصمیم بگیری با احتیاط جلو بروی یا مسیر امن کنار رودخانه را انتخاب کنی.'),
        ('رودخانه خروشان','پل چوبی قدیمی نصفه خراب شده است. هاپو یک راه سنگی پایین رودخانه پیدا می‌کند و با بو کشیدن مسیر امن را تشخیص می‌دهد. چند دقیقه بعد، یک کیف سفر قدیمی کنار آب پیدا می‌کنید که داخلش نقشه‌ای ناقص از منطقه است.'),
        ('دره سنگی','نقشه شما را به دره‌ای پر از سنگ‌های بزرگ می‌برد. باد شدید می‌وزد و هاپو باید از مسیر باریک عبور کند. در انتهای دره، نشانه‌ای روی صخره پیدا می‌کنید که می‌گوید مسیر اصلی هنوز چند کیلومتر جلوتر است.'),
        ('کلبه متروکه','شب نزدیک شده و یک کلبه قدیمی برای استراحت پیدا می‌شود. داخل کلبه چراغی خاموش، یک صندوق قفل‌شده و چند یادداشت قدیمی وجود دارد. هاپو بوی یک راه مخفی را حس می‌کند و پشت قفسه چوبی ورودی تونل را پیدا می‌کنید.'),
        ('تونل زیرزمینی','تونل به غاری بزرگ می‌رسد. صدای آب از دور شنیده می‌شود و روی دیوارها علامت‌های قدیمی دیده می‌شود. هاپو مسیر درست را پیدا می‌کند و شما یک صندوق کوچک حاوی استخوان‌های کمیاب و یک قطب‌نمای سالم پیدا می‌کنید.'),
        ('کوهستان مه‌آلود','صبح روز بعد مسیر به ارتفاعات می‌رسد. مه شدید دید را کم کرده، اما قطب‌نما هنوز جهت درست را نشان می‌دهد. هاپو جلوتر می‌رود و چند دقیقه بعد منظره‌ای وسیع از دره و یک برج سنگی دوردست دیده می‌شود.'),
        ('برج سنگی','برج از دور متروکه به نظر می‌رسد اما داخل آن ردپای تازه وجود دارد. شما با احتیاط وارد می‌شوید و روی طبقه آخر پرچم قدیمی و یک نقشه بزرگ پیدا می‌کنید که مقصد بعدی را نشان می‌دهد: قلعه شمالی.'),
        ('دشت بادخیز','مسیر قلعه از دشتی باز عبور می‌کند. باد شدید است و هاپو انرژی زیادی مصرف کرده. با استراحت کوتاه و پیدا کردن آب تازه، انرژی برمی‌گردد و یک مسیر میان‌بر در نقشه پیدا می‌کنید.'),
        ('پل سنگی','یک پل سنگی قدیمی بین دو صخره قرار دارد. بخشی از پل ترک خورده ولی مسیر قابل عبور است. هاپو با دقت جلو می‌رود و در طرف دیگر یک نشان فلزی پیدا می‌کند که کلید ورودی قلعه را کامل می‌کند.'),
        ('قلعه شمالی','دروازه قلعه با همان نشان باز می‌شود. حیاط بزرگ خالی است و اتاق‌های زیادی دارد. در سالن اصلی یک نقشه گنج و چند صندوق کوچک پیدا می‌کنید، اما نشانه‌ها می‌گویند جایزه اصلی هنوز در بخش زیرین قلعه است.'),
        ('راهروی مخفی','پشت یک دیوار سنگی راهرویی پنهان می‌شود. مسیر طولانی است و چند انتخاب اشتباه می‌تواند شما را دور کند. هاپو با دنبال کردن بوی خاک تازه راه درست را پیدا می‌کند و به یک اتاق گرد زیر قلعه می‌رسید.'),
        ('اتاق گنج','وسط اتاق یک صندوق بزرگ قرار دارد. داخل آن استخوان‌های طلایی تزئینی، یک نشان افتخار و دفترچه خاطرات یک ماجراجوی قدیمی است. در دفترچه نوشته شده که پایان سفر واقعی جایی است که از آن شروع کرده‌اید.'),
        ('بازگشت به جنگل','با نقشه جدید مسیر بازگشت را پیدا می‌کنید. هاپو حالا باتجربه‌تر شده و هر نشانه‌ای را سریع تشخیص می‌دهد. چند روز سفر آرام می‌گذرد تا دوباره به همان دروازه جنگل مه‌آلود می‌رسید.'),
        ('راز ردپاها','ردپاهایی که در فصل اول دیده بودید، متعلق به یک خانواده ماجراجو بوده است. دفترچه قدیمی مسیر آنها را کامل می‌کند و شما یک مأموریت تازه برای فصل بعد پیدا می‌کنید.'),
        ('پایان فصل اول','تمام مسیر فصل اول کامل شد. هاپو تجربه زیادی به دست آورده، وسایل سفر بهتر شده و صندوق پاداش نهایی آماده است. ماجراجویی بعدی می‌تواند با یک مسیر تازه ادامه پیدا کند.'),
    ]
    idx=min(chapter,len(stories)); title,story=stories[idx-1]
    reward=20+chapter*8
    if chapter>=len(stories):
        await DBX.execute('UPDATE bbx_hop SET bones=bones+?,points=points+? WHERE chat_id=? AND user_id=?',(reward,reward,cid,uid)); chapter=0
    await DBX.execute('UPDATE bbx_dog_adventure SET chapter=?,updated_at=? WHERE chat_id=? AND user_id=?',(chapter,int(time.time()),cid,uid))
    text=_bb_render_design_template(
        '🐾 <b>ماجراجویی هاپویی</b>\n\n📍 فصل {chapter}: <b>{title}</b>\n\n{story}\n\n🦴 پاداش این مرحله: <b>+{reward}</b> استخوان\n⭐ تجربه مسیر: <b>{chapter}</b>\n\n⏳ فصل بعدی را می‌توانی ادامه بدهی.',
        update, extra={'chapter':idx,'title':title,'story':story,'reward':reward}
    )
    await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([
        [btn('🐾 ادامه ماجراجویی',f'dogadv:{cid}:{uid}')],
        [btn('🦴 ارتقای هاپو',f'dogup:{cid}:{uid}')],
        [btn('🔙 بستن',user_cb(uid,'home'))]
    ]))
    return True
_bb_dog_adventure_callback = _bb_dog_adventure_callback_final

# ---- Whisper: always use the real bot username, with a hard fallback. ----
async def _bb_whisper_bot_url(context):
    username=''
    try: username=str(await _bb_runtime_bot_username(context.bot) or '').strip().lstrip('@')
    except Exception: pass
    username=username or str(globals().get('BOT_USERNAME') or '').strip().lstrip('@')
    username=username or 'Bil_bilakapibot'
    return f'https://t.me/{username}', f'@{username}'

async def _bb_yavashki_alias_final(update,context):
    msg=update.effective_message; chat=update.effective_chat; user=update.effective_user
    if not msg or not user or not chat or normalize(msg.text or '') not in {'یواشکی','نجوا'}: return False
    if chat.type=='private':
        await msg.reply_text('💬 نجوا را داخل گروه، با ریپلای روی گیرنده شروع کن.'); return True
    if not msg.reply_to_message or not msg.reply_to_message.from_user:
        await msg.reply_text('💬 روی پیام گیرنده ریپلای کن و «نجوا» را بفرست.'); return True
    target=msg.reply_to_message.from_user
    if target.is_bot:
        await msg.reply_text('⚠️ برای ربات نمی‌توان نجوا فرستاد.'); return True
    token=os.urandom(8).hex(); BBX_WHISPER_WAIT[user.id]=(token,target.id,chat.id,time.time()+300)
    bot_url,bot_mention=await _bb_whisper_bot_url(context)
    kb=InlineKeyboardMarkup([[InlineKeyboardButton('💬 ورود به ربات و ارسال نجوا',url=bot_url)]])
    try:
        await context.bot.send_message(user.id,
            f'💬 <b>نجوا آماده است</b>\n\nبرای ارسال پیام، وارد {bot_mention} شو و پیام را همان‌جا بفرست.\n⏳ اعتبار این نجوا: ۵ دقیقه.',
            parse_mode='HTML', reply_markup=kb)
        await msg.reply_text(f'💬 نجوا آماده شد. وارد {bot_mention} شو و پیام را در PV بفرست.',parse_mode='HTML',reply_markup=kb)
    except Exception:
        BBX_WHISPER_WAIT.pop(user.id,None)
        await msg.reply_text(f'💬 ابتدا {bot_mention} را Start کن، سپس دوباره «نجوا» را بزن.',parse_mode='HTML',reply_markup=kb)
    return True

# ---- Automatic country/player/team catalog synchronization.  Countries need
# no key.  Football catalogs use the already configured API credentials when
# available; the owner only manages the logo afterward.
async def _bb_auto_sync_countries_all():
    try:
        await _bb_country_schema()
        import urllib.parse as _up
        url='https://restcountries.com/v3.1/all?fields=name,cca2,cca3,ccn3,capital,region,subregion,population,area,languages,currencies,idd,timezones,borders,flags,demonyms,continents,flag'
        data=await _bb_http_json(url,timeout=25)
        if not isinstance(data,list): return 0
        count=0
        for x in data:
            n=x.get('name') or {}; name=(n.get('common') if isinstance(n,dict) else '') or ''
            if not name: continue
            flags=x.get('flags') or {}; langs=x.get('languages') or {}; curr=x.get('currencies') or {}; caps=x.get('capital') or []
            dem=x.get('demonyms') or {}; demtxt=''
            if isinstance(dem,dict):
                vals=[]
                for z in dem.values():
                    if isinstance(z,dict): vals.extend([z.get('m'),z.get('f')])
                demtxt=', '.join(str(v) for v in vals if v)
            vals=[
                name, (n.get('official') if isinstance(n,dict) else ''), x.get('cca2',''),x.get('cca3',''),x.get('ccn3',''),x.get('fifa',''),x.get('cioc',''),
                ', '.join(map(str,caps)) if isinstance(caps,list) else str(caps), x.get('region',''),x.get('subregion',''),', '.join(map(str,x.get('continents') or [])),
                x.get('population',''),x.get('area',''), ', '.join(str(v.get('name') if isinstance(v,dict) else v) for v in langs.values()),
                ', '.join(str((v.get('name') or '')+' ('+(v.get('symbol') or '')+')').strip() for v in curr.values()),
                str((x.get('idd') or {}).get('root','')) if isinstance(x.get('idd'),dict) else '', ', '.join(map(str,x.get('timezones') or [])), ', '.join(map(str,x.get('borders') or [])),
                x.get('flag',''),flags.get('png',''),flags.get('svg',''),demtxt,'football,basketball,tennis,volleyball,handball,baseball,cricket,rugby',
                'https://restcountries.com/v3.1/name/'+_up.quote(name),str(x),int(time.time())]
            await DBX.execute('INSERT OR REPLACE INTO bb_country_data(name,official_name,iso2,iso3,numeric_code,fifa_code,ioc_code,capital,region,subregion,continent,population,area,languages,currencies,calling_codes,timezones,borders,flag_emoji,flag_url,flag_svg,demonym,sports,source_url,raw_json,updated_at) VALUES('+','.join('?' for _ in vals)+')',tuple(vals))
            count+=1
        return count
    except Exception as exc:
        log.debug('country auto sync skipped: %s',exc); return 0

async def _bb_auto_sync_football_catalogs():
    # API-Sports/API-Football is optional. If the owner has configured the
    # player endpoint/key, populate teams and players automatically.
    try:
        base=(await _bb_api_get('PLAYER_API_URL','')).strip().rstrip('/')
        key=(await _bb_api_get('PLAYER_API_KEY','')).strip() or (await _bb_api_get('APISPORTS_API_KEY','')).strip()
        host=(await _bb_api_get('PLAYER_API_HOST','')).strip()
        if not base or not key: return 0
        import urllib.parse as _up
        headers={'User-Agent':'Bilbilak/6.0','x-apisports-key':key}
        if host: headers['x-rapidapi-host']=host
        # Broad set of major league IDs.  The API itself decides what exists.
        leagues=[39,140,135,78,61,2,3,94,88,203,71,72,253,262,307,98,1,13,15,16,17,18,20,21,22,23,24,25]
        seasons=[2025,2024]
        total=0
        for league in leagues:
            for season in seasons[:1]:
                try:
                    data=await _bb_http_json(base+'/teams?'+_up.urlencode({'league':league,'season':season}),headers=headers,timeout=15)
                    for item in (data.get('response') or []):
                        team=item.get('team') or item
                        name=str(team.get('name') or '').strip()
                        if not name: continue
                        country=str((item.get('team') or {}).get('country') or '')
                        logo=str(team.get('logo') or '')
                        await DBX.execute('INSERT OR IGNORE INTO bb_team_data(name,description,trophies,emoji_id,logo_url) VALUES(?,?,?,?,?)',(name,country,'','',''+logo))
                        try: await DBX.execute('UPDATE bb_team_data SET description=COALESCE(NULLIF(?,\'\'),description),logo_url=COALESCE(NULLIF(?,\'\'),logo_url) WHERE name=?',(country,logo,name))
                        except Exception: pass
                        total+=1
                except Exception: continue
        # A bounded first pass over players prevents startup/API quota abuse;
        # the design panel has a full resync button for repeated passes.
        for league in leagues[:12]:
            try:
                data=await _bb_http_json(base+'/players?'+_up.urlencode({'league':league,'season':2025,'page':1}),headers=headers,timeout=15)
                for item in (data.get('response') or []):
                    p=item.get('player') or {}; stats=(item.get('statistics') or [{}])[0] or {}; team=stats.get('team') or {}
                    name=str(p.get('name') or '').strip()
                    if not name: continue
                    await DBX.execute('INSERT OR IGNORE INTO bb_player_data(name,nationality,current_team,prime_team,prime_year,age,children,world_cups,national_trophies,club_trophies,spouse,emoji_id,photo_url,source_url,player_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',(
                        name,str(p.get('nationality') or ''),str(team.get('name') or ''),'','',''+str(p.get('age') or ''),'','','','','','',str(p.get('photo') or ''),base,str(p.get('id') or '')
                    ))
                    total+=1
            except Exception: continue
        return total
    except Exception as exc:
        log.debug('football catalog auto sync skipped: %s',exc); return 0

async def _bb_catalog_schema_final():
    await _bb_studio_v2_schema(); await _bb_country_schema(); await _bb_player_remote_schema()
    try: await DBX.execute("ALTER TABLE bb_team_data ADD COLUMN logo_url TEXT DEFAULT ''")
    except Exception: pass
    try: await DBX.execute("ALTER TABLE bb_country_data ADD COLUMN logo_url TEXT DEFAULT ''")
    except Exception: pass

async def _bb_catalog_sync_background():
    try:
        await _bb_catalog_schema_final()
        await _bb_seed_players(); await _bb_seed_teams()
        await _bb_auto_sync_countries_all()
        await _bb_auto_sync_football_catalogs()
    except Exception as exc:
        log.debug('catalog background sync failed: %s',exc)

