async def _bb_catalog_list_panel(q, kind, page=0):
    await _bb_catalog_schema_final()
    kind=str(kind); page=max(0,int(page)); per=18; table={'players':'bb_player_data','teams':'bb_team_data','countries':'bb_country_data'}[kind]
    total_row=await DBX.one(f'SELECT COUNT(*) c FROM {table}'); total=int(total_row['c'] or 0) if total_row else 0
