    nav=[]
    if page>0: nav.append(btn('⬅️ قبلی',f'sv2:catalog:{kind}:{page-1}'))
    if (page+1)*per<total: nav.append(btn('بعدی ➡️',f'sv2:catalog:{kind}:{page+1}'))
