# ---- Final group-management authority. These routes call the existing real
# Telegram API implementations and stop the legacy routers from answering too.
async def _bb_group_management_authority(update,context):
    msg=getattr(update,'effective_message',None); chat=getattr(update,'effective_chat',None)
    if not msg or not chat or chat.type=='private' or not getattr(msg,'text',None): return False
    n=normalize(str(msg.text).strip())
    if n in {'اطلاعات گروه','گروه'}:
        try:
            c=await context.bot.get_chat(chat.id); admins=await context.bot.get_chat_administrators(chat.id); me=await context.bot.get_chat_member(chat.id,context.bot.id)
            link=''
            try: link=(await context.bot.create_chat_invite_link(chat.id,creates_join_request=False)).invite_link
            except Exception: pass
            owner=next((a.user for a in admins if a.status==ChatMemberStatus.OWNER),None)
            text=(f'🏠 <b>اطلاعات واقعی گروه</b>\n\n📛 نام: <b>{safe_text(c.title or "",120)}</b>\n'
                  f'🆔 شناسه: <code>{chat.id}</code>\n👥 تعداد ادمین واقعی: <b>{len(admins)}</b>\n'
                  f'🤖 مقام ربات: <b>{safe_text(str(me.status),40)}</b>\n'
                  f'👑 مالک واقعی: {mention_html(owner) if owner else "نامشخص"}\n'
                  f'🔗 لینک: {safe_text(link or "ساخته نشد",300)}')
            await msg.reply_text(text,parse_mode='HTML'); return True
        except Exception:
            await msg.reply_text('❌ اطلاعات واقعی گروه دریافت نشد؛ دسترسی ربات را بررسی کن.'); return True
    if n in {'ادمین','ادمین ها','ادمین‌ها','لیست ادمین','لیست ادمین ها','لیست ادمین‌ها'}:
        try:
            admins=await context.bot.get_chat_administrators(chat.id)
            lines=[]
            for a in admins:
                role='👑 مالک' if a.status==ChatMemberStatus.OWNER else '🛡 ادمین'
                title=getattr(a,'custom_title','') or ''
                lines.append(f'{role} — {mention_html(a.user)}'+(f' — 🏷 {safe_text(title,60)}' if title else ''))
            await msg.reply_text('👮 <b>ادمین‌های واقعی گروه</b>\n\n'+'\n'.join(lines),parse_mode='HTML'); return True
        except Exception:
            await msg.reply_text('❌ دریافت ادمین‌های واقعی انجام نشد.'); return True
    if n.startswith('تغییر نام گروه '):
        context.args=msg.text.split()[3:]; await set_group_title(update,context); return True
    if n.startswith('تغییر بیو گروه '):
        context.args=msg.text.split()[3:]; await set_group_bio(update,context); return True
    if n=='تغییر عکس گروه': await set_group_photo(update,context); return True
    if re.match(r'^(?:لقب|عنوان)\s+',n):
        return await _bb_final_moderation_text(update,context)
    if n in {'رفع سکوت','رفع سکوت کاربر','آزاد','آزاد کردن'}:
        if not await is_admin(update): await msg.reply_text('⛔ فقط ادمین واقعی.'); return True
        target=getattr(msg.reply_to_message,'from_user',None) if getattr(msg,'reply_to_message',None) else None
        if not target:
            await msg.reply_text('👤 روی پیام کاربر ریپلای کن و «رفع سکوت» بفرست.'); return True
        try:
            await chat.restrict_member(target.id, ChatPermissions(
                can_send_messages=True, can_send_audios=True, can_send_documents=True,
                can_send_photos=True, can_send_videos=True, can_send_video_notes=True,
                can_send_voice_notes=True, can_send_polls=True, can_send_other_messages=True,
                can_add_web_page_previews=True, can_change_info=False, can_invite_users=True,
                can_pin_messages=False
            ))
            await msg.reply_text(f'🔊 {mention_html(target)} از سکوت خارج شد.',parse_mode='HTML')
        except Exception:
            await msg.reply_text('⚠️ رفع سکوت انجام نشد؛ دسترسی محدودسازی اعضا را بررسی کن.')
        return True
    if n.startswith(('سکوت','خفه','هیس','بن','اخراج','آنبن','رفع بن')):
        if n in {'آنبن','رفع بن'}: return await _bb_final_moderation_text(update,context)
        await bbx_moderation(update,context,n); return True
    return False

# ---- VIP authority: one path for activation/charge/status, no duplicate text.
async def _bb_vip_authority(update,context):
    msg=getattr(update,'effective_message',None); chat=getattr(update,'effective_chat',None); user=getattr(update,'effective_user',None)
    if not msg or not chat or not user or not getattr(msg,'text',None): return False
    n=normalize(str(msg.text).strip())
    if n.startswith('شارژ vip '):
        parts=n.split();
        if len(parts)==3 and parts[2].isdigit(): await vip_charge_text(update,context,int(parts[2])); return True
    if n in {'vip','💎 vip','وی آی پی','وی‌آی‌پی','پنل vip'}:
        if chat.type=='private':
            await msg.reply_text('💎 پنل VIP را داخل گروه باز کن.'); return True
        try:
            if not await local_admin(update,user.id): await msg.reply_text('⛔ فقط ادمین واقعی گروه.'); return True
            await ensure_vip_pro_row(chat.id); await msg.reply_text(await vip_pro_status(chat.id),parse_mode='HTML',reply_markup=await vip_pro_keyboard(user.id,chat.id)); return True
        except Exception:
            await msg.reply_text(await vip_status(chat.id) if 'vip_status' in globals() else '💎 وضعیت VIP قابل دریافت نیست.'); return True
    return False

