# ---- Exact final text authority for adventures, whisper, management and VIP.
_BB_FINAL_MESSAGE_AUTH_OLD = _bb_final_text_authority_handler
async def _bb_final_text_authority_handler_v2(update,context):
    try:
        for fn in (_bb_final_adventure_authority,_bb_yavashki_alias_final,_bb_group_management_authority,_bb_vip_authority):
            try:
                if await fn(update,context): raise ApplicationHandlerStop
            except ApplicationHandlerStop: raise
            except Exception as exc: log.debug('authority route %s failed: %s',getattr(fn,'__name__','?'),exc)
        await _BB_FINAL_MESSAGE_AUTH_OLD(update,context)
    except ApplicationHandlerStop:
        raise
    except Exception as exc:
        log.exception('final authority v2 failed: %s',exc); raise ApplicationHandlerStop
_bb_final_text_authority_handler = _bb_final_text_authority_handler_v2

# ---- Final builder. It deliberately leaves all music handlers intact; these
# additions only sit in front of text/callback presentation/control routes.
_BB_BUILD_BEFORE_FINAL_CATALOG_LAYER = build_application
def build_application(token=None):
    app=_BB_BUILD_BEFORE_FINAL_CATALOG_LAYER(token)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_final_text_authority_handler),group=-100000200)
    app.add_handler(CallbackQueryHandler(_bb_studio_v2_callback_final,pattern=r'^sv2:'),group=-100000199)
    app.add_handler(MessageHandler(filters.ALL,_bb_studio_v2_message_final),group=-100000198)
    return app

# ---- Final post-init: schema first, then non-blocking catalog synchronization.
_BB_POST_INIT_BEFORE_FINAL_CATALOG = post_init
async def post_init(application):
    try: await _bb_catalog_schema_final()
    except Exception as exc: log.debug('final catalog schema: %s',exc)
    try: await _bb_register_final_design_catalog()
    except Exception as exc: log.debug('final design catalog: %s',exc)
    try: asyncio.create_task(_bb_catalog_sync_background())
    except Exception: pass
    if _BB_POST_INIT_BEFORE_FINAL_CATALOG:
        try: await _BB_POST_INIT_BEFORE_FINAL_CATALOG(application)
        except Exception as exc: log.debug('previous post_init failed after final schema: %s',exc)




