async def _bb_studio_v2_callback_category_final(update,context):
    q=getattr(update,'callback_query',None); d=str(getattr(q,'data','') or '') if q else ''
    if d.startswith('sv2:cat:'):
        if not await _bb_owner_gate(update):
            await q.answer('⛔ فقط مالک.',show_alert=True); return True
        await q.answer(); await _bb_studio_scan_everything_final()
        parts=d.split(':'); cat=parts[2]; page=int(parts[3]) if len(parts)>3 else 0
        per=10; total_row=await DBX.one("SELECT COUNT(*) c FROM bb_ui_texts WHERE category=?",(cat,)); total=int(total_row['c'] or 0) if total_row else 0
        rows=await DBX.execute('SELECT key,original,custom,kind FROM bb_ui_texts WHERE category=? ORDER BY CASE WHEN source_line>0 THEN source_line ELSE 999999 END, original LIMIT ? OFFSET ?', (cat,per,page*per),fetch=True)
        kb=[]
        for r in rows:
            prefix='🔘' if r['kind']=='button' else '📝'; shown=str(r['custom'] or r['original']).replace('\n',' ')
            kb.append([btn(prefix+' '+shown[:48],f'sv2:edit:{r["key"]}')])
        nav=[]
        if page>0: nav.append(btn('⬅️ قبلی',f'sv2:cat:{cat}:{page-1}'))
        if (page+1)*per<total: nav.append(btn('بعدی ➡️',f'sv2:cat:{cat}:{page+1}'))
        if nav: kb.append(nav)
        kb += [[btn('🔄 اسکن دوباره','sv2:rescan')],[btn('🔙 طراحی','sv2:home')]]
        title=_BB_UI_CATEGORIES.get(cat,cat)
        await q.edit_message_text(f'🎨 <b>{safe_text(title,100)}</b>\n\nمتن‌ها و دکمه‌های این بخش با هم نمایش داده می‌شوند.\n{page*per+1 if total else 0} تا {min((page+1)*per,total)} از {total}',parse_mode='HTML',reply_markup=keyboard(kb)); return True
    return await _BB_STUDIO_CB_CATEGORY_OLD_FINAL(update,context)
_bb_studio_v2_callback = _bb_studio_v2_callback_category_final

# Final message wrapper gets a dedicated photo/logo state before the older owner
# text editor, so logo uploads never get interpreted as ordinary design text.
_BB_STUDIO_MSG_CATEGORY_OLD_FINAL = _bb_studio_v2_message
async def _bb_studio_v2_message_catalog_final(update,context):
    if await _bb_owner_gate(update):
        uid=int(getattr(getattr(update,'effective_user',None),'id',0) or 0)
        pending=_BB_CATALOG_PENDING.get(uid)
        msg=getattr(update,'effective_message',None)
        if pending and msg:
            kind,name=pending
            if getattr(msg,'photo',None):
                fid=msg.photo[-1].file_id; await _bb_catalog_schema_final()
                if kind=='players': await DBX.execute('UPDATE bb_player_data SET photo_url=? WHERE name=?',(fid,name))
                elif kind=='teams': await DBX.execute('UPDATE bb_team_data SET logo_url=? WHERE name=?',(fid,name))
                else: await DBX.execute('UPDATE bb_country_data SET logo_url=? WHERE name=?',(fid,name))
                _BB_CATALOG_PENDING.pop(uid,None); await msg.reply_text('✅ لوگو ثبت شد و فقط لوگوی همین مورد تغییر کرد.'); return True
            if getattr(msg,'text',None):
                raw=str(msg.text).strip()
                if raw.startswith(('http://','https://')):
                    await _bb_catalog_schema_final()
                    if kind=='players': await DBX.execute('UPDATE bb_player_data SET photo_url=? WHERE name=?',(raw,name))
                    elif kind=='teams': await DBX.execute('UPDATE bb_team_data SET logo_url=? WHERE name=?',(raw,name))
                    else: await DBX.execute('UPDATE bb_country_data SET logo_url=? WHERE name=?',(raw,name))
                    _BB_CATALOG_PENDING.pop(uid,None); await msg.reply_text('✅ لینک لوگو ذخیره شد.'); return True
    return await _BB_STUDIO_MSG_CATEGORY_OLD_FINAL(update,context)
_bb_studio_v2_message = _bb_studio_v2_message_catalog_final

# Schedule the catalog sync from the final builder as well. This avoids relying
# on which historical post_init object an earlier builder captured.
_BB_BUILD_BEFORE_SCHEDULED_CATALOG = build_application
def build_application(token=None):
    app=_BB_BUILD_BEFORE_SCHEDULED_CATALOG(token)
    try:
        jq=getattr(app,'job_queue',None)
        if jq:
            async def _catalog_job(context):
                await _bb_catalog_sync_background()
            jq.run_once(_catalog_job,when=3,name='bb-final-catalog-sync')
    except Exception as exc:
        log.debug('catalog job scheduling skipped: %s',exc)
    return app




