# =============================================================================
# FINAL ADMIN DESIGN + NIGHTLY OWNER BACKUP
# =============================================================================
# Registered bot admins (bot_admins) have the same full text/button designer
# access as the primary owner. Group admins retain their group-only editors.
async def _bb_nightly_owner_backup_job(context):
    """Create a consistent SQLite snapshot and send it to the primary owner at midnight."""
    try:
        owner=int(OWNER_ID_DEFAULT or 0)
        if owner <= 0:
            return
        # SQLite online backup API avoids copying a half-written DB/WAL file.
        stamp=datetime.now().strftime('%Y%m%d_%H%M%S')
        out=Path(tempfile.gettempdir()) / f'bilbilak_backup_{stamp}.sqlite3'
        src=sqlite3.connect(DB_PATH, check_same_thread=False)
        try:
            dst=sqlite3.connect(str(out), check_same_thread=False)
            try:
                src.backup(dst)
            finally:
                dst.close()
        finally:
            src.close()
        with open(out,'rb') as fh:
            await context.bot.send_document(
                chat_id=owner,
                document=fh,
                caption=f'💾 <b>بکاپ خودکار شبانه بیل‌بیلک</b>\n📅 {stamp}\n🕛 ساعت ۰۰:۰۰ به وقت تهران',
                parse_mode='HTML',
            )
        try: out.unlink()
        except Exception: pass
    except Exception as exc:
        log.exception('nightly owner backup failed: %r', exc)
        try:
            await context.bot.send_message(owner, f'⚠️ بکاپ خودکار شبانه انجام نشد.\nجزئیات: {type(exc).__name__}')
        except Exception:
            pass

async def _bb_install_final_owner_backup(application):
    jq=getattr(application,'job_queue',None)
    if jq is None:
        log.warning('job queue unavailable; nightly owner backup not installed')
        return
    for job in jq.get_jobs_by_name('bilbilak-owner-nightly-backup'):
        try: job.schedule_removal()
        except Exception: pass
    try:
        from zoneinfo import ZoneInfo
        at=datetime.now(ZoneInfo('Asia/Tehran')).replace(hour=0,minute=0,second=0,microsecond=0).timetz()
    except Exception:
        from datetime import time as _dt_time
        at=_dt_time(0,0,0)
    jq.run_daily(_bb_nightly_owner_backup_job,time=at,name='bilbilak-owner-nightly-backup')

_BB_BUILD_BEFORE_FINAL_OWNER_BACKUP = build_application
def build_application(token=None):
    app=_BB_BUILD_BEFORE_FINAL_OWNER_BACKUP(token)
    try:
        # The exhaustive designer handlers are already installed earlier in the
        # build chain. Do NOT register them a second time: duplicate callback
        # handlers would cause duplicate designer replies.
        jq=getattr(app,'job_queue',None)
        if jq:
            for job in jq.get_jobs_by_name('bilbilak-owner-nightly-backup'):
                try: job.schedule_removal()
                except Exception: pass
            try:
                from zoneinfo import ZoneInfo
                at=datetime.now(ZoneInfo('Asia/Tehran')).replace(hour=0,minute=0,second=0,microsecond=0).timetz()
            except Exception:
                from datetime import time as _dt_time
                at=_dt_time(0,0,0)
            jq.run_daily(_bb_nightly_owner_backup_job,time=at,name='bilbilak-owner-nightly-backup')
    except Exception as exc:
        log.warning('final owner backup installation failed: %r', exc)
    return app


