def _bb_group_setup_admin_update(q):
    return type('U', (), {
        'effective_user': q.from_user,
        'effective_chat': q.message.chat,
        'effective_message': q.message,
    })()


def _bb_group_setup_normalize_target(raw):
    raw=str(raw or '').strip().strip('<>')
    raw=raw.rstrip('/')
    # Public t.me links can be converted to @username so Telegram API can
    # resolve the destination and the existing enforcement code can store it.
    m=re.match(r'^(?:https?://)?(?:www\.)?t\.me/([A-Za-z0-9_]{4,})/?$',raw,re.I)
    if m:
        return '@'+m.group(1)
    if raw.startswith('https://t.me/') or raw.startswith('http://t.me/'):
        return raw
    return raw

async def _bb_group_setup_show(q, kind):
    uid=q.from_user.id
    if not await is_admin(_bb_group_setup_admin_update(q),uid):
        await q.answer('⛔ فقط ادمین واقعی گروه.',show_alert=True); return True
    if kind=='forcejoin':
        c=await DBX.get_chat(q.message.chat.id)
        target=(c['forced_channel'] if c else '') or 'تنظیم نشده'
        text=(
            '🔐 <b>تنظیم ساده جوین اجباری</b>\n\n'
            f'مقصد فعلی: <code>{safe_text(target,180)}</code>\n\n'
            '1️⃣ اول لینک یا @username مقصد را بفرست.\n'
            '2️⃣ ربات مقصد را بررسی می‌کند. اگر ادمین باشد، مرحله بعد باز می‌شود.\n'
            '3️⃣ اگر ادمین نباشد، ربات می‌گوید ربات را ادمین کن و بعد دوباره از همین دکمه شروع کن.\n'
            '4️⃣ بعد می‌توانی متن اختصاصی بدهی یا «پیش‌فرض» را بزنی.\n\n'
            + _BB_GROUP_VARIABLES_TEXT
        )
        await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([
            [btn('🔗 ثبت/تغییر مقصد','gsetup:force:target')],
            [btn('🧩 متغیرها','gsetup:vars:force')],
            [btn('🔙 مدیریت','gsetup:back')]
        ])); return True
    label='خوش‌آمدگویی' if kind=='welcome' else 'خداحافظی'
    text=(
        f'👋 <b>تنظیم {label}</b>\n\n'
        'فقط متن پیام را از شما می‌خواهم.\n'
        'اگر نمی‌خواهی متن را شخصی‌سازی کنی، «پیش‌فرض» را بزن تا متن استاندارد ذخیره و فعال شود.\n\n'
        + _BB_GROUP_VARIABLES_TEXT
    )
    await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([
        [btn('📝 تنظیم متن','gsetup:'+kind+':text'),btn('✨ استفاده از پیش‌فرض','gsetup:'+kind+':default')],
        [btn('🧩 متغیرها','gsetup:vars:'+kind)],
        [btn('🔙 مدیریت','gsetup:back')]
    ])); return True

async def _bb_group_setup_callback(update, context):
    q=getattr(update,'callback_query',None)
    d=str(getattr(q,'data','') or '') if q else ''
    if not d.startswith('gsetup:'): return False
    uid=q.from_user.id
    if not await is_admin(_bb_group_setup_admin_update(q),uid):
        await q.answer('⛔ فقط ادمین واقعی گروه.',show_alert=True); return True
    parts=d.split(':')
    action=parts[1] if len(parts)>1 else ''
    arg=parts[2] if len(parts)>2 else ''
    if action=='back':
        _BB_GROUP_SETUP_PENDING.pop(uid,None)
        await q.edit_message_text('🛡 <b>پنل مدیریت بیل بیلک</b>\n\nهر گزینه واقعاً به تنظیمات گروه وصل است. 🐾',parse_mode='HTML',reply_markup=management_keyboard_v4(uid))
        return True
    if action=='vars':
        title={'welcome':'خوش‌آمد','goodbye':'خداحافظی','force':'جوین اجباری'}.get(arg,'گروه')
        await q.edit_message_text(f'🧩 <b>متغیرهای {title}</b>\n\n'+_BB_GROUP_VARIABLES_TEXT,parse_mode='HTML',reply_markup=keyboard([[btn('🔙 برگشت','gsetup:'+('forcejoin' if arg=='force' else arg))]])); return True
    if action=='forcejoin':
        return await _bb_group_setup_show(q,'forcejoin')
    if action=='welcome' and not arg:
        return await _bb_group_setup_show(q,'welcome')
    if action=='goodbye' and not arg:
        return await _bb_group_setup_show(q,'goodbye')
    if action=='force':
        if arg=='target':
            _BB_GROUP_SETUP_PENDING[uid]={'kind':'force_target','chat_id':q.message.chat.id}
            await q.edit_message_text('🔗 <b>لینک مقصد جوین اجباری</b>\n\nلینک عمومی <code>https://t.me/...</code> یا <code>@username</code> مقصد را بفرست.\nبعد ربات خودش بررسی می‌کند که ادمین مقصد هست یا نه.',parse_mode='HTML',reply_markup=keyboard([[btn('❌ لغو','gsetup:back')]])); return True
        if arg=='default':
            cid=q.message.chat.id
            await DBX.execute('CREATE TABLE IF NOT EXISTS group_extra_settings(chat_id INTEGER PRIMARY KEY,forcejoin_text TEXT DEFAULT '')')
            await DBX.execute('INSERT OR REPLACE INTO group_extra_settings(chat_id,forcejoin_text) VALUES(?,?)',(cid,_BB_DEFAULT_FORCEJOIN_TEXT))
            _BB_GROUP_SETUP_PENDING.pop(uid,None)
            await q.answer('✅ متن پیش‌فرض ثبت شد و جوین اجباری فعال است.',show_alert=True)
            return True
    if action in {'welcome','goodbye'}:
        if arg=='text':
            _BB_GROUP_SETUP_PENDING[uid]={'kind':action+'_text','chat_id':q.message.chat.id}
            label='خوش‌آمد' if action=='welcome' else 'خداحافظی'
            await q.edit_message_text(f'📝 <b>متن {label}</b>\n\nمتن را در پیام بعدی بفرست.\nمی‌توانی از متغیرهای همین بخش استفاده کنی.\n\n'+_BB_GROUP_VARIABLES_TEXT,parse_mode='HTML',reply_markup=keyboard([[btn('✨ پیش‌فرض','gsetup:'+action+':default')],[btn('❌ لغو','gsetup:back')]])); return True
        if arg=='default':
            cid=q.message.chat.id
            if action=='welcome':
                await DBX.execute('UPDATE chats SET welcome_enabled=1,welcome_text=?,welcome_media_type="",welcome_media_id="",updated_at=? WHERE chat_id=?',(_BB_DEFAULT_WELCOME_TEXT,now_ts(),cid))
                await q.answer('✅ خوش‌آمد پیش‌فرض فعال شد.',show_alert=True)
            else:
                await DBX.execute('UPDATE chats SET goodbye_enabled=1,goodbye_text=?,goodbye_media_type="",goodbye_media_id="",updated_at=? WHERE chat_id=?',(_BB_DEFAULT_GOODBYE_TEXT,now_ts(),cid))
                await q.answer('✅ خداحافظی پیش‌فرض فعال شد.',show_alert=True)
            await _bb_group_setup_show(q,action); return True
    return True

async def _bb_group_setup_command(update, context):
    msg=getattr(update,'effective_message',None); user=getattr(update,'effective_user',None); chat=getattr(update,'effective_chat',None)
    if not msg or not user or not chat or not getattr(msg,'text',None) or chat.type=='private': return False
