# =============================================================================
# ABSOLUTE FINAL RELATIONSHIP + FAMILY ROUTES
# Repairs command priority and adds safe periodic marriage suggestions.
# =============================================================================
async def _bb_rel_final_text(update, context):
    msg=getattr(update,'effective_message',None); user=getattr(update,'effective_user',None)
    if not msg or not user or not getattr(msg,'text',None): return False
    t=normalize(str(msg.text or '').strip())
    if t in {'دوستی','دوست','ازدواج','خواستگاری','طلاق'}:
        target=getattr(getattr(msg,'reply_to_message',None),'from_user',None)
        if target and (int(target.id)==int(user.id) or bool(getattr(target,'is_bot',False))):
            await msg.reply_text('⚠️ <b>این بخش فقط برای ارتباط بین دو کاربر واقعی است.</b>\n\n⛔ ازدواج یا دوستی با خودت، ربات، تبچی یا هر حساب رباتی امکان‌پذیر نیست.',parse_mode='HTML')
            raise ApplicationHandlerStop
        if t in {'ازدواج','خواستگاری'} and bool(getattr(user,'is_bot',False)):
            await msg.reply_text('⚠️ حساب‌های رباتی نمی‌توانند وارد سیستم ازدواج شوند.')
            raise ApplicationHandlerStop
        handled=await _bb_rel_text(update,context)
        if handled:
            raise ApplicationHandlerStop
    return False

async def _bb_life_final_text(update, context):
    msg=getattr(update,'effective_message',None); user=getattr(update,'effective_user',None)
    if not msg or not user or not getattr(msg,'text',None): return False
    t=normalize(str(msg.text or '').strip())
    if t in {'زندگی','زندگی واقعی','زندگی مشترک جدید','خانه و زندگی','خانواده'}:
        fake=type('Q',(),{'from_user':user,'edit_message_text':msg.reply_text,'answer':lambda *a,**k:None})()
        await _bb_sim_home(fake,int(user.id))
        raise ApplicationHandlerStop
    return False

async def _bb_rel_final_callback(update, context):
    q=getattr(update,'callback_query',None); d=str(getattr(q,'data','') or '') if q else ''
    if not q or not d.startswith('bbrel:'): return False
    action=d.split(':')[1] if len(d.split(':'))>1 else ''
    if action in {'maccept','mquickaccept','divorce'}:
        await _bb_sim_marriage_callback(update,context)
    else:
        await _bb_rel_callback(update,context)
    raise ApplicationHandlerStop

async def _bb_relationship_suggestion_schema():
    await DBX.execute("""CREATE TABLE IF NOT EXISTS bb_relationship_suggestions(
        chat_id INTEGER NOT NULL, user1_id INTEGER NOT NULL, user2_id INTEGER NOT NULL,
        suggested_at INTEGER NOT NULL, PRIMARY KEY(chat_id,user1_id,user2_id))""")

async def _bb_relationship_suggestion_job(context):
    try:
        await _bb_rel_schema(); await _bb_relationship_suggestion_schema()
        chats=await DBX.execute("""SELECT DISTINCT chat_id FROM chat_member_stats
                                   WHERE is_bot=0 AND last_seen>=? LIMIT 80""",(now_ts()-14*86400,),fetch=True)
        for cr in chats:
            cid=int(cr['chat_id'])
            try:
                rows=await DBX.execute("""SELECT user_id,first_name,username FROM chat_member_stats
                                          WHERE chat_id=? AND is_bot=0 AND last_seen>=?
                                          ORDER BY RANDOM() LIMIT 40""",(cid,now_ts()-14*86400),fetch=True)
                eligible=[]
                for r in rows:
                    uid=int(r['user_id'])
                    if await _bb_rel_is_married(uid): continue
                    eligible.append(r)
                if len(eligible)<2: continue
                pair=None; random.shuffle(eligible)
                for i in range(min(len(eligible),12)):
                    for j in range(i+1,min(len(eligible),12)):
                        a,b=sorted([int(eligible[i]['user_id']),int(eligible[j]['user_id'])])
                        old=await DBX.one("""SELECT 1 FROM bb_relationship_suggestions
                                             WHERE chat_id=? AND user1_id=? AND user2_id=? AND suggested_at>=?""",(cid,a,b,now_ts()-7*86400))
                        if not old:
                            pair=(eligible[i],eligible[j],a,b); break
                    if pair: break
                if not pair: continue
                x,y,a,b=pair
                nx=safe_text(x['first_name'] or x['username'] or str(a),40)
                ny=safe_text(y['first_name'] or y['username'] or str(b),40)
                text=(f'💍 <b>پیشنهاد آشنایی و ازدواج</b>\n\n'
                      f'شاید بین <a href="tg://user?id={a}">{nx}</a> و <a href="tg://user?id={b}">{ny}</a> '
                      'یک آشنایی خوب شکل بگیرد.\n\n'
                      '⚠️ این فقط یک پیشنهاد است؛ هیچ ازدواجی خودکار ثبت نمی‌شود و رضایت هر دو نفر لازم است.\n'
                      '⛔ ازدواج با خود، ربات، تبچی یا هر حساب رباتی ممنوع است.')
                kb=keyboard([[btn(f'💍 {nx[:14]} خواستگاری',f'bbmatch:{a}:{b}'),btn(f'💍 {ny[:14]} خواستگاری',f'bbmatch:{b}:{a}')]])
                await context.bot.send_message(cid,text,parse_mode='HTML',reply_markup=kb)
                await DBX.execute("INSERT OR REPLACE INTO bb_relationship_suggestions(chat_id,user1_id,user2_id,suggested_at) VALUES(?,?,?,?)",(cid,a,b,now_ts()))
            except Exception as exc:
                log.debug('relationship suggestion failed chat=%s: %s',cid,exc)
    except Exception as exc:
        log.debug('relationship suggestion job failed: %s',exc)

async def _bb_relationship_suggestion_callback(update, context):
    q=getattr(update,'callback_query',None); d=str(getattr(q,'data','') or '') if q else ''
    if not q or not d.startswith('bbmatch:'): return False
    try:
        _,s,t=d.split(':',2); sender=int(s); target=int(t); uid=int(q.from_user.id)
    except Exception:
        await q.answer('درخواست نامعتبر است.',show_alert=True); return True
    if uid!=sender:
        await q.answer('⛔ این دکمه برای کاربر دیگری است.',show_alert=True); return True
    if sender==target:
        await q.answer('⚠️ ازدواج با خود امکان‌پذیر نیست.',show_alert=True); return True
    if await _bb_rel_is_married(sender) or await _bb_rel_is_married(target):
        await q.answer('💍 یکی از این دو نفر همسر ثبت‌شده دارد.',show_alert=True); return True
    try:
        cm=await context.bot.get_chat_member(int(q.message.chat.id),target)
        if bool(getattr(cm.user,'is_bot',False)):
            await q.answer('⛔ ازدواج با ربات یا تبچی مجاز نیست.',show_alert=True); return True
    except Exception:
        pass
    await _bb_rel_schema()
    old=await DBX.one('SELECT status FROM bb_marriage_requests WHERE sender_id=? AND receiver_id=? ORDER BY id DESC LIMIT 1',(sender,target))
    if old and str(old['status'])=='pending':
        await q.answer('⏳ درخواست ازدواج قبلاً ارسال شده است.',show_alert=True); return True
    await DBX.execute("""INSERT INTO bb_marriage_requests(sender_id,receiver_id,status,created_at) VALUES(?,?,'pending',?)
                         ON CONFLICT(sender_id,receiver_id) DO UPDATE SET status='pending',created_at=excluded.created_at""",(sender,target,now_ts()))
    name=await _bb_rel_user_name(sender); target_name=await _bb_rel_user_name(target)
    target_mention=f'<a href="tg://user?id={target}">{safe_text(target_name,80)}</a>'
    notice=_bb_ui_text(_BB_REL_TEXT_MARRIAGE_IN).format(name=name,target_mention=target_mention)
    await context.bot.send_message(q.message.chat.id,notice,parse_mode='HTML',reply_markup=keyboard([[btn(_BB_REL_BTN_ACCEPT,f'bbrel:mquickaccept:{sender}:{target}'),btn(_BB_REL_BTN_REJECT,f'bbrel:mquickreject:{sender}:{target}')]]))
    await q.answer(f'💍 درخواست برای {target_name} ارسال شد.',show_alert=True)
    return True

_BB_BUILD_BEFORE_REL_FINAL=build_application
def build_application(token=None):
    app=_BB_BUILD_BEFORE_REL_FINAL(token)
    app.add_handler(CallbackQueryHandler(_bb_relationship_suggestion_callback,pattern=r'^bbmatch:'),group=-100000500)
    app.add_handler(CallbackQueryHandler(_bb_rel_final_callback,pattern=r'^bbrel:'),group=-100000501)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_rel_final_text),group=-100000502)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_life_final_text),group=-100000503)
    old_post=getattr(app,'post_init',None)
    async def _rel_final_post(application):
        if old_post: await old_post(application)
        await _bb_relationship_suggestion_schema()
        try:
            jq=application.job_queue
            if jq:
                for job in jq.get_jobs_by_name('bilbilak-relationship-suggestions'):
                    job.schedule_removal()
                jq.run_repeating(_bb_relationship_suggestion_job,interval=4*3600,first=300,name='bilbilak-relationship-suggestions')
        except Exception as exc:
            log.debug('relationship suggestion scheduler failed: %s',exc)
    app.post_init=_rel_final_post
    return app


