# Register every catalog item and life text/button in the existing owner design system.
async def _bb_register_expanded_life_design():
    await _bb_life_expanded_schema()
    vals=[x[0] for x in _BB_LIFE_ASSETS]+_BB_LIFE_JOB_CATALOG+[x[0] for x in _BB_LIFE_LONG_CHALLENGES]
    for v in vals:
        try: await _bb_ui_register(v,category='life',kind='text')
        except Exception: pass
    for v in ('💼 بازار کار ۱۰۰+ شغل','🎯 چالش‌های بلندمدت','🧬 شخصیت و ویژگی‌ها','🚗 وسایل نقلیه','🛍 بازار وسایل و دارایی‌ها','🏠 زندگی'):
        try: await _bb_ui_register(v,category='life',kind='button')
        except Exception: pass

_BB_FINAL_LIFE_BUILD_OLD=build_application
def build_application(token=None):
    app=_BB_FINAL_LIFE_BUILD_OLD(token)
    app.add_handler(CallbackQueryHandler(_bb_life_expanded_callback,pattern=r'^life(?:jobs|job|trait|renew|assets|asset|challenge|chnew|chstep):'),group=-100001000)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_life_expanded_text),group=-100001001)
    old_post=getattr(app,'post_init',None)
    async def _life_expanded_post(application):
        if old_post: await old_post(application)
        try:
            await _bb_life_expanded_schema()
            couples=await DBX.all('SELECT user1_id,user2_id FROM bb_marriages')
            for cp in couples:
                x,y=sorted([int(cp['user1_id']),int(cp['user2_id'])])
                exists=await DBX.one('SELECT 1 FROM bb_life_shared_wallets WHERE user1_id=? AND user2_id=?',(x,y))
                if not exists:
                    await _bb_life_merge_wallet(x,y)
        except Exception as exc: log.debug('existing shared wallet migration failed: %s',exc)
        try: await _bb_register_expanded_life_design()
        except Exception as exc: log.debug('life design registration failed: %s',exc)
    app.post_init=_life_expanded_post
    return app


# Professional raffle safety layer: real users only, group-membership check,
# duplicate protection remains handled by the core raffle engine.
async def _bb_raffle_professional_guard(update, context):
    q=getattr(update,'callback_query',None); d=str(getattr(q,'data','') or '') if q else ''
    if not q or not d.startswith('raffle:join:'): return False
    try: rid=int(d.split(':')[2]); uid=int(q.from_user.id)
    except Exception: return False
    if bool(getattr(q.from_user,'is_bot',False)):
        await q.answer('⛔ حساب‌های رباتی نمی‌توانند در قرعه‌کشی شرکت کنند.',show_alert=True); raise ApplicationHandlerStop
    row=await DBX.one('SELECT chat_id,status FROM bb_raffles WHERE id=?',(rid,))
    if not row or str(row['status'])!='open':
        await q.answer('این قرعه‌کشی دیگر فعال نیست.',show_alert=True); raise ApplicationHandlerStop
    try:
        member=await context.bot.get_chat_member(int(row['chat_id']),uid)
        if str(getattr(member,'status','')) in {'left','kicked'}:
            await q.answer('⚠️ ابتدا باید عضو همین گروه باشی.',show_alert=True); raise ApplicationHandlerStop
        if bool(getattr(member.user,'is_bot',False)):
            await q.answer('⛔ حساب‌های رباتی مجاز نیستند.',show_alert=True); raise ApplicationHandlerStop
    except ApplicationHandlerStop:
        raise
    except Exception:
        # If Telegram temporarily cannot verify membership, let the core engine handle the request.
        pass
    return False

_BB_RAFFLE_PRO_BUILD_OLD=build_application
def build_application(token=None):
    app=_BB_RAFFLE_PRO_BUILD_OLD(token)
    app.add_handler(CallbackQueryHandler(_bb_raffle_professional_guard,pattern=r'^raffle:join:'),group=-100001200)
    return app


# ==================== WEDDING CEREMONY / INVITATION FINAL LAYER ====================
async def _bb_wedding_schema_final():
    await DBX.execute("""CREATE TABLE IF NOT EXISTS bb_wedding_invites_final(
        id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id INTEGER NOT NULL, groom_id INTEGER NOT NULL,
        bride_id INTEGER NOT NULL, officiant_id INTEGER, officiant_name TEXT NOT NULL DEFAULT 'ربات بیل بیلک',
        fee INTEGER NOT NULL DEFAULT 1000, guests TEXT NOT NULL DEFAULT 'all', venue TEXT,
        poem TEXT, catering TEXT, status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL,
        approved_at INTEGER)""")
    await DBX.execute("""CREATE TABLE IF NOT EXISTS bb_wedding_officiants_final(
        chat_id INTEGER NOT NULL, user_id INTEGER NOT NULL, fee INTEGER NOT NULL DEFAULT 1000,
        active INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(chat_id,user_id))""")

async def _bb_wedding_pair_final(uid, chat_id):
    m=await _bb_rel_is_married(int(uid))
    if not m or m.get('chat_id') is None or int(m['chat_id'])!=int(chat_id): return None
    return tuple(sorted([int(uid),int(m['other_id'])]))

async def _bb_wedding_member_final(bot, chat_id, uid):
    try:
        m=await bot.get_chat_member(int(chat_id),int(uid)); return m.user if m else None
    except Exception: return None

async def _bb_wedding_create_final(update, context):
    msg=update.effective_message; chat=update.effective_chat; user=update.effective_user
    if not msg or not chat or chat.type not in {'group','supergroup'}: return False
    text=(msg.text or '').strip()
    if not _bb_plain_tool_text(text).lower().startswith('دعوتنامه'): return False
    pair=await _bb_wedding_pair_final(user.id,chat.id)
    if not pair:
        await msg.reply_text('💍 دعوتنامه فقط برای زوجی ساخته می‌شود که ازدواجشان در همین گروه ثبت شده باشد.'); return True
    await _bb_wedding_schema_final()
    old=await DBX.one("SELECT id FROM bb_wedding_invites_final WHERE chat_id=? AND groom_id=? AND bride_id=? AND status='pending'",(chat.id,pair[0],pair[1]))
    if old:
        await msg.reply_text(f'💌 یک دعوتنامه در انتظار تأیید است. شناسه: <code>{old["id"]}</code>',parse_mode='HTML'); return True
    args=text.split()[1:]
    guests='all' if not args or any(x in {'همه','همه‌گروه','همه_گروه'} for x in args) else ','.join(x.lstrip('@') for x in args)
    off=None
    for r in await DBX.all('SELECT user_id,fee FROM bb_wedding_officiants_final WHERE chat_id=? AND active=1',(chat.id,)):
        u=await _bb_wedding_member_final(context.bot,chat.id,r['user_id'])
        if u and not getattr(u,'is_bot',False): off=(int(r['user_id']),int(r['fee'] or 1000),u.full_name); break
    if off: officiant_id,fee,offname=off
    else: officiant_id,fee,offname=None,1000,'ربات بیل بیلک'
    groom=await _bb_wedding_member_final(context.bot,chat.id,pair[0]); bride=await _bb_wedding_member_final(context.bot,chat.id,pair[1])
    groom_name=groom.mention_html() if groom else f'<a href="tg://user?id={pair[0]}">داماد</a>'
    bride_name=bride.mention_html() if bride else f'<a href="tg://user?id={pair[1]}">عروس</a>'
    poem='دو دل به یک پیمان رسیدند؛ امید که خانه‌شان همیشه پر از مهر، آرامش و خنده باشد. 💞'
    catering='چای، شیرینی، میوه و کیک عروسی'
    await DBX.execute('INSERT INTO bb_wedding_invites_final(chat_id,groom_id,bride_id,officiant_id,officiant_name,fee,guests,venue,poem,catering,status,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',(chat.id,pair[0],pair[1],officiant_id,offname,fee,guests,chat.title or 'گروه',poem,catering,'pending',now_ts()))
    r=await DBX.one('SELECT id FROM bb_wedding_invites_final WHERE chat_id=? AND groom_id=? AND bride_id=? AND status="pending" ORDER BY id DESC LIMIT 1',(chat.id,pair[0],pair[1])); wid=int(r['id'])
    preview=(f'💌 <b>دعوتنامه عقد و عروسی</b> — <code>#{wid}</code>\n\n🤵 داماد: {groom_name}\n👰 عروس: {bride_name}\n'
             f'📍 مکان: <b>{safe_text(chat.title or "گروه")}</b>\n💐 عاقد: <b>{safe_text(offname)}</b>\n💰 حق‌الزحمه: <b>{fee:,}</b> 🦴\n\n'
             f'🌹 <b>شعر عاشقانه</b>\n{poem}\n\n🍰 <b>پذیرایی</b>: {catering}\n\n👑 این دعوتنامه باید توسط ادمین گروه تأیید شود.')
    await msg.reply_text(preview,parse_mode='HTML',reply_markup=keyboard([[btn('✅ تأیید دعوتنامه توسط ادمین',f'bbwfinal:approve:{wid}')]])); return True

async def _bb_wedding_officiant_final(update, context):
    msg=update.effective_message; chat=update.effective_chat; user=update.effective_user
    if not msg or not chat or chat.type not in {'group','supergroup'}: return False
    parts=(msg.text or '').strip().split()
    if not parts or _bb_plain_tool_text(parts[0])!='عاقد': return False
    if not await _bb_is_group_admin(context.bot,chat.id,user.id): return False
    await _bb_wedding_schema_final()
    if len(parts)>=2 and parts[1] in {'ثبت','فعال','اضافه'}:
        fee=int(parts[2]) if len(parts)>=3 and parts[2].isdigit() else 1000
        await DBX.execute('INSERT OR REPLACE INTO bb_wedding_officiants_final(chat_id,user_id,fee,active) VALUES(?,?,?,1)',(chat.id,user.id,max(0,fee)))
        await msg.reply_text(f'💐 شما عاقد این گروه شدید. حق‌الزحمه هر مراسم: <b>{fee:,}</b> 🦴',parse_mode='HTML'); return True
    if len(parts)>=2 and parts[1] in {'حذف','غیرفعال'}:
        await DBX.execute('UPDATE bb_wedding_officiants_final SET active=0 WHERE chat_id=? AND user_id=?',(chat.id,user.id)); await msg.reply_text('💐 وضعیت عاقدی شما غیرفعال شد.'); return True
    return False

async def _bb_wedding_approve_final(update, context):
    q=update.callback_query; parts=str(q.data or '').split(':')
    if len(parts)!=3 or parts[0]!='bbwfinal' or parts[1]!='approve': return False
    cid=int(q.message.chat.id); wid=int(parts[2])
    if not await _bb_is_group_admin(context.bot,cid,q.from_user.id):
        await q.answer('⛔ فقط ادمین گروه می‌تواند دعوتنامه را تأیید کند.',show_alert=True); return True
    await _bb_wedding_schema_final(); w=await DBX.one('SELECT * FROM bb_wedding_invites_final WHERE id=? AND chat_id=? AND status="pending"',(wid,cid))
    if not w: await q.answer('این دعوتنامه قبلاً بررسی شده یا پیدا نشد.',show_alert=True); return True
    payer=int(w['groom_id']); fee=int(w['fee'])
    if await _bb_sim_money_expanded(payer)<fee:
        await q.answer('موجودی زندگی مشترک برای هزینه عاقد کافی نیست.',show_alert=True); return True
    await _bb_sim_sub_money_expanded(payer,fee)
    if w['officiant_id']: await DBX.execute('UPDATE users SET bones=bones+?,updated_at=? WHERE user_id=?',(fee,now_ts(),int(w['officiant_id'])))
    await DBX.execute('UPDATE bb_wedding_invites_final SET status="approved",approved_at=? WHERE id=?',(now_ts(),wid))
    groom=await _bb_wedding_member_final(context.bot,cid,w['groom_id']); bride=await _bb_wedding_member_final(context.bot,cid,w['bride_id'])
    gm=groom.mention_html() if groom else f'<a href="tg://user?id={w["groom_id"]}">داماد</a>'; bm=bride.mention_html() if bride else f'<a href="tg://user?id={w["bride_id"]}">عروس</a>'
    invite=(f'💍 <b>دعوتنامه عقد و عروسی — تأیید شد</b>\n\n🤵 داماد: {gm}\n👰 عروس: {bm}\n📍 مکان: <b>{safe_text(w["venue"] or q.message.chat.title or "گروه")}</b>\n'
            f'💐 عاقد: <b>{safe_text(w["officiant_name"])}</b>\n💰 حق‌الزحمه: <b>{fee:,}</b> 🦴\n\n🌹 <b>شعر عاشقانه</b>\n{w["poem"]}\n\n🍰 <b>پذیرایی</b>: {w["catering"]}\n\n📣 <b>از مهمانان دعوت‌شده برای حضور در مراسم عقد و عروسی دعوت می‌شود.</b>')
    await q.edit_message_text(invite,parse_mode='HTML')
    guests=str(w['guests'] or 'all'); ids=[]
    if guests=='all':
        rows=await DBX.all('SELECT user_id FROM chat_member_stats WHERE chat_id=? AND is_bot=0 ORDER BY last_seen DESC LIMIT 60',(cid,)); ids=[int(r['user_id']) for r in rows]
    else: ids=[int(x) for x in guests.split(',') if x.isdigit()]
    ids=list(dict.fromkeys(ids+[int(w['groom_id']),int(w['bride_id'])]))[:60]; tags=[]
    for uid in ids:
        u=await _bb_wedding_member_final(context.bot,cid,uid)
        if u and not getattr(u,'is_bot',False): tags.append(u.mention_html())
    if tags: await q.message.reply_text('📣 <b>مهمانان دعوت‌شده:</b>\n'+' '.join(tags),parse_mode='HTML')
    await q.answer('دعوتنامه تأیید و هزینه عاقد پرداخت شد.'); return True

_BB_WEDDING_BUILD_PREV=build_application
def build_application(token=None):
    app=_BB_WEDDING_BUILD_PREV(token)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_wedding_officiant_final),group=-100002000)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_wedding_create_final),group=-100002001)
    app.add_handler(CallbackQueryHandler(_bb_wedding_approve_final,pattern=r'^bbwfinal:approve:'),group=-100002002)
    return app

# ==================== REALISTIC CAREER SYSTEM V2 ====================
_BB_REAL_EDUCATION_LEVELS=[('بی‌سواد',0),('ابتدایی',1),('متوسطه',2),('دیپلم',3),('کاردانی',4),('کارشناسی',5),('کارشناسی ارشد',6),('دکترا',7)]
_BB_ADMIN_JOB_KEYWORDS=('مدیر ارشد','مدیر پروژه','مدیر محصول','مدیر منابع انسانی','مدیر فروش','مدیر رستوران','مدیر فروشگاه','مدیر تبلیغات','مدیر شبکه اجتماعی','مدیر عملیات','مدیر مالی','مدیر فناوری اطلاعات','مدیر اجرایی')
_BB_REAL_EXTRA_JOBS=['بلاگر','اینفلوئنسر','پادکستر','سازنده ویدیو','سازنده محتوای آموزشی','خبرنگار دیجیتال','مدیر کانال','مدیر انجمن آنلاین','متخصص روابط عمومی','مدیر برند','مدیر منابع انسانی','مدیر عملیات','مدیر مالی','مدیر فناوری اطلاعات','مدیر اجرایی','مشاور مدیریت','مشاور مالی','مشاور منابع انسانی','متخصص تبلیغات','متخصص روابط عمومی','طراح گرافیک ارشد','عکاس خبری','فیلمبردار تلویزیونی','تهیه‌کننده محتوا','نویسنده تبلیغاتی','کارشناس روابط عمومی','کارشناس فروش سازمانی','کارشناس آموزش','کارشناس کنترل کیفیت','کارشناس آزمایشگاه','تکنسین دندانپزشکی','تکنسین داروخانه','اپتومتریست','کاردرمانگر','گفتاردرمانگر','ماما','کارشناس تغذیه','مهندس پزشکی','مهندس کامپیوتر','مهندس نفت','مهندس معدن','مهندس محیط زیست','کارشناس منابع طبیعی','کارشناس آب و فاضلاب','کارشناس لجستیک','مدیر زنجیره تأمین','کارشناس خرید','کارشناس صادرات و واردات','کارشناس بانک','تحلیلگر سرمایه‌گذاری','کارشناس مالیاتی','کارشناس اعتبارات','کارشناس امور بیمه','کارشناس حقوقی','دستیار حقوقی','کارشناس جذب نیرو']
for _j in _BB_REAL_EXTRA_JOBS:
    if _j not in _BB_LIFE_JOB_CATALOG:_BB_LIFE_JOB_CATALOG.append(_j)
_BB_LIFE_JOB_SALARY={name:max(350,550+i*70) for i,name in enumerate(_BB_LIFE_JOB_CATALOG) if 'داستانی' not in name and 'بازی)' not in name}
_BB_LIFE_JOB_CATALOG=[j for j in _BB_LIFE_JOB_CATALOG if j in _BB_LIFE_JOB_SALARY]
async def _bb_career_schema():
    await _bb_life_expanded_schema()
    await DBX.execute("""CREATE TABLE IF NOT EXISTS bb_life_education(user_id INTEGER PRIMARY KEY,level INTEGER NOT NULL DEFAULT 3,title TEXT NOT NULL DEFAULT 'دیپلم',field TEXT NOT NULL DEFAULT 'عمومی',xp INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL DEFAULT 0)""")
    await DBX.execute("""CREATE TABLE IF NOT EXISTS bb_life_job_progress(user_id INTEGER PRIMARY KEY,job_key TEXT NOT NULL DEFAULT '',week_key TEXT NOT NULL DEFAULT '',task_total INTEGER NOT NULL DEFAULT 5,task_done INTEGER NOT NULL DEFAULT 0,quality INTEGER NOT NULL DEFAULT 50,streak INTEGER NOT NULL DEFAULT 0,last_task_ts INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL DEFAULT 0)""")
    await DBX.execute("""CREATE TABLE IF NOT EXISTS bb_life_job_history(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,job_key TEXT NOT NULL,week_key TEXT NOT NULL,tasks INTEGER NOT NULL DEFAULT 0,salary INTEGER NOT NULL DEFAULT 0,paid_at INTEGER NOT NULL DEFAULT 0)""")
async def _bb_career_education(uid):
    await _bb_career_schema(); r=await DBX.one('SELECT * FROM bb_life_education WHERE user_id=?',(uid,))
    if r:return r
    import random
    level=random.choices(range(8),weights=[2,3,7,28,18,22,12,8],k=1)[0]; field=random.choice(['عمومی','فنی','کامپیوتر','مهندسی','پزشکی','مدیریت','هنر','علوم پایه','زبان','گردشگری'])
    await DBX.execute('INSERT INTO bb_life_education(user_id,level,title,field,xp,updated_at) VALUES(?,?,?,?,?,?)',(uid,level,_BB_REAL_EDUCATION_LEVELS[level][0],field,0,now_ts())); return await DBX.one('SELECT * FROM bb_life_education WHERE user_id=?',(uid,))
def _bb_career_req(t):
    if any(x in t for x in ('پزشک','دندانپزشک','داروساز','استاد دانشگاه')):return 7,'discipline'
    if any(x in t for x in ('پژوهشگر','دانشمند','روان‌شناس','وکیل','حسابرس')):return 6,'discipline'
    if any(x in t for x in ('مهندس','معمار','برنامه‌نویس','توسعه‌دهنده','تحلیلگر','حسابدار','مدرس','معلم','خلبان','مدیر پروژه')):return 5,'discipline'
    if any(x in t for x in ('کارشناس','متخصص','طراح','نویسنده','خبرنگار')):return 4,'discipline'
    if any(x in t for x in ('بلاگر','اینفلوئنسر','پادکستر','محتوا','فروشنده','بازاریاب','مجری','بازیگر','خواننده','عکاس')):return 2,'social'
    return 1,'energy'
def _bb_career_admin_better(t):return any(x in t for x in _BB_ADMIN_JOB_KEYWORDS)
async def _bb_career_is_admin(bot,cid,uid):
    try:return getattr(await bot.get_chat_member(cid,uid),'status','') in ('administrator','creator')
    except:return False
async def _bb_career_check(bot,cid,uid,t):
    e=await _bb_career_education(uid); tr=await _bb_life_traits_for(uid); need,trait=_bb_career_req(t); reasons=[]
    if int(e['level'])<need:reasons.append(f'تحصیلات لازم: {_BB_REAL_EDUCATION_LEVELS[need][0]}؛ تحصیلات تو: {e["title"]}')
    if int(tr[trait])<55:reasons.append(f'ویژگی «{trait}» باید حداقل 55 باشد؛ مقدار فعلی {int(tr[trait])}')
    if _bb_career_admin_better(t) and not await _bb_career_is_admin(bot,cid,uid):reasons.append('این شغل مدیریتی ویژه ادمین‌های واقعی گروه است')
    return not reasons,reasons
async def _bb_career_week():
    from datetime import datetime,timezone
    return datetime.now(timezone.utc).strftime('%Y-W%V')
async def _bb_career_progress(uid,key):
    await _bb_career_schema(); w=await _bb_career_week(); r=await DBX.one('SELECT * FROM bb_life_job_progress WHERE user_id=?',(uid,))
    if not r or str(r['job_key'])!=key or str(r['week_key'])!=w:
        await DBX.execute('INSERT OR REPLACE INTO bb_life_job_progress(user_id,job_key,week_key,task_total,task_done,quality,streak,last_task_ts,updated_at) VALUES(?,?,?,?,?,?,?,?,?)',(uid,key,w,5,0,50,int(r['streak']) if r else 0,0,now_ts())); r=await DBX.one('SELECT * FROM bb_life_job_progress WHERE user_id=?',(uid,))
    return r
async def _bb_career_panel(q,uid,key):
    job=await DBX.one('SELECT title,salary FROM bb_life_jobs WHERE job_key=? AND enabled=1',(key,)); p=await _bb_career_progress(uid,key); e=await _bb_career_education(uid)
    if not job:return
    d=int(p['task_done']); text=f'💼 <b>{job["title"]}</b>\n\n🎓 {e["title"]} | {e["field"]}\n🛠 کارهای این هفته: <b>{d}/5</b>\n⭐ کیفیت: {int(p["quality"])}٪\n💰 حقوق هفتگی پایه: <b>{int(job["salary"])*7:,}</b> 🦴\n\nهر هفته باید کارهای شغلت را انجام بدهی؛ انتخاب شغل به‌تنهایی حقوق نمی‌دهد.'
    rows=[[btn(f'🛠 انجام کار ({d+1}/5)',f'career:task:{uid}:{key}')]] if d<5 else [[btn('💰 دریافت حقوق هفتگی',f'career:salary:{uid}:{key}')]]
