async def _bb_weekly_payroll_job(context):
    try:
        await _bb_career_schema();rows=await DBX.execute('SELECT * FROM bb_life_job_progress WHERE task_done>=task_total',fetch=True);w=await _bb_career_week()
        for p in rows:
            job=await DBX.one('SELECT title,salary FROM bb_life_jobs WHERE job_key=? AND enabled=1',(p['job_key'],));old=await DBX.one('SELECT id FROM bb_life_job_history WHERE user_id=? AND job_key=? AND week_key=?',(p['user_id'],p['job_key'],w))
            if not job or old:continue
            salary=int(round(int(job['salary'])*7*max(.75,min(1.35,int(p['quality'])/70))));await _bb_sim_add_money(int(p['user_id']),salary);await DBX.execute('INSERT INTO bb_life_job_history(user_id,job_key,week_key,tasks,salary,paid_at) VALUES(?,?,?,?,?,?)',(p['user_id'],p['job_key'],w,p['task_done'],salary,now_ts()))
            try:await context.bot.send_message(int(p['user_id']),f'💰 حقوق هفتگی {job["title"]}: <b>{salary:,}</b> 🦴',parse_mode='HTML')
            except:pass
    except Exception as e:log.debug('weekly payroll: %s',e)
_BB_PREV_CAREER_BUILD=build_application
def build_application(token=None):
    app=_BB_PREV_CAREER_BUILD(token);app.add_handler(CallbackQueryHandler(_bb_career_cb,pattern=r'^career:'),group=-100002000)
    app.add_handler(CallbackQueryHandler(_bb_life_expanded_callback_real,pattern=r'^lifejob:'),group=-100003000)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_jojo_amir_phrase),group=-100003100)
    old_post=getattr(app,'post_init',None)
    async def _career_post(application):
        if old_post:await old_post(application)
        await _bb_career_schema();jq=getattr(application,'job_queue',None)
        if jq:
            for j in jq.get_jobs_by_name('bilbilak-weekly-payroll-v2'):j.schedule_removal()
            jq.run_repeating(_bb_weekly_payroll_job,interval=7*86400,first=300,name='bilbilak-weekly-payroll-v2')
    app.post_init=_career_post;return app

