async def _bb_jojo_amir_phrase(update, context):
    if not update.message or not update.message.text:
        return
    if update.message.text.strip() != "جوجوی امیر":
        return
    await update.message.reply_text("جوجوی امیر مبیناس الهی امیر فداش بشه")
    raise ApplicationHandlerStop



# ==================== LIFE JOBS PRO: REALISTIC FICTIONAL WORKFLOWS ====================
# Jobs are fictional game simulations: they do not diagnose, treat, or replace
# real-world professional services. Each profession gets its own queue/tasks,
# work hours, customers/patients/clients and weekly payroll.
def _bb_job_pro_schema():
    DB.execute("""CREATE TABLE IF NOT EXISTS bb_job_profiles(
        user_id INTEGER PRIMARY KEY, job_key TEXT, education_level INTEGER DEFAULT 0,
        skill_xp INTEGER DEFAULT 0, work_started INTEGER DEFAULT 0,
        work_completed INTEGER DEFAULT 0, weekly_earnings INTEGER DEFAULT 0,
        last_pay_ts INTEGER DEFAULT 0, work_minutes INTEGER DEFAULT 0)""")
    DB.execute("""CREATE TABLE IF NOT EXISTS bb_job_tasks(
        id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, job_key TEXT,
        task_type TEXT, client_name TEXT, reward INTEGER DEFAULT 0,
        status TEXT DEFAULT 'open', created_at INTEGER, completed_at INTEGER)""")
    DB.execute("""CREATE TABLE IF NOT EXISTS bb_job_hours(
        user_id INTEGER, chat_id INTEGER, work_date TEXT, minutes INTEGER DEFAULT 0,
        PRIMARY KEY(user_id,chat_id,work_date))""")
    DB.execute("""CREATE TABLE IF NOT EXISTS bb_real_help_requests(
        id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id INTEGER, user_id INTEGER,
        category TEXT, status TEXT DEFAULT 'open', created_at INTEGER, resolved_at INTEGER,
        resolver_id INTEGER)""")

