def _bb_job_task_types(key):
    return _BB_JOB_TASKS.get(key,['پذیرش مشتری','بررسی درخواست','انجام مرحله تخصصی','کنترل کیفیت','تحویل کار'])

def _bb_job_eligible(uid,key):
    info=_BB_JOB_PROFESSIONS.get(key)
    if not info: return False,'این شغل تعریف نشده است.'
    row=DB.one('SELECT education_level FROM bb_job_profiles WHERE user_id=?',(uid,))
    edu=int(row['education_level'] or 0) if row else 0
    if edu < info[1]: return False,f'برای «{info[0]}» حداقل سطح تحصیلات {info[1]} لازم است.'
    return True,''

async def _bb_job_open(update, context, key=None):
    _bb_job_pro_schema(); uid=update.effective_user.id
    if key and key in _BB_JOB_PROFESSIONS:
        admin_jobs={'project_manager','hr_manager','sales_manager','it_manager'}
        if key in admin_jobs:
            try:
                if update.effective_chat.type not in ('group','supergroup') or not await _bb_is_group_admin(context.bot,update.effective_chat.id,uid):
                    await update.effective_message.reply_text('👑 این شغل مدیریتی ویژه ادمین واقعی گروه است.')
                    return
            except Exception:
                await update.effective_message.reply_text('👑 برای این شغل باید ادمین واقعی گروه باشی.')
                return
        ok,reason=_bb_job_eligible(uid,key)
        if not ok:
            suggestions=[]
            for k,v in _BB_JOB_PROFESSIONS.items():
                good,_=_bb_job_eligible(uid,k)
                if good: suggestions.append(v[0])
            await update.effective_message.reply_text('❌ '+reason+'\n\n💡 پیشنهادهای مناسب فعلی:\n'+'، '.join(suggestions[:6]) if suggestions else '💡 ابتدا تحصیلات و مهارتت را ارتقا بده.')
            return
        DB.execute("INSERT OR IGNORE INTO bb_job_profiles(user_id,job_key,work_started) VALUES(?,?,?)",(uid,key,int(time.time())))
        DB.execute("UPDATE bb_job_profiles SET job_key=? WHERE user_id=?",(key,uid))
    row=DB.one('SELECT * FROM bb_job_profiles WHERE user_id=?',(uid,))
    if not row or not row['job_key']:
        await update.effective_message.reply_text('💼 برای انتخاب شغل، «شغل» را بزن.\nمثال: «شغل پزشک» یا «شغل خیاط»')
        return
    key=row['job_key']; info=_BB_JOB_PROFESSIONS.get(key)
    await update.effective_message.reply_text(
        f'💼 <b>{info[0]}</b>\n\n⏰ ساعت کاری: ۹ تا ۱۷\n💰 حقوق پایه هفتگی: {info[3]:,}\n👥 مراجعان: {info[4]}\n\nبرای دریافت حقوق باید کارهای هفته را انجام بدهی.\n«کار» = دریافت مرحله کاری\n«کار بعدی» = مرحله بعدی',parse_mode='HTML')

async def _bb_job_work(update, context):
    _bb_job_pro_schema(); uid=update.effective_user.id
    row=DB.one('SELECT * FROM bb_job_profiles WHERE user_id=?',(uid,))
    if not row or not row['job_key']:
        await update.effective_message.reply_text('💼 هنوز شغلی نداری. اول «شغل» را اجرا کن.')
        return
    key=row['job_key']; info=_BB_JOB_PROFESSIONS.get(key); tasks=_bb_job_task_types(key)
    done=int(row['work_completed'] or 0)
    if done>=len(tasks):
        await update.effective_message.reply_text('✅ کارهای این هفته تمام شده‌اند. حقوقت در پرداخت هفتگی محاسبه می‌شود.')
        return
    task=tasks[done]
    reward=max(100,info[3]//len(tasks))
    client=f'{info[4]} #{random.randint(100,999)}'
    DB.execute('INSERT INTO bb_job_tasks(user_id,job_key,task_type,client_name,reward,status,created_at) VALUES(?,?,?,?,?,?,?)',(uid,key,task,client,reward,'open',int(time.time())))
    await update.effective_message.reply_text(f'🧑‍💼 مراجعه‌کننده جدید: <b>{client}</b>\n🛠 وظیفه: <b>{task}</b>\n\nبا «حل کار» این مرحله را انجام بده.',parse_mode='HTML')

async def _bb_job_resolve(update, context):
    _bb_job_pro_schema(); uid=update.effective_user.id
    t=DB.one("SELECT * FROM bb_job_tasks WHERE user_id=? AND status='open' ORDER BY id DESC LIMIT 1",(uid,))
    if not t:
        await update.effective_message.reply_text('📋 کار بازی فعالی نداری. «کار» را بزن.')
        return
    DB.execute('UPDATE bb_job_tasks SET status="done",completed_at=? WHERE id=?',(int(time.time()),t['id']))
    DB.execute('UPDATE bb_job_profiles SET work_completed=work_completed+1,skill_xp=skill_xp+5,weekly_earnings=weekly_earnings+? WHERE user_id=?',(t['reward'],uid))
    row=DB.one('SELECT * FROM bb_job_profiles WHERE user_id=?',(uid,))
    total=len(_bb_job_task_types(t['job_key']))
    done=int(row['work_completed'] or 0)
    msg=f'✅ مرحله «{t["task_type"]}» انجام شد.\n💰 سهم این مرحله: {t["reward"]:,}\n📈 پیشرفت هفته: {done}/{total}'
    if done>=total:
        now=int(time.time()); last=int(row['last_pay_ts'] or 0)
        if now-last>=7*86400:
            pay=int(row['weekly_earnings'] or 0)
            DB.execute('INSERT OR IGNORE INTO bbx_profiles(user_id,bones) VALUES(?,0)',(uid,))
            DB.execute('UPDATE bbx_profiles SET bones=bones+? WHERE user_id=?',(pay,uid))
            DB.execute('UPDATE bb_job_profiles SET last_pay_ts=?,work_completed=0,weekly_earnings=0 WHERE user_id=?',(now,uid))
            msg += f'\n\n💵 <b>حقوق هفتگی پرداخت شد: {pay:,}</b> 🦴'
        else:
            DB.execute('UPDATE bb_job_profiles SET work_completed=0 WHERE user_id=?',(uid,))
            msg += '\n\n📅 هفته کاری کامل شد؛ پرداخت بعدی طبق چرخه هفتگی انجام می‌شود.'
    await update.effective_message.reply_text(msg,parse_mode='HTML')

async def _bb_real_problem_scan(update, context):
    # This is an optional fictional in-group support layer. It never diagnoses
    # a real medical/legal problem and never claims to replace a professional.
    if not update.message or update.message.chat.type not in ('group','supergroup'): return
    text=(update.message.text or '').strip()
    if not text or len(text)<12: return
    triggers={'کمک','مشکل دارم','مشکل','گیر کردم','نمی‌تونم','راهنمایی می‌خوام'}
    if not any(x in text for x in triggers): return
    uid=update.effective_user.id; cid=update.effective_chat.id
    _bb_job_pro_schema()
    DB.execute("INSERT INTO bb_real_help_requests(chat_id,user_id,category,status,created_at) VALUES(?,?,?,?,?)",(cid,uid,'general','open',int(time.time())))
    await update.message.reply_text('🆘 اگر منظورت یک مشکل واقعی است، این بخش فقط می‌تواند مسیر کمک را پیشنهاد کند و تشخیص یا درمان حرفه‌ای انجام نمی‌دهد.\n\nاگر منظورت مشکل داخل بازی است، «مراجعه» را بزن تا یکی از متخصص‌های شغلی بازی برایت مرحله حل مشکل بسازد.',reply_markup=InlineKeyboardMarkup([[btn('🧩 مراجعه','jobhelp:open')]]))

