    q=update.callback_query; await q.answer()
    await q.message.reply_text('🧩 مراجعه به متخصص بازی\n\nیکی از بخش‌ها را انتخاب کن:',reply_markup=InlineKeyboardMarkup([[btn('🏥 پزشک بازی','jobhelp:doctor'),btn('⚖️ وکیل بازی','jobhelp:lawyer')],[btn('🏦 بانکدار بازی','jobhelp:banker'),btn('🧵 خیاط بازی','jobhelp:tailor')]]))

