def _bb_job_design_catalog():
    return {k:{'name':v[0],'education':v[1],'skill':v[2],'weekly_pay':v[3],'client':v[4],'tasks':_bb_job_task_types(k)} for k,v in _BB_JOB_PROFESSIONS.items()}

async def _bb_register_job_pro_handlers(application):
    _bb_job_pro_schema()
    application.add_handler(CallbackQueryHandler(_bb_real_help_open,pattern=r'^jobhelp:open$'),group=-100001100)
    application.add_handler(CallbackQueryHandler(_bb_real_help_specialist,pattern=r'^jobhelp:(doctor|lawyer|banker|tailor)$'),group=-100001101)
    application.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_real_problem_scan),group=-100001102)

# Final registration for the professional fictional job engine.
_BB_BUILD_BEFORE_JOB_PRO = build_application
def build_application(token: str) -> Application:
    app = _BB_BUILD_BEFORE_JOB_PRO(token)
    async def _job_text_router(update, context):
        msg=update.effective_message
        t=(getattr(msg,'text','') or '').strip()
        n=normalize(t) if 'normalize' in globals() else t
        if n in {'شغل','کار','شغل من'}:
            await _bb_job_open(update,context); raise ApplicationHandlerStop
        if n.startswith('شغل '):
            wanted=n.split(None,1)[1].strip()
            aliases={v[0]:k for k,v in _BB_JOB_PROFESSIONS.items()}
            key=aliases.get(wanted)
            if key:
                await _bb_job_open(update,context,key); raise ApplicationHandlerStop
        if n in {'کار بعدی','کار امروز','کار کن'}:
            await _bb_job_work(update,context); raise ApplicationHandlerStop
        if n in {'حل کار','انجام کار'}:
            await _bb_job_resolve(update,context); raise ApplicationHandlerStop
        if n in {'راهنمای شغل','راهنمای کار'}:
            await msg.reply_text('💼 راهنمای شغل\n\nهر شغل مسیر تخصصی خودش را دارد؛ مشتری/مراجعه‌کننده می‌آید، مرحله کاری می‌گیری، مرحله را انجام می‌دهی و در پایان هفته حقوقت محاسبه می‌شود. برای شغل‌های تخصصی، تحصیلات و مهارت لازم است.')
            raise ApplicationHandlerStop
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_job_text_router),group=-100001050)
    return app


