# FINAL OWNER DESIGN STUDIO V3 — EXHAUSTIVE SOURCE SCAN + 3 PANELS
# =============================================================================
async def _bb_studio_scan_source_exhaustive_v3():
    """Scan the complete source for user-facing strings and button labels."""
    import ast
    path=Path(__file__)
    tree=ast.parse(path.read_text(encoding='utf-8'))
    seen=set()
    text_calls={'reply_text','edit_message_text','send_message','answer','reply_photo','send_photo','reply_animation','send_animation','edit_caption','reply_voice','send_voice','reply_sticker','send_sticker','reply_video','send_video','reply_document','send_document','edit_text'}
    button_calls={'btn','reply_btn','InlineKeyboardButton','KeyboardButton'}
    def literal_parts(node):
        if isinstance(node,ast.Constant) and isinstance(node.value,str): return [node.value]
        if isinstance(node,ast.JoinedStr):
            return [v.value for v in node.values if isinstance(v,ast.Constant) and isinstance(v.value,str)]
        return []
    async def add(value,kind,lineno):
        value=str(value or '')
        if not value.strip() or len(value.strip())<2: return
        if value.strip() in {'utf-8','HTML','rb','wb','r','w','a','default','defaultdict'}: return
        key=(kind,value)
        if key in seen:return
        seen.add(key)
        try: await _bb_studio_register_literal(value,kind,lineno,path.name)
        except Exception:
            try: await _bb_ui_register(value,kind=kind)
            except Exception: pass
    for n in ast.walk(tree):
        if not isinstance(n,ast.Call): continue
        fname=n.func.id if isinstance(n.func,ast.Name) else (n.func.attr if isinstance(n.func,ast.Attribute) else '')
        if fname in button_calls:
            if n.args:
                for value in literal_parts(n.args[0]): await add(value,'button',getattr(n,'lineno',0))
            for kw in n.keywords:
                if kw.arg=='text':
                    for value in literal_parts(kw.value): await add(value,'button',getattr(n,'lineno',0))
        if fname in text_calls:
            if n.args:
                for value in literal_parts(n.args[0]): await add(value,'text',getattr(n,'lineno',0))
            for kw in n.keywords:
                if kw.arg in {'text','caption'}:
                    for value in literal_parts(kw.value): await add(value,'text',getattr(n,'lineno',0))
    try: await _bb_register_final_design_catalog()
    except Exception: pass
    try: await _bb_ui_refresh()
    except Exception: pass
    return len(seen)

async def _bb_studio_v3_rows(kind,page=0,category=None,per=12):
    await _bb_studio_scan_source_exhaustive_v3()
    where=['kind=?']; params=[kind]
    if category: where.append('category=?'); params.append(category)
    clause=' AND '.join(where)
    total_row=await DBX.one(f'SELECT COUNT(*) c FROM bb_ui_texts WHERE {clause}',tuple(params))
    total=int(total_row['c'] or 0) if total_row else 0
    rows=await DBX.execute(f"SELECT key,original,custom,kind,category,source_line FROM bb_ui_texts WHERE {clause} ORDER BY CASE WHEN source_line>0 THEN source_line ELSE 999999 END, original LIMIT ? OFFSET ?",(*params,per,page*per),fetch=True)
    return rows,total

async def _bb_studio_v3_send_panel(update,context,kind,page=0,category=None,edit_query=None):
    q=edit_query
    if q: await q.answer()
    rows,total=await _bb_studio_v3_rows(kind,page,category)
    kb=[]
    for r in rows:
        prefix='🔘' if kind=='button' else '📝'
        shown=str(r['custom'] or r['original']).replace('\n',' ')
        label=shown[:48]+('…' if len(shown)>48 else '')
        kb.append([btn(prefix+' '+label,f'sv3:edit:{r["key"]}')])
    nav=[]
    if page>0: nav.append(btn('⬅️ قبلی',f'sv3:list:{kind}:{page-1}'+(f':{category}' if category else '')))
    if (page+1)*12<total: nav.append(btn('بعدی ➡️',f'sv3:list:{kind}:{page+1}'+(f':{category}' if category else '')))
    if nav: kb.append(nav)
    kb.append([btn('🔍 اسکن کامل از اول تا آخر','sv3:scan')])
    kb.append([btn('🔙 مرکز طراحی','sv3:home')])
    title='🔘 همه دکمه‌ها' if kind=='button' else '📝 همه متن‌ها'
    if category: title += f' — {_BB_UI_CATEGORIES.get(category,category)}'
    body=f'🎨 <b>{safe_text(title,120)}</b>\n\nنمایش {page*12+1 if total else 0} تا {min((page+1)*12,total)} از <b>{total}</b> مورد\nهر مورد از کل سورس فایل اسکن شده و قابل طراحی است.'
    if q: await q.edit_message_text(body,parse_mode='HTML',reply_markup=keyboard(kb))
    else: await update.effective_message.reply_text(body,parse_mode='HTML',reply_markup=keyboard(kb))

async def _bb_studio_v3_home(update,context,q=None):
    await _bb_studio_scan_source_exhaustive_v3()
    rows=await DBX.execute('SELECT kind,COUNT(*) n FROM bb_ui_texts GROUP BY kind',fetch=True)
    stats={str(r['kind']):int(r['n'] or 0) for r in rows}; total=stats.get('text',0)+stats.get('button',0)
    categories=[]
    for k,v in _BB_UI_CATEGORIES.items():
        rr=await DBX.one('SELECT COUNT(*) c FROM bb_ui_texts WHERE category=?',(k,)); categories.append((k,int(rr['c'] or 0) if rr else 0,v))
    kb=[
        [btn('📝 همه متن‌ها','sv3:list:text:0'),btn('🔘 همه دکمه‌ها','sv3:list:button:0')],
        [btn('🔍 اسکن کامل خط اول تا آخر','sv3:scan'),btn('📊 پوشش کامل','sv3:coverage')],
        [btn('💼 شغل و تحصیلات','sv3:cat:career:0'),btn('💐 عقد و عروسی','sv3:cat:wedding:0')],
        [btn('🎟 قرعه‌کشی','sv3:cat:raffle:0'),btn('👨‍👩‍👧 خانواده','sv3:cat:family:0')],
        [btn('💍 زندگی و ازدواج','sv3:cat:life:0'),btn('🎵 موزیکال','sv3:cat:music:0')],
        [btn('📥 دانلودر','sv3:cat:downloader:0'),btn('👥 مدیریت گروه','sv3:cat:group:0')],
        [btn('💎 VIP','sv3:cat:vip:0'),btn('🎮 بازی‌ها','sv3:cat:games:0')],
    ]
    body=('🎨 <b>مرکز طراحی کامل V3</b>\n\n🔎 کل فایل از <b>خط اول تا خط آخر</b> اسکن می‌شود؛ متن‌ها و دکمه‌های قابل تشخیص ثبت می‌شوند.\n'
          f'📝 متن‌ها: <b>{stats.get("text",0)}</b>\n🔘 دکمه‌ها: <b>{stats.get("button",0)}</b>\n📦 مجموع: <b>{total}</b>\n\n'
          '🎨 طراحی فقط ظاهر، عنوان و متن را عوض می‌کند؛ callback، لینک و منطق اجرا دست‌نخورده می‌ماند.')
    if q: await q.edit_message_text(body,parse_mode='HTML',reply_markup=keyboard(kb))
    else: await update.effective_message.reply_text(body,parse_mode='HTML',reply_markup=keyboard(kb))

async def _bb_studio_v3_callback(update,context):
    q=getattr(update,'callback_query',None); d=str(getattr(q,'data','') or '') if q else ''
    if not d.startswith('sv3:'): return False
    if not await _bb_owner_gate(update): await q.answer('⛔ فقط مالک یا ادمین مرکزی ربات.',show_alert=True); return True
    if d=='sv3:home': await _bb_studio_v3_home(update,context,q); return True
    if d=='sv3:scan':
        n=await _bb_studio_scan_source_exhaustive_v3(); await q.answer(f'اسکن کامل انجام شد: {n} مورد',show_alert=True); await _bb_studio_v3_home(update,context,q); return True
    if d=='sv3:coverage':
        await _bb_studio_scan_source_exhaustive_v3(); rows=await DBX.execute('SELECT kind,COUNT(*) n FROM bb_ui_texts GROUP BY kind',fetch=True); stats={str(r['kind']):int(r['n'] or 0) for r in rows}
        await q.answer(); await q.edit_message_text(f'📊 <b>پوشش کامل طراحی</b>\n\n📝 متن: <b>{stats.get("text",0)}</b>\n🔘 دکمه: <b>{stats.get("button",0)}</b>\n📦 مجموع: <b>{sum(stats.values())}</b>\n\n🔎 اسکن از خط اول تا آخر فایل انجام شده است.',parse_mode='HTML',reply_markup=keyboard([[btn('🔍 اسکن دوباره','sv3:scan')],[btn('🔙 مرکز طراحی','sv3:home')]])); return True
    if d.startswith('sv3:list:'):
        p=d.split(':'); kind=p[2]; page=int(p[3]); cat=p[4] if len(p)>4 else None
        if kind not in {'text','button'}: return True
        await _bb_studio_v3_send_panel(update,context,kind,page,cat,q); return True
    if d.startswith('sv3:cat:'):
        p=d.split(':'); cat=p[2]; page=int(p[3]); await _bb_studio_v3_send_panel(update,context,'text',page,cat,q); return True
    if d.startswith('sv3:edit:'):
        key=d.split(':',2)[2]; r=await DBX.one('SELECT original,custom,kind,category FROM bb_ui_texts WHERE key=?',(key,))
        if not r: await q.answer('این مورد دیگر در فهرست نیست.',show_alert=True); return True
        context.user_data['sv3_edit']=key; await q.answer()
        await q.edit_message_text('✏️ <b>طراحی دقیق این مورد</b>\n\nنوع: <b>'+('دکمه' if r['kind']=='button' else 'متن')+'</b>\nبخش: <b>'+safe_text(_BB_UI_CATEGORIES.get(r['category'],r['category']),100)+'</b>\n\nفعلی:\n<code>'+safe_text(r['custom'] or r['original'],2200)+'</code>\n\nمتن جدید را بفرست.\nبرای برگشت به متن اصلی: <code>اصلی</code>\nبرای ایموجی پرمیوم: <code>emoji 123456</code>\nبرای حذف ایموجی: <code>emoji off</code>',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 برگشت','sv3:home')]])); return True
    return True

async def _bb_studio_v3_message(update,context):
    if not await _bb_owner_gate(update): return False
    key=getattr(context,'user_data',{}).pop('sv3_edit',None); msg=getattr(update,'effective_message',None)
    if not key or not msg or not getattr(msg,'text',None): return False
    raw=str(msg.text).strip(); row=await DBX.one('SELECT original,kind FROM bb_ui_texts WHERE key=?',(key,))
    if not row:return False
    if raw.lower()=='اصلی': raw=''
    elif raw.lower().startswith('emoji '):
        val=raw.split(None,1)[1].strip()
        if val.lower()=='off': await DBX.execute('UPDATE bb_ui_texts SET emoji_id=?,updated_at=? WHERE key=?',('',now_ts(),key)); await _bb_ui_refresh(); await msg.reply_text('✅ ایموجی پرمیوم این مورد حذف شد.'); return True
        if val.isdigit(): await DBX.execute('UPDATE bb_ui_texts SET emoji_id=?,updated_at=? WHERE key=?',(val,now_ts(),key)); await _bb_ui_refresh(); await msg.reply_text('✨ ایموجی پرمیوم ذخیره شد.'); return True
        await msg.reply_text('⚠️ شناسه ایموجی معتبر نیست.'); return True
    await DBX.execute('UPDATE bb_ui_texts SET custom=?,updated_at=? WHERE key=?',(raw,now_ts(),key)); await _bb_ui_refresh(); await msg.reply_text('✅ طراحی ذخیره شد؛ عملکرد و callback این مورد تغییر نکرد.'); return True

_BB_V3_OLD_BTN=btn
def btn(text,data=None,url=None,style=None):
    chosen=style or _button_style(text,data)
    shown=_bb_studio_apply_text(text) if '_bb_studio_apply_text' in globals() else str(text or '')
    shown=_bb_no_premium_markup(shown) if '_bb_no_premium_markup' in globals() else shown
    kwargs={'text':shown,'callback_data':data,'url':url,'style':chosen}
    eid=_BB_UI_EMOJI_CACHE.get(('button',str(text or ''))) or _BB_UI_EMOJI_CACHE.get(('button',str(shown or '')))
    if eid: kwargs['icon_custom_emoji_id']=str(eid)
    try:return InlineKeyboardButton(**kwargs)
    except TypeError:
        kwargs.pop('icon_custom_emoji_id',None)
        try:return InlineKeyboardButton(**kwargs)
        except TypeError: kwargs.pop('style',None); return InlineKeyboardButton(**kwargs)

async def _bb_design_v3_command(update,context):
    if not await _bb_owner_gate(update): return
    await _bb_studio_v3_home(update,context,None)
    await _bb_studio_v3_send_panel(update,context,'text',0,None,None)
    await _bb_studio_v3_send_panel(update,context,'button',0,None,None)

_BB_BUILD_BEFORE_DESIGN_V3=build_application
def build_application(token=None):
    app=_BB_BUILD_BEFORE_DESIGN_V3(token)
    app.add_handler(MessageHandler(filters.Regex(r'^\s*طراحی\s*$'),_bb_design_v3_command),group=-100002000)
    app.add_handler(CallbackQueryHandler(_bb_studio_v3_callback,pattern=r'^sv3:'),group=-100001999)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_studio_v3_message),group=-100001998)
    return app



