async def _bb_final_api_schema_sync():
    """Create the complete API catalog and migrate values between stores."""
    try:
        await _bb_studio_v2_schema()
        for key,_,_,_ in _BB_API_CATALOG_FINAL:
            await DBX.execute('INSERT OR IGNORE INTO bb_api_settings(key,value,updated_at) VALUES(?,?,?)',(key,'',0))
    except Exception as exc:
        log.warning('API catalog schema sync failed: %r',exc)

# Centralize old/new API stores: anything entered in /apis or Owner Studio is
# mirrored into bot_pro_settings, while old environment variables remain a
# fallback. This makes legacy and new features consume the same credentials.
_BB_API_GET_BEFORE_FINAL = _bb_api_get
_BB_API_SET_BEFORE_FINAL = _bb_api_set
async def _bb_api_get(key, default=''):
    key=str(key)
    try:
        value=await _BB_API_GET_BEFORE_FINAL(key,'')
        if value: return value
    except Exception: pass
    try:
        if '_bb_pro_get' in globals():
            value=await _bb_pro_get(key,'')
            if value: return value
    except Exception: pass
    return str(os.getenv(key,default) or default)

async def _bb_api_set(key,value):
    key=str(key).strip(); value=str(value or '').strip()
    await _BB_API_SET_BEFORE_FINAL(key,value)
    try:
        if '_bb_pro_set' in globals(): await _bb_pro_set(key,value)
    except Exception: pass

# Real native button style cache. Telegram currently exposes three native
# visual styles; arbitrary HEX colors are not a Bot API feature, so the owner
# chooses among primary(blue), success(green), danger(red), or automatic.
_BB_UI_STYLE_CACHE = globals().get('_BB_UI_STYLE_CACHE',{})
_BB_UI_REFRESH_BEFORE_STYLE = _bb_ui_refresh
async def _bb_ui_refresh():
    await _BB_UI_REFRESH_BEFORE_STYLE()
    try:
        rows=await DBX.execute('SELECT original,button_style FROM bb_ui_texts WHERE kind="button"',fetch=True)
        _BB_UI_STYLE_CACHE.clear()
        for r in rows:
            style=str(r['button_style'] or '').strip()
            if style in {'primary','success','danger'}:
                _BB_UI_STYLE_CACHE[str(r['original'])]=style
    except Exception as exc:
        log.debug('button style cache refresh: %r',exc)

async def _bb_ui_style_schema():
    try:
        await _bb_ui_schema()
        try: await DBX.execute("ALTER TABLE bb_ui_texts ADD COLUMN button_style TEXT DEFAULT ''")
        except Exception: pass
        await _bb_ui_refresh()
    except Exception as exc:
        log.debug('button style schema failed: %r',exc)

# btn() consults the owner-selected native style, but an explicit style in the
# code still wins. Existing callbacks, URLs and functionality remain untouched.
_BB_BTN_BEFORE_OWNER_STYLE = btn
def btn(text,data=None,url=None,style=None):
    original=str(text or '')
    chosen=style or _BB_UI_STYLE_CACHE.get(original) or _button_style(text,data)
    return _BB_BTN_BEFORE_OWNER_STYLE(text,data=data,url=url,style=chosen)

async def _bb_design_variables_schema_and_seed():
    await _bb_final_api_schema_sync()
    await _bb_ui_style_schema()
    # Register a small visible variable-help record for every section. These
    # are ordinary editable design texts, so the owner can also customize the
    # wording of the variable documentation itself.
    for cat,vars_ in _BB_DESIGN_SECTION_VARIABLES.items():
        title=f'🧩 متغیرهای طراحی — {cat}'
        body=' | '.join(vars_)
        try:
            await _bb_ui_register(title,category=cat,kind='text')
            await _bb_ui_register(body,category=cat,kind='text')
        except Exception: pass

