# Single source of truth for account settings, cleanup-security linkage,
# help/force-join/ads design and independent 0..9 digit sets.

async def _bb_final_design_runtime_schema():
    await _bb_final_api_schema_sync()
    await _bb_pro_schema()
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_digit_sets(
        set_key TEXT NOT NULL,
        digit INTEGER NOT NULL,
        emoji_id TEXT DEFAULT '',
        label TEXT DEFAULT '',
        description TEXT DEFAULT '',
        updated_at INTEGER DEFAULT 0,
        PRIMARY KEY(set_key,digit)
    )''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_digit_context_rules(
        section TEXT NOT NULL,
        target_kind TEXT NOT NULL,
        set_pool TEXT DEFAULT 'text_default',
        randomize INTEGER DEFAULT 0,
        updated_at INTEGER DEFAULT 0,
        PRIMARY KEY(section,target_kind)
    )''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_digit_set_meta(
        set_key TEXT PRIMARY KEY,
        title TEXT DEFAULT '',
        description TEXT DEFAULT '',
        target_kind TEXT DEFAULT 'text',
        updated_at INTEGER DEFAULT 0
    )''')
    defaults=[
        ('text_default','ارقام متن','اعداد مخصوص متن','text'),
        ('button_default','ارقام دکمه','اعداد مخصوص دکمه','button'),
        ('stats_default','ارقام آمار','اعداد مخصوص آمار و پروفایل','text'),
        ('cleanup_default','ارقام گزارش پاکسازی','اعداد مخصوص گزارش پاکسازی','text'),
        ('random_text','چرخشی متن','مجموعه چرخشی متن','text'),
        ('random_button','چرخشی دکمه','مجموعه چرخشی دکمه','button'),
    ]
    for sk,title,desc,kind in defaults:
        await DBX.execute('INSERT OR IGNORE INTO bb_digit_set_meta(set_key,title,description,target_kind,updated_at) VALUES(?,?,?,?,?)',(sk,title,desc,kind,now_ts()))
        for d in range(10):
            await DBX.execute('INSERT OR IGNORE INTO bb_digit_sets(set_key,digit,emoji_id,label,description,updated_at) VALUES(?,?,?,?,?,?)',(sk,d,'',str(d),f'{title} — رقم {d}',now_ts()))
    sections=set(_BB_DESIGN_SECTION_VARIABLES)|set(_BB_UI_CATEGORIES)|{'security','cleanup','forcejoin','ads','music_account','cleanup_account','digits'}
    for section in sections:
        await DBX.execute('INSERT OR IGNORE INTO bb_digit_context_rules(section,target_kind,set_pool,randomize,updated_at) VALUES(?,?,?,?,?)',(section,'text','text_default',0,now_ts()))
        await DBX.execute('INSERT OR IGNORE INTO bb_digit_context_rules(section,target_kind,set_pool,randomize,updated_at) VALUES(?,?,?,?,?)',(section,'button','button_default',0,now_ts()))

async def _bb_final_sync_account_settings():
    try:
        music_phone=await _bb_api_get('MUSIC_USER_PHONE','')
        music_session=await _bb_api_get('MUSIC_USER_SESSION','')
        if music_phone:
            await _bb_set_music_setting('MUSIC_USER_PHONE',music_phone); globals()['MUSIC_USER_PHONE']=music_phone
        if music_session:
            await _bb_set_music_setting('MUSIC_USER_SESSION',music_session); globals()['MUSIC_USER_SESSION']=music_session
        cleanup_phone=await _bb_api_get('CLEANUP_USER_PHONE','')
        cleanup_session=await _bb_api_get('CLEANUP_USER_SESSION','')
        if cleanup_phone or cleanup_session:
            await _bb_cleanup_save(phone=cleanup_phone or None,session=cleanup_session or None)
            if cleanup_phone: globals()['CLEANUP_USER_PHONE']=cleanup_phone
            if cleanup_session: globals()['CLEANUP_USER_SESSION']=cleanup_session
    except Exception as exc:
        log.debug('account settings sync: %r',exc)

async def _bb_digit_rule(section,target_kind):
    await _bb_final_design_runtime_schema()
    r=await DBX.one('SELECT set_pool,randomize FROM bb_digit_context_rules WHERE section=? AND target_kind=?',(str(section),str(target_kind)))
    pool=[x.strip() for x in str((r['set_pool'] if r else '') or '').split(',') if x.strip()]
    if not pool: pool=['text_default' if target_kind=='text' else 'button_default']
    return (_bb_random.choice(pool) if bool(r and int(r['randomize'] or 0)) else pool[0])

async def _bb_digit_map_for(section,target_kind='text'):
    sk=await _bb_digit_rule(section,target_kind)
    rows=await DBX.execute('SELECT digit,emoji_id FROM bb_digit_sets WHERE set_key=? ORDER BY digit',(sk,),fetch=True)
    return sk,{int(r['digit']):str(r['emoji_id'] or '') for r in rows}

_BB_DIGIT_BUTTON_ICON_CACHE={}
async def _bb_refresh_digit_button_icons():
    try:
        rows=await DBX.execute("SELECT set_key,digit,emoji_id FROM bb_digit_sets WHERE emoji_id<>'' ORDER BY set_key,digit",fetch=True)
        _BB_DIGIT_BUTTON_ICON_CACHE.clear()
        for r in rows or []:
            _BB_DIGIT_BUTTON_ICON_CACHE.setdefault(int(r['digit']),[]).append(str(r['emoji_id']))
    except Exception: pass

def _bb_digit_section_from_text(text):
    t=normalize(str(text or ''))
    for sec,words in [
        ('cleanup',('پاکسازی','حذف موفق','بررسی‌شده','ناموفق')),
        ('security',('امنیت','اخطار','ضدفlood','ضدتکرار','حذف امنیتی')),
        ('music',('موزیک','آهنگ','صف پخش','پخش')),
        ('forcejoin',('جوین اجباری','عضویت اجباری')),
        ('ads',('تبلیغ','تبلیغات')),
        ('help',('راهنما','دستورات','کمک')),
        ('profile',('پروفایل','xp','پیام امروز')),
        ('stats',('آمار','رتبه','امتیاز')),
    ]:
        if any(w in t for w in words): return sec
    return 'other'

async def _bb_render_design_digits(text,section=None,target_kind='text'):
    if not text:return text
    _,mp=await _bb_digit_map_for(section or _bb_digit_section_from_text(text),target_kind)
    if not any(mp.values()): return str(text)
    return ''.join(f'<tg-emoji emoji-id="{mp[int(ch)]}">{ch}</tg-emoji>' if '0'<=ch<='9' and mp.get(int(ch)) else ch for ch in str(text))

