        await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('🎵 تنظیمات موزیکال','own6:music'),btn('▶️ ورود موزیکال','sv3:connect:music')],[btn('🧹 اتصال پاکسازی','sv3:connect:cleanup')],[btn('🔑 APIها','sv3:apis')],[btn('🔄 همگام‌سازی حساب‌ها','sv3:accounts')],[btn('🔙 مرکز طراحی','sv3:home')]])); return True
