    for cat in allcats:
        vals=list(dict.fromkeys(list(_BB_DESIGN_SECTION_VARIABLES.get(cat,[]))+generic)); _BB_DESIGN_SECTION_VARIABLES[cat]=vals
        await _bb_ui_register(f'🧩 متغیرهای طراحی — {cat}',category=cat,kind='text'); await _bb_ui_register(' | '.join(vals),category=cat,kind='text')
    for text,cat in [('راهنمای شیشه‌ای بیل‌بیلک','help'),('گزارش کامل پاکسازی','cleanup'),('گزارش حذف امنیتی','security'),('عضویت اجباری فعال است','forcejoin'),('تبلیغات PV','ads'),('تنظیمات اتصال موزیکال','music_account'),('اکانت پاکسازی','cleanup_account')]: await _bb_ui_register(text,category=cat,kind='text')

