async def _bb_final_design_router(update,context):
    q=getattr(update,'callback_query',None); d=str(q.data or '') if q else ''
    if not q or not d.startswith('sv3:'): return False
    if d in {'sv3:digits','sv3:digitnew','sv3:digitrules','sv3:accounts'} or d.startswith(('sv3:connect:','sv3:digitnewkind:','sv3:digitset:','sv3:digit:','sv3:digitassign:','sv3:digitassign2:','sv3:digit-random:')): return await _bb_final_design_extra_callback(update,context)
    if d in {'sv3:guide_design','sv3:cleanup_design','sv3:force_design','sv3:ads_design','sv3:music_design'}:
        mapping={'sv3:guide_design':('help','📚 طراحی راهنما'),'sv3:cleanup_design':('cleanup','🧹 طراحی گزارش پاکسازی'),'sv3:force_design':('forcejoin','🔐 طراحی جوین اجباری'),'sv3:ads_design':('ads','📢 طراحی تبلیغات PV'),'sv3:music_design':('music','🎵 طراحی موزیکال')}; cat,title=mapping[d]
        if not await _bb_owner_gate(update): await q.answer('⛔ دسترسی ندارید.',show_alert=True); return True
        await _bb_final_seed_all_design_sections(); await _bb_final_design_subpanel(q,cat,title); return True
    return False

async def _bb_final_design_digit_text(update,context):
    msg=getattr(update,'effective_message',None)
    if not msg or not getattr(msg,'text',None) or not await _bb_owner_gate(update): return False
    key=getattr(context,'user_data',{}).pop('sv3_api_key',None)
    if key:
        raw=str(msg.text).strip(); value='' if normalize(raw) in {'خالی','پاک','حذف'} else raw
        if key in {'MUSIC_USER_PHONE','CLEANUP_USER_PHONE'}:
            value=value.replace(' ','').replace('-','')
            if value and not re.fullmatch(r'\+?[0-9]{7,20}',value): await msg.reply_text('❌ شماره معتبر نیست.'); return True
        if key=='MUSIC_USER_PHONE': await _bb_set_music_setting(key,value); globals()['MUSIC_USER_PHONE']=value
        elif key=='MUSIC_USER_SESSION': await _bb_set_music_setting(key,value); globals()['MUSIC_USER_SESSION']=value
        elif key=='CLEANUP_USER_PHONE': await _bb_cleanup_save(phone=value); globals()['CLEANUP_USER_PHONE']=value
        elif key=='CLEANUP_USER_SESSION': await _bb_cleanup_save(session=value); globals()['CLEANUP_USER_SESSION']=value
        else: await _bb_api_set(key,value)
        await msg.reply_text('✅ مقدار ثبت شد و با تنظیم واقعی همان اکانت همگام شد.'); return True
    inp=getattr(context,'user_data',{}).pop('bb_digit_input',None)
    if inp:
        sk,digit=inp; raw=str(msg.text).strip(); eid='' if normalize(raw) in {'خالی','پاک','حذف','off'} else _bb_custom_emoji_id_from_message(msg)
        if normalize(raw) not in {'خالی','پاک','حذف','off'} and not eid: await msg.reply_text('⚠️ یک Custom Emoji واقعی بفرست.'); return True
        await DBX.execute('INSERT OR REPLACE INTO bb_digit_sets(set_key,digit,emoji_id,label,description,updated_at) VALUES(?,?,?,?,?,?)',(sk,int(digit),eid,str(digit),f'{sk} — رقم {digit}',now_ts())); await msg.reply_text(f'✅ رقم {digit} در مجموعه {safe_text(sk,80)} ثبت شد.'); return True
    if context.user_data.get('bb_digit_new')=='title':
        title=str(msg.text).strip()
        if normalize(title) in {'لغو','cancel'}: context.user_data.pop('bb_digit_new',None); return True
        slug=re.sub(r'[^a-zA-Z0-9_]+','_',title)[:30].strip('_') or 'custom'; sk='set_'+slug+'_'+str(now_ts())
        await DBX.execute('INSERT OR REPLACE INTO bb_digit_set_meta(set_key,title,description,target_kind,updated_at) VALUES(?,?,?,?,?)',(sk,title,'مجموعه ارقام ساخته‌شده توسط مالک','text',now_ts()))
        for d in range(10): await DBX.execute('INSERT OR IGNORE INTO bb_digit_sets(set_key,digit,emoji_id,label,description,updated_at) VALUES(?,?,?,?,?,?)',(sk,d,'',str(d),f'{title} — رقم {d}',now_ts()))
        context.user_data.pop('bb_digit_new',None); await msg.reply_text(f'✅ مجموعه «{safe_text(title,80)}» ساخته شد.'); return True
    return False


_BB_OLD_STUDIO_V3_MESSAGE_LIVE_DESIGN=globals().get('_bb_studio_v3_message')
async def _bb_studio_v3_message(update,context):
    key=getattr(context,'user_data',{}).get('sv3_edit')
    if key:
        row=await DBX.one('SELECT original,kind,category FROM bb_ui_texts WHERE key=?',(key,))
        msg=getattr(update,'effective_message',None)
        if row and msg and getattr(msg,'text',None):
            raw=str(msg.text).strip()
            if raw.lower()=='اصلی': raw=''
            cat=str(row['category'] or ''); original=str(row['original'] or '')
            try:
                if cat=='help' or 'راهنمای شیشه‌ای' in original: await _bb_global_message_set('guide_text',raw)
                elif cat=='cleanup' and ('گزارش کامل پاکسازی' in original or 'cleanup_scanned' in original): await _bb_global_message_set('cleanup_report_text',raw)
                elif cat=='forcejoin' or 'عضویت اجباری فعال' in original: await _bb_global_message_set('pv_forcejoin_text',raw)
                elif cat=='security': await _bb_global_message_set('security_report_text',raw)
            except Exception as exc: log.debug('live design sync failed: %r',exc)
    if _BB_OLD_STUDIO_V3_MESSAGE_LIVE_DESIGN: return await _BB_OLD_STUDIO_V3_MESSAGE_LIVE_DESIGN(update,context)
    return False

