_BB_BTN_WITH_DIGIT_ICON_OLD=btn
def btn(text,data=None,url=None,style=None):
    shown=str(text or '')
    icon=None
    try:
        digits=[int(ch) for ch in shown if '0'<=ch<='9']
        if digits:
            pool=_BB_DIGIT_BUTTON_ICON_CACHE.get(digits[0],[])
            if pool: icon=random.choice(pool)
    except Exception: pass
    if icon:
        try:
            b=_BB_BTN_WITH_DIGIT_ICON_OLD(shown,data=data,url=url,style=style)
            b.icon_custom_emoji_id=str(icon)
            return b
        except Exception: pass
    return _BB_BTN_WITH_DIGIT_ICON_OLD(shown,data=data,url=url,style=style)

