async def _bb_trivia_schema():
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_trivia_settings(
        chat_id INTEGER PRIMARY KEY,
        category TEXT DEFAULT 'general', question_count INTEGER DEFAULT 5,
        answer_seconds INTEGER DEFAULT 15, registration_seconds INTEGER DEFAULT 60,
        difficulty TEXT DEFAULT 'mixed', updated_at INTEGER DEFAULT 0)''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_trivia_questions(
        id INTEGER PRIMARY KEY AUTOINCREMENT, category TEXT NOT NULL, difficulty TEXT NOT NULL,
        question TEXT NOT NULL, options_json TEXT NOT NULL, answer_index INTEGER NOT NULL,
        enabled INTEGER DEFAULT 1, updated_at INTEGER DEFAULT 0)''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_trivia_games(
        id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id INTEGER NOT NULL, state TEXT NOT NULL,
        category TEXT, difficulty TEXT, question_count INTEGER, answer_seconds INTEGER,
        registration_deadline INTEGER DEFAULT 0, current_index INTEGER DEFAULT -1,
        current_question_id INTEGER DEFAULT 0, message_id INTEGER DEFAULT 0,
        created_by INTEGER DEFAULT 0, created_at INTEGER DEFAULT 0, updated_at INTEGER DEFAULT 0)''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_trivia_players(
        game_id INTEGER NOT NULL, user_id INTEGER NOT NULL, name TEXT DEFAULT '', username TEXT DEFAULT '',
        score INTEGER DEFAULT 0, joined_at INTEGER DEFAULT 0, PRIMARY KEY(game_id,user_id))''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_trivia_answers(
        game_id INTEGER NOT NULL, question_index INTEGER NOT NULL, user_id INTEGER NOT NULL,
        option_index INTEGER NOT NULL, correct INTEGER DEFAULT 0, answered_at INTEGER DEFAULT 0,
        PRIMARY KEY(game_id,question_index,user_id))''')
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_trivia_game_questions(
        game_id INTEGER NOT NULL, position INTEGER NOT NULL, question_id INTEGER NOT NULL,
        PRIMARY KEY(game_id,position))''')
    for row in BB_TRIVIA_QUESTIONS:
        cat,diff,q,opts,ans=row
        exists=await DBX.one('SELECT id FROM bb_trivia_questions WHERE category=? AND difficulty=? AND question=?',(cat,diff,q))
        if not exists:
            await DBX.execute('INSERT INTO bb_trivia_questions(category,difficulty,question,options_json,answer_index,updated_at) VALUES(?,?,?,?,?,?)',(cat,diff,q,json.dumps(opts,ensure_ascii=False),ans,now_ts()))

async def _bb_trivia_get_settings(chat_id):
    await _bb_trivia_schema()
    r=await DBX.one('SELECT * FROM bb_trivia_settings WHERE chat_id=?',(int(chat_id),))
    if not r:
        await DBX.execute('INSERT INTO bb_trivia_settings(chat_id,category,question_count,answer_seconds,registration_seconds,difficulty,updated_at) VALUES(?,?,?,?,?,?,?)',(chat_id,BB_TRIVIA_DEFAULTS['category'],5,15,60,'mixed',now_ts()))
        r=await DBX.one('SELECT * FROM bb_trivia_settings WHERE chat_id=?',(int(chat_id),))
    return r

