async def _bb_trivia_active(chat_id):
    # Registration timers live in JobQueue and are lost on a process restart.
    # Never let an expired registration block a new game.
    row=await DBX.one("SELECT * FROM bb_trivia_games WHERE chat_id=? AND state IN ('registering','playing') ORDER BY id DESC LIMIT 1",(chat_id,))
    if not row: return None
    now=now_ts()
    state=str(row['state'] or '')
    if state=='registering' and int(row['registration_deadline'] or 0) <= now:
        await DBX.execute('UPDATE bb_trivia_games SET state="cancelled",updated_at=? WHERE id=?',(now,row['id']))
        return None
    # A playing room abandoned by a crashed/restarted process must not become
    # a permanent lock. Normal games are much shorter than this window.
    if state=='playing' and now-int(row['updated_at'] or row['created_at'] or now) > 24*3600:
        await DBX.execute('UPDATE bb_trivia_games SET state="cancelled",updated_at=? WHERE id=?',(now,row['id']))
        return None
    return row

async def _bb_trivia_scoreboard(game_id):
    rows=await DBX.execute('SELECT user_id,name,score FROM bb_trivia_players WHERE game_id=? ORDER BY score DESC,joined_at ASC',(game_id,),fetch=True)
    if not rows: return '—'
    return '\n'.join(f'👤 {i}. <b>{_bb_html.escape(str(r["name"] or "کاربر"))}</b> — <b>{int(r["score"] or 0)}</b>' for i,r in enumerate(rows,1))

async def _bb_trivia_question_pool(category,difficulty,count):
    where='enabled=1 AND category=?'; params=[category]
    if difficulty!='mixed': where+=' AND difficulty=?'; params.append(difficulty)
    rows=await DBX.execute(f'SELECT * FROM bb_trivia_questions WHERE {where} ORDER BY RANDOM()',tuple(params),fetch=True)
    if len(rows)<count:
        rows2=await DBX.execute('SELECT * FROM bb_trivia_questions WHERE enabled=1 AND category=? ORDER BY RANDOM()',(category,),fetch=True)
        seen={int(r['id']) for r in rows}; rows=list(rows)+[r for r in rows2 if int(r['id']) not in seen]
    if len(rows)<count:
        rows3=await DBX.execute('SELECT * FROM bb_trivia_questions WHERE enabled=1 ORDER BY RANDOM()',fetch=True)
        seen={int(r['id']) for r in rows}; rows+= [r for r in rows3 if int(r['id']) not in seen]
    return rows[:count]

