async def _bb_ludo_menu(update,context):
    if not update.effective_chat or update.effective_chat.type=='private':
        await update.effective_message.reply_text('🎲 لودو برای گروه طراحی شده؛ دستور را داخل گروه اجرا کن.')
        return
    if not await local_admin(update, update.effective_user.id):
        await update.effective_message.reply_text('⛔ شروع و تنظیم لودو فقط توسط ادمین‌های گروه انجام می‌شود.')
        return
    await _bb_ludo_schema(); await _bb_ludo_design_seed()
    s=await _bb_ludo_get_settings(update.effective_chat.id)
    text=(f'🎲 <b>لودو بیل‌بیلک</b>\n\n'
          f'👥 حداکثر بازیکن: <b>{int(s["max_players"])}</b>\n'
          f'⏳ زمان ثبت‌نام: <b>{int(s["registration_seconds"])} ثانیه</b>\n\n'
          f'ادمین بازی را باز می‌کند؛ خود ادمین لازم نیست بازیکن باشد.')
    kb=[[btn('👥 حداکثر بازیکن',f'ludo:max:{update.effective_chat.id}')],[btn('⏳ زمان ثبت‌نام',f'ludo:reg:{update.effective_chat.id}')],[btn('🚀 شروع ثبت‌نام',f'ludo:register:{update.effective_chat.id}')],[btn('📚 راهنمای کامل لودو',f'ludo:guide:{update.effective_chat.id}')]]
    await update.effective_message.reply_text(text,parse_mode='HTML',reply_markup=keyboard(kb))

async def _bb_ludo_start_registration(q,context,chat_id):
    if not await local_admin(type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat})(),q.from_user.id):
        await q.answer('⛔ فقط ادمین می‌تواند لودو را شروع کند.',show_alert=True); return
    active=await _bb_ludo_active(chat_id)
    if active: await q.answer('⚠️ یک لودو یا ثبت‌نام فعال است.',show_alert=True); return
    s=await _bb_ludo_get_settings(chat_id); deadline=now_ts()+int(s['registration_seconds'])
    cur=await DBX.execute('INSERT INTO bb_ludo_games(chat_id,state,max_players,registration_deadline,current_turn,turn_color,dice,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)',(chat_id,'registering',int(s['max_players']),deadline,0,'red',0,q.from_user.id,now_ts(),now_ts()))
    gid=int(cur.lastrowid)
    text=await _bb_ludo_render(gid,f'⏳ ثبت‌نام تا <b>{int(s["registration_seconds"])} ثانیه</b> باز است.')
    msg=await q.message.edit_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('👥 ورود به لودو',f'ludo:join:{gid}')],[btn('❌ انصراف از ثبت‌نام',f'ludo:cancel:{gid}')]]))
    await DBX.execute('UPDATE bb_ludo_games SET message_id=? WHERE id=?',(msg.message_id,gid))
    if context.application.job_queue:
        context.application.job_queue.run_once(_bb_ludo_registration_timeout,int(s['registration_seconds']),data={'game_id':gid},name=f'ludo-register-{gid}')

async def _bb_ludo_join(q,context,gid):
    g=await DBX.one('SELECT * FROM bb_ludo_games WHERE id=?',(gid,))
    if not g or g['state']!='registering': await q.answer('ثبت‌نام بسته شده است.',show_alert=True); return
    players=await _bb_ludo_players(gid)
    if any(int(p['user_id'])==q.from_user.id for p in players): await q.answer('قبلاً وارد شده‌ای.',show_alert=True); return
    if len(players)>=int(g['max_players']): await q.answer('ظرفیت لودو تکمیل است.',show_alert=True); return
    used={str(p['color']) for p in players}; color=next((c for c in BB_LUDO_ORDER if c not in used),'red')
    await DBX.execute('INSERT INTO bb_ludo_players(game_id,user_id,name,username,color,score,joined_at) VALUES(?,?,?,?,?,?,?)',(gid,q.from_user.id,display_name(q.from_user),getattr(q.from_user,'username','') or '',color,0,now_ts()))
    for n in range(1,5): await DBX.execute('INSERT INTO bb_ludo_pieces(game_id,user_id,piece_no,position) VALUES(?,?,?,-1)',(gid,q.from_user.id,n))
    text=await _bb_ludo_render(gid,f'👥 ظرفیت: <b>{len(players)+1}/{int(g["max_players"])}</b>')
    await context.bot.edit_message_text(chat_id=g['chat_id'],message_id=g['message_id'],text=text,parse_mode='HTML',reply_markup=keyboard([[btn('👥 ورود به لودو',f'ludo:join:{gid}')],[btn('❌ انصراف از ثبت‌نام',f'ludo:cancel:{gid}')]]))

async def _bb_ludo_registration_timeout(context):
    gid=int(context.job.data['game_id'])
    g=await DBX.one('SELECT * FROM bb_ludo_games WHERE id=?',(gid,))
    if not g or g['state']!='registering': return
    players=await _bb_ludo_players(gid)
    if len(players)<2:
        await DBX.execute('UPDATE bb_ludo_games SET state="cancelled",updated_at=? WHERE id=?',(now_ts(),gid))
        try: await context.bot.edit_message_text(chat_id=g['chat_id'],message_id=g['message_id'],text='❌ <b>لودو لغو شد.</b>\n\nحداقل <b>۲ بازیکن</b> لازم بود.',parse_mode='HTML')
        except TelegramError: pass
        return
    await _bb_ludo_begin(context,gid)

async def _bb_ludo_begin(context,gid):
    g=await DBX.one('SELECT * FROM bb_ludo_games WHERE id=?',(gid,))
    if not g or g['state']!='registering': return
    players=await _bb_ludo_players(gid)
    if len(players)<2: return
    first=players[0]
    await DBX.execute('UPDATE bb_ludo_games SET state="playing",current_turn=0,turn_color=?,updated_at=? WHERE id=?',(first['color'],now_ts(),gid))
    text=await _bb_ludo_render(gid,'🚀 <b>بازی شروع شد!</b>\n🎲 اولین نوبت با بازیکن مشخص‌شده است.')
    try:
        await context.bot.edit_message_text(chat_id=g['chat_id'],message_id=g['message_id'],text=text,parse_mode='HTML',reply_markup=await _bb_ludo_keyboard(gid))
        try: await context.bot.pin_chat_message(g['chat_id'],g['message_id'],disable_notification=True)
        except TelegramError: pass
    except TelegramError: return

async def _bb_ludo_keyboard(gid):
    g=await DBX.one('SELECT * FROM bb_ludo_games WHERE id=?',(gid,))
    if not g: return keyboard([])
    players=await _bb_ludo_players(gid)
    if g['state']=='registering': return keyboard([[btn('👥 ورود به لودو',f'ludo:join:{gid}')],[btn('❌ انصراف از ثبت‌نام',f'ludo:cancel:{gid}')]])
    turn_user=next((int(p['user_id']) for p in players if str(p['color'])==str(g['turn_color'])),0)
    rows=[]
    if turn_user: rows.append([btn('🎲 ریختن تاس',f'ludo:dice:{gid}')])
    if int(g['dice'] or 0):
        rows.append([btn(f'🔘 مهره {i}',f'ludo:move:{gid}:{i}') for i in range(1,5)])
    rows += [[btn('🏁 پایان بازی',f'ludo:forceend:{gid}')],[btn('📚 راهنمای کامل لودو',f'ludo:guide:{g["chat_id"]}')]]
    return keyboard(rows)

async def _bb_ludo_dice(q,context,gid):
    g=await DBX.one('SELECT * FROM bb_ludo_games WHERE id=?',(gid,))
    if not g or g['state']!='playing': await q.answer('بازی فعال نیست.',show_alert=True); return
    players=await _bb_ludo_players(gid); p=next((p for p in players if str(p['color'])==str(g['turn_color'])),None)
    if not p or int(p['user_id'])!=q.from_user.id: await q.answer('⛔ الان نوبت تو نیست.',show_alert=True); return
    roll=random.randint(1,6); await DBX.execute('UPDATE bb_ludo_games SET dice=?,updated_at=? WHERE id=?',(roll,now_ts(),gid))
    await q.answer(f'🎲 تاس: {roll}')
    text=await _bb_ludo_render(gid,f'🎲 <b>{_bb_html.escape(str(p["name"]))}</b> تاس ریخت: <b>{roll}</b>\nمهره قابل حرکت را انتخاب کن.')
    await q.message.edit_text(text,parse_mode='HTML',reply_markup=await _bb_ludo_keyboard(gid))

async def _bb_ludo_move(q,context,gid,piece_no):
    g=await DBX.one('SELECT * FROM bb_ludo_games WHERE id=?',(gid,))
    if not g or g['state']!='playing': return
    players=await _bb_ludo_players(gid); p=next((p for p in players if str(p['color'])==str(g['turn_color'])),None)
    if not p or int(p['user_id'])!=q.from_user.id: await q.answer('⛔ الان نوبت تو نیست.',show_alert=True); return
    roll=int(g['dice'] or 0); piece_no=int(piece_no)
    row=await DBX.one('SELECT position FROM bb_ludo_pieces WHERE game_id=? AND user_id=? AND piece_no=?',(gid,p['user_id'],piece_no))
    if not row or roll<=0: await q.answer('اول تاس بینداز.',show_alert=True); return
    pos=int(row['position'])
    if pos<0:
        if roll!=6: await q.answer('برای آوردن مهره بیرون باید ۶ بیاید.',show_alert=True); return
        newpos=0
    else:
        newpos=pos+roll
        if newpos>57: await q.answer('این مهره با این تاس حرکت نمی‌کند.',show_alert=True); return
    await DBX.execute('UPDATE bb_ludo_pieces SET position=? WHERE game_id=? AND user_id=? AND piece_no=?',(newpos,gid,p['user_id'],piece_no))
    # Simple capture rule on the shared 52-cell path.
    if 0<=newpos<52:
        for op in players:
            if int(op['user_id'])==int(p['user_id']): continue
            op_rows=await DBX.execute('SELECT piece_no,position FROM bb_ludo_pieces WHERE game_id=? AND user_id=?',(gid,op['user_id']),fetch=True)
            for orow in op_rows:
                if int(orow['position'])==newpos:
                    await DBX.execute('UPDATE bb_ludo_pieces SET position=-1 WHERE game_id=? AND user_id=? AND piece_no=?',(gid,op['user_id'],orow['piece_no']))
    finished=await DBX.one('SELECT COUNT(*) n FROM bb_ludo_pieces WHERE game_id=? AND user_id=? AND position>=52',(gid,p['user_id']))
    if finished and int(finished['n'])>=4:
        await DBX.execute('UPDATE bb_ludo_games SET state="finished",dice=0,updated_at=? WHERE id=?',(now_ts(),gid))
        text=await _bb_ludo_render(gid,f'🏆 <b>{_bb_html.escape(str(p["name"]))}</b> برنده لودو شد!')
        await q.message.edit_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('🎲 لودو دوباره',f'ludo:menu:{g["chat_id"]}')]])); return
    # Six gives another turn; otherwise rotate through registered players.
    next_index=int(g['current_turn']) if roll==6 else (int(g['current_turn'])+1)%len(players)
    next_p=players[next_index]
    await DBX.execute('UPDATE bb_ludo_games SET current_turn=?,turn_color=?,dice=0,updated_at=? WHERE id=?',(next_index,next_p['color'],now_ts(),gid))
    text=await _bb_ludo_render(gid,f'➡️ نوبت بعد: <b>{_bb_html.escape(str(next_p["name"]))}</b>')
    await q.message.edit_text(text,parse_mode='HTML',reply_markup=await _bb_ludo_keyboard(gid))

async def _bb_ludo_callback(update,context):
    q=update.callback_query; d=str(q.data or ''); p=d.split(':')
    if len(p)<2 or p[0]!='ludo': return False
    action=p[1]
    if action=='menu':
        fake=type('U',(),{'effective_chat':q.message.chat,'effective_message':q.message,'effective_user':q.from_user})()
        await _bb_ludo_menu(fake,context); return True
    if action in {'max','reg','register','cancel','forceend'}:
        if not await local_admin(type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat})(),q.from_user.id):
            await q.answer('⛔ فقط ادمین می‌تواند این بخش را کنترل کند.',show_alert=True); return True
    if action=='max':
        cid=int(p[2]); await q.edit_message_text('👥 <b>حداکثر بازیکن</b>',parse_mode='HTML',reply_markup=keyboard([[btn('۲ نفر',f'ludo:setmax:{cid}:2'),btn('۳ نفر',f'ludo:setmax:{cid}:3')],[btn('۴ نفر',f'ludo:setmax:{cid}:4')],[btn('🔙 لودو',f'ludo:menu:{cid}')]])); return True
    if action=='setmax':
        if not await local_admin(type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat})(),q.from_user.id): await q.answer('⛔ فقط ادمین.',show_alert=True); return True
        await _bb_ludo_get_settings(int(p[2])); await DBX.execute('UPDATE bb_ludo_settings SET max_players=?,updated_at=? WHERE chat_id=?',(int(p[3]),now_ts(),int(p[2]))); await _bb_ludo_menu(type('U',(),{'effective_chat':q.message.chat,'effective_message':q.message,'effective_user':q.from_user})(),context); return True
    if action=='reg':
        cid=int(p[2]); await q.edit_message_text('⏳ <b>زمان ثبت‌نام</b>',parse_mode='HTML',reply_markup=keyboard([[btn('۳۰ ثانیه',f'ludo:setreg:{cid}:30'),btn('۶۰ ثانیه',f'ludo:setreg:{cid}:60')],[btn('۹۰ ثانیه',f'ludo:setreg:{cid}:90'),btn('۱۲۰ ثانیه',f'ludo:setreg:{cid}:120')],[btn('🔙 لودو',f'ludo:menu:{cid}')]])); return True
    if action=='setreg':
        if not await local_admin(type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat})(),q.from_user.id): await q.answer('⛔ فقط ادمین.',show_alert=True); return True
        await _bb_ludo_get_settings(int(p[2])); await DBX.execute('UPDATE bb_ludo_settings SET registration_seconds=?,updated_at=? WHERE chat_id=?',(int(p[3]),now_ts(),int(p[2]))); await _bb_ludo_menu(type('U',(),{'effective_chat':q.message.chat,'effective_message':q.message,'effective_user':q.from_user})(),context); return True
    if action=='register': await _bb_ludo_start_registration(q,context,int(p[2])); return True
    if action=='join': await _bb_ludo_join(q,context,int(p[2])); return True
    if action=='cancel':
        gid=int(p[2]); g=await DBX.one('SELECT * FROM bb_ludo_games WHERE id=?',(gid,))
        if g and g['state']=='registering':
            await DBX.execute('UPDATE bb_ludo_games SET state="cancelled",updated_at=? WHERE id=?',(now_ts(),gid))
            try: await q.edit_message_text('❌ <b>ثبت‌نام لودو لغو شد.</b>',parse_mode='HTML')
            except TelegramError: pass
        return True
    if action=='dice': await _bb_ludo_dice(q,context,int(p[2])); return True
    if action=='move': await _bb_ludo_move(q,context,int(p[2]),int(p[3])); return True
    if action=='forceend':
        gid=int(p[2]); g=await DBX.one('SELECT * FROM bb_ludo_games WHERE id=?',(gid,))
        if g:
            await DBX.execute('UPDATE bb_ludo_games SET state="finished",updated_at=? WHERE id=?',(now_ts(),gid))
            await q.edit_message_text(await _bb_ludo_render(gid,'🏁 بازی توسط ادمین پایان یافت.'),parse_mode='HTML')
        return True
    if action=='guide':
        await q.edit_message_text('📚 <b>راهنمای کامل لودو</b>\n\n۱) فقط ادمین گروه با دستور «لودو» بازی را راه می‌اندازد؛ لازم نیست خودش بازیکن باشد.\n۲) بازیکنان روی «ورود به لودو» می‌زنند.\n۳) حداقل ۲ بازیکن لازم است؛ اگر تا پایان ثبت‌نام کمتر از ۲ نفر باشند، بازی خودکار لغو می‌شود.\n۴) بازی ۲ تا ۴ بازیکن دارد.\n۵) در نوبت خود «ریختن تاس» را بزن. برای بیرون آوردن مهره از خانه، ۶ لازم است.\n۶) با حرکت مهره روی مسیر، مهره حریف در خانه مشترک به خانه برمی‌گردد.\n۷) با ۶، نوبت دوباره برای همان بازیکن می‌ماند.\n۸) هر چهار مهره که به پایان مسیر برسند، بازیکن برنده می‌شود.\n۹) ادمین می‌تواند بازی را هر زمان پایان دهد.\n\n🎨 همه متن‌ها و دکمه‌های این بخش از پنل طراحی مالک قابل ویرایش‌اند.',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 لودو',f'ludo:menu:{q.message.chat.id}')]])); return True
    return True

# -----------------------------------------------------------------------------
# Enforce the same admin-only start policy on اطلاعات عمومی, while keeping
# join/answer actions open to normal group members.
