_BB_OLD_TRIVIA_MENU_ADMIN = _bb_trivia_menu
async def _bb_trivia_menu(update,context):
    if update.effective_chat and update.effective_chat.type!='private':
        if not await local_admin(update, update.effective_user.id):
            await update.effective_message.reply_text('⛔ شروع و تنظیم اطلاعات عمومی فقط توسط ادمین‌های گروه انجام می‌شود.')
            return
    return await _BB_OLD_TRIVIA_MENU_ADMIN(update,context)

_BB_OLD_TRIVIA_CALLBACK_ADMIN = _bb_trivia_callback
async def _bb_trivia_callback(update,context):
    d=str(getattr(update.callback_query,'data','') or '')
    if d.startswith('trivia:'):
        parts=d.split(':'); action=parts[1] if len(parts)>1 else ''
        # Management/configuration actions are admin-only. Join and answer stay public.
        if action in {'cat','menu','settings','count','setcount','time','settime','diff','setdiff','reg','setreg','register','cancel','forceend','guide'}:
            q=update.callback_query
            fake=type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat})()
            if not await local_admin(fake,q.from_user.id):
                await q.answer('⛔ فقط ادمین گروه می‌تواند این بخش را کنترل کند.',show_alert=True); return True
    return await _BB_OLD_TRIVIA_CALLBACK_ADMIN(update,context)

_BB_OLD_LUDO_BUILD=build_application
def build_application(token=None):
    app=_BB_OLD_LUDO_BUILD(token)
    app.add_handler(CommandHandler('ludo',_bb_ludo_menu),group=-100007000)
    # Persian group trigger: Telegram command parser does not accept Persian command names.
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND & filters.Regex(r'^\s*لودو\s*$'),_bb_ludo_menu),group=-100007001)
    app.add_handler(CallbackQueryHandler(_bb_ludo_callback,pattern=r'^ludo:'),group=-100007002)
    old_post=getattr(app,'post_init',None)
    async def _bb_ludo_post(application):
        if old_post: await old_post(application)
        try:
            await _bb_ludo_schema(); await _bb_ludo_design_seed()
        except Exception as exc: log.warning('ludo schema/design seed failed: %r',exc)
    try: app.post_init=_bb_ludo_post
    except Exception: pass
    return app

