async def _bb_proxy_seed():
    await _bb_proxy_schema()
    for u in _BB_DEFAULT_PROXY_URLS:
        await DBX.execute('INSERT OR IGNORE INTO bb_global_proxies(proxy_url,enabled,added_by,added_at) VALUES(?,?,?,?)',(u,1,0,now_ts()))

async def _bb_proxy_add_text(raw, added_by=0):
    await _bb_proxy_schema()
    # Accept one URL per line, spaces, commas, or Telegram proxy URLs mixed with prose.
    urls=[]
    for part in re.split(r'[\s,;]+', str(raw or '').strip()):
        if part.startswith('https://t.me/proxy?') or part.startswith('http://t.me/proxy?'):
            urls.append(part.strip())
    # Also tolerate a pasted block where a URL is surrounded by text.
    if not urls:
        urls=re.findall(r'https?://t\.me/proxy\?[^\s<>]+', str(raw or ''))
    urls=list(dict.fromkeys(urls))
    added=0
    for u in urls:
        try:
            cur=await DBX.execute('INSERT OR IGNORE INTO bb_global_proxies(proxy_url,enabled,added_by,added_at) VALUES(?,?,?,?)',(u,1,int(added_by or 0),now_ts()))
            if getattr(cur,'rowcount',0) not in (0,-1): added += 1
            else:
                # sqlite wrappers sometimes expose rowcount=-1; verify existence is enough.
                row=await DBX.one('SELECT id FROM bb_global_proxies WHERE proxy_url=?',(u,))
                if row: added += 0
        except Exception:
            pass
    return len(urls), added

async def _bb_proxy_pick():
    await _bb_proxy_seed()
    rows=await DBX.execute('SELECT id,proxy_url FROM bb_global_proxies WHERE enabled=1 ORDER BY RANDOM() LIMIT 1',fetch=True)
    if not rows: return None
    row=rows[0]
    await DBX.execute('UPDATE bb_global_proxies SET uses=uses+1,last_used_at=? WHERE id=?',(now_ts(),int(row['id'])))
    return str(row['proxy_url'])

async def _bb_proxy_user_command(update,context):
    msg=getattr(update,'effective_message',None)
    chat=getattr(update,'effective_chat',None)
    if not msg or not chat or chat.type=='private':
        if msg: await msg.reply_text('🌐 دستور «پروکسی» را داخل گروه بزن تا یک پروکسی تصادفی بگیری.')
        return True
    proxy=await _bb_proxy_pick()
    if not proxy:
        await msg.reply_text('⚠️ فعلاً پروکسی ثبت‌شده‌ای نداریم.')
        return True
    await msg.reply_text('🌐 <b>پروکسی تصادفی</b>\n\n'+safe_text(proxy,500),parse_mode='HTML',disable_web_page_preview=True)
    return True

async def _bb_proxy_add_command(update,context):
    # Registration is intentionally restricted to the bot owner/central admins.
    if not await _bb_owner_gate(update): return
    raw=' '.join(getattr(context,'args',[]) or []).strip()
    if not raw:
        await update.effective_message.reply_text('🌐 <b>ثبت پروکسی</b>\n\nیک یا چند لینک <code>t.me/proxy</code> را بعد از دستور بفرست.\nمثال:\n<code>/proxyadd https://t.me/proxy?...\nhttps://t.me/proxy?...</code>',parse_mode='HTML')
        return
    total,_=await _bb_proxy_add_text(raw,update.effective_user.id)
    count=await DBX.one('SELECT COUNT(*) c FROM bb_global_proxies WHERE enabled=1')
    await update.effective_message.reply_text(f'✅ {total} لینک معتبر دریافت شد.\n🌐 تعداد پروکسی‌های فعال مخزن سراسری: <b>{int(count["c"] or 0)}</b>',parse_mode='HTML')

async def _bb_proxy_list_command(update,context):
    if not await _bb_owner_gate(update): return
    await _bb_proxy_seed()
    rows=await DBX.execute('SELECT id,proxy_url,uses FROM bb_global_proxies WHERE enabled=1 ORDER BY id DESC LIMIT 80',fetch=True)
    text='🌐 <b>مخزن پروکسی سراسری</b>\n\n'+('\n'.join(f'{i}. <code>{safe_text(str(r["proxy_url"]),180)}</code> — {int(r["uses"] or 0)} بار' for i,r in enumerate(rows,1)) if rows else 'خالی است.')
    await update.effective_message.reply_text(text,parse_mode='HTML',disable_web_page_preview=True)

# ---------- Speaker: interactive `/voice` manager ----------
async def _bb_speaker_schema_final():
    # The existing global table is the source of truth. This small state table
    # only keeps multi-step admin entry resilient across updates.
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_speaker_entry_state(
        user_id INTEGER NOT NULL,
        chat_id INTEGER NOT NULL,
        mode TEXT NOT NULL,
        question TEXT DEFAULT '',
        updated_at INTEGER DEFAULT 0,
        PRIMARY KEY(user_id,chat_id))''')

async def _bb_speaker_panel(update,context):
    msg=getattr(update,'effective_message',None); chat=getattr(update,'effective_chat',None); user=getattr(update,'effective_user',None)
    if not msg or not chat or not user: return True
    if chat.type!='private' and not await local_admin(update,user.id):
        await msg.reply_text('⛔ ثبت و مدیریت سخنگو فقط توسط ادمین‌های همین گروه انجام می‌شود.')
        return True
    await _bb_speaker_schema_final()
    rows=await DBX.execute('SELECT question,COUNT(*) n FROM speaker_global_chats GROUP BY question ORDER BY MAX(id) DESC LIMIT 50',fetch=True)
    total=await DBX.one('SELECT COUNT(*) c FROM speaker_global_chats')
    buttons=[
        [btn('➕ ثبت سؤال و جواب','spk:ask')],
        [btn('📚 فهرست سؤال‌ها','spk:list')],
        [btn('🧹 پاکسازی سؤال‌های این گروه','spk:help')],
        [btn('📖 راهنما','spk:help')],
    ]
    await msg.reply_text(
        f'🎙 <b>سخنگوی بیل‌بیلک</b>\n\n'
        f'مخزن پاسخ‌ها <b>سراسری</b> است و هر مورد ثبت‌شده برای همه گروه‌ها قابل استفاده می‌شود.\n'
        f'📦 تعداد پاسخ‌های ذخیره‌شده: <b>{int(total["c"] or 0)}</b>\n\n'
        'برای ثبت، اول سؤال را از تو می‌خواهم؛ بعد جواب را.\n'
        'دیگر لازم نیست از «تنظیم چت» استفاده کنی.',
        parse_mode='HTML',reply_markup=keyboard(buttons))
    return True

async def _bb_speaker_callback(update,context):
    q=getattr(update,'callback_query',None); d=str(getattr(q,'data','') or '')
    if not q or not d.startswith('spk:'): return False
    chat=q.message.chat; user=q.from_user
    fake=type('U',(),{'effective_user':user,'effective_chat':chat})()
    if chat.type!='private' and not await local_admin(fake,user.id):
        await q.answer('⛔ فقط ادمین گروه.',show_alert=True); return True
    await _bb_speaker_schema_final()
    action=d.split(':',1)[1]
    if action=='ask':
        await DBX.execute('INSERT OR REPLACE INTO bb_speaker_entry_state(user_id,chat_id,mode,question,updated_at) VALUES(?,?,?,?,?)',(user.id,chat.id,'question','',now_ts()))
        await q.edit_message_text('🎙 <b>ثبت سؤال</b>\n\nاول متن سؤالی که کاربر باید بگوید/بنویسد را بفرست.\nمثال: <code>سلام</code>',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 سخنگو','spk:home')]])); return True
    if action=='list':
        rows=await DBX.execute('SELECT question,COUNT(*) n FROM speaker_global_chats GROUP BY question ORDER BY MAX(id) DESC LIMIT 50',fetch=True)
        text='📚 <b>فهرست سراسری سخنگو</b>\n\n'+('\n'.join(f'• {safe_text(str(r["question"]),80)} — {int(r["n"])} پاسخ' for r in rows) if rows else 'هنوز موردی ثبت نشده.')
        await q.edit_message_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('➕ ثبت جدید','spk:ask')],[btn('🔙 سخنگو','spk:home')]])); return True
    if action=='help':
        await q.edit_message_text('📖 <b>راهنمای سخنگو</b>\n\n۱) «ثبت سؤال و جواب» را بزن.\n۲) سؤال را بفرست.\n۳) ربات جواب را می‌خواهد.\n۴) جواب را بفرست.\n۵) همان سؤال و جواب در دیتابیس سراسری ذخیره می‌شود و همه گروه‌ها می‌توانند از آن استفاده کنند.\n\nبرای مدیریت از <code>/voice</code> استفاده کن.',parse_mode='HTML',reply_markup=keyboard([[btn('➕ ثبت سؤال و جواب','spk:ask')],[btn('🔙 سخنگو','spk:home')]])); return True
    if action=='home':
        fake2=type('U',(),{'effective_message':q.message,'effective_chat':chat,'effective_user':user})()
        return await _bb_speaker_panel(fake2,context)
    return True

async def _bb_speaker_message_final(update,context):
    msg=getattr(update,'effective_message',None); chat=getattr(update,'effective_chat',None); user=getattr(update,'effective_user',None)
    if not msg or not chat or not user or not getattr(msg,'text',None): return False
    state=await DBX.one('SELECT * FROM bb_speaker_entry_state WHERE user_id=? AND chat_id=?',(user.id,chat.id))
    if not state: return False
    fake=type('U',(),{'effective_user':user,'effective_chat':chat})()
    if chat.type!='private' and not await local_admin(fake,user.id): return False
    t=str(msg.text).strip()
    if not t: return True
    if state['mode']=='question':
        await DBX.execute('UPDATE bb_speaker_entry_state SET mode=?,question=?,updated_at=? WHERE user_id=? AND chat_id=?',('answer',t,now_ts(),user.id,chat.id))
        await msg.reply_text('🎙 <b>جواب را بفرست</b>\n\nحالا پاسخی که ربات باید برای این سؤال بدهد را ارسال کن.',parse_mode='HTML')
        return True
    question=str(state['question'] or '').strip()
    await DBX.execute('INSERT INTO speaker_global_chats(question,answer_type,answer_text,file_id,caption,source_chat_id,created_by,created_at) VALUES(?,?,?,?,?,?,?,?)',(question,'text',t,'',t,chat.id,user.id,now_ts()))
    await DBX.execute('DELETE FROM bb_speaker_entry_state WHERE user_id=? AND chat_id=?',(user.id,chat.id))
    await msg.reply_text(f'✅ ذخیره شد.\n\n❓ سؤال: <b>{safe_text(question,200)}</b>\n💬 جواب: <b>{safe_text(t,300)}</b>\n\n🌐 این مورد در مخزن سراسری سخنگو ثبت شد.',parse_mode='HTML')
    return True

# ---------- Truth/Dare: bulk list import + Persian commands ----------
async def _bb_td_schema_final():
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_td_items_global(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        kind TEXT NOT NULL,
        item TEXT NOT NULL UNIQUE,
        enabled INTEGER DEFAULT 1,
        added_by INTEGER DEFAULT 0,
        added_at INTEGER DEFAULT 0)''')

async def _bb_td_bulk_add(kind, raw, added_by=0):
    await _bb_td_schema_final()
    # One item per non-empty line. Also split numbered bullets and common separators.
    chunks=[]
    for line in str(raw or '').splitlines():
        line=re.sub(r'^\s*(?:\d+\s*[\).:\-]|[-•●▪️])\s*','',line).strip()
        if line: chunks.append(line)
    # If the user pasted a one-line list, semicolon/pipe is also accepted.
    if len(chunks)<=1 and any(x in str(raw or '') for x in (';','|')):
        chunks=[x.strip() for x in re.split(r'[;|]',str(raw or '')) if x.strip()]
    added=0
    for item in chunks:
        try:
            cur=await DBX.execute('INSERT OR IGNORE INTO bb_td_items_global(kind,item,enabled,added_by,added_at) VALUES(?,?,?,?,?)',(kind,item,1,int(added_by or 0),now_ts()))
            if getattr(cur,'rowcount',0)>0: added+=1
        except Exception: pass
    # Keep the existing game-list engine synchronized so all old truth/dare UI uses the same global pool.
    for item in chunks:
        try: await DBX.execute('INSERT OR IGNORE INTO bb_game_lists(game,item,created_at) VALUES(?,?,?)',(kind,item,now_ts()))
        except Exception: pass
    return len(chunks),added

async def _bb_td_panel(update,context,kind=None):
    msg=getattr(update,'effective_message',None); chat=getattr(update,'effective_chat',None); user=getattr(update,'effective_user',None)
    if not msg or not chat or not user: return True
    if chat.type!='private' and not await local_admin(update,user.id):
        await msg.reply_text('⛔ ثبت سؤال‌های جرأت/حقیقت فقط توسط ادمین گروه انجام می‌شود.'); return True
    await _bb_td_schema_final()
    truth=await DBX.one("SELECT COUNT(*) c FROM bb_td_items_global WHERE kind='truth' AND enabled=1")
    dare=await DBX.one("SELECT COUNT(*) c FROM bb_td_items_global WHERE kind='dare' AND enabled=1")
    if kind in ('truth','dare'):
        context.user_data['bb_td_pending_kind']=kind
        label='حقیقت' if kind=='truth' else 'جرأت'
        await msg.reply_text(f'📝 <b>ثبت لیست {label}</b>\n\nحالا کل لیست را یکجا بفرست؛ هر خط یک مورد باشد.\nربات خودش هر خط را جداگانه ذخیره می‌کند و در بازی موردبه‌مورد می‌دهد.\n\nمثال:\n<code>۱. سوال اول\n۲. سوال دوم\n۳. سوال سوم</code>',parse_mode='HTML')
        return True
    await msg.reply_text(f'🎭 <b>مدیریت جرأت و حقیقت</b>\n\n💬 حقیقت: <b>{int(truth["c"] or 0)}</b>\n🎯 جرأت: <b>{int(dare["c"] or 0)}</b>\n\nهر بخش را انتخاب کن و بعد لیست کامل را یکجا بفرست.',parse_mode='HTML',reply_markup=keyboard([[btn('💬 ثبت لیست حقیقت','tdfinal:truth')],[btn('🎯 ثبت لیست جرأت','tdfinal:dare')],[btn('🎲 اجرای بازی','tdfinal:play')],[btn('📚 راهنما','tdfinal:help')]]))
    return True

async def _bb_td_callback_final(update,context):
    q=getattr(update,'callback_query',None); d=str(getattr(q,'data','') or '')
    if not q or not d.startswith('tdfinal:'): return False
    fake=type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat})()
    if q.message.chat.type!='private' and not await local_admin(fake,q.from_user.id):
        await q.answer('⛔ فقط ادمین گروه.',show_alert=True); return True
    action=d.split(':',1)[1]
    if action in ('truth','dare'):
        context.user_data['bb_td_pending_kind']=action
        label='حقیقت' if action=='truth' else 'جرأت'
        await q.edit_message_text(f'📝 <b>لیست {label}</b>\n\nهمه موارد را یکجا بفرست؛ هر خط یک مورد.\nشماره‌گذاری و bulletها خودکار حذف می‌شوند.',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 مدیریت','tdfinal:home')]])); return True
    if action=='play':
        await q.edit_message_text('🎭 <b>جرأت یا حقیقت</b>\n\nیک گزینه را انتخاب کن:',parse_mode='HTML',reply_markup=keyboard([[btn('💬 حقیقت','arc:truth:truth'),btn('🎯 جرأت','arc:truth:dare')],[btn('🔙 مدیریت','tdfinal:home')]])); return True
    if action=='help':
        await q.edit_message_text('📚 <b>راهنما</b>\n\n• برای هر بخش یک لیست کامل بفرست.\n• هر خط به‌صورت خودکار یک آیتم جدا ذخیره می‌شود.\n• آیتم‌ها سراسری‌اند و در همه گروه‌ها استفاده می‌شوند.\n• متن‌ها و دکمه‌های این بخش از طراحی مالک قابل ویرایش‌اند.\n• شروع مدیریت/ثبت فقط برای ادمین گروه است.',parse_mode='HTML',reply_markup=keyboard([[btn('🔙 مدیریت','tdfinal:home')]])); return True
    if action=='home':
        fake2=type('U',(),{'effective_message':q.message,'effective_chat':q.message.chat,'effective_user':q.from_user})()
        return await _bb_td_panel(fake2,context)
    return True

async def _bb_td_message_final(update,context):
    msg=getattr(update,'effective_message',None); chat=getattr(update,'effective_chat',None); user=getattr(update,'effective_user',None)
    if not msg or not chat or not user or not getattr(msg,'text',None): return False
    kind=context.user_data.get('bb_td_pending_kind')
    if kind not in ('truth','dare'): return False
    fake=type('U',(),{'effective_user':user,'effective_chat':chat})()
    if chat.type!='private' and not await local_admin(fake,user.id): return False
    raw=msg.text
    context.user_data.pop('bb_td_pending_kind',None)
    total,added=await _bb_td_bulk_add(kind,raw,user.id)
    label='حقیقت' if kind=='truth' else 'جرأت'
    await msg.reply_text(f'✅ لیست {label} ثبت شد.\n\n📥 موارد جداشده: <b>{total}</b>\n➕ موارد جدید: <b>{added}</b>\n🌐 مخزن سراسری: فعال',parse_mode='HTML')
    return True

