async def _bb_name_family_start_command(update,context):
    msg=getattr(update,'effective_message',None); chat=getattr(update,'effective_chat',None); user=getattr(update,'effective_user',None)
    if not msg or not chat or not user: return True
    if chat.type=='private':
        await msg.reply_text('📝 اسم فامیل را داخل گروه اجرا کن.'); return True
    if not await local_admin(update,user.id):
        await msg.reply_text('⛔ شروع اسم فامیل فقط توسط ادمین گروه انجام می‌شود؛ ادمین لازم نیست خودش بازی کند.')
        return True
    room=NAME_FAMILY_ROOMS.get(chat.id)
