async def _bb_nf_message_admin_final(update,context):
    msg=getattr(update,'effective_message',None); chat=getattr(update,'effective_chat',None); user=getattr(update,'effective_user',None)
    if not msg or not chat or chat.type=='private' or not user or not getattr(msg,'text',None): return False
    t=normalize(msg.text)
    if t in {'این فامیل','اسم فامیل','اسم‌فامیل'}:
        return await _bb_name_family_start_command(update,context)
    if _BB_NF_MESSAGE_OLD_FINAL:
        return await _BB_NF_MESSAGE_OLD_FINAL(update,context)
    return False

