_BB_FINAL_REQUESTED_BUILD_PREV=build_application
def build_application(token=None):
    app=_BB_FINAL_REQUESTED_BUILD_PREV(token)
    # User-facing commands.
    app.add_handler(CommandHandler(['proxy'],_bb_proxy_user_command),group=-500000)
    app.add_handler(MessageHandler(filters.Regex(r'^\s*پروکسی\s*$'),_bb_proxy_user_command),group=-500001)
    app.add_handler(CommandHandler(['proxyadd'],_bb_proxy_add_command),group=-500002)
    app.add_handler(CommandHandler(['proxylist'],_bb_proxy_list_command),group=-500003)
    app.add_handler(CommandHandler(['voice','sokhangoo'],_bb_speaker_panel),group=-500004)
    app.add_handler(CommandHandler(['truth','dare','truthdare'],_bb_td_panel),group=-500005)
    app.add_handler(CommandHandler(['namefamily','esmfamily'],_bb_name_family_start_command),group=-500006)
    app.add_handler(CommandHandler(['familygame'],_bb_name_family_start_command),group=-500007)
    # Persian direct commands.
    app.add_handler(MessageHandler(filters.Regex(r'^\s*(اسم فامیل|اسم‌فامیل|این فامیل)\s*$'),_bb_name_family_start_command),group=-500008)
    app.add_handler(MessageHandler(filters.Regex(r'^\s*(جرأت حقیقت|جرئت حقیقت|جرات حقیقت|جرعت حقیقت)\s*$'),_bb_td_panel),group=-500009)
    # Interactive content states must run before generic text routers.
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_speaker_message_final),group=-500010)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_td_message_final),group=-500011)
    app.add_handler(CallbackQueryHandler(_bb_speaker_callback,pattern=r'^spk:'),group=-500012)
    app.add_handler(CallbackQueryHandler(_bb_td_callback_final,pattern=r'^tdfinal:'),group=-500013)
    # Preserve the existing name/family engine for join/answers, but force its start through admin gate.
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND,_bb_nf_message_admin_final),group=-500014)
    old_post=getattr(app,'post_init',None)
    async def _bb_requested_post(application):
        if old_post: await old_post(application)
        try: await _bb_final_requested_design_seed()
        except Exception as exc: log.warning('requested design seed failed: %r',exc)
        try: await _bb_proxy_seed()
        except Exception as exc: log.warning('proxy seed failed: %r',exc)
    app.post_init=_bb_requested_post
    return app

