# ---------- Shared AI study-note engine ----------
async def _bb_shared_ai_chat(messages, *, max_tokens=1200, temperature=0.35, timeout=10):
    """OpenAI-compatible shared AI endpoint used by speaker + study notes."""
    try:
        key=await _bb_api_get('AI_SHARED_API_KEY','')
    except Exception:
        key=''
    if not key:
        try:
            key=await _bb_api_get('OPENROUTER_API_KEY','')
        except Exception:
            key=os.getenv('OPENROUTER_API_KEY','')
    if not key:
        return None
    try:
        url=await _bb_api_get('AI_SHARED_API_URL','')
    except Exception:
        url=''
    url=(url or 'https://openrouter.ai/api/v1/chat/completions').strip()
    if not url.rstrip('/').endswith('/chat/completions'):
        url=url.rstrip('/')+'/chat/completions'
    try:
        model=await _bb_api_get('AI_SHARED_MODEL','')
    except Exception:
        model=''
    if not model:
        model=await _bb_api_get('OPENROUTER_MODEL','') or os.getenv('OPENROUTER_MODEL','') or 'openrouter/auto'
    body={
        'model':model,
        'messages':messages,
        'temperature':float(temperature),
        'max_tokens':int(max_tokens),
    }
    try:
        r=await _bb_http_post(url,{
            'Authorization':f'Bearer {key}',
            'Content-Type':'application/json',
            'HTTP-Referer':'https://t.me/',
            'X-Title':'Bil Bilak Study',
        },body,timeout=timeout)
        data=r.json()
        content=((data.get('choices') or [{}])[0].get('message') or {}).get('content')
        if isinstance(content,list):
            content=''.join(str(x.get('text','')) if isinstance(x,dict) else str(x) for x in content)
        if content and str(content).strip():
            return str(content).strip()
    except Exception as exc:
        log.warning('shared AI request failed: %r',exc)
    return None


def _bb_study_topic_parse(text):
    raw=str(text or '').strip()
    m=re.fullmatch(r'(کامل\s+)?جزوه\s+(.+)',raw,re.I)
    if not m:
        return None,None
    full=bool(m.group(1))
    topic=m.group(2).strip()
    return full,topic


def _bb_split_long_messages(text, limit=3000):
    text=str(text or '').strip()
    if not text: return []
    parts=[]; current=''
    for para in re.split(r'\n\s*\n',text):
        para=para.strip()
        if not para: continue
        if len(para)<=limit and len(current)+len(para)+2<=limit:
            current=(current+'\n\n'+para).strip()
            continue
        if current:
            parts.append(current); current=''
        if len(para)<=limit:
            current=para
        else:
            for i in range(0,len(para),limit):
                chunk=para[i:i+limit].strip()
                if chunk: parts.append(chunk)
    if current: parts.append(current)
    return parts


async def _bb_make_study_note(topic, full=False):
    level='کامل، دقیق و آموزشی' if full else 'خلاصه، نکته‌ای و مناسب مرور سریع'
    prompt=(
        'برای کاربر یک جزوه فارسی واقعی و قابل مطالعه آماده کن. '\
        f'سطح خروجی: {level}.\n'\
        f'موضوع/درخواست کاربر: {topic}\n\n'\
        'اگر پایه، مقطع، رشته، واحد یا نام درس در درخواست آمده همان را دقیق رعایت کن. '\
        'ساختار را منظم کن: عنوان، تعریف‌ها، نکات اصلی، فرمول‌ها یا قواعد لازم، مثال کوتاه، '\
        'نکات امتحانی و جمع‌بندی. چیزی را بی‌دلیل اختراع نکن؛ اگر مشخصات درس کافی نیست، '\
        'با همان اطلاعات موجود یک جزوه عمومی و درست درباره موضوع بساز. '\
        'خروجی فقط متن جزوه باشد، بدون مقدمه درباره هوش مصنوعی و بدون HTML.'
    )
    return await _bb_shared_ai_chat([
        {'role':'system','content':'تو دستیار آموزشی دقیق و خلاصه‌نویس فارسی هستی. مطالب را روشن، قابل فهم و منظم می‌نویسی.'},
        {'role':'user','content':prompt},
    ],max_tokens=1800 if full else 900,temperature=0.25,timeout=10)


async def _bb_study_command(update,context):
    msg=getattr(update,'effective_message',None)
    if not msg or not getattr(msg,'text',None): return False
    raw=str(msg.text).strip()
    full,topic=_bb_study_topic_parse(raw)
    if topic is None or not topic: return False
    if len(topic)>500:
        await msg.reply_text('📚 موضوع جزوه خیلی طولانی است؛ نام درس، پایه یا واحد را کوتاه‌تر بفرست.')
        return True
    # Full notes are deliberately handled in PV after the user starts the bot.
    if full and getattr(getattr(update,'effective_chat',None),'type',None)!='private':
        await msg.reply_text(
            '📚 برای جزوه کامل، همین دستور را در پیوی ربات بعد از استارت بفرست:\n'
            f'<code>کامل جزوه {safe_text(topic,450)}</code>\n\n'
            'در گروه نسخه خلاصه برایت آماده می‌کنم.',parse_mode='HTML')
        # Also give the requested fast group summary.
        full=False
    wait=await msg.reply_text('⏳ صبر کن؛ دارم جزوه را به‌صورت خلاصه و مرتب برایت می‌نویسم…')
    note=await _bb_make_study_note(topic,full=full)
    if not note:
        try: await wait.edit_text('⚠️ سرویس هوش آموزشی فعلاً پاسخ نداد. دوباره همین دستور را بفرست.')
        except Exception: pass
        return True
    chunks=_bb_split_long_messages(note,2800)
    try:
        await wait.edit_text('📚 <b>جزوه آماده شد</b>\n\n'+safe_text(chunks[0],2700),parse_mode='HTML')
    except Exception:
        await msg.reply_text('📚 <b>جزوه آماده شد</b>\n\n'+safe_text(chunks[0],2700),parse_mode='HTML')
    for chunk in chunks[1:]:
        await msg.reply_text(safe_text(chunk,3000),parse_mode='HTML')
    if not full:
        await msg.reply_text(
            '📖 اگر نسخه کامل‌تر می‌خواهی، در پیوی ربات استارت کن و اول دستور «کامل» را بگذار:\n'
            f'<code>کامل جزوه {safe_text(topic,450)}</code>',parse_mode='HTML')
    return True


# ---------- Safe Persian calculator ----------
_BB_CALC_FUNCS={
    'sqrt':math.sqrt,'رادیکال':math.sqrt,'sin':math.sin,'cos':math.cos,'tan':math.tan,
    'asin':math.asin,'acos':math.acos,'atan':math.atan,'log':math.log10,'ln':math.log,
    'abs':abs,'factorial':math.factorial,
}
_BB_CALC_CONST={'pi':math.pi,'π':math.pi,'e':math.e}


def _bb_calc_eval(expr):
    expr=str(expr or '').strip().replace('×','*').replace('÷','/').replace('−','-').replace('^','**').replace('٪','%')
    if not expr or len(expr)>120: raise ValueError('bad expression')
    # Common Persian decimal separator.
    expr=expr.replace('٫','.')
    tree=ast.parse(expr,mode='eval')
    def ev(node):
        if isinstance(node,ast.Expression): return ev(node.body)
        if isinstance(node,ast.Constant) and isinstance(node.value,(int,float)) and not isinstance(node.value,bool): return node.value
        if isinstance(node,ast.UnaryOp) and isinstance(node.op,(ast.UAdd,ast.USub)): return +ev(node.operand) if isinstance(node.op,ast.UAdd) else -ev(node.operand)
        if isinstance(node,ast.BinOp):
            a,b=ev(node.left),ev(node.right)
            if isinstance(node.op,ast.Add): return a+b
            if isinstance(node.op,ast.Sub): return a-b
            if isinstance(node.op,ast.Mult): return a*b
            if isinstance(node.op,ast.Div): return a/b
            if isinstance(node.op,ast.Pow): return a**b
            if isinstance(node.op,ast.Mod): return a%b
            raise ValueError('op')
        if isinstance(node,ast.Name):
            if node.id in _BB_CALC_CONST: return _BB_CALC_CONST[node.id]
            raise ValueError('name')
        if isinstance(node,ast.Call) and isinstance(node.func,ast.Name) and node.func.id in _BB_CALC_FUNCS and not node.keywords:
            args=[ev(x) for x in node.args]
            if node.func.id=='factorial' and (len(args)!=1 or args[0]<0 or int(args[0])!=args[0] or args[0]>500): raise ValueError('factorial')
            return _BB_CALC_FUNCS[node.func.id](*args)
        raise ValueError('unsupported')
    result=ev(tree)
    if isinstance(result,complex) or not math.isfinite(float(result)): raise ValueError('nonfinite')
    return result


def _bb_calc_format(value):
    if abs(float(value)-round(float(value)))<1e-12:
        return str(int(round(float(value))))
    return f'{float(value):.12g}'


async def _bb_calculator_command(update,context):
    msg=getattr(update,'effective_message',None)
    if not msg or not getattr(msg,'text',None): return False
    raw=str(msg.text).strip()
    m=re.fullmatch(r'جواب\s+(.+)',raw,re.I)
    radical=re.fullmatch(r'(?:رادیکال|جذر)\s+(.+)',raw,re.I)
    if not m and not radical: return False
    expr=radical.group(1) if radical else m.group(1).strip()
    if radical:
        expr=f'sqrt({expr})'
    # Do not let arbitrary text reach the evaluator.
    if not re.fullmatch(r'[0-9A-Za-z_πی\s+\-*/%^().,٫×÷−٪]+',expr):
        await msg.reply_text('🧮 عبارت ریاضی قابل تشخیص نیست. مثال: <code>جواب 14*5</code> یا <code>رادیکال 6</code>',parse_mode='HTML')
        return True
    try:
        result=_bb_calc_eval(expr)
        await msg.reply_text(f'🧮 <b>جواب:</b> <code>{safe_text(_bb_calc_format(result),100)}</code>',parse_mode='HTML')
    except Exception:
        await msg.reply_text('🧮 این عبارت قابل محاسبه نیست. مثال: <code>جواب 15+2</code>، <code>جواب 14*5</code>، <code>رادیکال 6</code>',parse_mode='HTML')
    return True


# ---------- Final build layer: these handlers run before generic routers. ----------
_BB_BUILD_BEFORE_REQUESTED_TOOLS=build_application
def build_application(token=None):
    app=_BB_BUILD_BEFORE_REQUESTED_TOOLS(token)
    # Strict calculator / study commands.
    app.add_handler(MessageHandler(filters.Regex(r'^\s*(?:جواب\s+.+|رادیکال\s+.+|جذر\s+.+)\s*$'),_bb_calculator_command),group=-20000000)
    app.add_handler(MessageHandler(filters.Regex(r'^\s*(?:کامل\s+)?جزوه\s+.+\s*$'),_bb_study_command),group=-19999999)
    # Shared AI API is initialized into the central design registry at startup.
    old_post=getattr(app,'post_init',None)
    async def _bb_requested_tools_post(application):
        if old_post: await old_post(application)
        try:
            await _bb_final_api_schema_sync()
            await _bb_proxy_schema()
            await _bb_speaker_schema_final()
            await _bb_td_schema_final()
            await _bb_rel_schema()
            for value,cat,kind in [
                ('📚 <b>جزوه هوشمند</b>','study','text'),
                ('⏳ صبر کن؛ دارم جزوه را به‌صورت خلاصه و مرتب برایت می‌نویسم…','study','text'),
                ('📖 اگر نسخه کامل‌تر می‌خواهی، در پیوی ربات استارت کن.','study','text'),
                ('📚 جزوه آماده شد','study','text'),
                ('🧮 <b>ماشین حساب</b>','calculator','text'),
                ('🧮 جواب: {result}','calculator','text'),
                ('📐 رادیکال','calculator','button'),
                ('➕ جمع','calculator','button'),
                ('✖️ ضرب','calculator','button'),
                ('➗ تقسیم','calculator','button'),
                ('📚 راهنمای ماشین حساب','calculator','button'),
                ('💍 {target_mention}\\n{name} برایت درخواست ازدواج فرستاده است.','relationships','text'),
                ('✅ قبول','relationships','button'),('❌ رد','relationships','button')]:
                try: await _bb_ui_register(value,category=cat,kind=kind)
                except Exception: pass
        except Exception as exc:
            log.debug('requested tools post init failed: %r',exc)
    app.post_init=_bb_requested_tools_post
    return app


# Strict moderation command gate: execute only exact bare words (or `سکوت N`),
# and consume punctuation variants so legacy routers cannot misread `سکوت.` etc.
async def _bb_strict_moderation_command(update,context):
    msg=getattr(update,'effective_message',None)
    if not msg or not getattr(msg,'text',None): return False
    raw=str(msg.text).strip()
    if raw=='سکوت' or re.fullmatch(r'سکوت\s+\d+',raw) or raw in {'بن','بَن','سیک','هیس','خفه'}:
        if raw=='سکوت' or raw in {'سیک','هیس','خفه'}:
            context.args=[]
        else:
            context.args=raw.split()[1:]
        return await bb_moderation_text(update,context,'mute' if raw.startswith(('سکوت','سیک','هیس','خفه')) else 'ban')
    # If a punctuation mark is attached to a bare moderation word, it is NOT a
    # command. Consume it before old routers that use startswith/loose matching.
    bare=re.sub(r'[^\w\u0600-\u06FF\s]','',raw).strip()
    if raw!=bare and bare in {'بن','بَن','سیک','هیس','خفه','سکوت'}:
        return True
    return False

_BB_BUILD_BEFORE_STRICT_MOD=build_application
def build_application(token=None):
    app=_BB_BUILD_BEFORE_STRICT_MOD(token)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_strict_moderation_command),group=-20000001)
    return app

