# ---------- POP / POO P group game ----------
async def _bb_pop_schema_final():
    await DBX.execute('''CREATE TABLE IF NOT EXISTS bb_pop_rooms(
        chat_id INTEGER PRIMARY KEY,
        host_id INTEGER NOT NULL,
        player2_id INTEGER DEFAULT 0,
        turn_id INTEGER DEFAULT 0,
        state TEXT DEFAULT 'waiting',
        board_json TEXT DEFAULT '',
        opened_json TEXT DEFAULT '',
        scores_json TEXT DEFAULT '{}',
        updated_at INTEGER DEFAULT 0)''')

async def _bb_pop_room_get(cid):
    await _bb_pop_schema_final()
    r=await DBX.one('SELECT * FROM bb_pop_rooms WHERE chat_id=?',(int(cid),))
    if not r: return None
    # A waiting room left behind by a restart must not block a fresh game.
    if str(r['state'] or '')=='waiting' and now_ts()-int(r['updated_at'] or 0) > 2*3600:
        await DBX.execute('DELETE FROM bb_pop_rooms WHERE chat_id=?',(int(cid),))
        return None
    if str(r['state'] or '')=='playing' and now_ts()-int(r['updated_at'] or 0) > 24*3600:
        await DBX.execute('DELETE FROM bb_pop_rooms WHERE chat_id=?',(int(cid),))
        return None
    def j(raw, default):
        try: return json.loads(raw or '')
        except Exception: return default
    return {
        'chat_id':int(r['chat_id']), 'host_id':int(r['host_id']), 'player2_id':int(r['player2_id'] or 0),
        'turn_id':int(r['turn_id'] or 0), 'state':str(r['state'] or 'waiting'),
        'board':j(r['board_json'],[]), 'opened':j(r['opened_json'],[]), 'scores':j(r['scores_json'],{}),
    }

async def _bb_pop_room_save(room):
    await DBX.execute('''INSERT OR REPLACE INTO bb_pop_rooms(chat_id,host_id,player2_id,turn_id,state,board_json,opened_json,scores_json,updated_at)
        VALUES(?,?,?,?,?,?,?,?,?)''',(room['chat_id'],room['host_id'],room.get('player2_id',0),room.get('turn_id',0),room.get('state','waiting'),
        json.dumps(room.get('board',[]),ensure_ascii=False),json.dumps(room.get('opened',[]),ensure_ascii=False),json.dumps(room.get('scores',{}),ensure_ascii=False),now_ts()))

async def _bb_pop_user_name(uid):
    r=await DBX.one('SELECT first_name,username FROM users WHERE user_id=?',(int(uid),))
    if r:
        return str(r['first_name'] or r['username'] or uid)
    return str(uid)

def _bb_pop_board(room):
    board=room['board']; opened=set(room.get('opened',[])); rows=[]
    for i in range(len(board)):
        if i in opened:
            val=board[i]
            if val=='gem': lab='💎'
            elif val=='poop': lab='💩'
            else: lab='⬜'
        else: lab='📦'
        rows.append(btn(lab,f'pop:cell:{room["chat_id"]}:{i}',style='primary'))
    kb=[rows[i:i+6] for i in range(0,len(rows),6)]
    kb.append([btn('🔄 بازی مجدد',f'pop:new:{room["chat_id"]}',style='success')])
    return keyboard(kb)

async def _bb_pop_start(update,context):
    msg=getattr(update,'effective_message',None); chat=getattr(update,'effective_chat',None); user=getattr(update,'effective_user',None)
    if not msg or not chat or not user: return True
    if chat.type not in ('group','supergroup'):
        await msg.reply_text('💩 بازی پوپ را داخل گروه اجرا کن.'); return True
    old=await _bb_pop_room_get(chat.id)
    if old and old.get('state')!='ended':
        await msg.reply_text('💩 یک بازی پوپ در این گروه فعال است؛ اول به بازی بپیوند یا بازی مجدد را بزن.')
        return True
    board=['gem']*4+['poop']*5+['empty']*21
    random.shuffle(board)
    room={'chat_id':chat.id,'host_id':user.id,'player2_id':0,'turn_id':user.id,'state':'waiting','board':board,'opened':[],
          'scores':{str(user.id):0}}
    await _bb_pop_room_save(room)
    name=await _bb_pop_user_name(user.id)
    text=(f'💩 <b>پوپ دو نفره</b> 💎\n\n👤 سازنده: <b>{safe_text(name,40)}</b>\n\n'
          '🎯 قوانین بازی:\n🔸 نفر دوم وارد می‌شود.\n🔸 هر نوبت یک جعبه باز می‌شود.\n🔸 💎 الماس امتیاز دارد.\n🔸 💩 پوپ پیدا شود، نوبت عوض می‌شود.\n\n'
          '👥 نفر دوم با دکمه زیر وارد شود.')
    await msg.reply_text(text,parse_mode='HTML',reply_markup=keyboard([[btn('➕ پیوستن به پوپ',f'pop:join:{chat.id}',style='success')],[btn('📚 راهنما',f'pop:help:{chat.id}')]]))
    return True

async def _bb_pop_callback(update,context):
    q=getattr(update,'callback_query',None); d=str(getattr(q,'data','') or '') if q else ''
    if not q or not d.startswith('pop:'): return False
    p=d.split(':'); action=p[1] if len(p)>1 else ''; cid=int(p[2]) if len(p)>2 and p[2].isdigit() else q.message.chat.id
    room=await _bb_pop_room_get(cid)
    if action=='help':
        await q.answer(); await q.message.reply_text('💩 پوپ دو نفره است. یک نفر بازی را می‌سازد و نفر دوم با «پیوستن» وارد می‌شود؛ بعد هر نفر نوبتی جعبه باز می‌کند و الماس امتیاز می‌گیرد.')
        return True
    if action=='new':
        if not room: await q.answer('بازی‌ای وجود ندارد.',show_alert=True); return True
        if q.from_user.id not in {room['host_id'],room.get('player2_id',0)}:
            await q.answer('⛔ فقط بازیکنان می‌توانند بازی را دوباره شروع کنند.',show_alert=True); return True
        room.update({'player2_id':0,'turn_id':room['host_id'],'state':'waiting','board':random.sample(['gem']*4+['poop']*5+['empty']*21,30),'opened':[],'scores':{str(room['host_id']):0}})
        await _bb_pop_room_save(room); await q.answer('بازی جدید ساخته شد.'); await q.message.edit_text('💩 <b>بازی جدید پوپ</b>\n\n👥 نفر دوم وارد شود.',parse_mode='HTML',reply_markup=keyboard([[btn('➕ پیوستن به پوپ',f'pop:join:{cid}',style='success')]])); return True
    if not room:
        await q.answer('بازی تمام شده یا وجود ندارد.',show_alert=True); return True
    uid=q.from_user.id
    if action=='join':
        if room['state']!='waiting': await q.answer('بازی شروع شده است.',show_alert=True); return True
        if uid==room['host_id']: await q.answer('تو سازنده بازی هستی.',show_alert=True); return True
        room['player2_id']=uid; room['turn_id']=room['host_id']; room['state']='playing'; room['scores'][str(uid)]=0
        await _bb_pop_room_save(room)
        a=await _bb_pop_user_name(room['host_id']); b=await _bb_pop_user_name(uid)
        await q.answer('وارد بازی شدی!'); await q.message.edit_text(f'💩 <b>پوپ دو نفره شروع شد!</b> 💎\n\n🔴 {safe_text(a,30)}: <b>0</b>\n🔵 {safe_text(b,30)}: <b>0</b>\n\n🎯 نوبت: <b>{safe_text(a,30)}</b>',parse_mode='HTML',reply_markup=_bb_pop_board(room)); return True
    if action=='cell':
        if room['state']!='playing': await q.answer('این بازی فعال نیست.',show_alert=True); return True
        if uid not in {room['host_id'],room['player2_id']}: await q.answer('⛔ تو بازیکن این بازی نیستی.',show_alert=True); return True
        if uid!=room['turn_id']: await q.answer('⏳ نوبت بازیکن دیگر است.',show_alert=True); return True
        idx=int(p[3]) if len(p)>3 and p[3].isdigit() else -1
        if idx<0 or idx>=len(room['board']) or idx in room['opened']: await q.answer('این جعبه قبلاً باز شده.',show_alert=True); return True
        room['opened'].append(idx); val=room['board'][idx]
        other=room['player2_id'] if uid==room['host_id'] else room['host_id']
        if val=='gem':
            room['scores'][str(uid)]=int(room['scores'].get(str(uid),0))+1
            msg=f'💎 {await _bb_pop_user_name(uid)} یک الماس پیدا کرد و <b>۱ امتیاز</b> گرفت!'
        elif val=='poop':
            msg=f'💩 {await _bb_pop_user_name(uid)} پوپ پیدا کرد! نوبت عوض شد.'
            room['turn_id']=other
        else:
            msg=f'📦 جعبه خالی بود! نوبت عوض شد.'
            room['turn_id']=other
        remaining=sum(1 for x in room['board'] if x=='gem' and room['board'].index(x) not in [])
        if all(i in room['opened'] for i in range(len(room['board']))) or not any(room['board'][i]=='gem' for i in range(len(room['board'])) if i not in room['opened']):
            room['state']='ended'; room['turn_id']=0
            s1=int(room['scores'].get(str(room['host_id']),0)); s2=int(room['scores'].get(str(room['player2_id']),0))
            winner=room['host_id'] if s1>s2 else room['player2_id'] if s2>s1 else 0
            if winner: msg+=f'\n\n🏆 برنده: <b>{safe_text(await _bb_pop_user_name(winner),50)}</b>'
            else: msg+='\n\n🤝 بازی مساوی شد!'
        await _bb_pop_room_save(room)
        turn_name=await _bb_pop_user_name(room['turn_id']) if room['turn_id'] else '—'
        a=await _bb_pop_user_name(room['host_id']); b=await _bb_pop_user_name(room['player2_id'])
        footer=f'\n\n🔴 {safe_text(a,30)}: 💎 {int(room["scores"].get(str(room["host_id"]),0))}\n🔵 {safe_text(b,30)}: 💎 {int(room["scores"].get(str(room["player2_id"]),0))}'
        if room['state']=='playing': footer+=f'\n\n🎯 نوبت: <b>{safe_text(turn_name,30)}</b>'
        await q.answer('باز شد!'); await q.message.edit_text('💩 <b>پوپ دو نفره</b>\n\n'+msg+footer,parse_mode='HTML',reply_markup=_bb_pop_board(room)); return True
    return True

