# Make sure newly-added lock keys are seeded for already-existing groups.
async def _bb_seed_all_advanced_locks_final():
    try:
        await DBX.execute('CREATE TABLE IF NOT EXISTS advanced_locks (chat_id INTEGER NOT NULL, lock_key TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(chat_id,lock_key))')
        rows=await DBX.execute('SELECT chat_id FROM chats',fetch=True)
        for row in rows:
            cid=int(row['chat_id'])
            for key in ADV_LOCK_KEYS:
                await DBX.execute('INSERT OR IGNORE INTO advanced_locks(chat_id,lock_key,enabled) VALUES(?,?,0)',(cid,key))
    except Exception as exc:
        log.warning('advanced lock seed failed: %r',exc)

# --- 2) Use OpenRouter itself for the study-note engine. The shared API fields
# remain in the owner center for compatibility, but study notes always prefer
# the bot's OpenRouter credentials/model. ---
async def _bb_make_study_note_openrouter(topic, full=False):
    level='کامل، دقیق و آموزشی' if full else 'خلاصه، نکته‌ای و مناسب مرور سریع'
    prompt=(
        'برای کاربر یک جزوه فارسی واقعی و قابل مطالعه آماده کن. '
        f'سطح خروجی: {level}.\n'
        f'موضوع/درخواست کاربر: {topic}\n\n'
        'اگر پایه، مقطع، رشته، واحد یا نام درس در درخواست آمده همان را دقیق رعایت کن. '
        'ساختار را منظم کن: عنوان، تعریف‌ها، نکات اصلی، فرمول‌ها یا قواعد لازم، مثال کوتاه، '
        'نکات امتحانی و جمع‌بندی. چیزی را بی‌دلیل اختراع نکن؛ اگر مشخصات درس کافی نیست، '
        'با همان اطلاعات موجود یک جزوه عمومی و درست درباره موضوع بساز. '
        'خروجی فقط متن جزوه باشد، بدون مقدمه درباره هوش مصنوعی و بدون HTML.'
    )
    key=await _bb_api_get('OPENROUTER_API_KEY','') or os.getenv('OPENROUTER_API_KEY','')
    if not key:
        return None
    model=await _bb_api_get('OPENROUTER_MODEL','') or os.getenv('OPENROUTER_MODEL','') or 'openai/gpt-4o-mini'
    body={'model':model,'messages':[
        {'role':'system','content':'تو دستیار آموزشی دقیق و خلاصه‌نویس فارسی هستی. مطالب را روشن، قابل فهم و منظم می‌نویسی.'},
        {'role':'user','content':prompt},
    ],'temperature':0.25,'max_tokens':1800 if full else 900}
    try:
        r=await _bb_http_post('https://openrouter.ai/api/v1/chat/completions',{
            'Authorization':f'Bearer {key}','Content-Type':'application/json',
            'HTTP-Referer':'https://t.me/','X-Title':'Bil Bilak Study / OpenRouter'
        },body,timeout=15)
        data=r.json(); content=((data.get('choices') or [{}])[0].get('message') or {}).get('content')
        if isinstance(content,list): content=''.join(str(x.get('text','')) if isinstance(x,dict) else str(x) for x in content)
        return str(content).strip() if content and str(content).strip() else None
    except Exception as exc:
        log.warning('OpenRouter study request failed: %r',exc)
        return None

