# Rebuild language schema/menu functions against the new four-language catalog.
async def _bb_get_user_lang(uid):
    await _bb_lang_schema()
    r=await DBX.one('SELECT lang FROM user_languages WHERE user_id=?',(int(uid or 0),))
    if r and r['lang'] in BB_UI_LANGS: return r['lang']
    return await _bb_get_global_lang()

async def _bb_set_user_lang(uid,lang):
    await _bb_lang_schema()
    if lang not in BB_UI_LANGS: lang='fa'
    await DBX.execute('INSERT INTO user_languages(user_id,lang,updated_at) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET lang=excluded.lang,updated_at=excluded.updated_at',(int(uid),lang,now_ts()))

async def _bb_language_callback(q,context):
    data=str(getattr(q,'data','') or ''); parts=data.split(':')
    if len(parts)!=3 or parts[2] not in BB_UI_LANGS: return False
    scope,lang=parts[1],parts[2]
    if scope=='global':
        if not await _bb_primary_owner(q.from_user.id): await q.answer('⛔ فقط سازنده اصلی.',show_alert=True); return True
        await _bb_set_global_lang(lang); await q.answer('Language changed.')
        await q.edit_message_text(_bb_lt(lang,'global_saved',lang=BB_LANG_NAMES[lang]),parse_mode='HTML'); return True
    await _bb_set_user_lang(q.from_user.id,lang)
    await q.answer('Language saved.')
    await q.edit_message_text(_bb_lt(lang,'saved',lang=BB_LANG_NAMES[lang]),parse_mode='HTML'); return True

# --- 4) ID/شناسه tool --------------------------------------------------------
_BB_ID_REQUEST_ALIASES={'شناسه','آیدی','ایدی','id','شناسه گروه','شناسه کانال','شناسه کاربر'}

def _bb_extract_tg_id_from_text(raw):
    s=str(raw or '').strip()
    # Numeric Telegram chat/user ID.
    if re.fullmatch(r'-?\d{5,20}',s): return int(s), 'numeric'
    # t.me/c/<internal-id>/<message-id> -> supergroup/channel ID is -100<internal-id>.
    m=re.search(r'(?:https?://)?t\.me/c/(\d{5,20})(?:/\d+)?',s,re.I)
    if m: return int('-100'+m.group(1)), 'tme_c'
    # tg://user?id=123 / tg://openmessage?user_id=123
    m=re.search(r'(?:tg://(?:user\?id=|openmessage\?user_id=))(\d{5,20})',s,re.I)
    if m: return int(m.group(1)), 'tg_scheme'
    return None, None

async def _bb_resolve_username_with_clients(username):
    name=username.lstrip('@').strip()
    if not name: return None
    # A connected cleanup/music personal account can resolve public usernames,
    # including personal accounts which the Bot API cannot resolve with getChat.
    for client_name in ('CLEANUP_USER_CLIENT','MUSIC_USER_CLIENT'):
        client=globals().get(client_name)
        if client is None or not getattr(client,'is_connected',False): continue
        try:
            obj=await client.get_chat(name)
            uid=getattr(obj,'id',None)
            if uid is not None:
                return int(uid), getattr(obj,'type','unknown'), getattr(obj,'title',None) or getattr(obj,'first_name',None) or name
        except Exception: pass
    return None

async def _bb_identifier_resolve(update,context):
    msg=getattr(update,'effective_message',None); chat=getattr(update,'effective_chat',None); user=getattr(update,'effective_user',None)
    if not msg or not user: return False
    raw=str(getattr(msg,'text',None) or '').strip()
    if normalize(raw) not in _BB_ID_REQUEST_ALIASES and not re.fullmatch(r'\s*(?:شناسه|آیدی|ایدی|id)\s*.*',raw,re.I):
        return False
    # 1) Reply to a user/message: most reliable way to get a real user ID.
    rep=getattr(msg,'reply_to_message',None)
    if rep:
        origin=getattr(rep,'forward_origin',None)
        fu=getattr(origin,'sender_user',None) if origin else None
        target=getattr(rep,'from_user',None) or fu
        if target:
            label='👤 کاربر'
            await msg.reply_text(f'🆔 <b>شناسه عددی</b>\n\n{label}: <code>{int(target.id)}</code>',parse_mode='HTML')
            return True
    # 2) Inline argument: شناسه @username / شناسه -100... / شناسه https://t.me/...
    arg=re.sub(r'^\s*(?:شناسه|آیدی|ایدی|id)\s*','',raw,flags=re.I).strip()
    if not arg and getattr(chat,'id',None) is not None:
        await msg.reply_text(f'🆔 <b>شناسه این چت</b>\n\n<code>{int(chat.id)}</code>',parse_mode='HTML')
        return True
    ident,kind=_bb_extract_tg_id_from_text(arg)
    if ident is not None:
        await msg.reply_text(f'🆔 <b>شناسه عددی</b>\n\n<code>{ident}</code>',parse_mode='HTML'); return True
    # 3) Public @username / t.me/username — first Bot API for chats, then helper account.
    username=None
    m=re.search(r'(?:https?://)?t\.me/([A-Za-z0-9_]{4,})',arg,re.I)
    if m: username=m.group(1)
    elif re.fullmatch(r'@?[A-Za-z0-9_]{4,}',arg): username=arg.lstrip('@')
    if username:
        try:
            obj=await context.bot.get_chat('@'+username)
            cid=getattr(obj,'id',None)
            if cid is not None:
                title=getattr(obj,'title',None) or getattr(obj,'full_name',None) or ('@'+username)
                await msg.reply_text(f'🆔 <b>شناسه عددی</b>\n\n{safe_text(title,100)}\n<code>{int(cid)}</code>',parse_mode='HTML'); return True
        except Exception: pass
        resolved=await _bb_resolve_username_with_clients(username)
        if resolved:
            rid,rtype,title=resolved
            await msg.reply_text(f'🆔 <b>شناسه عددی</b>\n\n{safe_text(str(title),100)}\n<code>{rid}</code>',parse_mode='HTML'); return True
    await msg.reply_text('⚠️ شناسه قابل تشخیص نیست.\n\nمثال‌ها:\n• <code>شناسه</code> داخل گروه/پیوی\n• <code>شناسه @username</code>\n• <code>شناسه https://t.me/username</code>\n• ریپلای روی پیام کاربر + <code>شناسه</code>\n• <code>شناسه -1001234567890</code>',parse_mode='HTML')
    return True

# --- 5) The group-entry message now resembles the requested advanced manager
# card and includes the real Telegram ID/owner/admin information. ---
async def bbx_welcome_added(update,context):
    cm=getattr(update,'my_chat_member',None); chat=getattr(update,'effective_chat',None)
    if not cm or not chat or getattr(chat,'type',None) not in ('group','supergroup'): return
    old_status=getattr(cm.old_chat_member,'status',None); new_status=getattr(cm.new_chat_member,'status',None)
    if new_status not in (ChatMemberStatus.MEMBER,ChatMemberStatus.ADMINISTRATOR): return
    if old_status not in (ChatMemberStatus.LEFT,ChatMemberStatus.BANNED,ChatMemberStatus.RESTRICTED): return
    try:
        admins=await chat.get_administrators()
        owner=next((a.user for a in admins if getattr(a,'status',None)==ChatMemberStatus.OWNER),None)
        admin_names=[]
        for a in admins:
            if getattr(a.user,'is_bot',False): continue
            name=getattr(a.user,'username',None) or getattr(a.user,'first_name',None) or str(a.user.id)
            admin_names.append('@'+name if getattr(a.user,'username',None) else name)
        rights=await get_bot_rights(context.bot,chat.id)
        lock_count=len(ADV_LOCK_NAMES)
        text=(
            '⚙️ <b>پنل مدیریت گروه</b>\n\n'
            f'🏷 <b>گروه:</b> {safe_text(chat.title or "بدون نام",80)}\n'
            f'🆔 <b>شناسه گروه:</b> <code>{int(chat.id)}</code>\n\n'
            f'👑 <b>مالک گروه:</b> {safe_text(("@"+owner.username) if owner and owner.username else (owner.first_name if owner else "نامشخص"),80)}\n\n'
            '👮 <b>ادمین‌های گروه:</b>\n' + ('\n'.join('• '+safe_text(x,80) for x in admin_names[:20]) or '• ثبت نشد') + '\n\n'
            '🛡 <b>امنیت آماده:</b>\n'
            f'🔒 {lock_count}+ قفل محتوایی و امنیتی\n'
            '🤖 ضدتبچی • ضداسپم • ضدفلود • ضدتکرار\n'
            '🔗 ضدلینک/فیشینگ • ضدتبلیغ • ضدکلاهبرداری\n'
            '🖼️ تحلیل رسانه‌ای AI برای ضدپورن/محتوای نامناسب در صورت فعال‌سازی\n'
            f'🧹 اکانت پاکسازی: {"🟢 متصل" if CLEANUP_USER_CLIENT and getattr(CLEANUP_USER_CLIENT,"is_connected",False) else "⚪ تنظیم نشده"}\n\n'
            f'⚡ <b>دسترسی حذف ربات:</b> {"🟢 فعال" if rights.get("delete") else "🔴 نیاز به دسترسی"}\n\n'
            '📚 برای تنظیمات: <b>پنل</b> یا <b>راهنما</b>\n'
            '🆔 برای دریافت شناسه: <b>شناسه</b>'
        )
        await chat.send_message(text,parse_mode='HTML',reply_markup=keyboard([
            [btn('⚙️ پنل مدیریت','bbentry:panel')],[btn('🔒 قفل‌های امنیتی','bbentry:locks')],
            [btn('🆔 شناسه گروه','bbentry:id')]
        ]))
    except Exception as exc:
        log.debug('advanced group-entry card failed: %r',exc)

# --- 6) Build final handlers. High priority ID handler runs in both PV/group. ---
_BB_BUILD_BEFORE_SECURITY_ID_LANG=build_application
def build_application(token=None):
    app=_BB_BUILD_BEFORE_SECURITY_ID_LANG(token)
    app.add_handler(CommandHandler(['id','identifier'],_bb_identifier_resolve),group=-800000)
    app.add_handler(MessageHandler(filters.Regex(r'^\s*(?:شناسه|آیدی|ایدی)\s*(?:@?[A-Za-z0-9_]{4,}|-?\d{5,20}|https?://\S+)?\s*$'),_bb_identifier_resolve),group=-800001)
    app.add_handler(MessageHandler(filters.Regex(r'^\s*زبان\s*$'),lambda u,c:_bb_language_menu(u,c,admin=False)),group=-800002)
    app.add_handler(CommandHandler(['language','lang'],lambda u,c:_bb_language_menu(u,c,admin=False)),group=-800003)
    app.add_handler(CallbackQueryHandler(_bb_language_callback,pattern=r'^bblang:'),group=-800004)
    old_post=getattr(app,'post_init',None)
    async def _bb_final_security_lang_post(application):
        if old_post: await old_post(application)
        try:
            await _bb_lang_schema()
            await _bb_seed_all_advanced_locks_final()
            # Seed design texts for the new language/ID/security center.
            for text,cat,kind in [
                ('🆔 شناسه','tools','button'),('شناسه عددی','tools','text'),('🔒 قفل‌های امنیتی','security','button'),
                ('🛡 امنیت آماده','security','text'),('ضدپورن','security','text'),('ضدتبچی','security','text'),
                ('اکانت پاکسازی','cleanup_account','text'),('🌐 زبان','settings','button'),
                ('🇷🇺 Русский','settings','button'),('📚 جزوه هوشمند','study','text'),
            ]:
                try: await _bb_ui_register(text,category=cat,kind=kind)
                except Exception: pass
        except Exception as exc: log.debug('final security/lang post failed: %r',exc)
    app.post_init=_bb_final_security_lang_post
    return app

