# Small callback layer for the buttons on the group-entry security card.
async def _bb_group_entry_callback(update,context):
    q=getattr(update,'callback_query',None)
    if not q: return False
    d=str(getattr(q,'data','') or '')
    if d=='bbentry:id':
        await q.answer(str(q.message.chat.id),show_alert=True); return True
    if d=='bbentry:panel':
        fake=type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat,'effective_message':q.message})()
        if not await is_admin(fake,q.from_user.id): await q.answer('⛔ فقط ادمین گروه.',show_alert=True); return True
        try: await q.message.reply_text('⚙️ برای باز کردن مدیریت گروه، «پنل» را ارسال کن.')
        except Exception: pass
        await q.answer(); return True
    if d=='bbentry:locks':
        fake=type('U',(),{'effective_user':q.from_user,'effective_chat':q.message.chat,'effective_message':q.message})()
        if not await is_admin(fake,q.from_user.id): await q.answer('⛔ فقط ادمین گروه.',show_alert=True); return True
        await advanced_security_panel(q,q.from_user.id,q.message.chat.id,0); return True
    return False

