async def _bb_meaning_ai_command(update, context, topic):
    msg=getattr(update,'effective_message',None)
    if not msg: return True
    key=str(topic or '').strip()
    if not key:
        await msg.reply_text('🧠 مثال: معنی کتاب یا معنی این جمله چیست؟')
        return True
    result=await _bb_shared_ai_chat([
        {'role':'system','content':'تو دستیار فارسی بیل بیلک هستی. معنی، مفهوم و توضیح را ساده، دقیق و کوتاه به فارسی بده. اگر متن چندمعنایی است، مهم‌ترین معنی‌ها را جدا کن.'},
        {'role':'user','content':key},
    ],max_tokens=700,temperature=0.25,timeout=12)
    if not result:
        await msg.reply_text('⚠️ سرویس هوش مصنوعی تنظیم نشده یا موقتاً در دسترس نیست.')
    else:
        await msg.reply_text('🧠 <b>معنی و توضیح</b>\n\n'+safe_text(result,3500),parse_mode='HTML')
    return True

async def _bb_car_ai_command(update, context, model):
    msg=getattr(update,'effective_message',None)
    model=str(model or '').strip()
    if not msg: return True
    if not model:
        await msg.reply_text('🚗 مثال: ماشین BMW M4')
        return True
    result=await _bb_shared_ai_chat([
        {'role':'system','content':'درباره خودروی درخواستی به فارسی و ساختاریافته توضیح بده: معرفی، موتور/پیشرانه، قدرت تقریبی در صورت اطمینان، مصرف یا برد، مزایا، معایب، کاربرد و نکات خرید. عدد ساختگی نساز و برای اطلاعات نامطمئن صریحاً بگو.'},
        {'role':'user','content':model},
    ],max_tokens=900,temperature=0.25,timeout=12)
    if not result:
        await msg.reply_text('⚠️ سرویس هوش مصنوعی تنظیم نشده یا موقتاً در دسترس نیست.')
    else:
        await msg.reply_text('🚗 <b>اطلاعات خودرو</b>\n\n'+safe_text(result,3800),parse_mode='HTML')
    return True

async def _bb_make_sticker_command(update, context):
    msg=getattr(update,'effective_message',None)
    rep=getattr(msg,'reply_to_message',None) if msg else None
    if not msg or not rep or not getattr(rep,'photo',None): return False
    try:
        import io
        from PIL import Image
        f=await rep.photo[-1].get_file()
        data=await f.download_as_bytearray()
        im=Image.open(io.BytesIO(bytes(data))).convert('RGBA')
        im.thumbnail((512,512),Image.Resampling.LANCZOS)
        canvas=Image.new('RGBA',(512,512),(0,0,0,0))
        x=(512-im.width)//2; y=(512-im.height)//2
        canvas.alpha_composite(im,(x,y))
        out=io.BytesIO(); out.name='bilbilak_sticker.webp'
        canvas.save(out,'WEBP',lossless=True,method=6); out.seek(0)
        await msg.reply_sticker(sticker=out)
        return True
    except Exception as exc:
        log.warning('sticker command failed: %r',exc)
        await msg.reply_text('⚠️ ساخت استیکر انجام نشد. مطمئن شو Pillow و پشتیبانی WEBP فعال است.')
        return True

async def _bb_make_gif_command(update, context):
    msg=getattr(update,'effective_message',None)
    rep=getattr(msg,'reply_to_message',None) if msg else None
    video=getattr(rep,'video',None) if rep else None
    if not msg or not video: return False
    duration=int(getattr(video,'duration',0) or 0)
    if duration<=0 or duration>5:
        await msg.reply_text('⚠️ ویدیو برای «گیف ربات» باید حداکثر ۵ ثانیه باشد.')
        return True
    try:
        f=await video.get_file()
        data=await f.download_as_bytearray()
        import io
        out=io.BytesIO(bytes(data)); out.name='bilbilak.gif.mp4'
        await msg.reply_animation(animation=out,caption='🎞️ گیف ربات')
        return True
    except Exception as exc:
        log.warning('gif command failed: %r',exc)
        await msg.reply_text('⚠️ تبدیل ویدیو به گیف انجام نشد.')
        return True

async def _bb_premium_id_command(update, context):
    msg=getattr(update,'effective_message',None)
    if not msg: return True
    target=getattr(msg,'reply_to_message',None) or msg
    eid=_bb_custom_emoji_id_from_message(target)
    if not eid:
        await msg.reply_text('❌ به یک پیام دارای Premium Custom Emoji ریپلای کن و «آیدی پرمیوم» را بفرست.')
        return True
    await msg.reply_text(f'✨ <b>Premium Custom Emoji ID</b>\n<code>{safe_text(eid,200)}</code>',parse_mode='HTML')
    return True

async def _bb_complete_persian_group_router(update, context):
    msg=getattr(update,'effective_message',None)
    if not msg: return False
    raw=str(getattr(msg,'text',None) or getattr(msg,'caption',None) or '').strip()
    if not raw: return False
    t=_bb_fa_cmd_norm(raw)

    # Exact high-value group game/utility entry points.
    exact={
        'لودو': globals().get('_bb_ludo_menu'),
        'اطلاعات عمومی': globals().get('_bb_trivia_menu'),
        'اسم فامیل': globals().get('_bb_name_family_start_command'),
        'اسم‌فامیل': globals().get('_bb_name_family_start_command'),
        'این فامیل': globals().get('_bb_name_family_start_command'),
        'جرأت حقیقت': globals().get('_bb_td_panel'),
        'جرئت حقیقت': globals().get('_bb_td_panel'),
        'جرات حقیقت': globals().get('_bb_td_panel'),
        'جرعت حقیقت': globals().get('_bb_td_panel'),
        'قرعه کشی': globals().get('_bb_raffle_text'),
        'قرعه‌کشی': globals().get('_bb_raffle_text'),
        'قرعه': globals().get('_bb_raffle_text'),
        'مافیا': globals().get('_bb_v7_priority_router'),
        'قرآن': globals().get('_bb_v7_quran'),
        'قران': globals().get('_bb_v7_quran'),
        'فال': globals().get('_bb_v7_fortune'),
        'فال حافظ': globals().get('_bb_v7_fortune'),
        'دعا': globals().get('_bb_v7_dua'),
        'خبر': globals().get('_bb_news_command'),
        'اخبار': globals().get('_bb_news_command'),
        'اخبار روز': globals().get('_bb_news_command'),
        'آیدی پرمیوم': _bb_premium_id_command,
        'راهنما': globals().get('_bb_final_help'),
        'کمک': globals().get('_bb_final_help'),
        'دستورات': globals().get('_bb_final_help'),
        'راهنمای کامل': globals().get('_bb_final_help'),
        'پنل مدیریت': globals().get('cmd_adminpanel'),
        'مدیریت': globals().get('cmd_adminpanel'),
        'قوانین': globals().get('rules_command'),
        'خوشامد': globals().get('set_welcome'),
        'خداحافظ': globals().get('set_goodbye'),
        'عضویت اجباری': globals().get('forcejoin_v4'),
        'پاکسازی': globals().get('cleanup_v4'),
        'اخطار': globals().get('moderation_action'),
        'لغو اخطار': globals().get('moderation_action'),
        'سکوت': globals().get('mute_command_v6'),
        'رفع سکوت': globals().get('moderation_v4'),
        'بن': globals().get('moderation_v4'),
        'رفع بن': globals().get('moderation_v4'),
        'پین': globals().get('pin_command'),
        'گزارش': globals().get('report_command'),
        'عنوان گروه': globals().get('set_group_title'),
        'بیو گروه': globals().get('set_group_bio'),
        'عکس گروه': globals().get('set_group_photo_v4'),
        'آمار مدیریت': globals().get('stats_v4_command'),
    }
    fn=exact.get(t)
    # Some callbacks need a kind/action or args; the existing generic router is
    # safer for those management commands, so only call exact feature entrypoints.
    if t in {'مافیا'}:
        return False
    if fn:
        try:
            if t in {'جرأت حقیقت','جرئت حقیقت','جرات حقیقت','جرعت حقیقت'}:
                await fn(update,context,kind=None)
            else:
                await fn(update,context)
            raise ApplicationHandlerStop
        except ApplicationHandlerStop:
            raise
        except TypeError:
            # Preserve the established router for callbacks with a different contract.
            return False
        except Exception as exc:
            log.exception('complete Persian command failed: %s',exc)
            await msg.reply_text('⚠️ اجرای این دستور فعلاً ناموفق بود؛ منطق اصلی ربات دست‌نخورده باقی مانده است.')
            raise ApplicationHandlerStop

    # Parameterized commands.
    if re.fullmatch(r'(?:افزایش کیفیت|بهبود کیفیت|کیفیت عکس|کیفیت تصویر)',t) and getattr(msg,'reply_to_message',None):
        if await _bb_enhance_photo(update,context): raise ApplicationHandlerStop
    if re.fullmatch(r'ساخت استیکر',t):
        if await _bb_make_sticker_command(update,context): raise ApplicationHandlerStop
    if re.fullmatch(r'گیف ربات',t):
        if await _bb_make_gif_command(update,context): raise ApplicationHandlerStop
    m=re.match(r'^معنی\s+(.+)$',t)
    if m:
        await _bb_meaning_ai_command(update,context,m.group(1)); raise ApplicationHandlerStop
    m=re.match(r'^(?:ماشین|خودرو)\s+(.+)$',t)
    if m:
        await _bb_car_ai_command(update,context,m.group(1)); raise ApplicationHandlerStop
    if re.match(r'^صفحه قرآن\s+\d{1,3}$',t) or re.match(r'^قرآن صفحه\s+\d{1,3}$',t):
        return False  # Existing Quran page router is already authoritative.
    if t.startswith('فونت '): return False
    if t.startswith('ترجمه '): return False
    if t.startswith('هوا ') or t.startswith('آب و هوا ') or t.startswith('ارز ') or t.startswith('نرخ ارز '): return False
    if t.startswith('جزوه ') or t.startswith('کامل جزوه '): return False
    if t.startswith('جواب ') or t.startswith('رادیکال ') or t.startswith('جذر '): return False
    if t.startswith('پخش آهنگ ') or t.startswith('پخش فیلم ') or t.startswith('لایو ') or t.startswith('دانلود '): return False
    if t in {'زندگی','خانواده','پروفایل','بیو','آیدی','شناسه','زمان','تاریخ','فوتبال','رادیو','مکانیابی','کشور','کشورها','بازی','ابزارها'}: return False
    return False

_BB_BUILD_BEFORE_COMPLETE_PERSIAN_COMMANDS=build_application
def build_application(token=None):
    app=_BB_BUILD_BEFORE_COMPLETE_PERSIAN_COMMANDS(token)
    # Group commands are plain Persian text. They intentionally do not use
    # CommandHandler, because Telegram bot command tokens cannot be Persian.
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,_bb_complete_persian_group_router),group=-10000020)
    app.add_handler(MessageHandler(filters.CAPTION & ~filters.COMMAND,_bb_complete_persian_group_router),group=-10000019)
    return app

# =============================================================================
# FINAL STARTUP GUARD
# PTB Application uses slots, so keep the re-entry state outside Application.
# =============================================================================
_BB_POST_INIT_RUNNING = set()
_BB_BUILD_BEFORE_STARTUP_GUARD = build_application

def build_application(token=None):
    app = _BB_BUILD_BEFORE_STARTUP_GUARD(token)
    current = getattr(app, 'post_init', None)
    if current is not None and not getattr(current, '_bb_guarded', False):
        async def _bb_guarded_post_init(application):
            key = id(application)
            if key in _BB_POST_INIT_RUNNING:
                log.warning('post_init recursion prevented')
                return
            _BB_POST_INIT_RUNNING.add(key)
            try:
                await current(application)
            finally:
                _BB_POST_INIT_RUNNING.discard(key)
        _bb_guarded_post_init._bb_guarded = True
        app.post_init = _bb_guarded_post_init
    return app



